/**
 * Complete Integration Example
 * Shows how to integrate the Prompt Library into a StoryCore pipeline
 */

import { promptLibrary, PromptTemplate } from './PromptLibraryService';

// Example: Complete scene generation workflow
export class SceneGenerator {
  private projectConfig = {
    name: 'Neon Dreams',
    genre: 'cyberpunk sci-fi',
    colors: 'electric blue, neon purple, chrome silver',
    lighting: 'neon volumetric lighting'
  };

  /**
   * Step 1: Generate Master Coherence Sheet
   */
  async generateMasterCoherence() {
    const template = await promptLibrary.loadPrompt(
      '01-master-coherence/coherence-grid.json'
    );

    const prompt = promptLibrary.fillPrompt(template, {
      PROJECT_NAME: this.projectConfig.name,
      GENRE_STYLE: this.projectConfig.genre,
      PRIMARY_COLORS: this.projectConfig.colors,
      LIGHTING_TYPE: this.projectConfig.lighting
    });

    console.log('Master Coherence Prompt:', prompt);
    return prompt;
  }

  /**
   * Step 2: Generate character design sheet
   */
  async generateCharacterSheet(characterData: {
    description: string;
    age: string;
    gender: string;
    features: string;
  }) {
    const template = await promptLibrary.loadPrompt(
      '01-master-coherence/character-grid.json'
    );

    const prompt = promptLibrary.fillPrompt(template, {
      CHARACTER_DESCRIPTION: characterData.description,
      AGE: characterData.age,
      GENDER: characterData.gender,
      DISTINCTIVE_FEATURES: characterData.features,
      ART_STYLE: this.projectConfig.genre
    });

    return prompt;
  }

  /**
   * Step 3: Generate specific scene shot
   */
  async generateSceneShot(
    sceneElement: string,
    shotType: 'wide' | 'medium' | 'close-up',
    lighting: 'golden-hour' | 'blue-hour' | 'night-moonlight'
  ) {
    // Load genre template
    const genreTemplate = await promptLibrary.loadPrompt('02-genres/scifi.json');
    
    // Load shot type template
    const shotPath = `03-shot-types/${shotType === 'close-up' ? 'close-up' : shotType + '-shot'}.json`;
    const shotTemplate = await promptLibrary.loadPrompt(shotPath);
    
    // Load lighting template
    const lightingTemplate = await promptLibrary.loadPrompt(
      `04-lighting/${lighting}.json`
    );

    // Generate each part
    const genrePrompt = promptLibrary.fillPrompt(genreTemplate, {
      SPECIFIC_ELEMENT: sceneElement,
      AESTHETIC: 'cyberpunk'
    });

    const shotPrompt = promptLibrary.fillPrompt(shotTemplate, {
      SUBJECT: sceneElement,
      ENVIRONMENT: 'neon city street',
      LIGHTING_TYPE: 'neon lighting'
    });

    const lightingPrompt = promptLibrary.fillPrompt(lightingTemplate, {
      SCENE: sceneElement,
      TIME: 'sunset'
    });

    // Combine prompts
    return `${shotPrompt}. ${genrePrompt}. ${lightingPrompt}`;
  }

  /**
   * Complete pipeline example
   */
  async generateCompleteScene() {
    console.log('=== Starting Scene Generation Pipeline ===\n');

    // Step 1: Master Coherence
    console.log('Step 1: Generating Master Coherence Sheet...');
    const masterPrompt = await this.generateMasterCoherence();
    console.log('✓ Master coherence prompt ready\n');

    // Step 2: Character Design
    console.log('Step 2: Generating Character Design...');
    const characterPrompt = await this.generateCharacterSheet({
      description: 'cyberpunk hacker',
      age: '25',
      gender: 'female',
      features: 'neon tattoos, augmented eyes, leather jacket'
    });
    console.log('✓ Character design prompt ready\n');

    // Step 3: Scene Shots
    console.log('Step 3: Generating Scene Shots...');
    
    const establishingShot = await this.generateSceneShot(
      'neon city skyline',
      'wide',
      'blue-hour'
    );
    console.log('✓ Establishing shot ready');

    const characterShot = await this.generateSceneShot(
      'hacker at terminal',
      'medium',
      'night-moonlight'
    );
    console.log('✓ Character shot ready');

    const detailShot = await this.generateSceneShot(
      'glowing holographic interface',
      'close-up',
      'night-moonlight'
    );
    console.log('✓ Detail shot ready\n');

    return {
      masterCoherence: masterPrompt,
      character: characterPrompt,
      shots: {
        establishing: establishingShot,
        character: characterShot,
        detail: detailShot
      }
    };
  }
}

// Example: Search and filter prompts
export class PromptDiscovery {
  /**
   * Find prompts for a specific genre
   */
  async findGenrePrompts(genre: string) {
    const results = await promptLibrary.search(genre);
    return results.filter(p => p.category === 'genres');
  }

  /**
   * Find all character-related prompts
   */
  async findCharacterPrompts() {
    return promptLibrary.searchByTags(['character', 'hero', 'villain']);
  }

  /**
   * Get recommended prompts for beginners
   */
  async getBeginnerPrompts() {
    const categories = await promptLibrary.getCategories();
    
    // Get one prompt from each category
    const recommendations: PromptTemplate[] = [];
    
    for (const [categoryId, category] of Object.entries(categories)) {
      if (category.prompts.length > 0) {
        const prompt = await promptLibrary.loadPrompt(category.prompts[0]);
        recommendations.push(prompt);
      }
    }
    
    return recommendations;
  }
}

// Example: Batch generation
export class BatchGenerator {
  /**
   * Generate multiple variations of a scene
   */
  async generateVariations(
    baseTemplate: PromptTemplate,
    variationSets: Array<Record<string, string>>
  ) {
    const prompts: string[] = [];

    for (const values of variationSets) {
      const validation = promptLibrary.validateValues(baseTemplate, values);
      
      if (validation.valid) {
        const prompt = promptLibrary.fillPrompt(baseTemplate, values);
        prompts.push(prompt);
      } else {
        console.warn(`Skipping invalid variation:`, validation.errors);
      }
    }

    return prompts;
  }

  /**
   * Generate a complete storyboard
   */
  async generateStoryboard(scenes: Array<{
    description: string;
    shotType: string;
    lighting: string;
  }>) {
    const storyboard: string[] = [];

    for (let i = 0; i < scenes.length; i++) {
      const scene = scenes[i];
      console.log(`Generating scene ${i + 1}/${scenes.length}...`);

      // Load templates
      const shotTemplate = await promptLibrary.loadPrompt(
        `03-shot-types/${scene.shotType}.json`
      );
      const lightingTemplate = await promptLibrary.loadPrompt(
        `04-lighting/${scene.lighting}.json`
      );

      // Generate prompts
      const shotPrompt = promptLibrary.fillPrompt(shotTemplate, {
        SUBJECT: scene.description,
        ENVIRONMENT: 'scene environment',
        LIGHTING_TYPE: 'cinematic'
      });

      const lightingPrompt = promptLibrary.fillPrompt(lightingTemplate, {
        SCENE: scene.description
      });

      storyboard.push(`${shotPrompt}. ${lightingPrompt}`);
    }

    return storyboard;
  }
}

// Usage examples
async function main() {
  console.log('=== Prompt Library Integration Examples ===\n');

  // Example 1: Complete scene generation
  const generator = new SceneGenerator();
  const scene = await generator.generateCompleteScene();
  console.log('\nGenerated Scene:', scene);

  // Example 2: Discover prompts
  const discovery = new PromptDiscovery();
  const scifiPrompts = await discovery.findGenrePrompts('sci-fi');
  console.log('\nFound', scifiPrompts.length, 'sci-fi prompts');

  // Example 3: Batch generation
  const batch = new BatchGenerator();
  const template = await promptLibrary.loadPrompt('02-genres/scifi.json');
  const variations = await batch.generateVariations(template, [
    { SPECIFIC_ELEMENT: 'hovering vehicle', AESTHETIC: 'cyberpunk' },
    { SPECIFIC_ELEMENT: 'space station', AESTHETIC: 'clean minimalist future' },
    { SPECIFIC_ELEMENT: 'robot factory', AESTHETIC: 'dystopian industrial' }
  ]);
  console.log('\nGenerated', variations.length, 'variations');
}

// Run if executed directly
if (require.main === module) {
  main().catch(console.error);
}

export { main };

/**
 * Property-Based Tests for Build Output Isolation
 * Feature: typescript-build-configuration
 * Task 8: Implement build output isolation tests
 * 
 * These tests validate that the build system maintains proper separation
 * between source files and compiled artifacts.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fc from 'fast-check';
import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

const SRC_DIR = path.join(process.cwd(), 'src');
const DIST_DIR = path.join(process.cwd(), 'dist');
const TEST_TEMP_DIR = path.join(process.cwd(), '.test-temp');

/**
 * Helper: Find all .js files in a directory recursively
 */
function findJsFiles(dir: string): string[] {
  const jsFiles: string[] = [];
  
  if (!fs.existsSync(dir)) {
    return jsFiles;
  }

  function traverse(currentDir: string) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });
    
    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      
      if (entry.isDirectory()) {
        // Skip node_modules and other common directories
        if (!['node_modules', '.git', 'dist', 'coverage'].includes(entry.name)) {
          traverse(fullPath);
        }
      } else if (entry.isFile() && entry.name.endsWith('.js')) {
        // Exclude root-level config files
        const relativePath = path.relative(process.cwd(), fullPath);
        const isRootConfig = !relativePath.includes(path.sep) && 
                            (entry.name.endsWith('.config.js') || 
                             entry.name === 'vite.config.js' ||
                             entry.name === 'vitest.config.js' ||
                             entry.name === 'eslint.config.js');
        
        if (!isRootConfig) {
          jsFiles.push(fullPath);
        }
      }
    }
  }
  
  traverse(dir);
  return jsFiles;
}

/**
 * Helper: Create a test .ts file
 */
function createTestTsFile(relativePath: string, content: string = 'export const test = "test";'): string {
  const fullPath = path.join(SRC_DIR, relativePath);
  const dir = path.dirname(fullPath);
  
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  
  fs.writeFileSync(fullPath, content, 'utf-8');
  return fullPath;
}

/**
 * Helper: Clean up test files
 */
function cleanupTestFiles(files: string[]) {
  for (const file of files) {
    try {
      if (fs.existsSync(file)) {
        fs.unlinkSync(file);
      }
    } catch (error) {
      // Ignore cleanup errors
    }
  }
}

describe('Feature: typescript-build-configuration', () => {
  describe('Property 1: Build Output Isolation', () => {
    /**
     * Property: For any build or development operation (dev, build, type-check),
     * after the operation completes, the src/ directory should contain zero .js or .js.map files.
     * 
     * Validates: Requirements 1.1, 1.2, 1.3, 1.5
     */
    
    it('should ensure src/ contains no .js files after build', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.constantFrom('build'),
          async (scriptName) => {
            // Clean before test
            try {
              execSync('npm run clean', { 
                cwd: process.cwd(), 
                stdio: 'pipe',
                timeout: 10000 
              });
            } catch (error) {
              // Cleanup might fail if nothing to clean
            }

            // Run the build script
            try {
              execSync(`npm run ${scriptName}`, { 
                cwd: process.cwd(), 
                stdio: 'pipe',
                timeout: 60000 
              });
            } catch (error) {
              // Build might fail for other reasons, but we still check for .js files
            }

            // Scan src/ for .js files
            const jsFiles = findJsFiles(SRC_DIR);
            
            // Assert no .js files exist in src/
            expect(jsFiles).toHaveLength(0);
          }
        ),
        { numRuns: 5, timeout: 120000 } // Reduced runs for build performance
      );
    }, 180000); // 3 minute timeout for build tests

    it('should ensure src/ contains no .js files after cleanup', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.array(fc.string({ minLength: 1, maxLength: 20 }), { minLength: 1, maxLength: 5 }),
          async (fileNames) => {
            const createdFiles: string[] = [];
            
            try {
              // Create test .js files in src/
              for (const fileName of fileNames) {
                const safeName = fileName.replace(/[^a-zA-Z0-9_-]/g, '_');
                const testFile = path.join(SRC_DIR, `test_${safeName}.js`);
                fs.writeFileSync(testFile, '// test file', 'utf-8');
                createdFiles.push(testFile);
              }

              // Run cleanup
              execSync('npm run clean', { 
                cwd: process.cwd(), 
                stdio: 'pipe',
                timeout: 10000 
              });

              // Scan src/ for .js files
              const jsFiles = findJsFiles(SRC_DIR);
              
              // Assert no .js files exist in src/
              expect(jsFiles).toHaveLength(0);
            } finally {
              // Cleanup any remaining test files
              cleanupTestFiles(createdFiles);
            }
          }
        ),
        { numRuns: 100, timeout: 30000 }
      );
    }, 60000);

    it('should preserve root-level config files during cleanup', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.constantFrom('vite.config.js', 'vitest.config.js', 'eslint.config.js'),
          async (configFile) => {
            const configPath = path.join(process.cwd(), configFile);
            const configExists = fs.existsSync(configPath);
            
            if (configExists) {
              const contentBefore = fs.readFileSync(configPath, 'utf-8');
              
              // Run cleanup
              execSync('npm run clean', { 
                cwd: process.cwd(), 
                stdio: 'pipe',
                timeout: 10000 
              });
              
              // Verify config file still exists
              expect(fs.existsSync(configPath)).toBe(true);
              
              // Verify content unchanged
              const contentAfter = fs.readFileSync(configPath, 'utf-8');
              expect(contentAfter).toBe(contentBefore);
            }
          }
        ),
        { numRuns: 10, timeout: 15000 }
      );
    }, 30000);
  });
});

/**
 * Property-Based Tests for Hot Module Replacement Isolation
 * Feature: typescript-build-configuration
 * Task 10: Implement development workflow tests
 * 
 * These tests validate that HMR updates during development do not
 * generate .js files in the src/ directory.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fc from 'fast-check';
import * as fs from 'fs';
import * as path from 'path';
import { spawn, ChildProcess } from 'child_process';

const SRC_DIR = path.join(process.cwd(), 'src');
const TEST_COMPONENT_DIR = path.join(SRC_DIR, 'test-hmr-components');

/**
 * Helper: Find all .js files in a directory recursively
 */
function findJsFiles(dir: string): string[] {
  const jsFiles: string[] = [];
  
  if (!fs.existsSync(dir)) {
    return jsFiles;
  }

  function traverse(currentDir: string) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });
    
    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      
      if (entry.isDirectory()) {
        // Skip node_modules and other common directories
        if (!['node_modules', '.git', 'dist', 'coverage'].includes(entry.name)) {
          traverse(fullPath);
        }
      } else if (entry.isFile() && entry.name.endsWith('.js')) {
        jsFiles.push(fullPath);
      }
    }
  }
  
  traverse(dir);
  return jsFiles;
}

/**
 * Helper: Start dev server and wait for it to be ready
 */
function startDevServer(): Promise<{ process: ChildProcess; port: number }> {
  return new Promise((resolve, reject) => {
    const devProcess = spawn('npm', ['run', 'dev'], {
      cwd: process.cwd(),
      shell: true,
      stdio: 'pipe'
    });

    let output = '';
    const timeout = setTimeout(() => {
      devProcess.kill();
      reject(new Error('Dev server startup timeout'));
    }, 60000); // 60 second timeout

    devProcess.stdout?.on('data', (data) => {
      output += data.toString();
      
      // Look for Vite's ready message
      if (output.includes('Local:') || output.includes('ready in')) {
        clearTimeout(timeout);
        
        // Extract port from output (default is 5173)
        const portMatch = output.match(/localhost:(\d+)/);
        const port = portMatch ? parseInt(portMatch[1]) : 5173;
        
        // Give it a moment to fully initialize
        setTimeout(() => {
          resolve({ process: devProcess, port });
        }, 2000);
      }
    });

    devProcess.stderr?.on('data', (data) => {
      output += data.toString();
    });

    devProcess.on('error', (error) => {
      clearTimeout(timeout);
      reject(error);
    });

    devProcess.on('exit', (code) => {
      clearTimeout(timeout);
      if (code !== 0 && code !== null) {
        reject(new Error(`Dev server exited with code ${code}`));
      }
    });
  });
}

/**
 * Helper: Stop dev server
 */
function stopDevServer(devProcess: ChildProcess): Promise<void> {
  return new Promise((resolve) => {
    if (!devProcess.killed) {
      devProcess.on('exit', () => {
        resolve();
      });
      
      // Try graceful shutdown first
      devProcess.kill('SIGTERM');
      
      // Force kill after 5 seconds if still running
      setTimeout(() => {
        if (!devProcess.killed) {
          devProcess.kill('SIGKILL');
        }
        resolve();
      }, 5000);
    } else {
      resolve();
    }
  });
}

/**
 * Helper: Create a test component file
 */
function createTestComponent(fileName: string, content: string): string {
  if (!fs.existsSync(TEST_COMPONENT_DIR)) {
    fs.mkdirSync(TEST_COMPONENT_DIR, { recursive: true });
  }
  
  const filePath = path.join(TEST_COMPONENT_DIR, fileName);
  fs.writeFileSync(filePath, content, 'utf-8');
  return filePath;
}

/**
 * Helper: Modify a test component file
 */
function modifyTestComponent(filePath: string, newContent: string): void {
  fs.writeFileSync(filePath, newContent, 'utf-8');
}

/**
 * Helper: Clean up test component directory
 */
function cleanupTestComponents(): void {
  if (fs.existsSync(TEST_COMPONENT_DIR)) {
    fs.rmSync(TEST_COMPONENT_DIR, { recursive: true, force: true });
  }
}

describe('Feature: typescript-build-configuration', () => {
  describe('Property 10: Hot Module Replacement Isolation', () => {
    /**
     * Property: For any file change that triggers HMR during development,
     * no .js files should be created in src/ as a result of the HMR update.
     * 
     * Validates: Requirements 6.4
     */
    
    afterEach(() => {
      cleanupTestComponents();
    });

    it('should not create .js files in src/ during HMR updates', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.tuple(
            fc.string({ minLength: 5, maxLength: 20 }).map(s => s.replace(/[^a-zA-Z0-9]/g, '_')),
            fc.integer({ min: 1, max: 5 })
          ),
          async ([componentName, updateCount]) => {
            let devServer: { process: ChildProcess; port: number } | null = null;
            
            try {
              // Start dev server
              devServer = await startDevServer();
              
              // Create initial test component
              const componentFile = createTestComponent(
                `${componentName}.tsx`,
                `export const ${componentName} = () => <div>Initial</div>;`
              );
              
              // Wait for initial compilation
              await new Promise(resolve => setTimeout(resolve, 1000));
              
              // Scan for .js files before modifications
              const jsFilesBefore = findJsFiles(SRC_DIR);
              
              // Perform multiple HMR updates
              for (let i = 0; i < updateCount; i++) {
                modifyTestComponent(
                  componentFile,
                  `export const ${componentName} = () => <div>Update ${i + 1}</div>;`
                );
                
                // Wait for HMR to process
                await new Promise(resolve => setTimeout(resolve, 500));
              }
              
              // Wait a bit more to ensure all HMR updates are processed
              await new Promise(resolve => setTimeout(resolve, 1000));
              
              // Scan for .js files after modifications
              const jsFilesAfter = findJsFiles(SRC_DIR);
              
              // Assert no new .js files were created
              expect(jsFilesAfter.length).toBe(jsFilesBefore.length);
              
              // Assert specifically no .js files in test component directory
              const testDirJsFiles = jsFilesAfter.filter(f => f.includes('test-hmr-components'));
              expect(testDirJsFiles).toHaveLength(0);
              
            } finally {
              // Clean up dev server
              if (devServer) {
                await stopDevServer(devServer.process);
              }
            }
          }
        ),
        { numRuns: 3, timeout: 180000 } // Reduced runs due to dev server overhead
      );
    }, 240000); // 4 minute timeout for dev server tests

    it('should not create .js files when modifying existing components', async () => {
      let devServer: { process: ChildProcess; port: number } | null = null;
      
      try {
        // Start dev server
        devServer = await startDevServer();
        
        // Create a test component
        const testFile = createTestComponent(
          'TestComponent.tsx',
          `import React from 'react';\nexport const TestComponent = () => <div>Test</div>;`
        );
        
        // Wait for initial compilation
        await new Promise(resolve => setTimeout(resolve, 2000));
        
        // Get initial .js file count
        const jsFilesBefore = findJsFiles(SRC_DIR);
        
        // Modify the component multiple times
        for (let i = 0; i < 3; i++) {
          modifyTestComponent(
            testFile,
            `import React from 'react';\nexport const TestComponent = () => <div>Modified ${i}</div>;`
          );
          
          // Wait for HMR
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
        
        // Get final .js file count
        const jsFilesAfter = findJsFiles(SRC_DIR);
        
        // Assert no .js files were created
        expect(jsFilesAfter.length).toBe(jsFilesBefore.length);
        
      } finally {
        if (devServer) {
          await stopDevServer(devServer.process);
        }
      }
    }, 120000); // 2 minute timeout

    it('should maintain clean src/ directory throughout dev server lifecycle', async () => {
      let devServer: { process: ChildProcess; port: number } | null = null;
      
      try {
        // Scan before starting dev server
        const jsFilesInitial = findJsFiles(SRC_DIR);
        
        // Start dev server
        devServer = await startDevServer();
        
        // Wait for server to be fully ready
        await new Promise(resolve => setTimeout(resolve, 3000));
        
        // Scan after dev server starts
        const jsFilesAfterStart = findJsFiles(SRC_DIR);
        
        // Create and modify a component
        const testFile = createTestComponent(
          'LifecycleTest.tsx',
          `export const LifecycleTest = () => <div>Test</div>;`
        );
        
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        modifyTestComponent(
          testFile,
          `export const LifecycleTest = () => <div>Modified</div>;`
        );
        
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // Scan after modifications
        const jsFilesAfterModify = findJsFiles(SRC_DIR);
        
        // Assert no .js files at any stage
        expect(jsFilesInitial).toHaveLength(0);
        expect(jsFilesAfterStart).toHaveLength(0);
        expect(jsFilesAfterModify).toHaveLength(0);
        
      } finally {
        if (devServer) {
          await stopDevServer(devServer.process);
        }
      }
    }, 120000); // 2 minute timeout
  });
});

/**
 * Property-Based Tests for Module Resolution Priority
 * Feature: typescript-build-configuration
 * Task 9.1: Write property test for module resolution priority
 * 
 * These tests validate that the module resolution system prefers TypeScript
 * files over JavaScript files when both exist with the same name.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fc from 'fast-check';
import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

const SRC_DIR = path.join(process.cwd(), 'src');
const TEST_TEMP_DIR = path.join(SRC_DIR, '__test_module_resolution__');

/**
 * Helper: Create a test file with specific content
 */
function createTestFile(filePath: string, content: string): void {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, content, 'utf-8');
}

/**
 * Helper: Clean up test directory
 */
function cleanupTestDir(): void {
  if (fs.existsSync(TEST_TEMP_DIR)) {
    fs.rmSync(TEST_TEMP_DIR, { recursive: true, force: true });
  }
}

/**
 * Helper: Create a test module that imports another module
 */
function createImporterModule(importPath: string): string {
  const importerPath = path.join(TEST_TEMP_DIR, 'importer.ts');
  const content = `
import { value } from '${importPath}';
export const importedValue = value;
`;
  createTestFile(importerPath, content);
  return importerPath;
}

describe('Feature: typescript-build-configuration', () => {
  beforeEach(() => {
    cleanupTestDir();
  });

  afterEach(() => {
    cleanupTestDir();
  });

  describe('Property 3: Module Resolution Priority', () => {
    /**
     * Property: For any module name where both a .ts and .js file exist with
     * the same base name, importing that module should resolve to the .ts file,
     * not the .js file.
     * 
     * Validates: Requirements 1.4, 5.2
