import type {
  DemoConfig,
  DemoState,
  DemoOperation,
  DemoAddonState,
} from './types';

export class DemoAddonManager {
  private config: DemoConfig;
  private state: DemoState;
  private operations: DemoOperation[] = [];
  private readonly MAX_OPERATIONS_SIZE = 50;

  constructor() {
    this.config = {
      autoAdvance: true,
      stepDuration: 3000,
      loop: false,
    };

    this.state = {
      isRunning: false,
      currentStep: 0,
      totalSteps: 0,
      startedAt: null,
      completedAt: null,
    };
  }

  /**
   * Start the demo
   */
  async startDemo(): Promise<void> {
    this.state = {
      isRunning: true,
      currentStep: 0,
      totalSteps: 5, // Example: 5 steps
      startedAt: new Date().toISOString(),
      completedAt: null,
    };

    this.recordOperation('start', 'Demo started');
  }

  /**
   * Stop the demo
   */
  async stopDemo(): Promise<void> {
    this.state = {
      isRunning: false,
      currentStep: this.state.currentStep,
      totalSteps: this.state.totalSteps,
      startedAt: this.state.startedAt,
      completedAt: new Date().toISOString(),
    };

    this.recordOperation('stop', 'Demo stopped');
  }

  /**
   * Get demo status
   */
  getDemoStatus(): DemoState {
    return { ...this.state };
  }

  /**
   * Get current configuration
   */
  getConfig(): DemoConfig {
    return { ...this.config };
  }

  /**
   * Update configuration
   */
  setConfig(config: Partial<DemoConfig>): void {
    this.config = { ...this.config, ...config };
    this.recordOperation('config', 'Configuration updated', { config });
  }

  /**
   * Execute a demo step
   */
  async executeDemoStep(step: string): Promise<any> {
    // In a real implementation, this would execute the demo step
    this.state.currentStep++;
    this.recordOperation('step', `Executed step: ${step}`, { step });

    return { success: true, step, result: `Step "${step}" executed` };
  }

  /**
   * Get demo logs
   */
  async getDemoLogs(): Promise<string[]> {
    return this.operations.map(op => `${op.timestamp} - ${op.description}`);
  }

  /**
   * Clear demo logs
   */
  async clearDemoLogs(): Promise<void> {
    this.operations = [];
    this.recordOperation('config', 'Demo logs cleared');
  }

  /**
   * Serialize manager state
   */
  serialize(): string {
    const state: DemoAddonState = {
      config: this.config,
      state: this.state,
      operations: this.operations,
      version: '1.0',
      lastModified: new Date().toISOString(),
    };

    return JSON.stringify(state, null, 2);
  }

  /**
   * Deserialize manager state
   */
  deserialize(data: string): void {
    try {
      const state = JSON.parse(data);
      if (this.isValidDemoAddonState(state)) {
        this.config = state.config;
        this.state = state.state;
        this.operations = state.operations || [];
      } else {
        console.warn('Invalid demo addon state format');
      }
    } catch (error) {
      console.error('Failed to deserialize demo addon state:', error);
    }
  }

  /**
   * Get operation history
   */
  getOperations(): DemoOperation[] {
    return [...this.operations];
  }

  /**
   * Clear operation history
   */
  clearOperations(): void {
    this.operations = [];
  }

  /**
   * Record an operation
   */
  private recordOperation(
    type: DemoOperation['type'],
    description: string,
    details?: unknown
  ): void {
    const operation: DemoOperation = {
      id: crypto.randomUUID(),
      type,
      timestamp: new Date().toISOString(),
      description,
      details,
    };

    this.operations.push(operation);

    // Maintain maximum operations size
    if (this.operations.length > this.MAX_OPERATIONS_SIZE) {
      this.operations.shift();
    }
  }

  /**
   * Validate demo addon state
   */
  private isValidDemoAddonState(state: unknown): state is DemoAddonState {
    return (
      state !== null &&
      typeof state === 'object' &&
      (state as any).config &&
      (state as any).state &&
      typeof (state as any).version === 'string' &&
      typeof (state as any).lastModified === 'string'
    );
  }

  /**
   * Get demo progress
   */
  getDemoProgress(): {
    progress: number;
    completed: boolean;
  } {
    const progress = this.state.totalSteps > 0
      ? (this.state.currentStep / this.state.totalSteps) * 100
      : 0;

    return {
      progress,
      completed: this.state.currentStep >= this.state.totalSteps,
    };
  }

  /**
   * Reset demo configuration to defaults
   */
  resetConfig(): void {
    this.config = {
      autoAdvance: true,
      stepDuration: 3000,
      loop: false,
    };

    this.recordOperation('config', 'Configuration reset to defaults');
  }

  /**
   * Get demo analytics
   */
  getDemoAnalytics(): {
    stepsCompleted: number;
    operationCount: number;
    duration: number; // Seconds
  } {
    const duration = this.state.startedAt && this.state.completedAt
      ? Math.floor((new Date(this.state.completedAt).getTime() - new Date(this.state.startedAt).getTime()) / 1000)
      : 0;

    return {
      stepsCompleted: this.state.currentStep,
      operationCount: this.operations.length,
      duration,
    };
  }
}

