import React, { useState, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Slider } from './ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select';
import { Switch } from './ui/switch';
import { Badge } from './ui/badge';
import { Separator } from './ui/separator';
import {
  Volume2,
  Filter,
  Waves,
  Zap,
  Music,
  RotateCcw,
  Play,
  Pause,
  Download,
  Upload,
  Settings,
  X,
  Plus,
  Trash2
} from 'lucide-react';

interface AudioEffect {
  id: string;
  type: string;
  name: string;
  parameters: Record<string, unknown>;
  enabled: boolean;
}

interface AudioEffectsPanelProps {
  onApplyEffects?: (effects: AudioEffect[]) => void;
  onPreviewEffect?: (effect: AudioEffect) => void;
  className?: string;
}

const effectCategories = {
  basic: {
    name: 'Basic',
    icon: Volume2,
    effects: [
      { type: 'gain', name: 'Gain', params: { gain_db: 0 } },
      { type: 'normalize', name: 'Normalize', params: { target_peak: 0.95 } },
      { type: 'amplification', name: 'Amplify', params: { amplification: 1.0 } },
      { type: 'invert', name: 'Invert Phase', params: {} },
      { type: 'fade_in', name: 'Fade In', params: { duration_seconds: 1.0, curve: 'exponential' } },
      { type: 'fade_out', name: 'Fade Out', params: { duration_seconds: 1.0, curve: 'exponential' } }
    ]
  },
  filters: {
    name: 'Filters',
    icon: Filter,
    effects: [
      { type: 'low_pass', name: 'Low Pass', params: { cutoff_freq: 1000, order: 4 } },
      { type: 'high_pass', name: 'High Pass', params: { cutoff_freq: 100, order: 4 } },
      { type: 'band_pass', name: 'Band Pass', params: { low_freq: 300, high_freq: 3000, order: 4 } },
      { type: 'equalization', name: '3-Band EQ', params: { low_gain: 0, mid_gain: 0, high_gain: 0, low_freq: 100, mid_freq: 1000, high_freq: 5000, mid_q: 1.0 } }
    ]
  },
  dynamics: {
    name: 'Dynamics',
    icon: Waves,
    effects: [
      { type: 'compression', name: 'Compressor', params: { threshold_db: -20, ratio: 4, attack_time: 0.01, release_time: 0.1, knee_db: 2, makeup_gain_db: 0 } },
      { type: 'limiter', name: 'Limiter', params: { threshold_db: -6, release_time: 0.05 } }
    ]
  },
  timeBased: {
    name: 'Time-Based',
    icon: Music,
    effects: [
      { type: 'reverb', name: 'Reverb', params: { room_size: 0.5, damping: 0.5, wet_level: 0.3, dry_level: 0.7, width: 1.0, pre_delay: 0.01 } },
      { type: 'delay', name: 'Delay', params: { delay_time: 0.3, feedback: 0.4, wet_level: 0.3, dry_level: 0.7, high_cut: 8000 } },
      { type: 'phaser', name: 'Phaser', params: { rate: 0.5, depth: 0.7, feedback: 0.7, wet_level: 0.5, dry_level: 0.5 } }
    ]
  },
  pitch: {
    name: 'Pitch/Voice',
    icon: Zap,
    effects: [
      { type: 'pitch_shift', name: 'Pitch Shift', params: { semitones: 0, formant_preserve: true, quality: 'high' } },
      { type: 'auto_tune', name: 'Auto-Tune', params: { key: 'C', scale: 'major', correction_speed: 0.5, retune_amount: 1.0 } },
      { type: 'voice_modification', name: 'Voice Modify', params: { pitch_shift: 0, formant_shift: 0, gender_change: false } }
    ]
  },
  modulation: {
    name: 'Modulation',
    icon: Settings,
    effects: [
      { type: 'wah_wah', name: 'Wah-Wah', params: { rate: 2.0, depth: 0.7, resonance: 2.0, wet_level: 0.5, dry_level: 0.5 } },
      { type: 'vibrato', name: 'Vibrato', params: { rate: 5.0, depth: 0.5, wet_level: 0.5, dry_level: 0.5 } },
      { type: 'tremolo', name: 'Tremolo', params: { rate: 5.0, depth: 0.5, shape: 'sine', wet_level: 0.5, dry_level: 0.5 } }
    ]
  },
  creative: {
    name: 'Creative',
    icon: Plus,
    effects: [
      { type: 'distortion', name: 'Distortion', params: { drive: 5.0, tone: 0.5, wet_level: 0.5, dry_level: 0.5 } },
      { type: 'chorus', name: 'Chorus', params: { rate: 0.25, depth: 0.5, delay_time: 0.025, wet_level: 0.3, dry_level: 0.7 } },
      { type: 'doppler', name: 'Doppler', params: { speed: 10.0, direction: 'approaching' } }
    ]
  },
  utility: {
    name: 'Utility',
    icon: Settings,
    effects: [
      { type: 'dc_correction', name: 'DC Correction', params: {} },
      { type: 'swap_channels', name: 'Swap Channels', params: {} },
      { type: 'invert_channels', name: 'Invert Channels', params: {} },
      { type: 'noise_reduction', name: 'Noise Reduction', params: { reduction_db: -20, smoothing_factor: 0.8 } },
      { type: 'remove_clicks_pops', name: 'Remove Clicks', params: { threshold: 0.8, window_size: 512 } },
      { type: 'change_speed', name: 'Change Speed', params: { speed_ratio: 1.0 } }
    ]
  }
};

export function AudioEffectsPanel({
  onApplyEffects,
  onPreviewEffect,
  className = ''
}: AudioEffectsPanelProps) {
  const [activeCategory, setActiveCategory] = useState('basic');
  const [effectChain, setEffectChain] = useState<AudioEffect[]>([]);
  const [selectedEffect, setSelectedEffect] = useState<AudioEffect | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const addEffectToChain = useCallback((effectType: string, name: string, params: Record<string, unknown>) => {
    const newEffect: AudioEffect = {
      id: `${effectType}_${Date.now()}`,
      type: effectType,
      name,
      parameters: { ...params },
      enabled: true
    };

    setEffectChain(prev => [...prev, newEffect]);
    setSelectedEffect(newEffect);
  }, []);

  const removeEffectFromChain = useCallback((effectId: string) => {
    setEffectChain(prev => prev.filter(effect => effect.id !== effectId));
    if (selectedEffect?.id === effectId) {
      setSelectedEffect(null);
    }
  }, [selectedEffect]);

  const updateEffectParameter = useCallback((effectId: string, paramName: string, value: unknown) => {
    setEffectChain(prev => prev.map(effect =>
      effect.id === effectId
        ? { ...effect, parameters: { ...effect.parameters, [paramName]: value } }
        : effect
    ));

    if (selectedEffect?.id === effectId) {
      setSelectedEffect(prev => prev ? {
        ...prev,
        parameters: { ...prev.parameters, [paramName]: value }
      } : null);
    }
  }, [selectedEffect]);

  const toggleEffect = useCallback((effectId: string) => {
    setEffectChain(prev => prev.map(effect =>
      effect.id === effectId
        ? { ...effect, enabled: !effect.enabled }
        : effect
    ));

    if (selectedEffect?.id === effectId) {
      setSelectedEffect(prev => prev ? { ...prev, enabled: !prev.enabled } : null);
    }
  }, [selectedEffect]);

  const renderParameterControl = (paramName: string, paramValue: any, paramType: string = 'number') => {
    const commonProps = {
      className: "flex-1"
    };

    switch (paramType) {
      case 'range':
        const { min = 0, max = 100, step = 1 } = getParameterConfig(selectedEffect!.type, paramName) as any;
        return (
          <Slider
            {...commonProps}
            value={[paramValue]}
            onValueChange={([value]) => updateEffectParameter(selectedEffect!.id, paramName, value)}
            min={min}
            max={max}
            step={step}
            className="flex-1"
          />
        );

      case 'select':
        const config = getParameterConfig(selectedEffect!.type, paramName) as any;
        const options = config.options || [];
        return (
          <Select
            value={String(paramValue)}
            onValueChange={(value) => updateEffectParameter(selectedEffect!.id, paramName, value)}
          >
            <SelectTrigger className="flex-1">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {options.map((option: any) => (
                <SelectItem key={String(option)} value={String(option)}>
                  {String(option)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        );

      case 'boolean':
        return (
          <Switch
            checked={!!paramValue}
            onCheckedChange={(checked) => updateEffectParameter(selectedEffect!.id, paramName, checked)}
          />
        );

      default:
        return (
          <input
            type="number"
            value={paramValue}
            onChange={(e) => updateEffectParameter(selectedEffect!.id, paramName, parseFloat(e.target.value))}
            className="flex-1 px-2 py-1 border rounded text-sm"
            step="0.1"
          />
        );
    }
  };

  const getParameterConfig = (effectType: string, paramName: string) => {
    const configs: Record<string, Record<string, unknown>> = {
      gain: {
        gain_db: { type: 'range', min: -20, max: 20, step: 0.1 }
      },
      normalize: {
        target_peak: { type: 'range', min: 0.1, max: 1.0, step: 0.01 }
      },
      amplification: {
        amplification: { type: 'range', min: 0.1, max: 10.0, step: 0.1 }
      },
      fade_in: {
        duration_seconds: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        curve: { type: 'select', options: ['linear', 'exponential', 'logarithmic'] }
      },
      fade_out: {
        duration_seconds: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        curve: { type: 'select', options: ['linear', 'exponential', 'logarithmic'] }
      },
      low_pass: {
        cutoff_freq: { type: 'range', min: 20, max: 20000, step: 10 },
        order: { type: 'select', options: [2, 4, 6, 8] }
      },
      high_pass: {
        cutoff_freq: { type: 'range', min: 20, max: 20000, step: 10 },
        order: { type: 'select', options: [2, 4, 6, 8] }
      },
      band_pass: {
        low_freq: { type: 'range', min: 20, max: 20000, step: 10 },
        high_freq: { type: 'range', min: 20, max: 20000, step: 10 },
        order: { type: 'select', options: [2, 4, 6, 8] }
      },
      equalization: {
        low_gain: { type: 'range', min: -20, max: 20, step: 0.1 },
        mid_gain: { type: 'range', min: -20, max: 20, step: 0.1 },
        high_gain: { type: 'range', min: -20, max: 20, step: 0.1 },
        mid_q: { type: 'range', min: 0.1, max: 10.0, step: 0.1 }
      },
      compression: {
        threshold_db: { type: 'range', min: -60, max: 0, step: 0.1 },
        ratio: { type: 'range', min: 1, max: 20, step: 0.1 },
        attack_time: { type: 'range', min: 0.001, max: 1.0, step: 0.001 },
        release_time: { type: 'range', min: 0.01, max: 5.0, step: 0.01 },
        knee_db: { type: 'range', min: 0, max: 20, step: 0.1 },
        makeup_gain_db: { type: 'range', min: -20, max: 20, step: 0.1 }
      },
      limiter: {
        threshold_db: { type: 'range', min: -20, max: 0, step: 0.1 },
        release_time: { type: 'range', min: 0.01, max: 1.0, step: 0.01 }
      },
      reverb: {
        room_size: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        damping: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        width: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        pre_delay: { type: 'range', min: 0.0, max: 0.1, step: 0.001 }
      },
      delay: {
        delay_time: { type: 'range', min: 0.01, max: 5.0, step: 0.01 },
        feedback: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        high_cut: { type: 'range', min: 1000, max: 20000, step: 100 }
      },
      phaser: {
        rate: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        depth: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        feedback: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      pitch_shift: {
        semitones: { type: 'range', min: -24, max: 24, step: 0.1 },
        quality: { type: 'select', options: ['low', 'medium', 'high'] }
      },
      auto_tune: {
        key: { type: 'select', options: ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'] },
        scale: { type: 'select', options: ['major', 'minor', 'chromatic'] },
        correction_speed: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        retune_amount: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      voice_modification: {
        pitch_shift: { type: 'range', min: -12, max: 12, step: 0.1 },
        formant_shift: { type: 'range', min: 0.5, max: 2.0, step: 0.01 },
        gender_change: { type: 'boolean' }
      },
      wah_wah: {
        rate: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        depth: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        resonance: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      vibrato: {
        rate: { type: 'range', min: 0.1, max: 10.0, step: 0.1 },
        depth: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      tremolo: {
        rate: { type: 'range', min: 0.1, max: 20.0, step: 0.1 },
        depth: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        shape: { type: 'select', options: ['sine', 'square', 'triangle'] },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      distortion: {
        drive: { type: 'range', min: 1.0, max: 20.0, step: 0.1 },
        tone: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      chorus: {
        rate: { type: 'range', min: 0.01, max: 5.0, step: 0.01 },
        depth: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        delay_time: { type: 'range', min: 0.005, max: 0.05, step: 0.001 },
        wet_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 },
        dry_level: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      doppler: {
        speed: { type: 'range', min: 1.0, max: 50.0, step: 0.1 },
        direction: { type: 'select', options: ['approaching', 'receding'] }
      },
      noise_reduction: {
        reduction_db: { type: 'range', min: -40, max: 0, step: 0.1 },
        smoothing_factor: { type: 'range', min: 0.0, max: 1.0, step: 0.01 }
      },
      remove_clicks_pops: {
        threshold: { type: 'range', min: 0.1, max: 5.0, step: 0.1 },
        window_size: { type: 'range', min: 128, max: 2048, step: 64 }
      },
      change_speed: {
        speed_ratio: { type: 'range', min: 0.25, max: 4.0, step: 0.01 }
      }
    };

    return configs[effectType]?.[paramName] || { type: 'number' };
  };

  return (
    <div className={`audio-effects-panel ${className}`}>
      <Card className="w-full">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Volume2 className="w-5 h-5" />
            Audio Effects
          </CardTitle>
          <CardDescription>
            Apply professional audio effects to your project
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-6">
          {/* Category Tabs */}
          <div className="flex flex-wrap gap-2">
            {Object.entries(effectCategories).map(([key, category]) => (
              <Button
                key={key}
                variant={activeCategory === key ? "default" : "outline"}
                size="sm"
                onClick={() => setActiveCategory(key)}
                className="flex items-center gap-1"
              >
                <category.icon className="w-4 h-4" />
                {category.name}
              </Button>
            ))}
          </div>

          {/* Effects Grid */}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {effectCategories[activeCategory as keyof typeof effectCategories].effects.map((effect) => (
              <Button
                key={effect.type}
                variant="outline"
                className="h-auto p-3 flex flex-col items-center gap-2 hover:bg-accent"
                onClick={() => addEffectToChain(effect.type, effect.name, effect.params)}
              >
                <span className="text-sm font-medium">{effect.name}</span>
                <Plus className="w-4 h-4" />
              </Button>
            ))}
          </div>

          <Separator />

          {/* Effect Chain */}
          <div>
            <h3 className="text-lg font-semibold mb-3">Effect Chain ({effectChain.length})</h3>
            <div className="space-y-2">
              {effectChain.map((effect, index) => (
                <div
                  key={effect.id}
                  className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${selectedEffect?.id === effect.id ? 'bg-accent border-primary' : 'hover:bg-muted'
                    }`}
                  onClick={() => setSelectedEffect(effect)}
                >
                  <span className="text-sm font-medium w-8">{index + 1}</span>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium">{effect.name}</span>
                      <Badge variant={effect.enabled ? "default" : "secondary"}>
                        {effect.enabled ? "On" : "Off"}
                      </Badge>
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleEffect(effect.id);
                      }}
                      className="w-8 h-8 p-0"
                    >
                      {effect.enabled ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={(e) => {
                        e.stopPropagation();
                        onPreviewEffect?.(effect);
                      }}
                      className="w-8 h-8 p-0"
                    >
                      <Play className="w-4 h-4" />
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={(e) => {
                        e.stopPropagation();
                        removeEffectFromChain(effect.id);
                      }}
                      className="w-8 h-8 p-0 text-destructive hover:text-destructive"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Effect Parameters */}
          {selectedEffect && (
            <div>
              <Separator className="mb-4" />
              <h3 className="text-lg font-semibold mb-3">
                {selectedEffect.name} Parameters
              </h3>
              <div className="space-y-4">
                {Object.entries(selectedEffect.parameters).map(([paramName, paramValue]) => {
                  const config = getParameterConfig(selectedEffect.type, paramName) as any;
                  return (
                    <div key={paramName} className="flex items-center gap-4">
                      <label className="text-sm font-medium w-32 capitalize">
                        {paramName.replace(/_/g, ' ')}:
                      </label>
                      <div className="flex-1">
                        {renderParameterControl(paramName, paramValue, config.type)}
                      </div>
                      <span className="text-sm text-muted-foreground w-16 text-right">
                        {typeof paramValue === 'number' ? paramValue.toFixed(2) : String(paramValue)}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex gap-2 pt-4">
            <Button
              onClick={() => onApplyEffects?.(effectChain)}
              disabled={effectChain.length === 0}
              className="flex-1"
            >
              <Zap className="w-4 h-4 mr-2" />
              Apply Effects ({effectChain.filter(e => e.enabled).length})
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                setEffectChain([]);
                setSelectedEffect(null);
              }}
              disabled={effectChain.length === 0}
            >
              <RotateCcw className="w-4 h-4 mr-2" />
              Clear All
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from 'react';
import { useStore } from '../store';
import type { AudioTrack } from '../types';
import { Volume2, VolumeX, Music, Mic, Radio, Headphones, Trash2, Settings } from 'lucide-react';
import { WaveformDisplay, generateWaveformData } from './WaveformDisplay';
import { AudioPlayer } from './AudioPlayer';
import { AudioEffectsPanel } from './AudioEffectsPanel';

interface AudioPanelProps {
  shotId: string;
}

export const AudioPanel: React.FC<AudioPanelProps> = ({ shotId }) => {
  const shot = useStore((state) => state.shots.find((s) => s.id === shotId));
  const addAudioTrack = useStore((state) => state.addAudioTrack);
  const updateAudioTrack = useStore((state) => state.updateAudioTrack);
  const deleteAudioTrack = useStore((state) => state.deleteAudioTrack);

  const [showAddTrack, setShowAddTrack] = useState(false);

  if (!shot) {
    return (
      <div className="p-4 text-gray-500">
        No shot selected. Select a shot to manage audio tracks.
      </div>
    );
  }

  const handleAddTrack = (type: AudioTrack['type']) => {
    const newTrack: AudioTrack = {
      id: `track-${Date.now()}`,
      name: `${type.charAt(0).toUpperCase() + type.slice(1)} Track`,
      type,
      url: '',
      startTime: 0,
      duration: shot.duration,
      offset: 0,
      volume: 80,
      fadeIn: 0,
      fadeOut: 0,
      pan: 0,
      muted: false,
      solo: false,
      effects: [],
    };

    addAudioTrack(shotId, newTrack);
    setShowAddTrack(false);
  };

  const handleDeleteTrack = (trackId: string) => {
    if (confirm('Are you sure you want to delete this audio track?')) {
      deleteAudioTrack(shotId, trackId);
    }
  };

  const handleToggleMute = (trackId: string, currentMuted: boolean) => {
    updateAudioTrack(shotId, trackId, { muted: !currentMuted });
  };

  const handleToggleSolo = (trackId: string, currentSolo: boolean) => {
    updateAudioTrack(shotId, trackId, { solo: !currentSolo });
  };

  const getTrackIcon = (type: AudioTrack['type']) => {
    switch (type) {
      case 'music':
        return <Music className="w-4 h-4" />;
      case 'dialogue':
        return <Mic className="w-4 h-4" />;
      case 'voiceover':
        return <Headphones className="w-4 h-4" />;
      case 'sfx':
        return <Radio className="w-4 h-4" />;
      case 'ambient':
        return <Volume2 className="w-4 h-4" />;
      default:
        return <Volume2 className="w-4 h-4" />;
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div>
        <h3 className="text-lg font-semibold mb-2">Audio Tracks</h3>
        <p className="text-sm text-gray-600">
          Manage audio tracks for this shot
        </p>
      </div>

      {/* Audio Tracks List */}
      <div className="space-y-3">
        {shot.audioTracks.length === 0 ? (
          <div className="text-center py-8 border border-dashed rounded">
            <Volume2 className="w-12 h-12 mx-auto text-gray-400 mb-2" />
            <p className="text-gray-500 mb-4">No audio tracks</p>
            <button
              onClick={() => setShowAddTrack(true)}
              className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
            >
              Add Audio Track
            </button>
          </div>
        ) : (
          <>
            {shot.audioTracks.map((track) => (
              <AudioTrackCard
                key={track.id}
                track={track}
                shotId={shotId}
                onDelete={() => handleDeleteTrack(track.id)}
                onToggleMute={() => handleToggleMute(track.id, track.muted)}
                onToggleSolo={() => handleToggleSolo(track.id, track.solo)}
                getIcon={getTrackIcon}
              />
            ))}

            <button
              onClick={() => setShowAddTrack(true)}
              className="w-full px-4 py-2 border-2 border-dashed border-gray-300 rounded text-gray-600 hover:border-blue-500 hover:text-blue-600"
            >
              + Add Audio Track
            </button>
          </>
        )}
      </div>

      {/* Add Track Modal */}
      {showAddTrack && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Add Audio Track</h3>
            <p className="text-sm text-gray-600 mb-4">
              Select the type of audio track to add:
            </p>

            <div className="space-y-2">
              {(['music', 'dialogue', 'voiceover', 'sfx', 'ambient'] as const).map(
                (type) => (
                  <button
                    key={type}
                    onClick={() => handleAddTrack(type)}
                    className="w-full flex items-center gap-3 px-4 py-3 border rounded hover:bg-gray-50 hover:border-blue-500"
                  >
                    {getTrackIcon(type)}
                    <span className="capitalize">{type}</span>
                  </button>
                )
              )}
            </div>

            <button
              onClick={() => setShowAddTrack(false)}
              className="w-full mt-4 px-4 py-2 border rounded hover:bg-gray-50"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// Audio Track Card Component
interface AudioTrackCardProps {
  track: AudioTrack;
  shotId: string;
  onDelete: () => void;
  onToggleMute: () => void;
  onToggleSolo: () => void;
  getIcon: (type: AudioTrack['type']) => React.ReactNode;
}

const AudioTrackCard: React.FC<AudioTrackCardProps> = ({
  track,
  shotId,
  onDelete,
  onToggleMute,
  onToggleSolo,
  getIcon,
}) => {
  const updateAudioTrack = useStore((state) => state.updateAudioTrack);
  const [showEffects, setShowEffects] = useState(false);

  const handleWaveformGenerated = async (waveformData: number[]) => {
    // Store waveform data in the track
    updateAudioTrack(shotId, track.id, { waveformData });
  };

  return (
    <div className="border rounded p-3 space-y-3 bg-gray-50">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="text-gray-600">{getIcon(track.type)}</div>
          <input
            type="text"
            value={track.name}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, { name: e.target.value })
            }
            className="font-medium bg-transparent border-none focus:outline-none focus:ring-1 focus:ring-blue-500 rounded px-1"
            aria-label="Track name"
            title="Track name"
            placeholder="Enter track name"
          />
        </div>
        <button
          onClick={onDelete}
          className="text-red-600 hover:text-red-800"
          title="Delete track"
        >
          <Trash2 className="w-4 h-4" />
        </button>
      </div>

      {/* Track Type Badge */}
      <div className="flex items-center gap-2">
        <span className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded capitalize">
          {track.type}
        </span>
        {track.muted && (
          <span className="text-xs px-2 py-1 bg-gray-200 text-gray-700 rounded">
            Muted
          </span>
        )}
        {track.solo && (
          <span className="text-xs px-2 py-1 bg-yellow-100 text-yellow-700 rounded">
            Solo
          </span>
        )}
      </div>

      {/* Audio File */}
      <div>
        <label htmlFor={`audio-file-${track.id}`} className="text-xs text-gray-600">
          Audio File
        </label>
        <input
          id={`audio-file-${track.id}`}
          type="text"
          value={track.url}
          onChange={(e) =>
            updateAudioTrack(shotId, track.id, { url: e.target.value })
          }
          placeholder="Enter audio file URL or path"
          className="w-full px-2 py-1 text-sm border rounded"
          aria-label="Audio file URL"
        />
      </div>

      {/* Waveform Visualization */}
      {track.url && (
        <div>
          <label className="text-xs text-gray-600 mb-1 block">Waveform</label>
          <WaveformDisplay
            track={track}
            width={280}
            height={50}
            onGenerate={handleWaveformGenerated}
          />
        </div>
      )}

      {/* Audio Player Controls */}
      {track.url && (
        <div>
          <label className="text-xs text-gray-600 mb-1 block">Playback</label>
          <AudioPlayer track={track} />
        </div>
      )}

      {/* Timing Controls */}
      <div className="grid grid-cols-3 gap-2">
        <div>
          <label htmlFor={`start-time-${track.id}`} className="text-xs text-gray-600">
            Start (s)
          </label>
          <input
            id={`start-time-${track.id}`}
            type="number"
            min={0}
            step={0.1}
            value={track.startTime}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, {
                startTime: parseFloat(e.target.value),
              })
            }
            className="w-full px-2 py-1 text-sm border rounded"
            aria-label="Start time in seconds"
            placeholder="0.0"
          />
        </div>
        <div>
          <label htmlFor={`duration-${track.id}`} className="text-xs text-gray-600">
            Duration (s)
          </label>
          <input
            id={`duration-${track.id}`}
            type="number"
            min={0.1}
            step={0.1}
            value={track.duration}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, {
                duration: parseFloat(e.target.value),
              })
            }
            className="w-full px-2 py-1 text-sm border rounded"
            aria-label="Duration in seconds"
            placeholder="1.0"
          />
        </div>
        <div>
          <label htmlFor={`offset-${track.id}`} className="text-xs text-gray-600">
            Offset (s)
          </label>
          <input
            id={`offset-${track.id}`}
            type="number"
            min={0}
            step={0.1}
            value={track.offset}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, {
                offset: parseFloat(e.target.value),
              })
            }
            className="w-full px-2 py-1 text-sm border rounded"
            aria-label="Offset in seconds"
            placeholder="0.0"
          />
        </div>
      </div>

      {/* Volume Control */}
      <div>
        <div className="flex items-center justify-between mb-1">
          <label htmlFor={`volume-${track.id}`} className="text-xs text-gray-600">
            Volume
          </label>
          <span className="text-xs text-gray-500">{track.volume}%</span>
        </div>
        <input
          id={`volume-${track.id}`}
          type="range"
          min={0}
          max={100}
          value={track.volume}
          onChange={(e) =>
            updateAudioTrack(shotId, track.id, {
              volume: parseInt(e.target.value),
            })
          }
          className="w-full"
          aria-label="Volume level"
        />
      </div>

      {/* Pan Control */}
      <div>
        <div className="flex items-center justify-between mb-1">
          <label htmlFor={`pan-${track.id}`} className="text-xs text-gray-600">
            Pan (L/R)
          </label>
          <span className="text-xs text-gray-500">
            {track.pan === 0
              ? 'Center'
              : track.pan < 0
                ? `${Math.abs(track.pan)}% L`
                : `${track.pan}% R`}
          </span>
        </div>
        <input
          id={`pan-${track.id}`}
          type="range"
          min={-100}
          max={100}
          value={track.pan}
          onChange={(e) =>
            updateAudioTrack(shotId, track.id, {
              pan: parseInt(e.target.value),
            })
          }
          className="w-full"
          aria-label="Pan position"
        />
      </div>

      {/* Fade Controls */}
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label htmlFor={`fade-in-${track.id}`} className="text-xs text-gray-600">
            Fade In (s)
          </label>
          <input
            id={`fade-in-${track.id}`}
            type="number"
            min={0}
            step={0.1}
            value={track.fadeIn}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, {
                fadeIn: parseFloat(e.target.value),
              })
            }
            className="w-full px-2 py-1 text-sm border rounded"
            aria-label="Fade in duration"
            placeholder="0.0"
          />
        </div>
        <div>
          <label htmlFor={`fade-out-${track.id}`} className="text-xs text-gray-600">
            Fade Out (s)
          </label>
          <input
            id={`fade-out-${track.id}`}
            type="number"
            min={0}
            step={0.1}
            value={track.fadeOut}
            onChange={(e) =>
              updateAudioTrack(shotId, track.id, {
                fadeOut: parseFloat(e.target.value),
              })
            }
            className="w-full px-2 py-1 text-sm border rounded"
            aria-label="Fade out duration"
            placeholder="0.0"
          />
        </div>
      </div>

      {/* Mute/Solo Buttons */}
      <div className="flex gap-2">
        <button
          onClick={onToggleMute}
          className={`flex-1 px-3 py-2 text-sm rounded border $
            ${track.muted
              ? 'bg-gray-600 text-white border-gray-700'
              : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}
          `}
          aria-label={track.muted ? 'Unmute track' : 'Mute track'}
        >
          {track.muted ? <VolumeX className="w-4 h-4 mx-auto" /> : 'Mute'}
        </button>
        <button
          onClick={onToggleSolo}
          className={`flex-1 px-3 py-2 text-sm rounded border $
            ${track.solo
              ? 'bg-yellow-500 text-white border-yellow-600'
              : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}
          `}
          aria-label={track.solo ? 'Disable solo' : 'Enable solo'}
        >
          Solo
        </button>
      </div>

      {/* Effects Count */}
      {track.effects.length > 0 && (
        <div className="flex items-center justify-between">
          <div className="text-xs text-gray-600">
            {track.effects.length} effect{track.effects.length !== 1 ? 's' : ''}{' '}
            applied
          </div>
          <button
            onClick={() => setShowEffects(!showEffects)}
            className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded hover:bg-blue-200"
            aria-label={showEffects ? 'Hide effects panel' : 'Show effects panel'}
          >
            <Settings className="w-3 h-3 inline mr-1" />
            {showEffects ? 'Hide' : 'Show'} Effects
          </button>
        </div>
      )}

      {!track.effects.length && (
        <button
          onClick={() => setShowEffects(!showEffects)}
          className="w-full text-xs px-2 py-1 border border-dashed rounded text-gray-600 hover:border-blue-500 hover:text-blue-600"
          aria-label="Add audio effects"
        >
          <Settings className="w-3 h-3 inline mr-1" />
          Add Audio Effects
        </button>
      )}

      {/* Effects Panel */}
      {showEffects && (
        <div className="border-t pt-3 -mx-3 -mb-3">
          <AudioEffectsPanel
            onApplyEffects={(effects: any) => {
              updateAudioTrack(shotId, track.id, { effects });
            }}
          />
        </div>
      )}
    </div>
  );
};

/**
 * AudioTimeline - Visual timeline for audio and shot management
 * 
 * Provides a zoomable timeline canvas with shot boundaries, draggable dialogue phrases,
 * playhead indicator, and snap-to-grid functionality.
 * 
 * Requirements: 4.1, 7.4
 */

import React, { useRef, useEffect, useState, useCallback } from 'react';
import type { Shot, DialoguePhrase } from '../types/projectDashboard';

// ============================================================================
// Constants
// ============================================================================

const MIN_ZOOM = 10; // 10 seconds visible
const MAX_ZOOM = 300; // 300 seconds visible
const DEFAULT_ZOOM = 60; // 60 seconds visible
const TIMELINE_HEIGHT = 200;
const SHOT_TRACK_HEIGHT = 40;
const PHRASE_TRACK_HEIGHT = 60;
const PLAYHEAD_WIDTH = 2;
const SNAP_THRESHOLD = 0.5; // seconds
const GRID_INTERVAL = 5; // seconds

// ============================================================================
// Component Props
// ============================================================================

export interface AudioTimelineProps {
  shots: Shot[];
  phrases: DialoguePhrase[];
  duration: number;
  currentTime: number;
  onPhraseMove: (phraseId: string, newStartTime: number) => void;
  onPhraseResize: (phraseId: string, newDuration: number) => void;
  onTimelineClick: (time: number) => void;
  className?: string;
}

// ============================================================================
// Drag State Interface
// ============================================================================

interface DragState {
  phraseId: string;
  type: 'move' | 'resize-start' | 'resize-end';
  startX: number;
  startTime: number;
  originalStartTime: number;
  originalEndTime: number;
}

// ============================================================================
// Component
// ============================================================================

export const AudioTimeline: React.FC<AudioTimelineProps> = ({
  shots,
  phrases,
  duration,
  currentTime,
  onPhraseMove,
  onPhraseResize,
  onTimelineClick,
  className = '',
}) => {
  // ============================================================================
  // Refs
  // ============================================================================

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // ============================================================================
  // State
  // ============================================================================

  const [zoom, setZoom] = useState(DEFAULT_ZOOM); // seconds visible
  const [scrollOffset, setScrollOffset] = useState(0);
  const [dragState, setDragState] = useState<DragState | null>(null);
  const [hoveredPhrase, setHoveredPhrase] = useState<string | null>(null);

  // ============================================================================
  // Computed Values
  // ============================================================================

  const pixelsPerSecond = canvasRef.current ? canvasRef.current.width / zoom : 0;

  /**
   * Convert time (seconds) to canvas x position
   */
  const timeToX = useCallback((time: number): number => {
    return time * pixelsPerSecond - scrollOffset;
  }, [pixelsPerSecond, scrollOffset]);

  /**
   * Convert canvas x position to time (seconds)
   */
  const xToTime = useCallback((x: number): number => {
    return (x + scrollOffset) / pixelsPerSecond;
  }, [pixelsPerSecond, scrollOffset]);

  /**
   * Snap time to grid if within threshold
   */
  const snapToGrid = useCallback((time: number): number => {
    const gridTime = Math.round(time / GRID_INTERVAL) * GRID_INTERVAL;
    if (Math.abs(time - gridTime) < SNAP_THRESHOLD) {
      return gridTime;
    }
    return time;
  }, []);

  /**
   * Check if phrase overlaps with any other phrase
   */
  const checkOverlap = useCallback((
    phraseId: string,
    startTime: number,
    endTime: number
  ): boolean => {
    return phrases.some(phrase => {
      if (phrase.id === phraseId) return false;
      return !(endTime <= phrase.startTime || startTime >= phrase.endTime);
    });
  }, [phrases]);

  // ============================================================================
  // Drawing Functions
  // ============================================================================

  /**
   * Draw the timeline canvas
   */
  const drawTimeline = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    for (let t = 0; t <= duration; t += GRID_INTERVAL) {
      const x = timeToX(t);
      if (x >= 0 && x <= canvas.width) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();

        // Draw time labels
        ctx.fillStyle = '#666';
        ctx.font = '10px sans-serif';
        ctx.fillText(`${t}s`, x + 2, 12);
      }
    }

    // Draw shot track
    const shotTrackY = 20;
    ctx.fillStyle = '#2a2a2a';
    ctx.fillRect(0, shotTrackY, canvas.width, SHOT_TRACK_HEIGHT);

    // Draw shot boundaries
    shots.forEach(shot => {
      const x = timeToX(shot.startTime);
      const width = (shot.duration * pixelsPerSecond);

      if (x + width >= 0 && x <= canvas.width) {
        // Shot background
        ctx.fillStyle = '#3a3a3a';
        ctx.fillRect(x, shotTrackY, width, SHOT_TRACK_HEIGHT);

        // Shot border
        ctx.strokeStyle = '#4a9eff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, shotTrackY, width, SHOT_TRACK_HEIGHT);

        // Shot label
        ctx.fillStyle = '#fff';
        ctx.font = '12px sans-serif';
        const label = `Shot ${shot.id.slice(-4)}`;
        ctx.fillText(label, x + 5, shotTrackY + 25);
      }
    });

    // Draw phrase track
    const phraseTrackY = shotTrackY + SHOT_TRACK_HEIGHT + 10;
    ctx.fillStyle = '#2a2a2a';
    ctx.fillRect(0, phraseTrackY, canvas.width, PHRASE_TRACK_HEIGHT);

    // Draw dialogue phrases
    phrases.forEach(phrase => {
      const x = timeToX(phrase.startTime);
      const width = ((phrase.endTime - phrase.startTime) * pixelsPerSecond);

      if (x + width >= 0 && x <= canvas.width) {
        const isHovered = hoveredPhrase === phrase.id;
        const isDragging = dragState?.phraseId === phrase.id;

        // Phrase background
        ctx.fillStyle = isDragging ? '#ff6b6b' : isHovered ? '#5a9eff' : '#4a9eff';
        ctx.fillRect(x, phraseTrackY, width, PHRASE_TRACK_HEIGHT);

        // Phrase border
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.strokeRect(x, phraseTrackY, width, PHRASE_TRACK_HEIGHT);

        // Phrase text
        ctx.fillStyle = '#fff';
        ctx.font = '11px sans-serif';
        const text = phrase.text.length > 20 ? phrase.text.slice(0, 20) + '...' : phrase.text;
        ctx.fillText(text, x + 5, phraseTrackY + 20);

        // Duration label
        ctx.font = '9px sans-serif';
        ctx.fillStyle = '#ccc';
        const durationText = `${(phrase.endTime - phrase.startTime).toFixed(1)}s`;
        ctx.fillText(durationText, x + 5, phraseTrackY + 35);

        // Resize handles
        if (isHovered || isDragging) {
          ctx.fillStyle = '#fff';
          // Left handle
          ctx.fillRect(x, phraseTrackY, 4, PHRASE_TRACK_HEIGHT);
          // Right handle
          ctx.fillRect(x + width - 4, phraseTrackY, 4, PHRASE_TRACK_HEIGHT);
        }
      }
    });

    // Draw playhead
    const playheadX = timeToX(currentTime);
    if (playheadX >= 0 && playheadX <= canvas.width) {
      ctx.fillStyle = '#ff4444';
      ctx.fillRect(playheadX - PLAYHEAD_WIDTH / 2, 0, PLAYHEAD_WIDTH, canvas.height);

      // Playhead time label
      ctx.fillStyle = '#ff4444';
      ctx.font = 'bold 11px sans-serif';
      ctx.fillText(`${currentTime.toFixed(1)}s`, playheadX + 5, 12);
    }
  }, [
    shots,
    phrases,
    duration,
    currentTime,
    timeToX,
    pixelsPerSecond,
    hoveredPhrase,
    dragState,
  ]);

  // ============================================================================
  // Mouse Event Handlers
  // ============================================================================

  /**
   * Handle mouse down - start drag operation
   */
  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const time = xToTime(x);

    const phraseTrackY = 20 + SHOT_TRACK_HEIGHT + 10;

    // Check if clicking on a phrase
    if (y >= phraseTrackY && y <= phraseTrackY + PHRASE_TRACK_HEIGHT) {
      for (const phrase of phrases) {
        const phraseX = timeToX(phrase.startTime);
        const phraseWidth = (phrase.endTime - phrase.startTime) * pixelsPerSecond;

        if (x >= phraseX && x <= phraseX + phraseWidth) {
          // Check if clicking on resize handles
          if (x <= phraseX + 4) {
            // Left handle - resize start
            setDragState({
              phraseId: phrase.id,
              type: 'resize-start',
              startX: x,
              startTime: time,
              originalStartTime: phrase.startTime,
              originalEndTime: phrase.endTime,
            });
          } else if (x >= phraseX + phraseWidth - 4) {
            // Right handle - resize end
            setDragState({
              phraseId: phrase.id,
              type: 'resize-end',
              startX: x,
              startTime: time,
              originalStartTime: phrase.startTime,
              originalEndTime: phrase.endTime,
            });
          } else {
            // Middle - move
            setDragState({
              phraseId: phrase.id,
              type: 'move',
              startX: x,
              startTime: time,
              originalStartTime: phrase.startTime,
              originalEndTime: phrase.endTime,
            });
          }
          return;
        }
      }
    }

    // If not clicking on a phrase, trigger timeline click
    onTimelineClick(time);
  }, [phrases, timeToX, xToTime, pixelsPerSecond, onTimelineClick]);

  /**
   * Handle mouse move - update drag operation or hover state
   */
  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const time = xToTime(x);

    // Handle dragging
    if (dragState) {
      const timeDelta = time - dragState.startTime;

      if (dragState.type === 'move') {
        let newStartTime = snapToGrid(dragState.originalStartTime + timeDelta);
        const duration = dragState.originalEndTime - dragState.originalStartTime;
        const newEndTime = newStartTime + duration;

        // Clamp to timeline bounds
        if (newStartTime < 0) newStartTime = 0;
        if (newEndTime > duration) newStartTime = duration - duration;

        // Check for overlaps
        if (!checkOverlap(dragState.phraseId, newStartTime, newEndTime)) {
          onPhraseMove(dragState.phraseId, newStartTime);
        }
      } else if (dragState.type === 'resize-start') {
        let newStartTime = snapToGrid(dragState.originalStartTime + timeDelta);

        // Ensure minimum duration of 0.5 seconds
        if (newStartTime >= dragState.originalEndTime - 0.5) {
          newStartTime = dragState.originalEndTime - 0.5;
        }
        if (newStartTime < 0) newStartTime = 0;

        // Check for overlaps
        if (!checkOverlap(dragState.phraseId, newStartTime, dragState.originalEndTime)) {
          const newDuration = dragState.originalEndTime - newStartTime;
          onPhraseMove(dragState.phraseId, newStartTime);
          onPhraseResize(dragState.phraseId, newDuration);
        }
      } else if (dragState.type === 'resize-end') {
        let newEndTime = snapToGrid(dragState.originalEndTime + timeDelta);

        // Ensure minimum duration of 0.5 seconds
        if (newEndTime <= dragState.originalStartTime + 0.5) {
          newEndTime = dragState.originalStartTime + 0.5;
        }
        if (newEndTime > duration) newEndTime = duration;

        // Check for overlaps
        if (!checkOverlap(dragState.phraseId, dragState.originalStartTime, newEndTime)) {
          const newDuration = newEndTime - dragState.originalStartTime;
          onPhraseResize(dragState.phraseId, newDuration);
        }
      }

      return;
    }

    // Handle hover state
    const phraseTrackY = 20 + SHOT_TRACK_HEIGHT + 10;
    if (y >= phraseTrackY && y <= phraseTrackY + PHRASE_TRACK_HEIGHT) {
      let foundPhrase: string | null = null;

      for (const phrase of phrases) {
        const phraseX = timeToX(phrase.startTime);
        const phraseWidth = (phrase.endTime - phrase.startTime) * pixelsPerSecond;

        if (x >= phraseX && x <= phraseX + phraseWidth) {
          foundPhrase = phrase.id;
          break;
        }
      }

      setHoveredPhrase(foundPhrase);
    } else {
      setHoveredPhrase(null);
    }
  }, [
    dragState,
    phrases,
    duration,
    xToTime,
    timeToX,
    pixelsPerSecond,
    snapToGrid,
    checkOverlap,
    onPhraseMove,
    onPhraseResize,
  ]);

  /**
   * Handle mouse up - end drag operation
   */
  const handleMouseUp = useCallback(() => {
    setDragState(null);
  }, []);

  /**
   * Handle mouse leave - end drag operation and clear hover
   */
  const handleMouseLeave = useCallback(() => {
    setDragState(null);
    setHoveredPhrase(null);
  }, []);

  /**
   * Handle wheel - zoom in/out
   */
  const handleWheel = useCallback((e: React.WheelEvent<HTMLCanvasElement>) => {
    e.preventDefault();

    const zoomDelta = e.deltaY > 0 ? 10 : -10;
    const newZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, zoom + zoomDelta));
    setZoom(newZoom);
  }, [zoom]);

  // ============================================================================
  // Effects
  // ============================================================================

  /**
   * Redraw timeline when dependencies change
   */
  useEffect(() => {
    drawTimeline();
  }, [drawTimeline]);

  /**
   * Handle canvas resize
   */
  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const resizeObserver = new ResizeObserver(() => {
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = TIMELINE_HEIGHT;
      drawTimeline();
    });

    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [drawTimeline]);

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div className={`audio-timeline ${className}`}>
      {/* Zoom Controls */}
      <div className="timeline-controls" style={styles.controls}>
        <button
          onClick={() => setZoom(Math.max(MIN_ZOOM, zoom - 10))}
          style={styles.button}
          disabled={zoom <= MIN_ZOOM}
        >
          Zoom In
        </button>
        <span style={styles.zoomLabel}>{zoom}s</span>
        <button
          onClick={() => setZoom(Math.min(MAX_ZOOM, zoom + 10))}
          style={styles.button}
          disabled={zoom >= MAX_ZOOM}
        >
          Zoom Out
        </button>
        <button
          onClick={() => setZoom(DEFAULT_ZOOM)}
          style={styles.button}
        >
          Reset
        </button>
      </div>

      {/* Timeline Canvas */}
      <div ref={containerRef} style={styles.container}>
        <canvas
          ref={canvasRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseLeave}
          onWheel={handleWheel}
          style={styles.canvas}
        />
      </div>

      {/* Legend */}
      <div style={styles.legend}>
        <div style={styles.legendItem}>
          <div style={{ ...styles.legendColor, backgroundColor: '#4a9eff' }} />
          <span>Shot Boundary</span>
        </div>
        <div style={styles.legendItem}>
          <div style={{ ...styles.legendColor, backgroundColor: '#4a9eff' }} />
          <span>Dialogue Phrase</span>
        </div>
        <div style={styles.legendItem}>
          <div style={{ ...styles.legendColor, backgroundColor: '#ff4444' }} />
          <span>Playhead</span>
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Styles
// ============================================================================

const styles: Record<string, React.CSSProperties> = {
  controls: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    padding: '10px',
    backgroundColor: '#2a2a2a',
    borderRadius: '4px',
    marginBottom: '10px',
  },
  button: {
    padding: '6px 12px',
    backgroundColor: '#4a9eff',
    color: '#fff',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '12px',
  },
  zoomLabel: {
    color: '#fff',
    fontSize: '12px',
    fontWeight: 'bold',
  },
  container: {
    width: '100%',
    height: `${TIMELINE_HEIGHT}px`,
    backgroundColor: '#1a1a1a',
    borderRadius: '4px',
    overflow: 'hidden',
  },
  canvas: {
    display: 'block',
    cursor: 'crosshair',
  },
  legend: {
    display: 'flex',
    gap: '20px',
    padding: '10px',
    marginTop: '10px',
  },
  legendItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    fontSize: '12px',
    color: '#ccc',
  },
  legendColor: {
    width: '16px',
    height: '16px',
    borderRadius: '2px',
  },
};

export default AudioTimeline;

/**
 * AudioTrackManager - Container component for audio track management
 * 
 * Integrates AudioTimeline, DialoguePhraseEditor, and VoiceGenerationPanel
 * to provide a complete workflow for creating, editing, and generating
 * dialogue phrases synchronized with shot timing.
 * 
 * Requirements: 4.1, 4.2, 4.3, 5.1
 */

import React, { useState, useCallback, useMemo } from 'react';
import { AudioTimeline } from './AudioTimeline';
import { DialoguePhraseEditor } from './DialoguePhraseEditor';
import { VoiceGenerationPanel } from './VoiceGenerationPanel';
import { useProject } from '../contexts/ProjectContext';
import type { DialoguePhrase, VoiceParameters } from '../types/projectDashboard';
import { Button } from './ui/button';

// ============================================================================
// Component Props
// ============================================================================

export interface AudioTrackManagerProps {
  className?: string;
}

// ============================================================================
// Component
// ============================================================================

export const AudioTrackManager: React.FC<AudioTrackManagerProps> = ({
  className = '',
}) => {
  // ============================================================================
  // Context
  // ============================================================================

  const {
    project,
    addDialoguePhrase,
    updateDialoguePhrase,
    deleteDialoguePhrase,
  } = useProject();

  // ============================================================================
  // State
  // ============================================================================

  const [selectedPhraseId, setSelectedPhraseId] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [isGeneratingVoice, setIsGeneratingVoice] = useState(false);

  // ============================================================================
  // Computed Values
  // ============================================================================

  const shots = project?.shots || [];
  const phrases = project?.audioPhrases || [];
  
  // Calculate total duration from shots
  const totalDuration = useMemo(() => {
    if (shots.length === 0) return 60; // Default 60 seconds
    return Math.max(...shots.map(shot => shot.startTime + shot.duration), 60);
  }, [shots]);

  // Get selected phrase
  const selectedPhrase = useMemo(() => {
    if (!selectedPhraseId) return null;
    return phrases.find(p => p.id === selectedPhraseId) || null;
  }, [selectedPhraseId, phrases]);

  // ============================================================================
  // Event Handlers - Timeline
  // ============================================================================

  /**
   * Handle phrase move on timeline
   * Requirements: 4.1, 7.1
   */
  const handlePhraseMove = useCallback((phraseId: string, newStartTime: number) => {
    const phrase = phrases.find(p => p.id === phraseId);
    if (!phrase) return;

    const duration = phrase.endTime - phrase.startTime;
    const newEndTime = newStartTime + duration;

    updateDialoguePhrase(phraseId, {
      startTime: newStartTime,
      endTime: newEndTime,
    });
  }, [phrases, updateDialoguePhrase]);

  /**
   * Handle phrase resize on timeline
   * Requirements: 4.1, 7.2
   */
  const handlePhraseResize = useCallback((phraseId: string, newDuration: number) => {
    const phrase = phrases.find(p => p.id === phraseId);
    if (!phrase) return;

    const newEndTime = phrase.startTime + newDuration;

    updateDialoguePhrase(phraseId, {
      endTime: newEndTime,
    });
  }, [phrases, updateDialoguePhrase]);

  /**
   * Handle timeline click - update current time
   * Requirements: 4.1
   */
  const handleTimelineClick = useCallback((time: number) => {
    setCurrentTime(time);
  }, []);

  // ============================================================================
  // Event Handlers - Phrase Editor
  // ============================================================================

  /**
   * Handle phrase update from editor
   * Requirements: 4.3
   */
  const handlePhraseUpdate = useCallback((updates: Partial<DialoguePhrase>) => {
    if (!selectedPhraseId) return;
    updateDialoguePhrase(selectedPhraseId, updates);
  }, [selectedPhraseId, updateDialoguePhrase]);

  /**
   * Handle phrase deletion
   * Requirements: 4.4
   */
  const handlePhraseDelete = useCallback(() => {
    if (!selectedPhraseId) return;
    deleteDialoguePhrase(selectedPhraseId);
    setSelectedPhraseId(null);
  }, [selectedPhraseId, deleteDialoguePhrase]);

  /**
   * Handle phrase selection from timeline or list
   * Requirements: 4.1
   */
  const handlePhraseSelect = useCallback((phraseId: string | null) => {
    setSelectedPhraseId(phraseId);
  }, []);

  // ============================================================================
  // Event Handlers - Voice Generation
  // ============================================================================

  /**
   * Handle voice generation for selected phrase
   * Requirements: 5.1, 5.2, 5.3
   */
  const handleVoiceGenerate = useCallback(async (voiceParams: VoiceParameters) => {
    if (!selectedPhraseId || !selectedPhrase) return;

    try {
      setIsGeneratingVoice(true);

      // For now, simulate generation with a delay
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Update phrase with voice parameters and mock audio URL
      updateDialoguePhrase(selectedPhraseId, {
        voiceParameters: voiceParams,
        generatedAudioUrl: `mock://audio/${selectedPhraseId}`,
      });

      ;
    } catch (error) {
      console.error('Voice generation failed:', error);
      throw error;
    } finally {
      setIsGeneratingVoice(false);
    }
  }, [selectedPhraseId, selectedPhrase, updateDialoguePhrase]);

  /**
   * Handle voice preview
   * Requirements: 5.4
   */
  const handleVoicePreview = useCallback((audioUrl: string) => {
    ;
    // Audio preview is handled internally by VoiceGenerationPanel
  }, []);

  // ============================================================================
  // Event Handlers - Phrase Creation
  // ============================================================================

  /**
   * Handle adding new phrase at current time
   * Requirements: 4.2
   */
  const handleAddPhrase = useCallback(() => {
    // Find shot at current time
    const shotAtTime = shots.find(
      shot => currentTime >= shot.startTime && currentTime < shot.startTime + shot.duration
    );

    if (!shotAtTime) {
      alert('Please select a time within a shot to add a phrase');
      return;
    }

    // Create new phrase with default duration of 3 seconds
    const newPhrase: Omit<DialoguePhrase, 'id'> = {
      shotId: shotAtTime.id,
      text: 'New dialogue phrase',
      startTime: currentTime,
      endTime: Math.min(currentTime + 3, shotAtTime.startTime + shotAtTime.duration),
      metadata: {},
    };

    addDialoguePhrase(newPhrase);
  }, [currentTime, shots, addDialoguePhrase]);

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const renderPhraseList = () => {
    if (phrases.length === 0) {
      return (
        <div style={styles.emptyState}>
          <p style={styles.emptyText}>No dialogue phrases yet</p>
          <p style={styles.emptyHint}>
            Click "Add Phrase" to create a new dialogue phrase at the current time
          </p>
        </div>
      );
    }

    return (
      <div style={styles.phraseList}>
        {phrases.map(phrase => {
          const isSelected = phrase.id === selectedPhraseId;
          const shot = shots.find(s => s.id === phrase.shotId);
          
          return (
            <div
              key={phrase.id}
              style={{
                ...styles.phraseItem,
                ...(isSelected ? styles.phraseItemSelected : {}),
              }}
              onClick={() => handlePhraseSelect(phrase.id)}
            >
              <div style={styles.phraseItemHeader}>
                <span style={styles.phraseItemText}>
                  {phrase.text.length > 40 ? phrase.text.slice(0, 40) + '...' : phrase.text}
                </span>
                {phrase.generatedAudioUrl && (
                  <span style={styles.audioIndicator}>🔊</span>
                )}
              </div>
              <div style={styles.phraseItemMeta}>
                <span style={styles.phraseItemTime}>
                  {phrase.startTime.toFixed(1)}s - {phrase.endTime.toFixed(1)}s
                </span>
                {shot && (
                  <span style={styles.phraseItemShot}>
                    Shot {shot.id.slice(-8)}
                  </span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  // ============================================================================
  // Render
  // ============================================================================

  if (!project) {
    return (
      <div className={`audio-track-manager ${className}`} style={styles.container}>
        <div style={styles.emptyState}>
          <p style={styles.emptyText}>No project loaded</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`audio-track-manager ${className}`} style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <h2 style={styles.title}>Audio Track Manager</h2>
        <div style={styles.headerActions}>
          <span style={styles.timeDisplay}>
            Current Time: {currentTime.toFixed(1)}s
          </span>
          <Button
            onClick={handleAddPhrase}
            disabled={shots.length === 0}
            aria-label="Add new dialogue phrase at current time"
            aria-disabled={shots.length === 0}
          >
            Add Phrase
          </Button>
        </div>
      </div>

      {/* Main Content */}
      <div style={styles.content}>
        {/* Left Panel - Timeline and Phrase List */}
        <div style={styles.leftPanel}>
          {/* Timeline */}
          <div style={styles.timelineSection}>
            <h3 style={styles.sectionTitle}>Timeline</h3>
            <AudioTimeline
              shots={shots}
              phrases={phrases}
              duration={totalDuration}
              currentTime={currentTime}
              onPhraseMove={handlePhraseMove}
              onPhraseResize={handlePhraseResize}
              onTimelineClick={handleTimelineClick}
            />
          </div>

          {/* Phrase List */}
          <div style={styles.phraseListSection}>
            <h3 style={styles.sectionTitle}>
              Dialogue Phrases ({phrases.length})
            </h3>
            {renderPhraseList()}
          </div>
        </div>

        {/* Right Panel - Editor and Voice Generation */}
        <div style={styles.rightPanel}>
          {selectedPhrase ? (
            <>
              {/* Phrase Editor */}
              <div style={styles.editorSection}>
                <DialoguePhraseEditor
                  phrase={selectedPhrase}
                  shots={shots}
                  onUpdate={handlePhraseUpdate}
                  onDelete={handlePhraseDelete}
                />
              </div>

              {/* Voice Generation Panel */}
              <div style={styles.voiceSection}>
                <VoiceGenerationPanel
                  phrase={selectedPhrase}
                  onGenerate={handleVoiceGenerate}
                  onPreview={handleVoicePreview}
                  isGenerating={isGeneratingVoice}
                />
              </div>
            </>
          ) : (
            <div style={styles.emptyState}>
              <p style={styles.emptyText}>No phrase selected</p>
              <p style={styles.emptyHint}>
                Select a phrase from the timeline or list to edit
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Styles
// ============================================================================

