import React, { useState, useEffect, useRef, useCallback } from 'react';
import { X, Minimize2, Maximize2, Move, Grip, ChevronUp, ChevronDown } from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';
import { LandingChatBox } from './launcher/LandingChatBox';
import { 
  loadChatPanelState, 
  saveChatPanelState,
  DEFAULT_CHAT_PANEL_STATE 
} from '@/utils/chatPanelStorage';
import './ChatPanel.css';

interface ChatPanelProps {
  className?: string;
  position?: { x: number; y: number };
  size?: { width: number; height: number };
}

const DEFAULT_POSITION = { x: 24, y: 24 };
const DEFAULT_SIZE = { width: 384, height: 500 };
const MIN_SIZE = { width: 300, height: 400 };
const MAX_SIZE_RATIO = 0.9;
const MINIMIZED_HEIGHT = 48;

// Calculate dynamic MAX_SIZE based on viewport
const getMaxSize = () => ({
  width: Math.floor(window.innerWidth * MAX_SIZE_RATIO),
  height: Math.floor(window.innerHeight * MAX_SIZE_RATIO),
});

export const ChatPanel: React.FC<ChatPanelProps> = ({
  className = '',
  position: initialPosition,
  size: initialSize,
}) => {
  const { showChat, setShowChat, chatPanelMinimized, setChatPanelMinimized, project } = useAppStore();
  const [position, setPosition] = useState(initialPosition || DEFAULT_POSITION);
  const [size, setSize] = useState(initialSize || DEFAULT_SIZE);
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [isMaximized, setIsMaximized] = useState(false);
  const [isOpening, setIsOpening] = useState(false);
  const [isClosing, setIsClosing] = useState(false);
  const [previousState, setPreviousState] = useState<{ position: typeof position; size: typeof size } | null>(null);
  const [zIndex, setZIndex] = useState(50);
  const [maxSize, setMaxSize] = useState(getMaxSize());
  const [showShortcuts, setShowShortcuts] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const dragHandleRef = useRef<HTMLDivElement>(null);
  const resizeHandleRef = useRef<HTMLDivElement>(null);
  const dragStartPos = useRef({ x: 0, y: 0 });
  const resizeStartSize = useRef({ width: 0, height: 0 });
  const animationFrameRef = useRef<number | null>(null);

  // Update max size on window resize
  useEffect(() => {
    const handleResize = () => setMaxSize(getMaxSize());
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Dashboard-context aware positioning
  const getContextAwarePosition = useCallback(() => {
    // If a project is loaded, position closer to the center-right area
    if (project) {
      return {
        x: Math.floor(window.innerWidth * 0.6),
        y: Math.floor(window.innerHeight * 0.1),
      };
    }
    return DEFAULT_POSITION;
  }, [project]);

  // Load position and size from local storage
  useEffect(() => {
    const savedState = loadChatPanelState();
    if (savedState) {
      setPosition(savedState.position);
      setSize(savedState.size);
      setChatPanelMinimized(savedState.isMinimized);
    }
  }, [setChatPanelMinimized]);

  // Save position and size to local storage (debounced)
  useEffect(() => {
    if (showChat) {
      const timeoutId = setTimeout(() => {
        saveChatPanelState({
          position,
          size,
          isOpen: showChat,
          isMinimized: chatPanelMinimized,
        });
      }, 500);
      
      return () => clearTimeout(timeoutId);
    }
  }, [position, size, showChat, chatPanelMinimized]);

  const handleDragStart = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsDragging(true);
    dragStartPos.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y,
    };
    bringToFront();
  };

  const handleDrag = (e: MouseEvent) => {
    if (!isDragging || !panelRef.current) return;
    
    // Use requestAnimationFrame for smoother drag
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    
    animationFrameRef.current = requestAnimationFrame(() => {
      const newX = e.clientX - dragStartPos.current.x;
      const newY = e.clientY - dragStartPos.current.y;
      
      // Keep panel within viewport with smooth boundaries
      const maxX = window.innerWidth - panelRef.current!.offsetWidth;
      const maxY = window.innerHeight - panelRef.current!.offsetHeight;
      
      // Apply smooth constraints
      const constrainedX = Math.max(0, Math.min(newX, maxX));
      const constrainedY = Math.max(0, Math.min(newY, maxY));
      
      setPosition({
        x: constrainedX,
        y: constrainedY,
      });
    });
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handleResizeStart = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
    resizeStartSize.current = { ...size };
    bringToFront();
  };

  const handleResize = (e: MouseEvent) => {
    if (!isResizing || !panelRef.current) return;
    
    requestAnimationFrame(() => {
      const rect = panelRef.current!.getBoundingClientRect();
      const newWidth = Math.max(MIN_SIZE.width, Math.min(e.clientX - rect.left, maxSize.width));
      const newHeight = Math.max(MIN_SIZE.height, Math.min(e.clientY - rect.top, maxSize.height));
      
      setSize({
        width: newWidth,
        height: newHeight,
      });
    });
  };

  const handleResizeEnd = () => {
    setIsResizing(false);
  };

  const handleMinimize = () => {
    setChatPanelMinimized(!chatPanelMinimized);
  };

  const handleMaximize = () => {
    if (isMaximized && previousState) {
      // Restore previous state
      setPosition(previousState.position);
      setSize(previousState.size);
      setPreviousState(null);
    } else {
      // Save current state and maximize
      setPreviousState({ position, size });
      setPosition({ x: 0, y: 0 });
      setSize({ 
        width: window.innerWidth - 48, 
        height: window.innerHeight - 48 
      });
    }
    setIsMaximized(!isMaximized);
  };

  const bringToFront = () => {
    setZIndex(51);
  };

  const handlePanelClick = () => {
    if (zIndex < 51) {
      bringToFront();
    }
  };

  const handleHeaderDoubleClick = () => {
    handleMaximize();
  };

  // Handle open/close animations
  useEffect(() => {
    if (showChat) {
      setIsOpening(true);
      const timer = setTimeout(() => setIsOpening(false), 300);
      return () => clearTimeout(timer);
    }
  }, [showChat]);

  // Handle close animation
  useEffect(() => {
    if (!showChat && isClosing) {
      const timer = setTimeout(() => {
        setIsClosing(false);
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [showChat, isClosing]);

  // Add event listeners for drag and resize
  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleDrag);
      window.addEventListener('mouseup', handleDragEnd);
    }
    
    if (isResizing) {
      window.addEventListener('mousemove', handleResize);
      window.addEventListener('mouseup', handleResizeEnd);
    }
    
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      window.removeEventListener('mousemove', handleDrag);
      window.removeEventListener('mouseup', handleDragEnd);
      window.removeEventListener('mousemove', handleResize);
      window.removeEventListener('mouseup', handleResizeEnd);
    };
  }, [isDragging, isResizing]);

  // Handle close with animation
  const handleCloseWithAnimation = () => {
    setIsClosing(true);
    setTimeout(() => {
      setShowChat(false);
      setIsClosing(false);
    }, 280);
  };

  return (
    <>
      {/* Overlay for mobile - only show when chat is open */}
      {showChat && !isClosing && (
        <div
          className="fixed inset-0 bg-black/50 z-40 md:hidden chat-backdrop chat-backdrop-opening"
          onClick={handleCloseWithAnimation}
        />
      )}

      {/* Floating Chat Window */}
      <div
        ref={panelRef}
        onClick={handlePanelClick}
        className={`
          fixed bg-white dark:bg-gray-800 shadow-2xl rounded-lg border border-gray-200 dark:border-gray-700 
          flex flex-col overflow-hidden chat-panel
          ${isOpening ? 'chat-panel-opening' : ''}
          ${isClosing ? 'chat-panel-closing' : ''}
          ${isDragging ? 'chat-panel-dragging' : ''}
          ${className}
        `}
        style={{
          left: `${position.x}px`,
          top: `${position.y}px`,
          width: `${size.width}px`,
          height: chatPanelMinimized ? `${MINIMIZED_HEIGHT}px` : `${size.height}px`,
          zIndex,
          cursor: isDragging ? 'grabbing' : 'auto',
          display: (showChat || isClosing) ? 'flex' : 'none',
        }}
      >
        {/* Drag Handle (invisible overlay on header) */}
        <div
          ref={dragHandleRef}
          className="absolute top-0 left-0 right-0 h-12 cursor-move z-10"
          onMouseDown={handleDragStart}
          onDoubleClick={handleHeaderDoubleClick}
        />

        {/* Chat Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700 cursor-move hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors">
          <div className="flex items-center gap-2">
            <Move className="w-4 h-4 text-gray-500" />
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              StoryCore AI Assistant
            </h3>
          </div>
          <div className="flex items-center gap-2 z-20">
            {/* Shortcuts Toggle */}
            <button
              onClick={() => setShowShortcuts(!showShortcuts)}
              className={`p-1 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-500 rounded transition-colors ${showShortcuts ? 'bg-gray-200 dark:bg-gray-600' : ''}`}
              aria-label="Show keyboard shortcuts"
              title="Keyboard shortcuts (?)"
            >
              <span className="text-xs font-semibold px-1">?</span>
            </button>
            {/* Maximize/Restore Button */}
            <button
              onClick={handleMaximize}
              className="p-1 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-500 rounded transition-colors"
              aria-label={isMaximized ? "Restore chat" : "Maximize chat"}
              title={isMaximized ? "Restore" : "Maximize"}
            >
              {isMaximized ? (
                <Minimize2 className="w-4 h-4" />
              ) : (
                <Maximize2 className="w-4 h-4" />
              )}
            </button>
            {/* Minimize Button */}
            <button
              onClick={handleMinimize}
              className="p-1 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-500 rounded transition-colors"
              aria-label={chatPanelMinimized ? "Restore chat" : "Minimize chat"}
              title={chatPanelMinimized ? "Restore" : "Minimize"}
            >
              {chatPanelMinimized ? (
                <ChevronUp className="w-4 h-4" />
              ) : (
                <Minimize2 className="w-4 h-4" />
              )}
            </button>
            {/* Close Button */}
            <button
              onClick={handleCloseWithAnimation}
              className="p-1 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-500 rounded transition-colors chat-btn"
              aria-label="Close chat"
              title="Close"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Keyboard Shortcuts Panel */}
        {showShortcuts && !chatPanelMinimized && (
          <div className="bg-gray-100 dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 p-3 text-xs">
            <div className="grid grid-cols-2 gap-2 text-gray-600 dark:text-gray-400">
              <div><kbd className="px-1.5 py-0.5 bg-gray-200 dark:bg-gray-700 rounded">Enter</kbd> Send</div>
              <div><kbd className="px-1.5 py-0.5 bg-gray-200 dark:bg-gray-700 rounded">Shift+Enter</kbd> New line</div>
              <div><kbd className="px-1.5 py-0.5 bg-gray-200 dark:bg-gray-700 rounded">Drag</kbd> Move panel</div>
              <div><kbd className="px-1.5 py-0.5 bg-gray-200 dark:bg-gray-700 rounded">Resize</kbd> Corner drag</div>
            </div>
          </div>
        )}

        {/* Chat Content */}
        {!chatPanelMinimized && (
          <div className="flex-1 overflow-hidden">
            <LandingChatBox 
              placeholder="Ask for modifications, ask questions about your project..."
              height={size.height - 48}
              context="project"
            />
          </div>
        )}

        {/* Resize Handle */}
        {!chatPanelMinimized && (
          <>
            <div
              ref={resizeHandleRef}
              className="absolute bottom-0 right-0 w-4 h-4 cursor-nwse-resize z-10"
              onMouseDown={handleResizeStart}
            />

            {/* Resize Handle Visual */}
            <div
              className="absolute bottom-0 right-0 w-4 h-4 bg-blue-500 hover:bg-blue-600 rounded-tl-lg cursor-nwse-resize transition-colors"
              onMouseDown={handleResizeStart}
            >
              <Grip className="w-3 h-3 text-white" />
            </div>
          </>
        )}
      </div>
    </>
  );
};

import React from 'react';
import { MessageSquare, X } from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';

interface ChatToggleButtonProps {
  className?: string;
  dashboardContext?: string;
  position?: 'fixed' | 'relative' | 'absolute';
}

export const ChatToggleButton: React.FC<ChatToggleButtonProps> = ({ className = '', dashboardContext, position }) => {
  const { showChat, setShowChat, chatMessages } = useAppStore();
  const [isHovered, setIsHovered] = React.useState(false);

  // Count unread messages (messages since last time chat was opened)
  const unreadCount = 0; // In a real app, track this properly

  const handleToggle = () => {
    setShowChat(!showChat);
  };

  // Apply dashboard-specific positioning logic
  const getPositionClasses = () => {
    switch (dashboardContext) {
      case 'project-dashboard':
        return 'relative inline-flex items-center justify-center w-8 h-8 ml-2';
      case 'editor':
        return 'fixed bottom-6 right-6';
      default:
        return position === 'relative' ? 'relative' : 'fixed bottom-6 right-6';
    }
  };

  const positionClasses = getPositionClasses();

  // Get visual state classes
  const getVisualStateClasses = () => {
    let stateClasses = 'bg-purple-600 hover:bg-purple-700 chat-toggle-btn';
    
    if (showChat) {
      stateClasses = 'bg-green-600 hover:bg-green-700 chat-toggle-btn';
    }
    
    if (unreadCount > 0) {
      stateClasses += ' chat-unread-indicator';
    }
    
    return stateClasses;
  };

  const visualStateClasses = getVisualStateClasses();

  return (
    <button
      onClick={handleToggle}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={`flex items-center justify-center w-14 h-14 text-white rounded-full shadow-lg transition-all duration-200 ${visualStateClasses} ${positionClasses} ${className} z-50`}
      aria-label={showChat ? 'Close chat' : 'Open chat'}
      title={showChat ? 'Close chat assistant' : 'Open chat assistant'}
      data-state={showChat ? 'active' : 'inactive'}
    >
      {showChat ? (
        <X className="w-6 h-6 chat-toggle-icon" />
      ) : (
        <>
          <MessageSquare className="w-6 h-6 chat-toggle-icon" />
          {unreadCount > 0 && (
            <span className="absolute -top-1 -right-1 flex items-center justify-center w-5 h-5 text-xs font-bold bg-red-500 rounded-full animate-bounce">
              {unreadCount > 9 ? '9+' : unreadCount}
            </span>
          )}
        </>
      )}
    </button>
  );
};

/**
 * ComfyUI Actions Component
 *
 * Provides action buttons for ComfyUI operations in the Canvas Area
 * - Generate images/videos from text prompts
 * - Upload media for processing
 * - Quick access to common workflows
 */

import React, { useState } from 'react';
import { useToast } from '@/hooks/use-toast';
import {
  Wand2,
  Upload,
  Image as ImageIcon,
  Video,
  Loader2,
  Sparkles,
} from 'lucide-react';

interface ComfyUIActionsProps {
  className?: string;
  onWorkflowExecute?: (workflowType: string, params: unknown) => void;
  onMediaUpload?: (filePath: string) => void;
}

export const ComfyUIActions: React.FC<ComfyUIActionsProps> = ({
  className = '',
  onWorkflowExecute,
  onMediaUpload,
}) => {
  const { toast } = useToast();
  const [isExecuting, setIsExecuting] = useState(false);
  const [executingType, setExecutingType] = useState<string | null>(null);

  const handleGenerateImage = async () => {
    setIsExecuting(true);
    setExecutingType('image');

    try {
      // Open prompt dialog or use default prompt
      const prompt = "A beautiful landscape with mountains and a lake, cinematic lighting, photorealistic";

      if (onWorkflowExecute) {
        await onWorkflowExecute('text-to-image', {
          prompt,
          width: 1024,
          height: 1024,
          steps: 25,
          cfg_scale: 7.5,
        });
      }

      toast({
        title: 'Image Generation Started',
        description: 'Generating image from text prompt...',
      });
    } catch (error) {
      toast({
        title: 'Generation Failed',
        description: 'Failed to start image generation',
        variant: 'destructive',
      });
    } finally {
      setIsExecuting(false);
      setExecutingType(null);
    }
  };

  const handleGenerateVideo = async () => {
    setIsExecuting(true);
    setExecutingType('video');

    try {
      // Open prompt dialog or use default prompt
      const prompt = "A cinematic scene of a forest in autumn, camera slowly moving through the trees";

      if (onWorkflowExecute) {
        await onWorkflowExecute('text-to-video', {
          prompt,
          width: 720,
          height: 480,
          frames: 121,
          fps: 24,
        });
      }

      toast({
        title: 'Video Generation Started',
        description: 'Generating video from text prompt...',
      });
    } catch (error) {
      toast({
        title: 'Generation Failed',
        description: 'Failed to start video generation',
        variant: 'destructive',
      });
    } finally {
      setIsExecuting(false);
      setExecutingType(null);
    }
  };

  const handleUploadMedia = async () => {
    // Create file input for media upload
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*,video/*';
    input.multiple = false;

    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        if (onMediaUpload) {
          await onMediaUpload(file.path);
        }

        toast({
          title: 'Media Uploaded',
          description: `${file.name} uploaded successfully`,
        });
      } catch (error) {
        toast({
          title: 'Upload Failed',
          description: 'Failed to upload media file',
          variant: 'destructive',
        });
      }
    };

    input.click();
  };

  const handleQuickWorkflow = async (workflowType: string) => {
    setIsExecuting(true);
    setExecutingType(workflowType);

    try {
      const workflows = {
        'anime-style': {
          prompt: "Anime character in fantasy setting, detailed, vibrant colors, studio ghibli style",
          width: 1024,
          height: 1536,
          steps: 30,
        },
        'realistic-portrait': {
          prompt: "Professional portrait photography, sharp focus, natural lighting, photorealistic",
          width: 1024,
          height: 1024,
          steps: 25,
        },
        'abstract-art': {
          prompt: "Abstract digital art, vibrant colors, geometric patterns, modern style",
          width: 1024,
          height: 1024,
          steps: 20,
        },
      };

      const params = workflows[workflowType as keyof typeof workflows];
      if (!params) return;

      if (onWorkflowExecute) {
        await onWorkflowExecute('text-to-image', params);
      }

      toast({
        title: 'Workflow Started',
        description: `${workflowType} generation in progress...`,
      });
    } catch (error) {
      toast({
        title: 'Workflow Failed',
        description: `Failed to start ${workflowType} workflow`,
        variant: 'destructive',
      });
    } finally {
      setIsExecuting(false);
      setExecutingType(null);
    }
  };

  return (
    <div className={`flex items-center gap-2 p-2 ${className}`}>
      {/* Primary Actions */}
      <div className="flex items-center gap-1">
        <button
          onClick={handleGenerateImage}
          disabled={isExecuting}
          className="flex items-center gap-2 px-3 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Generate Image from Text"
        >
          {isExecuting && executingType === 'image' ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <ImageIcon className="w-4 h-4" />
          )}
          <span className="text-sm font-medium">Generate Image</span>
        </button>

        <button
          onClick={handleGenerateVideo}
          disabled={isExecuting}
          className="flex items-center gap-2 px-3 py-2 bg-secondary text-secondary-foreground rounded-md hover:bg-secondary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Generate Video from Text"
        >
          {isExecuting && executingType === 'video' ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Video className="w-4 h-4" />
          )}
          <span className="text-sm font-medium">Generate Video</span>
        </button>

        <button
          onClick={handleUploadMedia}
          disabled={isExecuting}
          className="flex items-center gap-2 px-3 py-2 bg-muted text-muted-foreground rounded-md hover:bg-muted/80 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Upload Media for Processing"
        >
          <Upload className="w-4 h-4" />
          <span className="text-sm font-medium">Upload Media</span>
        </button>
      </div>

      {/* Quick Workflows */}
      <div className="flex items-center gap-1 ml-4 pl-4 border-l border-border">
        <span className="text-xs text-muted-foreground mr-2">Quick:</span>

        <button
          onClick={() => handleQuickWorkflow('anime-style')}
          disabled={isExecuting}
          className="flex items-center gap-1 px-2 py-1 bg-accent text-accent-foreground rounded hover:bg-accent/80 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Generate Anime-style Image"
        >
          {isExecuting && executingType === 'anime-style' ? (
            <Loader2 className="w-3 h-3 animate-spin" />
          ) : (
            <Sparkles className="w-3 h-3" />
          )}
          <span className="text-xs">Anime</span>
        </button>

        <button
          onClick={() => handleQuickWorkflow('realistic-portrait')}
          disabled={isExecuting}
          className="flex items-center gap-1 px-2 py-1 bg-accent text-accent-foreground rounded hover:bg-accent/80 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Generate Realistic Portrait"
        >
          {isExecuting && executingType === 'realistic-portrait' ? (
            <Loader2 className="w-3 h-3 animate-spin" />
          ) : (
            <Wand2 className="w-3 h-3" />
          )}
          <span className="text-xs">Portrait</span>
        </button>

        <button
          onClick={() => handleQuickWorkflow('abstract-art')}
          disabled={isExecuting}
          className="flex items-center gap-1 px-2 py-1 bg-accent text-accent-foreground rounded hover:bg-accent/80 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          title="Generate Abstract Art"
        >
          {isExecuting && executingType === 'abstract-art' ? (
            <Loader2 className="w-3 h-3 animate-spin" />
          ) : (
            <Sparkles className="w-3 h-3" />
          )}
          <span className="text-xs">Abstract</span>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { useToast } from '@/hooks/use-toast';
import { testComfyUIConnection, type ComfyUIConfig, type ComfyUIServerInfo } from '@/services/comfyuiService';
import { ComfyUIClient } from '@/services/wizard/ComfyUIClient';
import { backendApi } from '@/services/backendApiService';
import { ComfyUIMediaUpload } from '@/components/ComfyUIMediaUpload';
import { ComfyUIProgressMonitor } from '@/components/ComfyUIProgressMonitor';
import { ComfyUIParameterPanel } from '@/components/ComfyUIParameterPanel';
import {
  Server,
  Play,
  Square,
  Settings,
  RefreshCw,
  Zap,
  CheckCircle,
  XCircle,
  Loader2,
  Monitor,
  Cpu,
  HardDrive,
} from 'lucide-react';

interface WorkflowExecution {
  id: string;
  client: ComfyUIClient;
  status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
  progress: number;
  currentNode?: string;
  totalNodes?: number;
  completedNodes?: number;
  startTime: Date;
  endTime?: Date;
  error?: string;
  outputs?: Array<{
    type: 'image' | 'video' | 'audio';
    url: string;
    filename: string;
  }>;
}

interface ComfyUIControlPanelProps {
  className?: string;
}

export function ComfyUIControlPanel({ className }: ComfyUIControlPanelProps) {
  const { toast } = useToast();
  const project = useAppStore((state) => state.project);

  // ComfyUI state
  const [comfyConfig, setComfyConfig] = useState<ComfyUIConfig | null>(null);
  const [serverInfo, setServerInfo] = useState<ComfyUIServerInfo | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'disconnected' | 'connecting' | 'connected' | 'error'>('disconnected');
  const [isTestingConnection, setIsTestingConnection] = useState(false);
  const [activeWorkflow, setActiveWorkflow] = useState<string | null>(null);
  const [queueStatus, setQueueStatus] = useState<{ pending: number; running: number } | null>(null);
  const [executions, setExecutions] = useState<WorkflowExecution[]>([]);
  const [generationParams, setGenerationParams] = useState({
    prompt: '',
    negativePrompt: '',
    seed: -1,
    steps: 20,
    cfgScale: 7.0,
    sampler: 'euler',
    scheduler: 'normal',
    denoisingStrength: 1.0,
    width: 1024,
    height: 1024,
  });

  // Initialize ComfyUI configuration
  useEffect(() => {
    const config = backendApi.getComfyUIConfig();
    if (config) {
      setComfyConfig(config);
      testConnection(config);
    }
  }, []);

  // Test ComfyUI connection
  const testConnection = async (config: ComfyUIConfig) => {
    setIsTestingConnection(true);
    try {
      const result = await testComfyUIConnection(config);
      setConnectionStatus(result.success ? 'connected' : 'error');

      if (result.success && result.serverInfo) {
        setServerInfo(result.serverInfo);
        toast({
          title: 'ComfyUI Connected',
          description: `Server: ${result.serverInfo.version} | GPU: ${result.serverInfo.systemInfo.gpuName}`,
        });
      } else {
        toast({
          title: 'Connection Failed',
          description: result.message,
          variant: 'destructive',
        });
      }
    } catch (error) {
      setConnectionStatus('error');
      toast({
        title: 'Connection Test Failed',
        description: error instanceof Error ? error.message : 'Unknown error',
        variant: 'destructive',
      });
    } finally {
      setIsTestingConnection(false);
    }
  };

  // Get queue status
  const getQueueStatus = async () => {
    if (!comfyConfig) return;

    try {
      const response = await backendApi.getComfyUIQueue();
      if (response.success && response.data) {
        setQueueStatus({
          pending: response.data.pending,
          running: response.data.running,
        });
      }
    } catch (error) {
      console.error('Failed to get queue status:', error);
    }
  };

  // Execute workflow
  const executeWorkflow = async (workflowType: 'image' | 'video' | 'upscale' | 'inpaint') => {
    if (!comfyConfig || !project) return;

    setActiveWorkflow(workflowType);
    const executionId = `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Create execution tracking
    const execution: WorkflowExecution = {
      id: executionId,
      client: new ComfyUIClient(comfyConfig),
      status: 'running',
      progress: 0,
      startTime: new Date(),
    };

    setExecutions(prev => [...prev, execution]);

    try {
      // Create basic workflow based on type
      let workflow: unknown = {};
      switch (workflowType) {
        case 'image':
          workflow = execution.client.getStoryboardFrameTemplate();
          break;
        case 'video':
          break;
        default:
          workflow = execution.client.getStoryboardFrameTemplate();
      }

      // Execute workflow
      const result = await execution.client.executeWorkflow(workflow);

      // Update execution with results
      setExecutions(prev => prev.map(e =>
        e.id === executionId
          ? {
              ...e,
              status: 'completed',
              progress: 100,
              endTime: new Date(),
              outputs: result.outputs.map(output => ({
                type: 'image' as const, // Assume image for now
                url: `/comfyui/view?filename=${output.filename}&subfolder=${output.subfolder}&type=${output.type}`,
                filename: output.filename,
              })),
            }
          : e
      ));

      toast({
        title: 'Workflow Completed',
        description: `Generated ${result.outputs.length} output(s)`,
      });

      // Refresh queue status
      getQueueStatus();

    } catch (error) {
      // Update execution with error
      setExecutions(prev => prev.map(e =>
        e.id === executionId
          ? {
              ...e,
              status: 'failed',
              endTime: new Date(),
              error: error instanceof Error ? error.message : 'Unknown error',
            }
          : e
      ));

      toast({
        title: 'Workflow Failed',
        description: error instanceof Error ? error.message : 'Unknown error',
        variant: 'destructive',
      });
    } finally {
      setActiveWorkflow(null);
    }
  };

  // Refresh all status
  const refreshStatus = async () => {
    if (comfyConfig) {
      await testConnection(comfyConfig);
      await getQueueStatus();
    }
  };

  return (
    <div className={`h-full overflow-auto ${className || ''}`}>
      {/* Header */}
      <div className="p-4 border-b border-border">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-lg font-semibold flex items-center gap-2">
            <Zap className="w-5 h-5" />
            ComfyUI Control
          </h3>
          <button
            onClick={refreshStatus}
            className="p-2 hover:bg-muted rounded-md"
            title="Refresh status"
          >
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>

        {/* Connection Status */}
        <div className="flex items-center gap-2 text-sm">
          <div className={`w-2 h-2 rounded-full ${
            connectionStatus === 'connected' ? 'bg-green-500' :
            connectionStatus === 'connecting' ? 'bg-yellow-500' :
            connectionStatus === 'error' ? 'bg-red-500' : 'bg-gray-500'
          }`} />
          <span className="capitalize">{connectionStatus}</span>
          {serverInfo && (
            <span className="text-muted-foreground">
              v{serverInfo.version}
            </span>
          )}
        </div>
      </div>

      {/* Server Info */}
      {serverInfo && (
        <div className="p-4 border-b border-border">
          <h4 className="text-sm font-medium mb-2 flex items-center gap-2">
            <Server className="w-4 h-4" />
            Server Information
          </h4>
          <div className="space-y-1 text-xs text-muted-foreground">
            <div className="flex justify-between">
              <span>GPU:</span>
              <span>{serverInfo.systemInfo.gpuName}</span>
            </div>
            <div className="flex justify-between">
              <span>VRAM:</span>
              <span>{serverInfo.systemInfo.vramTotal}MB total</span>
            </div>
            <div className="flex justify-between">
              <span>Free:</span>
              <span>{serverInfo.systemInfo.vramFree}MB free</span>
            </div>
          </div>
        </div>
      )}

      {/* Queue Status */}
      {queueStatus && (
        <div className="p-4 border-b border-border">
          <h4 className="text-sm font-medium mb-2 flex items-center gap-2">
            <Monitor className="w-4 h-4" />
            Queue Status
          </h4>
          <div className="space-y-1 text-xs">
            <div className="flex justify-between">
              <span>Pending:</span>
              <span className="text-yellow-600">{queueStatus.pending}</span>
            </div>
            <div className="flex justify-between">
              <span>Running:</span>
              <span className="text-blue-600">{queueStatus.running}</span>
            </div>
          </div>
        </div>
      )}

      {/* Media Upload */}
      <div className="p-4 border-b border-border">
        <ComfyUIMediaUpload
          onFileUploaded={(file, uploadUrl) => {
            toast({
              title: 'Media Ready',
              description: `${file.name} can now be used in ComfyUI workflows`,
            });
          }}
        />
      </div>

      {/* Workflow Actions */}
      <div className="p-4">
        <h4 className="text-sm font-medium mb-3">Quick Workflows</h4>
        <div className="grid grid-cols-2 gap-2">
          <button
            onClick={() => executeWorkflow('image')}
            disabled={connectionStatus !== 'connected' || activeWorkflow === 'image'}
            className="p-3 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center gap-1 text-xs"
          >
            {activeWorkflow === 'image' ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Settings className="w-4 h-4" />
            )}
            <span>Generate Image</span>
          </button>

          <button
            onClick={() => executeWorkflow('video')}
            disabled={connectionStatus !== 'connected' || activeWorkflow === 'video'}
            className="p-3 bg-secondary text-secondary-foreground rounded-md hover:bg-secondary/90 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center gap-1 text-xs"
          >
            {activeWorkflow === 'video' ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Play className="w-4 h-4" />
            )}
            <span>Generate Video</span>
          </button>

          <button
            onClick={() => executeWorkflow('upscale')}
            disabled={connectionStatus !== 'connected' || activeWorkflow === 'upscale'}
            className="p-3 bg-accent text-accent-foreground rounded-md hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center gap-1 text-xs"
          >
            {activeWorkflow === 'upscale' ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <HardDrive className="w-4 h-4" />
            )}
            <span>Upscale</span>
          </button>

          <button
            onClick={() => executeWorkflow('inpaint')}
            disabled={connectionStatus !== 'connected' || activeWorkflow === 'inpaint'}
            className="p-3 bg-muted text-muted-foreground rounded-md hover:bg-muted/90 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center gap-1 text-xs"
          >
            {activeWorkflow === 'inpaint' ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Cpu className="w-4 h-4" />
            )}
            <span>Inpaint</span>
          </button>
        </div>
      </div>

      {/* Parameter Panel */}
      <div className="p-4 border-t border-border">
        <ComfyUIParameterPanel
          parameters={generationParams}
          onParametersChange={setGenerationParams}
          onExecuteWorkflow={(params) => executeWorkflow('image')} // Default to image generation
        />
      </div>

      {/* Progress Monitor */}
      <div className="p-4 border-t border-border">
        <ComfyUIProgressMonitor
          executions={executions}
          onExecutionUpdate={(execution) => {
            setExecutions(prev => prev.map(e =>
              e.id === execution.id ? execution : e
            ));
          }}
          onExecutionComplete={(execution) => {
            toast({
              title: 'Workflow Complete',
              description: `Execution ${execution.id.slice(-8)} finished`,
            });
          }}
        />
      </div>

      {/* Connection Test */}
      <div className="p-4 border-t border-border">
        <button
          onClick={() => comfyConfig && testConnection(comfyConfig)}
          disabled={isTestingConnection}
          className="w-full px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
        >
          {isTestingConnection ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : connectionStatus === 'connected' ? (
            <CheckCircle className="w-4 h-4" />
          ) : (
            <XCircle className="w-4 h-4" />
          )}
          <span>Test Connection</span>
        </button>
      </div>
    </div>
  );
}

import React, { useState, useRef, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import {
  Upload,
  X,
  Image as ImageIcon,
  Music,
  Video,
  FileText,
  Loader2,
  CheckCircle,
  AlertCircle,
} from 'lucide-react';

interface ComfyUIMediaUploadProps {
  onFileUploaded?: (file: File, uploadUrl: string) => void;
  acceptedTypes?: string;
  maxFileSize?: number; // in MB
  className?: string;
}

interface UploadState {
  file: File | null;
  status: 'idle' | 'uploading' | 'success' | 'error';
  progress: number;
  uploadUrl?: string;
  error?: string;
}

export function ComfyUIMediaUpload({
  onFileUploaded,
  acceptedTypes = 'image/*,audio/*,video/*',
  maxFileSize = 100, // 100MB default
  className
}: ComfyUIMediaUploadProps) {
  const { toast } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [uploadState, setUploadState] = useState<UploadState>({
    file: null,
    status: 'idle',
    progress: 0,
  });

  const [dragOver, setDragOver] = useState(false);

  // Get file type icon
  const getFileIcon = (file: File) => {
    if (file.type.startsWith('image/')) return <ImageIcon className="w-8 h-8" />;
    if (file.type.startsWith('audio/')) return <Music className="w-8 h-8" />;
    if (file.type.startsWith('video/')) return <Video className="w-8 h-8" />;
    return <FileText className="w-8 h-8" />;
  };

  // Format file size
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`;
  };

  // Validate file
  const validateFile = (file: File): { valid: boolean; error?: string } => {
    // Check file size
    const maxSizeBytes = maxFileSize * 1024 * 1024;
    if (file.size > maxSizeBytes) {
      return {
        valid: false,
        error: `File size exceeds ${maxFileSize}MB limit (${formatFileSize(file.size)})`,
      };
    }

    // Check file type
    const acceptedTypesArray = acceptedTypes.split(',').map(type => type.trim());
    const isAccepted = acceptedTypesArray.some(type => {
      if (type.endsWith('/*')) {
        const baseType = type.slice(0, -1);
        return file.type.startsWith(baseType);
      }
      return file.type === type;
    });

    if (!isAccepted) {
      return {
        valid: false,
        error: `File type not supported. Accepted: ${acceptedTypes}`,
      };
    }

    return { valid: true };
  };

  // Upload file to ComfyUI
  const uploadToComfyUI = async (file: File): Promise<string> => {
    // Get ComfyUI server URL from backend config
    const backendConfig = await import('@/services/backendApiService').then(m => m.backendApi.getComfyUIConfig());
    if (!backendConfig) {
      throw new Error('ComfyUI is not configured. Please configure ComfyUI settings first.');
    }

    const serverUrl = backendConfig.serverUrl || 'http://localhost:8000';

    // Build headers with authentication if needed
    const headers: Record<string, string> = {};
    if (backendConfig.authentication?.type === 'basic' && backendConfig.authentication.username) {
      const credentials = btoa(`${backendConfig.authentication.username}:${backendConfig.authentication.password || ''}`);
      headers['Authorization'] = `Basic ${credentials}`;
    } else if (backendConfig.authentication?.type === 'token' && backendConfig.authentication.token) {
      headers['Authorization'] = `Bearer ${backendConfig.authentication.token}`;
    }

    const formData = new FormData();
    formData.append('image', file); // ComfyUI expects 'image' field
    formData.append('type', 'input'); // or 'temp', 'output'
    formData.append('subfolder', 'user_uploads');

    try {
      const response = await fetch(`${serverUrl}/upload`, {
        method: 'POST',
        headers,
        body: formData,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => 'Unknown error');
        throw new Error(`ComfyUI upload failed: ${response.status} ${response.statusText} - ${errorText}`);
      }

      const result = await response.json();

      if (!result.name) {
        throw new Error('Invalid response from ComfyUI upload endpoint');
      }

      // Return the ComfyUI file reference
      // ComfyUI typically returns: { name: "filename.jpg", subfolder: "user_uploads", type: "input" }
      const uploadUrl = `${serverUrl}/view?filename=${encodeURIComponent(result.name)}&subfolder=${encodeURIComponent(result.subfolder || 'user_uploads')}&type=${encodeURIComponent(result.type || 'input')}`;

      return uploadUrl;
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Failed to upload file to ComfyUI');
    }
  };

  // Handle file selection
  const handleFileSelect = useCallback(async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    const file = files[0];
    const validation = validateFile(file);

    if (!validation.valid) {
      toast({
        title: 'Invalid File',
        description: validation.error,
        variant: 'destructive',
      });
      return;
    }

    setUploadState({
      file,
      status: 'uploading',
      progress: 0,
    });

    try {
      const uploadUrl = await uploadToComfyUI(file);

      setUploadState({
        file,
        status: 'success',
        progress: 100,
        uploadUrl,
      });

      toast({
        title: 'Upload Successful',
        description: `${file.name} uploaded to ComfyUI`,
      });

      onFileUploaded?.(file, uploadUrl);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Upload failed';
      setUploadState({
        file,
        status: 'error',
        progress: 0,
        error: errorMessage,
      });

      toast({
        title: 'Upload Failed',
        description: errorMessage,
        variant: 'destructive',
      });
    }
  }, [maxFileSize, acceptedTypes, toast, onFileUploaded]);

  // Handle drag and drop
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    handleFileSelect(e.dataTransfer.files);
  }, [handleFileSelect]);

  // Handle click to select
  const handleClick = () => {
    fileInputRef.current?.click();
  };

  // Clear upload
  const clearUpload = () => {
    setUploadState({
      file: null,
      status: 'idle',
      progress: 0,
    });
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <div className={`space-y-4 ${className || ''}`}>
      {/* Upload Area */}
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClick}
        className={`
          relative border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors
          ${dragOver
            ? 'border-primary bg-primary/5'
            : 'border-border hover:border-primary/50 hover:bg-muted/50'
          }
          ${uploadState.status === 'uploading' ? 'pointer-events-none opacity-50' : ''}
        `}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept={acceptedTypes}
          onChange={(e) => handleFileSelect(e.target.files)}
          className="hidden"
          aria-label="Upload media file for ComfyUI processing"
        />

        {uploadState.status === 'idle' && (
          <div className="space-y-2">
            <Upload className="w-12 h-12 mx-auto text-muted-foreground" />
            <div>
              <p className="text-sm font-medium">Upload Media for ComfyUI</p>
              <p className="text-xs text-muted-foreground">
                Drag & drop or click to select images, audio, or video files
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Max size: {maxFileSize}MB • Types: {acceptedTypes}
              </p>
            </div>
          </div>
        )}

        {uploadState.status === 'uploading' && uploadState.file && (
          <div className="space-y-4">
            <div className="flex items-center justify-center space-x-2">
              {getFileIcon(uploadState.file)}
              <Loader2 className="w-6 h-6 animate-spin" />
            </div>
            <div>
              <p className="text-sm font-medium">Uploading {uploadState.file.name}</p>
              <div className="w-full bg-muted rounded-full h-2 mt-2">
                <div
                  className="bg-primary h-2 rounded-full transition-all duration-300"
                  style={{ width: `${uploadState.progress}%` }}
                />
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                {uploadState.progress}% • {formatFileSize(uploadState.file.size)}
              </p>
            </div>
          </div>
        )}

        {uploadState.status === 'success' && uploadState.file && (
          <div className="space-y-2">
            <div className="flex items-center justify-center space-x-2">
              {getFileIcon(uploadState.file)}
              <CheckCircle className="w-6 h-6 text-green-500" />
            </div>
            <div>
              <p className="text-sm font-medium">{uploadState.file.name}</p>
              <p className="text-xs text-green-600">Uploaded successfully</p>
              <p className="text-xs text-muted-foreground">
                {formatFileSize(uploadState.file.size)} • Ready for processing
              </p>
            </div>
          </div>
        )}

        {uploadState.status === 'error' && uploadState.file && (
          <div className="space-y-2">
            <div className="flex items-center justify-center space-x-2">
              {getFileIcon(uploadState.file)}
              <AlertCircle className="w-6 h-6 text-red-500" />
            </div>
            <div>
              <p className="text-sm font-medium">{uploadState.file.name}</p>
              <p className="text-xs text-red-600">Upload failed</p>
              <p className="text-xs text-muted-foreground">
                {uploadState.error}
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Clear Button */}
      {uploadState.file && uploadState.status !== 'uploading' && (
        <div className="flex justify-center">
          <button
            onClick={clearUpload}
            className="px-4 py-2 text-sm bg-muted hover:bg-muted/80 rounded-md flex items-center space-x-2"
          >
            <X className="w-4 h-4" />
            <span>Clear</span>
          </button>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useToast } from '@/hooks/use-toast';
import {
  Settings,
  Shuffle,
  RotateCcw,
  Save,
  Play,
} from 'lucide-react';

interface ComfyUIParameters {
  // Generation settings
  prompt: string;
  negativePrompt: string;
  seed: number;
  steps: number;
  cfgScale: number;
  sampler: string;
  scheduler: string;
  denoisingStrength: number;

  // Image dimensions
  width: number;
  height: number;

  // Model settings
  checkpoint?: string;
  vae?: string;
  lora?: string[];
}

interface ComfyUIParameterPanelProps {
  parameters: ComfyUIParameters;
  onParametersChange: (parameters: ComfyUIParameters) => void;
  onExecuteWorkflow?: (parameters: ComfyUIParameters) => void;
  className?: string;
}

const AVAILABLE_SAMPLERS = [
  'euler', 'euler_ancestral', 'heun', 'dpm_2', 'dpm_2_ancestral',
  'lms', 'dpm_fast', 'dpm_adaptive', 'dpmpp_2s_ancestral', 'dpmpp_sde',
  'dpmpp_sde_gpu', 'dpmpp_2m', 'dpmpp_2m_sde', 'dpmpp_2m_sde_gpu',
  'ddim', 'plms', 'uni_pc', 'uni_pc_bh2'
];

const AVAILABLE_SCHEDULERS = [
  'normal', 'karras', 'exponential', 'sgm_uniform', 'simple', 'ddim_uniform'
];

const DEFAULT_PARAMETERS: ComfyUIParameters = {
  prompt: '',
  negativePrompt: '',
  seed: -1,
  steps: 20,
  cfgScale: 7.0,
  sampler: 'euler',
  scheduler: 'normal',
  denoisingStrength: 1.0,
  width: 1024,
  height: 1024,
};

export function ComfyUIParameterPanel({
  parameters,
  onParametersChange,
  onExecuteWorkflow,
  className,
}: ComfyUIParameterPanelProps) {
  const { toast } = useToast();
  const [localParams, setLocalParams] = useState<ComfyUIParameters>({
    ...DEFAULT_PARAMETERS,
    ...parameters,
  });

  // Update local params when props change
  useEffect(() => {
    setLocalParams(prev => ({
      ...prev,
      ...parameters,
    }));
  }, [parameters]);

  // Update parent when local params change
  const updateParameter = <K extends keyof ComfyUIParameters>(
    key: K,
    value: ComfyUIParameters[K]
  ) => {
    const newParams = { ...localParams, [key]: value };
    setLocalParams(newParams);
    onParametersChange(newParams);
  };

  // Generate random seed
  const randomizeSeed = () => {
    const newSeed = Math.floor(Math.random() * 1000000000);
    updateParameter('seed', newSeed);
  };

  // Reset to defaults
  const resetToDefaults = () => {
    setLocalParams(DEFAULT_PARAMETERS);
    onParametersChange(DEFAULT_PARAMETERS);
    toast({
      title: 'Parameters Reset',
      description: 'All parameters reset to default values',
    });
  };

  // Save as preset
  const saveAsPreset = () => {
    toast({
      title: 'Preset Saved',
      description: 'Parameter preset saved (not implemented yet)',
    });
  };

  // Execute workflow
  const executeWorkflow = () => {
    if (!localParams.prompt.trim()) {
      toast({
        title: 'Missing Prompt',
        description: 'Please enter a prompt before executing',
        variant: 'destructive',
      });
      return;
    }

    onExecuteWorkflow?.(localParams);
  };

  return (
    <div className={`space-y-6 ${className || ''}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Settings className="w-5 h-5" />
          Generation Parameters
        </h3>
        <div className="flex items-center gap-2">
          <button
            onClick={randomizeSeed}
            className="p-2 hover:bg-muted rounded-md"
            title="Randomize seed"
          >
            <Shuffle className="w-4 h-4" />
          </button>
          <button
            onClick={resetToDefaults}
            className="p-2 hover:bg-muted rounded-md"
            title="Reset to defaults"
          >
            <RotateCcw className="w-4 h-4" />
          </button>
          <button
            onClick={saveAsPreset}
            className="p-2 hover:bg-muted rounded-md"
            title="Save as preset"
          >
            <Save className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Prompts */}
      <div className="space-y-4">
        <div>
          <label className="text-sm font-medium mb-2 block">Prompt</label>
          <textarea
            value={localParams.prompt}
            onChange={(e) => updateParameter('prompt', e.target.value)}
            placeholder="Describe what you want to generate..."
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary resize-none"
            rows={3}
          />
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Negative Prompt</label>
          <textarea
            value={localParams.negativePrompt}
            onChange={(e) => updateParameter('negativePrompt', e.target.value)}
            placeholder="Describe what you want to avoid..."
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary resize-none"
            rows={2}
          />
        </div>
      </div>

      {/* Generation Settings */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm font-medium mb-2 block">Steps</label>
          <input
            type="number"
            min="1"
            max="150"
            value={localParams.steps}
            onChange={(e) => updateParameter('steps', parseInt(e.target.value) || 20)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Number of generation steps"
          />
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">CFG Scale</label>
          <input
            type="number"
            min="1"
            max="30"
            step="0.1"
            value={localParams.cfgScale}
            onChange={(e) => updateParameter('cfgScale', parseFloat(e.target.value) || 7.0)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="CFG scale parameter"
          />
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Sampler</label>
          <select
            value={localParams.sampler}
            onChange={(e) => updateParameter('sampler', e.target.value)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Sampler selection"
          >
            {AVAILABLE_SAMPLERS.map(sampler => (
              <option key={sampler} value={sampler}>{sampler}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Scheduler</label>
          <select
            value={localParams.scheduler}
            onChange={(e) => updateParameter('scheduler', e.target.value)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Scheduler selection"
          >
            {AVAILABLE_SCHEDULERS.map(scheduler => (
              <option key={scheduler} value={scheduler}>{scheduler}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Image Dimensions */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm font-medium mb-2 block">Width</label>
          <input
            type="number"
            min="64"
            max="2048"
            step="64"
            value={localParams.width}
            onChange={(e) => updateParameter('width', parseInt(e.target.value) || 1024)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Image width in pixels"
          />
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Height</label>
          <input
            type="number"
            min="64"
            max="2048"
            step="64"
            value={localParams.height}
            onChange={(e) => updateParameter('height', parseInt(e.target.value) || 1024)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Image height in pixels"
          />
        </div>
      </div>

      {/* Seed and Denoising */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm font-medium mb-2 block">Seed</label>
          <div className="flex gap-2">
            <input
              type="number"
              min="-1"
              value={localParams.seed}
              onChange={(e) => updateParameter('seed', parseInt(e.target.value) || -1)}
              className="flex-1 px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
              aria-label="Generation seed value"
            />
            <button
              onClick={randomizeSeed}
              className="px-3 py-2 bg-muted hover:bg-muted/80 rounded-md"
              title="Random seed"
            >
              <Shuffle className="w-4 h-4" />
            </button>
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            -1 for random seed
          </p>
        </div>

        <div>
          <label className="text-sm font-medium mb-2 block">Denoising Strength</label>
          <input
            type="number"
            min="0"
            max="1"
            step="0.01"
            value={localParams.denoisingStrength}
            onChange={(e) => updateParameter('denoisingStrength', parseFloat(e.target.value) || 1.0)}
            className="w-full px-3 py-2 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
            aria-label="Denoising strength"
          />
        </div>
      </div>

      {/* Execute Button */}
      {onExecuteWorkflow && (
        <div className="pt-4 border-t border-border">
          <button
            onClick={executeWorkflow}
            disabled={!localParams.prompt.trim()}
            className="w-full px-4 py-3 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 font-medium"
          >
            <Play className="w-4 h-4" />
            Generate with ComfyUI
          </button>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { ComfyUIClient } from '@/services/wizard/ComfyUIClient';
import { backendApi } from '@/services/backendApiService';
import {
  Play,
  Pause,
  Square,
  RefreshCw,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Loader2,
  Clock,
} from 'lucide-react';

interface WorkflowExecution {
  id: string;
  client: ComfyUIClient;
  status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
  progress: number;
  currentNode?: string;
  totalNodes?: number;
  completedNodes?: number;
  startTime: Date;
  endTime?: Date;
  error?: string;
  outputs?: Array<{
    type: 'image' | 'video' | 'audio';
    url: string;
    filename: string;
  }>;
}

interface ComfyUIProgressMonitorProps {
  executions: WorkflowExecution[];
  onExecutionUpdate?: (execution: WorkflowExecution) => void;
  onExecutionComplete?: (execution: WorkflowExecution) => void;
  className?: string;
}

export function ComfyUIProgressMonitor({
  executions,
  onExecutionUpdate,
  onExecutionComplete,
  className,
}: ComfyUIProgressMonitorProps) {
  const [activeExecutions, setActiveExecutions] = useState<WorkflowExecution[]>(executions);

  // Update executions when props change
  useEffect(() => {
    setActiveExecutions(executions);
  }, [executions]);

  // Format duration
  const formatDuration = (start: Date, end?: Date): string => {
    const endTime = end || new Date();
    const duration = endTime.getTime() - start.getTime();

    const seconds = Math.floor(duration / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);

    if (hours > 0) {
      return `${hours}h ${minutes % 60}m ${seconds % 60}s`;
    } else if (minutes > 0) {
      return `${minutes}m ${seconds % 60}s`;
    } else {
      return `${seconds}s`;
    }
  };

  // Get status color
  const getStatusColor = (status: WorkflowExecution['status']): string => {
    switch (status) {
      case 'queued': return 'text-yellow-600';
      case 'running': return 'text-blue-600';
      case 'completed': return 'text-green-600';
      case 'failed': return 'text-red-600';
      case 'cancelled': return 'text-gray-600';
      default: return 'text-gray-600';
    }
  };

  // Get status icon
  const getStatusIcon = (status: WorkflowExecution['status']) => {
    switch (status) {
      case 'queued':
        return <Clock className="w-4 h-4" />;
      case 'running':
        return <Loader2 className="w-4 h-4 animate-spin" />;
      case 'completed':
        return <CheckCircle className="w-4 h-4" />;
      case 'failed':
        return <XCircle className="w-4 h-4" />;
      case 'cancelled':
        return <Square className="w-4 h-4" />;
      default:
        return <AlertTriangle className="w-4 h-4" />;
    }
  };

  // Cancel execution
  const cancelExecution = useCallback(async (executionId: string) => {
    const execution = activeExecutions.find(e => e.id === executionId);
    if (!execution) return;

    try {
      // Cancel via backend API if available, otherwise interrupt client
      await backendApi.cancelComfyUIWorkflow(execution.id);

      const updatedExecution: WorkflowExecution = {
        ...execution,
        status: 'cancelled',
        endTime: new Date(),
      };

      setActiveExecutions(prev =>
        prev.map(e => e.id === executionId ? updatedExecution : e)
      );

      onExecutionUpdate?.(updatedExecution);
      onExecutionComplete?.(updatedExecution);
    } catch (error) {
      console.error('Failed to cancel execution:', error);
    }
  }, [activeExecutions, onExecutionUpdate, onExecutionComplete]);

  // Monitor execution progress
  useEffect(() => {
    const activeIds = activeExecutions
      .filter(e => e.status === 'running' || e.status === 'queued')
      .map(e => e.id);

    if (activeIds.length === 0) return;

    const interval = setInterval(async () => {
      for (const executionId of activeIds) {
        try {
          const response = await backendApi.getComfyUIStatus(executionId);

          if (response.success && response.data) {
            const statusData = response.data;

            setActiveExecutions(prev => prev.map(execution => {
              if (execution.id !== executionId) return execution;

              const updatedExecution: WorkflowExecution = {
                ...execution,
                status: statusData.status,
                progress: statusData.progress,
                currentNode: statusData.currentNode,
                totalNodes: statusData.totalNodes,
                completedNodes: statusData.completedNodes,
                outputs: statusData.outputs?.map(output => ({
                  type: output.type as 'image' | 'video' | 'audio',
                  url: output.url,
                  filename: output.filename,
                })),
              };

              // Mark as completed if status indicates completion
              if (statusData.status === 'completed' || statusData.status === 'failed') {
                updatedExecution.endTime = new Date();
                onExecutionComplete?.(updatedExecution);
              } else {
                onExecutionUpdate?.(updatedExecution);
              }

              return updatedExecution;
            }));
          }
        } catch (error) {
          console.error(`Failed to get status for execution ${executionId}:`, error);
        }
      }
    }, 2000); // Poll every 2 seconds

    return () => clearInterval(interval);
  }, [activeExecutions, onExecutionUpdate, onExecutionComplete]);

  if (activeExecutions.length === 0) {
    return (
      <div className={`text-center py-8 text-muted-foreground ${className || ''}`}>
        <RefreshCw className="w-8 h-8 mx-auto mb-2 opacity-50" />
        <p className="text-sm">No active workflow executions</p>
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className || ''}`}>
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-medium">Workflow Progress</h4>
        <span className="text-xs text-muted-foreground">
          {activeExecutions.filter(e => e.status === 'running').length} running
        </span>
      </div>

      <div className="space-y-3">
        {activeExecutions.map((execution) => (
          <div
            key={execution.id}
            className="border border-border rounded-lg p-4 bg-card"
          >
            {/* Header */}
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-2">
                <span className={getStatusColor(execution.status)}>
                  {getStatusIcon(execution.status)}
                </span>
                <span className="text-sm font-medium">
                  Workflow {execution.id.slice(-8)}
                </span>
                <span className={`text-xs px-2 py-1 rounded-full ${
                  execution.status === 'completed' ? 'bg-green-100 text-green-800' :
                  execution.status === 'running' ? 'bg-blue-100 text-blue-800' :
                  execution.status === 'failed' ? 'bg-red-100 text-red-800' :
                  execution.status === 'queued' ? 'bg-yellow-100 text-yellow-800' :
                  'bg-gray-100 text-gray-800'
                }`}>
                  {execution.status}
                </span>
              </div>

              {(execution.status === 'running' || execution.status === 'queued') && (
                <button
                  onClick={() => cancelExecution(execution.id)}
                  className="p-1 hover:bg-muted rounded text-muted-foreground hover:text-foreground"
                  title="Cancel execution"
                >
                  <Square className="w-4 h-4" />
                </button>
              )}
            </div>

            {/* Progress Bar */}
            <div className="mb-3">
              <div className="flex justify-between text-xs text-muted-foreground mb-1">
                <span>Progress</span>
                <span>{Math.round(execution.progress)}%</span>
              </div>
              <div className="w-full bg-muted rounded-full h-2">
                <div
                  className={`h-2 rounded-full transition-all duration-300 ${
                    execution.status === 'completed' ? 'bg-green-500' :
                    execution.status === 'failed' ? 'bg-red-500' :
                    'bg-blue-500'
                  }`}
                  style={{ width: `${execution.progress}%` }}
                />
              </div>
            </div>

            {/* Node Progress */}
            {execution.currentNode && execution.totalNodes && (
              <div className="mb-3">
                <div className="flex justify-between text-xs text-muted-foreground mb-1">
                  <span>Current Node</span>
                  <span>
                    {execution.completedNodes || 0} / {execution.totalNodes}
                  </span>
                </div>
                <div className="text-xs text-muted-foreground truncate">
                  {execution.currentNode}
                </div>
              </div>
            )}

            {/* Timing */}
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Duration: {formatDuration(execution.startTime, execution.endTime)}</span>
              {execution.outputs && execution.outputs.length > 0 && (
                <span>{execution.outputs.length} output{execution.outputs.length > 1 ? 's' : ''}</span>
              )}
            </div>

            {/* Error Display */}
            {execution.error && (
              <div className="mt-3 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-800">
                <div className="flex items-center space-x-1">
                  <AlertTriangle className="w-3 h-3" />
                  <span className="font-medium">Error:</span>
                </div>
                <div className="mt-1">{execution.error}</div>
              </div>
            )}

            {/* Outputs Preview */}
            {execution.outputs && execution.outputs.length > 0 && (
              <div className="mt-3">
                <div className="text-xs text-muted-foreground mb-2">Generated Files:</div>
                <div className="space-y-1">
                  {execution.outputs.slice(0, 3).map((output, index) => (
                    <div key={index} className="flex items-center space-x-2 text-xs">
                      <div className={`w-2 h-2 rounded-full ${
                        output.type === 'image' ? 'bg-green-500' :
                        output.type === 'video' ? 'bg-blue-500' :
                        'bg-purple-500'
                      }`} />
                      <span className="truncate">{output.filename}</span>
                    </div>
                  ))}
                  {execution.outputs.length > 3 && (
                    <div className="text-xs text-muted-foreground">
                      +{execution.outputs.length - 3} more files
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import React, { useEffect, useState, useMemo } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { useGenerationStore } from '@/stores/generationStore';
import { ChatPanel } from './ChatPanel';
import { loadChatPanelState, updateChatPanelOpenState } from '@/utils/chatPanelStorage';
import { PipelineAwareLLM } from '@/services/llm/PipelineAwareLLM';

export const FloatingAIAssistant: React.FC = () => {
  const {
    showChat,
    setShowChat,
    setChatPanelPosition,
    setChatPanelSize,
    setChatPanelMinimized,
    project
  } = useAppStore();

  // Subscribe to pipeline state for notification badge
  const currentPipeline = useGenerationStore((state) => state.currentPipeline);

  // Compute notification badge from pipeline state
  const notificationBadge = useMemo(() => {
    return PipelineAwareLLM.getNotificationBadge();
  }, [currentPipeline]);

  // Tooltip summary
  const tooltipText = useMemo(() => {
    const suggestions = PipelineAwareLLM.getContextualSuggestions();
    if (suggestions.length === 0) return 'Assistant StoryCore (Ctrl+K)';
    const firstSuggestion = suggestions[0];
    return `${firstSuggestion.title} — Ctrl+K pour ouvrir`;
  }, [currentPipeline]);

  // Load saved state on mount
  useEffect(() => {
    const savedState = loadChatPanelState();
    if (savedState) {
      setChatPanelPosition(savedState.position);
      setChatPanelSize(savedState.size);
      setChatPanelMinimized(savedState.isMinimized);
    }
  }, [setChatPanelPosition, setChatPanelSize, setChatPanelMinimized]);

  // Save open state when it changes
  useEffect(() => {
    updateChatPanelOpenState(showChat);
  }, [showChat]);

  // Keyboard shortcut: Ctrl+K / Cmd+K to toggle
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setShowChat(!showChat);
      }

      // Escape to close
      if (e.key === 'Escape' && showChat) {
        setShowChat(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [showChat, setShowChat]);

  // Handle window resize - reposition if off-screen
  useEffect(() => {
    const handleResize = () => {
      const savedState = loadChatPanelState();
      if (savedState) {
        const { position, size } = savedState;
        const maxX = window.innerWidth - size.width;
        const maxY = window.innerHeight - size.height;

        if (position.x > maxX || position.y > maxY) {
          const newPosition = {
            x: Math.max(0, Math.min(position.x, maxX)),
            y: Math.max(0, Math.min(position.y, maxY)),
          };
          setChatPanelPosition(newPosition);
        }
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [setChatPanelPosition]);

  // Notification badge colors
  const badgeColors: Record<string, string> = {
    error: '#ff4444',
    warning: '#ffaa00',
    info: '#4488ff',
    success: '#44cc44',
  };

  return (
    <>
      <ChatPanel />
      {/* Notification badge overlay — visible when chat is closed and project is open */}
      {!showChat && notificationBadge.count > 0 && project && (
        <div
          title={tooltipText}
          onClick={() => setShowChat(true)}
          style={{
            position: 'fixed',
            bottom: 114,
            right: 24,
            width: 48,
            height: 48,
            borderRadius: '50%',
            background: 'linear-gradient(135deg, #1a1a2e, #16213e)',
            border: `2px solid ${badgeColors[notificationBadge.type]}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            zIndex: 10000,
            boxShadow: `0 4px 20px ${badgeColors[notificationBadge.type]}40`,
            transition: 'all 0.3s ease',
            fontSize: '20px',
          }}
        >
          🤖
          <span
            style={{
              position: 'absolute',
              top: -4,
              right: -4,
              background: badgeColors[notificationBadge.type],
              color: '#fff',
              borderRadius: '50%',
              width: 20,
              height: 20,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '11px',
              fontWeight: 700,
              boxShadow: '0 2px 8px rgba(0,0,0,0.3)',
            }}
          >
            {notificationBadge.count}
          </span>
        </div>
      )}
    </>
  );
};

/**
 * Generation Progress Modal Component
 * 
 * Displays detailed progress during sequence generation through the StoryCore pipeline.
 * Shows stage-by-stage progress indicators, current shot processing, elapsed time,
 * estimated completion time, and error handling with retry functionality.
 * 
 * Requirements: 3.6, 8.1, 8.2, 8.3, 8.4, 8.5
 */

import { useEffect, useState, useRef } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { AlertCircle, CheckCircle2, Loader2, XCircle } from 'lucide-react';
import { useFocusManagement } from '../hooks/useFocusManagement';
import { useKeyboardShortcuts } from '../hooks/useKeyboardShortcuts';
import type { GenerationStatus } from '../types/projectDashboard';
import {
  getStageIcon,
  formatDuration,
  formatTimestamp,
  getProgressColor,
} from '../utils/generationStatusTracking';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for GenerationProgressModal component
 */
export interface GenerationProgressModalProps {
  /** Whether the modal is open */
  isOpen: boolean;
  /** Current generation status */
  status: GenerationStatus;
  /** Callback when cancel button is clicked */
  onCancel?: () => void;
  /** Callback when close button is clicked (after completion or error) */
  onClose: () => void;
  /** Callback when retry button is clicked (after error) */
  onRetry?: () => void;
}

/**
 * Stage information for display
 */
interface StageInfo {
  key: string;
  name: string;
  icon: string;
  status: 'pending' | 'in-progress' | 'complete' | 'error';
}

// ============================================================================
// Constants
// ============================================================================

/**
 * Pipeline stages in order
 * Requirements: 8.1
 */
const PIPELINE_STAGES: Array<{ key: string; name: string }> = [
  { key: 'grid', name: 'Master Coherence Sheet' },
  { key: 'comfyui', name: 'ComfyUI Generation' },
  { key: 'promotion', name: 'Promotion Engine' },
  { key: 'qa', name: 'QA Analysis' },
  { key: 'export', name: 'Export Package' },
];

// ============================================================================
// Component
// ============================================================================

/**
 * GenerationProgressModal Component
 * 
 * Displays generation progress with stage indicators, timing information,
 * and error handling capabilities.
 * 
 * Requirements: 3.6, 8.1, 8.2, 8.3, 8.4, 8.5
 */
export function GenerationProgressModal({
  isOpen,
  status,
  onCancel,
  onClose,
  onRetry,
}: GenerationProgressModalProps) {
  const [elapsedTime, setElapsedTime] = useState<number>(0);
  const modalRef = useRef<HTMLElement>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);

  // Focus management for modal
  useFocusManagement(modalRef, {
    enabled: isOpen,
    trapFocus: true,
  });

  // Keyboard shortcuts for modal
  useKeyboardShortcuts({
    shortcuts: [
      {
        key: 'Escape',
        action: () => {
          // Only allow escape to close if not generating
          if (!isGenerating) {
            onClose();
          }
        },
        description: 'Close modal',
      },
    ],
    enabled: isOpen,
  });

  // Update elapsed time every second
  // Requirements: 8.3
  useEffect(() => {
    if (!isOpen || !status.startTime) {
      setElapsedTime(0);
      return;
    }

    const updateElapsed = () => {
      const elapsed = Date.now() - (status.startTime || Date.now());
      setElapsedTime(elapsed);
    };

    // Initial update
    updateElapsed();

    // Update every second
    const interval = setInterval(updateElapsed, 1000);

    return () => clearInterval(interval);
  }, [isOpen, status.startTime]);

  /**
   * Get stage status based on current generation stage
   * Requirements: 8.1, 8.2
   */
  const getStageStatus = (stageKey: string): 'pending' | 'in-progress' | 'complete' | 'error' => {
    if (status.stage === 'error') {
      // If there's an error, mark all stages as error or complete based on progress
      const stageIndex = PIPELINE_STAGES.findIndex(s => s.key === stageKey);
      const currentIndex = PIPELINE_STAGES.findIndex(s => s.key === status.stage);
      if (stageIndex < currentIndex) return 'complete';
      if (stageIndex === currentIndex) return 'error';
      return 'pending';
    }

    if (status.stage === 'complete') {
      return 'complete';
    }

    const stageIndex = PIPELINE_STAGES.findIndex(s => s.key === stageKey);
    const currentIndex = PIPELINE_STAGES.findIndex(s => s.key === status.stage);

    if (stageIndex < currentIndex) return 'complete';
    if (stageIndex === currentIndex) return 'in-progress';
    return 'pending';
  };

  /**
   * Build stage information array
   * Requirements: 8.1
   */
  const stages: StageInfo[] = PIPELINE_STAGES.map(stage => ({
    key: stage.key,
    name: stage.name,
    icon: getStageIcon(stage.key),
    status: getStageStatus(stage.key),
  }));

  /**
   * Calculate estimated time remaining
   * Requirements: 8.4
   */
  const estimatedTimeRemaining = status.estimatedCompletion
    ? Math.max(0, status.estimatedCompletion - Date.now())
    : 0;

  /**
   * Determine if generation is in progress
   */
  const isGenerating =
    status.stage !== 'idle' &&
    status.stage !== 'complete' &&
    status.stage !== 'error';

  /**
   * Determine if generation has error
   */
  const hasError = status.stage === 'error';

  /**
   * Determine if generation is complete
   */
  const isComplete = status.stage === 'complete';

  /**
   * Get dialog title based on status
   */
  const getDialogTitle = (): string => {
    if (hasError) return 'Generation Failed';
    if (isComplete) return 'Generation Complete';
    return 'Generating Sequence';
  };

  /**
   * Get dialog description based on status
   */
  const getDialogDescription = (): string => {
    if (hasError) {
      return 'An error occurred during sequence generation. You can retry or cancel.';
    }
    if (isComplete) {
      return 'Your sequence has been generated successfully!';
    }
    return 'Processing your sequence through the StoryCore pipeline...';
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        ref={modalRef}
        className="sm:max-w-[600px]"
        onInteractOutside={(e) => {
          // Prevent closing while generating
          if (isGenerating) {
            e.preventDefault();
          }
        }}
        aria-describedby="generation-progress-description"
      >
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {hasError && <XCircle className="h-5 w-5 text-red-500" aria-hidden="true" />}
            {isComplete && <CheckCircle2 className="h-5 w-5 text-green-500" aria-hidden="true" />}
            {isGenerating && <Loader2 className="h-5 w-5 animate-spin text-blue-500" aria-hidden="true" />}
            {getDialogTitle()}
          </DialogTitle>
          <DialogDescription id="generation-progress-description">
            {getDialogDescription()}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Overall Progress Bar */}
          {/* Requirements: 8.2 */}
          <div className="space-y-2">
            <div className="flex items-center justify-between text-sm">
              <span className="font-medium">Overall Progress</span>
              <span className="text-muted-foreground">
                {Math.round(status.progress)}%
              </span>
            </div>
            <Progress
              value={status.progress}
              className="h-2"
              style={{
                // @ts-ignore - CSS custom property
                '--progress-color': getProgressColor(status.stage),
              }}
            />
          </div>

          {/* Stage Indicators */}
          {/* Requirements: 8.1 */}
          <div className="space-y-3">
            <h4 className="text-sm font-medium">Pipeline Stages</h4>
            <div className="space-y-2">
              {stages.map((stage) => (
                <div
                  key={stage.key}
                  className="flex items-center gap-3 rounded-lg border p-3 transition-colors"
                  style={{
                    borderColor:
                      stage.status === 'in-progress'
                        ? getProgressColor(stage.key)
                        : undefined,
                    backgroundColor:
                      stage.status === 'in-progress'
                        ? `${getProgressColor(stage.key)}10`
                        : undefined,
                  }}
                >
                  {/* Stage Icon/Status */}
                  <div className="flex-shrink-0">
                    {stage.status === 'complete' && (
                      <CheckCircle2 className="h-5 w-5 text-green-500" />
                    )}
                    {stage.status === 'in-progress' && (
                      <Loader2 className="h-5 w-5 animate-spin text-blue-500" />
                    )}
                    {stage.status === 'error' && (
                      <XCircle className="h-5 w-5 text-red-500" />
                    )}
                    {stage.status === 'pending' && (
                      <div className="h-5 w-5 rounded-full border-2 border-gray-300" />
                    )}
                  </div>

                  {/* Stage Name */}
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-lg">{stage.icon}</span>
                      <span className="text-sm font-medium">{stage.name}</span>
                    </div>
                  </div>

                  {/* Stage Status Text */}
                  <div className="text-xs text-muted-foreground">
                    {stage.status === 'complete' && 'Complete'}
                    {stage.status === 'in-progress' && 'In Progress'}
                    {stage.status === 'error' && 'Failed'}
                    {stage.status === 'pending' && 'Pending'}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Shot Progress */}
          {/* Requirements: 8.4 */}
          {status.totalShots && status.totalShots > 0 && (
            <div className="rounded-lg border p-3">
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium">Shot Progress</span>
                <span className="text-sm text-muted-foreground">
                  {status.currentShot || 0} / {status.totalShots}
                </span>
              </div>
            </div>
          )}

          {/* Timing Information */}
          {/* Requirements: 8.3, 8.4 */}
          <div className="grid grid-cols-2 gap-4">
            <div className="rounded-lg border p-3">
              <div className="text-xs text-muted-foreground mb-1">Elapsed Time</div>
              <div className="text-lg font-semibold">
                {formatDuration(elapsedTime)}
              </div>
            </div>
            <div className="rounded-lg border p-3">
              <div className="text-xs text-muted-foreground mb-1">
                {isComplete ? 'Total Time' : 'Est. Remaining'}
              </div>
              <div className="text-lg font-semibold">
                {isComplete
                  ? formatDuration(elapsedTime)
                  : estimatedTimeRemaining > 0
                  ? formatDuration(estimatedTimeRemaining)
                  : '--'}
              </div>
            </div>
          </div>

          {/* Estimated Completion Time */}
          {/* Requirements: 8.4 */}
          {!isComplete && !hasError && status.estimatedCompletion && (
            <div className="rounded-lg bg-muted p-3 text-center">
              <div className="text-xs text-muted-foreground mb-1">
                Estimated Completion
              </div>
              <div className="text-sm font-medium">
                {formatTimestamp(status.estimatedCompletion)}
              </div>
            </div>
          )}

          {/* Error Display */}
          {/* Requirements: 3.7, 8.5 */}
          {hasError && status.error && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-4">
              <div className="flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="text-sm font-semibold text-red-900 mb-1">
                    Error Details
                  </h4>
                  <p className="text-sm text-red-700">{status.error}</p>
                </div>
              </div>
            </div>
          )}

          {/* Success Message */}
          {isComplete && (
            <div className="rounded-lg border border-green-200 bg-green-50 p-4">
              <div className="flex items-start gap-3">
                <CheckCircle2 className="h-5 w-5 text-green-500 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="text-sm font-semibold text-green-900 mb-1">
                    Generation Successful
                  </h4>
                  <p className="text-sm text-green-700">
                    Your sequence has been generated and is ready to view.
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          {/* Cancel Button (only during generation) */}
          {/* Requirements: 8.5 */}
          {isGenerating && onCancel && (
            <Button variant="outline" onClick={onCancel}>
              Cancel Generation
            </Button>
          )}

          {/* Retry Button (only on error) */}
          {/* Requirements: 3.7, 8.5 */}
          {hasError && onRetry && (
            <Button variant="default" onClick={onRetry}>
              Retry Generation
            </Button>
          )}

          {/* Close Button (on error or completion) */}
          {(hasError || isComplete) && (
            <Button
              ref={closeButtonRef}
              variant={hasError ? 'outline' : 'default'}
              onClick={onClose}
              aria-label={hasError ? 'Close modal' : 'View generation results'}
            >
              {hasError ? 'Close' : 'View Results'}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Default export
 */
export default GenerationProgressModal;

