  onCloseActiveWizard: () => void;
  onCompleteWizard: (output: unknown) => void;
}

/**
 * Centralized modals container
 * Renders all application modals in one place to prevent duplication
 */
export function ModalsContainer({
  // Installation
  showInstallationWizard,
  onCloseInstallationWizard,
  onCompleteInstallation,

  // Wizards
  showWorldWizard,
  onCloseWorldWizard,
  onCompleteWorld,

  characterWizardWorldContext,
  showCharacterWizard,
  onCloseCharacterWizard,
  onCompleteCharacter,

  showObjectWizard,
  onCloseObjectWizard,
  onCompleteObject,

  showStorytellerWizard,
  onCloseStorytellerWizard,
  onCompleteStoryteller,

  // Settings
  showLLMSettings,
  onCloseLLMSettings,

  showComfyUISettings,
  onCloseComfyUISettings,

  showGeneralSettings,
  onCloseGeneralSettings,

  // Addons
  showAddonsModal,
  onCloseAddonsModal,

  // Content Modals
  showCharactersModal,
  onCloseCharactersModal,

  showWorldModal,
  onCloseWorldModal,

  showLocationsModal,
  onCloseLocationsModal,

  showObjectsModal,
  onCloseObjectsModal,

  showImageGalleryModal,
  onCloseImageGalleryModal,

  // Feedback
  showFeedbackPanel,
  onCloseFeedbackPanel,
  feedbackInitialContext,
  onOpenPendingReports,

  showPendingReportsList,
  onClosePendingReportsList,

  // Sequence Plan Wizard
  showSequencePlanWizard,
  onCloseSequencePlanWizard,
  onCompleteSequencePlan,
  sequencePlanWizardContext,

  // Shot Wizard
  showShotWizard,
  onCloseShotWizard,
  onCompleteShot,
  shotWizardContext,

  // Generic Wizard
  activeWizardType,
  onCloseActiveWizard,
  onCompleteWizard,
