  return (
    <>
      {/* Installation Wizard */}
      <InstallationWizardModal
        isOpen={showInstallationWizard}
        onClose={onCloseInstallationWizard}
        onComplete={onCompleteInstallation}
      />

      {/* Content Wizards */}
      <WorldWizardModal
        isOpen={showWorldWizard}
        onClose={onCloseWorldWizard}
