import React, { useState, useRef, useEffect } from 'react';
import { Move, Crosshair } from 'lucide-react';
import type { SurroundConfig } from '../types';

interface SpatialPositionerProps {
  config: SurroundConfig;
  onChange: (config: SurroundConfig) => void;
}

/**
 * SpatialPositioner - 3D audio positioning interface
 * 
 * Features:
 * - 2D top-down view of audio space
 * - Draggable audio source position
 * - X/Y/Z coordinate inputs
 * - Real-time channel level calculation
 * 
 * Requirements: 20.10
 */
export const SpatialPositioner: React.FC<SpatialPositionerProps> = ({ config, onChange }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState(
    config.spatialPosition ?? { x: 0, y: 0, z: 0 }
  );

  // Canvas dimensions
  const canvasWidth = 400;
  const canvasHeight = 400;
  const centerX = canvasWidth / 2;
  const centerY = canvasHeight / 2;
  const radius = 180; // Maximum distance from center

  useEffect(() => {
    drawCanvas();
  }, [position, config.mode]);

  const drawCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    // Draw background
    ctx.fillStyle = '#f9fafb';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    // Draw grid
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 8; i++) {
      const x = (canvasWidth / 8) * i;
      const y = (canvasHeight / 8) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvasHeight);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvasWidth, y);
      ctx.stroke();
    }

    // Draw center crosshair
    ctx.strokeStyle = '#9ca3af';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(centerX - 20, centerY);
    ctx.lineTo(centerX + 20, centerY);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(centerX, centerY - 20);
    ctx.lineTo(centerX, centerY + 20);
    ctx.stroke();

    // Draw listener position (center)
    ctx.fillStyle = '#6b7280';
    ctx.beginPath();
    ctx.arc(centerX, centerY, 8, 0, Math.PI * 2);
    ctx.fill();

    // Draw speaker positions based on mode
    drawSpeakers(ctx);

    // Draw audio source position
    const sourceX = centerX + position.x * radius;
    const sourceY = centerY - position.y * radius; // Invert Y for canvas coordinates

    // Draw connection line
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(sourceX, sourceY);
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw audio source
    ctx.fillStyle = '#3b82f6';
    ctx.strokeStyle = '#1e40af';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(sourceX, sourceY, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Draw height indicator
    const heightOpacity = (position.z + 1) / 2; // Map -1 to 1 -> 0 to 1
    ctx.fillStyle = `rgba(59, 130, 246, ${heightOpacity})`;
    ctx.beginPath();
    ctx.arc(sourceX, sourceY, 20, 0, Math.PI * 2);
    ctx.fill();

    // Draw labels
    ctx.fillStyle = '#374151';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Front', centerX, 20);
    ctx.fillText('Back', centerX, canvasHeight - 10);
    ctx.textAlign = 'left';
    ctx.fillText('Left', 10, centerY);
    ctx.textAlign = 'right';
    ctx.fillText('Right', canvasWidth - 10, centerY);
  };

  const drawSpeakers = (ctx: CanvasRenderingContext2D) => {
    const speakerRadius = 10;
    ctx.fillStyle = '#10b981';
    ctx.strokeStyle = '#059669';
    ctx.lineWidth = 2;

    if (config.mode === 'stereo') {
      // Left speaker
      ctx.beginPath();
      ctx.arc(centerX - 100, centerY - 100, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Right speaker
      ctx.beginPath();
      ctx.arc(centerX + 100, centerY - 100, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    } else if (config.mode === '5.1') {
      // Front Left
      ctx.beginPath();
      ctx.arc(centerX - 120, centerY - 120, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Front Right
      ctx.beginPath();
      ctx.arc(centerX + 120, centerY - 120, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Center
      ctx.beginPath();
      ctx.arc(centerX, centerY - 140, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Surround Left
      ctx.beginPath();
      ctx.arc(centerX - 140, centerY + 80, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Surround Right
      ctx.beginPath();
      ctx.arc(centerX + 140, centerY + 80, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    } else if (config.mode === '7.1') {
      // Front Left
      ctx.beginPath();
      ctx.arc(centerX - 120, centerY - 120, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Front Right
      ctx.beginPath();
      ctx.arc(centerX + 120, centerY - 120, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Center
      ctx.beginPath();
      ctx.arc(centerX, centerY - 140, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Side Left
      ctx.beginPath();
      ctx.arc(centerX - 160, centerY, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Side Right
      ctx.beginPath();
      ctx.arc(centerX + 160, centerY, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Surround Left
      ctx.beginPath();
      ctx.arc(centerX - 140, centerY + 100, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Surround Right
      ctx.beginPath();
      ctx.arc(centerX + 140, centerY + 100, speakerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Check if clicking on audio source
    const sourceX = centerX + position.x * radius;
    const sourceY = centerY - position.y * radius;
    const distance = Math.sqrt(
      Math.pow(mouseX - sourceX, 2) + Math.pow(mouseY - sourceY, 2)
    );

    if (distance <= 20) {
      setIsDragging(true);
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isDragging) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Calculate new position
    let newX = (mouseX - centerX) / radius;
    let newY = -(mouseY - centerY) / radius; // Invert Y

    // Clamp to -1 to 1 range
    newX = Math.max(-1, Math.min(1, newX));
    newY = Math.max(-1, Math.min(1, newY));

    const newPosition = { x: newX, y: newY, z: position.z };
    setPosition(newPosition);

    // Calculate channel levels from position
    const channelLevels = calculateChannelLevels(newPosition, config.mode);

    onChange({
      ...config,
      spatialPosition: newPosition,
      channels: channelLevels,
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleCoordinateChange = (axis: 'x' | 'y' | 'z', value: number) => {
    const newPosition = { ...position, [axis]: value };
    setPosition(newPosition);

    // Calculate channel levels from position
    const channelLevels = calculateChannelLevels(newPosition, config.mode);

    onChange({
      ...config,
      spatialPosition: newPosition,
      channels: channelLevels,
    });
  };

  return (
    <div className="space-y-4 p-4 bg-gray-50 rounded-lg">
      <div className="flex items-center gap-2 mb-4">
        <Move className="w-5 h-5 text-blue-600" />
        <h3 className="text-lg font-semibold">Spatial Positioning</h3>
      </div>

      {/* 2D Top-Down View */}
      <div className="space-y-2">
        <label className="text-sm font-medium text-gray-700">Top-Down View</label>
        <div className="bg-white rounded-lg border border-gray-200 p-4 flex justify-center">
          <canvas
            ref={canvasRef}
            width={canvasWidth}
            height={canvasHeight}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            className="w-full h-auto cursor-move"
          />
        </div>
        <p className="text-xs text-gray-500 text-center">
          <Crosshair className="w-3 h-3 inline mr-1" />
          Drag the blue circle to position the audio source
        </p>
      </div>

      {/* Coordinate Inputs */}
      <div className="grid grid-cols-3 gap-4">
        <div className="space-y-1">
          <label htmlFor="x-coordinate" className="text-sm font-medium text-gray-700">X (Left/Right)</label>
          <input
            id="x-coordinate"
            type="number"
            min="-1"
            max="1"
            step="0.1"
            value={position.x.toFixed(2)}
            onChange={(e) => handleCoordinateChange('x', Number(e.target.value))}
            className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
          />
          <p className="text-xs text-gray-500">-1 (Left) to 1 (Right)</p>
        </div>

        <div className="space-y-1">
          <label htmlFor="y-coordinate" className="text-sm font-medium text-gray-700">Y (Front/Back)</label>
          <input
            id="y-coordinate"
            type="number"
            min="-1"
            max="1"
            step="0.1"
            value={position.y.toFixed(2)}
            onChange={(e) => handleCoordinateChange('y', Number(e.target.value))}
            className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
          />
          <p className="text-xs text-gray-500">-1 (Back) to 1 (Front)</p>
        </div>

        <div className="space-y-1">
          <label htmlFor="z-coordinate" className="text-sm font-medium text-gray-700">Z (Height)</label>
          <input
            id="z-coordinate"
            type="number"
            min="-1"
            max="1"
            step="0.1"
            value={position.z.toFixed(2)}
            onChange={(e) => handleCoordinateChange('z', Number(e.target.value))}
            className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
          />
          <p className="text-xs text-gray-500">-1 (Ground) to 1 (Height)</p>
        </div>
      </div>

      {/* Position Presets */}
      <div className="space-y-2">
        <label className="text-sm font-medium text-gray-700">Quick Positions</label>
        <div className="grid grid-cols-3 gap-2">
          <button
            onClick={() => handleCoordinateChange('x', 0)}
            className="px-3 py-2 text-sm bg-white border border-gray-300 rounded-md hover:bg-gray-50"
          >
            Center
          </button>
          <button
            onClick={() => {
              setPosition({ x: -0.7, y: 0.7, z: 0 });
              const channelLevels = calculateChannelLevels({ x: -0.7, y: 0.7, z: 0 }, config.mode);
              onChange({ ...config, spatialPosition: { x: -0.7, y: 0.7, z: 0 }, channels: channelLevels });
            }}
            className="px-3 py-2 text-sm bg-white border border-gray-300 rounded-md hover:bg-gray-50"
          >
            Front Left
          </button>
          <button
            onClick={() => {
              setPosition({ x: 0.7, y: 0.7, z: 0 });
              const channelLevels = calculateChannelLevels({ x: 0.7, y: 0.7, z: 0 }, config.mode);
              onChange({ ...config, spatialPosition: { x: 0.7, y: 0.7, z: 0 }, channels: channelLevels });
            }}
            className="px-3 py-2 text-sm bg-white border border-gray-300 rounded-md hover:bg-gray-50"
          >
            Front Right
          </button>
        </div>
      </div>
    </div>
  );
};

/**
 * Calculate channel levels from 3D position
 * Uses distance-based attenuation and angle-based panning
 */
function calculateChannelLevels(
  position: { x: number; y: number; z: number },
  mode: 'stereo' | '5.1' | '7.1'
): SurroundConfig['channels'] {
  const { x, y, z } = position;

  // Helper function to calculate distance-based gain
  const calculateGain = (speakerX: number, speakerY: number, speakerZ: number = 0): number => {
    const distance = Math.sqrt(
      Math.pow(x - speakerX, 2) + Math.pow(y - speakerY, 2) + Math.pow(z - speakerZ, 2)
    );
    // Inverse square law with minimum distance to avoid division by zero
    const minDistance = 0.1;
    const effectiveDistance = Math.max(distance, minDistance);
    const gain = 1 / (effectiveDistance * effectiveDistance);
    // Normalize to 0-100 range
    return Math.min(100, gain * 25);
  };

  if (mode === 'stereo') {
    // Simple stereo panning
    const leftGain = calculateGain(-1, 1);
    const rightGain = calculateGain(1, 1);
    const total = leftGain + rightGain;

    return {
      left: Math.round((leftGain / total) * 100),
      right: Math.round((rightGain / total) * 100),
    };
  }

  if (mode === '5.1') {
    const frontLeft = calculateGain(-0.7, 1);
    const frontRight = calculateGain(0.7, 1);
    const center = calculateGain(0, 1);
    const surroundLeft = calculateGain(-0.7, -1);
    const surroundRight = calculateGain(0.7, -1);
    const lfe = 80; // LFE is typically constant

    const total = frontLeft + frontRight + center + surroundLeft + surroundRight;

    return {
      frontLeft: Math.round((frontLeft / total) * 100),
      frontRight: Math.round((frontRight / total) * 100),
      center: Math.round((center / total) * 100),
      lfe,
      surroundLeft: Math.round((surroundLeft / total) * 100),
      surroundRight: Math.round((surroundRight / total) * 100),
    };
  }

  // 7.1
  const frontLeft = calculateGain(-0.7, 1);
  const frontRight = calculateGain(0.7, 1);
  const center = calculateGain(0, 1);
  const sideLeft = calculateGain(-1, 0);
  const sideRight = calculateGain(1, 0);
  const surroundLeft = calculateGain(-0.7, -1);
  const surroundRight = calculateGain(0.7, -1);
  const lfe = 80; // LFE is typically constant

  const total =
    frontLeft + frontRight + center + sideLeft + sideRight + surroundLeft + surroundRight;

  return {
    frontLeft: Math.round((frontLeft / total) * 100),
    frontRight: Math.round((frontRight / total) * 100),
    center: Math.round((center / total) * 100),
    lfe,
    sideLeft: Math.round((sideLeft / total) * 100),
    sideRight: Math.round((sideRight / total) * 100),
    surroundLeft: Math.round((surroundLeft / total) * 100),
    surroundRight: Math.round((surroundRight / total) * 100),
  };
}

import React, { useCallback, useState } from 'react';
import { useDrag, useDrop } from 'react-dnd';
import { useStore } from '../store';
import type { Shot } from '../types';
import { DND_ITEM_TYPES, type ShotDragItem } from '../constants/dnd';
import { ShotEditModal } from './ShotEditModal';

/**
 * StoryboardCanvas Component
 * 
 * Displays shots in a responsive grid layout with visual cards.
 * This is the main visual workspace where shots are arranged and edited.
 * 
 * Features:
 * - Responsive grid layout (adjusts columns based on screen size)
 * - Shot cards with thumbnails, titles, descriptions, and durations
 * - Empty state when no shots exist
 * - Selection support (click to select)
 * - Drag-and-drop reordering with visual feedback
 * - Snap-to-grid behavior
 * 
 * Requirements: 2.1, 2.2, 7.2, 7.3 (Storyboard Canvas with drag-and-drop)
 */

interface StoryboardCanvasProps {
  className?: string;
}

export const StoryboardCanvas: React.FC<StoryboardCanvasProps> = ({ className = '' }) => {
  const shots = useStore((state) => state.shots);
  const selectedShotId = useStore((state) => state.selectedShotId);
  const selectShot = useStore((state) => state.selectShot);
  const reorderShots = useStore((state) => state.reorderShots);
  
  const [editingShot, setEditingShot] = useState<Shot | null>(null);

  const handleShotClick = (shotId: string) => {
    selectShot(shotId);
  };

  const handleShotDoubleClick = (shot: Shot) => {
    setEditingShot(shot);
  };

  const handleCloseEditModal = () => {
    setEditingShot(null);
  };

  // Handle shot reordering via drag-and-drop
  const moveShot = useCallback(
    (dragIndex: number, hoverIndex: number) => {
      const dragShot = shots[dragIndex];
      const newShots = [...shots];
      
      // Remove the dragged shot
      newShots.splice(dragIndex, 1);
      
      // Insert at the new position
      newShots.splice(hoverIndex, 0, dragShot);
      
      // Update positions
      const reorderedShots = newShots.map((shot, index) => ({
        ...shot,
        position: index,
      }));
      
      reorderShots(reorderedShots);
    },
    [shots, reorderShots]
  );

  // Set up drop target for the canvas
  const [{ isOver }, drop] = useDrop({
    accept: DND_ITEM_TYPES.SHOT,
    collect: (monitor) => ({
      isOver: monitor.isOver(),
    }),
  });

  // Empty state when no shots exist
  if (shots.length === 0) {
    return (
      <div className={`flex items-center justify-center h-full bg-gray-50 ${className}`}>
        <div className="text-center p-8">
          <div className="mb-4">
            <svg
              className="mx-auto h-24 w-24 text-gray-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M7 4v16M17 4v16M3 8h4m10 0h4M3 12h18M3 16h4m10 0h4M4 20h16a1 1 0 001-1V5a1 1 0 00-1-1H4a1 1 0 00-1 1v14a1 1 0 001 1z"
              />
            </svg>
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">No shots yet</h3>
          <p className="text-sm text-gray-500 mb-4">
            Get started by dragging assets from the library or using the chat assistant to create shots.
          </p>
          <div className="flex gap-2 justify-center text-xs text-gray-400">
            <span>💡 Tip: Drag images from the Asset Library to create shots</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div ref={drop as any} className={`h-full overflow-auto bg-gray-50 ${className} ${isOver ? 'bg-blue-50' : ''}`}>
      <div className="p-6">
        {/* Grid container with responsive columns */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {shots.map((shot, index) => (
            <ShotCard
              key={shot.id}
              shot={shot}
              index={index}
              isSelected={shot.id === selectedShotId}
              onClick={() => handleShotClick(shot.id)}
              onDoubleClick={() => handleShotDoubleClick(shot)}
              moveShot={moveShot}
            />
          ))}
        </div>
      </div>

      {/* Edit Modal */}
      {editingShot && (
        <ShotEditModal
          shot={editingShot}
          isOpen={true}
          onClose={handleCloseEditModal}
        />
      )}
    </div>
  );
};

/**
 * ShotCard Component
 * 
 * Displays a single shot with thumbnail, title, description, and metadata.
 * 
 * Features:
 * - Thumbnail image display (or placeholder if no image)
 * - Title and description
 * - Duration display
 * - Audio track indicators
 * - Visual selection indicator
 * - Hover effects
 * - Drag-and-drop support for reordering
 * - Double-click to edit
 * - Delete button
 */

interface ShotCardProps {
  shot: Shot;
  index: number;
  isSelected: boolean;
  onClick: () => void;
  onDoubleClick: () => void;
  moveShot: (dragIndex: number, hoverIndex: number) => void;
}

const ShotCard: React.FC<ShotCardProps> = ({ shot, index, isSelected, onClick, onDoubleClick, moveShot }) => {
  const deleteShot = useStore((state) => state.deleteShot);
  const cardRef = React.useRef<HTMLDivElement>(null);
  
  const hasAudio = shot.audioTracks && shot.audioTracks.length > 0;
  const hasEffects = shot.effects && shot.effects.length > 0;
  const hasTextLayers = shot.textLayers && shot.textLayers.length > 0;

  // Set up drag source
  const [{ isDragging }, drag] = useDrag({
    type: DND_ITEM_TYPES.SHOT,
    item: (): ShotDragItem => ({
      type: DND_ITEM_TYPES.SHOT,
      shotId: shot.id,
      index,
    }),
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  // Set up drop target
  const [{ isOver }, drop] = useDrop({
    accept: DND_ITEM_TYPES.SHOT,
    hover: (item: ShotDragItem, monitor) => {
      if (!cardRef.current) {
        return;
      }

      const dragIndex = item.index;
      const hoverIndex = index;

      // Don't replace items with themselves
      if (dragIndex === hoverIndex) {
        return;
      }

      // Determine rectangle on screen
      const hoverBoundingRect = cardRef.current.getBoundingClientRect();

      // Get vertical middle
      const hoverMiddleY = (hoverBoundingRect.bottom - hoverBoundingRect.top) / 2;

      // Determine mouse position
      const clientOffset = monitor.getClientOffset();

      if (!clientOffset) {
        return;
      }

      // Get pixels to the top
      const hoverClientY = clientOffset.y - hoverBoundingRect.top;

      // Only perform the move when the mouse has crossed half of the items height
      // When dragging downwards, only move when the cursor is below 50%
      // When dragging upwards, only move when the cursor is above 50%

      // Dragging downwards
      if (dragIndex < hoverIndex && hoverClientY < hoverMiddleY) {
        return;
      }

      // Dragging upwards
      if (dragIndex > hoverIndex && hoverClientY > hoverMiddleY) {
        return;
      }

      // Time to actually perform the action
      moveShot(dragIndex, hoverIndex);

      // Note: we're mutating the monitor item here!
      // Generally it's better to avoid mutations,
      // but it's good here for the sake of performance
      // to avoid expensive index searches.
      item.index = hoverIndex;
    },
    collect: (monitor) => ({
      isOver: monitor.isOver(),
    }),
  });

  // Combine drag and drop refs
  drag(drop(cardRef));

  // Handle double-click to edit
  const handleDoubleClick = () => {
    onDoubleClick();
  };

  // Handle delete
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent triggering onClick
    
    if (window.confirm(`Are you sure you want to delete "${shot.title || 'Untitled Shot'}"?`)) {
      deleteShot(shot.id);
    }
  };

  return (
    <div
      ref={cardRef}
      onClick={onClick}
      onDoubleClick={handleDoubleClick}
      className={`
        relative bg-white rounded-lg shadow-sm overflow-hidden cursor-pointer
        transition-all duration-200 hover:shadow-md
        ${isSelected ? 'ring-2 ring-blue-500 shadow-lg' : 'hover:ring-1 hover:ring-gray-300'}
        ${isDragging ? 'opacity-50 scale-95' : 'opacity-100'}
        ${isOver ? 'ring-2 ring-green-400' : ''}
      `}
      style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
    >
      {/* Delete button */}
      <button
        onClick={handleDelete}
        className="absolute top-2 right-2 z-10 bg-red-500 hover:bg-red-600 text-white rounded-full p-1.5 opacity-0 hover:opacity-100 transition-opacity group-hover:opacity-100"
        title="Delete shot"
        aria-label="Supprimer le plan"
      >
        <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M6 18L18 6M6 6l12 12"
          />
        </svg>
      </button>

      {/* Thumbnail */}
      <div className="aspect-video bg-gray-200 relative overflow-hidden">
        {shot.image ? (
          <img
            src={shot.image}
            alt={shot.title}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <svg
              className="h-16 w-16 text-gray-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
              />
            </svg>
          </div>
        )}
        
        {/* Duration badge */}
        <div className="absolute bottom-2 right-2 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded">
          {formatDuration(shot.duration)}
        </div>

        {/* Position indicator */}
        <div className="absolute top-2 left-2 bg-blue-600 text-white text-xs font-semibold px-2 py-1 rounded">
          #{shot.position + 1}
        </div>
        
        {/* Status indicator */}
        {shot.status && (
          <div className="absolute top-2 right-12 bg-yellow-600 text-white text-xs font-semibold px-2 py-1 rounded">
            {shot.status}
          </div>
        )}

        {/* Drag indicator */}
        {isDragging && (
          <div className="absolute inset-0 bg-blue-500 bg-opacity-20 flex items-center justify-center">
            <div className="bg-white rounded-lg px-3 py-2 shadow-lg">
              <span className="text-sm font-semibold text-gray-700">Moving...</span>
            </div>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="p-3">
        {/* Title */}
        <h3 className="font-semibold text-sm text-gray-900 mb-1 line-clamp-1">
          {shot.title || 'Untitled Shot'}
        </h3>

        {/* Description */}
        {shot.description && (
          <p className="text-xs text-gray-600 mb-2 line-clamp-2">
            {shot.description}
          </p>
        )}

        {/* Metadata indicators */}
        <div className="flex items-center gap-2 text-xs text-gray-500">
          {hasAudio && (
            <div className="flex items-center gap-1" title={`${shot.audioTracks.length} audio track(s)`}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z"
                />
              </svg>
              <span>{shot.audioTracks.length}</span>
            </div>
          )}

          {hasEffects && (
            <div className="flex items-center gap-1" title={`${shot.effects.length} effect(s)`}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01"
                />
              </svg>
              <span>{shot.effects.length}</span>
            </div>
          )}

          {hasTextLayers && (
            <div className="flex items-center gap-1" title={`${shot.textLayers.length} text layer(s)`}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                />
              </svg>
              <span>{shot.textLayers.length}</span>
            </div>
          )}

          {shot.transitionOut && (
            <div className="flex items-center gap-1" title={`Transition: ${shot.transitionOut.type}`}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M13 5l7 7-7 7M5 5l7 7-7 7"
                />
              </svg>
            </div>
          )}
          
          {/* Progress indicator */}
          {shot.progress && shot.progress < 100 && (
            <div className="flex items-center gap-1" title={`Progress: ${shot.progress}%`}>
              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                />
              </svg>
              <span>{shot.progress}%</span>
            </div>
          )}
        </div>
      </div>

      {/* Selection indicator overlay */}
      {isSelected && (
        <div className="absolute inset-0 pointer-events-none border-2 border-blue-500 rounded-lg" />
      )}
    </div>
  );
};

/**
 * Format duration in seconds to MM:SS format
 */
function formatDuration(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
}

