            </div>
          </div>

          <div className="export-section">
            <h4>Quality</h4>
            <div className="quality-slider">
              <label htmlFor="quality-slider" className="sr-only">Video quality</label>
              <input
                id="quality-slider"
                type="range"
                min="1"
