/**
 * Preview Player Component
 * Video preview with playback controls
 */

import React, { useRef, useEffect, useCallback, forwardRef } from 'react';
import './PreviewPlayer.css';

interface PreviewPlayerProps {
  src?: string;
  currentTime: number;
  onTimeUpdate: (time: number) => void;
  onDurationChange: (duration: number) => void;
  poster?: string;
}

export const PreviewPlayer = forwardRef<HTMLVideoElement, PreviewPlayerProps>(
  ({ src, currentTime, onTimeUpdate, onDurationChange, poster }, ref) => {
    const internalRef = useRef<HTMLVideoElement>(null);
    const combinedRef = (ref as React.MutableRefObject<HTMLVideoElement>) || internalRef;

    useEffect(() => {
      const video = combinedRef.current;
      if (!video) return;

      const handleTimeUpdate = () => {
        onTimeUpdate(video.currentTime);
      };

      const handleLoadedMetadata = () => {
        onDurationChange(video.duration);
      };

      const handleEnded = () => {
        onTimeUpdate(0);
      };

      video.addEventListener('timeupdate', handleTimeUpdate);
      video.addEventListener('loadedmetadata', handleLoadedMetadata);
      video.addEventListener('ended', handleEnded);

      return () => {
        video.removeEventListener('timeupdate', handleTimeUpdate);
        video.removeEventListener('loadedmetadata', handleLoadedMetadata);
        video.removeEventListener('ended', handleEnded);
      };
    }, [combinedRef, onTimeUpdate, onDurationChange]);

    useEffect(() => {
      const video = combinedRef.current;
      if (!video) return;

      if (Math.abs(video.currentTime - currentTime) > 0.1) {
        video.currentTime = currentTime;
      }
    }, [currentTime, combinedRef]);

    const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    return (
      <div className="preview-player">
        <video
          ref={combinedRef}
          className="preview-video"
          src={src}
          poster={poster}
          playsInline
        />
        {!src && (
          <div className="preview-placeholder">
            <div className="placeholder-icon">🎬</div>
            <p>No media selected</p>
          </div>
        )}
      </div>
    );
  }
);

PreviewPlayer.displayName = 'PreviewPlayer';

export default PreviewPlayer;

/**
 * Video Generation Panel Component
 * 
 * LTX-2 image-to-video generation interface with two-stage progress tracking.
 * 
 * Features:
 * - Input image selector
 * - Prompt input for motion description
 * - Video parameter controls (frame count, frame rate, dimensions)
 * - Two-stage progress display (latent generation + spatial upscaling)
 * - Video preview on completion
 * 
 * Validates: Requirements 14.13, 14.14
 */

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { backendApi, createBackendApi } from '@/services/backendApiService';
import type { TaskStatusResponse, ApiResponse } from '@/services/backendApiService';
import { Play, Square, Loader2, FileVideo, AlertCircle, CheckCircle } from 'lucide-react';

interface VideoGenerationPanelProps {
  onGenerateVideo?: (params: VideoGenerationParams) => Promise<void>;
  onCancel?: () => void;
}

interface VideoGenerationParams {
  inputImagePath: string;
  prompt: string;
  frameCount: number;
  frameRate: number;
  width: number;
  height: number;
}

interface GenerationProgress {
  stage: 'latent' | 'upscaling' | 'complete';
  stageProgress: number;  // 0-100
  overallProgress: number;  // 0-100
  message: string;
}

export const VideoGenerationPanel: React.FC<VideoGenerationPanelProps> = ({
  onGenerateVideo,
  onCancel
}) => {
  const [inputImage, setInputImage] = useState<string>('');
  const [prompt, setPrompt] = useState<string>('');
  const [frameCount, setFrameCount] = useState<number>(121);
  const [frameRate, setFrameRate] = useState<number>(25);
  const [width, setWidth] = useState<number>(1280);
  const [height, setHeight] = useState<number>(720);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [progress, setProgress] = useState<GenerationProgress | null>(null);
  const [generatedVideoPath, setGeneratedVideoPath] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [useComfyUI, setUseComfyUI] = useState<boolean>(true);

  // Polling interval ref for checking task status
  const pollingRef = useRef<NodeJS.Timeout | null>(null);

  // Cleanup polling on unmount
  useEffect(() => {
    return () => {
      if (pollingRef.current) {
        clearInterval(pollingRef.current);
      }
    };
  }, []);

  const handleGenerate = useCallback(async () => {
    if (!inputImage || !prompt) {
      setError('Please provide both input image and prompt');
      return;
    }

    setIsGenerating(true);
    setError(null);
    setProgress({
      stage: 'latent',
      stageProgress: 0,
      overallProgress: 0,
      message: 'Starting video generation...'
    });

    try {
      if (useComfyUI && onGenerateVideo) {
        // Use ComfyUI workflow for video generation
        await onGenerateVideo({
          inputImagePath: inputImage,
          prompt,
          frameCount,
          frameRate,
          width,
          height
        });
      } else {
        // Direct backend API call for LTX-2 video generation
        const response = await backendApi.invokeCliCommand('generate_video_from_image', {
          imagePath: inputImage,
          prompt,
          frameCount,
          frameRate,
          width,
          height
        });

        if (!response.success) {
          throw new Error(response.error || 'Video generation failed');
        }

        // Poll for task status
        if (response.data?.taskId) {
          await pollTaskStatus(response.data.taskId);
        }
      }

      setProgress({
        stage: 'complete',
        stageProgress: 100,
        overallProgress: 100,
        message: 'Video generation complete!'
      });

      // Generate mock video path for preview
      const timestamp = Date.now();
      setGeneratedVideoPath(`/api/video/output_${timestamp}.mp4`);

    } catch (err) {
      console.error('Video generation failed:', err);
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setProgress(null);
    } finally {
      setIsGenerating(false);
    }
  }, [inputImage, prompt, frameCount, frameRate, width, height, onGenerateVideo, useComfyUI]);

  // Poll task status until completion
  const pollTaskStatus = async (taskId: string): Promise<void> => {
    return new Promise((resolve, reject) => {
      pollingRef.current = setInterval(async () => {
        try {
          const response: ApiResponse<TaskStatusResponse> = await backendApi.getTaskStatus(taskId);

          if (!response.success || !response.data) {
            reject(new Error(response.error || 'Failed to get task status'));
            return;
          }

          const status = response.data;
          const stageProgress = Math.min(status.progress, 100);

          if (status.status === 'completed') {
            setProgress({
              stage: 'complete',
              stageProgress: 100,
              overallProgress: 100,
              message: 'Video generation complete!'
            });
            if (status.result?.videoPath) {
              setGeneratedVideoPath(status.result.videoPath);
            }
            clearInterval(pollingRef.current!);
            pollingRef.current = null;
            resolve();
          } else if (status.status === 'failed') {
            clearInterval(pollingRef.current!);
            pollingRef.current = null;
            reject(new Error(status.error || 'Task failed'));
          } else {
            // Still processing
            setProgress({
              stage: 'latent',
              stageProgress: stageProgress,
              overallProgress: stageProgress * 0.8, // 80% for latent
              message: status.message || 'Processing...'
            });
          }
        } catch (err) {
          clearInterval(pollingRef.current!);
          pollingRef.current = null;
          reject(err);
        }
      }, 2000); // Poll every 2 seconds
    });
  };

  const handleCancel = useCallback(() => {
    if (pollingRef.current) {
      clearInterval(pollingRef.current);
      pollingRef.current = null;
    }
    if (onCancel) {
      onCancel();
    }
    setIsGenerating(false);
    setProgress(null);
    setError(null);
  }, [onCancel]);

  const calculateDuration = () => {
    return (frameCount / frameRate).toFixed(2);
  };

  return (
    <div className="video-generation-panel">
      <h2>LTX-2 Image-to-Video Generation</h2>
      
      {/* Input Image Selector */}
      <div className="input-section">
        <label htmlFor="input-image">Input Image:</label>
        <input
          id="input-image"
          type="file"
          accept="image/*"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const filePath = (file as any).webkitRelativePath || (file as any).path || file.name;
              setInputImage(filePath);
            }
          }}
          disabled={isGenerating}
        />
        {inputImage && <p>Selected: {inputImage}</p>}
      </div>

      {/* Prompt Input */}
      <div className="prompt-section">
        <label htmlFor="motion-prompt">Motion Description:</label>
        <textarea
          id="motion-prompt"
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe the motion and scene (e.g., 'A wide, dynamic tracking shot follows a group of mountain bikers...')"
          rows={4}
          disabled={isGenerating}
        />
      </div>

      {/* Video Parameters */}
      <div className="parameters-section">
        <h3>Video Parameters</h3>
        
        <div className="parameter-group">
          <label htmlFor="frame-count">Frame Count:</label>
          <input
            id="frame-count"
            type="number"
            value={frameCount}
            onChange={(e) => setFrameCount(parseInt(e.target.value))}
            min={60}
            max={240}
            disabled={isGenerating}
          />
        </div>

        <div className="parameter-group">
          <label htmlFor="frame-rate">Frame Rate (fps):</label>
          <input
            id="frame-rate"
            type="number"
            value={frameRate}
            onChange={(e) => setFrameRate(parseInt(e.target.value))}
            min={24}
            max={30}
            disabled={isGenerating}
          />
        </div>

        <div className="parameter-group">
          <label htmlFor="width">Width:</label>
          <input
            id="width"
            type="number"
            value={width}
            onChange={(e) => setWidth(parseInt(e.target.value))}
            min={640}
            max={1920}
            step={64}
            disabled={isGenerating}
          />
        </div>

        <div className="parameter-group">
          <label htmlFor="height">Height:</label>
          <input
            id="height"
            type="number"
            value={height}
            onChange={(e) => setHeight(parseInt(e.target.value))}
            min={480}
            max={1080}
            step={64}
            disabled={isGenerating}
          />
        </div>

        <div className="duration-display">
          <strong>Duration:</strong> {calculateDuration()} seconds
        </div>
      </div>

      {/* Progress Display */}
      {progress && (
        <div className="progress-section">
          <h3>Generation Progress</h3>
          
          <div className="stage-indicator">
            <strong>Current Stage:</strong> {
              progress.stage === 'latent' ? 'Latent Video Generation' :
              progress.stage === 'upscaling' ? 'Spatial Upscaling' :
              'Complete'
            }
          </div>

          <div className="progress-bar">
            <div className="progress-label">Stage Progress:</div>
            <div className="progress-track">
              <div 
                className="progress-fill" 
                style={{ width: `${progress.stageProgress}%` }}
              />
            </div>
            <div className="progress-percentage">{progress.stageProgress}%</div>
          </div>

          <div className="progress-bar">
            <div className="progress-label">Overall Progress:</div>
            <div className="progress-track">
              <div 
                className="progress-fill" 
                style={{ width: `${progress.overallProgress}%` }}
              />
            </div>
            <div className="progress-percentage">{progress.overallProgress}%</div>
          </div>

          <div className="progress-message">{progress.message}</div>
        </div>
      )}

      {/* Video Preview */}
      {generatedVideoPath && (
        <div className="preview-section">
          <h3>Generated Video</h3>
          <video 
            src={generatedVideoPath} 
            controls 
            width={width} 
            height={height}
          >
            Your browser does not support the video tag.
          </video>
        </div>
      )}

      {/* Action Buttons */}
      <div className="actions-section">
        <button
          onClick={handleGenerate}
          disabled={isGenerating || !inputImage || !prompt}
          className="generate-button"
        >
          {isGenerating ? 'Generating...' : 'Generate Video'}
        </button>
        
        {isGenerating && (
          <button
            onClick={handleCancel}
            className="cancel-button"
          >
            Cancel
          </button>
        )}
      </div>
    </div>
  );
};

export default VideoGenerationPanel;

/**
 * VirtualShotList - Virtualized shot list for performance with large projects
 * 
 * Uses virtual scrolling to render only visible shots, improving performance
 * with projects containing 100+ shots.
 * 
 * Requirements: 10.2
 */

import React, { useRef, useState, useCallback } from 'react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { CheckCircle, AlertCircle, Circle } from 'lucide-react';
import type { Shot } from '../types/projectDashboard';
import { calculateVisibleItems } from '../utils/performanceOptimizations';

// ============================================================================
// Constants
// ============================================================================

const ITEM_HEIGHT = 100; // Height of each shot item in pixels
const OVERSCAN = 5; // Number of items to render outside viewport

// ============================================================================
// Component Props
// ============================================================================

export interface VirtualShotListProps {
  shots: Shot[];
  selectedShotId: string | null;
  onShotSelect: (shot: Shot) => void;
  getPromptIndicator: (shot: Shot) => {
    icon: React.ComponentType<any>;
    color: string;
    label: string;
    variant: 'default' | 'secondary' | 'outline' | 'destructive';
  };
  containerHeight: number;
  className?: string;
}

// ============================================================================
// Component
// ============================================================================

export const VirtualShotList: React.FC<VirtualShotListProps> = ({
  shots,
  selectedShotId,
  onShotSelect,
  getPromptIndicator,
  containerHeight,
  className = '',
}) => {
  // ============================================================================
  // State
  // ============================================================================

  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // ============================================================================
  // Handlers
  // ============================================================================

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  // ============================================================================
  // Virtual Scrolling Calculation
  // ============================================================================

  const { visibleItems, totalHeight, offsetY } = React.useMemo(() => {
    return calculateVisibleItems(
      shots,
      scrollTop,
      containerHeight,
      ITEM_HEIGHT,
      OVERSCAN
    );
  }, [shots, scrollTop, containerHeight]);

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div
      ref={containerRef}
      className={`virtual-shot-list overflow-auto ${className}`}
      style={{ height: containerHeight }}
      onScroll={handleScroll}
      role="list"
      aria-label="Shot list"
    >
      {/* Spacer for total height */}
      <div style={{ height: totalHeight, position: 'relative' }}>
        {/* Visible items container */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            transform: `translateY(${offsetY}px)`,
          }}
        >
          {visibleItems.map((shot) => {
            const indicator = getPromptIndicator(shot);
            const Icon = indicator.icon;
            const isSelected = selectedShotId === shot.id;

            return (
              <div
                key={shot.id}
                style={{ height: ITEM_HEIGHT }}
                className="px-2 py-1"
              >
                <Button
                  variant={isSelected ? 'default' : 'outline'}
                  className={`w-full justify-start text-left h-full py-3 px-4 ${
                    isSelected ? 'ring-2 ring-primary' : ''
                  }`}
                  onClick={() => onShotSelect(shot)}
                  role="listitem"
                  aria-label={`Shot ${shot.id.slice(0, 8)}, ${indicator.label}, ${shot.startTime} to ${shot.startTime + shot.duration} seconds`}
                  aria-pressed={isSelected}
                >
                  <div className="flex items-start gap-3 w-full">
                    {/* Completion Indicator */}
                    <Icon className={`h-5 w-5 mt-0.5 flex-shrink-0 ${indicator.color}`} aria-hidden="true" />
                    
                    {/* Shot Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2 mb-1">
                        <span className="font-medium text-sm truncate">
                          Shot {shot.id.slice(0, 8)}
                        </span>
                        <Badge variant={indicator.variant} className="text-xs" aria-hidden="true">
                          {indicator.label}
                        </Badge>
                      </div>
                      
                      {/* Shot Metadata */}
                      <div className="text-xs text-muted-foreground space-y-0.5">
                        <div>
                          Time: {shot.startTime}s - {shot.startTime + shot.duration}s
                        </div>
                        {shot.metadata.cameraAngle && (
                          <div>Camera: {shot.metadata.cameraAngle}</div>
                        )}
                      </div>
                      
                      {/* Prompt Preview */}
                      {shot.prompt && (
                        <div className="text-xs text-muted-foreground mt-2 line-clamp-2" aria-label="Prompt preview">
                          {shot.prompt}
                        </div>
                      )}
                    </div>
                  </div>
                </Button>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default VirtualShotList;

/**
 * VoiceGenerationPanel - Configure and trigger voice generation
 * 
 * Provides UI controls for voice generation parameters including voice type,
 * speed, pitch, and preview/generate functionality with loading states.
 * 
 * Requirements: 5.1, 5.4
 */

import React, { useState, useCallback, useEffect, useRef } from 'react';
import type { DialoguePhrase, VoiceParameters } from '../types/projectDashboard';
import { Button } from './ui/button';
import { Label } from './ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './ui/select';
import { Slider } from './ui/slider';
import { generateVoice, estimateAudioDuration } from '../services/voiceGenerationService';

// ============================================================================
// Component Props
// ============================================================================

export interface VoiceGenerationPanelProps {
  phrase: DialoguePhrase;
  onGenerate: (voiceParams: VoiceParameters) => Promise<void>;
  onPreview?: (audioUrl: string) => void;
  isGenerating?: boolean;
  className?: string;
}

// ============================================================================
// Component
// ============================================================================

export const VoiceGenerationPanel: React.FC<VoiceGenerationPanelProps> = ({
  phrase,
  onGenerate,
  onPreview,
  isGenerating: externalIsGenerating = false,
  className = '',
}) => {
  // ============================================================================
  // State
  // ============================================================================

  const [voiceType, setVoiceType] = useState<'male' | 'female' | 'neutral'>(
    phrase.voiceParameters?.voiceType || 'neutral'
  );
  const [speed, setSpeed] = useState<number>(
    phrase.voiceParameters?.speed || 1.0
  );
  const [pitch, setPitch] = useState<number>(
    phrase.voiceParameters?.pitch || 0
  );
  const [language, setLanguage] = useState<string>(
    phrase.voiceParameters?.language || 'en'
  );
  const [isPreviewGenerating, setIsPreviewGenerating] = useState(false);
  const [previewAudioUrl, setPreviewAudioUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // ============================================================================
  // Computed Values
  // ============================================================================

  const isGenerating = externalIsGenerating || isPreviewGenerating;
  const estimatedDuration = estimateAudioDuration(phrase.text, speed);
  const hasGeneratedAudio = !!phrase.generatedAudioUrl;

  // Current voice parameters
  const currentVoiceParams: VoiceParameters = {
    voiceType,
    speed,
    pitch,
    language,
  };

  // ============================================================================
  // Effects
  // ============================================================================

  /**
   * Update local state when phrase voice parameters change
   */
  useEffect(() => {
    if (phrase.voiceParameters) {
      setVoiceType(phrase.voiceParameters.voiceType);
      setSpeed(phrase.voiceParameters.speed);
      setPitch(phrase.voiceParameters.pitch);
      setLanguage(phrase.voiceParameters.language);
    }
  }, [phrase.voiceParameters]);

  /**
   * Cleanup audio URL on unmount
   */
  useEffect(() => {
    return () => {
      if (previewAudioUrl) {
        URL.revokeObjectURL(previewAudioUrl);
      }
    };
  }, [previewAudioUrl]);

  // ============================================================================
  // Event Handlers
  // ============================================================================

  /**
   * Handle voice type change
   */
  const handleVoiceTypeChange = useCallback((value: string) => {
    setVoiceType(value as 'male' | 'female' | 'neutral');
    setError(null);
  }, []);

  /**
   * Handle speed change
   */
  const handleSpeedChange = useCallback((value: number[]) => {
    setSpeed(value[0]);
    setError(null);
  }, []);

  /**
   * Handle pitch change
   */
  const handlePitchChange = useCallback((value: number[]) => {
    setPitch(value[0]);
    setError(null);
  }, []);

  /**
   * Handle language change
   */
  const handleLanguageChange = useCallback((value: string) => {
    setLanguage(value);
    setError(null);
  }, []);

  /**
   * Handle preview button click
   */
  const handlePreview = useCallback(async () => {
    if (!phrase.text || phrase.text.trim().length === 0) {
      setError('Cannot preview: phrase text is empty');
      return;
    }

    try {
      setIsPreviewGenerating(true);
      setError(null);
      setProgress(0);

      // Generate voice with current parameters
      const result = await generateVoice({
        text: phrase.text,
        voiceParams: currentVoiceParams,
        onProgress: setProgress,
      });

      if (result.success && result.audioUrl) {
        // Clean up previous preview audio
        if (previewAudioUrl) {
          URL.revokeObjectURL(previewAudioUrl);
        }

        setPreviewAudioUrl(result.audioUrl);
        
        // Trigger preview callback
        onPreview?.(result.audioUrl);

        // Auto-play preview
        if (audioRef.current) {
          audioRef.current.src = result.audioUrl;
          audioRef.current.play().catch(err => {
            console.warn('Auto-play failed:', err);
          });
        }
      } else {
        setError(result.error || 'Preview generation failed');
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Preview failed';
      setError(errorMessage);
      console.error('Preview error:', err);
    } finally {
      setIsPreviewGenerating(false);
      setProgress(0);
    }
  }, [phrase.text, currentVoiceParams, previewAudioUrl, onPreview]);

  /**
   * Handle generate button click
   */
  const handleGenerate = useCallback(async () => {
    if (!phrase.text || phrase.text.trim().length === 0) {
      setError('Cannot generate: phrase text is empty');
      return;
    }

    try {
      setError(null);
      await onGenerate(currentVoiceParams);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Generation failed';
      setError(errorMessage);
      console.error('Generation error:', err);
    }
  }, [phrase.text, currentVoiceParams, onGenerate]);

  /**
   * Handle stop preview
   */
  const handleStopPreview = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  }, []);

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div className={`voice-generation-panel ${className}`} style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <h3 style={styles.title}>Voice Generation</h3>
        {hasGeneratedAudio && (
          <span style={styles.badge}>Audio Generated</span>
        )}
      </div>

      {/* Phrase Text Display */}
      <div style={styles.textDisplay}>
        <Label>Phrase Text</Label>
        <div style={styles.textContent}>
          {phrase.text || <span style={styles.emptyText}>No text</span>}
        </div>
        <div style={styles.textInfo}>
          <span style={styles.infoLabel}>Estimated Duration:</span>
          <span style={styles.infoValue}>{estimatedDuration}s</span>
        </div>
      </div>

      {/* Voice Type Selection */}
      <div style={styles.field}>
        <Label htmlFor="voice-type">Voice Type</Label>
        <Select
          value={voiceType}
          onValueChange={handleVoiceTypeChange}
          disabled={isGenerating}
        >
          <SelectTrigger id="voice-type">
            <SelectValue placeholder="Select voice type..." />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="male">Male</SelectItem>
            <SelectItem value="female">Female</SelectItem>
            <SelectItem value="neutral">Neutral</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Language Selection */}
      <div style={styles.field}>
        <Label htmlFor="language">Language</Label>
        <Select
          value={language}
          onValueChange={handleLanguageChange}
          disabled={isGenerating}
        >
          <SelectTrigger id="language">
            <SelectValue placeholder="Select language..." />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="en">English</SelectItem>
            <SelectItem value="es">Spanish</SelectItem>
            <SelectItem value="fr">French</SelectItem>
            <SelectItem value="de">German</SelectItem>
            <SelectItem value="it">Italian</SelectItem>
            <SelectItem value="pt">Portuguese</SelectItem>
            <SelectItem value="ja">Japanese</SelectItem>
            <SelectItem value="zh">Chinese</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Speed Slider */}
      <div style={styles.field}>
        <div style={styles.sliderHeader}>
          <Label htmlFor="speed-slider">Speed</Label>
          <span style={styles.sliderValue}>{speed.toFixed(2)}x</span>
        </div>
        <Slider
          id="speed-slider"
          min={0.5}
          max={2.0}
          step={0.1}
          value={[speed]}
          onValueChange={handleSpeedChange}
          disabled={isGenerating}
          aria-label="Speech speed"
        />
        <div style={styles.sliderLabels}>
          <span style={styles.sliderLabel}>0.5x (Slower)</span>
          <span style={styles.sliderLabel}>2.0x (Faster)</span>
        </div>
      </div>

      {/* Pitch Slider */}
      <div style={styles.field}>
        <div style={styles.sliderHeader}>
          <Label htmlFor="pitch-slider">Pitch</Label>
          <span style={styles.sliderValue}>
            {pitch > 0 ? '+' : ''}{pitch} semitones
          </span>
        </div>
        <Slider
          id="pitch-slider"
          min={-12}
          max={12}
          step={1}
          value={[pitch]}
          onValueChange={handlePitchChange}
          disabled={isGenerating}
          aria-label="Voice pitch"
        />
        <div style={styles.sliderLabels}>
          <span style={styles.sliderLabel}>-12 (Lower)</span>
          <span style={styles.sliderLabel}>+12 (Higher)</span>
        </div>
      </div>

      {/* Progress Bar */}
      {isGenerating && progress > 0 && (
        <div style={styles.progressContainer}>
          <div style={styles.progressBar}>
            <div
              style={{
                ...styles.progressFill,
                width: `${progress}%`,
              }}
            />
          </div>
          <span style={styles.progressText}>{progress}%</span>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div style={styles.error} role="alert">
          {error}
        </div>
      )}

      {/* Action Buttons */}
      <div style={styles.actions}>
        <Button
          variant="outline"
          onClick={handlePreview}
          disabled={isGenerating || !phrase.text}
          aria-label="Preview voice"
        >
          {isPreviewGenerating ? 'Generating Preview...' : 'Preview'}
        </Button>
        
        {previewAudioUrl && (
          <Button
            variant="outline"
            onClick={handleStopPreview}
            disabled={isGenerating}
            aria-label="Stop preview"
          >
            Stop Preview
          </Button>
        )}

        <Button
          onClick={handleGenerate}
          disabled={isGenerating || !phrase.text}
          aria-label="Generate voice"
        >
          {externalIsGenerating ? 'Generating...' : 'Generate'}
        </Button>
      </div>

      {/* Hidden Audio Element for Preview */}
      <audio
        ref={audioRef}
        style={{ display: 'none' }}
        controls={false}
        aria-label="Voice preview audio"
      />
    </div>
  );
};

