          type: 'music',
          url: '/audio/music.mp3',
          startTime: 0,
          duration: 5,
          offset: 0,
          volume: 80,
          fadeIn: 0,
          fadeOut: 0,
          pan: 0,
          muted: false,
          solo: false,
          effects: [],
        },
      ],
      effects: [],
      textLayers: [],
      animations: [],
      position: 0,
    },
    {
      id: 'shot-2',
      title: 'Middle Scene',
      description: 'Second shot',
      duration: 8,
      audioTracks: [],
      effects: [],
      textLayers: [],
      animations: [],
      transitionOut: {
        id: 'trans-1',
        type: 'fade',
        duration: 1,
      },
      position: 1,
    },
    {
      id: 'shot-3',
      title: 'Closing Scene',
      description: 'Third shot',
      duration: 6,
      audioTracks: [],
      effects: [],
      textLayers: [],
      animations: [],
      position: 2,
    },
