      render(<Timeline />);
      
      const playButton = screen.getByTitle('Play');
      fireEvent.click(playButton);
      
      expect(mockPlay).toHaveBeenCalledTimes(1);
    });

    it('should show pause button when playing', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 0,
          isPlaying: true,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      expect(screen.getByTitle('Pause')).toBeInTheDocument();
    });

    it('should call pause when pause button is clicked', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 0,
          isPlaying: true,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      const pauseButton = screen.getByTitle('Pause');
      fireEvent.click(pauseButton);
      
      expect(mockPause).toHaveBeenCalledTimes(1);
    });

    it('should skip back 5 seconds when skip back button is clicked', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 10,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      const skipBackButton = screen.getByTitle('Skip back 5s');
      fireEvent.click(skipBackButton);
      
      expect(mockSetCurrentTime).toHaveBeenCalledWith(5);
    });

    it('should skip forward 5 seconds when skip forward button is clicked', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 10,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      const skipForwardButton = screen.getByTitle('Skip forward 5s');
      fireEvent.click(skipForwardButton);
      
      expect(mockSetCurrentTime).toHaveBeenCalledWith(15);
    });

    it('should not skip back below 0', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 2,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      const skipBackButton = screen.getByTitle('Skip back 5s');
      fireEvent.click(skipBackButton);
      
      expect(mockSetCurrentTime).toHaveBeenCalledWith(0);
    });

    it('should not skip forward beyond total duration', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: mockShots,
          currentTime: 18,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      const skipForwardButton = screen.getByTitle('Skip forward 5s');
      fireEvent.click(skipForwardButton);
      
      // Total duration is 20 seconds
      expect(mockSetCurrentTime).toHaveBeenCalledWith(20);
    });
  });

  describe('Shot Selection', () => {
    it('should select shot when clicked', () => {
      render(<Timeline />);
      
      const shotElement = screen.getByText('Opening Scene');
      fireEvent.click(shotElement);
      
      expect(mockSelectShot).toHaveBeenCalledWith('shot-1');
    });
  });

  describe('Duration Calculation', () => {
    it('should calculate total duration correctly', () => {
      render(<Timeline />);
      
      // Total: 5 + 8 + 1 (transition) + 6 = 20 seconds
      expect(screen.getByText('00:20')).toBeInTheDocument();
    });

    it('should handle shots without transitions', () => {
      const shotsWithoutTransitions: Shot[] = [
        {
          id: 'shot-1',
          title: 'Shot 1',
          description: 'First',
          duration: 10,
          audioTracks: [],
          effects: [],
          textLayers: [],
          animations: [],
          position: 0,
        },
        {
          id: 'shot-2',
          title: 'Shot 2',
          description: 'Second',
          duration: 15,
          audioTracks: [],
          effects: [],
          textLayers: [],
          animations: [],
          position: 1,
        },
      ];

      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: shotsWithoutTransitions,
          currentTime: 0,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      // Total: 10 + 15 = 25 seconds
      expect(screen.getByText('00:25')).toBeInTheDocument();
    });
  });

  describe('Empty State', () => {
    it('should render with no shots', () => {
      (useStore as unknown as ReturnType<typeof vi.fn>).mockImplementation((selector: any) => {
        const state = {
          shots: [],
          currentTime: 0,
          isPlaying: false,
          setCurrentTime: mockSetCurrentTime,
          play: mockPlay,
          pause: mockPause,
          selectShot: mockSelectShot,
        };
        return selector(state);
      });
      
      render(<Timeline />);
      
      // Should still show controls and 00:00 duration
      expect(screen.getByTitle('Play')).toBeInTheDocument();
      expect(screen.getByText('00:00')).toBeInTheDocument();
    });
  });
});

/**
 * **Validates: Requirements 4.1, 4.5**
 * 
 * These tests verify that the Timeline component:
 * - Displays all shots in chronological order with duration bars (4.1)
 * - Shows the current time position and total duration (4.5)
 * - Renders transition indicators between shots (4.1)
 * - Provides playback controls for navigation
 * - Calculates total project duration correctly
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { TransitionPanel } from '../TransitionPanel';
import { useStore, useSelectedShot } from '../../store';
import type { Shot, Transition } from '../../types';

// Mock the store
vi.mock('../../store', () => ({
  useStore: vi.fn(),
  useSelectedShot: vi.fn(),
}));

describe('TransitionPanel', () => {
  const mockSetTransition = vi.fn();
  
  const createMockShot = (id: string, title: string, position: number, transitionOut?: Transition): Shot => ({
    id,
    title,
    description: `Description for ${title}`,
    duration: 5,
    position,
    audioTracks: [],
    effects: [],
    textLayers: [],
    animations: [],
    transitionOut,
  });

  const createMockTransition = (overrides?: Partial<Transition>): Transition => ({
    id: 'transition-1',
    type: 'fade',
    duration: 1.0,
    easing: 'ease-in-out',
    ...overrides,
  });

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('No Shot Selected', () => {
    beforeEach(() => {
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(null);
    });

    it('should display "No Shot Selected" message when no shot is selected', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('No Shot Selected')).toBeInTheDocument();
      expect(screen.getByText('Select a shot to manage transitions')).toBeInTheDocument();
    });
  });

  describe('Last Shot', () => {
    beforeEach(() => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);
    });

    it('should display "Last Shot" message when selected shot is the last one', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Last Shot')).toBeInTheDocument();
      expect(screen.getByText('Transitions can only be added between shots')).toBeInTheDocument();
    });
  });

  describe('No Transition State', () => {
    const shot1 = createMockShot('shot-1', 'Opening Scene', 0);
    const shot2 = createMockShot('shot-2', 'Main Action', 1);

    beforeEach(() => {
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);
    });

    it('should display "No Transition" message when shot has no transition', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('No Transition')).toBeInTheDocument();
      expect(screen.getByText('Add a transition to smoothly connect this shot to the next')).toBeInTheDocument();
    });

    it('should display shot titles in the header', () => {
      render(<TransitionPanel />);

      expect(screen.getByText(/Transition from "Opening Scene" to "Main Action"/)).toBeInTheDocument();
    });

    it('should call setTransition with new transition when "Add Transition" is clicked', () => {
      render(<TransitionPanel />);

      const addButton = screen.getByRole('button', { name: /Add Transition/i });
      fireEvent.click(addButton);

      expect(mockSetTransition).toHaveBeenCalledWith(
        'shot-1',
        expect.objectContaining({
          type: 'fade',
          duration: 1.0,
          easing: 'ease-in-out',
        })
      );
    });
  });

  describe('Transition Editor', () => {
    const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition());
    const shot2 = createMockShot('shot-2', 'Shot 2', 1);

    beforeEach(() => {
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);
    });

    it('should display transition settings when shot has a transition', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Transition Settings')).toBeInTheDocument();
      expect(screen.getByText('Active')).toBeInTheDocument();
      expect(screen.getByText('Transition Type')).toBeInTheDocument();
      expect(screen.getByText('Duration')).toBeInTheDocument();
      expect(screen.getByText('Easing Curve')).toBeInTheDocument();
    });

    it('should display current transition duration', () => {
      const shotWithDuration = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ duration: 2.5 }));
      
      vi.mocked(useSelectedShot).mockReturnValue(shotWithDuration);

      render(<TransitionPanel />);

      expect(screen.getByText('2.5s')).toBeInTheDocument();
    });

    it('should call setTransition with undefined when "Remove Transition" is clicked', () => {
      render(<TransitionPanel />);

      const removeButton = screen.getByRole('button', { name: /Remove Transition/i });
      fireEvent.click(removeButton);

      expect(mockSetTransition).toHaveBeenCalledWith('shot-1', undefined);
    });
  });

  describe('Direction Controls', () => {
    it('should display direction controls for "wipe" transition', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'wipe', direction: 'right' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      expect(screen.getByText('Direction')).toBeInTheDocument();
      expect(screen.getByLabelText('Left')).toBeInTheDocument();
      expect(screen.getByLabelText('Right')).toBeInTheDocument();
      expect(screen.getByLabelText('Up')).toBeInTheDocument();
      expect(screen.getByLabelText('Down')).toBeInTheDocument();
    });

    it('should display direction controls for "slide" transition', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'slide', direction: 'left' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      expect(screen.getByText('Direction')).toBeInTheDocument();
    });

    it('should NOT display direction controls for "fade" transition', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'fade' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      expect(screen.queryByText('Direction')).not.toBeInTheDocument();
    });

    it('should NOT display direction controls for "dissolve" transition', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'dissolve' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      expect(screen.queryByText('Direction')).not.toBeInTheDocument();
    });

    it('should update direction when changed', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'wipe', direction: 'right' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      // Click the "Left" direction radio button
      const leftRadio = screen.getByLabelText('Left');
      fireEvent.click(leftRadio);

      expect(mockSetTransition).toHaveBeenCalledWith(
        'shot-1',
        expect.objectContaining({
          direction: 'left',
        })
      );
    });
  });

  describe('Transition Descriptions', () => {
    const transitionTypes: Array<{ type: Transition['type']; description: string }> = [
      { type: 'fade', description: 'Gradually fade from one shot to another' },
      { type: 'dissolve', description: 'Blend shots together with a cross-dissolve' },
      { type: 'wipe', description: 'Wipe across the screen in a direction' },
      { type: 'slide', description: 'Slide the next shot in from a direction' },
      { type: 'zoom', description: 'Zoom in or out between shots' },
      { type: 'custom', description: 'Custom transition with advanced parameters' },
    ];

    transitionTypes.forEach(({ type, description }) => {
      it(`should display correct description for ${type} transition`, () => {
        const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type }));
        const shot2 = createMockShot('shot-2', 'Shot 2', 1);
        
        vi.mocked(useStore).mockImplementation((selector: any) => {
          const state = {
            shots: [shot1, shot2],
            setTransition: mockSetTransition,
          };
          return selector ? selector(state) : state;
        });

        vi.mocked(useSelectedShot).mockReturnValue(shot1);

        render(<TransitionPanel />);
        
        expect(screen.getByText(description)).toBeInTheDocument();
      });
    });
  });

  describe('Transition Preview', () => {
    const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition());
    const shot2 = createMockShot('shot-2', 'Shot 2', 1);

    beforeEach(() => {
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);
    });

    it('should display transition preview section when transition exists', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Preview')).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /Play Preview/i })).toBeInTheDocument();
    });

    it('should display "Play Preview" button in initial state', () => {
      render(<TransitionPanel />);

      const playButton = screen.getByRole('button', { name: /Play Preview/i });
      expect(playButton).toBeInTheDocument();
      expect(playButton).not.toBeDisabled();
    });

    it('should display preview container with gradient backgrounds', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Shot 1')).toBeInTheDocument();
      expect(screen.getByText('Shot 2')).toBeInTheDocument();
    });

    it('should display preview help text', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Click "Play Preview" to see how the transition will look')).toBeInTheDocument();
    });

    it('should disable play button when playing', () => {
      render(<TransitionPanel />);

      const playButton = screen.getByRole('button', { name: /Play Preview/i });
      fireEvent.click(playButton);

      // Button should show "Playing..." and be disabled
      expect(screen.getByRole('button', { name: /Playing.../i })).toBeDisabled();
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { WaveformDisplay, generateWaveformData } from '../WaveformDisplay';
import type { AudioTrack } from '../../types';

// Mock AudioContext
class MockAudioContext {
  decodeAudioData = vi.fn();
  close = vi.fn().mockResolvedValue(undefined);
}

class MockAudioBuffer {
  length = 44100;
  numberOfChannels = 2;
  sampleRate = 44100;
  duration = 1;
  
  getChannelData(channel: number): Float32Array {
    // Return mock audio data (sine wave)
    const data = new Float32Array(this.length);
    for (let i = 0; i < this.length; i++) {
      data[i] = Math.sin((i / this.length) * Math.PI * 2) * 0.5;
    }
    return data;
  }
  
  copyFromChannel = vi.fn();
  copyToChannel = vi.fn();
}

describe('WaveformDisplay', () => {
  let mockAudioContext: MockAudioContext;
  let originalAudioContext: any;

  beforeEach(() => {
    mockAudioContext = new MockAudioContext();
    originalAudioContext = (window as any).AudioContext;
    (window as any).AudioContext = vi.fn(() => mockAudioContext);
    
    // Mock fetch
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      arrayBuffer: () => Promise.resolve(new ArrayBuffer(8)),
    });
    
    // Mock decodeAudioData to return mock audio buffer
    mockAudioContext.decodeAudioData.mockResolvedValue(new MockAudioBuffer());
  });

  afterEach(() => {
    (window as any).AudioContext = originalAudioContext;
    vi.clearAllMocks();
  });

  const createMockTrack = (overrides?: Partial<AudioTrack>): AudioTrack => ({
    id: 'track-1',
    name: 'Test Track',
    type: 'music',
    url: 'https://example.com/audio.mp3',
    startTime: 0,
    duration: 10,
    offset: 0,
    volume: 80,
    fadeIn: 0,
    fadeOut: 0,
    pan: 0,
    muted: false,
    solo: false,
    effects: [],
    ...overrides,
  });

  it('renders canvas element', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} />);
    
    const canvas = screen.getByRole('img', { hidden: true }) || document.querySelector('canvas');
    expect(canvas).toBeTruthy();
  });

  it('uses provided width and height', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} width={400} height={80} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas?.width).toBe(400);
    expect(canvas?.height).toBe(80);
  });

  it('uses default width and height when not provided', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas?.width).toBe(300);
    expect(canvas?.height).toBe(60);
  });

  it('displays placeholder when no URL or waveform data', () => {
    const track = createMockTrack({ url: '', waveformData: undefined });
    render(<WaveformDisplay track={track} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas).toBeTruthy();
  });

  it('generates waveform when URL is provided', async () => {
    const track = createMockTrack();
    const onGenerate = vi.fn();
    
    render(<WaveformDisplay track={track} onGenerate={onGenerate} />);
    
    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalledWith(track.url);
    });
    
    await waitFor(() => {
      expect(mockAudioContext.decodeAudioData).toHaveBeenCalled();
    });
    
    await waitFor(() => {
      expect(onGenerate).toHaveBeenCalled();
    });
  });

  it('uses existing waveform data when available', () => {
    const waveformData = [0.1, 0.5, 0.8, 0.3, 0.6];
    const track = createMockTrack({ waveformData });
    
    render(<WaveformDisplay track={track} />);
    
    // Should not fetch audio file
    expect(global.fetch).not.toHaveBeenCalled();
  });

  it('displays loading state while generating', async () => {
    const track = createMockTrack();
    
    // Make decodeAudioData take time
    mockAudioContext.decodeAudioData.mockImplementation(
      () => new Promise((resolve) => setTimeout(() => resolve(new MockAudioBuffer()), 100))
    );
    
    render(<WaveformDisplay track={track} />);
    
    // Should show loading state
    await waitFor(() => {
      expect(screen.getByText(/generating waveform/i)).toBeTruthy();
    });
  });

  it('displays error when fetch fails', async () => {
    const track = createMockTrack();
    
    // Mock fetch to fail
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
    });
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(screen.getByText(/failed to generate waveform/i)).toBeTruthy();
    });
  });

  it('displays error when audio decoding fails', async () => {
    const track = createMockTrack();
    
    // Mock decodeAudioData to fail
    mockAudioContext.decodeAudioData.mockRejectedValue(new Error('Decode error'));
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(screen.getByText(/failed to generate waveform/i)).toBeTruthy();
    });
  });

  it('calls onGenerate callback with waveform data', async () => {
    const track = createMockTrack();
    const onGenerate = vi.fn();
    
    render(<WaveformDisplay track={track} onGenerate={onGenerate} />);
    
    await waitFor(() => {
      expect(onGenerate).toHaveBeenCalled();
    });
    
    const waveformData = onGenerate.mock.calls[0][0];
    expect(Array.isArray(waveformData)).toBe(true);
    expect(waveformData.length).toBeGreaterThan(0);
    expect(waveformData.every((v: number) => v >= 0 && v <= 1)).toBe(true);
  });

  it('closes audio context after generating waveform', async () => {
    const track = createMockTrack();
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(mockAudioContext.close).toHaveBeenCalled();
    });
  });
});

describe('generateWaveformData', () => {
  let mockAudioContext: MockAudioContext;
  let originalAudioContext: any;

  beforeEach(() => {
    mockAudioContext = new MockAudioContext();
    originalAudioContext = (window as any).AudioContext;
    (window as any).AudioContext = vi.fn(() => mockAudioContext);
    
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      arrayBuffer: () => Promise.resolve(new ArrayBuffer(8)),
    });
    
    mockAudioContext.decodeAudioData.mockResolvedValue(new MockAudioBuffer());
  });

  afterEach(() => {
    (window as any).AudioContext = originalAudioContext;
    vi.clearAllMocks();
  });

  it('generates waveform data from audio URL', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl, 100);
    
    expect(Array.isArray(waveformData)).toBe(true);
    expect(waveformData.length).toBe(100);
    expect(waveformData.every((v) => v >= 0 && v <= 1)).toBe(true);
  });

  it('normalizes waveform data to 0-1 range', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl);
    
    const max = Math.max(...waveformData);
    expect(max).toBeLessThanOrEqual(1);
    expect(max).toBeGreaterThan(0);
  });

  it('uses default sample count when not provided', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl);
    
    expect(waveformData.length).toBe(1000);
  });

  it('throws error when fetch fails', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
    });
    
    const audioUrl = 'https://example.com/audio.mp3';
    
    await expect(generateWaveformData(audioUrl)).rejects.toThrow();
  });

  it('closes audio context even when error occurs', async () => {
    mockAudioContext.decodeAudioData.mockRejectedValue(new Error('Decode error'));
    
    const audioUrl = 'https://example.com/audio.mp3';
    
    try {
      await generateWaveformData(audioUrl);
    } catch (error) {
      // Expected to throw
    }
    
    expect(mockAudioContext.close).toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  FocusTrap,
  SkipLink,
  LiveRegion,
  AlertRegion,
  AnnouncementProvider,
  useAnnouncements,
  KeyboardShortcuts,
  AccessibleDialog,
  AccessibleTabs,
  Tooltip,
  HighContrastMode,
  ReducedMotion,
} from '../index';

// Test component for AnnouncementProvider
function TestAnnouncementComponent() {
  const { announce } = useAnnouncements();
  return (
    <div>
      <button onClick={() => announce('Test announcement')}>Announce</button>
      <button onClick={() => announce('Urgent announcement', 'assertive')}>Announce Urgent</button>
    </div>
  );
}

describe('Accessibility Components', () => {
  describe('FocusTrap', () => {
