      );

      expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
    });

    it('should have proper ARIA attributes', () => {
      render(
        <AccessibleDialog
          isOpen={true}
          onClose={() => {}}
          title="Test Dialog"
          description="Dialog description"
        >
