/**
 * AnimatedFeedback Component
 * 
 * Provides animated visual feedback for success and error states.
 * Includes checkmark animations, highlight effects, and shake animations.
 * 
 * Validates: Requirements 11.1, 11.2, 11.3
 */

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Check, X, AlertCircle, Info } from 'lucide-react';
import { successVariants, errorVariants, fadeVariants } from '../../config/animations';
import { useAnimationConfig } from './AnimationProvider';

export type FeedbackType = 'success' | 'error' | 'warning' | 'info';

interface AnimatedFeedbackProps {
  type: FeedbackType;
  message?: string;
  duration?: number;
  onComplete?: () => void;
  className?: string;
}

/**
 * Animated feedback component with icon and message
 * 
 * Validates: Requirements 11.2 (success), 11.3 (error)
 */
export function AnimatedFeedback({
  type,
  message,
  duration = 3000,
  onComplete,
  className = '',
}: AnimatedFeedbackProps) {
  const { isAnimationEnabled } = useAnimationConfig();
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    if (duration > 0) {
      const timer = setTimeout(() => {
        setIsVisible(false);
        onComplete?.();
      }, duration);

      return () => clearTimeout(timer);
    }
  }, [duration, onComplete]);

  const getIcon = () => {
    switch (type) {
      case 'success':
        return <Check className="w-5 h-5" />;
      case 'error':
        return <X className="w-5 h-5" />;
      case 'warning':
        return <AlertCircle className="w-5 h-5" />;
      case 'info':
        return <Info className="w-5 h-5" />;
    }
  };

  const getColorClasses = () => {
    switch (type) {
      case 'success':
        return 'bg-green-50 text-green-800 border-green-200';
      case 'error':
        return 'bg-red-50 text-red-800 border-red-200';
      case 'warning':
        return 'bg-yellow-50 text-yellow-800 border-yellow-200';
      case 'info':
        return 'bg-blue-50 text-blue-800 border-blue-200';
    }
  };

  const getVariants = () => {
    if (!isAnimationEnabled) {
      return fadeVariants;
    }
    return type === 'error' ? errorVariants : successVariants;
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          variants={getVariants()}
          initial="initial"
          animate="animate"
          exit="exit"
          className={`flex items-center gap-2 px-4 py-3 rounded-lg border ${getColorClasses()} ${className}`}
        >
          <span className="flex-shrink-0">{getIcon()}</span>
          {message && <span className="text-sm font-medium">{message}</span>}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

/**
 * Success highlight animation wrapper
 * Wraps content with a subtle success highlight animation
 * 
 * Validates: Requirements 11.2
 */
export function SuccessHighlight({
  children,
  trigger,
  className = '',
}: {
  children: React.ReactNode;
  trigger: boolean;
  className?: string;
}) {
  const { isAnimationEnabled } = useAnimationConfig();
  const [key, setKey] = useState(0);

  useEffect(() => {
    if (trigger) {
      setKey((prev) => prev + 1);
    }
  }, [trigger]);

  if (!isAnimationEnabled) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      key={key}
      variants={successVariants}
      initial="initial"
      animate={trigger ? 'animate' : 'initial'}
      className={className}
    >
      {children}
    </motion.div>
  );
}

/**
 * Error shake animation wrapper
 * Wraps content with a shake animation for errors
 * 
 * Validates: Requirements 11.3
 */
export function ErrorShake({
  children,
  trigger,
  className = '',
}: {
  children: React.ReactNode;
  trigger: boolean;
  className?: string;
}) {
  const { isAnimationEnabled } = useAnimationConfig();
  const [key, setKey] = useState(0);

  useEffect(() => {
    if (trigger) {
      setKey((prev) => prev + 1);
    }
  }, [trigger]);

  if (!isAnimationEnabled) {
    return <div className={className}>{children}</div>;
  }

  return (
    <motion.div
      key={key}
      variants={errorVariants}
      initial="initial"
      animate={trigger ? 'animate' : 'initial'}
      className={className}
    >
      {children}
    </motion.div>
  );
}

/**
 * Inline success checkmark animation
 * 
 * Validates: Requirements 11.2
 */
export function SuccessCheckmark({ className = '' }: { className?: string }) {
  const { isAnimationEnabled } = useAnimationConfig();

  return (
    <motion.div
      initial={{ scale: 0, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={{
        duration: isAnimationEnabled ? 0.3 : 0,
        ease: 'easeOut',
      }}
      className={`inline-flex items-center justify-center w-6 h-6 rounded-full bg-green-500 text-white ${className}`}
    >
      <Check className="w-4 h-4" />
    </motion.div>
  );
}

/**
 * Inline error icon animation
 * 
 * Validates: Requirements 11.3
 */
export function ErrorIcon({ className = '' }: { className?: string }) {
  const { isAnimationEnabled } = useAnimationConfig();

  return (
    <motion.div
      variants={errorVariants}
      initial="initial"
      animate="animate"
      className={`inline-flex items-center justify-center w-6 h-6 rounded-full bg-red-500 text-white ${className}`}
    >
      <X className="w-4 h-4" />
    </motion.div>
  );
}

/**
 * AnimationProvider Component
 * 
 * Provides animation configuration context to the entire application.
 * Handles prefers-reduced-motion and allows for global animation control.
 * 
 * Validates: Requirements 11.4, 11.7
 */

import React, { createContext, useContext, ReactNode } from 'react';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import { ANIMATION_DURATIONS } from '../../config/animations';

interface AnimationConfig {
  prefersReducedMotion: boolean;
  durations: typeof ANIMATION_DURATIONS;
  isAnimationEnabled: boolean;
}

const AnimationContext = createContext<AnimationConfig | undefined>(undefined);

interface AnimationProviderProps {
  children: ReactNode;
  disableAnimations?: boolean;
}

/**
 * Provider component for animation configuration
 */
export function AnimationProvider({ 
  children, 
  disableAnimations = false 
}: AnimationProviderProps) {
  const prefersReducedMotion = useReducedMotion();
  
  const config: AnimationConfig = {
    prefersReducedMotion,
    durations: ANIMATION_DURATIONS,
    isAnimationEnabled: !disableAnimations && !prefersReducedMotion,
  };

  return (
    <AnimationContext.Provider value={config}>
      {children}
    </AnimationContext.Provider>
  );
}

/**
 * Hook to access animation configuration
 * 
 * @returns Animation configuration object
 * 
 * @example
 * ```tsx
 * const { isAnimationEnabled, prefersReducedMotion } = useAnimationConfig();
 * 
 * if (!isAnimationEnabled) {
 *   return <div>Static content</div>;
 * }
 * ```
 */
export function useAnimationConfig(): AnimationConfig {
  const context = useContext(AnimationContext);
  
  if (context === undefined) {
    throw new Error('useAnimationConfig must be used within AnimationProvider');
  }
  
  return context;
}

/**
 * HOC to wrap components with animation configuration
 */
export function withAnimation<P extends object>(
  Component: React.ComponentType<P>
): React.FC<P> {
  return function AnimatedComponent(props: P) {
    return (
      <AnimationProvider>
        <Component {...props} />
      </AnimationProvider>
    );
  };
}

import React, { useState, useEffect } from 'react';
import { ProjectTemplate } from '../../../types/asset-integration';
import { ProjectTemplateService } from '../../../services/asset-integration';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Loader2, Plus } from 'lucide-react';

interface TemplateSelectorProps {
  selectedTemplate: ProjectTemplate | null;
  onTemplateSelect: (template: ProjectTemplate) => void;
  onNewTemplate: () => void;
}

export const TemplateSelector: React.FC<TemplateSelectorProps> = ({
  selectedTemplate,
  onTemplateSelect,
  onNewTemplate,
}) => {
  const [templates, setTemplates] = useState<ProjectTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const service = ProjectTemplateService.getInstance();

  useEffect(() => {
    loadTemplates();
  }, []);

  const loadTemplates = async () => {
    try {
      setLoading(true);
      const templatePaths = await service.listAvailableTemplates();
      const loadedTemplates = await Promise.all(
        templatePaths.map(path => service.loadProjectTemplate(path))
      );
      setTemplates(loadedTemplates);
      setError(null);
    } catch (err) {
      setError(`Failed to load templates: ${err instanceof Error ? err.message : 'Unknown error'}`);
    } finally {
      setLoading(false);
    }
  };

  const handleTemplateChange = (templateId: string) => {
    const template = templates.find(t => t.project.id === templateId);
    if (template) {
      onTemplateSelect(template);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center space-x-2">
        <Loader2 className="h-4 w-4 animate-spin" />
        <span>Loading templates...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-red-500 text-sm">
        {error}
        <Button
          variant="link"
          size="sm"
          onClick={loadTemplates}
          className="ml-2 p-0 h-auto"
        >
          Retry
        </Button>
      </div>
    );
  }

  return (
    <div className="flex items-center space-x-2">
      <Select
        value={selectedTemplate?.project.id || ''}
        onValueChange={handleTemplateChange}
      >
        <SelectTrigger className="w-64">
          <SelectValue placeholder="Select a template" />
        </SelectTrigger>
        <SelectContent>
          {templates.map(template => (
            <SelectItem key={template.project.id} value={template.project.id}>
              {template.project.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Button variant="outline" size="sm" onClick={onNewTemplate}>
        <Plus className="h-4 w-4 mr-1" />
        New
      </Button>
    </div>
  );
};

/**
 * Asset Browser Component
 * 
 * Displays the prompt library assets in a browsable interface
 * Allows filtering by category and searching
 */

import React, { useState, useMemo } from 'react';
import { usePromptLibrary } from '@/hooks/usePromptLibrary';
import { PromptTemplate } from '@/library/PromptLibraryService';
import { Search, Loader2, AlertCircle, Folder, Tag } from 'lucide-react';

// ============================================================================
// Types
// ============================================================================

interface AssetBrowserProps {
  onSelectAsset?: (asset: PromptTemplate) => void;
  selectedAssetId?: string;
  filterCategories?: string[];
  className?: string;
}

// ============================================================================
// Category Display Names
// ============================================================================

const CATEGORY_NAMES: Record<string, string> = {
  '01-master-coherence': '🎨 Master Coherence',
  '02-genres': '🎬 Genres',
  '03-shot-types': '📹 Shot Types',
  '04-lighting': '💡 Lighting',
  '05-scene-elements': '🏗️ Scene Elements',
  '06-visual-styles': '🖼️ Visual Styles',
  '07-camera-angles': '📐 Camera Angles',
  '08-camera-movements': '🎥 Camera Movements',
  '09-mood-atmosphere': '🌟 Mood & Atmosphere',
  '10-time-of-day': '🌅 Time of Day',
  '11-transitions': '🔄 Transitions',
  '12-color-palettes': '🎨 Color Palettes',
  '13-universe-types': '🌍 Universe Types',
  '14-character-archetypes': '👤 Character Archetypes',
};

// ============================================================================
// Component
// ============================================================================

export function AssetBrowser({
  onSelectAsset,
  selectedAssetId,
  filterCategories,
  className = '',
}: AssetBrowserProps) {
  const {
    isLoading,
    error,
    categories,
    totalPrompts,
    search,
  } = usePromptLibrary();

  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<PromptTemplate[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Filter categories if specified
  const availableCategories = useMemo(() => {
    const cats = Object.keys(categories);
    if (filterCategories && filterCategories.length > 0) {
      return cats.filter(cat => filterCategories.includes(cat));
    }
    return cats;
  }, [categories, filterCategories]);

  // Handle search
  const handleSearch = async (query: string) => {
    setSearchQuery(query);

    if (!query.trim()) {
      setSearchResults([]);
      return;
    }

    try {
      setIsSearching(true);
      const results = await search(query);
      setSearchResults(results);
    } catch (err) {
      console.error('Search failed:', err);
    } finally {
      setIsSearching(false);
    }
  };

  // Handle category selection
  const handleCategoryClick = (categoryId: string) => {
    setSelectedCategory(categoryId === selectedCategory ? null : categoryId);
    setSearchQuery('');
    setSearchResults([]);
  };

  // Handle asset selection
  const handleAssetClick = (asset: PromptTemplate) => {
    onSelectAsset?.(asset);
  };

  // Get assets to display
  const displayAssets = useMemo(() => {
    if (searchQuery && searchResults.length > 0) {
      return searchResults;
    }

    if (selectedCategory && categories[selectedCategory]) {
      // Would need to load category prompts here
      return [];
    }

    return [];
  }, [searchQuery, searchResults, selectedCategory, categories]);

  // Loading state
  if (isLoading) {
    return (
      <div className={`asset-browser flex items-center justify-center p-8 ${className}`}>
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin mx-auto mb-2 text-blue-500" />
          <p className="text-sm text-gray-600">Loading asset library...</p>
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className={`asset-browser flex items-center justify-center p-8 ${className}`}>
        <div className="text-center text-red-600">
          <AlertCircle className="h-8 w-8 mx-auto mb-2" />
          <p className="text-sm font-medium">Failed to load assets</p>
          <p className="text-xs mt-1">{error.message}</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`asset-browser flex flex-col h-full bg-white dark:bg-gray-900 ${className}`}>
      {/* Header */}
      <div className="p-4 border-b dark:border-gray-700">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-lg font-semibold">Asset Library</h3>
          <span className="text-xs text-gray-500">{totalPrompts} assets</span>
        </div>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search assets..."
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-800 dark:border-gray-700"
          />
          {isSearching && (
            <Loader2 className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 animate-spin text-gray-400" />
          )}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {searchQuery && searchResults.length > 0 ? (
          /* Search Results */
          <div className="p-4 space-y-2">
            <p className="text-sm text-gray-600 mb-3">
              {searchResults.length} result{searchResults.length !== 1 ? 's' : ''}
            </p>
            {searchResults.map((asset) => (
              <AssetCard
                key={asset.id}
                asset={asset}
                isSelected={asset.id === selectedAssetId}
                onClick={() => handleAssetClick(asset)}
              />
            ))}
          </div>
        ) : searchQuery && !isSearching ? (
          /* No Results */
          <div className="flex items-center justify-center p-8 text-gray-500">
            <div className="text-center">
              <Search className="h-8 w-8 mx-auto mb-2 opacity-50" />
              <p className="text-sm">No assets found</p>
            </div>
          </div>
        ) : (
          /* Category List */
          <div className="p-4 space-y-2">
            {availableCategories.map((categoryId) => (
              <CategoryItem
                key={categoryId}
                categoryId={categoryId}
                category={categories[categoryId]}
                isSelected={categoryId === selectedCategory}
                onClick={() => handleCategoryClick(categoryId)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// Category Item Component
// ============================================================================

interface CategoryItemProps {
  categoryId: string;
  category: any;
  isSelected: boolean;
  onClick: () => void;
}

function CategoryItem({ categoryId, category, isSelected, onClick }: CategoryItemProps) {
  const displayName = CATEGORY_NAMES[categoryId] || categoryId;
  const promptCount = category?.prompts?.length || 0;

  return (
    <button
      onClick={onClick}
      className={`
        w-full p-3 rounded-lg border text-left transition-all
        ${isSelected
          ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
          : 'border-gray-200 dark:border-gray-700 hover:border-blue-300 hover:bg-gray-50 dark:hover:bg-gray-800'
        }
      `}
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Folder className="h-4 w-4 text-gray-400" />
          <span className="font-medium text-sm">{displayName}</span>
        </div>
        <span className="text-xs text-gray-500">{promptCount}</span>
      </div>
      {category?.description && (
        <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 ml-6">
          {category.description}
        </p>
      )}
    </button>
  );
}

// ============================================================================
// Asset Card Component
// ============================================================================

interface AssetCardProps {
  asset: PromptTemplate;
  isSelected: boolean;
  onClick: () => void;
}

function AssetCard({ asset, isSelected, onClick }: AssetCardProps) {
  return (
    <button
      onClick={onClick}
      className={`
        w-full p-3 rounded-lg border text-left transition-all
        ${isSelected
          ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
          : 'border-gray-200 dark:border-gray-700 hover:border-blue-300 hover:bg-gray-50 dark:hover:bg-gray-800'
        }
      `}
    >
      <div className="flex items-start justify-between mb-2">
        <h4 className="font-medium text-sm">{asset.name}</h4>
        {isSelected && (
          <svg className="w-5 h-5 text-blue-500 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
          </svg>
        )}
      </div>

      <p className="text-xs text-gray-600 dark:text-gray-400 mb-2">
        {asset.description}
      </p>

      {asset.tags && asset.tags.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {asset.tags.slice(0, 3).map((tag, index) => (
            <span
              key={index}
              className="inline-flex items-center gap-1 px-2 py-0.5 bg-gray-100 dark:bg-gray-800 rounded text-xs"
            >
              <Tag className="h-3 w-3" />
              {tag}
            </span>
          ))}
          {asset.tags.length > 3 && (
            <span className="text-xs text-gray-500">+{asset.tags.length - 3}</span>
          )}
        </div>
      )}
    </button>
  );
}

/**
 * AssetDropZone Component
 * Provides drag-and-drop functionality for asset import
 * Requirements: 10.1, 10.2, 10.3, 10.4, 10.5
 */

import { useState, useCallback, DragEvent, ReactNode } from 'react';
import { AssetService } from '@/services/asset/AssetService';
import type { ImportResult } from '@/types/asset';
import { useToast } from '../../hooks/use-toast';
import { UploadCloudIcon } from 'lucide-react';

export interface AssetDropZoneProps {
  projectPath: string;
  onDrop?: (files: File[]) => void;
  onImportComplete?: (results: ImportResult[]) => void;
  children: ReactNode;
  className?: string;
  disabled?: boolean;
}

export function AssetDropZone({
  projectPath,
  onDrop,
  onImportComplete,
  children,
  className = '',
  disabled = false,
}: AssetDropZoneProps) {
  const [isDragOver, setIsDragOver] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const { toast } = useToast();
  const assetService = new AssetService();

  // Supported file extensions
  const SUPPORTED_EXTENSIONS = ['.png', '.jpg', '.jpeg', '.mp3', '.wav', '.mp4', '.mov'];

  /**
   * Validates if files are droppable (supported types)
   */
  const validateFiles = useCallback((files: File[]): { valid: File[]; invalid: File[] } => {
    const valid: File[] = [];
    const invalid: File[] = [];

    files.forEach((file) => {
      const extension = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
      if (SUPPORTED_EXTENSIONS.includes(extension)) {
        valid.push(file);
      } else {
        invalid.push(file);
      }
    });

    return { valid, invalid };
  }, []);

  /**
   * Handles drag enter event
   * Requirements: 10.1
   */
  const handleDragEnter = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    if (disabled) return;

    // Check if dragged items contain files
    if (e.dataTransfer.types.includes('Files')) {
      setIsDragOver(true);
    }
  }, [disabled]);

  /**
   * Handles drag over event
   * Requirements: 10.1, 10.4
   */
  const handleDragOver = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    if (disabled) {
      e.dataTransfer.dropEffect = 'none';
      return;
    }

    // Set drop effect to copy
    e.dataTransfer.dropEffect = 'copy';
  }, [disabled]);

  /**
   * Handles drag leave event
   */
  const handleDragLeave = useCallback((e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();

    // Only set isDragOver to false if we're leaving the drop zone entirely
    // (not just moving between child elements)
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX;
    const y = e.clientY;

    if (
      x <= rect.left ||
      x >= rect.right ||
      y <= rect.top ||
      y >= rect.bottom
    ) {
      setIsDragOver(false);
    }
  }, []);

  /**
   * Handles drop event
   * Requirements: 10.2, 10.3
   */
  const handleDrop = useCallback(async (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);

    if (disabled) return;

    // Get dropped files
    const droppedFiles = Array.from(e.dataTransfer.files);
    if (droppedFiles.length === 0) return;

    // Validate files
    const { valid, invalid } = validateFiles(droppedFiles);

    // Show warning for invalid files
    if (invalid.length > 0) {
      toast({
        title: 'Unsupported Files',
        description: `${invalid.length} file${invalid.length > 1 ? 's' : ''} skipped. Supported formats: PNG, JPG, JPEG, MP3, WAV, MP4, MOV`,
        variant: 'destructive',
      });
    }

    // If no valid files, return
    if (valid.length === 0) return;

    // Notify parent about dropped files
    if (onDrop) {
      onDrop(valid);
    }

    // Import files using AssetService
    setIsImporting(true);
    try {
      const results = await assetService.importAssets(
        valid,
        projectPath,
        (current, total, filename) => {
          // Progress tracking could be shown in a toast or progress indicator
          ;
        }
      );

      // Count successes and failures
      const successCount = results.filter((r) => r.success).length;
      const failureCount = results.filter((r) => !r.success).length;

      // Show success notification
      if (successCount > 0) {
        toast({
          title: 'Import Successful',
          description: `Successfully imported ${successCount} asset${successCount > 1 ? 's' : ''}`,
          variant: 'default',
        });
      }

      // Show error notification for failures
      if (failureCount > 0) {
        toast({
          title: 'Import Errors',
          description: `Failed to import ${failureCount} file${failureCount > 1 ? 's' : ''}`,
          variant: 'destructive',
        });
      }

      // Notify parent component
      if (onImportComplete) {
        onImportComplete(results);
      }
    } catch (error) {
      toast({
        title: 'Import Failed',
        description: error instanceof Error ? error.message : 'An unknown error occurred',
        variant: 'destructive',
      });
    } finally {
      setIsImporting(false);
    }
  }, [disabled, projectPath, validateFiles, onDrop, onImportComplete, assetService, toast]);

  return (
    <div
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`relative ${className}`}
      style={{ cursor: disabled ? 'not-allowed' : 'default' }}
    >
      {/* Visual feedback overlay when dragging over */}
      {isDragOver && !disabled && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-primary/10 backdrop-blur-sm border-2 border-dashed border-primary rounded-lg">
          <div className="flex flex-col items-center gap-2 text-primary">
            <UploadCloudIcon className="h-12 w-12" />
            <p className="text-lg font-semibold">Drop files to import</p>
            <p className="text-sm text-muted-foreground">
              Supported: PNG, JPG, JPEG, MP3, WAV, MP4, MOV
            </p>
          </div>
        </div>
      )}

      {/* Loading overlay when importing */}
      {isImporting && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm">
          <div className="flex flex-col items-center gap-2">
            <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
            <p className="text-sm font-medium">Importing assets...</p>
          </div>
        </div>
      )}

      {/* Children content */}
      {children}
    </div>
  );
}

/**
 * AssetImportButton Component
 * Provides a button to trigger file picker for asset import
 * Requirements: 9.1, 9.2
 */

import { useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { UploadIcon, CheckCircle2Icon, XCircleIcon } from 'lucide-react';
import { AssetService } from '@/services/assets/AssetService';
import type { ImportResult } from '@/types/asset';
import { Progress } from '@/components/ui/progress';
import { useToast } from '@/hooks/use-toast';

export interface AssetImportButtonProps {
  projectPath: string;
  onImportComplete?: (results: ImportResult[]) => void;
  variant?: 'default' | 'outline' | 'ghost';
  size?: 'default' | 'sm' | 'lg' | 'icon';
  className?: string;
}

export function AssetImportButton({
  projectPath,
  onImportComplete,
  variant = 'default',
  size = 'default',
  className,
}: AssetImportButtonProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0, filename: '' });
  const { toast } = useToast();
  const assetService = new AssetService();

  const handleButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setIsImporting(true);
    setProgress({ current: 0, total: files.length, filename: '' });

    try {
      // Import assets with progress tracking
      const results = await assetService.importAssets(
        Array.from(files),
        projectPath,
        (current, total, filename) => {
          setProgress({ current, total, filename });
        }
      );

      // Count successes and failures
      const successCount = results.filter((r) => r.success).length;
      const failureCount = results.filter((r) => !r.success).length;

      // Show success notification
      if (successCount > 0) {
        toast({
          title: 'Import Successful',
          description: `Successfully imported ${successCount} asset${successCount > 1 ? 's' : ''}`,
          variant: 'default',
        });
      }

      // Show error notification for failures
      if (failureCount > 0) {
        const failedFiles = results
          .filter((r) => !r.success)
          .map((r, i) => `${files[i].name}: ${r.error}`)
          .join('\n');

        toast({
          title: 'Import Errors',
          description: `Failed to import ${failureCount} file${failureCount > 1 ? 's' : ''}:\n${failedFiles}`,
          variant: 'destructive',
        });
      }

      // Notify parent component
      if (onImportComplete) {
        onImportComplete(results);
      }
    } catch (error) {
      toast({
        title: 'Import Failed',
        description: error instanceof Error ? error.message : 'An unknown error occurred',
        variant: 'destructive',
      });
    } finally {
      setIsImporting(false);
      setProgress({ current: 0, total: 0, filename: '' });

      // Reset file input
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  return (
    <div className={className}>
      <Button
        onClick={handleButtonClick}
        disabled={isImporting}
        variant={variant}
        size={size}
        className="gap-2"
      >
        {isImporting ? (
          <>
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
            Importing...
          </>
        ) : (
          <>
            <UploadIcon className="h-4 w-4" />
            Import Assets
          </>
        )}
      </Button>

      {/* Progress indicator */}
      {isImporting && progress.total > 0 && (
        <div className="mt-2 space-y-1">
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">
              {progress.current} / {progress.total}
            </span>
            <span className="text-muted-foreground truncate max-w-[200px]">
              {progress.filename}
            </span>
          </div>
          <Progress value={(progress.current / progress.total) * 100} />
        </div>
      )}

      {/* Hidden file input with type filtering */}
      <input
        ref={fileInputRef}
        type="file"
        multiple
        accept=".png,.jpg,.jpeg,.mp3,.wav,.mp4,.mov"
        onChange={handleFileChange}
        className="hidden"
      />
    </div>
  );
}

/**
 * StoryCore Assistant Component
 *
 * AI-powered assistant that can analyze projects, provide advice, and automatically
 * trigger wizards including the Ghost Tracker for project insights.
 * Enhanced with pipeline-aware generation context and re-generation commands.
 */

import React, { useState, useEffect, useRef } from 'react';
import type { WizardDefinition } from '../../types/configuration';
import { WizardService } from '../../services/wizard/WizardService';
import { WIZARD_DEFINITIONS } from '../../data/wizardDefinitions';
import { useAppStore } from '../../stores/useAppStore';
import { useEditorStore } from '../../stores/editorStore';
import { useGenerationStore } from '../../stores/generationStore';
import { LandingChatBox } from '../launcher/LandingChatBox';
import { ollamaClient } from '../../services/llm/OllamaClient';
import { PipelineAwareLLM } from '../../services/llm/PipelineAwareLLM';
import type { ContextualSuggestion } from '../../services/llm/PipelineAwareLLM';
import './StoryCoreAssistant.css';

interface AssistantMessage {
  id: string;
  type: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  suggestions?: AssistantSuggestion[];
}

interface AssistantSuggestion {
  type: 'wizard' | 'advice' | 'analysis';
  title: string;
  description: string;
  action: () => void;
  wizardId?: string;
  priority: 'high' | 'medium' | 'low';
}

interface ProjectAnalysis {
  score: number;
  issues: string[];
  recommendations: string[];
  suggestedWizards: string[];
}

export function StoryCoreAssistant() {
  const [messages, setMessages] = useState<AssistantMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [projectAnalysis, setProjectAnalysis] = useState<ProjectAnalysis | null>(null);
  const [isProcessingFile, setIsProcessingFile] = useState(false);
  const [pipelineSuggestions, setPipelineSuggestions] = useState<ContextualSuggestion[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const project = useAppStore((state) => state.project);
  const projectPath = useEditorStore((state) => state.projectPath);
  const currentPipeline = useGenerationStore((state) => state.currentPipeline);

  // Update pipeline suggestions when pipeline state changes
  useEffect(() => {
    const suggestions = PipelineAwareLLM.getContextualSuggestions();
    setPipelineSuggestions(suggestions);
  }, [currentPipeline]);

  // Initialize with welcome message (context-aware)
  useEffect(() => {
    const projectStatus = PipelineAwareLLM.getProjectCompletionStatus();
    const ctxSuggestions = PipelineAwareLLM.getContextualSuggestions();

    let welcomeContent = `👋 Salut ! Je suis ton Assistant StoryCore. Je t'aide à créer ton film de A à Z.\n\n`;
    welcomeContent += `📊 Ton projet est à **${projectStatus.completionPercentage}%**`;

    if (projectStatus.missingSteps.length > 0) {
      welcomeContent += `\n\n📋 Prochaines étapes :`;
      projectStatus.missingSteps.slice(0, 3).forEach(step => {
        welcomeContent += `\n• ${step}`;
      });
    }

    welcomeContent += `\n\nEssaie :\n• "Analyse mon projet"\n• "Régénérer l'image du shot 1"\n• "État du pipeline"\n• "Quel wizard lancer ?"`;

    // Build dynamic suggestions from pipeline state + defaults
    const dynamicSuggestions: AssistantSuggestion[] = [];

    // Add pipeline-aware suggestions first
    ctxSuggestions.slice(0, 2).forEach(cs => {
      dynamicSuggestions.push({
        type: cs.type === 'wizard' ? 'wizard' : 'analysis',
        title: cs.title,
        description: cs.description,
        action: () => handlePipelineSuggestion(cs),
        priority: cs.priority === 'critical' ? 'high' : cs.priority === 'high' ? 'high' : 'medium',
      });
    });

    // Always include analyze
    dynamicSuggestions.push({
      type: 'analysis',
      title: '📊 Analyser le projet',
      description: 'Analyse complète avec état du pipeline',
      action: () => handleQuickAction('analyze'),
      priority: 'high'
    });

    // Ghost Tracker
    dynamicSuggestions.push({
      type: 'wizard',
      title: '👻 Ghost Tracker',
      description: 'AI-powered project advisor',
      action: () => handleWizardLaunch('ghost-tracker-wizard'),
      wizardId: 'ghost-tracker-wizard',
      priority: 'medium'
    });

    const welcomeMessage: AssistantMessage = {
      id: 'welcome',
      type: 'assistant',
      content: welcomeContent,
      timestamp: new Date(),
      suggestions: dynamicSuggestions.slice(0, 4),
    };

    setMessages([welcomeMessage]);
     
    // Intentionally run only on mount - welcome message should be set once
  }, []);

  // Auto-analyze project when it loads
  useEffect(() => {
    if (project && projectPath && messages.length === 1) {
      // Auto-trigger analysis after a short delay
      const timeoutId = setTimeout(() => {
        handleQuickAction('analyze');
      }, 2000);
      return () => clearTimeout(timeoutId);
    }
     
    // Only trigger when project/projectPath changes; messages.length check prevents re-triggering
  }, [project, projectPath]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async () => {
    if (!inputValue.trim()) return;

    const userMessage: AssistantMessage = {
      id: `user-${Date.now()}`,
      type: 'user',
      content: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');

    // Process the message
    await processUserMessage(inputValue);
  };

  // Handle pipeline-aware suggestions when user clicks them
  const handlePipelineSuggestion = (suggestion: ContextualSuggestion) => {
    switch (suggestion.type) {
      case 'wizard':
        // Map suggestion IDs to wizard IDs
        if (suggestion.id === 'create-characters') handleWizardLaunch('character-creation');
        else if (suggestion.id === 'plan-shots') handleWizardLaunch('shot-planning');
        else addAssistantMessage(`🚀 Lancement de l'action: ${suggestion.title}`);
        break;
      case 'generate':
      case 'regenerate':
        addAssistantMessage(
          `🎨 Pour ${suggestion.actionLabel}, utilise le bouton correspondant dans la barre de génération (Prompt → Image → Vidéo → Audio).\n\n` +
          `💡 Astuce : Tu peux aussi cliquer droit sur un shot dans l'éditeur pour accéder aux options de re-génération.`,
          [{
            type: 'advice',
            title: '📊 Voir l\'état du pipeline',
            description: 'Afficher l\'état de toutes les générations',
            action: () => handleQuickAction('status'),
            priority: 'medium',
          }]
        );
        break;
      case 'export':
        addAssistantMessage(
          `🎞️ Pour exporter ton film, va dans le Video Editor et clique sur "Export".\n` +
          `Tu pourras choisir le format (MP4, MOV, etc.) et la qualité (Draft → Cinema).`
        );
        break;
      default:
        addAssistantMessage(`✅ ${suggestion.title} — ${suggestion.description}`);
    }
  };

  const processUserMessage = async (message: string) => {
    const lowerMessage = message.toLowerCase();

    // 1. Check for re-generation intent first (new feature)
    const regenIntent = PipelineAwareLLM.parseGenerationIntent(message);
    if (regenIntent) {
      const typeLabels = { prompt: 'le prompt', image: 'l\'image', video: 'la vidéo', audio: 'l\'audio' };
      const label = typeLabels[regenIntent.type];
      let response = `🔄 Tu veux régénérer ${label}`;
      if (regenIntent.targetName) {
        response += ` de "${regenIntent.targetName}"`;
      }
      response += `.\n\n`;
      response += `Pour lancer la re-génération :\n`;
      response += `1. Sélectionne le shot dans l'éditeur\n`;
      response += `2. Clique sur le bouton ${regenIntent.type === 'image' ? '🖼️ Image' : regenIntent.type === 'video' ? '🎬 Vidéo' : regenIntent.type === 'audio' ? '🔊 Audio' : '✏️ Prompt'} dans la barre de génération\n`;
      response += `3. Ajuste les paramètres si besoin et lance\n\n`;
      response += `💡 La re-génération remplacera le contenu existant.`;

      addAssistantMessage(response, [{
        type: 'analysis',
        title: '📊 État du pipeline',
        description: 'Voir les générations en cours',
        action: () => handleQuickAction('status'),
        priority: 'medium',
      }]);
      return;
    }

    // 2. Check for status/pipeline commands (new feature)
    if (lowerMessage.includes('status') || lowerMessage.includes('état') || lowerMessage.includes('pipeline') || lowerMessage.includes('progression')) {
      await handleQuickAction('status');
      return;
    }

    // 3. Existing command routing
    if (lowerMessage.includes('analyze') || lowerMessage.includes('analysis') || lowerMessage.includes('analyse')) {
      await handleQuickAction('analyze');
    } else if (lowerMessage.includes('ghost') || lowerMessage.includes('tracker')) {
      await handleWizardLaunch('ghost-tracker-wizard');
    } else if (lowerMessage.includes('character') || lowerMessage.includes('personnage')) {
      await handleWizardLaunch('character-creation');
    } else if (lowerMessage.includes('shot') || lowerMessage.includes('plan')) {
      await handleWizardLaunch('shot-planning');
    } else if (lowerMessage.includes('dialogue') || lowerMessage.includes('dialog')) {
      await handleWizardLaunch('dialogue-wizard');
    } else if (lowerMessage.includes('reference') || lowerMessage.includes('image')) {
      await handleWizardLaunch('shot-reference-wizard');
    } else if (lowerMessage.includes('world') || lowerMessage.includes('monde')) {
      await handleWizardLaunch('world-building');
    } else if (lowerMessage.includes('storyboard')) {
      await handleWizardLaunch('storyboard-creator');
    } else if (lowerMessage.includes('music') || lowerMessage.includes('musique')) {
      await handleWizardLaunch('music-generation');
    } else if (lowerMessage.includes('lyrics') || lowerMessage.includes('paroles') || lowerMessage.includes('chanson')) {
      await handleWizardLaunch('lyrics-generation');
    } else if (lowerMessage.includes('sequence') || lowerMessage.includes('séquence')) {
      await handleWizardLaunch('sequence-plan');
    } else if (lowerMessage.includes('export') || lowerMessage.includes('film')) {
      // New: export guidance
      const projectStatus = PipelineAwareLLM.getProjectCompletionStatus();
      if (projectStatus.completionPercentage < 80) {
        addAssistantMessage(
          `⚠️ Ton projet est à ${projectStatus.completionPercentage}%. Voici ce qu'il reste à faire avant l'export :\n\n` +
          projectStatus.missingSteps.map(s => `• ${s}`).join('\n') +
          `\n\n💡 Complète d'abord ces étapes pour un export de qualité.`
        );
      } else {
        addAssistantMessage(
          `🎞️ Ton projet est prêt pour l'export (${projectStatus.completionPercentage}%) !\n\n` +
          `Va dans le Video Editor → Export pour choisir :\n` +
          `• Format : MP4, MOV, AVI, MKV, WEBM\n` +
          `• Qualité : Draft, Preview, Standard, High, Broadcast, Cinema\n` +
          `• Options : Sous-titres, chapitres, package professionnel`
        );
      }
    } else {
      // 4. Use Ollama with CONTEXT-AWARE system prompt (enhanced)
      const ollamaStatus = useAppStore.getState().ollamaStatus;

      if (ollamaStatus === 'connected') {
        try {
          const models = await ollamaClient.listModels();
          const model = models.find(m => m.category === 'storytelling' || m.name.includes('llama'))?.name || models[0]?.name;

          if (model) {
            // Use pipeline-aware context instead of generic prompt
            const systemPrompt = PipelineAwareLLM.buildContextualSystemPrompt();
            const response = await ollamaClient.generate(model, `${systemPrompt}\n\nUser: ${message}`);
            addAssistantMessage(response);
            return;
          }
        } catch (error) {
          console.error('❌ [StoryCoreAssistant] Ollama chat failed:', error);
        }
      }

      // Fallback to generic response
      const response = generateGenericResponse(message);
      addAssistantMessage(response.content, response.suggestions);
    }
  };

  const handleQuickAction = async (action: string) => {
    if (action === 'status') {
      // New: Pipeline status command
      const statusMsg = PipelineAwareLLM.formatStatusMessage();
      const ctxSuggestions = PipelineAwareLLM.getContextualSuggestions();
      const suggestions: AssistantSuggestion[] = ctxSuggestions.slice(0, 3).map(cs => ({
        type: cs.type === 'wizard' ? 'wizard' as const : 'analysis' as const,
        title: cs.title,
        description: cs.description,
        action: () => handlePipelineSuggestion(cs),
        priority: cs.priority === 'critical' ? 'high' as const : 'medium' as const,
      }));
      addAssistantMessage(statusMsg, suggestions);
    } else if (action === 'analyze') {
      setIsAnalyzing(true);

      try {
        const analysis = await analyzeProject();
        setProjectAnalysis(analysis);
        const pipelineStatus = PipelineAwareLLM.getPipelineStatus();
        const projectStatus = PipelineAwareLLM.getProjectCompletionStatus();

        let content = `📊 **Analyse Complète du Projet !**\n\n`;
        content += `🎯 Score global : ${analysis.score}/10\n`;
        content += `📈 Complétion : ${projectStatus.completionPercentage}%\n`;
        content += `🔄 Pipeline : ${pipelineStatus.overallProgress}%\n\n`;

        if (analysis.issues.length > 0) {
          content += `⚠️ Problèmes détectés :\n`;
          analysis.issues.slice(0, 3).forEach(issue => {
            content += `• ${issue}\n`;
          });
          content += '\n';
        }

        if (pipelineStatus.failedStages.length > 0) {
          content += `❌ Étapes en échec : ${pipelineStatus.failedStages.join(', ')}\n\n`;
        }

        if (analysis.recommendations.length > 0) {
          content += `💡 Recommandations :\n`;
          analysis.recommendations.slice(0, 3).forEach(rec => {
            content += `• ${rec}\n`;
          });
          content += '\n';
        }

        if (analysis.suggestedWizards.length > 0) {
          content += `🚀 Wizards suggérés :\n`;
          analysis.suggestedWizards.forEach(wizardId => {
            const wizard = WIZARD_DEFINITIONS.find(w => w.id === wizardId);
            if (wizard) {
              content += `• ${wizard.name}\n`;
            }
          });
        }

        // Merge wizard suggestions with pipeline suggestions
        const suggestions: AssistantSuggestion[] = [];

        // Pipeline-aware suggestions first
        const ctxSuggestions = PipelineAwareLLM.getContextualSuggestions();
        ctxSuggestions.slice(0, 2).forEach(cs => {
          suggestions.push({
            type: cs.type === 'wizard' ? 'wizard' as const : 'analysis' as const,
            title: cs.title,
            description: cs.description,
            action: () => handlePipelineSuggestion(cs),
            priority: cs.priority === 'critical' ? 'high' as const : 'medium' as const,
          });
        });

        // Wizard suggestions
        analysis.suggestedWizards.slice(0, 2).forEach(wizardId => {
