// ============================================================================
// AudioMixingPanel Component
// ============================================================================

export const AudioMixingPanel: React.FC = () => {
  const {
    state,
    initialize,
    play,
    pause,
    stop,
    seek,
    setMasterVolume,
    setMasterMuted,
    addTrack,
    removeTrack,
    updateTrack,
    setTrackVolume,
    setTrackPan,
    setTrackMuted,
    setTrackSolo,
    addEffect,
    removeEffect,
    updateEffect
  } = useAudioMixing();

  const [selectedTrackId, setSelectedTrackId] = useState<string | null>(null);

  // Initialize audio context on first interaction
  const handlePlay = useCallback(async () => {
    if (state.audioContextState === 'suspended') {
      await initialize();
    }
    play();
  }, [initialize, play, state.audioContextState]);

  // Add a new track
  const handleAddTrack = useCallback(() => {
    const trackColors = ['#4a90d9', '#50c878', '#ff6b6b', '#ffd93d', '#9b59b6', '#3498db'];
    const trackTypes: Array<'voice' | 'music' | 'sfx' | 'ambient' | 'narration'> = ['voice', 'music', 'sfx', 'ambient', 'narration'];

    addTrack({
      name: `Track ${state.tracks.size + 1}`,
      type: trackTypes[state.tracks.size % trackTypes.length],
      src: '',
      volume: 0.8,
      pan: 0,
      muted: false,
      solo: false,
      locked: false,
      startTime: 0,
      duration: 0,
      fadeIn: 0,
      fadeOut: 0,
      effects: [],
      color: trackColors[state.tracks.size % trackColors.length]
    });
  }, [addTrack, state.tracks.size]);

  // Render a single track
  const renderTrack = useCallback((track: AudioTrack) => {
    const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setTrackVolume(track.id, parseFloat(e.target.value));
    };

    const handlePanChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setTrackPan(track.id, parseFloat(e.target.value));
    };

    const toggleMute = () => {
      setTrackMuted(track.id, !track.muted);
    };

    const toggleSolo = () => {
      setTrackSolo(track.id, !track.solo);
    };

    const handleRemove = () => {
      removeTrack(track.id);
    };

    const peakLevel = 0; // Placeholder for meter visualization

    return (
      <div 
        key={track.id} 
        style={{
          ...styles.track,
          borderLeft: `3px solid ${track.color}`
        }}
        onClick={() => setSelectedTrackId(track.id)}
      >
        {/* Track Header */}
        <div style={styles.trackHeader}>
          <div style={styles.trackName}>{track.name}</div>
          <div style={styles.trackType}>{track.type}</div>
          <div style={styles.trackControls}>
            <button 
              style={track.muted ? styles.activeButton : styles.smallButton}
              onClick={toggleMute}
            >
              M
            </button>
            <button 
              style={track.solo ? styles.activeButton : styles.smallButton}
              onClick={toggleSolo}
            >
              S
            </button>
            <button 
              style={styles.smallButton}
              onClick={handleRemove}
            >
              ×
            </button>
          </div>
        </div>

        {/* Track Faders */}
        <div style={styles.trackFaders}>
          {/* Volume Fader */}
          <div style={styles.faderRow}>
            <span style={styles.faderLabel}>Vol</span>
            <div style={styles.fader}>
              <div style={{
                ...styles.faderFill,
                height: `${track.volume * 100}%`
              }} />
              <span style={styles.faderValue}>{Math.round(track.volume * 100)}%</span>
            </div>
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={track.volume}
              onChange={handleVolumeChange}
              style={{ width: '100px' }}
            />
          </div>

          {/* Pan */}
          <div style={styles.faderRow}>
            <span style={styles.faderLabel}>Pan</span>
            <div style={styles.panKnob}>
              <div style={{
                ...styles.panIndicator,
                transform: `translateX(${track.pan * 12}px)`
              }} />
            </div>
            <input
              type="range"
              min="-1"
              max="1"
              step="0.01"
              value={track.pan}
              onChange={handlePanChange}
              style={{ width: '100px' }}
            />
          </div>
        </div>

        {/* Level Meter */}
        <div style={styles.meter}>
          <div style={{
            ...styles.meterFill,
            height: `${peakLevel * 100}%`
          }} />
        </div>

        {/* Effects */}
        {track.effects.length > 0 && (
          <div style={styles.effectsSection}>
            <div style={styles.effectsHeader}>
              <span>Effects</span>
            </div>
            {track.effects.map(effect => (
              <div key={effect.id} style={styles.effect}>
                <div 
                  style={effect.enabled ? styles.effectEnabled : styles.effectDisabled}
                  onClick={() => updateEffect(track.id, effect.id, { enabled: !effect.enabled })}
                />
                <span>{effect.type}</span>
                <button
                  style={styles.smallButton}
                  onClick={() => removeEffect(track.id, effect.id)}
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }, [setTrackVolume, setTrackPan, setTrackMuted, setTrackSolo, removeTrack, addEffect, removeEffect, updateEffect]);

  return (
    <div style={styles.panel}>
      {/* Header */}
      <div style={styles.header}>
        <span style={styles.title}>Audio Mixer</span>
        <div style={styles.controls}>
          <button style={styles.button} onClick={stop}>■</button>
          <button style={state.isPlaying ? styles.primaryButton : styles.button} onClick={handlePlay}>
            {state.isPlaying ? 'Pause' : 'Play'}
          </button>
        </div>
      </div>

      {/* Master Section */}
      <div style={styles.masterSection}>
        <div style={styles.masterFader}>
          <span style={{ fontSize: '11px' }}>Master</span>
          <div style={styles.masterMeter}>
            <div style={{ ...styles.meterFill, height: '50%' }} />
          </div>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={state.masterVolume}
            onChange={(e) => setMasterVolume(parseFloat(e.target.value))}
            style={{ width: '100px' }}
          />
          <span style={{ fontSize: '10px' }}>{Math.round(state.masterVolume * 100)}%</span>
        </div>
      </div>

      {/* Tracks */}
      <div style={styles.tracksContainer}>
        {Array.from(state.tracks.values()).map(track => renderTrack(track))}

        <button style={styles.addTrackButton} onClick={handleAddTrack}>
          + Add Track
        </button>
      </div>
    </div>
  );
};

export default AudioMixingPanel;

/**
 * Bar Visualizer Component for StoryCore
 * Renders frequency data as animated bars
 */

import React, { useRef, useEffect, useCallback, useMemo } from 'react';
import { FrequencyData } from '../../services/audio-visualization/AudioVisualizerTypes';

export interface BarVisualizerProps {
  /** Frequency data to display */
  data: FrequencyData | null;
  /** Width of the visualizer in pixels */
  width?: number;
  /** Height of the visualizer in pixels */
  height?: number;
  /** Background color */
  backgroundColor?: string;
  /** Bar colors (gradient) */
  colors?: string[];
  /** Number of bars to display */
  barCount?: number;
  /** Bar width in pixels */
  barWidth?: number;
  /** Bar spacing in pixels */
  barSpacing?: number;
  /** Whether to use gradient fill */
  gradientFill?: boolean;
  /** Whether to reflect bars */
  reflection?: boolean;
  /** Reflection opacity */
  reflectionOpacity?: number;
  /** Whether to show peak indicators */
  peakHold?: boolean;
  /** Peak decay rate */
  peakDecay?: number;
  /** Whether to show glow effect */
  glow?: boolean;
  /** Glow intensity */
  glowIntensity?: number;
  /** Whether to animate bars with smoothing */
  smoothing?: number;
  /** Whether to use logarithmic scale */
  logarithmic?: boolean;
  /** Whether to show center line */
  showCenterLine?: boolean;
  /** Center line color */
  centerLineColor?: string;
  /** Class name for styling */
  className?: string;
  /** Style overrides */
  style?: React.CSSProperties;
}

export const BarVisualizer: React.FC<BarVisualizerProps> = ({
  data,
  width = 800,
  height = 300,
  backgroundColor = '#1a1a2e',
  colors = ['#00d4ff', '#00ff88', '#ff6b6b', '#feca57'],
  barCount = 64,
  barWidth = 10,
  barSpacing = 2,
  gradientFill = true,
  reflection = true,
  reflectionOpacity = 0.3,
  peakHold = true,
  peakDecay = 0.98,
  glow = true,
  glowIntensity = 0.6,
  smoothing = 0.9,
  logarithmic = true,
  showCenterLine = true,
  centerLineColor = 'rgba(255, 255, 255, 0.2)',
  className,
  style,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const previousValuesRef = useRef<number[]>([]);
  const peakValuesRef = useRef<number[]>([]);
  const animationFrameRef = useRef<number | null>(null);

  // Initialize arrays
  useEffect(() => {
    previousValuesRef.current = new Array(barCount).fill(0);
    peakValuesRef.current = new Array(barCount).fill(0);
  }, [barCount]);

  // Create color gradient
  const colorGradient = useMemo(() => {
    if (colors.length <= 1) return colors;
    return colors;
  }, [colors]);

  const drawBars = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const centerY = height / 2;
    const totalBars = reflection ? barCount * 2 : barCount;
    const totalWidth = totalBars * (barWidth + barSpacing);
    const startX = (width - totalWidth) / 2;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    // Draw center line
    if (showCenterLine) {
      ctx.strokeStyle = centerLineColor;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, centerY);
      ctx.lineTo(width, centerY);
      ctx.stroke();
    }

    if (!data?.frequencyData) return;

    const { frequencyData } = data;
    const binCount = frequencyData.length;
    const step = Math.floor(binCount / barCount);

    // Draw bars
    for (let i = 0; i < barCount; i++) {
      // Calculate amplitude for this bar
      let sum = 0;
      for (let j = 0; j < step; j++) {
        const index = i * step + j;
        if (index < binCount) {
          sum += frequencyData[index];
        }
      }
      
      let amplitude = sum / step / 255;

      // Apply logarithmic scale
      if (logarithmic) {
        amplitude = Math.pow(amplitude, 0.5);
      }

      // Apply smoothing
      const prevValue = previousValuesRef.current[i] || 0;
      const smoothedValue = prevValue * smoothing + amplitude * (1 - smoothing);
      previousValuesRef.current[i] = smoothedValue;

      // Calculate bar dimensions
      const barHeight = smoothedValue * height * 0.45;
      const x = startX + i * (barWidth + barSpacing);
      const y = centerY - barHeight;

      // Get color
      const colorIndex = Math.floor((i / barCount) * (colorGradient.length - 1));
      const color = colorGradient[colorIndex] || colorGradient[0];

      // Apply glow
      if (glow) {
        ctx.shadowColor = color;
        ctx.shadowBlur = glowIntensity * 15;
      }

      // Draw bar with gradient
      if (gradientFill) {
        const gradient = ctx.createLinearGradient(x, centerY, x, y);
        gradient.addColorStop(0, color);
        gradient.addColorStop(1, adjustColorBrightness(color, 50));
        ctx.fillStyle = gradient;
      } else {
        ctx.fillStyle = color;
      }

      // Draw bar
      ctx.fillRect(x, y, barWidth, barHeight);

      // Draw peak indicator
      if (peakHold) {
        const peakValue = peakValuesRef.current[i] || 0;
        if (smoothedValue > peakValue) {
          peakValuesRef.current[i] = smoothedValue;
        } else {
          peakValuesRef.current[i] *= peakDecay;
        }

        if (peakValuesRef.current[i] > 0.05) {
          const peakY = centerY - peakValuesRef.current[i] * height * 0.45;
          ctx.fillStyle = '#ffffff';
          ctx.shadowBlur = 0;
          ctx.fillRect(x, peakY - 2, barWidth, 3);
        }
      }

      // Draw reflection
      if (reflection) {
        const reflectionY = centerY + barHeight;
        const reflectionHeight = barHeight * reflectionOpacity;

        ctx.globalAlpha = reflectionOpacity;
        ctx.fillStyle = color;
        ctx.fillRect(x, reflectionY, barWidth, reflectionHeight);
        ctx.globalAlpha = 1;
      }

      ctx.shadowBlur = 0;
    }

    // Draw bass indicator
    if (data.bassEnergy > 0.6) {
      const bassWidth = width * 0.3;
      const bassX = (width - bassWidth) / 2;
      
      ctx.fillStyle = `rgba(255, 107, 107, ${data.bassEnergy * 0.5})`;
      ctx.fillRect(bassX, height - 10, bassWidth, 10);
    }

    // Draw mid indicator
    if (data.midEnergy > 0.5) {
      const midWidth = width * 0.2;
      const midX = (width - midWidth) / 2;
      
      ctx.fillStyle = `rgba(254, 202, 87, ${data.midEnergy * 0.4})`;
      ctx.fillRect(midX, height - 10, midWidth, 10);
    }

    // Draw high indicator
    if (data.highEnergy > 0.4) {
      const highWidth = width * 0.15;
      const highX = (width - highWidth) / 2;
      
      ctx.fillStyle = `rgba(0, 212, 255, ${data.highEnergy * 0.3})`;
      ctx.fillRect(highX, height - 10, highWidth, 10);
    }

  }, [data, width, height, backgroundColor, colors, barCount, barWidth, barSpacing, gradientFill, reflection, reflectionOpacity, peakHold, peakDecay, glow, glowIntensity, smoothing, logarithmic, showCenterLine, centerLineColor, colorGradient]);

  // Animation loop
  useEffect(() => {
    const animate = () => {
      drawBars();
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [drawBars]);

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      className={className}
      style={{
        display: 'block',
        borderRadius: '8px',
        ...style,
      }}
    />
  );
};

/**
 * Helper function to adjust color brightness
 */
function adjustColorBrightness(hex: string, percent: number): string {
  const num = parseInt(hex.replace('#', ''), 16);
  const amt = Math.round(2.55 * percent);
  const R = Math.min(255, Math.max(0, (num >> 16) + amt));
  const G = Math.min(255, Math.max(0, ((num >> 8) & 0x00ff) + amt));
  const B = Math.min(255, Math.max(0, (num & 0x0000ff) + amt));
  return `#${(0x1000000 + R * 0x10000 + G * 0x100 + B).toString(16).slice(1)}`;
}

export default BarVisualizer;

/**
 * Circular Visualizer Component for StoryCore
 * Renders radial/circular frequency visualization
 */

import React, { useRef, useEffect, useCallback } from 'react';
import { FrequencyData } from '../../services/audio-visualization/AudioVisualizerTypes';

export interface CircularVisualizerProps {
  /** Frequency data to display */
  data: FrequencyData | null;
  /** Size of the visualizer in pixels */
  size?: number;
  /** Background color */
  backgroundColor?: string;
  /** Bar colors (gradient) */
  colors?: string[];
  /** Number of bars in the circle */
  barCount?: number;
  /** Inner radius of the circle */
  innerRadius?: number;
  /** Maximum bar height */
  maxBarHeight?: number;
  /** Bar width in degrees */
  barWidth?: number;
  /** Rotation offset in degrees */
  rotation?: number;
  /** Whether to animate rotation */
  autoRotate?: boolean;
  /** Auto-rotate speed */
  rotateSpeed?: number;
  /** Whether to show glow effect */
  glow?: boolean;
  /** Glow intensity */
  glowIntensity?: number;
  /** Whether to show bass kick visualization */
  showBassKick?: boolean;
  /** Bass kick color */
  bassKickColor?: string;
  /** Whether to mirror the visualization */
  mirror?: boolean;
  /** Class name for styling */
  className?: string;
  /** Style overrides */
  style?: React.CSSProperties;
}

export const CircularVisualizer: React.FC<CircularVisualizerProps> = ({
  data,
  size = 400,
  backgroundColor = '#0f0f1a',
  colors = ['#a55eea', '#ff6b6b', '#feca57', '#48dbfb', '#00ff88'],
  barCount = 64,
  innerRadius = 80,
  maxBarHeight = 100,
  barWidth = 5,
  rotation = 0,
  autoRotate = true,
  rotateSpeed = 0.5,
  glow = true,
  glowIntensity = 0.8,
  showBassKick = true,
  bassKickColor = '#ff6b6b',
  mirror = true,
  className,
  style,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rotationRef = useRef(0);
  const bassKickRef = useRef(0);
  const animationFrameRef = useRef<number | null>(null);

  const drawVisualization = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const centerX = size / 2;
    const centerY = size / 2;
    const angleStep = (Math.PI * 2) / barCount;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, size, size);

    // Apply rotation
    const currentRotation = rotation + rotationRef.current;
    rotationRef.current += rotateSpeed * 0.01;

    // Draw frequency bars
    if (data?.frequencyData) {
      const { frequencyData } = data;
      const step = Math.floor(frequencyData.length / barCount);

      for (let i = 0; i < barCount; i++) {
        // Calculate amplitude for this bar
        let sum = 0;
        for (let j = 0; j < step; j++) {
          const index = i * step + j;
          if (index < frequencyData.length) {
            sum += frequencyData[index];
          }
        }
        const amplitude = sum / step / 255;

        // Calculate bar dimensions
        const angle = i * angleStep + currentRotation;
        const barHeight = amplitude * maxBarHeight;

        // Get color from gradient
        const colorIndex = Math.floor((i / barCount) * (colors.length - 1));
        const color = colors[colorIndex];

        // Draw bar
        const x1 = centerX + Math.cos(angle) * innerRadius;
        const y1 = centerY + Math.sin(angle) * innerRadius;
        const x2 = centerX + Math.cos(angle) * (innerRadius + barHeight);
        const y2 = centerY + Math.sin(angle) * (innerRadius + barHeight);

        // Apply glow
        if (glow) {
          ctx.shadowColor = color;
          ctx.shadowBlur = glowIntensity * 15;
        }

        ctx.strokeStyle = color;
        ctx.lineWidth = barWidth;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();

        // Draw mirrored bar
        if (mirror) {
          const mirrorAngle = angle + Math.PI;
          const mx1 = centerX + Math.cos(mirrorAngle) * innerRadius;
          const my1 = centerY + Math.sin(mirrorAngle) * innerRadius;
          const mx2 = centerX + Math.cos(mirrorAngle) * (innerRadius + barHeight);
          const my2 = centerY + Math.sin(mirrorAngle) * (innerRadius + barHeight);

          ctx.globalAlpha = 0.5;
          ctx.beginPath();
          ctx.moveTo(mx1, my1);
          ctx.lineTo(mx2, my2);
          ctx.stroke();
          ctx.globalAlpha = 1;
        }
      }

      // Draw bass kick effect
      if (showBassKick && bassKickRef.current > 0) {
        ctx.shadowColor = bassKickColor;
        ctx.shadowBlur = bassKickRef.current * 20;
        ctx.strokeStyle = bassKickColor;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(centerX, centerY, innerRadius - 10 + bassKickRef.current * 10, 0, Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;

        bassKickRef.current *= 0.9;
      }
    }

    // Draw center circle
    const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, innerRadius);
    gradient.addColorStop(0, colors[0] || '#a55eea');
    gradient.addColorStop(1, backgroundColor);

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(centerX, centerY, innerRadius - 5, 0, Math.PI * 2);
    ctx.fill();

    // Draw outer ring
    ctx.strokeStyle = colors[0] || '#a55eea';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(centerX, centerY, innerRadius + maxBarHeight + 10, 0, Math.PI * 2);
    ctx.stroke();

  }, [data, size, backgroundColor, colors, barCount, innerRadius, maxBarHeight, barWidth, rotation, autoRotate, rotateSpeed, glow, glowIntensity, showBassKick, bassKickColor, mirror]);

  // Handle bass kick detection
  useEffect(() => {
    if (data && showBassKick && data.bassEnergy > 0.7 && bassKickRef.current < 0.1) {
      bassKickRef.current = data.bassEnergy;
    }
  }, [data, showBassKick]);

  // Animation loop
  useEffect(() => {
    const animate = () => {
      drawVisualization();
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    if (autoRotate || data) {
      animate();
    }

    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [drawVisualization, autoRotate, data]);

  return (
    <canvas
      ref={canvasRef}
      width={size}
      height={size}
      className={className}
      style={{
        display: 'block',
        borderRadius: '50%',
        ...style,
      }}
    />
  );
};

export default CircularVisualizer;

/**
 * Spectrum Analyzer Component for StoryCore
 * Renders FFT-based frequency spectrum visualization
 */

import React, { useRef, useEffect, useCallback, useMemo } from 'react';
import { FrequencyData } from '../../services/audio-visualization/AudioVisualizerTypes';

export interface SpectrumAnalyzerProps {
  /** Frequency data to display */
  data: FrequencyData | null;
  /** Width of the visualizer in pixels */
  width?: number;
  /** Height of the visualizer in pixels */
  height?: number;
  /** Background color */
  backgroundColor?: string;
  /** Bar colors (gradient) */
  colors?: string[];
  /** Whether to use GPU acceleration (WebGL) */
  gpuAccelerated?: boolean;
  /** Number of frequency bands to display */
  bandCount?: number;
  /** Bar width in pixels */
  barWidth?: number;
  /** Bar spacing in pixels */
  barSpacing?: number;
  /** Whether to show decibel labels */
  showLabels?: boolean;
  /** Whether to show frequency markers */
  showFrequencyMarkers?: boolean;
  /** Whether to mirror the spectrum */
  mirror?: boolean;
  /** Whether to show peak indicators */
  showPeaks?: boolean;
  /** Peak decay rate */
  peakDecay?: number;
  /** Glow intensity */
  glowIntensity?: number;
  /** Class name for styling */
  className?: string;
  /** Style overrides */
  style?: React.CSSProperties;
}

export const SpectrumAnalyzer: React.FC<SpectrumAnalyzerProps> = ({
  data,
  width = 800,
  height = 300,
  backgroundColor = '#0f0f1a',
  colors = ['#00ff88', '#00d4ff', '#ff6b6b', '#feca57'],
  gpuAccelerated = false,
  bandCount = 64,
  barWidth = 8,
  barSpacing = 2,
  showLabels = true,
  showFrequencyMarkers = true,
  mirror = true,
  showPeaks = true,
  peakDecay = 0.95,
  glowIntensity = 0.5,
  className,
  style,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const peakValuesRef = useRef<number[]>([]);
  const glRef = useRef<WebGLRenderingContext | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  // Initialize peak values
  useEffect(() => {
    peakValuesRef.current = new Array(bandCount).fill(0);
  }, [bandCount]);

  // Create color gradient
  const colorGradient = useMemo(() => {
    const gradient = [];
    const steps = colors.length - 1;
    for (let i = 0; i <= steps; i++) {
      gradient.push(colors[Math.min(i, colors.length - 1)]);
    }
    return gradient;
  }, [colors]);

  // Draw using Canvas 2D
  const drawWithCanvas2D = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !data?.frequencyData) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    const { frequencyData } = data;
    const binCount = frequencyData.length;
    const step = Math.floor(binCount / bandCount);
    const padding = barSpacing;

    // Draw frequency bands
    for (let i = 0; i < bandCount; i++) {
      // Calculate average amplitude for this band
      let sum = 0;
      for (let j = 0; j < step; j++) {
        const index = i * step + j;
        if (index < binCount) {
          sum += frequencyData[index];
        }
      }
      const avgAmplitude = sum / step / 255;

      // Calculate peak value with decay
      if (showPeaks) {
        peakValuesRef.current[i] = Math.max(
          peakValuesRef.current[i] * peakDecay,
          avgAmplitude
        );
      }

      const barHeight = avgAmplitude * height * 0.9;
      const x = i * (barWidth + padding);
      const y = height - barHeight;

      // Create gradient for this bar
      const gradient = ctx.createLinearGradient(x, height, x, y);
      const colorIndex = Math.floor((i / bandCount) * (colorGradient.length - 1));
      const nextColorIndex = Math.min(colorIndex + 1, colorGradient.length - 1);
      const t = (i / bandCount) * (colorGradient.length - 1) - colorIndex;

      gradient.addColorStop(0, colorGradient[colorIndex]);
      gradient.addColorStop(1, colorGradient[nextColorIndex] || colorGradient[colorGradient.length - 1]);

      // Draw bar with glow effect
      if (glowIntensity > 0) {
        ctx.shadowColor = colorGradient[Math.floor(i / bandCount * (colors.length - 1))];
        ctx.shadowBlur = glowIntensity * 10;
      }

      ctx.fillStyle = gradient;
      ctx.fillRect(x, y, barWidth, barHeight);

      // Draw peak indicator
      if (showPeaks && peakValuesRef.current[i] > 0) {
        const peakHeight = peakValuesRef.current[i] * height * 0.9;
        const peakY = height - peakHeight;

        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.fillRect(x, peakY - 2, barWidth, 4);
      }

      ctx.shadowBlur = 0;
    }

    // Draw mirrored spectrum
    if (mirror) {
      ctx.globalAlpha = 0.3;
      for (let i = 0; i < bandCount; i++) {
        let sum = 0;
        for (let j = 0; j < step; j++) {
          const index = i * step + j;
          if (index < binCount) {
            sum += frequencyData[index];
          }
        }
        const avgAmplitude = sum / step / 255;
        const barHeight = avgAmplitude * height * 0.9;
        const x = i * (barWidth + padding);
        const y = height - barHeight;

        ctx.fillStyle = colorGradient[Math.floor(i / bandCount * (colors.length - 1))];
        ctx.fillRect(x, 0, barWidth, barHeight);
      }
      ctx.globalAlpha = 1;
    }

    // Draw frequency markers
    if (showFrequencyMarkers) {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.font = '10px sans-serif';
      
      const markers = [
        { freq: 20, label: '20 Hz' },
        { freq: 200, label: '200 Hz' },
        { freq: 1000, label: '1 kHz' },
        { freq: 5000, label: '5 kHz' },
        { freq: 20000, label: '20 kHz' },
      ];

      const nyquist = 22050; // Half of 44100 sample rate
      for (const marker of markers) {
        const x = (Math.log10(marker.freq) / Math.log10(nyquist)) * width;
        if (x > 0 && x < width) {
          ctx.fillText(marker.label, x + 2, height - 5);
          ctx.fillRect(x, height - 15, 1, 15);
        }
      }
    }
  }, [data, width, height, backgroundColor, colors, bandCount, barWidth, barSpacing, showPeaks, peakDecay, glowIntensity, mirror, showFrequencyMarkers, colorGradient]);

  // Draw using WebGL (for GPU acceleration)
  const drawWithWebGL = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !data?.frequencyData) return;

    let gl = glRef.current;
    
    if (!gl) {
      gl = canvas.getContext('webgl', { alpha: false });
      if (!gl) return;
      glRef.current = gl;
    }

    // WebGL rendering would be implemented here for better performance
    // For now, fallback to 2D
    drawWithCanvas2D();
  }, [data, drawWithCanvas2D]);

  useEffect(() => {
    if (gpuAccelerated) {
      drawWithWebGL();
    } else {
      drawWithCanvas2D();
    }
  }, [gpuAccelerated, drawWithWebGL, drawWithCanvas2D]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (glRef.current) {
        glRef.current = null;
      }
    };
  }, []);

  return (
    <div className={className} style={style}>
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        style={{
          display: 'block',
          borderRadius: '8px',
        }}
      />
      {showLabels && (
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          padding: '4px 8px',
          backgroundColor: 'rgba(0, 0, 0, 0.3)',
          borderRadius: '0 0 8px 8px',
          fontSize: '10px',
          color: 'rgba(255, 255, 255, 0.6)',
        }}>
          <span>20 Hz</span>
          <span>200 Hz</span>
          <span>1 kHz</span>
          <span>5 kHz</span>
          <span>20 kHz</span>
        </div>
      )}
    </div>
  );
};

export default SpectrumAnalyzer;

/**
 * Waveform Visualizer Component for StoryCore
 * Renders real-time audio waveform data
 */

import React, { useRef, useEffect, useCallback } from 'react';
import { WaveformData } from '../../services/audio-visualization/AudioVisualizerTypes';

export interface WaveformVisualizerProps {
  /** Waveform data to display */
  data: WaveformData | null;
  /** Width of the visualizer in pixels */
  width?: number;
  /** Height of the visualizer in pixels */
  height?: number;
  /** Background color */
  backgroundColor?: string;
  /** Line color */
  lineColor?: string;
  /** Line width */
  lineWidth?: number;
  /** Whether to mirror the waveform */
  mirror?: boolean;
  /** Whether to show RMS indicator */
  showRMS?: boolean;
  /** RMS line color */
  rmsColor?: string;
  /** Whether to show peaks */
  showPeaks?: boolean;
  /** Peak color */
  peakColor?: string;
  /** Class name for styling */
  className?: string;
  /** Style overrides */
  style?: React.CSSProperties;
}

export const WaveformVisualizer: React.FC<WaveformVisualizerProps> = ({
  data,
  width = 800,
  height = 200,
  backgroundColor = '#1a1a2e',
  lineColor = '#00d4ff',
  lineWidth = 2,
  mirror = true,
  showRMS = true,
  rmsColor = '#ff6b6b',
  showPeaks = true,
  peakColor = '#feca57',
  className,
  style,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWaveform = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !data?.timeDomainData) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { timeDomainData, rms, peaks, currentTime, duration } = data;
    const centerY = height / 2;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    // Draw center line
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, centerY);
    ctx.lineTo(width, centerY);
    ctx.stroke();

    // Calculate scaling factors
    const bufferLength = timeDomainData.length;
    const sliceWidth = width / bufferLength;
    const amplitude = height * 0.4;

    // Draw waveform
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = lineWidth;
    ctx.beginPath();

    for (let i = 0; i < bufferLength; i++) {
      const v = timeDomainData[i];
      const y = centerY + v * amplitude;

      if (i === 0) {
        ctx.moveTo(0, y);
      } else {
        ctx.lineTo(i * sliceWidth, y);
      }
    }

    ctx.stroke();

    // Draw mirrored waveform
    if (mirror) {
      ctx.strokeStyle = lineColor;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();

      for (let i = 0; i < bufferLength; i++) {
        const v = timeDomainData[i];
        const y = centerY - v * amplitude;

        if (i === 0) {
          ctx.moveTo(0, y);
        } else {
          ctx.lineTo(i * sliceWidth, y);
        }
      }

      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // Draw RMS indicator
    if (showRMS && data.rms > 0) {
      ctx.strokeStyle = rmsColor;
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      ctx.moveTo(0, centerY + data.rms * amplitude);
      ctx.lineTo(width, centerY + data.rms * amplitude);
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // Draw peak indicators
    if (showPeaks && peaks.length > 0) {
      ctx.fillStyle = peakColor;
      for (const peak of peaks) {
        const peakX = peak * width;
        const peakY = centerY - timeDomainData[Math.floor(peak * bufferLength)] * amplitude;
        
        ctx.beginPath();
        ctx.arc(peakX, peakY, 4, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Draw time indicator
    if (duration > 0) {
      const timeX = (currentTime / duration) * width;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(timeX, 0);
      ctx.lineTo(timeX, height);
      ctx.stroke();
    }

    // Draw progress bar at bottom
    if (duration > 0) {
      const progress = currentTime / duration;
      ctx.fillStyle = lineColor;
      ctx.fillRect(0, height - 4, width * progress, 4);
    }
  }, [data, width, height, backgroundColor, lineColor, lineWidth, mirror, showRMS, rmsColor, showPeaks, peakColor]);

  useEffect(() => {
    drawWaveform();
  }, [drawWaveform]);

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      className={className}
      style={{
        display: 'block',
        borderRadius: '8px',
        ...style,
      }}
    />
  );
};

