    padding: '16px',
    backgroundColor: '#16213e',
    borderRadius: '6px',
  },
  sectionTitle: {
    fontSize: '16px',
    fontWeight: 600,
    marginBottom: '12px',
    color: '#00d4ff',
  },
  input: {
