/**
 * Props du composant
 */
export interface BatchOperationsToolbarProps {
  selectedShots: ProductionShot[];
  onOperationComplete?: (result: BatchOperationResult) => void;
  onClose?: () => void;
  estimatedTime?: number;
}

/**
 * État de l'opération en cours
 */
interface OperationState {
  type: BatchOperationType;
  progress: number;
  isRunning: boolean;
  result?: BatchOperationResult;
  error?: Error;
}

/**
 * Barre d'outils pour opérations par lots
 * Exigence: 8.1 - Affichage lors de sélection multiple
 * Exigence: 8.5 - Support des opérations
 * Exigence: 8.6 - Rapport d'erreurs
 */
export const BatchOperationsToolbar: React.FC<BatchOperationsToolbarProps> = ({
  selectedShots,
  onOperationComplete,
  onClose,
  estimatedTime
}) => {
  const [operationState, setOperationState] = useState<OperationState | null>(null);
  const [showErrorReport, setShowErrorReport] = useState(false);
  
  // Créer le gestionnaire d'opérations (use useState to avoid constructor issues)
  const [manager] = useState(() => new BatchOperationsManager());
  
  /**
   * Exécute une opération
   * Exigence: 8.5 - Support des opérations
   */
  const handleOperation = useCallback(async (
    type: BatchOperationType,
    options: BatchOperationOptions = {}
  ) => {
    setOperationState({
      type,
      progress: 0,
      isRunning: true
    });
    
    try {
      const convertedShots = selectedShots.map(productionShotToShot);
      const result = await manager.execute(type, convertedShots, options);
      
      setOperationState({
        type,
        progress: 100,
        isRunning: false,
        result
      });
      
      // Notifier le parent
      onOperationComplete?.(result);
      
      // Afficher le rapport d'erreurs si nécessaire
      if (result.failed.length > 0) {
        setShowErrorReport(true);
      } else {
        // Fermer automatiquement après succès complet
        setTimeout(() => {
          setOperationState(null);
        }, 2000);
      }
      
    } catch (error) {
      setOperationState({
        type,
        progress: 0,
        isRunning: false,
        error: error as Error
      });
    }
  }, [manager, selectedShots, onOperationComplete]);
  
  /**
   * Annule l'opération en cours
   */
  const handleCancel = useCallback(() => {
    if (operationState?.isRunning) {
      // Annuler via le gestionnaire
      // Note: nécessite l'ID de l'opération, à implémenter
      setOperationState(null);
    }
  }, [operationState]);
  
  /**
   * Ferme la barre d'outils
   */
  const handleClose = useCallback(() => {
    setOperationState(null);
    setShowErrorReport(false);
    onClose?.();
  }, [onClose]);
  
  /**
   * Formate le temps estimé
   */
  const formatEstimatedTime = (ms: number): string => {
    if (ms < 1000) {
      return `${ms}ms`;
    } else if (ms < 60000) {
      return `${Math.ceil(ms / 1000)}s`;
    } else {
      const minutes = Math.floor(ms / 60000);
      const seconds = Math.ceil((ms % 60000) / 1000);
      return `${minutes}m ${seconds}s`;
    }
  };
  
  /**
   * Obtient l'estimation de temps pour une opération
   */
  const getEstimatedTime = (type: BatchOperationType): string => {
    if (estimatedTime) {
      return formatEstimatedTime(estimatedTime);
    }
    const estimated = manager.estimateTime(type, selectedShots.length);
    return formatEstimatedTime(estimated);
  };
  
  return (
    <AnimatePresence>
      <motion.div
        className="batch-operations-toolbar"
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: -20, opacity: 0 }}
        transition={{ duration: 0.2 }}
      >
        <div className="toolbar-content">
          {/* En-tête */}
          <div className="toolbar-header">
            <span className="selection-count">
              {selectedShots.length} plan{selectedShots.length > 1 ? 's' : ''} sélectionné{selectedShots.length > 1 ? 's' : ''}
            </span>
            <button
              className="close-button"
              onClick={handleClose}
              aria-label="Fermer"
            >
              <X size={16} />
            </button>
          </div>
          
          {/* Boutons d'opérations */}
          {!operationState && (
            <div className="toolbar-actions">
              <button
                className="action-button"
                onClick={() => handleOperation('duplicate')}
                title={`Dupliquer (≈${getEstimatedTime('duplicate')})`}
              >
                <Copy size={18} />
                <span>Dupliquer</span>
              </button>
              
              <button
                className="action-button danger"
                onClick={() => {
                  if (selectedShots.length > 5) {
                    if (confirm(`Êtes-vous sûr de vouloir supprimer ${selectedShots.length} plans ?`)) {
                      handleOperation('delete');
                    }
                  } else {
                    handleOperation('delete');
                  }
                }}
                title={`Supprimer (≈${getEstimatedTime('delete')})`}
              >
                <Trash2 size={18} />
                <span>Supprimer</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('export')}
                title={`Exporter (≈${getEstimatedTime('export')})`}
              >
                <Download size={18} />
                <span>Exporter</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('transform')}
                title={`Transformer (≈${getEstimatedTime('transform')})`}
              >
                <Wand2 size={18} />
                <span>Transformer</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('tag')}
                title={`Ajouter des tags (≈${getEstimatedTime('tag')})`}
              >
                <Tag size={18} />
                <span>Tags</span>
              </button>
            </div>
          )}
          
          {/* Progression */}
          {operationState?.isRunning && (
            <div className="toolbar-progress">
              <div className="progress-header">
                <span className="progress-label">
                  {operationState.type === 'duplicate' && 'Duplication en cours...'}
                  {operationState.type === 'delete' && 'Suppression en cours...'}
                  {operationState.type === 'export' && 'Export en cours...'}
                  {operationState.type === 'transform' && 'Transformation en cours...'}
                  {operationState.type === 'tag' && 'Ajout de tags en cours...'}
                </span>
                <button
                  className="cancel-button"
                  onClick={handleCancel}
                  aria-label="Annuler"
                >
                  <X size={14} />
                </button>
              </div>
              
              <div className="progress-bar-container">
                <div
                  className="progress-bar"
                  style={{ width: `${operationState.progress}%` }}
                />
              </div>
              
              <div className="progress-info">
                <span>{Math.round(operationState.progress)}%</span>
                <Loader2 size={14} className="spinner" />
              </div>
            </div>
          )}
          
          {/* Résultat */}
          {operationState && !operationState.isRunning && operationState.result && (
            <div className="toolbar-result">
              {operationState.result.failed.length === 0 ? (
                <div className="result-success">
                  <CheckCircle size={18} className="success-icon" />
                  <span>
                    {operationState.result.success.length} plan{operationState.result.success.length > 1 ? 's' : ''} traité{operationState.result.success.length > 1 ? 's' : ''} avec succès
                  </span>
                  <span className="result-time">
                    ({formatEstimatedTime(operationState.result.totalTime)})
                  </span>
                </div>
              ) : (
                <div className="result-partial">
                  <AlertCircle size={18} className="warning-icon" />
                  <span>
                    {operationState.result.success.length} succès, {operationState.result.failed.length} échec{operationState.result.failed.length > 1 ? 's' : ''}
                  </span>
                  <button
                    className="view-errors-button"
                    onClick={() => setShowErrorReport(true)}
                  >
                    Voir les erreurs
                  </button>
                </div>
              )}
            </div>
          )}
          
          {/* Erreur */}
          {operationState && !operationState.isRunning && operationState.error && (
            <div className="toolbar-error">
              <AlertCircle size={18} className="error-icon" />
              <span>Erreur: {operationState.error.message}</span>
            </div>
          )}
        </div>
        
        {/* Rapport d'erreurs */}
        <AnimatePresence>
          {showErrorReport && operationState?.result && (
            <motion.div
              className="error-report-overlay"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setShowErrorReport(false)}
            >
              <motion.div
                className="error-report"
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.9, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
              >
                <div className="error-report-header">
                  <h3>Rapport d'erreurs</h3>
                  <button
                    className="close-button"
                    onClick={() => setShowErrorReport(false)}
                    aria-label="Fermer"
                  >
                    <X size={18} />
                  </button>
                </div>
                
                <div className="error-report-content">
                  <p className="error-summary">
                    {operationState.result.failed.length} plan{operationState.result.failed.length > 1 ? 's' : ''} n'ont pas pu être traité{operationState.result.failed.length > 1 ? 's' : ''}:
                  </p>
                  
                  <ul className="error-list">
                    {operationState.result.failed.map((failure, index) => (
                      <li key={index} className="error-item">
                        <strong>{`Shot ${failure.shot.number}`}</strong>
                        <span className="error-message">{failure.error.message}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                
                <div className="error-report-footer">
                  <button
                    className="retry-button"
                    onClick={() => {
                      setShowErrorReport(false);
                      // Réessayer avec les plans échoués
                      handleOperation(operationState.type, {});
                    }}
                  >
                    Réessayer les échecs
                  </button>
                  <button
                    className="close-button-secondary"
                    onClick={() => setShowErrorReport(false)}
                  >
                    Fermer
                  </button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
};

/**
 * BulkMetadataEditor - Éditeur de métadonnées groupées
 * 
 * Permet l'édition de métadonnées pour plusieurs plans simultanément:
 * - Interface d'édition groupée
 * - Prévisualisation des changements
 * - Application à tous les plans sélectionnés
 * 
 * Exigence: 8.3 - Édition groupée de métadonnées
 */

import React, { useState, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { Shot } from '../../types';
import { X, Eye, Check, AlertCircle } from 'lucide-react';

/**
 * Props du composant
 */
export interface BulkMetadataEditorProps {
  selectedShots: Shot[];
  onApply: (updates: Partial<Shot>) => void;
  onCancel: () => void;
}

/**
 * Champs de métadonnées éditables
 */
interface MetadataField {
  key: keyof Shot | string;
  label: string;
  type: 'text' | 'number' | 'select' | 'tags';
  options?: string[];
  placeholder?: string;
}

/**
 * Changements de métadonnées
 */
interface MetadataChanges {
  [key: string]: unknown;
}

/**
 * Éditeur de métadonnées groupées
 * Exigence: 8.3 - Édition groupée avec prévisualisation
 */
export const BulkMetadataEditor: React.FC<BulkMetadataEditorProps> = ({
  selectedShots,
  onApply,
  onCancel
}) => {
  const [changes, setChanges] = useState<MetadataChanges>({});
  const [showPreview, setShowPreview] = useState(false);
  const [previewIndex, setPreviewIndex] = useState(0);

  /**
   * Champs de métadonnées disponibles
   */
  const fields: MetadataField[] = useMemo(() => [
    {
      key: 'title',
      label: 'Titre',
      type: 'text',
      placeholder: 'Nouveau titre...'
    },
    {
      key: 'description',
      label: 'Description',
      type: 'text',
      placeholder: 'Nouvelle description...'
    },
    {
      key: 'duration',
      label: 'Durée (secondes)',
      type: 'number',
      placeholder: '0'
    },
    {
      key: 'metadata.category',
      label: 'Catégorie',
      type: 'select',
      options: ['Action', 'Dialogue', 'Transition', 'Establishing', 'Close-up']
    },
    {
      key: 'metadata.tags',
      label: 'Tags',
      type: 'tags',
      placeholder: 'Ajouter des tags...'
    }
  ], []);

  /**
   * Valeurs communes entre les plans sélectionnés
   */
  const commonValues = useMemo(() => {
    const values: Record<string, unknown> = {};

    for (const field of fields) {
      const fieldValues = selectedShots.map(shot => {
        if (field.key.includes('.')) {
          const [parent, child] = field.key.split('.');
          return (shot as any)[parent]?.[child];
        }
        return (shot as any)[field.key];
      });

      // Vérifier si toutes les valeurs sont identiques
      const firstValue = fieldValues[0];
      const allSame = fieldValues.every(v =>
        JSON.stringify(v) === JSON.stringify(firstValue)
      );

      if (allSame) {
        values[field.key] = firstValue;
      } else {
        values[field.key] = null; // Valeurs mixtes
      }
    }

    return values;
  }, [selectedShots, fields]);

  /**
   * Met à jour un champ
   */
  const handleFieldChange = useCallback((key: string, value: unknown) => {
    setChanges(prev => ({
      ...prev,
      [key]: value
    }));
  }, []);

  /**
   * Applique les changements
   */
  const handleApply = useCallback(() => {
    const updates: Partial<Shot> = {};

    for (const [key, value] of Object.entries(changes)) {
      if (key.includes('.')) {
        const [parent, child] = key.split('.');
        if (!updates[parent as keyof Shot]) {
          (updates as any)[parent] = {};
        }
        (updates as any)[parent][child] = value;
      } else {
        (updates as any)[key] = value;
      }
    }

    onApply(updates);
  }, [changes, onApply]);

  /**
   * Prévisualise les changements sur un plan
   */
  const previewShot = useMemo(() => {
    if (!showPreview || selectedShots.length === 0) {
      return null;
    }

    const shot = selectedShots[previewIndex];
    const preview = { ...shot };

    for (const [key, value] of Object.entries(changes)) {
      if (key.includes('.')) {
        const [parent, child] = key.split('.');
        if (!preview[parent as keyof Shot]) {
          (preview as any)[parent] = {};
        }
        (preview as any)[parent][child] = value;
      } else {
        (preview as any)[key] = value;
      }
    }

    return preview;
  }, [showPreview, selectedShots, previewIndex, changes]);

  /**
   * Nombre de changements
   */
  const changeCount = Object.keys(changes).length;

  /**
   * Rend un champ d'édition
   */
  const renderField = (field: MetadataField) => {
    const currentValue = changes[field.key] ?? commonValues[field.key];
    const hasChange = field.key in changes;
    const isMixed = commonValues[field.key] === null && !hasChange;

    return (
      <div key={field.key} className={`metadata-field ${hasChange ? 'has-change' : ''}`}>
        <label className="field-label">
          {field.label}
          {isMixed && <span className="mixed-indicator">(Valeurs mixtes)</span>}
        </label>

        {field.type === 'text' && (
          <input
            type="text"
            className="field-input"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, e.target.value)}
            placeholder={field.placeholder}
          />
        )}

        {field.type === 'number' && (
          <input
            type="number"
            className="field-input"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, parseFloat(e.target.value))}
            placeholder={field.placeholder}
          />
        )}

        {field.type === 'select' && (
          <select
            className="field-select"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, e.target.value)}
          >
            <option value="">-- Sélectionner --</option>
            {field.options?.map(option => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </select>
        )}

        {field.type === 'tags' && (
          <input
            type="text"
            className="field-input"
            value={Array.isArray(currentValue) ? currentValue.join(', ') : ''}
            onChange={(e) => {
              const tags = e.target.value.split(',').map(t => t.trim()).filter(Boolean);
              handleFieldChange(field.key, tags);
            }}
            placeholder={field.placeholder}
          />
        )}

        {hasChange && (
          <button
            className="reset-field-button"
            onClick={() => {
              setChanges(prev => {
                const next = { ...prev };
                delete next[field.key];
                return next;
              });
            }}
            title="Réinitialiser"
          >
            <X size={14} />
          </button>
        )}
      </div>
    );
  };

  return (
    <motion.div
      className="bulk-metadata-editor-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onCancel}
    >
      <motion.div
        className="bulk-metadata-editor"
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.9, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* En-tête */}
        <div className="editor-header">
          <div className="header-info">
            <h2>Édition groupée</h2>
            <span className="selection-info">
              {selectedShots.length} plan{selectedShots.length > 1 ? 's' : ''} sélectionné{selectedShots.length > 1 ? 's' : ''}
            </span>
          </div>
          <button
            className="close-button"
            onClick={onCancel}
            aria-label="Fermer"
          >
            <X size={20} />
          </button>
        </div>

        {/* Contenu */}
        <div className="editor-content">
          {/* Champs d'édition */}
          <div className="fields-section">
            <h3>Métadonnées</h3>
            <div className="fields-list">
              {fields.map(renderField)}
            </div>
          </div>

          {/* Prévisualisation */}
          {showPreview && previewShot && (
            <div className="preview-section">
              <div className="preview-header">
                <h3>Prévisualisation</h3>
                <div className="preview-navigation">
                  <button
                    onClick={() => setPreviewIndex(Math.max(0, previewIndex - 1))}
                    disabled={previewIndex === 0}
                  >
                    ←
                  </button>
                  <span>
                    {previewIndex + 1} / {selectedShots.length}
                  </span>
                  <button
                    onClick={() => setPreviewIndex(Math.min(selectedShots.length - 1, previewIndex + 1))}
                    disabled={previewIndex === selectedShots.length - 1}
                  >
                    →
                  </button>
                </div>
              </div>

              <div className="preview-content">
                <div className="preview-item">
                  <strong>Titre:</strong>
                  <span>{previewShot.title}</span>
                </div>
                <div className="preview-item">
                  <strong>Description:</strong>
                  <span>{previewShot.description}</span>
                </div>
                <div className="preview-item">
                  <strong>Durée:</strong>
                  <span>{previewShot.duration}s</span>
                </div>
                {previewShot.metadata?.category && (
                  <div className="preview-item">
                    <strong>Catégorie:</strong>
                    <span>{(previewShot.metadata as any).category}</span>
                  </div>
                )}
                {previewShot.metadata?.tags && (
                  <div className="preview-item">
                    <strong>Tags:</strong>
                    <span>{(previewShot.metadata as any).tags.join(', ')}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Pied de page */}
        <div className="editor-footer">
          <div className="footer-info">
            {changeCount > 0 ? (
              <span className="change-count">
                <AlertCircle size={16} />
                {changeCount} changement{changeCount > 1 ? 's' : ''}
              </span>
            ) : (
              <span className="no-changes">Aucun changement</span>
            )}
          </div>

          <div className="footer-actions">
            <button
              className="preview-button"
              onClick={() => setShowPreview(!showPreview)}
              disabled={changeCount === 0}
            >
              <Eye size={16} />
              {showPreview ? 'Masquer' : 'Prévisualiser'}
            </button>

            <button
              className="cancel-button"
              onClick={onCancel}
            >
              Annuler
            </button>

            <button
              className="apply-button"
              onClick={handleApply}
              disabled={changeCount === 0}
            >
              <Check size={16} />
              Appliquer
            </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

/**
 * CameraAngleEditor Component
 * 
 * Main editor interface for AI-powered camera angle generation.
 * Combines source image preview, angle preset selector, generation options,
 * and results grid into a cohesive editing experience.
 * 
 * Usage:
 * ```tsx
 * <CameraAngleEditor
 *   initialImageId="image-123"
 *   initialImagePath="/path/to/image.jpg"
 *   onGenerationComplete={(results) => handleResults(results)}
 * />
 * ```
 */

import React, { useEffect, useCallback } from 'react';
import {
  Image as ImageIcon,
  Sparkles,
  Settings2,
  X,
  Upload,
  RefreshCw,
  Wand2,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useCameraAngleGeneration } from '@/hooks/useCameraAngleGeneration';
import { AnglePresetSelector } from './AnglePresetSelector';
import { ResultsGrid } from './ResultsGrid';
import type {
  CameraAngleResult,
  CameraAngleQuality,
} from '@/types/cameraAngle';

// ============================================================================
// Types
// ============================================================================

export interface CameraAngleEditorProps {
  /** Initial image ID (for reference) */
  initialImageId?: string;
  /** Initial image path or URL */
  initialImagePath?: string;
  /** Callback when generation completes */
  onGenerationComplete?: (results: CameraAngleResult[]) => void;
  /** Callback when generation fails */
  onGenerationError?: (error: string) => void;
  /** Callback when editor closes (optional) */
  onClose?: () => void;
  /** Additional CSS classes */
  className?: string;
  /** Show header with title */
  showHeader?: boolean;
  /** Show options panel */
  showOptions?: boolean;
}

// ============================================================================
// Component
// ============================================================================

export const CameraAngleEditor: React.FC<CameraAngleEditorProps> = ({
  initialImageId,
  initialImagePath,
  onGenerationComplete,
  onGenerationError,
  onClose,
  className,
  showHeader = true,
  showOptions = true,
}) => {
  // Use the camera angle generation hook
  const {
    job,
    presets,
    selectedAngles,
    sourceImage,
    options,
    error,
    isGenerating,
    hasResults,
    startGeneration,
    cancelGeneration,
    reset,
    setSourceImageFromUrl,
    setSourceImageFromFile,
    setSourceImage,
    toggleAngle,
    setSelectedAngles,
    selectAllAngles,
    clearAngleSelection,
    setOptions,
    clearError,
    downloadResult,
    downloadAllResults,
  } = useCameraAngleGeneration({
    onGenerationComplete,
    onGenerationError,
  });

  /**
   * Load initial image on mount
   */
  useEffect(() => {
    if (initialImagePath && !sourceImage) {
      setSourceImageFromUrl(initialImagePath).catch((err) => {
        console.error('Failed to load initial image:', err);
      });
    }
  }, [initialImagePath, sourceImage, setSourceImageFromUrl]);

  /**
   * Handle file upload
   */
  const handleFileUpload = useCallback(
    async (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      try {
        await setSourceImageFromFile(file);
      } catch (err) {
        console.error('Failed to load file:', err);
      }
    },
    [setSourceImageFromFile]
  );

  /**
   * Handle generate button click
   */
  const handleGenerate = useCallback(async () => {
    if (isGenerating) {
      await cancelGeneration();
    } else {
      await startGeneration();
    }
  }, [isGenerating, cancelGeneration, startGeneration]);

  /**
   * Handle retry after error
   */
  const handleRetry = useCallback(() => {
    clearError();
    startGeneration();
  }, [clearError, startGeneration]);

  /**
   * Handle quality change
   */
  const handleQualityChange = useCallback(
    (value: string) => {
      setOptions({ quality: value as CameraAngleQuality });
    },
    [setOptions]
  );

  /**
   * Handle custom prompt change
   */
  const handleCustomPromptChange = useCallback(
    (event: React.ChangeEvent<HTMLTextAreaElement>) => {
      setOptions({ customPrompt: event.target.value || null });
    },
    [setOptions]
  );

  /**
   * Handle preserve style toggle
   */
  const handlePreserveStyleChange = useCallback(
    (checked: boolean) => {
      setOptions({ preserveStyle: checked });
    },
    [setOptions]
  );

  /**
   * Handle reset
   */
  const handleReset = useCallback(() => {
    reset();
    if (initialImagePath) {
      setSourceImageFromUrl(initialImagePath).catch(console.error);
    }
  }, [reset, initialImagePath, setSourceImageFromUrl]);

  // Determine if generate button should be disabled
  const isGenerateDisabled = !sourceImage || selectedAngles.length === 0;

  return (
    <div className={cn('flex flex-col h-full', className)}>
      {/* Header */}
      {showHeader && (
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 dark:border-gray-700">
          <div className="flex items-center gap-2">
            <Wand2 className="w-5 h-5 text-primary" />
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Camera Angle Editor
            </h2>
          </div>
          {onClose && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              <X className="w-5 h-5" />
            </Button>
          )}
        </div>
      )}

      {/* Main content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {/* Source Image Section */}
        <section>
          <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">
            Source Image
          </h3>
          <div className="flex gap-4">
            {/* Image preview */}
            <div className="relative w-40 h-40 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 overflow-hidden bg-gray-50 dark:bg-gray-800 flex-shrink-0">
              {sourceImage ? (
                <img
                  src={
                    sourceImage.startsWith('data:')
                      ? sourceImage
                      : `data:image/png;base64,${sourceImage}`
                  }
                  alt="Source image"
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400">
                  <ImageIcon className="w-8 h-8 mb-2" />
                  <span className="text-xs">No image</span>
                </div>
              )}
            </div>

            {/* Upload controls */}
            <div className="flex-1 flex flex-col justify-center gap-2">
              <label className="cursor-pointer">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  className="hidden"
                  disabled={isGenerating}
                />
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full"
                  disabled={isGenerating}
                  asChild
                >
                  <span>
                    <Upload className="w-4 h-4 mr-2" />
                    Upload Image
                  </span>
                </Button>
              </label>
              {sourceImage && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setSourceImage(null)}
                  disabled={isGenerating}
                  className="text-gray-500"
                >
                  <X className="w-4 h-4 mr-2" />
                  Clear Image
                </Button>
              )}
            </div>
          </div>
        </section>

        {/* Angle Preset Selector */}
        <section>
          <AnglePresetSelector
            presets={presets}
            selectedAngles={selectedAngles}
            onAngleToggle={toggleAngle}
            onSelectAll={selectAllAngles}
            onClearSelection={clearAngleSelection}
            disabled={isGenerating}
            columns={4}
          />
        </section>

        {/* Generation Options */}
        {showOptions && (
          <section>
            <div className="flex items-center gap-2 mb-3">
              <Settings2 className="w-4 h-4 text-gray-500" />
              <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                Generation Options
              </h3>
            </div>
            <div className="space-y-4 p-4 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
              {/* Preserve Style */}
              <div className="flex items-center justify-between">
                <Label
                  htmlFor="preserve-style"
                  className="text-sm text-gray-700 dark:text-gray-300"
                >
                  Preserve Original Style
                </Label>
                <Switch
                  id="preserve-style"
                  checked={options.preserveStyle}
                  onCheckedChange={handlePreserveStyleChange}
                  disabled={isGenerating}
                />
              </div>

              {/* Quality */}
              <div className="space-y-2">
                <Label
                  htmlFor="quality"
                  className="text-sm text-gray-700 dark:text-gray-300"
                >
                  Quality
                </Label>
                <Select
                  value={options.quality}
                  onValueChange={handleQualityChange}
                  disabled={isGenerating}
                >
                  <SelectTrigger id="quality" className="w-full">
                    <SelectValue placeholder="Select quality" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">Draft (Fast)</SelectItem>
                    <SelectItem value="standard">Standard</SelectItem>
                    <SelectItem value="high">High (Slow)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Custom Prompt */}
              <div className="space-y-2">
                <Label
                  htmlFor="custom-prompt"
                  className="text-sm text-gray-700 dark:text-gray-300"
                >
                  Custom Prompt (Optional)
                </Label>
                <Textarea
                  id="custom-prompt"
                  placeholder="Add additional instructions for the AI..."
                  value={options.customPrompt || ''}
                  onChange={handleCustomPromptChange}
                  disabled={isGenerating}
                  rows={3}
                  className="resize-none"
                />
              </div>
            </div>
          </section>
        )}

        {/* Results Grid */}
        <section>
          <ResultsGrid
            results={job.results}
            presets={presets}
            onDownload={downloadResult}
            onDownloadAll={downloadAllResults}
            isLoading={isGenerating}
            progress={job.progress}
            currentStep={job.currentStep}
            error={error || job.error}
            onRetry={handleRetry}
            columns={3}
          />
        </section>
      </div>

      {/* Footer with action buttons */}
      <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
        <Button
          variant="outline"
          size="sm"
          onClick={handleReset}
          disabled={isGenerating}
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          Reset
        </Button>

        <Button
          size="sm"
          onClick={handleGenerate}
          disabled={isGenerateDisabled && !isGenerating}
          className="min-w-[140px]"
        >
          {isGenerating ? (
            <>
              <X className="w-4 h-4 mr-2" />
              Cancel
            </>
          ) : (
            <>
              <Sparkles className="w-4 h-4 mr-2" />
              Generate ({selectedAngles.length})
            </>
          )}
        </Button>
      </div>
    </div>
  );
};

