/**
 * Caption Styles Panel Component
 * MI2: Caption Styles - Modern, Classic, Dynamic
 */

import React, { useState, useEffect } from 'react';
import { useCaptionStyleStore } from '../../stores/captionStyleStore';
import { captionStylesService } from '../../services/CaptionStylesService';
import { CaptionStyle } from '../../types/caption-style';
import styles from './CaptionStylesPanel.module.css';

type StyleCategory = 'modern' | 'classic' | 'dynamic' | 'all';

export const CaptionStylesPanel: React.FC = () => {
  const {
    builtInStyles,
    userPresets,
    favoriteStyleIds,
    recentStyles,
    activeTrack,
    selectedStyleId,
    previewMode,
    isPanelOpen,
    isStyleEditorOpen,
    applyStyleToTrack,
    togglePanel,
    toggleStyleEditor,
    setPreviewMode,
    selectStyle,
  } = useCaptionStyleStore();

  const [activeCategory, setActiveCategory] = useState<StyleCategory>('all');
  const [previewText, setPreviewText] = useState('Hello, World!');
  const [selectedStyle, setSelectedStyle] = useState<CaptionStyle | null>(null);

  // Load built-in styles on mount
  useEffect(() => {
    captionStylesService.getAllStyles().forEach((style) => {
      useCaptionStyleStore.getState().registerBuiltInStyle(style);
    });
  }, []);

  // Combine built-in and user presets
  const allStyles = [...builtInStyles, ...userPresets.map((p) => ({
    ...p,
    id: p.styleId,
  } as CaptionStyle))];

  const filteredStyles = activeCategory === 'all'
    ? allStyles
    : allStyles.filter((s) => s.category === activeCategory);

  const handleStyleClick = (style: CaptionStyle) => {
    setSelectedStyle(style);
    selectStyle(style.id);
  };

  const handleApplyStyle = (style: CaptionStyle) => {
    if (activeTrack) {
      applyStyleToTrack(style.id, activeTrack.id);
    }
  };

  const toggleFavorite = (styleId: string) => {
    if (favoriteStyleIds.includes(styleId)) {
      useCaptionStyleStore.getState().removeFromFavorites(styleId);
    } else {
      useCaptionStyleStore.getState().addToFavorites(styleId);
    }
  };

  const categories = [
    { id: 'all', label: 'All', icon: '📝' },
    { id: 'modern', label: 'Modern', icon: '✨' },
    { id: 'classic', label: 'Classic', icon: '📜' },
    { id: 'dynamic', label: 'Dynamic', icon: '🎭' },
  ];

  if (!isPanelOpen) {
    return (
      <button className={styles.toggleButton} onClick={togglePanel}>
        💬 Captions
      </button>
    );
  }

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3>Caption Styles</h3>
        <div className={styles.headerActions}>
          <button
            className={`${styles.actionBtn} ${previewMode ? styles.active : ''}`}
            onClick={() => setPreviewMode(!previewMode)}
            title="Preview Mode"
          >
            👁
          </button>
          <button
            className={styles.actionBtn}
            onClick={toggleStyleEditor}
            title="Style Editor"
          >
            ✏️
          </button>
          <button className={styles.closeButton} onClick={togglePanel}>
            ×
          </button>
        </div>
      </div>

      <div className={styles.content}>
        {/* Preview Text Input */}
        <div className={styles.previewInput}>
          <input
            type="text"
            value={previewText}
            onChange={(e) => setPreviewText(e.target.value)}
            placeholder="Enter preview text..."
            className={styles.textInput}
          />
        </div>

        {/* Category Tabs */}
        <div className={styles.categories}>
          {categories.map((cat) => (
            <button
              key={cat.id}
              className={`${styles.categoryTab} ${
                activeCategory === cat.id ? styles.active : ''
              }`}
              onClick={() => setActiveCategory(cat.id as StyleCategory)}
            >
              <span className={styles.catIcon}>{cat.icon}</span>
              <span className={styles.catLabel}>{cat.label}</span>
            </button>
          ))}
        </div>

        {/* Styles Grid */}
        <div className={styles.stylesGrid}>
          {filteredStyles.map((style) => (
            <div
              key={style.id}
              className={`${styles.styleCard} ${
                selectedStyleId === style.id ? styles.selected : ''
              }`}
              onClick={() => handleStyleClick(style)}
            >
              {/* Style Preview */}
              <div
                className={styles.stylePreview}
                style={getStylePreviewStyle(style)}
              >
                <span style={getStyleTextStyle(style)}>{previewText}</span>
              </div>

              <div className={styles.styleInfo}>
                <h4 className={styles.styleName}>{style.name}</h4>
                <p className={styles.styleDesc}>{style.description}</p>
              </div>

              <div className={styles.styleActions}>
                <button
                  className={`${styles.favBtn} ${
                    favoriteStyleIds.includes(style.id) ? styles.active : ''
                  }`}
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleFavorite(style.id);
                  }}
                >
                  {favoriteStyleIds.includes(style.id) ? '★' : '☆'}
                </button>
                <button
                  className={styles.applyBtn}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleApplyStyle(style);
                  }}
                  disabled={!activeTrack}
                >
                  Apply
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Recently Used */}
        {recentStyles.length > 0 && (
          <div className={styles.section}>
            <h4 className={styles.sectionTitle}>Recently Used</h4>
            <div className={styles.recentList}>
              {recentStyles.slice(0, 5).map((styleId) => {
                const style = allStyles.find((s) => s.id === styleId);
                if (!style) return null;
                return (
                  <button
                    key={styleId}
                    className={styles.recentItem}
                    onClick={() => handleApplyStyle(style)}
                    disabled={!activeTrack}
                  >
                    <span style={getStyleTextStyle(style)}>Aa</span>
                    <span>{style.name}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Active Track Info */}
        {activeTrack && (
          <div className={styles.trackInfo}>
            <span>Active Track:</span>
            <strong>{activeTrack.name}</strong>
            <span className={styles.trackLang}>{activeTrack.language}</span>
          </div>
        )}

        {/* Preview Mode */}
        {previewMode && selectedStyle && (
          <div className={styles.fullPreview}>
            <div className={styles.fullPreviewContent}>
              <div
                className={styles.previewCard}
                style={getStylePreviewStyle(selectedStyle)}
              >
                <span style={getStyleTextStyle(selectedStyle)}>
                  {previewText}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Helper function to generate preview style for cards
function getStylePreviewStyle(style: CaptionStyle): React.CSSProperties {
  return {
    background: style.background.enabled
      ? `rgba(0, 0, 0, ${style.background.opacity / 100})`
      : 'transparent',
    padding: style.background.padding,
    borderRadius: style.background.cornerRadius,
  };
}

// Helper function to generate text style
function getStyleTextStyle(style: CaptionStyle): React.CSSProperties {
  return {
    fontFamily: style.font.family,
    fontSize: `${style.font.size}px`,
    fontWeight: style.font.weight,
    fontStyle: style.font.style,
    color: style.textAppearance.color,
    textShadow: style.textAppearance.shadow
      ? `${style.textAppearance.shadow.offsetX}px ${style.textAppearance.shadow.offsetY}px ${style.textAppearance.shadow.blur}px rgba(0, 0, 0, ${style.textAppearance.shadow.opacity / 100})`
      : 'none',
    textTransform: style.font.textTransform,
    letterSpacing: `${style.font.letterSpacing}px`,
    lineHeight: style.font.lineHeight,
  };
}

export default CaptionStylesPanel;

import React, { useState, useEffect, useCallback } from 'react';
import { Edit2, Trash2, User, Image as ImageIcon, Loader2, RefreshCw } from 'lucide-react';
import type { Character } from '@/types/character';
import { ComfyUIService } from '@/services/comfyuiService';
import { useAppStore } from '@/stores/useAppStore';
import { downloadAndSaveImage, getImageDisplayUrl } from '@/services/imageStorageService';
import { devLog, devWarn } from '@/utils/devOnly';
import { logger } from '@/utils/logger';
import './CharacterCard.css';

/**
 * Props for the CharacterCard component
 * Requirements: 1.2, 1.4, 2.1, 4.2
 */
export interface CharacterCardProps {
  /** The character to display */
  character: Character;

  /** Optional click handler for the card */
  onClick?: () => void;

  /** Whether the card is in selection mode (for Story Generator) */
  selectable?: boolean;

  /** Whether the card is currently selected */
  selected?: boolean;

  /** Handler for selection changes */
  onSelect?: (selected: boolean) => void;

  /** Whether to show action buttons (edit, delete) */
  showActions?: boolean;

  /** Handler for edit button click */
  onEdit?: () => void;

  /** Handler for delete button click */
  onDelete?: () => void;

  /** Handler for image generation */
  /** Handler for image generation */
  onImageGenerated?: (imageUrl: string, prompt?: string) => void | Promise<void>;

  /** Whether the card is in loading state */
  loading?: boolean;
}

/**
 * CharacterCard Component
 * 
 * Displays a character summary card with thumbnail, name, archetype, age range,
 * and creation date. Supports selection mode for Story Generator and action buttons
 * for editing and deletion.
 * 
 * Requirements:
 * - Req 1.2: Display character name, archetype, age range, creation date
 * - Req 1.4: Display thumbnail if available
 * - Req 2.1: Edit button functionality
 * - Req 4.2: Selection mode for Story Generator
 */
export const CharacterCard = React.memo<CharacterCardProps>(({
  character,
  onClick,
  selectable = false,
  selected = false,
  onSelect,
  showActions = false,
  onEdit,
  onDelete,
  onImageGenerated,
  loading = false,
}) => {
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [displayImageUrl, setDisplayImageUrl] = useState<string | null>(null);

  const comfyuiService = ComfyUIService.getInstance();
  const project = useAppStore((state) => state.project);

  // Get visual style from project
  const visualStyle = (project as any)?.visualStyle || (project as any)?.visual_style || 'realistic';

  // Load display URL for saved portrait
  useEffect(() => {
    const loadDisplayUrl = async () => {
      // Priority 1: Generated image URL (temporary, from current session)
      if (generatedImageUrl) {
        setDisplayImageUrl(generatedImageUrl);
        return;
      }

      // Priority 2: Saved portrait path (persistent)
      if (character.visual_identity?.generated_portrait) {
        const portraitPath = character.visual_identity.generated_portrait;
        const url = await getImageDisplayUrl(
          typeof portraitPath === 'string' ? portraitPath : String(portraitPath),
          project?.metadata?.path as string | undefined
        );
        if (url) {
          setDisplayImageUrl(url);
          return;
        }
      }

      // Priority 3: Legacy thumbnail_url
      if ((character as any).thumbnail_url) {
        setDisplayImageUrl((character as any).thumbnail_url);
        return;
      }

      // No image available
      setDisplayImageUrl(null);
    };

    loadDisplayUrl();
  }, [character, generatedImageUrl, project?.metadata?.path]);
  // Format creation date
  const formatDate = (timestamp: string): string => {
    try {
      const date = new Date(timestamp);
      // Check if date is valid
      if (Number.isNaN(date.getTime())) {
        return 'Unknown date';
      }
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });
    } catch {
      return 'Unknown date';
    }
  };

  // Handle card click
  const handleCardClick = useCallback(() => {
    if (selectable && onSelect) {
      onSelect(!selected);
    } else if (onClick) {
      onClick();
    }
  }, [selectable, onSelect, selected, onClick]);

  // Handle checkbox change
  const handleCheckboxChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    e.stopPropagation();
    if (onSelect) {
      onSelect(e.target.checked);
    }
  }, [onSelect]);

  // Handle edit button click
  const handleEditClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) {
      onEdit();
    }
  }, [onEdit]);

  // Handle delete button click
  const handleDeleteClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete) {
      onDelete();
    }
  }, [onDelete]);

  // Get thumbnail URL from visual identity or use placeholder
  const thumbnailUrl = displayImageUrl;

  /**
   * Build visual style prefix for prompt
   */
  const buildStylePrefix = (): string => {
    const styleMap: Record<string, string> = {
      'photorealistic': 'photorealistic',
      'cinematic': 'cinematic',
      'anime': 'anime style',
      'cartoon': 'cartoon style',
      'sketch': 'sketch art',
      'oil-painting': 'oil painting',
      'watercolor': 'watercolor painting',
      'digital-art': 'digital art',
      'comic-book': 'comic book style',
      'noir': 'film noir style',
      'vintage': 'vintage style',
      'modern': 'modern style',
      'minimalist': 'minimalist style',
      'realistic': 'realistic'
    };
    return styleMap[visualStyle] || visualStyle;
  };

  /**
   * Build visual identity details for prompt
   */
  const buildVisualDetails = (): string[] => {
    const details: string[] = [];
    const visual = character.visual_identity;

    if (!visual) return details;

    // Face and hair
    if (visual.hair_color && visual.hair_style) {
      details.push(`${visual.hair_color} ${visual.hair_style} hair`);
    } else if (visual.hair_color) {
      details.push(`${visual.hair_color} hair`);
    }

    if (visual.eye_color) {
      details.push(`${visual.eye_color} eyes`);
    }

    if (visual.facial_structure) {
      details.push(`${visual.facial_structure} face`);
    }

    // Skin and build
    if (visual.skin_tone) {
      details.push(`${visual.skin_tone} skin`);
    }

    if (visual.build) {
      details.push(`${visual.build} build`);
    }

    // Clothing
    if (visual.clothing_style) {
      details.push(`wearing ${visual.clothing_style} clothing`);
    }

    // Distinctive features
    if (visual.distinctive_features && visual.distinctive_features.length > 0) {
      details.push(visual.distinctive_features.join(', '));
    }

    return details;
  };

  /**
   * Build a detailed prompt from character data
   */
  const buildCharacterPrompt = (): string => {
    const parts: string[] = [buildStylePrefix()];
    parts.push(`Portrait of ${character.name}`);
    const visualDetails = buildVisualDetails();
    for (const detail of visualDetails) {
      parts.push(detail);
    }
    parts.push('high quality', 'detailed', 'professional portrait', 'centered composition');
    return parts.join(', ');
  };

  /**
   * Build negative prompt to avoid unwanted elements
   */
  const buildNegativePrompt = (): string => {
    return [
      'blurry',
      'low quality',
      'distorted',
      'deformed',
      'ugly',
      'bad anatomy',
      'watermark',
      'text',
      'signature',
      'multiple people',
      'full body',
      'background clutter',
    ].join(', ');
  };

  /**
   * Handle image generation with automatic model detection and local storage
   */
  const handleGenerateImage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsGeneratingImage(true);
    let prompt = ''; // Captured for persistence

    try {
      prompt = buildCharacterPrompt();
      const negativePrompt = buildNegativePrompt();

      devLog('🎨 [CharacterCard] Starting image generation');
      devLog('📝 Prompt:', prompt);
      devLog('🚫 Negative:', negativePrompt);
      devLog('🎭 Visual Style:', visualStyle);

      // Flux Turbo parameters (Z-Image Turbo workflow)
      const imageUrl = await comfyuiService.generateImage({
        prompt,
        negativePrompt,
        width: 784,
        height: 1024,
        steps: 4,
        cfgScale: 1,
        seed: Math.floor(Math.random() * 1000000),
        model: 'z_image_turbo_bf16.safetensors', // Not used in Flux Turbo workflow
        sampler: 'res_multistep',
        scheduler: 'simple',
      });

      devLog('✅ [CharacterCard] Image generated:', imageUrl);
      setGeneratedImageUrl(imageUrl);

      // Download and save image to project folder
      const projectPath = project?.metadata?.path as string | undefined;
      if (projectPath) {
        devLog('💾 [CharacterCard] Saving image to project folder...');
        const saveResult = await downloadAndSaveImage(
          imageUrl,
          character.character_id,
          projectPath
        );

        if (saveResult.success && saveResult.localPath) {
          devLog('✅ [CharacterCard] Image saved locally:', saveResult.localPath);

          // Notify parent component to update character data
          if (onImageGenerated) {
            onImageGenerated(saveResult.localPath, prompt);
          }
        } else {
          devWarn('⚠️ [CharacterCard] Failed to save image locally:', saveResult.error);
          // Still show the image from ComfyUI URL
          if (onImageGenerated) {
            onImageGenerated(imageUrl, prompt);
          }
        }
      } else {
        devWarn('⚠️ [CharacterCard] No project path available, image not saved locally');
        // Fallback: just notify with ComfyUI URL
        if (onImageGenerated) {
          onImageGenerated(imageUrl, prompt);
        }
      }
    } catch (err) {
      logger.error('❌ [CharacterCard] Failed to generate character portrait:', err);

      // Show user-friendly error message
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';

      // Set a placeholder image with error message
      setGeneratedImageUrl(
        `data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256"><rect fill="%23f0f0f0" width="256" height="256"/><text x="50%" y="40%" text-anchor="middle" fill="%23999" font-size="14" font-weight="bold">Generation Failed</text><text x="50%" y="55%" text-anchor="middle" fill="%23666" font-size="10">Check ComfyUI settings</text><text x="50%" y="65%" text-anchor="middle" fill="%23666" font-size="8">${encodeURIComponent(errorMessage.substring(0, 40))}</text></svg>`
      );

      // You can also show a toast notification here if you have a notification system
      devWarn('💡 [CharacterCard] To fix: 1) Start ComfyUI 2) Configure in Settings > ComfyUI 3) Test connection');
    } finally {
      setIsGeneratingImage(false);
    }
  };

  // Loading skeleton
  if (loading) {
    return (
      <div className="character-card character-card--loading">
        <div className="character-card__skeleton">
          <div className="character-card__skeleton-thumbnail" />
          <div className="character-card__skeleton-content">
            <div className="character-card__skeleton-line character-card__skeleton-line--title" />
            <div className="character-card__skeleton-line character-card__skeleton-line--subtitle" />
            <div className="character-card__skeleton-line character-card__skeleton-line--text" />
          </div>
        </div>
      </div>
    );
  }

  // Determine if card is clickable
  const isClickable = !!(onClick || selectable);

  // Render the card content
  const renderCardContent = () => (
    <>
      {/* Thumbnail */}
      <div className="character-card__thumbnail">
        {thumbnailUrl ? (
          <div className="character-card__thumbnail-wrapper">
            <img
              src={thumbnailUrl}
              alt={`${character.name} thumbnail`}
              className="character-card__thumbnail-image"
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                target.style.display = 'none';
                const parent = target.parentElement;
                if (parent) {
                  const placeholder = document.createElement('div');
                  placeholder.className = 'character-card__thumbnail-placeholder';
                  placeholder.innerHTML = '<svg class="character-card__thumbnail-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>';
                  parent.appendChild(placeholder);
                }
              }}
            />
          </div>
        ) : (
          <div className="character-card__thumbnail-placeholder">
            <User className="character-card__thumbnail-icon" />
          </div>
        )}
      </div>

      {/* Content */}
      <div className="character-card__content">
        <div className="character-card__header">
          <h3 className="character-card__name">{character.name || 'Unnamed Character'}</h3>
          <p className="character-card__archetype">{character.role?.archetype || 'Unspecified'}</p>
        </div>

        <div className="character-card__details">
          <div className="character-card__detail">
            <span className="character-card__detail-label">Age:</span>
            <span className="character-card__detail-value">
              {character.visual_identity?.age_range || 'Not specified'}
            </span>
          </div>
          <div className="character-card__detail">
            <span className="character-card__detail-label">Created:</span>
            <span className="character-card__detail-value">
              {formatDate(character.creation_timestamp)}
            </span>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div
      className={`
        character-card
        ${selectable ? 'character-card--selectable' : ''}
        ${selected ? 'character-card--selected' : ''}
        ${isClickable ? 'character-card--clickable' : ''}
      `}
    >
      {/* Selection checkbox - outside clickable area */}
      {selectable && (
        <div className="character-card__checkbox">
          <input
            type="checkbox"
            checked={selected}
            onChange={handleCheckboxChange}
            aria-label={`Select ${character.name}`}
          />
        </div>
      )}

      {/* Main clickable area */}
      {isClickable ? (
        <button
          type="button"
          className="character-card__main-button"
          onClick={handleCardClick}
          aria-label={onClick ? `${character.name}` : `${character.name} - click to select`}
        >
          {renderCardContent()}
        </button>
      ) : (
        <div className="character-card__main">
          {renderCardContent()}
        </div>
      )}

      {/* Generate image button - outside clickable area */}
      <div className="character-card__generate">
        {thumbnailUrl ? (
          <button
            className="character-card__regenerate-button"
            onClick={handleGenerateImage}
            title="Regenerate character portrait with ComfyUI"
            aria-label={`Regenerate portrait for ${character.name}`}
            disabled={isGeneratingImage}
          >
            <RefreshCw size={16} className={isGeneratingImage ? 'character-card__spinner' : ''} />
            {isGeneratingImage && <span>Regenerating...</span>}
          </button>
        ) : (
          !isGeneratingImage && (
            <button
              className="character-card__generate-button"
              onClick={handleGenerateImage}
              title="Generate character portrait with ComfyUI"
              aria-label={`Generate portrait for ${character.name}`}
            >
              <ImageIcon size={20} />
              <span>Generate Portrait</span>
            </button>
          )
        )}
        {isGeneratingImage && (
          <div className="character-card__generating">
            <Loader2 size={20} className="character-card__spinner" />
            <span>Generating...</span>
          </div>
        )}
      </div>

      {/* Action buttons */}
      {showActions && (
        <div className="character-card__actions">
          {onEdit && (
            <button
              className="character-card__action-button character-card__action-button--edit"
              onClick={handleEditClick}
              aria-label={`Edit ${character.name}`}
              title="Edit character"
            >
              <Edit2 className="character-card__action-icon" />
            </button>
          )}
          {onDelete && (
            <button
              className="character-card__action-button character-card__action-button--delete"
              onClick={handleDeleteClick}
              aria-label={`Delete ${character.name}`}
              title="Delete character"
            >
              <Trash2 className="character-card__action-icon" />
            </button>
          )}
        </div>
      )}
    </div>
  );
});

// ============================================================================
// CharacterCard Component (Memoized)
// ============================================================================
// Performance-optimized version of CharacterCard with React.memo to prevent
// unnecessary re-renders when parent components update.
//
// Optimizations:
// - React.memo with custom comparison function
// - Memoized event handlers
// - Optimized thumbnail loading with lazy loading
// - Reduced DOM operations
//
// Requirements: 1.2, 1.4, 2.1, 4.2
// ============================================================================

import React, { memo, useCallback } from 'react';
import { Edit2, Trash2, User } from 'lucide-react';
import type { Character } from '@/types/character';
import './CharacterCard.css';

// ============================================================================
// Types
// ============================================================================

export interface CharacterCardProps {
  character: Character;
  onClick?: () => void;
  selectable?: boolean;
  selected?: boolean;
  onSelect?: (selected: boolean) => void;
  showActions?: boolean;
  onEdit?: () => void;
  onDelete?: () => void;
  loading?: boolean;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Format creation date (memoized)
 */
const formatDate = (timestamp: string): string => {
  try {
    const date = new Date(timestamp);
    if (Number.isNaN(date.getTime())) {
      return 'Unknown date';
    }
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return 'Unknown date';
  }
};

// ============================================================================
// CharacterCard Component (Memoized)
// ============================================================================

/**
 * CharacterCard Component with React.memo optimization
 * 
 * Only re-renders when:
 * - character data changes
 * - selected state changes
 * - loading state changes
 * - callback functions change (should be memoized in parent)
 */
const CharacterCardComponent = ({
  character,
  onClick,
  selectable = false,
  selected = false,
  onSelect,
  showActions = false,
  onEdit,
  onDelete,
  loading = false,
}: CharacterCardProps) => {
  // ============================================================================
  // Memoized Event Handlers
  // ============================================================================

  const handleCardClick = useCallback(() => {
    if (selectable && onSelect) {
      onSelect(!selected);
    } else if (onClick) {
      onClick();
    }
  }, [selectable, onSelect, selected, onClick]);

  const handleCheckboxChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      e.stopPropagation();
      if (onSelect) {
        onSelect(e.target.checked);
      }
    },
    [onSelect]
  );

  const handleEditClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      if (onEdit) {
        onEdit();
      }
    },
    [onEdit]
  );

  const handleDeleteClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      if (onDelete) {
        onDelete();
      }
    },
    [onDelete]
  );

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if ((e.key === 'Enter' || e.key === ' ') && (onClick || selectable)) {
        e.preventDefault();
        handleCardClick();
      }
    },
    [onClick, selectable, handleCardClick]
  );

  // ============================================================================
  // Render Helpers
  // ============================================================================

  // Get thumbnail URL
  const thumbnailUrl = (character as any).thumbnail_url || null;

  // Loading skeleton
  if (loading) {
    return (
      <div className="character-card character-card--loading">
        <div className="character-card__skeleton">
          <div className="character-card__skeleton-thumbnail" />
          <div className="character-card__skeleton-content">
            <div className="character-card__skeleton-line character-card__skeleton-line--title" />
            <div className="character-card__skeleton-line character-card__skeleton-line--subtitle" />
            <div className="character-card__skeleton-line character-card__skeleton-line--text" />
          </div>
        </div>
      </div>
    );
  }

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div
      className={`
        character-card
        ${selectable ? 'character-card--selectable' : ''}
        ${selected ? 'character-card--selected' : ''}
        ${onClick || selectable ? 'character-card--clickable' : ''}
      `}
      onClick={handleCardClick}
      role="article"
      tabIndex={onClick || selectable ? 0 : undefined}
      onKeyDown={handleKeyDown}
    >
      {/* Selection checkbox */}
      {selectable && (
        <div className="character-card__checkbox">
          <input
            type="checkbox"
            checked={selected}
            onChange={handleCheckboxChange}
            onClick={(e) => e.stopPropagation()}
            aria-label={`Select ${character.name}`}
          />
        </div>
      )}

      {/* Thumbnail with lazy loading */}
      <div className="character-card__thumbnail">
        {thumbnailUrl ? (
          <img
            src={thumbnailUrl}
            alt={`${character.name} thumbnail`}
            className="character-card__thumbnail-image"
            loading="lazy"
            onError={(e) => {
              const target = e.target as HTMLImageElement;
              target.style.display = 'none';
              const parent = target.parentElement;
              if (parent) {
                const placeholder = document.createElement('div');
                placeholder.className = 'character-card__thumbnail-placeholder';
                placeholder.innerHTML =
                  '<svg class="character-card__thumbnail-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>';
                parent.appendChild(placeholder);
              }
            }}
          />
        ) : (
          <div className="character-card__thumbnail-placeholder">
            <User className="character-card__thumbnail-icon" />
          </div>
        )}
      </div>

      {/* Content */}
      <div className="character-card__content">
        <div className="character-card__header">
          <h3 className="character-card__name">{character.name || 'Unnamed Character'}</h3>
          <p className="character-card__archetype">{character.role?.archetype || 'Unspecified'}</p>
        </div>

        <div className="character-card__details">
          <div className="character-card__detail">
            <span className="character-card__detail-label">Age:</span>
            <span className="character-card__detail-value">
              {character.visual_identity?.age_range || 'Not specified'}
            </span>
          </div>
          <div className="character-card__detail">
            <span className="character-card__detail-label">Created:</span>
            <span className="character-card__detail-value">
              {formatDate(character.creation_timestamp)}
            </span>
          </div>
        </div>
      </div>

      {/* Action buttons */}
      {showActions && (
        <div className="character-card__actions">
          {onEdit && (
            <button
              className="character-card__action-button character-card__action-button--edit"
              onClick={handleEditClick}
              aria-label={`Edit ${character.name}`}
              title="Edit character"
            >
              <Edit2 className="character-card__action-icon" />
            </button>
          )}
          {onDelete && (
            <button
              className="character-card__action-button character-card__action-button--delete"
              onClick={handleDeleteClick}
              aria-label={`Delete ${character.name}`}
              title="Delete character"
            >
              <Trash2 className="character-card__action-icon" />
            </button>
          )}
        </div>
      )}
    </div>
  );
};

// ============================================================================
// Memoization with Custom Comparison
// ============================================================================

/**
 * Custom comparison function for React.memo
 * Only re-render if these props change:
 * - character.character_id
 * - character.name
 * - character.role.archetype
 * - character.visual_identity.age_range
 * - character.creation_timestamp
 * - selected
 * - loading
 */
function arePropsEqual(
  prevProps: CharacterCardProps,
  nextProps: CharacterCardProps
): boolean {
  // Always re-render if loading state changes
  if (prevProps.loading !== nextProps.loading) {
    return false;
  }

  // If loading, don't compare character data
  if (nextProps.loading) {
    return true;
  }

  // Compare character data
  const prevChar = prevProps.character;
  const nextChar = nextProps.character;

  // Add null checks for potentially undefined properties
  const prevName = prevChar?.name ?? '';
  const nextName = nextChar?.name ?? '';
  const prevArchetype = prevChar?.role?.archetype ?? '';
  const nextArchetype = nextChar?.role?.archetype ?? '';
  const prevAgeRange = prevChar?.visual_identity?.age_range ?? '';
  const nextAgeRange = nextChar?.visual_identity?.age_range ?? '';
  const prevTimestamp = prevChar?.creation_timestamp ?? '';
  const nextTimestamp = nextChar?.creation_timestamp ?? '';

  if (
    prevChar.character_id !== nextChar.character_id ||
    prevName !== nextName ||
    prevArchetype !== nextArchetype ||
    prevAgeRange !== nextAgeRange ||
    prevTimestamp !== nextTimestamp
  ) {
    return false;
  }

  // Compare selection state
  if (prevProps.selected !== nextProps.selected) {
    return false;
  }

  // Compare selectable mode
  if (prevProps.selectable !== nextProps.selectable) {
    return false;
  }

  // Compare showActions
  if (prevProps.showActions !== nextProps.showActions) {
    return false;
  }

  // Props are equal, don't re-render
  return true;
}

// Export memoized component
export const CharacterCardMemoized = memo(CharacterCardComponent, arePropsEqual);

import React, { useState, useEffect } from 'react';
import { X, Save, Trash2, AlertTriangle } from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import { useCharacterManager } from '@/hooks/useCharacterManager';
import { BasicIdentitySection } from './editor/BasicIdentitySection';
import { AppearanceSection } from './editor/AppearanceSection';
import { PersonalitySection } from './editor/PersonalitySection';
import { BackgroundSection } from './editor/BackgroundSection';
import { RelationshipsSection } from './editor/RelationshipsSection';
import { CharacterImagesSection } from './editor/CharacterImagesSection';
import { PromptsManager } from '../common/PromptsManager';
import { buildVisualPromptForCharacter } from '@/lib/promptUtils';
import './CharacterEditor.css';

/**
 * Props for the CharacterEditor component
 * Requirements: 2.1, 2.2, 2.3, 2.4, 2.5, 2.6, 7.1, 7.2
 */
export interface CharacterEditorProps {
  /** ID of the character to edit */
  characterId: string;

  /** Handler called when editor is closed */
  onClose: () => void;

  /** Optional handler called after successful save */
  onSave?: (character: Character) => void;

  /** Optional handler called after successful deletion */
  onDelete?: (characterId: string) => void;
}

type TabId = 'identity' | 'appearance' | 'personality' | 'background' | 'relationships' | 'images' | 'prompts';

interface ValidationErrors {
  [key: string]: string[];
}

/**
 * CharacterEditor Component
 * 
 * Modal interface for editing existing characters with tabbed sections,
 * validation, unsaved changes detection, and dependency checking.
 * 
 * Requirements:
 * - Req 2.1: Opens when user clicks on character
 * - Req 2.2: Displays all character fields in editable form
 * - Req 2.3: Validates changes before saving
 * - Req 2.4: Displays specific error messages
 * - Req 2.5: Updates store and persistence on save
 * - Req 2.6: Discards unsaved changes on cancel
 * - Req 7.1: Checks dependencies before deletion
 * - Req 7.2: Displays warning for dependencies
 */
export function CharacterEditor({
  characterId,
  onClose,
  onSave,
  onDelete,
}: CharacterEditorProps) {
  const project = useAppStore((state) => state.project);
  const characterManager = useCharacterManager();
  const dialogRef = React.useRef<HTMLDialogElement>(null);
  const unsavedDialogRef = React.useRef<HTMLDialogElement>(null);
  const deleteDialogRef = React.useRef<HTMLDialogElement>(null);
  const previousActiveElement = React.useRef<HTMLElement | null>(null);

  // Get the character
  const originalCharacter = characterManager.getCharacter(characterId);

  // State
  const [formData, setFormData] = useState<Partial<Character>>(originalCharacter || {});
  const [activeTab, setActiveTab] = useState<TabId>('identity');
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);
  const [dependencies, setDependencies] = useState<any>(null);

  // Initialize form data when character loads
  useEffect(() => {
    if (originalCharacter) {
      const initialPrompts = originalCharacter.prompts || [];

      // If no prompts exist, suggest a base visual prompt
      if (initialPrompts.length === 0) {
        const basePrompt = buildVisualPromptForCharacter(originalCharacter);
        if (basePrompt) {
          initialPrompts.push(basePrompt);
        }
      }

      setFormData({
        ...originalCharacter,
        prompts: initialPrompts,
      });
    }
  }, [originalCharacter]);

  // Handle form field changes
  const handleFieldChange = (field: string, value: unknown) => {
    setFormData(prev => ({
      ...prev,
      [field]: value,
    }));
    setIsDirty(true);

    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  // Handle nested field changes
  const handleNestedFieldChange = (section: string, field: string, value: unknown) => {
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...(prev[section as keyof Character] as any),
        [field]: value,
      },
    }));
    setIsDirty(true);

    // Clear error for this field
    const errorKey = `${section}.${field}`;
    if (errors[errorKey]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[errorKey];
        return newErrors;
      });
    }
  };

  // Validate form data
  const validateForm = (): boolean => {
    const validationResult = characterManager.validateCharacter(formData);
    setErrors(validationResult.errors);
    return validationResult.valid;
  };

  // Handle save
  const handleSave = async () => {
    // Validate first
    if (!validateForm()) {
      return;
    }

    setIsSaving(true);
    try {
      const updatedCharacter = await characterManager.updateCharacter(
        characterId,
        formData
      );

      setIsDirty(false);

      if (onSave) {
        onSave(updatedCharacter);
      }

      onClose();
    } catch (error) {
      console.error('Failed to save character:', error);
      setErrors({
        _general: [(error as Error).message || 'Failed to save character'],
      });
    } finally {
      setIsSaving(false);
    }
  };

  // Handle cancel
  const handleCancel = () => {
    if (isDirty) {
      setShowUnsavedWarning(true);
    } else {
      onClose();
    }
  };

  // Confirm cancel with unsaved changes
  const confirmCancel = () => {
    setShowUnsavedWarning(false);
    setIsDirty(false);
    onClose();
  };

  // Handle delete
  const handleDelete = async () => {
    // Check dependencies first
    const deps = characterManager.checkDependencies(characterId);
    setDependencies(deps);

    // Always show confirmation dialog
    setShowDeleteConfirm(true);
  };

  // Perform deletion
  const performDelete = async () => {
    try {
      await characterManager.deleteCharacter(characterId);

      if (onDelete) {
        onDelete(characterId);
      }

      onClose();
    } catch (error) {
      console.error('Failed to delete character:', error);
      setErrors({
        _general: [(error as Error).message || 'Failed to delete character'],
      });
    } finally {
      setShowDeleteConfirm(false);
    }
  };

  // Handle backdrop click
  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) {
      handleCancel();
    }
  };

  // Handle escape key - native dialog handles this automatically, but we keep for cleanup
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        // Native dialog handles escape automatically
        handleCancel();
      }
    };

    globalThis.addEventListener('keydown', handleEscape);
    return () => globalThis.removeEventListener('keydown', handleEscape);
  }, [isDirty]);

  // Open dialog when component mounts
  useEffect(() => {
    if (dialogRef.current && !dialogRef.current.open) {
      previousActiveElement.current = document.activeElement as HTMLElement;
      dialogRef.current.showModal();
    }
  }, []);

  // Handle unsaved warning dialog open
  useEffect(() => {
    if (showUnsavedWarning && unsavedDialogRef.current && !unsavedDialogRef.current.open) {
      unsavedDialogRef.current.showModal();
    } else if (!showUnsavedWarning && unsavedDialogRef.current?.open) {
      unsavedDialogRef.current.close();
    }
  }, [showUnsavedWarning]);

  // Handle delete dialog open
  useEffect(() => {
    if (showDeleteConfirm && deleteDialogRef.current && !deleteDialogRef.current.open) {
      deleteDialogRef.current.showModal();
    } else if (!showDeleteConfirm && deleteDialogRef.current?.open) {
      deleteDialogRef.current.close();
    }
  }, [showDeleteConfirm]);

  if (!originalCharacter) {
    return null;
  }

  const tabs: { id: TabId; label: string }[] = [
    { id: 'identity', label: 'Identity' },
    { id: 'appearance', label: 'Appearance' },
    { id: 'personality', label: 'Personality' },
    { id: 'background', label: 'Background' },
    { id: 'relationships', label: 'Relationships' },
    { id: 'images', label: 'Images' },
    { id: 'prompts', label: 'Prompts' },
  ];

  return (
    <>
      {/* Modal - Using native <dialog> element for WCAG compliance */}
      <dialog
        ref={dialogRef}
        className="character-editor"
        aria-labelledby="editor-title"
        onClose={() => {
          // Restore focus when dialog closes
          if (previousActiveElement.current) {
            previousActiveElement.current.focus();
          }
          handleCancel();
        }}
        onClick={(e) => {
          // Close on backdrop click (native dialog behavior)
          const rect = dialogRef.current?.getBoundingClientRect();
          if (rect && (
            e.clientX < rect.left ||
            e.clientX > rect.right ||
            e.clientY < rect.top ||
            e.clientY > rect.bottom
          )) {
            handleCancel();
          }
        }}
      >
        {/* Header */}
        <div className="character-editor__header">
          <h2 id="editor-title" className="character-editor__title">
            Edit Character: {originalCharacter.name}
          </h2>
          <button
            className="character-editor__close"
            onClick={handleCancel}
            aria-label="Close editor"
          >
            <X />
          </button>
        </div>

        {/* General errors */}
        {errors._general && (
          <div className="character-editor__error-banner">
            {errors._general.map((error) => (
              <p key={error}>{error}</p>
            ))}
          </div>
        )}

        {/* Tabs */}
        <div className="character-editor__tabs" role="tablist">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              className={`character-editor__tab ${activeTab === tab.id ? 'character-editor__tab--active' : ''
                }`}
              onClick={() => setActiveTab(tab.id)}
              role="tab"
              aria-selected={activeTab === tab.id}
              aria-controls={`panel-${tab.id}`}
              id={`tab-${tab.id}`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab panels */}
        <div className="character-editor__content">
          {activeTab === 'identity' && (
            <BasicIdentitySection
              data={formData}
              errors={errors}
              onChange={handleFieldChange}
              onNestedChange={handleNestedFieldChange}
              id="panel-identity"
            />
          )}

          {activeTab === 'appearance' && (
            <AppearanceSection
              data={formData.visual_identity || {}}
              errors={errors}
              onChange={(field, value) => handleNestedFieldChange('visual_identity', field, value)}
              characterName={formData.name || ''}
              archetype={formData.role?.archetype || ''}
              ageRange={formData.visual_identity?.age_range || ''}
              gender={formData.visual_identity?.gender || ''}
              id="panel-appearance"
            />
          )}

          {activeTab === 'personality' && (
            <PersonalitySection
              data={formData.personality || {}}
              errors={errors}
              onChange={(field, value) => handleNestedFieldChange('personality', field, value)}
              id="panel-personality"
            />
          )}

          {activeTab === 'background' && (
            <BackgroundSection
              data={formData.background || {}}
              errors={errors}
              onChange={(field, value) => handleNestedFieldChange('background', field, value)}
              id="panel-background"
            />
          )}

          {activeTab === 'relationships' && (
            <RelationshipsSection
              characterId={characterId}
              relationships={formData.relationships || []}
              errors={errors}
              onChange={(relationships) => handleFieldChange('relationships', relationships)}
              id="panel-relationships"
            />
          )}

          {activeTab === 'images' && (
            <CharacterImagesSection
              characterId={characterId}
              characterName={originalCharacter.name}
              character={formData as Character}
              id="panel-images"
            />
          )}


          {activeTab === 'prompts' && (
            <div className="character-editor__section">
              <PromptsManager
                prompts={formData.prompts || []}
                onUpdate={(newPrompts) => handleFieldChange('prompts', newPrompts)}
                entityName={formData.name || 'Character'}
              />
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="character-editor__footer">
          <button
            className="character-editor__button character-editor__button--delete"
            onClick={handleDelete}
            disabled={isSaving}
          >
            <Trash2 />
            Delete Character
          </button>

          <div className="character-editor__footer-actions">
            <button
              className="character-editor__button character-editor__button--secondary"
              onClick={handleCancel}
              disabled={isSaving}
            >
              Cancel
            </button>

            <button
              className="character-editor__button character-editor__button--primary"
              onClick={handleSave}
              disabled={isSaving}
            >
              <Save />
              {isSaving ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </div>
      </dialog>

      {/* Unsaved changes warning - Using native <dialog> element for WCAG compliance */}
      <dialog
        ref={unsavedDialogRef}
        className="character-editor-dialog"
        aria-labelledby="unsaved-changes-title"
        aria-describedby="unsaved-changes-desc"
      >
        <div className="character-editor-dialog__header">
          <AlertTriangle className="character-editor-dialog__icon" />
          <h3 id="unsaved-changes-title">Unsaved Changes</h3>
        </div>
        <p id="unsaved-changes-desc">You have unsaved changes. Are you sure you want to discard them?</p>
        <div className="character-editor-dialog__actions">
          <button
            className="character-editor__button character-editor__button--secondary"
            onClick={() => setShowUnsavedWarning(false)}
          >
            Keep Editing
          </button>
          <button
            className="character-editor__button character-editor__button--danger"
            onClick={confirmCancel}
          >
            Discard Changes
          </button>
        </div>
      </dialog>

      {/* Delete confirmation - Using native <dialog> element for WCAG compliance */}
      <dialog
        ref={deleteDialogRef}
        className="character-editor-dialog"
        aria-labelledby="delete-character-title"
        aria-describedby="delete-character-desc"
      >
        <div className="character-editor-dialog__header">
          <AlertTriangle className="character-editor-dialog__icon character-editor-dialog__icon--danger" />
          <h3 id="delete-character-title">Delete Character</h3>
        </div>

        {dependencies && (dependencies.stories.length > 0 || dependencies.relationships.length > 0) ? (
          <>
            <p>This character is used in the following places:</p>

            {dependencies.stories.length > 0 && (
              <div className="character-editor-dialog__dependencies">
                <h4>Stories ({dependencies.stories.length}):</h4>
                <ul>
                  {dependencies.stories.map((story: any) => (
                    <li key={story.id}>{story.title || 'Untitled Story'}</li>
                  ))}
                </ul>
              </div>
            )}

            {dependencies.relationships.length > 0 && (
              <div className="character-editor-dialog__dependencies">
                <h4>Relationships ({dependencies.relationships.length}):</h4>
                <ul>
                  {dependencies.relationships.map((char: any) => (
                    <li key={char.character_id}>{char.name}</li>
                  ))}
                </ul>
              </div>
            )}

            <p className="character-editor-dialog__warning">
              Deleting this character will remove it from all stories and relationships.
              This action cannot be undone.
            </p>
          </>
        ) : (
          <p id="delete-character-desc">Are you sure you want to delete this character? This action cannot be undone.</p>
        )}

        <div className="character-editor-dialog__actions">
          <button
            className="character-editor__button character-editor__button--secondary"
            onClick={() => setShowDeleteConfirm(false)}
          >
            Cancel
          </button>
          <button
            className="character-editor__button character-editor__button--danger"
            onClick={performDelete}
          >
            Delete Character
          </button>
        </div>
      </dialog>
    </>
  );
}

