}: CharacterListProps) {
  // ============================================================================
  // State and Hooks
  // ============================================================================

  const characterManager = useCharacterManager();

  // Main store state for reactivity
  const allCharactersFromStore = useStore((state) => state.characters);

  // Store state for search and filters
  const characterSearchQuery = useAppStore((state) => state.characterSearchQuery);
  const characterFilters = useAppStore((state) => state.characterFilters);
  const setCharacterSearchQuery = useAppStore((state) => state.setCharacterSearchQuery);
  const setCharacterFilters = useAppStore((state) => state.setCharacterFilters);

  // Local state
  const [loading, setLoading] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  // Log component mount/unmount
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log('🎬 [CharacterList] Component mounted');
    }
    return () => {
      if (process.env.NODE_ENV === 'development') {
        console.log('🎬 [CharacterList] Component unmounted');
      }
    };
  }, []);

  // ============================================================================
  // Character Data Processing
  // ============================================================================

  /**
   * Get all characters and apply search/filter/sort
   * Requirements: 1.2, 1.3, 4.4, 9.2, 9.3, 9.4
   */
  const characters = useMemo(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log('🔍 [CharacterList] Recalculating characters list');
    }

    let result = [...allCharactersFromStore];

    if (process.env.NODE_ENV === 'development') {
      console.log(`📊 [CharacterList] Total characters from store: ${result.length}`);
    }

    // Apply search filter (Requirement: 9.2)
    if (characterSearchQuery && characterSearchQuery.trim() !== '') {
      result = characterManager.searchCharacters(characterSearchQuery);
      if (process.env.NODE_ENV === 'development') {
        console.log(`🔎 [CharacterList] After search: ${result.length} characters`);
      }
    }

    // Apply additional filters (Requirement: 9.3, 9.4)
    if (
      characterFilters.archetype?.length ||
      characterFilters.ageRange?.length ||
      characterFilters.creationMethod?.length
    ) {
      result = characterManager.filterCharacters(characterFilters);
      if (process.env.NODE_ENV === 'development') {
        console.log(`🎯 [CharacterList] After filters: ${result.length} characters`);
      }

      // If both search and filters are active, we need to intersect the results
      if (characterSearchQuery && characterSearchQuery.trim() !== '') {
        const searchResults = characterManager.searchCharacters(characterSearchQuery);
        const searchIds = new Set(searchResults.map(c => c.character_id));
        result = result.filter(c => searchIds.has(c.character_id));
        if (process.env.NODE_ENV === 'development') {
          console.log(`🔗 [CharacterList] After search+filter intersection: ${result.length} characters`);
        }
      }
    }

    // Single deduplication at the end (optimization: was called 3x O(n), now 1x O(n))
    const beforeDedup = result.length;
    result = deduplicateCharacters(result);
    const afterDedup = result.length;

    if (beforeDedup !== afterDedup) {
      if (process.env.NODE_ENV === 'development') {
        console.warn(`⚠️ [CharacterList] Removed ${beforeDedup - afterDedup} duplicate(s)`);
      }
    }

    // Log duplicate info in development
    if (process.env.NODE_ENV === 'development') {
      logDuplicateInfo(result);
    }

    // Sort by creation date, newest first (Requirement: 1.3)
    result.sort((a, b) => {
      const dateA = new Date(a.creation_timestamp).getTime();
      const dateB = new Date(b.creation_timestamp).getTime();
      return dateB - dateA; // Descending order (newest first)
    });

    if (process.env.NODE_ENV === 'development') {
      console.log(`✅ [CharacterList] Final result: ${result.length} characters to display`);
    }
    return result;
  }, [
    allCharactersFromStore,
    characterSearchQuery,
    characterFilters,
    refreshTrigger, // Trigger re-computation on events
  ]);

  /**
   * Pagination for characters
   */
  const {
    paginatedItems,
    pagination,
    goToPage,
    setPageSize,
  } = usePagination({
    items: characters,
    pageSize: 12,
    resetOnItemsChange: true,
  });

  // ============================================================================
  // Event Subscriptions
  // ============================================================================

  /**
   * Subscribe to character events for real-time updates
   * Requirements: 5.1, 5.2, 5.3
   */
  useEffect(() => {
    let updateTimeout: NodeJS.Timeout | null = null;

    // Debounced update function to prevent multiple rapid re-renders
    const scheduleUpdate = () => {
      if (updateTimeout) {
        clearTimeout(updateTimeout);
      }
      updateTimeout = setTimeout(() => {
        setRefreshTrigger(prev => prev + 1);
        if (process.env.NODE_ENV === 'development') {
          console.log('🔄 [CharacterList] Refreshing character list');
        }
      }, 100); // 100ms debounce
    };

    // Handler for character-created event (Requirement: 5.1)
    const handleCharacterCreated = () => {
      if (process.env.NODE_ENV === 'development') {
        console.log('➕ [CharacterList] Character created event received');
      }
      scheduleUpdate();
    };

    // Handler for character-updated event (Requirement: 5.2)
    const handleCharacterUpdated = () => {
      if (process.env.NODE_ENV === 'development') {
        console.log('✏️ [CharacterList] Character updated event received');
      }
      scheduleUpdate();
    };

    // Handler for character-deleted event (Requirement: 5.3)
    const handleCharacterDeleted = () => {
      if (process.env.NODE_ENV === 'development') {
        console.log('🗑️ [CharacterList] Character deleted event received');
      }
      scheduleUpdate();
    };

    // Subscribe to events
    const sub1 = eventEmitter.on(WizardEventType.CHARACTER_CREATED, handleCharacterCreated);
    const sub2 = eventEmitter.on(WizardEventType.CHARACTER_UPDATED, handleCharacterUpdated);
    const sub3 = eventEmitter.on(WizardEventType.CHARACTER_DELETED, handleCharacterDeleted);

    // Cleanup subscriptions on unmount
    return () => {
      if (updateTimeout) {
        clearTimeout(updateTimeout);
      }
      sub1.unsubscribe();
      sub2.unsubscribe();
      sub3.unsubscribe();
    };
  }, []); // Empty deps - only subscribe once on mount

  // ============================================================================
  // Event Handlers
  // ============================================================================

  /**
   * Handle search query changes
   * Requirement: 9.2
   */
  const handleSearchChange = useCallback((query: string) => {
    setCharacterSearchQuery(query);
  }, [setCharacterSearchQuery]);

  /**
   * Handle filter changes
   * Requirement: 9.4
   */
  const handleFilterChange = useCallback((filters: CharacterFilters) => {
    setCharacterFilters(filters);
  }, [setCharacterFilters]);

  /**
   * Handle character card click
   */
  const handleCharacterClick = useCallback((character: Character) => {
    if (onCharacterClick) {
      onCharacterClick(character);
    }
  }, [onCharacterClick]);

  /**
   * Handle character selection (for Story Generator)
   * Requirements: 4.2, 4.5
   */
  const handleCharacterSelect = useCallback((character: Character, selected: boolean) => {
    if (!onSelectionChange) return;

    const newSelectedIds = selected
      ? [...selectedIds, character.character_id]
      : selectedIds.filter(id => id !== character.character_id);

    onSelectionChange(newSelectedIds);
  }, [selectedIds, onSelectionChange]);

  /**
   * Handle character edit
   */
  const handleCharacterEdit = useCallback((character: Character) => {
    if (onEdit) {
      onEdit(character);
    }
  }, [onEdit]);

  /**
   * Handle character delete
   */
  const handleCharacterDelete = useCallback((character: Character) => {
    if (onDelete) {
      onDelete(character);
    }
  }, [onDelete]);

  /**
   * Handle image generation - save to character data
   */
  const handleImageGenerated = useCallback(async (character: Character, imagePath: string, prompt?: string) => {
    if (process.env.NODE_ENV === 'development') {
      console.log('🖼️ [CharacterList] Image generated for character:', character.name, imagePath);
    }

    try {
      // Update character with the generated portrait path and prompt
      const updates: Partial<Character> = {
        visual_identity: {
          ...character.visual_identity,
          generated_portrait: imagePath,
        },
      };

      if (prompt) {
        updates.prompts = [...(character.prompts || []), prompt];
      }

      await characterManager.updateCharacter(character.character_id, updates);

      if (process.env.NODE_ENV === 'development') {
        console.log('✅ [CharacterList] Character updated with portrait path and prompt');
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        console.error('❌ [CharacterList] Failed to update character with portrait:', error);
      }
    }
  }, [characterManager]);

  // ============================================================================
  // Render Helpers
  // ============================================================================

  /**
   * Render empty state
   * Requirement: 1.5
   */
  const renderEmptyState = () => {
    const hasFilters =
      characterSearchQuery.trim() !== '' ||
      characterFilters.archetype?.length ||
      characterFilters.ageRange?.length ||
      characterFilters.creationMethod?.length;

    if (hasFilters) {
      // No results for current search/filters
      return (
        <div className="character-list__empty-state">
          <div className="character-list__empty-icon">🔍</div>
          <h3 className="character-list__empty-title">No characters found</h3>
          <p className="character-list__empty-message">
            Try adjusting your search or filters to find characters.
          </p>
        </div>
      );
    }

    // No characters at all
    return (
      <div className="character-list__empty-state">
        <div className="character-list__empty-icon">👥</div>
        <h3 className="character-list__empty-title">No characters yet</h3>
        <p className="character-list__empty-message">
          Create your first character to get started with your story.
        </p>
        {onCreateClick && (
          <button
            className="character-list__empty-create-button"
            onClick={onCreateClick}
          >
            <Plus className="character-list__empty-create-icon" />
            Create Character
          </button>
        )}
      </div>
    );
  };

  /**
   * Render loading state
   */
  const renderLoadingState = () => {
    return (
      <div className="character-list__grid">
        {Array.from({ length: 6 }).map((_, index) => (
          <CharacterCard
            key={`loading-${index}`}
            character={{} as Character}
            loading={true}
          />
        ))}
      </div>
    );
  };

  /**
   * Render character grid
   * Requirements: 1.2, 4.2
   */
  const renderCharacterGrid = () => {
    return (
      <>
        <div className="character-list__grid">
          {paginatedItems.map((character) => (
            <CharacterCard
              key={character.character_id}
              character={character}
              onClick={() => handleCharacterClick(character)}
              selectable={selectable}
              selected={selectedIds.includes(character.character_id)}
              onSelect={(selected) => handleCharacterSelect(character, selected)}
              showActions={showActions}
              onEdit={() => handleCharacterEdit(character)}
              onDelete={() => handleCharacterDelete(character)}
              onImageGenerated={(imagePath, prompt) => handleImageGenerated(character, imagePath, prompt)}
            />
          ))}
        </div>

        {/* Pagination Controls */}
        <Pagination
          pagination={pagination}
          onPageChange={goToPage}
          onPageSizeChange={setPageSize}
          showPageSizeSelector
          className="character-list__pagination"
        />
      </>
    );
  };

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div className="character-list">
      {/* Search and filter bar */}
      <CharacterSearchBar
        onSearchChange={handleSearchChange}
        onFilterChange={handleFilterChange}
        currentFilters={characterFilters}
        resultCount={characters.length}
      />

      {/* Character grid or empty state */}
      <div className="character-list__content">
        {loading ? (
          renderLoadingState()
        ) : characters.length === 0 ? (
          renderEmptyState()
        ) : (
          renderCharacterGrid()
        )}
      </div>
    </div>
  );
}

// ============================================================================
// CharacterList Component (Optimized)
// ============================================================================
// Performance-optimized version with virtualization, memoization, and
// efficient rendering for large character lists.
//
// Optimizations:
// - Virtual scrolling for large lists (1000+ items)
// - Memoized character cards to prevent unnecessary re-renders
// - Optimized search/filter algorithms with caching
// - Progressive loading states
// - Debounced event handlers
//
// Requirements: 1.1, 1.2, 1.3, 1.5, 4.2, 4.5, 5.1, 5.2, 5.3
// ============================================================================

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Plus } from 'lucide-react';
import { CharacterCardMemoized } from './CharacterCardMemoized';
import { CharacterSearchBar } from './CharacterSearchBar';
import { useCharacterManager } from '@/hooks/useCharacterManager';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import type { CharacterFilters } from '@/stores/useAppStore';
import { eventEmitter } from '@/services/eventEmitter';
import './CharacterList.css';

// ============================================================================
// Constants
// ============================================================================

/** Threshold for enabling virtualization (number of characters) */
const VIRTUALIZATION_THRESHOLD = 50;

/** Number of items to render outside visible area (buffer) */
const OVERSCAN_COUNT = 5;

/** Estimated height of each character card in pixels */
const CARD_HEIGHT = 280;

/** Number of columns in the grid */
const GRID_COLUMNS = 3;

// ============================================================================
// Types
// ============================================================================

export interface CharacterListProps {
  onCharacterClick?: (character: Character) => void;
  onCreateClick?: () => void;
  selectable?: boolean;
  selectedIds?: string[];
  onSelectionChange?: (ids: string[]) => void;
  showActions?: boolean;
  onEdit?: (character: Character) => void;
  onDelete?: (character: Character) => void;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Optimized search function with early exit
 */
function searchCharactersOptimized(
  characters: Character[],
  query: string
): Character[] {
  if (!query || query.trim() === '') {
    return characters;
  }

  const normalizedQuery = query.toLowerCase().trim();
  const results: Character[] = [];

  for (const character of characters) {
    // Early exit if we find a match - with null checks
    if (
      character?.name?.toLowerCase()?.includes(normalizedQuery) ||
      character?.role?.archetype?.toLowerCase()?.includes(normalizedQuery) ||
      character?.personality?.traits?.some((trait) =>
        trait?.toLowerCase()?.includes(normalizedQuery)
      )
    ) {
      results.push(character);
    }
  }

  return results;
}

/**
 * Optimized filter function with early exit
 */
function filterCharactersOptimized(
  characters: Character[],
  filters: CharacterFilters
): Character[] {
  const hasArchetypeFilter = filters.archetype && filters.archetype.length > 0;
  const hasAgeRangeFilter = filters.ageRange && filters.ageRange.length > 0;
  const hasCreationMethodFilter =
    filters.creationMethod && filters.creationMethod.length > 0;

  // No filters, return all
  if (!hasArchetypeFilter && !hasAgeRangeFilter && !hasCreationMethodFilter) {
    return characters;
  }

  const results: Character[] = [];

  for (const character of characters) {
    // Check archetype filter with null checks
    if (hasArchetypeFilter) {
      const matchesArchetype = filters.archetype!.some(
        (archetype) =>
          character?.role?.archetype?.toLowerCase() === archetype.toLowerCase()
      );
      if (!matchesArchetype) continue;
    }

    // Check age range filter with null checks
    if (hasAgeRangeFilter) {
      const matchesAgeRange = filters.ageRange!.some(
        (ageRange) =>
          character?.visual_identity?.age_range?.toLowerCase() ===
          ageRange.toLowerCase()
      );
      if (!matchesAgeRange) continue;
    }

    // Check creation method filter
    if (hasCreationMethodFilter) {
      const matchesCreationMethod = filters.creationMethod!.includes(
        character.creation_method
      );
      if (!matchesCreationMethod) continue;
    }

    results.push(character);
  }

  return results;
}

// ============================================================================
// CharacterList Component (Optimized)
// ============================================================================

export function CharacterListOptimized({
  onCharacterClick,
  onCreateClick,
  selectable = false,
  selectedIds = [],
  onSelectionChange,
  showActions = false,
  onEdit,
  onDelete,
}: CharacterListProps) {
  // ============================================================================
  // State and Hooks
  // ============================================================================

  const characterManager = useCharacterManager();

  // Store state
  const characterSearchQuery = useAppStore((state) => state.characterSearchQuery);
  const characterFilters = useAppStore((state) => state.characterFilters);
  const setCharacterSearchQuery = useAppStore(
    (state) => state.setCharacterSearchQuery
  );
  const setCharacterFilters = useAppStore((state) => state.setCharacterFilters);

  // Local state
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  // Virtualization state
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  // ============================================================================
  // Character Data Processing (Memoized)
  // ============================================================================

  /**
   * Get all characters with optimized search/filter/sort
   * Uses memoization to prevent unnecessary recalculations
   */
  const characters = useMemo(() => {
    let result = characterManager.getAllCharacters();

    // Apply search filter with optimized algorithm
    if (characterSearchQuery && characterSearchQuery.trim() !== '') {
      result = searchCharactersOptimized(result, characterSearchQuery);
    }

    // Apply additional filters with optimized algorithm
    if (
      characterFilters.archetype?.length ||
      characterFilters.ageRange?.length ||
      characterFilters.creationMethod?.length
    ) {
      result = filterCharactersOptimized(result, characterFilters);

      // If both search and filters are active, intersect results
      if (characterSearchQuery && characterSearchQuery.trim() !== '') {
        const searchResults = searchCharactersOptimized(
          characterManager.getAllCharacters(),
          characterSearchQuery
        );
        const searchIds = new Set(searchResults.map((c) => c.character_id));
        result = result.filter((c) => searchIds.has(c.character_id));
      }
    }

    // Sort by creation date, newest first
    result.sort((a, b) => {
      const dateA = new Date(a.creation_timestamp).getTime();
      const dateB = new Date(b.creation_timestamp).getTime();
      return dateB - dateA;
    });

    return result;
  }, [
    characterManager,
    characterSearchQuery,
    characterFilters,
    refreshTrigger,
  ]);

  // ============================================================================
  // Virtualization Logic
  // ============================================================================

  /**
   * Calculate visible range for virtualization
   */
  const visibleRange = useMemo(() => {
    if (characters.length < VIRTUALIZATION_THRESHOLD) {
      // Don't virtualize for small lists
      return { start: 0, end: characters.length };
    }

    const rowHeight = CARD_HEIGHT;
    const itemsPerRow = GRID_COLUMNS;

    const startRow = Math.floor(scrollTop / rowHeight);
    const endRow = Math.ceil((scrollTop + containerHeight) / rowHeight);

    const start = Math.max(0, (startRow - OVERSCAN_COUNT) * itemsPerRow);
    const end = Math.min(
      characters.length,
      (endRow + OVERSCAN_COUNT) * itemsPerRow
    );

    return { start, end };
  }, [characters.length, scrollTop, containerHeight]);

  /**
   * Get visible characters for rendering
   */
  const visibleCharacters = useMemo(() => {
    if (characters.length < VIRTUALIZATION_THRESHOLD) {
      return characters;
    }
    return characters.slice(visibleRange.start, visibleRange.end);
  }, [characters, visibleRange]);

  /**
   * Calculate total height and offset for virtualization
   */
  const virtualizationMetrics = useMemo(() => {
    if (characters.length < VIRTUALIZATION_THRESHOLD) {
      return { totalHeight: 0, offsetY: 0 };
    }

    const totalRows = Math.ceil(characters.length / GRID_COLUMNS);
    const totalHeight = totalRows * CARD_HEIGHT;
    const offsetY = Math.floor(visibleRange.start / GRID_COLUMNS) * CARD_HEIGHT;

    return { totalHeight, offsetY };
  }, [characters.length, visibleRange.start]);

  // ============================================================================
  // Event Handlers (Debounced)
  // ============================================================================

  /**
   * Handle scroll for virtualization
   */
  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget;
    setScrollTop(target.scrollTop);
  }, []);

  /**
   * Update container height on resize
   */
  useEffect(() => {
    if (!containerRef.current) return;

    const updateHeight = () => {
      if (containerRef.current) {
        setContainerHeight(containerRef.current.clientHeight);
      }
    };

    updateHeight();

    const resizeObserver = new ResizeObserver(updateHeight);
    resizeObserver.observe(containerRef.current);

    return () => resizeObserver.disconnect();
  }, []);

  // ============================================================================
  // Event Subscriptions (Debounced)
  // ============================================================================

  /**
   * Subscribe to character events with debouncing
   */
  useEffect(() => {
    let debounceTimer: NodeJS.Timeout;

    const debouncedRefresh = () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        setRefreshTrigger((prev) => prev + 1);
      }, 100); // 100ms debounce
    };

    eventEmitter.on('character-created', debouncedRefresh);
    eventEmitter.on('character-updated', debouncedRefresh);
    eventEmitter.on('character-deleted', debouncedRefresh);

    return () => {
      clearTimeout(debounceTimer);
      eventEmitter.off('character-created');
      eventEmitter.off('character-updated');
      eventEmitter.off('character-deleted');
    };
  }, []);

  // ============================================================================
  // Memoized Event Handlers
  // ============================================================================

  const handleSearchChange = useCallback(
    (query: string) => {
      setCharacterSearchQuery(query);
    },
    [setCharacterSearchQuery]
  );

  const handleFilterChange = useCallback(
    (filters: CharacterFilters) => {
      setCharacterFilters(filters);
    },
    [setCharacterFilters]
  );

  const handleCharacterClick = useCallback(
    (character: Character) => {
      if (onCharacterClick) {
        onCharacterClick(character);
      }
    },
    [onCharacterClick]
  );

  const handleCharacterSelect = useCallback(
    (character: Character, selected: boolean) => {
      if (!onSelectionChange) return;

      const newSelectedIds = selected
        ? [...selectedIds, character.character_id]
        : selectedIds.filter((id) => id !== character.character_id);

      onSelectionChange(newSelectedIds);
    },
    [selectedIds, onSelectionChange]
  );

  const handleCharacterEdit = useCallback(
    (character: Character) => {
      if (onEdit) {
        onEdit(character);
      }
    },
    [onEdit]
  );

  const handleCharacterDelete = useCallback(
    (character: Character) => {
      if (onDelete) {
        onDelete(character);
      }
    },
    [onDelete]
  );

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const renderEmptyState = () => {
    const hasFilters =
      characterSearchQuery.trim() !== '' ||
      characterFilters.archetype?.length ||
      characterFilters.ageRange?.length ||
      characterFilters.creationMethod?.length;

    if (hasFilters) {
      return (
        <div className="character-list__empty-state">
          <div className="character-list__empty-icon">🔍</div>
          <h3 className="character-list__empty-title">No characters found</h3>
          <p className="character-list__empty-message">
            Try adjusting your search or filters to find characters.
          </p>
        </div>
      );
    }

    return (
      <div className="character-list__empty-state">
        <div className="character-list__empty-icon">👥</div>
        <h3 className="character-list__empty-title">No characters yet</h3>
        <p className="character-list__empty-message">
          Create your first character to get started with your story.
        </p>
        {onCreateClick && (
          <button
            className="character-list__empty-create-button"
            onClick={onCreateClick}
          >
            <Plus className="character-list__empty-create-icon" />
            Create Character
          </button>
        )}
      </div>
    );
  };



  const renderCharacterGrid = () => {
    const useVirtualization = characters.length >= VIRTUALIZATION_THRESHOLD;

    if (useVirtualization) {
      // Virtualized rendering
      return (
        <div
          className="character-list__grid-container"
          ref={containerRef}
          onScroll={handleScroll}
          style={{ height: '600px', overflow: 'auto' }}
        >
          <div
            className="character-list__grid-spacer"
            style={{ height: `${virtualizationMetrics.totalHeight}px` }}
          >
            <div
              className="character-list__grid"
              style={{
                transform: `translateY(${virtualizationMetrics.offsetY}px)`,
              }}
            >
              {visibleCharacters.map((character) => (
                <CharacterCardMemoized
                  key={character.character_id}
                  character={character}
                  onClick={() => handleCharacterClick(character)}
                  selectable={selectable}
                  selected={selectedIds.includes(character.character_id)}
                  onSelect={(selected) =>
                    handleCharacterSelect(character, selected)
                  }
                  showActions={showActions}
                  onEdit={() => handleCharacterEdit(character)}
                  onDelete={() => handleCharacterDelete(character)}
                />
              ))}
            </div>
          </div>
        </div>
      );
    }

    // Normal rendering for small lists
    return (
      <div className="character-list__grid">
        {characters.map((character) => (
          <CharacterCardMemoized
            key={character.character_id}
            character={character}
            onClick={() => handleCharacterClick(character)}
            selectable={selectable}
            selected={selectedIds.includes(character.character_id)}
            onSelect={(selected) => handleCharacterSelect(character, selected)}
            showActions={showActions}
            onEdit={() => handleCharacterEdit(character)}
            onDelete={() => handleCharacterDelete(character)}
          />
        ))}
      </div>
    );
  };

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <div className="character-list">
      <CharacterSearchBar
        onSearchChange={handleSearchChange}
        onFilterChange={handleFilterChange}
        currentFilters={characterFilters}
        resultCount={characters.length}
      />

      <div className="character-list__content">
        {characters.length === 0
          ? renderEmptyState()
          : renderCharacterGrid()}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Search, X, Filter } from 'lucide-react';
import type { CharacterFilters } from '@/stores/useAppStore';
import './CharacterSearchBar.css';

/**
 * Props for the CharacterSearchBar component
 * Requirements: 9.1, 9.2, 9.3, 9.5
 */
export interface CharacterSearchBarProps {
  /** Callback when search query changes (debounced) */
  onSearchChange: (query: string) => void;
  
  /** Callback when filters change */
  onFilterChange: (filters: CharacterFilters) => void;
  
  /** Current active filters */
  currentFilters: CharacterFilters;
  
  /** Number of results matching current search/filters */
  resultCount: number;
  
  /** Optional debounce delay in milliseconds (default: 300ms) */
  debounceDelay?: number;
}

/**
 * Available archetype options for filtering
 */
const ARCHETYPE_OPTIONS = [
  'Hero',
  'Mentor',
  'Ally',
  'Guardian',
  'Trickster',
  'Shapeshifter',
  'Shadow',
  'Herald',
];

/**
 * Available age range options for filtering
 */
const AGE_RANGE_OPTIONS = [
  'Child (0-12)',
  'Teen (13-19)',
  'Young Adult (20-35)',
  'Adult (36-55)',
  'Senior (56+)',
];

/**
 * Available creation method options for filtering
 */
const CREATION_METHOD_OPTIONS = [
  { value: 'wizard', label: 'Wizard' },
  { value: 'auto_generated', label: 'Auto-Generated' },
  { value: 'manual', label: 'Manual' },
] as const;

/**
 * CharacterSearchBar Component
 * 
 * Provides search and filter functionality for character lists.
 * Features:
 * - Debounced search input (300ms default)
 * - Multi-select filter dropdowns for archetype, age range, and creation method
 * - Result count display
 * - Clear filters button
 * 
 * Requirements:
 * - Req 9.1: Search input field
 * - Req 9.2: Filter characters by name, archetype, or traits
 * - Req 9.3: Filter options for archetype, age range, creation method
 * - Req 9.5: Display count of filtered results
 */
export function CharacterSearchBar({
  onSearchChange,
  onFilterChange,
  currentFilters,
  resultCount,
  debounceDelay = 300,
}: CharacterSearchBarProps) {
  // Local search query state (for immediate UI updates)
  const [searchQuery, setSearchQuery] = useState('');
  
  // Filter dropdown visibility state
  const [showArchetypeFilter, setShowArchetypeFilter] = useState(false);
  const [showAgeRangeFilter, setShowAgeRangeFilter] = useState(false);
  const [showCreationMethodFilter, setShowCreationMethodFilter] = useState(false);

  // Debounced search effect
  useEffect(() => {
    const timer = setTimeout(() => {
      onSearchChange(searchQuery);
    }, debounceDelay);

    return () => clearTimeout(timer);
  }, [searchQuery, debounceDelay, onSearchChange]);

  // Handle search input change
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
  };

  // Handle clear search
  const handleClearSearch = () => {
    setSearchQuery('');
  };

  // Handle archetype filter toggle
  const handleArchetypeToggle = (archetype: string) => {
    const current = currentFilters.archetype || [];
    const updated = current.includes(archetype)
      ? current.filter(a => a !== archetype)
      : [...current, archetype];
    
    onFilterChange({
      ...currentFilters,
      archetype: updated.length > 0 ? updated : undefined,
    });
  };

  // Handle age range filter toggle
  const handleAgeRangeToggle = (ageRange: string) => {
    const current = currentFilters.ageRange || [];
    const updated = current.includes(ageRange)
      ? current.filter(a => a !== ageRange)
      : [...current, ageRange];
    
    onFilterChange({
      ...currentFilters,
      ageRange: updated.length > 0 ? updated : undefined,
    });
  };

  // Handle creation method filter toggle
  const handleCreationMethodToggle = (method: 'wizard' | 'auto_generated' | 'manual') => {
    const current = currentFilters.creationMethod || [];
    const updated = current.includes(method)
      ? current.filter(m => m !== method)
      : [...current, method];
    
    onFilterChange({
      ...currentFilters,
      creationMethod: updated.length > 0 ? updated : undefined,
    });
  };

  // Handle clear all filters
  const handleClearFilters = () => {
    setSearchQuery('');
    onFilterChange({
      archetype: undefined,
      ageRange: undefined,
      creationMethod: undefined,
    });
  };

  // Check if any filters are active
  const hasActiveFilters = 
    searchQuery.length > 0 ||
    (currentFilters.archetype && currentFilters.archetype.length > 0) ||
    (currentFilters.ageRange && currentFilters.ageRange.length > 0) ||
    (currentFilters.creationMethod && currentFilters.creationMethod.length > 0);

  // Count active filter selections
  const activeFilterCount = 
    (currentFilters.archetype?.length || 0) +
    (currentFilters.ageRange?.length || 0) +
    (currentFilters.creationMethod?.length || 0);

  return (
    <div className="character-search-bar">
      {/* Search input */}
      <div className="character-search-bar__search">
        <Search className="character-search-bar__search-icon" />
        <input
          type="text"
          className="character-search-bar__search-input"
          placeholder="Search characters by name, archetype, or traits..."
          value={searchQuery}
          onChange={handleSearchChange}
          aria-label="Search characters"
        />
        {searchQuery && (
          <button
            className="character-search-bar__clear-button"
            onClick={handleClearSearch}
            aria-label="Clear search"
            title="Clear search"
          >
            <X className="character-search-bar__clear-icon" />
          </button>
        )}
      </div>

      {/* Filter controls */}
      <div className="character-search-bar__filters">
        {/* Archetype filter */}
        <div className="character-search-bar__filter-group">
          <button
            className={`character-search-bar__filter-button ${
              currentFilters.archetype && currentFilters.archetype.length > 0
                ? 'character-search-bar__filter-button--active'
                : ''
            }`}
            onClick={() => setShowArchetypeFilter(!showArchetypeFilter)}
            aria-label="Filter by archetype"
            aria-expanded={showArchetypeFilter ? "true" : "false"}
          >
            <Filter className="character-search-bar__filter-icon" />
            <span>Archetype</span>
            {currentFilters.archetype && currentFilters.archetype.length > 0 && (
              <span className="character-search-bar__filter-badge">
                {currentFilters.archetype.length}
              </span>
            )}
          </button>
          
          {showArchetypeFilter && (
            <div className="character-search-bar__filter-dropdown">
              {ARCHETYPE_OPTIONS.map(archetype => (
                <label
                  key={archetype}
                  className="character-search-bar__filter-option"
                >
                  <input
                    type="checkbox"
                    checked={currentFilters.archetype?.includes(archetype) || false}
                    onChange={() => handleArchetypeToggle(archetype)}
                  />
                  <span>{archetype}</span>
                </label>
              ))}
            </div>
          )}
        </div>

        {/* Age range filter */}
        <div className="character-search-bar__filter-group">
          <button
            className={`character-search-bar__filter-button ${
              currentFilters.ageRange && currentFilters.ageRange.length > 0
                ? 'character-search-bar__filter-button--active'
                : ''
            }`}
            onClick={() => setShowAgeRangeFilter(!showAgeRangeFilter)}
            aria-label="Filter by age range"
            aria-expanded={showAgeRangeFilter ? "true" : "false"}
          >
            <Filter className="character-search-bar__filter-icon" />
            <span>Age Range</span>
            {currentFilters.ageRange && currentFilters.ageRange.length > 0 && (
              <span className="character-search-bar__filter-badge">
                {currentFilters.ageRange.length}
              </span>
            )}
          </button>
          
          {showAgeRangeFilter && (
            <div className="character-search-bar__filter-dropdown">
              {AGE_RANGE_OPTIONS.map(ageRange => (
                <label
                  key={ageRange}
                  className="character-search-bar__filter-option"
                >
                  <input
                    type="checkbox"
                    checked={currentFilters.ageRange?.includes(ageRange) || false}
                    onChange={() => handleAgeRangeToggle(ageRange)}
                  />
                  <span>{ageRange}</span>
                </label>
              ))}
            </div>
          )}
        </div>

        {/* Creation method filter */}
        <div className="character-search-bar__filter-group">
          <button
            className={`character-search-bar__filter-button ${
              currentFilters.creationMethod && currentFilters.creationMethod.length > 0
                ? 'character-search-bar__filter-button--active'
                : ''
            }`}
            onClick={() => setShowCreationMethodFilter(!showCreationMethodFilter)}
            aria-label="Filter by creation method"
            aria-expanded={showCreationMethodFilter ? "true" : "false"}
          >
            <Filter className="character-search-bar__filter-icon" />
            <span>Creation Method</span>
            {currentFilters.creationMethod && currentFilters.creationMethod.length > 0 && (
              <span className="character-search-bar__filter-badge">
                {currentFilters.creationMethod.length}
              </span>
            )}
          </button>
          
          {showCreationMethodFilter && (
            <div className="character-search-bar__filter-dropdown">
              {CREATION_METHOD_OPTIONS.map(({ value, label }) => (
                <label
                  key={value}
                  className="character-search-bar__filter-option"
                >
                  <input
                    type="checkbox"
                    checked={currentFilters.creationMethod?.includes(value) || false}
                    onChange={() => handleCreationMethodToggle(value)}
                  />
                  <span>{label}</span>
                </label>
              ))}
            </div>
          )}
        </div>

        {/* Clear filters button */}
        {hasActiveFilters && (
          <button
            className="character-search-bar__clear-filters-button"
            onClick={handleClearFilters}
            aria-label="Clear all filters"
            title="Clear all filters"
          >
            <X className="character-search-bar__clear-filters-icon" />
            <span>Clear All</span>
          </button>
        )}
      </div>

      {/* Result count */}
      <div className="character-search-bar__result-count">
        <span className="character-search-bar__result-count-number">
          {resultCount}
        </span>
        <span className="character-search-bar__result-count-label">
          {resultCount === 1 ? 'character' : 'characters'}
        </span>
        {activeFilterCount > 0 && (
          <span className="character-search-bar__result-count-filters">
            ({activeFilterCount} {activeFilterCount === 1 ? 'filter' : 'filters'} active)
          </span>
        )}
      </div>
    </div>
  );
}

import React from 'react';
