    it('should delete character when confirmed', async () => {
      render(
        <CharacterEditor
          characterId="char-1"
          onClose={mockOnClose}
          onDelete={mockOnDelete}
        />
      );
      
      const deleteButton = screen.getByRole('button', { name: /Delete Character/i });
      fireEvent.click(deleteButton);
      
      // Wait for dialog to appear
