    it('should not close when clicking inside modal', () => {
      render(
        <CharacterEditor
          characterId="char-1"
          onClose={mockOnClose}
        />
      );
      
      const modal = screen.getByRole('dialog');
      fireEvent.click(modal);
      
      expect(mockOnClose).not.toHaveBeenCalled();
    });
  });
});

