import React, { useState } from 'react';
import { Image, Loader2, AlertCircle } from 'lucide-react';
import { ComfyUIService } from '@/services/comfyuiService';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import './CharacterImageGenerator.css';

interface CharacterImageGeneratorProps {
  character: Partial<Character>;
  onImageGenerated?: (imageUrl: string) => void;
}

/**
 * CharacterImageGenerator Component
 * 
 * Generates a 512x512 character portrait image using ComfyUI
 * based on the character's visual identity and description.
 */
export function CharacterImageGenerator({
  character,
  onImageGenerated,
}: CharacterImageGeneratorProps) {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);

  const comfyuiService = ComfyUIService.getInstance();
  const project = useAppStore((state) => state.project);

  // Get visual style from project
  const visualStyle = (project as any)?.visualStyle || (project as any)?.visual_style || 'realistic';

  /**
   * Build a detailed prompt from character data
   */
  const buildCharacterPrompt = (): string => {
    const parts: string[] = [];

    // Add visual style first
    const styleMap: Record<string, string> = {
      'photorealistic': 'photorealistic',
      'cinematic': 'cinematic',
      'anime': 'anime style',
      'cartoon': 'cartoon style',
      'sketch': 'sketch art',
      'oil-painting': 'oil painting',
      'watercolor': 'watercolor painting',
      'digital-art': 'digital art',
      'comic-book': 'comic book style',
      'noir': 'film noir style',
      'vintage': 'vintage style',
      'modern': 'modern style',
      'minimalist': 'minimalist style',
      'realistic': 'realistic'
    };

    const stylePrefix = styleMap[visualStyle] || visualStyle;
    parts.push(stylePrefix);

    // Basic description
    if (character.name) {
      parts.push(`Portrait of ${character.name}`);
    } else {
      parts.push('Character portrait');
    }

    // Visual identity details
    const visual = character.visual_identity;
    if (visual) {
      // Face and hair
      if (visual.hair_color && visual.hair_style) {
        parts.push(`${visual.hair_color} ${visual.hair_style} hair`);
      } else if (visual.hair_color) {
        parts.push(`${visual.hair_color} hair`);
      }

      if (visual.eye_color) {
        parts.push(`${visual.eye_color} eyes`);
      }

      if (visual.facial_structure) {
        parts.push(`${visual.facial_structure} face`);
      }

      // Skin and build
      if (visual.skin_tone) {
        parts.push(`${visual.skin_tone} skin`);
      }

      if (visual.build) {
        parts.push(`${visual.build} build`);
      }

      // Clothing
      if (visual.clothing_style) {
        parts.push(`wearing ${visual.clothing_style} clothing`);
      }

      // Distinctive features
      if (visual.distinctive_features && visual.distinctive_features.length > 0) {
        parts.push(visual.distinctive_features.join(', '));
      }
    }

    // Add quality tags from user requirements
    parts.push(
      'Cinematic view',
      'photorealist',
      'high skin details',
      '8K',
      'highly detailed',
      'professional portrait',
      'centered composition',
      'sharp focus',
      'depth of field'
    );

    return parts.join(', ');
  };

  /**
   * Build negative prompt to avoid unwanted elements
   */
  const buildNegativePrompt = (): string => {
    return [
      'blurry',
      'low quality',
      'distorted',
      'deformed',
      'ugly',
      'bad anatomy',
      'watermark',
      'text',
      'signature',
      'multiple people',
      'full body',
      'background clutter',
    ].join(', ');
  };

  /**
   * Handle image generation
   */
  const handleGenerate = async () => {
    setIsGenerating(true);
    setError(null);

    try {
      const prompt = buildCharacterPrompt();
      const negativePrompt = buildNegativePrompt();

      console.log('Generating character image with prompt:', prompt);

      // Flux Turbo parameters (Z-Image Turbo workflow)
      const imageUrl = await comfyuiService.generateImage({
        prompt,
        negativePrompt,
        width: 784,
        height: 1024,
        steps: 4,
        cfgScale: 1.0,
        seed: Math.floor(Math.random() * 1000000),
        model: 'z_image_turbo_bf16.safetensors', // Not used in Flux Turbo workflow
        sampler: 'res_multistep',
        scheduler: 'simple',
      });

      setGeneratedImage(imageUrl);

      if (onImageGenerated) {
        onImageGenerated(imageUrl);
      }
    } catch (err) {
      console.error('Failed to generate character image:', err);
      setError(err instanceof Error ? err.message : 'Failed to generate image');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="character-image-generator">
      <div className="character-image-generator__header">
        <h4 className="character-image-generator__title">
          <Image size={18} />
          Character Portrait
        </h4>
        <p className="character-image-generator__description">
          Generate a 512x512 portrait image based on character appearance
        </p>
      </div>

      {/* Preview area */}
      <div className="character-image-generator__preview">
        {generatedImage ? (
          <img
            src={generatedImage}
            alt={`Portrait of ${character.name || 'character'}`}
            className="character-image-generator__image"
          />
        ) : (
          <div className="character-image-generator__placeholder">
            <Image size={48} />
            <p>No image generated yet</p>
          </div>
        )}
      </div>

      {/* Error message */}
      {error && (
        <div className="character-image-generator__error">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      {/* Generate button */}
      <button
        className="character-image-generator__button"
        onClick={handleGenerate}
        disabled={isGenerating}
      >
        {isGenerating ? (
          <>
            <Loader2 size={18} className="character-image-generator__spinner" />
            Generating...
          </>
        ) : (
          <>
            <Image size={18} />
            Generate Portrait
          </>
        )}
      </button>

      {/* Info text */}
      <p className="character-image-generator__info">
        The image will be generated using ComfyUI based on the character's appearance details.
        Make sure ComfyUI is running and configured.
      </p>
    </div>
  );
}

/**
 * Character Images Section - 2-STEP METHODOLOGY
 * 1. Generate reference image first (full body front view)
 * 2. Select reference and generate complete reference sheet
 * 
 * Issues Fixed:
 * - Images now stored in character visual_identity
 * - Progress tracking aligned with ComfyUI (25 steps)
 * - Realistic skin prompts for photorealistic results
 * - Enhanced demo mode with realistic placeholders
 * 
 * Multi-view sheet support:
 * - Uses generated reference images as default if no custom sheet created
 * - Stores reference_sheet_images in visual_identity for persistence
 */
import React, { useState, useCallback, useEffect } from 'react';
import { Image, Grid3X3, RefreshCw, Download, X, Eye, CheckCircle } from 'lucide-react';
import { useStore } from '@/store';
import type { Character, ReferenceImageData, SheetImageData } from '@/types/character';

interface CharacterImagesSectionProps {
  characterId: string;
  characterName: string;
  character?: Character;
  id?: string;
}

interface CharacterImage {
  id: number;
  url: string;
  type: 'reference' | 'reference_sheet';
  timestamp: string;
  panel?: string;
  filename?: string;
}

const OUTFIT_TYPES = [
  { id: 'casual', label: 'Casual', color: '#4CAF50' },
  { id: 'formal', label: 'Formal', color: '#2196F3' },
  { id: 'combat', label: 'Combat', color: '#F44336' },
  { id: 'armor', label: 'Armor', color: '#FF9800' },
];

function buildCharacterPrompt(character: Character | undefined, outfits: string[]): string {
  if (!character) return 'a character';

  const parts: string[] = [];
  if (character.name) parts.push(`Character name: ${character.name}`);
  if (character.visual_identity) {
    const v = character.visual_identity;
    if (v.hair_color) parts.push(`Hair: ${v.hair_color} ${v.hair_style || ''}`.trim());
    if (v.eye_color) parts.push(`Eyes: ${v.eye_color}`);
    if (v.skin_tone) parts.push(`Skin tone: ${v.skin_tone}`);
    if (v.height) parts.push(`Height: ${v.height}`);
    if (v.build) parts.push(`Build: ${v.build}`);
    if (v.distinctive_features?.length) parts.push(`Features: ${v.distinctive_features.join(', ')}`);
    if (v.color_palette?.length) parts.push(`Colors: ${v.color_palette.join(', ')}`);
    if (v.age_range) parts.push(`Age: ${v.age_range}`);
    if (v.clothing_style) parts.push(`Clothing: ${v.clothing_style}`);
  }
  if (outfits.length) parts.push(`Outfits: ${outfits.join(', ')}`);
  return parts.join('. ');
}

function generateViewPrompt(description: string, view: string): string {
  const prompts: Record<string, string> = {
    front: `Full body standing view, front facing camera, ${description}`,
    left: `Full body standing view, profile facing left, ${description}`,
    right: `Full body standing view, profile facing right, ${description}`,
    back: `Full body standing view, back facing camera, ${description}`,
  };
  return prompts[view] || prompts.front;
}

/**
 * Build Flux Turbo workflow - Same as comfyuiService.ts
 * Uses UNETLoader + CLIPLoader + VAELoader separately for FLUX model support
 */
function buildFluxTurboWorkflow(params: {
  prompt: string;
  negativePrompt?: string;
  width: number;
  height: number;
  steps: number;
  cfgScale: number;
  seed: number;
}): Record<string, unknown> {
  const seed = params.seed || Math.floor(Math.random() * 1000000);

  return {
    "9": {
      "inputs": {
        "filename_prefix": "character_reference",
        "images": ["57:8", 0]
      },
      "class_type": "SaveImage",
      "_meta": { "title": "Save Image" }
    },
    "58": {
      "inputs": {
        "value": params.prompt
      },
      "class_type": "PrimitiveStringMultiline",
      "_meta": { "title": "Prompt" }
    },
    "57:30": {
      "inputs": {
        "clip_name": "qwen_3_4b.safetensors",
        "type": "lumina2",
        "device": "default"
      },
      "class_type": "CLIPLoader",
      "_meta": { "title": "Load CLIP" }
    },
    "57:29": {
      "inputs": {
        "vae_name": "ae.safetensors"
      },
