/**
 * GenerationStatusDisplay Component
 * 
 * Displays current generation status with progress tracking for ComfyUI integration.
 * Shows current step description, progress bar, item counters, and timing information.
 * 
 * Requirements: 8.1, 8.2, 8.3
 */

import React, { useEffect, useState } from 'react';
import { Progress } from '@/components/ui/progress';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Loader2, CheckCircle2, XCircle, Clock } from 'lucide-react';

// ============================================================================
// Types
// ============================================================================

/**
 * Generation progress information
 */
export interface GenerationProgress {
  /** Current step description */
  currentStep: string;
  /** Progress percentage (0-100) */
  progress: number;
  /** Current item number */
  currentItem: number;
  /** Total number of items */
  totalItems: number;
  /** Start time timestamp */
  startTime?: number;
  /** Estimated completion timestamp */
  estimatedCompletion?: number;
  /** Current stage */
  stage: 'idle' | 'grid' | 'comfyui' | 'promotion' | 'qa' | 'export' | 'complete' | 'error';
  /** Error message if any */
  error?: string;
}

/**
 * Props for GenerationStatusDisplay component
 */
export interface GenerationStatusDisplayProps {
  /** Current generation progress */
  progress: GenerationProgress;
  /** Optional CSS class name */
  className?: string;
  /** Whether to show in compact mode */
  compact?: boolean;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Format duration in milliseconds to human-readable string
 */
function formatDuration(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    return `${hours}h ${minutes % 60}m ${seconds % 60}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds % 60}s`;
  }
  return `${seconds}s`;
}

/**
 * Get color class for progress bar based on stage
 */
function getProgressColor(stage: GenerationProgress['stage']): string {
  switch (stage) {
    case 'grid':
      return 'bg-blue-500';
    case 'comfyui':
      return 'bg-purple-500';
    case 'promotion':
      return 'bg-indigo-500';
    case 'qa':
      return 'bg-cyan-500';
    case 'export':
      return 'bg-green-500';
    case 'complete':
      return 'bg-green-600';
    case 'error':
      return 'bg-red-500';
    default:
      return 'bg-gray-500';
  }
}

/**
 * Get status icon based on stage
 */
function getStatusIcon(stage: GenerationProgress['stage']) {
  switch (stage) {
    case 'complete':
      return <CheckCircle2 className="h-5 w-5 text-green-500" />;
    case 'error':
      return <XCircle className="h-5 w-5 text-red-500" />;
    case 'idle':
      return null;
    default:
      return <Loader2 className="h-5 w-5 animate-spin text-blue-500" />;
  }
}

// ============================================================================
// Component
// ============================================================================

/**
 * GenerationStatusDisplay Component
 * 
 * Displays real-time generation progress with step description, progress bar,
 * item counters, and timing information.
 * 
 * Requirements: 8.1, 8.2, 8.3
 */
export const GenerationStatusDisplay: React.FC<GenerationStatusDisplayProps> = ({
  progress,
  className = '',
  compact = false,
}) => {
  const [elapsedTime, setElapsedTime] = useState<number>(0);
  const [estimatedRemaining, setEstimatedRemaining] = useState<number>(0);

  // ============================================================================
  // Update Timing Information
  // ============================================================================

  useEffect(() => {
    if (!progress.startTime || progress.stage === 'idle') {
      setElapsedTime(0);
      setEstimatedRemaining(0);
      return;
    }

    const updateTiming = () => {
      const now = Date.now();
      const elapsed = now - (progress.startTime || now);
      setElapsedTime(elapsed);

      if (progress.estimatedCompletion) {
        const remaining = Math.max(0, progress.estimatedCompletion - now);
        setEstimatedRemaining(remaining);
      } else {
        setEstimatedRemaining(0);
      }
    };

    // Initial update
    updateTiming();

    // Update every second
    const interval = setInterval(updateTiming, 1000);

    return () => clearInterval(interval);
  }, [progress.startTime, progress.estimatedCompletion, progress.stage]);

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const isActive = progress.stage !== 'idle' && progress.stage !== 'complete' && progress.stage !== 'error';
  const isComplete = progress.stage === 'complete';
  const hasError = progress.stage === 'error';

  // ============================================================================
  // Compact Mode Render
  // ============================================================================

  if (compact) {
    return (
      <div className={`flex items-center gap-3 ${className}`}>
        {getStatusIcon(progress.stage)}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm font-medium truncate">{progress.currentStep}</span>
            <span className="text-sm text-muted-foreground ml-2">{Math.round(progress.progress)}%</span>
          </div>
          <Progress value={progress.progress} className="h-1.5" />
        </div>
      </div>
    );
  }

  // ============================================================================
  // Full Mode Render
  // ============================================================================

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="flex items-center gap-2 text-base">
          {getStatusIcon(progress.stage)}
          Generation Progress
        </CardTitle>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Current Step Description */}
        {/* Requirements: 8.1 */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">Current Step</span>
            <span className="text-sm text-muted-foreground">
              {progress.currentStep || 'Idle'}
            </span>
          </div>
        </div>

        {/* Progress Bar with Percentage */}
        {/* Requirements: 8.2 */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">Progress</span>
            <span className="text-sm text-muted-foreground">
              {Math.round(progress.progress)}%
            </span>
          </div>
          <Progress 
            value={progress.progress} 
            className="h-2"
            style={{
              // @ts-ignore - CSS custom property
              '--progress-color': getProgressColor(progress.stage),
            }}
          />
        </div>

        {/* Current Item / Total Items Counter */}
        {/* Requirements: 8.2 */}
        {progress.totalItems > 0 && (
          <div className="flex items-center justify-between p-3 bg-muted rounded-lg">
            <span className="text-sm font-medium">Items</span>
            <span className="text-sm font-mono">
              {progress.currentItem} / {progress.totalItems}
            </span>
          </div>
        )}

        {/* Elapsed Time and Estimated Remaining Time */}
        {/* Requirements: 8.3 */}
        {isActive && (
          <div className="grid grid-cols-2 gap-3">
            <div className="flex flex-col gap-1 p-3 bg-muted rounded-lg">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Clock className="h-3 w-3" />
                <span>Elapsed</span>
              </div>
              <span className="text-sm font-mono font-semibold">
                {formatDuration(elapsedTime)}
              </span>
            </div>

            <div className="flex flex-col gap-1 p-3 bg-muted rounded-lg">
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <Clock className="h-3 w-3" />
                <span>Remaining</span>
              </div>
              <span className="text-sm font-mono font-semibold">
                {estimatedRemaining > 0 ? formatDuration(estimatedRemaining) : '--'}
              </span>
            </div>
          </div>
        )}

        {/* Completion Summary */}
        {isComplete && (
          <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-green-600" />
              <span className="text-sm font-medium text-green-900">
                Generation completed in {formatDuration(elapsedTime)}
              </span>
            </div>
          </div>
        )}

        {/* Error Display */}
        {hasError && progress.error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-start gap-2">
              <XCircle className="h-4 w-4 text-red-600 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <span className="text-sm font-medium text-red-900 block mb-1">
                  Generation Failed
                </span>
                <span className="text-sm text-red-700">
                  {progress.error}
                </span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default GenerationStatusDisplay;

/**
 * MasterCoherenceSheetProgress Component
 * 
 * Displays progress for Master Coherence Sheet (3x3 grid) generation.
 * Shows individual progress for each of the 9 panels with grid visualization
 * and real-time updates as each panel completes.
 * 
 * Requirements: 8.4, 8.5
 */

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, Loader2, Circle, XCircle } from 'lucide-react';
import { cn } from '@/lib/utils';

// ============================================================================
// Types
// ============================================================================

/**
 * Status of a single panel in the grid
 */
export type PanelStatus = 'pending' | 'in-progress' | 'complete' | 'error';

/**
 * Information about a single panel
 */
export interface PanelInfo {
  /** Panel index (0-8) */
  index: number;
  /** Panel status */
  status: PanelStatus;
  /** Progress percentage (0-100) */
  progress: number;
  /** Error message if status is 'error' */
  error?: string;
}

/**
 * Props for MasterCoherenceSheetProgress component
 */
export interface MasterCoherenceSheetProgressProps {
  /** Array of 9 panel information objects */
  panels: PanelInfo[];
  /** Overall progress percentage (0-100) */
  overallProgress: number;
  /** Optional CSS class name */
  className?: string;
  /** Whether to show in compact mode */
  compact?: boolean;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Get panel position in 3x3 grid (row, col)
 */
function getPanelPosition(index: number): { row: number; col: number } {
  return {
    row: Math.floor(index / 3),
    col: index % 3,
  };
}

/**
 * Get panel label (A1, A2, A3, B1, B2, B3, C1, C2, C3)
 */
function getPanelLabel(index: number): string {
  const row = Math.floor(index / 3);
  const col = index % 3;
  const rowLabel = String.fromCharCode(65 + row); // A, B, C
  const colLabel = (col + 1).toString(); // 1, 2, 3
  return `${rowLabel}${colLabel}`;
}

/**
 * Get status icon for panel
 */
function getPanelIcon(status: PanelStatus) {
  switch (status) {
    case 'complete':
      return <CheckCircle2 className="h-5 w-5 text-green-500" />;
    case 'in-progress':
      return <Loader2 className="h-5 w-5 animate-spin text-blue-500" />;
    case 'error':
      return <XCircle className="h-5 w-5 text-red-500" />;
    case 'pending':
    default:
      return <Circle className="h-5 w-5 text-gray-300" />;
  }
}

/**
 * Get background color class for panel based on status
 */
function getPanelColorClass(status: PanelStatus): string {
  switch (status) {
    case 'complete':
      return 'bg-green-50 border-green-300';
    case 'in-progress':
      return 'bg-blue-50 border-blue-300';
    case 'error':
      return 'bg-red-50 border-red-300';
    case 'pending':
    default:
      return 'bg-gray-50 border-gray-200';
  }
}

/**
 * Calculate completion statistics
 */
function getCompletionStats(panels: PanelInfo[]): {
  completed: number;
  inProgress: number;
  pending: number;
  errors: number;
} {
  return panels.reduce(
    (acc, panel) => {
      switch (panel.status) {
        case 'complete':
          acc.completed++;
          break;
        case 'in-progress':
          acc.inProgress++;
          break;
        case 'error':
          acc.errors++;
          break;
        case 'pending':
          acc.pending++;
          break;
      }
      return acc;
    },
    { completed: 0, inProgress: 0, pending: 0, errors: 0 }
  );
}

// ============================================================================
// Component
// ============================================================================

/**
 * MasterCoherenceSheetProgress Component
 * 
 * Displays a 3x3 grid visualization showing the progress of each panel
 * in the Master Coherence Sheet generation process.
 * 
 * Requirements: 8.4, 8.5
 */
export const MasterCoherenceSheetProgress: React.FC<MasterCoherenceSheetProgressProps> = ({
  panels,
  overallProgress,
  className = '',
  compact = false,
}) => {
  // Ensure we have exactly 9 panels
  const gridPanels = Array.from({ length: 9 }, (_, i) => {
    return panels[i] || {
      index: i,
      status: 'pending' as PanelStatus,
      progress: 0,
    };
  });

  const stats = getCompletionStats(gridPanels);

  // ============================================================================
  // Compact Mode Render
  // ============================================================================

  if (compact) {
    return (
      <div className={`space-y-2 ${className}`}>
        <div className="flex items-center justify-between text-sm">
          <span className="font-medium">Master Coherence Sheet</span>
          <span className="text-muted-foreground">
            {stats.completed} / 9 panels
          </span>
        </div>
        
        {/* Mini grid visualization */}
        <div className="grid grid-cols-3 gap-1">
          {gridPanels.map((panel) => (
            <div
              key={panel.index}
              className={cn(
                'aspect-square rounded border-2 flex items-center justify-center transition-all',
                getPanelColorClass(panel.status)
              )}
              title={`Panel ${getPanelLabel(panel.index)}: ${panel.status}`}
            >
              <div className="scale-75">
                {getPanelIcon(panel.status)}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // ============================================================================
  // Full Mode Render
  // ============================================================================

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <CardTitle className="text-base">Master Coherence Sheet Progress</CardTitle>
        <p className="text-sm text-muted-foreground">
          Generating 3x3 grid for visual DNA lock
        </p>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Overall Progress */}
        {/* Requirements: 8.4 */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="font-medium">Overall Progress</span>
            <span className="text-muted-foreground">
              {Math.round(overallProgress)}%
            </span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2">
            <div
              className="bg-blue-500 h-2 rounded-full transition-all duration-300"
              style={{ width: `${overallProgress}%` }}
            />
          </div>
        </div>

        {/* Completion Statistics */}
        <div className="grid grid-cols-4 gap-2 text-center">
          <div className="p-2 bg-green-50 rounded-lg">
            <div className="text-lg font-bold text-green-700">{stats.completed}</div>
            <div className="text-xs text-green-600">Complete</div>
          </div>
          <div className="p-2 bg-blue-50 rounded-lg">
            <div className="text-lg font-bold text-blue-700">{stats.inProgress}</div>
            <div className="text-xs text-blue-600">Active</div>
          </div>
          <div className="p-2 bg-gray-50 rounded-lg">
            <div className="text-lg font-bold text-gray-700">{stats.pending}</div>
            <div className="text-xs text-gray-600">Pending</div>
          </div>
          <div className="p-2 bg-red-50 rounded-lg">
            <div className="text-lg font-bold text-red-700">{stats.errors}</div>
            <div className="text-xs text-red-600">Errors</div>
          </div>
        </div>

        {/* 3x3 Grid Visualization */}
        {/* Requirements: 8.4, 8.5 */}
        <div className="space-y-2">
          <h4 className="text-sm font-medium">Panel Status</h4>
          
          <div className="grid grid-cols-3 gap-3 p-4 bg-muted rounded-lg">
            {gridPanels.map((panel) => {
              const label = getPanelLabel(panel.index);
              
              return (
                <div
                  key={panel.index}
                  className={cn(
                    'aspect-square rounded-lg border-2 flex flex-col items-center justify-center p-2 transition-all',
                    getPanelColorClass(panel.status),
                    panel.status === 'in-progress' && 'animate-pulse'
                  )}
                  title={`Panel ${label}: ${panel.status}${panel.error ? ` - ${panel.error}` : ''}`}
                >
                  {/* Panel Icon */}
                  <div className="mb-1">
                    {getPanelIcon(panel.status)}
                  </div>
                  
                  {/* Panel Label */}
                  <div className="text-xs font-mono font-semibold text-gray-700">
                    {label}
                  </div>
                  
                  {/* Progress Percentage (for in-progress panels) */}
                  {panel.status === 'in-progress' && panel.progress > 0 && (
                    <div className="text-xs text-blue-600 mt-1">
                      {Math.round(panel.progress)}%
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Individual Panel Details */}
        {/* Requirements: 8.5 */}
        <div className="space-y-2">
          <h4 className="text-sm font-medium">Panel Details</h4>
          
          <div className="space-y-1 max-h-48 overflow-y-auto">
            {gridPanels.map((panel) => {
              const label = getPanelLabel(panel.index);
              
              return (
                <div
                  key={panel.index}
                  className="flex items-center justify-between p-2 rounded border text-sm"
                >
                  <div className="flex items-center gap-2">
                    <div className="scale-75">
                      {getPanelIcon(panel.status)}
                    </div>
                    <span className="font-mono font-medium">{label}</span>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    {panel.status === 'in-progress' && (
                      <span className="text-xs text-blue-600">
                        {Math.round(panel.progress)}%
                      </span>
                    )}
                    <span className="text-xs text-muted-foreground capitalize">
                      {panel.status.replace('-', ' ')}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Error Summary */}
        {stats.errors > 0 && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-start gap-2">
              <XCircle className="h-4 w-4 text-red-600 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <span className="text-sm font-medium text-red-900 block mb-1">
                  {stats.errors} Panel{stats.errors !== 1 ? 's' : ''} Failed
                </span>
                <div className="text-xs text-red-700 space-y-1">
                  {gridPanels
                    .filter((p) => p.status === 'error')
                    .map((p) => (
                      <div key={p.index}>
                        Panel {getPanelLabel(p.index)}: {p.error || 'Unknown error'}
                      </div>
                    ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default MasterCoherenceSheetProgress;

/**
 * MockModeToggle Component
 * 
 * Provides a toggle switch to manually enable/disable mock mode.
 * Persists user preference and handles mode transitions gracefully.
 * 
 * Validates: Requirement 11.7
 */

import React, { useState, useEffect, useCallback } from 'react';
import './MockModeToggle.css';

export interface MockModeToggleProps {
  /** Current mock mode state */
  enabled: boolean;
  
  /** Callback when toggle state changes */
  onChange: (enabled: boolean) => void;
  
  /** Whether the backend is available */
  backendAvailable?: boolean;
  
  /** Whether the toggle is disabled */
  disabled?: boolean;
  
  /** Optional label text */
  label?: string;
  
  /** Show description text */
  showDescription?: boolean;
}

/**
 * Get stored mock mode preference from localStorage
 */
function getStoredPreference(): boolean {
  try {
    const stored = localStorage.getItem('comfyui_mock_mode_preference');
    return stored === 'true';
  } catch (error) {
    console.warn('Failed to read mock mode preference from localStorage:', error);
    return false;
  }
}

/**
 * Store mock mode preference to localStorage
 */
function storePreference(enabled: boolean): void {
  try {
    localStorage.setItem('comfyui_mock_mode_preference', enabled.toString());
  } catch (error) {
    console.warn('Failed to store mock mode preference to localStorage:', error);
  }
}

export const MockModeToggle: React.FC<MockModeToggleProps> = ({
  enabled,
  onChange,
  backendAvailable = false,
  disabled = false,
  label = 'Mock Mode',
  showDescription = true,
}) => {
  const [isTransitioning, setIsTransitioning] = useState(false);
  
  /**
   * Load stored preference on mount
   */
  useEffect(() => {
    const storedPreference = getStoredPreference();
    if (storedPreference !== enabled) {
      onChange(storedPreference);
    }
  }, []); // Only run on mount
  
  /**
   * Handle toggle change
   */
  const handleToggle = useCallback(() => {
    if (disabled || isTransitioning) {
      return;
    }
    
    setIsTransitioning(true);
    
    const newState = !enabled;
    
    // Store preference
    storePreference(newState);
    
    // Call onChange callback
    onChange(newState);
    
    // Reset transition state after animation
    setTimeout(() => {
      setIsTransitioning(false);
    }, 300);
  }, [enabled, disabled, isTransitioning, onChange]);
  
  /**
   * Handle keyboard interaction
   */
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleToggle();
    }
  }, [handleToggle]);
  
  /**
   * Get description text based on state
   */
  const getDescription = (): string => {
    if (enabled) {
      return 'Using placeholder images instead of real AI generation';
    } else if (backendAvailable) {
      return 'Using real ComfyUI backend for generation';
    } else {
      return 'Backend unavailable - will use placeholders when enabled';
    }
  };
  
  /**
   * Get status indicator color
   */
  const getStatusColor = (): string => {
    if (enabled) {
      return '#f59e0b'; // Amber for mock mode
    } else if (backendAvailable) {
      return '#10b981'; // Green for real mode with backend
    } else {
      return '#6b7280'; // Gray for real mode without backend
    }
  };
  
  const isDisabled = disabled || isTransitioning;
  const statusColor = getStatusColor();
  const description = getDescription();
  
  return (
    <div className="mock-mode-toggle-container">
      <div 
        className={`mock-mode-toggle ${isDisabled ? 'disabled' : ''} ${isTransitioning ? 'transitioning' : ''}`}
        onClick={handleToggle}
        onKeyDown={handleKeyDown}
        role="switch"
        aria-checked={enabled}
        aria-label={`${label}: ${enabled ? 'enabled' : 'disabled'}`}
        aria-disabled={isDisabled}
        tabIndex={isDisabled ? -1 : 0}
      >
        <div className="mock-mode-toggle-content">
          <div className="mock-mode-toggle-label-section">
            <span className="mock-mode-toggle-label">{label}</span>
            {showDescription && (
              <span className="mock-mode-toggle-description">
                {description}
              </span>
            )}
          </div>
          
          <div className="mock-mode-toggle-switch-section">
            <div 
              className={`mock-mode-toggle-switch ${enabled ? 'enabled' : 'disabled'}`}
              style={{ 
                backgroundColor: enabled ? statusColor : '#e5e7eb',
              }}
            >
              <div 
                className="mock-mode-toggle-slider"
                style={{
                  transform: enabled ? 'translateX(20px)' : 'translateX(0)',
                }}
              />
            </div>
            
            <span 
              className="mock-mode-toggle-status"
              style={{ color: statusColor }}
            >
              {enabled ? 'ON' : 'OFF'}
            </span>
          </div>
        </div>
      </div>
      
      {!backendAvailable && !enabled && (
        <div className="mock-mode-toggle-warning">
          ⚠ Backend unavailable - mock mode will activate automatically if generation is attempted
        </div>
      )}
    </div>
  );
};

export default MockModeToggle;

