import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import './EffectKeyframes.css';
import { EffectKeyframe } from './EffectsLibrary';

export interface EffectParameter {
  id: string;
  name: string;
  min: number;
  max: number;
  defaultValue: number;
  keyframes: EffectKeyframe[];
}

interface EffectKeyframesProps {
  parameter: EffectParameter;
  duration: number; // total duration in seconds
  currentTime: number;
  onKeyframesChange: (keyframes: EffectKeyframe[]) => void;
  onValueChange: (value: number) => void;
  height?: number;
}

export const EffectKeyframes: React.FC<EffectKeyframesProps> = ({
  parameter,
  duration,
  currentTime,
  onKeyframesChange,
  onValueChange,
  height = 120,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [draggedKeyframe, setDraggedKeyframe] = useState<string | null>(null);
  const [selectedKeyframe, setSelectedKeyframe] = useState<string | null>(null);

  // Calculate current value based on keyframes
  const getCurrentValue = useCallback(() => {
    if (parameter.keyframes.length === 0) {
      return parameter.defaultValue;
    }

    // Find keyframes before and after current time
    const sortedKeyframes = [...parameter.keyframes].sort((a, b) => a.time - b.time);
    const beforeKeyframe = sortedKeyframes.filter(k => k.time <= currentTime).pop();
    const afterKeyframe = sortedKeyframes.filter(k => k.time > currentTime)[0];

    if (!beforeKeyframe) {
      return parameter.defaultValue;
    }

    if (!afterKeyframe) {
      return beforeKeyframe.value * (parameter.max - parameter.min) + parameter.min;
    }

    // Interpolate between keyframes
    const timeDiff = afterKeyframe.time - beforeKeyframe.time;
    const valueDiff = afterKeyframe.value - beforeKeyframe.value;
    const progress = (currentTime - beforeKeyframe.time) / timeDiff;

    let interpolatedValue = beforeKeyframe.value;
    switch (beforeKeyframe.interpolation) {
      case 'ease-in':
        interpolatedValue = beforeKeyframe.value + valueDiff * (progress * progress);
        break;
      case 'ease-out':
        interpolatedValue = beforeKeyframe.value + valueDiff * (1 - (1 - progress) * (1 - progress));
        break;
      case 'ease-in-out':
        const t = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
        interpolatedValue = beforeKeyframe.value + valueDiff * t;
        break;
      default: // linear
        interpolatedValue = beforeKeyframe.value + valueDiff * progress;
    }

    return interpolatedValue * (parameter.max - parameter.min) + parameter.min;
  }, [parameter, currentTime]);

  // Update current value when keyframes change
  useEffect(() => {
    const currentValue = getCurrentValue();
    onValueChange(currentValue);
  }, [getCurrentValue, onValueChange]);

  const addKeyframe = useCallback((time: number, value: number = 0.5) => {
    const newKeyframe: EffectKeyframe = {
      id: `keyframe_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      time,
      value,
      interpolation: 'linear',
    };

    const newKeyframes = [...parameter.keyframes, newKeyframe];
    onKeyframesChange(newKeyframes);
    setSelectedKeyframe(newKeyframe.id);
  }, [parameter.keyframes, onKeyframesChange]);

  const removeKeyframe = useCallback((keyframeId: string) => {
    const newKeyframes = parameter.keyframes.filter(k => k.id !== keyframeId);
    onKeyframesChange(newKeyframes);
    if (selectedKeyframe === keyframeId) {
      setSelectedKeyframe(null);
    }
  }, [parameter.keyframes, onKeyframesChange, selectedKeyframe]);

  const updateKeyframe = useCallback((keyframeId: string, updates: Partial<EffectKeyframe>) => {
    const newKeyframes = parameter.keyframes.map(k =>
      k.id === keyframeId ? { ...k, ...updates } : k
    );
    onKeyframesChange(newKeyframes);
  }, [parameter.keyframes, onKeyframesChange]);

  const handleCanvasClick = useCallback((event: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    const time = (x / rect.width) * duration;
    const value = 1 - (y / rect.height); // Invert Y axis

    // Check if clicking on existing keyframe
    const clickedKeyframe = parameter.keyframes.find(k => {
      const keyframeX = (k.time / duration) * rect.width;
      const keyframeY = (1 - k.value) * rect.height;
      const distance = Math.sqrt((x - keyframeX) ** 2 + (y - keyframeY) ** 2);
      return distance < 8; // 8px radius
    });

    if (clickedKeyframe) {
      setSelectedKeyframe(clickedKeyframe.id);
    } else {
      addKeyframe(time, value);
    }
  }, [parameter.keyframes, duration, addKeyframe]);

  const handleMouseDown = useCallback((event: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    const clickedKeyframe = parameter.keyframes.find(k => {
      const keyframeX = (k.time / duration) * rect.width;
      const keyframeY = (1 - k.value) * rect.height;
      const distance = Math.sqrt((x - keyframeX) ** 2 + (y - keyframeY) ** 2);
      return distance < 8;
    });

    if (clickedKeyframe) {
      setIsDragging(true);
      setDraggedKeyframe(clickedKeyframe.id);
    }
  }, [parameter.keyframes, duration]);

  const handleMouseMove = useCallback((event: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isDragging || !draggedKeyframe) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = Math.max(0, Math.min(rect.width, event.clientX - rect.left));
    const y = Math.max(0, Math.min(rect.height, event.clientY - rect.top));

    const time = (x / rect.width) * duration;
    const value = 1 - (y / rect.height);

    updateKeyframe(draggedKeyframe, { time, value });
  }, [isDragging, draggedKeyframe, duration, updateKeyframe]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    setDraggedKeyframe(null);
  }, []);

  // Draw the keyframe curve
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvas;

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    // Draw background grid
    ctx.strokeStyle = '#2a2a2a';
    ctx.lineWidth = 1;

    // Vertical lines (time)
    for (let i = 0; i <= 10; i++) {
      const x = (i / 10) * width;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
    }

    // Horizontal lines (value)
    for (let i = 0; i <= 4; i++) {
      const y = (i / 4) * height;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // Draw curve
    if (parameter.keyframes.length > 0) {
      const sortedKeyframes = [...parameter.keyframes].sort((a, b) => a.time - b.time);

      ctx.strokeStyle = '#7c3aed';
      ctx.lineWidth = 2;
      ctx.beginPath();

      for (let i = 0; i < sortedKeyframes.length; i++) {
        const keyframe = sortedKeyframes[i];
        const x = (keyframe.time / duration) * width;
        const y = (1 - keyframe.value) * height;

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      }

      ctx.stroke();
    }

    // Draw keyframes
    parameter.keyframes.forEach(keyframe => {
      const x = (keyframe.time / duration) * width;
      const y = (1 - keyframe.value) * height;

      ctx.fillStyle = selectedKeyframe === keyframe.id ? '#7c3aed' : '#e0e0e0';
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
      ctx.stroke();
    });

    // Draw current time indicator
    const currentX = (currentTime / duration) * width;
    ctx.strokeStyle = '#ff6b35';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(currentX, 0);
    ctx.lineTo(currentX, height);
    ctx.stroke();

  }, [parameter.keyframes, duration, currentTime, selectedKeyframe]);

  return (
    <div className="effect-keyframes">
      <div className="keyframes-header">
        <div className="parameter-info">
          <span className="parameter-name">{parameter.name}</span>
          <span className="parameter-value">
            {getCurrentValue().toFixed(2)}
          </span>
        </div>
        <div className="keyframes-actions">
          <button
            className="btn-add-keyframe"
            onClick={() => addKeyframe(currentTime)}
            title="Add keyframe at current time"
          >
            <Plus size={16} />
          </button>
          {selectedKeyframe && (
            <button
              className="btn-remove-keyframe"
              onClick={() => removeKeyframe(selectedKeyframe)}
              title="Remove selected keyframe"
            >
              <Trash2 size={16} />
            </button>
          )}
        </div>
      </div>

      <div className="keyframes-canvas-container">
        <canvas
          ref={canvasRef}
          width={400}
          height={height}
          className="keyframes-canvas"
          onClick={handleCanvasClick}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
        />
      </div>

      {selectedKeyframe && (
        <div className="keyframe-properties">
          <div className="property-group">
            <label>Interpolation:</label>
            <select
              value={parameter.keyframes.find(k => k.id === selectedKeyframe)?.interpolation || 'linear'}
              onChange={(e) => updateKeyframe(selectedKeyframe, {
                interpolation: e.target.value as EffectKeyframe['interpolation']
              })}
              aria-label="Keyframe interpolation method"
            >
              <option value="linear">Linear</option>
              <option value="ease-in">Ease In</option>
              <option value="ease-out">Ease Out</option>
              <option value="ease-in-out">Ease In-Out</option>
            </select>
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Effect Library Panel Component
 * 
 * A unified library of high-quality presets for video and audio.
 * Complements the manual EffectPanel by providing "one-click" creative looks.
 */

import React, { useState } from 'react';
import { FilterLibrary } from './FilterLibrary';
import { AudioFilterLibrary } from './AudioFilterLibrary';
import { Film, Volume2, Sparkles, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import './EffectLibraryPanel.css';

interface EffectLibraryPanelProps {
    onVideoFilterSelect: (preset: unknown) => void;
    onAudioFilterSelect: (preset: unknown) => void;
    selectedVideoFilterId?: string;
    selectedAudioFilterId?: string;
    onClose?: () => void;
}

export const EffectLibraryPanel: React.FC<EffectLibraryPanelProps> = ({
    onVideoFilterSelect,
    onAudioFilterSelect,
    selectedVideoFilterId,
    selectedAudioFilterId,
    onClose
}) => {
    const [activeTab, setActiveTab] = useState<'visual' | 'audio'>('visual');

    return (
        <div className="effect-library-panel">
            <div className="panel-header">
                <div className="header-title">
                    <Sparkles size={18} className="sparkle-icon" />
                    <h2>Bibliothèque de Styles</h2>
                </div>
                {onClose && (
                    <button className="close-btn" onClick={onClose}>
                        <X size={18} />
                    </button>
                )}
            </div>

            <div className="library-tabs">
                <button
                    className={cn("lib-tab", activeTab === 'visual' && "active")}
                    onClick={() => setActiveTab('visual')}
                >
                    <Film size={16} />
                    <span>Visuels</span>
                </button>
                <button
                    className={cn("lib-tab", activeTab === 'audio' && "active")}
                    onClick={() => setActiveTab('audio')}
                >
                    <Volume2 size={16} />
                    <span>Audio</span>
                </button>
            </div>

            <div className="library-content">
                {activeTab === 'visual' ? (
                    <FilterLibrary
                        onFilterSelect={onVideoFilterSelect}
                        selectedFilter={undefined} // Map ID to preset if needed
                    />
                ) : (
                    <AudioFilterLibrary
                        onFilterSelect={onAudioFilterSelect}
                        selectedFilterId={selectedAudioFilterId}
                    />
                )}
            </div>
        </div>
    );
};

import React, { useState, useCallback } from 'react';
import { Settings, Eye, EyeOff, Trash2, Plus, Sliders, Palette, Move, RotateCw, Zap } from 'lucide-react';
import './EffectPanel.css';

interface Effect {
  id: string;
  name: string;
  type: 'color' | 'transform' | 'temporal' | 'filter';
  enabled: boolean;
  parameters: Record<string, number | string | boolean>;
  category: string;
}

interface EffectPanelProps {
  effects: Effect[];
  onEffectAdd: (effect: Omit<Effect, 'id'>) => void;
  onEffectUpdate: (effectId: string, updates: Partial<Effect>) => void;
  onEffectRemove: (effectId: string) => void;
  onEffectReorder: (effectId: string, newIndex: number) => void;
}

export function EffectPanel({
  effects,
  onEffectAdd,
  onEffectUpdate,
  onEffectRemove,
  onEffectReorder
}: EffectPanelProps) {
  const [selectedEffectId, setSelectedEffectId] = useState<string | null>(null);
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set(['color']));

  // Group effects by category
  const effectsByCategory = effects.reduce((acc, effect) => {
    if (!acc[effect.category]) {
      acc[effect.category] = [];
    }
    acc[effect.category].push(effect);
    return acc;
  }, {} as Record<string, Effect[]>);

  const toggleCategory = useCallback((category: string) => {
    setExpandedCategories(prev => {
      const newSet = new Set(prev);
      if (newSet.has(category)) {
        newSet.delete(category);
      } else {
        newSet.add(category);
      }
      return newSet;
    });
  }, []);

  const handleParameterChange = useCallback((effectId: string, param: string, value: unknown) => {
    const effect = effects.find(e => e.id === effectId);
    if (!effect) return;

    onEffectUpdate(effectId, {
      parameters: {
        ...effect.parameters,
        [param]: value
      }
    });
  }, [effects, onEffectUpdate]);

  const getEffectIcon = (type: Effect['type']) => {
    switch (type) {
      case 'color': return <Palette size={16} />;
      case 'transform': return <Move size={16} />;
      case 'temporal': return <Zap size={16} />;
      case 'filter': return <Sliders size={16} />;
      default: return <Settings size={16} />;
    }
  };

  const renderEffectControls = (effect: Effect) => {
    switch (effect.type) {
      case 'color':
        return (
          <div className="effect-controls color-controls">
            <div className="control-group">
              <label>Brightness</label>
              <input
                type="range"
                min="-100"
                max="100"
                value={effect.parameters.brightness || 0}
                onChange={(e) => handleParameterChange(effect.id, 'brightness', parseInt(e.target.value))}
              />
              <span>{effect.parameters.brightness || 0}</span>
            </div>
            <div className="control-group">
              <label>Contrast</label>
              <input
                type="range"
                min="-100"
                max="100"
                value={effect.parameters.contrast || 0}
                onChange={(e) => handleParameterChange(effect.id, 'contrast', parseInt(e.target.value))}
              />
              <span>{effect.parameters.contrast || 0}</span>
            </div>
            <div className="control-group">
              <label>Saturation</label>
              <input
                type="range"
                min="-100"
                max="100"
                value={effect.parameters.saturation || 0}
                onChange={(e) => handleParameterChange(effect.id, 'saturation', parseInt(e.target.value))}
              />
              <span>{effect.parameters.saturation || 0}</span>
            </div>
            <div className="control-group">
              <label>Hue</label>
              <input
                type="range"
                min="0"
                max="360"
                value={effect.parameters.hue || 0}
                onChange={(e) => handleParameterChange(effect.id, 'hue', parseInt(e.target.value))}
              />
              <span>{effect.parameters.hue || 0}°</span>
            </div>
          </div>
        );

      case 'transform':
        return (
          <div className="effect-controls transform-controls">
            <div className="control-group">
              <label>Position X</label>
              <input
                type="range"
                min="-500"
                max="500"
                value={effect.parameters.positionX || 0}
                onChange={(e) => handleParameterChange(effect.id, 'positionX', parseInt(e.target.value))}
              />
              <span>{effect.parameters.positionX || 0}px</span>
            </div>
            <div className="control-group">
              <label>Position Y</label>
              <input
                type="range"
                min="-500"
                max="500"
                value={effect.parameters.positionY || 0}
                onChange={(e) => handleParameterChange(effect.id, 'positionY', parseInt(e.target.value))}
              />
              <span>{effect.parameters.positionY || 0}px</span>
            </div>
            <div className="control-group">
              <label>Scale</label>
              <input
                type="range"
                min="0.1"
                max="3.0"
                step="0.1"
                value={effect.parameters.scale || 1}
                onChange={(e) => handleParameterChange(effect.id, 'scale', parseFloat(e.target.value))}
              />
              <span>{effect.parameters.scale || 1}x</span>
            </div>
            <div className="control-group">
              <label>Rotation</label>
              <input
                type="range"
                min="-180"
                max="180"
                value={effect.parameters.rotation || 0}
                onChange={(e) => handleParameterChange(effect.id, 'rotation', parseInt(e.target.value))}
              />
              <span>{effect.parameters.rotation || 0}°</span>
            </div>
          </div>
        );

      case 'temporal':
        return (
          <div className="effect-controls temporal-controls">
            <div className="control-group">
              <label>Speed</label>
              <input
                type="range"
                min="0.1"
                max="4.0"
                step="0.1"
                value={effect.parameters.speed || 1}
                onChange={(e) => handleParameterChange(effect.id, 'speed', parseFloat(e.target.value))}
              />
              <span>{effect.parameters.speed || 1}x</span>
            </div>
            <div className="control-group">
              <label>Reverse</label>
              <input
                type="checkbox"
                checked={effect.parameters.reverse || false}
                onChange={(e) => handleParameterChange(effect.id, 'reverse', e.target.checked)}
              />
            </div>
          </div>
        );

      case 'filter':
        return (
          <div className="effect-controls filter-controls">
            <div className="control-group">
              <label>Intensity</label>
              <input
                type="range"
                min="0"
                max="100"
                value={effect.parameters.intensity || 50}
                onChange={(e) => handleParameterChange(effect.id, 'intensity', parseInt(e.target.value))}
              />
              <span>{effect.parameters.intensity || 50}%</span>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="effect-panel">
      <div className="panel-header">
        <h3>Effects</h3>
        <button
          className="add-effect-btn"
          onClick={() => {
            // This would typically open a menu to select effect type
            onEffectAdd({
              name: 'New Effect',
              type: 'color',
              enabled: true,
              parameters: {},
              category: 'adjustment'
            });
          }}
        >
          <Plus size={16} />
        </button>
      </div>

      <div className="effects-list">
        {Object.entries(effectsByCategory).map(([category, categoryEffects]) => (
          <div key={category} className="effect-category">
            <div
              className="category-header"
              onClick={() => toggleCategory(category)}
            >
              <span className="category-name">{category}</span>
              <span className="category-count">({categoryEffects.length})</span>
            </div>

            {expandedCategories.has(category) && (
              <div className="category-effects">
                {categoryEffects.map((effect, index) => (
                  <div
                    key={effect.id}
                    className={`effect-item ${selectedEffectId === effect.id ? 'selected' : ''}`}
                    onClick={() => setSelectedEffectId(effect.id)}
                  >
                    <div className="effect-header">
                      <div className="effect-info">
                        {getEffectIcon(effect.type)}
                        <span className="effect-name">{effect.name}</span>
                      </div>

                      <div className="effect-actions">
                        <button
                          className={`visibility-btn ${effect.enabled ? 'visible' : 'hidden'}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            onEffectUpdate(effect.id, { enabled: !effect.enabled });
                          }}
                        >
                          {effect.enabled ? <Eye size={14} /> : <EyeOff size={14} />}
                        </button>

                        <button
                          className="delete-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            onEffectRemove(effect.id);
                          }}
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>

                    {selectedEffectId === effect.id && (
                      <div className="effect-details">
                        {renderEffectControls(effect)}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}

        {effects.length === 0 && (
          <div className="no-effects">
            <p>No effects applied</p>
            <button
              className="add-first-effect-btn"
              onClick={() => {
                onEffectAdd({
                  name: 'Brightness/Contrast',
                  type: 'color',
                  enabled: true,
                  parameters: { brightness: 0, contrast: 0 },
                  category: 'adjustment'
                });
              }}
            >
              <Plus size={16} />
              Add Effect
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

