export function FilterLibrary({ onFilterSelect, selectedFilter }: FilterLibraryProps) {
  const [activeCategory, setActiveCategory] = useState<'all' | FilterPreset['category']>('all');
  const [searchTerm, setSearchTerm] = useState('');

  const categories = [
    { id: 'all', name: 'All Filters', count: FILTER_PRESETS.length },
    { id: 'basic', name: 'Basic', count: FILTER_PRESETS.filter(f => f.category === 'basic').length },
    { id: 'cinematic', name: 'Cinematic', count: FILTER_PRESETS.filter(f => f.category === 'cinematic').length },
    { id: 'vintage', name: 'Vintage', count: FILTER_PRESETS.filter(f => f.category === 'vintage').length },
    { id: 'artistic', name: 'Artistic', count: FILTER_PRESETS.filter(f => f.category === 'artistic').length },
    { id: 'color', name: 'Color', count: FILTER_PRESETS.filter(f => f.category === 'color').length },
    { id: 'mood', name: 'Mood', count: FILTER_PRESETS.filter(f => f.category === 'mood').length },
  ];

  const filteredFilters = FILTER_PRESETS.filter(filter => {
    const matchesCategory = activeCategory === 'all' || filter.category === activeCategory;
    const matchesSearch = filter.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      filter.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const popularFilters = FILTER_PRESETS.filter(f => f.popular);

  const handleFilterClick = useCallback((filter: FilterPreset) => {
    onFilterSelect(filter);
  }, [onFilterSelect]);

  return (
    <div className="filter-library">
      <div className="library-header">
        <h3>Filter Library</h3>
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search filters..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <Filter size={16} />
        </div>
      </div>

      {/* Categories */}
      <div className="categories">
        {categories.map(category => (
          <button
            key={category.id}
            className={`category-tab ${activeCategory === category.id ? 'active' : ''}`}
            onClick={() => setActiveCategory(category.id as any)}
          >
            {category.name}
            <span className="count">({category.count})</span>
          </button>
        ))}
      </div>

      {/* Popular Filters */}
      {activeCategory === 'all' && !searchTerm && (
        <div className="popular-section">
          <h4>
            <Star size={14} />
            Popular Filters
          </h4>
          <div className="popular-filters">
            {popularFilters.map(filter => (
              <div
                key={`popular-${filter.id}`}
                className={`filter-item popular ${selectedFilter?.id === filter.id ? 'selected' : ''}`}
                onClick={() => handleFilterClick(filter)}
              >
                <div className="filter-preview">
                  {filter.icon}
                  <span className="preview-emoji">{filter.preview}</span>
                </div>
                <div className="filter-info">
                  <span className="filter-name">{filter.name}</span>
                  <span className="filter-description">{filter.description}</span>
                </div>
                <div className="popular-badge">
                  <Star size={10} />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* All Filters Grid */}
      <div className="filters-grid">
        {filteredFilters.map(filter => (
          <div
            key={filter.id}
            className={`filter-item ${selectedFilter?.id === filter.id ? 'selected' : ''}`}
            onClick={() => handleFilterClick(filter)}
          >
            <div className="filter-preview">
              {filter.icon}
              <span className="preview-emoji">{filter.preview}</span>
            </div>
            <div className="filter-info">
              <span className="filter-name">{filter.name}</span>
              <span className="filter-description">{filter.description}</span>
            </div>
            {filter.popular && (
              <div className="popular-indicator">
                <Star size={10} />
              </div>
            )}
          </div>
        ))}
      </div>

      {filteredFilters.length === 0 && (
        <div className="no-filters">
          <Filter size={48} />
          <p>No filters found matching "{searchTerm}"</p>
          <button onClick={() => setSearchTerm('')}>Clear Search</button>
        </div>
      )}
    </div>
  );
}

import { Effect, EffectParameter } from './EffectsLibrary';

interface AppliedEffect extends Effect {
  enabled: boolean;
  order: number;
}

interface GPUResourceLimits {
  maxTextureSize: number;
  maxViewportDims: [number, number];
  maxRenderbufferSize: number;
  maxTextureUnits: number;
  maxFragmentUniformVectors: number;
  maxVertexUniformVectors: number;
}

interface GPUMemoryUsage {
  textures: number;
  framebuffers: number;
  shaders: number;
  buffers: number;
  totalMB: number;
}

interface PerformanceProfile {
  name: string;
  targetFPS: number;
  maxEffects: number;
  textureSize: number;
  shaderComplexity: 'low' | 'medium' | 'high';
  enableAntialiasing: boolean;
  powerPreference: 'low-power' | 'high-performance';
}

export class GPUResourceManager {
  private static instance: GPUResourceManager;
  private gl: WebGLRenderingContext | null = null;
  private limits: GPUResourceLimits | null = null;
  private memoryUsage: GPUMemoryUsage = {
    textures: 0,
    framebuffers: 0,
    shaders: 0,
    buffers: 0,
    totalMB: 0,
  };

  private performanceProfiles: PerformanceProfile[] = [
    {
      name: 'ultra-low',
      targetFPS: 15,
      maxEffects: 2,
      textureSize: 512,
      shaderComplexity: 'low',
      enableAntialiasing: false,
      powerPreference: 'low-power',
    },
    {
      name: 'low',
      targetFPS: 24,
      maxEffects: 4,
      textureSize: 720,
      shaderComplexity: 'low',
      enableAntialiasing: false,
      powerPreference: 'low-power',
    },
    {
      name: 'medium',
      targetFPS: 30,
      maxEffects: 6,
      textureSize: 1080,
      shaderComplexity: 'medium',
      enableAntialiasing: false,
      powerPreference: 'low-power',
    },
    {
      name: 'high',
      targetFPS: 45,
      maxEffects: 8,
      textureSize: 1440,
      shaderComplexity: 'medium',
      enableAntialiasing: true,
      powerPreference: 'high-performance',
    },
    {
      name: 'ultra-high',
      targetFPS: 60,
      maxEffects: 12,
      textureSize: 2160,
      shaderComplexity: 'high',
      enableAntialiasing: true,
      powerPreference: 'high-performance',
    },
  ];

  private currentProfile: PerformanceProfile = this.performanceProfiles[1]; // Default to 'low'
  private activeEffects: AppliedEffect[] = [];
  private resourcePool: Map<string, WebGLTexture | WebGLFramebuffer | WebGLProgram | WebGLBuffer> = new Map();

  private constructor() {}

  static getInstance(): GPUResourceManager {
    if (!GPUResourceManager.instance) {
      GPUResourceManager.instance = new GPUResourceManager();
    }
    return GPUResourceManager.instance;
  }

  initialize(gl: WebGLRenderingContext): boolean {
    this.gl = gl;

    // Get GPU limits
    this.limits = {
      maxTextureSize: gl.getParameter(gl.MAX_TEXTURE_SIZE),
      maxViewportDims: gl.getParameter(gl.MAX_VIEWPORT_DIMS),
      maxRenderbufferSize: gl.getParameter(gl.MAX_RENDERBUFFER_SIZE),
      maxTextureUnits: gl.getParameter(gl.MAX_TEXTURE_IMAGE_UNITS),
      maxFragmentUniformVectors: gl.getParameter(gl.MAX_FRAGMENT_UNIFORM_VECTORS),
      maxVertexUniformVectors: gl.getParameter(gl.MAX_VERTEX_UNIFORM_VECTORS),
    };

    // Auto-detect optimal performance profile based on GPU capabilities
    this.detectOptimalProfile();

    console.log('GPU Resource Manager initialized:', {
      limits: this.limits,
      profile: this.currentProfile.name,
      memoryUsage: this.memoryUsage,
    });

    return true;
  }

  private detectOptimalProfile(): void {
    if (!this.limits) return;

    const { maxTextureSize, maxFragmentUniformVectors } = this.limits;

    // Conservative approach for shared GPU usage with ComfyUI
    if (maxTextureSize >= 4096 && maxFragmentUniformVectors >= 256) {
      this.currentProfile = this.performanceProfiles.find(p => p.name === 'medium')!;
    } else if (maxTextureSize >= 2048 && maxFragmentUniformVectors >= 128) {
      this.currentProfile = this.performanceProfiles.find(p => p.name === 'low')!;
    } else {
      this.currentProfile = this.performanceProfiles.find(p => p.name === 'ultra-low')!;
    }

    // Force low-power mode when ComfyUI might be running
    this.currentProfile.powerPreference = 'low-power';
    this.currentProfile.enableAntialiasing = false;
  }

  getOptimalWebGLContextAttributes(): WebGLContextAttributes {
    return {
      alpha: false,
      depth: false,
      stencil: false,
      antialias: this.currentProfile.enableAntialiasing,
      powerPreference: this.currentProfile.powerPreference,
      failIfMajorPerformanceCaveat: false,
      preserveDrawingBuffer: false,
    };
  }

  canHandleEffects(effects: AppliedEffect[]): boolean {
    const enabledEffects = effects.filter(e => e.enabled);
    return enabledEffects.length <= this.currentProfile.maxEffects;
  }

  optimizeEffectsForGPU(effects: AppliedEffect[]): AppliedEffect[] {
    const enabledEffects = effects.filter(e => e.enabled);

    if (enabledEffects.length <= this.currentProfile.maxEffects) {
      return effects;
    }

    // Disable excess effects to stay within GPU limits
    const optimizedEffects = [...effects];
    let excessCount = enabledEffects.length - this.currentProfile.maxEffects;

    for (let i = optimizedEffects.length - 1; i >= 0 && excessCount > 0; i--) {
      if (optimizedEffects[i].enabled) {
        optimizedEffects[i] = { ...optimizedEffects[i], enabled: false };
        excessCount--;
      }
    }

    return optimizedEffects;
  }

  getShaderComplexityLevel(): 'low' | 'medium' | 'high' {
    return this.currentProfile.shaderComplexity;
  }

  getMaxTextureSize(): number {
    return Math.min(this.limits?.maxTextureSize || 2048, this.currentProfile.textureSize);
  }

  allocateTexture(key: string, width: number, height: number): WebGLTexture | null {
    if (!this.gl) return null;

    // Check memory limits
    const textureSizeMB = (width * height * 4) / (1024 * 1024); // RGBA bytes
    if (this.memoryUsage.totalMB + textureSizeMB > 256) { // 256MB limit
      console.warn('GPU memory limit reached, cannot allocate texture');
      return null;
    }

    const texture = this.gl.createTexture();
    if (texture) {
      this.resourcePool.set(key, texture);
      this.memoryUsage.textures++;
      this.memoryUsage.totalMB += textureSizeMB;
    }

    return texture;
  }

  allocateFramebuffer(key: string): WebGLFramebuffer | null {
    if (!this.gl) return null;

    if (this.memoryUsage.framebuffers >= 8) { // Limit framebuffers
      console.warn('Maximum framebuffers reached');
      return null;
    }

    const framebuffer = this.gl.createFramebuffer();
    if (framebuffer) {
      this.resourcePool.set(key, framebuffer);
      this.memoryUsage.framebuffers++;
      this.memoryUsage.totalMB += 0.1; // Rough estimate
    }

    return framebuffer;
  }

  allocateShader(key: string, program: WebGLProgram): void {
    this.resourcePool.set(key, program);
    this.memoryUsage.shaders++;
    this.memoryUsage.totalMB += 0.5; // Rough estimate for shader
  }

  deallocateResource(key: string): void {
    const resource = this.resourcePool.get(key);
    if (!resource || !this.gl) return;

    if (resource instanceof WebGLTexture) {
      this.gl.deleteTexture(resource);
      this.memoryUsage.textures = Math.max(0, this.memoryUsage.textures - 1);
      this.memoryUsage.totalMB -= 2; // Rough estimate
    } else if (resource instanceof WebGLFramebuffer) {
      this.gl.deleteFramebuffer(resource);
      this.memoryUsage.framebuffers = Math.max(0, this.memoryUsage.framebuffers - 1);
      this.memoryUsage.totalMB -= 0.1;
    } else if (resource instanceof WebGLProgram) {
      this.gl.deleteProgram(resource);
      this.memoryUsage.shaders = Math.max(0, this.memoryUsage.shaders - 1);
      this.memoryUsage.totalMB -= 0.5;
    } else if (resource instanceof WebGLBuffer) {
      this.gl.deleteBuffer(resource);
      this.memoryUsage.buffers = Math.max(0, this.memoryUsage.buffers - 1);
      this.memoryUsage.totalMB -= 0.1;
    }

    this.resourcePool.delete(key);
  }

  getMemoryUsage(): GPUMemoryUsage {
    return { ...this.memoryUsage };
  }

  getPerformanceProfile(): PerformanceProfile {
    return { ...this.currentProfile };
  }

  setPerformanceProfile(profileName: string): boolean {
    const profile = this.performanceProfiles.find(p => p.name === profileName);
    if (profile) {
      this.currentProfile = profile;
      return true;
    }
    return false;
  }

  cleanup(): void {
    if (!this.gl) return;

    // Clean up all resources
    for (const [key, resource] of this.resourcePool) {
      this.deallocateResource(key);
    }

    this.resourcePool.clear();
    this.memoryUsage = {
      textures: 0,
      framebuffers: 0,
      shaders: 0,
      buffers: 0,
      totalMB: 0,
    };
  }

  // Monitor GPU performance
  monitorPerformance(callback: (metrics: {
    fps: number;
    memoryUsage: GPUMemoryUsage;
    profile: PerformanceProfile;
  }) => void): () => void {
    let lastTime = performance.now();
    let frameCount = 0;

    const monitor = () => {
      frameCount++;
      const currentTime = performance.now();

      if (currentTime - lastTime >= 1000) { // Update every second
        const fps = Math.round((frameCount * 1000) / (currentTime - lastTime));

        callback({
          fps,
          memoryUsage: this.getMemoryUsage(),
          profile: this.getPerformanceProfile(),
        });

        frameCount = 0;
        lastTime = currentTime;
      }

      requestAnimationFrame(monitor);
    };

    const animationId = requestAnimationFrame(monitor);

    return () => cancelAnimationFrame(animationId);
  }
}

// Export singleton instance
export const gpuResourceManager = GPUResourceManager.getInstance();

import React, { useState, useCallback } from 'react';
import {
  Eye,
  EyeOff,
  Lock,
  Unlock,
  ChevronDown,
  ChevronRight,
  Plus,
  Trash2,
  Copy,
  Settings,
  Move,
  Layers
} from 'lucide-react';
import './LayerPanel.css';

export interface Layer {
  id: string;
  name: string;
  type: 'video' | 'audio' | 'text' | 'image' | 'effect' | 'adjustment';
  visible: boolean;
  locked: boolean;
  opacity: number; // 0-1
  blendMode: 'normal' | 'multiply' | 'screen' | 'overlay' | 'soft-light' | 'hard-light';
  position: { x: number; y: number; z: number };
  parentId?: string; // For grouped layers
  children?: string[]; // Child layer IDs
  collapsed?: boolean; // For group layers
}

interface LayerPanelProps {
  layers: Layer[];
  selectedLayerIds: string[];
  onLayerSelect: (layerId: string, multiSelect?: boolean) => void;
  onLayerUpdate: (layerId: string, updates: Partial<Layer>) => void;
  onLayerAdd: (type: Layer['type'], name?: string) => void;
  onLayerRemove: (layerId: string) => void;
  onLayerDuplicate: (layerId: string) => void;
  onLayerReorder: (layerId: string, newIndex: number) => void;
  onLayerGroup: (layerIds: string[], groupName?: string) => void;
  onLayerUngroup: (groupId: string) => void;
}

const BLEND_MODES = [
  { value: 'normal', label: 'Normal' },
  { value: 'multiply', label: 'Multiply' },
  { value: 'screen', label: 'Screen' },
  { value: 'overlay', label: 'Overlay' },
  { value: 'soft-light', label: 'Soft Light' },
  { value: 'hard-light', label: 'Hard Light' }
];

export function LayerPanel({
  layers,
  selectedLayerIds,
  onLayerSelect,
  onLayerUpdate,
  onLayerAdd,
  onLayerRemove,
  onLayerDuplicate,
  onLayerReorder,
  onLayerGroup,
  onLayerUngroup
}: LayerPanelProps) {
  const [draggedLayer, setDraggedLayer] = useState<string | null>(null);
  const [dragOverLayer, setDragOverLayer] = useState<string | null>(null);

  // Build hierarchical layer structure
  const buildLayerTree = useCallback(() => {
    const layerMap = new Map(layers.map(layer => [layer.id, layer]));
    const rootLayers: Layer[] = [];
    const processedIds = new Set<string>();

    // Find root layers (no parent)
    layers.forEach(layer => {
      if (!layer.parentId) {
        rootLayers.push(layer);
        processedIds.add(layer.id);
      }
    });

    // Attach children to parents
    const attachChildren = (parent: Layer): Layer => {
      if (parent.children && parent.children.length > 0) {
        parent.children.forEach(childId => {
          if (layerMap.has(childId) && !processedIds.has(childId)) {
            const child = layerMap.get(childId)!;
            attachChildren(child);
            processedIds.add(childId);
          }
        });
      }
      return parent;
    };

    return rootLayers.map(attachChildren);
  }, [layers]);

  const layerTree = buildLayerTree();

  const getLayerIcon = (type: Layer['type']) => {
    switch (type) {
      case 'video': return '🎬';
      case 'audio': return '🔊';
      case 'text': return '📝';
      case 'image': return '🖼️';
      case 'effect': return '✨';
      case 'adjustment': return '🎨';
      default: return '📄';
    }
  };

  const getLayerDepth = (layer: Layer, depth = 0): number => {
    if (!layer.parentId) return depth;
    const parent = layers.find(l => l.id === layer.parentId);
    return parent ? getLayerDepth(parent, depth + 1) : depth;
  };

  const handleDragStart = (e: React.DragEvent, layerId: string) => {
    setDraggedLayer(layerId);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, layerId: string) => {
    e.preventDefault();
    setDragOverLayer(layerId);
  };

  const handleDragEnd = () => {
    setDraggedLayer(null);
    setDragOverLayer(null);
  };

  const handleDrop = (e: React.DragEvent, targetLayerId: string) => {
    e.preventDefault();
    if (!draggedLayer || draggedLayer === targetLayerId) return;

    const draggedLayerData = layers.find(l => l.id === draggedLayer);
    const targetLayerData = layers.find(l => l.id === targetLayerId);

    if (!draggedLayerData || !targetLayerData) return;

    // For now, simple reordering (can be enhanced for grouping)
    const allLayers = [...layers];
    const draggedIndex = allLayers.findIndex(l => l.id === draggedLayer);
    const targetIndex = allLayers.findIndex(l => l.id === targetLayerId);

    if (draggedIndex !== -1 && targetIndex !== -1) {
      const [removed] = allLayers.splice(draggedIndex, 1);
      allLayers.splice(targetIndex, 0, removed);

      // Update positions (simplified - in real app, update backend)
      allLayers.forEach((layer, index) => {
        onLayerUpdate(layer.id, { position: { ...layer.position, z: index } });
      });
    }

    setDraggedLayer(null);
    setDragOverLayer(null);
  };

  const renderLayerItem = (layer: Layer, index: number) => {
    const depth = getLayerDepth(layer);
    const isSelected = selectedLayerIds.includes(layer.id);
    const isGroup = layer.children && layer.children.length > 0;
    const hasParent = !!layer.parentId;

    return (
      <div
        key={layer.id}
        className={`layer-item ${isSelected ? 'selected' : ''} ${dragOverLayer === layer.id ? 'drag-over' : ''} ${hasParent ? 'child' : ''} layer-depth-${depth}`}
        draggable={!layer.locked}
        onDragStart={(e) => handleDragStart(e, layer.id)}
        onDragOver={(e) => handleDragOver(e, layer.id)}
        onDrop={(e) => handleDrop(e, layer.id)}
        onDragEnd={handleDragEnd}
      >
        {/* Layer Controls */}
        <div className="layer-controls">
          {isGroup && (
            <button
              className="collapse-btn"
              onClick={() => onLayerUpdate(layer.id, { collapsed: !layer.collapsed })}
            >
              {layer.collapsed ? <ChevronRight size={12} /> : <ChevronDown size={12} />}
            </button>
          )}

          <button
            className={`visibility-btn ${layer.visible ? 'visible' : 'hidden'}`}
            onClick={() => onLayerUpdate(layer.id, { visible: !layer.visible })}
            title={layer.visible ? 'Hide Layer' : 'Show Layer'}
          >
            {layer.visible ? <Eye size={14} /> : <EyeOff size={14} />}
          </button>

          <button
            className={`lock-btn ${layer.locked ? 'locked' : 'unlocked'}`}
            onClick={() => onLayerUpdate(layer.id, { locked: !layer.locked })}
            title={layer.locked ? 'Unlock Layer' : 'Lock Layer'}
          >
            {layer.locked ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        </div>

        {/* Layer Icon and Name */}
        <div
          className="layer-info"
          onClick={() => onLayerSelect(layer.id, false)}
        >
          <span className="layer-icon">{getLayerIcon(layer.type)}</span>
          <span className="layer-name">{layer.name}</span>
          {isGroup && (
            <span className="layer-count">({layer.children?.length || 0})</span>
          )}
        </div>

        {/* Layer Actions */}
        <div className="layer-actions">
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={layer.opacity}
            onChange={(e) => onLayerUpdate(layer.id, { opacity: parseFloat(e.target.value) })}
            title={`Opacity: ${Math.round(layer.opacity * 100)}%`}
            className="opacity-slider"
          />

          <select
            value={layer.blendMode}
            onChange={(e) => onLayerUpdate(layer.id, { blendMode: e.target.value as Layer['blendMode'] })}
            title="Blend Mode"
            className="blend-mode-select"
          >
            {BLEND_MODES.map(mode => (
              <option key={mode.value} value={mode.value}>
                {mode.label}
              </option>
            ))}
          </select>

          <button
            className="action-btn"
            onClick={() => onLayerDuplicate(layer.id)}
            title="Duplicate Layer"
          >
            <Copy size={12} />
          </button>

          <button
            className="action-btn delete"
            onClick={() => onLayerRemove(layer.id)}
            title="Delete Layer"
          >
            <Trash2 size={12} />
          </button>
        </div>
      </div>
    );
  };

  const renderLayerTree = (layerList: Layer[]) => {
    return layerList.map((layer, index) => {
      const isCollapsed = layer.collapsed;
      const children = layer.children
        ? layers.filter(l => layer.children!.includes(l.id))
        : [];

      return (
        <div key={layer.id}>
          {renderLayerItem(layer, index)}
          {layer.children && layer.children.length > 0 && !isCollapsed && (
            <div className="layer-children">
              {renderLayerTree(children)}
            </div>
          )}
        </div>
      );
    });
  };

  return (
    <div className="layer-panel">
      <div className="panel-header">
        <h3>
          <Layers size={16} />
          Layers
        </h3>

        <div className="header-actions">
          <button
            className="add-layer-btn"
            onClick={() => {
              // Show layer type menu (simplified)
              onLayerAdd('video', 'New Layer');
            }}
            title="Add Layer"
          >
            <Plus size={14} />
          </button>

          {selectedLayerIds.length > 1 && (
            <button
              className="group-btn"
              onClick={() => onLayerGroup(selectedLayerIds, 'New Group')}
              title="Group Layers"
            >
              <Move size={14} />
            </button>
          )}

          {selectedLayerIds.length === 1 && layers.find(l => l.id === selectedLayerIds[0])?.children && (
            <button
              className="ungroup-btn"
              onClick={() => onLayerUngroup(selectedLayerIds[0])}
              title="Ungroup Layer"
            >
              <ChevronRight size={14} />
            </button>
          )}
        </div>
      </div>

      <div className="layers-container">
        {layerTree.length === 0 ? (
          <div className="no-layers">
            <Layers size={48} />
            <p>No layers in this composition</p>
            <button
              onClick={() => onLayerAdd('video', 'New Layer')}
              className="add-first-layer-btn"
            >
              <Plus size={16} />
              Add Layer
            </button>
          </div>
        ) : (
          renderLayerTree(layerTree)
        )}
      </div>

      {selectedLayerIds.length > 0 && (
        <div className="layer-properties">
          <h4>Layer Properties</h4>
          {selectedLayerIds.map(layerId => {
            const layer = layers.find(l => l.id === layerId);
            if (!layer) return null;

            return (
              <div key={layer.id} className="property-group">
                <h5>{layer.name}</h5>

                <div className="property-row">
                  <label>Name:</label>
                  <input
                    type="text"
                    value={layer.name}
                    onChange={(e) => onLayerUpdate(layer.id, { name: e.target.value })}
                    aria-label="Layer Name"
                    title="Layer Name"
                  />
                </div>

                <div className="property-row">
                  <label>Opacity:</label>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    value={layer.opacity}
                    onChange={(e) => onLayerUpdate(layer.id, { opacity: parseFloat(e.target.value) })}
                    aria-label="Layer Opacity"
                    title={`Layer Opacity: ${Math.round(layer.opacity * 100)}%`}
                  />
                  <span>{Math.round(layer.opacity * 100)}%</span>
                </div>

                <div className="property-row">
                  <label>Position:</label>
                  <input
                    type="number"
                    value={layer.position.x}
                    onChange={(e) => onLayerUpdate(layer.id, {
                      position: { ...layer.position, x: parseInt(e.target.value) }
                    })}
                    placeholder="X"
                    aria-label="Position X"
                    title="Position X"
                  />
                  <input
                    type="number"
                    value={layer.position.y}
                    onChange={(e) => onLayerUpdate(layer.id, {
                      position: { ...layer.position, y: parseInt(e.target.value) }
                    })}
                    placeholder="Y"
                    aria-label="Position Y"
                    title="Position Y"
                  />
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useState, useCallback, useRef } from 'react';
import {
  Folder,
  FolderOpen,
  File,
  Image,
  Video,
  Music,
  Upload,
  Search,
  Filter,
  Grid,
  List,
  Download,
  Trash2,
  Star,
  Tag,
  Calendar,
  HardDrive
} from 'lucide-react';
import './MediaLibrary.css';

interface MediaAsset {
  id: string;
  name: string;
  type: 'video' | 'audio' | 'image' | 'document';
  url: string;
  thumbnail?: string;
  duration?: number; // for video/audio
  size: number; // bytes
  dimensions?: { width: number; height: number }; // for images/videos
  dateCreated: Date;
  dateModified: Date;
  tags: string[];
  folderId: string;
  favorite: boolean;
  metadata: {
    codec?: string;
    bitrate?: number;
    frameRate?: number;
    sampleRate?: number;
  };
}

interface MediaFolder {
  id: string;
  name: string;
  parentId?: string;
  children: string[];
  expanded: boolean;
  assetCount: number;
}

interface MediaLibraryProps {
  assets: MediaAsset[];
  folders: MediaFolder[];
  selectedAssetIds: string[];
  onAssetSelect: (assetId: string, multiSelect?: boolean) => void;
  onAssetImport: (files: FileList) => void;
  onAssetDelete: (assetId: string) => void;
  onAssetDownload: (assetId: string) => void;
  onAssetFavorite: (assetId: string) => void;
  onFolderCreate: (name: string, parentId?: string) => void;
  onFolderDelete: (folderId: string) => void;
  onAssetMove: (assetId: string, folderId: string) => void;
}

const VIEW_MODES = {
  GRID: 'grid',
  LIST: 'list'
} as const;

const SORT_OPTIONS = [
  { value: 'name', label: 'Name' },
  { value: 'dateModified', label: 'Date Modified' },
  { value: 'dateCreated', label: 'Date Created' },
  { value: 'size', label: 'Size' },
  { value: 'type', label: 'Type' }
];

export function MediaLibrary({
  assets,
  folders,
  selectedAssetIds,
  onAssetSelect,
  onAssetImport,
  onAssetDelete,
  onAssetDownload,
  onAssetFavorite,
  onFolderCreate,
  onFolderDelete,
  onAssetMove
}: MediaLibraryProps) {
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedFolderId, setSelectedFolderId] = useState<string>('root');
  const [sortBy, setSortBy] = useState('dateModified');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [filterType, setFilterType] = useState<string>('all');
  const [showUpload, setShowUpload] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const dropZoneRef = useRef<HTMLDivElement>(null);

  // Get current folder assets
  const currentFolderAssets = assets.filter(asset =>
    asset.folderId === selectedFolderId
  );

  // Filter and sort assets
  const filteredAssets = currentFolderAssets
    .filter(asset => {
      const matchesSearch = asset.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           asset.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesType = filterType === 'all' || asset.type === filterType;
      return matchesSearch && matchesType;
    })
    .sort((a, b) => {
      let aValue: unknown = a[sortBy as keyof MediaAsset];
      let bValue: unknown = b[sortBy as keyof MediaAsset];

      if (sortBy === 'size') {
        aValue = a.size;
        bValue = b.size;
      } else if (sortBy.startsWith('date')) {
        aValue = a[sortBy as keyof MediaAsset] as Date;
        bValue = b[sortBy as keyof MediaAsset] as Date;
      }

      if (aValue < bValue) return sortOrder === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

  // Build folder tree
  const buildFolderTree = useCallback(() => {
    const folderMap = new Map(folders.map(f => [f.id, f]));
    const rootFolders: MediaFolder[] = [];

    folders.forEach(folder => {
      if (!folder.parentId) {
        rootFolders.push(folder);
      }
    });

    const attachChildren = (parent: MediaFolder): MediaFolder => {
      parent.children.forEach(childId => {
        if (folderMap.has(childId)) {
          attachChildren(folderMap.get(childId)!);
        }
      });
      return parent;
    };

    return rootFolders.map(attachChildren);
  }, [folders]);

  const folderTree = buildFolderTree();

  const getAssetIcon = (type: MediaAsset['type']) => {
    switch (type) {
      case 'video': return <Video size={16} />;
      case 'audio': return <Music size={16} />;
      case 'image': return <Image size={16} />;
      default: return <File size={16} />;
    }
  };

  const formatFileSize = (bytes: number) => {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;

    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }

    return `${size.toFixed(1)} ${units[unitIndex]}`;
  };

  const formatDuration = (seconds?: number) => {
    if (!seconds) return '';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleFileUpload = useCallback((files: FileList) => {
    onAssetImport(files);
    setShowUpload(false);
  }, [onAssetImport]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileUpload(files);
    }
  }, [handleFileUpload]);

  const handleFolderClick = useCallback((folderId: string) => {
    setSelectedFolderId(folderId);
  }, []);

  const renderFolderTree = (folderList: MediaFolder[], depth = 0) => {
    return folderList.map(folder => (
      <div key={folder.id} style={{ paddingLeft: `${depth * 16}px` }}>
        <div
          className={`folder-item ${selectedFolderId === folder.id ? 'selected' : ''}`}
          onClick={() => handleFolderClick(folder.id)}
        >
          {folder.children.length > 0 ? (
            folder.expanded ? <FolderOpen size={16} /> : <Folder size={16} />
          ) : (
            <Folder size={16} />
          )}
          <span className="folder-name">{folder.name}</span>
          <span className="folder-count">({folder.assetCount})</span>
        </div>

        {folder.expanded && folder.children.length > 0 && (
          <div className="folder-children">
            {renderFolderTree(
              folders.filter(f => folder.children.includes(f.id)),
              depth + 1
            )}
          </div>
        )}
      </div>
    ));
  };

  const renderAssetGrid = (asset: MediaAsset) => (
    <div
      key={asset.id}
      className={`asset-item grid ${selectedAssetIds.includes(asset.id) ? 'selected' : ''}`}
      onClick={() => onAssetSelect(asset.id, false)}
    >
      <div className="asset-preview">
        {asset.thumbnail ? (
          <img src={asset.thumbnail} alt={asset.name} />
        ) : (
          <div className="asset-placeholder">
            {getAssetIcon(asset.type)}
          </div>
        )}

        {asset.favorite && (
          <div className="favorite-badge">
            <Star size={12} />
          </div>
        )}
      </div>

      <div className="asset-info">
        <div className="asset-name" title={asset.name}>
          {asset.name}
        </div>
        <div className="asset-meta">
          {asset.type === 'video' || asset.type === 'audio' ? (
            <span>{formatDuration(asset.duration)}</span>
          ) : asset.dimensions ? (
            <span>{asset.dimensions.width}×{asset.dimensions.height}</span>
          ) : null}
          <span>{formatFileSize(asset.size)}</span>
        </div>
      </div>

      <div className="asset-actions">
        <button
          className={`favorite-btn ${asset.favorite ? 'active' : ''}`}
          onClick={(e) => {
            e.stopPropagation();
            onAssetFavorite(asset.id);
          }}
          title={asset.favorite ? 'Remove from favorites' : 'Add to favorites'}
        >
          <Star size={14} />
        </button>

        <button
          className="download-btn"
          onClick={(e) => {
            e.stopPropagation();
            onAssetDownload(asset.id);
          }}
          title="Download"
        >
          <Download size={14} />
        </button>

        <button
          className="delete-btn"
          onClick={(e) => {
            e.stopPropagation();
            if (confirm(`Delete "${asset.name}"?`)) {
              onAssetDelete(asset.id);
            }
          }}
          title="Delete"
        >
          <Trash2 size={14} />
        </button>
      </div>
    </div>
  );

  const renderAssetList = (asset: MediaAsset) => (
    <div
      key={asset.id}
      className={`asset-item list ${selectedAssetIds.includes(asset.id) ? 'selected' : ''}`}
      onClick={() => onAssetSelect(asset.id, false)}
    >
      <div className="asset-icon">
        {getAssetIcon(asset.type)}
      </div>

      <div className="asset-preview-small">
        {asset.thumbnail ? (
          <img src={asset.thumbnail} alt={asset.name} />
        ) : (
          <div className="asset-placeholder-small">
            {getAssetIcon(asset.type)}
          </div>
        )}
      </div>

      <div className="asset-details">
        <div className="asset-name">{asset.name}</div>
        <div className="asset-meta">
          <span className="asset-type">{asset.type}</span>
          <span className="asset-size">{formatFileSize(asset.size)}</span>
          {asset.duration && (
            <span className="asset-duration">{formatDuration(asset.duration)}</span>
          )}
          <span className="asset-date">
            {asset.dateModified.toLocaleDateString()}
          </span>
        </div>
      </div>

      <div className="asset-tags">
        {asset.tags.slice(0, 3).map(tag => (
          <span key={tag} className="tag">{tag}</span>
        ))}
        {asset.tags.length > 3 && (
          <span className="tag more">+{asset.tags.length - 3}</span>
        )}
      </div>

      <div className="asset-actions">
        <button
          className={`favorite-btn ${asset.favorite ? 'active' : ''}`}
          onClick={(e) => {
            e.stopPropagation();
            onAssetFavorite(asset.id);
          }}
        >
          <Star size={14} />
        </button>

        <button
          className="download-btn"
          onClick={(e) => {
            e.stopPropagation();
            onAssetDownload(asset.id);
          }}
        >
          <Download size={14} />
        </button>

        <button
          className="delete-btn"
          onClick={(e) => {
            e.stopPropagation();
            if (confirm(`Delete "${asset.name}"?`)) {
              onAssetDelete(asset.id);
            }
          }}
        >
          <Trash2 size={14} />
        </button>
      </div>
    </div>
  );

  return (
    <div className="media-library">
      {/* Header */}
      <div className="library-header">
        <div className="header-left">
          <HardDrive size={20} />
          <h3>Media Library</h3>
        </div>

        <div className="header-actions">
          <button
            className={`view-btn ${viewMode === 'grid' ? 'active' : ''}`}
            onClick={() => setViewMode('grid')}
            title="Grid View"
          >
            <Grid size={16} />
          </button>

          <button
            className={`view-btn ${viewMode === 'list' ? 'active' : ''}`}
            onClick={() => setViewMode('list')}
            title="List View"
          >
            <List size={16} />
          </button>

          <button
            className="upload-btn"
            onClick={() => setShowUpload(true)}
            title="Upload Files"
          >
            <Upload size={16} />
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="library-toolbar">
        <div className="search-bar">
          <Search size={16} />
          <input
            type="text"
            placeholder="Search media..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="filters">
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
          >
            <option value="all">All Types</option>
            <option value="video">Videos</option>
            <option value="audio">Audio</option>
            <option value="image">Images</option>
            <option value="document">Documents</option>
          </select>

          <select
            value={`${sortBy}-${sortOrder}`}
            onChange={(e) => {
              const [field, order] = e.target.value.split('-');
              setSortBy(field);
              setSortOrder(order as 'asc' | 'desc');
            }}
          >
            {SORT_OPTIONS.map(option => (
              <>
                <option key={`${option.value}-desc`} value={`${option.value}-desc`}>
                  {option.label} ↓
                </option>
                <option key={`${option.value}-asc`} value={`${option.value}-asc`}>
                  {option.label} ↑
                </option>
              </>
            ))}
          </select>
        </div>
      </div>

      <div className="library-content">
        {/* Folders Sidebar */}
        <div className="folders-sidebar">
          <div className="folders-header">
            <h4>Folders</h4>
            <button
              className="add-folder-btn"
              onClick={() => {
                const name = prompt('Enter folder name:');
                if (name) {
                  onFolderCreate(name, selectedFolderId === 'root' ? undefined : selectedFolderId);
                }
              }}
              title="Create Folder"
            >
              <Folder size={14} />
            </button>
          </div>

          <div className="folders-tree">
            <div
              className={`folder-item ${selectedFolderId === 'root' ? 'selected' : ''}`}
              onClick={() => handleFolderClick('root')}
            >
              <HardDrive size={16} />
              <span className="folder-name">All Media</span>
              <span className="folder-count">({assets.length})</span>
            </div>

            {renderFolderTree(folderTree)}
          </div>
        </div>

        {/* Assets Area */}
        <div className="assets-area">
          <div
            ref={dropZoneRef}
            className={`assets-container ${viewMode}`}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
          >
            {filteredAssets.length === 0 ? (
              <div className="no-assets">
                <Upload size={48} />
                <h4>No media found</h4>
                <p>Drag files here or click upload to get started</p>
                <button
                  className="upload-empty-btn"
                  onClick={() => setShowUpload(true)}
                >
                  Upload Files
                </button>
              </div>
            ) : (
              filteredAssets.map(asset =>
                viewMode === 'grid'
                  ? renderAssetGrid(asset)
                  : renderAssetList(asset)
              )
            )}
          </div>
        </div>
      </div>

      {/* Upload Modal */}
      {showUpload && (
        <div className="upload-modal-overlay">
          <div className="upload-modal">
            <div className="upload-header">
              <h4>Upload Media Files</h4>
              <button onClick={() => setShowUpload(false)}>×</button>
            </div>

            <div className="upload-content">
              <div
                className="upload-dropzone"
                onClick={() => fileInputRef.current?.click()}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
              >
                <Upload size={48} />
                <h4>Drop files here or click to browse</h4>
                <p>Supported formats: MP4, MOV, JPG, PNG, MP3, WAV</p>
              </div>

              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept="video/*,audio/*,image/*"
                style={{ display: 'none' }}
                onChange={(e) => e.target.files && handleFileUpload(e.target.files)}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Settings, Wand2, Save, X } from 'lucide-react';
import { Scene } from '@/types/sequencePlan';

export interface AIPromptGeneratorProps {
  scene: Scene | undefined;
  onPromptGenerated: (prompt: string) => void;
  onClose: () => void;
  className?: string;
}

export const AIPromptGenerator: React.FC<AIPromptGeneratorProps> = ({
  scene,
  onPromptGenerated,
  onClose,
  className = ''
}) => {
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [generatedPrompt, setGeneratedPrompt] = React.useState('');

  const handleGenerate = async () => {
    if (!scene) return;

    setIsGenerating(true);
    // Mock AI generation - would call actual LLM service
    setTimeout(() => {
      const prompt = `Create a cinematic scene in ${scene.title}: ${scene.description}. The scene should be visually striking with dramatic lighting and composition.`;
      setGeneratedPrompt(prompt);
      setIsGenerating(false);
    }, 2000);
  };

  const handleAccept = () => {
    if (generatedPrompt) {
      onPromptGenerated(generatedPrompt);
      onClose();
    }
  };

  return (
    <div className={`ai-prompt-generator ${className}`}>
      <div className="generator-header">
        <h3>Génération de Prompt IA</h3>
        <button className="close-btn" onClick={onClose} aria-label="Close prompt generator">
          <X size={16} />
        </button>
      </div>

      <div className="generator-content">
        <div className="scene-info">
          <h4>{scene?.title}</h4>
          <p>{scene?.description}</p>
        </div>

        <div className="prompt-output">
          <textarea
            value={generatedPrompt}
            onChange={(e) => setGeneratedPrompt(e.target.value)}
            placeholder="Le prompt généré apparaîtra ici..."
            rows={8}
          />
        </div>

        <div className="generator-actions">
          <button
            className="generate-btn"
            onClick={handleGenerate}
            disabled={isGenerating}
          >
            {isGenerating ? (
              <>Génération...</>
            ) : (
              <>
                <Wand2 size={16} />
                Générer Prompt
              </>
            )}
          </button>

          {generatedPrompt && (
            <button className="accept-btn" onClick={handleAccept}>
              <Save size={16} />
              Accepter
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Volume2, Speaker } from 'lucide-react';

export interface AudioSurroundPreviewProps {
  surroundMode: '5.1' | '7.1';
  elements: Array<{
    id: string;
    name: string;
    audio?: {
      enabled: boolean;
      speakerAssignment: string;
      volume: number;
    };
  }>;
  className?: string;
}

export const AudioSurroundPreview: React.FC<AudioSurroundPreviewProps> = ({
  surroundMode,
  elements,
  className = ''
}) => {
  const speakers = surroundMode === '5.1'
    ? ['front-left', 'front-center', 'front-right', 'surround-left', 'surround-right', 'lfe']
    : ['front-left', 'front-center', 'front-right', 'surround-left', 'surround-right', 'back-left', 'back-right', 'lfe'];

  const getElementsForSpeaker = (speaker: string) => {
    return elements.filter(el =>
      el.audio?.enabled &&
      (el.audio.speakerAssignment === speaker || el.audio.speakerAssignment === 'auto')
    );
  };

  return (
    <div className={`audio-surround-preview ${className}`}>
      <div className="preview-header">
        <Volume2 size={16} />
        <span>Configuration {surroundMode}</span>
      </div>

      <div className="surround-layout">
        {/* Front speakers */}
        <div className="speaker-row front">
          <div className="speaker front-left">
            <Speaker size={14} />
            <span>L</span>
            {getElementsForSpeaker('front-left').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('front-left').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>

          <div className="speaker front-center">
            <Speaker size={14} />
            <span>C</span>
            {getElementsForSpeaker('front-center').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('front-center').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>

          <div className="speaker front-right">
            <Speaker size={14} />
            <span>R</span>
            {getElementsForSpeaker('front-right').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('front-right').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Surround speakers */}
        <div className="speaker-row surround">
          <div className="speaker surround-left">
            <Speaker size={14} />
            <span>SL</span>
            {getElementsForSpeaker('surround-left').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('surround-left').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>

          <div className="speaker lfe">
            <Speaker size={14} />
            <span>LFE</span>
            {getElementsForSpeaker('lfe').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('lfe').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>

          <div className="speaker surround-right">
            <Speaker size={14} />
            <span>SR</span>
            {getElementsForSpeaker('surround-right').length > 0 && (
              <div className="speaker-elements">
                {getElementsForSpeaker('surround-right').map(el => (
                  <div key={el.id} className="element-dot" title={el.name} />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Back speakers (7.1 only) */}
        {surroundMode === '7.1' && (
          <div className="speaker-row back">
            <div className="speaker back-left">
              <Speaker size={14} />
              <span>BL</span>
              {getElementsForSpeaker('back-left').length > 0 && (
                <div className="speaker-elements">
                  {getElementsForSpeaker('back-left').map(el => (
                    <div key={el.id} className="element-dot" title={el.name} />
                  ))}
                </div>
              )}
            </div>

            <div className="speaker back-right">
              <Speaker size={14} />
              <span>BR</span>
              {getElementsForSpeaker('back-right').length > 0 && (
                <div className="speaker-elements">
                  {getElementsForSpeaker('back-right').map(el => (
                    <div key={el.id} className="element-dot" title={el.name} />
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, ChevronLeft, ChevronRight, Wand2, Save, Eye, Volume2 } from 'lucide-react';
import { LLMService } from '../../../services/llmService';
import { ttsService } from '../../../services/ttsService';
import { EnhancedCharacterAssistant } from '../../wizard/character-creator/EnhancedCharacterAssistant';
import { ConfigManager } from '../../../services/llm/ConfigManager';

export interface CharacterCreatorWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (character: unknown) => void;
  worldContext?: unknown; // From project world/lore
}

interface CharacterData {
  name: string;
  gender: 'male' | 'female' | 'other';
  age: number;
  personality: string[];
  appearance: string;
  backstory: string;
  voiceId: string;
  abilities: string[];
  worldRelation: string; // How it relates to the project world
}

export const CharacterCreatorWizard: React.FC<CharacterCreatorWizardProps> = ({
  isOpen,
  onClose,
  onSave,
  worldContext
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [character, setCharacter] = useState<CharacterData>({
    name: '',
    gender: 'other',
    age: 25,
    personality: [],
    appearance: '',
    backstory: '',
    voiceId: '',
    abilities: [],
    worldRelation: ''
  });

  const [llmSuggestions, setLlmSuggestions] = useState<any>({});
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<{[key: number]: string[]}>({});
  const [isPlayingPreview, setIsPlayingPreview] = useState(false);
  const [audioPreviewUrl, setAudioPreviewUrl] = useState<string | null>(null);

  // Auto-save functionality
  const [draftData, setDraftData] = useState<CharacterData | null>(null);

  // Character templates for quick start
  const characterTemplates = [
    {
      id: 'hero',
      name: 'Héros',
      description: 'Personnage principal courageux et déterminé',
      icon: '⚔️',
      baseStats: {
        personality: ['Courageux', 'Déterminé', 'Protecteur'],
        abilities: ['Combat au corps à corps', 'Leadership']
      }
    },
    {
      id: 'mage',
      name: 'Mage',
      description: 'Maître des arts mystiques et de la magie',
      icon: '🔮',
      baseStats: {
        personality: ['Sage', 'Curieux', 'Réservé'],
        abilities: ['Magie élémentaire', 'Télékinésie']
      }
    },
    {
      id: 'rogue',
      name: 'Voleur',
      description: 'Expert en discrétion et en subterfuges',
      icon: '🗡️',
      baseStats: {
        personality: ['Rusé', 'Indépendant', 'Mystérieux'],
        abilities: ['Furtivité', 'Crochetage']
      }
    },
    {
      id: 'scholar',
      name: 'Érudit',
      description: 'Chercheur de connaissances et de vérités',
      icon: '📚',
      baseStats: {
        personality: ['Intelligent', 'Analytique', 'Curieux'],
        abilities: ['Connaissances étendues', 'Analyse rapide']
      }
    },
    {
      id: 'villain',
      name: 'Antagoniste',
      description: 'Adversaire avec motivations complexes',
      icon: '👹',
      baseStats: {
        personality: ['Ambitieux', 'Intelligent', 'Manipulateur'],
        abilities: ['Stratégie avancée', 'Manipulation mentale']
      }
    },
    {
      id: 'mentor',
      name: 'Mentor',
      description: 'Guide sage et expérimenté',
      icon: '🧙‍♂️',
      baseStats: {
        personality: ['Sage', 'Patient', 'Inspirant'],
        abilities: ['Enseignement', 'Conseil stratégique']
      }
    },
    {
      id: 'sidekick',
      name: 'Compagnon',
      description: 'Ami loyal et humoristique',
      icon: '🤝',
      baseStats: {
        personality: ['Loyal', 'Humoristique', 'Fiable'],
        abilities: ['Soutien logistique', 'Évasion rapide']
      }
    },
    {
      id: 'rebel',
      name: 'Rebelle',
      description: 'En rébellion contre l\'autorité',
      icon: '🚩',
      baseStats: {
        personality: ['Révolté', 'Passionné', 'Idéaliste'],
        abilities: ['Guérilla urbaine', 'Propagande']
      }
    },
    {
      id: 'mystic',
      name: 'Mystique',
      description: 'Figure spirituelle et énigmatique',
      icon: '✨',
      baseStats: {
        personality: ['Énigmatique', 'Spirituel', 'Introspectif'],
        abilities: ['Prémonition', 'Communication spirituelle']
      }
    }
  ];

  const steps = [
    { title: 'Template de Personnage', description: 'Choisissez un archétype de départ' },
    { title: 'Informations de Base', description: 'Nom, genre, âge' },
    { title: 'Personnalité & Apparence', description: 'Traits et description physique' },
    { title: 'Histoire & Contexte', description: 'Backstory et lien au monde' },
    { title: 'Capacités & Voix', description: 'Pouvoirs et voix SAPI' },
    { title: 'Aperçu & Sauvegarde', description: 'Validation finale' }
  ];

  useEffect(() => {
    if (worldContext) {
      // Generate LLM suggestions based on world
      generateLlmSuggestions();
    }
  }, [worldContext]);

  // Auto-save functionality
  useEffect(() => {
    // Restore draft on component mount
    const savedDraft = localStorage.getItem('characterCreator_draft');
    if (savedDraft) {
      try {
        const draft = JSON.parse(savedDraft);
        const draftAge = Date.now() - draft.timestamp;
        // Only restore if draft is less than 24 hours old
        if (draftAge < 24 * 60 * 60 * 1000) {
          setDraftData(draft.data);
          setCharacter(draft.data);
          setSelectedTemplate(draft.selectedTemplate || null);
        } else {
          // Clean up old draft
          localStorage.removeItem('characterCreator_draft');
        }
      } catch (error) {
        console.error('Error restoring draft:', error);
        localStorage.removeItem('characterCreator_draft');
      }
    }

    // Start auto-save timer
    const timer = setInterval(() => {
      autoSave();
    }, 30000); // 30 seconds

    // Cleanup on unmount
    return () => {
      if (timer) {
        clearInterval(timer);
      }
    };
  }, []);

  const autoSave = () => {
    const draftToSave = {
      data: character,
      selectedTemplate,
      timestamp: Date.now()
    };
    localStorage.setItem('characterCreator_draft', JSON.stringify(draftToSave));
    setDraftData(character);
  };

  const clearDraft = () => {
    localStorage.removeItem('characterCreator_draft');
    setDraftData(null);
  };

  const getGenreString = (genre: unknown): string => {
    // Handle different cases safely
    if (!genre) {
      return 'fantastique';
    }

    if (typeof genre === 'string') {
      return genre;
    }

    if (Array.isArray(genre)) {
      return genre.join(', ');
    }

    return String(genre);
  };

  const generateLlmSuggestions = async () => {
    if (!worldContext) return;

    try {
      // Get properly configured LLM service from ConfigManager
      const llmConfig = ConfigManager.getLLMConfig();
      // Cast to required type to fix type mismatch
      const llmService = new LLMService(llmConfig as any);

      // Safely get genre string with proper error handling
      const genreString = getGenreString(worldContext.genre);
      const rulesString = worldContext.rules && Array.isArray(worldContext.rules)
        ? worldContext.rules.map((r: unknown) => r.rule).join(', ')
        : 'magie et technologie';

      // Enhanced prompts with more world context
      const namePrompt = `Pour un monde ${genreString} avec ces caractéristiques: ${worldContext.description || 'monde fantastique'}, génère 5 noms de personnages originaux et immersifs. Les noms doivent être cohérents avec le genre et l'ambiance du monde. Format: nom1, nom2, nom3, nom4, nom5`;

      const personalityPrompt = `Dans un monde ${genreString} (${worldContext.atmosphere || 'mystérieux'}), décris 4 traits de personnalité complexes et intéressants pour des personnages. Chaque trait doit être unique et adapté au contexte du monde. Format: trait1, trait2, trait3, trait4`;

      const abilityPrompt = `Pour un monde ${genreString} avec ces règles: ${rulesString}, quelles seraient 4 capacités ou pouvoirs uniques et équilibrés ? Chaque capacité doit être cohérente avec les règles du monde. Format: capacité1, capacité2, capacité3, capacité4`;

      const backstoryPrompt = `Génère 3 concepts d'histoire personnelle courte pour un personnage dans ce monde: ${worldContext.description || 'monde fantastique'}. Chaque backstory doit être intrigante et liée aux éléments culturels du monde. Format: histoire1 | histoire2 | histoire3`;

      // Parallel generation for better performance
      const [nameResponse, personalityResponse, abilityResponse, backstoryResponse] = await Promise.all([
        llmService.generateText(namePrompt, { temperature: 0.8, maxTokens: 150 }),
        llmService.generateText(personalityPrompt, { temperature: 0.7, maxTokens: 150 }),
        llmService.generateText(abilityPrompt, { temperature: 0.7, maxTokens: 150 }),
        llmService.generateText(backstoryPrompt, { temperature: 0.8, maxTokens: 200 })
      ]);

      const names = nameResponse.split(',').map(n => n.trim()).filter(n => n.length > 0).slice(0, 5);
      const personalities = personalityResponse.split(',').map(p => p.trim()).filter(p => p.length > 0).slice(0, 4);
      const abilities = abilityResponse.split(',').map(a => a.trim()).filter(a => a.length > 0).slice(0, 4);
      const backstories = backstoryResponse.split('|').map(b => b.trim()).filter(b => b.length > 0).slice(0, 3);

      setLlmSuggestions({
        name: names,
        personality: personalities,
        abilities: abilities,
        backstory: backstories
      });
    } catch (error) {
      console.error('Erreur lors de la génération des suggestions LLM:', error);
      // Enhanced fallback with world-aware defaults
      setLlmSuggestions({
        name: ['Elyndor', 'Sylvana', 'Tharivol', 'Morwen', 'Kaelith'],
        personality: ['Courageux et déterminé', 'Sage et mystérieux', 'Charismatique et ambitieux', 'Réservé et observateur'],
        abilities: ['Manipulation des éléments', 'Communication animale', 'Art de l\'illusion', 'Maîtrise des ombres'],
        backstory: [
          'Ancien guerrier ayant perdu son royaume dans une guerre ancienne',
          'Mage errant à la recherche d\'un artefact légendaire',
          'Enfant des rues devenu maître voleur dans les bas-fonds'
        ]
      });
    }
  };

  const applyTemplate = (templateId: string) => {
    const template = characterTemplates.find(t => t.id === templateId);
    if (template) {
      setSelectedTemplate(templateId);
      updateCharacter('personality', template.baseStats.personality);
      updateCharacter('abilities', template.baseStats.abilities);
    }
  };

  const validateStep = (stepIndex: number): string[] => {
    const errors: string[] = [];

    switch (stepIndex) {
      case 1: // Basic Information
        if (!character.name.trim()) {
          errors.push("Le nom du personnage est obligatoire");
        }
        break;
      case 2: // Personality & Appearance
        if (character.personality.length === 0) {
          errors.push("Au moins un trait de personnalité est requis");
        }
        if (!character.appearance.trim()) {
          errors.push("La description de l'apparence est obligatoire");
        }
        break;
      case 3: // History & Context
        if (!character.backstory.trim()) {
          errors.push("L'histoire personnelle est obligatoire");
        }
        if (!character.worldRelation.trim()) {
          errors.push("La relation au monde du projet est obligatoire");
        }
        break;
      case 4: // Abilities & Voice
        if (character.abilities.length === 0) {
          errors.push("Au moins une capacité est requise");
        }
        if (!character.voiceId) {
          errors.push("La sélection d'une voix SAPI est obligatoire");
        }
        break;
      default:
        break;
    }

    return errors;
  };

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      const errors = validateStep(currentStep);
      if (errors.length > 0) {
        setValidationErrors({ ...validationErrors, [currentStep]: errors });
        return;
      }

      // Clear any previous errors for this step
      const newErrors = { ...validationErrors };
      delete newErrors[currentStep];
      setValidationErrors(newErrors);

      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSave = () => {
    onSave(character);
    clearDraft(); // Clear the draft after successful save
    onClose();
  };

  const updateCharacter = (field: keyof CharacterData, value: unknown) => {
    setCharacter(prev => ({ ...prev, [field]: value }));
  };

  const previewVoice = async () => {
    if (!character.voiceId) return;

    setIsPlayingPreview(true);
    try {
      const previewText = `Bonjour, je m'appelle ${character.name || 'votre personnage'}. Voici un aperçu de ma voix.`;

      // Create a voice over object for the TTS service
      const voiceOver = {
        id: `preview_${Date.now()}`,
        text: previewText,
        voice: character.voiceId.startsWith('Microsoft-') ? character.voiceId.replace('Microsoft-', '').toLowerCase() : character.voiceId,
        language: character.voiceId.includes('Hortense') ? 'fr-FR' : 'en-US',
        speed: 1.0,
        pitch: 0,
        emotion: 'neutral' as const
      };

      const audioUrl = await ttsService.generateVoiceOver(voiceOver);
      setAudioPreviewUrl(audioUrl);

      // Play the audio
      const audio = new Audio(audioUrl);
      audio.play();

      // Clean up after playing
      audio.onended = () => {
        URL.revokeObjectURL(audioUrl);
        setAudioPreviewUrl(null);
      };

    } catch (error) {
      console.error('Erreur lors de la prévisualisation audio:', error);
    } finally {
      setIsPlayingPreview(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full mx-4 max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b">
          <div>
            <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              Créateur de Personnage
              {draftData && (
                <span className="text-xs bg-orange-100 text-orange-800 px-2 py-1 rounded-full">
                  Brouillon restauré
                </span>
              )}
            </h2>
            <p className="text-gray-600">Étape {currentStep + 1} sur {steps.length}: {steps[currentStep].title}</p>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600" title="Fermer">
            <X size={24} />
          </button>
        </div>

        {/* Progress Bar */}
        <div className="px-6 py-4">
          <div className="flex items-center space-x-2">
            {steps.map((step, index) => (
              <div key={index} className="flex flex-col items-center flex-1">
                <button
                  onClick={() => {
                    // Allow navigation backwards freely
                    if (index < currentStep) {
                      setCurrentStep(index);
                    }
                    // For forwards navigation, could add validation here later
                  }}
                  className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all ${
                    index <= currentStep
                      ? 'bg-blue-500 text-white'
                      : index === currentStep + 1
                      ? 'bg-gray-300 text-gray-600 cursor-pointer hover:bg-gray-400'
                      : 'bg-gray-200 text-gray-400'
                  }`}
                  disabled={index > currentStep + 1}
                >
                  {index + 1}
                </button>
                <div className="mt-2 text-xs text-center">
                  <div className={`font-medium ${index <= currentStep ? 'text-blue-600' : 'text-gray-400'}`}>
                    {step.title}
                  </div>
                  <div className="text-gray-500 hidden sm:block">
                    {step.description}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Validation Errors */}
        {validationErrors[currentStep] && validationErrors[currentStep].length > 0 && (
          <div className="mx-6 mb-4 p-4 bg-red-50 border border-red-200 rounded-md">
            <div className="flex items-start gap-2">
              <div className="text-red-500 font-medium">❌ Erreurs de validation:</div>
            </div>
            <ul className="mt-2 space-y-1">
              {validationErrors[currentStep].map((error, index) => (
                <li key={index} className="text-sm text-red-700">• {error}</li>
              ))}
            </ul>
          </div>
        )}

        {/* Content */}
        <div className="px-6 py-4 overflow-y-auto max-h-96">
          {currentStep === 0 && (
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-medium text-gray-900 mb-4">Choisissez un archétype de personnage</h3>
                <p className="text-gray-600 mb-6">Sélectionnez un template pour commencer rapidement, ou passez cette étape pour créer un personnage personnalisé.</p>

                <div className="grid grid-cols-2 gap-4">
                  {characterTemplates.map((template) => (
                    <div
                      key={template.id}
                      onClick={() => applyTemplate(template.id)}
                      className={`p-4 border-2 rounded-lg cursor-pointer transition-all ${
                        selectedTemplate === template.id
                          ? 'border-blue-500 bg-blue-50'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <div className="text-2xl mb-2">{template.icon}</div>
                      <h4 className="font-medium text-gray-900">{template.name}</h4>
                      <p className="text-sm text-gray-600 mt-1">{template.description}</p>
                      <div className="mt-3">
                        <div className="text-xs text-gray-500">Traits: {template.baseStats.personality.join(', ')}</div>
                        <div className="text-xs text-gray-500">Capacités: {template.baseStats.abilities.join(', ')}</div>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="mt-6 p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-600">
                    💡 <strong>Conseil:</strong> Vous pouvez modifier tous les aspects du personnage dans les étapes suivantes,
                    même si vous choisissez un template.
                  </p>
                </div>
              </div>
            </div>
          )}

          {currentStep === 1 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Nom</label>
                <input
                  type="text"
                  value={character.name}
                  onChange={(e) => updateCharacter('name', e.target.value)}
                  className="w-full border border-gray-300 rounded-md shadow-sm p-2 mb-2"
                  placeholder="Entrez le nom du personnage"
                />
                <EnhancedCharacterAssistant
                  worldContext={worldContext}
                  characterData={character}
                  onSuggestion={(field, value) => updateCharacter(field as keyof CharacterData, value)}
                  suggestionType="name"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700" htmlFor="gender">Genre</label>
                <select
                  id="gender"
                  value={character.gender}
                  onChange={(e) => updateCharacter('gender', e.target.value as any)}
                  className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                  title="Sélectionnez le genre du personnage"
                >
                  <option value="male">Masculin</option>
                  <option value="female">Féminin</option>
                  <option value="other">Autre</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700" htmlFor="age">Âge</label>
                <input
                  id="age"
                  type="number"
                  value={character.age}
                  onChange={(e) => updateCharacter('age', parseInt(e.target.value))}
                  className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                  min="1"
                  max="200"
                  placeholder="Entrez l'âge"
                />
              </div>
            </div>
          )}

          {currentStep === 2 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Traits de Personnalité</label>
                <div className="mt-2 space-y-2">
                  <div className="flex flex-wrap gap-2">
                    {character.personality.map((trait, index) => (
                      <span key={index} className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm">
                        {trait}
                        <button
                          onClick={() => updateCharacter('personality', character.personality.filter((_, i) => i !== index))}
                          className="ml-2 text-blue-600 hover:text-blue-800"
                        >
                          ×
                        </button>
                      </span>
                    ))}
                  </div>
                  <EnhancedCharacterAssistant
                    worldContext={worldContext}
                    characterData={character}
                    onSuggestion={(field, value) => updateCharacter(field as keyof CharacterData, value)}
                    suggestionType="personality"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Apparence Physique</label>
                <textarea
                  value={character.appearance}
                  onChange={(e) => updateCharacter('appearance', e.target.value)}
                  className="w-full border border-gray-300 rounded-md shadow-sm p-2 mb-2"
                  rows={3}
                  placeholder="Décrivez l'apparence du personnage"
                />
                <EnhancedCharacterAssistant
                  worldContext={worldContext}
                  characterData={character}
                  onSuggestion={(field, value) => updateCharacter(field as keyof CharacterData, value)}
                  suggestionType="appearance"
                />
              </div>
            </div>
          )}

          {currentStep === 3 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Histoire Personnelle</label>
                <textarea
                  value={character.backstory}
                  onChange={(e) => updateCharacter('backstory', e.target.value)}
                  className="w-full border border-gray-300 rounded-md shadow-sm p-2 mb-2"
                  rows={4}
                  placeholder="Racontez l'histoire du personnage"
                />
                <EnhancedCharacterAssistant
                  worldContext={worldContext}
                  characterData={character}
                  onSuggestion={(field, value) => updateCharacter(field as keyof CharacterData, value)}
                  suggestionType="backstory"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Relation au Monde du Projet</label>
                <textarea
                  value={character.worldRelation}
                  onChange={(e) => updateCharacter('worldRelation', e.target.value)}
                  className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                  rows={3}
                  placeholder="Comment ce personnage s'intègre-t-il au monde de votre projet ?"
                />
                {worldContext && (
                  <p className="text-sm text-gray-600 mt-2">
                    Monde détecté: {getGenreString(worldContext.genre)} - {worldContext.description}
                  </p>
                )}
              </div>
            </div>
          )}

          {currentStep === 4 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Capacités/Pouvoirs</label>
                <div className="mt-2 space-y-2">
                  <div className="flex flex-wrap gap-2">
                    {character.abilities.map((ability, index) => (
                      <span key={index} className="px-3 py-1 bg-purple-100 text-purple-800 rounded-full text-sm">
                        {ability}
                        <button
                          onClick={() => updateCharacter('abilities', character.abilities.filter((_, i) => i !== index))}
                          className="ml-2 text-purple-600 hover:text-purple-800"
                        >
                          ×
                        </button>
                      </span>
                    ))}
                  </div>
                  <EnhancedCharacterAssistant
                    worldContext={worldContext}
                    characterData={character}
                    onSuggestion={(field, value) => updateCharacter(field as keyof CharacterData, value)}
                    suggestionType="abilities"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700" htmlFor="voiceId">Voix SAPI</label>
                <div className="flex gap-2">
                  <select
                    id="voiceId"
                    value={character.voiceId}
                    onChange={(e) => updateCharacter('voiceId', e.target.value)}
                    className="flex-1 border border-gray-300 rounded-md shadow-sm p-2"
                    title="Sélectionnez une voix SAPI pour le personnage"
                  >
                    <option value="">Sélectionnez une voix</option>
                    <option value="Microsoft-Zira">Zira (Femme, Anglais)</option>
                    <option value="Microsoft-David">David (Homme, Anglais)</option>
                    <option value="Microsoft-Hortense">Hortense (Femme, Français)</option>
                    {/* Add more voices from SAPIService */}
                  </select>
                  <button
                    onClick={previewVoice}
                    disabled={!character.voiceId || isPlayingPreview}
                    className="px-3 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1"
                    title="Aperçu de la voix"
                  >
                    <Volume2 size={16} />
                    {isPlayingPreview ? '...' : 'Aperçu'}
                  </button>
                </div>
                {audioPreviewUrl && (
                  <div className="mt-2 p-2 bg-green-50 border border-green-200 rounded-md">
                    <p className="text-sm text-green-800">🎵 Aperçu audio généré avec succès</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {currentStep === 5 && (
            <div className="space-y-6">
              <div className="bg-gradient-to-r from-blue-50 to-purple-50 p-6 rounded-lg border">
                <h3 className="text-xl font-bold mb-4 text-gray-900 flex items-center gap-2">
                  <Eye size={20} />
                  Aperçu Final du Personnage
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Informations de Base</h4>
                      <div className="space-y-1 text-sm">
                        <div><strong>Nom:</strong> {character.name || 'Non défini'}</div>
                        <div><strong>Genre:</strong> {character.gender === 'male' ? 'Masculin' : character.gender === 'female' ? 'Féminin' : 'Autre'}</div>
                        <div><strong>Âge:</strong> {character.age} ans</div>
                        <div><strong>Voix:</strong> {character.voiceId || 'Non définie'}</div>
                      </div>
                    </div>

                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Traits de Personnalité</h4>
                      <div className="flex flex-wrap gap-1">
                        {character.personality.length > 0 ? (
                          character.personality.map((trait, index) => (
                            <span key={index} className="px-2 py-1 bg-green-100 text-green-800 rounded-full text-xs">
                              {trait}
                            </span>
                          ))
                        ) : (
                          <span className="text-gray-500 text-sm">Aucun trait défini</span>
                        )}
                      </div>
                    </div>

                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Capacités</h4>
                      <div className="flex flex-wrap gap-1">
                        {character.abilities.length > 0 ? (
                          character.abilities.map((ability, index) => (
                            <span key={index} className="px-2 py-1 bg-purple-100 text-purple-800 rounded-full text-xs">
                              {ability}
                            </span>
                          ))
                        ) : (
                          <span className="text-gray-500 text-sm">Aucune capacité définie</span>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Apparence Physique</h4>
                      <p className="text-sm text-gray-700">
                        {character.appearance || 'Non décrite'}
                      </p>
                    </div>

                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Histoire Personnelle</h4>
                      <p className="text-sm text-gray-700 line-clamp-4">
                        {character.backstory || 'Non racontée'}
                      </p>
                    </div>

                    <div className="bg-white p-4 rounded-md shadow-sm">
                      <h4 className="font-semibold text-gray-800 mb-2">Lien au Monde</h4>
                      <p className="text-sm text-gray-700">
                        {character.worldRelation || 'Non défini'}
                      </p>
                      {worldContext && (
                        <p className="text-xs text-gray-500 mt-1">
                          Monde: {getGenreString(worldContext.genre)} - {worldContext.description}
                        </p>
                      )}
                    </div>
                  </div>
                </div>

                <div className="mt-6 p-4 bg-yellow-50 border border-yellow-200 rounded-md">
                  <p className="text-sm text-yellow-800">
                    <strong>Validation:</strong> Assurez-vous que tous les champs importants sont remplis.
                    Le personnage sera sauvegardé dans votre projet et pourra être utilisé dans vos séquences.
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 border-t">
          <button
            onClick={handlePrevious}
            disabled={currentStep === 0}
            className="flex items-center px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <ChevronLeft size={16} className="mr-2" />
            Précédent
          </button>
          <div className="flex space-x-2">
            {currentStep < steps.length - 1 ? (
              <button
                onClick={handleNext}
                className="flex items-center px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600"
              >
                Suivant
                <ChevronRight size={16} className="ml-2" />
              </button>
            ) : (
              <button
                onClick={handleSave}
                className="flex items-center px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600"
              >
                <Save size={16} className="mr-2" />
                Sauvegarder
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

