import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Volume2, VolumeX } from 'lucide-react';
import './AudioWaveform.css';

interface AudioWaveformProps {
  audioUrl?: string;
  duration: number;
  currentTime: number;
  volume?: number;
  isMuted?: boolean;
  onVolumeChange?: (volume: number) => void;
  onMuteToggle?: () => void;
  height?: number;
  className?: string;
}

export const AudioWaveform: React.FC<AudioWaveformProps> = ({
  audioUrl,
  duration,
  currentTime,
  volume = 1,
  isMuted = false,
  onVolumeChange,
  onMuteToggle,
  height = 60,
  className = '',
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [waveformData, setWaveformData] = useState<number[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Generate mock waveform data (in a real implementation, this would analyze the audio file)
  const generateWaveformData = useCallback((samples: number = 200) => {
    const data: number[] = [];
    for (let i = 0; i < samples; i++) {
      // Create a more realistic waveform with some variation
      const baseHeight = Math.random() * 0.3 + 0.2; // Base height between 0.2 and 0.5
      const variation = Math.sin(i * 0.1) * 0.2; // Sine wave variation
      const noise = (Math.random() - 0.5) * 0.1; // Random noise
      data.push(Math.max(0.05, Math.min(1, baseHeight + variation + noise)));
    }
    return data;
  }, []);

  // Load and analyze audio file
  useEffect(() => {
    if (!audioUrl) {
      // Generate mock data if no audio URL provided
      setWaveformData(generateWaveformData());
      return;
    }

    setIsLoading(true);
    // In a real implementation, you would:
    // 1. Load the audio file
    // 2. Use Web Audio API to analyze the waveform
    // 3. Generate waveform data from the audio buffer
    // For now, we'll use mock data
    setTimeout(() => {
      setWaveformData(generateWaveformData());
      setIsLoading(false);
    }, 500);
  }, [audioUrl, generateWaveformData]);

  // Draw waveform on canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || waveformData.length === 0) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const canvasHeight = canvas.height;

    // Clear canvas
    ctx.clearRect(0, 0, width, canvasHeight);

    // Draw waveform
    const barWidth = width / waveformData.length;
    const centerY = canvasHeight / 2;

    waveformData.forEach((amplitude, index) => {
      const x = index * barWidth;
      const barHeight = amplitude * canvasHeight * 0.8; // Scale to 80% of canvas height

      // Calculate progress-based coloring
      const progress = currentTime / duration;
      const isPlayed = index / waveformData.length <= progress;

      // Color gradient: blue for unplayed, green for played
      ctx.fillStyle = isPlayed ? '#10b981' : '#3b82f6';

      // Draw the waveform bar (centered vertically)
      ctx.fillRect(x, centerY - barHeight / 2, barWidth - 1, barHeight);
    });

    // Draw progress line
    if (duration > 0) {
      const progressX = (currentTime / duration) * width;
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(progressX, 0);
      ctx.lineTo(progressX, canvasHeight);
      ctx.stroke();
    }
  }, [waveformData, currentTime, duration]);

  const handleCanvasClick = useCallback((event: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const clickProgress = x / canvas.width;
    const newTime = clickProgress * duration;

    // In a real implementation, you would call onTimeChange here
    // For now, we'll just log it
    console.log('Waveform clicked at time:', newTime);
  }, [duration]);

  return (
    <div className={`audio-waveform ${className}`}>
      <div className="waveform-header">
        <div className="waveform-info">
          <span className="waveform-label">Audio Track</span>
          {audioUrl && <span className="waveform-duration">{formatTime(duration)}</span>}
        </div>

        <div className="waveform-controls">
          {/* Volume slider */}
          <div className="volume-control">
            <button
              className="volume-btn"
              onClick={onMuteToggle}
              title={isMuted ? 'Unmute' : 'Mute'}
            >
              {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={isMuted ? 0 : volume}
              onChange={(e) => onVolumeChange?.(parseFloat(e.target.value))}
              className="volume-slider"
            />
            <span className="volume-value">{Math.round((isMuted ? 0 : volume) * 100)}%</span>
          </div>
        </div>
      </div>

      <div className="waveform-canvas-container">
        {isLoading ? (
          <div className="waveform-loading">
            <div className="loading-spinner"></div>
            <span>Loading audio...</span>
          </div>
        ) : (
          <canvas
            ref={canvasRef}
            width={800}
            height={height}
            className="waveform-canvas"
            onClick={handleCanvasClick}
            style={{ cursor: 'pointer' }}
          />
        )}
      </div>
    </div>
  );
};

// Utility function to format time
function formatTime(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
}

import React, { useMemo } from 'react';

interface TimelineRulerProps {
  duration: number;
  zoom: number;
  currentTime: number;
  fps?: number;
}

export function TimelineRuler({ duration, zoom, currentTime, fps = 30 }: TimelineRulerProps) {
  // Calculate major and minor tick intervals based on zoom
  const tickIntervals = useMemo(() => {
    const totalWidth = duration * zoom * 100; // pixels per second * zoom

    // Major ticks (with time labels)
    let majorInterval = 1; // seconds
    if (totalWidth < 500) majorInterval = 5;
    else if (totalWidth < 1000) majorInterval = 2;
    else if (totalWidth > 2000) majorInterval = 0.5;

    // Minor ticks (without labels)
    const minorInterval = majorInterval / 5;

    return { major: majorInterval, minor: minorInterval };
  }, [duration, zoom]);

  // Generate tick marks
  const ticks = useMemo(() => {
    const ticks = [];
    const { major, minor } = tickIntervals;

    // Calculate visible time range (this could be enhanced with scrolling)
    const startTime = 0;
    const endTime = duration;

    // Major ticks
    for (let time = startTime; time <= endTime; time += major) {
      const position = (time / duration) * 100;
      ticks.push({
        time,
        position,
        type: 'major',
        label: formatTime(time)
      });
    }

    // Minor ticks
    for (let time = startTime; time <= endTime; time += minor) {
      // Skip if there's already a major tick at this position
      if (time % major !== 0) {
        const position = (time / duration) * 100;
        ticks.push({
          time,
          position,
          type: 'minor',
          label: null
        });
      }
    }

    return ticks;
  }, [duration, tickIntervals]);

  // Current time indicator
  const currentTimePosition = (currentTime / duration) * 100;

  return (
    <div className="timeline-ruler">
      <div className="ruler-track">
        {ticks.map((tick, index) => (
          <div
            key={`${tick.type}-${tick.time}-${index}`}
            className={`ruler-tick ${tick.type}`}
            style={{ left: `${tick.position}%` }}
          >
            {tick.type === 'major' && tick.label && (
              <span className="tick-label">{tick.label}</span>
            )}
          </div>
        ))}

        {/* Current time indicator */}
        <div
          className="current-time-indicator"
          style={{ left: `${currentTimePosition}%` }}
        >
          <div className="time-line" />
          <div className="time-caret" />
        </div>
      </div>
    </div>
  );
}

// Format time as MM:SS, HH:MM:SS, or HH:MM:SS:FF (with frames)
function formatTime(seconds: number, showFrames: boolean = false): string {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const frames = showFrames ? Math.floor((seconds % 1) * 30) : 0; // Assuming 30fps

  if (hours > 0) {
    if (showFrames) {
      return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
    } else {
      return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }
  } else {
    if (showFrames) {
      return `${minutes}:${secs.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
    } else {
      return `${minutes}:${secs.toString().padStart(2, '0')}`;
    }
  }
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Play, Pause, SkipBack, SkipForward, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';

interface TimelineScrubberProps {
  currentTime: number;
  duration: number;
  zoom: number;
  isPlaying: boolean;
  onTimeChange: (time: number) => void;
  onPlayPause: () => void;
  onZoomChange: (zoom: number) => void;
  onFrameStep: (direction: 'forward' | 'backward') => void;
  loopEnabled?: boolean;
  onLoopToggle?: () => void;
}

export function TimelineScrubber({
  currentTime,
  duration,
  zoom,
  isPlaying,
  onTimeChange,
  onPlayPause,
  onZoomChange,
  onFrameStep,
  loopEnabled = false,
  onLoopToggle
