/**
 * Asset Preview Panel Component
 * 
 * Unified component for displaying generated assets of any type (image, video, audio, prompt).
 * Provides asset display, metadata viewer, export controls, regenerate button, and related assets.
 * 
 * Requirements: 9.2, 9.3, 9.4
 */

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import {
  Download,
  RefreshCw,
  Image as ImageIcon,
  Video as VideoIcon,
  Volume2 as AudioIcon,
  FileText,
  Calendar,
  HardDrive,
  Link2,
  ExternalLink,
} from 'lucide-react';
import type { GeneratedAsset, ExportFormat } from '../../types/generation';
import { ImagePreviewPanel } from './ImagePreviewPanel';
import { VideoPreviewPanel } from './VideoPreviewPanel';
import { AudioPreviewPanel } from './AudioPreviewPanel';

export interface AssetPreviewPanelProps {
  /**
   * Generated asset to display
   */
  asset: GeneratedAsset;
  
  /**
   * Callback when save is clicked
   */
  onSave?: (asset: GeneratedAsset) => void;
  
  /**
   * Callback when export is clicked
   */
  onExport?: (asset: GeneratedAsset, format: ExportFormat) => void;
  
  /**
   * Callback when regenerate is clicked
   */
  onRegenerate?: () => void;
  
  /**
   * Related assets in the pipeline
   */
  relatedAssets?: GeneratedAsset[];
  
  /**
   * Callback when a related asset is clicked
   */
  onRelatedAssetClick?: (asset: GeneratedAsset) => void;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Format file size for display
 */
const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`;
};

/**
 * Format timestamp for display
 */
const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  return date.toLocaleString();
};

/**
 * Get asset type icon
 */
const getAssetIcon = (type: GeneratedAsset['type']) => {
  switch (type) {
    case 'image':
      return ImageIcon;
    case 'video':
      return VideoIcon;
    case 'audio':
      return AudioIcon;
    case 'prompt':
      return FileText;
    default:
      return FileText;
  }
};

/**
 * Get asset type label
 */
const getAssetTypeLabel = (type: GeneratedAsset['type']): string => {
  switch (type) {
    case 'image':
      return 'Image';
    case 'video':
      return 'Video';
    case 'audio':
      return 'Audio';
    case 'prompt':
      return 'Prompt';
    default:
      return 'Asset';
  }
};

/**
 * Get available export formats for asset type
 */
const getExportFormats = (type: GeneratedAsset['type']): ExportFormat[] => {
  switch (type) {
    case 'image':
      return ['original', 'png', 'jpg'];
    case 'video':
      return ['original', 'mp4', 'webm'];
    case 'audio':
      return ['original', 'wav', 'mp3'];
    case 'prompt':
      return ['original'];
    default:
      return ['original'];
  }
};

/**
 * Asset Preview Panel
 * 
 * Unified component that displays any type of generated asset with appropriate
 * preview, metadata, export controls, and related assets.
 */
export const AssetPreviewPanel: React.FC<AssetPreviewPanelProps> = ({
  asset,
  onSave,
  onExport,
  onRegenerate,
  relatedAssets = [],
  onRelatedAssetClick,
  className = '',
}) => {
  const [selectedExportFormat, setSelectedExportFormat] = useState<ExportFormat>('original');
  
  const { metadata } = asset;
  const { fileSize, format } = metadata;
  const AssetIcon = getAssetIcon(asset.type);
  const assetTypeLabel = getAssetTypeLabel(asset.type);
  const exportFormats = getExportFormats(asset.type);
  
  /**
   * Handle save action
   */
  const handleSave = () => {
    if (onSave) {
      onSave(asset);
    }
  };
  
  /**
   * Handle export action
   */
  const handleExport = () => {
    if (onExport) {
      onExport(asset, selectedExportFormat);
    }
  };
  
  /**
   * Handle regenerate action
   */
  const handleRegenerate = () => {
    if (onRegenerate) {
      onRegenerate();
    }
  };
  
  /**
   * Handle related asset click
   */
  const handleRelatedAssetClick = (relatedAsset: GeneratedAsset) => {
    if (onRelatedAssetClick) {
      onRelatedAssetClick(relatedAsset);
    }
  };
  
  // For specialized asset types, use their dedicated preview panels
  if (asset.type === 'image') {
    return (
      <div className={className}>
        <ImagePreviewPanel
          asset={asset}
          onSave={onSave}
          onRegenerate={onRegenerate}
        />
        {relatedAssets.length > 0 && (
          <RelatedAssetsSection
            relatedAssets={relatedAssets}
            onAssetClick={handleRelatedAssetClick}
            className="mt-4"
          />
        )}
      </div>
    );
  }
  
  if (asset.type === 'video') {
    return (
      <div className={className}>
        <VideoPreviewPanel
          asset={asset}
          onSave={onSave}
          onRegenerate={onRegenerate}
        />
        {relatedAssets.length > 0 && (
          <RelatedAssetsSection
            relatedAssets={relatedAssets}
            onAssetClick={handleRelatedAssetClick}
            className="mt-4"
          />
        )}
      </div>
    );
  }
  
  if (asset.type === 'audio') {
    return (
      <div className={className}>
        <AudioPreviewPanel
          asset={asset}
          onSave={onSave}
          onRegenerate={onRegenerate}
        />
        {relatedAssets.length > 0 && (
          <RelatedAssetsSection
            relatedAssets={relatedAssets}
            onAssetClick={handleRelatedAssetClick}
            className="mt-4"
          />
        )}
      </div>
    );
  }
  
  // Generic asset preview for prompt or unknown types
  return (
    <div className={className}>
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <AssetIcon className="h-5 w-5" />
            Generated {assetTypeLabel}
          </CardTitle>
          <CardDescription>
            {assetTypeLabel} generated successfully. You can save, export, or regenerate.
          </CardDescription>
        </CardHeader>
        
        <CardContent className="space-y-4">
          {/* Asset Display */}
          {asset.type === 'prompt' && metadata.generationParams.text && (
            <div className="p-4 bg-muted rounded-lg">
              <p className="text-sm whitespace-pre-wrap">
                {metadata.generationParams.text}
              </p>
            </div>
          )}
          
          {/* Metadata */}
          <div className="space-y-2">
            <h4 className="text-sm font-semibold">Metadata</h4>
            <div className="grid grid-cols-2 gap-2 text-sm">
              {/* File Size */}
              <div className="flex items-center gap-2">
                <HardDrive className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Size:</span>
                <Badge variant="secondary">{formatFileSize(fileSize)}</Badge>
              </div>
              
              {/* Format */}
              <div className="flex items-center gap-2">
                <AssetIcon className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Format:</span>
                <Badge variant="secondary">{format.toUpperCase()}</Badge>
              </div>
              
              {/* Timestamp */}
              <div className="flex items-center gap-2 col-span-2">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Created:</span>
                <Badge variant="secondary">{formatTimestamp(asset.timestamp)}</Badge>
              </div>
            </div>
          </div>
          
          <Separator />
          
          {/* Generation Parameters */}
          <div className="space-y-2">
            <h4 className="text-sm font-semibold">Generation Parameters</h4>
            <div className="grid grid-cols-2 gap-2 text-sm">
              {Object.entries(metadata.generationParams).map(([key, value]) => {
                // Skip text field as it's displayed above
                if (key === 'text') return null;
                
                return (
                  <div key={key}>
                    <span className="text-muted-foreground capitalize">
                      {key.replace(/([A-Z])/g, ' $1').trim()}:
                    </span>{' '}
                    <span className="font-medium">
                      {typeof value === 'object' ? JSON.stringify(value) : String(value)}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
          
          {/* Export Format Selection */}
          {onExport && exportFormats.length > 1 && (
            <>
              <Separator />
              <div className="space-y-2">
                <h4 className="text-sm font-semibold">Export Format</h4>
                <div className="flex flex-wrap gap-2">
                  {exportFormats.map((format) => (
                    <Button
                      key={format}
                      variant={selectedExportFormat === format ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => setSelectedExportFormat(format)}
                    >
                      {format.toUpperCase()}
                    </Button>
                  ))}
                </div>
              </div>
            </>
          )}
        </CardContent>
        
        <CardFooter className="flex flex-wrap gap-2">
          {/* Save Button */}
          {onSave && (
            <Button variant="outline" onClick={handleSave}>
              <Download className="mr-2 h-4 w-4" />
              Save
            </Button>
          )}
          
          {/* Export Button */}
          {onExport && (
            <Button variant="outline" onClick={handleExport}>
              <ExternalLink className="mr-2 h-4 w-4" />
              Export as {selectedExportFormat.toUpperCase()}
            </Button>
          )}
          
          {/* Regenerate Button */}
          {onRegenerate && (
            <Button variant="outline" onClick={handleRegenerate} className="ml-auto">
              <RefreshCw className="mr-2 h-4 w-4" />
              Regenerate
            </Button>
          )}
        </CardFooter>
      </Card>
      
      {/* Related Assets */}
      {relatedAssets.length > 0 && (
        <RelatedAssetsSection
          relatedAssets={relatedAssets}
          onAssetClick={handleRelatedAssetClick}
          className="mt-4"
        />
      )}
    </div>
  );
};

/**
 * Related Assets Section Component
 * 
 * Displays related assets in the pipeline with thumbnails and metadata.
 */
interface RelatedAssetsSectionProps {
  relatedAssets: GeneratedAsset[];
  onAssetClick?: (asset: GeneratedAsset) => void;
  className?: string;
}

const RelatedAssetsSection: React.FC<RelatedAssetsSectionProps> = ({
  relatedAssets,
  onAssetClick,
  className = '',
}) => {
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <Link2 className="h-4 w-4" />
          Related Assets in Pipeline
        </CardTitle>
        <CardDescription>
          Assets generated in the same pipeline workflow
        </CardDescription>
      </CardHeader>
      
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {relatedAssets.map((relatedAsset) => {
            const RelatedIcon = getAssetIcon(relatedAsset.type);
            const relatedLabel = getAssetTypeLabel(relatedAsset.type);
            
            return (
              <button
                key={relatedAsset.id}
                onClick={() => onAssetClick?.(relatedAsset)}
                className="group relative aspect-square rounded-lg border bg-muted/30 overflow-hidden hover:border-primary transition-colors"
              >
                {/* Thumbnail */}
                {relatedAsset.type === 'image' && (
                  <img
                    src={relatedAsset.url}
                    alt={`Related ${relatedLabel}`}
                    className="w-full h-full object-cover"
                  />
                )}
                
                {relatedAsset.type === 'video' && (
                  <video
                    src={relatedAsset.url}
                    className="w-full h-full object-cover"
                    muted
                  />
                )}
                
                {(relatedAsset.type === 'audio' || relatedAsset.type === 'prompt') && (
                  <div className="w-full h-full flex items-center justify-center">
                    <RelatedIcon className="h-12 w-12 text-muted-foreground" />
                  </div>
                )}
                
                {/* Overlay */}
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white p-2">
                  <RelatedIcon className="h-6 w-6 mb-2" />
                  <span className="text-xs font-medium">{relatedLabel}</span>
                  <span className="text-xs text-white/80 mt-1">
                    {formatTimestamp(relatedAsset.timestamp)}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
};

/**
 * Audio Generation Dialog Component
 * 
 * Dialog for generating audio and voiceovers using TTS services.
 * Provides parameter controls and integrates with the generation pipeline.
 * 
 * Requirements: 4.1, 4.2, 4.3, 4.4, 10.3, 10.4
 */

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Slider } from '../ui/slider';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { Loader2, Volume2, Check, AlertCircle, Play } from 'lucide-react';
import { generationOrchestrator } from '../../services/GenerationOrchestrator';
import { useGenerationStore } from '../../stores/generationStore';
import type { AudioGenerationParams } from '../../types/generation';
import { ErrorDisplay } from './ErrorDisplay';
import { PresetManager } from './PresetManager';
import type { AudioPreset } from '../../services/PresetManagementService';
import {
  categorizeError,
  preserveStateOnError,
  type CategorizedError,
  type PreservedState,
} from '../../utils/errorHandling';

export interface AudioGenerationDialogProps {
  /**
   * Whether the dialog is open
   */
  isOpen: boolean;
  
  /**
   * Callback when dialog is closed
   */
  onClose: () => void;
}

/**
 * Default audio generation parameters
 */
const DEFAULT_PARAMS: AudioGenerationParams = {
  text: '',
  voiceType: 'neutral',
  speed: 1.0,
  pitch: 0,
  language: 'en-US',
  emotion: 'neutral',
};

/**
 * Available languages
 */
const LANGUAGES = [
  { value: 'en-US', label: 'English (US)' },
  { value: 'en-GB', label: 'English (UK)' },
  { value: 'es-ES', label: 'Spanish' },
  { value: 'fr-FR', label: 'French' },
  { value: 'de-DE', label: 'German' },
  { value: 'it-IT', label: 'Italian' },
  { value: 'pt-BR', label: 'Portuguese (Brazil)' },
  { value: 'ja-JP', label: 'Japanese' },
  { value: 'ko-KR', label: 'Korean' },
  { value: 'zh-CN', label: 'Chinese (Simplified)' },
];

/**
 * Available emotions
 */
const EMOTIONS: Array<AudioGenerationParams['emotion']> = [
  'neutral',
  'happy',
  'sad',
  'excited',
  'calm',
];

/**
 * Audio Generation Dialog
 * 
 * Provides UI for configuring audio generation parameters and triggering generation.
 * Integrates with TTSService for audio generation.
 */
export const AudioGenerationDialog: React.FC<AudioGenerationDialogProps> = ({
  isOpen,
  onClose,
}) => {
  const { currentPipeline, completeStage, failStage, updateStageProgress } = useGenerationStore();
  
  // Parameters state
  const [params, setParams] = useState<AudioGenerationParams>(DEFAULT_PARAMS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPreviewing, setIsPreviewing] = useState(false);
  const [categorizedError, setCategorizedError] = useState<CategorizedError | null>(null);
  const [preservedState, setPreservedState] = useState<PreservedState | null>(null);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  const [previewAudioUrl, setPreviewAudioUrl] = useState<string | null>(null);
  
  // Reset state when dialog opens
  useEffect(() => {
    if (isOpen) {
      setParams(DEFAULT_PARAMS);
      setCategorizedError(null);
      setValidationErrors({});
      setPreviewAudioUrl(null);
    }
  }, [isOpen]);
  
  /**
   * Update parameter value
   */
  const updateParam = <K extends keyof AudioGenerationParams>(
    key: K,
    value: AudioGenerationParams[K]
  ) => {
    setParams((prev) => ({
      ...prev,
      [key]: value,
    }));
    
    // Clear validation error for this field
    if (validationErrors[key]) {
      setValidationErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[key];
        return newErrors;
      });
    }
  };
  
  /**
   * Load preset parameters
   */
  const handleLoadPreset = (preset: AudioPreset) => {
    setParams((prev) => ({
      ...prev,
      ...preset.params,
    }));
  };
  
  /**
   * Validate parameters
   */
  const validateParams = (): boolean => {
    const errors: Record<string, string> = {};
    
    if (!params.text.trim()) {
      errors.text = 'Text is required';
    }
    
    if (params.text.length > 5000) {
      errors.text = 'Text must be less than 5000 characters';
    }
    
    if (params.speed < 0.5 || params.speed > 2.0) {
      errors.speed = 'Speed must be between 0.5 and 2.0';
    }
    
    if (params.pitch < -10 || params.pitch > 10) {
      errors.pitch = 'Pitch must be between -10 and 10';
    }
    
    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };
  
  /**
   * Preview audio
   */
  const handlePreview = async () => {
    // Validate parameters
    if (!validateParams()) {
      const error = new Error('Please fix the validation errors before previewing');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      return;
    }
    
    setIsPreviewing(true);
    setCategorizedError(null);
    
    try {
      const result = await generationOrchestrator.generateAudio(
        params,
        (progress) => {
          // Progress updates for preview
        },
        (error) => {
          const categorized = categorizeError(error);
          setCategorizedError(categorized);
        }
      );
      
      // Set preview audio URL
      setPreviewAudioUrl(result.url);
      
      // Play preview audio
      const audio = new Audio(result.url);
      audio.play();
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to preview audio');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
    } finally {
      setIsPreviewing(false);
    }
  };
  
  /**
   * Generate final audio
   */
  const handleGenerate = async () => {
    // Validate parameters
    if (!validateParams()) {
      const error = new Error('Please fix the validation errors before generating');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      return;
    }
    
    setIsGenerating(true);
    setCategorizedError(null);
    
    try {
      const result = await generationOrchestrator.generateAudio(
        params,
        (progress) => {
          updateStageProgress('audio', progress);
        },
        (error) => {
          const categorized = categorizeError(error);
          setCategorizedError(categorized);
          failStage('audio', error.message);
          
          // Preserve state on error
          const preserved = preserveStateOnError(
            categorized,
            { params },
            [],
            null
          );
          setPreservedState(preserved);
        }
      );
      
      // Complete the audio stage
      completeStage('audio', result);
      
      // Close dialog
      onClose();
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to generate audio');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      
      // Preserve state on error
      const preserved = preserveStateOnError(
        categorized,
        { params },
        [],
        null
      );
      setPreservedState(preserved);
    } finally {
      setIsGenerating(false);
    }
  };
  
  /**
   * Handle dialog close
   */
  const handleClose = () => {
    if (!isGenerating && !isPreviewing) {
      onClose();
    }
  };
  
  /**
   * Calculate character count
   */
  const characterCount = params.text.length;
  const maxCharacters = 5000;
  
  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Volume2 className="h-5 w-5" />
            Generate Audio
          </DialogTitle>
          <DialogDescription>
            Configure parameters for audio and voiceover generation using TTS.
          </DialogDescription>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          {/* Preset Manager */}
          <PresetManager
            type="audio"
            currentParams={params}
            onLoadPreset={(preset) => handleLoadPreset(preset as AudioPreset)}
          />
          
          {/* Text Input */}
          <div className="space-y-2">
            <Label htmlFor="text">
              Narration Text <span className="text-destructive">*</span>
            </Label>
            <Textarea
              id="text"
              value={params.text}
              onChange={(e) => updateParam('text', e.target.value)}
              placeholder="Enter the text to be spoken..."
              className="min-h-[150px]"
              disabled={isGenerating || isPreviewing}
            />
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Enter the text you want to convert to speech</span>
              <span className={characterCount > maxCharacters ? 'text-destructive' : ''}>
                {characterCount} / {maxCharacters}
              </span>
            </div>
            {validationErrors.text && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.text}
              </p>
            )}
          </div>
          
          {/* Voice Type */}
          <div className="space-y-2">
            <Label htmlFor="voiceType">Voice Type</Label>
            <Select
              value={params.voiceType}
              onValueChange={(value) => updateParam('voiceType', value as AudioGenerationParams['voiceType'])}
              disabled={isGenerating || isPreviewing}
            >
              <SelectTrigger id="voiceType">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="male">Male</SelectItem>
                <SelectItem value="female">Female</SelectItem>
                <SelectItem value="neutral">Neutral</SelectItem>
              </SelectContent>
            </Select>
          </div>
          
          {/* Language */}
          <div className="space-y-2">
            <Label htmlFor="language">Language</Label>
            <Select
              value={params.language}
              onValueChange={(value) => updateParam('language', value)}
              disabled={isGenerating || isPreviewing}
            >
              <SelectTrigger id="language">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {LANGUAGES.map((lang) => (
                  <SelectItem key={lang.value} value={lang.value}>
                    {lang.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          
          {/* Speed */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="speed">Speed</Label>
              <span className="text-sm text-muted-foreground">{params.speed.toFixed(2)}x</span>
            </div>
            <Slider
              id="speed"
              value={[params.speed]}
              onValueChange={([value]) => updateParam('speed', value)}
              min={0.5}
              max={2.0}
              step={0.05}
              disabled={isGenerating || isPreviewing}
            />
            <p className="text-xs text-muted-foreground">
              Adjust the speaking speed (0.5 = slow, 1.0 = normal, 2.0 = fast)
            </p>
            {validationErrors.speed && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.speed}
              </p>
            )}
          </div>
          
          {/* Pitch */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="pitch">Pitch</Label>
              <span className="text-sm text-muted-foreground">
                {params.pitch > 0 ? '+' : ''}{params.pitch}
              </span>
            </div>
            <Slider
              id="pitch"
              value={[params.pitch]}
              onValueChange={([value]) => updateParam('pitch', value)}
              min={-10}
              max={10}
              step={1}
              disabled={isGenerating || isPreviewing}
            />
            <p className="text-xs text-muted-foreground">
              Adjust the voice pitch (-10 = lower, 0 = normal, +10 = higher)
            </p>
            {validationErrors.pitch && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.pitch}
              </p>
            )}
          </div>
          
          {/* Emotion */}
          <div className="space-y-2">
            <Label htmlFor="emotion">Emotion</Label>
            <Select
              value={params.emotion}
              onValueChange={(value) => updateParam('emotion', value as AudioGenerationParams['emotion'])}
              disabled={isGenerating || isPreviewing}
            >
              <SelectTrigger id="emotion">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {EMOTIONS.map((emotion) => (
                  <SelectItem key={emotion} value={emotion}>
                    {emotion.charAt(0).toUpperCase() + emotion.slice(1)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              Select the emotional tone for the voice
            </p>
          </div>
          
          {/* Preview Audio Player */}
          {previewAudioUrl && (
            <div className="space-y-2">
              <Label>Preview</Label>
              <audio
                controls
                src={previewAudioUrl}
                className="w-full"
              />
            </div>
          )}
          
          {/* Error Display */}
          {categorizedError && (
            <ErrorDisplay
              error={categorizedError}
              onRetry={categorizedError.canRetry ? handleGenerate : undefined}
              onDismiss={() => setCategorizedError(null)}
              className="mt-4"
            />
          )}
        </div>
        
        <DialogFooter className="gap-2">
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isGenerating || isPreviewing}
          >
            Cancel
          </Button>
          
          <Button
            variant="secondary"
            onClick={handlePreview}
            disabled={isGenerating || isPreviewing || !params.text.trim()}
          >
            {isPreviewing ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Previewing...
              </>
            ) : (
              <>
                <Play className="mr-2 h-4 w-4" />
                Preview
              </>
            )}
          </Button>
          
          <Button
            onClick={handleGenerate}
            disabled={isGenerating || isPreviewing || !params.text.trim()}
          >
            {isGenerating ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Check className="mr-2 h-4 w-4" />
                Generate Audio
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Audio Preview Panel Component
 * 
 * Displays generated audio with waveform visualization, playback controls, metadata, and action buttons.
 * Provides save, regenerate, and export options.
 * Associates audio with current shot or sequence.
 * 
 * Requirements: 4.5
 */

import React, { useState, useRef, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import { Slider } from '../ui/slider';
import {
  Download,
  RefreshCw,
  Volume2 as AudioIcon,
  Calendar,
  HardDrive,
  Play,
  Pause,
  Volume2,
  VolumeX,
  Clock,
  SkipBack,
  SkipForward,
} from 'lucide-react';
import type { GeneratedAsset } from '../../types/generation';

export interface AudioPreviewPanelProps {
  /**
   * Generated audio asset
   */
  asset: GeneratedAsset;
  
  /**
   * Callback when save is clicked
   */
  onSave?: (asset: GeneratedAsset) => void;
  
  /**
   * Callback when regenerate is clicked
   */
  onRegenerate?: () => void;
  
  /**
   * Callback when audio is associated with shot/sequence
   */
  onAssociate?: (asset: GeneratedAsset) => void;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Format file size for display
 */
const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`;
};

/**
 * Format timestamp for display
 */
const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  return date.toLocaleString();
};

/**
 * Format duration for display (seconds to MM:SS)
 */
const formatDuration = (seconds: number): string => {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

/**
 * Audio Preview Panel
 * 
 * Displays generated audio with waveform visualization, playback controls, metadata, parameters, and action buttons.
 * Allows association with current shot or sequence.
 */
export const AudioPreviewPanel: React.FC<AudioPreviewPanelProps> = ({
  asset,
  onSave,
  onRegenerate,
  onAssociate,
  className = '',
}) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [waveformData, setWaveformData] = useState<number[]>([]);
  
  const { metadata } = asset;
  const { generationParams, fileSize, format } = metadata;
  const audioDuration = metadata.duration || 0;
  
  /**
   * Generate simple waveform visualization
   */
  useEffect(() => {
    // Generate mock waveform data (in production, this would analyze the audio)
    const mockWaveform = Array.from({ length: 100 }, () => Math.random());
    setWaveformData(mockWaveform);
  }, [asset.url]);
  
  /**
   * Draw waveform on canvas
   */
  useEffect(() => {
    if (!canvasRef.current || waveformData.length === 0) return;
    
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    
    // Set canvas size
    const width = canvas.width;
    const height = canvas.height;
    
    // Clear canvas
    ctx.clearRect(0, 0, width, height);
    
    // Draw waveform
    const barWidth = width / waveformData.length;
    const centerY = height / 2;
    
    ctx.fillStyle = 'hsl(var(--primary))';
    
    waveformData.forEach((value, index) => {
      const barHeight = value * centerY;
      const x = index * barWidth;
      
      // Draw bar (mirrored top and bottom)
      ctx.fillRect(x, centerY - barHeight, barWidth - 1, barHeight);
      ctx.fillRect(x, centerY, barWidth - 1, barHeight);
    });
    
    // Draw progress indicator
    if (duration > 0) {
      const progress = currentTime / duration;
      const progressX = progress * width;
      
      ctx.fillStyle = 'hsl(var(--primary) / 0.3)';
      ctx.fillRect(0, 0, progressX, height);
    }
  }, [waveformData, currentTime, duration]);
  
  /**
   * Handle play/pause toggle
   */
  const togglePlayPause = () => {
    if (!audioRef.current) return;
    
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };
  
  /**
   * Handle mute toggle
   */
  const toggleMute = () => {
    if (!audioRef.current) return;
    
    audioRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  };
  
  /**
   * Handle volume change
   */
  const handleVolumeChange = (value: number[]) => {
    if (!audioRef.current) return;
    
    const newVolume = value[0];
    audioRef.current.volume = newVolume;
    setVolume(newVolume);
    
    // Unmute if volume is increased from 0
    if (newVolume > 0 && isMuted) {
      setIsMuted(false);
      audioRef.current.muted = false;
    }
  };
  
  /**
   * Handle time update
   */
  const handleTimeUpdate = () => {
    if (!audioRef.current) return;
    setCurrentTime(audioRef.current.currentTime);
  };
  
  /**
   * Handle loaded metadata
   */
  const handleLoadedMetadata = () => {
    if (!audioRef.current) return;
    setDuration(audioRef.current.duration);
  };
  
  /**
   * Handle seek
   */
  const handleSeek = (value: number[]) => {
    if (!audioRef.current) return;
    
    const newTime = value[0];
    audioRef.current.currentTime = newTime;
    setCurrentTime(newTime);
  };
  
  /**
   * Handle audio ended
   */
  const handleAudioEnded = () => {
    setIsPlaying(false);
  };
  
  /**
   * Skip backward 10 seconds
   */
  const skipBackward = () => {
    if (!audioRef.current) return;
    audioRef.current.currentTime = Math.max(0, audioRef.current.currentTime - 10);
  };
  
  /**
   * Skip forward 10 seconds
   */
  const skipForward = () => {
    if (!audioRef.current) return;
    audioRef.current.currentTime = Math.min(duration, audioRef.current.currentTime + 10);
  };
  
  /**
   * Handle save action
   */
  const handleSave = () => {
    if (onSave) {
      onSave(asset);
    }
  };
  
  /**
   * Handle regenerate action
   */
  const handleRegenerate = () => {
    if (onRegenerate) {
      onRegenerate();
    }
  };
  
  /**
   * Handle associate action
   */
  const handleAssociate = () => {
    if (onAssociate) {
      onAssociate(asset);
    }
  };
  
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <AudioIcon className="h-5 w-5" />
          Generated Audio
        </CardTitle>
        <CardDescription>
          Audio generated successfully. You can save, regenerate, or associate with your project.
        </CardDescription>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {/* Hidden Audio Element */}
        <audio
          ref={audioRef}
          src={asset.url}
          onTimeUpdate={handleTimeUpdate}
          onLoadedMetadata={handleLoadedMetadata}
          onEnded={handleAudioEnded}
        />
        
        {/* Waveform Visualization */}
        <div className="relative">
          <canvas
            ref={canvasRef}
            width={800}
            height={120}
            className="w-full h-[120px] rounded-lg border bg-muted/30"
          />
        </div>
        
        {/* Audio Controls */}
        <div className="space-y-2">
          {/* Progress Bar */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground min-w-[40px]">
              {formatDuration(currentTime)}
            </span>
            <Slider
              value={[currentTime]}
              max={duration || 100}
              step={0.1}
              onValueChange={handleSeek}
              className="flex-1"
            />
            <span className="text-xs text-muted-foreground min-w-[40px]">
              {formatDuration(duration)}
            </span>
          </div>
          
          {/* Control Buttons */}
          <div className="flex items-center gap-2">
            {/* Skip Backward */}
            <Button
              variant="outline"
              size="icon"
              onClick={skipBackward}
            >
              <SkipBack className="h-4 w-4" />
            </Button>
            
            {/* Play/Pause */}
            <Button
              variant="outline"
              size="icon"
              onClick={togglePlayPause}
            >
              {isPlaying ? (
                <Pause className="h-4 w-4" />
              ) : (
                <Play className="h-4 w-4" />
              )}
            </Button>
            
            {/* Skip Forward */}
            <Button
              variant="outline"
              size="icon"
              onClick={skipForward}
            >
              <SkipForward className="h-4 w-4" />
            </Button>
            
            {/* Mute/Unmute */}
            <Button
              variant="outline"
              size="icon"
              onClick={toggleMute}
            >
              {isMuted ? (
                <VolumeX className="h-4 w-4" />
              ) : (
                <Volume2 className="h-4 w-4" />
              )}
            </Button>
            
            {/* Volume Slider */}
            <div className="flex items-center gap-2 flex-1 max-w-[200px]">
              <Slider
                value={[volume]}
                max={1}
                step={0.01}
                onValueChange={handleVolumeChange}
              />
            </div>
          </div>
        </div>
        
        {/* Metadata */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Metadata</h4>
          <div className="grid grid-cols-2 gap-2 text-sm">
            {/* Duration */}
            {audioDuration > 0 && (
              <div className="flex items-center gap-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Duration:</span>
                <Badge variant="secondary">{formatDuration(audioDuration)}</Badge>
              </div>
            )}
            
            {/* File Size */}
            <div className="flex items-center gap-2">
              <HardDrive className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Size:</span>
              <Badge variant="secondary">{formatFileSize(fileSize)}</Badge>
            </div>
            
            {/* Format */}
            <div className="flex items-center gap-2">
              <AudioIcon className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Format:</span>
              <Badge variant="secondary">{format.toUpperCase()}</Badge>
            </div>
            
            {/* Timestamp */}
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Created:</span>
              <Badge variant="secondary">{formatTimestamp(asset.timestamp)}</Badge>
            </div>
          </div>
        </div>
        
        <Separator />
        
        {/* Generation Parameters */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Generation Parameters</h4>
          <div className="grid grid-cols-2 gap-2 text-sm">
            {generationParams.voiceType && (
              <div>
                <span className="text-muted-foreground">Voice Type:</span>{' '}
                <span className="font-medium capitalize">{generationParams.voiceType}</span>
              </div>
            )}
            {generationParams.language && (
              <div>
                <span className="text-muted-foreground">Language:</span>{' '}
                <span className="font-medium">{generationParams.language}</span>
              </div>
            )}
            {generationParams.speed !== undefined && (
              <div>
                <span className="text-muted-foreground">Speed:</span>{' '}
                <span className="font-medium">{generationParams.speed}x</span>
              </div>
            )}
            {generationParams.pitch !== undefined && (
              <div>
                <span className="text-muted-foreground">Pitch:</span>{' '}
                <span className="font-medium">
                  {generationParams.pitch > 0 ? '+' : ''}{generationParams.pitch}
                </span>
              </div>
            )}
            {generationParams.emotion && (
              <div>
                <span className="text-muted-foreground">Emotion:</span>{' '}
                <span className="font-medium capitalize">{generationParams.emotion}</span>
              </div>
            )}
          </div>
          
          {/* Narration Text */}
          {generationParams.text && (
            <div className="mt-2">
              <span className="text-muted-foreground text-sm">Narration Text:</span>
              <p className="text-sm mt-1 p-2 bg-muted rounded-md">
                {generationParams.text}
              </p>
            </div>
          )}
        </div>
      </CardContent>
      
      <CardFooter className="flex flex-wrap gap-2">
        {/* Save Button */}
        {onSave && (
          <Button variant="outline" onClick={handleSave}>
            <Download className="mr-2 h-4 w-4" />
            Save
          </Button>
        )}
        
        {/* Regenerate Button */}
        {onRegenerate && (
          <Button variant="outline" onClick={handleRegenerate}>
            <RefreshCw className="mr-2 h-4 w-4" />
            Regenerate
          </Button>
        )}
        
        {/* Associate Button */}
        {onAssociate && (
          <Button onClick={handleAssociate} className="ml-auto">
            <AudioIcon className="mr-2 h-4 w-4" />
            Associate with Shot
          </Button>
        )}
      </CardFooter>
    </Card>
  );
};

/**
 * Batch Configuration Panel Component
 * 
 * Provides UI for configuring batch generation settings:
 * - Batch mode toggle
 * - Batch size control
 * - Variation parameter controls
 * 
 * Requirements: 11.1, 11.2
 */

import React from 'react';
import { useGenerationStore } from '../../stores/generationStore';
import type { BatchGenerationConfig } from '../../types/generation';

interface BatchConfigPanelProps {
  onClose?: () => void;
}

export const BatchConfigPanel: React.FC<BatchConfigPanelProps> = ({ onClose }) => {
  const { batchConfig, setBatchConfig } = useGenerationStore();

  const handleToggleBatch = () => {
    setBatchConfig({ enabled: !batchConfig.enabled });
  };

  const handleBatchSizeChange = (size: number) => {
    setBatchConfig({ batchSize: Math.max(1, Math.min(20, size)) });
  };

  const handleToggleVarySeeds = () => {
    setBatchConfig({
      variationParams: {
        ...batchConfig.variationParams,
        varySeeds: !batchConfig.variationParams.varySeeds,
      },
    });
  };

  const handleSeedRangeChange = (min: number, max: number) => {
    setBatchConfig({
      variationParams: {
        ...batchConfig.variationParams,
        seedRange: [min, max],
      },
    });
  };

  const handleToggleVaryPrompts = () => {
    setBatchConfig({
      variationParams: {
        ...batchConfig.variationParams,
        varyPrompts: !batchConfig.variationParams.varyPrompts,
      },
    });
  };

  const handleToggleVaryParameters = () => {
    setBatchConfig({
      variationParams: {
        ...batchConfig.variationParams,
        varyParameters: !batchConfig.variationParams.varyParameters,
      },
    });
  };

  return (
    <div className="batch-config-panel bg-gray-800 rounded-lg p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white">Batch Generation Settings</h3>
        {onClose && (
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
            aria-label="Close batch configuration"
          >
            ✕
          </button>
        )}
      </div>

      {/* Batch Mode Toggle */}
      <div className="flex items-center justify-between">
        <label htmlFor="batch-enabled" className="text-sm font-medium text-gray-300">
          Enable Batch Generation
        </label>
        <button
          id="batch-enabled"
          role="switch"
          aria-checked={batchConfig.enabled}
          onClick={handleToggleBatch}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
            batchConfig.enabled ? 'bg-blue-600' : 'bg-gray-600'
          }`}
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
              batchConfig.enabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>

      {batchConfig.enabled && (
        <>
          {/* Batch Size */}
          <div className="space-y-2">
            <label htmlFor="batch-size" className="text-sm font-medium text-gray-300">
              Batch Size: {batchConfig.batchSize}
            </label>
            <input
              id="batch-size"
              type="range"
              min="1"
              max="20"
              value={batchConfig.batchSize}
              onChange={(e) => handleBatchSizeChange(parseInt(e.target.value))}
              className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
            />
            <div className="flex justify-between text-xs text-gray-500">
              <span>1</span>
              <span>20</span>
            </div>
          </div>

          {/* Variation Parameters */}
          <div className="space-y-4 border-t border-gray-700 pt-4">
            <h4 className="text-sm font-medium text-gray-300">Variation Parameters</h4>

            {/* Vary Seeds */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label htmlFor="vary-seeds" className="text-sm text-gray-400">
                  Vary Seeds
                </label>
                <button
                  id="vary-seeds"
                  role="switch"
                  aria-checked={batchConfig.variationParams.varySeeds}
                  onClick={handleToggleVarySeeds}
                  className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
                    batchConfig.variationParams.varySeeds ? 'bg-blue-600' : 'bg-gray-600'
                  }`}
                >
                  <span
                    className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${
                      batchConfig.variationParams.varySeeds ? 'translate-x-5' : 'translate-x-1'
                    }`}
                  />
                </button>
              </div>

              {batchConfig.variationParams.varySeeds && (
                <div className="pl-4 space-y-2">
                  <div className="flex items-center gap-2">
                    <label htmlFor="seed-min" className="text-xs text-gray-500">
                      Min:
                    </label>
                    <input
                      id="seed-min"
                      type="number"
                      value={batchConfig.variationParams.seedRange?.[0] || 0}
                      onChange={(e) =>
                        handleSeedRangeChange(
                          parseInt(e.target.value),
                          batchConfig.variationParams.seedRange?.[1] || 999999
                        )
                      }
                      className="flex-1 bg-gray-700 text-white text-xs rounded px-2 py-1"
                    />
                    <label htmlFor="seed-max" className="text-xs text-gray-500">
                      Max:
                    </label>
                    <input
                      id="seed-max"
                      type="number"
                      value={batchConfig.variationParams.seedRange?.[1] || 999999}
                      onChange={(e) =>
                        handleSeedRangeChange(
                          batchConfig.variationParams.seedRange?.[0] || 0,
                          parseInt(e.target.value)
                        )
                      }
                      className="flex-1 bg-gray-700 text-white text-xs rounded px-2 py-1"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Vary Prompts */}
            <div className="flex items-center justify-between">
              <label htmlFor="vary-prompts" className="text-sm text-gray-400">
                Vary Prompts
              </label>
              <button
                id="vary-prompts"
                role="switch"
                aria-checked={batchConfig.variationParams.varyPrompts}
                onClick={handleToggleVaryPrompts}
                className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
                  batchConfig.variationParams.varyPrompts ? 'bg-blue-600' : 'bg-gray-600'
                }`}
              >
                <span
                  className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${
                    batchConfig.variationParams.varyPrompts ? 'translate-x-5' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>

            {/* Vary Parameters */}
            <div className="flex items-center justify-between">
              <label htmlFor="vary-parameters" className="text-sm text-gray-400">
                Vary Parameters
              </label>
              <button
                id="vary-parameters"
                role="switch"
                aria-checked={batchConfig.variationParams.varyParameters}
                onClick={handleToggleVaryParameters}
                className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
                  batchConfig.variationParams.varyParameters ? 'bg-blue-600' : 'bg-gray-600'
                }`}
              >
                <span
                  className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${
                    batchConfig.variationParams.varyParameters ? 'translate-x-5' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>
          </div>

          {/* Info */}
          <div className="bg-blue-900/20 border border-blue-700/50 rounded p-3">
            <p className="text-xs text-blue-300">
              Batch generation will create {batchConfig.batchSize} variations with the selected
              parameters. Each variation will be queued and processed sequentially.
            </p>
          </div>
        </>
      )}
    </div>
  );
};

