/**
 * Image Generation Dialog
 * 
 * Provides UI for configuring image generation parameters and triggering generation.
 * Integrates with ComfyUIService for z_image_turbo workflow.
 */
export const ImageGenerationDialog: React.FC<ImageGenerationDialogProps> = ({
  isOpen,
  onClose,
  initialPrompt,
}) => {
  const { currentPipeline, completeStage, failStage, updateStageProgress } = useGenerationStore();
  
  // Parameters state
  const [params, setParams] = useState<ImageGenerationParams>(DEFAULT_PARAMS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [categorizedError, setCategorizedError] = useState<CategorizedError | null>(null);
  const [preservedState, setPreservedState] = useState<PreservedState | null>(null);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  
  // Pre-fill prompt from previous step
  useEffect(() => {
    if (isOpen) {
      const promptStage = currentPipeline?.stages.prompt;
      const promptText = initialPrompt || promptStage?.result?.text || '';
      
      setParams((prev) => ({
        ...prev,
        prompt: promptText,
      }));
      setCategorizedError(null);
      setValidationErrors({});
    }
  }, [isOpen, initialPrompt, currentPipeline]);
  
  /**
   * Update parameter value
   */
  const updateParam = <K extends keyof ImageGenerationParams>(
    key: K,
    value: ImageGenerationParams[K]
  ) => {
    setParams((prev) => ({
      ...prev,
      [key]: value,
    }));
    
    // Clear validation error for this field
    if (validationErrors[key]) {
      setValidationErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[key];
        return newErrors;
      });
    }
  };
  
  /**
   * Apply preset dimensions
   */
  const applyDimensions = (width: number, height: number) => {
    setParams((prev) => ({
      ...prev,
      width,
      height,
    }));
  };
  
  /**
   * Load preset parameters
   */
  const handleLoadPreset = (preset: ImagePreset) => {
    setParams((prev) => ({
      ...prev,
      ...preset.params,
    }));
  };
  
  /**
   * Validate parameters
   */
  const validateParams = (): boolean => {
    const errors: Record<string, string> = {};
    
    if (!params.prompt.trim()) {
      errors.prompt = 'Prompt is required';
    }
    
    if (params.width < 256 || params.width > 2048) {
      errors.width = 'Width must be between 256 and 2048';
    }
    
    if (params.height < 256 || params.height > 2048) {
      errors.height = 'Height must be between 256 and 2048';
    }
    
    if (params.width % 8 !== 0) {
      errors.width = 'Width must be divisible by 8';
    }
    
    if (params.height % 8 !== 0) {
      errors.height = 'Height must be divisible by 8';
    }
    
    if (params.steps < 1 || params.steps > 150) {
      errors.steps = 'Steps must be between 1 and 150';
    }
    
    if (params.cfgScale < 1 || params.cfgScale > 30) {
      errors.cfgScale = 'CFG Scale must be between 1 and 30';
    }
    
    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };
  
  /**
   * Generate image
   */
  const handleGenerate = async () => {
    // Validate parameters
    if (!validateParams()) {
      const error = new Error('Please fix the validation errors before generating');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      return;
    }
    
    setIsGenerating(true);
    setCategorizedError(null);
    
    try {
      const result = await generationOrchestrator.generateImage(
        params,
        (progress) => {
          updateStageProgress('image', progress);
        },
        (error) => {
          const categorized = categorizeError(error);
          setCategorizedError(categorized);
          failStage('image', error.message);
          
          // Preserve state on error
          const preserved = preserveStateOnError(
            categorized,
            { params },
            [],
            null
          );
          setPreservedState(preserved);
        }
      );
      
      // Complete the image stage
      completeStage('image', result);
      
      // Close dialog
      onClose();
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to generate image');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      
      // Preserve state on error
      const preserved = preserveStateOnError(
        categorized,
        { params },
        [],
        null
      );
      setPreservedState(preserved);
    } finally {
      setIsGenerating(false);
    }
  };
  
  /**
   * Handle dialog close
   */
  const handleClose = () => {
    if (!isGenerating) {
      onClose();
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ImageIcon className="h-5 w-5" />
            Generate Image
          </DialogTitle>
          <DialogDescription>
            Configure parameters for image generation using Flux Turbo.
          </DialogDescription>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          {/* Preset Manager */}
          <PresetManager
            type="image"
            currentParams={params}
            onLoadPreset={(preset) => handleLoadPreset(preset as ImagePreset)}
          />
          
          {/* Prompt */}
          <div className="space-y-2">
            <Label htmlFor="prompt">
              Prompt <span className="text-destructive">*</span>
            </Label>
            <Textarea
              id="prompt"
              value={params.prompt}
              onChange={(e) => updateParam('prompt', e.target.value)}
              placeholder="Describe the image you want to generate..."
              className="min-h-[100px]"
              disabled={isGenerating}
            />
            {validationErrors.prompt && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.prompt}
              </p>
            )}
          </div>
          
          {/* Negative Prompt */}
          <div className="space-y-2">
            <Label htmlFor="negativePrompt">Negative Prompt</Label>
            <Textarea
              id="negativePrompt"
              value={params.negativePrompt}
              onChange={(e) => updateParam('negativePrompt', e.target.value)}
              placeholder="What to avoid in the image..."
              className="min-h-[60px]"
              disabled={isGenerating}
            />
          </div>
          
          {/* Dimensions */}
          <div className="space-y-2">
            <Label>Dimensions</Label>
            <div className="grid grid-cols-2 gap-2 mb-2">
              {COMMON_DIMENSIONS.map((preset) => (
                <Button
                  key={preset.label}
                  variant="outline"
                  size="sm"
                  onClick={() => applyDimensions(preset.width, preset.height)}
                  disabled={isGenerating}
                  className={
                    params.width === preset.width && params.height === preset.height
                      ? 'border-primary'
                      : ''
                  }
                >
                  {preset.label}
                </Button>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="width">Width</Label>
                <Input
                  id="width"
                  type="number"
                  value={params.width}
                  onChange={(e) => updateParam('width', parseInt(e.target.value) || 1024)}
                  min={256}
                  max={2048}
                  step={8}
                  disabled={isGenerating}
                />
                {validationErrors.width && (
                  <p className="text-sm text-destructive flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" />
                    {validationErrors.width}
                  </p>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="height">Height</Label>
                <Input
                  id="height"
                  type="number"
                  value={params.height}
                  onChange={(e) => updateParam('height', parseInt(e.target.value) || 1024)}
                  min={256}
                  max={2048}
                  step={8}
                  disabled={isGenerating}
                />
                {validationErrors.height && (
                  <p className="text-sm text-destructive flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" />
                    {validationErrors.height}
                  </p>
                )}
              </div>
            </div>
          </div>
          
          {/* Steps */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="steps">Steps</Label>
              <span className="text-sm text-muted-foreground">{params.steps}</span>
            </div>
            <Slider
              id="steps"
              value={[params.steps]}
              onValueChange={([value]) => updateParam('steps', value)}
              min={1}
              max={150}
              step={1}
              disabled={isGenerating}
            />
            {validationErrors.steps && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.steps}
              </p>
            )}
          </div>
          
          {/* CFG Scale */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="cfgScale">CFG Scale</Label>
              <span className="text-sm text-muted-foreground">{params.cfgScale.toFixed(1)}</span>
            </div>
            <Slider
              id="cfgScale"
              value={[params.cfgScale]}
              onValueChange={([value]) => updateParam('cfgScale', value)}
              min={1}
              max={30}
              step={0.5}
              disabled={isGenerating}
            />
            {validationErrors.cfgScale && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.cfgScale}
              </p>
            )}
          </div>
          
          {/* Seed */}
          <div className="space-y-2">
            <Label htmlFor="seed">Seed (-1 for random)</Label>
            <Input
              id="seed"
              type="number"
              value={params.seed}
              onChange={(e) => updateParam('seed', parseInt(e.target.value) || -1)}
              disabled={isGenerating}
            />
          </div>
          
          {/* Sampler and Scheduler */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="sampler">Sampler</Label>
              <Select
                value={params.sampler}
                onValueChange={(value) => updateParam('sampler', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="sampler">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {SAMPLERS.map((sampler) => (
                    <SelectItem key={sampler} value={sampler}>
                      {sampler}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="scheduler">Scheduler</Label>
              <Select
                value={params.scheduler}
                onValueChange={(value) => updateParam('scheduler', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="scheduler">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {SCHEDULERS.map((scheduler) => (
                    <SelectItem key={scheduler} value={scheduler}>
                      {scheduler}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          
          {/* Error Display */}
          {categorizedError && (
            <ErrorDisplay
              error={categorizedError}
              onRetry={categorizedError.canRetry ? handleGenerate : undefined}
              onAdjustParameters={() => {
                // Suggest parameter adjustments
                const suggestions = suggestParameterAdjustments(categorizedError, params);
                if (suggestions) {
                  setParams((prev) => ({ ...prev, ...suggestions }));
                }
                setCategorizedError(null);
              }}
              onDismiss={() => setCategorizedError(null)}
              className="mt-4"
            />
          )}
        </div>
        
        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isGenerating}
          >
            Cancel
          </Button>
          
          <Button
            onClick={handleGenerate}
            disabled={isGenerating || !params.prompt.trim()}
          >
            {isGenerating ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Check className="mr-2 h-4 w-4" />
                Generate Image
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Pipeline Completion View Component
 * 
 * Displays all generated assets together when pipeline is complete,
 * with export options and asset relationship visualization.
 * 
 * Requirements: 6.5, 9.4
 */

import React, { useState } from 'react';
import { useGenerationStore } from '../../stores/generationStore';
import { PipelineStateMachine } from '../../services/PipelineStateMachine';
import type { GeneratedAsset, GeneratedPrompt } from '../../types/generation';

export interface PipelineCompletionViewProps {
  pipelineId: string;
  onClose?: () => void;
  onExport?: (assets: GeneratedAsset[], format: ExportFormat) => void;
  onRestart?: () => void;
}

export type ExportFormat = 'individual' | 'batch' | 'zip' | 'mp4' | 'webm';

interface ExportOptions {
  format: ExportFormat;
  includeMetadata: boolean;
  includePrompt: boolean;
  quality: 'low' | 'medium' | 'high';
}

/**
 * Pipeline Completion View Component
 */
export const PipelineCompletionView: React.FC<PipelineCompletionViewProps> = ({
  pipelineId,
  onClose,
  onExport,
  onRestart,
}) => {
  const currentPipeline = useGenerationStore(state => state.currentPipeline);
  const getRelatedAssets = useGenerationStore(state => state.getRelatedAssets);
  const getAllPipelineAssets = useGenerationStore(state => state.getAllPipelineAssets);

  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: 'individual',
    includeMetadata: true,
    includePrompt: true,
    quality: 'high',
  });

  const [selectedAssets, setSelectedAssets] = useState<Set<string>>(new Set());

  if (!currentPipeline || currentPipeline.id !== pipelineId) {
    return (
      <div className="pipeline-completion-view">
        <div className="error-message">
          Pipeline not found
        </div>
      </div>
    );
  }

  if (!PipelineStateMachine.isPipelineComplete(currentPipeline)) {
    return (
      <div className="pipeline-completion-view">
        <div className="info-message">
          Pipeline is not yet complete
        </div>
      </div>
    );
  }

  const assets = getAllPipelineAssets();
  const completedStages = PipelineStateMachine.getCompletedStages(currentPipeline);
  const allAssets: GeneratedAsset[] = [
    assets.image,
    assets.video,
    assets.audio,
  ].filter((asset): asset is GeneratedAsset => asset !== undefined);

  const handleAssetSelect = (assetId: string) => {
    const newSelected = new Set(selectedAssets);
    if (newSelected.has(assetId)) {
      newSelected.delete(assetId);
    } else {
      newSelected.add(assetId);
    }
    setSelectedAssets(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedAssets.size === allAssets.length) {
      setSelectedAssets(new Set());
    } else {
      setSelectedAssets(new Set(allAssets.map(a => a.id)));
    }
  };

  const handleExport = () => {
    const assetsToExport = allAssets.filter(a => selectedAssets.has(a.id));
    if (assetsToExport.length === 0) {
      alert('Please select at least one asset to export');
      return;
    }

    onExport?.(assetsToExport, exportOptions.format);
  };

  const getAssetRelationships = (assetId: string): GeneratedAsset[] => {
    return getRelatedAssets(assetId);
  };

  return (
    <div className="pipeline-completion-view">
      {/* Header */}
      <div className="completion-header">
        <h2>Pipeline Complete</h2>
        <p className="completion-subtitle">
          All stages completed successfully. Review and export your generated assets.
        </p>
        {onClose && (
          <button
            className="close-button"
            onClick={onClose}
            aria-label="Close completion view"
          >
            ×
          </button>
        )}
      </div>

      {/* Pipeline Summary */}
      <div className="pipeline-summary">
        <div className="summary-card">
          <h3>Pipeline Summary</h3>
          <div className="summary-stats">
            <div className="stat">
              <span className="stat-label">Completed Stages</span>
              <span className="stat-value">{completedStages.length}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Generated Assets</span>
              <span className="stat-value">{allAssets.length}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Duration</span>
              <span className="stat-value">
                {Math.round((currentPipeline.updatedAt - currentPipeline.createdAt) / 1000)}s
              </span>
            </div>
          </div>
        </div>

        {/* Prompt Display */}
        {assets.prompt && (
          <div className="prompt-card">
            <h4>Generated Prompt</h4>
            <p className="prompt-text">{assets.prompt.text}</p>
          </div>
        )}
      </div>

      {/* Assets Grid */}
      <div className="assets-section">
        <div className="assets-header">
          <h3>Generated Assets</h3>
          <button
            className="select-all-button"
            onClick={handleSelectAll}
          >
            {selectedAssets.size === allAssets.length ? 'Deselect All' : 'Select All'}
          </button>
        </div>

        <div className="assets-grid">
          {allAssets.map(asset => {
            const isSelected = selectedAssets.has(asset.id);
            const relatedAssets = getAssetRelationships(asset.id);

            return (
              <div
                key={asset.id}
                className={`asset-card ${isSelected ? 'selected' : ''}`}
                onClick={() => handleAssetSelect(asset.id)}
              >
                <div className="asset-checkbox">
                  <input
                    type="checkbox"
                    checked={isSelected}
                    onChange={() => handleAssetSelect(asset.id)}
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>

                <div className="asset-preview">
                  {asset.type === 'image' && (
                    <img src={asset.url} alt="Generated image" />
                  )}
                  {asset.type === 'video' && (
                    <video src={asset.url} controls />
                  )}
                  {asset.type === 'audio' && (
                    <audio src={asset.url} controls />
                  )}
                </div>

                <div className="asset-info">
                  <div className="asset-type-badge">{asset.type}</div>
                  <div className="asset-metadata">
                    <span className="metadata-item">
                      {(asset.metadata.fileSize / 1024).toFixed(2)} KB
                    </span>
                    {asset.metadata.dimensions && (
                      <span className="metadata-item">
                        {asset.metadata.dimensions.width}×{asset.metadata.dimensions.height}
                      </span>
                    )}
                    {asset.metadata.duration && (
                      <span className="metadata-item">
                        {asset.metadata.duration.toFixed(1)}s
                      </span>
                    )}
                  </div>

                  {relatedAssets.length > 0 && (
                    <div className="asset-relationships">
                      <span className="relationships-label">Related:</span>
                      <span className="relationships-count">{relatedAssets.length} asset(s)</span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Export Options */}
      <div className="export-section">
        <h3>Export Options</h3>
        
        <div className="export-options-grid">
          <div className="option-group">
            <label htmlFor="export-format">Format</label>
            <select
              id="export-format"
              value={exportOptions.format}
              onChange={(e) => setExportOptions({
                ...exportOptions,
                format: e.target.value as ExportFormat,
              })}
            >
              <option value="individual">Individual Files</option>
              <option value="batch">Batch Export</option>
              <option value="zip">ZIP Archive</option>
              <option value="mp4">MP4 Video</option>
              <option value="webm">WebM Video</option>
            </select>
          </div>

          <div className="option-group">
            <label htmlFor="export-quality">Quality</label>
            <select
              id="export-quality"
              value={exportOptions.quality}
              onChange={(e) => setExportOptions({
                ...exportOptions,
                quality: e.target.value as 'low' | 'medium' | 'high',
              })}
            >
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
          </div>

          <div className="option-group checkbox-group">
            <label>
              <input
                type="checkbox"
                checked={exportOptions.includeMetadata}
                onChange={(e) => setExportOptions({
                  ...exportOptions,
                  includeMetadata: e.target.checked,
                })}
              />
              Include Metadata
            </label>
          </div>

          <div className="option-group checkbox-group">
            <label>
              <input
                type="checkbox"
                checked={exportOptions.includePrompt}
                onChange={(e) => setExportOptions({
                  ...exportOptions,
                  includePrompt: e.target.checked,
                })}
              />
              Include Prompt
            </label>
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="completion-actions">
        <button
          className="export-button primary"
          onClick={handleExport}
          disabled={selectedAssets.size === 0}
        >
          Export Selected ({selectedAssets.size})
        </button>

        {onRestart && (
          <button
            className="restart-button secondary"
            onClick={onRestart}
          >
            Start New Pipeline
          </button>
        )}

        {onClose && (
          <button
            className="close-button-footer secondary"
            onClick={onClose}
          >
            Close
          </button>
        )}
      </div>

      {/* Asset Relationships Visualization */}
      {allAssets.length > 1 && (
        <div className="relationships-section">
          <h3>Asset Relationships</h3>
          <div className="relationships-diagram">
            <div className="pipeline-flow">
              {assets.prompt && (
                <div className="flow-node prompt-node">
                  <span className="node-label">Prompt</span>
                </div>
              )}
              {assets.image && (
                <>
                  <div className="flow-arrow">→</div>
                  <div className="flow-node image-node">
                    <span className="node-label">Image</span>
                  </div>
                </>
              )}
              {assets.video && (
                <>
                  <div className="flow-arrow">→</div>
                  <div className="flow-node video-node">
                    <span className="node-label">Video</span>
                  </div>
                </>
              )}
              {assets.audio && (
                <>
                  <div className="flow-arrow">→</div>
                  <div className="flow-node audio-node">
                    <span className="node-label">Audio</span>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PipelineCompletionView;

/**
 * Preset Manager Component
 * 
 * UI for managing generation parameter presets.
 * Provides list, save, load, delete, and rename functionality.
 * 
 * Requirements: 10.5
 */

import React, { useState, useEffect } from 'react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '../ui/dropdown-menu';
import {
  Save,
  FolderOpen,
  Trash2,
  Edit2,
  Check,
  X,
  MoreVertical,
  Download,
  Upload,
} from 'lucide-react';
import {
  PresetManagementService,
  type Preset,
  type PresetType,
} from '../../services/PresetManagementService';

export interface PresetManagerProps {
  /**
   * Type of presets to manage
   */
  type: PresetType;
  
  /**
   * Current parameters to save as preset
   */
  currentParams: unknown;
  
  /**
   * Callback when preset is loaded
   */
  onLoadPreset: (preset: Preset) => void;
  
  /**
   * Optional className
   */
  className?: string;
}

/**
 * Preset Manager Component
 * 
 * Provides UI for saving, loading, and managing presets.
 */
export const PresetManager: React.FC<PresetManagerProps> = ({
  type,
  currentParams,
  onLoadPreset,
  className,
}) => {
  const [presets, setPresets] = useState<Preset[]>([]);
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [showLoadDialog, setShowLoadDialog] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');
  const [editingPresetId, setEditingPresetId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');
  
  // Load presets on mount and when type changes
  useEffect(() => {
    loadPresets();
  }, [type]);
  
  /**
   * Load presets from storage
   */
  const loadPresets = () => {
    const loaded = PresetManagementService.getPresets(type);
    setPresets(loaded);
  };
  
  /**
   * Save current parameters as preset
   */
  const handleSavePreset = () => {
    if (!newPresetName.trim()) {
      return;
    }
    
    try {
      const preset = PresetManagementService.savePreset({
        name: newPresetName.trim(),
        type,
        ...(type === 'prompt' ? { categories: currentParams } : { params: currentParams }),
      } as any);
      
      loadPresets();
      setShowSaveDialog(false);
      setNewPresetName('');
    } catch (error) {
      console.error('Failed to save preset:', error);
    }
  };
  
  /**
   * Load a preset
   */
  const handleLoadPreset = (preset: Preset) => {
    onLoadPreset(preset);
    setShowLoadDialog(false);
  };
  
  /**
   * Delete a preset
   */
  const handleDeletePreset = (id: string) => {
    if (confirm('Are you sure you want to delete this preset?')) {
      PresetManagementService.deletePreset(id);
      loadPresets();
    }
  };
  
  /**
   * Start editing preset name
   */
  const startEditingPreset = (preset: Preset) => {
    setEditingPresetId(preset.id);
    setEditingName(preset.name);
  };
  
  /**
   * Save edited preset name
   */
  const saveEditedPresetName = () => {
    if (editingPresetId && editingName.trim()) {
      PresetManagementService.renamePreset(editingPresetId, editingName.trim());
      loadPresets();
      setEditingPresetId(null);
      setEditingName('');
    }
  };
  
  /**
   * Cancel editing
   */
  const cancelEditing = () => {
    setEditingPresetId(null);
    setEditingName('');
  };
  
  /**
   * Export presets
   */
  const handleExportPresets = () => {
    const json = PresetManagementService.exportPresets(type);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${type}-presets.json`;
    a.click();
    URL.revokeObjectURL(url);
  };
  
  /**
   * Import presets
   */
  const handleImportPresets = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        try {
          const text = await file.text();
          const result = PresetManagementService.importPresets(text);
          alert(`Imported ${result.success} presets. ${result.failed} failed.`);
          loadPresets();
        } catch (error) {
          alert('Failed to import presets. Please check the file format.');
        }
      }
    };
    input.click();
  };
  
  return (
    <div className={className}>
      <div className="flex gap-2">
        {/* Save Preset Button */}
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowSaveDialog(true)}
          className="flex-1"
        >
          <Save className="mr-2 h-4 w-4" />
          Save Preset
        </Button>
        
        {/* Load Preset Button */}
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowLoadDialog(true)}
          className="flex-1"
          disabled={presets.length === 0}
        >
          <FolderOpen className="mr-2 h-4 w-4" />
          Load Preset
        </Button>
        
        {/* More Options */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm">
              <MoreVertical className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={handleExportPresets} disabled={presets.length === 0}>
              <Download className="mr-2 h-4 w-4" />
              Export Presets
            </DropdownMenuItem>
            <DropdownMenuItem onClick={handleImportPresets}>
              <Upload className="mr-2 h-4 w-4" />
              Import Presets
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      
      {/* Save Preset Dialog */}
      <Dialog open={showSaveDialog} onOpenChange={setShowSaveDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Save Preset</DialogTitle>
            <DialogDescription>
              Give your preset a name to save the current parameters.
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="presetName">Preset Name</Label>
              <Input
                id="presetName"
                value={newPresetName}
                onChange={(e) => setNewPresetName(e.target.value)}
                placeholder="Enter preset name..."
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleSavePreset();
                  }
                }}
              />
            </div>
          </div>
          
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowSaveDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleSavePreset} disabled={!newPresetName.trim()}>
              <Save className="mr-2 h-4 w-4" />
              Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      
      {/* Load Preset Dialog */}
      <Dialog open={showLoadDialog} onOpenChange={setShowLoadDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Load Preset</DialogTitle>
            <DialogDescription>
              Select a preset to load its parameters.
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-2 py-4 max-h-[400px] overflow-y-auto">
            {presets.length === 0 ? (
              <div className="text-center text-muted-foreground py-8">
                No presets saved yet.
              </div>
            ) : (
              presets.map((preset) => (
                <div
                  key={preset.id}
                  className="flex items-center gap-2 p-2 rounded-md border hover:bg-accent"
                >
                  {editingPresetId === preset.id ? (
                    <>
                      <Input
                        value={editingName}
                        onChange={(e) => setEditingName(e.target.value)}
                        className="flex-1"
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            saveEditedPresetName();
                          } else if (e.key === 'Escape') {
                            cancelEditing();
                          }
                        }}
                        autoFocus
                      />
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={saveEditedPresetName}
                      >
                        <Check className="h-4 w-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={cancelEditing}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </>
                  ) : (
                    <>
                      <Button
                        variant="ghost"
                        className="flex-1 justify-start"
                        onClick={() => handleLoadPreset(preset)}
                      >
                        <FolderOpen className="mr-2 h-4 w-4" />
                        {preset.name}
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => startEditingPreset(preset)}
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleDeletePreset(preset.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </>
                  )}
                </div>
              ))
            )}
          </div>
          
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowLoadDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

/**
 * Prompt Generation Button Component
 * 
 * Button that triggers prompt generation dialog.
 * Supports enabled/disabled states, tooltips, and keyboard shortcuts.
 * 
 * Requirements: 1.1, 5.3, 5.4, 5.5, 13.1
 */

import React, { useEffect } from 'react';
import { Button } from '../ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';
import { FileText } from 'lucide-react';
import { useGenerationStore } from '../../stores/generationStore';
import {
  useKeyboardShortcut,
  useButtonStateAnnouncer,
  getButtonAriaDescription,
} from '../../hooks/useAccessibility';

export interface PromptGenerationButtonProps {
  /**
   * Whether the button is disabled
   */
  disabled?: boolean;
  
  /**
   * Reason for disabled state (shown in tooltip)
   */
  disabledReason?: string;
  
  /**
   * Callback when button is clicked
   */
  onClick: () => void;
  
  /**
   * Whether generation is in progress
   */
  isGenerating?: boolean;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Prompt Generation Button
 * 
 * Displays a button that opens the prompt generation dialog.
 * Shows appropriate state (enabled, disabled, generating) with visual indicators.
 * Supports keyboard shortcut (Ctrl+Shift+P).
 */
export const PromptGenerationButton: React.FC<PromptGenerationButtonProps> = ({
  disabled = false,
  disabledReason,
  onClick,
  isGenerating = false,
  className = '',
}) => {
  const { currentPipeline } = useGenerationStore();
  
  // Determine button state based on pipeline
  const promptStage = currentPipeline?.stages.prompt;
  const isCompleted = promptStage?.status === 'completed';
  const isFailed = promptStage?.status === 'failed';
  const isInProgress = promptStage?.status === 'in_progress' || isGenerating;
  
  const isButtonDisabled = disabled || isInProgress;
  
  // Register keyboard shortcut with accessibility
  const shortcutString = useKeyboardShortcut(
    'P',
    onClick,
    {
      ctrl: true,
      shift: true,
      enabled: !isButtonDisabled,
    }
  );
  
  // Announce button state changes
  useButtonStateAnnouncer(
    'Prompt generation button',
    isButtonDisabled,
    disabledReason
  );
  
  // Determine tooltip content
  const getTooltipContent = (): string => {
    if (disabledReason) {
      return disabledReason;
    }
    
    if (isInProgress) {
      return 'Generating prompt...';
    }
    
    if (isCompleted) {
      return `Prompt generated. Click to regenerate. (${shortcutString})`;
    }
    
    if (isFailed) {
      return `Prompt generation failed. Click to retry. (${shortcutString})`;
    }
    
    return `Generate AI prompt from categories (${shortcutString})`;
  };
  
  // Get ARIA description
  const ariaDescription = getButtonAriaDescription(
    'prompt',
    isButtonDisabled,
    isInProgress,
    isCompleted,
    isFailed,
    disabledReason
  );
  
  // Determine button variant
  const getButtonVariant = (): 'default' | 'outline' | 'secondary' | 'ghost' | 'destructive' => {
    if (isFailed) {
      return 'destructive';
    }
    
    if (isCompleted) {
      return 'secondary';
    }
    
    return 'default';
  };
  
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            onClick={onClick}
            disabled={isButtonDisabled}
            variant={getButtonVariant()}
            className={`gap-2 ${className}`}
            aria-label="Generate prompt"
            aria-description={ariaDescription}
            aria-busy={isInProgress}
            aria-disabled={isButtonDisabled}
            aria-keyshortcuts={shortcutString}
          >
            <FileText className="h-4 w-4" aria-hidden="true" />
            {isInProgress ? 'Generating...' : isCompleted ? 'Regenerate Prompt' : 'Generate Prompt'}
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          <p>{getTooltipContent()}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

/**
 * Prompt Generation Dialog Component
 * 
 * Dialog for generating AI prompts with category selection.
 * Allows users to select genre, shot type, lighting, and other categories,
 * then generates and displays an editable prompt.
 * 
 * Requirements: 1.2, 1.3, 1.4, 1.5
 */

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { Loader2, Sparkles, Check } from 'lucide-react';
import { generationOrchestrator } from '../../services/GenerationOrchestrator';
import { useGenerationStore } from '../../stores/generationStore';
import type { PromptCategories, GeneratedPrompt } from '../../types/generation';
import { ErrorDisplay } from './ErrorDisplay';
import { PresetManager } from './PresetManager';
import type { PromptPreset } from '../../services/PresetManagementService';
import {
  categorizeError,
  preserveStateOnError,
  restorePreservedState,
  type CategorizedError,
  type PreservedState,
} from '../../utils/errorHandling';

export interface PromptGenerationDialogProps {
  /**
   * Whether the dialog is open
   */
  isOpen: boolean;
  
  /**
   * Callback when dialog is closed
   */
  onClose: () => void;
  
  /**
   * Callback when prompt is generated and approved
   */
  onGenerate: (prompt: GeneratedPrompt) => void;
  
  /**
   * Initial categories (optional)
   */
  initialCategories?: PromptCategories;
}

/**
 * Prompt Generation Dialog
 * 
 * Provides UI for selecting prompt categories and generating AI prompts.
 * Users can edit the generated prompt before using it.
 */
export const PromptGenerationDialog: React.FC<PromptGenerationDialogProps> = ({
  isOpen,
  onClose,
  onGenerate,
  initialCategories,
}) => {
  const { completeStage, failStage, updateStageProgress } = useGenerationStore();
  
  // Category state
  const [categories, setCategories] = useState<PromptCategories>(
    initialCategories || {
      genre: 'cinematic',
      shotType: 'medium-shot',
      lighting: 'natural',
      sceneElements: [],
      mood: 'neutral',
    }
  );
  
  // Generated prompt state
  const [generatedPrompt, setGeneratedPrompt] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [categorizedError, setCategorizedError] = useState<CategorizedError | null>(null);
  const [preservedState, setPreservedState] = useState<PreservedState | null>(null);
  const [hasGenerated, setHasGenerated] = useState(false);
  
  // Reset state when dialog opens
  useEffect(() => {
    if (isOpen) {
      // Restore preserved state if available
      if (preservedState) {
        const restored = restorePreservedState(preservedState);
        setCategories(restored.userInputs.categories || categories);
        setGeneratedPrompt(restored.userInputs.generatedPrompt || '');
        setHasGenerated(!!restored.userInputs.generatedPrompt);
        setPreservedState(null);
      } else {
        setGeneratedPrompt('');
        setHasGenerated(false);
        if (initialCategories) {
          setCategories(initialCategories);
        }
      }
      setCategorizedError(null);
    }
  }, [isOpen, initialCategories, preservedState]);
  
  /**
   * Handle category change
   */
  const handleCategoryChange = (key: keyof PromptCategories, value: string) => {
    setCategories((prev) => ({
      ...prev,
      [key]: value,
    }));
  };
  
  /**
   * Load preset categories
   */
  const handleLoadPreset = (preset: PromptPreset) => {
    setCategories(preset.categories);
  };
  
  /**
   * Generate prompt from categories
   */
  const handleGenerate = async () => {
    setIsGenerating(true);
    setCategorizedError(null);
    
    try {
      const prompt = await generationOrchestrator.generatePrompt(
        categories,
        (progress) => {
          updateStageProgress('prompt', progress);
        },
        (error) => {
          const categorized = categorizeError(error);
          setCategorizedError(categorized);
          failStage('prompt', error.message);
          
          // Preserve state on error
          const preserved = preserveStateOnError(
            categorized,
            { categories, generatedPrompt },
            [],
            null
          );
          setPreservedState(preserved);
        }
      );
      
      setGeneratedPrompt(prompt.text);
      setHasGenerated(true);
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to generate prompt');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      
      // Preserve state on error
      const preserved = preserveStateOnError(
        categorized,
        { categories, generatedPrompt },
        [],
        null
      );
      setPreservedState(preserved);
    } finally {
      setIsGenerating(false);
    }
  };
  
  /**
   * Handle prompt text edit
   */
  const handlePromptEdit = (value: string) => {
    setGeneratedPrompt(value);
  };
  
  /**
   * Use the generated/edited prompt
   */
  const handleUsePrompt = () => {
    if (!generatedPrompt.trim()) {
      const error = new Error('Prompt cannot be empty');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      return;
    }
    
    const prompt: GeneratedPrompt = {
      text: generatedPrompt,
      categories,
      timestamp: Date.now(),
      editable: true,
    };
    
    // Complete the prompt stage
    completeStage('prompt', prompt);
    
    // Call the callback
    onGenerate(prompt);
    
    // Close dialog
    onClose();
  };
  
  /**
   * Handle dialog close
   */
  const handleClose = () => {
    if (!isGenerating) {
      onClose();
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5" />
            Generate AI Prompt
          </DialogTitle>
          <DialogDescription>
            Select categories to generate an optimized prompt for image generation.
            You can edit the generated prompt before using it.
          </DialogDescription>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          {/* Preset Manager */}
          <PresetManager
            type="prompt"
            currentParams={categories}
            onLoadPreset={(preset) => handleLoadPreset(preset as PromptPreset)}
          />
          
          {/* Category Selectors */}
          <div className="grid grid-cols-2 gap-4">
            {/* Genre */}
            <div className="space-y-2">
              <Label htmlFor="genre">Genre</Label>
              <Select
                value={categories.genre}
                onValueChange={(value) => handleCategoryChange('genre', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="genre">
                  <SelectValue placeholder="Select genre" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="cinematic">Cinematic</SelectItem>
                  <SelectItem value="sci-fi">Sci-Fi</SelectItem>
                  <SelectItem value="fantasy">Fantasy</SelectItem>
                  <SelectItem value="horror">Horror</SelectItem>
                  <SelectItem value="documentary">Documentary</SelectItem>
                  <SelectItem value="anime">Anime</SelectItem>
                  <SelectItem value="noir">Noir</SelectItem>
                </SelectContent>
              </Select>
            </div>
            
            {/* Shot Type */}
            <div className="space-y-2">
              <Label htmlFor="shotType">Shot Type</Label>
              <Select
                value={categories.shotType}
                onValueChange={(value) => handleCategoryChange('shotType', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="shotType">
                  <SelectValue placeholder="Select shot type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="extreme-close-up">Extreme Close-Up</SelectItem>
                  <SelectItem value="close-up">Close-Up</SelectItem>
                  <SelectItem value="medium-shot">Medium Shot</SelectItem>
                  <SelectItem value="full-shot">Full Shot</SelectItem>
                  <SelectItem value="wide-shot">Wide Shot</SelectItem>
                  <SelectItem value="extreme-wide-shot">Extreme Wide Shot</SelectItem>
                  <SelectItem value="over-shoulder">Over-the-Shoulder</SelectItem>
                </SelectContent>
              </Select>
            </div>
            
            {/* Lighting */}
            <div className="space-y-2">
              <Label htmlFor="lighting">Lighting</Label>
              <Select
                value={categories.lighting}
                onValueChange={(value) => handleCategoryChange('lighting', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="lighting">
                  <SelectValue placeholder="Select lighting" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="natural">Natural</SelectItem>
                  <SelectItem value="golden-hour">Golden Hour</SelectItem>
                  <SelectItem value="blue-hour">Blue Hour</SelectItem>
                  <SelectItem value="dramatic">Dramatic</SelectItem>
                  <SelectItem value="soft">Soft</SelectItem>
                  <SelectItem value="hard">Hard</SelectItem>
                  <SelectItem value="neon">Neon</SelectItem>
                  <SelectItem value="candlelight">Candlelight</SelectItem>
                </SelectContent>
              </Select>
            </div>
            
            {/* Mood */}
            <div className="space-y-2">
              <Label htmlFor="mood">Mood</Label>
              <Select
                value={categories.mood}
                onValueChange={(value) => handleCategoryChange('mood', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="mood">
                  <SelectValue placeholder="Select mood" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="neutral">Neutral</SelectItem>
                  <SelectItem value="tense">Tense</SelectItem>
                  <SelectItem value="peaceful">Peaceful</SelectItem>
                  <SelectItem value="mysterious">Mysterious</SelectItem>
                  <SelectItem value="energetic">Energetic</SelectItem>
                  <SelectItem value="melancholic">Melancholic</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          
          {/* Generate Button */}
          {!hasGenerated && (
            <Button
              onClick={handleGenerate}
              disabled={isGenerating}
              className="w-full"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Generating Prompt...
                </>
              ) : (
                <>
                  <Sparkles className="mr-2 h-4 w-4" />
                  Generate Prompt
                </>
              )}
            </Button>
          )}
          
          {/* Generated Prompt Display */}
          {hasGenerated && (
            <div className="space-y-2">
              <Label htmlFor="prompt">Generated Prompt (Editable)</Label>
              <Textarea
                id="prompt"
                value={generatedPrompt}
                onChange={(e) => handlePromptEdit(e.target.value)}
                placeholder="Generated prompt will appear here..."
                className="min-h-[150px] font-mono text-sm"
                disabled={isGenerating}
              />
              <p className="text-sm text-muted-foreground">
                You can edit the prompt above before using it for image generation.
              </p>
            </div>
          )}
          
          {/* Error Display */}
          {categorizedError && (
            <ErrorDisplay
              error={categorizedError}
              onRetry={categorizedError.canRetry ? handleGenerate : undefined}
              onDismiss={() => setCategorizedError(null)}
              className="mt-4"
            />
          )}
        </div>
        
        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isGenerating}
          >
            Cancel
          </Button>
          
          {hasGenerated && (
            <>
              <Button
                variant="secondary"
                onClick={handleGenerate}
                disabled={isGenerating}
              >
                <Sparkles className="mr-2 h-4 w-4" />
                Regenerate
              </Button>
              
              <Button
                onClick={handleUsePrompt}
                disabled={isGenerating || !generatedPrompt.trim()}
              >
                <Check className="mr-2 h-4 w-4" />
                Use Prompt
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Re-generation Buttons Component
 *
 * Provides contextual re-generation buttons for shots and assets.
 * Displayed inline on shot cards and in the editor preview.
 *
 * Features:
 * - Portrait re-generation (character images)
 * - Text/prompt re-generation
 * - Audio re-generation (voice, SFX)
 * - Batch re-generation (all selected)
 */

import React, { useState, useCallback } from 'react';
import {
    RefreshCw,
    Image,
    Type,
    Volume2,
    Layers,
    Sparkles,
    Loader2,
    RotateCcw,
} from 'lucide-react';
import { useGenerationStore } from '../../stores/generationStore';
import type { GeneratedAsset } from '../../types/generation';
import './RegenerationButtons.css';

// =============================================================================
// Types
// =============================================================================

export type RegenerationType = 'portrait' | 'text' | 'audio' | 'image' | 'video';

export interface RegenerationButtonProps {
    /** Type of re-generation */
    type: RegenerationType;
    /** Target ID (shot ID, character ID, etc.) */
    targetId: string;
    /** Optional target label for tooltip */
    targetLabel?: string;
    /** Size variant */
    size?: 'sm' | 'md' | 'lg';
    /** Whether to show label text */
    showLabel?: boolean;
    /** Custom onClick override */
    onRegenerate?: (type: RegenerationType, targetId: string) => void;
    /** Disabled state */
    disabled?: boolean;
}

export interface BatchRegenerationProps {
    /** IDs to re-generate */
    targetIds: string[];
    /** Type of assets to regenerate */
    type: RegenerationType;
    /** Callback */
    onBatchRegenerate?: (type: RegenerationType, ids: string[]) => void;
}

// =============================================================================
// Config
// =============================================================================

const REGEN_CONFIG: Record<
    RegenerationType,
    { icon: typeof RefreshCw; label: string; color: string; gradientFrom: string; gradientTo: string }
> = {
    portrait: {
        icon: Image,
        label: 'Portrait',
        color: '#a855f7',
        gradientFrom: '#7c3aed',
        gradientTo: '#a855f7',
    },
    text: {
        icon: Type,
        label: 'Texte',
        color: '#3b82f6',
        gradientFrom: '#2563eb',
        gradientTo: '#60a5fa',
    },
    audio: {
        icon: Volume2,
        label: 'Audio',
        color: '#22c55e',
        gradientFrom: '#16a34a',
        gradientTo: '#4ade80',
