              type: 'image',
              url: 'test.png',
              metadata: { generationParams: {}, fileSize: 1000, format: 'png' },
              relatedAssets: [],
              timestamp: Date.now(),
            }
          },
        },
      },
    } as any);
    
    render(<ImageGenerationButton onClick={mockOnClick} />);
    
    expect(screen.getByText(/regenerate image/i)).toBeInTheDocument();
