/**
 * AnnotationTools Component - Drawing tools for annotations
 * 
 * Provides:
 * - Pen tool for freehand drawing
 * - Shape tools (rectangle, ellipse, line)
 * - Text annotation tool
 * - Stores annotations as separate layer type
 * 
 * Requirements: 12.1, 12.2, 12.3
 */

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { useGridStore } from '../../stores/gridEditorStore';
import type { 
  Panel, 
  Point, 
  DrawingElement, 
  TextAnnotation,
  AnnotationContent,
  Layer
} from '../../types/gridEditor';

// ============================================================================
// Type Definitions
// ============================================================================

export type AnnotationToolType = 'pen' | 'rectangle' | 'ellipse' | 'line' | 'text';

export interface AnnotationToolsProps {
  /**
   * The panel to annotate
   */
  panel: Panel;
  
  /**
   * Panel bounds in screen space
   */
  panelBounds: { x: number; y: number; width: number; height: number };
  
  /**
   * Active annotation tool
   */
  activeTool: AnnotationToolType;
  
  /**
   * Drawing style settings
   */
  style: {
    strokeColor: string;
    strokeWidth: number;
    fillColor?: string;
    opacity: number;
  };
  
  /**
   * Text style settings
   */
  textStyle: {
    fontSize: number;
    fontFamily: string;
    color: string;
    backgroundColor?: string;
  };
  
  /**
   * Callback when annotation is created
   */
  onAnnotationCreated?: () => void;
}

// ============================================================================
// Component
// ============================================================================

export const AnnotationTools: React.FC<AnnotationToolsProps> = ({
  panel,
  panelBounds,
  activeTool,
  style,
  textStyle,
  onAnnotationCreated,
}) => {
  const addLayer = useGridStore((state) => state.addLayer);
  const updateLayer = useGridStore((state) => state.updateLayer);
  
  // Drawing state
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentPoints, setCurrentPoints] = useState<Point[]>([]);
  const [startPoint, setStartPoint] = useState<Point | null>(null);
  const [textInput, setTextInput] = useState<{ position: Point; visible: boolean }>({
    position: { x: 0, y: 0 },
    visible: false,
  });
  const [textValue, setTextValue] = useState('');
  
  const svgRef = useRef<SVGSVGElement>(null);
  const textInputRef = useRef<HTMLInputElement>(null);

  // ============================================================================
  // Helper Functions
  // ============================================================================

  /**
   * Convert screen coordinates to panel-relative coordinates (0-1 normalized)
   */
  const screenToPanel = useCallback((screenPoint: Point): Point => {
    return {
      x: (screenPoint.x - panelBounds.x) / panelBounds.width,
      y: (screenPoint.y - panelBounds.y) / panelBounds.height,
    };
  }, [panelBounds]);

  /**
   * Convert panel-relative coordinates to screen coordinates
   */
  const panelToScreen = useCallback((panelPoint: Point): Point => {
    return {
      x: panelPoint.x * panelBounds.width + panelBounds.x,
      y: panelPoint.y * panelBounds.height + panelBounds.y,
    };
  }, [panelBounds]);

  /**
   * Get or create annotation layer for the panel
   */
  const getAnnotationLayer = useCallback((): Layer | null => {
    return panel.layers.find(
      (layer) => layer.type === 'annotation'
    ) || null;
  }, [panel.layers]);

  /**
   * Create a new annotation layer if it doesn't exist
   */
  const ensureAnnotationLayer = useCallback((): Layer => {
    let annotationLayer = getAnnotationLayer();
    
    if (!annotationLayer) {
      const newLayer: Layer = {
        id: `annotation-${Date.now()}`,
        name: 'Annotations',
        type: 'annotation',
        visible: true,
        locked: false,
        opacity: 1.0,
        blendMode: 'normal',
        content: {
          type: 'annotation',
          drawings: [],
          textAnnotations: [],
        },
      };
      
      addLayer(panel.id, newLayer);
      annotationLayer = newLayer;
    }
    
    return annotationLayer;
  }, [panel.id, getAnnotationLayer, addLayer]);

  /**
   * Add a drawing element to the annotation layer
   */
  const addDrawingElement = useCallback((element: DrawingElement) => {
    const layer = ensureAnnotationLayer();
    const content = layer.content as AnnotationContent;
    
    const updatedContent: AnnotationContent = {
      ...content,
      drawings: [...content.drawings, element],
    };
    
    updateLayer(panel.id, layer.id, { content: updatedContent });
    onAnnotationCreated?.();
  }, [panel.id, ensureAnnotationLayer, updateLayer, onAnnotationCreated]);

  /**
   * Add a text annotation to the annotation layer
   */
  const addTextAnnotation = useCallback((annotation: TextAnnotation) => {
    const layer = ensureAnnotationLayer();
    const content = layer.content as AnnotationContent;
    
    const updatedContent: AnnotationContent = {
      ...content,
      textAnnotations: [...content.textAnnotations, annotation],
    };
    
    updateLayer(panel.id, layer.id, { content: updatedContent });
    onAnnotationCreated?.();
  }, [panel.id, ensureAnnotationLayer, updateLayer, onAnnotationCreated]);

  // ============================================================================
  // Drawing Event Handlers
  // ============================================================================

  const handleMouseDown = useCallback((event: React.MouseEvent<SVGSVGElement>) => {
    if (activeTool === 'text') {
      // Text tool - show input at click position
      const point = screenToPanel({ x: event.clientX, y: event.clientY });
      setTextInput({ position: point, visible: true });
      setTextValue('');
      return;
    }

    // Start drawing
    setIsDrawing(true);
    const point = screenToPanel({ x: event.clientX, y: event.clientY });
    setStartPoint(point);
    setCurrentPoints([point]);
  }, [activeTool, screenToPanel]);

  const handleMouseMove = useCallback((event: React.MouseEvent<SVGSVGElement>) => {
    if (!isDrawing || !startPoint) return;

    const point = screenToPanel({ x: event.clientX, y: event.clientY });

    if (activeTool === 'pen') {
      // Freehand drawing - add points continuously
      setCurrentPoints((prev) => [...prev, point]);
    } else {
      // Shape tools - update end point
      setCurrentPoints([startPoint, point]);
    }
  }, [isDrawing, startPoint, activeTool, screenToPanel]);

  const handleMouseUp = useCallback(() => {
    if (!isDrawing || currentPoints.length === 0) return;

    // Create drawing element based on tool type
    const element: DrawingElement = {
      id: `drawing-${Date.now()}`,
      type: activeTool === 'pen' ? 'path' : (activeTool === 'text' ? 'path' : activeTool),
      points: currentPoints,
      style: {
        strokeColor: style.strokeColor,
        strokeWidth: style.strokeWidth,
        fillColor: style.fillColor,
        opacity: style.opacity,
      },
    };

    addDrawingElement(element);

    // Reset drawing state
    setIsDrawing(false);
    setCurrentPoints([]);
    setStartPoint(null);
  }, [isDrawing, currentPoints, activeTool, style, addDrawingElement]);

  // ============================================================================
  // Text Input Handlers
  // ============================================================================

  const handleTextSubmit = useCallback(() => {
    if (!textValue.trim() || !textInput.visible) return;

    const annotation: TextAnnotation = {
      id: `text-${Date.now()}`,
      text: textValue,
      position: textInput.position,
      style: {
        fontSize: textStyle.fontSize,
        fontFamily: textStyle.fontFamily,
        color: textStyle.color,
        backgroundColor: textStyle.backgroundColor,
      },
    };

    addTextAnnotation(annotation);

    // Reset text input
    setTextInput({ position: { x: 0, y: 0 }, visible: false });
    setTextValue('');
  }, [textValue, textInput, textStyle, addTextAnnotation]);

  const handleTextKeyDown = useCallback((event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      handleTextSubmit();
    } else if (event.key === 'Escape') {
      setTextInput({ position: { x: 0, y: 0 }, visible: false });
      setTextValue('');
    }
  }, [handleTextSubmit]);

  // Focus text input when it becomes visible
  useEffect(() => {
    if (textInput.visible && textInputRef.current) {
      textInputRef.current.focus();
    }
  }, [textInput.visible]);

  // ============================================================================
  // Render Preview
  // ============================================================================

  const renderPreview = () => {
    if (!isDrawing || currentPoints.length === 0) return null;

    const screenPoints = currentPoints.map(panelToScreen);

    switch (activeTool) {
      case 'pen':
        // Freehand path
        const pathData = screenPoints
          .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`)
          .join(' ');
        return (
          <path
            d={pathData}
            stroke={style.strokeColor}
            strokeWidth={style.strokeWidth}
            fill="none"
            opacity={style.opacity}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        );

      case 'line':
        // Straight line
        if (screenPoints.length >= 2) {
          const start = screenPoints[0];
          const end = screenPoints[screenPoints.length - 1];
          return (
            <line
              x1={start.x}
              y1={start.y}
              x2={end.x}
              y2={end.y}
              stroke={style.strokeColor}
              strokeWidth={style.strokeWidth}
              opacity={style.opacity}
              strokeLinecap="round"
            />
          );
        }
        return null;

      case 'rectangle':
        // Rectangle
        if (screenPoints.length >= 2) {
          const start = screenPoints[0];
          const end = screenPoints[screenPoints.length - 1];
          const x = Math.min(start.x, end.x);
          const y = Math.min(start.y, end.y);
          const width = Math.abs(end.x - start.x);
          const height = Math.abs(end.y - start.y);
          return (
            <rect
              x={x}
              y={y}
              width={width}
              height={height}
              stroke={style.strokeColor}
              strokeWidth={style.strokeWidth}
              fill={style.fillColor || 'none'}
              opacity={style.opacity}
            />
          );
        }
        return null;

      case 'ellipse':
        // Ellipse
        if (screenPoints.length >= 2) {
          const start = screenPoints[0];
          const end = screenPoints[screenPoints.length - 1];
          const cx = (start.x + end.x) / 2;
          const cy = (start.y + end.y) / 2;
          const rx = Math.abs(end.x - start.x) / 2;
          const ry = Math.abs(end.y - start.y) / 2;
          return (
            <ellipse
              cx={cx}
              cy={cy}
              rx={rx}
              ry={ry}
              stroke={style.strokeColor}
              strokeWidth={style.strokeWidth}
              fill={style.fillColor || 'none'}
              opacity={style.opacity}
            />
          );
        }
        return null;

      default:
        return null;
    }
  };

  // ============================================================================
  // Render
  // ============================================================================

  const textScreenPos = textInput.visible ? panelToScreen(textInput.position) : null;

  return (
    <>
      {/* SVG overlay for drawing */}
      <svg
        ref={svgRef}
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'all',
          cursor: activeTool === 'text' ? 'text' : 'crosshair',
        }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {renderPreview()}
      </svg>

      {/* Text input overlay */}
      {textInput.visible && textScreenPos && (
        <input
          ref={textInputRef}
          type="text"
          value={textValue}
          onChange={(e) => setTextValue(e.target.value)}
          onKeyDown={handleTextKeyDown}
          onBlur={handleTextSubmit}
          style={{
            position: 'absolute',
            left: `${textScreenPos.x}px`,
            top: `${textScreenPos.y}px`,
            fontSize: `${textStyle.fontSize}px`,
            fontFamily: textStyle.fontFamily,
            color: textStyle.color,
            backgroundColor: textStyle.backgroundColor || 'transparent',
            border: '1px solid #4a90e2',
            outline: 'none',
            padding: '4px 8px',
            borderRadius: '2px',
            minWidth: '100px',
            zIndex: 1000,
          }}
        />
      )}
    </>
  );
};

export default AnnotationTools;

/**
 * Auto-Save Indicator Component
 * 
 * This component provides:
 * - Visual indicator for auto-save status
 * - Last saved timestamp display
 * - Auto-save enable/disable toggle
 * - Interval configuration
 * 
 * Requirements: 15.7
 */

import React, { useState } from 'react';
import { useAutoSave, useAutoSaveStatus, useAutoSaveIndicator } from '../../hooks/useAutoSave';
import { useGridStore } from '../../stores/gridEditorStore';
import './AutoSaveIndicator.css';

// ============================================================================
// Type Definitions
// ============================================================================

export interface AutoSaveIndicatorProps {
  /**
   * Project ID for version control
   */
  projectId: string;

  /**
   * Author name for auto-saved versions
   */
  author?: string;

  /**
   * Initial auto-save interval in minutes
   * Default: 5 minutes
   */
  initialInterval?: number;

  /**
   * Whether auto-save is enabled by default
   * Default: false
   */
  defaultEnabled?: boolean;

  /**
   * Show configuration controls
   * Default: true
   */
  showControls?: boolean;

  /**
   * Compact mode (minimal UI)
   * Default: false
   */
  compact?: boolean;
}

// ============================================================================
// Auto-Save Indicator Component
// ============================================================================

export const AutoSaveIndicator: React.FC<AutoSaveIndicatorProps> = ({
  projectId,
  author = 'User',
  initialInterval = 5,
  defaultEnabled = false,
  showControls = true,
  compact = false,
}) => {
  const { exportConfiguration } = useGridStore();
  const [intervalMinutes, setIntervalMinutes] = useState(initialInterval);
  const [showSettings, setShowSettings] = useState(false);

  const {
    isEnabled,
    toggle,
    lastSavedAt,
    setInterval,
    saveNow,
  } = useAutoSave(
    () => exportConfiguration(),
    {
      interval: intervalMinutes * 60 * 1000,
      enabled: defaultEnabled,
      author,
      onAutoSave: (timestamp) => {
        ;
      },
      onError: (error) => {
        console.error('Auto-save error:', error);
      },
    }
  );

  const { lastSavedText } = useAutoSaveStatus(lastSavedAt);
  const { isSaving, showSaved } = useAutoSaveIndicator(lastSavedAt);

  const handleIntervalChange = (minutes: number) => {
    if (minutes < 1 || minutes > 60) {
      alert('Interval must be between 1 and 60 minutes');
      return;
    }
    setIntervalMinutes(minutes);
    setInterval(minutes * 60 * 1000);
  };

  if (compact) {
    return (
      <div className="auto-save-indicator compact">
        <button
          className={`auto-save-toggle ${isEnabled ? 'enabled' : 'disabled'}`}
          onClick={toggle}
          title={isEnabled ? 'Disable auto-save' : 'Enable auto-save'}
        >
          {isEnabled ? '💾' : '💾'}
        </button>

        {isSaving && <span className="saving-indicator">Saving...</span>}
        {showSaved && <span className="saved-indicator">✓</span>}

        {lastSavedAt && (
          <span className="last-saved-text">{lastSavedText}</span>
        )}
      </div>
    );
  }

  return (
    <div className="auto-save-indicator">
      <div className="auto-save-status">
        {/* Status indicator */}
        <div className="status-icon">
          {isSaving && (
            <span className="saving-spinner" title="Saving...">
              ⏳
            </span>
          )}
          {showSaved && (
            <span className="saved-checkmark" title="Saved">
              ✓
            </span>
          )}
          {!isSaving && !showSaved && isEnabled && (
            <span className="auto-save-active" title="Auto-save enabled">
              💾
            </span>
          )}
          {!isEnabled && (
            <span className="auto-save-inactive" title="Auto-save disabled">
              💾
            </span>
          )}
        </div>

        {/* Status text */}
        <div className="status-text">
          {isSaving && <span className="saving-text">Saving...</span>}
          {showSaved && <span className="saved-text">Saved!</span>}
          {!isSaving && !showSaved && lastSavedAt && (
            <span className="last-saved-text">{lastSavedText}</span>
          )}
          {!lastSavedAt && (
            <span className="not-saved-text">Not saved yet</span>
          )}
        </div>
      </div>

      {showControls && (
        <div className="auto-save-controls">
          {/* Enable/Disable toggle */}
          <label className="auto-save-toggle-label">
            <input
              type="checkbox"
              checked={isEnabled}
              onChange={toggle}
              className="auto-save-checkbox"
            />
            <span>Auto-Save</span>
          </label>

          {/* Manual save button */}
          <button
            className="manual-save-btn"
            onClick={saveNow}
            title="Save now"
          >
            Save Now
          </button>

          {/* Settings button */}
          <button
            className="settings-btn"
            onClick={() => setShowSettings(!showSettings)}
            title="Auto-save settings"
          >
            ⚙️
          </button>
        </div>
      )}

      {/* Settings panel */}
      {showSettings && (
        <div className="auto-save-settings">
          <div className="settings-header">
            <h4>Auto-Save Settings</h4>
            <button
              className="close-settings-btn"
              onClick={() => setShowSettings(false)}
            >
              ×
            </button>
          </div>

          <div className="settings-content">
            <label className="interval-label">
              <span>Save every:</span>
              <div className="interval-input-group">
                <input
                  type="number"
                  min="1"
                  max="60"
                  value={intervalMinutes}
                  onChange={(e) => {
                    const value = parseInt(e.target.value, 10);
                    if (!isNaN(value)) {
                      handleIntervalChange(value);
                    }
                  }}
                  className="interval-input"
                />
                <span className="interval-unit">minutes</span>
              </div>
            </label>

            <div className="settings-info">
              <p>
                Auto-save will automatically save your work at the specified interval.
                Versions are stored locally and can be restored from the version history.
              </p>
            </div>

            <div className="settings-actions">
              <button
                className="btn-primary"
                onClick={() => setShowSettings(false)}
              >
                Done
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// ============================================================================
// Simple Auto-Save Toggle Component
// ============================================================================

export interface SimpleAutoSaveToggleProps {
  projectId: string;
  author?: string;
  intervalMinutes?: number;
}

export const SimpleAutoSaveToggle: React.FC<SimpleAutoSaveToggleProps> = ({
  projectId,
  author = 'User',
  intervalMinutes = 5,
}) => {
  const { exportConfiguration } = useGridStore();

  const { isEnabled, toggle, lastSavedAt } = useAutoSave(
    () => exportConfiguration(),
    {
      interval: intervalMinutes * 60 * 1000,
      enabled: false,
      author,
    }
  );

  const { lastSavedText } = useAutoSaveStatus(lastSavedAt);

  return (
    <div className="simple-auto-save-toggle">
      <label>
        <input
          type="checkbox"
          checked={isEnabled}
          onChange={toggle}
        />
        <span>Auto-Save ({intervalMinutes}m)</span>
      </label>
      {lastSavedAt && (
        <span className="last-saved">{lastSavedText}</span>
      )}
    </div>
  );
};

export default AutoSaveIndicator;

/**
 * Backend Integration Example
 * 
 * Demonstrates the complete backend integration workflow:
 * - Panel image generation with loading states
 * - Batch generation for multiple panels
 * - Error handling and recovery
 * - Undo/redo integration
 * - Modified panel tracking
 * 
 * This example shows how all the backend integration pieces work together.
 */

import React, { useState } from 'react';
import { useGridStore } from '../../stores/gridEditorStore';
import { useUndoRedoStore } from '../../stores/undoRedoStore';
import { PanelGenerationControls } from './PanelGenerationControls';
import { PanelContextMenu } from './PanelContextMenu';
import { gridApi } from '../../services/gridEditor/GridAPIService';
import { imageLoader } from '../../services/gridEditor/ImageLoaderService';
import type { Panel } from '../../types/gridEditor';

export const BackendIntegrationExample: React.FC = () => {
  const panels = useGridStore((state) => state.config.panels);
  const selectedPanelIds = useGridStore((state) => state.selectedPanelIds);
  const selectPanel = useGridStore((state) => state.selectPanel);
  const updatePanelImage = useGridStore((state) => state.updatePanelImage);
  const markPanelAsModified = useGridStore((state) => state.markPanelAsModified);
  
  const pushOperation = useUndoRedoStore((state) => state.pushOperation);
  const undo = useUndoRedoStore((state) => state.undo);
  const redo = useUndoRedoStore((state) => state.redo);
  const canUndo = useUndoRedoStore((state) => state.canUndo);
  const canRedo = useUndoRedoStore((state) => state.canRedo);

  const [contextMenu, setContextMenu] = useState<{
    panel: Panel;
    position: { x: number; y: number };
  } | null>(null);

  const [batchGenerating, setBatchGenerating] = useState(false);
  const [batchProgress, setBatchProgress] = useState({ completed: 0, total: 0 });

  /**
   * Handle panel right-click to show context menu
   */
  const handlePanelContextMenu = (panel: Panel, event: React.MouseEvent) => {
    event.preventDefault();
    setContextMenu({
      panel,
      position: { x: event.clientX, y: event.clientY },
    });
  };

  /**
   * Handle generate from context menu
   */
  const handleGenerateFromMenu = async (panelId: string) => {
    const panel = panels.find((p) => p.id === panelId);
    if (!panel) return;

    // The PanelGenerationControls component handles the actual generation
    // This is just to demonstrate the workflow
    ;
  };

  /**
   * Handle batch generation for all panels
   */
  const handleBatchGenerate = async () => {
    setBatchGenerating(true);
    setBatchProgress({ completed: 0, total: panels.length });

    try {
      // Build batch request
      const batchRequest = {
        panels: panels.map((panel) => ({
          panelId: panel.id,
          prompt: `Generate image for panel ${panel.position.row}-${panel.position.col}`,
          seed: Math.floor(Math.random() * 1000000),
          transform: panel.transform,
          crop: panel.crop,
          styleReference: 'master-coherence-sheet',
          width: 512,
          height: 512,
        })),
        parallel: true,
        maxConcurrent: 3,
      };

      // Submit batch generation
      const response = await gridApi.batchGeneratePanels(batchRequest);

      if (!response.success || !response.data) {
        throw new Error(response.error || 'Batch generation failed');
      }

      // Update panels with generated images
      for (const result of response.data.results) {
        updatePanelImage(result.panelId, result.imageUrl, result.metadata);
        
        // Preload image for better performance
        await imageLoader.loadImage(result.imageUrl);
        
        setBatchProgress((prev) => ({
          ...prev,
          completed: prev.completed + 1,
        }));
      }

      // Record batch operation for undo
      pushOperation({
        type: 'batch_generation',
        timestamp: Date.now(),
        data: {
          panelId: response.data.results[0]?.panelId || '',
          before: {},
          after: response.data.results,
        },
      });

      ;
    } catch (error) {
      console.error('Batch generation error:', error);
    } finally {
      setBatchGenerating(false);
    }
  };

  /**
   * Handle panel modification (e.g., after transform)
   */
  const handlePanelModified = (panelId: string) => {
    markPanelAsModified(panelId);
  };

  /**
   * Handle generation complete
   */
  const handleGenerationComplete = (panelId: string, imageUrl: string) => {
    ;
    
    // Preload image with mipmaps for better performance
    imageLoader.loadImageWithMipmaps(imageUrl).then((mipmaps) => {
      ;
    });
  };

  /**
   * Handle generation error
   */
  const handleGenerationError = (panelId: string, error: string) => {
    console.error('Generation error:', panelId, error);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-100 dark:bg-gray-900">
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 p-4">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">
          Backend Integration Example
        </h1>
        <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
          Demonstrates panel generation, batch processing, and undo/redo
        </p>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* Grid Display */}
        <div className="flex-1 p-8 overflow-auto">
          <div className="grid grid-cols-3 gap-4 max-w-4xl mx-auto">
            {panels.map((panel) => (
              <div
                key={panel.id}
                className={`
                  aspect-square border-2 rounded-lg overflow-hidden cursor-pointer
                  transition-all duration-200
                  ${
                    selectedPanelIds.includes(panel.id)
                      ? 'border-blue-500 shadow-lg'
                      : 'border-gray-300 dark:border-gray-600 hover:border-gray-400'
                  }
                  ${panel.metadata?.modified ? 'ring-2 ring-yellow-400' : ''}
                `}
                onClick={() => selectPanel(panel.id, false)}
                onContextMenu={(e) => handlePanelContextMenu(panel, e)}
              >
                {panel.layers[0]?.content.type === 'image' ? (
                  <img
                    src={(panel.layers[0].content as any).url}
                    alt={`Panel ${panel.position.row}-${panel.position.col}`}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gray-200 dark:bg-gray-700">
                    <span className="text-gray-500 dark:text-gray-400 text-sm">
                      Panel {panel.position.row * 3 + panel.position.col + 1}
                    </span>
                  </div>
                )}
                
                {/* Modified Indicator */}
                {panel.metadata?.modified && (
                  <div className="absolute top-2 right-2 bg-yellow-400 text-yellow-900 text-xs px-2 py-1 rounded">
                    Modified
                  </div>
                )}
              </div>
            ))}
          </div>

          {/* Batch Generation Controls */}
          <div className="max-w-4xl mx-auto mt-8">
            <button
              onClick={handleBatchGenerate}
              disabled={batchGenerating}
              className="w-full px-6 py-3 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-700 hover:to-blue-700 text-white rounded-lg font-medium transition-all duration-200 shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {batchGenerating
                ? `Generating... ${batchProgress.completed}/${batchProgress.total}`
                : 'Generate All Panels'}
            </button>
          </div>
        </div>

        {/* Properties Panel */}
        <div className="w-80 bg-white dark:bg-gray-800 border-l border-gray-200 dark:border-gray-700 overflow-y-auto">
          {selectedPanelIds.length === 1 && (
            <div className="p-4">
              <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
                Panel Properties
              </h2>
              
              {/* Generation Controls */}
              <PanelGenerationControls
                panel={panels.find((p) => p.id === selectedPanelIds[0])!}
                onGenerationComplete={handleGenerationComplete}
                onGenerationError={handleGenerationError}
              />

              {/* Undo/Redo Controls */}
              <div className="mt-6 space-y-2">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
                  History
                </h3>
                <div className="flex gap-2">
                  <button
                    onClick={() => undo()}
                    disabled={!canUndo()}
                    className="flex-1 px-3 py-2 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-900 dark:text-gray-100 rounded disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Undo
                  </button>
                  <button
                    onClick={() => redo()}
                    disabled={!canRedo()}
                    className="flex-1 px-3 py-2 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-900 dark:text-gray-100 rounded disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Redo
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Context Menu */}
      {contextMenu && (
        <PanelContextMenu
          panel={contextMenu.panel}
          position={contextMenu.position}
          onClose={() => setContextMenu(null)}
          onGenerate={handleGenerateFromMenu}
        />
      )}
    </div>
  );
};

export default BackendIntegrationExample;

