          animation: slideIn 0.3s ease-out;
          min-width: 300px;
        }

        @keyframes slideIn {
          from {
            transform: translateX(100%);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }

        .notification-header {
          display: flex;
          align-items: flex-start;
          gap: 0.75rem;
        }

        .notification-icon {
          flex-shrink: 0;
          width: 1.5rem;
