// ============================================================================
// Hook for using notifications
// ============================================================================

/**
 * Hook for using the notification system
 */
export function useNotifications() {
  return {
    showSuccess,
    showError,
    showWarning,
    showInfo,
    dismiss: dismissNotification,
    clearAll: clearAllNotifications,
  };
}

// ============================================================================
// Predefined Notification Templates
// ============================================================================

/**
 * Show notification for successful operation
 */
export function notifyOperationSuccess(operation: string) {
  return showSuccess('Success', `${operation} completed successfully`);
}

/**
 * Show notification for failed operation
 */
export function notifyOperationError(
  operation: string,
  error: Error,
  recoveryOptions?: RecoveryOption[]
) {
  return showError(
    'Operation Failed',
    `Failed to ${operation.toLowerCase()}`,
    {
      recoveryOptions,
      technicalDetails: error.stack,
    }
  );
}

/**
 * Show notification for validation warning
 */
export function notifyValidationWarning(field: string, issue: string) {
  return showWarning('Validation Warning', `${field}: ${issue}`);
}

/**
 * Show notification for import error
 */
export function notifyImportError(error: Error) {
  return showError(
    'Import Failed',
    'Failed to import grid configuration',
    {
      technicalDetails: error.message,
      recoveryOptions: [
        {
          label: 'Try Again',
          action: () => {
            // Trigger file picker again
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.json';
            input.click();
          },
          isPrimary: true,
        },
      ],
    }
  );
}

/**
 * Show notification for export success
 */
export function notifyExportSuccess(filename: string) {
  return showSuccess('Export Complete', `Configuration saved as ${filename}`);
}

/**
 * Show notification for generation in progress
 */
export function notifyGenerationInProgress(panelCount: number) {
  return showInfo(
    'Generating Images',
    `Generating ${panelCount} panel${panelCount > 1 ? 's' : ''}...`,
    0 // Don't auto-dismiss
  );
}

/**
 * Show notification for generation complete
 */
export function notifyGenerationComplete(successCount: number, failCount: number) {
  if (failCount === 0) {
    return showSuccess(
      'Generation Complete',
      `Successfully generated ${successCount} panel${successCount > 1 ? 's' : ''}`
    );
  } else {
    return showWarning(
      'Generation Partially Complete',
      `Generated ${successCount} panel${successCount > 1 ? 's' : ''}, ${failCount} failed`
    );
  }
}

export default NotificationContainer;

/**
 * Panel Context Menu Component
 * 
 * Provides context menu for panel operations including generation
 * Displays on right-click or long-press on a panel
 * 
 * Validates Requirements: 11.1, 11.3
 */

import React, { useState, useEffect, useRef } from 'react';
import {
  Sparkles,
  Copy,
  Trash2,
  Crop,
  RotateCw,
  Maximize2,
  Eye,
  EyeOff,
  Lock,
  Unlock,
} from 'lucide-react';
import type { Panel } from '../../types/gridEditor';

// ============================================================================
// Type Definitions
// ============================================================================

export interface PanelContextMenuProps {
  /**
   * Panel for which the context menu is shown
   */
  panel: Panel;

  /**
   * Position to display the menu
   */
  position: { x: number; y: number };

  /**
   * Callback when menu is closed
   */
  onClose: () => void;

  /**
   * Callback when generate is clicked
   */
  onGenerate?: (panelId: string) => void;

  /**
   * Callback when duplicate is clicked
   */
  onDuplicate?: (panelId: string) => void;

  /**
   * Callback when delete is clicked
   */
  onDelete?: (panelId: string) => void;

  /**
   * Callback when crop is clicked
   */
  onCrop?: (panelId: string) => void;

  /**
   * Callback when rotate is clicked
   */
  onRotate?: (panelId: string) => void;

  /**
   * Callback when scale is clicked
   */
  onScale?: (panelId: string) => void;

  /**
   * Callback when visibility is toggled
   */
  onToggleVisibility?: (panelId: string) => void;

  /**
   * Callback when lock is toggled
   */
  onToggleLock?: (panelId: string) => void;
}

/**
 * Menu item definition
 */
interface MenuItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  onClick: () => void;
  disabled?: boolean;
  divider?: boolean;
  variant?: 'default' | 'primary' | 'danger';
}

// ============================================================================
// Component
// ============================================================================

export const PanelContextMenu: React.FC<PanelContextMenuProps> = ({
  panel,
  position,
  onClose,
  onGenerate,
  onDuplicate,
  onDelete,
  onCrop,
  onRotate,
  onScale,
  onToggleVisibility,
  onToggleLock,
}) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const [adjustedPosition, setAdjustedPosition] = useState(position);

  // Adjust menu position to keep it within viewport
  useEffect(() => {
    if (!menuRef.current) return;

    const menu = menuRef.current;
    const rect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let { x, y } = position;

    // Adjust horizontal position
    if (x + rect.width > viewportWidth) {
      x = viewportWidth - rect.width - 10;
    }

    // Adjust vertical position
    if (y + rect.height > viewportHeight) {
      y = viewportHeight - rect.height - 10;
    }

    setAdjustedPosition({ x, y });
  }, [position]);

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]);

  // Build menu items
  const menuItems: MenuItem[] = [
    {
      id: 'generate',
      label: 'Generate Image',
      icon: <Sparkles className="h-4 w-4" />,
      onClick: () => {
        onGenerate?.(panel.id);
        onClose();
      },
      variant: 'primary',
    },
    {
      id: 'divider-1',
      label: '',
      icon: null,
      onClick: () => {},
      divider: true,
    },
    {
      id: 'crop',
      label: 'Crop',
      icon: <Crop className="h-4 w-4" />,
      onClick: () => {
        onCrop?.(panel.id);
        onClose();
      },
    },
    {
      id: 'rotate',
      label: 'Rotate',
      icon: <RotateCw className="h-4 w-4" />,
      onClick: () => {
        onRotate?.(panel.id);
        onClose();
      },
    },
    {
      id: 'scale',
      label: 'Scale',
      icon: <Maximize2 className="h-4 w-4" />,
      onClick: () => {
        onScale?.(panel.id);
        onClose();
      },
    },
    {
      id: 'divider-2',
      label: '',
      icon: null,
      onClick: () => {},
      divider: true,
    },
    {
      id: 'visibility',
      label: panel.layers[0]?.visible ? 'Hide' : 'Show',
      icon: panel.layers[0]?.visible ? (
        <EyeOff className="h-4 w-4" />
      ) : (
        <Eye className="h-4 w-4" />
      ),
      onClick: () => {
        onToggleVisibility?.(panel.id);
        onClose();
      },
    },
    {
      id: 'lock',
      label: panel.layers[0]?.locked ? 'Unlock' : 'Lock',
      icon: panel.layers[0]?.locked ? (
        <Unlock className="h-4 w-4" />
      ) : (
        <Lock className="h-4 w-4" />
      ),
      onClick: () => {
        onToggleLock?.(panel.id);
        onClose();
      },
    },
    {
      id: 'divider-3',
      label: '',
      icon: null,
      onClick: () => {},
      divider: true,
    },
    {
      id: 'duplicate',
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        onDuplicate?.(panel.id);
        onClose();
      },
    },
    {
      id: 'delete',
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => {
        onDelete?.(panel.id);
        onClose();
      },
      variant: 'danger',
    },
  ];

  return (
    <div
      ref={menuRef}
      className="fixed z-50 min-w-[200px] bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-xl overflow-hidden"
      style={{
        left: `${adjustedPosition.x}px`,
        top: `${adjustedPosition.y}px`,
      }}
    >
      {/* Menu Header */}
      <div className="px-3 py-2 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900">
        <p className="text-xs font-medium text-gray-700 dark:text-gray-300">
          Panel {panel.position.row * 3 + panel.position.col + 1}
        </p>
      </div>

      {/* Menu Items */}
      <div className="py-1">
        {menuItems.map((item) => {
          if (item.divider) {
            return (
              <div
                key={item.id}
                className="my-1 border-t border-gray-200 dark:border-gray-700"
              />
            );
          }

          const baseClasses =
            'w-full flex items-center gap-3 px-3 py-2 text-sm transition-colors';
          const variantClasses = {
            default:
              'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700',
            primary:
              'text-purple-700 dark:text-purple-300 hover:bg-purple-50 dark:hover:bg-purple-900/20 font-medium',
            danger:
              'text-red-700 dark:text-red-300 hover:bg-red-50 dark:hover:bg-red-900/20',
          };

          return (
            <button
              key={item.id}
              onClick={item.onClick}
              disabled={item.disabled}
              className={`${baseClasses} ${
                variantClasses[item.variant || 'default']
              } ${item.disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              {item.icon}
              <span>{item.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default PanelContextMenu;

import React, { useRef, useEffect, useCallback, useState } from 'react';
import { Panel, Layer, AnnotationContent, EffectContent } from '../../types/gridEditor';

interface PanelRendererProps {
  panel: Panel;
  width: number;
  height: number;
  isSelected?: boolean;
  isHovered?: boolean;
  onLoad?: () => void;
}

/**
 * PanelRenderer - Renders an individual panel with all its layers
 * 
 * Responsibilities:
 * - Render individual panel with all layers
 * - Handle empty panel state with placeholder
 * - Implement layer blending with opacity and blend modes
 * - Add hover state highlighting
 * - Preserve image aspect ratios
 */
export const PanelRenderer: React.FC<PanelRendererProps> = ({
  panel,
  width,
  height,
  isSelected = false,
  isHovered = false,
  onLoad,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [imagesLoaded, setImagesLoaded] = useState(false);
  const imageCache = useRef<Map<string, HTMLImageElement>>(new Map());

  // Style constants
  const BORDER_COLOR = '#cccccc';
  const SELECTED_BORDER_COLOR = '#2196f3';
  const HOVER_BORDER_COLOR = '#64b5f6';
  const SELECTED_BORDER_WIDTH = 3;
  const HOVER_BORDER_WIDTH = 2;
  const PLACEHOLDER_COLOR = '#999999';
  const PLACEHOLDER_BG_COLOR = '#f5f5f5';

  /**
   * Load an image and cache it
   */
  const loadImage = useCallback((url: string): Promise<HTMLImageElement> => {
    const cached = imageCache.current.get(url);
    if (cached) {
      return Promise.resolve(cached);
    }

    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        imageCache.current.set(url, img);
        resolve(img);
      };
      img.onerror = reject;
      img.src = url;
    });
  }, []);

  /**
   * Render a single layer with proper blending and opacity
   */
  const renderLayer = useCallback((
    ctx: CanvasRenderingContext2D,
    layer: Layer,
    bounds: { x: number; y: number; width: number; height: number }
  ) => {
    if (!layer.visible) return;

    ctx.save();

    // Apply layer opacity
    ctx.globalAlpha = layer.opacity;

    // Apply blend mode
    const blendModeMap: Record<string, GlobalCompositeOperation> = {
      normal: 'source-over',
      multiply: 'multiply',
      screen: 'screen',
      overlay: 'overlay',
      darken: 'darken',
      lighten: 'lighten',
    };
    ctx.globalCompositeOperation = blendModeMap[layer.blendMode] || 'source-over';

    // Render based on layer type
    if (layer.type === 'image' && layer.content.type === 'image') {
      const img = imageCache.current.get(layer.content.url);
      if (img) {
        renderImageLayer(ctx, img, bounds, panel.transform, panel.crop);
      }
    } else if (layer.type === 'annotation' && layer.content.type === 'annotation') {
      renderAnnotationLayer(ctx, layer.content, bounds);
    } else if (layer.type === 'effect' && layer.content.type === 'effect') {
      renderEffectLayer(ctx, layer.content, bounds);
    }

    ctx.restore();
  }, [panel.transform, panel.crop]);

  /**
   * Render an image layer with aspect ratio preservation
   */
  const renderImageLayer = useCallback((
    ctx: CanvasRenderingContext2D,
    img: HTMLImageElement,
    bounds: { x: number; y: number; width: number; height: number },
    transform: unknown,
    crop: unknown
  ) => {
    // Calculate source rectangle (crop region)
    let srcX = 0;
    let srcY = 0;
    let srcWidth = img.naturalWidth;
    let srcHeight = img.naturalHeight;

    if (crop) {
      srcX = crop.x * img.naturalWidth;
      srcY = crop.y * img.naturalHeight;
      srcWidth = crop.width * img.naturalWidth;
      srcHeight = crop.height * img.naturalHeight;
    }

    // Calculate destination rectangle preserving aspect ratio
    const srcAspect = srcWidth / srcHeight;
    const boundsAspect = bounds.width / bounds.height;

    let drawWidth = bounds.width;
    let drawHeight = bounds.height;
    let drawX = bounds.x;
    let drawY = bounds.y;

    // Fit image within bounds while preserving aspect ratio
    if (srcAspect > boundsAspect) {
      // Image is wider - fit to width
      drawHeight = bounds.width / srcAspect;
      drawY = bounds.y + (bounds.height - drawHeight) / 2;
    } else {
      // Image is taller - fit to height
      drawWidth = bounds.height * srcAspect;
      drawX = bounds.x + (bounds.width - drawWidth) / 2;
    }

    // Apply transform if present
    if (transform) {
      const centerX = bounds.x + bounds.width / 2;
      const centerY = bounds.y + bounds.height / 2;

      ctx.translate(centerX, centerY);
      ctx.rotate((transform.rotation * Math.PI) / 180);
      ctx.scale(transform.scale.x, transform.scale.y);
      ctx.translate(-centerX, -centerY);
      ctx.translate(transform.position.x, transform.position.y);
    }

    // Draw the image
    ctx.drawImage(
      img,
      srcX, srcY, srcWidth, srcHeight,
      drawX, drawY, drawWidth, drawHeight
    );
  }, []);

  /**
   * Render annotation layer (drawings and text)
   */
  const renderAnnotationLayer = useCallback((
    ctx: CanvasRenderingContext2D,
    content: AnnotationContent,
    bounds: { x: number; y: number; width: number; height: number }
  ) => {
    // Render drawings
    if (content.drawings) {
      content.drawings.forEach((drawing: unknown) => {
        ctx.save();
        ctx.strokeStyle = drawing.style.strokeColor || '#000000';
        ctx.lineWidth = drawing.style.strokeWidth || 2;
        ctx.globalAlpha = drawing.style.opacity || 1;

        if (drawing.style.fillColor) {
          ctx.fillStyle = drawing.style.fillColor;
        }

        if (drawing.type === 'path' && drawing.points.length > 0) {
          ctx.beginPath();
          ctx.moveTo(
            bounds.x + drawing.points[0].x * bounds.width,
            bounds.y + drawing.points[0].y * bounds.height
          );
          for (let i = 1; i < drawing.points.length; i++) {
            ctx.lineTo(
              bounds.x + drawing.points[i].x * bounds.width,
              bounds.y + drawing.points[i].y * bounds.height
            );
          }
          ctx.stroke();
        } else if (drawing.type === 'rectangle') {
          const rect = {
            x: bounds.x + drawing.points[0].x * bounds.width,
            y: bounds.y + drawing.points[0].y * bounds.height,
            width: (drawing.points[1].x - drawing.points[0].x) * bounds.width,
            height: (drawing.points[1].y - drawing.points[0].y) * bounds.height,
          };
          if (drawing.style.fillColor) {
            ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
          }
          ctx.strokeRect(rect.x, rect.y, rect.width, rect.height);
        } else if (drawing.type === 'ellipse') {
          const centerX = bounds.x + drawing.points[0].x * bounds.width;
          const centerY = bounds.y + drawing.points[0].y * bounds.height;
          const radiusX = Math.abs(drawing.points[1].x - drawing.points[0].x) * bounds.width / 2;
          const radiusY = Math.abs(drawing.points[1].y - drawing.points[0].y) * bounds.height / 2;
          
          ctx.beginPath();
          ctx.ellipse(centerX, centerY, radiusX, radiusY, 0, 0, 2 * Math.PI);
          if (drawing.style.fillColor) {
            ctx.fill();
          }
          ctx.stroke();
        }

        ctx.restore();
      });
    }

    // Render text annotations
    if (content.textAnnotations) {
      content.textAnnotations.forEach((text: unknown) => {
        ctx.save();
        ctx.font = `${text.style.fontSize || 16}px ${text.style.fontFamily || 'sans-serif'}`;
        ctx.fillStyle = text.style.color || '#000000';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';

        const x = bounds.x + text.position.x * bounds.width;
        const y = bounds.y + text.position.y * bounds.height;

        // Draw background if specified
        if (text.style.backgroundColor) {
          const metrics = ctx.measureText(text.text);
          const padding = 4;
          ctx.fillStyle = text.style.backgroundColor;
          ctx.fillRect(
            x - padding,
            y - padding,
            metrics.width + padding * 2,
            (text.style.fontSize || 16) + padding * 2
          );
          ctx.fillStyle = text.style.color || '#000000';
        }

        ctx.fillText(text.text, x, y);
        ctx.restore();
      });
    }
  }, []);

  /**
   * Render effect layer (placeholder for future effects)
   */
  const renderEffectLayer = useCallback((
    ctx: CanvasRenderingContext2D,
    content: EffectContent,
    bounds: { x: number; y: number; width: number; height: number }
  ) => {
    // Placeholder for effect rendering
    // Effects could include filters, adjustments, etc.
    // For now, this is a no-op
    ;
  }, []);

  /**
   * Render empty panel placeholder
   */
  const renderPlaceholder = useCallback((
    ctx: CanvasRenderingContext2D,
    bounds: { x: number; y: number; width: number; height: number }
  ) => {
    // Draw background
    ctx.fillStyle = PLACEHOLDER_BG_COLOR;
    ctx.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);

    // Draw placeholder text
    ctx.save();
    ctx.fillStyle = PLACEHOLDER_COLOR;
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    
    const panelNumber = panel.position.row * 3 + panel.position.col + 1;
    ctx.fillText(
      `Panel ${panelNumber}`,
      bounds.x + bounds.width / 2,
      bounds.y + bounds.height / 2 - 10
    );
    
    ctx.font = '12px sans-serif';
    ctx.fillText(
      'Empty',
      bounds.x + bounds.width / 2,
      bounds.y + bounds.height / 2 + 10
    );
    ctx.restore();
  }, [panel.position]);

  /**
   * Main render function
   */
  const render = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Set canvas size with DPI handling
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.scale(dpr, dpr);

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    const bounds = { x: 0, y: 0, width, height };

    // Check if panel has visible layers
    const visibleLayers = panel.layers.filter(layer => layer.visible && !layer.locked);

    if (visibleLayers.length === 0) {
      // Render placeholder for empty panel
      renderPlaceholder(ctx, bounds);
    } else {
      // Render all visible layers in order (bottom to top)
      visibleLayers.forEach(layer => {
        renderLayer(ctx, layer, bounds);
      });
    }

    // Draw border
    let borderColor = BORDER_COLOR;
    let borderWidth = 1;

    if (isSelected) {
      borderColor = SELECTED_BORDER_COLOR;
      borderWidth = SELECTED_BORDER_WIDTH;
    } else if (isHovered) {
      borderColor = HOVER_BORDER_COLOR;
      borderWidth = HOVER_BORDER_WIDTH;
    }

    ctx.strokeStyle = borderColor;
    ctx.lineWidth = borderWidth;
    ctx.strokeRect(0, 0, width, height);

    // Draw hover highlight
    if (isHovered && !isSelected) {
      ctx.save();
      ctx.fillStyle = 'rgba(100, 181, 246, 0.1)';
      ctx.fillRect(0, 0, width, height);
      ctx.restore();
    }
  }, [width, height, panel, isSelected, isHovered, renderLayer, renderPlaceholder]);

  /**
   * Load all images and render
   */
  useEffect(() => {
    const imageUrls = panel.layers
      .filter(layer => layer.type === 'image' && layer.content.type === 'image')
      .map(layer => (layer.content as any).url);

    if (imageUrls.length === 0) {
      setImagesLoaded(true);
      render();
      onLoad?.();
      return;
    }

    Promise.all(imageUrls.map(url => loadImage(url).catch(() => null)))
      .then(() => {
        setImagesLoaded(true);
        render();
        onLoad?.();
      });
  }, [panel, loadImage, render, onLoad]);

  /**
   * Re-render when state changes
   */
  useEffect(() => {
    if (imagesLoaded) {
      render();
    }
  }, [imagesLoaded, isSelected, isHovered, render]);

  return (
    <canvas
      ref={canvasRef}
      style={{
        display: 'block',
        width: '100%',
        height: '100%',
      }}
    />
  );
};

/**
 * Preset System Integration Example
 * 
 * Demonstrates how to integrate the preset system into the grid editor.
 * Shows preset panel usage, custom preset creation, and preset application.
 */

import React, { useState } from 'react';
import { PresetPanel } from './PresetPanel';
import { usePresetStore, createPresetFromPanels } from '../../stores/gridEditor/presetStore';
import { useGridEditorStore } from '../../stores/gridEditorStore';
import './PresetPanel.css';

/**
 * Example 1: Basic Preset Panel Integration
 * 
 * Shows how to add the preset panel to your grid editor UI
 */
export const BasicPresetPanelExample: React.FC = () => {
  const [showPresets, setShowPresets] = useState(false);

  return (
    <div className="grid-editor-container">
      <div className="toolbar">
        <button onClick={() => setShowPresets(!showPresets)}>
          {showPresets ? 'Hide' : 'Show'} Presets
        </button>
      </div>

      {showPresets && (
        <div className="preset-sidebar">
          <PresetPanel onClose={() => setShowPresets(false)} />
        </div>
      )}

      <div className="grid-canvas">
        {/* Your grid editor canvas here */}
        <p>Grid Editor Canvas</p>
      </div>
    </div>
  );
};

/**
 * Example 2: Programmatic Preset Application
 * 
 * Shows how to apply presets programmatically
 */
export const ProgrammaticPresetExample: React.FC = () => {
  const { getPresetById } = usePresetStore();
  const { applyPreset } = useGridEditorStore();

  const applyDefaultPreset = () => {
    const preset = getPresetById('preset-default');
    if (preset) {
      applyPreset(preset);
      ;
    }
  };

  const applyCinematicPreset = () => {
    const preset = getPresetById('preset-cinematic');
    if (preset) {
      applyPreset(preset);
      ;
    }
  };

  const applyComicPreset = () => {
    const preset = getPresetById('preset-comic');
    if (preset) {
      applyPreset(preset);
      ;
    }
  };

  return (
    <div className="preset-controls">
      <h3>Quick Preset Application</h3>
      <div className="button-group">
        <button onClick={applyDefaultPreset}>Default</button>
        <button onClick={applyCinematicPreset}>Cinematic</button>
        <button onClick={applyComicPreset}>Comic Book</button>
      </div>
    </div>
  );
};

/**
 * Example 3: Custom Preset Creation
 * 
 * Shows how to create and save custom presets from current configuration
 */
export const CustomPresetCreationExample: React.FC = () => {
  const { addCustomPreset } = usePresetStore();
  const { panels } = useGridEditorStore();
  const [presetName, setPresetName] = useState('');

  const saveCurrentAsPreset = () => {
    if (!presetName.trim()) {
      alert('Please enter a preset name');
      return;
    }

    const presetData = createPresetFromPanels(
      presetName,
      'Custom preset created from current configuration',
      panels.map(p => ({ transform: p.transform, crop: p.crop }))
    );

    const presetId = addCustomPreset(presetData);
    ;
    setPresetName('');
  };

  return (
    <div className="custom-preset-creator">
      <h3>Save Current Configuration</h3>
      <input
        type="text"
        value={presetName}
        onChange={(e) => setPresetName(e.target.value)}
        placeholder="Enter preset name..."
      />
      <button onClick={saveCurrentAsPreset}>Save as Preset</button>
    </div>
  );
};

/**
 * Example 4: Preset List with Preview
 * 
 * Shows how to display all presets with custom rendering
 */
export const PresetListExample: React.FC = () => {
  const { getAllPresets, selectPreset, selectedPresetId } = usePresetStore();
  const { applyPreset } = useGridEditorStore();
  const allPresets = getAllPresets();

  const handlePresetClick = (presetId: string) => {
    const preset = allPresets.find(p => p.id === presetId);
    if (preset) {
      selectPreset(presetId);
      applyPreset(preset);
    }
  };

  return (
    <div className="preset-list">
      <h3>Available Presets</h3>
      <ul>
        {allPresets.map((preset) => (
          <li
            key={preset.id}
            className={selectedPresetId === preset.id ? 'selected' : ''}
            onClick={() => handlePresetClick(preset.id)}
          >
            <strong>{preset.name}</strong>
            <p>{preset.description}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

/**
 * Example 5: Complete Integration
 * 
 * Full example showing all preset features integrated
 */
export const CompletePresetIntegrationExample: React.FC = () => {
  const [showPresetPanel, setShowPresetPanel] = useState(false);
  const { getAllPresets, selectedPresetId } = usePresetStore();
  const { applyPreset } = useGridEditorStore();

  const quickApplyPreset = (presetId: string) => {
    const preset = getAllPresets().find(p => p.id === presetId);
    if (preset) {
      applyPreset(preset);
    }
  };

  return (
    <div className="complete-preset-integration">
      {/* Main toolbar with preset button */}
      <div className="main-toolbar">
        <button onClick={() => setShowPresetPanel(!showPresetPanel)}>
          📐 Presets
        </button>
        
        {/* Quick preset buttons */}
        <div className="quick-presets">
          <button onClick={() => quickApplyPreset('preset-cinematic')}>
            🎬 Cinematic
          </button>
          <button onClick={() => quickApplyPreset('preset-comic')}>
            📚 Comic
          </button>
          <button onClick={() => quickApplyPreset('preset-portrait')}>
            🖼️ Portrait
          </button>
          <button onClick={() => quickApplyPreset('preset-landscape')}>
            🏞️ Landscape
          </button>
        </div>
      </div>

      {/* Grid editor layout */}
      <div className="editor-layout">
        {/* Preset panel sidebar */}
        {showPresetPanel && (
          <aside className="preset-sidebar">
            <PresetPanel onClose={() => setShowPresetPanel(false)} />
          </aside>
        )}

        {/* Main canvas */}
        <main className="canvas-area">
          <div className="canvas-header">
            {selectedPresetId && (
              <div className="active-preset-indicator">
                Active Preset: {getAllPresets().find(p => p.id === selectedPresetId)?.name}
              </div>
            )}
          </div>
          <div className="grid-canvas">
            {/* Your grid editor canvas component here */}
            <p>Grid Editor Canvas</p>
          </div>
        </main>
      </div>
    </div>
  );
};

/**
 * Example 6: Preset with Backend Integration
 * 
 * Shows how to integrate presets with backend generation
 */
export const PresetBackendIntegrationExample: React.FC = () => {
  const { getPresetById } = usePresetStore();
  const { applyPreset, panels } = useGridEditorStore();
  const [isGenerating, setIsGenerating] = useState(false);

  const applyPresetAndGenerate = async (presetId: string) => {
    const preset = getPresetById(presetId);
    if (!preset) return;

    // Apply preset
    applyPreset(preset);

    // Trigger backend generation with preset parameters
    setIsGenerating(true);
    try {
      // Example: Send preset style parameters to backend
      const response = await fetch('/api/generate-with-preset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          presetId: preset.id,
          presetName: preset.name,
          panels: panels.map((panel, index) => ({
            panelId: panel.id,
            transform: preset.panelTransforms[index],
            crop: preset.panelCrops[index],
          })),
        }),
      });

      const result = await response.json();
      ;
    } catch (error) {
      console.error('Generation failed:', error);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="preset-backend-integration">
      <h3>Apply Preset & Generate</h3>
      <div className="preset-actions">
        <button
          onClick={() => applyPresetAndGenerate('preset-cinematic')}
          disabled={isGenerating}
        >
          {isGenerating ? 'Generating...' : 'Cinematic + Generate'}
        </button>
        <button
          onClick={() => applyPresetAndGenerate('preset-comic')}
          disabled={isGenerating}
        >
          {isGenerating ? 'Generating...' : 'Comic + Generate'}
        </button>
      </div>
    </div>
  );
};

