/**
 * ResponsiveGridLayout Component
 * 
 * Grid layout that adapts to different screen sizes with smooth transitions.
 * Automatically switches between grid and list modes based on viewport width.
 * 
 * Exigences: 12.1, 12.2, 12.3, 12.4, 12.5, 12.6, 12.7, 12.8
 */

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useResponsiveGrid } from '../../hooks/useResponsiveGrid';
import { getLayoutPreferencesManager } from '../../services/responsive/LayoutPreferences';
import type { GridLayoutConfig, GridPanel } from '../../types/gridEditorAdvanced';
import { GridLayout } from './GridLayout';
import { GridListView } from './GridListView';

export interface ResponsiveGridLayoutProps {
  items: GridPanel[];
  baseConfig: GridLayoutConfig;
  onLayoutChange?: (items: GridPanel[]) => void;
  enablePreferences?: boolean;
  animateTransitions?: boolean;
}

export const ResponsiveGridLayout: React.FC<ResponsiveGridLayoutProps> = ({
  items,
  baseConfig,
  onLayoutChange,
  enablePreferences = true,
  animateTransitions = true
}) => {
  const responsive = useResponsiveGrid();
  const [config, setConfig] = useState<GridLayoutConfig>(baseConfig);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const preferencesManager = useMemo(() => getLayoutPreferencesManager(), []);

  /**
   * Load preferences for current breakpoint
   * Exigence: 12.8
   */
  useEffect(() => {
    if (!enablePreferences) return;

    const preference = preferencesManager.getPreference(responsive.breakpoint);
    if (preference) {
      setConfig(prev => ({
        ...prev,
        columns: preference.columns ?? prev.columns,
        showGridLines: preference.showGridLines ?? prev.showGridLines,
        snapEnabled: preference.snapEnabled ?? prev.snapEnabled,
        cellSize: preference.gridSize 
          ? { width: preference.gridSize, height: preference.gridSize }
          : prev.cellSize
      }));
    }
  }, [responsive.breakpoint, enablePreferences, preferencesManager]);

  /**
   * Update config when breakpoint changes
   * Exigences: 12.2, 12.3, 12.4
   */
  useEffect(() => {
    setConfig(prev => ({
      ...prev,
      columns: responsive.columns
    }));
  }, [responsive.columns]);

  /**
   * Handle window resize with animation
   * Exigences: 12.1, 12.6
   */
  useEffect(() => {
    if (animateTransitions) {
      setIsTransitioning(true);
      const timer = setTimeout(() => setIsTransitioning(false), 300);
      return () => clearTimeout(timer);
    }
  }, [responsive.width, responsive.height, animateTransitions]);

  /**
   * Adjust layout for fullscreen mode
   * Exigence: 12.5
   */
  useEffect(() => {
    if (responsive.isFullscreen) {
      // Maximize space utilization in fullscreen
      setConfig(prev => ({
        ...prev,
        gap: Math.max(4, prev.gap - 4), // Reduce gap slightly
        showGridLines: false // Hide grid lines for cleaner look
      }));
    } else {
      // Restore normal config
      setConfig(prev => ({
        ...prev,
        gap: baseConfig.gap,
        showGridLines: baseConfig.showGridLines
      }));
    }
  }, [responsive.isFullscreen, baseConfig.gap, baseConfig.showGridLines]);

  /**
   * Handle orientation change
   * Exigence: 12.7
   */
  useEffect(() => {
    // Recalculate layout immediately on orientation change
    if (responsive.orientation === 'portrait' && responsive.width < 1024) {
      // Force list mode in portrait on smaller screens
      setConfig(prev => ({
        ...prev,
        columns: 1
      }));
    }
  }, [responsive.orientation, responsive.width]);

  /**
   * Save preferences when config changes
   * Exigence: 12.8
   */
  const handleConfigChange = useCallback((newConfig: Partial<GridLayoutConfig>) => {
    setConfig(prev => ({ ...prev, ...newConfig }));

    if (enablePreferences) {
      preferencesManager.setPreference(responsive.breakpoint, {
        columns: newConfig.columns,
        showGridLines: newConfig.showGridLines,
        snapEnabled: newConfig.snapEnabled,
        gridSize: newConfig.cellSize?.width
      });
    }
  }, [enablePreferences, preferencesManager, responsive.breakpoint]);

  /**
   * Handle layout change with proportion maintenance
   * Exigence: 12.6
   */
  const handleLayoutChange = useCallback((newItems: GridPanel[]) => {
    // Maintain proportions when resizing
    const scaledItems = newItems.map(item => {
      const widthRatio = item.size.width / config.cellSize.width;
      const heightRatio = item.size.height / config.cellSize.height;

      return {
        ...item,
        size: {
          width: Math.round(widthRatio * config.cellSize.width),
          height: Math.round(heightRatio * config.cellSize.height)
        }
      };
    });

    onLayoutChange?.(scaledItems);
  }, [config.cellSize, onLayoutChange]);

  /**
   * Render appropriate view based on breakpoint
   * Exigence: 12.2
   */
  const renderView = () => {
    if (responsive.useListMode) {
      // List mode for small screens (< 1024px)
      return (
        <GridListView
          items={items}
          onItemClick={(item) => console.log('Item clicked:', item)}
          onLayoutChange={onLayoutChange}
        />
      );
    }

    // Grid mode for larger screens
    return (
      <GridLayout
        config={config}
        items={items}
        onLayoutChange={handleLayoutChange}
      />
    );
  };

  return (
    <motion.div
      className="responsive-grid-layout"
      style={{
        width: '100%',
        height: '100%',
        position: 'relative',
        overflow: 'hidden'
      }}
      animate={{
        opacity: isTransitioning ? 0.8 : 1
      }}
      transition={{
        duration: 0.3,
        ease: 'easeInOut'
      }}
    >
      {/* Breakpoint indicator (dev mode) */}
      {process.env.NODE_ENV === 'development' && (
        <div
          style={{
            position: 'absolute',
            top: 8,
            right: 8,
            padding: '4px 8px',
            background: 'rgba(0, 0, 0, 0.7)',
            color: 'white',
            fontSize: '12px',
            borderRadius: '4px',
            zIndex: 9999,
            pointerEvents: 'none'
          }}
        >
          {responsive.breakpoint.name} ({responsive.width}x{responsive.height})
          {responsive.isFullscreen && ' [Fullscreen]'}
        </div>
      )}

      {/* Animated view transition */}
      <AnimatePresence mode="wait">
        <motion.div
          key={responsive.useListMode ? 'list' : 'grid'}
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.95 }}
          transition={{
            duration: animateTransitions ? 0.3 : 0,
            ease: 'easeInOut'
          }}
          style={{
            width: '100%',
            height: '100%'
          }}
        >
          {renderView()}
        </motion.div>
      </AnimatePresence>

      {/* Configuration controls */}
      <ResponsiveGridControls
        config={config}
        responsive={responsive}
        onConfigChange={handleConfigChange}
      />
    </motion.div>
  );
};

/**
 * Controls for responsive grid configuration
 */
interface ResponsiveGridControlsProps {
  config: GridLayoutConfig;
  responsive: ReturnType<typeof useResponsiveGrid>;
  onConfigChange: (config: Partial<GridLayoutConfig>) => void;
}

const ResponsiveGridControls: React.FC<ResponsiveGridControlsProps> = ({
  config,
  responsive,
  onConfigChange
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <motion.div
      className="responsive-grid-controls"
      style={{
        position: 'absolute',
        bottom: 16,
        right: 16,
        background: 'white',
        borderRadius: '8px',
        boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
        overflow: 'hidden',
        zIndex: 1000
      }}
      initial={false}
      animate={{
        width: isExpanded ? 280 : 48,
        height: isExpanded ? 'auto' : 48
      }}
    >
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        style={{
          width: '100%',
          padding: '12px',
          border: 'none',
          background: 'transparent',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        ⚙️
      </button>

      {isExpanded && (
        <div style={{ padding: '0 16px 16px' }}>
          <div style={{ marginBottom: '12px' }}>
            <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px' }}>
              Columns: {config.columns}
            </label>
            <input
              type="range"
              min="1"
              max="6"
              value={config.columns}
              onChange={(e) => onConfigChange({ columns: parseInt(e.target.value) })}
              style={{ width: '100%' }}
            />
          </div>

          <div style={{ marginBottom: '12px' }}>
            <label style={{ display: 'flex', alignItems: 'center', fontSize: '12px' }}>
              <input
                type="checkbox"
                checked={config.showGridLines}
                onChange={(e) => onConfigChange({ showGridLines: e.target.checked })}
                style={{ marginRight: '8px' }}
              />
              Show Grid Lines
            </label>
          </div>

          <div style={{ marginBottom: '12px' }}>
            <label style={{ display: 'flex', alignItems: 'center', fontSize: '12px' }}>
              <input
                type="checkbox"
                checked={config.snapEnabled}
                onChange={(e) => onConfigChange({ snapEnabled: e.target.checked })}
                style={{ marginRight: '8px' }}
              />
              Snap to Grid
            </label>
          </div>

          <div style={{ fontSize: '10px', color: '#666', marginTop: '12px' }}>
            {responsive.breakpoint.name} • {responsive.orientation}
          </div>
        </div>
      )}
    </motion.div>
  );
};

/**
 * Toolbar Integration Example
 * 
 * This example demonstrates how to integrate the Toolbar component
 * and useKeyboardShortcuts hook into a Grid Editor application.
 */

import React, { useState } from 'react';
import { Toolbar } from './Toolbar';
import { useKeyboardShortcuts } from './useKeyboardShortcuts';
import { useGridStore } from '../../stores/gridEditorStore';

// ============================================================================
// Example: Basic Toolbar Integration
// ============================================================================

export const BasicToolbarExample: React.FC = () => {
  const gridBounds = { width: 1920, height: 1080 };

  return (
    <div style={{ width: '100%', height: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Toolbar at the top */}
      <Toolbar gridBounds={gridBounds} />

      {/* Grid editor content */}
      <div style={{ flex: 1, backgroundColor: '#1a1a1a', position: 'relative' }}>
        <div style={{ color: '#ccc', padding: '20px' }}>
          <h2>Grid Editor Canvas</h2>
          <p>Use the toolbar above to select tools and control the viewport.</p>
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Example: Toolbar with Keyboard Shortcuts
// ============================================================================

export const ToolbarWithKeyboardShortcutsExample: React.FC = () => {
  const gridBounds = { width: 1920, height: 1080 };
  const [lastShortcut, setLastShortcut] = useState<string>('');

  // Enable keyboard shortcuts
  useKeyboardShortcuts({
    enabled: true,
    gridBounds,
    onShortcut: (action, key) => {
      setLastShortcut(`${action} (${key})`);
    },
    onDelete: () => {
      console.log('Delete action');
      // Implement delete logic here
    },
    onDuplicate: () => {
      console.log('Duplicate action');
      // Implement duplicate logic here
    },
  });

  return (
    <div style={{ width: '100%', height: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Toolbar */}
      <Toolbar gridBounds={gridBounds} />

      {/* Grid editor content */}
      <div style={{ flex: 1, backgroundColor: '#1a1a1a', position: 'relative' }}>
        <div style={{ color: '#ccc', padding: '20px' }}>
          <h2>Grid Editor with Keyboard Shortcuts</h2>
          <p>Try pressing keyboard shortcuts:</p>
          <ul>
            <li>V - Select tool</li>
            <li>C - Crop tool</li>
            <li>R - Rotate tool</li>
            <li>S - Scale tool</li>
            <li>Space - Pan tool (hold)</li>
            <li>Ctrl+Z - Undo</li>
            <li>Ctrl+Shift+Z - Redo</li>
            <li>[ / ] - Cycle panels</li>
            <li>F - Focus mode</li>
            <li>Escape - Deselect all</li>
          </ul>
          {lastShortcut && (
            <div style={{ marginTop: '20px', padding: '10px', backgroundColor: '#2a2a2a', borderRadius: '4px' }}>
              <strong>Last shortcut:</strong> {lastShortcut}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Example: Complete Grid Editor Integration
// ============================================================================

export const CompleteGridEditorExample: React.FC = () => {
  const gridBounds = { width: 1920, height: 1080 };
  const activeTool = useGridStore((state) => state.activeTool);
  const selectedPanelIds = useGridStore((state) => state.selectedPanelIds);

  // Keyboard shortcuts with full callbacks
  useKeyboardShortcuts({
    enabled: true,
    gridBounds,
    onShortcut: (action, key) => {
      console.log(`Shortcut: ${action} (${key})`);
    },
    onDelete: () => {
      if (selectedPanelIds.length > 0) {
        console.log('Deleting panels:', selectedPanelIds);
        // Implement delete logic
        // Example: Clear layers from selected panels
        selectedPanelIds.forEach((panelId) => {
          const panel = useGridStore.getState().getPanelById(panelId);
          if (panel) {
            panel.layers.forEach((layer) => {
              useGridStore.getState().removeLayer(panelId, layer.id);
            });
          }
        });
      }
    },
    onDuplicate: () => {
      if (selectedPanelIds.length === 1) {
        const sourcePanelId = selectedPanelIds[0];
        console.log('Duplicating panel:', sourcePanelId);
        // Implement duplicate logic
        // Example: Copy to clipboard
        useGridStore.getState().copyPanel(sourcePanelId);
      }
    },
  });

  return (
    <div style={{ width: '100%', height: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Toolbar */}
      <Toolbar
        gridBounds={gridBounds}
        onToolChange={(tool) => {
          ;
        }}
      />

      {/* Status bar */}
      <div
        style={{
          padding: '8px 16px',
          backgroundColor: '#2a2a2a',
          borderBottom: '1px solid #444',
          color: '#ccc',
          fontSize: '12px',
          display: 'flex',
          gap: '20px',
        }}
      >
        <div>
          <strong>Active Tool:</strong> {activeTool}
        </div>
        <div>
          <strong>Selected Panels:</strong> {selectedPanelIds.length}
        </div>
      </div>

      {/* Grid editor content */}
      <div style={{ flex: 1, backgroundColor: '#1a1a1a', position: 'relative' }}>
        {/* Your grid renderer, viewport, and interaction layer go here */}
        <div style={{ color: '#ccc', padding: '20px' }}>
          <h2>Complete Grid Editor</h2>
          <p>This example shows full integration with toolbar and keyboard shortcuts.</p>
          <p>Current tool: <strong>{activeTool}</strong></p>
          <p>Selected panels: <strong>{selectedPanelIds.length}</strong></p>
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Example: Conditional Keyboard Shortcuts
// ============================================================================

export const ConditionalShortcutsExample: React.FC = () => {
  const [shortcutsEnabled, setShortcutsEnabled] = useState(true);
  const gridBounds = { width: 1920, height: 1080 };

  useKeyboardShortcuts({
    enabled: shortcutsEnabled,
    gridBounds,
    onShortcut: (action, key) => {
      console.log(`Shortcut: ${action} (${key})`);
    },
  });

  return (
    <div style={{ width: '100%', height: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Toolbar gridBounds={gridBounds} />

      <div style={{ padding: '20px', backgroundColor: '#1a1a1a', color: '#ccc' }}>
        <h2>Conditional Keyboard Shortcuts</h2>
        <p>Toggle keyboard shortcuts on/off:</p>
        <button
          onClick={() => setShortcutsEnabled(!shortcutsEnabled)}
          style={{
            padding: '8px 16px',
            backgroundColor: shortcutsEnabled ? '#4a90e2' : '#666',
            color: '#fff',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
          }}
        >
          Shortcuts: {shortcutsEnabled ? 'Enabled' : 'Disabled'}
        </button>
        <p style={{ marginTop: '20px' }}>
          {shortcutsEnabled
            ? 'Try pressing V, C, R, or S to change tools'
            : 'Keyboard shortcuts are disabled'}
        </p>
      </div>
    </div>
  );
};

// ============================================================================
// Example: Custom Toolbar Styling
// ============================================================================

export const CustomStyledToolbarExample: React.FC = () => {
  const gridBounds = { width: 1920, height: 1080 };

  return (
    <div style={{ width: '100%', height: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Toolbar with custom className */}
      <Toolbar
        className="custom-toolbar"
        gridBounds={gridBounds}
        onToolChange={(tool) => {
          ;
        }}
      />

      {/* Add custom styles */}
      <style>{`
        .custom-toolbar {
          box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
        }
      `}</style>

      <div style={{ flex: 1, backgroundColor: '#1a1a1a' }}>
        <div style={{ color: '#ccc', padding: '20px' }}>
          <h2>Custom Styled Toolbar</h2>
          <p>The toolbar has custom styling applied via className.</p>
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Export All Examples
// ============================================================================

export default {
  BasicToolbarExample,
  ToolbarWithKeyboardShortcutsExample,
  CompleteGridEditorExample,
  ConditionalShortcutsExample,
  CustomStyledToolbarExample,
};

