      // Act - Generate image
      const generationConfig: PanelGenerationConfig = {
        panelId: panel.id,
        prompt: 'Test panel',
        seed: 12345,
        transform: panel.transform,
        crop: panel.crop,
        styleReference: 'master-coherence-sheet',
        width: 512,
        height: 512,
      };

      const response = await mockGridAPI.generatePanelImage(generationConfig);

      if (response.success && response.data) {
        act(() => {
          gridStore.current.updatePanelImage(
            response.data!.panelId,
            response.data!.imageUrl,
            response.data!.metadata
          );
        });
      }

      // Act - Enter focus mode
      act(() => {
        viewportStore.current.focusPanel(panel.id, panelBounds);
      });

      // Assert
      const updatedPanel = gridStore.current.getPanelById(panel.id);
      expect(updatedPanel?.layers.length).toBeGreaterThan(0);
      expect(viewportStore.current.focusedPanelId).toBe(panel.id);
    });

    it('should handle generation error while in focus mode', async () => {
      // Arrange
      mockGridAPI.setMockFailureRate(1.0); // Force failure
      const { result: gridStore } = renderHook(() => useGridStore());
      const { result: viewportStore } = renderHook(() => useViewportStore());
      
      const panel = gridStore.current.getAllPanels()[0];
      const panelBounds = { width: 640, height: 360 };

      // Enter focus mode first
      act(() => {
        viewportStore.current.focusPanel(panel.id, panelBounds);
      });

      // Act - Attempt generation
      const generationConfig: PanelGenerationConfig = {
        panelId: panel.id,
        prompt: 'Test panel',
        seed: 12345,
        transform: panel.transform,
        crop: panel.crop,
        styleReference: 'master-coherence-sheet',
      };

      const response = await mockGridAPI.generatePanelImage(generationConfig);

      // Assert - Should remain in focus mode despite error
      expect(response.success).toBe(false);
      expect(viewportStore.current.focusedPanelId).toBe(panel.id);
      
      // Panel state should be unchanged
      const unchangedPanel = gridStore.current.getPanelById(panel.id);
      expect(unchangedPanel?.layers.length).toBe(0);
    });
  });
});

/**
 * Tests for useTransformInteraction hook
 * 
 * Validates:
 * - Position drag with delta calculation (Req 3.2)
 * - Scale drag with proportional/non-proportional modes (Req 3.3, 3.4)
 * - Rotation drag with angle calculation and snapping (Req 3.5, 3.6)
 * - Transform commit on mouse release (Req 3.8)
 */

import { renderHook, act } from '@testing-library/react';
import { vi } from 'vitest';
import { useTransformInteraction } from '../useTransformInteraction';
import { useGridStore } from '../../../stores/gridEditorStore';
import { useViewportStore } from '../../../stores/viewportStore';
import { createEmptyPanel } from '../../../types/gridEditor.factories';
import type { Panel } from '../../../stores/gridEditorStore';

// Mock stores
vi.mock('../../../stores/gridEditorStore');
vi.mock('../../../stores/viewportStore');

describe('useTransformInteraction', () => {
  let mockUpdatePanelTransform: ReturnType<typeof vi.fn>;
  let mockScreenToCanvas: ReturnType<typeof vi.fn>;
  let testPanel: Panel;

  beforeEach(() => {
    // Reset mocks
    mockUpdatePanelTransform = vi.fn();
    mockScreenToCanvas = vi.fn((point) => point); // Identity transform for simplicity

    // Setup store mocks
    vi.mocked(useGridStore).mockImplementation((selector: any) =>
      selector({ updatePanelTransform: mockUpdatePanelTransform })
    );

    vi.mocked(useViewportStore).mockImplementation((selector: any) =>
      selector({ screenToCanvas: mockScreenToCanvas })
    );

    // Create test panel
    testPanel = createEmptyPanel(0, 0);
    testPanel.transform = {
      position: { x: 100, y: 100 },
      scale: { x: 1, y: 1 },
      rotation: 0,
      pivot: { x: 0.5, y: 0.5 },
    };
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  // ============================================================================
  // Position Transform Tests (Req 3.2)
  // ============================================================================

  describe('Position Transform', () => {
    it('should handle position drag with delta calculation', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      // Start position transform
      act(() => {
        result.current.startTransform('position', 'top', { x: 200, y: 200 });
      });

      expect(result.current.isTransforming).toBe(true);
      expect(result.current.transformType).toBe('position');

      // Simulate mouse move with delta
      act(() => {
        // Simulate mousemove event
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 250,
          clientY: 250,
          shiftKey: false,
          ctrlKey: false,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      // Current transform should reflect the delta (50, 50)
      expect(result.current.currentTransform).toMatchObject({
        position: {
          x: 150, // 100 + 50
          y: 150, // 100 + 50
        },
      });

      // Simulate mouse up to commit
      act(() => {
        const mouseUpEvent = new MouseEvent('mouseup');
        window.dispatchEvent(mouseUpEvent);
      });

      // Should commit transform
      expect(mockUpdatePanelTransform).toHaveBeenCalledWith(
        'panel-0-0',
        expect.objectContaining({
          position: { x: 150, y: 150 },
        })
      );
    });

    it('should apply position delta correctly for negative movements', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('position', 'bottom', { x: 200, y: 200 });
      });

      // Move mouse backwards (negative delta)
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 150,
          clientY: 150,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      expect(result.current.currentTransform?.position).toEqual({
        x: 50, // 100 - 50
        y: 50, // 100 - 50
      });
    });
  });

  // ============================================================================
  // Scale Transform Tests (Req 3.3, 3.4)
  // ============================================================================

  describe('Scale Transform', () => {
    it('should handle proportional scaling when Shift is NOT held', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('scale', 'bottomRight', { x: 200, y: 200 });
      });

      // Move mouse without Shift key (proportional mode)
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 300,
          clientY: 300,
          shiftKey: false, // Proportional scaling
          ctrlKey: false,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      // Should maintain aspect ratio
      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      if (transform) {
        const aspectRatio = transform.scale.x / transform.scale.y;
        const originalAspectRatio = testPanel.transform.scale.x / testPanel.transform.scale.y;
        expect(Math.abs(aspectRatio - originalAspectRatio)).toBeLessThan(0.01);
      }
    });

    it('should handle non-proportional scaling when Shift IS held', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('scale', 'bottomRight', { x: 200, y: 200 });
      });

      // Move mouse with Shift key (non-proportional mode)
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 300,
          clientY: 250,
          shiftKey: true, // Non-proportional scaling
          ctrlKey: false,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      // Scale values can be different
      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      if (transform) {
        // With non-proportional scaling, x and y can differ
        expect(transform.scale.x).toBeGreaterThan(0);
        expect(transform.scale.y).toBeGreaterThan(0);
      }
    });

    it('should clamp scale values to MIN and MAX limits', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('scale', 'topLeft', { x: 200, y: 200 });
      });

      // Try to scale way beyond limits
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 10000,
          clientY: 10000,
          shiftKey: true,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      if (transform) {
        // Should be clamped to MAX_SCALE (10.0)
        expect(transform.scale.x).toBeLessThanOrEqual(10.0);
        expect(transform.scale.y).toBeLessThanOrEqual(10.0);
      }
    });
  });

  // ============================================================================
  // Rotation Transform Tests (Req 3.5, 3.6)
  // ============================================================================

  describe('Rotation Transform', () => {
    it('should calculate rotation angle from mouse position', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('rotation', 'rotation', { x: 200, y: 200 });
      });

      // Move mouse to a position that creates a specific angle
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 200, // Same x as panel center (100 + some offset)
          clientY: 50,  // Above panel center
          shiftKey: false,
          ctrlKey: false, // No snapping
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      expect(transform?.rotation).toBeDefined();
    });

    it('should snap rotation to 15-degree increments when Ctrl is held', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('rotation', 'rotation', { x: 200, y: 200 });
      });

      // Move mouse with Ctrl key (snapping enabled)
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 210,
          clientY: 190,
          shiftKey: false,
          ctrlKey: true, // Enable snapping
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      if (transform) {
        // Rotation should be a multiple of 15
        expect(transform.rotation % 15).toBe(0);
      }
    });

    it('should allow free rotation when Ctrl is NOT held', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      act(() => {
        result.current.startTransform('rotation', 'rotation', { x: 200, y: 200 });
      });

      // Move mouse without Ctrl key (no snapping)
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 213,
          clientY: 187,
          shiftKey: false,
          ctrlKey: false, // No snapping
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      const transform = result.current.currentTransform;
      expect(transform).toBeDefined();
      // Rotation can be any value (not necessarily a multiple of 15)
    });
  });

  // ============================================================================
  // Transform Commit Tests (Req 3.8)
  // ============================================================================

  describe('Transform Commit', () => {
    it('should commit transform to store on mouse release', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      // Start any transform
      act(() => {
        result.current.startTransform('position', 'top', { x: 200, y: 200 });
      });

      // Move mouse
      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 250,
          clientY: 250,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      // Release mouse
      act(() => {
        const mouseUpEvent = new MouseEvent('mouseup');
        window.dispatchEvent(mouseUpEvent);
      });

      // Should have called updatePanelTransform
      expect(mockUpdatePanelTransform).toHaveBeenCalledTimes(1);
      expect(mockUpdatePanelTransform).toHaveBeenCalledWith(
        'panel-0-0',
        expect.any(Object)
      );

      // Should reset transform state
      expect(result.current.isTransforming).toBe(false);
      expect(result.current.transformType).toBeNull();
    });

    it('should call onTransformCommit callback when provided', () => {
      const onTransformCommit = vi.fn();

      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel, onTransformCommit })
      );

      act(() => {
        result.current.startTransform('scale', 'bottomRight', { x: 200, y: 200 });
      });

      act(() => {
        const mouseMoveEvent = new MouseEvent('mousemove', {
          clientX: 300,
          clientY: 300,
        });
        window.dispatchEvent(mouseMoveEvent);
      });

      act(() => {
        const mouseUpEvent = new MouseEvent('mouseup');
        window.dispatchEvent(mouseUpEvent);
      });

      // Should have called the callback
      expect(onTransformCommit).toHaveBeenCalledTimes(1);
      expect(onTransformCommit).toHaveBeenCalledWith(expect.any(Object));
    });

    it('should not commit if no transform was started', () => {
      renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      // Just trigger mouse up without starting transform
      act(() => {
        const mouseUpEvent = new MouseEvent('mouseup');
        window.dispatchEvent(mouseUpEvent);
      });

      // Should not call updatePanelTransform
      expect(mockUpdatePanelTransform).not.toHaveBeenCalled();
    });
  });

  // ============================================================================
  // Integration Tests
  // ============================================================================

  describe('Integration', () => {
    it('should handle complete transform workflow', () => {
      const { result } = renderHook(() =>
        useTransformInteraction({ panel: testPanel })
      );

      // 1. Start transform
      act(() => {
        result.current.startTransform('position', 'left', { x: 100, y: 100 });
      });

      expect(result.current.isTransforming).toBe(true);

      // 2. Update transform multiple times
      act(() => {
        const move1 = new MouseEvent('mousemove', { clientX: 120, clientY: 120 });
        window.dispatchEvent(move1);
      });

      act(() => {
        const move2 = new MouseEvent('mousemove', { clientX: 150, clientY: 150 });
        window.dispatchEvent(move2);
      });

      // 3. Commit transform
      act(() => {
        const mouseUp = new MouseEvent('mouseup');
        window.dispatchEvent(mouseUp);
      });

      expect(result.current.isTransforming).toBe(false);
      expect(mockUpdatePanelTransform).toHaveBeenCalledTimes(1);
    });
  });
});

/**
 * useKeyboardShortcuts Hook - Keyboard shortcut system for Grid Editor
 * 
 * Provides keyboard shortcuts for:
 * - Tool selection: V (select), C (crop), R (rotate), S (scale), A (annotate)
 * - Undo/Redo: Ctrl+Z (undo), Ctrl+Shift+Z (redo), Ctrl+Y (redo)
 * - Panel operations: Delete/Backspace (delete), Ctrl+D (duplicate), Ctrl+A (select all)
 * - Navigation: Space (pan), F (focus), [ and ] (cycle panels)
 * - Viewport: Escape (deselect all)
 * 
 * Requirements: 8.1-8.12
 */

import { useEffect, useCallback, useRef } from 'react';
import { useGridStore } from '../../stores/gridEditorStore';
import { useUndoRedoStore } from '../../stores/undoRedoStore';
import { useViewportStore } from '../../stores/viewportStore';

// ============================================================================
// Type Definitions
// ============================================================================

export interface KeyboardShortcutsConfig {
  /**
   * Enable/disable shortcuts globally
   */
  enabled?: boolean;

  /**
   * Callback when a shortcut is triggered
   */
  onShortcut?: (action: string, key: string) => void;

  /**
   * Grid bounds for focus mode
   */
  gridBounds?: { width: number; height: number };

  /**
   * Callback for delete action
   */
  onDelete?: () => void;

  /**
   * Callback for duplicate action
   */
  onDuplicate?: () => void;
}

// ============================================================================
// Keyboard Shortcuts Hook
// ============================================================================

export const useKeyboardShortcuts = (config: KeyboardShortcutsConfig = {}) => {
  const {
    enabled = true,
    onShortcut,
    gridBounds,
    onDelete,
    onDuplicate,
  } = config;

  // ============================================================================
  // Store Hooks
  // ============================================================================

  const setActiveTool = useGridStore((state) => state.setActiveTool);
  const deselectAll = useGridStore((state) => state.deselectAll);
  const selectedPanelIds = useGridStore((state) => state.selectedPanelIds);
  const getAllPanels = useGridStore((state) => state.getAllPanels);
  const selectPanel = useGridStore((state) => state.selectPanel);

  const undo = useUndoRedoStore((state) => state.undo);
  const redo = useUndoRedoStore((state) => state.redo);
  const canUndo = useUndoRedoStore((state) => state.canUndo());
  const canRedo = useUndoRedoStore((state) => state.canRedo());

  const focusPanel = useViewportStore((state) => state.focusPanel);
  const exitFocusMode = useViewportStore((state) => state.exitFocusMode);
  const focusedPanelId = useViewportStore((state) => state.focusedPanelId);

  // ============================================================================
  // State
  // ============================================================================

  const isSpacePressed = useRef(false);

  // ============================================================================
  // Helper Functions
  // ============================================================================

  /**
   * Check if the event target is an input element
   */
  const isInputElement = (target: EventTarget | null): boolean => {
    if (!target || !(target instanceof HTMLElement)) {
      return false;
    }

    const tagName = target.tagName.toLowerCase();
    const isContentEditable = target.isContentEditable;

    return (
      tagName === 'input' ||
      tagName === 'textarea' ||
      tagName === 'select' ||
      isContentEditable
    );
  };

  /**
   * Cycle through panels in sequence
   */
  const cyclePanels = useCallback(
    (direction: 'next' | 'prev') => {
      const panels = getAllPanels();
      if (panels.length === 0) return;

      const currentIndex = selectedPanelIds.length > 0
        ? panels.findIndex((p) => p.id === selectedPanelIds[0])
        : -1;

      let nextIndex: number;
      if (direction === 'next') {
        nextIndex = currentIndex < panels.length - 1 ? currentIndex + 1 : 0;
      } else {
        nextIndex = currentIndex > 0 ? currentIndex - 1 : panels.length - 1;
      }

      const nextPanel = panels[nextIndex];
      if (nextPanel) {
        selectPanel(nextPanel.id, false);
        onShortcut?.('cycle_panel', direction);
      }
    },
    [getAllPanels, selectedPanelIds, selectPanel, onShortcut]
  );

  /**
   * Select all panels
   */
  const selectAllPanels = useCallback(() => {
    const panels = getAllPanels();
    panels.forEach((panel, index) => {
      selectPanel(panel.id, index > 0);
    });
    onShortcut?.('select_all', 'Ctrl+A');
  }, [getAllPanels, selectPanel, onShortcut]);

  /**
   * Handle focus mode toggle
   */
  const handleFocusToggle = useCallback(() => {
    if (focusedPanelId) {
      exitFocusMode();
      onShortcut?.('exit_focus', 'F');
    } else if (selectedPanelIds.length === 1 && gridBounds) {
      focusPanel(selectedPanelIds[0], gridBounds);
      onShortcut?.('enter_focus', 'F');
    }
  }, [focusedPanelId, selectedPanelIds, gridBounds, focusPanel, exitFocusMode, onShortcut]);

  // ============================================================================
  // Keyboard Event Handlers
  // ============================================================================

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled) return;

      // Don't trigger shortcuts when typing in input fields
      if (isInputElement(event.target)) return;

      const { key, ctrlKey, metaKey, shiftKey } = event;
      const isModifier = ctrlKey || metaKey;

      // ============================================================================
      // Tool Selection Shortcuts (Requirements 8.1-8.4)
      // ============================================================================

      if (!isModifier && !shiftKey) {
        switch (key.toLowerCase()) {
          case 'v':
            setActiveTool('select');
            onShortcut?.('tool_select', 'V');
            event.preventDefault();
            return;

          case 'c':
            setActiveTool('crop');
            onShortcut?.('tool_crop', 'C');
            event.preventDefault();
            return;

          case 'r':
            setActiveTool('rotate');
            onShortcut?.('tool_rotate', 'R');
            event.preventDefault();
            return;

          case 's':
            setActiveTool('scale');
            onShortcut?.('tool_scale', 'S');
            event.preventDefault();
            return;

          case 'a':
            setActiveTool('annotate');
            onShortcut?.('tool_annotate', 'A');
            event.preventDefault();
            return;
        }
      }

      // ============================================================================
      // Undo/Redo Shortcuts (Requirements 8.5, 8.6)
      // ============================================================================

      if (isModifier) {
        // Ctrl+Z or Cmd+Z - Undo
        if (key.toLowerCase() === 'z' && !shiftKey) {
          if (canUndo) {
            undo();
            onShortcut?.('undo', 'Ctrl+Z');
          }
          event.preventDefault();
          return;
        }

        // Ctrl+Shift+Z or Cmd+Shift+Z - Redo
        if (key.toLowerCase() === 'z' && shiftKey) {
          if (canRedo) {
            redo();
            onShortcut?.('redo', 'Ctrl+Shift+Z');
          }
          event.preventDefault();
          return;
        }

        // Ctrl+Y or Cmd+Y - Redo (alternative)
        if (key.toLowerCase() === 'y') {
          if (canRedo) {
            redo();
            onShortcut?.('redo', 'Ctrl+Y');
          }
          event.preventDefault();
          return;
        }

        // Ctrl+A or Cmd+A - Select All (Requirement 8.9)
        if (key.toLowerCase() === 'a') {
          selectAllPanels();
          event.preventDefault();
          return;
        }

        // Ctrl+D or Cmd+D - Duplicate (Requirement 8.8)
        if (key.toLowerCase() === 'd') {
          onDuplicate?.();
          onShortcut?.('duplicate', 'Ctrl+D');
          event.preventDefault();
          return;
        }
      }

      // ============================================================================
      // Delete Shortcut (Requirement 8.7)
      // ============================================================================

      if (key === 'Delete' || key === 'Backspace') {
        if (selectedPanelIds.length > 0) {
          onDelete?.();
          onShortcut?.('delete', key);
          event.preventDefault();
        }
        return;
      }

      // ============================================================================
      // Navigation Shortcuts (Requirements 8.10, 8.11, 8.12)
      // ============================================================================

      // Space - Pan tool (temporary activation)
      if (key === ' ') {
        if (!isSpacePressed.current) {
          isSpacePressed.current = true;
          setActiveTool('pan');
          onShortcut?.('pan_start', 'Space');
        }
        event.preventDefault();
        return;
      }

      // F - Focus mode toggle (Requirement 8.11)
      if (key.toLowerCase() === 'f' && !isModifier) {
        handleFocusToggle();
        event.preventDefault();
        return;
      }

      // [ - Cycle to previous panel (Requirement 8.12)
      if (key === '[' && !isModifier) {
        cyclePanels('prev');
        event.preventDefault();
        return;
      }

      // ] - Cycle to next panel (Requirement 8.12)
      if (key === ']' && !isModifier) {
        cyclePanels('next');
        event.preventDefault();
        return;
      }

      // Escape - Deselect all (Requirement 2.4)
      if (key === 'Escape') {
        if (focusedPanelId) {
          exitFocusMode();
          onShortcut?.('exit_focus', 'Escape');
        } else {
          deselectAll();
          onShortcut?.('deselect_all', 'Escape');
        }
        event.preventDefault();
        return;
      }
    },
    [
      enabled,
      setActiveTool,
      undo,
      redo,
      canUndo,
      canRedo,
      deselectAll,
      selectedPanelIds,
      focusedPanelId,
      exitFocusMode,
      onShortcut,
      onDelete,
      onDuplicate,
      selectAllPanels,
      cyclePanels,
      handleFocusToggle,
    ]
  );

  const handleKeyUp = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled) return;

      // Space - Release pan tool
      if (event.key === ' ') {
        if (isSpacePressed.current) {
          isSpacePressed.current = false;
          setActiveTool('select');
          onShortcut?.('pan_end', 'Space');
        }
        event.preventDefault();
      }
    },
    [enabled, setActiveTool, onShortcut]
  );

  // ============================================================================
  // Effect - Register Event Listeners
  // ============================================================================

  useEffect(() => {
    if (!enabled) return;

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [enabled, handleKeyDown, handleKeyUp]);

  // ============================================================================
  // Return API
  // ============================================================================

  return {
    /**
     * Check if Space key is currently pressed
     */
    isSpacePressed: isSpacePressed.current,

    /**
     * Manually trigger a shortcut action
     */
    triggerShortcut: (action: string) => {
      switch (action) {
        case 'undo':
          if (canUndo) undo();
          break;
        case 'redo':
          if (canRedo) redo();
          break;
        case 'select_all':
          selectAllPanels();
          break;
        case 'deselect_all':
          deselectAll();
          break;
        case 'focus_toggle':
          handleFocusToggle();
          break;
        case 'cycle_next':
          cyclePanels('next');
          break;
        case 'cycle_prev':
          cyclePanels('prev');
          break;
        default:
          console.warn(`Unknown shortcut action: ${action}`);
      }
    },
  };
};

// ============================================================================
// Export
// ============================================================================

export default useKeyboardShortcuts;

/**
 * useTouchInteraction Hook
 * 
 * Provides touch interaction support for tablets and mobile devices:
 * - Touch-based pan and zoom (pinch-to-zoom)
 * - Touch-based transform operations
 * - Long-press for context menus
 * - Swipe gestures
 */

import { useEffect, useRef, useCallback } from 'react';
import { useViewportStore } from '../../stores/viewportStore';

interface TouchPoint {
  x: number;
  y: number;
}

interface TouchInteractionOptions {
  enablePinchZoom?: boolean;
  enablePan?: boolean;
  enableLongPress?: boolean;
  longPressDuration?: number;
  onLongPress?: (point: TouchPoint) => void;
  onSwipe?: (direction: 'left' | 'right' | 'up' | 'down') => void;
}

/**
 * Calculate distance between two touch points
 */
function getTouchDistance(touch1: Touch, touch2: Touch): number {
  const dx = touch1.clientX - touch2.clientX;
  const dy = touch1.clientY - touch2.clientY;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Calculate center point between two touches
 */
function getTouchCenter(touch1: Touch, touch2: Touch): TouchPoint {
  return {
    x: (touch1.clientX + touch2.clientX) / 2,
    y: (touch1.clientY + touch2.clientY) / 2,
  };
}

/**
 * Hook for touch interactions
 */
export function useTouchInteraction(
  elementRef: React.RefObject<HTMLElement | null>,
  options: TouchInteractionOptions = {}
) {
  const {
    enablePinchZoom = true,
    enablePan = true,
    enableLongPress = true,
    longPressDuration = 500,
    onLongPress,
    onSwipe,
  } = options;

  const { setZoom, setPan, zoom, pan } = useViewportStore();

  const touchStateRef = useRef({
    initialDistance: 0,
    initialZoom: 1,
    initialPan: { x: 0, y: 0 },
    lastTouchPoint: null as TouchPoint | null,
    longPressTimer: null as ReturnType<typeof setTimeout> | null,
    swipeStartPoint: null as TouchPoint | null,
    swipeStartTime: 0,
  });

  /**
   * Handle touch start
   */
  const handleTouchStart = useCallback(
    (e: TouchEvent) => {
      const touches = e.touches;

      if (touches.length === 1) {
        // Single touch - potential pan or long press
        const touch = touches[0];
        const point = { x: touch.clientX, y: touch.clientY };

        touchStateRef.current.lastTouchPoint = point;
        touchStateRef.current.swipeStartPoint = point;
        touchStateRef.current.swipeStartTime = Date.now();

        // Start long press timer
        if (enableLongPress && onLongPress) {
          touchStateRef.current.longPressTimer = setTimeout(() => {
            onLongPress(point);
          }, longPressDuration);
        }
      } else if (touches.length === 2 && enablePinchZoom) {
        // Two touches - pinch zoom
        touchStateRef.current.initialDistance = getTouchDistance(touches[0], touches[1]);
        touchStateRef.current.initialZoom = zoom;

        // Cancel long press
        if (touchStateRef.current.longPressTimer) {
          clearTimeout(touchStateRef.current.longPressTimer);
          touchStateRef.current.longPressTimer = null;
        }
      }
    },
    [enableLongPress, enablePinchZoom, longPressDuration, onLongPress, zoom]
  );

  /**
   * Handle touch move
   */
  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      e.preventDefault();
      const touches = e.touches;

      // Cancel long press on move
      if (touchStateRef.current.longPressTimer) {
        clearTimeout(touchStateRef.current.longPressTimer);
        touchStateRef.current.longPressTimer = null;
      }

      if (touches.length === 1 && enablePan) {
        // Single touch - pan
        const touch = touches[0];
        const currentPoint = { x: touch.clientX, y: touch.clientY };
        const lastPoint = touchStateRef.current.lastTouchPoint;

        if (lastPoint) {
          const dx = currentPoint.x - lastPoint.x;
          const dy = currentPoint.y - lastPoint.y;

          setPan({
            x: pan.x + dx,
            y: pan.y + dy,
          });
        }

        touchStateRef.current.lastTouchPoint = currentPoint;
      } else if (touches.length === 2 && enablePinchZoom) {
        // Two touches - pinch zoom
        const currentDistance = getTouchDistance(touches[0], touches[1]);
        const initialDistance = touchStateRef.current.initialDistance;

        if (initialDistance > 0) {
          const scale = currentDistance / initialDistance;
          const newZoom = touchStateRef.current.initialZoom * scale;

          // Clamp zoom between 0.1 and 10
          const clampedZoom = Math.max(0.1, Math.min(10, newZoom));

          // Get center point for zoom
          const center = getTouchCenter(touches[0], touches[1]);

          // Calculate new pan to keep center point stable
          const zoomRatio = clampedZoom / zoom;
          const newPan = {
            x: center.x - (center.x - pan.x) * zoomRatio,
            y: center.y - (center.y - pan.y) * zoomRatio,
          };

          setZoom(clampedZoom);
          setPan(newPan);
        }
      }
    },
    [enablePan, enablePinchZoom, pan, zoom, setPan, setZoom]
  );

  /**
   * Handle touch end
   */
  const handleTouchEnd = useCallback(
    (e: TouchEvent) => {
      // Cancel long press
      if (touchStateRef.current.longPressTimer) {
        clearTimeout(touchStateRef.current.longPressTimer);
        touchStateRef.current.longPressTimer = null;
      }

      // Detect swipe gesture
      if (onSwipe && touchStateRef.current.swipeStartPoint) {
        const touch = e.changedTouches[0];
        const endPoint = { x: touch.clientX, y: touch.clientY };
        const startPoint = touchStateRef.current.swipeStartPoint;
        const duration = Date.now() - touchStateRef.current.swipeStartTime;

        const dx = endPoint.x - startPoint.x;
        const dy = endPoint.y - startPoint.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        // Swipe detection: minimum distance 50px, maximum duration 300ms
        if (distance > 50 && duration < 300) {
          const angle = Math.atan2(dy, dx) * (180 / Math.PI);

          if (angle >= -45 && angle < 45) {
            onSwipe('right');
          } else if (angle >= 45 && angle < 135) {
            onSwipe('down');
          } else if (angle >= -135 && angle < -45) {
            onSwipe('up');
          } else {
            onSwipe('left');
          }
        }
      }

      // Reset state
      touchStateRef.current.lastTouchPoint = null;
      touchStateRef.current.swipeStartPoint = null;
      touchStateRef.current.initialDistance = 0;
    },
    [onSwipe]
  );

  /**
   * Set up touch event listeners
   */
  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    element.addEventListener('touchstart', handleTouchStart, { passive: false });
    element.addEventListener('touchmove', handleTouchMove, { passive: false });
    element.addEventListener('touchend', handleTouchEnd, { passive: false });

    return () => {
      element.removeEventListener('touchstart', handleTouchStart);
      element.removeEventListener('touchmove', handleTouchMove);
      element.removeEventListener('touchend', handleTouchEnd);

      // Clean up timer
      if (touchStateRef.current.longPressTimer) {
        clearTimeout(touchStateRef.current.longPressTimer);
      }
    };
  }, [elementRef, handleTouchStart, handleTouchMove, handleTouchEnd]);

  return {
    // Expose touch state if needed
    isTouchDevice: 'ontouchstart' in window,
  };
}

export default useTouchInteraction;

/**
 * useTransformInteraction Hook - Handle transform interactions
 * 
 * Manages:
 * - Position drag with delta calculation
 * - Scale drag with proportional/non-proportional modes (Shift)
 * - Rotation drag with angle calculation and snapping (Ctrl)
 * - Transform commit on mouse release
 * 
 * Requirements: 3.2, 3.3, 3.4, 3.5, 3.6, 3.8
 */

import { useState, useCallback, useEffect, useRef } from 'react';
import { useGridStore } from '../../stores/gridEditorStore';
import { useViewportStore } from '../../stores/viewportStore';
import type { Transform, Point, Panel } from '../../stores/gridEditorStore';

// ============================================================================
// Type Definitions
// ============================================================================

export type TransformType = 'position' | 'scale' | 'rotation';

export interface TransformInteractionState {
  isTransforming: boolean;
  transformType: TransformType | null;
  handle: string | null;
  startTransform: Transform | null;
  startMousePos: Point | null;
  currentTransform: Transform | null;
}

export interface UseTransformInteractionOptions {
  panel: Panel;
  onTransformCommit?: (transform: Transform) => void;
}

// ============================================================================
// Constants
// ============================================================================

const ROTATION_SNAP_ANGLE = 15; // degrees
const MIN_SCALE = 0.1;
const MAX_SCALE = 10.0;

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Calculate angle between two points in degrees
 */
const calculateAngle = (center: Point, point: Point): number => {
  const dx = point.x - center.x;
  const dy = point.y - center.y;
  return (Math.atan2(dy, dx) * 180) / Math.PI;
};

/**
 * Snap angle to nearest increment
 */
const snapAngle = (angle: number, snapIncrement: number): number => {
  return Math.round(angle / snapIncrement) * snapIncrement;
};

/**
 * Clamp value between min and max
 */
const clamp = (value: number, min: number, max: number): number => {
  return Math.min(Math.max(value, min), max);
};

/**
 * Calculate distance between two points (reserved for future use)
 */
// const distance = (p1: Point, p2: Point): number => {
//   const dx = p2.x - p1.x;
//   const dy = p2.y - p1.y;
//   return Math.sqrt(dx * dx + dy * dy);
// };

// ============================================================================
// Hook
// ============================================================================

export const useTransformInteraction = ({
  panel,
  onTransformCommit,
}: UseTransformInteractionOptions) => {
  const updatePanelTransform = useGridStore((state) => state.updatePanelTransform);
  const screenToCanvas = useViewportStore((state) => state.screenToCanvas);

  const [state, setState] = useState<TransformInteractionState>({
    isTransforming: false,
    transformType: null,
    handle: null,
    startTransform: null,
    startMousePos: null,
    currentTransform: null,
  });

  const stateRef = useRef(state);
  stateRef.current = state;

  // ============================================================================
  // Transform Start
  // ============================================================================

  const startTransform = useCallback(
    (type: TransformType, handle: string, mousePos: Point) => {
      setState({
        isTransforming: true,
        transformType: type,
        handle,
        startTransform: { ...panel.transform },
        startMousePos: screenToCanvas(mousePos),
        currentTransform: { ...panel.transform },
      });
    },
    [panel.transform, screenToCanvas]
  );

  // ============================================================================
  // Transform Update
  // ============================================================================

  const updateTransform = useCallback(
    (mousePos: Point, shiftKey: boolean, ctrlKey: boolean) => {
      const { transformType, handle, startTransform, startMousePos } = stateRef.current;

      if (!transformType || !startTransform || !startMousePos) return;

      const currentMousePos = screenToCanvas(mousePos);
      const delta: Point = {
        x: currentMousePos.x - startMousePos.x,
        y: currentMousePos.y - startMousePos.y,
      };

      let newTransform: Transform = { ...startTransform };

      switch (transformType) {
        case 'position':
          newTransform = handlePositionDrag(startTransform, delta);
          break;

        case 'scale':
          newTransform = handleScaleDrag(
            startTransform,
            delta,
            handle!,
            shiftKey // proportional mode
          );
          break;

        case 'rotation':
          newTransform = handleRotationDrag(
            startTransform,
            currentMousePos,
            panel,
            ctrlKey // snap mode
          );
          break;
      }

      setState((prev) => ({
        ...prev,
        currentTransform: newTransform,
      }));
    },
    [panel, screenToCanvas]
  );

  // ============================================================================
  // Transform End
  // ============================================================================

  const endTransform = useCallback(() => {
    const { currentTransform } = stateRef.current;

    if (currentTransform) {
      // Commit transform to store
      updatePanelTransform(panel.id, currentTransform);

      // Call optional callback
      if (onTransformCommit) {
        onTransformCommit(currentTransform);
      }
    }

    setState({
      isTransforming: false,
      transformType: null,
      handle: null,
      startTransform: null,
      startMousePos: null,
      currentTransform: null,
    });
  }, [panel.id, updatePanelTransform, onTransformCommit]);

  // ============================================================================
  // Position Transform Handler
  // ============================================================================

  const handlePositionDrag = (
    startTransform: Transform,
    delta: Point
  ): Transform => {
    return {
      ...startTransform,
      position: {
        x: startTransform.position.x + delta.x,
        y: startTransform.position.y + delta.y,
      },
    };
  };

  // ============================================================================
  // Scale Transform Handler
  // ============================================================================

  const handleScaleDrag = (
    startTransform: Transform,
    delta: Point,
    handle: string,
    proportional: boolean
  ): Transform => {
    // Calculate scale factor based on handle and delta
    let scaleX = startTransform.scale.x;
    let scaleY = startTransform.scale.y;

    // Determine scale direction based on handle
    const scaleFactor = 0.01; // Sensitivity

    switch (handle) {
      case 'topLeft':
        scaleX = clamp(
          startTransform.scale.x - delta.x * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        scaleY = clamp(
          startTransform.scale.y - delta.y * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        break;

      case 'topRight':
        scaleX = clamp(
          startTransform.scale.x + delta.x * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        scaleY = clamp(
          startTransform.scale.y - delta.y * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        break;

      case 'bottomLeft':
        scaleX = clamp(
          startTransform.scale.x - delta.x * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        scaleY = clamp(
          startTransform.scale.y + delta.y * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        break;

      case 'bottomRight':
        scaleX = clamp(
          startTransform.scale.x + delta.x * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        scaleY = clamp(
          startTransform.scale.y + delta.y * scaleFactor,
          MIN_SCALE,
          MAX_SCALE
        );
        break;
    }

    // Apply proportional scaling if Shift is NOT held
    // Requirements: 3.3, 3.4
    if (!proportional) {
      // Maintain aspect ratio
      const aspectRatio = startTransform.scale.x / startTransform.scale.y;
      const avgScale = (scaleX + scaleY) / 2;
      scaleX = avgScale;
      scaleY = avgScale / aspectRatio;
    }

    return {
      ...startTransform,
      scale: {
        x: scaleX,
        y: scaleY,
      },
    };
  };

  // ============================================================================
  // Rotation Transform Handler
  // ============================================================================

  const handleRotationDrag = (
    startTransform: Transform,
    mousePos: Point,
    panel: Panel,
    snap: boolean
  ): Transform => {
    // Calculate panel center in canvas space
    const panelCenter: Point = {
      x: panel.transform.position.x,
      y: panel.transform.position.y,
    };

    // Calculate angle from center to mouse
    let angle = calculateAngle(panelCenter, mousePos);

    // Apply snapping if Ctrl is held
    // Requirements: 3.6
    if (snap) {
      angle = snapAngle(angle, ROTATION_SNAP_ANGLE);
    }

    return {
      ...startTransform,
      rotation: angle,
    };
  };

  // ============================================================================
  // Mouse Event Handlers
  // ============================================================================

  useEffect(() => {
    if (!state.isTransforming) return;

    const handleMouseMove = (event: MouseEvent) => {
      updateTransform(
        { x: event.clientX, y: event.clientY },
        event.shiftKey,
        event.ctrlKey
      );
    };

    const handleMouseUp = () => {
      endTransform();
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [state.isTransforming, updateTransform, endTransform]);

  // ============================================================================
  // Return
  // ============================================================================

  return {
    isTransforming: state.isTransforming,
    transformType: state.transformType,
    currentTransform: state.currentTransform,
    startTransform,
  };
};

import React, { useState } from 'react';
import styles from './ImageHoverOverlay.module.css';

interface RegenerateOptions {
  prompt?: string;
  strength?: number;
  seed?: number;
}

interface ImageHoverOverlayProps {
  imageUrl: string;
  imageId: string;
  onRegenerate: (imageId: string, options: RegenerateOptions) => Promise<void>;
  onQuickEdit: (imageId: string) => void;
  isGenerating?: boolean;
}

export const ImageHoverOverlay: React.FC<ImageHoverOverlayProps> = ({
  imageUrl,
  imageId,
  onRegenerate,
  onQuickEdit,
  isGenerating = false
}) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showQuickEdit, setShowQuickEdit] = useState(false);

  return (
    <div className={styles.overlayContainer}>
      <img src={imageUrl} alt={imageId} className={styles.image} />

      <div className={styles.hoverOverlay}>
        <div className={styles.actionButtons}>
          <button
            className={styles.actionBtn}
            onClick={() => setShowMenu(true)}
            disabled={isGenerating}
          >
            <span className={styles.icon}>O</span>
            Regenerer
          </button>

          <button
            className={styles.actionBtn}
            onClick={() => setShowQuickEdit(true)}
            disabled={isGenerating}
          >
            <span className={styles.icon}>E</span>
            Edit Rapide
          </button>
        </div>
      </div>

      {showMenu && (
        <RegenerateDialog
          imageId={imageId}
          onClose={() => setShowMenu(false)}
          onConfirm={async (options) => {
            await onRegenerate(imageId, options);
            setShowMenu(false);
          }}
        />
      )}

      {showQuickEdit && (
        <QuickEditDialog
          imageId={imageId}
          onClose={() => setShowQuickEdit(false)}
          onSave={onQuickEdit}
        />
      )}
    </div>
  );
};

interface RegenerateDialogProps {
  imageId: string;
  onClose: () => void;
  onConfirm: (options: RegenerateOptions) => Promise<void>;
}

const RegenerateDialog: React.FC<RegenerateDialogProps> = ({
  imageId,
  onClose,
  onConfirm
}) => {
  const [prompt, setPrompt] = useState('');
  const [strength, setStrength] = useState(0.7);
  const [workflow, setWorkflow] = useState('flux');

  const workflows = [
    { id: 'flux', name: 'Flux.1 Dev' },
    { id: 'sdxl', name: 'SDXL' },
    { id: 'qwen', name: 'Qwen 2.5' }
  ];

  return (
    <div className={styles.dialogBackdrop} onClick={onClose}>
      <div className={styles.dialog} onClick={e => e.stopPropagation()}>
        <h3>Regenerer l'Image</h3>

        <div className={styles.formGroup}>
          <label>Workflow</label>
          <div className={styles.workflowGrid}>
            {workflows.map(w => (
              <button
                key={w.id}
                className={`${styles.workflowBtn} ${workflow === w.id ? styles.active : ''}`}
                onClick={() => setWorkflow(w.id)}
              >
                {w.name}
              </button>
            ))}
          </div>
        </div>

        <div className={styles.formGroup}>
          <label>Prompt</label>
          <textarea
            value={prompt}
            onChange={e => setPrompt(e.target.value)}
            placeholder="Decrivez ce que vous voulez..."
            rows={3}
          />
        </div>

        <div className={styles.formGroup}>
          <label>Force: {strength.toFixed(2)}</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.05"
            value={strength}
            onChange={e => setStrength(parseFloat(e.target.value))}
          />
        </div>

        <div className={styles.dialogActions}>
          <button className={styles.cancelBtn} onClick={onClose}>Annuler</button>
          <button
            className={styles.confirmBtn}
            onClick={() => onConfirm({ prompt, strength })}
          >
            Generer
          </button>
        </div>
      </div>
    </div>
  );
};

interface QuickEditDialogProps {
  imageId: string;
  onClose: () => void;
  onSave: (imageId: string) => void;
}

const QuickEditDialog: React.FC<QuickEditDialogProps> = ({
  imageId,
  onClose,
  onSave
}) => {
  const [brightness, setBrightness] = useState(100);
  const [contrast, setContrast] = useState(100);
  const [saturation, setSaturation] = useState(100);

  return (
    <div className={styles.dialogBackdrop} onClick={onClose}>
      <div className={styles.quickEditDialog} onClick={e => e.stopPropagation()}>
        <h3>Edition Rapide</h3>

        <div className={styles.presetsRow}>
          <button className={styles.presetBtn} onClick={() => { setBrightness(110); setContrast(105); }}>Clair</button>
          <button className={styles.presetBtn} onClick={() => { setBrightness(90); setContrast(110); }}>Sombre</button>
          <button className={styles.presetBtn} onClick={() => { setBrightness(100); setContrast(115); setSaturation(130); }}>Vibrant</button>
          <button className={styles.presetBtn} onClick={() => { setSaturation(0); }}>NB</button>
        </div>

        <div className={styles.sliderGroup}>
          <label>Lumi: {brightness}%</label>
          <input
            type="range"
            min="0"
            max="200"
            value={brightness}
            onChange={e => setBrightness(parseInt(e.target.value))}
          />
        </div>

        <div className={styles.sliderGroup}>
          <label>Contrast: {contrast}%</label>
          <input
            type="range"
            min="0"
            max="200"
            value={contrast}
            onChange={e => setContrast(parseInt(e.target.value))}
          />
        </div>

        <div className={styles.dialogActions}>
          <button className={styles.cancelBtn} onClick={onClose}>Annuler</button>
          <button className={styles.resetBtn} onClick={() => { setBrightness(100); setContrast(100); setSaturation(100); }}>Reset</button>
          <button className={styles.confirmBtn} onClick={() => onSave(imageId)}>Appliquer</button>
        </div>
      </div>
    </div>
  );
};

export default ImageHoverOverlay;

