  path: string;
  isDirectory: boolean;
  size: number;
  modified: string;
}

interface FolderNavigationModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelectProject: (projectPath: string) => Promise<void>;
  initialPath?: string;
}

interface TreeNode {
  item: DirectoryItem;
  children?: TreeNode[];
  expanded?: boolean;
  loading?: boolean;
}

// ============================================================================
// Folder Navigation Modal Component
// ============================================================================

/**
 * Folder Navigation Modal Component
 * 
 * **DEMO MODE ONLY**: This component provides a custom folder navigation
 * interface for web browser environments where native OS dialogs are unavailable.
 * 
 * **DO NOT USE IN ELECTRON MODE**: When running as a desktop application,
 * the native OS file dialog (Windows File Explorer, macOS Finder, etc.) 
 * should ALWAYS be used via window.electronAPI.project.selectForOpen().
 * 
 * The native dialog provides:
 * - Familiar user experience with OS-native controls
 * - Better performance and responsiveness
 * - Access to all file system features (network drives, shortcuts, etc.)
 * - Proper keyboard navigation and accessibility
 * - Integration with OS-level file management features
 * 
 * This custom modal should only be rendered when window.electronAPI is undefined.
 * It has been incorrectly reintroduced 3 times in place of the native dialog,
 * causing poor user experience. The conditional rendering in LandingPageWithHooks.tsx
 * ensures this component is excluded from the React component tree in Electron mode.
 * 
 * @see LandingPageWithHooks.tsx for conditional rendering implementation
 * @see useLandingPage.ts for native dialog usage in Electron mode
 * 
 * @param {FolderNavigationModalProps} props - Component props
 * @param {boolean} props.open - Whether the modal is open
 * @param {function} props.onOpenChange - Callback when modal open state changes
 * @param {function} props.onSelectProject - Callback when a project is selected
 * @param {string} [props.initialPath] - Optional initial directory path
 */
export function FolderNavigationModal({
  open,
  onOpenChange,
  onSelectProject,
  initialPath,
}: FolderNavigationModalProps) {
  const [currentPath, setCurrentPath] = useState(initialPath || '');
  const [searchQuery, setSearchQuery] = useState('');
  const [treeData, setTreeData] = useState<TreeNode[]>([]);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState<any>(null);
  const [isOpening, setIsOpening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize with default path
  useEffect(() => {
    if (open && !currentPath) {
      const defaultPath = initialPath || 'C:/Users/Documents'; // Default to Documents folder
      setCurrentPath(defaultPath);
      if (defaultPath) {
        loadDirectory(defaultPath);
      }
    }
  }, [open, initialPath]);

  // Load directory contents
  const loadDirectory = useCallback(async (path: string, node?: TreeNode) => {
    if (node) {
      node.loading = true;
      setTreeData(prev => [...prev]); // Trigger re-render
    }

    try {
      let contents: DirectoryItem[] = [];

      if (window.electronAPI) {
        contents = await (window.electronAPI.project as any).listDirectory(path);
      } else {
        // Demo mode - simulate directory listing
        contents = [
          { name: 'Documents', path: 'C:/Users/Documents', isDirectory: true, size: 0, modified: new Date().toISOString() },
          { name: 'Downloads', path: 'C:/Users/Downloads', isDirectory: true, size: 0, modified: new Date().toISOString() },
          { name: 'Desktop', path: 'C:/Users/Desktop', isDirectory: true, size: 0, modified: new Date().toISOString() },
        ];
      }

      const children = contents
        .filter(item => item.isDirectory)
        .map(item => ({ item, expanded: false, loading: false }));

      if (node) {
        node.children = children;
        node.loading = false;
      } else {
        setTreeData(children);
      }
      setTreeData(prev => [...prev]); // Trigger re-render
    } catch (err) {
      console.error('Failed to load directory:', err);
      setError('Failed to load directory contents');
      if (node) {
        node.loading = false;
        setTreeData(prev => [...prev]);
      }
    }
  }, []);

  // Toggle directory expansion
  const toggleDirectory = async (node: TreeNode) => {
    if (node.expanded) {
      node.expanded = false;
      setTreeData(prev => [...prev]);
    } else {
      node.expanded = true;
      if (!node.children) {
        await loadDirectory(node.item.path, node);
      } else {
        setTreeData(prev => [...prev]);
      }
    }
  };

  // Handle path selection
  const handleSelectPath = async (path: string) => {
    setSelectedPath(path);
    setError(null);

    // Validate project
    await validateProject(path);
  };

  // Validate project
  const validateProject = async (path: string) => {
    setIsValidating(true);
    setValidationResult(null);

    try {
      if (window.electronAPI) {
        const result = await window.electronAPI.project.validate(path);
        setValidationResult(result);
      } else {
        // Demo validation
        await new Promise(resolve => setTimeout(resolve, 500));
        setValidationResult({
          isValid: true,
          errors: [],
          warnings: [{ type: 'info', message: 'Demo mode: validation skipped' }],
        });
      }
    } catch (err) {
      console.error('Validation failed:', err);
      setValidationResult({
        isValid: false,
        errors: [{ type: 'error', message: err instanceof Error ? err.message : 'Validation failed' }],
        warnings: [],
      });
    } finally {
      setIsValidating(false);
    }
  };

  // Handle open project
  const handleOpenProject = async () => {
    if (!selectedPath || !validationResult?.isValid) return;

    setIsOpening(true);
    setError(null);

    try {
      await onSelectProject(selectedPath);
      onOpenChange(false);
      // Reset state
      setSelectedPath(null);
      setValidationResult(null);
      setSearchQuery('');
    } catch (err) {
      console.error('Failed to open project:', err);
      setError(err instanceof Error ? err.message : 'Failed to open project');
    } finally {
      setIsOpening(false);
    }
  };

  // Render tree node
  const renderTreeNode = (node: TreeNode, level = 0) => (
    <div key={node.item.path}>
      <div
        className={`flex items-center gap-2 px-2 py-1 hover:bg-gray-700 cursor-pointer rounded ${
          selectedPath === node.item.path ? 'bg-blue-600/20 border border-blue-500' : ''
        }`}
        style={{ paddingLeft: `${level * 20 + 8}px` }}
        onClick={() => handleSelectPath(node.item.path)}
      >
        {node.item.isDirectory ? (
          <>
            {node.expanded ? (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronRight className="w-4 h-4 text-gray-400" />
            )}
            <Folder className="w-4 h-4 text-blue-400" />
          </>
        ) : (
          <>
            <div className="w-4" /> {/* Spacer */}
            <File className="w-4 h-4 text-gray-400" />
          </>
        )}
        <span className="text-sm text-white truncate">{node.item.name}</span>
        {node.loading && <Loader2 className="w-4 h-4 animate-spin text-gray-400 ml-auto" />}
      </div>
      {node.expanded && node.children && (
        <div>
          {node.children.map(child => renderTreeNode(child, level + 1))}
        </div>
      )}
    </div>
  );

  // Filter tree data based on search
  const filteredTreeData = treeData.filter(node =>
    node.item.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[80vh] bg-gray-900 border-gray-700 text-white flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-xl">
            <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-purple-500/20">
              <FolderOpen className="w-5 h-5 text-purple-400" />
            </div>
            Open Existing Project
          </DialogTitle>
          <DialogDescription className="text-gray-400">
            Navigate through your folders to find and open a StoryCore project.
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-4 flex-1 min-h-0">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              placeholder="Search folders..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 bg-gray-800 border-gray-700 text-white placeholder:text-gray-500"
            />
          </div>

          {/* Error Display */}
          {error && (
            <Alert variant="destructive" className="bg-red-900/20 border-red-800 text-red-400">
              <AlertCircle className="h-4 w-4" />
              <p>{error}</p>
            </Alert>
          )}

          {/* Directory Tree */}
          <div className="flex-1 min-h-0">
            <ScrollArea className="h-full">
              <div className="space-y-1">
                {filteredTreeData.length > 0 ? (
                  filteredTreeData.map(node => renderTreeNode(node))
                ) : (
                  <div className="text-center py-8 text-gray-400">
                    {searchQuery ? 'No folders match your search' : 'No folders to display'}
                  </div>
                )}
              </div>
            </ScrollArea>
          </div>

          {/* Selected Path Display */}
          {selectedPath && (
            <div className="p-3 rounded-lg bg-gray-800 border border-gray-700">
              <div className="flex items-center gap-2 mb-2">
                <Home className="w-4 h-4 text-gray-400" />
                <span className="text-sm font-medium text-gray-200">Selected:</span>
              </div>
              <p className="text-sm text-gray-300 font-mono break-all">{selectedPath}</p>
            </div>
          )}

          {/* Validation Results */}
          {isValidating && (
            <div className="flex items-center justify-center py-4">
              <div className="flex items-center gap-2 text-gray-400">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-sm">Validating project...</span>
              </div>
            </div>
          )}

          {validationResult && !isValidating && (
            <div className="space-y-2">
              {validationResult.isValid ? (
                <div className="rounded-lg bg-green-900/20 border border-green-800 p-3">
                  <div className="flex items-center gap-2">
                    <CheckCircle className="w-4 h-4 text-green-400" />
                    <span className="text-sm text-green-300">Valid StoryCore project</span>
                  </div>
                </div>
              ) : (
                <div className="rounded-lg bg-red-900/20 border border-red-800 p-3">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <span className="text-sm font-medium text-red-400">Invalid project</span>
                      <ul className="mt-1 space-y-1">
                        {validationResult.errors?.map((error: unknown, index: number) => (
                          <li key={index} className="text-xs text-red-300">• {error.message}</li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isOpening || isValidating}
            className="bg-gray-800 border-gray-700 text-white hover:bg-gray-700"
          >
            <X className="w-4 h-4 mr-2" />
            Cancel
          </Button>
          <Button
            onClick={handleOpenProject}
            disabled={!selectedPath || !validationResult?.isValid || isOpening || isValidating}
            className="bg-purple-600 hover:bg-purple-700 text-white"
          >
            {isOpening ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Opening...
              </>
            ) : (
              <>
                <FolderOpen className="mr-2 h-4 w-4" />
                Open Project
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { memo } from 'react';
import { Check, Globe } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { type LanguageCode } from '@/utils/llmConfigStorage';

// ============================================================================
// Types
// ============================================================================

export type { LanguageCode };

export interface LanguageOption {
  code: LanguageCode;
  name: string;
  nativeName: string;
  flag: string;
}

export interface LanguageSelectorProps {
  currentLanguage: LanguageCode;
  onLanguageChange: (language: LanguageCode) => void;
  position?: 'top' | 'bottom';
}

// ============================================================================
// Constants
// ============================================================================

export const SUPPORTED_LANGUAGES: LanguageOption[] = [
  { code: 'fr', name: 'French', nativeName: 'Français', flag: '🇫🇷' },
  { code: 'en', name: 'English', nativeName: 'English', flag: '🇬🇧' },
  { code: 'es', name: 'Spanish', nativeName: 'Español', flag: '🇪🇸' },
  { code: 'de', name: 'German', nativeName: 'Deutsch', flag: '🇩🇪' },
  { code: 'it', name: 'Italian', nativeName: 'Italiano', flag: '🇮🇹' },
  { code: 'pt', name: 'Portuguese', nativeName: 'Português', flag: '🇵🇹' },
  { code: 'ja', name: 'Japanese', nativeName: '日本語', flag: '🇯🇵' },
  { code: 'zh', name: 'Chinese', nativeName: '中文', flag: '🇨🇳' },
  { code: 'ko', name: 'Korean', nativeName: '한국어', flag: '🇰🇷' },
];

// ============================================================================
// Language Selector Component
// ============================================================================

export const LanguageSelector = memo(function LanguageSelector({
  currentLanguage,
  onLanguageChange,
  position = 'bottom',
}: LanguageSelectorProps) {
  const currentLanguageOption = SUPPORTED_LANGUAGES.find(
    (lang) => lang.code === currentLanguage
  );

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="text-gray-400 hover:text-white hover:bg-gray-700"
          title="Change Language"
          aria-label={`Change language. Current language: ${currentLanguageOption?.nativeName || currentLanguage}`}
          aria-haspopup="menu"
        >
          <Globe className="w-5 h-5" aria-hidden="true" />
          <span className="sr-only">Change language</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="w-56 bg-gray-800 border-gray-700 text-gray-200"
      >
        {SUPPORTED_LANGUAGES.map((language) => {
          const isSelected = language.code === currentLanguage;
          
          return (
            <DropdownMenuItem
              key={language.code}
              onSelect={() => onLanguageChange(language.code)}
              className="hover:bg-gray-700 focus:bg-gray-700 cursor-pointer"
            >
              <div className="flex items-center gap-3 w-full">
                <span className="text-xl" role="img" aria-label={`${language.name} flag`}>{language.flag}</span>
                <div className="flex-1">
                  <div className="text-sm font-medium text-gray-200">
                    {language.nativeName}
                  </div>
                  <div className="text-xs text-gray-400">{language.name}</div>
                </div>
                {isSelected && (
                  <Check className="w-4 h-4 text-purple-400" aria-hidden="true" />
                )}
              </div>
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
});

