    it('should highlight recommended models with star', () => {
      render(
        <ModelSelector
          currentModel="qwen3-vl:8b"
          availableModels={mockModels}
          onModelChange={mockOnModelChange}
          taskType="vision"
        />
      );

      const select = screen.getByRole('combobox') as HTMLSelectElement;
