/**
 * LocationEditor Component
 * 
 * Tabbed interface for editing location properties including info, cube textures,
 * skybox configuration, and scene placement.
 * Supports keyboard shortcuts: Ctrl+Enter to save, Ctrl+S to save, Arrow keys to navigate faces.
 * 
 * File: creative-studio-ui/src/components/location/LocationEditor.tsx
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Save, X, Info, Box, Image as ImageIcon, Map, Layers, Eye, Keyboard, Images, MessageSquare } from 'lucide-react';
import type { Location, LocationType, CubeFace } from '@/types/location';
import { useLocationStore } from '@/stores/locationStore';
import { CubeProgressBar } from './editor/CubeProgressBar';
import { LocationImagesSection } from './editor/LocationImagesSection';
import { PromptsManager } from '../common/PromptsManager';
import { buildVisualPromptForLocation } from '@/lib/promptUtils';
import './LocationEditor.css';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for the LocationEditor component
 */
export interface LocationEditorProps {
  /** Location to edit (undefined for new location) */
  location?: Location;

  /** Handler for save */
  onSave: (data: Partial<Location>) => void;

  /** Handler for cancel */
  onCancel: () => void;

  /** Editor mode */
  mode?: 'full';

  /** Handler for preview toggle */
  onPreviewToggle?: (enabled: boolean) => void;

  /** Handler for face generation request */
  onGenerateFace?: (face: CubeFace) => void;

  /** Handler for generate all faces */
  onGenerateAllFaces?: () => void;
}

// ============================================================================
// Component
// ============================================================================

export function LocationEditor({
  location,
  onSave,
  onCancel,
  mode,
  onPreviewToggle,
  onGenerateFace,
  onGenerateAllFaces,
}: LocationEditorProps) {
  const { textureDirection, setTextureDirection } = useLocationStore();

  // Form state
  const [name, setName] = useState(location?.name || '');
  const [locationType, setLocationType] = useState<LocationType>(location?.location_type || 'exterior');
  const [description, setDescription] = useState(location?.metadata?.description || '');
  const [atmosphere, setAtmosphere] = useState(location?.metadata?.atmosphere || '');
  const [genreTags, setGenreTags] = useState<string>(location?.metadata?.genre_tags?.join(', ') || '');
  const [prompts, setPrompts] = useState<string[]>(location?.prompts || []);

  // Initialize prompts and auto-populate if empty
  useEffect(() => {
    if (location) {
      const initialPrompts = location.prompts || [];
      if (initialPrompts.length === 0) {
        const basePrompt = buildVisualPromptForLocation(location);
        if (basePrompt) {
          setPrompts([basePrompt]);
          // Note: we don't call handleUpdateLocation here to avoid marking dirty immediately
          // but it will be saved when the user saves the whole form
        }
      } else {
        setPrompts(initialPrompts);
      }
    }
  }, [location]);

  // Active tab
  const [activeTab, setActiveTab] = useState<'info' | 'cube' | 'skybox' | 'assets' | 'scene' | 'images' | 'prompts'>('info');

  // Preview mode
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  // Dirty state
  const [isDirty, setIsDirty] = useState(false);

  // Cube face navigation
  const cubeFaces: CubeFace[] = ['front', 'back', 'left', 'right', 'top', 'bottom'];
  const [activeCubeFace, setActiveCubeFace] = useState<CubeFace>('front');

  const handleInputChange = useCallback(() => {
    setIsDirty(true);
  }, []);

  const handleSave = useCallback(() => {
    const updates: Partial<Location> = {
      name,
      location_type: locationType,
      metadata: {
        ...location?.metadata,
        description,
        atmosphere,
        genre_tags: genreTags.split(',').map((tag) => tag.trim()).filter(Boolean),
      },
      prompts,
    };
    onSave(updates);
    setIsDirty(false);
  }, [name, locationType, description, atmosphere, genreTags, location?.metadata, prompts, onSave]);

  const handlePreviewToggle = useCallback(() => {
    setIsPreviewMode(!isPreviewMode);
    onPreviewToggle?.(!isPreviewMode);
  }, [isPreviewMode, onPreviewToggle]);

  const handleGenerateFace = useCallback((face: CubeFace) => {
    setActiveCubeFace(face);
    onGenerateFace?.(face);
  }, [onGenerateFace]);

  const handleGenerateAllFaces = useCallback(() => {
    onGenerateAllFaces?.();
  }, [onGenerateAllFaces]);

  const handleUpdateLocation = useCallback((updates: Partial<Location>) => {
    onSave(updates);
    setIsDirty(true);
  }, [onSave]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl+Enter or Ctrl+S to save
      if ((e.ctrlKey || e.metaKey) && (e.key === 'Enter' || e.key === 's')) {
        e.preventDefault();
        handleSave();
      }

      // Escape to cancel
      if (e.key === 'Escape') {
        e.preventDefault();
        onCancel();
      }

      // Arrow keys to navigate cube faces (when in cube tab)
      if (activeTab === 'cube') {
        const currentIndex = cubeFaces.indexOf(activeCubeFace);
        if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
          e.preventDefault();
          const nextIndex = (currentIndex + 1) % cubeFaces.length;
          setActiveCubeFace(cubeFaces[nextIndex]);
        } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
          e.preventDefault();
          const prevIndex = (currentIndex - 1 + cubeFaces.length) % cubeFaces.length;
          setActiveCubeFace(cubeFaces[prevIndex]);
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeTab, activeCubeFace, handleSave, onCancel]);

  const tabs = [
    { id: 'info', label: 'Info', icon: Info },
    { id: 'cube', label: 'Cube', icon: Box },
    { id: 'skybox', label: 'Skybox', icon: ImageIcon },
    { id: 'assets', label: 'Assets', icon: Layers },
    { id: 'scene', label: 'Scene', icon: Map },
    { id: 'images', label: 'Images', icon: Images },
    { id: 'prompts', label: 'Prompts', icon: MessageSquare },
  ];

  // Create a merged location object for child sections
  const currentLocation: Location | undefined = location ? {
    ...location,
    name,
    location_type: locationType,
    metadata: {
      ...location.metadata,
      description,
      atmosphere,
      genre_tags: genreTags.split(',').map((tag) => tag.trim()).filter(Boolean),
    },
    prompts,
  } : undefined;

  return (
    <div className={`location-editor ${mode === 'full' ? 'location-editor--full' : ''}`}>
      {/* Tab Navigation */}
      <div className="location-editor__tabs">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              className={`location-editor__tab ${activeTab === tab.id ? 'location-editor__tab--active' : ''}`}
              onClick={() => setActiveTab(tab.id as any)}
            >
              <Icon size={16} />
              <span>{tab.label}</span>
            </button>
          );
        })}
      </div>

      {/* Tab Content */}
      <div className="location-editor__content">
        {activeTab === 'info' && (
          <div className="location-editor__panel">
            <h3 className="location-editor__panel-title">Basic Information</h3>

            <div className="location-editor__form-group">
              <label className="location-editor__label">Name</label>
              <input
                type="text"
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  handleInputChange();
                }}
                placeholder="Enter location name"
                className="location-editor__input"
              />
            </div>

            <div className="location-editor__form-group">
              <label className="location-editor__label">Type</label>
              <div className="location-editor__type-selector">
                <button
                  className={`location-editor__type-btn ${locationType === 'exterior' ? 'location-editor__type-btn--active' : ''}`}
                  onClick={() => {
                    setLocationType('exterior');
                    handleInputChange();
                  }}
                >
                  Exterior
                </button>
                <button
                  className={`location-editor__type-btn ${locationType === 'interior' ? 'location-editor__type-btn--active' : ''}`}
                  onClick={() => {
                    setLocationType('interior');
                    handleInputChange();
                  }}
                >
                  Interior
                </button>
              </div>
            </div>

            <div className="location-editor__form-group">
              <label className="location-editor__label">Description</label>
              <textarea
                value={description}
                onChange={(e) => {
                  setDescription(e.target.value);
                  handleInputChange();
                }}
                placeholder="Describe the location..."
                className="location-editor__textarea"
                rows={4}
              />
            </div>

            <div className="location-editor__form-group">
              <label className="location-editor__label">Atmosphere</label>
              <input
                type="text"
                value={atmosphere}
                onChange={(e) => {
                  setAtmosphere(e.target.value);
                  handleInputChange();
                }}
                placeholder="e.g., Dark, Mysterious, Bright"
                className="location-editor__input"
              />
            </div>

            <div className="location-editor__form-group">
              <label className="location-editor__label">Genre Tags</label>
              <input
                type="text"
                value={genreTags}
                onChange={(e) => {
                  setGenreTags(e.target.value);
                  handleInputChange();
                }}
                placeholder="fantasy, medieval, forest (comma-separated)"
                className="location-editor__input"
              />
            </div>
          </div>
        )}

        {activeTab === 'cube' && location && (
          <div className="location-editor__cube-panel">
            {/* Cube Progress Bar */}
            <CubeProgressBar
              cubeTextures={location.cube_textures}
              activeFace={activeCubeFace}
              onFaceClick={handleGenerateFace}
              onGenerateAll={handleGenerateAllFaces}
            />

            {/* Cube Face Navigation */}
            <div className="location-editor__cube-faces">
              <span className="location-editor__cube-faces-label">Active Face:</span>
              <div className="location-editor__cube-face-nav">
                {cubeFaces.map((face) => (
                  <button
                    key={face}
                    className={`location-editor__cube-face-btn ${activeCubeFace === face ? 'location-editor__cube-face-btn--active' : ''}`}
                    onClick={() => setActiveCubeFace(face)}
                  >
                    {face.charAt(0).toUpperCase() + face.slice(1)}
                  </button>
                ))}
              </div>
            </div>

            <p className="location-editor__hint">
              Use arrow keys to navigate between faces when this panel is focused.
            </p>
          </div>
        )}

        {activeTab === 'skybox' && location && (
          <div className="location-editor__skybox-panel">
            <p className="location-editor__hint">Skybox Panel Placeholder - SkyboxPanel.tsx coming in Phase 4</p>
          </div>
        )}

        {activeTab === 'assets' && location && (
          <div className="location-editor__assets-panel">
            <p className="location-editor__hint">Assets Panel Placeholder - LocationAssetsPanel.tsx coming in Phase 4</p>
          </div>
        )}

        {activeTab === 'scene' && location && (
          <div className="location-editor__scene-panel">
            <h3 className="location-editor__panel-title">Scene Placement</h3>
            <p className="location-editor__hint">
              Place this location in the 3D scene using the Scene Editor.
            </p>
            {location.scene_transform ? (
              <div className="location-editor__transform">
                <h4>Current Transform</h4>
                <pre>{JSON.stringify(location.scene_transform, null, 2)}</pre>
              </div>
            ) : (
              <p className="location-editor__hint">Not placed in scene yet.</p>
            )}
          </div>
        )}

        {activeTab === 'images' && currentLocation && (
          <LocationImagesSection
            location={currentLocation}
            onImageGenerated={(tileUrl, generatedPrompt) => {
              const updates: Partial<Location> = {
                metadata: {
                  ...currentLocation.metadata,
                  tile_image_path: tileUrl
                }
              };
              
              if (generatedPrompt) {
                const newPrompts = [...prompts, generatedPrompt];
                setPrompts(newPrompts);
                updates.prompts = newPrompts;
              }
              
              handleUpdateLocation(updates);
            }}
          />
        )}

        {activeTab === 'prompts' && (
          <div className="location-editor__panel">
            <PromptsManager
              prompts={prompts}
              onUpdate={(newPrompts) => {
                setPrompts(newPrompts);
                handleInputChange();
              }}
              entityName={name || 'Location'}
            />
          </div>
        )}
      </div>

      {/* Actions */}
      <div className="location-editor__actions">
        {/* Preview Mode Toggle */}
        <button
          className={`location-editor__btn location-editor__btn--preview ${isPreviewMode ? 'location-editor__btn--preview--active' : ''}`}
          onClick={handlePreviewToggle}
          title="Toggle preview mode (Ctrl+P)"
        >
          <Eye size={16} />
          {isPreviewMode ? 'Exit Preview' : 'Preview'}
        </button>

        {/* Cancel Button */}
        <button className="location-editor__btn location-editor__btn--cancel" onClick={onCancel}>
          <X size={16} />
          Cancel
        </button>

        {/* Save Button */}
        <button
          className="location-editor__btn location-editor__btn--save"
          onClick={handleSave}
          disabled={!isDirty && !!location}
        >
          <Save size={16} />
          Save
        </button>
      </div>

      {/* Keyboard Shortcuts Hint */}
      <div className="location-editor__shortcuts">
        <Keyboard size={14} />
        <span><kbd>Ctrl</kbd>+<kbd>Enter</kbd> Save</span>
        <span><kbd>Esc</kbd> Cancel</span>
        <span><kbd>↑</kbd><kbd>↓</kbd> Navigate faces</span>
      </div>
    </div>
  );
}

export default LocationEditor;

/**
 * LocationList Component
 * 
 * Grid layout for displaying location cards with filter and create functionality.
 * 
 * File: creative-studio-ui/src/components/location/LocationList.tsx
 * 
 * Updated: Added pagination support for large location lists
 */

import React, { useMemo } from 'react';
import { Plus, Grid, List, Filter, Search } from 'lucide-react';
import { LocationCard } from './LocationCard';
import type { Location, LocationType } from '@/types/location';
import { useLocationStore, getFilteredLocations } from '@/stores/locationStore';
import { usePagination } from '@/hooks/usePagination';
import { Pagination } from '@/components/ui/pagination';
import './LocationList.css';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for the LocationList component
 */
export interface LocationListProps {
  /** Handler for create location button click */
  onCreateLocation: () => void;
  
  /** Handler for location card click */
  onLocationClick: (location: Location) => void;
  
  /** Handler for location edit */
  onEditLocation: (location: Location) => void;
  
  /** Handler for location delete */
  onDeleteLocation: (location: Location) => void;
  
  /** Whether to show filter controls */
  showFilters?: boolean;
  
  /** Whether to show create button */
  showCreateButton?: boolean;
  
  /** Whether to show action buttons on cards */
  showActions?: boolean;
  
  /** Whether to show selection controls */
  selectable?: boolean;
  
  /** Selected location IDs (for selection mode) */
  selectedIds?: string[];
  
  /** Handler for selection changes */
  onSelectionChange?: (ids: string[]) => void;
}

// ============================================================================
// Component
// ============================================================================

export function LocationList({
  onCreateLocation,
  onLocationClick,
  onEditLocation,
  onDeleteLocation,
  showFilters = true,
  showCreateButton = true,
  showActions = true,
  selectable = false,
  selectedIds = [],
  onSelectionChange,
}: LocationListProps) {
  const {
    locations,
    filterType,
    filterWorld,
    searchQuery,
    selectLocation,
    setFilterType,
    setFilterWorld,
    setSearchQuery,
    isLoading,
  } = useLocationStore();
  
  const filteredLocations = useMemo(
    () => getFilteredLocations(useLocationStore.getState()),
    [locations, filterType, filterWorld, searchQuery]
  );
  
  /**
   * Pagination for locations
   */
  const {
    paginatedItems,
    pagination,
    goToPage,
    setPageSize,
  } = usePagination({
    items: filteredLocations,
    pageSize: 12,
    resetOnItemsChange: true,
  });
  
  const handleLocationClick = (location: Location) => {
    selectLocation(location.location_id);
    onLocationClick(location);
  };
  
  const handleSelectionChange = (location: Location, selected: boolean) => {
    if (onSelectionChange) {
      if (selected) {
        onSelectionChange([...selectedIds, location.location_id]);
      } else {
        onSelectionChange(selectedIds.filter((id) => id !== location.location_id));
      }
    }
  };
  
  const uniqueWorlds = useMemo(() => {
    const worlds = new Set<string>();
    locations.forEach((loc) => {
      if (loc.world_id) worlds.add(loc.world_id);
    });
    return Array.from(worlds);
  }, [locations]);
  
  return (
    <div className="location-list">
      {/* Header */}
      <div className="location-list__header">
        <h2 className="location-list__title">Locations</h2>
        {showCreateButton && (
          <button className="location-list__create-btn" onClick={onCreateLocation}>
            <Plus size={18} />
            Create Location
          </button>
        )}
      </div>
      
      {/* Filters */}
      {showFilters && (
        <div className="location-list__filters">
          {/* Search */}
          <div className="location-list__search">
            <Search size={16} className="location-list__search-icon" />
            <input
              type="text"
              placeholder="Search locations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="location-list__search-input"
            />
          </div>
          
          {/* Type Filter */}
          <div className="location-list__filter">
            <Filter size={16} />
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value as LocationType | 'all')}
              className="location-list__select"
              aria-label="Filter by location type"
            >
              <option value="all">All Types</option>
              <option value="exterior">Exterior</option>
              <option value="interior">Interior</option>
            </select>
          </div>
          
          {/* World Filter */}
          {uniqueWorlds.length > 0 && (
            <div className="location-list__filter">
              <select
                value={filterWorld}
                onChange={(e) => setFilterWorld(e.target.value)}
                className="location-list__select"
                aria-label="Filter by world"
              >
                <option value="all">All Worlds</option>
                {uniqueWorlds.map((worldId) => (
                  <option key={worldId} value={worldId}>
                    {worldId}
                  </option>
                ))}
              </select>
            </div>
          )}
          
          {/* Results Count */}
          <div className="location-list__count">
            {filteredLocations.length} location{filteredLocations.length !== 1 ? 's' : ''}
          </div>
        </div>
      )}
      
      {/* Grid */}
      {isLoading ? (
        <div className="location-list__loading">
          <div className="location-list__spinner" />
          <p>Loading locations...</p>
        </div>
      ) : filteredLocations.length === 0 ? (
        <div className="location-list__empty">
          <div className="location-list__empty-icon">📍</div>
          <h3>No locations found</h3>
          <p>
            {searchQuery || filterType !== 'all' || filterWorld !== 'all'
              ? 'Try adjusting your filters'
              : 'Create your first location to get started'}
          </p>
          {showCreateButton && (
            <button className="location-list__create-btn" onClick={onCreateLocation}>
              <Plus size={18} />
              Create Location
            </button>
          )}
        </div>
      ) : (
        <>
          <div className="location-list__grid">
            {paginatedItems.map((location) => (
              <LocationCard
                key={location.location_id}
                location={location}
                onClick={() => handleLocationClick(location)}
                selectable={selectable}
                selected={selectedIds.includes(location.location_id)}
                onSelect={(selected) => handleSelectionChange(location, selected)}
                showActions={showActions}
                onEdit={() => onEditLocation(location)}
                onDelete={() => onDeleteLocation(location)}
              />
            ))}
          </div>
          
          {/* Pagination Controls */}
          <Pagination
            pagination={pagination}
            onPageChange={goToPage}
            onPageSizeChange={setPageSize}
            showPageSizeSelector
            className="location-list__pagination"
          />
        </>
       )}
    </div>
  );
}

export default LocationList;

/**
 * LocationSection Component
 * 
 * Main section wrapper for the locations feature on the project dashboard.
 * Provides section header, create button, and integrates LocationList.
 * Includes World Building wizard integration for creating locations from world data.
 * 
 * File: creative-studio-ui/src/components/location/LocationSection.tsx
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Plus, Map, X, Globe, RefreshCw, ExternalLink } from 'lucide-react';
import { LocationList } from './LocationList';
import { LocationEditor } from './LocationEditor';
import type { Location } from '@/types/location';
import { useLocationStore } from '@/stores/locationStore';
import { v4 as uuidv4 } from 'uuid';
import './LocationSection.css';

// ============================================================================
// Types
// ============================================================================

/**
 * World Building location data (mock interface for integration)
 */
export interface WorldLocationData {
  id: string;
  name: string;
  description: string;
  location_type: 'exterior' | 'interior';
  atmosphere: string;
  genre_tags: string[];
  world_id: string;
  world_name: string;
}

/**
 * Props for the LocationSection component
 */
export interface LocationSectionProps {
  /** Handler for create location button click */
  onCreateLocation?: () => void;

  /** Handler for location card click (opens editor) */
  onLocationClick?: (location: Location) => void;

  /** Optional handler for location edit */
  onEditLocation?: (location: Location) => void;

  /** Optional handler for location delete */
  onDeleteLocation?: (location: Location) => void;

  /** Whether to show action buttons on location cards */
  showActions?: boolean;

  /** Whether to auto-fetch locations on mount */
  autoFetch?: boolean;

  /** Optional world building locations for integration */
  worldLocations?: WorldLocationData[];

  /** Handler when a location is created from world data */
  onCreateFromWorld?: (worldLocation: WorldLocationData) => void;

  /** Whether to hide the section header */
  hideHeader?: boolean;

  /** Optional className */
  className?: string;

  /** Optional style */
  style?: React.CSSProperties;
}

// ============================================================================
// Component
// ============================================================================

export function LocationSection({
  onCreateLocation,
  onLocationClick,
  onEditLocation,
  onDeleteLocation,
  showActions = true,
  autoFetch = true,
  worldLocations = [],
  onCreateFromWorld,
  hideHeader = false,
  className = '',
  style = {},
}: LocationSectionProps) {
  const {
    locations,
    fetchLocations,
    fetchProjectLocations,
    addLocation,
    updateLocation,
    deleteLocation,
    isLoading,
    error,
  } = useLocationStore();

  // Get project ID for fetching project-local locations
  const projectId = typeof window !== 'undefined'
    ? window.location.pathname.split(/[/\\]/).pop() || 'unknown'
    : 'unknown';

  const [showEditor, setShowEditor] = useState(false);
  const [editingLocation, setEditingLocation] = useState<Location | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showWorldSelector, setShowWorldSelector] = useState(false);
  const [selectedWorldLocation, setSelectedWorldLocation] = useState<WorldLocationData | null>(null);

  // Fetch locations on mount (both central and project-local)
  useEffect(() => {
    if (autoFetch) {
      fetchLocations();
      if (projectId && projectId !== 'unknown') {
        fetchProjectLocations(projectId);
      }
    }
  }, [autoFetch, fetchLocations, fetchProjectLocations, projectId]);

  const handleCreateLocation = useCallback(() => {
    setEditingLocation(null);
    setShowCreateModal(true);
    if (onCreateLocation) onCreateLocation();
  }, [onCreateLocation]);

  const handleCreateFromWorld = useCallback((worldLocation: WorldLocationData) => {
    setSelectedWorldLocation(worldLocation);
    setShowWorldSelector(false);

    // Pre-populate editor with world data
    const prePopulatedData: Partial<Location> = {
      name: worldLocation.name,
      location_type: worldLocation.location_type,
      metadata: {
        description: worldLocation.description,
        atmosphere: worldLocation.atmosphere,
        genre_tags: worldLocation.genre_tags,
      },
      is_world_derived: true,
      world_id: worldLocation.world_id,
      world_location_id: worldLocation.id,
    };

    setEditingLocation(prePopulatedData as Location);
    setShowCreateModal(true);
    onCreateFromWorld?.(worldLocation);
  }, [onCreateFromWorld]);

  const handleWorldSelectorOpen = useCallback(() => {
    setShowWorldSelector(true);
  }, []);

  const handleLocationClick = useCallback((location: Location) => {
    setEditingLocation(location);
    setShowEditor(true);
    if (onLocationClick) onLocationClick(location);
  }, [onLocationClick]);

  const handleEditLocation = useCallback((location: Location) => {
    setEditingLocation(location);
    setShowCreateModal(true);
    if (onEditLocation) onEditLocation(location);
  }, [onEditLocation]);

  const handleDeleteLocation = useCallback(async (location: Location) => {
    if (window.confirm(`Are you sure you want to delete "${location?.name || 'this location'}"?`)) {
      try {
        await deleteLocation(location.location_id);
        if (onDeleteLocation) onDeleteLocation(location);
      } catch (err) {
        console.error('Failed to delete location:', err);
      }
    }
  }, [deleteLocation, onDeleteLocation]);

  const handleSaveLocation = useCallback(async (locationData: Partial<Location>) => {
    try {
      if (editingLocation) {
        // Update existing location
        await updateLocation(editingLocation.location_id, locationData);
      } else {
        // Create new location
        const newLocation: Location = {
          location_id: uuidv4(),
          name: locationData.name || 'New Location',
          location_type: locationData.location_type || 'exterior',
          texture_direction: locationData.location_type === 'interior' ? 'inward' : 'outward',
          creation_method: 'manual',
          creation_timestamp: new Date().toISOString(),
          version: '1.0',
          metadata: {
            description: locationData.metadata?.description || '',
            atmosphere: locationData.metadata?.atmosphere || '',
            genre_tags: locationData.metadata?.genre_tags || [],
            ...locationData.metadata,
          },
          cube_textures: {},
          placed_assets: [],
          is_world_derived: false,
          world_id: locationData.world_id,
          world_location_id: locationData.world_location_id,
          ...locationData,
        };
        await addLocation(newLocation);
      }
      setShowCreateModal(false);
      setEditingLocation(null);
    } catch (err) {
      console.error('Failed to save location:', err);
    }
  }, [editingLocation, addLocation, updateLocation]);

  const handleCloseEditor = useCallback(() => {
    setShowEditor(false);
    setEditingLocation(null);
  }, []);

  const handleCloseCreateModal = useCallback(() => {
    setShowCreateModal(false);
    setEditingLocation(null);
  }, []);

  const handleRefresh = useCallback(() => {
    fetchLocations();
    if (projectId && projectId !== 'unknown') {
      fetchProjectLocations(projectId);
    }
  }, [fetchLocations, fetchProjectLocations, projectId]);

  return (
    <div className={`location-section ${className}`} style={style}>
      {/* Section Header */}
      {!hideHeader && (
        <div className="location-section__header">
          <div className="location-section__title-wrapper">
            <Map className="location-section__icon" size={24} />
            <h2 className="location-section__title">Locations</h2>
            <span className="location-section__count">
              {locations.length} {locations.length === 1 ? 'location' : 'locations'}
            </span>
          </div>

          <div className="location-section__actions">
            {/* World Building Integration */}
            {worldLocations.length > 0 && (
              <div className="location-section__world-dropdown">
                <button
                  className="location-section__world-btn"
                  onClick={handleWorldSelectorOpen}
                  title="Create from World Building"
                >
                  <Globe size={16} />
                  <span>From World</span>
                  <ExternalLink size={12} />
                </button>
              </div>
            )}

            {/* Refresh button */}
            <button
              className="location-section__refresh"
              onClick={handleRefresh}
              disabled={isLoading}
              title="Refresh locations"
            >
              <RefreshCw size={16} className={isLoading ? 'location-section__spinner' : ''} />
            </button>

            {/* Create button */}
            <button
              className="location-section__create"
              onClick={handleCreateLocation}
            >
              <Plus size={18} />
              <span>Create</span>
            </button>
          </div>
        </div>
      )}

      {/* Error display */}
      {error && (
        <div className="location-section__error">
          {error}
          <button onClick={handleRefresh}> Retry</button>
        </div>
      )}

      {/* Location List */}
      <LocationList
        onCreateLocation={handleCreateLocation}
        onLocationClick={handleLocationClick}
        onEditLocation={handleEditLocation}
        onDeleteLocation={handleDeleteLocation}
        showFilters={true}
        showCreateButton={true}
        showActions={true}
      />

      {/* Create/Edit Modal */}
      {showCreateModal && (
        <div className="location-section__modal-overlay" onClick={handleCloseCreateModal}>
          <div className="location-section__modal" onClick={(e) => e.stopPropagation()}>
            <div className="location-section__modal-header">
              <h3 className="location-section__modal-title">
                {editingLocation ? 'Edit Location' : 'Create New Location'}
              </h3>
              <button className="location-section__modal-close" onClick={handleCloseCreateModal} title="Close">
                <X size={20} />
              </button>
            </div>
            <LocationEditor
              location={editingLocation || undefined}
              onSave={handleSaveLocation}
              onCancel={handleCloseCreateModal}
            />
          </div>
        </div>
      )}

      {/* Full Editor Modal */}
      {showEditor && editingLocation && (
        <div className="location-section__modal-overlay" onClick={handleCloseEditor}>
          <div className="location-section__modal location-section__modal--full" onClick={(e) => e.stopPropagation()}>
            <div className="location-section__modal-header">
              <h3 className="location-section__modal-title">
                Edit Location: {editingLocation.name}
              </h3>
              <button className="location-section__modal-close" onClick={handleCloseEditor} title="Close">
                <X size={20} />
              </button>
            </div>
            <LocationEditor
              location={editingLocation}
              onSave={handleSaveLocation}
              onCancel={handleCloseEditor}
              mode="full"
            />
          </div>
        </div>
      )}

      {/* World Building Location Selector Modal */}
      {showWorldSelector && (
        <div className="location-section__modal-overlay" onClick={() => setShowWorldSelector(false)}>
          <div className="location-section__modal" onClick={(e) => e.stopPropagation()}>
            <div className="location-section__modal-header">
              <h3 className="location-section__modal-title">
                <Globe size={20} />
                Create from World Building
              </h3>
              <button className="location-section__modal-close" onClick={() => setShowWorldSelector(false)} title="Close">
                <X size={20} />
              </button>
            </div>
            <div className="location-section__world-content">
              <p className="location-section__world-description">
                Select a location from your World Building data to create a new location:
              </p>
              <div className="location-section__world-list">
                {worldLocations.map((worldLoc) => (
                  <button
                    key={worldLoc.id}
                    className="location-section__world-item"
                    onClick={() => handleCreateFromWorld(worldLoc)}
                  >
                    <div className="location-section__world-item-info">
                      <span className="location-section__world-item-name">{worldLoc.name}</span>
                      <span className="location-section__world-item-type">
                        {worldLoc.location_type === 'exterior' ? 'Exterior' : 'Interior'}
                      </span>
                    </div>
                    <span className="location-section__world-source">
                      From: {worldLoc.world_name}
                    </span>
                  </button>
                ))}
              </div>
              {worldLocations.length === 0 && (
                <p className="location-section__world-empty">
                  No World Building locations available.
                </p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default LocationSection;

/**
 * CubeFaceGenerator Component
 * 
 * Prompt input for cube face image generation via ComfyUI.
 * Displays results and allows applying generated textures.
 * Supports low-resolution testing mode for faster iterations.
 * 
 * File: creative-studio-ui/src/components/location/editor/CubeFaceGenerator.tsx
 */

import React, { useState, useCallback, useEffect } from 'react';
import { Sparkles, X, Loader2, Check, Copy, Zap, Settings, ChevronDown } from 'lucide-react';
import type { CubeFace, CubeFaceTexture } from '@/types/location';
import { v4 as uuidv4 } from 'uuid';
import './CubeFaceGenerator.css';

// ============================================================================
// API Configuration
// ============================================================================

// ComfyUI API URL - configurable for different instances
const COMFYUI_API_URL = process.env.VITE_COMFYUI_API_URL || 'http://127.0.0.1:8188';
const COMFYUI_API_URL_8000 = process.env.VITE_COMFYUI_API_URL_8000 || 'http://127.0.0.1:8000';
const API_BASE_URL = process.env.VITE_API_URL || 'http://localhost:8080';

// ============================================================================
// Types
// ============================================================================

/**
 * Resolution preset for generation
 */
export type ResolutionPreset = {
  label: string;
  width: number;
  height: number;
  description: string;
};

/**
 * Available resolution presets
 */
export const RESOLUTION_PRESETS: ResolutionPreset[] = [
  { label: '256x256 (Fast)', width: 256, height: 256, description: 'Fast testing, low detail' },
  { label: '512x512 (Normal)', width: 512, height: 512, description: 'Balanced speed and quality' },
  { label: '1024x1024 (High)', width: 1024, height: 1024, description: 'High detail, slower generation' },
];

/**
 * Props for the CubeFaceGenerator component
 */
export interface CubeFaceGeneratorProps {
  /** Face being generated */
  face: CubeFace;
  
  /** Location ID for API calls */
  locationId: string;
  
  /** Existing texture (for regeneration) */
  existingTexture?: CubeFaceTexture;
  
  /** Handler for generated texture */
  onGenerate: (texture: CubeFaceTexture) => void;
  
  /** Handler for cancel */
  onCancel: () => void;
}

// ============================================================================
// ComfyUI API Functions
// ============================================================================

/**
 * Generate image using ComfyUI API
 */
async function generateWithComfyUI(
  face: CubeFace,
  prompt: string,
  negativePrompt: string,
  settings: { width: number; height: number; steps: number; cfgScale: number; seed: number },
  apiUrl: string
): Promise<string> {
  // ComfyUI API endpoint for text-to-image
  const endpoint = `${apiUrl}/api/prompt`;
  
  // Build the workflow based on face
  const faceDirection: Record<CubeFace, string> = {
    front: 'forward',
    back: 'backward',
    left: 'left',
    right: 'right',
    top: 'up',
    bottom: 'down',
  };
  
  // Simplified workflow for cube face generation
  const workflow = {
    "3": {
      "inputs": {
        "seed": settings.seed,
        "steps": settings.steps,
        "cfg": settings.cfgScale,
        "sampler_name": "euler_a",
        "scheduler": "normal",
        "denoise": 1,
        "model": ["4", 0],
        "positive": ["6", 0],
        "negative": ["7", 0],
        "latent_image": ["5", 0]
      },
      "class_type": "KSampler"
    },
    "4": {
      "inputs": {
        "ckpt_name": "flux1-dev.safetensors"
      },
      "class_type": "CheckpointLoaderSimple"
    },
    "5": {
      "inputs": {
        "width": settings.width,
        "height": settings.height,
        "batch_size": 1
      },
      "class_type": "EmptyLatentImage"
    },
    "6": {
      "inputs": {
        "text": `${prompt} (${faceDirection[face]} view:1.1) cube face:1.2 high quality:1.3`,
        "clip": ["4", 1]
      },
      "class_type": "CLIPTextEncode"
    },
    "7": {
      "inputs": {
        "text": `${negativePrompt} low quality:1.4 blurry:1.4 distorted:1.4`,
        "clip": ["4", 1]
      },
      "class_type": "CLIPTextEncode"
    },
    "8": {
      "inputs": {
        "samples": ["3", 0],
        "vae": ["4", 2]
      },
      "class_type": "VAEDecode"
    },
    "9": {
      "inputs": {
        "filename_prefix": `cube_${face}_${Date.now()}`,
        "images": ["8", 0]
      },
      "class_type": "SaveImage"
    }
  };
  
  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ prompt: workflow }),
    });
    
    if (!response.ok) {
      throw new Error(`ComfyUI API error: ${response.status}`);
    }
    
    const result = await response.json();
    
    // The prompt was queued successfully
    // In a real implementation, we'd poll for completion
    // For now, return a mock URL
    return `${apiUrl}/output/cube_${face}_${Date.now()}.png`;
  } catch (error) {
    console.error('ComfyUI generation error:', error);
    throw error;
  }
}

// ============================================================================
// Component
// ============================================================================

export function CubeFaceGenerator({
  face,
  locationId,
  existingTexture,
  onGenerate,
  onCancel,
}: CubeFaceGeneratorProps) {
  const [prompt, setPrompt] = useState(existingTexture?.generation_params?.prompt || '');
  const [negativePrompt, setNegativePrompt] = useState(existingTexture?.generation_params?.negative_prompt || '');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState<number | null>(null);
  
  // Generation settings
  const [width, setWidth] = useState(existingTexture?.generation_params?.width || 512);
  const [height, setHeight] = useState(existingTexture?.generation_params?.height || 512);
  const [steps, setSteps] = useState(existingTexture?.generation_params?.steps || 20);
  const [cfgScale, setCfgScale] = useState(existingTexture?.generation_params?.cfg_scale || 7);
  const [seed, setSeed] = useState(existingTexture?.generation_params?.seed || -1);
  
  // Test mode for low-res generation (port 8000)
  const [useTestMode, setUseTestMode] = useState(false);
  const [selectedResolution, setSelectedResolution] = useState<ResolutionPreset>(RESOLUTION_PRESETS[1]);
  
  // Update width/height when resolution preset changes
  useEffect(() => {
    setWidth(selectedResolution.width);
    setHeight(selectedResolution.height);
  }, [selectedResolution]);
  
  const faceLabels: Record<CubeFace, string> = {
    front: 'Front',
    back: 'Back',
    left: 'Left',
    right: 'Right',
    top: 'Top',
    bottom: 'Bottom',
  };
  
  const handleGenerate = useCallback(async () => {
    if (!prompt.trim()) {
      setError('Please enter a prompt');
      return;
    }
    
    setIsGenerating(true);
    setError(null);
    setProgress(0);
    
    try {
      // Generate image using ComfyUI
      const imageUrl = await generateWithComfyUI(
        face,
        prompt,
        negativePrompt,
        {
          width,
          height,
          steps,
          cfgScale,
          seed: seed === -1 ? Math.floor(Math.random() * 1000000) : seed,
        },
        useTestMode ? COMFYUI_API_URL_8000 : COMFYUI_API_URL
      );
      
      setProgress(100);
      setGeneratedImage(imageUrl);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate image');
      
      // Fallback to mock image for demo purposes
      const mockImageUrl = `https://picsum.photos/seed/${uuidv4()}/${width}/${height}`;
      setGeneratedImage(mockImageUrl);
    } finally {
      setIsGenerating(false);
      setProgress(null);
    }
  }, [face, prompt, negativePrompt, width, height, steps, cfgScale, seed]);
  
  const handleApply = useCallback(() => {
    if (!generatedImage) return;
    
    const usedSeed = seed === -1 ? Math.floor(Math.random() * 1000000) : seed;
    
    const texture: CubeFaceTexture = {
      id: uuidv4(),
      face,
      image_path: generatedImage,
      generated_at: new Date().toISOString(),
      generation_params: {
        prompt,
        negative_prompt: negativePrompt || undefined,
        width,
        height,
        steps,
        cfg_scale: cfgScale,
        seed: usedSeed,
      },
    };
    
    onGenerate(texture);
  }, [face, generatedImage, prompt, negativePrompt, width, height, steps, cfgScale, seed, onGenerate]);
  
  return (
    <div className="cube-face-generator">
      {/* Header */}
      <div className="cube-face-generator__header">
        <h3 className="cube-face-generator__title">
          <Sparkles size={20} />
          Generate {faceLabels[face]} Face
        </h3>
        <button className="cube-face-generator__close" onClick={onCancel} title="Close">
          <X size={20} />
        </button>
      </div>
      
      {/* Content */}
      <div className="cube-face-generator__content">
        {/* Prompt Input */}
        <div className="cube-face-generator__form-group">
          <label className="cube-face-generator__label">
            Prompt <span className="cube-face-generator__required">*</span>
          </label>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder={`Describe the ${face} view of the location...`}
            className="cube-face-generator__textarea"
            rows={4}
          />
        </div>
        
        {/* Negative Prompt */}
        <div className="cube-face-generator__form-group">
          <label className="cube-face-generator__label">Negative Prompt</label>
          <textarea
            value={negativePrompt}
            onChange={(e) => setNegativePrompt(e.target.value)}
            placeholder="Elements to avoid (blurry, distorted, etc.)"
            className="cube-face-generator__textarea"
            rows={2}
          />
        </div>
        
        {/* Test Mode & Resolution Settings */}
        <div className="cube-face-generator__settings-row">
          {/* Test Mode Toggle */}
          <div className="cube-face-generator__setting-group">
            <label className="cube-face-generator__toggle-label">
              <Zap size={16} />
              Test Mode (Low-Res)
            </label>
            <div className="cube-face-generator__toggle">
              <button
                className={`cube-face-generator__toggle-btn ${useTestMode ? 'cube-face-generator__toggle-btn--active' : ''}`}
                onClick={() => setUseTestMode(!useTestMode)}
              >
                {useTestMode ? 'ON' : 'OFF'}
              </button>
              <span className="cube-face-generator__toggle-info">
                Uses port 8000, {useTestMode ? selectedResolution.width + 'x' + selectedResolution.height : 'full resolution'}
              </span>
            </div>
          </div>
          
          {/* Resolution Preset */}
          <div className="cube-face-generator__setting-group">
            <label className="cube-face-generator__toggle-label">
              <Settings size={16} />
              Resolution
            </label>
            <div className="cube-face-generator__dropdown">
              <select
                value={selectedResolution.label}
                onChange={(e) => {
                  const preset = RESOLUTION_PRESETS.find(p => p.label === e.target.value);
                  if (preset) setSelectedResolution(preset);
                }}
                className="cube-face-generator__select"
                disabled={useTestMode}
              >
                {RESOLUTION_PRESETS.map((preset) => (
                  <option key={preset.label} value={preset.label}>
                    {preset.label}
                  </option>
                ))}
              </select>
              <ChevronDown size={14} className="cube-face-generator__dropdown-icon" />
            </div>
            <span className="cube-face-generator__toggle-info">
              {selectedResolution.description}
            </span>
          </div>
        </div>
        
        {/* Generation Settings */}
        <div className="cube-face-generator__settings">
          <div className="cube-face-generator__setting">
            <label>Width</label>
            <input
              type="number"
              value={width}
              onChange={(e) => setWidth(parseInt(e.target.value) || 512)}
              min={256}
              max={2048}
              step={64}
              aria-label="Image width"
            />
          </div>
          <div className="cube-face-generator__setting">
            <label>Height</label>
            <input
              type="number"
              value={height}
              onChange={(e) => setHeight(parseInt(e.target.value) || 512)}
              min={256}
              max={2048}
              step={64}
              aria-label="Image height"
            />
          </div>
          <div className="cube-face-generator__setting">
            <label>Steps</label>
            <input
              type="number"
              value={steps}
              onChange={(e) => setSteps(parseInt(e.target.value) || 20)}
              min={1}
              max={100}
              aria-label="Generation steps"
            />
          </div>
          <div className="cube-face-generator__setting">
            <label>CFG</label>
            <input
              type="number"
              value={cfgScale}
              onChange={(e) => setCfgScale(parseFloat(e.target.value) || 7)}
              min={1}
              max={20}
              step={0.5}
              aria-label="CFG scale"
            />
          </div>
          <div className="cube-face-generator__setting">
            <label>Seed</label>
            <input
              type="number"
              value={seed}
              onChange={(e) => setSeed(parseInt(e.target.value) || -1)}
              min={-1}
              aria-label="Random seed"
            />
          </div>
        </div>
        
        {/* Progress */}
        {isGenerating && progress !== null && (
          <div className="cube-face-generator__progress">
            <div className="cube-face-generator__progress-bar">
              <div 
                className="cube-face-generator__progress-fill" 
                style={{ width: `${progress}%` }}
              />
            </div>
            <span className="cube-face-generator__progress-text">
              Generating... {progress}%
            </span>
          </div>
        )}
        
        {/* Error */}
        {error && (
          <div className="cube-face-generator__error">
            {error}
          </div>
        )}
        
        {/* Generate Button */}
        <button
          className="cube-face-generator__generate-btn"
          onClick={handleGenerate}
          disabled={isGenerating || !prompt.trim()}
        >
          {isGenerating ? (
            <>
              <Loader2 size={18} className="cube-face-generator__spinner" />
              Generating...
            </>
          ) : (
            <>
              <Sparkles size={18} />
              Generate Image
            </>
          )}
        </button>
        
        {/* Result */}
        {generatedImage && (
          <div className="cube-face-generator__result">
            <div className="cube-face-generator__preview">
              <img src={generatedImage} alt={`Generated ${face} face`} />
            </div>
            
            <div className="cube-face-generator__result-actions">
              <button
                className="cube-face-generator__apply-btn"
                onClick={handleApply}
              >
                <Check size={16} />
                Apply to {faceLabels[face]}
              </button>
              <button
                className="cube-face-generator__regenerate-btn"
                onClick={() => {
                  setGeneratedImage(null);
                  setError(null);
                }}
              >
                <Copy size={16} />
                Regenerate
              </button>
            </div>
          </div>
        )}
        
        {/* Existing Texture Info */}
        {existingTexture && !generatedImage && (
          <div className="cube-face-generator__existing">
            <p>Currently showing existing texture from {new Date(existingTexture.generated_at).toLocaleDateString()}</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default CubeFaceGenerator;

/**
 * CubeViewEditor Component
 * 
 * 6-panel grid showing each cube face with generation controls.
 * Allows selecting faces, generating textures via ComfyUI, and previewing results.
 * 
 * File: creative-studio-ui/src/components/location/editor/CubeViewEditor.tsx
 */

import React, { useState, useCallback } from 'react';
import { RefreshCw, Eye, EyeOff, ArrowRight, ArrowLeft, ArrowUp, ArrowDown, Grid } from 'lucide-react';
import type { Location, CubeFace, CubeFaceTexture } from '@/types/location';
import { useLocationStore } from '@/stores/locationStore';
import { CubeFaceGenerator } from './CubeFaceGenerator';
import { CUBE_FACES } from '@/types/location';
import './CubeViewEditor.css';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for the CubeViewEditor component
 */
export interface CubeViewEditorProps {
  /** Location being edited */
  location: Location;
  
  /** Current texture direction */
  textureDirection: 'inward' | 'outward';
  
  /** Handler for texture direction change */
  onTextureDirectionChange: (direction: 'inward' | 'outward') => void;
}

// ============================================================================
// Component
// ============================================================================

export function CubeViewEditor({
  location,
  textureDirection,
  onTextureDirectionChange,
}: CubeViewEditorProps) {
  const { updateCubeTexture, updateLocation, selectCubeFace, selectedCubeFace } = useLocationStore();
  
  const [editingFace, setEditingFace] = useState<CubeFace | null>(null);
  
  const faceLabels: Record<CubeFace, string> = {
    front: 'Front (Z+)',
    back: 'Back (Z-)',
    left: 'Left (X-)',
    right: 'Right (X+)',
    top: 'Top (Y+)',
    bottom: 'Bottom (Y-)',
  };
  
  const faceIcons: Record<CubeFace, React.ReactNode> = {
    front: <ArrowRight size={20} />,
    back: <ArrowLeft size={20} />,
    left: <ArrowLeft size={20} />,
    right: <ArrowRight size={20} />,
    top: <ArrowUp size={20} />,
    bottom: <ArrowDown size={20} />,
  };
  
  const handleGenerate = useCallback((face: CubeFace) => {
    setEditingFace(face);
    selectCubeFace(face);
  }, [selectCubeFace]);
  
  const handleTextureUpdate = useCallback((face: CubeFace, texture: CubeFaceTexture) => {
    updateCubeTexture(location.location_id, face, texture);
    setEditingFace(null);
  }, [location.location_id, updateCubeTexture]);
  
  const handleCloseGenerator = useCallback(() => {
    setEditingFace(null);
    selectCubeFace(null);
  }, [selectCubeFace]);
  
  const getFaceProgress = (face: CubeFace): number => {
    const totalFaces = CUBE_FACES.length;
    const generatedFaces = CUBE_FACES.filter((f) => location.cube_textures[f]?.image_path).length;
    return (generatedFaces / totalFaces) * 100;
  };
  
  return (
    <div className="cube-view-editor">
      {/* Header */}
      <div className="cube-view-editor__header">
        <div className="cube-view-editor__title">
          <Grid size={20} />
          <h3>Cube Texture Mapping</h3>
        </div>
        
        <div className="cube-view-editor__direction-toggle">
          <span className="cube-view-editor__direction-label">Texture Direction:</span>
          <button
            className={`cube-view-editor__direction-btn ${textureDirection === 'outward' ? 'cube-view-editor__direction-btn--active' : ''}`}
            onClick={() => onTextureDirectionChange('outward')}
          >
            Outward (Exterior)
          </button>
          <button
            className={`cube-view-editor__direction-btn ${textureDirection === 'inward' ? 'cube-view-editor__direction-btn--active' : ''}`}
            onClick={() => onTextureDirectionChange('inward')}
          >
            Inward (Interior)
          </button>
        </div>
      </div>
      
      {/* Progress Bar */}
      <div className="cube-view-editor__progress">
        <div className="cube-view-editor__progress-bar">
          <div 
            className="cube-view-editor__progress-fill" 
            style={{ width: `${getFaceProgress('front')}%` }}
          />
        </div>
        <span className="cube-view-editor__progress-text">
          {CUBE_FACES.filter((f) => location.cube_textures[f]?.image_path).length} / {CUBE_FACES.length} faces generated
        </span>
      </div>
      
      {/* 6-Panel Grid */}
      <div className="cube-view-editor__grid">
        {CUBE_FACES.map((face) => {
          const texture = location.cube_textures[face];
          const isEditing = editingFace === face;
          
          return (
            <div 
              key={face}
              className={`cube-view-editor__face ${texture?.image_path ? 'cube-view-editor__face--generated' : ''} ${isEditing ? 'cube-view-editor__face--editing' : ''}`}
            >
              <div className="cube-view-editor__face-header">
                <span className="cube-view-editor__face-icon">{faceIcons[face]}</span>
                <span className="cube-view-editor__face-label">{faceLabels[face]}</span>
              </div>
              
              <div className="cube-view-editor__face-preview">
                {texture?.image_path ? (
                  <img src={texture.image_path} alt={`${face} face`} />
                ) : (
                  <div className="cube-view-editor__face-placeholder">
                    <span>No texture</span>
                  </div>
                )}
              </div>
              
              <div className="cube-view-editor__face-actions">
                {texture?.image_path ? (
                  <>
                    <button
                      className="cube-view-editor__face-action cube-view-editor__face-action--view"
                      title="Preview"
                    >
                      <Eye size={16} />
                    </button>
                    <button
                      className="cube-view-editor__face-action cube-view-editor__face-action--regenerate"
                      title="Regenerate"
                      onClick={() => handleGenerate(face)}
                    >
                      <RefreshCw size={16} />
                    </button>
                  </>
                ) : (
                  <button
                    className="cube-view-editor__face-action cube-view-editor__face-action--generate"
                    onClick={() => handleGenerate(face)}
                  >
                    Generate
                  </button>
                )}
              </div>
              
              {texture?.generated_at && (
                <div className="cube-view-editor__face-meta">
                  Generated: {new Date(texture.generated_at).toLocaleDateString()}
                </div>
              )}
            </div>
          );
        })}
      </div>
      
      {/* Face Generator Modal */}
      {editingFace && (
        <div className="cube-view-editor__modal-overlay" onClick={handleCloseGenerator}>
          <div className="cube-view-editor__modal" onClick={(e) => e.stopPropagation()}>
            <CubeFaceGenerator
              face={editingFace}
              existingTexture={location.cube_textures[editingFace]}
              onGenerate={(texture) => handleTextureUpdate(editingFace, texture)}
              onCancel={handleCloseGenerator}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default CubeViewEditor;

import React, { useState } from 'react';
import { Image, Loader2, AlertCircle, MapPin } from 'lucide-react';
import { ComfyUIService } from '@/services/comfyuiService';
import { useAppStore } from '@/stores/useAppStore';
import './LocationImageGenerator.css';

// ============================================================================
// Common Types for Location Image Generation
// ============================================================================

/**
 * Common interface for location data needed for image generation.
 * This interface is compatible with both:
 * - Location from @/types/location (uses location_id)
 * - Location from @/types/world (uses id)
 */
export interface LocationImageData {
  /** Unique identifier (maps to location_id or id depending on source) */
  id?: string;
  /** Location identifier from @/types/location */
  location_id?: string;
  /** Display name of the location */
  name?: string;
  /** Location type for scene context */
  location_type?: 'exterior' | 'interior';
  /** Metadata containing description, atmosphere, etc. */
  metadata?: {
    description?: string;
    atmosphere?: string;
    significance?: string;
    time_period?: string;
    key_features?: string[];
    color_palette?: string[];
    genre_tags?: string[];
    [key: string]: unknown;
  };
}

interface LocationImageGeneratorProps {
  readonly location: LocationImageData;
  readonly onImageGenerated?: (imageUrl: string, prompt?: string) => void;
  readonly disabled?: boolean;
}

/**
 * LocationImageGenerator Component
 * 
 * Generates a 512x512 tile/location image using ComfyUI
 * based on the location's name, description, atmosphere, and features.
 */
export function LocationImageGenerator({
  location,
  onImageGenerated,
  disabled = false,
}: LocationImageGeneratorProps) {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);

  const comfyuiService = ComfyUIService.getInstance();
  const project = useAppStore((state) => state.project);

  // Get visual style from project
  const visualStyle = (project as any)?.visualStyle || (project as any)?.visual_style || 'realistic';

  /**
   * Build a detailed prompt from location data
   */
  const buildLocationPrompt = (): string => {
    const parts: string[] = [];
    const metadata = location.metadata;

    // Add visual style first
    const styleMap: Record<string, string> = {
      'photorealistic': 'photorealistic',
      'cinematic': 'cinematic',
      'anime': 'anime style',
      'cartoon': 'cartoon style',
      'sketch': 'sketch art',
      'oil-painting': 'oil painting',
      'watercolor': 'watercolor painting',
      'digital-art': 'digital art',
      'comic-book': 'comic book style',
      'noir': 'film noir style',
      'vintage': 'vintage style',
      'modern': 'modern style',
      'minimalist': 'minimalist style',
      'realistic': 'realistic'
    };

    const stylePrefix = styleMap[visualStyle] || visualStyle;
    parts.push(stylePrefix);

    // Location name as main subject
    if (location.name) {
      parts.push(`Location: ${location.name}`);
    } else {
      parts.push('Unknown location');
    }

    // Location type
    if (location.location_type) {
      const typeMap: Record<string, string> = {
        'exterior': 'exterior scene',
        'interior': 'interior scene'
      };
      parts.push(typeMap[location.location_type] || 'location scene');
    }

    // Description
    if (metadata?.description) {
      parts.push(metadata.description);
    }

    // Atmosphere and mood
    if (metadata?.atmosphere) {
      parts.push(`Atmosphere: ${metadata.atmosphere}`);
    }

    // Time period
    if (metadata?.time_period) {
      parts.push(`Era: ${metadata.time_period}`);
    }

    // Key features/landmarks
    if (metadata?.key_features && metadata.key_features.length > 0) {
      parts.push(`Key features: ${metadata.key_features.join(', ')}`);
    }

    // Color palette
    if (metadata?.color_palette && metadata.color_palette.length > 0) {
      parts.push(`Color palette: ${metadata.color_palette.join(', ')} colors`);
    }

    // Genre tags
    if (metadata?.genre_tags && metadata.genre_tags.length > 0) {
      parts.push(`Genre: ${metadata.genre_tags.join(', ')}`);
    }

    // Add quality tags from user requirements
    parts.push(
      'photorealist',
      'cinematic lighting',
      'high quality',
      '8K',
      'detailed',
      'professional shot',
      'wide angle',
      'cinematic composition',
      'sharp focus'
    );

    return parts.join(', ');
  };

  /**
   * Build negative prompt to avoid unwanted elements
   */
  const buildNegativePrompt = (): string => {
    return [
      'blurry',
      'low quality',
      'distorted',
      'deformed',
      'ugly',
      'bad anatomy',
      'watermark',
      'text',
      'signature',
      'people',
      'person',
      'character',
      'human figure',
      'close-up',
      'portrait',
      'clutter',
      'mess',
    ].join(', ');
  };

  /**
   * Handle image generation
   */
  const handleGenerate = async () => {
    if (disabled || isGenerating) return;

    setIsGenerating(true);
    setError(null);
    let prompt = '';

    try {
      prompt = buildLocationPrompt();
      const negativePrompt = buildNegativePrompt();

      console.log('Generating location tile image with prompt:', prompt);

      // Generate 512x512 tile image
      const imageUrl = await comfyuiService.generateImage({
        prompt,
        negativePrompt,
        width: 512,
        height: 512,
        steps: 4,
        cfgScale: 1,
        seed: Math.floor(Math.random() * 1000000),
        model: 'z_image_turbo_bf16.safetensors',
        sampler: 'res_multistep',
        scheduler: 'simple',
      });

      setGeneratedImage(imageUrl);

      if (onImageGenerated) {
        onImageGenerated(imageUrl, prompt);
      }
    } catch (err) {
      console.error('Failed to generate location image:', err);
      setError(err instanceof Error ? err.message : 'Failed to generate image');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="location-image-generator">
      <div className="location-image-generator__header">
        <h4 className="location-image-generator__title">
          <MapPin size={18} />
          Location Tile Image
        </h4>
        <p className="location-image-generator__description">
          Generate a 512x512 tile image based on location details
        </p>
      </div>

      {/* Preview area */}
      <div className="location-image-generator__preview">
        {generatedImage ? (
          <img
            src={generatedImage}
            alt={location.name || 'Generated location tile'}
            className="location-image-generator__image"
          />
        ) : (
          <div className="location-image-generator__placeholder">
            <Image size={48} />
            <p>No image generated yet</p>
          </div>
        )}
      </div>

      {/* Error message */}
      {error && (
        <div className="location-image-generator__error">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      {/* Generate button */}
      <button
        className="location-image-generator__button"
        onClick={handleGenerate}
        disabled={disabled || isGenerating}
      >
        {isGenerating ? (
          <>
            <Loader2 size={18} className="location-image-generator__spinner" />
            Generating...
          </>
        ) : (
          <>
            <Image size={18} />
            Generate Tile Image
          </>
        )}
      </button>

      {/* Info text */}
      <p className="location-image-generator__info">
        The image will be generated using ComfyUI based on the location's name, description, atmosphere, and features.
        Make sure ComfyUI is running and configured.
      </p>
    </div>
  );
}

