/**
 * LocationImagesSection Component
 * 
 * Tab content for the Images tab in LocationEditor.
 * Displays the current tile image and provides generation functionality.
 * 
 * File: creative-studio-ui/src/components/location/editor/LocationImagesSection.tsx
 */

import React, { useState, useEffect } from 'react';
import { Image as ImageIcon, Eye, MapPin, RefreshCw } from 'lucide-react';
import type { Location } from '@/types/location';
import { LocationImageGenerator } from './LocationImageGenerator';
import './LocationImagesSection.css';

interface LocationImagesSectionProps {
  /** Location to edit */
  location: Location;

  /** Handler when an image is generated */
  onImageGenerated?: (tileUrl: string, prompt?: string) => void;
}

/**
 * Display current tile image and provide generation options
 */
export function LocationImagesSection({
  location,
  onImageGenerated,
}: LocationImagesSectionProps) {
  const [showGenerator, setShowGenerator] = useState(false);
  const [currentTileImage, setCurrentTileImage] = useState<string | null>(
    location.metadata?.tile_image_path || null
  );

  // Update local state when location changes
  useEffect(() => {
    if (location.metadata?.tile_image_path) {
      setCurrentTileImage(location.metadata.tile_image_path);
    }
  }, [location.metadata?.tile_image_path]);

  const handleImageGenerated = (tileUrl: string, prompt?: string) => {
    setCurrentTileImage(tileUrl);
    onImageGenerated?.(tileUrl, prompt);
    setShowGenerator(false);
  };

  return (
    <div className="location-images-section">
      <div className="location-images-section__header">
        <h3 className="location-images-section__title">
          <ImageIcon size={20} />
          Location Tile Image
        </h3>
        <p className="location-images-section__description">
          View and generate the tile image for this location. The tile image is used
          for map representation and identification.
        </p>
      </div>

      {/* Current tile image display */}
      <div className="location-images-section__current">
        <h4 className="location-images-section__subsection-title">
          <MapPin size={16} />
          Current Tile Image
        </h4>

        {currentTileImage ? (
          <div className="location-images-section__preview">
            <img
              src={currentTileImage}
              alt={`Tile image of ${location.name}`}
              className="location-images-section__image"
            />
            <div className="location-images-section__image-info">
              <span className="location-images-section__image-label">
                {location.name || 'Unnamed Location'}
              </span>
            </div>
          </div>
        ) : (
          <div className="location-images-section__placeholder">
            <ImageIcon size={48} />
            <p>No tile image set for this location</p>
            <span className="location-images-section__placeholder-hint">
              Generate a tile image using the button below
            </span>
          </div>
        )}
      </div>

      {/* Generate new image button */}
      <div className="location-images-section__actions">
        <button
          className="location-images-section__generate-btn"
          onClick={() => setShowGenerator(true)}
        >
          <RefreshCw size={18} />
          Generate New Tile Image
        </button>
      </div>

      {/* Image generator modal */}
      {showGenerator && (
        <div
          className="location-images-section__modal-overlay"
          onClick={() => setShowGenerator(false)}
          role="dialog"
          aria-modal="true"
        >
          <div
            className="location-images-section__modal"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="location-images-section__modal-header">
              <h4 className="location-images-section__modal-title">
                <RefreshCw size={18} />
                Generate Tile Image
              </h4>
              <button
                className="location-images-section__modal-close"
                onClick={() => setShowGenerator(false)}
                aria-label="Close generator"
              >
                ×
              </button>
            </div>

            <LocationImageGenerator
              location={location as any}
              onImageGenerated={handleImageGenerated}
            />
          </div>
        </div>
      )}

      {/* Location info for reference */}
      <div className="location-images-section__info">
        <h4 className="location-images-section__subsection-title">
          <Eye size={16} />
          Location Details Used for Generation
        </h4>
        <div className="location-images-section__details">
          {location.name && (
            <div className="location-images-section__detail">
              <span className="location-images-section__detail-label">Name:</span>
              <span className="location-images-section__detail-value">{location.name}</span>
            </div>
          )}
          {location.location_type && (
            <div className="location-images-section__detail">
              <span className="location-images-section__detail-label">Type:</span>
              <span className="location-images-section__detail-value">
                {location.location_type === 'exterior' ? 'Exterior' : 'Interior'}
              </span>
            </div>
          )}
          {location.metadata?.description && (
            <div className="location-images-section__detail">
              <span className="location-images-section__detail-label">Description:</span>
              <span className="location-images-section__detail-value">
                {location.metadata.description}
              </span>
            </div>
          )}
          {location.metadata?.atmosphere && (
            <div className="location-images-section__detail">
              <span className="location-images-section__detail-label">Atmosphere:</span>
              <span className="location-images-section__detail-value">
                {location.metadata.atmosphere}
              </span>
            </div>
          )}
          {!location.name && !location.metadata?.description && (
            <p className="location-images-section__no-info">
              Add location details in the Info tab for better image generation results.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default LocationImagesSection;

/**
 * Lottie Panel Component
 * ME2: Lottie Integration - Support for Lottie animations
 */

import React, { useEffect, useRef, useState } from 'react';
import { useLottieStore } from '../../stores/lottieStore';
import { lottieService } from '../../services/LottieService';
import styles from './LottiePanel.module.css';

interface LottiePanelProps {
  animationUrl?: string;
  onLoadComplete?: (animationId: string) => void;
}

export const LottiePanel: React.FC<LottiePanelProps> = ({
  animationUrl,
  onLoadComplete,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const {
    animations,
    activeAnimationId,
    playback,
    state,
    isPanelOpen,
    selectedLayerId,
    setActiveAnimation,
    loadAnimation,
    play,
    pause,
    stop,
    setFrame,
    setSpeed,
    setLoop,
    setDirection,
    togglePanel,
    selectLayer,
  } = useLottieStore();

  const [urlInput, setUrlInput] = useState(animationUrl || '');

  // Load animation from URL
  const handleLoadAnimation = async () => {
    if (!urlInput) return;
    
    const id = `lottie_${Date.now()}`;
    const animation = await lottieService.loadAnimation(urlInput, id);
    
    if (animation) {
      loadAnimation(animation);
      onLoadComplete?.(id);
    }
  };

  // Get active animation
  const activeAnimation = activeAnimationId 
    ? animations.get(activeAnimationId) 
    : null;

  if (!isPanelOpen) {
    return (
      <button className={styles.toggleButton} onClick={togglePanel}>
        🎬 Lottie
      </button>
    );
  }

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3>Lottie Animations</h3>
        <button className={styles.closeButton} onClick={togglePanel}>
          ×
        </button>
      </div>

      <div className={styles.content}>
        {/* URL Input */}
        <div className={styles.urlSection}>
          <input
            type="text"
            value={urlInput}
            onChange={(e) => setUrlInput(e.target.value)}
            placeholder="Enter Lottie JSON URL..."
            className={styles.urlInput}
          />
          <button 
            onClick={handleLoadAnimation}
            className={styles.loadButton}
            disabled={!urlInput}
          >
            Load
          </button>
        </div>

        {/* Animation Preview */}
        {activeAnimation && (
          <div className={styles.previewSection}>
            <div 
              ref={containerRef}
              className={styles.previewContainer}
              style={{
                width: activeAnimation.width,
                height: activeAnimation.height,
              }}
            >
              {/* Placeholder for Lottie renderer */}
              <div className={styles.placeholder}>
                {activeAnimation.name}
              </div>
            </div>

            {/* Playback Controls */}
            <div className={styles.playbackControls}>
              <button onClick={stop} className={styles.controlButton}>
                ⏮
              </button>
              {state.isPlaying ? (
                <button onClick={pause} className={styles.controlButton}>
                  ⏸
                </button>
              ) : (
                <button onClick={play} className={styles.controlButton}>
                  ▶
                </button>
              )}
              <button onClick={stop} className={styles.controlButton}>
                ⏭
              </button>
            </div>

            {/* Progress Bar */}
            <div className={styles.progressSection}>
              <input
                type="range"
                min="0"
                max={activeAnimation.totalFrames}
                value={state.currentFrame}
                onChange={(e) => setFrame(Number(e.target.value))}
                className={styles.progressSlider}
              />
              <span className={styles.progressText}>
                {state.currentFrame} / {activeAnimation.totalFrames}
              </span>
            </div>

            {/* Speed Control */}
            <div className={styles.controlRow}>
              <label>Speed:</label>
              <input
                type="range"
                min="0.1"
                max="3"
                step="0.1"
                value={playback.speed}
                onChange={(e) => setSpeed(Number(e.target.value))}
                className={styles.slider}
              />
              <span>{playback.speed.toFixed(1)}x</span>
            </div>

            {/* Loop Toggle */}
            <div className={styles.controlRow}>
              <label>
                <input
                  type="checkbox"
                  checked={playback.loop}
                  onChange={(e) => setLoop(e.target.checked)}
                />
                Loop
              </label>
            </div>

            {/* Direction Toggle */}
            <div className={styles.controlRow}>
              <label>Direction:</label>
              <select
                value={playback.direction}
                onChange={(e) => setDirection(e.target.value as 'forward' | 'reverse')}
                className={styles.select}
              >
                <option value="forward">Forward</option>
                <option value="reverse">Reverse</option>
              </select>
            </div>
          </div>
        )}

        {/* Layers List */}
        {activeAnimation && activeAnimation.layers.length > 0 && (
          <div className={styles.layersSection}>
            <h4>Layers</h4>
            <div className={styles.layersList}>
              {activeAnimation.layers.map((layer) => (
                <div
                  key={layer.id}
                  className={`${styles.layerItem} ${
                    selectedLayerId === layer.id ? styles.selected : ''
                  }`}
                  onClick={() => selectLayer(layer.id)}
                >
                  <span className={styles.layerType}>
                    {layer.type.charAt(0).toUpperCase()}
                  </span>
                  <span className={styles.layerName}>{layer.name}</span>
                  {!layer.isEnabled && (
                    <span className={styles.disabledBadge}>Hidden</span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Loaded Animations */}
        {animations.size > 0 && (
          <div className={styles.loadedSection}>
            <h4>Loaded Animations</h4>
            <div className={styles.animationList}>
              {Array.from(animations.values()).map((anim) => (
                <div
                  key={anim.id}
                  className={`${styles.animationItem} ${
                    activeAnimationId === anim.id ? styles.active : ''
                  }`}
                  onClick={() => setActiveAnimation(anim.id)}
                >
                  <span>{anim.name}</span>
                  <span className={styles.animationInfo}>
                    {anim.width}x{anim.height}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* State Display */}
        {state.error && (
          <div className={styles.error}>
            {state.error}
          </div>
        )}
      </div>
    </div>
  );
};

export default LottiePanel;

/**
 * Menu Component Examples
 * 
 * Demonstrates various use cases for the Menu, MenuDropdown, and MenuItem components.
 */

import React, { useState } from 'react';
import { Menu } from './Menu';
import { Save, FolderOpen, FileText, Settings } from 'lucide-react';

/**
 * Basic File Menu Example
 */
export function BasicFileMenuExample() {
  const [project, setProject] = useState<any>(null);

  const fileMenuItems = [
    {
      id: 'new',
      label: 'New Project',
      shortcut: 'Ctrl+N',
      icon: <FileText className="w-4 h-4" />,
      onClick: () => {
        console.log('Creating new project');
        setProject({ name: 'New Project' });
      },
    },
    {
      id: 'open',
      label: 'Open Project',
      shortcut: 'Ctrl+O',
      icon: <FolderOpen className="w-4 h-4" />,
      onClick: () => {
        console.log('Opening project');
      },
    },
    {
      id: 'save',
      label: 'Save',
      shortcut: 'Ctrl+S',
      icon: <Save className="w-4 h-4" />,
      enabled: project !== null,
      onClick: () => {
        console.log('Saving project');
      },
    },
  ];

  return (
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-4">Basic File Menu</h3>
      <Menu id="file" label="File" items={fileMenuItems} />
      {project && (
        <p className="mt-4 text-sm text-gray-600">
          Current project: {project.name}
        </p>
      )}
    </div>
  );
}

/**
 * View Menu with Toggle Items Example
 */
export function ViewMenuWithTogglesExample() {
  const [viewState, setViewState] = useState({
    timeline: true,
    grid: false,
    properties: true,
    assets: true,
  });

  const viewMenuItems = [
    {
      id: 'timeline',
      label: 'Timeline',
      checked: viewState.timeline,
      onClick: () =>
        setViewState((prev) => ({ ...prev, timeline: !prev.timeline })),
    },
    {
      id: 'grid',
      label: 'Grid',
      checked: viewState.grid,
      onClick: () => setViewState((prev) => ({ ...prev, grid: !prev.grid })),
    },
    {
      id: 'properties',
      label: 'Properties Panel',
      checked: viewState.properties,
      onClick: () =>
        setViewState((prev) => ({ ...prev, properties: !prev.properties })),
    },
    {
      id: 'assets',
      label: 'Assets Panel',
      checked: viewState.assets,
      onClick: () => setViewState((prev) => ({ ...prev, assets: !prev.assets })),
    },
  ];

  return (
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-4">View Menu with Toggles</h3>
      <Menu id="view" label="View" items={viewMenuItems} />
      <div className="mt-4 text-sm text-gray-600">
        <p>Timeline: {viewState.timeline ? 'Visible' : 'Hidden'}</p>
        <p>Grid: {viewState.grid ? 'Visible' : 'Hidden'}</p>
        <p>Properties: {viewState.properties ? 'Visible' : 'Hidden'}</p>
        <p>Assets: {viewState.assets ? 'Visible' : 'Hidden'}</p>
      </div>
    </div>
  );
}

/**
 * Menu with Submenu Indicators Example
 */
export function MenuWithSubmenuExample() {
  const recentProjects = [
    { id: 'project1', name: 'My First Project' },
    { id: 'project2', name: 'Marketing Campaign' },
    { id: 'project3', name: 'Product Demo' },
  ];

  const fileMenuItems = [
    {
      id: 'new',
      label: 'New Project',
      shortcut: 'Ctrl+N',
      onClick: () => console.log('New project'),
    },
    {
      id: 'open',
      label: 'Open Project',
      shortcut: 'Ctrl+O',
      onClick: () => console.log('Open project'),
    },
    {
      id: 'recent',
      label: 'Recent Projects',
      hasSubmenu: true,
      // Note: Submenu functionality would be implemented in a future enhancement
      onClick: () => console.log('Show recent projects'),
    },
  ];

  return (
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-4">Menu with Submenu Indicator</h3>
      <Menu id="file" label="File" items={fileMenuItems} />
      <p className="mt-4 text-sm text-gray-600">
        Note: The "Recent Projects" item shows a submenu indicator (arrow)
      </p>
    </div>
  );
}

/**
 * Complete MenuBar Example
 */
export function CompleteMenuBarExample() {
  const [project, setProject] = useState<any>(null);
  const [viewState, setViewState] = useState({
    timeline: true,
    grid: false,
  });
  const [zoomLevel, setZoomLevel] = useState(100);

  const fileMenuItems = [
    {
      id: 'new',
      label: 'New Project',
      shortcut: 'Ctrl+N',
      onClick: () => setProject({ name: 'New Project' }),
    },
    {
      id: 'open',
      label: 'Open Project',
      shortcut: 'Ctrl+O',
      onClick: () => console.log('Open project'),
    },
    {
      id: 'save',
      label: 'Save',
      shortcut: 'Ctrl+S',
      enabled: project !== null,
      onClick: () => console.log('Save project'),
    },
  ];

  const viewMenuItems = [
    {
      id: 'timeline',
      label: 'Timeline',
      checked: viewState.timeline,
      onClick: () =>
        setViewState((prev) => ({ ...prev, timeline: !prev.timeline })),
    },
    {
      id: 'grid',
      label: 'Grid',
      checked: viewState.grid,
      onClick: () => setViewState((prev) => ({ ...prev, grid: !prev.grid })),
    },
    {
      id: 'zoom-in',
      label: 'Zoom In',
      shortcut: 'Ctrl++',
      enabled: zoomLevel < 400,
      onClick: () => setZoomLevel((prev) => Math.min(prev + 25, 400)),
    },
    {
      id: 'zoom-out',
      label: 'Zoom Out',
      shortcut: 'Ctrl+-',
      enabled: zoomLevel > 25,
      onClick: () => setZoomLevel((prev) => Math.max(prev - 25, 25)),
    },
    {
      id: 'zoom-reset',
      label: 'Reset Zoom',
      shortcut: 'Ctrl+0',
      onClick: () => setZoomLevel(100),
    },
  ];

  const settingsMenuItems = [
    {
      id: 'preferences',
      label: 'Preferences',
      icon: <Settings className="w-4 h-4" />,
      onClick: () => console.log('Open preferences'),
    },
  ];

  return (
    <div>
      <nav className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center h-12 px-4 gap-2">
          <Menu id="file" label="File" items={fileMenuItems} />
          <Menu id="view" label="View" items={viewMenuItems} />
          <Menu id="settings" label="Settings" items={settingsMenuItems} />
        </div>
      </nav>

      <div className="p-4">
        <h3 className="text-lg font-semibold mb-4">Complete MenuBar</h3>
        <div className="text-sm text-gray-600 space-y-2">
          <p>Project: {project ? project.name : 'None'}</p>
          <p>Timeline: {viewState.timeline ? 'Visible' : 'Hidden'}</p>
          <p>Grid: {viewState.grid ? 'Visible' : 'Hidden'}</p>
          <p>Zoom: {zoomLevel}%</p>
        </div>
      </div>
    </div>
  );
}

/**
 * All Examples Container
 */
export function MenuExamples() {
  return (
    <div className="space-y-8 p-8">
      <h1 className="text-2xl font-bold mb-8">Menu Component Examples</h1>
      
      <div className="border border-gray-200 dark:border-gray-700 rounded-lg">
        <BasicFileMenuExample />
      </div>

      <div className="border border-gray-200 dark:border-gray-700 rounded-lg">
        <ViewMenuWithTogglesExample />
      </div>

      <div className="border border-gray-200 dark:border-gray-700 rounded-lg">
        <MenuWithSubmenuExample />
      </div>

      <div className="border border-gray-200 dark:border-gray-700 rounded-lg">
        <CompleteMenuBarExample />
      </div>
    </div>
  );
}

export default MenuExamples;

