    mockContext = {
      state: {
        project: mockProject,
        hasUnsavedChanges: false,
        viewState: {
          timelineVisible: true,
          gridVisible: false,
          zoomLevel: 100,
          minZoom: 25,
          maxZoom: 400,
          zoomStep: 25,
          panelsVisible: {
            properties: true,
            assets: true,
            preview: true,
          },
          fullScreen: false,
        },
        undoStack: {
          canUndo: false,
          canRedo: false,
          undo: vi.fn(),
          redo: vi.fn(),
