describe('Clipboard Operations', () => {
  let mockContext: ActionContext;
  let mockClipboard: ClipboardState;
  let mockProject: Project;
  let mockShot: Shot;

  beforeEach(() => {
    // Create a mock shot
    mockShot = {
      id: 'shot-1',
      title: 'Test shot',
      description: 'Test shot',
      duration: 5,
      position: 1,
      audioTracks: [],
      effects: [],
      textLayers: [],
      animations: [],
    };

    // Create a mock project with a selected shot
    mockProject = {
      schema_version: '1.0',
      project_name: 'Test Project',
      description: 'Test project for clipboard operations',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      shots: [mockShot],
      capabilities: {
        grid_generation: true,
        promotion_engine: true,
        qa_engine: true,
        autofix_engine: true,
      },
      generation_status: {
        grid: 'pending',
        promotion: 'pending',
      },
      selectedShotId: 'shot-1', // Selected shot
    } as any;

    // Create mock clipboard
    mockClipboard = {
      hasContent: false,
      contentType: null,
      cut: vi.fn((content) => {
        mockClipboard.hasContent = true;
        mockClipboard.contentType = 'shot';
      }),
