/**
 * ImageGalleryModal - Galerie d'images générées par IA
 *
 * Permet de voir, organiser et gérer toutes les images générées
 * pour les personnages, objets, mondes et scènes
 *
 * Améliorations de lisibilité:
 * - Meilleur contraste des textes
 * - Couleurs adaptées au thème sombre/clair
 * - Accessibilité améliorée
 */

import React, { useState, useEffect, useMemo } from 'react';
import './ImageGalleryModal.css';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  BookOpenIcon,
  PlusIcon,
  EditIcon,
  TrashIcon,
  SaveIcon,
  XIcon,
  SearchIcon,
  DownloadIcon,
  HeartIcon,
  StarIcon,
  FolderIcon,
  ImageIcon,
  SparklesIcon,
  FilterIcon,
  GridIcon,
  ListIcon,
  EyeIcon,
  TagIcon,
  CalendarIcon,
  UserIcon,
  GlobeIcon,
  MapPinIcon,
  GemIcon,
  TargetIcon,
  CameraIcon,
} from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';
import { imageGalleryService, type ImageMetadata, type ImageCollection } from '@/services/ImageGalleryService';
import { notificationService } from '@/services/NotificationService';

interface ImageGalleryModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function ImageGalleryModal({ isOpen, onClose }: ImageGalleryModalProps) {
  const project = useAppStore((state) => state.project);

  // État local pour la galerie
  const [images, setImages] = useState<ImageMetadata[]>([]);
  const [collections, setCollections] = useState<ImageCollection[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContext, setSelectedContext] = useState<ImageMetadata['contextType'] | 'all'>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [selectedCollection, setSelectedCollection] = useState<string | null>(null);
  const [showCollectionModal, setShowCollectionModal] = useState(false);
  const [showImageDetails, setShowImageDetails] = useState<ImageMetadata | null>(null);

  // Charger les images et collections du projet
  useEffect(() => {
    if (project && isOpen) {
      loadGallery();
    }
  }, [project, isOpen]);

  const loadGallery = () => {
    if (!project) return;

    try {
      const projectImages = imageGalleryService.getProjectImages();
      const projectCollections = imageGalleryService.getProjectCollections();

      setImages(projectImages);
      setCollections(projectCollections);
    } catch (error) {
      console.error('Failed to load gallery:', error);
      notificationService.error('Erreur', 'Impossible de charger la galerie d\'images');
    }
  };

  // Images filtrées
  const filteredImages = useMemo(() => {
    let filtered = images;

    // Filtre par recherche
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(img =>
        img.prompt.toLowerCase().includes(query) ||
        (img.revisedPrompt && img.revisedPrompt.toLowerCase().includes(query)) ||
        img.contextName?.toLowerCase().includes(query) ||
        img.tags.some(tag => tag.toLowerCase().includes(query))
      );
    }

    // Filtre par contexte
    if (selectedContext !== 'all') {
      filtered = filtered.filter(img => img.contextType === selectedContext);
    }

    // Filtre par favoris
    if (showOnlyFavorites) {
      filtered = filtered.filter(img => img.favorite);
    }

    // Filtre par collection
    if (selectedCollection) {
      const collection = collections.find(c => c.id === selectedCollection);
      if (collection) {
        filtered = filtered.filter(img => collection.imageIds.includes(img.id));
      }
    }

    // Tri par date de création (plus récent en premier)
    return filtered.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  }, [images, searchQuery, selectedContext, showOnlyFavorites, selectedCollection, collections]);

  const handleDownloadImage = (image: ImageMetadata) => {
    imageGalleryService.downloadImage(image.id);
  };

  const handleToggleFavorite = (image: ImageMetadata) => {
    const success = imageGalleryService.toggleFavorite(image.id);
    if (success) {
      // Mettre à jour l'état local
      setImages(prev => prev.map(img =>
        img.id === image.id ? { ...img, favorite: !img.favorite } : img
      ));
    }
  };

  const handleDeleteImage = (image: ImageMetadata) => {
    if (confirm(`Êtes-vous sûr de vouloir supprimer l'image "${image.prompt.substring(0, 50)}..." ?`)) {
      const success = imageGalleryService.deleteImage(image.id);
      if (success) {
        setImages(prev => prev.filter(img => img.id !== image.id));
        notificationService.success('Image supprimée', 'L\'image a été retirée de la galerie');
      }
    }
  };

  const handleCreateCollection = () => {
    const collectionName = prompt('Nom de la nouvelle collection:');
    if (collectionName?.trim()) {
      const newCollection = imageGalleryService.createCollection(collectionName.trim());
      setCollections(prev => [...prev, newCollection]);
    }
  };

  const handleAddToCollection = (imageId: string, collectionId: string) => {
    const success = imageGalleryService.addImageToCollection(collectionId, imageId);
    if (success) {
      // Mettre à jour l'état local des collections
      setCollections(prev => prev.map(coll =>
        coll.id === collectionId
          ? { ...coll, imageIds: [...coll.imageIds, imageId], updatedAt: new Date() }
          : coll
      ));
      notificationService.success('Image ajoutée', 'L\'image a été ajoutée à la collection');
    }
  };

  const handleRemoveFromCollection = (imageId: string, collectionId: string) => {
    const success = imageGalleryService.removeImageFromCollection(collectionId, imageId);
    if (success) {
      setCollections(prev => prev.map(coll =>
        coll.id === collectionId
          ? { ...coll, imageIds: coll.imageIds.filter(id => id !== imageId), updatedAt: new Date() }
          : coll
      ));
    }
  };

  const getContextIcon = (contextType: ImageMetadata['contextType']) => {
    switch (contextType) {
      case 'character':
        return <UserIcon className="w-4 h-4 text-blue-500" />;
      case 'world':
        return <GlobeIcon className="w-4 h-4 text-green-500" />;
      case 'location':
        return <MapPinIcon className="w-4 h-4 text-purple-500" />;
      case 'object':
        return <GemIcon className="w-4 h-4 text-orange-500" />;
      case 'scene':
        return <CameraIcon className="w-4 h-4 text-red-500" />;
      default:
        return <ImageIcon className="w-4 h-4 text-gray-500" />;
    }
  };

  const getContextLabel = (contextType: ImageMetadata['contextType']) => {
    switch (contextType) {
      case 'character':
        return 'Personnage';
      case 'world':
        return 'Monde';
      case 'location':
        return 'Lieu';
      case 'object':
        return 'Objet';
      case 'scene':
        return 'Scène';
      default:
        return 'Général';
    }
  };

  const stats = imageGalleryService.getGalleryStats();

  if (!project) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-hidden">
          <DialogHeader>
            <DialogTitle>Galerie d'images</DialogTitle>
          </DialogHeader>
          <div className="p-8 text-center text-gray-500">
            <BookOpenIcon className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>Aucun projet ouvert</p>
            <p className="text-sm">Ouvrez un projet pour accéder à la galerie d'images</p>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="image-gallery-dialog max-w-7xl max-h-[95vh] overflow-hidden flex flex-col">
          <DialogHeader className="flex-shrink-0">
            <DialogTitle className="dialog-title flex items-center gap-2">
              <BookOpenIcon className="w-5 h-5" />
              Galerie d'images - {project.project_name}
            </DialogTitle>
          </DialogHeader>

          {/* Stats Bar */}
          <div className="flex-shrink-0 px-6 py-2 stats-bar">
            <div className="flex items-center justify-between text-sm stat-text">
              <div className="flex items-center gap-4">
                <span>{stats.totalImages} images</span>
                <span>{stats.favoriteImages} favoris</span>
                <span>{stats.totalCollections} collections</span>
              </div>
              <div className="flex items-center gap-2">
                {Object.entries(stats.imagesByType).map(([type, count]) => (
                  <Badge key={type} variant="outline" className="text-xs">
                    {getContextLabel(type as ImageMetadata['contextType'])}: {count}
                  </Badge>
                ))}
              </div>
            </div>
          </div>

          {/* Toolbar */}
          <div className="flex-shrink-0 p-4 toolbar border-b border-gray-200">
            <div className="flex items-center justify-between gap-4">
              {/* Search and filters */}
              <div className="flex items-center gap-4 flex-1">
                <div className="relative flex-1 max-w-sm">
                  <SearchIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4" style={{ color: 'var(--gallery-text-muted)' }} />
                  <Input
                    placeholder="Rechercher dans les prompts, noms..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10"
                    aria-label="Rechercher des images"
                  />
                </div>

                <select
                  value={selectedContext}
                  onChange={(e) => setSelectedContext(e.target.value as ImageMetadata['contextType'] | 'all')}
                  className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  aria-label="Filtrer par contexte"
                  title="Filtrer par contexte"
                >
                  <option value="all">Tous les contextes</option>
                  <option value="character">Personnages</option>
                  <option value="world">Mondes</option>
                  <option value="location">Lieux</option>
                  <option value="object">Objets</option>
                  <option value="scene">Scènes</option>
                  <option value="general">Général</option>
                </select>

                <select
                  value={selectedCollection || ''}
                  onChange={(e) => setSelectedCollection(e.target.value || null)}
                  className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  aria-label="Filtrer par collection"
                  title="Filtrer par collection"
                >
                  <option value="">Toutes les images</option>
                  {collections.map(collection => (
                    <option key={collection.id} value={collection.id}>
                      📁 {collection.name} ({collection.imageIds.length})
                    </option>
                  ))}
                </select>

                <Button
                  variant={showOnlyFavorites ? "default" : "outline"}
                  size="sm"
                  onClick={() => setShowOnlyFavorites(!showOnlyFavorites)}
                  className="flex items-center gap-1"
                >
                  <HeartIcon className="w-4 h-4" />
                  Favoris
                </Button>
              </div>

              {/* View controls */}
              <div className="flex items-center gap-2">
                <Button
                  variant={viewMode === 'grid' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setViewMode('grid')}
                >
                  <GridIcon className="w-4 h-4" />
                </Button>
                <Button
                  variant={viewMode === 'list' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setViewMode('list')}
                >
                  <ListIcon className="w-4 h-4" />
                </Button>
                <Button onClick={handleCreateCollection} className="flex items-center gap-2">
                  <PlusIcon className="w-4 h-4" />
                  Collection
                </Button>
              </div>
            </div>
          </div>

          {/* Images Display */}
          <div className="flex-1 overflow-y-auto p-4">
            {filteredImages.length === 0 ? (
              <div className="empty-state text-center py-12">
                <ImageIcon className="w-12 h-12 mx-auto mb-4" style={{ color: 'var(--gallery-text-muted)' }} />
                <h3 className="empty-state-title text-lg font-medium mb-2">
                  {searchQuery || selectedContext !== 'all' || showOnlyFavorites || selectedCollection
                    ? 'Aucune image trouvée'
                    : 'Aucune image dans la galerie'}
                </h3>
                <p className="empty-state-text mb-4">
                  {searchQuery || selectedContext !== 'all' || showOnlyFavorites || selectedCollection
                    ? 'Essayez de modifier vos critères de recherche.'
                    : 'Générez des images avec l\'IA pour commencer votre collection.'}
                </p>
              </div>
            ) : viewMode === 'grid' ? (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                {filteredImages.map(image => (
                  <div
                    key={image.id}
                    className="image-card group"
                  >
                    {/* Image */}
                    <div className="aspect-square relative overflow-hidden" style={{ background: 'var(--gallery-bg-hover)' }}>
                      <img
                        src={image.url}
                        alt={image.prompt}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-200"
                        loading="lazy"
                        onError={(e) => {
                          e.currentTarget.src = 'data:image/svg+xml;base64,';
                        }}
                      />

                      {/* Overlay avec actions */}
                      <div className="absolute inset-0 image-overlay transition-all duration-200 flex items-center justify-center opacity-0 group-hover:opacity-100">
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            variant="secondary"
                            onClick={() => setShowImageDetails(image)}
                            className="bg-white/90 hover:bg-white"
                            aria-label="Voir les détails"
                          >
                            <EyeIcon className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="secondary"
                            onClick={() => handleDownloadImage(image)}
                            className="bg-white/90 hover:bg-white"
                            aria-label="Télécharger"
                          >
                            <DownloadIcon className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="secondary"
                            onClick={() => handleToggleFavorite(image)}
                            className={`bg-white/90 hover:bg-white ${image.favorite ? 'text-red-500' : ''}`}
                            aria-label={image.favorite ? 'Retirer des favoris' : 'Ajouter aux favoris'}
                          >
                            <HeartIcon className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>

                      {/* Badge favori */}
                      {image.favorite && (
                        <div className="absolute top-2 right-2">
                          <HeartIcon className="w-5 h-5 text-red-500 bg-white rounded-full p-1" />
                        </div>
                      )}
                    </div>

                    {/* Info */}
                    <div className="p-3">
                      <div className="flex items-center gap-2 mb-1">
                        {getContextIcon(image.contextType)}
                        <span className="image-info-context text-xs">
                          {getContextLabel(image.contextType)}
                        </span>
                      </div>
                      <p className="image-info-title text-xs line-clamp-2 mb-1">
                        {image.contextName || image.prompt.substring(0, 50) + '...'}
                      </p>
                      <div className="flex items-center gap-1 text-xs" style={{ color: 'var(--gallery-text-muted)' }}>
                        <CalendarIcon className="w-3 h-3" />
                        {image.createdAt.toLocaleDateString('fr-FR')}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              /* Vue liste */
              <div className="space-y-2">
                {filteredImages.map(image => (
                  <div
                    key={image.id}
                    className="image-card flex items-center gap-4 p-4"
                  >
                    {/* Miniature */}
                    <div className="w-16 h-16 rounded-lg overflow-hidden flex-shrink-0" style={{ background: 'var(--gallery-bg-hover)' }}>
                      <img
                        src={image.url}
                        alt={image.prompt}
                        className="w-full h-full object-cover"
                        loading="lazy"
                      />
                    </div>

                    {/* Infos */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        {getContextIcon(image.contextType)}
                        <span className="text-sm font-medium" style={{ color: 'var(--gallery-text-primary)' }}>
                          {image.contextName || 'Image générée'}
                        </span>
                        {image.favorite && <HeartIcon className="w-4 h-4 text-red-500" />}
                      </div>
                      <p className="text-sm line-clamp-1 mb-1" style={{ color: 'var(--gallery-text-secondary)' }}>
                        {image.prompt}
                      </p>
                      <div className="flex items-center gap-4 text-xs" style={{ color: 'var(--gallery-text-muted)' }}>
                        <span>{getContextLabel(image.contextType)}</span>
                        <span>{image.model} • {image.size}</span>
                        <span>{image.createdAt.toLocaleDateString('fr-FR')}</span>
                        {image.quality && <span>Qualité: {image.quality}</span>}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-2 flex-shrink-0">
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => setShowImageDetails(image)}
                        aria-label="Voir les détails"
                      >
                        <EyeIcon className="w-4 h-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleDownloadImage(image)}
                        aria-label="Télécharger"
                      >
                        <DownloadIcon className="w-4 h-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleToggleFavorite(image)}
                        className={image.favorite ? 'text-red-500' : ''}
                        aria-label={image.favorite ? 'Retirer des favoris' : 'Ajouter aux favoris'}
                      >
                        <HeartIcon className="w-4 h-4" />
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleDeleteImage(image)}
                        className="text-red-500 hover:text-red-700"
                        aria-label="Supprimer"
                      >
                        <TrashIcon className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal détails d'image */}
      {showImageDetails && (
        <ImageDetailsModal
          image={showImageDetails}
          collections={collections}
          onAddToCollection={handleAddToCollection}
          onRemoveFromCollection={handleRemoveFromCollection}
          onClose={() => setShowImageDetails(null)}
        />
      )}
    </>
  );
}

/**
 * ImageDetailsModal - Détails complets d'une image
 */
interface ImageDetailsModalProps {
  image: ImageMetadata;
  collections: ImageCollection[];
  onAddToCollection: (imageId: string, collectionId: string) => void;
  onRemoveFromCollection: (imageId: string, collectionId: string) => void;
  onClose: () => void;
}

function ImageDetailsModal({ image, collections, onAddToCollection, onRemoveFromCollection, onClose }: ImageDetailsModalProps) {
  const [notes, setNotes] = useState(image.notes || '');
  const [rating, setRating] = useState(image.rating || 0);
  const [selectedCollection, setSelectedCollection] = useState('');

  const handleSaveNotes = () => {
  };

  const handleRateImage = (newRating: number) => {
    setRating(newRating);
  };

  const handleAddToCollection = () => {
    if (selectedCollection) {
      onAddToCollection(image.id, selectedCollection);
      setSelectedCollection('');
    }
  };

  const availableCollections = collections.filter(coll => !coll.imageIds.includes(image.id));

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="image-gallery-dialog details-section max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="details-section-title flex items-center gap-2">
            <ImageIcon className="w-5 h-5" />
            Détails de l'image
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Image */}
            <div className="space-y-4">
              <div className="aspect-square rounded-lg overflow-hidden" style={{ background: 'var(--gallery-bg-hover)' }}>
                <img
                  src={image.url}
                  alt={image.prompt}
                  className="w-full h-full object-contain"
                />
              </div>

              {/* Actions rapides */}
              <div className="flex gap-2">
                <Button className="flex-1" variant="outline">
                  <DownloadIcon className="w-4 h-4 mr-2" />
                  Télécharger
                </Button>
                <Button variant={image.favorite ? "default" : "outline"}>
                  <HeartIcon className="w-4 h-4 mr-2" />
                  {image.favorite ? 'Favori' : 'Ajouter aux favoris'}
                </Button>
              </div>
            </div>

            {/* Métadonnées */}
            <div className="space-y-6">
              {/* Informations de base */}
              <div>
                <h3 className="details-section-title text-lg font-semibold mb-3">Informations</h3>
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span className="details-label">Contexte:</span>
                    <Badge variant="outline">{image.contextType}</Badge>
                  </div>
                  <div className="flex justify-between">
                    <span className="details-label">Modèle:</span>
                    <span className="details-value">{image.model}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="details-label">Taille:</span>
                    <span className="details-value">{image.size}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="details-label">Qualité:</span>
                    <span className="details-value">{image.quality}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="details-label">Créée le:</span>
                    <span className="details-value">{image.createdAt.toLocaleString('fr-FR')}</span>
                  </div>
                </div>
              </div>

              {/* Prompt */}
              <div>
                <h3 className="details-section-title text-lg font-semibold mb-3">Prompt original</h3>
                <p className="prompt-box text-sm">
                  {image.prompt}
                </p>
                {image.revisedPrompt && (
                  <div className="mt-2">
                    <h4 className="text-sm font-medium mb-1" style={{ color: 'var(--gallery-text-secondary)' }}>Prompt révisé par IA:</h4>
                    <p className="prompt-box-revised text-sm">
                      {image.revisedPrompt}
                    </p>
                  </div>
                )}
              </div>

              {/* Évaluation */}
              <div>
                <h3 className="details-section-title text-lg font-semibold mb-3">Évaluation</h3>
                <div className="star-rating flex items-center gap-1 mb-2">
                  {[1, 2, 3, 4, 5].map((star) => (
                    <button
                      key={star}
                      onClick={() => handleRateImage(star)}
                      className={`w-6 h-6 ${star <= rating ? 'filled' : 'empty'} star`}
                      aria-label={`Noter ${star} étoiles sur 5`}
                      title={`Noter ${star} étoiles sur 5`}
                    >
                      <StarIcon className="w-full h-full fill-current" />
                    </button>
                  ))}
                  <span className="ml-2 text-sm" style={{ color: 'var(--gallery-text-secondary)' }}>
                    {rating > 0 ? `${rating}/5 étoiles` : 'Non évaluée'}
                  </span>
                </div>
              </div>

              {/* Notes personnelles */}
              <div>
                <h3 className="details-section-title text-lg font-semibold mb-3">Notes personnelles</h3>
                <Textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Ajoutez vos notes sur cette image..."
                  rows={4}
                  className="notes-area"
                />
                <Button onClick={handleSaveNotes} className="mt-2" size="sm">
                  Sauvegarder les notes
                </Button>
              </div>

              {/* Collections */}
              <div>
                <h3 className="details-section-title text-lg font-semibold mb-3">Collections</h3>
                <div className="flex gap-2 mb-3">
                  <select
                    value={selectedCollection}
                    onChange={(e) => setSelectedCollection(e.target.value)}
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    aria-label="Choisir une collection"
                    title="Choisir une collection"
                  >
                    <option value="">Choisir une collection...</option>
                    {availableCollections.map(collection => (
                      <option key={collection.id} value={collection.id}>
                        {collection.name}
                      </option>
                    ))}
                  </select>
                  <Button onClick={handleAddToCollection} disabled={!selectedCollection}>
                    Ajouter
                  </Button>
                </div>

                {/* Collections actuelles */}
                {collections.filter(coll => coll.imageIds.includes(image.id)).length > 0 && (
                  <div>
                    <h4 className="text-sm font-medium mb-2" style={{ color: 'var(--gallery-text-secondary)' }}>Dans les collections:</h4>
                    <div className="flex flex-wrap gap-2">
                      {collections
                        .filter(coll => coll.imageIds.includes(image.id))
                        .map(collection => (
                          <Badge key={collection.id} variant="secondary" className="flex items-center gap-1">
                            {collection.name}
                            <button
                              onClick={() => onRemoveFromCollection(image.id, collection.id)}
                              className="ml-1 hover:text-red-500"
                              style={{ color: 'var(--gallery-text-muted)' }}
                              aria-label={`Retirer de la collection ${collection.name}`}
                              title={`Retirer de la collection ${collection.name}`}
                            >
                              <XIcon className="w-3 h-3" />
                            </button>
                          </Badge>
                        ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Tags */}
              {image.tags.length > 0 && (
                <div>
                  <h3 className="details-section-title text-lg font-semibold mb-3">Tags</h3>
                  <div className="flex flex-wrap gap-2">
                    {image.tags.map(tag => (
                      <Badge key={tag} variant="outline">
                        <TagIcon className="w-3 h-3 mr-1" />
                        {tag}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="flex-shrink-0 flex items-center justify-end gap-3 p-6 border-t border-gray-200">
          <Button variant="outline" onClick={onClose}>
            Fermer
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * ImageGenerationModal Component
 * 
 * A modal dialog for selecting workflow, model, and generation parameters
 * before generating images with ComfyUI.
 * 
 * Features:
 * - Workflow selection with descriptions
 * - Checkpoint/model selection
 * - Resolution presets with GPU memory validation
 * - Advanced parameters (steps, CFG, sampler, scheduler)
 * - Model download integration
 */

import React, { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { 
  Sparkles, 
  Loader2, 
  AlertCircle, 
  Download, 
  Settings2, 
  Image, 
  CheckCircle2,
  Info,
  RefreshCw,
  Zap,
  Cpu,
  HardDrive
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import {
  WORKFLOW_OPTIONS,
  RESOLUTION_PRESETS,
  SAMPLER_OPTIONS,
  SCHEDULER_OPTIONS,
  DEFAULT_GENERATION_PARAMS,
  getAvailableCheckpoints,
  getGPUInfo,
  validateResolution,
  getDefaultParamsForWorkflow,
  type WorkflowOption,
  type GPUInfo,
  type GenerationParams
} from '@/services/imageGenerationService';

// Extend WorkflowType to include FireRed
type ExtendedWorkflowType = 'flux2' | 'z_image_turbo' | 'z_image_turbo_coherence' | 'sdxl' | 'firered_image_edit' | 'custom';

export interface ImageGenerationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (result: { imageUrl: string; params: GenerationParams }) => void;
  initialPrompt?: string;
  initialImageUrl?: string; // For editing/inpainting workflows
  title?: string;
}

export function ImageGenerationModal({
  isOpen,
  onClose,
  onGenerate,
  initialPrompt = '',
  initialImageUrl,
  title = 'Generate Image'
}: ImageGenerationModalProps) {
  const { toast } = useToast();
  
  // State
  const [activeTab, setActiveTab] = useState('workflow');
  const [selectedWorkflow, setSelectedWorkflow] = useState<ExtendedWorkflowType>('z_image_turbo');
  const [checkpoints, setCheckpoints] = useState<string[]>([]);
  const [selectedCheckpoint, setSelectedCheckpoint] = useState<string>('');
  const [isLoadingCheckpoints, setIsLoadingCheckpoints] = useState(false);
  const [gpuInfo, setGpuInfo] = useState<GPUInfo | null>(null);
  const [isLoadingGpu, setIsLoadingGpu] = useState(false);
  
  // Generation parameters
  const [prompt, setPrompt] = useState(initialPrompt);
  const [negativePrompt, setNegativePrompt] = useState(DEFAULT_GENERATION_PARAMS.negativePrompt || '');
  const [width, setWidth] = useState(DEFAULT_GENERATION_PARAMS.width || 1024);
  const [height, setHeight] = useState(DEFAULT_GENERATION_PARAMS.height || 1024);
  const [steps, setSteps] = useState(DEFAULT_GENERATION_PARAMS.steps || 20);
  const [cfgScale, setCfgScale] = useState(DEFAULT_GENERATION_PARAMS.cfgScale || 7.0);
  const [sampler, setSampler] = useState(DEFAULT_GENERATION_PARAMS.sampler || 'euler');
  const [scheduler, setScheduler] = useState(DEFAULT_GENERATION_PARAMS.scheduler || 'normal');
  const [seed, setSeed] = useState<number | undefined>(undefined);
  const [useRandomSeed, setUseRandomSeed] = useState(true);
  
  // Generation state
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  
  // Model download - open HuggingFace in new tab
  const handleOpenModelDownload = () => {
    window.open('https://huggingface.co/cocorang/FireRed-Image-Edit-1.0-FP8_And_BF16', '_blank');
  };
  
  // Validation
  const [resolutionWarning, setResolutionWarning] = useState<string | null>(null);

  // Load checkpoints and GPU info when modal opens
  useEffect(() => {
    if (isOpen) {
      loadCheckpoints();
      loadGpuInfo();
    }
  }, [isOpen]);

  // Update default parameters when workflow changes
  useEffect(() => {
    const defaults = getDefaultParamsForWorkflow(selectedWorkflow as any);
    if (defaults.width) setWidth(defaults.width);
    if (defaults.height) setHeight(defaults.height);
  }, [selectedWorkflow]);

  // Validate resolution when width/height/workflow changes
  useEffect(() => {
    const validation = validateResolution(width, height, selectedWorkflow as any, gpuInfo);
    if (validation.warning) {
      setResolutionWarning(validation.warning);
    } else if (validation.error) {
      setResolutionWarning(validation.error);
    } else {
      setResolutionWarning(null);
    }
  }, [width, height, selectedWorkflow, gpuInfo]);

  const loadCheckpoints = async () => {
    setIsLoadingCheckpoints(true);
    try {
      const models = await getAvailableCheckpoints();
      setCheckpoints(models);
      if (models.length > 0) {
        setSelectedCheckpoint(models[0]);
      }
    } catch (error) {
      console.error('Failed to load checkpoints:', error);
    } finally {
      setIsLoadingCheckpoints(false);
    }
  };

  const loadGpuInfo = async () => {
    setIsLoadingGpu(true);
    try {
      const info = await getGPUInfo();
      setGpuInfo(info);
    } catch (error) {
      console.error('Failed to load GPU info:', error);
    } finally {
      setIsLoadingGpu(false);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) {
      toast({
        title: 'Prompt Required',
        description: 'Please enter a prompt for image generation',
        variant: 'destructive'
      });
      return;
    }

    setIsGenerating(true);
    setGenerationProgress(0);
    setGeneratedImageUrl(null);

    try {
      const params: GenerationParams = {
        prompt: prompt.trim(),
        negativePrompt: negativePrompt.trim() || undefined,
        width,
        height,
        steps,
        cfgScale,
        seed: useRandomSeed ? undefined : seed,
        sampler,
        scheduler,
        workflowType: selectedWorkflow as any,
        checkpoint: selectedCheckpoint || undefined
      };

      // Call the generation service
      const { generateImage } = await import('@/services/imageGenerationService');
      
      const imageUrl = await generateImage(params, (progress, message) => {
        setGenerationProgress(progress);
      });

      setGeneratedImageUrl(imageUrl);
      
      toast({
        title: 'Image Generated',
        description: 'Your image has been generated successfully',
        variant: 'default'
      });

      // Return result to parent
      onGenerate({ imageUrl, params });
      
    } catch (error) {
      console.error('Image generation failed:', error);
      toast({
        title: 'Generation Failed',
        description: error instanceof Error ? error.message : 'Failed to generate image',
        variant: 'destructive'
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const handleResolutionPreset = (w: number, h: number) => {
    setWidth(w);
    setHeight(h);
  };

  const handleClose = () => {
    if (!isGenerating) {
      setGeneratedImageUrl(null);
      setGenerationProgress(0);
      onClose();
    }
  };

  const getWorkflowIcon = (workflow: WorkflowOption) => {
    return workflow.icon || '🎨';
  };

  // Filter out custom from workflow options for selection
  const selectableWorkflows = WORKFLOW_OPTIONS.filter(w => w.id !== 'custom');

  return (
    <>
      <Dialog open={isOpen} onOpenChange={handleClose}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-yellow-500" />
              {title}
            </DialogTitle>
            <DialogDescription>
              Select workflow, model, and parameters for image generation
            </DialogDescription>
          </DialogHeader>

          {/* GPU Info Banner */}
          {gpuInfo && (
            <div className="flex items-center gap-4 px-4 py-2 bg-muted/50 rounded-md text-xs">
              <div className="flex items-center gap-1">
                <Cpu className="w-3 h-3" />
                <span>{gpuInfo.name}</span>
              </div>
              <div className="flex items-center gap-1">
                <HardDrive className="w-3 h-3" />
                <span>{(gpuInfo.vramFree / 1024).toFixed(1)}GB free</span>
              </div>
              <Button 
                variant="ghost" 
                size="sm" 
                className="ml-auto h-6 px-2"
                onClick={loadGpuInfo}
                disabled={isLoadingGpu}
              >
                <RefreshCw className={`w-3 h-3 ${isLoadingGpu ? 'animate-spin' : ''}`} />
              </Button>
            </div>
          )}

          <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1 overflow-hidden flex flex-col">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="workflow" className="gap-1">
                <Zap className="w-4 h-4" /> Workflow
              </TabsTrigger>
              <TabsTrigger value="model" className="gap-1">
                <Image className="w-4 h-4" /> Model
              </TabsTrigger>
              <TabsTrigger value="advanced" className="gap-1">
                <Settings2 className="w-4 h-4" /> Advanced
              </TabsTrigger>
            </TabsList>

            <ScrollArea className="flex-1 mt-4">
              {/* Workflow Selection Tab */}
              <TabsContent value="workflow" className="space-y-4 m-0 p-1">
                <div className="grid grid-cols-2 gap-3">
                  {selectableWorkflows.map((workflow) => (
                    <Card 
                      key={workflow.id}
                      className={`cursor-pointer transition-all ${
                        selectedWorkflow === workflow.id 
                          ? 'border-primary bg-primary/5 ring-2 ring-primary/20' 
                          : 'hover:border-muted-foreground/50'
                      }`}
                      onClick={() => setSelectedWorkflow(workflow.id as ExtendedWorkflowType)}
                    >
                      <CardHeader className="p-3 pb-1">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-sm flex items-center gap-2">
                            <span className="text-lg">{getWorkflowIcon(workflow)}</span>
                            {workflow.name}
                          </CardTitle>
                          {selectedWorkflow === workflow.id && (
                            <CheckCircle2 className="w-4 h-4 text-primary" />
                          )}
                        </div>
                      </CardHeader>
                      <CardContent className="p-3 pt-0">
                        <CardDescription className="text-xs">
                          {workflow.description}
                        </CardDescription>
                        <div className="flex flex-wrap gap-1 mt-2">
                          {workflow.bestFor.slice(0, 3).map((tag) => (
                            <Badge key={tag} variant="secondary" className="text-[10px] px-1 py-0">
                              {tag}
                            </Badge>
                          ))}
                        </div>
                        <div className="mt-2 text-[10px] text-muted-foreground">
                          Recommended: {workflow.recommendedResolution.width}x{workflow.recommendedResolution.height}
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>

                {/* Resolution Section */}
                <div className="space-y-3 mt-4 pt-4 border-t">
                  <div className="flex items-center justify-between">
                    <Label className="text-sm font-semibold">Resolution</Label>
                    <Button 
                      variant="ghost" 
                      size="sm" 
                      className="h-6 text-xs"
                      onClick={() => {
                        const workflow = WORKFLOW_OPTIONS.find(w => w.id === selectedWorkflow);
                        if (workflow) {
                          setWidth(workflow.recommendedResolution.width);
                          setHeight(workflow.recommendedResolution.height);
                        }
                      }}
                    >
                      Use Recommended
                    </Button>
                  </div>
                  
                  {/* Resolution Presets */}
                  <div className="flex flex-wrap gap-2">
                    {RESOLUTION_PRESETS.slice(0, 6).map((preset) => (
                      <Button
                        key={preset.label}
                        variant={width === preset.width && height === preset.height ? 'default' : 'outline'}
                        size="sm"
                        className="text-xs h-7"
                        onClick={() => handleResolutionPreset(preset.width, preset.height)}
                      >
                        {preset.label}
                      </Button>
                    ))}
                  </div>

                  {/* Custom Resolution */}
                  <div className="flex items-center gap-4">
                    <div className="flex-1 space-y-1">
                      <Label className="text-xs">Width</Label>
                      <Input
                        type="number"
                        value={width}
                        onChange={(e) => setWidth(parseInt(e.target.value) || 512)}
                        min={256}
                        max={2048}
                        step={8}
                        className="h-8"
                      />
                    </div>
                    <span className="pt-5 text-muted-foreground">×</span>
                    <div className="flex-1 space-y-1">
                      <Label className="text-xs">Height</Label>
                      <Input
                        type="number"
                        value={height}
                        onChange={(e) => setHeight(parseInt(e.target.value) || 512)}
                        min={256}
                        max={2048}
                        step={8}
                        className="h-8"
                      />
                    </div>
                  </div>

                  {/* Resolution Warning */}
                  {resolutionWarning && (
                    <div className={`flex items-center gap-2 p-2 rounded-md text-xs ${
                      resolutionWarning.includes('error') || resolutionWarning.includes('Maximum') 
                        ? 'bg-red-50 text-red-600' 
                        : 'bg-yellow-50 text-yellow-600'
                    }`}>
                      <AlertCircle className="w-3 h-3 flex-shrink-0" />
                      {resolutionWarning}
                    </div>
                  )}
                </div>
              </TabsContent>

              {/* Model Selection Tab */}
              <TabsContent value="model" className="space-y-4 m-0 p-1">
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <Label className="text-sm font-semibold">Checkpoint Model</Label>
                    <Button 
                      variant="outline" 
                      size="sm"
                      className="gap-1"
                      onClick={handleOpenModelDownload}
                    >
                      <Download className="w-3 h-3" /> Download Model
                    </Button>
                  </div>
                  
                  <Select value={selectedCheckpoint} onValueChange={setSelectedCheckpoint}>
                    <SelectTrigger>
                      <SelectValue placeholder={isLoadingCheckpoints ? "Loading models..." : "Select checkpoint"} />
                    </SelectTrigger>
                    <SelectContent>
                      {checkpoints.length > 0 ? (
                        checkpoints.map((checkpoint) => (
                          <SelectItem key={checkpoint} value={checkpoint}>
                            {checkpoint}
                          </SelectItem>
                        ))
                      ) : (
                        <SelectItem value="default">default (sd_xl_base_1.0.safetensors)</SelectItem>
                      )}
                    </SelectContent>
                  </Select>

                  {checkpoints.length === 0 && !isLoadingCheckpoints && (
                    <div className="flex items-center gap-2 p-3 bg-muted/50 rounded-md text-xs text-muted-foreground">
                      <Info className="w-3 h-3" />
                      <span>No checkpoints found. Make sure ComfyUI is running and models are installed.</span>
                    </div>
                  )}
                </div>

                {/* Quick Actions */}
                <div className="flex gap-2 pt-2">
                  <Button 
                    variant="outline" 
                    size="sm"
                    className="gap-1"
                    onClick={loadCheckpoints}
                    disabled={isLoadingCheckpoints}
                  >
                    <RefreshCw className={`w-3 h-3 ${isLoadingCheckpoints ? 'animate-spin' : ''}`} />
                    Refresh Models
                  </Button>
                </div>

                {/* Model Info */}
                <div className="space-y-2 pt-4 border-t">
                  <Label className="text-sm font-semibold">About Checkpoints</Label>
                  <p className="text-xs text-muted-foreground">
                    Checkpoint models contain the neural network weights for image generation.
                    Different models produce different styles and quality levels.
                  </p>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div className="p-2 bg-muted/50 rounded">
                      <div className="font-semibold">FLUX.2</div>
                      <div className="text-muted-foreground">Best text rendering</div>
                    </div>
                    <div className="p-2 bg-muted/50 rounded">
                      <div className="font-semibold">SDXL</div>
                      <div className="text-muted-foreground">Most versatile</div>
                    </div>
                    <div className="p-2 bg-muted/50 rounded">
                      <div className="font-semibold">FireRed</div>
                      <div className="text-muted-foreground">Image editing</div>
                    </div>
                    <div className="p-2 bg-muted/50 rounded">
                      <div className="font-semibold">Z-Turbo</div>
                      <div className="text-muted-foreground">Fast preview</div>
                    </div>
                  </div>
                </div>
              </TabsContent>

              {/* Advanced Parameters Tab */}
              <TabsContent value="advanced" className="space-y-4 m-0 p-1">
                {/* Prompt */}
                <div className="space-y-2">
                  <Label className="text-sm font-semibold">Prompt *</Label>
                  <Textarea
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder="Describe the image you want to generate..."
                    rows={4}
                    className="resize-none"
                  />
                </div>

                {/* Negative Prompt */}
                <div className="space-y-2">
                  <Label className="text-sm font-semibold">Negative Prompt</Label>
                  <Textarea
                    value={negativePrompt}
                    onChange={(e) => setNegativePrompt(e.target.value)}
                    placeholder="What to avoid in the image..."
                    rows={2}
                    className="resize-none"
                  />
                </div>

                {/* Generation Parameters Grid */}
                <div className="grid grid-cols-2 gap-4">
                  {/* Steps */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <Label className="text-xs">Steps</Label>
                      <span className="text-xs text-muted-foreground">{steps}</span>
                    </div>
                    <Slider
                      value={[steps]}
                      onValueChange={([v]) => setSteps(v)}
                      min={1}
                      max={50}
                      step={1}
                    />
                  </div>

                  {/* CFG Scale */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <Label className="text-xs">CFG Scale</Label>
                      <span className="text-xs text-muted-foreground">{cfgScale}</span>
                    </div>
                    <Slider
                      value={[cfgScale]}
                      onValueChange={([v]) => setCfgScale(v)}
                      min={1}
                      max={20}
                      step={0.5}
                    />
                  </div>

                  {/* Sampler */}
                  <div className="space-y-2">
                    <Label className="text-xs">Sampler</Label>
                    <Select value={sampler} onValueChange={setSampler}>
                      <SelectTrigger className="h-8">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {SAMPLER_OPTIONS.slice(0, 15).map((s) => (
                          <SelectItem key={s} value={s}>{s}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {/* Scheduler */}
                  <div className="space-y-2">
                    <Label className="text-xs">Scheduler</Label>
                    <Select value={scheduler} onValueChange={setScheduler}>
                      <SelectTrigger className="h-8">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {SCHEDULER_OPTIONS.map((s) => (
                          <SelectItem key={s} value={s}>{s}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Seed */}
                <div className="space-y-2 pt-2">
                  <div className="flex items-center justify-between">
                    <Label className="text-sm font-semibold">Seed</Label>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-muted-foreground">Random</span>
                      <Switch
                        checked={!useRandomSeed}
                        onCheckedChange={(checked) => setUseRandomSeed(!checked)}
                      />
                    </div>
                  </div>
                  {!useRandomSeed && (
                    <Input
                      type="number"
                      value={seed || 0}
                      onChange={(e) => setSeed(parseInt(e.target.value) || 0)}
                      className="h-8"
                      placeholder="Enter seed value..."
                    />
                  )}
                </div>
              </TabsContent>
            </ScrollArea>
          </Tabs>

          {/* Generated Image Preview */}
          {generatedImageUrl && (
            <div className="p-3 bg-muted/30 rounded-md">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-green-500" />
                <span className="text-sm font-semibold">Generated Image</span>
              </div>
              <div className="relative aspect-video bg-black rounded-md overflow-hidden">
                <img 
                  src={generatedImageUrl} 
                  alt="Generated" 
                  className="w-full h-full object-contain"
                />
              </div>
            </div>
          )}

          {/* Progress Bar */}
          {isGenerating && (
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs">
                <span className="flex items-center gap-1">
                  <Loader2 className="w-3 h-3 animate-spin" />
                  Generating...
                </span>
                <span>{Math.round(generationProgress)}%</span>
              </div>
              <div className="w-full bg-muted rounded-full h-2">
                <div 
                  className="bg-primary h-2 rounded-full transition-all"
                  style={{ width: `${generationProgress}%` }}
                />
              </div>
            </div>
          )}

          <DialogFooter className="mt-4">
            <Button 
              variant="outline" 
              onClick={handleClose}
              disabled={isGenerating}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleGenerate}
              disabled={isGenerating || !prompt.trim()}
              className="gap-2"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Generating...
                </>
              ) : (
                <>
                  <Sparkles className="w-4 h-4" />
                  Generate Image
                </>
              )}
            </Button>

          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

export default ImageGenerationModal;

