/**
 * ReferenceSheetManager
 * UI component for managing master reference sheets, character appearances, and location appearances
 */

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Tabs,
  Tab,
  Grid,
  Card,
  CardContent,
  CardMedia,
  IconButton,
  TextField,
  Chip,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Avatar,
  FormControl,
  InputLabel,
  Select,
  SelectChangeEvent,
  MenuItem,
  Alert,
  Dialog as ConfirmDialog,
} from '@mui/material';
import {
  Add,
  Delete,
  Image,
  Person,
  LocationOn,
  Style,
  PhotoCamera,
  Palette,
  LightMode,
  CameraAlt,
} from '@mui/icons-material';
import {
  referenceSheetService,
} from '../../services/referenceSheetService';
import type {
  MasterReferenceSheet,
  CharacterAppearanceSheet,
  LocationAppearanceSheet,
  ObjectAppearanceSheet,
  GlobalStyleSheet,
  ReferenceImage,
  AppearanceImage,
} from '../../types/reference';
import { WorkflowDestinationDialog } from './WorkflowDestinationDialog';
import {
  Category,
  Settings,
  SmartToy,
  AutoFixHigh,
  AutoMode
} from '@mui/icons-material';

// ============================================================================
// Types
// ============================================================================

interface ReferenceSheetManagerProps {
  open: boolean;
  onClose: () => void;
  projectId: string;
  projectPath?: string;
  onSheetUpdate?: (sheetId: string) => void;
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

// ============================================================================
// Tab Panel Component
// ============================================================================

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div role="tabpanel" hidden={value !== index} {...other}>
      {value === index && <Box sx={{ p: 2 }}>{children}</Box>}
    </div>
  );
}

// ============================================================================
// ReferenceSheetManager Component
// ============================================================================

export const ReferenceSheetManager: React.FC<ReferenceSheetManagerProps> = ({
  open,
  onClose,
  projectId,
  projectPath = '',
  onSheetUpdate,
}: ReferenceSheetManagerProps) => {
  const [tabValue, setTabValue] = useState<number>(0);
  const [masterSheet, setMasterSheet] = useState<MasterReferenceSheet | null>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<CharacterAppearanceSheet | null>(null);
  const [selectedLocation, setSelectedLocation] = useState<LocationAppearanceSheet | null>(null);
  const [selectedObject, setSelectedObject] = useState<ObjectAppearanceSheet | null>(null);
  const [workflowDialog, setWorkflowDialog] = useState<{
    open: boolean;
    entityId: string;
    entityName: string;
    entityType: 'Character' | 'Location' | 'Object' | 'Style';
    currentWorkflowId?: string;
  }>({
    open: false,
    entityId: '',
    entityName: '',
    entityType: 'Character',
  });
  const [deleteConfirm, setDeleteConfirm] = useState<{ open: boolean; type: string; id: string }>({
    open: false,
    type: '',
    id: '',
  });
  const [loading, setLoading] = useState(false);

  // Initialize service and load master sheet
  useEffect(() => {
    if (open && projectId) {
      loadMasterSheet();
    }
  }, [open, projectId, projectPath]);

  const loadMasterSheet = async () => {
    setLoading(true);
    try {
      // Initialize the service with project path
      if (projectPath) {
        await referenceSheetService.initialize(projectPath);
      }

      // Try to get existing or create new
      let sheet = await referenceSheetService.getMasterReferenceSheet(projectId);

      if (!sheet) {
        sheet = await referenceSheetService.createMasterReferenceSheet(projectId);
      }

      setMasterSheet(sheet);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to load master sheet:', error);
    } finally {
      setLoading(false);
    }
  };

  // Handle tab change
  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  // Add character appearance
  const handleAddCharacter = async () => {
    if (!masterSheet) return;
    setLoading(true);
    try {
      const newCharacter: CharacterAppearanceSheet = {
        id: `char_${Date.now()}`,
        characterId: `char_def_${Date.now()}`,
        characterName: 'New Character',
        appearanceImages: [],
        styleGuidelines: [],
        colorPalette: [],
        proportions: 'anime standard',
      };

      await referenceSheetService.addCharacterAppearance(masterSheet.id, newCharacter);
      await loadMasterSheet();
      setSelectedCharacter(newCharacter);
      onSheetUpdate?.(newCharacter.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to add character:', error);
    } finally {
      setLoading(false);
    }
  };

  // Add location appearance
  const handleAddLocation = async () => {
    if (!masterSheet) return;
    setLoading(true);
    try {
      const newLocation: LocationAppearanceSheet = {
        id: `loc_${Date.now()}`,
        locationId: `loc_def_${Date.now()}`,
        locationName: 'New Location',
        referenceImages: [],
        environmentalGuidelines: [],
      };

      await referenceSheetService.addLocationAppearance(masterSheet.id, newLocation);
      await loadMasterSheet();
      setSelectedLocation(newLocation);
      onSheetUpdate?.(newLocation.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to add location:', error);
    } finally {
      setLoading(false);
    }
  };

  // Add object appearance
  const handleAddObject = async () => {
    if (!masterSheet) return;
    setLoading(true);
    try {
      const newObject: ObjectAppearanceSheet = {
        id: `obj_app_${Date.now()}`,
        objectId: `obj_def_${Date.now()}`,
        objectName: 'New Object',
        referenceImages: [],
        materialGuidelines: [],
      };

      await referenceSheetService.addObjectAppearance(masterSheet.id, newObject);
      await loadMasterSheet();
      setSelectedObject(newObject);
      onSheetUpdate?.(newObject.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to add object:', error);
    } finally {
      setLoading(false);
    }
  };

  // Update object
  const handleUpdateObject = async (object: ObjectAppearanceSheet) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.updateObjectAppearance(masterSheet.id, object);
      await loadMasterSheet();
      onSheetUpdate?.(object.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to update object:', error);
    }
  };

  // Delete object
  const handleDeleteObject = async (objectId: string) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.removeObjectAppearance(masterSheet.id, objectId);
      await loadMasterSheet();
      setSelectedObject(null);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to delete object:', error);
    }
  };

  // Update character
  const handleUpdateCharacter = async (character: CharacterAppearanceSheet) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.updateCharacterAppearance(masterSheet.id, character);
      await loadMasterSheet();
      onSheetUpdate?.(character.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to update character:', error);
    }
  };

  // Update location
  const handleUpdateLocation = async (location: LocationAppearanceSheet) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.updateLocationAppearance(masterSheet.id, location);
      await loadMasterSheet();
      onSheetUpdate?.(location.id);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to update location:', error);
    }
  };

  // Delete character
  const handleDeleteCharacter = async (characterId: string) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.removeCharacterAppearance(masterSheet.id, characterId);
      await loadMasterSheet();
      setSelectedCharacter(null);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to delete character:', error);
    }
  };

  // Delete location
  const handleDeleteLocation = async (locationId: string) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.removeLocationAppearance(masterSheet.id, locationId);
      await loadMasterSheet();
      setSelectedLocation(null);
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to delete location:', error);
    }
  };

  // Update style
  const handleUpdateStyle = async (style: Partial<GlobalStyleSheet>) => {
    if (!masterSheet) return;
    try {
      await referenceSheetService.updateGlobalStyle(masterSheet.id, {
        ...masterSheet.styleSheet,
        ...style,
      });
      await loadMasterSheet();
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to update style:', error);
    }
  };

  // Handle workflow selection
  const handleWorkflowSelect = async (workflowId: string) => {
    if (!masterSheet) return;

    const { entityId, entityType } = workflowDialog;

    try {
      if (entityType === 'Character') {
        const char = masterSheet.characterSheets.find(c => c.id === entityId);
        if (char) {
          await handleUpdateCharacter({ ...char, workflowId });
          if (selectedCharacter?.id === char.id) {
            setSelectedCharacter({ ...selectedCharacter, workflowId });
          }
        }
      } else if (entityType === 'Location') {
        const loc = masterSheet.locationSheets.find(l => l.id === entityId);
        if (loc) {
          await handleUpdateLocation({ ...loc, workflowId });
          if (selectedLocation?.id === loc.id) {
            setSelectedLocation({ ...selectedLocation, workflowId });
          }
        }
      } else if (entityType === 'Object') {
        const obj = masterSheet.objectSheets.find(o => o.id === entityId);
        if (obj) {
          await handleUpdateObject({ ...obj, workflowId });
          if (selectedObject?.id === obj.id) {
            setSelectedObject({ ...selectedObject, workflowId });
          }
        }
      } else if (entityType === 'Style') {
        await handleUpdateStyle({ workflowId });
      }
    } catch (error) {
      console.error('[ReferenceSheetManager] Failed to update workflow:', error);
    }
  };

  // Add reference image to character
  const handleAddCharacterImage = async () => {
    if (!selectedCharacter) return;
    const url = prompt('Enter image URL:');
    if (url) {
      const newImage: AppearanceImage = {
        id: `img_${Date.now()}`,
        url,
        viewType: 'portrait',
        description: '',
      };
      await handleUpdateCharacter({
        ...selectedCharacter,
        appearanceImages: [...selectedCharacter.appearanceImages, newImage],
      });
    }
  };

  // Add reference image to location
  const handleAddLocationImage = async () => {
    if (!selectedLocation) return;
    const url = prompt('Enter image URL:');
    if (url) {
      const newImage: ReferenceImage = {
        id: `img_${Date.now()}`,
        url,
        weight: 0.8,
        source: 'environment',
      };
      await handleUpdateLocation({
        ...selectedLocation,
        referenceImages: [...selectedLocation.referenceImages, newImage],
      });
    }
  };

  // Add reference image to object
  const handleAddObjectImage = async () => {
    if (!selectedObject) return;
    const url = prompt('Enter image URL:');
    if (url) {
      const newImage: ReferenceImage = {
        id: `img_${Date.now()}`,
        url,
        weight: 0.8,
        source: 'visual-style',
      };
      await handleUpdateObject({
        ...selectedObject,
        referenceImages: [...selectedObject.referenceImages, newImage],
      });
    }
  };

  // Handle art style change
  const handleArtStyleChange = (event: SelectChangeEvent<string>) => {
    handleUpdateStyle({ artStyle: event.target.value });
  };

  // Handle lighting style change
  const handleLightingStyleChange = (event: SelectChangeEvent<string>) => {
    handleUpdateStyle({ lightingStyle: event.target.value });
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Style color="primary" />
          <Typography variant="h6">Reference Sheet Manager</Typography>
          {masterSheet && (
            <Chip
              size="small"
              label={`${masterSheet.characterSheets.length} Characters • ${masterSheet.locationSheets.length} Locations • ${masterSheet.objectSheets?.length || 0} Objects`}
              sx={{ ml: 2 }}
            />
          )}
        </Box>
      </DialogTitle>

      <DialogContent dividers>
        {loading && !masterSheet ? (
          <Box sx={{ textAlign: 'center', py: 4 }}>
            <Typography color="text.secondary">Loading reference sheets...</Typography>
          </Box>
        ) : !masterSheet ? (
          <Alert severity="error">Failed to load master sheet</Alert>
        ) : (
          <>
            <Tabs value={tabValue} onChange={handleTabChange} sx={{ mb: 2 }}>
              <Tab label="Characters" icon={<Person />} iconPosition="start" />
              <Tab label="Locations" icon={<LocationOn />} iconPosition="start" />
              <Tab label="Objects" icon={<Category />} iconPosition="start" />
              <Tab label="Style" icon={<Palette />} iconPosition="start" />
              <Tab label="Overview" icon={<Style />} iconPosition="start" />
            </Tabs>

            {/* Tab 1: Characters */}
            <TabPanel value={tabValue} index={0}>
              <Grid container spacing={2}>
                <Grid size={{ xs: 12, md: 5 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="subtitle1" fontWeight="bold">
                      Character Appearances
                    </Typography>
                    <Button size="small" startIcon={<Add />} onClick={handleAddCharacter}>
                      Add
                    </Button>
                  </Box>
                  <List sx={{ maxHeight: 400, overflow: 'auto' }}>
                    {masterSheet.characterSheets.map((character) => (
                      <ListItemButton
                        key={character.id}
                        selected={selectedCharacter?.id === character.id}
                        onClick={() => setSelectedCharacter(character)}
                        sx={{
                          border: 1,
                          borderColor: selectedCharacter?.id === character.id ? 'primary.main' : 'divider',
                          borderRadius: 1,
                          mb: 1,
                        }}
                      >
                        <ListItemIcon>
                          <Avatar sx={{ bgcolor: 'primary.main' }}>
                            {character.characterName.charAt(0)}
                          </Avatar>
                        </ListItemIcon>
                        <ListItemText
                          primary={character.characterName}
                          secondary={`${character.appearanceImages.length} images`}
                        />
                        <IconButton
                          size="small"
                          onClick={(e: React.MouseEvent) => {
                            e.stopPropagation();
                            setDeleteConfirm({ open: true, type: 'character', id: character.id });
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </ListItemButton>
                    ))}
                  </List>
                </Grid>

                <Grid size={{ xs: 12, md: 7 }}>
                  {selectedCharacter ? (
                    <Card>
                      <CardContent>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                          <Typography variant="subtitle1" fontWeight="bold">
                            Edit Character
                          </Typography>
                          <Button
                            variant="outlined"
                            size="small"
                            startIcon={<Settings />}
                            onClick={() => setWorkflowDialog({
                              open: true,
                              entityId: selectedCharacter.id,
                              entityName: selectedCharacter.characterName,
                              entityType: 'Character',
                              currentWorkflowId: selectedCharacter.workflowId
                            })}
                          >
                            Workflow: {selectedCharacter.workflowId || 'Default'}
                          </Button>
                        </Box>

                        <TextField
                          fullWidth
                          label="Character Name"
                          value={selectedCharacter.characterName}
                          onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleUpdateCharacter({
                            ...selectedCharacter,
                            characterName: e.target.value,
                          })}
                          sx={{ mb: 2 }}
                        />

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Style Guidelines
                        </Typography>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                          {selectedCharacter.styleGuidelines.map((guideline: string, index: number) => (
                            <Chip
                              key={index}
                              label={guideline}
                              onDelete={() => {
                                const newGuidelines = selectedCharacter.styleGuidelines.filter(
                                  (_: string, i: number) => i !== index
                                );
                                handleUpdateCharacter({
                                  ...selectedCharacter,
                                  styleGuidelines: newGuidelines,
                                });
                              }}
                            />
                          ))}
                          <Chip label="+ Add" onClick={() => {
                            const guideline = prompt('Enter style guideline:');
                            if (guideline) {
                              handleUpdateCharacter({
                                ...selectedCharacter,
                                styleGuidelines: [...selectedCharacter.styleGuidelines, guideline],
                              });
                            }
                          }} />
                        </Box>

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Color Palette
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
                          {selectedCharacter.colorPalette.map((color: string, index: number) => (
                            <Box
                              key={index}
                              sx={{
                                width: 40,
                                height: 40,
                                bgcolor: color,
                                borderRadius: 1,
                                border: 1,
                                borderColor: 'divider',
                                cursor: 'pointer',
                              }}
                              onClick={() => {
                                const newPalette = selectedCharacter.colorPalette.filter(
                                  (_: string, i: number) => i !== index
                                );
                                handleUpdateCharacter({
                                  ...selectedCharacter,
                                  colorPalette: newPalette,
                                });
                              }}
                            />
                          ))}
                          <Chip label="+ Add Color" onClick={() => {
                            const color = prompt('Enter color hex (e.g., #FF6B6B):');
                            if (color && /^#[0-9A-Fa-f]{6}$/.test(color)) {
                              handleUpdateCharacter({
                                ...selectedCharacter,
                                colorPalette: [...selectedCharacter.colorPalette, color],
                              });
                            }
                          }} />
                        </Box>

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Appearance Images ({selectedCharacter.appearanceImages.length})
                        </Typography>
                        <Grid container spacing={1}>
                          {selectedCharacter.appearanceImages.map((image: AppearanceImage) => (
                            <Grid size={{ xs: 4 }} key={image.id}>
                              <Card>
                                <CardMedia
                                  component="img"
                                  height={100}
                                  image={image.url}
                                  sx={{ objectFit: 'cover' }}
                                />
                              </Card>
                            </Grid>
                          ))}
                          <Grid size={{ xs: 4 }}>
                            <Card sx={{
                              height: 100,
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              border: 2,
                              borderStyle: 'dashed',
                              borderColor: 'divider',
                              cursor: 'pointer',
                            }}
                              onClick={handleAddCharacterImage}
                            >
                              <PhotoCamera color="action" />
                            </Card>
                          </Grid>
                        </Grid>
                      </CardContent>
                    </Card>
                  ) : (
                    <Alert severity="info">
                      Select a character to edit or add a new one
                    </Alert>
                  )}
                </Grid>
              </Grid>
            </TabPanel>

            {/* Tab 2: Locations */}
            <TabPanel value={tabValue} index={1}>
              <Grid container spacing={2}>
                <Grid size={{ xs: 12, md: 5 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="subtitle1" fontWeight="bold">
                      Location Appearances
                    </Typography>
                    <Button size="small" startIcon={<Add />} onClick={handleAddLocation}>
                      Add
                    </Button>
                  </Box>
                  <List sx={{ maxHeight: 400, overflow: 'auto' }}>
                    {masterSheet.locationSheets.map((location) => (
                      <ListItemButton
                        key={location.id}
                        selected={selectedLocation?.id === location.id}
                        onClick={() => setSelectedLocation(location)}
                        sx={{
                          border: 1,
                          borderColor: selectedLocation?.id === location.id ? 'primary.main' : 'divider',
                          borderRadius: 1,
                          mb: 1,
                        }}
                      >
                        <ListItemIcon>
                          <Avatar sx={{ bgcolor: 'secondary.main' }}>
                            <LocationOn />
                          </Avatar>
                        </ListItemIcon>
                        <ListItemText
                          primary={location.locationName}
                          secondary={`${location.referenceImages.length} images`}
                        />
                        <IconButton
                          size="small"
                          onClick={(e: React.MouseEvent) => {
                            e.stopPropagation();
                            setDeleteConfirm({ open: true, type: 'location', id: location.id });
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </ListItemButton>
                    ))}
                  </List>
                </Grid>

                <Grid size={{ xs: 12, md: 7 }}>
                  {selectedLocation ? (
                    <Card>
                      <CardContent>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                          <Typography variant="subtitle1" fontWeight="bold">
                            Edit Location
                          </Typography>
                          <Button
                            variant="outlined"
                            size="small"
                            startIcon={<Settings />}
                            onClick={() => setWorkflowDialog({
                              open: true,
                              entityId: selectedLocation.id,
                              entityName: selectedLocation.locationName,
                              entityType: 'Location',
                              currentWorkflowId: selectedLocation.workflowId
                            })}
                          >
                            Workflow: {selectedLocation.workflowId || 'Default'}
                          </Button>
                        </Box>

                        <TextField
                          fullWidth
                          label="Location Name"
                          value={selectedLocation.locationName}
                          onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleUpdateLocation({
                            ...selectedLocation,
                            locationName: e.target.value,
                          })}
                          sx={{ mb: 2 }}
                        />

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Environmental Guidelines
                        </Typography>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                          {selectedLocation.environmentalGuidelines.map((guideline: string, index: number) => (
                            <Chip
                              key={index}
                              label={guideline}
                              onDelete={() => {
                                const newGuidelines = selectedLocation.environmentalGuidelines.filter(
                                  (_: string, i: number) => i !== index
                                );
                                handleUpdateLocation({
                                  ...selectedLocation,
                                  environmentalGuidelines: newGuidelines,
                                });
                              }}
                            />
                          ))}
                          <Chip label="+ Add" onClick={() => {
                            const guideline = prompt('Enter environmental guideline:');
                            if (guideline) {
                              handleUpdateLocation({
                                ...selectedLocation,
                                environmentalGuidelines: [...selectedLocation.environmentalGuidelines, guideline],
                              });
                            }
                          }} />
                        </Box>

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Reference Images ({selectedLocation.referenceImages.length})
                        </Typography>
                        <Grid container spacing={1}>
                          {selectedLocation.referenceImages.map((image: ReferenceImage) => (
                            <Grid size={{ xs: 4 }} key={image.id}>
                              <Card>
                                <CardMedia
                                  component="img"
                                  height={100}
                                  image={image.url}
                                  sx={{ objectFit: 'cover' }}
                                />
                              </Card>
                            </Grid>
                          ))}
                          <Grid size={{ xs: 4 }}>
                            <Card sx={{
                              height: 100,
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              border: 2,
                              borderStyle: 'dashed',
                              borderColor: 'divider',
                              cursor: 'pointer',
                            }}
                              onClick={handleAddLocationImage}
                            >
                              <PhotoCamera color="action" />
                            </Card>
                          </Grid>
                        </Grid>
                      </CardContent>
                    </Card>
                  ) : (
                    <Alert severity="info">
                      Select a location to edit or add a new one
                    </Alert>
                  )}
                </Grid>
              </Grid>
            </TabPanel>

            {/* Tab 3: Objects */}
            <TabPanel value={tabValue} index={2}>
              <Grid container spacing={2}>
                <Grid size={{ xs: 12, md: 5 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="subtitle1" fontWeight="bold">
                      Object Appearances
                    </Typography>
                    <Button size="small" startIcon={<Add />} onClick={handleAddObject}>
                      Add
                    </Button>
                  </Box>
                  <List sx={{ maxHeight: 400, overflow: 'auto' }}>
                    {(masterSheet.objectSheets || []).map((object) => (
                      <ListItemButton
                        key={object.id}
                        selected={selectedObject?.id === object.id}
                        onClick={() => setSelectedObject(object)}
                        sx={{
                          border: 1,
                          borderColor: selectedObject?.id === object.id ? 'primary.main' : 'divider',
                          borderRadius: 1,
                          mb: 1,
                        }}
                      >
                        <ListItemIcon>
                          <Avatar sx={{ bgcolor: 'warning.main' }}>
                            <Category />
                          </Avatar>
                        </ListItemIcon>
                        <ListItemText
                          primary={object.objectName}
                          secondary={`${object.referenceImages?.length || 0} images`}
                        />
                        <IconButton
                          size="small"
                          onClick={(e: React.MouseEvent) => {
                            e.stopPropagation();
                            setDeleteConfirm({ open: true, type: 'object', id: object.id });
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </ListItemButton>
                    ))}
                  </List>
                </Grid>

                <Grid size={{ xs: 12, md: 7 }}>
                  {selectedObject ? (
                    <Card>
                      <CardContent>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                          <Typography variant="subtitle1" fontWeight="bold">
                            Edit Object
                          </Typography>
                          <Button
                            variant="outlined"
                            size="small"
                            startIcon={<Settings />}
                            onClick={() => setWorkflowDialog({
                              open: true,
                              entityId: selectedObject.id,
                              entityName: selectedObject.objectName,
                              entityType: 'Object',
                              currentWorkflowId: selectedObject.workflowId
                            })}
                          >
                            Workflow: {selectedObject.workflowId || 'Default'}
                          </Button>
                        </Box>

                        <TextField
                          fullWidth
                          label="Object Name"
                          value={selectedObject.objectName}
                          onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleUpdateObject({
                            ...selectedObject,
                            objectName: e.target.value,
                          })}
                          sx={{ mb: 2 }}
                        />

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Material & Visual Guidelines
                        </Typography>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                          {selectedObject.materialGuidelines?.map((guideline: string, index: number) => (
                            <Chip
                              key={index}
                              label={guideline}
                              onDelete={() => {
                                const newGuidelines = selectedObject.materialGuidelines.filter(
                                  (_: string, i: number) => i !== index
                                );
                                handleUpdateObject({
                                  ...selectedObject,
                                  materialGuidelines: newGuidelines,
                                });
                              }}
                            />
                          ))}
                          <Chip label="+ Add" onClick={() => {
                            const guideline = prompt('Enter material guideline:');
                            if (guideline) {
                              handleUpdateObject({
                                ...selectedObject,
                                materialGuidelines: [...(selectedObject.materialGuidelines || []), guideline],
                              });
                            }
                          }} />
                        </Box>

                        <Typography variant="body2" color="text.secondary" gutterBottom>
                          Reference Images ({selectedObject.referenceImages?.length || 0})
                        </Typography>
                        <Grid container spacing={1}>
                          {selectedObject.referenceImages?.map((image: ReferenceImage) => (
                            <Grid size={{ xs: 4 }} key={image.id}>
                              <Card>
                                <CardMedia
                                  component="img"
                                  height={100}
                                  image={image.url}
                                  sx={{ objectFit: 'cover' }}
                                />
                              </Card>
                            </Grid>
                          ))}
                          <Grid size={{ xs: 4 }}>
                            <Card sx={{
                              height: 100,
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              border: 2,
                              borderStyle: 'dashed',
                              borderColor: 'divider',
                              cursor: 'pointer',
                            }}
                              onClick={handleAddObjectImage}
                            >
                              <PhotoCamera color="action" />
                            </Card>
                          </Grid>
                        </Grid>
                      </CardContent>
                    </Card>
                  ) : (
                    <Alert severity="info">
                      Select an object to edit or add a new one
                    </Alert>
                  )}
                </Grid>
              </Grid>
            </TabPanel>

            {/* Tab 4: Style */}
            <TabPanel value={tabValue} index={3}>
              <Grid container spacing={3}>
                <Grid size={{ xs: 12, md: 6 }}>
                  <Card>
                    <CardContent>
                      <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                        <Palette sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                        Art Style
                      </Typography>
                      <FormControl fullWidth sx={{ mb: 2 }}>
                        <InputLabel>Art Style</InputLabel>
                        <Select
                          value={masterSheet.styleSheet.artStyle}
                          label="Art Style"
                          onChange={handleArtStyleChange}
                        >
                          <MenuItem value="anime">Anime</MenuItem>
                          <MenuItem value="realistic">Realistic</MenuItem>
                          <MenuItem value="cartoon">Cartoon</MenuItem>
                          <MenuItem value="watercolor">Watercolor</MenuItem>
                          <MenuItem value="oil-painting">Oil Painting</MenuItem>
                          <MenuItem value="sketch">Sketch</MenuItem>
                        </Select>
                      </FormControl>
                    </CardContent>
                  </Card>
                </Grid>

                <Grid size={{ xs: 12, md: 6 }}>
                  <Card>
                    <CardContent>
                      <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                        <LightMode sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                        Lighting Style
                      </Typography>
                      <FormControl fullWidth sx={{ mb: 2 }}>
                        <InputLabel>Lighting Style</InputLabel>
                        <Select
                          value={masterSheet.styleSheet.lightingStyle}
                          label="Lighting Style"
                          onChange={handleLightingStyleChange}
                        >
                          <MenuItem value="natural">Natural</MenuItem>
                          <MenuItem value="dramatic">Dramatic</MenuItem>
                          <MenuItem value="cinematic">Cinematic</MenuItem>
                          <MenuItem value="soft">Soft</MenuItem>
                          <MenuItem value="high-contrast">High Contrast</MenuItem>
                          <MenuItem value="neon">Neon</MenuItem>
                        </Select>
                      </FormControl>
                    </CardContent>
                  </Card>
                </Grid>

                <Grid size={12}>
                  <Card>
                    <CardContent>
                      <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                        <Palette sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                        Global Color Palette
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                        {masterSheet.styleSheet.colorPalette.map((color: string, index: number) => (
                          <Box
                            key={index}
                            sx={{
                              width: 60,
                              height: 60,
                              bgcolor: color,
                              borderRadius: 1,
                              border: 2,
                              borderColor: 'divider',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                            }}
                          >
                            <Typography variant="caption" sx={{ color: 'white', textShadow: '0 0 3px black' }}>
                              {color}
                            </Typography>
                          </Box>
                        ))}
                        <Button
                          variant="outlined"
                          onClick={() => {
                            const color = prompt('Enter color hex:');
                            if (color && /^#[0-9A-Fa-f]{6}$/.test(color)) {
                              handleUpdateStyle({
                                colorPalette: [...masterSheet.styleSheet.colorPalette, color],
                              });
                            }
                          }}
                        >
                          Add Color
                        </Button>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>

                <Grid size={12}>
                  <Card>
                    <CardContent>
                      <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                        <CameraAlt sx={{ verticalAlign: 'middle', mr: 0.5 }} />
