        cameraMovement: 'static',
      },
      {
        id: 'shot_nh_2',
        startTime: 8,
        endTime: 16,
        duration: 8,
        composition: {
          ruleOfThirds: false,
          centerComposition: true,
          leadingLines: [],
          framing: 'medium',
          aspectRatio: '16:9',
        },
        cameraMovement: 'static',
      },
      {
        id: 'shot_nh_3',
        startTime: 16,
        endTime: 25,
        duration: 9,
        composition: {
          ruleOfThirds: true,
          centerComposition: false,
          leadingLines: [],
          framing: 'close-up',
          aspectRatio: '16:9',
        },
        cameraMovement: 'static',
      },
    ],
    transitions: [],
    keyframeCount: 3,
    sceneChanges: [
      { timestamp: 8, confidence: 0.93 },
      { timestamp: 16, confidence: 0.89 },
    ],
  },
  digitalHumanAnalysis: mockDigitalHumanAnalysisNoHuman,
};

// ============================================================================
// Storybook Configuration
// ============================================================================

const meta = {
  title: 'Reference/VideoReplicationDialog',
  component: VideoReplicationDialog,
  parameters: {
    layout: 'fullscreen',
    docs: {
      description: {
        component: 'UI component for uploading reference videos and configuring replication settings.',
      },
    },
  },
  tags: ['autodocs'],
  argTypes: {
    open: {
      control: 'boolean',
      description: 'Controls whether the dialog is open',
