        )}
        {onDelete && (
          <button
            className="location-transform-control__action location-transform-control__action--delete"
            onClick={onDelete}
            title="Delete"
          >
            <Trash2 size={14} />
          </button>
        )}
      </div>
    </div>
  );
}

