/**
 * Service Status Banner Component
 * 
 * Displays connection status for Ollama (LLM) and ComfyUI services.
 * Provides clear feedback and quick configuration options when services are unavailable.
 * 
 * Requirements: Service availability check for wizards that require LLM/ComfyUI
 */

import React, { useState, useEffect } from 'react';
import { useServiceStatus, ServiceStatus } from '@/hooks/useServiceStatus';
import { AlertCircle, CheckCircle, Settings, Loader2, ExternalLink, RefreshCw } from 'lucide-react';

export interface ServiceRequirement {
  service: 'ollama' | 'comfyui';
  required: boolean;
  description: string;
  configUrl?: string;
}

export interface ServiceStatusBannerProps {
  requirements: ServiceRequirement[];
  onConfigure?: (service: 'ollama' | 'comfyui') => void;
  onRetry?: () => void;
  showDetails?: boolean;
  variant?: 'banner' | 'card' | 'inline';
}

// Map service names to display names
const SERVICE_NAMES: Record<string, string> = {
  ollama: 'Ollama (LLM)',
  comfyui: 'ComfyUI',
};

// Map service names to setup instructions
const SERVICE_SETUP_INSTRUCTIONS: Record<string, string> = {
  ollama: 'Download Ollama from ollama.com and run: ollama serve',
  comfyui: 'Ensure ComfyUI is running and the server URL is configured in settings.',
};

/**
 * Get status icon and color based on service status
 */
function getStatusConfig(status: ServiceStatus): {
  icon: React.ReactNode;
  color: string;
  text: string;
} {
  switch (status) {
    case 'connected':
      return {
        icon: <CheckCircle className="w-4 h-4" />,
        color: 'text-green-500',
        text: 'Connected',
      };
    case 'disconnected':
      return {
        icon: <AlertCircle className="w-4 h-4" />,
        color: 'text-red-500',
        text: 'Not connected',
      };
    case 'checking':
      return {
        icon: <Loader2 className="w-4 h-4 animate-spin" />,
        color: 'text-yellow-500',
        text: 'Checking...',
      };
  }
}

/**
 * Service status badge component
 */
interface ServiceBadgeProps {
  service: string;
  status: ServiceStatus;
  required: boolean;
  onConfigure?: () => void;
  showDetails?: boolean;
}

function ServiceBadge({
  service,
  status,
  required,
  onConfigure,
  showDetails,
}: ServiceBadgeProps) {
  const { icon, color, text } = getStatusConfig(status);
  const isAvailable = status === 'connected';
  const showWarning = status === 'disconnected' && required;

  return (
    <div
      className={`
        flex items-center gap-2 px-3 py-2 rounded-lg border
        ${showWarning 
          ? 'border-red-200 bg-red-50' 
          : 'border-gray-200 bg-white'
        }
      `}
    >
      <span className={color}>{icon}</span>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-gray-900">
          {SERVICE_NAMES[service]}
        </p>
        {showDetails && (
          <p className={`text-xs ${color}`}>{text}</p>
        )}
      </div>
      {showWarning && onConfigure && (
        <button
          onClick={onConfigure}
          className="flex items-center gap-1 px-2 py-1 text-xs font-medium
                   text-red-700 bg-red-100 rounded hover:bg-red-200
                   transition-colors"
        >
          <Settings className="w-3 h-3" />
          Configure
        </button>
      )}
    </div>
  );
}

/**
 * Service Status Banner Component
 */
export function ServiceStatusBanner({
  requirements,
  onConfigure,
  onRetry,
  showDetails = true,
  variant = 'banner',
}: ServiceStatusBannerProps) {
  const serviceStatus = useServiceStatus();
  const [isExpanded, setIsExpanded] = useState(false);
  
  // Check all requirements
  const allConnected = requirements.every(req => 
    serviceStatus[req.service] === 'connected'
  );
  
  const missingRequired = requirements.filter(req => 
    req.required && serviceStatus[req.service] !== 'connected'
  );
  
  const isChecking = Object.values(serviceStatus).some(s => s === 'checking');

  // Auto-expand if there are missing required services
  useEffect(() => {
    if (missingRequired.length > 0) {
      setIsExpanded(true);
    }
  }, [missingRequired.length]);

  // Don't show anything if all services are connected and not checking
  if (allConnected && !isChecking) {
    return null;
  }

  const variantStyles = {
    banner: 'fixed bottom-4 right-4 z-50 max-w-md shadow-lg',
    card: 'border rounded-xl p-4',
    inline: 'inline-flex',
  };

  const content = (
    <div 
      className={`
        ${variantStyles[variant]}
        ${variant === 'banner' ? 'bg-white rounded-xl' : ''}
      `}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {isChecking ? (
            <Loader2 className="w-5 h-5 animate-spin text-blue-500" />
          ) : missingRequired.length > 0 ? (
            <AlertCircle className="w-5 h-5 text-amber-500" />
          ) : (
            <CheckCircle className="w-5 h-5 text-green-500" />
          )}
          
          <div>
            <p className="text-sm font-medium text-gray-900">
              {isChecking 
                ? 'Checking services...' 
                : missingRequired.length > 0
                  ? `${missingRequired.length} service(s) unavailable`
                  : 'All services connected'
              }
            </p>
            {variant !== 'inline' && (
              <p className="text-xs text-gray-500">
                {missingRequired.length > 0
                  ? 'Some features may be limited'
                  : 'Ready to use AI-powered features'
                }
              </p>
            )}
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          {onRetry && (
            <button
              onClick={onRetry}
              className="p-2 text-gray-500 hover:text-gray-700 
                       hover:bg-gray-100 rounded-lg transition-colors"
              title="Retry connection check"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          )}
          
          {variant !== 'inline' && (
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className="text-sm text-blue-600 hover:text-blue-700 
                       font-medium transition-colors"
            >
              {isExpanded ? 'Hide details' : 'Show details'}
            </button>
          )}
        </div>
      </div>

      {/* Expanded details */}
      {isExpanded && variant !== 'inline' && (
        <div className="mt-4 pt-4 border-t border-gray-200">
          {/* Service badges */}
          <div className="grid gap-3">
            {requirements.map(req => (
              <ServiceBadge
                key={req.service}
                service={req.service}
                status={serviceStatus[req.service]}
                required={req.required}
                onConfigure={onConfigure ? () => onConfigure(req.service) : undefined}
                showDetails={showDetails}
              />
            ))}
          </div>

          {/* Missing services info */}
          {missingRequired.length > 0 && (
            <div className="mt-4 p-3 bg-amber-50 rounded-lg">
              <p className="text-sm font-medium text-amber-900">
                Missing required services
              </p>
              <ul className="mt-2 space-y-1">
                {missingRequired.map(req => (
                  <li key={req.service} className="text-sm text-amber-800">
                    • {SERVICE_NAMES[req.service]}: {req.description}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Setup instructions link */}
          {missingRequired.length > 0 && (
            <div className="mt-4 flex items-center gap-3">
              <a
                href="https://ollama.com/download"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-sm text-blue-600 
                         hover:text-blue-700"
              >
                <ExternalLink className="w-3 h-3" />
                Download Ollama
              </a>
              <span className="text-gray-300">|</span>
              <a
                href="https://github.com/comfyanonymous/ComfyUI"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-sm text-blue-600 
                         hover:text-blue-700"
              >
                <ExternalLink className="w-3 h-3" />
                Get ComfyUI
              </a>
            </div>
          )}
        </div>
      )}

      {/* Inline variant: simple indicator */}
      {variant === 'inline' && missingRequired.length > 0 && (
        <div className="mt-2 text-xs text-amber-600">
          {missingRequired.map(r => SERVICE_NAMES[r.service]).join(', ')} unavailable
        </div>
      )}
    </div>
  );

  // For banner variant, add backdrop
  if (variant === 'banner') {
    return (
      <>
        {content}
      </>
    );
  }

  return content;
}

/**
 * Wizard-specific service requirements helper
 */
export function getWizardServiceRequirements(wizardId: string): ServiceRequirement[] {
  const requirementsMap: Record<string, ServiceRequirement[]> = {
    'project-init': [
      { service: 'ollama', required: false, description: 'For AI story generation' },
    ],
    'world-building': [
      { service: 'ollama', required: true, description: 'Required for world generation' },
    ],
    'character-creation': [
      { service: 'ollama', required: true, description: 'Required for character generation' },
      { service: 'comfyui', required: false, description: 'For image tile generation' },
    ],
    'storyteller-wizard': [
      { service: 'ollama', required: true, description: 'Required for story generation' },
    ],
    'shot-planning': [
      { service: 'ollama', required: false, description: 'For shot suggestions' },
    ],
    'shot-reference-wizard': [
      { service: 'comfyui', required: true, description: 'Required for image generation' },
    ],
    'dialogue-wizard': [
      { service: 'ollama', required: true, description: 'Required for dialogue generation' },
    ],
    'scene-generator': [
      { service: 'ollama', required: true, description: 'Required for scene generation' },
      { service: 'comfyui', required: true, description: 'Required for image generation' },
    ],
    'storyboard-creator': [
      { service: 'ollama', required: true, description: 'Required for storyboard generation' },
      { service: 'comfyui', required: true, description: 'Required for panel images' },
    ],
    'style-transfer': [
      { service: 'comfyui', required: true, description: 'Required for style transfer' },
    ],
    'marketing-wizard': [
      { service: 'ollama', required: false, description: 'For content suggestions' },
      { service: 'comfyui', required: false, description: 'For thumbnail generation' },
    ],
  };

  return requirementsMap[wizardId] || [];
}

/**
 * Component to show service status in wizard header
 */
export function WizardServiceIndicator({
  wizardId,
  onConfigure,
}: {
  wizardId: string;
  onConfigure?: (service: 'ollama' | 'comfyui') => void;
}) {
  const requirements = getWizardServiceRequirements(wizardId);
  const serviceStatus = useServiceStatus();
  
  const missingRequired = requirements.filter(req => 
    req.required && serviceStatus[req.service] !== 'connected'
  );

  if (missingRequired.length === 0) {
    return null;
  }

  return (
    <ServiceStatusBanner
      requirements={requirements}
      onConfigure={onConfigure}
      variant="inline"
    />
  );
}

/**
 * AddonSettingsModal - Modal de configuration des paramètres d'un add-on
 *
 * Permet de configurer les paramètres spécifiques à chaque add-on
 */

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { addonManager, AddonSetting } from '@/services/AddonManager';
import { Save, RotateCcw, X } from 'lucide-react';

export interface AddonSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  addonId: string;
  addonName: string;
}

export function AddonSettingsModal({ isOpen, onClose, addonId, addonName }: AddonSettingsModalProps) {
  const [settings, setSettings] = useState<Record<string, unknown>>({});
  const [settingsDefinition, setSettingsDefinition] = useState<AddonSetting[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (isOpen && addonId) {
      loadSettings();
    }
  }, [isOpen, addonId]);

  const loadSettings = () => {
    const definition = addonManager.getAddonSettingsDefinition(addonId);
    const currentSettings = addonManager.getAddonSettingsWithDefaults(addonId);

    setSettingsDefinition(definition);
    setSettings({ ...currentSettings });
    setHasChanges(false);
  };

  const handleSettingChange = (key: string, value: unknown) => {
    setSettings(prev => ({
      ...prev,
      [key]: value
    }));
    setHasChanges(true);
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      addonManager.updateAddonSettings(addonId, settings);
      setHasChanges(false);
      onClose();
    } catch (error) {
      console.error('Failed to save addon settings:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleReset = () => {
    loadSettings();
  };

  const renderSettingInput = (setting: AddonSetting) => {
    const value = settings[setting.key];

    switch (setting.type) {
      case 'boolean':
        return (
          <label className="flex items-center space-x-3">
            <input
              type="checkbox"
              checked={Boolean(value)}
              onChange={(e) => handleSettingChange(setting.key, e.target.checked)}
              className="w-4 h-4 text-purple-600 bg-gray-100 border-gray-300 rounded focus:ring-purple-500 focus:ring-2"
            />
            <span className="text-sm text-gray-700">
              {setting.description || setting.label}
            </span>
          </label>
        );

      case 'number':
        return (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">
              {setting.label}
            </label>
            <input
              type="number"
              value={value || ''}
              onChange={(e) => handleSettingChange(setting.key, parseFloat(e.target.value) || 0)}
              min={setting.min}
              max={setting.max}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
            {setting.description && (
              <p className="text-xs text-gray-500">{setting.description}</p>
            )}
          </div>
        );

      case 'text':
        return (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">
              {setting.label}
            </label>
            <input
              type="text"
              value={value || ''}
              onChange={(e) => handleSettingChange(setting.key, e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
            {setting.description && (
              <p className="text-xs text-gray-500">{setting.description}</p>
            )}
          </div>
        );

      case 'textarea':
        return (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">
              {setting.label}
            </label>
            <textarea
              value={value || ''}
              onChange={(e) => handleSettingChange(setting.key, e.target.value)}
              rows={4}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
            {setting.description && (
              <p className="text-xs text-gray-500">{setting.description}</p>
            )}
          </div>
        );

      case 'select':
        return (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">
              {setting.label}
            </label>
            <select
              value={value || ''}
              onChange={(e) => handleSettingChange(setting.key, e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            >
              {setting.options?.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            {setting.description && (
              <p className="text-xs text-gray-500">{setting.description}</p>
            )}
          </div>
        );

      default:
        return (
          <div className="text-sm text-gray-500">
            Type de paramètre non supporté: {setting.type}
          </div>
        );
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <span>Paramètres - {addonName}</span>
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto max-h-[60vh]">
          {settingsDefinition.length === 0 ? (
            <div className="text-center py-8">
              <p className="text-gray-500">
                Aucun paramètre configurable pour cet add-on.
              </p>
            </div>
          ) : (
            <div className="space-y-6">
              {settingsDefinition.map(setting => (
                <div key={setting.key} className="border-b border-gray-200 pb-6 last:border-b-0 last:pb-0">
                  {renderSettingInput(setting)}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flex justify-end gap-3 pt-4 border-t">
          <Button
            variant="outline"
            onClick={handleReset}
            disabled={!hasChanges || isSaving}
            className="flex items-center gap-2"
          >
            <RotateCcw className="w-4 h-4" />
            Réinitialiser
          </Button>

          <Button
            variant="outline"
            onClick={onClose}
            className="flex items-center gap-2"
          >
            <X className="w-4 h-4" />
            Annuler
          </Button>

          <Button
            onClick={handleSave}
            disabled={!hasChanges || isSaving}
            className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700"
          >
            {isSaving ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                Sauvegarde...
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                Sauvegarder
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * AddonsPanel - Panneau de gestion des add-ons
 *
 * Interface utilisateur pour activer/désactiver les add-ons
 */

import React, { useState, useEffect } from 'react';
import { addonManager, AddonInfo } from '@/services/AddonManager';
import {
  Puzzle,
  ToggleLeft,
  ToggleRight,
  Settings,
  AlertCircle,
  CheckCircle,
  Loader,
  Search,
  Filter,
  RefreshCw,
  Info,
  Save,
  Upload
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';

export interface AddonsPanelProps {
  className?: string;
  onOpenSettings?: (addonId: string, addonName: string) => void;
}

export function AddonsPanel({ className = '', onOpenSettings }: AddonsPanelProps) {
  const [addons, setAddons] = useState<AddonInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<AddonInfo['category'] | 'all'>('all');
  const [togglingAddon, setTogglingAddon] = useState<string | null>(null);
  const { toast } = useToast();

  useEffect(() => {
    initializeAddons();
  }, []);

  const initializeAddons = async () => {
    try {
      await addonManager.initialize();
      setAddons(addonManager.getAddons());
    } catch (error) {
      console.error('Failed to initialize add-ons:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleToggleAddon = async (addonId: string) => {
    setTogglingAddon(addonId);

    try {
      const success = await addonManager.toggleAddon(addonId);
      if (success) {
        // Rafraîchir la liste
        setAddons(addonManager.getAddons());
      } else {
        console.error('Failed to toggle addon');
      }
    } catch (error) {
      console.error('Error toggling addon:', error);
    } finally {
      setTogglingAddon(null);
    }
  };

  /**
   * Exporte la configuration des add-ons vers un fichier
   */
  const handleExportConfig = async () => {
    try {
      await addonManager.saveToFile();
      toast({
        title: 'Succès',
        description: 'Configuration sauvegardée avec succès',
        variant: 'default'
      });
    } catch (error) {
      toast({
        title: 'Erreur',
        description: `Échec de la sauvegarde: ${error.message}`,
        variant: 'destructive'
      });
    }
  };

  /**
   * Importe la configuration des add-ons depuis un fichier
   */
  const handleImportConfig = async () => {
    try {
      await addonManager.loadFromFile();
      // Rafraîchir la liste des add-ons
      setAddons(addonManager.getAddons());

      toast({
        title: 'Succès',
        description: 'Configuration restaurée avec succès',
        variant: 'default'
      });
    } catch (error) {
      toast({
        title: 'Erreur',
        description: `Échec de la restauration: ${error.message}`,
        variant: 'destructive'
      });
    }
  };

  const filteredAddons = addons.filter(addon => {
    if (!addon) return false;

    const name = addon.name || '';
    const description = addon.description || '';

    const matchesSearch = searchQuery === '' ||
      name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      addon.tags?.some(tag => tag && tag.toLowerCase().includes(searchQuery.toLowerCase()));

    const matchesCategory = selectedCategory === 'all' || addon.category === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const getStatusIcon = (addon: AddonInfo) => {
    switch (addon.status) {
      case 'active':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'inactive':
        return <ToggleLeft className="w-4 h-4 text-gray-400" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-red-500" />;
      case 'loading':
        return <Loader className="w-4 h-4 text-blue-500 animate-spin" />;
      default:
        return <ToggleLeft className="w-4 h-4 text-gray-400" />;
    }
  };

  const getStatusText = (addon: AddonInfo) => {
    switch (addon.status) {
      case 'active':
        return 'Activé';
      case 'inactive':
        return 'Désactivé';
      case 'error':
        return 'Erreur';
      case 'loading':
        return 'Chargement...';
      default:
        return 'Inconnu';
    }
  };

  const getCategoryColor = (category: AddonInfo['category']) => {
    switch (category) {
      case 'ui':
        return 'bg-blue-100 text-blue-800';
      case 'processing':
        return 'bg-green-100 text-green-800';
      case 'export':
        return 'bg-purple-100 text-purple-800';
      case 'integration':
        return 'bg-orange-100 text-orange-800';
      case 'utility':
        return 'bg-gray-100 text-gray-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const categories: Array<{ value: AddonInfo['category'] | 'all', label: string }> = [
    { value: 'all', label: 'Tous' },
    { value: 'ui', label: 'Interface' },
    { value: 'processing', label: 'Traitement' },
    { value: 'export', label: 'Export' },
    { value: 'integration', label: 'Intégration' },
    { value: 'utility', label: 'Utilitaires' }
  ];

  if (loading) {
    return (
      <div className={`p-6 ${className}`}>
        <div className="flex items-center justify-center h-64">
          <div className="flex items-center gap-2">
            <Loader className="w-6 h-6 animate-spin text-blue-500" />
            <span className="text-gray-600">Chargement des add-ons...</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-full overflow-hidden ${className}`}>
      <div className="p-6 flex flex-col h-full overflow-hidden">
        {/* Header - Fixed at top */}
        <div className="mb-6 flex-shrink-0">
          <div className="flex items-center gap-3 mb-4">
            <Puzzle className="w-6 h-6 text-purple-600" />
            <h2 className="text-xl font-semibold text-gray-900">Gestion des Add-ons</h2>
          </div>

          <p className="text-gray-600 mb-4">
            Activez ou désactivez les extensions pour personnaliser votre expérience StoryCore.
          </p>

          {/* Search and Filter */}
          <div className="flex flex-col sm:flex-row gap-4 mb-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Rechercher des add-ons..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              />
            </div>

            <div className="flex gap-2 flex-wrap">
              {categories.map(category => (
                <button
                  key={category.value}
                  onClick={() => setSelectedCategory(category.value)}
                  className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${selectedCategory === category.value
                    ? 'bg-purple-600 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                >
                  {category.label}
                </button>
              ))}
            </div>

            <Button
              variant="outline"
              size="sm"
              onClick={initializeAddons}
              className="flex items-center gap-2 flex-shrink-0"
            >
              <RefreshCw className="w-4 h-4" />
              Actualiser
            </Button>

            {/* Boutons d'export/import */}
            <div className="flex gap-2 flex-shrink-0">
              <Button
                variant="outline"
                size="sm"
                onClick={handleExportConfig}
                className="flex items-center gap-2"
                title="Exporter la configuration"
              >
                <Save className="w-4 h-4" />
                Exporter
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleImportConfig}
                className="flex items-center gap-2"
                title="Importer la configuration"
              >
                <Upload className="w-4 h-4" />
                Importer
              </Button>
            </div>
          </div>
        </div>

        {/* Stats - Fixed height */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6 flex-shrink-0">
          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total</p>
                <p className="text-2xl font-bold text-gray-900">{addons.length}</p>
              </div>
              <Puzzle className="w-8 h-8 text-gray-400" />
            </div>
          </div>

          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Activés</p>
                <p className="text-2xl font-bold text-green-600">
                  {addons.filter(a => a.enabled && a.status === 'active').length}
                </p>
              </div>
              <CheckCircle className="w-8 h-8 text-green-500" />
            </div>
          </div>

          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Désactivés</p>
                <p className="text-2xl font-bold text-gray-600">
                  {addons.filter(a => !a.enabled).length}
                </p>
              </div>
              <ToggleLeft className="w-8 h-8 text-gray-400" />
            </div>
          </div>

          <div className="bg-white p-4 rounded-lg border border-gray-200">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Erreurs</p>
                <p className="text-2xl font-bold text-red-600">
                  {addons.filter(a => a.status === 'error').length}
                </p>
              </div>
              <AlertCircle className="w-8 h-8 text-red-500" />
            </div>
          </div>
        </div>

        {/* Add-ons List - Scrollable content */}
        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="space-y-4 pb-4">
            {filteredAddons.length === 0 ? (
              <div className="text-center py-12">
                <Puzzle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">
                  Aucun add-on trouvé
                </h3>
                <p className="text-gray-600">
                  {searchQuery || selectedCategory !== 'all'
                    ? 'Essayez de modifier vos critères de recherche.'
                    : 'Aucun add-on n\'est disponible pour le moment.'}
                </p>
              </div>
            ) : (
              filteredAddons.map(addon => (
                <div
                  key={addon.id}
                  className="bg-white border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="text-lg font-semibold text-gray-900">
                          {addon.name}
                        </h3>
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(addon.category)}`}>
                          {addon.category}
                        </span>
                        {addon.builtin && (
                          <span className="px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                            Intégré
                          </span>
                        )}
                      </div>

                      <p className="text-gray-600 mb-3">{addon.description}</p>

                      <div className="flex items-center gap-4 text-sm text-gray-500 mb-3">
                        <span>Version {addon.version}</span>
                        <span>Par {addon.author}</span>
                        {addon.tags && addon.tags.length > 0 && (
                          <div className="flex gap-1">
                            {addon.tags.slice(0, 3).map(tag => (
                              <span key={tag} className="bg-gray-100 px-2 py-1 rounded text-xs">
                                {tag}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>

                      {addon.errorMessage && (
                        <div className="bg-red-50 border border-red-200 rounded p-3 mb-3">
                          <div className="flex items-center gap-2">
                            <AlertCircle className="w-4 h-4 text-red-500" />
                            <span className="text-red-700 text-sm">{addon.errorMessage}</span>
                          </div>
                        </div>
                      )}

                      <div className="flex items-center gap-2">
                        {getStatusIcon(addon)}
                        <span className="text-sm font-medium">{getStatusText(addon)}</span>
                      </div>
                    </div>

                    <div className="flex items-center gap-3 ml-6 flex-shrink-0">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onOpenSettings?.(addon.id, addon.name)}
                        className="flex items-center gap-2"
                        title="Paramètres de l'add-on"
                      >
                        <Settings className="w-4 h-4" />
                        Paramètres
                      </Button>

                      <Button
                        variant={addon.enabled ? "default" : "outline"}
                        size="sm"
                        onClick={() => handleToggleAddon(addon.id)}
                        disabled={togglingAddon === addon.id || addon.status === 'loading'}
                        className={`flex items-center gap-2 ${addon.enabled
                          ? 'bg-green-600 hover:bg-green-700'
                          : 'bg-gray-600 hover:bg-gray-700'
                          }`}
                      >
                        {togglingAddon === addon.id ? (
                          <Loader className="w-4 h-4 animate-spin" />
                        ) : addon.enabled ? (
                          <ToggleRight className="w-4 h-4" />
                        ) : (
                          <ToggleLeft className="w-4 h-4" />
                        )}
                        {addon.enabled ? 'Désactiver' : 'Activer'}
                      </Button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Help Text - Fixed at bottom */}
        <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4 flex-shrink-0">
          <div className="flex items-start gap-3">
            <Info className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" />
            <div>
              <h4 className="font-medium text-blue-900 mb-1">À propos des add-ons</h4>
              <p className="text-sm text-blue-700 mb-2">
                Les add-ons étendent les fonctionnalités de StoryCore. Les add-ons intégrés sont
                développés par l'équipe StoryCore et sont entièrement sécurisés.
              </p>
              <p className="text-sm text-blue-700">
                <strong>Note :</strong> Certains add-ons peuvent nécessiter un redémarrage de l'application
                pour être pleinement opérationnels.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

