/**
 * ComfyUI Server Modal Component
 * 
 * Modal for adding or editing a ComfyUI server
 */

import { useState, useEffect } from 'react';
import { X, Eye, EyeOff } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Switch } from '@/components/ui/switch';
import { Slider } from '@/components/ui/slider';
import { cn } from '@/lib/utils';
import type { ComfyUIServer, CreateComfyUIServerInput } from '@/types/comfyuiServers';
import type { AuthenticationType } from '@/services/comfyuiService';

export interface ComfyUIServerModalProps {
  server?: ComfyUIServer | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (input: CreateComfyUIServerInput) => void;
}

export function ComfyUIServerModal({
  server,
  isOpen,
  onClose,
  onSave,
}: ComfyUIServerModalProps) {
  const isEditing = !!server;

  // Form state
  const [name, setName] = useState('');
  const [serverUrl, setServerUrl] = useState('');
  const [authType, setAuthType] = useState<AuthenticationType>('none');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [token, setToken] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showToken, setShowToken] = useState(false);
  
  // Advanced settings
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [maxQueueSize, setMaxQueueSize] = useState(10);
  const [timeout, setTimeout] = useState(300000);
  const [vramLimit, setVramLimit] = useState<number | undefined>(undefined);
  const [modelsPath, setModelsPath] = useState('');
  const [autoStart, setAutoStart] = useState(false);

  // Validation
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Load server data when editing
  useEffect(() => {
    if (server) {
      setName(server.name);
      setServerUrl(server.serverUrl);
      setAuthType(server.authentication.type);
      setUsername(server.authentication.username || '');
      setPassword(server.authentication.password || '');
      setToken(server.authentication.token || '');
      setMaxQueueSize(server.maxQueueSize || 10);
      setTimeout(server.timeout || 300000);
      setVramLimit(server.vramLimit);
      setModelsPath(server.modelsPath || '');
      setAutoStart(server.autoStart || false);
    } else {
      // Reset form for new server
      setName('');
      setServerUrl('http://localhost:8188');
      setAuthType('none');
      setUsername('');
      setPassword('');
      setToken('');
      setMaxQueueSize(10);
      setTimeout(300000);
      setVramLimit(undefined);
      setModelsPath('');
      setAutoStart(false);
    }
    setErrors({});
    setShowAdvanced(false);
  }, [server, isOpen]);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!name.trim()) {
      newErrors.name = 'Server name is required';
    }

    if (!serverUrl.trim()) {
      newErrors.serverUrl = 'Server URL is required';
    } else {
      try {
        const url = new URL(serverUrl);
        if (!['http:', 'https:'].includes(url.protocol)) {
          newErrors.serverUrl = 'URL must use HTTP or HTTPS protocol';
        }
      } catch {
        newErrors.serverUrl = 'Invalid URL format';
      }
    }

    if (authType === 'basic') {
      if (!username.trim()) {
        newErrors.username = 'Username is required for Basic auth';
      }
      if (!password.trim()) {
        newErrors.password = 'Password is required for Basic auth';
      }
    }

    if ((authType === 'bearer' || authType === 'api-key') && !token.trim()) {
      newErrors.token = 'Token is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = () => {
    if (!validate()) return;

    const input: CreateComfyUIServerInput = {
      name: name.trim(),
      serverUrl: serverUrl.trim(),
      authentication: {
        type: authType,
        ...(authType === 'basic' && { username, password }),
        ...(authType === 'bearer' && { token }),
        ...(authType === 'api-key' && { token }),
      },
      maxQueueSize,
      timeout,
      vramLimit,
      modelsPath: modelsPath.trim() || undefined,
      autoStart,
    };

    onSave(input);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? 'Edit ComfyUI Server' : 'Add ComfyUI Server'}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Server Name */}
          <div className="space-y-2">
            <Label htmlFor="name">
              Server Name <span className="text-destructive">*</span>
            </Label>
            <Input
              id="name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Local Dev, Production, GPU Server 1"
              className={cn(errors.name && 'border-destructive')}
            />
            {errors.name && (
              <p className="text-sm text-destructive">{errors.name}</p>
            )}
          </div>

          {/* Server URL */}
          <div className="space-y-2">
            <Label htmlFor="serverUrl">
              Server URL <span className="text-destructive">*</span>
            </Label>
            <Input
              id="serverUrl"
              type="url"
              value={serverUrl}
              onChange={(e) => setServerUrl(e.target.value)}
              placeholder="http://localhost:8188"
              className={cn(errors.serverUrl && 'border-destructive')}
            />
            {errors.serverUrl && (
              <p className="text-sm text-destructive">{errors.serverUrl}</p>
            )}
          </div>

          {/* Authentication */}
          <div className="space-y-3">
            <Label>Authentication</Label>
            <RadioGroup value={authType} onValueChange={(value) => setAuthType(value as AuthenticationType)}>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="none" id="auth-none" />
                <Label htmlFor="auth-none" className="font-normal cursor-pointer">None</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="basic" id="auth-basic" />
                <Label htmlFor="auth-basic" className="font-normal cursor-pointer">Basic (Username/Password)</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="bearer" id="auth-bearer" />
                <Label htmlFor="auth-bearer" className="font-normal cursor-pointer">Bearer Token</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="api-key" id="auth-api-key" />
                <Label htmlFor="auth-api-key" className="font-normal cursor-pointer">API Key</Label>
              </div>
            </RadioGroup>

            {/* Basic Auth Fields */}
            {authType === 'basic' && (
              <div className="space-y-3 pl-6">
                <div className="space-y-2">
                  <Label htmlFor="username">Username</Label>
                  <Input
                    id="username"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className={cn(errors.username && 'border-destructive')}
                  />
                  {errors.username && (
                    <p className="text-sm text-destructive">{errors.username}</p>
                  )}
                </div>
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <div className="relative">
                    <Input
                      id="password"
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className={cn(errors.password && 'border-destructive')}
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3"
                      onClick={() => setShowPassword(!showPassword)}
                    >
                      {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </Button>
                  </div>
                  {errors.password && (
                    <p className="text-sm text-destructive">{errors.password}</p>
                  )}
                </div>
              </div>
            )}

            {/* Token Fields */}
            {(authType === 'bearer' || authType === 'api-key') && (
              <div className="space-y-2 pl-6">
                <Label htmlFor="token">Token</Label>
                <div className="relative">
                  <Input
                    id="token"
                    type={showToken ? 'text' : 'password'}
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                    className={cn(errors.token && 'border-destructive')}
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="absolute right-0 top-0 h-full px-3"
                    onClick={() => setShowToken(!showToken)}
                  >
                    {showToken ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </Button>
                </div>
                {errors.token && (
                  <p className="text-sm text-destructive">{errors.token}</p>
                )}
              </div>
            )}
          </div>

          {/* Advanced Settings */}
          <div className="space-y-3">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="w-full justify-start"
            >
              {showAdvanced ? '▼' : '▶'} Advanced Settings
            </Button>

            {showAdvanced && (
              <div className="space-y-4 pl-6">
                {/* Auto-start */}
                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label htmlFor="autoStart">Auto-start ComfyUI</Label>
                    <p className="text-xs text-muted-foreground">
                      Automatically start server when application launches
                    </p>
                  </div>
                  <Switch
                    id="autoStart"
                    checked={autoStart}
                    onCheckedChange={setAutoStart}
                  />
                </div>

                {/* Max Queue Size */}
                <div className="space-y-2">
                  <Label htmlFor="maxQueueSize">Max Queue Size: {maxQueueSize}</Label>
                  <Slider
                    id="maxQueueSize"
                    min={1}
                    max={50}
                    step={1}
                    value={[maxQueueSize]}
                    onValueChange={([value]) => setMaxQueueSize(value)}
                  />
                </div>

                {/* Timeout */}
                <div className="space-y-2">
                  <Label htmlFor="timeout">Request Timeout (ms)</Label>
                  <Input
                    id="timeout"
                    type="number"
                    value={timeout}
                    onChange={(e) => setTimeout(parseInt(e.target.value) || 300000)}
                    min={1000}
                    step={1000}
                  />
                </div>

                {/* VRAM Limit */}
                <div className="space-y-2">
                  <Label htmlFor="vramLimit">VRAM Limit (GB)</Label>
                  <Input
                    id="vramLimit"
                    type="number"
                    value={vramLimit || ''}
                    onChange={(e) => setVramLimit(e.target.value ? parseInt(e.target.value) : undefined)}
                    placeholder="Leave empty for auto-detect"
                    min={1}
                  />
                </div>

                {/* Models Path */}
                <div className="space-y-2">
                  <Label htmlFor="modelsPath">Models Path</Label>
                  <Input
                    id="modelsPath"
                    value={modelsPath}
                    onChange={(e) => setModelsPath(e.target.value)}
                    placeholder="/path/to/ComfyUI/models"
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSave}>
            {isEditing ? 'Save Changes' : 'Add Server'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * ComfyUI Servers Panel Component
 * 
 * Main panel for managing multiple ComfyUI servers
 */

import { useState, useEffect } from 'react';
import { Plus, RefreshCw, Download, Upload, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ComfyUIServerCard } from './ComfyUIServerCard';
import { ComfyUIServerModal } from './ComfyUIServerModal';
import { getComfyUIServersService } from '@/services/comfyuiServersService';
import type { ComfyUIServer, CreateComfyUIServerInput } from '@/types/comfyuiServers';
import { useToast } from '@/hooks/use-toast';

export interface ComfyUIServersPanelProps {
  className?: string;
}

export function ComfyUIServersPanel({ className }: ComfyUIServersPanelProps) {
  const service = getComfyUIServersService();
  const { toast } = useToast();

  // State
  const [servers, setServers] = useState<ComfyUIServer[]>([]);
  const [activeServerId, setActiveServerId] = useState<string | null>(null);
  const [autoSwitch, setAutoSwitch] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingServer, setEditingServer] = useState<ComfyUIServer | null>(null);
  const [isTestingAll, setIsTestingAll] = useState(false);

  // Load servers on mount
  useEffect(() => {
    loadServers();
  }, []);

  const loadServers = () => {
    setServers(service.getAllServers());
    setActiveServerId(service.getActiveServerId());
    setAutoSwitch(service.getAutoSwitchOnFailure());
  };

  const handleAddServer = (input: CreateComfyUIServerInput) => {
    try {
      service.addServer(input);
      loadServers();
      toast({
        title: 'Server Added',
        description: `${input.name} has been added successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to add server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleEditServer = (input: CreateComfyUIServerInput) => {
    if (!editingServer) return;

    try {
      service.updateServer(editingServer.id, input);
      loadServers();
      toast({
        title: 'Server Updated',
        description: `${input.name} has been updated successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleDeleteServer = (id: string) => {
    const server = service.getServer(id);
    if (!server) return;

    if (confirm(`Are you sure you want to delete "${server.name}"?`)) {
      try {
        service.deleteServer(id);
        loadServers();
        toast({
          title: 'Server Deleted',
          description: `${server.name} has been deleted.`,
        });
      } catch (error) {
        toast({
          title: 'Error',
          description: 'Failed to delete server. Please try again.',
          variant: 'destructive',
        });
      }
    }
  };

  const handleSetActive = (id: string) => {
    try {
      service.setActiveServer(id);
      loadServers();
      const server = service.getServer(id);
      toast({
        title: 'Active Server Changed',
        description: `${server?.name} is now the active server.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to set active server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleTestServer = async (id: string) => {
    try {
      const success = await service.testServer(id);
      loadServers();
      
      const server = service.getServer(id);
      if (success) {
        toast({
          title: 'Connection Successful',
          description: `Successfully connected to ${server?.name}.`,
        });
      } else {
        toast({
          title: 'Connection Failed',
          description: `Failed to connect to ${server?.name}.`,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to test connection. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleTestAll = async () => {
    setIsTestingAll(true);
    try {
      const results = await service.testAllServers();
      loadServers();
      
      const successCount = Array.from(results.values()).filter(Boolean).length;
      toast({
        title: 'Connection Tests Complete',
        description: `${successCount} of ${results.size} servers connected successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to test connections. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsTestingAll(false);
    }
  };

  const handleAutoSwitchChange = (enabled: boolean) => {
    service.setAutoSwitchOnFailure(enabled);
    setAutoSwitch(enabled);
    toast({
      title: 'Auto-Switch Updated',
      description: `Auto-switch on failure is now ${enabled ? 'enabled' : 'disabled'}.`,
    });
  };

  const handleExport = () => {
    try {
      const config = service.exportConfig();
      const blob = new Blob([config], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `comfyui-servers-${Date.now()}.json`;
      a.click();
      URL.revokeObjectURL(url);
      
      toast({
        title: 'Configuration Exported',
        description: 'Server configuration has been exported successfully.',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to export configuration.',
        variant: 'destructive',
      });
    }
  };

  const handleImport = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        const text = await file.text();
        const success = service.importConfig(text);
        
        if (success) {
          loadServers();
          toast({
            title: 'Configuration Imported',
            description: 'Server configuration has been imported successfully.',
          });
        } else {
          toast({
            title: 'Import Failed',
            description: 'Invalid configuration file.',
            variant: 'destructive',
          });
        }
      } catch (error) {
        toast({
          title: 'Error',
          description: 'Failed to import configuration.',
          variant: 'destructive',
        });
      }
    };
    
    input.click();
  };

  return (
    <div className={className}>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>ComfyUI Servers</CardTitle>
              <CardDescription>
                Manage multiple ComfyUI server connections
              </CardDescription>
            </div>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleTestAll}
                disabled={isTestingAll || servers.length === 0}
              >
                <RefreshCw className={`mr-2 h-4 w-4 ${isTestingAll ? 'animate-spin' : ''}`} />
                Test All
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleExport}
                disabled={servers.length === 0}
              >
                <Download className="mr-2 h-4 w-4" />
                Export
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleImport}
              >
                <Upload className="mr-2 h-4 w-4" />
                Import
              </Button>
              <Button onClick={() => setShowAddModal(true)}>
                <Plus className="mr-2 h-4 w-4" />
                Add Server
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Auto-Switch Setting */}
          <div className="flex items-center justify-between p-4 border rounded-lg">
            <div className="space-y-0.5">
              <Label htmlFor="autoSwitch">Auto-switch on Failure</Label>
              <p className="text-sm text-muted-foreground">
                Automatically switch to another server if the active one fails
              </p>
            </div>
            <Switch
              id="autoSwitch"
              checked={autoSwitch}
              onCheckedChange={handleAutoSwitchChange}
            />
          </div>

          {/* Server List */}
          {servers.length === 0 ? (
            <Alert>
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                No servers configured. Click "Add Server" to get started.
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-2">
              {servers.map((server) => (
                <ComfyUIServerCard
                  key={server.id}
                  server={server}
                  isActive={server.id === activeServerId}
                  onSetActive={() => handleSetActive(server.id)}
                  onEdit={() => setEditingServer(server)}
                  onDelete={() => handleDeleteServer(server.id)}
                  onTest={() => handleTestServer(server.id)}
                />
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Add/Edit Modal */}
      <ComfyUIServerModal
        server={editingServer}
        isOpen={showAddModal || !!editingServer}
        onClose={() => {
          setShowAddModal(false);
          setEditingServer(null);
        }}
        onSave={editingServer ? handleEditServer : handleAddServer}
      />
    </div>
  );
}

/**
 * LLM Settings Panel Component
 * 
 * Provides UI for configuring LLM integration settings including:
 * - Provider selection (OpenAI, Anthropic, Local, Custom)
 * - Model selection with info display
 * - Generation parameters (temperature, max tokens, etc.)
 * - System prompt editors
 * - Connection testing and validation
 * 
 * Validates Requirements: 3.1, 3.2, 3.6
 */

import React, { useState, useEffect } from 'react';
import { Check, AlertCircle, Loader2, Info, Eye, EyeOff, Download, Upload, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Textarea } from '@/components/ui/textarea';
import { Separator } from '@/components/ui/separator';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { cn } from '@/lib/utils';
import type {
  LLMConfig,
  LLMProvider,
} from '@/services/llmService';
import { getAvailableProviders, getDefaultSystemPrompts } from '@/services/llmService';
import {
  saveLLMSettings,
  loadLLMSettings,
  deleteLLMSettings,
  exportSettings,
  importSettings,
  isCryptoAvailable,
  getLastValidationTime,
} from '@/utils/secureStorage';
import { LocalModelSelector } from './LocalModelSelector';

// ============================================================================
// Types
// ============================================================================

export interface LLMSettingsPanelProps {
  currentConfig?: Partial<LLMConfig>;
  onSave: (config: LLMConfig) => void | Promise<void>;
  onCancel?: () => void;
  onTestConnection?: (config: Partial<LLMConfig>) => Promise<boolean>;
  className?: string;
}

interface ConnectionStatus {
  state: 'idle' | 'testing' | 'success' | 'error';
  message?: string;
}

// ============================================================================
// Validation Helpers
// ============================================================================

/**
 * Validate API key format based on provider
 */
function validateApiKeyFormat(provider: LLMProvider, apiKey: string): string | null {
  if (!apiKey) {
    return 'API key is required';
  }

  switch (provider) {
    case 'openai':
      if (!apiKey.startsWith('sk-')) {
        return 'OpenAI API keys must start with "sk-"';
      }
      if (apiKey.length < 20) {
        return 'OpenAI API key appears to be too short';
      }
      break;
    case 'anthropic':
      if (!apiKey.startsWith('sk-ant-')) {
        return 'Anthropic API keys must start with "sk-ant-"';
      }
      if (apiKey.length < 20) {
        return 'Anthropic API key appears to be too short';
      }
      break;
  }

  return null;
}

/**
 * Validate endpoint URL format
 */
function validateEndpointFormat(endpoint: string): string | null {
  if (!endpoint) {
    return 'API endpoint is required';
  }

  try {
    const url = new URL(endpoint);
    if (!['http:', 'https:'].includes(url.protocol)) {
      return 'Endpoint must use HTTP or HTTPS protocol';
    }
  } catch {
    return 'Invalid URL format. Please enter a valid endpoint URL.';
  }

  return null;
}

/**
 * Get provider-specific connection error message
 */
function getConnectionErrorMessage(provider: LLMProvider): string {
  switch (provider) {
    case 'openai':
      return 'Connection failed. Please verify your OpenAI API key has the correct permissions and your account has sufficient credits.';
    case 'anthropic':
      return 'Connection failed. Please verify your Anthropic API key is valid and has access to the selected model.';
    case 'local':
      return 'Connection failed. Please ensure your local LLM server is running and accessible at the specified endpoint.';
    case 'custom':
      return 'Connection failed. Please verify the custom endpoint is accessible and the API key (if required) is correct.';
    default:
      return 'Connection failed. Please check your settings and try again.';
  }
}

/**
 * Get provider-specific connection error guidance
 */
function getConnectionErrorGuidance(provider: LLMProvider): string {
  switch (provider) {
    case 'openai':
      return 'Check: 1) API key is correct, 2) Account has credits, 3) Key has proper permissions.';
    case 'anthropic':
      return 'Check: 1) API key is correct, 2) Model access is enabled, 3) Account is active.';
    case 'local':
      return 'Check: 1) Server is running, 2) Endpoint URL is correct, 3) No firewall blocking.';
    case 'custom':
      return 'Check: 1) Endpoint is accessible, 2) Authentication is correct, 3) API is compatible.';
    default:
      return 'Please verify your configuration and try again.';
  }
}

// ============================================================================
// LLM Settings Panel Component
// ============================================================================

export function LLMSettingsPanel({
  currentConfig,
  onSave,
  onCancel,
  onTestConnection,
  className,
}: LLMSettingsPanelProps) {
  // ============================================================================
  // State
  // ============================================================================

  const [provider, setProvider] = useState<LLMProvider>(currentConfig?.provider || 'openai');
  const [apiKey, setApiKey] = useState(currentConfig?.apiKey || '');
  const [apiEndpoint, setApiEndpoint] = useState(currentConfig?.apiEndpoint || '');
  const [model, setModel] = useState(currentConfig?.model || '');
  const [temperature, setTemperature] = useState(currentConfig?.parameters?.temperature ?? 0.7);
  const [maxTokens, setMaxTokens] = useState(currentConfig?.parameters?.maxTokens ?? 2000);
  const [topP, setTopP] = useState(currentConfig?.parameters?.topP ?? 1.0);
  const [frequencyPenalty, setFrequencyPenalty] = useState(currentConfig?.parameters?.frequencyPenalty ?? 0);
  const [presencePenalty, setPresencePenalty] = useState(currentConfig?.parameters?.presencePenalty ?? 0);
  const [timeout, setTimeout] = useState(currentConfig?.timeout ?? 30000);
  const [retryAttempts, setRetryAttempts] = useState(currentConfig?.retryAttempts ?? 3);
  const [streamingEnabled, setStreamingEnabled] = useState(currentConfig?.streamingEnabled ?? true);

  // New creativity and vectorial enhancement parameters
  const [creativityMode, setCreativityMode] = useState(currentConfig?.parameters?.creativityMode || 'balanced');
  const [jokesEnabled, setJokesEnabled] = useState(currentConfig?.parameters?.jokesEnabled || false);
  const [wordGamesEnabled, setWordGamesEnabled] = useState(currentConfig?.parameters?.wordGamesEnabled || false);
  const [probabilityFramingEnabled, setProbabilityFramingEnabled] = useState(currentConfig?.parameters?.probabilityFramingEnabled || false);
  const [vectorialOptimization, setVectorialOptimization] = useState(currentConfig?.parameters?.vectorialOptimization || 'standard');
  const [embeddingModel, setEmbeddingModel] = useState(currentConfig?.parameters?.embeddingModel || 'default');
  const [similarityThreshold, setSimilarityThreshold] = useState(currentConfig?.parameters?.similarityThreshold || 0.7);
  
  const defaultPrompts = getDefaultSystemPrompts();
  const [worldPrompt, setWorldPrompt] = useState(
    currentConfig?.systemPrompts?.worldGeneration || defaultPrompts.worldGeneration
  );
  const [characterPrompt, setCharacterPrompt] = useState(
    currentConfig?.systemPrompts?.characterGeneration || defaultPrompts.characterGeneration
  );
  const [dialoguePrompt, setDialoguePrompt] = useState(
    currentConfig?.systemPrompts?.dialogueGeneration || defaultPrompts.dialogueGeneration
  );

  const [showApiKey, setShowApiKey] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>({ state: 'idle' });
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [cryptoAvailable, setCryptoAvailable] = useState(true);
  const [lastValidated, setLastValidated] = useState<Date | null>(null);

  const providers = getAvailableProviders();
  const currentProviderInfo = providers.find(p => p.id === provider);
  const currentModelInfo = currentProviderInfo?.models.find(m => m.id === model);

  // ============================================================================
  // Effects
  // ============================================================================

  // Load settings on mount
  useEffect(() => {
    const loadStoredSettings = async () => {
      setIsLoading(true);
      
      // Check if Web Crypto API is available
      if (!isCryptoAvailable()) {
        setCryptoAvailable(false);
        console.warn('Web Crypto API not available. Settings encryption disabled.');
      }

      try {
        // Load settings from secure storage
        const storedConfig = await loadLLMSettings();
        
        if (storedConfig) {
          // Populate form with stored settings
          setProvider(storedConfig.provider);
          setApiKey(storedConfig.apiKey);
          
          // Use stored endpoint or fall back to provider's default
          let endpoint = storedConfig.apiEndpoint || '';
          if (!endpoint && (storedConfig.provider === 'local' || storedConfig.provider === 'custom')) {
            const providerInfo = providers.find(p => p.id === storedConfig.provider);
            endpoint = providerInfo?.defaultEndpoint || '';
          }
          setApiEndpoint(endpoint);
          
          setModel(storedConfig.model);
          setTemperature(storedConfig.parameters.temperature);
          setMaxTokens(storedConfig.parameters.maxTokens);
          setTopP(storedConfig.parameters.topP);
          setFrequencyPenalty(storedConfig.parameters.frequencyPenalty);
          setPresencePenalty(storedConfig.parameters.presencePenalty);
          setTimeout(storedConfig.timeout);
          setRetryAttempts(storedConfig.retryAttempts);
          setStreamingEnabled(storedConfig.streamingEnabled);
          
          // Safely access systemPrompts with fallback to defaults
          if (storedConfig.systemPrompts) {
            setWorldPrompt(storedConfig.systemPrompts.worldGeneration || defaultPrompts.worldGeneration);
            setCharacterPrompt(storedConfig.systemPrompts.characterGeneration || defaultPrompts.characterGeneration);
            setDialoguePrompt(storedConfig.systemPrompts.dialogueGeneration || defaultPrompts.dialogueGeneration);
          } else {
            // Use defaults if systemPrompts is missing
            setWorldPrompt(defaultPrompts.worldGeneration);
            setCharacterPrompt(defaultPrompts.characterGeneration);
            setDialoguePrompt(defaultPrompts.dialogueGeneration);
          }

          // Set last validation time
          const lastValidation = getLastValidationTime();
          setLastValidated(lastValidation);
        } else if (currentConfig) {
          // Fall back to currentConfig prop if no stored settings
          // (This maintains backward compatibility)
        }
      } catch (error) {
        console.error('Failed to load stored settings:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadStoredSettings();
  }, []); // Only run on mount

  // Update model when provider changes
  useEffect(() => {
    const providerInfo = providers.find(p => p.id === provider);
    if (providerInfo && providerInfo.models.length > 0) {
      // Set first model as default if current model is not available
      const modelExists = providerInfo.models.some(m => m.id === model);
      if (!modelExists) {
        setModel(providerInfo.models[0].id);
      }
    }
  }, [provider, providers, model]);

  // Update endpoint when provider changes
  useEffect(() => {
    const providerInfo = providers.find(p => p.id === provider);
    if (providerInfo && !apiEndpoint) {
      setApiEndpoint(providerInfo.defaultEndpoint);
    }
  }, [provider, providers, apiEndpoint]);

  // ============================================================================
  // Handlers
  // ============================================================================

  const validateCredentials = (): string | null => {
    // Validate provider-specific requirements
    if (currentProviderInfo?.requiresApiKey) {
      const apiKeyError = validateApiKeyFormat(provider, apiKey);
      if (apiKeyError) {
        return apiKeyError;
      }
    }

    // Validate endpoint for local/custom providers
    if (provider === 'local' || provider === 'custom') {
      const endpointError = validateEndpointFormat(apiEndpoint);
      if (endpointError) {
        return endpointError;
      }
    }

    // Validate model selection
    if (!model) {
      return 'Please select a model';
    }

    // Validate parameters are within valid ranges
    if (temperature < 0 || temperature > 2) {
      return 'Temperature must be between 0 and 2';
    }

    if (maxTokens < 1) {
      return 'Max tokens must be at least 1';
    }

    if (currentModelInfo && maxTokens > currentModelInfo.contextWindow) {
      return `Max tokens cannot exceed model limit of ${currentModelInfo.contextWindow.toLocaleString()}`;
    }

    if (topP < 0 || topP > 1) {
      return 'Top P must be between 0 and 1';
    }

    if (frequencyPenalty < -2 || frequencyPenalty > 2) {
      return 'Frequency penalty must be between -2 and 2';
    }

    if (presencePenalty < -2 || presencePenalty > 2) {
      return 'Presence penalty must be between -2 and 2';
    }

    if (timeout < 1000) {
      return 'Timeout must be at least 1000ms (1 second)';
    }

    if (retryAttempts < 0 || retryAttempts > 10) {
      return 'Retry attempts must be between 0 and 10';
    }

    return null;
  };

  const handleTestConnection = async () => {
    if (!onTestConnection) return;

    // Validate before testing
    const validationError = validateCredentials();
    if (validationError) {
      setConnectionStatus({
        state: 'error',
        message: validationError,
      });
      return;
    }

    setConnectionStatus({ state: 'testing', message: 'Testing connection...' });

    try {
      const config: Partial<LLMConfig> = {
        provider,
        apiKey,
        apiEndpoint: (provider === 'local' || provider === 'custom') ? apiEndpoint : undefined,
        model,
      };

      const success = await onTestConnection(config);

      if (success) {
        setConnectionStatus({
          state: 'success',
          message: 'Connection successful! API key is valid and the model is accessible.',
        });
      } else {
        setConnectionStatus({
          state: 'error',
          message: getConnectionErrorMessage(provider),
        });
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Connection test failed';
      setConnectionStatus({
        state: 'error',
        message: `${errorMessage}. ${getConnectionErrorGuidance(provider)}`,
      });
    }
  };

  const handleSave = async () => {
    // Validate before saving
    const validationError = validateCredentials();
    if (validationError) {
      setConnectionStatus({
        state: 'error',
        message: validationError,
      });
      return;
    }

    // Validate connection if handler is provided
    if (onTestConnection && connectionStatus.state !== 'success') {
      setConnectionStatus({
        state: 'error',
        message: 'Please test the connection before saving.',
      });
      return;
    }

    setIsSaving(true);

    try {
      const config: LLMConfig = {
        provider,
        apiKey,
        apiEndpoint: (provider === 'local' || provider === 'custom') ? apiEndpoint : undefined,
        model,
        parameters: {
          temperature,
          maxTokens,
          topP,
          frequencyPenalty,
          presencePenalty,
          creativityMode,
          jokesEnabled,
          wordGamesEnabled,
          probabilityFramingEnabled,
          vectorialOptimization,
          embeddingModel,
          similarityThreshold,
        },
        systemPrompts: {
          worldGeneration: worldPrompt,
          characterGeneration: characterPrompt,
          dialogueGeneration: dialoguePrompt,
        },
        timeout,
        retryAttempts,
        streamingEnabled,
      };

      // Save to secure storage with encryption
      if (cryptoAvailable) {
        await saveLLMSettings(config);
        setLastValidated(new Date());
      }

      // Also call the onSave callback for backward compatibility
      await onSave(config);

      // Show success message
      setConnectionStatus({
        state: 'success',
        message: 'Settings saved successfully with encrypted credentials.',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to save settings',
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleResetPrompts = () => {
    const defaults = getDefaultSystemPrompts();
    setWorldPrompt(defaults.worldGeneration);
    setCharacterPrompt(defaults.characterGeneration);
    setDialoguePrompt(defaults.dialogueGeneration);
  };

  const handleExportSettings = () => {
    try {
      const exportData = exportSettings();
      
      // Create download link
      const blob = new Blob([exportData], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `storycore-settings-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setConnectionStatus({
        state: 'success',
        message: 'Settings exported successfully (credentials excluded for security).',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to export settings',
      });
    }
  };

  const handleImportSettings = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        const text = await file.text();
        const success = importSettings(text);

        if (success) {
          // Reload settings
          const storedConfig = await loadLLMSettings();
          if (storedConfig) {
            setProvider(storedConfig.provider);
            setModel(storedConfig.model);
            setTemperature(storedConfig.parameters.temperature);
            setMaxTokens(storedConfig.parameters.maxTokens);
            setTopP(storedConfig.parameters.topP);
            setFrequencyPenalty(storedConfig.parameters.frequencyPenalty);
            setPresencePenalty(storedConfig.parameters.presencePenalty);
            setTimeout(storedConfig.timeout);
            setRetryAttempts(storedConfig.retryAttempts);
            setStreamingEnabled(storedConfig.streamingEnabled);
            
            // Safely access systemPrompts with fallback to defaults
            const defaults = getDefaultSystemPrompts();
            if (storedConfig.systemPrompts) {
              setWorldPrompt(storedConfig.systemPrompts.worldGeneration || defaults.worldGeneration);
              setCharacterPrompt(storedConfig.systemPrompts.characterGeneration || defaults.characterGeneration);
              setDialoguePrompt(storedConfig.systemPrompts.dialogueGeneration || defaults.dialogueGeneration);
            } else {
              setWorldPrompt(defaults.worldGeneration);
              setCharacterPrompt(defaults.characterGeneration);
              setDialoguePrompt(defaults.dialogueGeneration);
            }
          }

          setConnectionStatus({
            state: 'success',
            message: 'Settings imported successfully. Please re-enter your API key.',
          });
        } else {
          throw new Error('Invalid settings file format');
        }
      } catch (error) {
        setConnectionStatus({
          state: 'error',
          message: error instanceof Error ? error.message : 'Failed to import settings',
        });
      }
    };

    input.click();
  };

  const handleDeleteSettings = () => {
    if (!confirm('Are you sure you want to delete all saved settings? This action cannot be undone.')) {
      return;
    }

    try {
      deleteLLMSettings();
      
      // Reset form to defaults
      const defaults = getDefaultSystemPrompts();
      setProvider('openai');
      setApiKey('');
      setApiEndpoint('');
      setModel('');
      setTemperature(0.7);
      setMaxTokens(2000);
      setTopP(1.0);
      setFrequencyPenalty(0);
      setPresencePenalty(0);
      setTimeout(30000);
      setRetryAttempts(3);
      setStreamingEnabled(true);
      setWorldPrompt(defaults.worldGeneration);
      setCharacterPrompt(defaults.characterGeneration);
      setDialoguePrompt(defaults.dialogueGeneration);
      setConnectionStatus({ state: 'idle' });
      setLastValidated(null);

      setConnectionStatus({
        state: 'success',
        message: 'All settings deleted successfully.',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to delete settings',
      });
    }
  };

  const isFormValid = () => {
    if (!provider || !model) return false;
    if (currentProviderInfo?.requiresApiKey && !apiKey) return false;
    if ((provider === 'local' || provider === 'custom') && !apiEndpoint) return false;
    return true;
  };

  // ============================================================================
  // Render
  // ============================================================================

  if (isLoading) {
    return (
      <div className={cn('flex items-center justify-center p-8', className)}>
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className={cn('space-y-6', className)}>
      {/* Crypto Warning */}
      {!cryptoAvailable && (
        <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-amber-50 text-amber-800 border border-amber-200 dark:bg-amber-950 dark:text-amber-200 dark:border-amber-800">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-medium">Encryption unavailable</p>
            <p className="text-xs mt-1 opacity-90">
              Web Crypto API is not available in your browser. Credentials will be stored without encryption.
            </p>
          </div>
        </div>
      )}

      {/* Last Validated Info */}
      {lastValidated && (
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Check className="h-3 w-3 text-green-600" />
          <span>Last validated: {lastValidated.toLocaleString()}</span>
        </div>
      )}

      {/* Provider Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Provider Selection</CardTitle>
          <CardDescription>
            Choose your LLM provider and configure authentication
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-3">
            <Label>Provider</Label>
            <RadioGroup value={provider} onValueChange={(value) => {
              const newProvider = value as LLMProvider;
              setProvider(newProvider);
              
              // Get the default endpoint for the selected provider
              const providerInfo = providers.find(p => p.id === newProvider);
              const defaultEndpoint = providerInfo?.defaultEndpoint || '';
              
              // Set the endpoint to the provider's default
              setApiEndpoint(defaultEndpoint);
              
              // Clear connection status when provider changes
              if (connectionStatus.state !== 'idle') {
                setConnectionStatus({ state: 'idle' });
              }
            }}>
              {providers.map((p) => (
                <div key={p.id} className="flex items-center space-x-2">
                  <RadioGroupItem value={p.id} id={p.id} />
                  <Label htmlFor={p.id} className="font-normal cursor-pointer">
                    {p.name}
                    {p.requiresApiKey && (
                      <Badge variant="outline" className="ml-2 text-xs">
                        Requires API Key
                      </Badge>
                    )}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          </div>

          {/* Model Selection */}
          <div className="space-y-2">
            <Label htmlFor="model">Model</Label>
            {(provider === 'local' || provider === 'custom') ? (
              // Show Local Model Selector for local/custom providers
              <div className="mt-4">
                <LocalModelSelector
                  selectedModel={model}
                  onModelSelect={(modelId) => {
                    setModel(modelId);
                    // Clear connection status when model changes
                    if (connectionStatus.state !== 'idle') {
                      setConnectionStatus({ state: 'idle' });
                    }
                  }}
                  endpoint={apiEndpoint || 'http://localhost:11434'}
                />
              </div>
            ) : (
              // Show regular dropdown for cloud providers
              <>
                <Select value={model} onValueChange={setModel}>
                  <SelectTrigger id="model">
                    <SelectValue placeholder="Select a model" />
                  </SelectTrigger>
                  <SelectContent>
                    {currentProviderInfo?.models.map((m) => (
                      <SelectItem key={m.id} value={m.id}>
                        {m.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {currentModelInfo && (
                  <div className="text-xs text-muted-foreground space-y-1 mt-2">
                    <div className="flex items-center gap-2">
                      <Info className="h-3 w-3" />
                      <span>Context: {currentModelInfo.contextWindow.toLocaleString()} tokens</span>
                    </div>
                    {currentModelInfo.costPer1kTokens && (
                      <div className="ml-5">
                        Cost: ${currentModelInfo.costPer1kTokens}/1K tokens
                      </div>
                    )}
                    <div className="ml-5">
                      Capabilities: {currentModelInfo.capabilities.join(', ')}
                    </div>
                  </div>
                )}
              </>
            )}
          </div>

          {/* API Key */}
          {currentProviderInfo?.requiresApiKey && (
            <div className="space-y-2">
              <Label htmlFor="apiKey">API Key</Label>
              <div className="relative">
                <Input
                  id="apiKey"
                  type={showApiKey ? 'text' : 'password'}
                  value={apiKey}
                  onChange={(e) => {
                    setApiKey(e.target.value);
                    // Clear connection status when API key changes
                    if (connectionStatus.state !== 'idle') {
                      setConnectionStatus({ state: 'idle' });
                    }
                  }}
                  placeholder="sk-..."
                  className={cn(
                    'pr-10',
                    apiKey && validateApiKeyFormat(provider, apiKey) && 'border-red-500 focus-visible:ring-red-500'
                  )}
                  aria-invalid={apiKey ? !!validateApiKeyFormat(provider, apiKey) : undefined}
                  aria-describedby={apiKey && validateApiKeyFormat(provider, apiKey) ? 'apiKey-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowApiKey(!showApiKey)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label={showApiKey ? 'Hide API key' : 'Show API key'}
                >
                  {showApiKey ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
              {apiKey && validateApiKeyFormat(provider, apiKey) && (
                <p id="apiKey-error" className="text-xs text-red-600 dark:text-red-400" role="alert">
                  {validateApiKeyFormat(provider, apiKey)}
                </p>
              )}
            </div>
          )}

          {/* Custom Endpoint */}
          {(provider === 'local' || provider === 'custom') && (
            <div className="space-y-2">
              <Label htmlFor="apiEndpoint">API Endpoint</Label>
              <Input
                id="apiEndpoint"
                type="url"
                value={apiEndpoint}
                onChange={(e) => {
                  setApiEndpoint(e.target.value);
                  // Clear connection status when endpoint changes
                  if (connectionStatus.state !== 'idle') {
                    setConnectionStatus({ state: 'idle' });
                  }
                }}
                placeholder={currentProviderInfo?.defaultEndpoint || 'http://localhost:8000'}
                className={cn(
                  apiEndpoint && validateEndpointFormat(apiEndpoint) && 'border-red-500 focus-visible:ring-red-500'
                )}
                aria-invalid={apiEndpoint ? !!validateEndpointFormat(apiEndpoint) : undefined}
                aria-describedby={apiEndpoint && validateEndpointFormat(apiEndpoint) ? 'endpoint-error' : undefined}
              />
              <p className="text-xs text-muted-foreground">
                The base URL for your {provider} LLM server (default: {currentProviderInfo?.defaultEndpoint || 'http://localhost:8000'})
              </p>
              {apiEndpoint && validateEndpointFormat(apiEndpoint) && (
                <p id="endpoint-error" className="text-xs text-red-600 dark:text-red-400" role="alert">
                  {validateEndpointFormat(apiEndpoint)}
                </p>
              )}
            </div>
          )}

          {/* Connection Test */}
          {onTestConnection && (
            <div className="space-y-2">
              <Button
                onClick={handleTestConnection}
                disabled={!isFormValid() || connectionStatus.state === 'testing'}
                variant="outline"
                className="w-full"
              >
                {connectionStatus.state === 'testing' && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Test Connection
              </Button>

              {connectionStatus.state !== 'idle' && (
                <div
                  className={cn(
                    'flex items-start gap-2 p-3 rounded-lg text-sm',
                    connectionStatus.state === 'success' && 'bg-green-50 text-green-800 border border-green-200 dark:bg-green-950 dark:text-green-200 dark:border-green-800',
                    connectionStatus.state === 'error' && 'bg-red-50 text-red-800 border border-red-200 dark:bg-red-950 dark:text-red-200 dark:border-red-800',
                    connectionStatus.state === 'testing' && 'bg-blue-50 text-blue-800 border border-blue-200 dark:bg-blue-950 dark:text-blue-200 dark:border-blue-800'
                  )}
                  role="alert"
                  aria-live="polite"
                >
                  {connectionStatus.state === 'success' && <Check className="h-4 w-4 mt-0.5 flex-shrink-0" />}
                  {connectionStatus.state === 'error' && <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />}
                  {connectionStatus.state === 'testing' && <Loader2 className="h-4 w-4 mt-0.5 flex-shrink-0 animate-spin" />}
                  <div className="flex-1">
                    <p className="font-medium">{connectionStatus.message}</p>
                    {connectionStatus.state === 'error' && (
                      <p className="mt-1 text-xs opacity-90">
                        {getConnectionErrorGuidance(provider)}
                      </p>
                    )}
                  </div>
                </div>
              )}

              {connectionStatus.state === 'success' && (
                <p className="text-xs text-muted-foreground">
                  ✓ Connection verified. You can now save your settings.
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Generation Parameters */}
      <Card>
        <CardHeader>
          <CardTitle>Generation Parameters</CardTitle>
          <CardDescription>
            Fine-tune how the AI generates content
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Temperature */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="temperature" className="flex items-center gap-2">
                Temperature
                <TooltipInfo content="Controls randomness. Lower values make output more focused and deterministic, higher values make it more creative and varied." />
              </Label>
              <span className="text-sm text-muted-foreground">{temperature.toFixed(2)}</span>
            </div>
            <Slider
              id="temperature"
              min={0}
              max={2}
              step={0.1}
              value={[temperature]}
              onValueChange={([value]) => setTemperature(value)}
            />
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Focused (0)</span>
              <span>Balanced (1)</span>
              <span>Creative (2)</span>
            </div>
          </div>

          {/* Max Tokens */}
          <div className="space-y-2">
            <Label htmlFor="maxTokens" className="flex items-center gap-2">
              Max Tokens
              <TooltipInfo content="Maximum length of generated response. Higher values allow longer responses but cost more." />
            </Label>
            <Input
              id="maxTokens"
              type="number"
              min={100}
              max={currentModelInfo?.contextWindow || 4096}
              value={maxTokens}
              onChange={(e) => setMaxTokens(parseInt(e.target.value) || 2000)}
            />
            {currentModelInfo && (
              <p className="text-xs text-muted-foreground">
                Model limit: {currentModelInfo.contextWindow.toLocaleString()} tokens
              </p>
            )}
          </div>

          {/* Top P */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="topP" className="flex items-center gap-2">
                Top P
                <TooltipInfo content="Controls diversity via nucleus sampling. Lower values make output more focused, higher values more diverse." />
              </Label>
              <span className="text-sm text-muted-foreground">{topP.toFixed(2)}</span>
            </div>
            <Slider
              id="topP"
              min={0}
              max={1}
              step={0.05}
              value={[topP]}
              onValueChange={([value]) => setTopP(value)}
            />
          </div>

          {/* Frequency Penalty */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="frequencyPenalty" className="flex items-center gap-2">
                Frequency Penalty
                <TooltipInfo content="Reduces repetition of tokens based on their frequency. Positive values discourage repetition." />
              </Label>
              <span className="text-sm text-muted-foreground">{frequencyPenalty.toFixed(2)}</span>
            </div>
            <Slider
              id="frequencyPenalty"
              min={-2}
              max={2}
              step={0.1}
              value={[frequencyPenalty]}
              onValueChange={([value]) => setFrequencyPenalty(value)}
            />
          </div>

          {/* Presence Penalty */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="presencePenalty" className="flex items-center gap-2">
                Presence Penalty
                <TooltipInfo content="Reduces repetition of topics. Positive values encourage discussing new topics." />
              </Label>
              <span className="text-sm text-muted-foreground">{presencePenalty.toFixed(2)}</span>
            </div>
            <Slider
              id="presencePenalty"
              min={-2}
              max={2}
              step={0.1}
              value={[presencePenalty]}
              onValueChange={([value]) => setPresencePenalty(value)}
            />
          </div>
        </CardContent>
      </Card>

      {/* Creativity Enhancement */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <span className="text-2xl">🎨</span>
            Creativity Enhancement
          </CardTitle>
          <CardDescription>
            Configure creativity settings and linguistic enhancements
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Creativity Mode */}
          <div className="space-y-2">
            <Label htmlFor="creativityMode">Creativity Mode</Label>
            <Select value={creativityMode} onValueChange={setCreativityMode}>
              <SelectTrigger id="creativityMode">
                <SelectValue placeholder="Select creativity mode" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="conservative">Conservative - Focused and precise</SelectItem>
                <SelectItem value="balanced">Balanced - Standard creativity</SelectItem>
                <SelectItem value="creative">Creative - Highly imaginative</SelectItem>
                <SelectItem value="experimental">Experimental - Maximum creativity</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Jokes & Word Games */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="jokesEnabled">Enable Jokes & Humor</Label>
                <p className="text-xs text-muted-foreground">
                  Allow AI to include jokes and wordplay in responses
                </p>
              </div>
              <Switch
                id="jokesEnabled"
                checked={jokesEnabled}
                onCheckedChange={setJokesEnabled}
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="wordGamesEnabled">Enable Word Games</Label>
                <p className="text-xs text-muted-foreground">
                  Allow puns, rhymes, and linguistic creativity
                </p>
              </div>
              <Switch
                id="wordGamesEnabled"
                checked={wordGamesEnabled}
                onCheckedChange={setWordGamesEnabled}
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="probabilityFramingEnabled">Probability Framing</Label>
                <p className="text-xs text-muted-foreground">
                  Frame responses with confidence levels and alternatives
                </p>
              </div>
              <Switch
                id="probabilityFramingEnabled"
                checked={probabilityFramingEnabled}
                onCheckedChange={setProbabilityFramingEnabled}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Vectorial Space Optimization */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <span className="text-2xl">🧠</span>
            Vectorial Space Optimization
          </CardTitle>
          <CardDescription>
            Configure vectorial distribution and embedding settings
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Vectorial Optimization Mode */}
          <div className="space-y-2">
            <Label htmlFor="vectorialOptimization">Vectorial Distribution Law</Label>
            <Select value={vectorialOptimization} onValueChange={setVectorialOptimization}>
              <SelectTrigger id="vectorialOptimization">
                <SelectValue placeholder="Select optimization mode" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="standard">Standard - Default distribution</SelectItem>
                <SelectItem value="gaussian">Gaussian - Bell curve optimization</SelectItem>
                <SelectItem value="exponential">Exponential - Rapid decay optimization</SelectItem>
                <SelectItem value="pareto">Pareto - Power-law distribution (80/20 rule)</SelectItem>
                <SelectItem value="adaptive">Adaptive - Dynamic optimization</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Embedding Model */}
          <div className="space-y-2">
            <Label htmlFor="embeddingModel">Embedding Model</Label>
            <Select value={embeddingModel} onValueChange={setEmbeddingModel}>
              <SelectTrigger id="embeddingModel">
                <SelectValue placeholder="Select embedding model" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="default">Default - Model's built-in embeddings</SelectItem>
                <SelectItem value="text-embedding-ada-002">OpenAI Ada-002 - High quality embeddings</SelectItem>
                <SelectItem value="text-embedding-3-small">OpenAI Embedding-3-Small - Fast and efficient</SelectItem>
                <SelectItem value="text-embedding-3-large">OpenAI Embedding-3-Large - Maximum quality</SelectItem>
                <SelectItem value="local-sentence-transformer">Local Sentence Transformer - Privacy-focused</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Similarity Threshold */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="similarityThreshold">Similarity Threshold</Label>
              <span className="text-sm text-muted-foreground">{similarityThreshold.toFixed(2)}</span>
            </div>
            <Slider
              id="similarityThreshold"
              min={0.1}
              max={0.95}
              step={0.05}
              value={[similarityThreshold]}
              onValueChange={([value]) => setSimilarityThreshold(value)}
            />
            <p className="text-xs text-muted-foreground">
              Minimum similarity score for vector matching (0.1-0.95)
            </p>
          </div>
        </CardContent>
      </Card>

      {/* System Prompts */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>System Prompts</CardTitle>
              <CardDescription>
                Customize how the AI behaves for different tasks
              </CardDescription>
            </div>
            <Button variant="outline" size="sm" onClick={handleResetPrompts}>
              Reset to Defaults
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* World Generation Prompt */}
          <div className="space-y-2">
            <Label htmlFor="worldPrompt">World Generation</Label>
            <Textarea
              id="worldPrompt"
              value={worldPrompt}
              onChange={(e) => setWorldPrompt(e.target.value)}
              rows={4}
              className="font-mono text-sm"
            />
          </div>

          <Separator />

          {/* Character Generation Prompt */}
          <div className="space-y-2">
            <Label htmlFor="characterPrompt">Character Generation</Label>
            <Textarea
              id="characterPrompt"
              value={characterPrompt}
              onChange={(e) => setCharacterPrompt(e.target.value)}
              rows={4}
              className="font-mono text-sm"
            />
          </div>

          <Separator />

          {/* Dialogue Generation Prompt */}
          <div className="space-y-2">
            <Label htmlFor="dialoguePrompt">Dialogue Generation</Label>
            <Textarea
              id="dialoguePrompt"
              value={dialoguePrompt}
              onChange={(e) => setDialoguePrompt(e.target.value)}
              rows={4}
              className="font-mono text-sm"
            />
          </div>
        </CardContent>
      </Card>

      {/* Advanced Settings */}
      <Card>
        <CardHeader>
          <CardTitle>Advanced Settings</CardTitle>
          <CardDescription>
            Configure timeout, retry behavior, and streaming
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Timeout */}
          <div className="space-y-2">
            <Label htmlFor="timeout" className="flex items-center gap-2">
              Timeout (ms)
              <TooltipInfo content="Maximum time to wait for a response before timing out." />
            </Label>
            <Input
              id="timeout"
              type="number"
              min={5000}
              max={120000}
              step={1000}
              value={timeout}
              onChange={(e) => setTimeout(parseInt(e.target.value) || 30000)}
            />
          </div>

          {/* Retry Attempts */}
          <div className="space-y-2">
            <Label htmlFor="retryAttempts" className="flex items-center gap-2">
              Retry Attempts
              <TooltipInfo content="Number of times to retry failed requests before giving up." />
            </Label>
            <Input
              id="retryAttempts"
              type="number"
              min={0}
              max={5}
              value={retryAttempts}
              onChange={(e) => setRetryAttempts(parseInt(e.target.value) || 3)}
            />
          </div>

          {/* Streaming */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label htmlFor="streaming">Enable Streaming</Label>
              <p className="text-xs text-muted-foreground">
                Stream responses in real-time for faster perceived performance
              </p>
            </div>
            <Switch
              id="streaming"
              checked={streamingEnabled}
              onCheckedChange={setStreamingEnabled}
            />
          </div>
        </CardContent>
      </Card>

      {/* Settings Management */}
      <Card>
        <CardHeader>
          <CardTitle>Settings Management</CardTitle>
          <CardDescription>
            Export, import, or delete your settings
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {/* Export Settings */}
            <Button
              variant="outline"
              onClick={handleExportSettings}
              className="w-full"
            >
              <Download className="mr-2 h-4 w-4" />
              Export Settings
            </Button>

            {/* Import Settings */}
            <Button
              variant="outline"
              onClick={handleImportSettings}
              className="w-full"
            >
              <Upload className="mr-2 h-4 w-4" />
              Import Settings
            </Button>

            {/* Delete Settings */}
            <Button
              variant="outline"
              onClick={handleDeleteSettings}
              className="w-full text-red-600 hover:text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950"
            >
              <Trash2 className="mr-2 h-4 w-4" />
              Delete All
            </Button>
          </div>

          <div className="text-xs text-muted-foreground space-y-1">
            <p>• <strong>Export:</strong> Download settings without credentials (safe to share)</p>
            <p>• <strong>Import:</strong> Load settings from a file (you'll need to re-enter credentials)</p>
            <p>• <strong>Delete:</strong> Permanently remove all saved settings and credentials</p>
          </div>

          {cryptoAvailable && (
            <div className="flex items-start gap-2 p-3 rounded-lg text-xs bg-green-50 text-green-800 border border-green-200 dark:bg-green-950 dark:text-green-200 dark:border-green-800">
              <Check className="h-3 w-3 mt-0.5 flex-shrink-0" />
              <p>
                Your API keys are encrypted using AES-256-GCM encryption before being stored locally.
                Encryption keys are session-specific and never leave your browser.
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <div className="space-y-3">
        {/* Validation message */}
        {!isFormValid() && (
          <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-amber-50 text-amber-800 border border-amber-200 dark:bg-amber-950 dark:text-amber-200 dark:border-amber-800">
            <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium">Configuration incomplete</p>
              <p className="text-xs mt-1 opacity-90">
                {validateCredentials() || 'Please fill in all required fields'}
              </p>
            </div>
          </div>
        )}

        {/* Connection test reminder */}
        {onTestConnection && isFormValid() && connectionStatus.state !== 'success' && (
          <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-blue-50 text-blue-800 border border-blue-200 dark:bg-blue-950 dark:text-blue-200 dark:border-blue-800">
            <Info className="h-4 w-4 mt-0.5 flex-shrink-0" />
            <p>Please test the connection before saving to ensure your settings are correct.</p>
          </div>
        )}

        <div className="flex justify-end gap-3">
          {onCancel && (
            <Button variant="outline" onClick={onCancel} disabled={isSaving}>
              Cancel
            </Button>
          )}
          <Button 
            onClick={handleSave} 
            disabled={!isFormValid() || isSaving || (onTestConnection && connectionStatus.state !== 'success')}
          >
            {isSaving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Settings
          </Button>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// Tooltip Info Component
// ============================================================================

interface TooltipInfoProps {
  content: string;
}

function TooltipInfo({ content }: TooltipInfoProps) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="relative inline-block">
      <button
        type="button"
        onMouseEnter={() => setIsOpen(true)}
        onMouseLeave={() => setIsOpen(false)}
        onFocus={() => setIsOpen(true)}
        onBlur={() => setIsOpen(false)}
        className="text-muted-foreground hover:text-foreground"
        aria-label="More information"
      >
        <Info className="h-3 w-3" />
      </button>
      {isOpen && (
        <div className="absolute z-50 w-64 p-2 text-xs bg-popover text-popover-foreground border rounded-md shadow-md left-0 top-full mt-1">
          {content}
        </div>
      )}
    </div>
  );
}

/**
 * Local Model Selector Component
 * 
 * Provides UI for selecting and downloading local LLM models
 * Integrates with Ollama for model management
 */

import { useState, useEffect } from 'react';
import { Download, Check, AlertCircle, Loader2, Trash2, Info, HardDrive, Cpu, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import {
  getLocalModelService,
  type LocalModel,
  type ModelDownloadProgress,
  LOCAL_MODELS,
} from '@/services/localModelService';

// ============================================================================
// Types
// ============================================================================

export interface LocalModelSelectorProps {
  selectedModel?: string;
  onModelSelect: (modelId: string) => void;
  endpoint?: string;
  className?: string;
}

interface ModelState {
  installed: boolean;
  downloading: boolean;
  progress: number;
  error?: string;
}

// ============================================================================
// Local Model Selector Component
// ============================================================================

export function LocalModelSelector({
  selectedModel,
  onModelSelect,
  endpoint = 'http://localhost:11434',
  className,
}: LocalModelSelectorProps) {
  // ============================================================================
  // State
  // ============================================================================

  const [isOllamaRunning, setIsOllamaRunning] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [modelStates, setModelStates] = useState<Map<string, ModelState>>(new Map());
  const [recommendedModels, setRecommendedModels] = useState<LocalModel[]>([]);
  const [selectedFamily, setSelectedFamily] = useState<LocalModel['family'] | 'all'>('all');
  const [showOnlyInstalled, setShowOnlyInstalled] = useState(false);

  const modelService = getLocalModelService(endpoint);

  // ============================================================================
  // Effects
  // ============================================================================

  useEffect(() => {
    checkOllamaStatus();
  }, [endpoint]);

  useEffect(() => {
    if (isOllamaRunning) {
      loadInstalledModels();
      loadRecommendedModels();
    }
  }, [isOllamaRunning]);

  // ============================================================================
  // Handlers
  // ============================================================================

  const checkOllamaStatus = async () => {
    setIsLoading(true);
    const running = await modelService.isOllamaRunning();
    setIsOllamaRunning(running);
    setIsLoading(false);
  };

  const loadInstalledModels = async () => {
    const installed = await modelService.getInstalledModels();
    const newStates = new Map<string, ModelState>();

    LOCAL_MODELS.forEach(model => {
      newStates.set(model.id, {
        installed: installed.includes(model.id),
        downloading: false,
        progress: 0,
      });
    });

    setModelStates(newStates);
  };

  const loadRecommendedModels = async () => {
    const recommended = await modelService.getRecommendedModels();
    setRecommendedModels(recommended);
  };

  const handleDownloadModel = async (modelId: string) => {
    try {
      // First check if Ollama is running
      const isRunning = await modelService.isOllamaRunning();
      if (!isRunning) {
        setModelStates(prev => {
          const newStates = new Map(prev);
          newStates.set(modelId, {
            installed: false,
            downloading: false,
            progress: 0,
            error: 'Ollama is not running. Please start Ollama and try again.',
          });
          return newStates;
        });
        return;
      }

      // Update state to show downloading
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: true,
          progress: 0,
        });
        return newStates;
      });

      ;

      // Start download
      const success = await modelService.downloadModel(
        modelId,
        (progress: ModelDownloadProgress) => {
          ;
          
          setModelStates(prev => {
            const newStates = new Map(prev);
            newStates.set(modelId, {
              installed: progress.status === 'completed',
              downloading: progress.status === 'downloading',
              progress: progress.progress,
              error: progress.error,
            });
            return newStates;
          });
        }
      );

      if (success) {
        ;
        // Automatically select the downloaded model
        onModelSelect(modelId);
      } else {
        console.error(`Model ${modelId} download failed`);
      }
    } catch (error) {
      console.error('Error in handleDownloadModel:', error);
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: false,
          progress: 0,
          error: error instanceof Error ? error.message : 'Download failed',
        });
        return newStates;
      });
    }
  };

  const handleDeleteModel = async (modelId: string) => {
    if (!confirm(`Are you sure you want to delete ${modelId}? This will free up disk space but you'll need to download it again to use it.`)) {
      return;
    }

    const success = await modelService.deleteModel(modelId);
    
    if (success) {
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: false,
          progress: 0,
        });
        return newStates;
      });

      // If deleted model was selected, clear selection
      if (selectedModel === modelId) {
        onModelSelect('');
      }
    }
  };

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const getFilteredModels = (): LocalModel[] => {
    let filtered = LOCAL_MODELS;

    // Filter by family
    if (selectedFamily !== 'all') {
      filtered = filtered.filter(m => m.family === selectedFamily);
    }

    // Filter by installed status
    if (showOnlyInstalled) {
      filtered = filtered.filter(m => modelStates.get(m.id)?.installed);
    }

    return filtered;
  };

  const renderModelCard = (model: LocalModel) => {
    const state = modelStates.get(model.id) || {
      installed: false,
      downloading: false,
      progress: 0,
    };

    const isSelected = selectedModel === model.id;
    const isRecommended = recommendedModels.some(m => m.id === model.id);

    return (
      <Card
        key={model.id}
        className={cn(
          'cursor-pointer transition-all hover:shadow-md',
          isSelected && 'ring-2 ring-primary',
          !state.installed && !state.downloading && 'opacity-75'
        )}
        onClick={() => {
          if (state.installed) {
            onModelSelect(model.id);
          }
        }}
      >
        <CardHeader className="pb-3">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <CardTitle className="text-base flex items-center gap-2">
                {model.displayName}
                {isRecommended && (
                  <Badge variant="secondary" className="text-xs">
                    <Zap className="h-3 w-3 mr-1" />
                    Recommended
                  </Badge>
                )}
                {state.installed && (
                  <Badge variant="default" className="text-xs">
                    <Check className="h-3 w-3 mr-1" />
                    Installed
                  </Badge>
                )}
              </CardTitle>
              <CardDescription className="text-xs mt-1">
                {model.description}
              </CardDescription>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-3">
          {/* Model Info */}
          <div className="flex flex-wrap gap-2 text-xs">
            <Badge variant="outline" className="gap-1">
              <HardDrive className="h-3 w-3" />
              {model.size}
            </Badge>
            <Badge variant="outline" className="gap-1">
              <Cpu className="h-3 w-3" />
              {model.minRAM}GB RAM min
            </Badge>
            {model.requiresGPU && (
              <Badge variant="outline" className="gap-1">
                <Zap className="h-3 w-3" />
                GPU Required
              </Badge>
            )}
          </div>

          {/* Capabilities */}
          <div className="flex flex-wrap gap-1">
            {model.capabilities.slice(0, 3).map(cap => (
              <Badge key={cap} variant="secondary" className="text-xs">
                {cap}
              </Badge>
            ))}
            {model.capabilities.length > 3 && (
              <Badge variant="secondary" className="text-xs">
                +{model.capabilities.length - 3} more
              </Badge>
            )}
          </div>

          {/* Download Progress */}
          {state.downloading && (
            <div className="space-y-2">
              <Progress value={state.progress} className="h-2" />
              <p className="text-xs text-muted-foreground">
                Downloading... {Math.round(state.progress)}%
              </p>
            </div>
          )}

          {/* Error Message */}
          {state.error && (
            <div className="flex items-start gap-2 p-2 rounded-lg text-xs bg-red-50 text-red-800 border border-red-200 dark:bg-red-950 dark:text-red-200 dark:border-red-800">
              <AlertCircle className="h-3 w-3 mt-0.5 flex-shrink-0" />
              <p>{state.error}</p>
            </div>
          )}

          {/* Actions */}
          <div className="flex gap-2">
            {!state.installed && !state.downloading && (
              <Button
                size="sm"
                variant="default"
                className="flex-1"
                onClick={(e) => {
                  e.stopPropagation();
                  handleDownloadModel(model.id);
                }}
              >
                <Download className="h-4 w-4 mr-2" />
                Download
              </Button>
            )}

            {state.installed && (
              <>
                <Button
                  size="sm"
                  variant={isSelected ? 'default' : 'outline'}
                  className="flex-1"
                  onClick={(e) => {
                    e.stopPropagation();
                    onModelSelect(model.id);
                  }}
                >
                  {isSelected ? (
                    <>
                      <Check className="h-4 w-4 mr-2" />
                      Selected
                    </>
                  ) : (
                    'Select'
                  )}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteModel(model.id);
                  }}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </>
            )}

            {state.downloading && (
              <Button size="sm" variant="outline" className="flex-1" disabled>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Downloading...
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  };

  // ============================================================================
  // Render
  // ============================================================================

  if (isLoading) {
    return (
      <div className={cn('flex items-center justify-center p-8', className)}>
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!isOllamaRunning) {
    return (
      <div className={cn('space-y-4', className)}>
        <div className="flex items-start gap-2 p-4 rounded-lg text-sm bg-amber-50 text-amber-800 border border-amber-200 dark:bg-amber-950 dark:text-amber-200 dark:border-amber-800">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-medium">Ollama is not running</p>
            <p className="text-xs mt-1 opacity-90">
              Please start Ollama to manage local models. Visit{' '}
              <a
                href="https://ollama.ai"
                target="_blank"
                rel="noopener noreferrer"
                className="underline"
              >
                ollama.ai
              </a>{' '}
              to download and install.
            </p>
          </div>
        </div>

        <Button onClick={checkOllamaStatus} variant="outline" className="w-full">
          Retry Connection
        </Button>
      </div>
    );
  }

  const filteredModels = getFilteredModels();

  return (
    <div className={cn('space-y-4', className)}>
      {/* Info Banner */}
      <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-blue-50 text-blue-800 border border-blue-200 dark:bg-blue-950 dark:text-blue-200 dark:border-blue-800">
        <Info className="h-4 w-4 mt-0.5 flex-shrink-0" />
        <div>
          <p className="font-medium">Local Model Management</p>
          <p className="text-xs mt-1 opacity-90">
            Download and manage local LLM models. Models run on your machine without requiring API keys.
          </p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        <Button
          size="sm"
          variant={selectedFamily === 'all' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('all')}
        >
          All Models
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'gemma' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('gemma')}
        >
          Gemma
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'llama' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('llama')}
        >
          Llama
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'mistral' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('mistral')}
        >
          Mistral
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'phi' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('phi')}
        >
          Phi
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'qwen' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('qwen')}
        >
          Qwen
        </Button>

        <Separator orientation="vertical" className="h-8" />

        <Button
          size="sm"
          variant={showOnlyInstalled ? 'default' : 'outline'}
          onClick={() => setShowOnlyInstalled(!showOnlyInstalled)}
        >
          <Check className="h-4 w-4 mr-2" />
          Installed Only
        </Button>
      </div>

      {/* Model Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredModels.map(model => renderModelCard(model))}
      </div>

      {filteredModels.length === 0 && (
        <div className="text-center py-8 text-muted-foreground">
          <p>No models found matching your filters.</p>
          <Button
            variant="link"
            onClick={() => {
              setSelectedFamily('all');
              setShowOnlyInstalled(false);
            }}
          >
            Clear filters
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * Ollama Settings Component
 * 
 * Allows users to configure Ollama local LLM with automatic model selection
 */

import { useState, useEffect } from 'react';
import {
  detectSystemCapabilities,
  getModelRecommendation,
  checkOllamaStatus,
  getInstalledModels,
  isModelInstalled,
  GEMMA3_MODELS,
  DEFAULT_OLLAMA_CONFIG,
  type ModelRecommendation,
  type SystemCapabilities,
  type OllamaModelConfig,
} from '@/services/ollamaConfig';

export interface OllamaSettingsProps {
  onConfigChange?: (config: {
    endpoint: string;
    model: string;
  }) => void;
}

export function OllamaSettings({ onConfigChange }: OllamaSettingsProps) {
  const [capabilities, setCapabilities] = useState<SystemCapabilities | null>(null);
  const [recommendation, setRecommendation] = useState<ModelRecommendation | null>(null);
  const [selectedModel, setSelectedModel] = useState<string>('');
  const [endpoint, setEndpoint] = useState(DEFAULT_OLLAMA_CONFIG.endpoint);
  const [isOllamaRunning, setIsOllamaRunning] = useState(false);
  const [installedModels, setInstalledModels] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Detect system capabilities and get recommendation
  useEffect(() => {
    async function initialize() {
      setIsLoading(true);
      setError(null);

      try {
        // Detect system capabilities
        const caps = await detectSystemCapabilities();
        setCapabilities(caps);

        // Get model recommendation
        const rec = await getModelRecommendation();
        setRecommendation(rec);
        setSelectedModel(rec.model.id);

        // Check Ollama status
        const running = await checkOllamaStatus(endpoint);
        setIsOllamaRunning(running);

        if (running) {
          // Get installed models
          const models = await getInstalledModels(endpoint);
          setInstalledModels(models);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to initialize Ollama settings');
      } finally {
        setIsLoading(false);
      }
    }

    initialize();
  }, [endpoint]);

  // Notify parent of config changes
  useEffect(() => {
    if (selectedModel && endpoint) {
      onConfigChange?.({ endpoint, model: selectedModel });
    }
  }, [selectedModel, endpoint, onConfigChange]);

  const handleModelChange = (modelId: string) => {
    setSelectedModel(modelId);
  };

  const handleEndpointChange = (newEndpoint: string) => {
    setEndpoint(newEndpoint);
  };

  const handleRefresh = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const running = await checkOllamaStatus(endpoint);
      setIsOllamaRunning(running);

      if (running) {
        const models = await getInstalledModels(endpoint);
        setInstalledModels(models);
      }
    } catch (err) {
      setError('Failed to connect to Ollama');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-center">
          <div className="mb-4 h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
          <p className="text-sm text-muted-foreground">Detecting system capabilities...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h3 className="text-lg font-semibold">Ollama Configuration</h3>
        <p className="text-sm text-muted-foreground">
          Configure local LLM with automatic model selection based on your system
        </p>
      </div>

      {/* Error Display */}
      {error && (
        <div className="rounded-md bg-destructive/10 p-4 text-sm text-destructive">
          {error}
        </div>
      )}

      {/* Ollama Status */}
      <div className="rounded-lg border p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div
              className={`h-3 w-3 rounded-full ${
                isOllamaRunning ? 'bg-green-500' : 'bg-red-500'
              }`}
            />
            <div>
              <p className="font-medium">
                {isOllamaRunning ? 'Ollama is running' : 'Ollama is not running'}
              </p>
              <p className="text-sm text-muted-foreground">{endpoint}</p>
            </div>
          </div>
          <button
            onClick={handleRefresh}
            className="rounded-md bg-secondary px-3 py-1.5 text-sm hover:bg-secondary/80"
          >
            Refresh
          </button>
        </div>

        {!isOllamaRunning && (
          <div className="mt-4 rounded-md bg-muted p-3 text-sm">
            <p className="font-medium">Ollama not detected</p>
            <p className="mt-1 text-muted-foreground">
              Make sure Ollama is installed and running. Visit{' '}
              <a
                href="https://ollama.ai"
                target="_blank"
                rel="noopener noreferrer"
                className="text-primary underline"
              >
                ollama.ai
              </a>{' '}
              to download.
            </p>
          </div>
        )}
      </div>

      {/* System Capabilities */}
      {capabilities && (
        <div className="rounded-lg border p-4">
          <h4 className="mb-3 font-medium">System Capabilities</h4>
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <p className="text-muted-foreground">Total RAM</p>
              <p className="font-medium">{capabilities.totalRAM.toFixed(1)} GB</p>
            </div>
            <div>
              <p className="text-muted-foreground">Available RAM</p>
              <p className="font-medium">{capabilities.availableRAM.toFixed(1)} GB</p>
            </div>
            <div>
              <p className="text-muted-foreground">GPU</p>
              <p className="font-medium">{capabilities.hasGPU ? 'Yes' : 'No'}</p>
            </div>
            {capabilities.gpuVRAM && (
              <div>
                <p className="text-muted-foreground">GPU VRAM</p>
                <p className="font-medium">{capabilities.gpuVRAM.toFixed(1)} GB</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Model Recommendation */}
      {recommendation && (
        <div className="rounded-lg border border-primary/20 bg-primary/5 p-4">
          <div className="mb-2 flex items-center gap-2">
            <svg
              className="h-5 w-5 text-primary"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
            <h4 className="font-medium">Recommended Model</h4>
          </div>
          <p className="mb-3 text-sm text-muted-foreground">{recommendation.reason}</p>

          {recommendation.warnings.length > 0 && (
            <div className="mb-3 rounded-md bg-yellow-500/10 p-3 text-sm text-yellow-700 dark:text-yellow-400">
              {recommendation.warnings.map((warning, i) => (
                <p key={i}>{warning}</p>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Model Selection */}
      <div className="space-y-3">
        <h4 className="font-medium">Select Model</h4>
        <div className="space-y-2">
          {GEMMA3_MODELS.map((model) => {
            const isInstalled = installedModels.includes(model.id);
            const isRecommended = recommendation?.model.id === model.id;
            const canRun = capabilities
              ? capabilities.availableRAM >= model.minRAM
              : true;

            return (
              <label
                key={model.id}
                className={`flex cursor-pointer items-start gap-3 rounded-lg border p-4 transition-colors ${
                  selectedModel === model.id
                    ? 'border-primary bg-primary/5'
                    : 'hover:bg-muted/50'
                } ${!canRun ? 'opacity-50' : ''}`}
              >
                <input
                  type="radio"
                  name="model"
                  value={model.id}
                  checked={selectedModel === model.id}
                  onChange={(e) => handleModelChange(e.target.value)}
                  disabled={!canRun}
                  className="mt-1"
                />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-medium">{model.name}</p>
                    {isRecommended && (
                      <span className="rounded-full bg-primary px-2 py-0.5 text-xs text-primary-foreground">
                        Recommended
                      </span>
                    )}
                    {isInstalled && (
                      <span className="rounded-full bg-green-500/10 px-2 py-0.5 text-xs text-green-700 dark:text-green-400">
                        Installed
                      </span>
                    )}
                  </div>
                  <p className="mt-1 text-sm text-muted-foreground">{model.description}</p>
                  <div className="mt-2 flex gap-4 text-xs text-muted-foreground">
                    <span>Min RAM: {model.minRAM}GB</span>
                    <span>Recommended: {model.recommendedRAM}GB</span>
                    {model.minVRAM && <span>Min VRAM: {model.minVRAM}GB</span>}
                  </div>
                  {!canRun && (
                    <p className="mt-2 text-xs text-destructive">
                      Insufficient RAM for this model
                    </p>
                  )}
                  {!isInstalled && isOllamaRunning && (
                    <p className="mt-2 text-xs text-muted-foreground">
                      Run: <code className="rounded bg-muted px-1">ollama pull {model.id}</code>
                    </p>
                  )}
                </div>
              </label>
            );
          })}
        </div>
      </div>

      {/* Endpoint Configuration */}
      <div className="space-y-2">
        <label className="text-sm font-medium">Ollama Endpoint</label>
        <input
          type="text"
          value={endpoint}
          onChange={(e) => handleEndpointChange(e.target.value)}
          placeholder="http://localhost:11434"
          className="w-full rounded-md border bg-background px-3 py-2 text-sm"
        />
        <p className="text-xs text-muted-foreground">
          Default: {DEFAULT_OLLAMA_CONFIG.endpoint}
        </p>
      </div>

      {/* Alternative Models */}
      {recommendation && recommendation.alternatives.length > 0 && (
        <div className="rounded-lg border p-4">
          <h4 className="mb-2 font-medium">Alternative Models</h4>
          <p className="mb-3 text-sm text-muted-foreground">
            Other models compatible with your system
          </p>
          <div className="space-y-2">
            {recommendation.alternatives.map((model) => (
              <div key={model.id} className="flex items-center justify-between text-sm">
                <span>{model.name}</span>
                <span className="text-muted-foreground">{model.description}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Tests d'intégration pour AddonsPanel
 * 
 * Teste l'intégration entre l'interface utilisateur et les services de gestion des add-ons
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { AddonsPanel } from '../AddonsPanel';
import { addonManager } from '@/services/AddonManager';
import { fileSystemService } from '@/services/FileSystemService';
import { promises as fs } from 'fs';
import path from 'path';
import { vi } from 'vitest';

// Mock useToast hook
vi.mock('@/hooks/use-toast', () => ({
  useToast: () => ({
    toast: vi.fn()
  })
}));

describe('AddonsPanel Integration Tests', () => {
  const testFile = 'test-addons-panel.json';

  beforeEach(async () => {
    // Nettoyer le fichier de test
    try {
      await fs.unlink(testFile);
    } catch {}

    // Réinitialiser le manager
    await addonManager.initialize();
  });

  afterEach(async () => {
    // Nettoyer le fichier de test
    try {
      await fs.unlink(testFile);
    } catch {}
  });

  it('should render and initialize add-ons', async () => {
    render(<AddonsPanel />);

    // Vérifier que le titre est affiché
    expect(screen.getByText('Gestion des Add-ons')).toBeInTheDocument();

    // Vérifier que les boutons d'export/import sont présents
    expect(screen.getByText('Exporter')).toBeInTheDocument();
    expect(screen.getByText('Importer')).toBeInTheDocument();

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });
  });

  it('should export configuration when export button is clicked', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Exporter
    const exportButton = screen.getByText('Exporter');
    fireEvent.click(exportButton);

    // Vérifier que le fichier a été créé
    const fileExists = await fileSystemService.fileExists(testFile);
    expect(fileExists).toBe(true);

    // Vérifier le contenu du fichier
    const config = await fileSystemService.readConfigFile(testFile);
    expect(config).toBeDefined();
  });

  it('should import configuration when import button is clicked', async () => {
    // Créer un fichier de configuration de test
    const testConfig = {
      'casting': {
        enabled: true,
        settings: { maxActorsPerScene: 10 }
      }
    };

    await fileSystemService.writeConfigFile(testFile, testConfig);

    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Importer
    const importButton = screen.getByText('Importer');
    fireEvent.click(importButton);

    // Vérifier que la configuration a été importée
    const castingAddon = addonManager.getAddon('casting');
    expect(castingAddon?.enabled).toBe(true);

    const settings = addonManager.getAddonSettings('casting');
    expect(settings?.maxActorsPerScene).toBe(10);
  });

  it('should toggle add-on activation', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Trouver le bouton d'activation pour le casting
    const toggleButton = screen.getByText('Activer');
    fireEvent.click(toggleButton);

    // Attendre que l'add-on soit activé
    await waitFor(() => {
      expect(screen.getByText('Désactiver')).toBeInTheDocument();
    });

    // Vérifier que l'add-on est activé
    const castingAddon = addonManager.getAddon('casting');
    expect(castingAddon?.enabled).toBe(true);
  });

  it('should filter add-ons by search query', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Rechercher "Audio"
    const searchInput = screen.getByPlaceholderText('Rechercher des add-ons...');
    fireEvent.change(searchInput, { target: { value: 'Audio' } });

    // Vérifier que seul l'add-on audio est affiché
    expect(screen.getByText('Audio Production Suite')).toBeInTheDocument();
    expect(screen.queryByText('Casting Manager')).not.toBeInTheDocument();
  });

  it('should filter add-ons by category', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Filtrer par catégorie "Traitement"
    const processingButton = screen.getByText('Traitement');
    fireEvent.click(processingButton);

    // Vérifier que seuls les add-ons de traitement sont affichés
    expect(screen.getByText('Audio Production Suite')).toBeInTheDocument();
    expect(screen.getByText('Comic to Sequence Converter')).toBeInTheDocument();
    expect(screen.queryByText('Casting Manager')).not.toBeInTheDocument();
  });

  it('should handle export error gracefully', async () => {
    // Simuler une erreur d'écriture de fichier
    const originalWriteFile = fileSystemService.writeConfigFile;
    fileSystemService.writeConfigFile = async () => {
      throw new Error('Permission denied');
    };

    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Exporter
    const exportButton = screen.getByText('Exporter');
    fireEvent.click(exportButton);

    // Restaurer la méthode originale
    fileSystemService.writeConfigFile = originalWriteFile;

    // Vérifier que l'erreur est gérée (pas de crash)
    expect(screen.getByText('Casting Manager')).toBeInTheDocument();
  });

  it('should handle import error gracefully', async () => {
    // Créer un fichier de configuration invalide
    await fs.writeFile(testFile, 'invalid json content', 'utf-8');

    render(<AddonsPanel />);

    // Attendre que les add-ons soient chargés
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Importer
    const importButton = screen.getByText('Importer');
    fireEvent.click(importButton);

    // Vérifier que l'erreur est gérée (pas de crash)
    expect(screen.getByText('Casting Manager')).toBeInTheDocument();
  });
});

/**
 * Integration Tests for LLM Settings Panel Persistence
 * 
 * Tests the integration of LLMSettingsPanel with secure storage
 * Validates Requirements: 3.7, 10.1, 10.2, 10.3, 10.4, 10.6
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { LLMSettingsPanel } from '../LLMSettingsPanel';
import * as secureStorage from '@/utils/secureStorage';
import type { LLMConfig } from '@/services/llmService';

// ============================================================================
// Test Setup
// ============================================================================

// Mock secure storage
vi.mock('@/utils/secureStorage', () => ({
  saveLLMSettings: vi.fn(),
  loadLLMSettings: vi.fn(),
  deleteLLMSettings: vi.fn(),
  exportSettings: vi.fn(),
  importSettings: vi.fn(),
  clearAllSettings: vi.fn(),
  isCryptoAvailable: vi.fn(() => true),
  hasStoredSettings: vi.fn(() => false),
  getLastValidationTime: vi.fn(() => null),
}));

// Mock crypto API
const mockCrypto = {
  subtle: {
    generateKey: vi.fn(),
    importKey: vi.fn(),
    exportKey: vi.fn(),
    encrypt: vi.fn(),
    decrypt: vi.fn(),
  },
  getRandomValues: vi.fn((arr: Uint8Array) => {
    for (let i = 0; i < arr.length; i++) {
      arr[i] = i;
    }
    return arr;
  }),
};

beforeEach(() => {
  localStorage.clear();
  sessionStorage.clear();
  global.crypto = mockCrypto as any;
  vi.clearAllMocks();
});

// ============================================================================
// Sample Data
// ============================================================================

const sampleConfig: LLMConfig = {
  provider: 'openai',
  apiKey: 'sk-test-key',
  model: 'gpt-4',
  parameters: {
    temperature: 0.7,
    maxTokens: 2000,
    topP: 1.0,
    frequencyPenalty: 0,
    presencePenalty: 0,
  },
  systemPrompts: {
    worldGeneration: 'Generate world...',
    characterGeneration: 'Generate character...',
    dialogueGeneration: 'Generate dialogue...',
  },
  timeout: 30000,
  retryAttempts: 3,
  streamingEnabled: true,
};

// ============================================================================
// Loading Tests
// ============================================================================

describe('Settings Loading', () => {
  it('should load stored settings on mount', async () => {
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(sampleConfig);

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    // Should show loading state initially
    expect(screen.getByRole('progressbar', { hidden: true })).toBeInTheDocument();

    // Wait for settings to load
    await waitFor(() => {
      expect(secureStorage.loadLLMSettings).toHaveBeenCalled();
    });

    // Should populate form with loaded settings
    await waitFor(() => {
      const apiKeyInput = screen.getByLabelText('API Key') as HTMLInputElement;
      expect(apiKeyInput.value).toBe(sampleConfig.apiKey);
    });
  });

  it('should handle loading failure gracefully', async () => {
    vi.mocked(secureStorage.loadLLMSettings).mockRejectedValue(new Error('Load failed'));

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    // Should still render form with defaults
    await waitFor(() => {
      expect(screen.getByLabelText('API Key')).toBeInTheDocument();
    });
  });

  it('should show last validation time when available', async () => {
    const lastValidated = new Date('2024-01-15T10:30:00Z');
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(sampleConfig);
    vi.mocked(secureStorage.getLastValidationTime).mockReturnValue(lastValidated);

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    await waitFor(() => {
      expect(screen.getByText(/Last validated:/)).toBeInTheDocument();
    });
  });

  it('should show warning when crypto is unavailable', async () => {
    vi.mocked(secureStorage.isCryptoAvailable).mockReturnValue(false);
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(null);

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    await waitFor(() => {
      expect(screen.getByText(/Encryption unavailable/)).toBeInTheDocument();
    });
  });
});

// ============================================================================
// Saving Tests
// ============================================================================

describe('Settings Saving', () => {
  it('should save settings with encryption', async () => {
    const user = userEvent.setup();
    const onSave = vi.fn();
    const onTestConnection = vi.fn().mockResolvedValue(true);
    
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(null);
    vi.mocked(secureStorage.saveLLMSettings).mockResolvedValue();

    render(
      <LLMSettingsPanel
        onSave={onSave}
        onTestConnection={onTestConnection}
      />
    );

    await waitFor(() => {
      expect(screen.getByLabelText('API Key')).toBeInTheDocument();
    });

    // Fill in form
    await user.type(screen.getByLabelText('API Key'), 'sk-test-key');
    
    // Test connection
    await user.click(screen.getByText('Test Connection'));
    await waitFor(() => {
      expect(screen.getByText(/Connection successful/)).toBeInTheDocument();
    });

    // Save settings
    await user.click(screen.getByText('Save Settings'));

    await waitFor(() => {
      expect(secureStorage.saveLLMSettings).toHaveBeenCalled();
      expect(onSave).toHaveBeenCalled();
    });
  });

  it('should show success message after saving', async () => {
    const user = userEvent.setup();
    const onTestConnection = vi.fn().mockResolvedValue(true);
    
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(null);
    vi.mocked(secureStorage.saveLLMSettings).mockResolvedValue();

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={onTestConnection}
      />
    );

    await waitFor(() => {
      expect(screen.getByLabelText('API Key')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText('API Key'), 'sk-test-key');
    await user.click(screen.getByText('Test Connection'));
    
    await waitFor(() => {
      expect(screen.getByText(/Connection successful/)).toBeInTheDocument();
    });

    await user.click(screen.getByText('Save Settings'));

    await waitFor(() => {
      expect(screen.getByText(/Settings saved successfully/)).toBeInTheDocument();
    });
  });

  it('should handle save failure', async () => {
    const user = userEvent.setup();
    const onTestConnection = vi.fn().mockResolvedValue(true);
    
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(null);
    vi.mocked(secureStorage.saveLLMSettings).mockRejectedValue(new Error('Save failed'));

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={onTestConnection}
      />
    );

    await waitFor(() => {
      expect(screen.getByLabelText('API Key')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText('API Key'), 'sk-test-key');
    await user.click(screen.getByText('Test Connection'));
    
    await waitFor(() => {
      expect(screen.getByText(/Connection successful/)).toBeInTheDocument();
    });

    await user.click(screen.getByText('Save Settings'));

    await waitFor(() => {
      expect(screen.getByText(/Save failed/)).toBeInTheDocument();
    });
  });
});

// ============================================================================
// Export Tests
// ============================================================================

describe('Settings Export', () => {
  it('should export settings without credentials', async () => {
    const user = userEvent.setup();
    const exportData = JSON.stringify({ version: '1.0', llm: { config: {} } });
    
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(sampleConfig);
    vi.mocked(secureStorage.exportSettings).mockReturnValue(exportData);

    // Mock URL.createObjectURL and related functions
    global.URL.createObjectURL = vi.fn(() => 'blob:mock-url');
    global.URL.revokeObjectURL = vi.fn();
    
    // Mock document.createElement to track link creation
    const mockLink = {
      href: '',
      download: '',
      click: vi.fn(),
    };
    const originalCreateElement = document.createElement.bind(document);
    document.createElement = vi.fn((tag) => {
      if (tag === 'a') {
        return mockLink as any;
      }
      return originalCreateElement(tag);
    });

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    await waitFor(() => {
      expect(screen.getByText('Export Settings')).toBeInTheDocument();
    });

    await user.click(screen.getByText('Export Settings'));

    await waitFor(() => {
      expect(secureStorage.exportSettings).toHaveBeenCalled();
      expect(mockLink.click).toHaveBeenCalled();
    });
  });

  it('should show success message after export', async () => {
    const user = userEvent.setup();
    
    vi.mocked(secureStorage.loadLLMSettings).mockResolvedValue(sampleConfig);
    vi.mocked(secureStorage.exportSettings).mockReturnValue('{}');

    global.URL.createObjectURL = vi.fn(() => 'blob:mock-url');
    global.URL.revokeObjectURL = vi.fn();

    render(
      <LLMSettingsPanel
        onSave={vi.fn()}
        onTestConnection={vi.fn()}
      />
    );

    await waitFor(() => {
      expect(screen.getByText('Export Settings')).toBeInTheDocument();
    });

    await user.click(screen.getByText('Export Settings'));

    await waitFor(() => {
      expect(screen.getByText(/exported successfully/)).toBeInTheDocument();
    });
  });
});

