/**
 * Skeleton Loader Component
 * Provides visual loading states with animated skeleton placeholders
 */

import React from 'react';
import { cn } from '@/lib/utils';

interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: 'text' | 'circular' | 'rectangular' | 'rounded';
  width?: number | string;
  height?: number | string;
  animation?: 'pulse' | 'wave' | 'none';
}

/**
 * Base skeleton component with variant and animation options
 */
export function Skeleton({
  className,
  variant = 'text',
  width,
  height,
  animation = 'pulse',
  ...props
}: SkeletonProps) {
  const variantClasses = {
    text: 'rounded h-4',
    circular: 'rounded-full',
    rectangular: 'rounded-none',
    rounded: 'rounded-md',
  };

  const animationClasses = {
    pulse: 'animate-pulse',
    wave: 'animate-shimmer',
    none: '',
  };

  return (
    <div
      className={cn(
        'bg-muted',
        variantClasses[variant],
        animationClasses[animation],
        className
      )}
      style={{
        width: width !== undefined ? (typeof width === 'number' ? `${width}px` : width) : undefined,
        height: height !== undefined ? (typeof height === 'number' ? `${height}px` : height) : undefined,
      }}
      {...props}
    />
  );
}

/**
 * Single line text skeleton
 */
export function SkeletonText({
  className,
  lines = 1,
  width = '100%',
  lastLineWidth,
  ...props
}: {
  className?: string;
  lines?: number;
  width?: number | string;
  lastLineWidth?: number | string;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-2', className)} {...props}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton
          key={i}
          variant="text"
          width={i === lines - 1 && lastLineWidth ? lastLineWidth : width}
          height={16}
        />
      ))}
    </div>
  );
}

/**
 * Avatar/Circular skeleton for profile images
 */
export function SkeletonAvatar({
  className,
  size = 40,
  ...props
}: {
  className?: string;
  size?: number;
  [key: string]: unknown;
}) {
  return (
    <Skeleton
      className={className}
      variant="circular"
      width={size}
      height={size}
      {...props}
    />
  );
}

/**
 * Card skeleton for content cards
 */
export function SkeletonCard({
  className,
  showAvatar = true,
  showTitle = true,
  showDescription = true,
  lines = 3,
  ...props
}: {
  className?: string;
  showAvatar?: boolean;
  showTitle?: boolean;
  showDescription?: boolean;
  lines?: number;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-4 p-4 border rounded-lg', className)} {...props}>
      {/* Header with avatar */}
      {showAvatar && (
        <div className="flex items-center gap-3">
          <SkeletonAvatar size={48} />
          <div className="flex-1 space-y-2">
            {showTitle && (
              <Skeleton variant="text" width="60%" height={20} />
            )}
            {showDescription && (
              <Skeleton variant="text" width="40%" height={14} />
            )}
          </div>
        </div>
      )}
      
      {/* Content lines */}
      <SkeletonText lines={lines} />
      
      {/* Footer */}
      <div className="flex gap-2 pt-2">
        <Skeleton variant="rounded" width={80} height={32} />
        <Skeleton variant="rounded" width={80} height={32} />
      </div>
    </div>
  );
}

/**
 * Table row skeleton
 */
export function SkeletonTableRow({
  className,
  columns = 4,
  showActions = true,
  ...props
}: {
  className?: string;
  columns?: number;
  showActions?: boolean;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('flex gap-4 py-3 border-b items-center', className)} {...props}>
      {/* Checkbox */}
      <Skeleton variant="rounded" width={20} height={20} />
      
      {/* Data columns */}
      {Array.from({ length: columns }).map((_, i) => (
        <Skeleton
          key={i}
          variant="text"
          width={i === 0 ? 120 : i === columns - 1 ? 80 : 100}
          height={16}
        />
      ))}
      
      {/* Actions */}
      {showActions && (
        <div className="flex gap-2 ml-auto">
          <Skeleton variant="rounded" width={32} height={32} />
          <Skeleton variant="rounded" width={32} height={32} />
        </div>
      )}
    </div>
  );
}

/**
 * Media item skeleton for galleries
 */
export function SkeletonMediaItem({
  className,
  aspectRatio = '16/9',
  showInfo = true,
  ...props
}: {
  className?: string;
  aspectRatio?: string;
  showInfo?: boolean;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-2', className)} {...props}>
      <div
        className="bg-muted animate-pulse rounded-md overflow-hidden"
        style={{ aspectRatio }}
      />
      {showInfo && (
        <div className="space-y-1">
          <Skeleton variant="text" width="80%" height={16} />
          <Skeleton variant="text" width="50%" height={12} />
        </div>
      )}
    </div>
  );
}

/**
 * Timeline/Shot skeleton
 */
export function SkeletonTimeline({
  className,
  shots = 5,
  showWaveform = true,
  ...props
}: {
  className?: string;
  shots?: number;
  showWaveform?: boolean;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-2', className)} {...props}>
      {Array.from({ length: shots }).map((_, i) => (
        <div key={i} className="flex gap-3 p-2 border rounded">
          {/* Thumbnail */}
          <Skeleton variant="rounded" width={80} height={50} />
          
          {/* Info */}
          <div className="flex-1 space-y-2">
            <Skeleton variant="text" width="40%" height={18} />
            <Skeleton variant="text" width="30%" height={14} />
            
            {/* Waveform */}
            {showWaveform && (
              <div className="flex items-end gap-0.5 h-8">
                {Array.from({ length: 20 }).map((_, j) => (
                  <Skeleton
                    key={j}
                    variant="rounded"
                    width={3}
                    height={Math.random() * 30 + 10}
                    className="flex-shrink-0"
                  />
                ))}
              </div>
            )}
          </div>
          
          {/* Duration */}
          <Skeleton variant="text" width={50} height={14} />
        </div>
      ))}
    </div>
  );
}

/**
 * Form skeleton
 */
export function SkeletonForm({
  className,
  fields = 4,
  showSubmit = true,
  ...props
}: {
  className?: string;
  fields?: number;
  showSubmit?: boolean;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-6', className)} {...props}>
      {Array.from({ length: fields }).map((_, i) => (
        <div key={i} className="space-y-2">
          <Skeleton variant="text" width={120} height={14} />
          <Skeleton variant="rounded" width="100%" height={40} />
        </div>
      ))}
      
      {showSubmit && (
        <Skeleton variant="rounded" width={120} height={40} className="mt-4" />
      )}
    </div>
  );
}

/**
 * Dashboard widget skeleton
 */
export function SkeletonWidget({
  className,
  title = true,
  chart = true,
  stats = 4,
  ...props
}: {
  className?: string;
  title?: boolean;
  chart?: boolean;
  stats?: number;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-4 p-4 border rounded-lg', className)} {...props}>
      {title && (
        <Skeleton variant="text" width={150} height={20} />
      )}
      
      {chart && (
        <Skeleton variant="rounded" width="100%" height={150} />
      )}
      
      {stats > 0 && (
        <div className="grid grid-cols-2 gap-4">
          {Array.from({ length: stats }).map((_, i) => (
            <div key={i} className="space-y-1">
              <Skeleton variant="text" width={60} height={12} />
              <Skeleton variant="text" width={80} height={24} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Conversation/Chat skeleton
 */
export function SkeletonConversation({
  className,
  messages = 3,
  ...props
}: {
  className?: string;
  messages?: number;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-4', className)} {...props}>
      {Array.from({ length: messages }).map((_, i) => (
        <div
          key={i}
          className={cn(
            'flex gap-3',
            i % 2 === 1 && 'flex-row-reverse'
          )}
        >
          <SkeletonAvatar size={32} />
          <div className={cn('space-y-2', i % 2 === 1 && 'items-end')}>
            <Skeleton
              variant="rounded"
              width={Math.random() * 100 + 150}
              height={i === 1 ? 60 : 40}
              className={cn(i % 2 === 1 && '!bg-muted-foreground/20')}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Wizard step skeleton
 */
export function SkeletonWizardStep({
  className,
  steps = 3,
  currentStep = 1,
  ...props
}: {
  className?: string;
  steps?: number;
  currentStep?: number;
  [key: string]: unknown;
}) {
  return (
    <div className={cn('space-y-6', className)} {...props}>
      {/* Progress indicator */}
      <div className="flex items-center justify-between">
        {Array.from({ length: steps }).map((_, i) => (
          <React.Fragment key={i}>
            <div className="flex items-center gap-2">
              <Skeleton
                variant="circular"
                width={32}
                height={32}
                animation={i + 1 < currentStep ? 'none' : 'pulse'}
                className={i + 1 < currentStep ? 'bg-green-500' : ''}
              />
              <Skeleton variant="text" width={60} height={12} />
            </div>
            {i < steps - 1 && (
              <Skeleton
                variant="text"
                width={40}
                height={2}
                className="flex-1 mx-2"
              />
            )}
          </React.Fragment>
        ))}
      </div>
      
      {/* Content area */}
      <SkeletonCard />
    </div>
  );
}

export default Skeleton;

/**
 * Task Queue Panel Component
 * 
 * Displays the generation job queue with priority controls.
 * Allows users to reorder jobs, retry failed jobs, and monitor progress.
 */

import { useState, useEffect, useCallback } from 'react';
import type {
  TaskQueueItem,
  TaskQueueResponse,
  PriorityUpdateResponse,
  RetryResponse,
} from '../types';
import {
  getTaskQueue,
  moveJobUp,
  moveJobDown,
  retryJob,
  deleteJob,
  getStatusColor,
  getPriorityColor,
  formatEstimatedTime,
  getStatusIcon,
  getPriorityIcon,
} from '../services/taskQueueService';

interface TaskQueuePanelProps {
  projectId?: string;
  isOpen?: boolean;
  onClose?: () => void;
}

export function TaskQueuePanel({ projectId, isOpen = true, onClose }: TaskQueuePanelProps) {
  const [tasks, setTasks] = useState<TaskQueueItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<string>('all');
  const [autoRefresh, setAutoRefresh] = useState(true);

  // Fetch tasks
  const fetchTasks = useCallback(async () => {
    try {
      setError(null);
      const response = await getTaskQueue(projectId, filter === 'all' ? undefined : filter);
      setTasks(response.tasks);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch tasks');
    } finally {
      setLoading(false);
    }
  }, [projectId, filter]);

  // Initial fetch and auto-refresh
  useEffect(() => {
    fetchTasks();

    if (autoRefresh) {
      const interval = setInterval(fetchTasks, 5000);
      return () => clearInterval(interval);
    }
  }, [fetchTasks, autoRefresh]);

  // Handle move job up
  const handleMoveUp = async (jobId: string) => {
    try {
      await moveJobUp(jobId);
      fetchTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to move job up');
    }
  };

  // Handle move job down
  const handleMoveDown = async (jobId: string) => {
    try {
      await moveJobDown(jobId);
      fetchTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to move job down');
    }
  };

  // Handle retry job
  const handleRetry = async (jobId: string) => {
    try {
      await retryJob(jobId);
      fetchTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to retry job');
    }
  };

  // Handle delete job
  const handleDelete = async (jobId: string) => {
    try {
      await deleteJob(jobId);
      fetchTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete job');
    }
  };

  // Stats calculation
  const stats = {
    total: tasks.length,
    pending: tasks.filter(t => t.status === 'pending').length,
    processing: tasks.filter(t => t.status === 'processing').length,
    completed: tasks.filter(t => t.status === 'completed').length,
    failed: tasks.filter(t => t.status === 'failed').length,
    cancelled: tasks.filter(t => t.status === 'cancelled').length,
  };

  if (!isOpen) return null;

  return (
    <div className="task-queue-panel bg-gray-900 border-l border-gray-700 w-96 flex flex-col h-full">
      {/* Header */}
      <div className="panel-header p-4 border-b border-gray-700 flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-white">File d'attente</h2>
          <p className="text-xs text-gray-400 mt-1">
            {stats.total} tâche(s) • {stats.processing} en cours
          </p>
        </div>
        <button
          onClick={onClose}
          className="text-gray-400 hover:text-white transition-colors"
        >
          ✕
        </button>
      </div>

      {/* Filters and controls */}
      <div className="p-4 border-b border-gray-700 space-y-3">
        <div className="flex gap-2">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="flex-1 bg-gray-800 text-white text-sm rounded px-3 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
            title="Filtrer les tâches par statut"
          >
            <option value="all">Toutes les tâches</option>
            <option value="pending">En attente</option>
            <option value="processing">En cours</option>
            <option value="completed">Terminées</option>
            <option value="failed">Échouées</option>
            <option value="cancelled">Annulées</option>
          </select>
          <button
            onClick={() => setAutoRefresh(!autoRefresh)}
            className={`px-3 py-2 rounded text-sm border transition-colors ${
              autoRefresh
                ? 'bg-green-500/20 border-green-500/50 text-green-400'
                : 'bg-gray-800 border-gray-600 text-gray-400'
            }`}
            title={autoRefresh ? 'Auto-refresh activé' : 'Auto-refresh désactivé'}
          >
            {autoRefresh ? '🔄' : '⏸️'}
          </button>
        </div>
        
        {/* Stats */}
        <div className="flex gap-2 text-xs">
          <span className="bg-yellow-500/20 text-yellow-400 px-2 py-1 rounded">
            ⏳ {stats.pending}
          </span>
          <span className="bg-blue-500/20 text-blue-400 px-2 py-1 rounded">
            ⚙️ {stats.processing}
          </span>
          <span className="bg-green-500/20 text-green-400 px-2 py-1 rounded">
            ✅ {stats.completed}
          </span>
          <span className="bg-red-500/20 text-red-400 px-2 py-1 rounded">
            ❌ {stats.failed}
          </span>
        </div>
      </div>

      {/* Error message */}
      {error && (
        <div className="mx-4 mt-4 p-3 bg-red-500/20 border border-red-500/50 rounded text-red-400 text-sm">
          {error}
        </div>
      )}

      {/* Task list */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {loading && tasks.length === 0 ? (
          <div className="flex items-center justify-center h-32">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
          </div>
        ) : tasks.length === 0 ? (
          <div className="text-center text-gray-400 py-8">
            <p>Aucune tâche dans la file</p>
            <p className="text-xs mt-2">Les tâches de génération apparaîtront ici</p>
          </div>
        ) : (
          tasks.map((task, index) => (
            <TaskCard
              key={task.job_id}
              task={task}
              index={index}
              isFirst={index === 0}
              isLast={index === tasks.length - 1}
              onMoveUp={handleMoveUp}
              onMoveDown={handleMoveDown}
              onRetry={handleRetry}
              onDelete={handleDelete}
            />
          ))
        )}
      </div>

      {/* Footer */}
      <div className="p-4 border-t border-gray-700">
        <button
          onClick={fetchTasks}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 rounded transition-colors"
        >
          Rafraîchir
        </button>
      </div>
    </div>
  );
}

/**
 * Task card component
 */
interface TaskCardProps {
  task: TaskQueueItem;
  index: number;
  isFirst: boolean;
  isLast: boolean;
  onMoveUp: (jobId: string) => void;
  onMoveDown: (jobId: string) => void;
  onRetry: (jobId: string) => void;
  onDelete: (jobId: string) => void;
}

function TaskCard({
  task,
  isFirst,
  isLast,
  onMoveUp,
  onMoveDown,
  onRetry,
  onDelete,
}: TaskCardProps) {
  const [expanded, setExpanded] = useState(false);

  const isPendingOrProcessing = task.status === 'pending' || task.status === 'processing';

  return (
    <div className="bg-gray-800 rounded-lg border border-gray-700 overflow-hidden">
      {/* Task header */}
      <div className="p-3">
        <div className="flex items-start gap-3">
          {/* Priority indicator */}
          <div className={`w-8 h-8 rounded flex items-center justify-center text-sm font-bold ${getPriorityColor(task.priority)}`}>
            {getPriorityIcon(task.priority)}
          </div>

          {/* Task info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <span className={`px-2 py-0.5 rounded text-xs font-medium border ${getStatusColor(task.status)}`}>
                {getStatusIcon(task.status)} {task.status}
              </span>
              <span className="text-xs text-gray-400">
                #{task.shot_count} shots
              </span>
            </div>
            
            <p className="text-white text-sm mt-1 truncate">
              {task.prompt}
            </p>

            {/* Progress bar for processing tasks */}
            {task.status === 'processing' && (
              <div className="mt-2">
                <div className="flex justify-between text-xs text-gray-400 mb-1">
                  <span>{task.current_step || 'Traitement...'}</span>
                  <span>{task.progress}%</span>
                </div>
                <div className="h-1.5 bg-gray-700 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-blue-500 animate-pulse"
                    style={{ width: `${task.progress}%` }}
                  />
                </div>
              </div>
            )}

            {/* Error message for failed tasks */}
            {task.status === 'failed' && task.error && (
              <p className="text-red-400 text-xs mt-1">
                Erreur: {task.error}
              </p>
            )}
          </div>

          {/* Expand button */}
          <button
            onClick={() => setExpanded(!expanded)}
            className="text-gray-400 hover:text-white transition-colors"
          >
            {expanded ? '▼' : '▶'}
          </button>
        </div>

        {/* Expandable details */}
        {expanded && (
          <div className="mt-3 pt-3 border-t border-gray-700 space-y-2">
            {/* Details row */}
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div>
                <span className="text-gray-400">Créé:</span>
                <span className="text-gray-300 ml-2">
                  {new Date(task.created_at).toLocaleString()}
                </span>
              </div>
              <div>
                <span className="text-gray-400">Estimé:</span>
                <span className="text-gray-300 ml-2">
                  {formatEstimatedTime(task.estimated_time)}
                </span>
              </div>
              {task.started_at && (
                <div>
                  <span className="text-gray-400">Début:</span>
                  <span className="text-gray-300 ml-2">
                    {new Date(task.started_at).toLocaleString()}
                  </span>
                </div>
              )}
              {task.completed_at && (
                <div>
                  <span className="text-gray-400">Fin:</span>
                  <span className="text-gray-300 ml-2">
                    {new Date(task.completed_at).toLocaleString()}
                  </span>
                </div>
              )}
            </div>

            {/* Priority info */}
            <div className="flex items-center gap-2 text-xs">
              <span className="text-gray-400">Priorité:</span>
              <span className={`px-2 py-0.5 rounded ${getPriorityColor(task.priority)}`}>
                {task.priority}/10
              </span>
              {isPendingOrProcessing && (
                <span className="text-gray-400">
                  (1 = plus prioritaire)
                </span>
              )}
            </div>

            {/* Actions */}
            <div className="flex gap-2 pt-2">
              {/* Move up/down buttons (only for pending jobs) */}
              {isPendingOrProcessing && (
                <>
                  <button
                    onClick={() => onMoveUp(task.job_id)}
                    disabled={isFirst}
                    className={`px-2 py-1 text-xs rounded border transition-colors ${
                      isFirst
                        ? 'bg-gray-700/50 border-gray-600/50 text-gray-500 cursor-not-allowed'
                        : 'bg-gray-700 border-gray-600 text-gray-300 hover:bg-gray-600'
                    }`}
                    title="Monter dans la file"
                  >
                    ↑
                  </button>
                  <button
                    onClick={() => onMoveDown(task.job_id)}
                    disabled={isLast}
                    className={`px-2 py-1 text-xs rounded border transition-colors ${
                      isLast
                        ? 'bg-gray-700/50 border-gray-600/50 text-gray-500 cursor-not-allowed'
                        : 'bg-gray-700 border-gray-600 text-gray-300 hover:bg-gray-600'
                    }`}
                    title="Descendre dans la file"
                  >
                    ↓
                  </button>
                </>
              )}

              {/* Retry button (for failed/cancelled jobs) */}
              {(task.status === 'failed' || task.status === 'cancelled') && (
                <button
                  onClick={() => onRetry(task.job_id)}
                  className="px-2 py-1 text-xs rounded border bg-yellow-500/20 border-yellow-500/50 text-yellow-400 hover:bg-yellow-500/30 transition-colors"
                >
                  🔄 Réessayer
                </button>
              )}

              {/* Delete button (for completed/failed/cancelled jobs) */}
              {(task.status === 'completed' || task.status === 'failed' || task.status === 'cancelled') && (
                <button
                  onClick={() => onDelete(task.job_id)}
                  className="px-2 py-1 text-xs rounded border bg-red-500/20 border-red-500/50 text-red-400 hover:bg-red-500/30 transition-colors"
                >
                  🗑️ Supprimer
                </button>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default TaskQueuePanel;

import React, { useState, useRef, useCallback } from 'react';
import { Play, Pause, StopCircle, Volume2, VolumeX } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from './button';

// ============================================================================
// VoicePreview Component
// Prévisualisation audio des voix SAPI
// ============================================================================

interface VoicePreviewProps {
  voiceId: string;
  voiceName?: string;
  sampleText?: string;
  disabled?: boolean;
  className?: string;
}

export function VoicePreview({
  voiceId,
  voiceName,
  sampleText = "Bonjour, je suis la voix de prévisualisation.",
  disabled = false,
  className,
}: VoicePreviewProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const stopAudio = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    setIsPlaying(false);
    setIsLoading(false);
  }, []);

  const playPreview = useCallback(async () => {
    if (!voiceId) return;

    // Si déjà en cours de lecture, arrêter
    if (isPlaying) {
      stopAudio();
      return;
    }

    setIsLoading(true);

    try {
      // Appel au service TTS pour générer l'audio
      const response = await fetch('/api/tts/preview', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          voiceId,
          text: sampleText,
        }),
      });

      if (!response.ok) {
        throw new Error('Erreur lors de la génération audio');
      }

      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      
      setAudioUrl(url);
      
      // Créer l'élément audio
      const audio = new Audio(url);
      audioRef.current = audio;

      audio.onended = () => {
        setIsPlaying(false);
        setIsLoading(false);
      };

      audio.onerror = () => {
        setIsPlaying(false);
        setIsLoading(false);
        console.error('Erreur de lecture audio');
      };

      audio.play();
      setIsPlaying(true);
    } catch (error) {
      console.error('Erreur de prévisualisation:', error);
      setIsLoading(false);
    }
  }, [voiceId, sampleText, isPlaying, stopAudio]);

  // Nettoyer l'URL audio lors du démontage
  React.useEffect(() => {
    return () => {
      if (audioUrl) {
        URL.revokeObjectURL(audioUrl);
      }
    };
  }, [audioUrl]);

  return (
    <div className={cn('flex items-center gap-2', className)}>
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={playPreview}
        disabled={!voiceId || disabled || isLoading}
        className="gap-2"
      >
        {isLoading ? (
          <>
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-300 border-t-gray-600" />
            <span>Génération...</span>
          </>
        ) : isPlaying ? (
          <>
            <StopCircle className="h-4 w-4" />
            <span>Arrêter</span>
          </>
        ) : (
          <>
            <Play className="h-4 w-4" />
            <span>Écouter</span>
          </>
        )}
      </Button>

      {voiceName && (
        <span className="text-sm text-muted-foreground">
          {voiceName}
        </span>
      )}

      {audioUrl && (
        <audio ref={audioRef} className="hidden" src={audioUrl} />
      )}
    </div>
  );
}

// ============================================================================
// VoiceSelector Component
// Sélecteur de voix avec prévisualisation
// ============================================================================

interface Voice {
  id: string;
  name: string;
  gender?: string;
  language?: string;
  age?: string;
}

interface VoiceSelectorProps {
  voices: Voice[];
  value: string;
  onChange: (voiceId: string) => void;
  label?: string;
  required?: boolean;
  helpText?: string;
  className?: string;
}

export function VoiceSelector({
  voices,
  value,
  onChange,
  label = 'Voix SAPI',
  required = false,
  helpText,
  className,
}: VoiceSelectorProps) {
  const selectedVoice = voices.find(v => v.id === value);

  return (
    <div className={cn('space-y-2', className)}>
      {label && (
        <label className="block text-sm font-medium text-foreground">
          {label}
          {required && <span className="text-red-500 ml-1">*</span>}
        </label>
      )}

      <select
        id="voice-selector"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        aria-label={label}
        className={cn(
          'w-full px-3 py-2 rounded-lg border border-input bg-background',
          'text-foreground focus:outline-none focus:ring-2 focus:ring-ring',
          'disabled:opacity-50 disabled:cursor-not-allowed'
        )}
        disabled={voices.length === 0}
      >
        <option value="">Sélectionnez une voix</option>
        {voices.map(voice => (
          <option key={voice.id} value={voice.id}>
            {voice.name} {voice.gender && `(${voice.gender})`} {voice.language && `- ${voice.language}`}
          </option>
        ))}
      </select>

      {helpText && (
        <p className="text-sm text-muted-foreground">{helpText}</p>
      )}

      {selectedVoice && (
        <VoicePreview
          voiceId={selectedVoice.id}
          voiceName={selectedVoice.name}
          disabled={!selectedVoice.id}
        />
      )}
    </div>
  );
}

// ============================================================================
// VoiceComparison Component
// Comparaison de plusieurs voix côte à côte
// ============================================================================

interface VoiceComparisonProps {
  voices: Voice[];
  sampleText?: string;
  className?: string;
}

export function VoiceComparison({
  voices,
  sampleText = "Bonjour, je suis la voix de prévisualisation.",
  className,
}: VoiceComparisonProps) {
  const [playingId, setPlayingId] = useState<string | null>(null);
  const audioRefs = useRef<Map<string, HTMLAudioElement>>(new Map());

  const playVoice = useCallback(async (voiceId: string) => {
    // Arrêter la voix en cours si différente
    if (playingId && playingId !== voiceId) {
      const currentAudio = audioRefs.current.get(playingId);
      if (currentAudio) {
        currentAudio.pause();
        currentAudio.currentTime = 0;
      }
    }

    // Si même voix, arrêter
    if (playingId === voiceId) {
      const audio = audioRefs.current.get(voiceId);
      if (audio) {
        audio.pause();
        audio.currentTime = 0;
      }
      setPlayingId(null);
      return;
    }

    // Jouer la nouvelle voix
    try {
      setPlayingId(voiceId);
      
      const response = await fetch('/api/tts/preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ voiceId, text: sampleText }),
      });

      if (!response.ok) throw new Error('Erreur');

      const blob = await response.blob();
      const url = URL.createObjectURL(blob);

      const audio = new Audio(url);
      audioRefs.current.set(voiceId, audio);

      audio.onended = () => {
        setPlayingId(null);
        URL.revokeObjectURL(url);
      };

      audio.onerror = () => {
        setPlayingId(null);
      };

      audio.play();
    } catch (error) {
      console.error('Erreur:', error);
      setPlayingId(null);
    }
  }, [playingId, sampleText]);

  return (
    <div className={cn('space-y-2', className)}>
      <h4 className="text-sm font-medium text-foreground">Comparer les voix</h4>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
        {voices.map(voice => (
          <Button
            key={voice.id}
            type="button"
            variant={playingId === voice.id ? 'default' : 'outline'}
            size="sm"
            onClick={() => playVoice(voice.id)}
            className="justify-between"
          >
            <span>{voice.name}</span>
            {playingId === voice.id ? (
              <Pause className="h-4 w-4" />
            ) : (
              <Play className="h-4 w-4" />
            )}
          </Button>
        ))}
      </div>
    </div>
  );
}

