/**
 * Custom Select component with rich content support
 * This component allows rendering complex JSX (icons, descriptions) in dropdown items
 * while properly handling the text content for the select value display.
 */

// ============================================================================
// Base Select Components (from original select.tsx)
// ============================================================================

const Select = SelectPrimitive.Root

const SelectGroup = SelectPrimitive.Group

const SelectValue = SelectPrimitive.Value

const SelectTrigger = React.forwardRef<
