// ============================================
// Component
// ============================================

export const PlaybackControls: React.FC<PlaybackControlsProps> = (props) => {
  const {
    videoElement,
    autoInitialize,
    className,
    showFrameNavigation,
    showSpeedSelector,
    showLoopToggle,
    showMuteToggle,
    showTimeDisplay,
    showProgressBar,
    timeFormat,
    compact,
    onSeek,
    onPlayStateChange,
  } = { ...DEFAULT_PROPS, ...props };
  
  const {
    isPlaying,
    isMuted,
    isLooping,
    currentTime,
    duration,
    currentFrame,
    totalFrames,
    formattedTime,
    formattedTimecode,
    playbackRate,
    stop,
    togglePlay,
    seek,
    stepForward,
    stepBackward,
    setPlaybackRate,
    toggleMute,
    toggleLoop,
  } = useVideoPlayer(videoElement, autoInitialize);
  
  // Local state for progress bar
  const [progress, setProgress] = useState(0);
  const [isSeeking, setIsSeeking] = useState(false);
  const [showSpeedMenu, setShowSpeedMenu] = useState(false);
  
  // Update progress
  useEffect(() => {
    if (duration > 0 && !isSeeking) {
      const newProgress = (currentTime / duration) * 100;
      setProgress(newProgress);
    }
  }, [currentTime, duration, isSeeking]);
  
  // Handle play state change
  useEffect(() => {
    onPlayStateChange?.(isPlaying);
  }, [isPlaying, onPlayStateChange]);
  
  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName)) {
        return;
      }
      
      switch (e.key) {
        case ' ':
        case 'k':
          e.preventDefault();
          togglePlay();
          break;
        case 'ArrowLeft':
          e.preventDefault();
          if (e.shiftKey) {
            stepBackward(5);
          } else {
            stepBackward(1);
          }
          break;
        case 'ArrowRight':
          e.preventDefault();
          if (e.shiftKey) {
            stepForward(5);
          } else {
            stepForward(1);
          }
          break;
        case 'Home':
          e.preventDefault();
          seek(0);
          break;
        case 'End':
          e.preventDefault();
          seek(duration);
          break;
        case 'm':
        case 'M':
          e.preventDefault();
          toggleMute();
          break;
        case 'l':
        case 'L':
          e.preventDefault();
          toggleLoop();
          break;
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [togglePlay, stepForward, stepBackward, seek, toggleMute, toggleLoop, duration]);
  
  // Handle progress bar click
  const handleProgressClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const percentage = x / rect.width;
    const newTime = percentage * duration;
    seek(newTime);
    onSeek?.(newTime);
  }, [duration, seek, onSeek]);
  
  // Handle progress bar drag
  const handleProgressMouseDown = useCallback(() => {
    setIsSeeking(true);
  }, []);
  
  useEffect(() => {
    const handleMouseUp = () => {
      setIsSeeking(false);
    };
    
    if (isSeeking) {
      document.addEventListener('mouseup', handleMouseUp);
      return () => document.removeEventListener('mouseup', handleMouseUp);
    }
  }, [isSeeking]);
  
  // Handle speed change
  const handleSpeedChange = useCallback((rate: PlaybackRate) => {
    setPlaybackRate(rate);
    setShowSpeedMenu(false);
  }, [setPlaybackRate]);
  
  // Format display
  const formatDisplay = () => {
    if (timeFormat === 'timecode') {
      return formattedTimecode;
    } else if (timeFormat === 'frames') {
      return `${currentFrame} / ${totalFrames}`;
    }
    return formattedTime;
  };
  
  // Combined class names
  const containerClassName = [
    'playback-controls',
    compact ? 'playback-controls-compact' : '',
    className,
  ].filter(Boolean).join(' ');

  // Progress value for ARIA
  const progressValue = Math.round(progress);
  
  // ARIA string values for boolean states
  const ariaExpanded = showSpeedMenu ? 'true' : 'false';

  return (
    <div className={containerClassName} role="region" aria-label="Video playback controls">
      <style>{`
        .playback-progress {
          --progress-width: 0%;
          --progress-position: 0%;
        }
      `}</style>
        {/* Progress bar */}
        {showProgressBar && (
          <div
            className="playback-progress"
            onClick={handleProgressClick}
            onMouseDown={handleProgressMouseDown}
            role="slider"
            aria-label="Video progress"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={String(progressValue)}
            tabIndex={0}
          >
            <div
              className="playback-progress-bar"
            />
            <div
              className="playback-progress-thumb"
            />
          </div>
        )}
      
      {/* Main controls */}
      <div className="playback-controls-main">
        {/* Left section */}
        <div className="playback-controls-left">
          {/* Play/Pause button */}
          <button
            className="playback-btn playback-btn-primary"
            onClick={togglePlay}
            aria-label={isPlaying ? 'Pause (Space)' : 'Play (Space)'}
          >
            {isPlaying ? Icons.pause : Icons.play}
          </button>
          
          {/* Stop button */}
          <button
            className="playback-btn"
            onClick={stop}
            aria-label="Stop"
          >
            {Icons.stop}
          </button>
          
          {/* Frame navigation */}
          {showFrameNavigation && (
            <>
              <button
                className="playback-btn"
                onClick={() => stepBackward(1)}
                aria-label="Previous frame (Left arrow)"
              >
                {Icons.stepBackward}
              </button>
              <button
                className="playback-btn"
                onClick={() => stepForward(1)}
                aria-label="Next frame (Right arrow)"
              >
                {Icons.stepForward}
              </button>
            </>
          )}
          
          {/* Skip buttons */}
          <button
            className="playback-btn"
            onClick={() => seek(0)}
            aria-label="Skip to start (Home)"
          >
            {Icons.skipPrevious}
          </button>
          <button
            className="playback-btn"
            onClick={() => seek(duration)}
            aria-label="Skip to end (End)"
          >
            {Icons.skipNext}
          </button>
          
          {/* Mute/Volume */}
          {showMuteToggle && (
            <button
              className="playback-btn playback-btn-volume"
              onClick={toggleMute}
              aria-label={isMuted ? 'Unmute (M)' : 'Mute (M)'}
            >
              {isMuted ? Icons.volumeMute : Icons.volumeUp}
            </button>
          )}
        </div>
        
        {/* Center section - Time display */}
        {showTimeDisplay && (
          <div className="playback-controls-center">
            <span className="playback-time-current">
              {formatDisplay()}
            </span>
            <span className="playback-time-separator">/</span>
            <span className="playback-time-total">
              {timeFormat === 'timecode' 
                ? formattedTimecode.split('/')[1] || formattedTimecode
                : formattedTime}
            </span>
          </div>
        )}
        
        {/* Right section */}
        <div className="playback-controls-right">
          {/* Loop toggle */}
          {showLoopToggle && (
            <button
              className={`playback-btn ${isLooping ? 'playback-btn-active' : ''}`}
              onClick={toggleLoop}
              aria-label={isLooping ? 'Disable loop (L)' : 'Enable loop (L)'}
              aria-pressed={isLooping ? 'true' : 'false'}
            >
              {isLooping ? Icons.loopOne : Icons.loop}
            </button>
          )}
          
          {/* Playback speed */}
          {showSpeedSelector && (
            <div className="playback-speed">
              <button
                className="playback-btn playback-speed-btn"
                onClick={() => setShowSpeedMenu(!showSpeedMenu)}
                aria-label={`Playback speed: ${playbackRate}x`}
                aria-expanded={ariaExpanded}
              >
                {playbackRate}x
              </button>
              
              {showSpeedMenu && (
                <div className="playback-speed-menu">
                  {PLAYBACK_RATES.map(rate => (
                    <button
                      key={rate}
                      className={`playback-speed-option ${rate === playbackRate ? 'playback-speed-option-active' : ''}`}
                      onClick={() => handleSpeedChange(rate)}
                    >
                      {rate}x
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
          
          {/* Fullscreen button */}
          <button
            className="playback-btn"
            aria-label="Fullscreen"
          >
            {Icons.fullscreen}
          </button>
        </div>
      </div>
      
      {/* Keyboard shortcuts hint */}
      {!compact && (
        <div className="playback-shortcuts">
          <span><kbd>Space</kbd> Play/Pause</span>
          <span><kbd>←</kbd><kbd>→</kbd> Frame</span>
          <span><kbd>Shift</kbd>+<kbd>←</kbd> -5s</span>
          <span><kbd>M</kbd> Mute</span>
          <span><kbd>L</kbd> Loop</span>
        </div>
      )}
    </div>
  );
};

export default PlaybackControls;

import React, { useState } from 'react';
import styles from './RegenerateVideoDialog.module.css';

interface RegenerateVideoDialogProps {
  assetId: string;
  assetType: 'video' | 'audio';
  onClose: () => void;
  onRegenerate: (config: unknown) => Promise<void>;
}

export const RegenerateVideoDialog: React.FC<RegenerateVideoDialogProps> = ({
  assetId,
  assetType,
  onClose,
  onRegenerate
}) => {
  const [methodology, setMethodology] = useState('ai-enhanced');
  const [workflow, setWorkflow] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const methodologies = [
    { 
      id: 'ai-enhanced', 
      name: 'IA Amelioree', 
      description: 'Modeles IA avances',
      workflows: [
        { id: 'wan22', name: 'Wan 2.2' },
        { id: 'stable-video', name: 'Stable Video' }
      ]
    },
    { 
      id: 'interpolation', 
      name: 'Interpolation', 
      description: 'Interpolation de frames',
      workflows: [
        { id: 'optical-flow', name: 'Optical Flow' }
      ]
    },
    { 
      id: 'upscaling', 
      name: 'Upscaling', 
      description: 'Amelioration resolution',
      workflows: [
        { id: 'real-esrgan', name: 'Real-ESRGAN' }
      ]
    }
  ];

  const selectedMethodology = methodologies.find(m => m.id === methodology);

  return (
    <div className={styles.dialogBackdrop} onClick={onClose}>
      <div className={styles.dialog} onClick={e => e.stopPropagation()}>
        <h2>Regenerer {assetType === 'video' ? 'Video' : 'Audio'}</h2>

        <div className={styles.preview}>
          {assetType === 'video' ? (
            <video src={`/api/videos/${assetId}/preview`} controls />
          ) : (
            <audio src={`/api/audio/${assetId}/preview`} controls />
          )}
        </div>

        <div className={styles.section}>
          <h3>Methodologie</h3>
          <div className={styles.methodologyGrid}>
            {methodologies.map(m => (
              <button
                key={m.id}
                className={`${styles.methodologyBtn} ${methodology === m.id ? styles.active : ''}`}
                onClick={() => setMethodology(m.id)}
              >
                <span>{m.name}</span>
                <small>{m.description}</small>
              </button>
            ))}
          </div>
        </div>

        {selectedMethodology && (
          <div className={styles.section}>
            <h3>Workflow</h3>
            <div className={styles.workflowList}>
              {selectedMethodology.workflows.map(w => (
                <button
                  key={w.id}
                  className={`${styles.workflowBtn} ${workflow === w.id ? styles.active : ''}`}
                  onClick={() => setWorkflow(w.id)}
                >
                  {w.name}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className={styles.dialogActions}>
          <button className={styles.cancelBtn} onClick={onClose}>Annuler</button>
          <button
            className={styles.confirmBtn}
            onClick={() => onRegenerate({ methodology, workflow })}
            disabled={!workflow || isLoading}
          >
            {isLoading ? 'Generation...' : 'Regenerer'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default RegenerateVideoDialog;

