import React, { useRef, useState, useEffect, useCallback } from 'react';
import { VideoPlayer } from './VideoPlayer';
import type { Shot } from '@/types';

export interface VideoSequencePlayerProps {
  shots: Shot[];
  currentIndex: number;
  onShotChange?: (index: number) => void;
  seamlessTransition?: boolean;
  autoPlay?: boolean;
  className?: string;
}

interface PreloadedVideo {
  shotId: string;
  videoElement: HTMLVideoElement;
  isReady: boolean;
}

export const VideoSequencePlayer: React.FC<VideoSequencePlayerProps> = ({
  shots,
  currentIndex,
  onShotChange,
  seamlessTransition = true,
  autoPlay = false,
  className = '',
}) => {
  const [currentShotIndex, setCurrentShotIndex] = useState(currentIndex);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [preloadedVideos, setPreloadedVideos] = useState<Map<string, PreloadedVideo>>(new Map());
  const currentVideoRef = useRef<HTMLVideoElement>(null);
  const nextVideoRef = useRef<HTMLVideoElement>(null);

  // Get current and next shots
  const currentShot = shots[currentShotIndex];
  const nextShot = currentShotIndex < shots.length - 1 ? shots[currentShotIndex + 1] : null;

  // Preload next video
  const preloadNextVideo = useCallback(() => {
    if (!nextShot || !seamlessTransition) return;

    const videoUrl = nextShot.metadata?.videoUrl || nextShot.image;
    if (!videoUrl) return;

    // Check if already preloaded
    if (preloadedVideos.has(nextShot.id)) return;

    // Create video element for preloading
    const videoElement = document.createElement('video');
    videoElement.src = videoUrl;
    videoElement.preload = 'auto';

    const preloadedVideo: PreloadedVideo = {
      shotId: nextShot.id,
      videoElement,
      isReady: false,
    };

    // Listen for canplaythrough event
    videoElement.addEventListener('canplaythrough', () => {
      preloadedVideo.isReady = true;
      setPreloadedVideos((prev) => new Map(prev).set(nextShot.id, preloadedVideo));
    });

    // Start loading
    videoElement.load();

    setPreloadedVideos((prev) => new Map(prev).set(nextShot.id, preloadedVideo));
  }, [nextShot, seamlessTransition, preloadedVideos]);

  // Preload next video when current shot changes
  useEffect(() => {
    preloadNextVideo();
  }, [preloadNextVideo]);

  // Transition to next shot
  const transitionToShot = useCallback(
    (index: number) => {
      if (index < 0 || index >= shots.length) return;

      setCurrentShotIndex(index);
      onShotChange?.(index);

      // If playing, continue playing the next shot
      if (isPlaying && seamlessTransition) {
        // Small delay to ensure video is ready
        setTimeout(() => {
          if (currentVideoRef.current) {
            currentVideoRef.current.play().catch((err) => {
              console.error('Failed to play next video:', err);
            });
          }
        }, 50);
      }
    },
    [shots.length, onShotChange, isPlaying, seamlessTransition]
  );

  // Handle video ended
  const handleVideoEnded = useCallback(() => {
    if (currentShotIndex < shots.length - 1) {
      // Move to next shot
      transitionToShot(currentShotIndex + 1);
    } else {
      // End of sequence
      setIsPlaying(false);
    }
  }, [currentShotIndex, shots.length, transitionToShot]);

  // Sync current index from props
  useEffect(() => {
    if (currentIndex !== currentShotIndex) {
      setCurrentShotIndex(currentIndex);
    }
  }, [currentIndex, currentShotIndex]);

  // Synchronize audio between shots
  const synchronizeAudio = useCallback(() => {
    if (!currentVideoRef.current) return;

    // Get all audio tracks from current shot
    const audioTracks = currentShot?.audioTracks || [];

    // For each audio track, ensure it's synchronized with video playback
    audioTracks.forEach((track) => {
      // This is a placeholder for audio synchronization logic
      // In a real implementation, you would:
      // 1. Load audio files
      // 2. Sync their playback with video currentTime
      // 3. Handle volume, pan, and effects
      // 4. Ensure smooth transitions between shots
      ;
    });
  }, [currentShot]);

  // Synchronize audio when shot changes or playback state changes
  useEffect(() => {
    if (isPlaying) {
      synchronizeAudio();
    }
  }, [isPlaying, currentShotIndex, synchronizeAudio]);

  // Navigation controls
  const goToPreviousShot = useCallback(() => {
    if (currentShotIndex > 0) {
      transitionToShot(currentShotIndex - 1);
    }
  }, [currentShotIndex, transitionToShot]);

  const goToNextShot = useCallback(() => {
    if (currentShotIndex < shots.length - 1) {
      transitionToShot(currentShotIndex + 1);
    }
  }, [currentShotIndex, shots.length, transitionToShot]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in an input field
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault();
          goToPreviousShot();
          break;
        case 'ArrowDown':
          e.preventDefault();
          goToNextShot();
          break;
        case 'PageUp':
          e.preventDefault();
          goToPreviousShot();
          break;
        case 'PageDown':
          e.preventDefault();
          goToNextShot();
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [goToPreviousShot, goToNextShot]);

  // Cleanup preloaded videos
  useEffect(() => {
    return () => {
      preloadedVideos.forEach((preloaded) => {
        preloaded.videoElement.src = '';
        preloaded.videoElement.load();
      });
    };
  }, [preloadedVideos]);

  if (!currentShot) {
    return (
      <div className={`relative bg-gray-900 flex items-center justify-center ${className}`}>
        <div className="text-center p-8">
          <div className="text-gray-600 text-6xl mb-4">🎬</div>
          <h3 className="text-lg font-semibold text-gray-300 mb-2">
            Aucun plan disponible
          </h3>
          <p className="text-sm text-gray-400">
            La séquence ne contient aucun plan.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`relative ${className}`}>
      {/* Current Video Player */}
      <VideoPlayer
        shot={currentShot}
        autoPlay={autoPlay}
        controls={true}
        onEnded={handleVideoEnded}
        className="w-full h-full"
      />

      {/* Sequence Navigation Overlay */}
      <div className="absolute top-4 left-4 bg-black bg-opacity-70 rounded-lg px-4 py-2">
        <div className="flex items-center gap-2 text-white text-sm">
          <span className="font-semibold">
            Plan {currentShotIndex + 1} / {shots.length}
          </span>
          {currentShot.title && (
            <>
              <span className="text-gray-400">-</span>
              <span className="text-gray-300">{currentShot.title}</span>
            </>
          )}
        </div>
      </div>

      {/* Navigation Buttons */}
      <div className="absolute top-1/2 left-4 right-4 flex justify-between pointer-events-none">
        {currentShotIndex > 0 && (
          <button
            onClick={goToPreviousShot}
            className="pointer-events-auto p-3 bg-black bg-opacity-50 hover:bg-opacity-70 rounded-full transition-all"
            title="Plan précédent"
          >
            <svg
              className="w-6 h-6 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M15 19l-7-7 7-7"
              />
            </svg>
          </button>
        )}

        {currentShotIndex < shots.length - 1 && (
          <button
            onClick={goToNextShot}
            className="pointer-events-auto p-3 bg-black bg-opacity-50 hover:bg-opacity-70 rounded-full transition-all ml-auto"
            title="Plan suivant"
          >
            <svg
              className="w-6 h-6 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5l7 7-7 7"
              />
            </svg>
          </button>
        )}
      </div>

      {/* Preload indicator */}
      {seamlessTransition && nextShot && (
        <div className="absolute top-4 right-4 bg-black bg-opacity-70 rounded-lg px-3 py-1.5">
          <div className="flex items-center gap-2 text-xs text-gray-300">
            {preloadedVideos.get(nextShot.id)?.isReady ? (
              <>
                <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                <span>Suivant prêt</span>
              </>
            ) : (
              <>
                <span className="w-2 h-2 bg-yellow-500 rounded-full animate-pulse"></span>
                <span>Chargement...</span>
              </>
            )}
          </div>
        </div>
      )}

      {/* Shot Thumbnails Strip (optional) */}
      <div className="absolute bottom-20 left-0 right-0 flex justify-center pointer-events-none">
        <div className="pointer-events-auto flex gap-2 bg-black bg-opacity-70 rounded-lg p-2 max-w-full overflow-x-auto">
          {shots.map((shot, index) => (
            <button
              key={shot.id}
              onClick={() => transitionToShot(index)}
              className={`flex-shrink-0 w-16 h-12 rounded overflow-hidden border-2 transition-all ${
                index === currentShotIndex
                  ? 'border-blue-500 scale-110'
                  : 'border-gray-600 hover:border-gray-400'
              }`}
              title={shot.title}
            >
              {shot.image ? (
                <img
                  src={shot.image}
                  alt={shot.title}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full bg-gray-800 flex items-center justify-center text-gray-500 text-xs">
                  {index + 1}
                </div>
              )}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoSequencePlayer;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

export interface VideoThumbnailPreviewProps {
  videoUrl: string;
  time: number;
  width?: number;
  height?: number;
  mouseX?: number;
  mouseY?: number;
  visible?: boolean;
  onThumbnailGenerated?: (blob: Blob) => void;
}

// Simple in-memory cache for thumbnails
class ThumbnailCache {
  private cache: Map<string, string> = new Map();
  private maxSize: number = 50;

  generateKey(videoUrl: string, time: number): string {
    return `${videoUrl}:${Math.floor(time * 10) / 10}`; // Round to 0.1s precision
  }

  get(videoUrl: string, time: number): string | null {
    const key = this.generateKey(videoUrl, time);
    return this.cache.get(key) || null;
  }

  set(videoUrl: string, time: number, thumbnailUrl: string): void {
    const key = this.generateKey(videoUrl, time);
    
    // LRU eviction if cache is full
    if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      const oldUrl = this.cache.get(firstKey);
      if (oldUrl) {
        URL.revokeObjectURL(oldUrl);
      }
      this.cache.delete(firstKey);
    }
    
    this.cache.set(key, thumbnailUrl);
  }

  clear(): void {
    // Revoke all object URLs
    this.cache.forEach((url) => {
      URL.revokeObjectURL(url);
    });
    this.cache.clear();
  }
}

// Singleton cache instance
const thumbnailCache = new ThumbnailCache();

export const VideoThumbnailPreview: React.FC<VideoThumbnailPreviewProps> = ({
  videoUrl,
  time,
  width = 160,
  height = 90,
  mouseX = 0,
  mouseY = 0,
  visible = true,
  onThumbnailGenerated,
}) => {
  const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  // Format timecode
  const formatTimecode = useCallback((seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 100);
    return `${mins.toString().padStart(2, '0')}:${secs
      .toString()
      .padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
  }, []);

  // Generate thumbnail
  const generateThumbnail = useCallback(async () => {
    // Check cache first
    const cachedUrl = thumbnailCache.get(videoUrl, time);
    if (cachedUrl) {
      setThumbnailUrl(cachedUrl);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Create video element if not exists
      if (!videoRef.current) {
        videoRef.current = document.createElement('video');
        videoRef.current.crossOrigin = 'anonymous';
        videoRef.current.preload = 'metadata';
      }

      // Create canvas if not exists
      if (!canvasRef.current) {
        canvasRef.current = document.createElement('canvas');
      }

      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Set video source if changed
      if (video.src !== videoUrl) {
        video.src = videoUrl;
      }

      // Wait for video to load metadata
      await new Promise<void>((resolve, reject) => {
        const handleLoadedMetadata = () => {
          video.removeEventListener('loadedmetadata', handleLoadedMetadata);
          resolve();
        };

        const handleError = () => {
          video.removeEventListener('error', handleError);
          reject(new Error('Failed to load video'));
        };

        if (video.readyState >= 1) {
          resolve();
        } else {
          video.addEventListener('loadedmetadata', handleLoadedMetadata);
          video.addEventListener('error', handleError);
        }
      });

      // Seek to time
      video.currentTime = time;

      // Wait for seek to complete
      await new Promise<void>((resolve, reject) => {
        const handleSeeked = () => {
          video.removeEventListener('seeked', handleSeeked);
          resolve();
        };

        const handleError = () => {
          video.removeEventListener('error', handleError);
          reject(new Error('Failed to seek video'));
        };

        video.addEventListener('seeked', handleSeeked);
        video.addEventListener('error', handleError);

        // Timeout after 5 seconds
        setTimeout(() => {
          video.removeEventListener('seeked', handleSeeked);
          video.removeEventListener('error', handleError);
          reject(new Error('Seek timeout'));
        }, 5000);
      });

      // Draw frame to canvas
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('Failed to get canvas context');
      }

      // Calculate aspect ratio
      const videoAspect = video.videoWidth / video.videoHeight;
      const canvasAspect = width / height;

      let drawWidth = width;
      let drawHeight = height;
      let offsetX = 0;
      let offsetY = 0;

      if (videoAspect > canvasAspect) {
        // Video is wider
        drawHeight = width / videoAspect;
        offsetY = (height - drawHeight) / 2;
      } else {
        // Video is taller
        drawWidth = height * videoAspect;
        offsetX = (width - drawWidth) / 2;
      }

      // Clear canvas
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, width, height);

      // Draw video frame
      ctx.drawImage(video, offsetX, offsetY, drawWidth, drawHeight);

      // Convert canvas to blob
      const blob = await new Promise<Blob>((resolve, reject) => {
        canvas.toBlob(
          (blob) => {
            if (blob) {
              resolve(blob);
            } else {
              reject(new Error('Failed to create blob'));
            }
          },
          'image/jpeg',
          0.8
        );
      });

      // Create object URL
      const url = URL.createObjectURL(blob);
      setThumbnailUrl(url);

      // Cache the thumbnail
      thumbnailCache.set(videoUrl, time, url);

      // Notify parent
      onThumbnailGenerated?.(blob);

      setIsLoading(false);
    } catch (err) {
      console.error('Failed to generate thumbnail:', err);
      setError(err instanceof Error ? err.message : 'Unknown error');
      setIsLoading(false);
    }
  }, [videoUrl, time, width, height, onThumbnailGenerated]);

  // Generate thumbnail when props change
  useEffect(() => {
    if (visible) {
      generateThumbnail();
    }
  }, [visible, generateThumbnail]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (thumbnailUrl && !thumbnailCache.get(videoUrl, time)) {
        URL.revokeObjectURL(thumbnailUrl);
      }
    };
  }, [thumbnailUrl, videoUrl, time]);

  if (!visible) {
    return null;
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -10 }}
        transition={{ duration: 0.15 }}
        className="fixed z-50 pointer-events-none"
        style={{
          left: mouseX + 10,
          top: mouseY - height - 40,
        }}
      >
        <div className="bg-gray-900 border border-gray-700 rounded-lg shadow-2xl overflow-hidden">
          {/* Thumbnail */}
          <div
            className="relative bg-black"
            style={{ width, height }}
          >
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-white"></div>
              </div>
            )}

            {error && (
              <div className="absolute inset-0 flex items-center justify-center p-2">
                <div className="text-center">
                  <div className="text-red-500 text-2xl mb-1">⚠️</div>
                  <p className="text-xs text-gray-400">Erreur</p>
                </div>
              </div>
            )}

            {thumbnailUrl && !isLoading && !error && (
              <img
                src={thumbnailUrl}
                alt="Video preview"
                className="w-full h-full object-contain"
              />
            )}
          </div>

          {/* Timecode */}
          <div className="px-2 py-1 bg-gray-800 border-t border-gray-700">
            <span className="text-xs font-mono text-gray-300">
              {formatTimecode(time)}
            </span>
          </div>
        </div>

        {/* Arrow pointing down */}
        <div
          className="absolute left-1/2 -translate-x-1/2 w-0 h-0"
          style={{
            bottom: -8,
            borderLeft: '8px solid transparent',
            borderRight: '8px solid transparent',
            borderTop: '8px solid #374151', // gray-700
          }}
        />
      </motion.div>
    </AnimatePresence>
  );
};

// Hook for using thumbnail preview
export const useVideoThumbnailPreview = () => {
  const [previewState, setPreviewState] = useState<{
    visible: boolean;
    videoUrl: string;
    time: number;
    mouseX: number;
    mouseY: number;
  }>({
    visible: false,
    videoUrl: '',
    time: 0,
    mouseX: 0,
    mouseY: 0,
  });

  const showPreview = useCallback(
    (videoUrl: string, time: number, mouseX: number, mouseY: number) => {
      setPreviewState({
        visible: true,
        videoUrl,
        time,
        mouseX,
        mouseY,
      });
    },
    []
  );

  const hidePreview = useCallback(() => {
    setPreviewState((prev) => ({ ...prev, visible: false }));
  }, []);

  const updatePosition = useCallback((mouseX: number, mouseY: number) => {
    setPreviewState((prev) => ({ ...prev, mouseX, mouseY }));
  }, []);

  return {
    previewState,
    showPreview,
    hidePreview,
    updatePosition,
  };
};

export default VideoThumbnailPreview;

