/**
 * BaseWizard Component
 * 
 * A standardized wizard component that provides common functionality
 * for all wizard types. Use this as the base for new wizards.
 */

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { WizardStepIndicator, StepState, WizardStep } from './WizardStepIndicator';
import { WizardNavigation } from './WizardNavigation';
import { WizardErrorBoundary } from './WizardErrorBoundary';
import { useWizardAutoSave, WizardAutoSaveState } from '@/hooks/useWizardAutoSave';
import { useWizardCompletion } from '@/hooks/useWizardCompletion';
import { useWizardErrorHandler } from '@/hooks/useWizardErrorHandler';
import type { WizardType } from '@/utils/wizardStorage';

// ============================================================================
// Types
// ============================================================================

export interface WizardStepComponentProps<T> {
  data: Partial<T>;
  onUpdate: (data: Partial<T>) => void;
  errors?: Record<string, string[]>;
  isValid?: boolean;
}

export interface BaseWizardConfig<T> {
  wizardType: WizardType;
  steps: WizardStep[];
  initialData?: Partial<T>;
  validateStep?: (step: number, data: Partial<T>) => Promise<{ valid: boolean; errors?: Record<string, string[]> }>;
  onComplete?: (data: T) => void | Promise<void>;
  onCancel?: () => void;
  autoSave?: boolean;
  autoSaveInterval?: number;
}

export interface BaseWizardProps<T> {
  config: BaseWizardConfig<T>;
  renderStep: (step: number, data: Partial<T>, onUpdate: (data: Partial<T>) => void) => React.ReactNode;
  className?: string;
}

// ============================================================================
// BaseWizard Component
// ============================================================================

export function BaseWizard<T>({
  config,
  renderStep,
  className,
}: BaseWizardProps<T>) {
  const {
    wizardType,
    steps,
    initialData,
    validateStep,
    onComplete,
    onCancel,
    autoSave = true,
    autoSaveInterval = 30000,
  } = config;

  // State
  const [currentStep, setCurrentStep] = useState(1);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
  const [stepData, setStepData] = useState<Record<number, Partial<T>>>({
    ...steps.reduce((acc, step) => ({ ...acc, [step.number]: {} }), {}),
    ...initialData,
  });
  const [stepErrors, setStepErrors] = useState<Record<number, Record<string, string[]>>>({});
  const [stepStates, setStepStates] = useState<Record<number, StepState>>({});
  const [isReviewMode, setIsReviewMode] = useState(false);

  // Hooks
  const getWizardState = useCallback((): WizardAutoSaveState => ({
    currentStep,
    completedSteps,
    isReviewMode,
    stepData,
  }), [currentStep, completedSteps, isReviewMode, stepData]);

  const autoSaveResult = useWizardAutoSave(getWizardState, {
    wizardType,
    intervalMs: autoSaveInterval,
    enabled: autoSave,
  });

  const completion = useWizardCompletion<T>({
    onComplete: async (data) => {
      await onComplete?.(data);
    },
    onError: (error) => {
      console.error('Wizard completion error:', error);
    },
    onCancel: () => {
      onCancel?.();
    },
  });

  const errorHandler = useWizardErrorHandler(wizardType);

  // =========================================================================
  // Data Management
  // =========================================================================

  const updateStepData = useCallback((step: number, data: Partial<T>) => {
    setStepData(prev => ({
      ...prev,
      [step]: { ...prev[step], ...data },
    }));
    
    // Clear errors when data changes
    setStepErrors(prev => ({
      ...prev,
      [step]: {},
    }));

    // Update step state
    setStepStates(prev => ({
      ...prev,
      [step]: { status: 'pending' },
    }));
  }, []);

  const getAllData = useCallback(() => {
    let merged: Partial<T> = {};
    Object.values(stepData).forEach(data => {
      merged = { ...merged, ...data };
    });
    return merged as T;
  }, [stepData]);

  // =========================================================================
  // Navigation
  // =========================================================================

  const canGoNext = useMemo(() => {
    const errors = stepErrors[currentStep] || {};
    return Object.keys(errors).length === 0;
  }, [stepErrors, currentStep]);

  const canGoPrevious = currentStep > 1;

  const handleNext = useCallback(async () => {
    // Validate current step
    if (validateStep) {
      const result = await validateStep(currentStep, stepData[currentStep]);
      setStepErrors(prev => ({
        ...prev,
        [currentStep]: result.errors || {},
      }));
      
      setStepStates(prev => ({
        ...prev,
        [currentStep]: {
          status: result.valid ? 'valid' : 'invalid',
          errorCount: Object.keys(result.errors || {}).length,
        },
      }));

      if (!result.valid) {
        return;
      }
    } else {
      setStepStates(prev => ({
        ...prev,
        [currentStep]: { status: 'valid' },
      }));
    }

    // Mark step as completed
    if (!completedSteps.includes(currentStep)) {
      setCompletedSteps(prev => [...prev, currentStep]);
    }

    // Go to next step
    const currentIndex = steps.findIndex(s => s.number === currentStep);
    if (currentIndex < steps.length - 1) {
      setCurrentStep(steps[currentIndex + 1].number);
    } else {
      setIsReviewMode(true);
    }
  }, [currentStep, stepData, validateStep, steps, completedSteps]);

  const handlePrevious = useCallback(() => {
    const currentIndex = steps.findIndex(s => s.number === currentStep);
    if (currentIndex > 0) {
      setCurrentStep(steps[currentIndex - 1].number);
    }
  }, [currentStep, steps]);

  const handleGoToStep = useCallback((step: number) => {
    // Only allow going to completed steps or the next step
    if (step < currentStep || step === currentStep + 1) {
      setCurrentStep(step);
    }
  }, [currentStep]);

  const handleComplete = useCallback(async () => {
    await completion.complete(getAllData());
  }, [completion, getAllData]);

  const handleCancel = useCallback(() => {
    completion.cancel();
    onCancel?.();
  }, [completion, onCancel]);

  // =========================================================================
  // Effects
  // =========================================================================

  // Update current step state when entering
  useEffect(() => {
    if (!isReviewMode) {
      setStepStates(prev => ({
        ...prev,
        [currentStep]: { status: 'pending' },
      }));
    }
  }, [currentStep, isReviewMode]);

  // =========================================================================
  // Render
  // =========================================================================

  const currentStepData = stepData[currentStep] || {};
  const currentErrors = stepErrors[currentStep] || {};

  return (
    <WizardErrorBoundary
      wizardType={wizardType}
      onReset={() => {
        setCurrentStep(1);
        setCompletedSteps([]);
        setStepData({});
        setStepErrors({});
        setStepStates({});
        setIsReviewMode(false);
        completion.reset();
        errorHandler.clearError();
      }}
    >
      <div className={`base-wizard ${className || ''}`}>
        {/* Header with step indicator */}
        <div className="base-wizard__header">
          <WizardStepIndicator
            steps={steps}
            currentStep={isReviewMode ? steps.length : currentStep}
            stepStates={stepStates}
            onStepClick={handleGoToStep}
            allowJumpToStep={false}
          />
        </div>

        {/* Auto-save indicator */}
        {autoSave && (
          <div className="base-wizard__autosave">
            {autoSaveResult.isSaving && (
              <span className="text-amber-500">Saving...</span>
            )}
            {autoSaveResult.isDirty && !autoSaveResult.isSaving && (
              <span className="text-orange-500">Unsaved changes</span>
            )}
            {!autoSaveResult.isDirty && autoSaveResult.lastSaved && (
              <span className="text-green-500">
                Saved at {autoSaveResult.lastSaved.toLocaleTimeString()}
              </span>
            )}
          </div>
        )}

        {/* Error display */}
        {errorHandler.hasError && (
          <div className="base-wizard__error">
            <p className="text-red-500">{errorHandler.getErrorMessage()}</p>
            <button
              onClick={errorHandler.clearError}
              className="text-sm text-gray-500 underline"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Content */}
        <div className="base-wizard__content">
          {isReviewMode ? (
            <div className="base-wizard__review">
              <h2 className="text-xl font-bold mb-4">Review</h2>
              <pre className="bg-gray-100 p-4 rounded overflow-auto max-h-96">
                {JSON.stringify(getAllData(), null, 2)}
              </pre>
            </div>
          ) : (
            renderStep(currentStep, currentStepData, (data) => updateStepData(currentStep, data))
          )}
        </div>

        {/* Navigation */}
        <div className="base-wizard__footer">
          <WizardNavigation
            currentStep={isReviewMode ? steps.length : currentStep}
            totalSteps={steps.length}
            canGoNext={canGoNext && !completion.isCompleting}
            canGoBack={canGoPrevious && !isReviewMode && !completion.isCompleting}
            isSubmitting={completion.isCompleting}
            onNext={isReviewMode ? undefined : handleNext}
            onBack={isReviewMode ? undefined : handlePrevious}
            onSubmit={isReviewMode ? handleComplete : undefined}
            onCancel={handleCancel}
          />
        </div>
      </div>
    </WizardErrorBoundary>
  );
}

// ============================================================================
// Factory function for creating wizards
// ============================================================================

export function createWizard<T>(
  config: Omit<BaseWizardConfig<T>, 'wizardType'> & { wizardType: WizardType }
) {
  return function WizardComponent({
    renderStep,
    className,
  }: Omit<BaseWizardProps<T>, 'config'>) {
    return (
      <BaseWizard<T>
        config={config}
        renderStep={renderStep}
        className={className}
      />
    );
  };
}

// ============================================================================
// Example usage
// ============================================================================

/*
// Character Wizard using BaseWizard
const CharacterWizard = createWizard<Character>({
  wizardType: 'character',
  steps: [
    { number: 1, title: 'Basic Identity', description: 'Name and role' },
    { number: 2, title: 'Appearance', description: 'Physical traits' },
    { number: 3, title: 'Personality', description: 'Traits and values' },
    { number: 4, title: 'Background', description: 'History and origin' },
    { number: 5, title: 'Relationships', description: 'Character connections' },
    { number: 6, title: 'Review', description: 'Finalize character' },
  ],
  validateStep: async (step, data) => {
    const result = await validationEngine.validateStep('character', step, data);
    return {
      valid: result.isValid,
      errors: formatValidationErrors(result),
    };
  },
  onComplete: (character) => {
    console.log('Character created:', character);
  },
  autoSave: true,
});

// Usage
<CharacterWizard
  renderStep={(step, data, onUpdate) => {
    switch (step) {
      case 1:
        return <Step1BasicIdentity data={data} onUpdate={onUpdate} />;
      case 2:
        return <Step2PhysicalAppearance data={data} onUpdate={onUpdate} />;
      // ...
    }
  }}
/>
*/

export default BaseWizard;

import React from 'react';
import { CreateProjectDialog, type SerializableProjectFormat } from '@/components/launcher/CreateProjectDialog';
import { useAppStore } from '@/stores/useAppStore';
import { generateProjectTemplate, sequencesToShots } from '@/utils/projectTemplateGenerator';

export function CreateProjectDialogModal() {
  const showCreateProjectDialog = useAppStore((state) => state.showCreateProjectDialog);
  const setShowCreateProjectDialog = useAppStore((state) => state.setShowCreateProjectDialog);
  const setProject = useAppStore((state) => state.setProject);
  const setShots = useAppStore((state) => state.setShots);

  if (!showCreateProjectDialog) {
    return null;
  }

  const handleCreateProject = async (
    projectName: string,
    projectPath: string,
    format: SerializableProjectFormat
  ) => {
    console.log('[CreateProjectDialogModal] Creating project:', {
      projectName,
      projectPath: projectPath || '(default)',
      format: format.name,
      electronAPIAvailable: !!window.electronAPI,
      projectAPIAvailable: !!window.electronAPI?.project,
      createAPIAvailable: !!window.electronAPI?.project?.create,
    });

    try {
      // Generate project template based on format
      const template = generateProjectTemplate(format);
      const initialShots = sequencesToShots(template.sequences);
      console.log('[CreateProjectDialogModal] Generated template:', {
        sequencesCount: template.sequences.length,
        shotsCount: initialShots.length,
      });

      if (window.electronAPI) {
        // Create project via Electron API
        const createData: unknown = {
          name: projectName,
          format: format,
          initialShots: initialShots,
        };

        // Only include location if it's not empty
        if (projectPath && projectPath.trim() !== '') {
          createData.location = projectPath;
        }

        console.log('[CreateProjectDialogModal] Calling electronAPI.project.create with:', createData);
        const electronProject = await window.electronAPI.project.create(createData);
        console.log('[CreateProjectDialogModal] Project created successfully:', electronProject);

        // Convert Electron project to Store project format
        const storeProject = {
          schema_version: electronProject.config?.schema_version || '1.0',
          project_name: electronProject.name || projectName,
          shots: initialShots,
          assets: [],
          capabilities: {
            grid_generation: true,
            promotion_engine: true,
            qa_engine: true,
            autofix_engine: true,
          },
          generation_status: {
            grid: 'pending',
            promotion: 'pending',
          },
          metadata: {
            id: electronProject.id,
            path: electronProject.path,
            version: electronProject.version,
            created_at: electronProject.createdAt instanceof Date
              ? electronProject.createdAt.toISOString()
              : electronProject.createdAt || new Date().toISOString(),
            updated_at: electronProject.modifiedAt instanceof Date
              ? electronProject.modifiedAt.toISOString()
              : electronProject.modifiedAt || new Date().toISOString(),
          },
        };

        // Load the created project into the store
        setProject(storeProject as any);
        setShots(initialShots);
      } else {
        throw new Error('Electron API not available. Cannot create project files.');
      }

      // Close the dialog
      setShowCreateProjectDialog(false);
    } catch (error) {
      console.error('Failed to create project:', error);
      throw error;
    }
  };

  return (
    <CreateProjectDialog
      open={showCreateProjectDialog}
      onOpenChange={setShowCreateProjectDialog}
      onCreateProject={handleCreateProject}
    />
  );
}

/**
 * Create Project Wizard
 * 3-step guided wizard: World → Characters → Scenario
 */

import React, { useState } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { useToast } from '@/hooks/use-toast';
import { StepProgress } from '@/components/ui/progress';
import {
  Globe,
  Users,
  FileText,
  ChevronRight,
  ChevronLeft,
  Check,
  Sparkles,
  Plus,
  Trash2,
  Trash2,
  Loader2,
  Wand2,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';

interface World {
  id: string;
  name: string;
  description: string;
  era: string;
  atmosphere: string;
  technology: string;
}

interface Character {
  id: string;
  name: string;
  role: string;
  description: string;
  personality: string;
  appearance: string;
}

interface Scenario {
  title: string;
  genre: string;
  synopsis: string;
  tone: string;
  targetDuration: number;
  acts: number;
}

type Step = 'world' | 'characters' | 'scenario';

interface CreateProjectWizardProps {
  onComplete?: (data: { world: World; characters: Character[]; scenario: Scenario }) => void;
  onCancel?: () => void;
  className?: string;
}

export function CreateProjectWizard({
  onComplete,
  onCancel,
  className,
}: CreateProjectWizardProps) {
  const { toast } = useToast();
  // const createProject = useAppStore((state) => state.createProject); // Removed invalid selector
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  const [currentStep, setCurrentStep] = useState<Step>('world');
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [world, setWorld] = useState<World>({
    id: '',
    name: '',
    description: '',
    era: 'present',
    atmosphere: 'realistic',
    technology: 'modern',
  });

  const [characters, setCharacters] = useState<Character[]>([
    { id: 'char_1', name: '', role: 'Protagonist', description: '', personality: '', appearance: '' },
  ]);

  const [scenario, setScenario] = useState<Scenario>({
    title: '',
    genre: 'drama',
    synopsis: '',
    tone: 'neutral',
    targetDuration: 10,
    acts: 3,
  });

  const steps = [
    { label: 'Monde', description: 'Univers & époque' },
    { label: 'Personnages', description: 'Cast & rôles' },
    { label: 'Scénario', description: 'Synopsis & structure' },
  ];

  const goToStep = (step: Step) => {
    setCurrentStep(step);
  };

  const nextStep = () => {
    if (currentStep === 'world') {
      if (!world.name.trim()) {
        toast({ title: 'Nom requis', description: 'Donnez un nom à votre monde', variant: 'destructive' });
        return;
      }
      goToStep('characters');
    } else if (currentStep === 'characters') {
      if (characters.length === 0 || !characters[0]?.name.trim()) {
        toast({ title: 'Personnage requis', description: 'Ajoutez au moins un personnage', variant: 'destructive' });
        return;
      }
      goToStep('scenario');
    }
  };

  const generateContent = async (prompt: string, context: string): Promise<string | null> => {
    setIsAIProcessing(true);
    try {
      // Use LLMConfigService directly to avoid hook issues
      const { llmConfigService } = await import('@/services/llmConfigService');
      const service = llmConfigService.getService();

      if (!service) {
        toast({ title: 'Service non disponible', description: 'Configurez le LLM dans les paramètres', variant: 'destructive' });
        return null;
      }

      const response = await service.generateCompletion({
        prompt,
        systemPrompt: `You are a creative assistant helping with ${context}.`,
        temperature: 0.7
      });

      if (response.success && response.data) {
        return response.data.content;
      } else {
        throw new Error(response.error || 'Generation failed');
      }
    } catch (error) {
      console.error('Generation failed', error);
      toast({ title: 'Erreur', description: 'La génération a échoué', variant: 'destructive' });
      return null;
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateWorld = async () => {
    if (!world.name) return;
    const prompt = `Generate a creative description for a world named "${world.name}" set in a ${world.era} era with a ${world.atmosphere} atmosphere and ${world.technology} technology level. Keep it under 100 words.`;
    const result = await generateContent(prompt, 'world-building');
    if (result) {
      setWorld(prev => ({ ...prev, description: result }));
    }
  };

  const handleGenerateCharacter = async (index: number) => {
    const char = characters[index];
    if (!char.name || !char.role) return;
    const prompt = `Generate a brief personality and appearance description for a character named "${char.name}" who is a ${char.role} in a ${world.atmosphere} ${world.era} setting. Keep it under 50 words.`;
    const result = await generateContent(prompt, 'character-creation');
    if (result) {
      handleUpdateCharacter(index, 'description', result);
    }
  };

  const handleGenerateScenario = async () => {
    if (!scenario.title) return;
    const prompt = `Generate a synopsis for a ${scenario.genre} story titled "${scenario.title}" with a ${scenario.tone} tone, set in a world described as: ${world.description}. The protagonist is ${characters[0]?.name}. Keep it under 150 words.`;
    const result = await generateContent(prompt, 'story-writing');
    if (result) {
      setScenario(prev => ({ ...prev, synopsis: result }));
    }
  };

  const handleUpdateCharacter = (index: number, field: keyof Character, value: string) => {
    const newChars = [...characters];
    newChars[index] = { ...newChars[index], [field]: value };
    setCharacters(newChars);
  };

  const addCharacter = () => {
    setCharacters([...characters, {
      id: `char_${Date.now()}`,
      name: '',
      role: 'Supporting',
      description: '',
      personality: '',
      appearance: ''
    }]);
  };

  const removeCharacter = (index: number) => {
    if (characters.length > 1) {
      const newChars = characters.filter((_, i) => i !== index);
      setCharacters(newChars);
    }
  };

  const prevStep = () => {
    if (currentStep === 'scenario') {
      goToStep('characters');
    } else if (currentStep === 'characters') {
      goToStep('world');
    }
  };

  const handleComplete = async () => {
    if (!scenario.title.trim()) {
      toast({ title: 'Titre requis', description: 'Donnez un titre à votre scénario', variant: 'destructive' });
      return;
    }

    setIsSaving(true);
    try {
      const projectData = {
        world,
        characters,
        scenario,
      };

      // Call the onComplete callback if provided
      if (onComplete) {
        onComplete(projectData);
      }

      toast({ title: 'Projet créé', description: 'Votre projet a été créé avec succès' });
    } catch (error) {
      console.error('Error creating project:', error);
      toast({ title: 'Erreur', description: 'Impossible de créer le projet', variant: 'destructive' });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className={cn('w-full max-w-4xl mx-auto p-6', className)}>
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2">Créer un nouveau projet</h1>
        <p className="text-gray-600 dark:text-gray-400">
          Suivez les étapes pour définir votre univers, vos personnages et votre scénario
        </p>
      </div>

      {/* Step Progress */}
      <div className="mb-8">
        <StepProgress
          steps={steps}
          currentStep={steps.findIndex((s) => s.label.toLowerCase() === currentStep)}
        />
      </div>

      {/* Step Content */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 mb-6">
        {currentStep === 'world' && (
          <div className="space-y-4">
            <h2 className="text-2xl font-semibold flex items-center gap-2">
              <Globe className="w-6 h-6" />
              Définir le monde
            </h2>
            <p className="text-gray-600 dark:text-gray-400">
              Créez l'univers dans lequel se déroulera votre histoire
            </p>
            <div className="grid gap-4">
              <div className="grid gap-2">
                <Label htmlFor="world-name">Nom du monde</Label>
                <Input
                  id="world-name"
                  value={world.name}
                  onChange={(e) => setWorld({ ...world, name: e.target.value })}
                  placeholder="Ex: Terra Nova"
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="grid gap-2">
                  <Label>Époque</Label>
                  <Select value={world.era} onValueChange={(v) => setWorld({ ...world, era: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="ancient">Antique</SelectItem>
                      <SelectItem value="medieval">Médiéval</SelectItem>
                      <SelectItem value="modern">Moderne</SelectItem>
                      <SelectItem value="future">Futuriste</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid gap-2">
                  <Label>Atmosphère</Label>
                  <Select value={world.atmosphere} onValueChange={(v) => setWorld({ ...world, atmosphere: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="bright">Lumineuse</SelectItem>
                      <SelectItem value="dark">Sombre</SelectItem>
                      <SelectItem value="mysterious">Mystérieuse</SelectItem>
                      <SelectItem value="chaotic">Chaotique</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid gap-2">
                  <Label>Technologie</Label>
                  <Select value={world.technology} onValueChange={(v) => setWorld({ ...world, technology: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="magic">Magique</SelectItem>
                      <SelectItem value="steampunk">Steampunk</SelectItem>
                      <SelectItem value="modern">Moderne</SelectItem>
                      <SelectItem value="hightech">High-Tech</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid gap-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="world-desc">Description</Label>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleGenerateWorld}
                    disabled={!world.name || isAIProcessing}
                    className="h-8 text-purple-600"
                  >
                    {isAIProcessing ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                    Générer
                  </Button>
                </div>
                <Textarea
                  id="world-desc"
                  value={world.description}
                  onChange={(e) => setWorld({ ...world, description: e.target.value })}
                  placeholder="Décrivez votre monde..."
                  rows={4}
                />
              </div>
            </div>
          </div>
        )}

        {currentStep === 'characters' && (
          <div className="space-y-4">
            <h2 className="text-2xl font-semibold flex items-center gap-2">
              <Users className="w-6 h-6" />
              Créer les personnages
            </h2>
            <p className="text-gray-600 dark:text-gray-400">
              Définissez les personnages principaux de votre histoire
            </p>
            <div className="space-y-6">
              {characters.map((char, index) => (
                <div key={char.id} className="p-4 border rounded-lg bg-gray-50 dark:bg-gray-900/50 relative group">
                  <div className="absolute right-2 top-2">
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => removeCharacter(index)}
                      disabled={characters.length <= 1}
                      className="opacity-0 group-hover:opacity-100 transition-opacity text-red-500 hover:text-red-700 hover:bg-red-100"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>

                  <div className="grid gap-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="grid gap-2">
                        <Label>Nom</Label>
                        <Input
                          value={char.name}
                          onChange={(e) => handleUpdateCharacter(index, 'name', e.target.value)}
                          placeholder="Nom du personnage"
                        />
                      </div>
                      <div className="grid gap-2">
                        <Label>Rôle</Label>
                        <Select value={char.role} onValueChange={(v) => handleUpdateCharacter(index, 'role', v)}>
                          <SelectTrigger><SelectValue /></SelectTrigger>
                          <SelectContent>
                            <SelectItem value="Protagonist">Protagoniste</SelectItem>
                            <SelectItem value="Antagonist">Antagoniste</SelectItem>
                            <SelectItem value="Supporting">Secondaire</SelectItem>
                            <SelectItem value="Mentor">Mentor</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>

                    <div className="grid gap-2">
                      <div className="flex items-center justify-between">
                        <Label>Description</Label>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleGenerateCharacter(index)}
                          disabled={!char.name || isAIProcessing}
                          className="h-8 text-purple-600"
                        >
                          {isAIProcessing ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                          Générer
                        </Button>
                      </div>
                      <Textarea
                        value={char.description}
                        onChange={(e) => handleUpdateCharacter(index, 'description', e.target.value)}
                        placeholder="Description, personnalité..."
                        rows={2}
                      />
                    </div>
                  </div>
                </div>
              ))}

              <Button onClick={addCharacter} variant="outline" className="w-full dashed border-2">
                <Plus className="w-4 h-4 mr-2" />
                Ajouter un personnage
              </Button>
            </div>
          </div>
        )}

        {currentStep === 'scenario' && (
          <div className="space-y-4">
            <h2 className="text-2xl font-semibold flex items-center gap-2">
              <FileText className="w-6 h-6" />
              Écrire le scénario
            </h2>
            <p className="text-gray-600 dark:text-gray-400">
              Définissez la structure et le synopsis de votre histoire
            </p>
            <div className="grid gap-4">
              <div className="grid gap-2">
                <Label htmlFor="scenario-title">Titre du scénario</Label>
                <Input
                  id="scenario-title"
                  value={scenario.title}
                  onChange={(e) => setScenario({ ...scenario, title: e.target.value })}
                  placeholder="Titre de l'histoire"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="grid gap-2">
                  <Label>Genre</Label>
                  <Select value={scenario.genre} onValueChange={(v) => setScenario({ ...scenario, genre: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="fantasy">Fantasy</SelectItem>
                      <SelectItem value="scifi">Science-Fiction</SelectItem>
                      <SelectItem value="drama">Drame</SelectItem>
                      <SelectItem value="thriller">Thriller</SelectItem>
                      <SelectItem value="comedy">Comédie</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid gap-2">
                  <Label>Ton</Label>
                  <Select value={scenario.tone} onValueChange={(v) => setScenario({ ...scenario, tone: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="dark">Sombre</SelectItem>
                      <SelectItem value="hopeful">Optimiste</SelectItem>
                      <SelectItem value="serious">Sérieux</SelectItem>
                      <SelectItem value="humorous">Humoristique</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid gap-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="synopsis">Synopsis</Label>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleGenerateScenario}
                    disabled={!scenario.title || isAIProcessing}
                    className="h-8 text-purple-600"
                  >
                    {isAIProcessing ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Wand2 className="w-3 h-3 mr-1" />}
                    Générer
                  </Button>
                </div>
                <Textarea
                  id="synopsis"
                  value={scenario.synopsis}
                  onChange={(e) => setScenario({ ...scenario, synopsis: e.target.value })}
                  placeholder="Résumé de l'histoire..."
                  rows={6}
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Navigation Buttons */}
      <div className="flex justify-between">
        <button
          onClick={currentStep === 'world' ? onCancel : prevStep}
          disabled={isLoading || isSaving}
          className="px-6 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50"
        >
          <ChevronLeft className="w-4 h-4 inline mr-2" />
          {currentStep === 'world' ? 'Annuler' : 'Précédent'}
        </button>

        <button
          onClick={nextStep}
          disabled={isLoading || isSaving}
          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
        >
          {isSaving ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Création...
            </>
          ) : currentStep === 'scenario' ? (
            <>
              <Check className="w-4 h-4" />
              Créer le projet
            </>
          ) : (
            <>
              Suivant
              <ChevronRight className="w-4 h-4" />
            </>
          )}
        </button>
      </div>
    </div>
  );
}

/**
 * Dialogue Writer Wizard Component
 *
 * Modal wizard for creating dialogue using the DialogueWriterForm
 * Provides a modal interface for dialogue generation
 */

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { DialogueWriterForm, DialogueWriterFormProps, DialogueInput } from './forms/DialogueWriterForm';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Copy, RefreshCw, Check, ArrowLeft, Loader2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

export interface DialogueWriterWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onComplete: (data: DialogueInput, result?: string) => void;
  characters: DialogueWriterFormProps['characters'];
  initialData?: Partial<DialogueInput>;
}

export function DialogueWriterWizard({
  isOpen,
  onClose,
  onComplete,
  characters,
  initialData,
}: DialogueWriterWizardProps) {
  const { toast } = useToast();
  const [step, setStep] = useState<'input' | 'result'>('input');
  const [formData, setFormData] = useState<DialogueInput | null>(null);
  const [generatedDialogue, setGeneratedDialogue] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const generateDialogue = async (data: DialogueInput) => {
    setIsGenerating(true);
    setFormData(data);

    try {
      const { llmConfigService } = await import('@/services/llmConfigService');
      const service = llmConfigService.getService();

      if (!service) {
        toast({ title: "Service non disponible", description: "Configurez le LLM dans les paramètres", variant: "destructive" });
        setIsGenerating(false);
        return;
      }

      const charNames = data.characters
        .map(id => characters.find(c => c.id === id)?.name || id)
        .join(', ');

      const prompt = `Write a dialogue scene based on the following context:\n\nContext: ${data.sceneContext}\n\nCharacters: ${charNames}\n\nTone: ${data.tone}\n\nFormat the dialogue as a standard screenplay script.`;

      const response = await service.generateCompletion({
        prompt,
        systemPrompt: "You are an expert screenwriter and dialogue writer.",
        temperature: 0.7
      });

      if (response.success && response.data) {
        setGeneratedDialogue(response.data.content);
        setStep('result');
      } else {
        throw new Error(response.error || 'Unknown error');
      }
    } catch (error) {
      console.error("Dialogue generation failed:", error);
      toast({ title: "Erreur de génération", description: "Impossible de générer le dialogue.", variant: "destructive" });
    } finally {
      setIsGenerating(false);
    }
  };

  const handleUse = () => {
    if (formData) {
      onComplete(formData, generatedDialogue);
      onClose();
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(generatedDialogue);
    toast({ title: "Copié !", description: "Le dialogue a été copié dans le presse-papier." });
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-3xl max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>Dialogue Writer</DialogTitle>
          <DialogDescription>
            {step === 'input'
              ? "Define the context and characters for your scene."
              : "Review and edit the generated dialogue."}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-hidden mt-4">
          {step === 'input' ? (
            <DialogueWriterForm
              initialData={initialData}
              characters={characters}
              onSubmit={generateDialogue}
              onCancel={onClose}
              isGenerating={isGenerating}
            />
          ) : (
            <div className="flex flex-col h-full space-y-4">
              <ScrollArea className="flex-1 border rounded-md p-4 bg-muted/30">
                <div className="whitespace-pre-wrap font-mono text-sm leading-relaxed">
                  {generatedDialogue}
                </div>
              </ScrollArea>

              <div className="flex justify-between items-center pt-2">
                <Button variant="outline" onClick={() => setStep('input')} className="gap-2">
                  <ArrowLeft className="w-4 h-4" />
                  Back to Edit
                </Button>

                <div className="flex gap-2">
                  <Button variant="outline" onClick={handleCopy} title="Copy to clipboard">
                    <Copy className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="outline"
                    onClick={() => formData && generateDialogue(formData)}
                    disabled={isGenerating}
                    className="gap-2"
                  >
                    {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                    Regenerate
                  </Button>
                  <Button onClick={handleUse} className="gap-2">
                    <Check className="w-4 h-4" />
                    Use This Dialogue
                  </Button>
                </div>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

