import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';

// ============================================================================
// Live Region Component for Screen Reader Announcements
// ============================================================================

interface LiveRegionProps {
  message: string;
  politeness?: 'polite' | 'assertive' | 'off';
  clearAfter?: number; // milliseconds
  className?: string;
}

/**
 * Live Region component for announcing dynamic content to screen readers
 * 
 * Usage:
 * - Use 'polite' for non-urgent updates (default)
 * - Use 'assertive' for important/urgent updates
 * - Use 'off' to disable announcements
 * 
 * @param message - The message to announce
 * @param politeness - The ARIA live politeness level
 * @param clearAfter - Optional delay before clearing the message (in ms)
 * @param className - Optional CSS classes
 */
export function LiveRegion({
  message,
  politeness = 'polite',
  clearAfter,
  className,
}: LiveRegionProps) {
  const [currentMessage, setCurrentMessage] = useState(message);

  useEffect(() => {
    setCurrentMessage(message);

    if (clearAfter && message) {
      const timer = setTimeout(() => {
        setCurrentMessage('');
      }, clearAfter);

      return () => clearTimeout(timer);
    }
  }, [message, clearAfter]);

  return (
    <div
      role="status"
      aria-live={politeness}
      aria-atomic="true"
      className={cn('sr-only', className)}
    >
      {currentMessage}
    </div>
  );
}

// ============================================================================
// Alert Live Region Component
// ============================================================================

interface AlertLiveRegionProps {
  message: string;
  type?: 'info' | 'success' | 'warning' | 'error';
  clearAfter?: number;
  className?: string;
}

/**
 * Alert Live Region component for important announcements
 * Uses assertive politeness for immediate screen reader attention
 * 
 * @param message - The alert message to announce
 * @param type - The type of alert (affects semantics)
 * @param clearAfter - Optional delay before clearing the message (in ms)
 * @param className - Optional CSS classes
 */
export function AlertLiveRegion({
  message,
  type = 'info',
  clearAfter,
  className,
}: AlertLiveRegionProps) {
  const [currentMessage, setCurrentMessage] = useState(message);

  useEffect(() => {
    setCurrentMessage(message);

    if (clearAfter && message) {
      const timer = setTimeout(() => {
        setCurrentMessage('');
      }, clearAfter);

      return () => clearTimeout(timer);
    }
  }, [message, clearAfter]);

  const roleMap = {
    info: 'status',
    success: 'status',
    warning: 'alert',
    error: 'alert',
  };

  return (
    <div
      role={roleMap[type]}
      aria-live="assertive"
      aria-atomic="true"
      className={cn('sr-only', className)}
    >
      {currentMessage}
    </div>
  );
}

// ============================================================================
// Loading Announcement Component
// ============================================================================

interface LoadingAnnouncementProps {
  isLoading: boolean;
  loadingMessage?: string;
  completeMessage?: string;
  className?: string;
}

/**
 * Loading Announcement component for async operations
 * Announces when loading starts and completes
 * 
 * @param isLoading - Whether the operation is currently loading
 * @param loadingMessage - Message to announce when loading starts
 * @param completeMessage - Message to announce when loading completes
 * @param className - Optional CSS classes
 */
export function LoadingAnnouncement({
  isLoading,
  loadingMessage = 'Loading...',
  completeMessage = 'Loading complete',
  className,
}: LoadingAnnouncementProps) {
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (isLoading) {
      setMessage(loadingMessage);
    } else if (message === loadingMessage) {
      // Only announce completion if we were previously loading
      setMessage(completeMessage);
      
      // Clear the completion message after a delay
      const timer = setTimeout(() => {
        setMessage('');
      }, 3000);

      return () => clearTimeout(timer);
    }
  }, [isLoading, loadingMessage, completeMessage, message]);

  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic="true"
      className={cn('sr-only', className)}
    >
      {message}
    </div>
  );
}

// ============================================================================
// Step Change Announcement Component
// ============================================================================

interface StepChangeAnnouncementProps {
  currentStep: number;
  totalSteps: number;
  stepTitle: string;
  className?: string;
}

/**
 * Step Change Announcement component for wizard navigation
 * Announces when the user navigates to a new step
 * 
 * @param currentStep - The current step number
 * @param totalSteps - The total number of steps
 * @param stepTitle - The title of the current step
 * @param className - Optional CSS classes
 */
export function StepChangeAnnouncement({
  currentStep,
  totalSteps,
  stepTitle,
  className,
}: StepChangeAnnouncementProps) {
  const [message, setMessage] = useState('');

  useEffect(() => {
    const announcement = `Step ${currentStep} of ${totalSteps}: ${stepTitle}`;
    setMessage(announcement);

    // Clear after announcement
    const timer = setTimeout(() => {
      setMessage('');
    }, 2000);

    return () => clearTimeout(timer);
  }, [currentStep, totalSteps, stepTitle]);

  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic="true"
      className={cn('sr-only', className)}
    >
      {message}
    </div>
  );
}

/**
 * Object Wizard Modal
 * 
 * Modal wrapper for the Object Wizard that handles opening/closing
 * and completion logic.
 */

import React from 'react';
import { ObjectWizard } from './object/ObjectWizard';
import { useAppStore } from '@/stores/useAppStore';
import type { StoryObject } from '@/types/object';
import './WizardModal.css';

export interface ObjectWizardModalProps {
  isOpen: boolean;
  onClose: () => void;
  onComplete: (object: StoryObject) => void;
  initialData?: Partial<StoryObject>;
}

export function ObjectWizardModal({
  isOpen,
  onClose,
  onComplete,
  initialData,
}: ObjectWizardModalProps) {
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  console.log('[ObjectWizardModal] Rendered with isOpen:', isOpen);

  if (!isOpen) {
    return null;
  }

  const handleCancel = () => {
    console.log('[ObjectWizardModal] Wizard cancelled');
    onClose();
  };

  const handleComplete = (object: StoryObject) => {
    console.log('[ObjectWizardModal] Object completed:', object);
    onComplete(object);
    onClose();
  };

  return (
    <div className="wizard-modal-overlay">
      <div className="wizard-modal-container">
        <ObjectWizard
          onComplete={handleComplete}
          onCancel={handleCancel}
          initialData={initialData}
        />
      </div>
    </div>
  );
}

export default ObjectWizardModal;

/**
 * Prompt Library Modal
 * Modal wrapper for the Prompt Library Browser
 */

import { useState } from 'react';
import { X, BookOpen } from 'lucide-react';
import { PromptLibraryBrowser } from '../../library/PromptLibraryBrowser';
import '../../library/PromptLibraryBrowser.css';

interface PromptLibraryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectPrompt: (prompt: string) => void;
  title?: string;
}

export function PromptLibraryModal({
  isOpen,
  onClose,
  onSelectPrompt,
  title = 'Prompt Library'
}: PromptLibraryModalProps) {
  if (!isOpen) return null;

  const handlePromptSelect = (prompt: string) => {
    onSelectPrompt(prompt);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Modal */}
      <div className="relative w-full max-w-7xl h-[90vh] mx-4 bg-white dark:bg-gray-900 rounded-lg shadow-2xl flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-800">
          <div className="flex items-center gap-2">
            <BookOpen className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              {title}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            aria-label="Close"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden">
          <PromptLibraryBrowser onSelectPrompt={handlePromptSelect} />
        </div>
      </div>
    </div>
  );
}

// Export a hook to manage the modal state
export function usePromptLibraryModal() {
  const [isOpen, setIsOpen] = useState(false);

  return {
    isOpen,
    open: () => setIsOpen(true),
    close: () => setIsOpen(false),
    toggle: () => setIsOpen(prev => !prev)
  };
}

/**
 * PromptStyleTransfer
 * Component for configuring prompt-based style transfer
 */

import React, { useCallback, useState, useEffect } from 'react';
import { PromptStyleTransferProps, StylePresetName, STYLE_PRESETS } from '../../types/styleTransfer';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/card';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Slider } from '../../components/ui/slider';
import { Textarea } from '../../components/ui/textarea';
import { Upload, Image as ImageIcon, Type, Settings2, X, Sparkles, Palette } from 'lucide-react';
import { cn } from '../../lib/utils';

export const PromptStyleTransfer: React.FC<PromptStyleTransferProps> = ({
  config,
  onConfigChange,
  sourceFile,
  onSourceFileChange,
  selectedPreset,
  onPresetChange,
  customPrompt,
  onCustomPromptChange
}) => {
  const [sourcePreview, setSourcePreview] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'preset' | 'custom'>(
    selectedPreset ? 'preset' : 'custom'
  );

  // Update config when preset changes
  useEffect(() => {
    if (selectedPreset && STYLE_PRESETS[selectedPreset]) {
      const preset = STYLE_PRESETS[selectedPreset];
      onConfigChange({
        ...config,
        prompt: preset.prompt
      });
    }
  }, [selectedPreset]);

  // Update config when custom prompt changes
  useEffect(() => {
    if (activeTab === 'custom' && customPrompt) {
      onConfigChange({
        ...config,
        prompt: customPrompt
      });
    }
  }, [customPrompt, activeTab]);

  const handleSourceFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onSourceFileChange(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setSourcePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  }, [onSourceFileChange]);

  const clearSourceFile = useCallback(() => {
    onSourceFileChange(undefined as any);
    setSourcePreview(null);
  }, [onSourceFileChange]);

  const updateConfig = useCallback((updates: Partial<typeof config>) => {
    onConfigChange({ ...config, ...updates });
  }, [config, onConfigChange]);

  const handlePresetSelect = useCallback((preset: StylePresetName) => {
    onPresetChange(preset);
    setActiveTab('preset');
  }, [onPresetChange]);

  const handleCustomTabClick = useCallback(() => {
    setActiveTab('custom');
    onPresetChange(undefined as any);
  }, [onPresetChange]);

  const categories = Array.from(new Set(Object.values(STYLE_PRESETS).map(p => p.category)));

  return (
    <div className="space-y-6">
      {/* Source Image Upload */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ImageIcon className="w-4 h-4" />
            Source Image
          </CardTitle>
        </CardHeader>
        <CardContent>
          {sourcePreview ? (
            <div className="relative">
              <img 
                src={sourcePreview} 
                alt="Source" 
                className="w-full h-48 object-cover rounded-lg"
              />
              <button
                onClick={clearSourceFile}
                className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-600"
                aria-label="Remove source image"
                title="Remove source image"
              >
                <X className="w-4 h-4" />
              </button>
              <p className="text-xs text-muted-foreground mt-2 text-center">
                {sourceFile?.name}
              </p>
            </div>
          ) : (
            <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-8 text-center hover:border-primary/50 transition-colors">
              <input
                type="file"
                accept="image/*"
                onChange={handleSourceFileSelect}
                className="hidden"
                id="prompt-source-upload"
              />
              <label 
                htmlFor="prompt-source-upload"
                className="cursor-pointer flex flex-col items-center gap-2"
              >
                <Upload className="w-8 h-8 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">
                  Click to upload source image
                </span>
                <span className="text-xs text-muted-foreground/60">
                  Supports: PNG, JPG, WEBP
                </span>
              </label>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Style Selection Tabs */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <Palette className="w-4 h-4" />
              Style Selection
            </CardTitle>
            <div className="flex gap-2">
              <Button
                variant={activeTab === 'preset' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setActiveTab('preset')}
              >
                Presets
              </Button>
              <Button
                variant={activeTab === 'custom' ? 'default' : 'outline'}
                size="sm"
                onClick={handleCustomTabClick}
              >
                Custom
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {activeTab === 'preset' ? (
            <div className="space-y-4">
              {categories.map(category => (
                <div key={category}>
                  <h4 className="text-sm font-medium text-muted-foreground mb-2">{category}</h4>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {Object.entries(STYLE_PRESETS)
                      .filter(([_, preset]) => preset.category === category)
                      .map(([key, preset]) => (
                        <button
                          key={key}
                          onClick={() => handlePresetSelect(key as StylePresetName)}
                          className={cn(
                            'p-3 rounded-lg border text-left transition-all',
                            selectedPreset === key
                              ? 'border-primary bg-primary/5 ring-1 ring-primary'
                              : 'border-muted hover:border-primary/50 hover:bg-muted/50'
                          )}
                        >
                          <div className="font-medium text-sm">{preset.name}</div>
                          <div className="text-xs text-muted-foreground mt-1 line-clamp-2">
                            {preset.description}
                          </div>
                        </button>
                      ))}
                  </div>
                </div>
              ))}
              
              {selectedPreset && (
                <div className="mt-4 p-3 bg-muted rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles className="w-4 h-4 text-primary" />
                    <span className="font-medium">Selected: {STYLE_PRESETS[selectedPreset].name}</span>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    {STYLE_PRESETS[selectedPreset].prompt}
                  </p>
                </div>
              )}
            </div>
          ) : (
            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="custom-prompt">Custom Style Prompt</Label>
                <Textarea
                  id="custom-prompt"
                  value={customPrompt || ''}
                  onChange={(e) => onCustomPromptChange(e.target.value)}
                  placeholder="Describe the style you want to apply... (e.g., 'oil painting style with thick brushstrokes and vibrant colors')"
                  rows={4}
                />
                <p className="text-xs text-muted-foreground">
                  Describe the artistic style, lighting, colors, and mood you want
                </p>
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="negative-prompt">Negative Prompt (Optional)</Label>
                <Textarea
                  id="negative-prompt"
                  value={config.negativePrompt}
                  onChange={(e) => updateConfig({ negativePrompt: e.target.value })}
                  placeholder="Elements to avoid in the output..."
                  rows={2}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Configuration Section */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Settings2 className="w-4 h-4" />
            Generation Settings
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Output Prefix */}
          <div className="space-y-2">
            <Label htmlFor="prompt-output-prefix">Output Filename Prefix</Label>
            <Input
              id="prompt-output-prefix"
              value={config.outputPrefix}
              onChange={(e) => updateConfig({ outputPrefix: e.target.value })}
              placeholder="prompt_style"
            />
          </div>

          {/* Steps Slider */}
          <div className="space-y-4">
            <div className="flex justify-between">
              <Label>Inference Steps</Label>
              <span className="text-sm text-muted-foreground">{config.steps}</span>
            </div>
            <Slider
              value={[config.steps]}
              onValueChange={([value]) => updateConfig({ steps: value })}
              min={1}
              max={50}
              step={1}
            />
            <p className="text-xs text-muted-foreground">
              More steps = higher quality but slower. Recommended: 10-20
            </p>
          </div>

          {/* CFG Scale Slider */}
          <div className="space-y-4">
            <div className="flex justify-between">
              <Label>CFG Scale</Label>
              <span className="text-sm text-muted-foreground">{config.cfgScale.toFixed(1)}</span>
            </div>
            <Slider
              value={[config.cfgScale]}
              onValueChange={([value]) => updateConfig({ cfgScale: value })}
              min={0.5}
              max={3.0}
              step={0.1}
            />
            <p className="text-xs text-muted-foreground">
              Higher = stronger prompt adherence. Recommended: 1.0-1.5
            </p>
          </div>

          {/* Dimensions */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="width">Width</Label>
              <Input
                id="width"
                type="number"
                value={config.width}
                onChange={(e) => updateConfig({ width: parseInt(e.target.value) || 1024 })}
                min={512}
                max={2048}
                step={64}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="height">Height</Label>
              <Input
                id="height"
                type="number"
                value={config.height}
                onChange={(e) => updateConfig({ height: parseInt(e.target.value) || 1024 })}
                min={512}
                max={2048}
                step={64}
              />
            </div>
          </div>
          <p className="text-xs text-muted-foreground">
            Output dimensions. Must be multiples of 64. Default: 1024x1024
          </p>

          {/* Seed Input */}
          <div className="space-y-2">
            <Label htmlFor="prompt-seed">Random Seed</Label>
            <Input
              id="prompt-seed"
              type="number"
              value={config.seed}
              onChange={(e) => updateConfig({ seed: parseInt(e.target.value) || -1 })}
              placeholder="-1 for random"
            />
            <p className="text-xs text-muted-foreground">
              -1 for random, or set for reproducible results
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Tips Card */}
      <Card className="bg-purple-50 border-purple-200">
        <CardContent className="p-4">
