                <button
                  onClick={clearSourceFile}
                  className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-600"
                  aria-label="Remove source image"
                  title="Remove source image"
                >
                  <X className="w-4 h-4" />
                </button>

                <p className="text-xs text-muted-foreground mt-2 text-center">
                  {sourceFile?.name}
                </p>
              </div>
            ) : (
              <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-8 text-center hover:border-primary/50 transition-colors">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleSourceFileSelect}
                  className="hidden"
                  id="source-image-upload"
                />
                <label 
                  htmlFor="source-image-upload"
                  className="cursor-pointer flex flex-col items-center gap-2"
                >
                  <Upload className="w-8 h-8 text-muted-foreground" />
                  <span className="text-sm text-muted-foreground">
                    Click to upload source image
                  </span>
                  <span className="text-xs text-muted-foreground/60">
                    Supports: PNG, JPG, WEBP
                  </span>
                </label>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Style Reference Image */}
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Palette className="w-4 h-4" />
              Style Reference
            </CardTitle>
          </CardHeader>
          <CardContent>
            {stylePreview ? (
              <div className="relative">
                <img 
                  src={stylePreview} 
                  alt="Style" 
                  className="w-full h-48 object-cover rounded-lg"
                />
                <button
                  onClick={clearStyleFile}
                  className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-600"
                  aria-label="Remove style reference image"
                  title="Remove style reference image"
                >
                  <X className="w-4 h-4" />
                </button>

                <p className="text-xs text-muted-foreground mt-2 text-center">
                  {styleFile?.name}
                </p>
              </div>
            ) : (
              <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-8 text-center hover:border-primary/50 transition-colors">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleStyleFileSelect}
                  className="hidden"
                  id="style-image-upload"
                />
                <label 
                  htmlFor="style-image-upload"
                  className="cursor-pointer flex flex-col items-center gap-2"
                >
                  <Palette className="w-8 h-8 text-muted-foreground" />
                  <span className="text-sm text-muted-foreground">
