import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, waitFor, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { WizardProvider, useWizard } from '@/contexts/WizardContext';
import { useWizardNavigation } from '@/hooks/useWizardNavigation';
import {
  saveWizardState,
  loadWizardState,
  clearWizardState,
  isLocalStorageAvailable,
} from '@/utils/wizardStorage';

// ============================================================================
// Test Component
// ============================================================================

interface TestFormData {
  name: string;
  email: string;
  age: number;
}

function TestWizardContent() {
  const { formData, updateFormData, validationErrors } = useWizard<TestFormData>();
  const { currentStep, nextStep, previousStep, canGoNext, canGoPrevious } = useWizardNavigation();

  return (
    <div>
      <div data-testid="current-step">Step {currentStep}</div>
      <div data-testid="form-data">{JSON.stringify(formData)}</div>
      
      {currentStep === 1 && (
        <div>
          <input
            data-testid="name-input"
            value={formData.name || ''}
            onChange={(e) => updateFormData({ name: e.target.value })}
          />
          {validationErrors.name && (
            <span data-testid="name-error">{validationErrors.name[0]}</span>
          )}
        </div>
      )}

      {currentStep === 2 && (
        <div>
          <input
            data-testid="email-input"
            value={formData.email || ''}
            onChange={(e) => updateFormData({ email: e.target.value })}
          />
        </div>
      )}

      <button
        data-testid="previous-button"
        onClick={previousStep}
        disabled={!canGoPrevious}
      >
        Previous
      </button>
      <button
        data-testid="next-button"
        onClick={nextStep}
        disabled={!canGoNext}
      >
        Next
      </button>
    </div>
  );
}

// ============================================================================
// Tests
// ============================================================================

describe('Wizard Infrastructure', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  describe('WizardContext', () => {
    it('should provide wizard state to children', () => {
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      expect(screen.getByTestId('current-step')).toHaveTextContent('Step 1');
    });

    it('should update form data', async () => {
      const user = userEvent.setup();
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      const nameInput = screen.getByTestId('name-input');
      await user.type(nameInput, 'John Doe');

      await waitFor(() => {
        const formData = JSON.parse(screen.getByTestId('form-data').textContent || '{}');
        expect(formData.name).toBe('John Doe');
      });
    });

    it('should navigate between steps', async () => {
      const user = userEvent.setup();
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      expect(screen.getByTestId('current-step')).toHaveTextContent('Step 1');

      const nextButton = screen.getByTestId('next-button');
      await user.click(nextButton);

      expect(screen.getByTestId('current-step')).toHaveTextContent('Step 2');

      const previousButton = screen.getByTestId('previous-button');
      await user.click(previousButton);

      expect(screen.getByTestId('current-step')).toHaveTextContent('Step 1');
    });

    it('should preserve form data during navigation', async () => {
      const user = userEvent.setup();
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      // Enter data on step 1
      const nameInput = screen.getByTestId('name-input');
      await user.type(nameInput, 'John Doe');

      // Navigate to step 2
      const nextButton = screen.getByTestId('next-button');
      await user.click(nextButton);

      // Navigate back to step 1
      const previousButton = screen.getByTestId('previous-button');
      await user.click(previousButton);

      // Data should still be there
      await waitFor(() => {
        const formData = JSON.parse(screen.getByTestId('form-data').textContent || '{}');
        expect(formData.name).toBe('John Doe');
      });
    });
  });

  describe('wizardStorage utilities', () => {
    it('should check localStorage availability', () => {
      expect(isLocalStorageAvailable()).toBe(true);
    });

    it('should save and load wizard state', () => {
      const formData = { name: 'Test', email: 'test@example.com', age: 25 };
      
      const saved = saveWizardState('world', 2, formData);
      expect(saved).toBe(true);

      const loaded = loadWizardState<TestFormData>('world');
      expect(loaded).not.toBeNull();
      expect(loaded?.currentStep).toBe(2);
      expect(loaded?.formData).toEqual(formData);
    });

    it('should clear wizard state', () => {
      const formData = { name: 'Test', email: 'test@example.com', age: 25 };
      
      saveWizardState('world', 2, formData);
      clearWizardState('world');

      const loaded = loadWizardState<TestFormData>('world');
      expect(loaded).toBeNull();
    });

    it('should handle expired state', () => {
      const formData = { name: 'Test', email: 'test@example.com', age: 25 };
      
      // Save with negative expiration (already expired)
      saveWizardState('world', 2, formData, -1);

      const loaded = loadWizardState<TestFormData>('world');
      expect(loaded).toBeNull();
    });

    it('should handle corrupted state', () => {
      // Manually set corrupted data
      localStorage.setItem('wizard-world', 'invalid-json{');

      const loaded = loadWizardState<TestFormData>('world');
      expect(loaded).toBeNull();

      // Should have cleared the corrupted data
      expect(localStorage.getItem('wizard-world')).toBeNull();
    });
  });

  describe('useWizardNavigation', () => {
    it('should provide navigation state', () => {
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      // On first step
      expect(screen.getByTestId('previous-button')).toBeDisabled();
      expect(screen.getByTestId('next-button')).not.toBeDisabled();
    });

    it('should disable navigation at boundaries', async () => {
      const user = userEvent.setup();
      const onSubmit = vi.fn();

      render(
        <WizardProvider
          wizardType="world"
          totalSteps={3}
          onSubmit={onSubmit}
          autoSave={false}
        >
          <TestWizardContent />
        </WizardProvider>
      );

      // Navigate to last step
      const nextButton = screen.getByTestId('next-button');
      await user.click(nextButton);
      await user.click(nextButton);

      expect(screen.getByTestId('current-step')).toHaveTextContent('Step 3');
      expect(screen.getByTestId('next-button')).toBeDisabled();
      expect(screen.getByTestId('previous-button')).not.toBeDisabled();
    });
  });
});

import React, { useCallback, useState, useEffect } from 'react';
import { WizardProvider, useWizard } from '@/contexts/WizardContext';
import { ProductionWizardContainer } from '../production-wizards/ProductionWizardContainer';
import type { WizardStep } from '../WizardStepIndicator';
import type { Character } from '@/types/character';
import { createEmptyCharacter } from '@/types/character';
import type { World } from '@/types/world';
import type { Story } from '@/types/story';
import { useCharacterPersistence } from '@/hooks/useCharacterPersistence';
import { useServiceStatus } from '@/components/ui/service-warning';
import { eventEmitter, CharacterEventType, createCharacterCreatedPayload } from '@/services/eventEmitter';
import { Step1BasicIdentity } from './Step1BasicIdentity';
import { Step2PhysicalAppearance } from './Step2PhysicalAppearance';
import { Step3Personality } from './Step3Personality';
import { Step4Background } from './Step4Background';
import { Step5Relationships } from './Step5Relationships';
import { Step6ReviewFinalize } from './Step6ReviewFinalize';
import { WizardChainOptions, WizardChainOption } from '../WizardChainOptions';
import { Loader2, AlertCircle, CheckCircle2, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/button';

// ============================================================================
// Character Wizard Component
// ============================================================================

/**
 * Story context for character creation
 * Used when creating a character from within the Story Generator
 */
export interface StoryContext {
  storyId?: string;
  storyName?: string;
  storyData?: Partial<Story>;
}

export interface CharacterWizardProps {
  onComplete: (character: Character, context?: StoryContext) => void;
  onCancel: () => void;
  worldContext?: World;
  storyContext?: StoryContext;
  initialData?: Partial<Character>;
}

const WIZARD_STEPS: WizardStep[] = [
  {
    number: 1,
    title: 'Neural Signature',
    description: 'Establish core identity parameters',
  },
  {
    number: 2,
    title: 'Morphological Profile',
    description: 'Synthesize visual appearance data',
  },
  {
    number: 3,
    title: 'Cognitive Matrix',
    description: 'Map heuristic traits and values',
  },
  {
    number: 4,
    title: 'Chronological Data',
    description: 'Access background and history',
  },
  {
    number: 5,
    title: 'SocialGrid Nexus',
    description: 'Map interpersonal connections',
  },
  {
    number: 6,
    title: 'Final Materialization',
    description: 'Validate and commit consciousness',
  },
];

// ============================================================================
// Character Wizard Content (uses wizard context)
// ============================================================================

interface CharacterWizardContentProps {
  steps: WizardStep[];
  onCancel: () => void;
  worldContext?: World;
  storyContext?: StoryContext;
  renderStepContent: (step: number) => React.ReactNode;
  onComplete?: () => void;
}

function CharacterWizardContent({
  steps,
  onCancel,
  renderStepContent,
  onComplete,
}: CharacterWizardContentProps) {
  const { currentStep, nextStep, previousStep, goToStep, isDirty, submitWizard } = useWizard<Character>();

  const handleComplete = async () => {
    await submitWizard();
    onComplete?.();
  };

  return (
    <ProductionWizardContainer
      title="Neural Character Synthesis"
      steps={steps}
      onCancel={onCancel}
      onComplete={handleComplete}
      allowJumpToStep={false}
      showAutoSaveIndicator={true}
      currentStep={currentStep}
      onNextStep={nextStep}
      onPreviousStep={previousStep}
      onGoToStep={goToStep}
      isDirty={isDirty}
    >
      {renderStepContent(currentStep)}
    </ProductionWizardContainer>
  );
}

export function CharacterWizard({
  onComplete,
  onCancel,
  worldContext,
  storyContext,
  initialData,
}: CharacterWizardProps) {
  // ============================================================================
  // ALL HOOKS MUST BE CALLED BEFORE ANY CONDITIONAL RETURNS
  // ============================================================================

  // Check LLM service status
  const { llmConfigured, llmChecking } = useServiceStatus();

  // Character Persistence hook
  const { saveCharacter } = useCharacterPersistence();

  // Local state for success view
  const [isSuccess, setIsSuccess] = useState(false);
  const [createdCharacter, setCreatedCharacter] = useState<Character | null>(null);

  // ============================================================================
  // Validation
  // ============================================================================

  const validateStep = useCallback(
    async (step: number, data: Partial<Character>): Promise<Record<string, string[]>> => {
      const errors: Record<string, string[]> = {};

      switch (step) {
        case 1: // Basic Identity
          if (!data.name || data.name.trim() === '') {
            errors.name = ['Character name is required'];
          }
          if (!data.role?.archetype || data.role.archetype.trim() === '') {
            errors.archetype = ['Character archetype is required'];
          }
          if (!data.visual_identity?.gender || data.visual_identity.gender.trim() === '') {
            errors.gender = ['Gender is required'];
          }
          if (!data.visual_identity?.age_range || data.visual_identity.age_range.trim() === '') {
            errors.age_range = ['Age Range is required'];
          }
          break;

        case 2: // Physical Appearance
          // Optional validation - appearance fields can be empty
          // LLM will help fill these in
          break;

        case 3: // Personality
          // Optional validation - personality can be built gradually
          if (data.personality?.traits && data.personality.traits.length > 10) {
            errors.traits = ['Maximum 10 personality traits allowed'];
          }
          break;

        case 4: // Background
          // Optional validation - background can be empty
          break;

        case 5: // Relationships
          // Validate that referenced characters exist
          if (data.relationships && data.relationships.length > 0) {
            data.relationships.forEach((rel, index) => {
              if (!rel.character_name || rel.character_name.trim() === '') {
                errors[`relationship-${index}-name`] = ['Character name is required'];
              }
              if (!rel.relationship_type || rel.relationship_type.trim() === '') {
                errors[`relationship-${index}-type`] = ['Relationship type is required'];
              }
            });
          }
          break;

        case 6: // Review
          // Final validation - ensure all required fields are present
          if (!data.name || data.name.trim() === '') {
            errors.name = ['Character name is required'];
          }
          if (!data.role?.archetype || data.role.archetype.trim() === '') {
            errors.archetype = ['Character archetype is required'];
          }
          if (!data.visual_identity?.gender || data.visual_identity.gender.trim() === '') {
            errors.gender = ['Gender is required'];
          }
          if (!data.visual_identity?.age_range || data.visual_identity.age_range.trim() === '') {
            errors.age_range = ['Age Range is required'];
          }
          break;
      }

      return errors;
    },
    []
  );

  // ============================================================================
  // Submission
  // ============================================================================

  const handleSubmit = useCallback(
    async (data: Partial<Character>) => {
      try {
        // Save character to JSON file and update store
        const savedCharacter = await saveCharacter(data);

        // Emit character-created event with proper payload structure
        // Requirements: 3.4, 12.1
        eventEmitter.emit(
          CharacterEventType.CHARACTER_CREATED,
          createCharacterCreatedPayload(
            savedCharacter,
            'wizard',
            storyContext?.storyName
          )
        );

        // Call the onComplete callback with saved character and story context
        // Requirements: 3.2, 3.5
        onComplete(savedCharacter, storyContext);
      } catch (error) {
        console.error('Failed to save character:', error);

        // Create a detailed error message based on the error type
        let errorMessage = 'Failed to save character: ';
        if (error instanceof Error) {
          errorMessage += error.message;

          // Add specific guidance for common error types
          if (error.message.includes('permission') || error.message.includes('access')) {
            errorMessage += '\nPlease check your file system permissions.';
          } else if (error.message.includes('network') || error.message.includes('connection')) {
            errorMessage += '\nPlease check your network connection.';
          } else if (error.message.includes('invalid')) {
            errorMessage += '\nPlease verify all character data is valid.';
          }
        } else {
          errorMessage += 'Unknown error occurred.';
        }

        // Show error to user
        alert(errorMessage);

        // Still create the character object for the callback
        // even if persistence failed
        // Generate UUID with fallback
        let characterId = data.character_id;
        if (!characterId) {
          if (typeof crypto !== 'undefined' && crypto.randomUUID) {
            characterId = crypto.randomUUID();
          } else {
            characterId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
              const r = (Math.random() * 16) | 0;
              const v = c === 'x' ? r : (r & 0x3) | 0x8;
              return v.toString(16);
            });
          }
        }

        const character: Character = {
          character_id: characterId,
          name: data.name || '',
          creation_method: 'wizard',
          creation_timestamp: Date.now(),
          version: '1.0',
          visual_identity: {
            hair_color: data.visual_identity?.hair_color || '',
            hair_style: data.visual_identity?.hair_style || '',
            hair_length: data.visual_identity?.hair_length || '',
            eye_color: data.visual_identity?.eye_color || '',
            eye_shape: data.visual_identity?.eye_shape || '',
            skin_tone: data.visual_identity?.skin_tone || '',
            facial_structure: data.visual_identity?.facial_structure || '',
            distinctive_features: data.visual_identity?.distinctive_features || [],
            age_range: data.visual_identity?.age_range || '',
            gender: data.visual_identity?.gender || '',
            height: data.visual_identity?.height || '',
            build: data.visual_identity?.build || '',
            posture: data.visual_identity?.posture || '',
            clothing_style: data.visual_identity?.clothing_style || '',
            color_palette: data.visual_identity?.color_palette || [],
            reference_images: data.visual_identity?.reference_images || [],
            reference_sheet_images: data.visual_identity?.reference_sheet_images || [],
          },
          personality: {
            traits: data.personality?.traits || [],
            values: data.personality?.values || [],
            fears: data.personality?.fears || [],
            desires: data.personality?.desires || [],
            flaws: data.personality?.flaws || [],
            strengths: data.personality?.strengths || [],
            temperament: data.personality?.temperament || '',
            communication_style: data.personality?.communication_style || '',
          },
          background: {
            origin: data.background?.origin || '',
            occupation: data.background?.occupation || '',
            education: data.background?.education || '',
            family: data.background?.family || '',
            significant_events: data.background?.significant_events || [],
            current_situation: data.background?.current_situation || '',
          },
          relationships: data.relationships || [],
          role: {
            archetype: data.role?.archetype || '',
            narrative_function: data.role?.narrative_function || '',
            character_arc: data.role?.character_arc || '',
          },
          prompts: data.prompts || [],
        };

        // Emit event even on persistence failure
        eventEmitter.emit(
          CharacterEventType.CHARACTER_CREATED,
          createCharacterCreatedPayload(
            character,
            'wizard',
            storyContext?.storyName
          )
        );

        // onComplete(character, storyContext); // Removed to show success screen first

        // Store for success view
        setCreatedCharacter(character);
        setIsSuccess(true);
        // Note: We do NOT call onComplete here immediately anymore, 
        // to allow the user to see the success screen.
      }
    },
    [onComplete, saveCharacter, storyContext]
  );

  const handleCreateAnother = useCallback(() => {
    setIsSuccess(false);
    setCreatedCharacter(null);
    // WizardProvider will remount and reset
  }, []);

  const handleFinish = useCallback(() => {
    if (createdCharacter) {
      onComplete(createdCharacter, storyContext);
    }
  }, [createdCharacter, onComplete, storyContext]);

  // Create a callback for WizardContainer that triggers completion
  // The actual character data is handled by handleSubmit (passed to WizardProvider.onSubmit)
  // This callback is called after submitWizard() completes successfully
  const handleWizardComplete = useCallback(() => {
    // This callback is called by WizardNavigation when user clicks "Complete"
    // The character has already been created and onComplete(character) was called by handleSubmit
    // This is just a notification that the wizard finished successfully
    console.log('[CharacterWizard] Wizard completion confirmed');
  }, []);

  // ============================================================================
  // Render Step Content
  // ============================================================================

  const renderStepContent = (currentStep: number) => {
    switch (currentStep) {
      case 1:
        return <Step1BasicIdentity worldContext={worldContext} storyContext={storyContext} />;
      case 2:
        return <Step2PhysicalAppearance worldContext={worldContext} storyContext={storyContext} />;
      case 3:
        return <Step3Personality storyContext={storyContext} />;
      case 4:
        return <Step4Background worldContext={worldContext} storyContext={storyContext} />;
      case 5:
        return <Step5Relationships storyContext={storyContext} />;
      case 6:
        return <Step6ReviewFinalize storyContext={storyContext} />;
      default:
        return null;
    }
  };


  // ============================================================================
  // CONDITIONAL RENDERING (after all hooks)
  // ============================================================================

  if (isSuccess && createdCharacter) {
    const chainOptions: WizardChainOption[] = [
      {
        wizardType: 'create-another',
        label: 'Create Another Character',
        description: 'Create another character for this world',
        icon: 'UserPlus'
      }
    ];

    return (
      <div className="flex flex-col items-center justify-center p-8 space-y-6 h-full">
        <div className="flex flex-col items-center text-center space-y-2">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
            <CheckCircle2 className="w-10 h-10 text-green-600" />
          </div>
          <h2 className="text-2xl font-bold">Character Created!</h2>
          <p className="text-gray-600 max-w-md">
            "{createdCharacter.name}" has been saved successfully.
          </p>
        </div>

        <div className="w-full max-w-md border-t pt-6">
          <WizardChainOptions
            isChained={true}
            triggeredWizards={chainOptions}
            currentChainIndex={0}
            onLaunchNext={handleCreateAnother}
            onSkipChain={handleFinish}
            onContinue={handleFinish}
          />
        </div>
      </div>
    );
  }


  return (
    <WizardProvider<Character>
      wizardType="character"
      totalSteps={6}
      initialData={initialData || createEmptyCharacter()}
      onSubmit={handleSubmit}
      onValidateStep={validateStep}
      autoSave={true}
      autoSaveDelay={2000}
    >
      <CharacterWizardContent
        steps={WIZARD_STEPS}
        onCancel={onCancel}
        worldContext={worldContext}
        storyContext={storyContext}
        onComplete={handleWizardComplete}
        renderStepContent={renderStepContent}
      />
    </WizardProvider>
  );
}

import React from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { ValidationErrorSummary } from '../ValidationErrorSummary';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Sparkles, X, Activity, Fingerprint, User, Clock } from 'lucide-react';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';
import { cn } from '@/lib/utils';
import { LLMLoadingState, LLMErrorDisplay } from '../LLMErrorDisplay';
import { useMemoryStore } from '@/stores/memoryStore';
import { CHARACTER_ARCHETYPES, AGE_RANGES, GENDER_OPTIONS } from '@/constants/characterOptions';
import type { Character } from '@/types/character';
import type { World } from '@/types/world';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 1: Neural Signature (Basic Identity)
// ============================================================================

interface Step1BasicIdentityProps {
  worldContext?: World;
  storyContext?: StoryContext;
}

export function Step1BasicIdentity({ worldContext }: Step1BasicIdentityProps) {
  const { formData, updateFormData, validationErrors } = useWizard<Character>();
  const { llmConfigured, llmChecking } = useServiceStatus();
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);
  const [suggestions, setSuggestions] = React.useState<string[]>([]);

  // LLM generation for name suggestions
  const {
    generate,
    isLoading,
    error: llmError,
    clearError,
  } = useLLMGeneration({
    onSuccess: (response) => {
      const names = parseLLMNames(response.content);
      if (names.length > 0) {
        setSuggestions(names);
        if (!formData.name) {
          updateFormData({ name: names[0] });
        }
      }
    },
  });

  const handleGenerateName = async (random: boolean = false) => {
    clearError();

    const uniqueEntropy = {
      timestamp: Date.now(),
      randomId: Math.random().toString(36).substring(2, 10),
      sessionSeed: Math.floor(Math.random() * 1000000),
    };

    const context = {
      archetype: formData.role?.archetype || 'character',
      ageRange: formData.visual_identity?.age_range || 'adult',
      worldName: worldContext?.name || 'the world',
      worldGenre: worldContext?.genre?.join(', ') || 'fantasy',
      worldTimePeriod: worldContext?.timePeriod || 'medieval',
      entropy: uniqueEntropy,
    };

    const systemPrompt = random
      ? 'You are a creative character naming assistant. Generate UNIQUE, DIVERSE names that fit the character\'s world setting and cultural context.'
      : 'You are a creative character naming assistant. Generate names that fit the character\'s role, world setting, and cultural context.';

    const prompt = `Generate 3 UNIQUE and DIFFERENT character names for:
- Archetype: ${context.archetype}
- Age Range: ${context.ageRange}
- World: ${context.worldName}
- Genre: ${context.worldGenre}
- Time Period: ${context.worldTimePeriod}
- Entropy ID: ${uniqueEntropy.sessionSeed}

[EXISTING PROJECT PROTOCOLS / MEMORY]:
${useMemoryStore.getState().workingContext}

Format as a JSON array of strings: ["Name1", "Name2", "Name3"]`;

    await generate({
      prompt,
      systemPrompt,
      temperature: random ? 0.9 : 0.7,
      maxTokens: 200,
    });
  };

  const parseLLMNames = (response: string): string[] => {
    try {
      const jsonMatch = response.match(/\[[\s\S]*?\]/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        if (Array.isArray(parsed)) {
          return parsed.filter((name) => typeof name === 'string' && name.trim());
        }
      }
      return response.split('\n')
        .map(line => line.replace(/^\d+\.\s*/, '').replace(/["']/g, '').trim())
        .filter(name => name.length > 0 && name.length < 50)
        .slice(0, 3);
    } catch (error) {
      console.error('Failed to parse LLM response:', error);
    }
    return [];
  };

  return (
    <WizardFormLayout
      title="Neural Signature"
      description="Establish the fundamental parameters of a new consciousness"
    >
      <ValidationErrorSummary errors={validationErrors} className="mb-6" />

      {/* AI Assistance Section */}
      <div className="space-y-4 mb-8 p-4 rounded-lg border border-primary/20 bg-primary/5 backdrop-blur-sm shadow-[inset_0_0_10px_rgba(var(--primary-rgb),0.05)]">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-primary neon-text uppercase tracking-widest text-[10px] font-mono mb-1">// Identity Synthesizer</h3>
            <p className="text-[10px] text-primary/60 uppercase tracking-wider">
              Access the collective unconscious for evocative designations
            </p>
          </div>
          <div className="flex gap-2">
            <Button
              onClick={() => handleGenerateName(false)}
              disabled={isLoading || llmChecking || !formData.role?.archetype || !llmConfigured}
              className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
              size="sm"
            >
              <Activity className="h-3.5 w-3.5" />
              <span className="text-[10px] font-black uppercase tracking-widest">Heuristic</span>
            </Button>
            <Button
              onClick={() => handleGenerateName(true)}
              disabled={isLoading || llmChecking || !formData.role?.archetype || !llmConfigured}
              className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
              size="sm"
            >
              <Sparkles className="h-3.5 w-3.5" />
              <span className="text-[10px] font-black uppercase tracking-widest">Entropy</span>
            </Button>
          </div>
        </div>

        {!llmChecking && !llmConfigured && (
          <ServiceWarning
            service="llm"
            variant="inline"
            onConfigure={() => setShowLLMSettings(true)}
            className="bg-red-500/10 border-red-500/20 text-red-400"
          />
        )}

        {isLoading && (
          <LLMLoadingState message="Extracting linguistic patterns..." />
        )}

        {llmError && (
          <LLMErrorDisplay
            error={llmError}
            onRetry={() => handleGenerateName(false)}
            onDismiss={clearError}
          />
        )}
      </div>

      <div className="space-y-10">
        {/* Core Identity Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 p-6 bg-primary/5 border border-primary/10 rounded-none relative overflow-hidden">
          {/* Background scanner line effect */}
          <div className="absolute inset-x-0 h-px bg-primary/20 top-0 animate-scan" />

          <FormField
            label="Identity Designation"
            name="name"
            required
            error={validationErrors.name?.[0]}
            helpText="The primary linguistic identifier for this entity"
          >
            <div className="relative group">
              <Fingerprint className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Input
                id="name"
                value={formData.name || ''}
                onChange={(e) => updateFormData({ name: e.target.value })}
                placeholder="e.g., K-749_VOX"
                className="pl-10"
              />
            </div>

            {suggestions.length > 0 && !isLoading && (
              <div className="flex flex-wrap gap-2 mt-3">
                {suggestions.map((name, index) => (
                  <button
                    key={index}
                    onClick={() => updateFormData({ name })}
                    className={cn(
                      "px-2 py-0.5 text-[9px] font-black uppercase tracking-[0.2em] border transition-all duration-300",
                      formData.name === name
                        ? "bg-primary text-primary-foreground border-primary shadow-[0_0_10px_rgba(var(--primary-rgb),0.5)]"
                        : "bg-primary/5 text-primary/60 border-primary/20 hover:bg-primary/10 hover:border-primary/40"
                    )}
                  >
                    {name}
                  </button>
                ))}
              </div>
            )}
          </FormField>

          <FormField
            label="Societal Archetype"
            name="archetype"
            required
            error={validationErrors.archetype?.[0]}
            helpText="The primary systemic role within the social grid"
          >
            <div className="relative group">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-primary/40 z-10" />
              <Select
                value={formData.role?.archetype || ''}
                onValueChange={(val) => updateFormData({ role: { ...formData.role, archetype: val } as Character['role'] })}
              >
                <SelectTrigger className="pl-10">
                  <SelectValue placeholder="Select archetype" />
                </SelectTrigger>
                <SelectContent className="bg-[#050b10] border-primary/30">
                  {CHARACTER_ARCHETYPES.map((arch) => (
                    <SelectItem key={arch} value={arch} className="focus:bg-primary/20 focus:text-primary">
                      <span className="uppercase tracking-widest text-[10px] font-black font-mono">{arch}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </FormField>
        </div>

        {/* Biological/Visual Matrix */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField
            label="Maturity Cycle"
            name="age_range"
            required
            error={validationErrors.age_range?.[0]}
            helpText="Chronological stage of the entity's current iteration"
          >
            <div className="relative group">
              <Clock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-primary/40 z-10" />
              <Select
                value={formData.visual_identity?.age_range || ''}
                onValueChange={(val) => updateFormData({ visual_identity: { ...formData.visual_identity, age_range: val } as Character['visual_identity'] })}
              >
                <SelectTrigger className="pl-10">
                  <SelectValue placeholder="Select cycle" />
                </SelectTrigger>
                <SelectContent className="bg-[#050b10] border-primary/30">
                  {AGE_RANGES.map((range) => (
                    <SelectItem key={range} value={range} className="focus:bg-primary/20 focus:text-primary">
                      <span className="uppercase tracking-widest text-[10px] font-black font-mono">{range}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </FormField>

          <FormField
            label="Gender Matrix"
            name="gender"
            required
            error={validationErrors.gender?.[0]}
            helpText="Internal and external identity alignment"
          >
            <Select
              value={GENDER_OPTIONS.includes(formData.visual_identity?.gender as any) ? formData.visual_identity?.gender || '' : formData.visual_identity?.gender ? 'Other' : ''}
              onValueChange={(val) => updateFormData({ visual_identity: { ...formData.visual_identity, gender: val } as Character['visual_identity'] })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select gender" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {GENDER_OPTIONS.map((option) => (
                  <SelectItem key={option} value={option} className="focus:bg-primary/20 focus:text-primary">
                    <span className="uppercase tracking-widest text-[10px] font-black font-mono">{option}</span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {formData.visual_identity?.gender && !['Male', 'Female', 'Non-binary'].includes(formData.visual_identity.gender) && (
              <Input
                value={formData.visual_identity.gender === 'Other' ? '' : formData.visual_identity.gender}
                onChange={(e) => updateFormData({ visual_identity: { ...formData.visual_identity, gender: e.target.value || 'Other' } as Character['visual_identity'] })}
                placeholder="SPECIFY_CUSTOM_MATRIX..."
                className="mt-3"
              />
            )}
          </FormField>
        </div>

        {/* Narrative Layers */}
        <div className="space-y-8">
          <FormField
            label="Causal Trajectory"
            name="narrative_function"
            helpText="Define the entity's primary influence on the causal timeline"
          >
            <Textarea
              value={formData.role?.narrative_function || ''}
              onChange={(e) => updateFormData({ role: { ...formData.role, narrative_function: e.target.value } as Character['role'] })}
              placeholder="Identify the strategic narrative purpose..."
              rows={3}
            />
          </FormField>

          <FormField
            label="Developmental Protocol"
            name="character_arc"
            helpText="The projected evolution of this entity's consciousness"
          >
            <Textarea
              value={formData.role?.character_arc || ''}
              onChange={(e) => updateFormData({ role: { ...formData.role, character_arc: e.target.value } as Character['role'] })}
              placeholder="Map the transformation of the neuro-matrix..."
              rows={3}
            />
          </FormField>
        </div>
      </div>
    </WizardFormLayout>
  );
}

