import React, { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Sparkles, X, History, Calendar, Briefcase, GraduationCap, Users, Flag, Terminal, Microscope, Activity } from 'lucide-react';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';
import { LLMErrorDisplay, LLMLoadingState } from '../LLMErrorDisplay';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import type { World } from '@/types/world';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 4: Chronological Data (Background)
// ============================================================================

interface Step4BackgroundProps {
  worldContext?: World;
  storyContext?: StoryContext;
}

export function Step4Background({ worldContext }: Step4BackgroundProps) {
  const { formData, updateFormData } = useWizard<Character>();
  const [newEvent, setNewEvent] = useState('');
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  // Check if LLM service is configured
  const { llmConfigured, llmChecking } = useServiceStatus();

  // LLM generation for background suggestions
  const {
    generate,
    isLoading,
    error: llmError,
    clearError,
  } = useLLMGeneration({
    onSuccess: (response) => {
      const background = parseLLMBackground(response.content);
      if (background) {
        updateFormData({
          background: {
            ...(formData.background || {}),
            ...background,
          } as Character['background'],
        });
      }
    },
  });

  const handleGenerateBackground = async () => {
    clearError();

    const context = {
      characterName: formData.name || 'the character',
      archetype: formData.role?.archetype || 'character',
      ageRange: formData.visual_identity?.age_range || 'adult',
      personality: formData.personality,
      worldGenre: worldContext?.genre?.join(', ') || 'fantasy',
      worldTone: worldContext?.tone?.join(', ') || 'dramatic',
      worldTimePeriod: worldContext?.timePeriod || 'medieval',
    };

    const systemPrompt = 'You are a character backstory specialist. Create detailed, believable backgrounds.';

    const prompt = `Generate a detailed background (Chronological Data) for an entity:
- Name: ${context.characterName}
- Archetype: ${context.archetype}
- Maturity: ${context.ageRange}
- Traits: ${context.personality?.traits?.join(', ') || 'unspecified'}
- Genre: ${context.worldGenre}
- Tone: ${context.worldTone}

Format as JSON with keys: origin (string), occupation (string), education (string), family (string), significant_events (array of strings), current_situation (string)`;

    await generate({
      prompt,
      systemPrompt,
      temperature: 0.8,
      maxTokens: 1200,
    });
  };

  const parseLLMBackground = (response: string): Partial<Character['background']> | null => {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const result: Partial<Character['background']> = {};
        if (parsed.origin) result.origin = parsed.origin;
        if (parsed.occupation) result.occupation = parsed.occupation;
        if (parsed.education) result.education = parsed.education;
        if (parsed.family) result.family = parsed.family;
        if (Array.isArray(parsed.significant_events) || Array.isArray(parsed.significantEvents)) {
          result.significant_events = parsed.significant_events || parsed.significantEvents;
        }
        if (parsed.current_situation || parsed.currentSituation) {
          result.current_situation = parsed.current_situation || parsed.currentSituation;
        }
        return result;
      }
    } catch (error) {
      console.error('Failed to parse LLM response:', error);
    }
    return null;
  };

  const handleAddEvent = () => {
    if (newEvent.trim()) {
      const events = formData.background?.significant_events || [];
      updateBackground({ significant_events: [...events, newEvent.trim()] });
      setNewEvent('');
    }
  };

  const handleRemoveEvent = (index: number) => {
    const events = formData.background?.significant_events || [];
    updateBackground({ significant_events: events.filter((_, i) => i !== index) });
  };

  const updateBackground = (updates: Partial<Character['background']>) => {
    updateFormData({
      background: {
        ...(formData.background || {}),
        ...updates,
      } as Character['background']
    });
  };

  return (
    <WizardFormLayout
      title="Chronological Data"
      description="Access and reconstruct the historical datasets and causal events of the entity"
    >
      {/* AI Assistance Section */}
      <div className="space-y-4 mb-8 p-4 rounded-lg border border-primary/20 bg-primary/5 backdrop-blur-sm shadow-[inset_0_0_10px_rgba(var(--primary-rgb),0.05)]">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-primary neon-text uppercase tracking-widest text-[10px] font-mono mb-1">// Timeline Synthesizer</h3>
            <p className="text-[10px] text-primary/60 uppercase tracking-wider">
              Reconstruct the entity's chronological trajectory from heuristic datasets
            </p>
          </div>
          <Button
            onClick={handleGenerateBackground}
            disabled={isLoading || llmChecking || !formData.personality?.traits?.length || !llmConfigured}
            className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
            size="sm"
          >
            <Microscope className="h-3.5 w-3.5" />
            <span className="text-[10px] font-black uppercase tracking-widest">Synthesize Timeline</span>
          </Button>
        </div>

        {!llmChecking && !llmConfigured && (
          <ServiceWarning
            service="llm"
            variant="inline"
            onConfigure={() => setShowLLMSettings(true)}
            className="bg-red-500/10 border-red-500/20 text-red-400"
          />
        )}

        {isLoading && (
          <LLMLoadingState message="Accessing chronological archives..." showProgress />
        )}

        {llmError && (
          <LLMErrorDisplay
            error={llmError}
            onRetry={handleGenerateBackground}
            onDismiss={clearError}
          />
        )}
      </div>

      <div className="space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Causal Inception (Origin)" name="origin">
            <div className="relative group">
              <History className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.origin || ''}
                onChange={(e) => updateBackground({ origin: e.target.value })}
                placeholder="Define the causal origins and developmental environments..."
                rows={4}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>

          <FormField label="Lineage Matrix (Family)" name="family">
            <div className="relative group">
              <Users className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.family || ''}
                onChange={(e) => updateBackground({ family: e.target.value })}
                placeholder="Map the interpersonal lineage and primary connections..."
                rows={4}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Functional Designation (Occupation)" name="occupation">
            <div className="relative group">
              <Briefcase className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.occupation || ''}
                onChange={(e) => updateBackground({ occupation: e.target.value })}
                placeholder="Specify functional roles and developed skillsets..."
                rows={3}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>

          <FormField label="Acquisition Profile (Education)" name="education">
            <div className="relative group">
              <GraduationCap className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.education || ''}
                onChange={(e) => updateBackground({ education: e.target.value })}
                placeholder="Reconstruct the knowledge acquisition trajectory..."
                rows={3}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>
        </div>

        {/* Critical Iterations (Significant Events) */}
        <div className="space-y-4 p-4 border border-primary/20 bg-primary/5">
          <div className="flex items-center gap-2 mb-2">
            <Activity className="h-4 w-4 text-primary" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Critical Iterations (Significant Events)</span>
          </div>

          <div className="flex gap-2">
            <Input
              value={newEvent}
              onChange={(e) => setNewEvent(e.target.value)}
              placeholder="Record critical event..."
              onKeyPress={(e) => e.key === 'Enter' && handleAddEvent()}
              className="bg-primary/5 border-primary/20"
            />
            <Button onClick={handleAddEvent} className="btn-neon bg-primary/20 text-primary border-primary/20 px-4">
              <span className="text-[10px] font-black uppercase tracking-widest">Inject Moment</span>
            </Button>
          </div>

          <div className="space-y-2">
            {formData.background?.significant_events?.map((event, index) => (
              <div key={index} className="flex items-start gap-3 p-3 border border-primary/10 bg-primary/5 group">
                <Terminal className="h-4 w-4 text-primary/40 mt-0.5" />
                <span className="flex-1 text-[11px] font-mono text-primary/80">{event}</span>
                <button
                  onClick={() => handleRemoveEvent(index)}
                  className="text-primary/20 hover:text-red-500 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ))}
            {(!formData.background?.significant_events || formData.background.significant_events.length === 0) && (
              <p className="text-[10px] text-primary/30 uppercase tracking-widest font-mono italic p-2 border border-dashed border-primary/10">No iterations recorded</p>
            )}
          </div>
        </div>

        <FormField label="Active Parameters (Current Situation)" name="current_situation">
          <div className="relative group">
            <Flag className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
            <Textarea
              value={formData.background?.current_situation || ''}
              onChange={(e) => updateBackground({ current_situation: e.target.value })}
              placeholder="Describe the active state and immediate contextual factors..."
              rows={4}
              className="pl-10 bg-primary/5 border-primary/20"
            />
          </div>
        </FormField>
      </div>
    </WizardFormLayout>
  );
}

import { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Plus, Trash2, AlertCircle, CheckCircle2, Share2, Users, Link2, GitCommit, Shield, Heart, Zap, ZapOff, Terminal, Activity } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { useCharacters } from '@/store';
import { cn } from '@/lib/utils';
import type { Character, CharacterRelationship } from '@/types/character';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 5: Social Linkages (Relationships)
// ============================================================================

interface Step5RelationshipsProps {
  storyContext?: StoryContext;
}

const RELATIONSHIP_TYPES = [
  'Genetic / Unit',
  'Allied Peer',
  'Symbiotic Partner',
  'Knowledge Node',
  'Processing Node',
  'Competitive Parallel',
  'Antagonistic Adversary',
  'Strategic Proxy',
  'Operational Associate',
  'Casual Node',
  'Other / Custom',
];

const RELATIONSHIP_DYNAMICS = [
  'Augmenting',
  'Subtractive',
  'Non-Linear',
  'High-Latency',
  'Low-Latency',
  'Adaptive',
  'Fragmented',
  'Synchronized',
  'Sustained',
  'Autonomous',
];

export function Step5Relationships({ storyContext }: Step5RelationshipsProps = {}) {
  const { formData, updateFormData, validationErrors } = useWizard<Character>();
  const existingCharacters = useCharacters();

  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [currentRelationship, setCurrentRelationship] = useState<CharacterRelationship>({
    character_id: '',
    character_name: '',
    relationship_type: '',
    description: '',
    dynamic: '',
  });
  const [useExistingCharacter, setUseExistingCharacter] = useState<boolean>(true);
  const [validationError, setValidationError] = useState<string>('');

  const validateCharacterExists = (characterId: string): boolean => {
    if (!characterId) return false;
    return existingCharacters.some((char) => char.character_id === characterId);
  };

  const getCharacterNameById = (characterId: string): string => {
    const character = existingCharacters.find((char) => char.character_id === characterId);
    return character?.name || '';
  };

  const handleAddRelationship = () => {
    if (useExistingCharacter && !validateCharacterExists(currentRelationship.character_id)) {
      setValidationError('Entity archival lookup failed: Selection required');
      return;
    }

    if (!useExistingCharacter && !currentRelationship.character_name.trim()) {
      setValidationError('Entity designation failed: Identifier required');
      return;
    }

    if (!currentRelationship.relationship_type) {
      setValidationError('Linkage protocol failed: Type required');
      return;
    }

    setValidationError('');

    const relationshipData: CharacterRelationship = {
      ...currentRelationship,
      character_id: useExistingCharacter
        ? currentRelationship.character_id
        : crypto.randomUUID(),
      character_name: useExistingCharacter
        ? getCharacterNameById(currentRelationship.character_id)
        : currentRelationship.character_name,
    };

    if (editingIndex !== null) {
      const relationships = [...(formData.relationships || [])];
      relationships[editingIndex] = relationshipData;
      updateFormData({ relationships });
      setEditingIndex(null);
    } else {
      const relationships = formData.relationships || [];
      updateFormData({
        relationships: [...relationships, relationshipData],
      });
    }

    setCurrentRelationship({
      character_id: '',
      character_name: '',
      relationship_type: '',
      description: '',
      dynamic: '',
    });
    setUseExistingCharacter(existingCharacters.length > 0);
  };

  const handleEditRelationship = (index: number) => {
    const relationship = formData.relationships?.[index];
    if (relationship) {
      setCurrentRelationship(relationship);
      setEditingIndex(index);
      const isExisting = validateCharacterExists(relationship.character_id);
      setUseExistingCharacter(isExisting);
      setValidationError('');
    }
  };

  const handleDeleteRelationship = (index: number) => {
    const relationships = formData.relationships || [];
    updateFormData({
      relationships: relationships.filter((_, i) => i !== index),
    });
  };

  const handleCancelEdit = () => {
    setEditingIndex(null);
    setCurrentRelationship({
      character_id: '',
      character_name: '',
      relationship_type: '',
      description: '',
      dynamic: '',
    });
    setUseExistingCharacter(existingCharacters.length > 0);
    setValidationError('');
  };

  const isFormValid = () => {
    if (useExistingCharacter) {
      return (
        currentRelationship.character_id !== '' &&
        currentRelationship.relationship_type !== '' &&
        validateCharacterExists(currentRelationship.character_id)
      );
    } else {
      return (
        currentRelationship.character_name.trim() !== '' &&
        currentRelationship.relationship_type !== ''
      );
    }
  };

  const isRelationshipValid = (relationship: CharacterRelationship): boolean => {
    return validateCharacterExists(relationship.character_id);
  };

  return (
    <WizardFormLayout
      title="SocialGrid Nexus"
      description="Initialize interpersonal linkages and map social proximity within the network"
    >
      <div className="space-y-10">
        {/* Connection Setup */}
        <div className="p-6 border border-primary/20 bg-primary/5 backdrop-blur-sm relative">
          <div className="absolute -top-3 left-6 bg-[#050b10] px-3 py-0.5 border border-primary/20">
            <span className="text-[10px] font-black text-primary neon-text uppercase tracking-widest font-mono">
              {editingIndex !== null ? '// Linkage Modification' : '// Linkage Initialization'}
            </span>
          </div>

          <div className="space-y-6 mt-2">
            {/* Source Selection */}
            {existingCharacters.length > 0 && (
              <div className="space-y-3">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 font-mono italic">Select Entity Source:</span>
                <div className="flex gap-6">
                  <label className="flex items-center gap-3 cursor-pointer group">
                    <div className={cn(
                      "w-4 h-4 border flex items-center justify-center transition-all",
                      useExistingCharacter ? "border-primary bg-primary/20 shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]" : "border-primary/20 hover:border-primary/50"
                    )}>
                      {useExistingCharacter && <div className="w-1.5 h-1.5 bg-primary pulse-neon" />}
                      <input type="radio" checked={useExistingCharacter} onChange={() => { setUseExistingCharacter(true); setValidationError(''); }} className="hidden" />
                    </div>
                    <span className={cn("text-[11px] font-mono uppercase tracking-wider transition-colors", useExistingCharacter ? "text-primary" : "text-primary/40 group-hover:text-primary/60")}>Archive Entity</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer group">
                    <div className={cn(
                      "w-4 h-4 border flex items-center justify-center transition-all",
                      !useExistingCharacter ? "border-primary bg-primary/20 shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]" : "border-primary/20 hover:border-primary/50"
                    )}>
                      {!useExistingCharacter && <div className="w-1.5 h-1.5 bg-primary pulse-neon" />}
                      <input type="radio" checked={!useExistingCharacter} onChange={() => { setUseExistingCharacter(false); setValidationError(''); }} className="hidden" />
                    </div>
                    <span className={cn("text-[11px] font-mono uppercase tracking-wider transition-colors", !useExistingCharacter ? "text-primary" : "text-primary/40 group-hover:text-primary/60")}>Unregistered Entity</span>
                  </label>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {useExistingCharacter && existingCharacters.length > 0 ? (
                <FormField label="Target Archive Entity" name="character_id">
                  <Select
                    value={currentRelationship.character_id}
                    onValueChange={(value) => {
                      setCurrentRelationship({
                        ...currentRelationship,
                        character_id: value,
                        character_name: getCharacterNameById(value),
                      });
                      setValidationError('');
                    }}
                  >
                    <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                      <SelectValue placeholder="Accessing archives..." />
                    </SelectTrigger>
                    <SelectContent className="bg-[#050b10] border-primary/30">
                      {existingCharacters
                        .filter((char) => char.character_id !== formData.character_id)
                        .map((character) => (
                          <SelectItem key={character.character_id} value={character.character_id} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                            {character.name} {character.role?.archetype && `[${character.role.archetype}]`}
                          </SelectItem>
                        ))
                      }
                    </SelectContent>
                  </Select>
                </FormField>
              ) : (
                <FormField label="Entity Designation" name="character_name">
                  <Input
                    value={currentRelationship.character_name}
                    onChange={(e) => { setCurrentRelationship({ ...currentRelationship, character_name: e.target.value }); setValidationError(''); }}
                    placeholder="Input identifier..."
                    className="bg-primary/5 border-primary/20 font-mono text-[10px]"
                  />
                </FormField>
              )}

              <FormField label="Linkage Protocol (Type)" name="relationship_type">
                <Select
                  value={currentRelationship.relationship_type}
                  onValueChange={(value) => setCurrentRelationship({ ...currentRelationship, relationship_type: value })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                    <SelectValue placeholder="Protocol defined..." />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {RELATIONSHIP_TYPES.map((type) => (
                      <SelectItem key={type} value={type} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                        {type}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </FormField>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <FormField label="Iterative Dynamic" name="dynamic">
                <Select
                  value={currentRelationship.dynamic}
                  onValueChange={(value) => setCurrentRelationship({ ...currentRelationship, dynamic: value })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                    <SelectValue placeholder="Dynamic state..." />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {RELATIONSHIP_DYNAMICS.map((dynamic) => (
                      <SelectItem key={dynamic} value={dynamic} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                        {dynamic}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </FormField>

              <FormField label="Operational History" name="description">
                <Textarea
                  value={currentRelationship.description}
                  onChange={(e) => setCurrentRelationship({ ...currentRelationship, description: e.target.value })}
                  placeholder="Detail the causal history of this linkage..."
                  rows={3}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
              </FormField>
            </div>

            {validationError && (
              <div className="p-2 border border-red-500/30 bg-red-500/5 flex items-center gap-2">
                <AlertCircle className="w-3.5 h-3.5 text-red-500" />
                <span className="text-[10px] text-red-400 font-mono uppercase tracking-tighter">{validationError}</span>
              </div>
            )}

            <div className="flex gap-3">
              <Button
                onClick={handleAddRelationship}
                disabled={!isFormValid()}
                className="flex-1 btn-neon bg-primary/20 text-primary border-primary/20"
              >
                <Plus className="w-4 h-4 mr-2" />
                <span className="text-[10px] font-black uppercase tracking-widest">
                  {editingIndex !== null ? 'Modify Linkage' : 'Initialize Linkage'}
                </span>
              </Button>
              {editingIndex !== null && (
                <Button onClick={handleCancelEdit} variant="outline" className="border-primary/20 text-primary/60 hover:text-primary">
                  <span className="text-[10px] font-black uppercase tracking-widest">Abort</span>
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Linkage Archives */}
        <div className="space-y-4">
          <div className="flex items-center gap-2 text-primary/60">
            <Terminal className="h-4 w-4" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em]">Active Linkage Archives</span>
          </div>

          {formData.relationships && formData.relationships.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {formData.relationships.map((rel, index) => {
                const isValid = isRelationshipValid(rel);
                return (
                  <div key={index} className={cn(
                    "p-4 border bg-primary/5 relative group transition-all",
                    isValid ? "border-primary/10 hover:border-primary/30" : "border-yellow-500/30 bg-yellow-500/5 hover:border-yellow-500/50"
                  )}>
                    <div className="flex justify-between items-start mb-2">
                      <div className="space-y-1">
                        <div className="flex items-center gap-2">
                          <span className="text-[11px] font-black uppercase text-primary tracking-wider">{rel.character_name}</span>
                          {isValid ? <CheckCircle2 className="w-3 h-3 text-green-500" /> : <AlertCircle className="w-3 h-3 text-yellow-500" />}
                        </div>
                        <div className="flex flex-wrap gap-2">
                          <span className="text-[9px] font-mono px-1.5 py-0.5 border border-primary/20 bg-primary/10 text-primary/80 uppercase tracking-tighter">{rel.relationship_type}</span>
                          {rel.dynamic && <span className="text-[9px] font-mono px-1.5 py-0.5 border border-primary/20 bg-primary/10 text-primary/60 uppercase tracking-tighter">{rel.dynamic}</span>}
                        </div>
                      </div>
                      <div className="flex gap-1">
                        <Button onClick={() => handleEditRelationship(index)} variant="ghost" size="icon" className="h-7 w-7 text-primary/40 hover:text-primary hover:bg-primary/10">
                          <Activity className="h-3.5 w-3.5" />
                        </Button>
                        <Button onClick={() => handleDeleteRelationship(index)} variant="ghost" size="icon" className="h-7 w-7 text-primary/20 hover:text-red-500 hover:bg-red-500/10">
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </div>
                    {rel.description && (
                      <p className="text-[10px] font-mono text-primary/60 italic line-clamp-2 mt-2 pt-2 border-t border-primary/5">
                        "{rel.description}"
                      </p>
                    )}
                    {!isValid && (
                      <div className="mt-2 text-[9px] text-yellow-600 font-mono uppercase tracking-tighter opacity-70">
                        [!] archival target unregistered [!]
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="p-8 border border-dashed border-primary/10 flex flex-col items-center justify-center opacity-40">
              <Share2 className="h-8 w-8 text-primary/20 mb-3" />
              <p className="text-[10px] font-mono uppercase tracking-widest text-primary/60">No linkages initialized</p>
            </div>
          )}
        </div>
      </div>
    </WizardFormLayout>
  );
}

// ============================================================================
// Character Creation Flow Integration Tests
// ============================================================================
// Tests the complete character creation workflow from step 1 to final save

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, waitFor, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { CharacterWizard } from '../CharacterWizard';
import type { Character } from '@/types/character';

// Mock the store
const mockAddCharacter = vi.fn();
const mockUpdateCharacter = vi.fn();
const mockCharacters: Character[] = [];

vi.mock('@/store', () => ({
  useStore: vi.fn((selector) => {
    const mockState = {
      characters: mockCharacters,
      addCharacter: mockAddCharacter,
      updateCharacter: mockUpdateCharacter,
      deleteCharacter: vi.fn(),
      getAllCharacters: vi.fn(() => mockCharacters),
    };
    return selector ? selector(mockState) : mockState;
  }),
  useCharacters: vi.fn(() => mockCharacters),
}));

// Mock hooks
vi.mock('@/hooks/useCharacterPersistence', () => ({
  useCharacterPersistence: vi.fn(() => ({
    saveCharacter: vi.fn().mockResolvedValue({
      character_id: 'test-uuid',
      name: 'Test Hero',
      creation_method: 'wizard',
    }),
    isSaving: false,
    error: null,
  })),
}));

vi.mock('@/hooks/useServiceStatus', () => ({
  useServiceStatus: vi.fn(() => ({
    ollama: { available: true, status: 'running' },
    comfyui: { available: true, status: 'running' },
  })),
}));

// Mock fetch for API calls
global.fetch = vi.fn();

describe('Character Creation Flow Integration', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
    
    // Reset mock implementations
    mockAddCharacter.mockClear();
    mockUpdateCharacter.mockClear();
    
    (global.fetch as any).mockReset();
  });

  afterEach(() => {
    cleanup();
  });

  describe('Complete Character Creation Workflow', () => {
    it('creates character from step 1 to final save', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      // Mock successful API response
      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          character_id: 'test-uuid',
          name: 'Test Hero',
          creation_method: 'wizard',
        }),
      });

      render(
        <CharacterWizard
          onComplete={onComplete}
          onCancel={vi.fn()}
        />
      );

      // Step 1: Basic Identity
      await user.type(screen.getByLabelText(/character name/i), 'Test Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Navigate to step 2
      await user.click(screen.getByRole('button', { name: /next/i }));

      // Step 2: Physical Appearance
      await waitFor(() => {
        expect(screen.getByText(/physical appearance/i)).toBeInTheDocument();
      });

      // Fill some physical traits
      const hairColorSelect = screen.getByRole('combobox', { name: /hair color/i });
      if (hairColorSelect) {
        await user.click(hairColorSelect);
        await user.click(screen.getByText('Brown'));
      }

      // Navigate to step 3
      await user.click(screen.getByRole('button', { name: /next/i }));

      // Step 3: Personality
      await waitFor(() => {
        expect(screen.getByText(/personality/i)).toBeInTheDocument();
      });

      // Navigate to step 4
      await user.click(screen.getByRole('button', { name: /next/i }));

      // Step 4: Background
      await waitFor(() => {
        expect(screen.getByText(/background/i)).toBeInTheDocument();
      });

      // Navigate to step 5
      await user.click(screen.getByRole('button', { name: /next/i }));

      // Step 5: Relationships
      await waitFor(() => {
        expect(screen.getByText(/relationships/i)).toBeInTheDocument();
      });

      // Skip relationships (no relationships added)
      await user.click(screen.getByRole('button', { name: /next/i }));

      // Step 6: Review
      await waitFor(() => {
        expect(screen.getByText(/review your character/i)).toBeInTheDocument();
      });

      // Verify character summary is shown
      expect(screen.getByText(/test hero/i)).toBeInTheDocument();
      expect(screen.getByText(/protagonist/i)).toBeInTheDocument();

      // Finalize character
      await user.click(screen.getByRole('button', { name: /create character/i }));

      // Verify completion
      await waitFor(() => {
        expect(onComplete).toHaveBeenCalled();
      });

      const createdCharacter = onComplete.mock.calls[0][0];
      expect(createdCharacter.name).toBe('Test Hero');
      expect(createdCharacter.role.archetype).toBe('Protagonist');
    });

    it('persists data through all steps of the flow', async () => {
      const user = userEvent.setup();

      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          character_id: 'test-uuid',
          name: 'Persistent Hero',
        }),
      });

      render(
        <CharacterWizard
          onComplete={vi.fn()}
          onCancel={vi.fn()}
        />
      );

      // Fill step 1 with data
      await user.type(screen.getByLabelText(/character name/i), 'Persistent Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Antagonist'));

      // Navigate through all steps
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
      }

      // Navigate back to step 1
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /previous/i }));
      }

      // Verify data persisted
      await waitFor(() => {
        expect(screen.getByLabelText(/character name/i)).toHaveValue('Persistent Hero');
      });
    });
  });

  describe('Error Handling and Recovery', () => {
    it('handles API failure gracefully', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      // Mock API failure
      (global.fetch as any).mockRejectedValueOnce(new Error('Network Error'));

      // Mock successful fallback
      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          character_id: 'local-uuid',
          name: 'Fallback Hero',
        }),
      });

      render(
        <CharacterWizard
          onComplete={onComplete}
          onCancel={vi.fn()}
        />
      );

      // Fill required fields
      await user.type(screen.getByLabelText(/character name/i), 'Fallback Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Navigate to final step
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
      }

      // Finalize
      await user.click(screen.getByRole('button', { name: /create character/i }));

      // Should still complete despite API failure
      await waitFor(() => {
        expect(onComplete).toHaveBeenCalled();
      });
    });

    it('validates required fields before allowing navigation', async () => {
      const user = userEvent.setup();

      render(
        <CharacterWizard
          onComplete={vi.fn()}
          onCancel={vi.fn()}
        />
      );

      // Try to navigate without required fields
      const nextButton = screen.getByRole('button', { name: /next/i });
      expect(nextButton).toBeDisabled();

      // Fill only name, still need archetype
      await user.type(screen.getByLabelText(/character name/i), 'Test Hero');
      expect(nextButton).toBeDisabled();

      // Fill archetype too
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      // Still need age
      expect(nextButton).toBeDisabled();

      // Fill age
      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Now should be enabled
      expect(nextButton).toBeEnabled();
    });

    it('shows error message on save failure', async () => {
      const user = userEvent.setup();

      // Mock persistent API failure
      (global.fetch as any).mockRejectedValue(new Error('Save Failed'));

      render(
        <CharacterWizard
          onComplete={vi.fn()}
          onCancel={vi.fn()}
        />
      );

      // Fill required fields
      await user.type(screen.getByLabelText(/character name/i), 'Test Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Navigate to final step
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
      }

      // Finalize
      await user.click(screen.getByRole('button', { name: /create character/i }));

      // Should show error message
      await waitFor(() => {
        expect(screen.getByText(/error saving character/i)).toBeInTheDocument();
      });
    });
  });

  describe('Edge Cases in the Flow', () => {
    it('handles empty optional fields gracefully', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          character_id: 'test-uuid',
          name: 'Minimal Hero',
          role: { archetype: 'Protagonist' },
        }),
      });

      render(
        <CharacterWizard
          onComplete={onComplete}
          onCancel={vi.fn()}
        />
      );

      // Fill only required fields
      await user.type(screen.getByLabelText(/character name/i), 'Minimal Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Navigate through all steps without filling optional fields
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
      }

      await user.click(screen.getByRole('button', { name: /create character/i }));

      await waitFor(() => {
        expect(onComplete).toHaveBeenCalled();
      });
    });

    it('handles rapid navigation between steps', async () => {
      const user = userEvent.setup();

      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({ character_id: 'test-uuid', name: 'Rapid Hero' }),
      });

      render(
        <CharacterWizard
          onComplete={vi.fn()}
          onCancel={vi.fn()}
        />
      );

      // Fill required fields
      await user.type(screen.getByLabelText(/character name/i), 'Rapid Hero');
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Rapidly navigate through steps
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
        await user.click(screen.getByRole('button', { name: /previous/i }));
      }

      // Should still be on step 1
      expect(screen.getByLabelText(/character name/i)).toBeInTheDocument();
    });

    it('handles special characters in character name', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      (global.fetch as any).mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          character_id: 'test-uuid',
          name: "O'Brien-Smith Jr. 'The Great'",
        }),
      });

      render(
        <CharacterWizard
          onComplete={onComplete}
          onCancel={vi.fn()}
        />
      );

      // Fill name with special characters
      await user.type(screen.getByLabelText(/character name/i), "O'Brien-Smith Jr. 'The Great'");
      
      const archetypeSelect = screen.getByRole('combobox', { name: /character archetype/i });
      await user.click(archetypeSelect);
      await user.click(screen.getByText('Protagonist'));

      const ageSelect = screen.getByRole('combobox', { name: /age range/i });
      await user.click(ageSelect);
      await user.click(screen.getByText('Adult (25-50)'));

      // Navigate to final step
      for (let i = 0; i < 5; i++) {
        await user.click(screen.getByRole('button', { name: /next/i }));
      }

      await user.click(screen.getByRole('button', { name: /create character/i }));

      await waitFor(() => {
        expect(onComplete).toHaveBeenCalled();
        const character = onComplete.mock.calls[0][0];
        expect(character.name).toBe("O'Brien-Smith Jr. 'The Great'");
      });
    });

    it('handles all archetype options', async () => {
      const user = userEvent.setup();

      const archetypes = ['Protagonist', 'Antagonist', 'Mentor', 'Sidekick', 'Love Interest', 'Supporting'];

      for (const archetype of archetypes) {
        cleanup();
        vi.clearAllMocks();
        localStorage.clear();
        
