import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, waitFor, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Step5Relationships } from '../Step5Relationships';
import { WizardProvider } from '@/contexts/WizardContext';
import type { Character } from '@/types/character';
import { createEmptyCharacter } from '@/types/character';

// Mock the store
vi.mock('@/store', () => ({
  useStore: vi.fn(),
  useCharacters: vi.fn(),
}));

import { useCharacters } from '@/store';

describe('Step5Relationships - Character Relationship Validation', () => {
  const mockNextStep = vi.fn();
  const mockPreviousStep = vi.fn();
  const mockUpdateFormData = vi.fn();

  const mockCharacter: Partial<Character> = {
    ...createEmptyCharacter(),
    character_id: 'char-1',
    name: 'Test Character',
  };

  const existingCharacters: Character[] = [
    {
      ...createEmptyCharacter(),
      character_id: 'char-2',
      name: 'Alice',
      role: {
        archetype: 'Protagonist',
        narrative_function: 'Hero',
        character_arc: 'Growth',
      },
    } as Character,
    {
      ...createEmptyCharacter(),
      character_id: 'char-3',
      name: 'Bob',
      role: {
        archetype: 'Mentor',
        narrative_function: 'Guide',
        character_arc: 'Flat',
      },
    } as Character,
  ];

  beforeEach(() => {
    vi.clearAllMocks();
    // Mock useCharacters to return existing characters
    vi.mocked(useCharacters).mockReturnValue(existingCharacters);
  });

  const renderComponent = (formData: Partial<Character> = mockCharacter) => {
    return render(
      <WizardProvider
        initialData={formData}
        onComplete={vi.fn()}
        storageKey="test-character-wizard"
      >
        <Step5Relationships />
      </WizardProvider>
    );
  };

  it('displays existing characters count when characters exist', () => {
    renderComponent();
    
    expect(screen.getByText(/You have 2 existing characters in your project/i)).toBeInTheDocument();
  });

  it('shows character selection dropdown for existing characters', () => {
    renderComponent();
    
    expect(screen.getByText('Character Source')).toBeInTheDocument();
    expect(screen.getByLabelText('Existing Character')).toBeChecked();
    expect(screen.getByText('Select Character')).toBeInTheDocument();
  });

  it('allows switching between existing and new character modes', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Initially in existing character mode
    expect(screen.getByLabelText('Existing Character')).toBeChecked();
    expect(screen.getByText('Select Character')).toBeInTheDocument();
    
    // Switch to new character mode
    await user.click(screen.getByLabelText('New Character'));
    
    expect(screen.getByLabelText('New Character')).toBeChecked();
    expect(screen.getByLabelText('Character Name')).toBeInTheDocument();
  });

  it('validates that selected character exists when adding relationship', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Try to add without selecting a character
    const addButton = screen.getByRole('button', { name: /Add Relationship/i });
    expect(addButton).toBeDisabled();
  });

  it('displays existing characters in dropdown excluding current character', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Open the select dropdown
    const selectTrigger = screen.getByRole('combobox', { name: /Select Character/i });
    await user.click(selectTrigger);
    
    // Should show Alice and Bob
    await waitFor(() => {
      expect(screen.getByText('Alice')).toBeInTheDocument();
      expect(screen.getByText('Bob')).toBeInTheDocument();
    });
  });

  it('shows validation status for relationships with existing characters', () => {
    const characterWithRelationships: Partial<Character> = {
      ...mockCharacter,
      relationships: [
        {
          character_id: 'char-2', // Alice - exists
          character_name: 'Alice',
          relationship_type: 'Friend',
          description: 'Best friends',
          dynamic: 'Supportive',
        },
        {
          character_id: 'char-999', // Doesn't exist
          character_name: 'Unknown',
          relationship_type: 'Enemy',
          description: 'Rival',
          dynamic: 'Antagonistic',
        },
      ],
    };

    renderComponent(characterWithRelationships);
    
    // Should show both relationships
    expect(screen.getByText('Alice')).toBeInTheDocument();
    expect(screen.getByText('Unknown')).toBeInTheDocument();
    
    // Should show warning for non-existent character
    expect(screen.getByText(/This character doesn't exist yet/i)).toBeInTheDocument();
  });

  it('allows adding relationship with new character name', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Switch to new character mode
    await user.click(screen.getByLabelText('New Character'));
    
    // Fill in character name
    const nameInput = screen.getByLabelText('Character Name');
    await user.type(nameInput, 'Charlie');
    
    // Select relationship type
    const typeSelect = screen.getByRole('combobox', { name: /Relationship Type/i });
    await user.click(typeSelect);
    await user.click(screen.getByText('Friend'));
    
    // Add button should be enabled
    const addButton = screen.getByRole('button', { name: /Add Relationship/i });
    expect(addButton).toBeEnabled();
  });

  it('displays relationship type options', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Switch to new character mode for easier testing
    await user.click(screen.getByLabelText('New Character'));
    await user.type(screen.getByLabelText('Character Name'), 'Test');
    
    // Open relationship type dropdown
    const typeSelect = screen.getByRole('combobox', { name: /Relationship Type/i });
    await user.click(typeSelect);
    
    // Check for relationship types
    await waitFor(() => {
      expect(screen.getByText('Family')).toBeInTheDocument();
      expect(screen.getByText('Friend')).toBeInTheDocument();
      expect(screen.getByText('Romantic Partner')).toBeInTheDocument();
      expect(screen.getByText('Mentor')).toBeInTheDocument();
      expect(screen.getByText('Rival')).toBeInTheDocument();
      expect(screen.getByText('Enemy')).toBeInTheDocument();
    });
  });

  it('displays relationship dynamic options', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Switch to new character mode
    await user.click(screen.getByLabelText('New Character'));
    await user.type(screen.getByLabelText('Character Name'), 'Test');
    
    // Open dynamic dropdown
    const dynamicSelect = screen.getByRole('combobox', { name: /Relationship Dynamic/i });
    await user.click(dynamicSelect);
    
    // Check for dynamic options
    await waitFor(() => {
      expect(screen.getByText('Supportive')).toBeInTheDocument();
      expect(screen.getByText('Antagonistic')).toBeInTheDocument();
      expect(screen.getByText('Complicated')).toBeInTheDocument();
      expect(screen.getByText('Close')).toBeInTheDocument();
    });
  });

  it('shows validation error when trying to add without required fields', async () => {
    const user = userEvent.setup();
    renderComponent();
    
    // Switch to new character mode
    await user.click(screen.getByLabelText('New Character'));
    
    // Try to add without filling required fields
    const addButton = screen.getByRole('button', { name: /Add Relationship/i });
    expect(addButton).toBeDisabled();
  });

  it('allows editing existing relationships', async () => {
    const user = userEvent.setup();
    const characterWithRelationships: Partial<Character> = {
      ...mockCharacter,
      relationships: [
        {
          character_id: 'char-2',
          character_name: 'Alice',
          relationship_type: 'Friend',
          description: 'Best friends',
          dynamic: 'Supportive',
        },
      ],
    };

    renderComponent(characterWithRelationships);
    
    // Click edit button
    const editButton = screen.getByRole('button', { name: /Edit/i });
    await user.click(editButton);
    
    // Should show Update button instead of Add
    expect(screen.getByRole('button', { name: /Update Relationship/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Cancel/i })).toBeInTheDocument();
  });

  it('allows deleting relationships', async () => {
    const user = userEvent.setup();
    const characterWithRelationships: Partial<Character> = {
      ...mockCharacter,
      relationships: [
        {
          character_id: 'char-2',
          character_name: 'Alice',
          relationship_type: 'Friend',
          description: 'Best friends',
          dynamic: 'Supportive',
        },
      ],
    };

    renderComponent(characterWithRelationships);
    
    // Should show the relationship
    expect(screen.getByText('Alice')).toBeInTheDocument();
    
    // Delete button should be present
    const deleteButtons = screen.getAllByRole('button');
    const deleteButton = deleteButtons.find(btn => btn.querySelector('svg')); // Trash icon
    expect(deleteButton).toBeInTheDocument();
  });
});

/**
 * Character Wizard Form Component
 * 
 * Form fields for name, description, personality, visual attributes
 * Field validation with error messages
 * Form submission handler
 * 
 * Requirements: 3.1
 */

import React, { useState, useCallback } from 'react';
import { FormField, FormSection, FormGrid } from '../WizardFormLayout';
import './CharacterWizardForm.css';

export interface CharacterWizardInput {
  name: string;
  description: string;
  personality: string[];
  visualAttributes: {
    age: string;
    gender: string;
    appearance: string;
    clothing: string;
  };
}

export interface CharacterWizardFormProps {
  initialData?: Partial<CharacterWizardInput>;
  onSubmit: (data: CharacterWizardInput) => void;
  onCancel: () => void;
  onChange?: (data: Partial<CharacterWizardInput>) => void;
}

interface FormErrors {
  name?: string;
  description?: string;
  personality?: string;
  age?: string;
  gender?: string;
  appearance?: string;
  clothing?: string;
}

export function CharacterWizardForm({
  initialData,
  onSubmit,
  onCancel,
  onChange,
}: CharacterWizardFormProps) {
  const [formData, setFormData] = useState<CharacterWizardInput>({
    name: initialData?.name || '',
    description: initialData?.description || '',
    personality: initialData?.personality || [],
    visualAttributes: {
      age: initialData?.visualAttributes?.age || '',
      gender: initialData?.visualAttributes?.gender || '',
      appearance: initialData?.visualAttributes?.appearance || '',
      clothing: initialData?.visualAttributes?.clothing || '',
    },
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [personalityInput, setPersonalityInput] = useState('');

  const validateForm = useCallback((): boolean => {
    const newErrors: FormErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Character name is required';
    } else if (formData.name.length < 2) {
      newErrors.name = 'Name must be at least 2 characters';
    }

    if (!formData.description.trim()) {
      newErrors.description = 'Character description is required';
    } else if (formData.description.length < 10) {
      newErrors.description = 'Description must be at least 10 characters';
    }

    if (formData.personality.length === 0) {
      newErrors.personality = 'At least one personality trait is required';
    }

    if (!formData.visualAttributes.age.trim()) {
      newErrors.age = 'Age is required';
    }

    if (!formData.visualAttributes.gender.trim()) {
      newErrors.gender = 'Gender is required';
    }

    if (!formData.visualAttributes.appearance.trim()) {
      newErrors.appearance = 'Appearance description is required';
    } else if (formData.visualAttributes.appearance.length < 10) {
      newErrors.appearance = 'Appearance must be at least 10 characters';
    }

    if (!formData.visualAttributes.clothing.trim()) {
      newErrors.clothing = 'Clothing description is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [formData]);

  const handleFieldChange = useCallback((field: string, value: unknown) => {
    setFormData(prev => {
      const updated = { ...prev };
      
      if (field.startsWith('visualAttributes.')) {
        const attrField = field.split('.')[1];
        updated.visualAttributes = {
          ...prev.visualAttributes,
          [attrField]: value,
        };
      } else {
        (updated as any)[field] = value;
      }
      
      onChange?.(updated);
      return updated;
    });

    // Clear error for this field
    setErrors(prev => ({ ...prev, [field.split('.').pop()!]: undefined }));
  }, [onChange]);

  const handleAddPersonality = useCallback(() => {
    if (personalityInput.trim() && !formData.personality.includes(personalityInput.trim())) {
      handleFieldChange('personality', [...formData.personality, personalityInput.trim()]);
      setPersonalityInput('');
    }
  }, [personalityInput, formData.personality, handleFieldChange]);

  const handleRemovePersonality = useCallback((trait: string) => {
    handleFieldChange('personality', formData.personality.filter(t => t !== trait));
  }, [formData.personality, handleFieldChange]);

  const handleSubmit = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    
    if (validateForm()) {
      onSubmit(formData);
    }
  }, [formData, validateForm, onSubmit]);

  return (
    <form className="character-wizard-form" onSubmit={handleSubmit}>
      <FormSection title="Basic Information">
        <FormField
          name="name"
          label="Character Name"
          required
          error={errors.name}
        >
          <input
            type="text"
            value={formData.name}
            onChange={(e) => handleFieldChange('name', e.target.value)}
            placeholder="Enter character name"
            className={errors.name ? 'error' : ''}
          />
        </FormField>

        <FormField
          name="description"
          label="Description"
          required
          error={errors.description}
          helpText="Provide a brief overview of the character"
        >
          <textarea
            value={formData.description}
            onChange={(e) => handleFieldChange('description', e.target.value)}
            placeholder="Describe the character's role, background, and key traits"
            rows={4}
            className={errors.description ? 'error' : ''}
          />
        </FormField>
      </FormSection>

      <FormSection title="Personality Traits">
        <FormField
          name="personality"
          label="Personality"
          required
          error={errors.personality}
          helpText="Add personality traits that define this character"
        >
          <div className="personality-input-group">
            <input
              type="text"
              value={personalityInput}
              onChange={(e) => setPersonalityInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), handleAddPersonality())}
              placeholder="e.g., brave, curious, witty"
              className={errors.personality ? 'error' : ''}
            />
            <button
              type="button"
              onClick={handleAddPersonality}
              className="add-trait-button"
            >
              Add
            </button>
          </div>
          
          {formData.personality.length > 0 && (
            <div className="personality-tags">
              {formData.personality.map(trait => (
                <span key={trait} className="personality-tag">
                  {trait}
                  <button
                    type="button"
                    onClick={() => handleRemovePersonality(trait)}
                    className="remove-tag"
                    aria-label={`Remove ${trait}`}
                  >
                    ×
                  </button>
                </span>
              ))}
            </div>
          )}
        </FormField>
      </FormSection>

      <FormSection title="Visual Attributes">
        <FormGrid columns={2}>
          <FormField
            name="age"
            label="Age"
            required
            error={errors.age}
          >
            <input
              type="text"
              value={formData.visualAttributes.age}
              onChange={(e) => handleFieldChange('visualAttributes.age', e.target.value)}
              placeholder="e.g., 25, mid-30s, elderly"
              className={errors.age ? 'error' : ''}
            />
          </FormField>

          <FormField
            name="gender"
            label="Gender"
            required
            error={errors.gender}
          >
            <input
              type="text"
              value={formData.visualAttributes.gender}
              onChange={(e) => handleFieldChange('visualAttributes.gender', e.target.value)}
              placeholder="e.g., male, female, non-binary"
              className={errors.gender ? 'error' : ''}
            />
          </FormField>
        </FormGrid>

        <FormField
          name="appearance"
          label="Appearance"
          required
          error={errors.appearance}
          helpText="Describe physical features, build, hair, eyes, etc."
        >
          <textarea
            value={formData.visualAttributes.appearance}
            onChange={(e) => handleFieldChange('visualAttributes.appearance', e.target.value)}
            placeholder="Describe the character's physical appearance in detail"
            rows={3}
            className={errors.appearance ? 'error' : ''}
          />
        </FormField>

        <FormField
          name="clothing"
          label="Clothing"
          required
          error={errors.clothing}
          helpText="Describe typical attire and style"
        >
          <textarea
            value={formData.visualAttributes.clothing}
            onChange={(e) => handleFieldChange('visualAttributes.clothing', e.target.value)}
            placeholder="Describe the character's typical clothing and style"
            rows={3}
            className={errors.clothing ? 'error' : ''}
          />
        </FormField>
      </FormSection>
    </form>
  );
}

