import { useState, useEffect, useMemo, useRef } from 'react';
import { Play, Pause, ZoomIn, ZoomOut, Camera, Clock, AlertTriangle, Download, Eye, SkipBack, SkipForward } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Slider } from '@/components/ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { cn } from '@/lib/utils';
import { SequencePlan, Scene } from '@/types/sequencePlan';
import { ProductionShot, ShotType } from '@/types/shot';

interface Step5ShotPreviewProps {
  sequencePlan: Partial<SequencePlan>;
  onShotsChange: (shots: ProductionShot[]) => void;
}

// Extended shot interface for preview
interface PreviewShot extends Omit<ProductionShot, 'id' | 'sequencePlanId'> {
  id: string;
  sequencePlanId: string;
  description: string;
  estimatedDuration: number; // in frames
  videoUrl?: string; // URL to the generated video preview
}

// Camera angle presets for shot generation (Coherence Character LoRA ready)
const CAMERA_PRESETS: {
  type: ShotType;
  framing: string;
  angle: string;
  azimuth: number;
  elevation: number;
  distance: 'closeup' | 'medium' | 'wide';
  description: string
}[] = [
    { type: 'wide', framing: 'wide', angle: 'eye-level', azimuth: 0, elevation: 0, distance: 'wide', description: 'Establishing front shot' },
    { type: 'medium', framing: 'medium', angle: 'eye-level', azimuth: 30, elevation: 10, distance: 'medium', description: '3/4 angle conversation' },
    { type: 'close-up', framing: 'close-up', angle: 'eye-level', azimuth: 0, elevation: 0, distance: 'closeup', description: 'Character close-up' },
    { type: 'over-the-shoulder', framing: 'medium', angle: 'eye-level', azimuth: 150, elevation: 15, distance: 'medium', description: 'Over-the-shoulder POV' },
    { type: 'pov', framing: 'medium', angle: 'eye-level', azimuth: 0, elevation: 0, distance: 'medium', description: 'Subjective POV' },
  ];

function generateShotsFromScenes(scenes: Scene[], sequencePlanId: string, characters: any[] = []): PreviewShot[] {
  const shots: PreviewShot[] = [];
  let shotCounter = 1;

  scenes.forEach(scene => {
    const shotCount = Math.max(1, scene.estimatedShotCount);
    const defaultDuration = 120; // 5 seconds at 24fps

    // Generate shots based on beats + base shots
    const totalShots = Math.max(shotCount, scene.beats.length + 1);

    for (let i = 0; i < totalShots; i++) {
      const preset = CAMERA_PRESETS[i % CAMERA_PRESETS.length];

      // Get character names for prompt
      const sceneCharacters = characters.filter(c => scene.characterIds.includes(c.character_id));
      const charNames = sceneCharacters.map(c => c.name).join(', ');

      // Coherence Trigger: Add SKS for recognized characters (Requirement: CP1.0)
      const cohTrigger = sceneCharacters.length > 0 ? `SKS character ${charNames}` : 'a cinematic character';

      const shot: PreviewShot = {
        id: `shot-${scene.id}-${i + 1}`,
        sequencePlanId,
        sceneId: scene.id,
        number: shotCounter++,
        type: preset.type,
        category: i === 0 ? 'establishing' : i === totalShots - 1 ? 'reaction' : 'action',
        description: scene.beats[i] || `Shot ${i + 1} of scene ${scene.number}`,
        estimatedDuration: defaultDuration,
        videoUrl: undefined, // Clear mock URL to force placeholder instead of BigBuckBunny
        composition: {
          characterIds: scene.characterIds,
          characterPositions: [],
          environmentId: scene.locationId,
          props: [],
          lightingMood: 'cinematic',
          timeOfDay: 'dramatic',
        },
        camera: {
          framing: preset.framing as any,
          angle: preset.angle as any,
          azimuth: preset.azimuth,
          elevation: preset.elevation,
          distance: preset.distance,
          movement: { type: 'static' },
        },
        timing: {
          duration: defaultDuration,
          inPoint: 0,
          outPoint: defaultDuration,
          transition: 'cut',
          transitionDuration: 0,
        },
        generation: {
          aiProvider: 'flux_klein', // Default to the optimized model
          model: 'flux-v2-dev',
          prompt: `High quality cinematic shot, ${preset.description.toLowerCase()}, ${cohTrigger}, at location: ${scene.title}. Cinematic lighting, 8k resolution.`,
          negativePrompt: 'low quality, blurry, deformed, watermark',
          comfyuiPreset: 'cinematic_v2',
          parameters: {
            width: 1920,
            height: 1080,
            steps: 25,
            cfgScale: 7.5,
            sampler: 'dpmpp_2m',
            scheduler: 'karras',
          },
          styleReferences: [],
        },
        status: 'planned',
        notes: preset.description,
        tags: [`scene-${scene.number}`, preset.type, 'coherent'],
        templates: [],
      };

      shots.push(shot);
    }
  });

  return shots;
}

export function Step5ShotPreview({
  sequencePlan,
  onShotsChange,
}: Step5ShotPreviewProps) {
  const [generatedShots, setGeneratedShots] = useState<PreviewShot[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [zoom, setZoom] = useState(1);
  const [selectedShot, setSelectedShot] = useState<PreviewShot | null>(null);
  const [playbackSpeed, setPlaybackSpeed] = useState(1);
  const [viewerZoom, setViewerZoom] = useState(1);
  const timelineRef = useRef<HTMLDivElement>(null);

  const allCharacters = useStore(state => state.characters);

  // Generate shots when scenes change
  useEffect(() => {
    if (sequencePlan.scenes && sequencePlan.scenes.length > 0 && sequencePlan.id) {
      const shots = generateShotsFromScenes(sequencePlan.scenes, sequencePlan.id, allCharacters);
      setGeneratedShots(shots);
      onShotsChange(shots);
    }
  }, [sequencePlan.scenes, sequencePlan.id, onShotsChange, allCharacters]);

  // Calculate total duration
  const totalDuration = useMemo(() => {
    return generatedShots.reduce((total, shot) => total + shot.estimatedDuration, 0);
  }, [generatedShots]);

  // Calculate duration per act/scene
  const durationByAct = useMemo(() => {
    const durations: Record<string, number> = {};
    if (!sequencePlan.acts || !sequencePlan.scenes) return durations;

    sequencePlan.acts.forEach(act => {
      const actScenes = sequencePlan.scenes!.filter(scene => scene.actId === act.id);
      const actShots = generatedShots.filter(shot =>
        actScenes.some(scene => scene.id === shot.sceneId)
      );
      durations[act.id] = actShots.reduce((total, shot) => total + shot.estimatedDuration, 0);
    });
    return durations;
  }, [sequencePlan.acts, sequencePlan.scenes, generatedShots]);

  const formatDuration = (frames: number): string => {
    const fps = sequencePlan.frameRate || 24;
    const seconds = frames / fps;
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = Math.floor(seconds % 60);
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
  };

  const handleScrub = (time: number[]) => {
    setCurrentTime(time[0]);
  };

  const handleZoom = (direction: 'in' | 'out') => {
    setZoom(prev => Math.max(0.1, Math.min(5, prev + (direction === 'in' ? 0.1 : -0.1))));
  };

  const stepForward = () => {
    setCurrentTime(prev => Math.min(totalDuration, prev + 1));
  };

  const stepBackward = () => {
    setCurrentTime(prev => Math.max(0, prev - 1));
  };

  // Timeline simulation
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentTime(prev => {
          const next = prev + 1;
          if (next >= totalDuration) {
            setIsPlaying(false);
            return 0;
          }
          return next;
        });
      }, 1000 / ((sequencePlan.frameRate || 24) * playbackSpeed));
    }
    return () => clearInterval(interval);
  }, [isPlaying, totalDuration, sequencePlan.frameRate, playbackSpeed]);

  const validationErrors = useMemo(() => {
    const errors: string[] = [];
    if (generatedShots.length === 0) {
      errors.push("No shots generated. Please ensure scenes have been created in the previous step.");
    }
    return errors;
  }, [generatedShots]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-bold text-gray-900">Shot Preview</h2>
        <p className="text-gray-600">
          Preview your sequence timeline and visualize the shot breakdown.
        </p>
      </div>

      {/* Validation Errors */}
      {validationErrors.length > 0 && (
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription>
            {validationErrors.map((error, index) => (
              <div key={index}>{error}</div>
            ))}
          </AlertDescription>
        </Alert>
      )}

      {/* Summary Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-blue-50 p-4 rounded-lg">
          <div className="text-2xl font-bold text-blue-600">{generatedShots.length}</div>
          <div className="text-sm text-blue-600">Total Shots</div>
        </div>
        <div className="bg-green-50 p-4 rounded-lg">
          <div className="text-2xl font-bold text-green-600">{formatDuration(totalDuration)}</div>
          <div className="text-sm text-green-600">Total Duration</div>
        </div>
        <div className="bg-purple-50 p-4 rounded-lg">
          <div className="text-2xl font-bold text-purple-600">{sequencePlan.acts?.length || 0}</div>
          <div className="text-sm text-purple-600">Acts</div>
        </div>
        <div className="bg-orange-50 p-4 rounded-lg">
          <div className="text-2xl font-bold text-orange-600">{sequencePlan.scenes?.length || 0}</div>
          <div className="text-sm text-orange-600">Scenes</div>
        </div>
      </div>

      {/* Timeline Controls */}
      <div className="flex items-center justify-between bg-gray-50 p-4 rounded-lg">
        <div className="flex items-center gap-4">
          <Button
            variant="outline"
            size="sm"
            onClick={stepBackward}
            disabled={generatedShots.length === 0}
          >
            <SkipBack className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePlayPause}
            disabled={generatedShots.length === 0}
          >
            {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
            {isPlaying ? 'Pause' : 'Play'}
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={stepForward}
            disabled={generatedShots.length === 0}
          >
            <SkipForward className="h-4 w-4" />
          </Button>

          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={() => handleZoom('out')}>
              <ZoomOut className="h-4 w-4" />
            </Button>
            <span className="text-sm text-gray-600 min-w-[3rem]">{Math.round(zoom * 100)}%</span>
            <Button variant="ghost" size="sm" onClick={() => handleZoom('in')}>
              <ZoomIn className="h-4 w-4" />
            </Button>
          </div>

          <Select value={playbackSpeed.toString()} onValueChange={(value) => setPlaybackSpeed(parseFloat(value))}>
            <SelectTrigger className="w-20">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="z-[9999]">
              <SelectItem value="0.25">0.25x</SelectItem>
              <SelectItem value="0.5">0.5x</SelectItem>
              <SelectItem value="1">1x</SelectItem>
              <SelectItem value="1.5">1.5x</SelectItem>
              <SelectItem value="2">2x</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="flex items-center gap-4">
          <Button variant="outline" size="sm">
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
          <Button variant="outline" size="sm">
            <Eye className="h-4 w-4 mr-2" />
            Preview
          </Button>
        </div>
      </div>

      {/* Timeline Scrubber */}
      <div className="space-y-2">
        <div className="flex items-center justify-between text-sm text-gray-600">
          <span>Timeline</span>
          <span>{formatDuration(currentTime)} / {formatDuration(totalDuration)}</span>
        </div>
        <Slider
          value={[currentTime]}
          onValueChange={handleScrub}
          max={totalDuration}
          step={1}
          className="w-full"
        />
      </div>

      {/* Timeline Visualization */}
      <div
        ref={timelineRef}
        className="border rounded-lg bg-white overflow-x-auto"
        style={{ maxHeight: '600px' }}
      >
        <div className="p-4" style={{ width: `${Math.max(100, totalDuration * zoom)}px` }}>
          {/* Act/Scene/Shots Hierarchy */}
          {sequencePlan.acts?.map(act => (
            <div key={act.id} className="mb-8">
              {/* Act Header */}
              <div className="flex items-center gap-2 mb-4 p-2 bg-blue-50 rounded">
                <div className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center text-sm font-bold">
                  {act.number}
                </div>
                <div className="flex-1">
                  <h3 className="font-semibold text-gray-900">Act {act.number}: {act.title}</h3>
                  <div className="flex items-center gap-4 text-xs text-gray-600">
                    <span className="flex items-center gap-1">
                      <Clock className="h-3 w-3" />
                      {formatDuration(durationByAct[act.id] || 0)}
                    </span>
                  </div>
                </div>
              </div>

              {/* Scenes in this Act */}
              {sequencePlan.scenes?.filter(scene => scene.actId === act.id).map(scene => (
                <div key={scene.id} className="ml-4 mb-4">
                  {/* Scene Header */}
                  <div className="flex items-center gap-2 mb-2 p-2 bg-gray-50 rounded">
                    <div className="w-6 h-6 bg-gray-600 text-white rounded-full flex items-center justify-center text-xs">
                      {scene.number}
                    </div>
                    <div className="flex-1">
                      <h4 className="text-sm font-medium text-gray-900">{scene.title}</h4>
                      <div className="flex items-center gap-2 text-xs text-gray-500">
                        <span>{scene.estimatedShotCount} shots</span>
                      </div>
                    </div>
                  </div>

                  {/* Shots in this Scene */}
                  <div className="ml-6 flex gap-1">
                    {generatedShots.filter(shot => shot.sceneId === scene.id).map(shot => (
                      <div
                        key={shot.id}
                        className={cn(
                          'h-20 rounded cursor-pointer transition-all border-2 flex flex-col items-center justify-center text-xs font-medium min-w-[80px] overflow-hidden',
                          selectedShot?.id === shot.id
                            ? 'border-blue-500 bg-blue-100'
                            : 'border-gray-300 bg-gray-50 hover:bg-gray-100'
                        )}
                        style={{ width: `${Math.max(80, shot.estimatedDuration * zoom)}px` }}
                        onClick={() => setSelectedShot(shot)}
                        title={`${shot.type} - ${shot.description}`}
                      >
                        {shot.videoUrl ? (
                          <video
                            src={shot.videoUrl}
                            className="w-full h-12 object-cover rounded-t"
                            preload="metadata"
                            muted
                            loop
                          />
                        ) : (
                          <div className="w-full h-12 bg-gray-200 flex items-center justify-center rounded-t">
                            <Camera className="h-4 w-4 text-gray-500" />
                          </div>
                        )}
                        <div className="flex items-center gap-1 mt-1">
                          <span>{shot.number}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Selected Shot Details */}
      {selectedShot && (
        <div className="border rounded-lg p-4 bg-gray-50 space-y-4">
          <h3 className="font-semibold text-gray-900">Shot {selectedShot.number} Details</h3>

          {/* Video Viewer */}
          <div className="flex flex-col items-center space-y-2">
            <div className="relative overflow-hidden rounded-lg bg-black" style={{ width: '400px', height: '225px' }}>
              {selectedShot.videoUrl ? (
                <video
                  src={selectedShot.videoUrl}
                  className="w-full h-full object-contain"
                  controls
                  style={{ transform: `scale(${viewerZoom})`, transformOrigin: 'center' }}
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-white">
                  <Camera className="h-8 w-8" />
                  <span>No video available</span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-2">
              <Button variant="ghost" size="sm" onClick={() => setViewerZoom(prev => Math.max(1, prev - 0.25))}>
                <ZoomOut className="h-4 w-4" />
              </Button>
              <span className="text-sm text-gray-600 min-w-[3rem]">{Math.round(viewerZoom * 100)}%</span>
              <Button variant="ghost" size="sm" onClick={() => setViewerZoom(prev => Math.min(4, prev + 0.25))}>
                <ZoomIn className="h-4 w-4" />
              </Button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-medium text-gray-600">Type</label>
              <div className="flex items-center gap-2">
                <Badge variant="outline">{selectedShot.type}</Badge>
                <span className="text-sm text-gray-600">{selectedShot.category}</span>
              </div>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-600">Duration</label>
              <div className="text-sm">{formatDuration(selectedShot.estimatedDuration)}</div>
            </div>
            <div>
              <label className="text-sm font-medium text-gray-600">Camera Specs</label>
              <div className="text-sm">
                Framing: {selectedShot.camera.framing} <br />
                Angle: {selectedShot.camera.angle} <br />
                Azimuth: {selectedShot.camera.azimuth}° | Elev: {selectedShot.camera.elevation}°
              </div>
            </div>
          </div>
          <div className="mt-2">
            <label className="text-sm font-medium text-gray-600">Description</label>
            <div className="text-sm text-gray-700">{selectedShot.description}</div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ChevronDownIcon, ChevronUpIcon, EditIcon, DownloadIcon, CheckCircleIcon, AlertTriangleIcon, EyeIcon, Film } from 'lucide-react';
import { SequencePlan, Act, Scene } from '@/types/sequencePlan';
import { ProductionShot } from '@/types/shot';
import { SequenceTemplate } from '@/types/template';

interface Step6ReviewFinalizeProps {
  sequencePlan: Partial<SequencePlan>;
  selectedTemplate?: SequenceTemplate;
  onEditStep: (stepIndex: number) => void;
  onComplete: (engine: string) => void;
}

interface ValidationIssue {
  type: 'error' | 'warning';
  message: string;
  step: number;
  section: string;
}

export function Step6ReviewFinalize({
  sequencePlan,
  selectedTemplate,
  onEditStep,
  onComplete
}: Step6ReviewFinalizeProps) {
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['overview']));
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  const [selectedEngine, setSelectedEngine] = useState('comfyui');

  const AVAILABLE_ENGINES = [
    { id: 'comfyui', name: 'Standard (ComfyUI)', description: 'Local generation using stable diffusion / Wan', icon: '⚡' },
    { id: 'Grok Imagine', name: 'Grok Imagine (xAI)', description: 'Advanced AI image & video generation', icon: '👁️', premium: true },
    { id: 'Seedance 2.0', name: 'Seedance 2.0', description: 'Turbo cinematic video & 3D export', icon: '🌱', suggested: true, premium: true }
  ];

  // Validation logic
  const validationIssues = useMemo((): ValidationIssue[] => {
    const issues: ValidationIssue[] = [];

    // Check basic information
    if (!sequencePlan.name?.trim()) {
      issues.push({
        type: 'error',
        message: 'Sequence name is required',
        step: 2,
        section: 'Basic Information'
      });
    }
    if (!sequencePlan.worldId) {
      issues.push({
        type: 'error',
        message: 'World must be selected',
        step: 2,
        section: 'Basic Information'
      });
    }

    // Check narrative structure
    if (!sequencePlan.acts?.length) {
      issues.push({
        type: 'error',
        message: 'At least one act must be defined',
        step: 3,
        section: 'Narrative Structure'
      });
    }

    // Check scenes
    if (!sequencePlan.scenes?.length) {
      issues.push({
        type: 'warning',
        message: 'No scenes have been created yet',
        step: 4,
        section: 'Scene Planning'
      });
    }

    // Check scene completeness
    sequencePlan.scenes?.forEach((scene, index) => {
      if (!scene.title?.trim()) {
        issues.push({
          type: 'warning',
          message: `Scene ${scene.number} is missing a title`,
          step: 4,
          section: 'Scene Planning'
        });
      }
      if (!scene.locationId) {
        issues.push({
          type: 'warning',
          message: `Scene ${scene.number} has no location assigned`,
          step: 4,
          section: 'Scene Planning'
        });
      }
      if (!scene.characterIds?.length) {
        issues.push({
          type: 'warning',
          message: `Scene ${scene.number} has no characters assigned`,
          step: 4,
          section: 'Scene Planning'
        });
      }
    });

    // Check shots
    if (!sequencePlan.shots?.length) {
      issues.push({
        type: 'warning',
        message: 'No shots have been created yet',
        step: 5,
        section: 'Shot Preview'
      });
    }

    return issues;
  }, [sequencePlan]);

  const toggleSection = (section: string) => {
    setExpandedSections(prev => {
      const newSet = new Set(prev);
      if (newSet.has(section)) {
        newSet.delete(section);
      } else {
        newSet.add(section);
      }
      return newSet;
    });
  };

  const handleExport = (format: 'json' | 'project') => {
    if (format === 'json') {
      const dataStr = JSON.stringify(sequencePlan, null, 2);
      const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
      const exportFileDefaultName = `${sequencePlan.name || 'sequence-plan'}.json`;
      const linkElement = document.createElement('a');
      linkElement.setAttribute('href', dataUri);
      linkElement.setAttribute('download', exportFileDefaultName);
      linkElement.click();
    }
  };

  const renderValidationSummary = () => {
    if (validationIssues.length === 0) {
      return (
        <Alert className="border-green-200 bg-green-50/10 backdrop-blur-sm border-primary/30">
          <CheckCircleIcon className="h-4 w-4 text-primary neon-text" />
          <AlertDescription className="text-primary-foreground font-medium">
            Your multishot sequence is ready for production! All validation checks passed.
          </AlertDescription>
        </Alert>
      );
    }

    const errors = validationIssues.filter(i => i.type === 'error');
    const warnings = validationIssues.filter(i => i.type === 'warning');

    return (
      <Alert className={errors.length > 0 ? "border-red-200 bg-red-50" : "border-yellow-200 bg-yellow-50"}>
        {errors.length > 0 ? (
          <AlertTriangleIcon className="h-4 w-4 text-red-600" />
        ) : (
          <AlertTriangleIcon className="h-4 w-4 text-yellow-600" />
        )}
        <AlertDescription>
          {errors.length > 0 && (
            <div className="mb-2">
              <strong className="text-red-800">{errors.length} Error{errors.length !== 1 ? 's' : ''}:</strong>
              <ul className="mt-1 space-y-1">
                {errors.map((error, index) => (
                  <li key={index} className="text-red-700 text-sm">
                    • {error.message} (
                    <Button
                      variant="link"
                      className="h-auto p-0 text-red-700 underline"
                      onClick={() => onEditStep(error.step - 1)}
                    >
                      Edit Step {error.step}
                    </Button>
                    )
                  </li>
                ))}
              </ul>
            </div>
          )}
          {warnings.length > 0 && (
            <div>
              <strong className={errors.length > 0 ? "text-yellow-800" : "text-yellow-800"}>
                {warnings.length} Warning{warnings.length !== 1 ? 's' : ''}:
              </strong>
              <ul className="mt-1 space-y-1">
                {warnings.map((warning, index) => (
                  <li key={index} className="text-yellow-700 text-sm">
                    • {warning.message} (
                    <Button
                      variant="link"
                      className="h-auto p-0 text-yellow-700 underline"
                      onClick={() => onEditStep(warning.step - 1)}
                    >
                      Edit Step {warning.step}
                    </Button>
                    )
                  </li>
                ))}
              </ul>
            </div>
          )}
        </AlertDescription>
      </Alert>
    );
  };

  const renderOverviewSection = () => (
    <Card className="cursor-pointer">
      <CardHeader
        className="flex flex-row items-center justify-between space-y-0 pb-2"
        onClick={() => toggleSection('overview')}
      >
        <div>
          <CardTitle className="text-lg neon-text">Scene Editor Overview</CardTitle>
          <CardDescription>Basic information and technical specifications</CardDescription>
        </div>
        {expandedSections.has('overview') ? <ChevronUpIcon className="h-4 w-4" /> : <ChevronDownIcon className="h-4 w-4" />}
      </CardHeader>
      {expandedSections.has('overview') && (
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <h4 className="font-medium text-sm text-gray-600 uppercase tracking-wide">Basic Info</h4>
              <div className="mt-2 space-y-1">
                <p><strong>Name:</strong> {sequencePlan.name || 'Not set'}</p>
                <p><strong>Description:</strong> {sequencePlan.description || 'Not set'}</p>
                <p><strong>World:</strong> {sequencePlan.worldId || 'Not set'}</p>
                <p><strong>Template:</strong> {selectedTemplate?.name || 'Custom'}</p>
              </div>
            </div>
            <div>
              <h4 className="font-medium text-sm text-gray-600 uppercase tracking-wide">Technical Specs</h4>
              <div className="mt-2 space-y-1">
                <p><strong>Duration:</strong> {sequencePlan.targetDuration || 0} seconds</p>
                <p><strong>Frame Rate:</strong> {sequencePlan.frameRate || 24} fps</p>
                <p><strong>Resolution:</strong> {sequencePlan.resolution ? `${sequencePlan.resolution.width}x${sequencePlan.resolution.height}` : 'Not set'}</p>
              </div>
            </div>
          </div>
          <div className="flex justify-end mt-4">
            <Button variant="outline" size="sm" onClick={() => onEditStep(1)}>
              <EditIcon className="h-4 w-4 mr-2" />
              Edit Basic Info
            </Button>
          </div>
        </CardContent>
      )}
    </Card>
  );

  const renderActsSection = () => (
    <Card className="cursor-pointer">
      <CardHeader
        className="flex flex-row items-center justify-between space-y-0 pb-2"
        onClick={() => toggleSection('acts')}
      >
        <div>
          <CardTitle className="text-lg">Acts ({sequencePlan.acts?.length || 0})</CardTitle>
          <CardDescription>Narrative structure and act breakdown</CardDescription>
        </div>
        {expandedSections.has('acts') ? <ChevronUpIcon className="h-4 w-4" /> : <ChevronDownIcon className="h-4 w-4" />}
      </CardHeader>
      {expandedSections.has('acts') && (
        <CardContent>
          {sequencePlan.acts?.length ? (
            <div className="space-y-3">
              {sequencePlan.acts.map((act, index) => (
                <div key={act.id} className="border rounded-lg p-3">
                  <div className="flex items-center justify-between">
                    <h4 className="font-medium">Act {act.number}: {act.title}</h4>
                    <Badge variant="outline">{act.targetDuration}s</Badge>
                  </div>
                  <p className="text-sm text-gray-600 mt-1">{act.description}</p>
                  <p className="text-sm text-gray-500 mt-1"><strong>Purpose:</strong> {act.narrativePurpose}</p>
                  <p className="text-sm text-gray-500"><strong>Scenes:</strong> {act.sceneIds.length}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500">No acts defined yet.</p>
          )}
          <div className="flex justify-end mt-4">
            <Button variant="outline" size="sm" onClick={() => onEditStep(2)}>
              <EditIcon className="h-4 w-4 mr-2" />
              Edit Narrative Structure
            </Button>
          </div>
        </CardContent>
      )}
    </Card>
  );

  const renderScenesSection = () => (
    <Card className="cursor-pointer">
      <CardHeader
        className="flex flex-row items-center justify-between space-y-0 pb-2"
        onClick={() => toggleSection('scenes')}
      >
        <div>
          <CardTitle className="text-lg">Scenes ({sequencePlan.scenes?.length || 0})</CardTitle>
          <CardDescription>Location and character assignments</CardDescription>
        </div>
        {expandedSections.has('scenes') ? <ChevronUpIcon className="h-4 w-4" /> : <ChevronDownIcon className="h-4 w-4" />}
      </CardHeader>
      {expandedSections.has('scenes') && (
        <CardContent>
          {sequencePlan.scenes?.length ? (
            <div className="space-y-3">
              {sequencePlan.scenes.map((scene) => (
                <div key={scene.id} className="border rounded-lg p-3">
                  <div className="flex items-center justify-between">
                    <h4 className="font-medium">Scene {scene.number}: {scene.title}</h4>
                    <div className="flex gap-2">
                      <Badge variant="outline">Act {sequencePlan.acts?.find(a => a.id === scene.actId)?.number || '?'}</Badge>
                      <Badge variant="outline">{scene.estimatedShotCount} shots</Badge>
                    </div>
                  </div>
                  <p className="text-sm text-gray-600 mt-1">{scene.description}</p>
                  <div className="mt-2 space-y-1">
                    <p className="text-sm text-gray-500"><strong>Location:</strong> {scene.locationId || 'Not set'}</p>
                    <p className="text-sm text-gray-500"><strong>Characters:</strong> {scene.characterIds?.length || 0}</p>
                    <p className="text-sm text-gray-500"><strong>Beats:</strong> {scene.beats?.length || 0}</p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500">No scenes defined yet.</p>
          )}
          <div className="flex justify-end mt-4">
            <Button variant="outline" size="sm" onClick={() => onEditStep(3)}>
              <EditIcon className="h-4 w-4 mr-2" />
              Edit Scene Planning
            </Button>
          </div>
        </CardContent>
      )}
    </Card>
  );

  const renderEngineSelection = () => (
    <div className="space-y-6 py-6 bg-gradient-to-b from-transparent to-primary/5 rounded-2xl p-6 border border-primary/10">
      <div className="flex flex-col gap-1">
        <h4 className="font-bold text-xl flex items-center gap-3 neon-text">
          <Film className="w-6 h-6 text-primary animate-pulse" />
          Production Engine Selection
        </h4>
        <p className="text-sm text-muted-foreground ml-9">
          Choose the hardware and AI pipeline for high-fidelity rendering
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {AVAILABLE_ENGINES.map((engine) => (
          <div
            key={engine.id}
            onClick={() => setSelectedEngine(engine.id)}
            className={`cursor-pointer group relative p-6 rounded-2xl border-2 transition-all duration-500 transform hover:scale-[1.02] ${selectedEngine === engine.id
              ? 'border-primary bg-primary/20 shadow-[0_0_30px_rgba(var(--primary),0.4)] backdrop-blur-md'
              : 'border-white/5 bg-white/5 hover:border-white/20 hover:bg-white/10'
              }`}
          >
            <div className="flex flex-col h-full gap-4">
              <div className="flex items-center justify-between">
                <div className={`p-3 rounded-xl ${selectedEngine === engine.id ? 'bg-primary/20' : 'bg-white/5'} transition-colors duration-500`}>
                  <span className="text-3xl">{engine.icon}</span>
                </div>
                {selectedEngine === engine.id && (
                  <div className="bg-primary p-1 rounded-full shadow-[0_0_10px_rgba(var(--primary),0.8)]">
                    <CheckCircleIcon className="w-5 h-5 text-white" />
                  </div>
                )}
              </div>

              <div>
                <h5 className={`font-bold text-lg mb-1 transition-colors duration-500 ${selectedEngine === engine.id ? 'text-primary neon-text' : 'text-foreground'}`}>
                  {engine.name}
                </h5>
                <p className="text-sm text-muted-foreground leading-relaxed group-hover:text-muted-foreground/80 transition-colors">
                  {engine.description}
                </p>
              </div>

              <div className="mt-auto pt-2 flex flex-wrap gap-2">
                {selectedEngine === engine.id && (
                  <Badge className="bg-primary/30 text-primary border-primary/50 text-[10px] uppercase tracking-widest font-bold">
                    Optimized
                  </Badge>
                )}
                {(engine as any).premium && (
                  <Badge className="bg-amber-500/20 text-amber-500 border-amber-500/30 text-[10px] uppercase tracking-widest font-bold">
                    Premium
                  </Badge>
                )}
                {(engine as any).suggested && (
                  <Badge className="bg-emerald-500/20 text-emerald-500 border-emerald-500/30 text-[10px] uppercase tracking-widest font-bold">
                    Recommended
                  </Badge>
                )}
              </div>
            </div>

            {/* Glossy overlay effect */}
            {selectedEngine === engine.id && (
              <div className="absolute inset-0 rounded-2xl bg-gradient-to-tr from-primary/10 via-transparent to-white/5 pointer-events-none" />
            )}
          </div>
        ))}
      </div>
    </div>
  );

  const renderShotsSection = () => (
    <Card className="cursor-pointer">
      <CardHeader
        className="flex flex-row items-center justify-between space-y-0 pb-2"
        onClick={() => toggleSection('shots')}
      >
        <div>
          <CardTitle className="text-lg">Shots ({sequencePlan.shots?.length || 0})</CardTitle>
          <CardDescription>Timeline and shot breakdown</CardDescription>
        </div>
        {expandedSections.has('shots') ? <ChevronUpIcon className="h-4 w-4" /> : <ChevronDownIcon className="h-4 w-4" />}
      </CardHeader>
      {expandedSections.has('shots') && (
        <CardContent>
          {sequencePlan.shots?.length ? (
            <div className="space-y-3">
              {sequencePlan.shots.slice(0, 10).map((shot, index) => (
                <div key={shot.id || index} className="border rounded-lg p-3">
                  <div className="flex items-center justify-between">
                    <h4 className="font-medium">Shot {shot.number}: {shot.generation.prompt || 'No prompt'}</h4>
                    <Badge variant="outline">{shot.timing.duration} frames</Badge>
                  </div>
                  <p className="text-sm text-gray-600 mt-1">{shot.notes || 'No notes'}</p>
                  <p className="text-sm text-gray-500"><strong>Type:</strong> {shot.type} • <strong>Category:</strong> {shot.category}</p>
                </div>
              ))}
              {sequencePlan.shots.length > 10 && (
                <p className="text-sm text-gray-500">... and {sequencePlan.shots.length - 10} more shots</p>
              )}
            </div>
          ) : (
            <p className="text-gray-500">No shots defined yet.</p>
          )}
          <div className="flex justify-end mt-4">
            <Button variant="outline" size="sm" onClick={() => onEditStep(4)}>
              <EditIcon className="h-4 w-4 mr-2" />
              Edit Shot Preview
            </Button>
          </div>
        </CardContent>
      )}
    </Card>
  );

  const renderConfirmDialog = () => (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <Card className="w-full max-w-md mx-4">
        <CardHeader>
          <CardTitle>Confirm Completion</CardTitle>
          <CardDescription>
            Are you sure you want to finalize this sequence plan? This action cannot be undone.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex justify-end space-x-2">
            <Button variant="outline" onClick={() => setShowConfirmDialog(false)}>
              Back to Editor
            </Button>
            <Button onClick={() => {
              setShowConfirmDialog(false);
              onComplete(selectedEngine);
            }} className="bg-primary text-primary-foreground">
              Finalize Sequence
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );

  const hasErrors = validationIssues.some(i => i.type === 'error');

  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Review & Finalize</h2>
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => handleExport('json')}>
            <DownloadIcon className="h-4 w-4 mr-2" />
            Export JSON
          </Button>
          <Button variant="outline" disabled>
            <DownloadIcon className="h-4 w-4 mr-2" />
            Export Project
          </Button>
        </div>
      </div>

      {renderValidationSummary()}

      <div className="space-y-4">
        {renderOverviewSection()}
        <Separator className="bg-white/5" />
        {renderEngineSelection()}
        <Separator className="bg-white/5" />
        {renderActsSection()}
        {renderScenesSection()}
        {renderShotsSection()}
      </div>

      <Separator />

      <div className="flex justify-between items-center">
        <div className="text-sm text-gray-600">
          Ready to complete your sequence plan?
        </div>
        <Button
          onClick={() => setShowConfirmDialog(true)}
          disabled={hasErrors}
          className="px-6 btn-neon"
        >
          <CheckCircleIcon className="h-4 w-4 mr-2" />
          Export to Production
        </Button>
      </div>

      {showConfirmDialog && renderConfirmDialog()}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { ProductionWizardContainer } from '../production-wizards/ProductionWizardContainer';
import { WizardStep } from '@/types/wizard';
import { ShotWizardState } from '@/types/wizard';
import { ShotTemplate } from '@/types/template';
import { ProductionShot, ShotType } from '@/types/shot';
import { ShotTypeSelector } from './ShotTypeSelector';
import {
  CameraAngleSelector,
  CameraMovementSelector,
  LightingSelector,
  MoodSelector,
  TimeOfDaySelector,
  TransitionSelector,
} from '@/components/assets/AssetSelector';
import {
  Camera,
  Layers,
  Video,
  Clock,
  Settings,
  Eye,
  CheckCircle,
} from 'lucide-react';

// Services
import { templateManager } from '@/services/templateManager';
import { draftStorage } from '@/services/draftStorage';
import { aiShotCompositionService } from '@/services/aiShotCompositionService';
import { Button } from '@/components/ui/button';
import { Wand2, Loader2 } from 'lucide-react';

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Convert a ShotTemplate to a base ProductionShot
 */
function templateToBaseProductionShot(template: ShotTemplate): Partial<ProductionShot> {
  const config = template.configuration as Partial<ProductionShot>;
  return {
    ...config,
    notes: `New ${template.name}`,
    tags: template.tags,
  };
}

// ============================================================================
// Shot Wizard Steps Configuration
// ============================================================================

const SHOT_STEPS: WizardStep[] = [
  {
    number: 1,
    title: 'Type Selection',
    description: 'Choose shot type and apply template',
    icon: Camera,
  },
  {
    number: 2,
    title: 'Composition',
    description: 'Set up characters, environment, and framing',
    icon: Layers,
  },
  {
    number: 3,
    title: 'Camera Setup',
    description: 'Configure camera angle, movement, and framing',
    icon: Video,
  },
  {
    number: 4,
    title: 'Timing',
    description: 'Set duration, transitions, and timing',
    icon: Clock,
  },
  {
    number: 5,
    title: 'Generation Settings',
    description: 'Configure AI model, prompts, and parameters',
    icon: Settings,
  },
  {
    number: 6,
    title: 'Preview',
    description: 'Review configuration and generation estimates',
    icon: Eye,
  },
  {
    number: 7,
    title: 'Finalize',
    description: 'Save shot or generate immediately',
    icon: CheckCircle,
  },
];

// ============================================================================
// Shot Wizard Component
// ============================================================================

interface ShotWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onComplete: (shot: ProductionShot) => void;
  sequenceId?: string;
  sceneId?: string;
  shotNumber?: number;
  initialTemplateId?: string;
  existingShot?: ProductionShot;
  quickMode?: boolean;
}

export function ShotWizard({
  isOpen,
  onClose,
  onComplete,
  sequenceId,
  sceneId,
  shotNumber,
  initialTemplateId,
  existingShot,
  quickMode = false,
}: ShotWizardProps) {
  // ============================================================================
  // State Management
  // ============================================================================

  const [wizardState, setWizardState] = useState<ShotWizardState>(() => ({
    currentStep: 0,
    formData: existingShot ? { dialogues: [], ...existingShot } : { dialogues: [] },
    selectedTemplate: undefined,
    generatedPrompt: '',
    validationErrors: {},
    previewData: {
      thumbnailUrl: undefined,
      estimatedDuration: 0,
      estimatedCost: 0,
      qualityScore: 0,
    },
    isDirty: false,
    lastSaved: 0,
    quickMode,
  }));

  const [availableTemplates, setAvailableTemplates] = useState<ShotTemplate[]>([]);
  void availableTemplates; // Used in ShotTypeSelector step
  const [isLoading, setIsLoading] = useState(false);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // ============================================================================
  // AI Suggestion Handler
  // ============================================================================

  const handleAISuggest = async () => {
    const sceneDescription = wizardState.formData.notes || wizardState.formData.title || "Cinematic scene";
    
    try {
      setIsGeneratingAI(true);
      const suggestion = await aiShotCompositionService.generateConfigWithAI(sceneDescription);
      
      // Mapping AI suggestion to Wizard's ProductionShot format
      const framingMap: Record<string, string> = {
        'extreme_close_up': 'extreme-close-up',
        'close_up': 'close-up',
        'medium_close_up': 'close-up',
        'medium_shot': 'medium',
        'wide_shot': 'wide',
        'establishing': 'extreme-wide'
      };

      const angleMap: Record<string, string> = {
        'low_angle': 'low',
        'eye_level': 'eye-level',
        'high_angle': 'high',
        'dutch_angle': 'dutch'
      };

      const movementMap: Record<string, string> = {
        'static': 'static',
        'pan': 'pan',
        'tilt': 'tilt',
        'dolly': 'dolly',
        'tracking': 'tracking',
        'steadicam': 'handheld'
      };

      const updatedFormData = {
        ...wizardState.formData,
        type: framingMap[suggestion.shotType] as any || wizardState.formData.type,
        camera: {
          ...wizardState.formData.camera,
          framing: framingMap[suggestion.shotType] as any || wizardState.formData.camera?.framing,
          angle: angleMap[suggestion.cameraAngle] as any || wizardState.formData.camera?.angle,
          movement: {
            ...wizardState.formData.camera?.movement,
            type: movementMap[suggestion.cameraMovement] as any || 'static'
          }
        },
        composition: {
          ...wizardState.formData.composition,
          lightingMood: suggestion.lightingStyle,
        },
        notes: (wizardState.formData.notes || '') + (suggestion.reasoning ? `\n\nAI Reasoning: ${suggestion.reasoning}` : '')
      };

      setWizardState(prev => ({
        ...prev,
        formData: updatedFormData as any,
        isDirty: true
      }));

    } catch (err) {
      console.error('AI suggestion failed:', err);
    } finally {
      setIsGeneratingAI(false);
    }
  };

  // ============================================================================
  // Initialization Effects
  // ============================================================================

  const initializeWizard = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Load available templates
      const templates = await templateManager.getAllShotTemplates();
      setAvailableTemplates(templates);

      // Initialize state based on props
      const initialState: ShotWizardState = {
        currentStep: 0,
        formData: {
          dialogues: [],
        },
        selectedTemplate: undefined,
        generatedPrompt: '',
        validationErrors: {},
        previewData: {
          thumbnailUrl: undefined,
          estimatedDuration: 0,
          estimatedCost: 0,
          qualityScore: 0,
        },
        isDirty: false,
        lastSaved: 0,
        quickMode,
      };

      if (existingShot) {
        // Editing existing shot
        initialState.formData = { 
          dialogues: [],
          ...existingShot 
        };
        initialState.currentStep = 0; // Start at first step for review
      } else if (initialTemplateId) {
        // Starting with a template
        const template = templates.find(t => t.id === initialTemplateId);
        if (template) {
          initialState.selectedTemplate = template;
          initialState.formData = {
            dialogues: [],
            ...templateToBaseProductionShot(template)
          };
        }
      }

      // Set context information
      if (sequenceId) initialState.formData.sequencePlanId = sequenceId;
      if (sceneId) initialState.formData.sceneId = sceneId;
      if (shotNumber) initialState.formData.number = shotNumber;

      // Try to load draft if no existing shot
      if (!existingShot) {
        const draftMetas = await draftStorage.listDrafts('shot');
        if (draftMetas.length > 0) {
          // Load the most recent draft
          const mostRecentDraft = draftMetas[0];
          const draftData = await draftStorage.loadDraft<ProductionShot>('shot', mostRecentDraft.id);
          if (draftData) {
            initialState.formData = { 
              ...initialState.formData, 
              ...draftData 
            };
            // Note: DraftStorage doesn't currently store stepIndex, so we default to 0
          }
        }
      }

      setWizardState(initialState);
    } catch (err) {
      console.error('Failed to initialize shot wizard:', err);
      setError('Failed to initialize. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [existingShot, initialTemplateId, sequenceId, sceneId, shotNumber, quickMode]);

  useEffect(() => {
    if (isOpen) {
      initializeWizard();
    }
  }, [isOpen, initializeWizard]);

  // ============================================================================
  // Auto-save Effect
  // ============================================================================

  useEffect(() => {
    if (wizardState.isDirty && !existingShot) {
      const saveDraft = async () => {
        try {
          // Create a temporary full production shot for draft saving
          const draftShot: ProductionShot = {
            id: wizardState.formData.id || `draft-${Date.now()}`,
            sequencePlanId: wizardState.formData.sequencePlanId || '',
            sceneId: wizardState.formData.sceneId || '',
            number: wizardState.formData.number || 1,
            type: wizardState.formData.type || 'medium',
            category: wizardState.formData.category || 'establishing',
            composition: wizardState.formData.composition || {
              characterIds: [],
              characterPositions: [],
              environmentId: '',
              props: [],
              lightingMood: '',
              timeOfDay: '',
            },
            camera: wizardState.formData.camera || {
              framing: 'medium',
              angle: 'eye-level',
              movement: { type: 'static' },
            },
            timing: wizardState.formData.timing || {
              duration: 0,
              inPoint: 0,
              outPoint: 0,
              transition: 'cut',
              transitionDuration: 0,
            },
            generation: wizardState.formData.generation || {
              aiProvider: '',
              model: '',
              prompt: wizardState.generatedPrompt || '',
              negativePrompt: '',
              comfyuiPreset: '',
              parameters: {
                width: 1920,
                height: 1080,
                steps: 20,
                cfgScale: 7,
                sampler: 'euler',
                scheduler: 'normal',
              },
              styleReferences: [],
            },
            status: 'planned',
            thumbnailUrl: undefined,
            generatedAssetUrl: undefined,
            notes: '',
            tags: wizardState.formData.tags || [],
            templates: wizardState.formData.templates || [],
            dialogues: wizardState.formData.dialogues || [],
          };

          await draftStorage.saveDraft('shot', draftShot);
          setWizardState(prev => ({
            ...prev,
            lastSaved: Date.now(),
            isDirty: false,
          }));
        } catch (err) {
         console.error('Failed to auto-save draft:', err);
         
         // Create a detailed error message based on the error type
         let errorMessage = 'Failed to auto-save draft: ';
         if (err instanceof Error) {
           errorMessage += err.message;
           
           // Add specific guidance for common error types
           if (err.message.includes('permission') || err.message.includes('access')) {
             errorMessage += '\nPlease check your file system permissions.';
           } else if (err.message.includes('network') || err.message.includes('connection')) {
             errorMessage += '\nPlease check your network connection.';
           } else if (err.message.includes('quota') || err.message.includes('storage')) {
             errorMessage += '\nPlease check your available storage space.';
           }
         } else {
           errorMessage += 'Unknown error occurred.';
         }
         
         console.warn(errorMessage);
       }
      };

      const timer = setTimeout(saveDraft, 30000); // Auto-save every 30 seconds
      return () => clearTimeout(timer);
    }
  }, [wizardState.isDirty, wizardState.formData, wizardState.generatedPrompt, existingShot]);

  // ============================================================================
  // Navigation Handlers
  // ============================================================================

  const updateFormData = useCallback((updates: Partial<ProductionShot>) => {
    setWizardState(prev => ({
      ...prev,
      formData: { ...prev.formData, ...updates },
      isDirty: true,
    }));
  }, []);

  const updateGeneratedPrompt = useCallback((prompt: string) => {
    setWizardState(prev => ({
      ...prev,
      generatedPrompt: prompt,
      isDirty: true,
    }));
  }, []);

  const updatePreviewData = useCallback((data: Partial<ShotWizardState['previewData']>) => {
    setWizardState(prev => ({
      ...prev,
      previewData: { ...prev.previewData, ...data },
    }));
  }, []);
  void updatePreviewData; // Available for preview step

  const goToStep = useCallback((stepIndex: number) => {
    if (stepIndex >= 0 && stepIndex < SHOT_STEPS.length) {
      setWizardState(prev => ({
        ...prev,
        currentStep: stepIndex,
      }));
    }
  }, []);

  const nextStep = useCallback(() => {
    if (wizardState.currentStep < SHOT_STEPS.length - 1) {
      goToStep(wizardState.currentStep + 1);
    }
  }, [wizardState.currentStep, goToStep]);

  const previousStep = useCallback(() => {
    if (wizardState.currentStep > 0) {
      goToStep(wizardState.currentStep - 1);
    }
  }, [wizardState.currentStep, goToStep]);

  // ============================================================================
  // Quick Mode Logic
  // ============================================================================

  const getEffectiveSteps = useCallback(() => {
    if (!wizardState.quickMode) return SHOT_STEPS;

    // In quick mode, skip steps 4 (Timing) and 6 (Preview) as they are optional
    return SHOT_STEPS.filter(step => step.number !== 4 && step.number !== 6);
  }, [wizardState.quickMode]);

  const getActualStepIndex = useCallback((displayStep: number) => {
    const effectiveSteps = getEffectiveSteps();
    return effectiveSteps.findIndex(step => step.number === displayStep);
  }, [getEffectiveSteps]);
  void getActualStepIndex; // Used in quick mode navigation

  // ============================================================================
  // Completion Handler
  // ============================================================================

  const handleComplete = useCallback(async () => {
    try {
      setIsLoading(true);

      // Create final production shot
      const finalShot: ProductionShot = {
        id: wizardState.formData.id || `shot_${Date.now()}`,
        sequencePlanId: wizardState.formData.sequencePlanId || '',
        sceneId: wizardState.formData.sceneId || '',
        number: wizardState.formData.number || 1,
        type: wizardState.formData.type || 'medium',
        category: wizardState.formData.category || 'establishing',
        composition: wizardState.formData.composition || {
          characterIds: [],
          characterPositions: [],
          environmentId: '',
          props: [],
          lightingMood: '',
          timeOfDay: '',
        },
        camera: wizardState.formData.camera || {
          framing: 'medium',
          angle: 'eye-level',
          movement: { type: 'static' },
        },
        timing: wizardState.formData.timing || {
          duration: 0,
          inPoint: 0,
          outPoint: 0,
          transition: 'cut',
          transitionDuration: 0,
        },
        generation: {
          ...wizardState.formData.generation,
          prompt: wizardState.generatedPrompt || wizardState.formData.generation?.prompt || '',
        } as any,
        dialogues: wizardState.formData.dialogues || [],
        status: 'planned',
        thumbnailUrl: undefined,
        generatedAssetUrl: undefined,
        notes: '',
        tags: wizardState.formData.tags || [],
        templates: wizardState.formData.templates || [],
      };

      // Clear any draft
      if (!existingShot) {
        await draftStorage.clearAllDrafts('shot');
      }

      onComplete(finalShot);
      onClose();
    } catch (err) {
     console.error('Failed to complete shot:', err);
     
     // Create a detailed error message based on the error type
     let errorMessage = 'Failed to complete shot: ';
     if (err instanceof Error) {
       errorMessage += err.message;
       
       // Add specific guidance for common error types
       if (err.message.includes('validation') || err.message.includes('Validation')) {
         errorMessage += '\nPlease verify all shot data is valid.';
       } else if (err.message.includes('network') || err.message.includes('connection')) {
         errorMessage += '\nPlease check your network connection.';
       } else if (err.message.includes('permission') || err.message.includes('access')) {
         errorMessage += '\nPlease check your file system permissions.';
       }
     } else {
       errorMessage += 'Unknown error occurred.';
     }
     
     setError(errorMessage);
   } finally {
     setIsLoading(false);
   }
  }, [wizardState, existingShot, onComplete, onClose]);

  // ============================================================================
  // Cancel Handler with Confirmation
  // ============================================================================

  const handleCancel = useCallback(() => {
    if (wizardState.isDirty) {
      // Show confirmation dialog (would be implemented with a proper dialog)
      const confirmed = window.confirm(
        'You have unsaved changes. Are you sure you want to cancel?'
      );
      if (!confirmed) return;
    }

    // Clear draft if cancelling
    if (!existingShot) {
      draftStorage.clearAllDrafts('shot').catch(console.error);
    }

    onClose();
  }, [wizardState.isDirty, existingShot, onClose]);

  // ============================================================================
  // Context Header Component
  // ============================================================================

  const ContextHeader = () => {
    const contextSequenceId = sequenceId || wizardState.formData.sequencePlanId;
    const contextSceneId = sceneId || wizardState.formData.sceneId;
    const contextShotNumber = shotNumber || wizardState.formData.number;

    if (!contextSequenceId && !contextSceneId && !contextShotNumber) return null;

    return (
      <div className="bg-blue-50 border-b px-6 py-3">
        <div className="text-sm text-blue-800">
          <span className="font-medium">Context:</span>
          {contextSequenceId && <span className="ml-2">Sequence {contextSequenceId}</span>}
          {contextSceneId && <span className="ml-2">• Scene {contextSceneId}</span>}
          {contextShotNumber && <span className="ml-2">• Shot {contextShotNumber}</span>}
          {wizardState.quickMode && (
            <span className="ml-2 px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-medium">
              Quick Mode
            </span>
          )}
        </div>
      </div>
    );
  };

  // ============================================================================
  // Validation Logic
  // ============================================================================

  const canProceedFromCurrentStep = useCallback(() => {
    const currentStepNumber = getEffectiveSteps()[wizardState.currentStep].number;

    switch (currentStepNumber) {
      case 1: // Type Selection
        return !!wizardState.formData.type;
      
      case 2: // Composition
        // Add validation for composition if needed
        return true;
      
      case 3: // Camera Setup
        // Add validation for camera if needed
        return true;
      
      case 4: // Timing
        // Add validation for timing if needed
        return true;
      
      case 5: // Generation Settings
        // Add validation for generation settings if needed
        return true;
      
      case 6: // Preview
        return true;
      
      case 7: // Finalize
        return true;
      
      default:
        return true;
    }
  }, [wizardState.currentStep, wizardState.formData, getEffectiveSteps]);

  // ============================================================================
  // Step Content Renderer (Shell - placeholders for now)
  // ============================================================================

  const renderStepContent = () => {
    const currentStepNumber = getEffectiveSteps()[wizardState.currentStep].number;

    switch (currentStepNumber) {
      case 1:
        return (
          <ShotTypeSelector
            selectedType={wizardState.formData.type}
            onSelect={(type: ShotType) => {
              updateFormData({ type });
            }}
          />
        );

      case 2:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Composition Setup</h3>
            <div className="flex justify-between items-center mb-6">
              <p className="text-sm text-gray-600">
                Configure the visual composition and atmosphere of your shot
              </p>
              <Button 
                onClick={handleAISuggest} 
                disabled={isGeneratingAI}
                variant="outline"
                size="sm"
                className="flex items-center gap-2"
              >
                {isGeneratingAI ? <Loader2 className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />}
                AI Suggest
              </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <LightingSelector
                selectedAssetId={wizardState.formData.composition?.lightingMood}
                onSelect={(asset) => {
                  updateFormData({
                    composition: {
                      ...wizardState.formData.composition,
                      lightingMood: asset.id,
                    } as any,
                  });
                }}
              />

              <TimeOfDaySelector
                selectedAssetId={wizardState.formData.composition?.timeOfDay}
                onSelect={(asset) => {
                  updateFormData({
                    composition: {
                      ...wizardState.formData.composition,
                      timeOfDay: asset.id,
                    } as any,
                  });
                }}
              />

              <MoodSelector
                selectedAssetId={wizardState.formData.composition?.lightingMood}
                onSelect={(asset) => {
                  updateFormData({
                    composition: {
                      ...wizardState.formData.composition,
                      lightingMood: asset.id,
                    } as any,
                  });
                }}
                className="md:col-span-2"
              />
            </div>

            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
              <p className="text-sm text-blue-800 dark:text-blue-200">
                💡 <strong>Tip:</strong> These settings will influence the AI generation prompt
                to create the desired atmosphere and lighting conditions.
              </p>
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Camera Setup</h3>
            <p className="text-sm text-gray-600 mb-6">
              Define how the camera will capture this shot
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <CameraAngleSelector
                selectedAssetId={wizardState.formData.camera?.angle}
                onSelect={(asset) => {
                  updateFormData({
                    camera: {
                      ...wizardState.formData.camera,
                      angle: asset.id as any,
                    } as any,
                  });
                }}
              />

              <CameraMovementSelector
                selectedAssetId={wizardState.formData.camera?.movement?.type}
                onSelect={(asset) => {
                  updateFormData({
                    camera: {
                      ...wizardState.formData.camera,
                      movement: {
                        type: asset.id as any,
                      },
                    } as any,
                  });
                }}
              />
            </div>

            <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
              <p className="text-sm text-blue-800 dark:text-blue-200">
                💡 <strong>Tip:</strong> Camera angle and movement greatly affect the emotional
                impact and storytelling of your shot.
              </p>
            </div>
          </div>
        );

      case 4:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Timing & Transitions</h3>
            <p className="text-sm text-gray-600 mb-6">
              Set the duration and transition style for this shot
            </p>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Duration (seconds)
                </label>
                <input
                  type="number"
                  min="1"
                  max="60"
                  value={wizardState.formData.timing?.duration || 5}
                  onChange={(e) => {
                    updateFormData({
                      timing: {
                        ...wizardState.formData.timing,
                        duration: parseInt(e.target.value) || 5,
                      } as any,
                    });
                  }}
                  className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-800 dark:border-gray-700"
                  aria-label="Duration in seconds"
                  placeholder="Enter duration"
                />
              </div>

              <TransitionSelector
                selectedAssetId={wizardState.formData.timing?.transition}
                onSelect={(asset) => {
                  updateFormData({
                    timing: {
                      ...wizardState.formData.timing,
                      transition: asset.id as any,
                    } as any,
                  });
                }}
              />
            </div>
          </div>
        );

      case 5:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Generation Settings</h3>
            <p className="text-sm text-gray-600 mb-6">
              Configure AI generation parameters
            </p>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Custom Prompt (Optional)
                </label>
                <textarea
                  rows={4}
                  value={wizardState.generatedPrompt}
                  onChange={(e) => updateGeneratedPrompt(e.target.value)}
                  placeholder="Add custom prompt details or leave empty to use template-based generation..."
                  className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-800 dark:border-gray-700"
                />
              </div>

              <div className="p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                <h4 className="text-sm font-medium mb-2">Auto-Generated Prompt Preview</h4>
                <p className="text-xs text-gray-600 dark:text-gray-400">
                  Based on your selections, the following prompt will be generated:
                </p>
                <div className="mt-2 p-3 bg-white dark:bg-gray-900 rounded border text-xs font-mono">
                  {wizardState.formData.type || '[shot type]'},{' '}
                  {wizardState.formData.camera?.angle || '[camera angle]'},{' '}
                  {wizardState.formData.composition?.lightingMood || '[lighting]'},{' '}
                  {wizardState.formData.composition?.timeOfDay || '[time of day]'}
                </div>
              </div>
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Preview & Review</h3>
            <p className="text-sm text-gray-600 mb-6">
              Review your shot configuration before finalizing
            </p>

            <div className="space-y-4">
              <div className="p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                <h4 className="text-sm font-medium mb-3">Shot Configuration</h4>
                <dl className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Type:</dt>
                    <dd className="font-medium">{wizardState.formData.type || 'Not set'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Camera Angle:</dt>
                    <dd className="font-medium">{wizardState.formData.camera?.angle || 'Not set'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Camera Movement:</dt>
                    <dd className="font-medium">{wizardState.formData.camera?.movement?.type || 'Not set'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Lighting:</dt>
                    <dd className="font-medium">{wizardState.formData.composition?.lightingMood || 'Not set'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Time of Day:</dt>
                    <dd className="font-medium">{wizardState.formData.composition?.timeOfDay || 'Not set'}</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Duration:</dt>
                    <dd className="font-medium">{wizardState.formData.timing?.duration || 5}s</dd>
                  </div>
                  <div className="flex justify-between">
                    <dt className="text-gray-600 dark:text-gray-400">Transition:</dt>
                    <dd className="font-medium">{wizardState.formData.timing?.transition || 'Not set'}</dd>
                  </div>
                </dl>
              </div>
            </div>
          </div>
        );

      case 7:
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold mb-4">Finalize Shot</h3>
            <p className="text-sm text-gray-600 mb-6">
              Your shot is ready to be saved or generated
            </p>

            <div className="p-6 bg-green-50 dark:bg-green-900/20 rounded-lg border border-green-200 dark:border-green-800">
              <div className="flex items-center gap-3 mb-4">
                <svg className="w-8 h-8 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                </svg>
                <div>
                  <h4 className="font-semibold text-green-900 dark:text-green-100">
                    Shot Configuration Complete
                  </h4>
                  <p className="text-sm text-green-700 dark:text-green-300">
                    All required settings have been configured
                  </p>
                </div>
              </div>

              <div className="flex gap-3">
                <button
                  onClick={handleComplete}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  Save Shot
                </button>
                <button
                  onClick={handleComplete}
                  className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
                >
                  Save & Generate
                </button>
              </div>
            </div>
          </div>
        );

      default:
        return <div>Unknown step</div>;
    }
  };

  // ============================================================================
  // Render
  // ============================================================================

  const effectiveSteps = getEffectiveSteps();

  return (
    <Dialog open={isOpen} onOpenChange={handleCancel}>
      <DialogContent className="max-w-6xl h-[90vh] flex flex-col p-0">
        <DialogHeader className="px-6 pt-6 pb-4 border-b">
          <DialogTitle>Create Shot</DialogTitle>
        </DialogHeader>

        {/* Context Header */}
        <ContextHeader />

        <div className="flex-1 min-h-0 overflow-hidden">
          <ProductionWizardContainer
            title="Shot Wizard"
            steps={effectiveSteps}
            currentStep={wizardState.currentStep}
            onNextStep={nextStep}
            onPreviousStep={previousStep}
            onGoToStep={goToStep}
            onCancel={handleCancel}
            onComplete={wizardState.currentStep === effectiveSteps.length - 1 ? handleComplete : nextStep}
            allowJumpToStep={false} // Can be enabled later if needed
            showAutoSaveIndicator={!existingShot}
            canProceed={canProceedFromCurrentStep()}
            isDirty={wizardState.isDirty}
            lastSaved={wizardState.lastSaved}
            className="h-full"
          >
            {isLoading ? (
              <div className="flex items-center justify-center h-64">
                <div className="text-center">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
                  <p className="text-gray-600">Loading...</p>
                </div>
              </div>
            ) : error ? (
              <div className="flex items-center justify-center h-64">
                <div className="text-center text-red-600">
                  <p className="mb-4">{error}</p>
                  <button
                    onClick={initializeWizard}
                    className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                  >
                    Retry
                  </button>
                </div>
              </div>
            ) : (
              renderStepContent()
            )}
          </ProductionWizardContainer>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Step 7: Scene Breakdown (Découpage)
 * Allows users to break down their story into individual scenes with metadata
 */

import { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, GripVertical, Clock, MapPin, Users, AlertTriangle, Film } from 'lucide-react';
import { WizardFormLayout, FormField, FormSection, FormGrid } from '../WizardFormLayout';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItemWithDescription,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select-rich';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import type {
  SceneBreakdown,
  Location,
  CharacterProfile,
  ProjectTypeData,
} from '@/types/wizard';

// ============================================================================
// Time of Day Options
// ============================================================================

const TIME_OF_DAY_OPTIONS: {
  value: SceneBreakdown['timeOfDay'];
  label: string;
  icon: string;
}[] = [
  { value: 'dawn', label: 'Dawn', icon: '🌅' },
  { value: 'morning', label: 'Morning', icon: '🌄' },
  { value: 'afternoon', label: 'Afternoon', icon: '☀️' },
  { value: 'evening', label: 'Evening', icon: '🌆' },
  { value: 'night', label: 'Night', icon: '🌙' },
  { value: 'unspecified', label: 'Unspecified', icon: '⏰' },
];

// ============================================================================
// Component Props
// ============================================================================

interface Step7_SceneBreakdownProps {
  data: SceneBreakdown[] | null;
  onUpdate: (data: SceneBreakdown[]) => void;
  errors?: Record<string, string>;
  // Context from previous steps
  locations?: Location[];
  characters?: CharacterProfile[];
  projectType?: ProjectTypeData;
}

// ============================================================================
// Component
// ============================================================================

export function Step7_SceneBreakdown({
  data,
  onUpdate,
  errors = {},
  locations = [],
  characters = [],
  projectType,
}: Step7_SceneBreakdownProps) {
  // State
  const [scenes, setScenes] = useState<SceneBreakdown[]>(data || []);
  const [isSceneDialogOpen, setIsSceneDialogOpen] = useState(false);
  const [editingScene, setEditingScene] = useState<SceneBreakdown | null>(null);
  const [draggedSceneId, setDraggedSceneId] = useState<string | null>(null);

  // Scene form state
  const [sceneForm, setSceneForm] = useState<Partial<SceneBreakdown>>({
    sceneNumber: 1,
    sceneName: '',
    durationMinutes: 0,
    locationId: '',
    characterIds: [],
    timeOfDay: 'unspecified',
    emotionalBeat: '',
    keyActions: [],
  });

  // Key action input
  const [keyActionInput, setKeyActionInput] = useState('');

  // Update parent when scenes change
  useEffect(() => {
    onUpdate(scenes);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scenes]); // Only depend on scenes, not onUpdate

  // Calculate total duration
  const totalDuration = scenes.reduce((sum, scene) => sum + scene.durationMinutes, 0);
  const projectDuration = projectType?.durationMinutes || 0;
  const durationWarning = projectDuration > 0 && totalDuration > projectDuration;

  // Handle scene dialog open
  const handleAddScene = () => {
    setEditingScene(null);
    const nextSceneNumber = scenes.length > 0 
      ? Math.max(...scenes.map(s => s.sceneNumber)) + 1 
      : 1;
    setSceneForm({
      sceneNumber: nextSceneNumber,
      sceneName: '',
      durationMinutes: 0,
      locationId: locations.length > 0 ? locations[0].id : '',
      characterIds: [],
      timeOfDay: 'unspecified',
      emotionalBeat: '',
      keyActions: [],
    });
    setKeyActionInput('');
    setIsSceneDialogOpen(true);
  };

  // Handle scene edit
  const handleEditScene = (scene: SceneBreakdown) => {
    setEditingScene(scene);
    setSceneForm(scene);
    setKeyActionInput('');
    setIsSceneDialogOpen(true);
  };

  // Handle scene save
  const handleSaveScene = () => {
    if (!sceneForm.sceneName || !sceneForm.locationId || sceneForm.characterIds?.length === 0) {
      return;
    }

    const newScene: SceneBreakdown = {
      id: editingScene?.id || `scene-${Date.now()}`,
      sceneNumber: sceneForm.sceneNumber || 1,
      sceneName: sceneForm.sceneName || '',
      durationMinutes: sceneForm.durationMinutes || 0,
      locationId: sceneForm.locationId || '',
      characterIds: sceneForm.characterIds || [],
      timeOfDay: sceneForm.timeOfDay || 'unspecified',
      emotionalBeat: sceneForm.emotionalBeat || '',
      keyActions: sceneForm.keyActions || [],
      order: editingScene?.order || scenes.length,
    };

    if (editingScene) {
      // Update existing scene
      setScenes((prev) =>
        prev.map((s) => (s.id === editingScene.id ? newScene : s))
      );
    } else {
      // Add new scene
      setScenes((prev) => [...prev, newScene]);
    }

    setIsSceneDialogOpen(false);
    setSceneForm({
      sceneNumber: 1,
      sceneName: '',
      durationMinutes: 0,
      locationId: '',
      characterIds: [],
      timeOfDay: 'unspecified',
      emotionalBeat: '',
      keyActions: [],
    });
  };

  // Handle scene delete
  const handleDeleteScene = (sceneId: string) => {
    setScenes((prev) => prev.filter((s) => s.id !== sceneId));
  };

  // Handle key action add
  const handleAddKeyAction = () => {
    if (keyActionInput.trim() && !sceneForm.keyActions?.includes(keyActionInput.trim())) {
      setSceneForm((prev) => ({
        ...prev,
        keyActions: [...(prev.keyActions || []), keyActionInput.trim()],
      }));
      setKeyActionInput('');
    }
  };

  // Handle key action remove
  const handleRemoveKeyAction = (action: string) => {
    setSceneForm((prev) => ({
      ...prev,
      keyActions: (prev.keyActions || []).filter((a) => a !== action),
    }));
  };

  // Handle character selection toggle
  const handleToggleCharacter = (characterId: string) => {
    setSceneForm((prev) => {
      const currentIds = prev.characterIds || [];
      const newIds = currentIds.includes(characterId)
        ? currentIds.filter((id) => id !== characterId)
        : [...currentIds, characterId];
      return { ...prev, characterIds: newIds };
    });
  };

  // Drag and drop handlers
  const handleDragStart = (sceneId: string) => {
    setDraggedSceneId(sceneId);
  };

  const handleDragOver = (e: React.DragEvent, targetSceneId: string) => {
    e.preventDefault();
    if (!draggedSceneId || draggedSceneId === targetSceneId) return;

    const draggedIndex = scenes.findIndex((s) => s.id === draggedSceneId);
    const targetIndex = scenes.findIndex((s) => s.id === targetSceneId);

    if (draggedIndex === -1 || targetIndex === -1) return;

    const newScenes = [...scenes];
    const [draggedScene] = newScenes.splice(draggedIndex, 1);
    newScenes.splice(targetIndex, 0, draggedScene);

    // Update order property
    const reorderedScenes = newScenes.map((scene, index) => ({
      ...scene,
      order: index,
    }));

    setScenes(reorderedScenes);
  };

  const handleDragEnd = () => {
    setDraggedSceneId(null);
  };

  // Get location name by ID
  const getLocationName = (locationId: string) => {
    return locations.find((loc) => loc.id === locationId)?.name || 'Unknown Location';
  };

  // Get character names by IDs
  const getCharacterNames = (characterIds: string[]) => {
    return characterIds
      .map((id) => characters.find((char) => char.id === id)?.name)
      .filter(Boolean)
      .join(', ');
  };

  // Sort scenes by order
  const sortedScenes = [...scenes].sort((a, b) => a.order - b.order);

  return (
    <WizardFormLayout
      title="Scene Breakdown (Découpage)"
      description="Break down your story into individual scenes with detailed metadata"
    >
      {/* Error Summary */}
      {Object.keys(errors).length > 0 && (
        <div
          className="rounded-lg border border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950 p-4"
          role="alert"
        >
          <ul className="text-sm text-red-800 dark:text-red-200 space-y-1">
            {Object.values(errors).map((error, index) => (
              <li key={index}>{error}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Duration Warning */}
      {durationWarning && (
        <div className="rounded-lg border border-yellow-200 bg-yellow-50 dark:border-yellow-800 dark:bg-yellow-950 p-4">
          <div className="flex items-start gap-3">
            <AlertTriangle className="h-5 w-5 text-yellow-600 dark:text-yellow-400 mt-0.5" />
            <div>
              <h4 className="font-semibold text-yellow-900 dark:text-yellow-100 mb-1">
                Duration Warning
              </h4>
              <p className="text-sm text-yellow-700 dark:text-yellow-300">
                Total scene duration (<strong>{totalDuration} minutes</strong>) exceeds project
                duration (<strong>{projectDuration} minutes</strong>). Consider adjusting scene
                durations or project type.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Duration Summary */}
      <div className="rounded-lg bg-blue-50 dark:bg-blue-950 p-4 border border-blue-200 dark:border-blue-800">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Clock className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            <div>
              <h4 className="font-semibold text-blue-900 dark:text-blue-100">
                Total Duration
              </h4>
              <p className="text-sm text-blue-700 dark:text-blue-300">
                {totalDuration} minutes across {scenes.length} scenes
              </p>
            </div>
          </div>
          {projectDuration > 0 && (
            <div className="text-right">
              <p className="text-sm text-blue-700 dark:text-blue-300">
                Project Target: {projectDuration} min
              </p>
              <p className="text-xs text-blue-600 dark:text-blue-400">
                {totalDuration > 0 
                  ? `${Math.round((totalDuration / projectDuration) * 100)}% of target`
                  : 'No scenes yet'}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Scene List */}
      <FormSection
        title="Scenes"
        description="Drag and drop to reorder scenes"
      >
        {sortedScenes.length > 0 ? (
          <div className="space-y-3">
            {sortedScenes.map((scene) => (
              <Card
                key={scene.id}
                className={`hover:shadow-md transition-shadow cursor-move ${
                  draggedSceneId === scene.id ? 'opacity-50' : ''
                }`}
                draggable
                onDragStart={() => handleDragStart(scene.id)}
                onDragOver={(e) => handleDragOver(e, scene.id)}
                onDragEnd={handleDragEnd}
              >
                <CardContent className="p-4">
                  <div className="flex items-start gap-3">
                    {/* Drag Handle */}
                    <div className="flex-shrink-0 cursor-grab active:cursor-grabbing">
                      <GripVertical className="h-5 w-5 text-gray-400" />
                    </div>

                    {/* Scene Number Badge */}
                    <div className="flex-shrink-0">
                      <div className="h-10 w-10 rounded-full bg-gradient-to-br from-blue-100 to-purple-100 dark:from-blue-900 dark:to-purple-900 flex items-center justify-center">
                        <span className="text-sm font-semibold text-blue-700 dark:text-blue-300">
                          {scene.sceneNumber}
                        </span>
                      </div>
                    </div>

                    {/* Scene Details */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="flex-1">
                          <h4 className="font-semibold text-lg mb-1">{scene.sceneName}</h4>
                          <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                            <div className="flex items-center gap-1">
                              <MapPin className="h-4 w-4" />
                              <span>{getLocationName(scene.locationId)}</span>
                            </div>
                            <span>•</span>
                            <div className="flex items-center gap-1">
                              <Clock className="h-4 w-4" />
                              <span>{scene.durationMinutes} min</span>
                            </div>
                            <span>•</span>
                            <span>
                              {TIME_OF_DAY_OPTIONS.find((opt) => opt.value === scene.timeOfDay)?.icon}{' '}
                              {TIME_OF_DAY_OPTIONS.find((opt) => opt.value === scene.timeOfDay)?.label}
                            </span>
                          </div>
                        </div>
                        <div className="flex items-center gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEditScene(scene)}
                            aria-label={`Edit ${scene.sceneName}`}
                          >
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDeleteScene(scene.id)}
                            aria-label={`Delete ${scene.sceneName}`}
                            className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>

                      {/* Characters */}
                      {scene.characterIds.length > 0 && (
                        <div className="flex items-center gap-2 mb-2">
                          <Users className="h-4 w-4 text-gray-500" />
                          <div className="flex flex-wrap gap-1">
                            {scene.characterIds.map((charId) => {
                              const character = characters.find((c) => c.id === charId);
                              return character ? (
                                <Badge key={charId} variant="secondary" className="text-xs">
                                  {character.name}
                                </Badge>
                              ) : null;
                            })}
                          </div>
                        </div>
                      )}

                      {/* Emotional Beat */}
                      {scene.emotionalBeat && (
                        <p className="text-sm text-gray-600 dark:text-gray-400 italic mb-2">
                          "{scene.emotionalBeat}"
                        </p>
                      )}

                      {/* Key Actions */}
                      {scene.keyActions.length > 0 && (
                        <div className="mt-2">
                          <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 mb-1">
                            Key Actions:
                          </p>
                          <ul className="text-sm text-gray-600 dark:text-gray-400 space-y-1">
                            {scene.keyActions.map((action, index) => (
                              <li key={index} className="flex items-start gap-2">
                                <span className="text-blue-500">•</span>
                                <span>{action}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        ) : (
          <div className="text-center py-12 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-lg">
            <Film className="h-12 w-12 text-gray-400 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400 mb-4">
              No scenes yet. Add your first scene to begin the breakdown.
            </p>
          </div>
        )}

        {/* Add Scene Button */}
        <Button onClick={handleAddScene} variant="outline" className="w-full" type="button">
          <Plus className="h-4 w-4 mr-2" />
          Add Scene
        </Button>
      </FormSection>

      {/* Scene Dialog */}
      <Dialog open={isSceneDialogOpen} onOpenChange={setIsSceneDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingScene ? 'Edit Scene' : 'Add Scene'}
            </DialogTitle>
            <DialogDescription>
              Define the details and metadata for this scene
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Scene Number and Name */}
            <FormGrid columns={2}>
              <FormField
                label="Scene Number"
                name="sceneNumber"
                required
                helpText="Sequential scene number"
              >
                <Input
                  id="sceneNumber"
                  type="number"
                  min="1"
                  value={sceneForm.sceneNumber || 1}
                  onChange={(e) =>
                    setSceneForm((prev) => ({
                      ...prev,
                      sceneNumber: parseInt(e.target.value) || 1,
                    }))
                  }
                />
              </FormField>

              <FormField
                label="Duration (Minutes)"
                name="durationMinutes"
                required
                helpText="Estimated scene duration"
              >
                <Input
                  id="durationMinutes"
                  type="number"
                  min="0"
                  step="0.5"
                  value={sceneForm.durationMinutes || 0}
                  onChange={(e) =>
                    setSceneForm((prev) => ({
                      ...prev,
                      durationMinutes: parseFloat(e.target.value) || 0,
                    }))
                  }
                />
              </FormField>
            </FormGrid>

            <FormField
              label="Scene Name"
              name="sceneName"
              required
              helpText="Descriptive name for this scene"
            >
              <Input
                id="sceneName"
                value={sceneForm.sceneName || ''}
                onChange={(e) =>
                  setSceneForm((prev) => ({ ...prev, sceneName: e.target.value }))
                }
                placeholder="e.g., Hero's Call to Adventure, Final Confrontation"
              />
            </FormField>

            {/* Location and Time of Day */}
            <FormGrid columns={2}>
              <FormField
                label="Location"
                name="locationId"
                required
                helpText="Where does this scene take place?"
              >
                <Select
                  value={sceneForm.locationId || ''}
                  onValueChange={(value) =>
                    setSceneForm((prev) => ({ ...prev, locationId: value }))
                  }
                >
                  <SelectTrigger id="locationId">
                    <SelectValue placeholder="Select location" />
                  </SelectTrigger>
                  <SelectContent className="z-[9999]">
                    {locations.length > 0 ? (
                      locations.map((location) => (
                        <SelectItem key={location.id} value={location.id}>
                          {location.name}
                        </SelectItem>
                      ))
                    ) : (
                      <SelectItem value="none" disabled>
                        No locations defined
                      </SelectItem>
                    )}
                  </SelectContent>
                </Select>
              </FormField>

              <FormField
                label="Time of Day"
                name="timeOfDay"
                required
                helpText="When does this scene occur?"
              >
                <Select
                  value={sceneForm.timeOfDay || 'unspecified'}
                  onValueChange={(value) =>
                    setSceneForm((prev) => ({
                      ...prev,
                      timeOfDay: value as SceneBreakdown['timeOfDay'],
                    }))
                  }
                >
                  <SelectTrigger id="timeOfDay">
                    <SelectValue placeholder="Select time of day" />
                  </SelectTrigger>
                  <SelectContent className="z-[9999]">
                    {TIME_OF_DAY_OPTIONS.map((option) => (
                      <SelectItemWithDescription
                        key={option.value}
                        value={option.value}
                        label={option.label}
                        icon={option.icon}
                      />
                    ))}
                  </SelectContent>
                </Select>
              </FormField>
            </FormGrid>

            {/* Characters */}
            <FormField
              label="Characters Present"
              name="characterIds"
              required
              helpText="Select all characters in this scene"
            >
              {characters.length > 0 ? (
                <div className="flex flex-wrap gap-2">
                  {characters.map((character) => (
                    <Badge
                      key={character.id}
                      variant={
                        sceneForm.characterIds?.includes(character.id)
                          ? 'default'
                          : 'outline'
                      }
                      className="cursor-pointer hover:bg-blue-100 dark:hover:bg-blue-900"
                      onClick={() => handleToggleCharacter(character.id)}
                    >
                      {character.name}
                    </Badge>
                  ))}
                </div>
              ) : (
                <p className="text-sm text-gray-500">No characters defined in previous steps</p>
              )}
            </FormField>

            {/* Emotional Beat */}
            <FormField
              label="Emotional Beat"
              name="emotionalBeat"
              helpText="The emotional tone or turning point of this scene"
            >
              <Input
                id="emotionalBeat"
                value={sceneForm.emotionalBeat || ''}
                onChange={(e) =>
                  setSceneForm((prev) => ({ ...prev, emotionalBeat: e.target.value }))
                }
                placeholder="e.g., Tension builds, Hope restored, Betrayal revealed"
              />
            </FormField>

            {/* Key Actions */}
            <FormField
              label="Key Actions"
              name="keyActions"
              helpText="Important events or actions that occur in this scene"
            >
              <div className="space-y-2">
                <div className="flex gap-2">
                  <Input
                    value={keyActionInput}
                    onChange={(e) => setKeyActionInput(e.target.value)}
                    placeholder="e.g., Hero discovers the truth, Villain escapes"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddKeyAction();
                      }
                    }}
                  />
                  <Button type="button" onClick={handleAddKeyAction} variant="secondary">
                    Add
                  </Button>
                </div>
                {sceneForm.keyActions && sceneForm.keyActions.length > 0 && (
                  <ul className="space-y-1">
                    {sceneForm.keyActions.map((action, index) => (
                      <li
                        key={index}
                        className="flex items-start gap-2 text-sm bg-gray-50 dark:bg-gray-800 p-2 rounded"
                      >
                        <span className="text-blue-500">•</span>
                        <span className="flex-1">{action}</span>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => handleRemoveKeyAction(action)}
                          className="h-6 w-6 p-0 text-red-600 hover:text-red-700"
                        >
                          ×
                        </Button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </FormField>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsSceneDialogOpen(false)}
              type="button"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveScene}
              disabled={
                !sceneForm.sceneName ||
                !sceneForm.locationId ||
                !sceneForm.characterIds ||
                sceneForm.characterIds.length === 0
              }
              type="button"
            >
              {editingScene ? 'Update Scene' : 'Add Scene'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </WizardFormLayout>
  );
}

/**
 * Step 8: Shot Planning (Plan & Séquence)
 * Allows users to plan individual shots for each scene with detailed camera work
 */

import { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, Camera, Film, BarChart3, AlertCircle } from 'lucide-react';
import { WizardFormLayout, FormField, FormSection, FormGrid } from '../WizardFormLayout';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItemWithDescription,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select-rich';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import type {
  ShotPlan,
  ShotType,
  CameraAngle,
  CameraMovement,
  Transition,
  SceneBreakdown,
} from '@/types/wizard';

// ============================================================================
// Shot Type Options
// ============================================================================

const SHOT_TYPE_OPTIONS: {
  value: ShotType;
  label: string;
  description: string;
}[] = [
  { value: 'extreme-wide', label: 'Extreme Wide Shot', description: 'Establishes environment' },
  { value: 'wide', label: 'Wide Shot', description: 'Shows full subject and surroundings' },
  { value: 'medium', label: 'Medium Shot', description: 'Waist up, conversational' },
  { value: 'close-up', label: 'Close-Up', description: 'Face or object detail' },
  { value: 'extreme-close-up', label: 'Extreme Close-Up', description: 'Intense detail focus' },
  { value: 'over-the-shoulder', label: 'Over-the-Shoulder', description: 'Dialogue perspective' },
  { value: 'pov', label: 'POV', description: "Character's point of view" },
];

// ============================================================================
// Camera Angle Options
// ============================================================================

const CAMERA_ANGLE_OPTIONS: {
  value: CameraAngle;
  label: string;
  description: string;
}[] = [
  { value: 'eye-level', label: 'Eye Level', description: 'Neutral, natural perspective' },
  { value: 'high-angle', label: 'High Angle', description: 'Looking down, diminishes subject' },
  { value: 'low-angle', label: 'Low Angle', description: 'Looking up, empowers subject' },
  { value: 'dutch-angle', label: 'Dutch Angle', description: 'Tilted, creates unease' },
  { value: 'birds-eye', label: "Bird's Eye", description: 'Directly overhead' },
  { value: 'worms-eye', label: "Worm's Eye", description: 'Directly below' },
];

// ============================================================================
// Camera Movement Options
// ============================================================================

const CAMERA_MOVEMENT_OPTIONS: {
  value: CameraMovement;
  label: string;
  description: string;
}[] = [
  { value: 'static', label: 'Static', description: 'Fixed position' },
  { value: 'pan', label: 'Pan', description: 'Horizontal rotation' },
  { value: 'tilt', label: 'Tilt', description: 'Vertical rotation' },
  { value: 'dolly', label: 'Dolly', description: 'Move toward/away' },
  { value: 'track', label: 'Track', description: 'Follow subject laterally' },
  { value: 'zoom', label: 'Zoom', description: 'Lens focal length change' },
  { value: 'handheld', label: 'Handheld', description: 'Dynamic, intimate feel' },
  { value: 'crane', label: 'Crane', description: 'Vertical movement' },
];

// ============================================================================
// Transition Options
// ============================================================================

const TRANSITION_OPTIONS: {
  value: Transition;
  label: string;
  description: string;
}[] = [
  { value: 'cut', label: 'Cut', description: 'Instant transition' },
  { value: 'fade', label: 'Fade', description: 'Gradual to/from black' },
  { value: 'dissolve', label: 'Dissolve', description: 'Blend between shots' },
  { value: 'wipe', label: 'Wipe', description: 'One shot replaces another' },
  { value: 'match-cut', label: 'Match Cut', description: 'Visual/thematic connection' },
];

// ============================================================================
// Component Props
// ============================================================================

interface Step8_ShotPlanningProps {
  data: ShotPlan[] | null;
  onUpdate: (data: ShotPlan[]) => void;
  errors?: Record<string, string>;
  // Context from previous steps
  scenes?: SceneBreakdown[];
}

// ============================================================================
// Component
// ============================================================================

export function Step8_ShotPlanning({
  data,
  onUpdate,
  errors = {},
  scenes = [],
}: Step8_ShotPlanningProps) {
  // State
  const [shots, setShots] = useState<ShotPlan[]>(data || []);
  const [selectedSceneId, setSelectedSceneId] = useState<string>(
    scenes.length > 0 ? scenes[0].id : ''
  );
  const [isShotDialogOpen, setIsShotDialogOpen] = useState(false);
  const [editingShot, setEditingShot] = useState<ShotPlan | null>(null);

  // Shot form state
  const [shotForm, setShotForm] = useState<Partial<ShotPlan>>({
    shotNumber: 1,
    shotType: 'medium',
    cameraAngle: 'eye-level',
    cameraMovement: 'static',
    transition: 'cut',
    compositionNotes: '',
  });

  // Update parent when shots change
  useEffect(() => {
    onUpdate(shots);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shots]); // Only depend on shots, not onUpdate

  // Get shots for selected scene
  const sceneShotsFiltered = shots.filter((shot) => shot.sceneId === selectedSceneId);
  const sortedSceneShots = [...sceneShotsFiltered].sort((a, b) => a.order - b.order);

  // Calculate statistics
  const totalShots = shots.length;
  const shotsPerScene = scenes.map((scene) => ({
    sceneId: scene.id,
    sceneName: scene.sceneName,
    sceneNumber: scene.sceneNumber,
    shotCount: shots.filter((shot) => shot.sceneId === scene.id).length,
  }));
  const scenesWithoutShots = shotsPerScene.filter((s) => s.shotCount === 0);

  // Handle scene selection
  const handleSceneChange = (sceneId: string) => {
    setSelectedSceneId(sceneId);
  };

  // Handle shot dialog open
  const handleAddShot = () => {
    if (!selectedSceneId) return;

    setEditingShot(null);
    const sceneShots = shots.filter((s) => s.sceneId === selectedSceneId);
    const nextShotNumber = sceneShots.length > 0 
      ? Math.max(...sceneShots.map(s => s.shotNumber)) + 1 
      : 1;
    
    setShotForm({
      shotNumber: nextShotNumber,
      shotType: 'medium',
      cameraAngle: 'eye-level',
      cameraMovement: 'static',
      transition: 'cut',
      compositionNotes: '',
    });
    setIsShotDialogOpen(true);
  };

  // Handle shot edit
  const handleEditShot = (shot: ShotPlan) => {
    setEditingShot(shot);
    setShotForm(shot);
    setIsShotDialogOpen(true);
  };

  // Handle shot save
  const handleSaveShot = () => {
    if (!selectedSceneId) return;

    const newShot: ShotPlan = {
      id: editingShot?.id || `shot-${Date.now()}`,
      sceneId: selectedSceneId,
      shotNumber: shotForm.shotNumber || 1,
      shotType: shotForm.shotType || 'medium',
      cameraAngle: shotForm.cameraAngle || 'eye-level',
      cameraMovement: shotForm.cameraMovement || 'static',
      transition: shotForm.transition || 'cut',
      compositionNotes: shotForm.compositionNotes || '',
      order: editingShot?.order || sceneShotsFiltered.length,
    };

    if (editingShot) {
      // Update existing shot
      setShots((prev) =>
        prev.map((s) => (s.id === editingShot.id ? newShot : s))
      );
    } else {
      // Add new shot
      setShots((prev) => [...prev, newShot]);
    }

    setIsShotDialogOpen(false);
    setShotForm({
      shotNumber: 1,
      shotType: 'medium',
      cameraAngle: 'eye-level',
      cameraMovement: 'static',
      transition: 'cut',
      compositionNotes: '',
    });
  };

  // Handle shot delete
  const handleDeleteShot = (shotId: string) => {
    setShots((prev) => prev.filter((s) => s.id !== shotId));
  };

  // Get scene name by ID
  const getSceneName = (sceneId: string) => {
    const scene = scenes.find((s) => s.id === sceneId);
    return scene ? `Scene ${scene.sceneNumber}: ${scene.sceneName}` : 'Unknown Scene';
  };

  // Get option label
  const getOptionLabel = (
    value: string,
    options: { value: string; label: string; description: string }[]
  ) => {
    return options.find((opt) => opt.value === value)?.label || value;
  };

  return (
    <WizardFormLayout
      title="Shot Planning (Plan & Séquence)"
      description="Plan individual shots for each scene with detailed camera work and composition"
    >
      {/* Error Summary */}
      {Object.keys(errors).length > 0 && (
        <div
          className="rounded-lg border border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950 p-4"
          role="alert"
        >
          <ul className="text-sm text-red-800 dark:text-red-200 space-y-1">
            {Object.values(errors).map((error, index) => (
              <li key={index}>{error}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Statistics Summary */}
      <div className="rounded-lg bg-gradient-to-br from-blue-50 to-purple-50 dark:from-blue-950 dark:to-purple-950 p-6 border border-blue-200 dark:border-blue-800">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center">
              <BarChart3 className="h-6 w-6 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <h4 className="font-semibold text-lg text-blue-900 dark:text-blue-100">
                Shot Statistics
              </h4>
              <p className="text-sm text-blue-700 dark:text-blue-300">
                {totalShots} total shots across {scenes.length} scenes
              </p>
            </div>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold text-blue-900 dark:text-blue-100">
              {totalShots}
            </div>
            <p className="text-xs text-blue-600 dark:text-blue-400">
              {scenes.length > 0 ? `~${Math.round(totalShots / scenes.length)} per scene` : 'No scenes'}
            </p>
          </div>
        </div>

        {/* Scenes without shots warning */}
        {scenesWithoutShots.length > 0 && (
          <div className="mt-4 pt-4 border-t border-blue-200 dark:border-blue-800">
            <div className="flex items-start gap-2">
              <AlertCircle className="h-5 w-5 text-yellow-600 dark:text-yellow-400 mt-0.5 flex-shrink-0" />
              <div>
                <p className="text-sm font-semibold text-yellow-900 dark:text-yellow-100 mb-1">
                  Scenes Without Shots
                </p>
                <div className="flex flex-wrap gap-2">
                  {scenesWithoutShots.map((scene) => (
                    <Badge
                      key={scene.sceneId}
                      variant="outline"
                      className="text-xs cursor-pointer hover:bg-yellow-100 dark:hover:bg-yellow-900"
                      onClick={() => handleSceneChange(scene.sceneId)}
                    >
                      Scene {scene.sceneNumber}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Scene Selector */}
      <FormSection
        title="Select Scene"
        description="Choose a scene to plan shots for"
      >
        {scenes.length > 0 ? (
          <div className="space-y-3">
            <Select value={selectedSceneId} onValueChange={handleSceneChange}>
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Select a scene" />
              </SelectTrigger>
              <SelectContent className="z-[9999]">
                {scenes.map((scene) => {
                  const shotCount = shots.filter((s) => s.sceneId === scene.id).length;
                  return (
                    <SelectItem key={scene.id} value={scene.id}>
                      <div className="flex items-center justify-between gap-4 w-full">
                        <span>Scene {scene.sceneNumber}: {scene.sceneName}</span>
                        <Badge variant="secondary" className="ml-2">
                          {shotCount} {shotCount === 1 ? 'shot' : 'shots'}
                        </Badge>
                      </div>
                    </SelectItem>
                  );
                })}
              </SelectContent>
            </Select>

            {/* Shot count per scene overview */}
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
              {shotsPerScene.map((scene) => (
                <Card
                  key={scene.sceneId}
                  className={`cursor-pointer transition-all hover:shadow-md ${
                    selectedSceneId === scene.sceneId
                      ? 'ring-2 ring-blue-500 bg-blue-50 dark:bg-blue-950'
                      : ''
                  }`}
                  onClick={() => handleSceneChange(scene.sceneId)}
                >
                  <CardContent className="p-3">
                    <div className="text-xs font-semibold text-gray-500 dark:text-gray-400 mb-1">
                      Scene {scene.sceneNumber}
                    </div>
                    <div className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                      {scene.shotCount}
                    </div>
                    <div className="text-xs text-gray-600 dark:text-gray-400">
                      {scene.shotCount === 1 ? 'shot' : 'shots'}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        ) : (
          <div className="text-center py-8 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-lg">
            <Film className="h-10 w-10 text-gray-400 mx-auto mb-2" />
            <p className="text-gray-500 dark:text-gray-400">
              No scenes available. Please complete the Scene Breakdown step first.
            </p>
          </div>
        )}
      </FormSection>

      {/* Shot List for Selected Scene */}
      {selectedSceneId && (
        <FormSection
          title={`Shots for ${getSceneName(selectedSceneId)}`}
          description="Define camera work and composition for each shot"
        >
          {sortedSceneShots.length > 0 ? (
            <div className="space-y-3">
              {sortedSceneShots.map((shot) => (
                <Card key={shot.id} className="hover:shadow-md transition-shadow">
                  <CardContent className="p-4">
                    <div className="flex items-start gap-3">
                      {/* Shot Number Badge */}
                      <div className="flex-shrink-0">
                        <div className="h-10 w-10 rounded-full bg-gradient-to-br from-purple-100 to-pink-100 dark:from-purple-900 dark:to-pink-900 flex items-center justify-center">
                          <span className="text-sm font-semibold text-purple-700 dark:text-purple-300">
                            {shot.shotNumber}
                          </span>
                        </div>
                      </div>

                      {/* Shot Details */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2 mb-2">
                          <div className="flex-1">
                            <h4 className="font-semibold text-base mb-2">
                              Shot {shot.shotNumber}
                            </h4>
                            <div className="grid grid-cols-2 gap-2 text-sm">
                              <div>
                                <span className="text-gray-500 dark:text-gray-400">Type:</span>{' '}
                                <span className="font-medium">
                                  {getOptionLabel(shot.shotType, SHOT_TYPE_OPTIONS)}
                                </span>
                              </div>
                              <div>
                                <span className="text-gray-500 dark:text-gray-400">Angle:</span>{' '}
                                <span className="font-medium">
                                  {getOptionLabel(shot.cameraAngle, CAMERA_ANGLE_OPTIONS)}
                                </span>
                              </div>
                              <div>
                                <span className="text-gray-500 dark:text-gray-400">Movement:</span>{' '}
                                <span className="font-medium">
                                  {getOptionLabel(shot.cameraMovement, CAMERA_MOVEMENT_OPTIONS)}
                                </span>
                              </div>
                              <div>
                                <span className="text-gray-500 dark:text-gray-400">Transition:</span>{' '}
                                <span className="font-medium">
                                  {getOptionLabel(shot.transition, TRANSITION_OPTIONS)}
                                </span>
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEditShot(shot)}
                              aria-label={`Edit shot ${shot.shotNumber}`}
                            >
                              <Edit2 className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDeleteShot(shot.id)}
                              aria-label={`Delete shot ${shot.shotNumber}`}
                              className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950"
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>

                        {/* Composition Notes */}
                        {shot.compositionNotes && (
                          <div className="mt-2 p-2 bg-gray-50 dark:bg-gray-800 rounded text-sm">
                            <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 mb-1">
                              Composition Notes:
                            </p>
                            <p className="text-gray-700 dark:text-gray-300">
                              {shot.compositionNotes}
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <div className="text-center py-12 border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-lg">
              <Camera className="h-12 w-12 text-gray-400 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400 mb-4">
                No shots yet for this scene. Add your first shot to begin planning.
              </p>
            </div>
          )}

          {/* Add Shot Button */}
          <Button
            onClick={handleAddShot}
            variant="outline"
            className="w-full"
            type="button"
            disabled={!selectedSceneId}
          >
            <Plus className="h-4 w-4 mr-2" />
            Add Shot
          </Button>
        </FormSection>
      )}

      {/* Shot Dialog */}
      <Dialog open={isShotDialogOpen} onOpenChange={setIsShotDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingShot ? 'Edit Shot' : 'Add Shot'}
            </DialogTitle>
            <DialogDescription>
              Define camera work and composition for this shot
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Shot Number */}
            <FormField
              label="Shot Number"
              name="shotNumber"
              required
              helpText="Sequential shot number within the scene"
            >
              <Input
                id="shotNumber"
                type="number"
                min="1"
                value={shotForm.shotNumber || 1}
                onChange={(e) =>
                  setShotForm((prev) => ({
                    ...prev,
                    shotNumber: parseInt(e.target.value) || 1,
                  }))
                }
              />
            </FormField>

            {/* Shot Type */}
            <FormField
              label="Shot Type"
              name="shotType"
              required
              helpText="The framing and distance of the shot"
            >
              <Select
                value={shotForm.shotType || 'medium'}
                onValueChange={(value) =>
                  setShotForm((prev) => ({ ...prev, shotType: value as ShotType }))
                }
              >
                <SelectTrigger id="shotType">
                  <SelectValue placeholder="Select shot type" />
                </SelectTrigger>
<SelectContent className="z-[9999]">
                  {SHOT_TYPE_OPTIONS.map((option) => (
                    <SelectItemWithDescription
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      description={option.description}
                    />
                  ))}
                </SelectContent>
              </Select>
            </FormField>

            {/* Camera Angle */}
            <FormField
              label="Camera Angle"
              name="cameraAngle"
              required
              helpText="The vertical perspective of the camera"
            >
              <Select
                value={shotForm.cameraAngle || 'eye-level'}
                onValueChange={(value) =>
                  setShotForm((prev) => ({ ...prev, cameraAngle: value as CameraAngle }))
                }
              >
                <SelectTrigger id="cameraAngle">
                  <SelectValue placeholder="Select camera angle" />
                </SelectTrigger>
<SelectContent className="z-[9999]">
                  {CAMERA_ANGLE_OPTIONS.map((option) => (
                    <SelectItemWithDescription
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      description={option.description}
                    />
                  ))}
                </SelectContent>
              </Select>
            </FormField>

            {/* Camera Movement */}
            <FormField
              label="Camera Movement"
              name="cameraMovement"
              required
              helpText="How the camera moves during the shot"
            >
              <Select
                value={shotForm.cameraMovement || 'static'}
                onValueChange={(value) =>
                  setShotForm((prev) => ({ ...prev, cameraMovement: value as CameraMovement }))
                }
              >
                <SelectTrigger id="cameraMovement">
                  <SelectValue placeholder="Select camera movement" />
                </SelectTrigger>
<SelectContent className="z-[9999]">
                  {CAMERA_MOVEMENT_OPTIONS.map((option) => (
                    <SelectItemWithDescription
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      description={option.description}
                    />
                  ))}
                </SelectContent>
              </Select>
            </FormField>

            {/* Transition */}
            <FormField
              label="Transition"
              name="transition"
              required
              helpText="How this shot transitions to the next"
            >
              <Select
                value={shotForm.transition || 'cut'}
                onValueChange={(value) =>
                  setShotForm((prev) => ({ ...prev, transition: value as Transition }))
                }
              >
                <SelectTrigger id="transition">
                  <SelectValue placeholder="Select transition" />
                </SelectTrigger>
<SelectContent className="z-[9999]">
                  {TRANSITION_OPTIONS.map((option) => (
                    <SelectItemWithDescription
                      key={option.value}
                      value={option.value}
                      label={option.label}
                      description={option.description}
                    />
                  ))}
                </SelectContent>
              </Select>
            </FormField>

            {/* Composition Notes */}
            <FormField
              label="Composition Notes"
              name="compositionNotes"
              helpText="Visual composition details, lighting, focus, or special instructions"
            >
              <Textarea
                id="compositionNotes"
                value={shotForm.compositionNotes || ''}
                onChange={(e) =>
                  setShotForm((prev) => ({ ...prev, compositionNotes: e.target.value }))
                }
                placeholder="e.g., Rule of thirds, subject in left frame, soft lighting from window, shallow depth of field"
                rows={4}
              />
            </FormField>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setIsShotDialogOpen(false)}
              type="button"
            >
              Cancel
            </Button>
            <Button onClick={handleSaveShot} type="button">
              {editingShot ? 'Update Shot' : 'Add Shot'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </WizardFormLayout>
  );
}

