];

// ============================================================================
// Extended Form Data with Methodology
// ============================================================================

interface ExtendedStorySetupData extends StorySetupData {
  methodology?: string;
  methodologyOptions?: Record<string, unknown>;
  methodologySettings?: FullSettings;
}

// ============================================================================
// Step 1: Story Setup
// ============================================================================

export function Step1StorySetup() {
  const { formData, updateFormData, validationErrors } = useWizard<ExtendedStorySetupData>();

  // Track if preferences have been applied to avoid infinite loops
  const preferencesAppliedRef = React.useRef(false);

  // Load saved style preferences on mount
  useEffect(() => {
    // Only apply preferences once per component lifecycle
    if (preferencesAppliedRef.current) return;

    const savedPreferences = loadStylePreferences();
    if (savedPreferences) {
      // Only apply saved preferences if form data is empty (first load)
      const hasExistingGenre = (formData.genre?.length ?? 0) > 0;
      const hasExistingTone = (formData.tone?.length ?? 0) > 0;
      const hasExistingLength = formData.length && formData.length !== 'medium' && formData.length !== undefined;

      const updates: Partial<ExtendedStorySetupData> = {};

      if (!hasExistingGenre && savedPreferences.lastUsedGenre.length > 0) {
        updates.genre = savedPreferences.lastUsedGenre;
      }
      if (!hasExistingTone && savedPreferences.lastUsedTone.length > 0) {
        updates.tone = savedPreferences.lastUsedTone;
      }
      if (!hasExistingLength && savedPreferences.lastUsedLength) {
        updates.length = savedPreferences.lastUsedLength as any;
      }

      // Only update if there are changes to make
      if (Object.keys(updates).length > 0) {
        console.log('[Step1StorySetup] Applying saved preferences:', updates);
        updateFormData(updates);
      }

      preferencesAppliedRef.current = true;
    }
  }, [updateFormData]); // Include updateFormData in dependencies

  // Local state for methodology selection (synced with formData)
  const [selectedMethodology, setSelectedMethodology] = useState(formData.methodology || 'sequential');
  const [methodologyOptions, setMethodologyOptions] = useState<Record<string, unknown>>(
    formData.methodologyOptions || {}
  );
  const [methodologySettings, setMethodologySettings] = useState<FullSettings>(
    formData.methodologySettings || {
      writingStyle: WritingStyle.DESCRIPTIVE,
      toneConsistencyCheck: true,
      characterVoiceConsistency: true,
      revisionHistory: true,
    }
  );
  const [showMethodology, setShowMethodology] = useState(false);

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateFormData({ title: e.target.value });
  };

  const handleGenreToggle = (genre: string) => {
    const currentGenres = formData.genre || [];
    const newGenres = currentGenres.includes(genre)
      ? currentGenres.filter((g) => g !== genre)
      : [...currentGenres, genre];
    updateFormData({ genre: newGenres });
    // Save to preferences
    saveStylePreferences({ lastUsedGenre: newGenres });
  };

  const handleToneToggle = (tone: string) => {
    const currentTones = formData.tone || [];
    const newTones = currentTones.includes(tone)
      ? currentTones.filter((t) => t !== tone)
      : [...currentTones, tone];
    updateFormData({ tone: newTones });
    // Save to preferences
    saveStylePreferences({ lastUsedTone: newTones });
  };

  const handleLengthChange = (value: string) => {
    updateFormData({ length: value as 'short' | 'medium' | 'long' });
    // Save to preferences
    saveStylePreferences({ lastUsedLength: value });
  };

  const handleMethodologyChange = (methodology: string) => {
    setSelectedMethodology(methodology);
    updateFormData({ methodology });
  };

  const handleMethodologyOptionsChange = (options: Record<string, unknown>) => {
    setMethodologyOptions(options);
    updateFormData({ methodologyOptions: options });
  };

  const handleMethodologySettingsChange = (settings: FullSettings) => {
    setMethodologySettings(settings);
    updateFormData({ methodologySettings: settings });
  };

  const handleWritingStyleChange = (style: WritingStyle) => {
    const newSettings = { ...methodologySettings, writingStyle: style };
    setMethodologySettings(newSettings);
    updateFormData({ methodologySettings: newSettings });
  };

  return (
    <WizardFormLayout
      title="Story Setup"
      description="Define the basic parameters for your story"
    >
      {/* Validation Error Summary */}
      <ValidationErrorSummary errors={validationErrors} className="mb-6" />

      {/* Story Title (Optional) */}
      <FormField
        label="Story Title"
        name="title"
        helpText="Give your story a title (optional - you can add this later)"
      >
        <Input
          id="title"
          value={formData.title || ''}
          onChange={handleTitleChange}
          placeholder="e.g., The Crystal Prophecy, Shadows of Tomorrow"
          aria-describedby="title-help"
        />
      </FormField>

      {/* Genre Selection */}
      <FormField
        label={
          <>
            Genre <span className="text-red-600">*</span>
          </>
        }
        name="genre"
        required
        error={validationErrors.genre?.[0]}
        helpText="Select one or more genres for your story (at least one required)"
      >
        <div
          className="grid grid-cols-2 md:grid-cols-3 gap-3"
          role="group"
          aria-labelledby="genre-label"
          aria-required="true"
        >
          {GENRE_OPTIONS.map((option) => (
            <div key={option.value} className="flex items-center space-x-2">
              <Checkbox
                id={`genre-${option.value}`}
                checked={formData.genre?.includes(option.value) || false}
                onCheckedChange={() => handleGenreToggle(option.value)}
                aria-label={option.label}
              />
              <Label
                htmlFor={`genre-${option.value}`}
                className="text-sm font-normal cursor-pointer"
              >
                {option.label}
              </Label>
            </div>
          ))}
        </div>
      </FormField>

      {/* Tone Selection */}
      <FormField
        label={
          <>
            Tone <span className="text-red-600">*</span>
          </>
        }
        name="tone"
        required
        error={validationErrors.tone?.[0]}
        helpText="Select one or more tones that define the story's atmosphere (at least one required)"
      >
        <div
          className="grid grid-cols-2 md:grid-cols-3 gap-3"
          role="group"
          aria-labelledby="tone-label"
          aria-required="true"
        >
          {TONE_OPTIONS.map((option) => (
            <div key={option.value} className="flex items-center space-x-2">
              <Checkbox
                id={`tone-${option.value}`}
                checked={formData.tone?.includes(option.value) || false}
                onCheckedChange={() => handleToneToggle(option.value)}
                aria-label={option.label}
              />
              <Label
                htmlFor={`tone-${option.value}`}
                className="text-sm font-normal cursor-pointer"
              >
                {option.label}
              </Label>
            </div>
          ))}
        </div>
      </FormField>

      {/* Story Length */}
      <FormField
        label={
          <>
            Story Length <span className="text-red-600">*</span>
          </>
        }
        name="length"
        required
        error={validationErrors.length?.[0]}
        helpText="Choose the desired length for your story"
      >
        <RadioGroup
          value={formData.length || 'medium'}
          onValueChange={handleLengthChange}
          aria-required="true"
          aria-invalid={!!validationErrors.length}
          aria-describedby={validationErrors.length ? 'length-error' : 'length-help'}
        >
          {LENGTH_OPTIONS.map((option) => (
            <div key={option.value} className="flex items-center space-x-2">
              <RadioGroupItem
                value={option.value}
                id={`length-${option.value}`}
                aria-label={`${option.label} - ${option.description}`}
              />
              <Label
                htmlFor={`length-${option.value}`}
                className="text-sm font-normal cursor-pointer flex flex-col"
              >
                <span className="font-medium">{option.label}</span>
                <span className="text-xs text-muted-foreground">{option.description}</span>
              </Label>
            </div>
          ))}
        </RadioGroup>
      </FormField>

      {/* Methodology Selection Toggle */}
      <div className="border-t pt-6 mt-6">
        <button
          type="button"
          onClick={() => setShowMethodology(!showMethodology)}
          className="w-full flex items-center justify-between p-4 rounded-lg bg-muted/50 hover:bg-muted transition-colors"
        >
          <div className="text-left">
            <h3 className="font-semibold">Story Creation Methodology</h3>
            <p className="text-sm text-muted-foreground">
              Choose how you want to create your story
            </p>
          </div>
          <Label className="text-sm text-muted-foreground">
            {showMethodology ? 'Hide options' : 'Show options'}
          </Label>
        </button>

        {/* Methodology Selector */}
        {showMethodology && (
          <div className="mt-4">
            <MethodologySelector
              selectedMethodology={selectedMethodology}
              onMethodologyChange={handleMethodologyChange}
              options={methodologyOptions}
              onOptionsChange={handleMethodologyOptionsChange}
              writingStyle={methodologySettings.writingStyle}
              onWritingStyleChange={handleWritingStyleChange}
              settings={methodologySettings}
              onSettingsChange={handleMethodologySettingsChange}
            />
          </div>
        )}
      </div>

      {/* Info Box */}
      <div className="bg-blue-50 dark:bg-blue-950/20 p-4 rounded-md">
        <p className="text-sm text-blue-900 dark:text-blue-100">
          💡 <strong>Tip:</strong> The genre and tone you select will influence how the AI generates your story.
          You can combine multiple genres and tones to create unique narratives.
        </p>
      </div>
    </WizardFormLayout>
  );
}

import { useState, useCallback } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout } from '../WizardFormLayout';
import { ValidationErrorSummary } from '../ValidationErrorSummary';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Sparkles, Users, Bookmark } from 'lucide-react';
import { useStore } from '@/store';
import type { CharacterSelectionData, CharacterCreationRequest, WorldContext } from '@/types/story';
import type { Character } from '@/types/character';
import { createCharacter } from '@/services/storyGenerationService';
import { LLMErrorDisplay, LLMLoadingState } from '../LLMErrorDisplay';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import { LLMErrorCategory, type ErrorRecoveryOptions } from '@/services/llmService';
import { CharacterList } from '@/components/character/CharacterList';
import { eventEmitter } from '@/services/eventEmitter';
import {
  getCharacterTemplatesByGenre,
  characterTemplateToReference,
  type CharacterTemplate
} from '@/services/globalTemplatesService';

// ============================================================================
// Step 2: Character Selection
// ============================================================================

export function Step2CharacterSelection() {
  const { formData, updateFormData, validationErrors } = useWizard<CharacterSelectionData>();
  const addCharacter = useStore((state) => state.addCharacter);
  const currentWorld = useStore((state) => state.worlds?.find(w => w.id === state.selectedWorldId));

  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [isCreating, setIsCreating] = useState(false);
  const [createError, setCreateError] = useState<ErrorRecoveryOptions | null>(null);
  const [newCharacter, setNewCharacter] = useState<CharacterCreationRequest>({
    name: '',
    role: '',
    description: '',
  });

  const { llmConfigured } = useServiceStatus();
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  // Get character templates based on selected genre (from global templates)
  const genreFromWizard = (formData as any).genre || [];
  const characterTemplates = getCharacterTemplatesByGenre(genreFromWizard);

  // Get selected character IDs from form data
  const selectedCharacterIds = (formData.selectedCharacters || []).map(c => c.id);

  /**
   * Handle selecting a template character
   */
  const handleSelectTemplate = useCallback((template: CharacterTemplate) => {
    const templateRef = characterTemplateToReference(template);

    // Check if already selected
    if (selectedCharacterIds.includes(template.id)) {
      return;
    }

    // Add to selected characters
    updateFormData({
      selectedCharacters: [
        ...(formData.selectedCharacters || []),
        templateRef
      ]
    });
  }, [selectedCharacterIds, formData.selectedCharacters, updateFormData]);

  /**
   * Handle character selection changes
   * Requirements: 4.2, 4.5
   */
  const handleSelectionChange = useCallback((ids: string[]) => {
    // Get all characters from store
    const allCharacters = useStore.getState().characters || [];

    // Map IDs to character summary objects
    const selectedCharacters = ids.map(id => {
      const character = allCharacters.find(c => c.character_id === id);
      if (!character) return null;

      return {
        id: character.character_id,
        name: character.name,
        role: character.role?.archetype || 'Character',
      };
    }).filter(Boolean) as Array<{ id: string; name: string; role: string }>;

    updateFormData({
      selectedCharacters,
    });
  }, [updateFormData]);

  /**
   * Handle character creation from story context
   * Requirements: 3.2, 3.5
   */
  const handleCreateCharacter = async () => {
    if (!newCharacter.name || !newCharacter.role) {
      setCreateError({
        message: 'Name and role are required',
        userMessage: 'Name and role are required',
        actions: [],
        retryable: false,
        category: LLMErrorCategory.INVALID_REQUEST,
      });
      return;
    }

    setIsCreating(true);
    setCreateError(null);

    try {
      // Build world context - map WorldRule to story WorldRule format
      const worldContext: WorldContext | undefined = currentWorld ? {
        id: currentWorld.id,
        name: currentWorld.name,
        genre: currentWorld.genre || [],
        tone: currentWorld.tone || [],
        rules: (currentWorld.rules || []).map(rule => ({
          id: rule.id,
          category: rule.category,
          rule: rule.rule,
          description: rule.implications || '', // Map implications to description
        })),
        culturalElements: currentWorld.culturalElements || {},
        atmosphere: currentWorld.atmosphere || '',
      } : undefined;

      // Call LLM service to create character (worldContext is optional)
      const createdCharacter = await createCharacter(newCharacter, worldContext);

      // Add to store
      addCharacter(createdCharacter);

      // Emit character-created event for real-time updates
      // Requirement: 3.4, 12.1
      eventEmitter.emit('character-created', {
        character: createdCharacter,
        source: 'wizard',
        timestamp: new Date(),
      });

      // Auto-select the newly created character
      // Requirement: 3.5
      const newSelectedIds = [...selectedCharacterIds, createdCharacter.character_id];
      handleSelectionChange(newSelectedIds);

      // Close dialog and reset form
      setShowCreateDialog(false);
      setNewCharacter({ name: '', role: '', description: '' });
    } catch (error) {
      console.error('Failed to create character:', error);
      setCreateError({
        message: error instanceof Error ? error.message : 'Failed to create character',
        userMessage: error instanceof Error ? error.message : 'Failed to create character',
        actions: [],
        retryable: true,
        category: LLMErrorCategory.UNKNOWN,
      });
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <WizardFormLayout
      title="Select Characters"
      description="Choose characters for your story or create new ones"
    >
      {/* Validation Error Summary */}
      <ValidationErrorSummary errors={validationErrors} className="mb-6" />

      {/* Service Warning */}
      {!llmConfigured && (
        <ServiceWarning
          service="llm"
          variant="inline"
          onConfigure={() => setShowLLMSettings(true)}
          className="mb-6"
        />
      )}

      {/* Selected Count */}
      <div className="mb-4 p-3 bg-blue-50 dark:bg-blue-950/20 rounded-md">
        <p className="text-sm text-blue-900 dark:text-blue-100">
          <strong>{selectedCharacterIds.length}</strong> character{selectedCharacterIds.length !== 1 ? 's' : ''} selected
        </p>
      </div>

      {/* Character List with Selection Mode */}
      {/* Requirements: 4.1, 4.2, 4.3 */}
      <div className="mb-6">
        <CharacterList
          selectable={true}
          selectedIds={selectedCharacterIds}
          onSelectionChange={handleSelectionChange}
          showActions={false}
        />
      </div>

      {/* Global Templates Section */}
      {characterTemplates.length > 0 && (
        <div className="mb-6">
          <div className="flex items-center gap-2 mb-3">
            <Bookmark className="w-4 h-4 text-purple-500" />
            <Label className="text-sm font-semibold">Quick Start Templates</Label>
            <span className="text-xs text-muted-foreground">(Outside project - click to add)</span>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            {characterTemplates.map((template) => {
              const isSelected = selectedCharacterIds.includes(template.id);
              return (
                <button
                  key={template.id}
                  onClick={() => handleSelectTemplate(template)}
                  disabled={isSelected}
                  className={`p-3 rounded-lg border text-left transition-all ${isSelected
                      ? 'border-green-500 bg-green-50 dark:bg-green-950/20 cursor-default'
                      : 'border-gray-200 dark:border-gray-700 hover:border-purple-400 hover:bg-purple-50 dark:hover:bg-purple-950/20 cursor-pointer'
                    }`}
                >
                  <div className="flex items-center gap-2">
                    <Users className="w-4 h-4 text-purple-500 flex-shrink-0" />
                    <div className="min-w-0">
                      <p className="font-medium text-sm truncate">{template.name}</p>
                      <p className="text-xs text-muted-foreground truncate">{template.role}</p>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Create New Character Button */}
      {/* Requirements: 3.2 */}
      <Button
        onClick={() => setShowCreateDialog(true)}
        variant="outline"
        className="w-full gap-2"
        disabled={!llmConfigured}
      >
        <Plus className="w-4 h-4" />
        Create New Character
      </Button>

      {/* Info Box */}
      <div className="mt-6 bg-amber-50 dark:bg-amber-950/20 p-4 rounded-md">
        <p className="text-sm text-amber-900 dark:text-amber-100">
          💡 <strong>Tip:</strong> You can select multiple characters or proceed without any.
          The AI will use selected characters in the story or create new ones as needed.
        </p>
      </div>

      {/* Create Character Dialog */}
      <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-blue-500" />
              Create New Character
            </DialogTitle>
            <DialogDescription>
              Provide basic information and the AI will generate a complete character profile
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Name */}
            <div className="space-y-2">
              <Label htmlFor="new-character-name">
                Name <span className="text-red-600">*</span>
              </Label>
              <Input
                id="new-character-name"
                value={newCharacter.name}
                onChange={(e) => setNewCharacter({ ...newCharacter, name: e.target.value })}
                placeholder="e.g., Aria Stormwind"
                disabled={isCreating}
              />
            </div>

            {/* Role */}
            <div className="space-y-2">
              <Label htmlFor="new-character-role">
                Role <span className="text-red-600">*</span>
              </Label>
              <Input
                id="new-character-role"
                value={newCharacter.role}
                onChange={(e) => setNewCharacter({ ...newCharacter, role: e.target.value })}
                placeholder="e.g., Protagonist, Mentor, Villain"
                disabled={isCreating}
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="new-character-description">
                Description
                <span className="text-muted-foreground ml-1">(Optional)</span>
              </Label>
              <Textarea
                id="new-character-description"
                value={newCharacter.description}
                onChange={(e) => setNewCharacter({ ...newCharacter, description: e.target.value })}
                placeholder="Brief description of the character's personality or background"
                rows={3}
                disabled={isCreating}
              />
            </div>

            {/* Loading State */}
            {isCreating && (
              <LLMLoadingState message="Creating character with AI..." showProgress />
            )}

            {/* Error Display */}
            {createError && (
              <LLMErrorDisplay
                error={createError}
                onRetry={handleCreateCharacter}
                onDismiss={() => setCreateError(null)}
              />
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowCreateDialog(false);
                setNewCharacter({ name: '', role: '', description: '' });
                setCreateError(null);
              }}
              disabled={isCreating}
            >
              Cancel
            </Button>
            <Button
              onClick={handleCreateCharacter}
              disabled={isCreating || !newCharacter.name || !newCharacter.role || !llmConfigured}
              className="gap-2"
            >
              <Sparkles className="w-4 h-4" />
              {isCreating ? 'Creating...' : 'Create Character'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </WizardFormLayout>
  );
}

import React, { useEffect, useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout } from '../WizardFormLayout';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Loader2, CheckCircle, AlertCircle, RefreshCw, ChevronRight, ChevronLeft } from 'lucide-react';
import { useStore } from '@/store';
import type { GenerationProgress, StoryGenerationParams, WorldContext, StoryPart, Story } from '@/types/story';
import type { MethodologyState, StoryPhase } from '@/types/storyMethodology';
import { generateStory } from '@/services/storyGenerationService';
import { Star, ScrollText, Layers, FileEdit } from 'lucide-react';

// ============================================================================
// Wizard Form Data Interface
// ============================================================================

interface StoryWizardFormData {
  title?: string;
  genre?: string[];
  tone?: string[];
  length?: 'short' | 'medium' | 'long';
  selectedCharacters?: Array<{ id: string; name: string; role: string }>;
  selectedLocations?: Array<{ id: string; name: string; significance: string }>;
  generatedContent?: string;
  generatedSummary?: string;
  parts?: unknown[];
  methodologyState?: MethodologyState;
}

// ============================================================================
// Phase Progress Component
// ============================================================================

interface Phase {
  phase: StoryPhase;
  name: string;
  description: string;
}

interface PhaseProgressProps {
  phases: Phase[];
  currentPhase: StoryPhase;
  progress: number;
}

function PhaseProgress({ phases, currentPhase, progress }: PhaseProgressProps) {
  const getPhaseIndex = (phase: StoryPhase) =>
    phases.findIndex(p => p.phase === phase);

  const currentIndex = getPhaseIndex(currentPhase);

  return (
    <div className="space-y-4">
      {/* Overall Progress */}
      <div className="space-y-2">
        <div className="flex items-center justify-between text-sm">
          <span className="font-medium">Overall Progress</span>
          <span className="text-muted-foreground">{progress}%</span>
        </div>
        <Progress value={progress} className="h-2" />
      </div>

      {/* Phase Steps */}
      <div className="flex items-center justify-between">
        {phases.map((phase, index) => {
          const isComplete = index < currentIndex;
          const isCurrent = index === currentIndex;
          const isPending = index > currentIndex;

          return (
            <React.Fragment key={phase.phase}>
              <div className="flex flex-col items-center">
                <div
                  className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-colors ${isComplete
                    ? 'bg-green-500 text-white'
                    : isCurrent
                      ? 'bg-blue-500 text-white animate-pulse'
                      : 'bg-muted text-muted-foreground'
                    }`}
                >
                  {isComplete ? (
                    <CheckCircle className="w-5 h-5" />
                  ) : (
                    index + 1
                  )}
                </div>
                <span className={`text-xs mt-1 ${isCurrent ? 'font-medium text-primary' : 'text-muted-foreground'}`}>
                  {phase.name}
                </span>
              </div>
              {index < phases.length - 1 && (
                <div className={`flex-1 h-0.5 mx-2 ${index < currentIndex ? 'bg-green-500' : 'bg-muted'}`} />
              )}
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================================
// Generation Progress Component
// ============================================================================

interface GenerationProgressProps {
  progress: GenerationProgress;
}

function GenerationProgressComponent({ progress }: GenerationProgressProps) {
  const stageLabels: Record<string, string> = {
    preparing: 'Preparing generation...',
    creating_elements: 'Creating story elements...',
    generating_intro: 'Generating story introduction...',
    generating_chapter: `Generating chapter ${progress.currentChapter || 1} of ${progress.totalChapters || '?'}...`,
    generating_ending: 'Finalizing the story ending...',
    reviewing: 'Reviewing content quality...',
    refining: 'Refining story details...',
    generating_story: 'Generating story content...',
    complete: 'Generation complete!',
  };

  const isError = !!progress.error;
  const isComplete = progress.stage === 'complete';

  return (
    <div className="space-y-4">
      {/* Progress Bar */}
      <div className="space-y-2">
        <div className="flex items-center justify-between text-sm">
          <span className="font-medium">{stageLabels[progress.stage]}</span>
          <span className="text-muted-foreground">{progress.progress}%</span>
        </div>
        <Progress value={progress.progress} className="h-2" />
      </div>

      {/* Current Task */}
      <div className="flex items-center gap-3 p-4 rounded-lg bg-gray-50 dark:bg-gray-900">
        {isError ? (
          <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0" />
        ) : isComplete ? (
          <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" />
        ) : (
          <Loader2 className="w-5 h-5 text-blue-500 animate-spin flex-shrink-0" />
        )}
        <p className="text-sm text-muted-foreground">{progress.currentTask}</p>
      </div>

      {/* Error Message */}
      {isError && (
        <div className="p-4 rounded-lg bg-red-50 dark:bg-red-950/20 border border-red-200 dark:border-red-800">
          <p className="text-sm text-red-900 dark:text-red-100">
            <strong>Error:</strong> {progress.error}
          </p>
        </div>
      )}
    </div>
  );
}

// ============================================================================
// Story Preview Component
// ============================================================================

function StoryPartPreview({ part }: { part: StoryPart }) {
  const scores = part.reviewScore;

  return (
    <div className="p-4 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 space-y-3">
      <div className="flex items-center justify-between">
        <h4 className="font-medium flex items-center gap-2">
          <ScrollText className="w-4 h-4 text-primary" />
          {part.title}
        </h4>
        {scores && (
          <div className="flex items-center gap-2 px-2 py-1 rounded bg-amber-amber-900/30 text-amber100 dark:bg--700 dark:text-amber-400 text-xs font-bold">
            <Star className="w-3 h-3 fill-current" />
            Quality: {scores.overall}/10
          </div>
        )}
      </div>
      <p className="text-sm text-muted-foreground whitespace-pre-wrap line-clamp-4">{part.content}</p>

      {scores && (
        <div className="grid grid-cols-4 gap-2 pt-2 border-t border-gray-200 dark:border-gray-800">
          <div className="text-center">
            <div className="text-[10px] text-muted-foreground uppercase">Tension</div>
            <div className="text-xs font-bold">{scores.tension}</div>
          </div>
          <div className="text-center">
            <div className="text-[10px] text-muted-foreground uppercase">Drama</div>
            <div className="text-xs font-bold">{scores.drama}</div>
          </div>
          <div className="text-center">
            <div className="text-[10px] text-muted-foreground uppercase">Sense</div>
            <div className="text-xs font-bold">{scores.sense}</div>
          </div>
          <div className="text-center">
            <div className="text-[10px] text-muted-foreground uppercase">Emotion</div>
            <div className="text-xs font-bold">{scores.emotion}</div>
          </div>
