// ============================================================================
// Step 5: Review and Export
// ============================================================================

export function Step5ReviewExport() {
  const { formData, updateFormData } = useWizard<StoryWizardFormData>();
  const { getVersionsByStoryId, loadVersion } = useStore();
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  const [isExporting, setIsExporting] = useState(false);
  const [exportSuccess, setExportSuccess] = useState(false);
  const [exportError, setExportError] = useState<string | null>(null);
  const [exportedFilePath, setExportedFilePath] = useState<string | null>(null);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [storyId] = useState(() => crypto.randomUUID()); // Generate stable ID for this story
  const [versions, setVersions] = useState<Array<{ id: string; versionNumber: number; createdAt: number; changes: string }>>([]);
  const [selectedVersionId, setSelectedVersionId] = useState<string | null>(null);

  const [assetPrompts, setAssetPrompts] = useState<{
    image?: string;
    audio?: string;
    video?: string;
  }>({});

  // Load versions when component mounts or storyId changes
  useEffect(() => {
    const loadedVersions = getVersionsByStoryId(storyId);
    setVersions(loadedVersions);
  }, [storyId, getVersionsByStoryId]);

  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: 'md',
    includeMetadata: true,
    includeSummary: true,
    filename: formData.title || 'story',
  });

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    updateFormData({ generatedContent: e.target.value });
    setHasUnsavedChanges(true);
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateFormData({ title: e.target.value });
    setExportOptions({ ...exportOptions, filename: e.target.value || 'story' });
  };

  const handleLoadVersion = (versionId: string) => {
    if (versionId === 'current') {
      setSelectedVersionId(null);
      return;
    }

    loadVersion(versionId);
    setSelectedVersionId(versionId);

    // Reload versions to get updated data
    const loadedVersions = getVersionsByStoryId(storyId);
    setVersions(loadedVersions);
  };

  const handleExport = async () => {
    setIsExporting(true);
    setExportSuccess(false);
    setExportError(null);

    try {
      const now = Date.now();
      // Build story object for export with correct types
      const story: Story = {
        id: crypto.randomUUID(),
        title: formData.title || 'Untitled Story',
        content: formData.generatedContent || '',
        summary: formData.generatedSummary || '',
        genre: formData.genre || [],
        tone: formData.tone || [],
        length: formData.length || 'medium',
        charactersUsed: formData.selectedCharacters || [],
        locationsUsed: formData.selectedLocations || [],
        autoGeneratedElements: [],
        parts: formData.parts,
        createdAt: now,
        updatedAt: now,
        version: 1,
        fileFormat: 'md',
      };

      // Get current project path from store
      const currentProject = useStore.getState().project;
      const projectPath = (currentProject?.metadata?.path || currentProject?.project_name) as string | undefined;

      // If Electron API available and we have a project path, save full project structure
      if (window.electronAPI?.fs && projectPath) {
        try {
          // Save complete story with all parts using saveStoryToDisk
          await saveStoryToDisk(projectPath, story);

          setExportSuccess(true);
          setExportedFilePath(`${projectPath}/story/`);
          setHasUnsavedChanges(false);
          console.log('[Step5ReviewExport] Story saved to project:', projectPath);
        } catch (diskError) {
          console.warn('[Step5ReviewExport] Failed to save to disk, falling back to export:', diskError);
          // Fallback to simple export
          const filePath = await exportStory(story, exportOptions);
          setExportSuccess(true);
          setExportedFilePath(filePath);
        }
      } else {
        // Browser environment or no project - use simple export
        const filePath = await exportStory(story, exportOptions);
        setExportSuccess(true);
        setExportedFilePath(filePath);
        setHasUnsavedChanges(false);
      }
    } catch (error) {
      console.error('Export failed:', error);
      setExportError(error instanceof Error ? error.message : 'Failed to export story');
    } finally {
      setIsExporting(false);
    }
  };

  const generateContent = async (prompt: string, type: 'image' | 'audio' | 'video'): Promise<string | null> => {
    setIsAIProcessing(true);
    try {
      const { llmConfigService } = await import('@/services/llmConfigService');
      const service = llmConfigService.getService();

      if (!service) {
        return null;
      }

      let systemPrompt = '';
      if (type === 'image') systemPrompt = 'You are an expert AI art prompt engineer.';
      if (type === 'audio') systemPrompt = 'You are an expert sound designer and music supervisor.';
      if (type === 'video') systemPrompt = 'You are an expert video director and cinematographer.';

      const response = await service.generateCompletion({
        prompt,
        systemPrompt,
        temperature: 0.7
      });

      if (response.success && response.data) {
        return response.data.content;
      }
      return null;
    } catch (error) {
      console.error(`Failed to generate ${type} prompts`, error);
      return null;
    } finally {
      setIsAIProcessing(false);
    }
  };

  const generateAssetPrompts = async (type: 'image' | 'audio' | 'video') => {
    if (!formData.generatedSummary && !formData.generatedContent) return;

    const context = formData.generatedSummary || formData.generatedContent?.substring(0, 1000) || '';

    let prompt = '';

    switch (type) {
      case 'image':
        prompt = `Based on this story summary, generate 3 detailed Midjourney/DALL-E image prompts for the main scenes/characters: \n\n${context}`;
        break;
      case 'audio':
        prompt = `Based on this story summary, describe the audio atmosphere, creating a prompt for music generation and a list of key sound effects: \n\n${context}`;
        break;
      case 'video':
        prompt = `Based on this story summary, create a prompt for an AI video generator (like Sora/Runway) to create a cinematic trailer for this story: \n\n${context}`;
        break;
    }

    const result = await generateContent(prompt, type);
    if (result) {
      setAssetPrompts(prev => ({ ...prev, [type]: result }));
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const wordCount = formData.generatedContent?.split(' ').length || 0;
  const characterCount = formData.generatedContent?.length || 0;

  return (
    <WizardFormLayout
      title="Review and Export"
      description="Review your story and export it to a file"
    >
      {/* Story Title */}
      <FormField
        label="Story Title"
        name="title"
        helpText="Edit the title if needed"
      >
        <Input
          id="title"
          value={formData.title || ''}
          onChange={handleTitleChange}
          placeholder="Enter story title"
        />
      </FormField>

      {/* Version History */}
      {versions.length > 0 && (
        <div className="space-y-2">
          <Label htmlFor="version-selector" className="flex items-center gap-2">
            <History className="w-4 h-4" />
            Version History
          </Label>
          <div className="flex gap-2">
            <Select
              value={selectedVersionId || 'current'}
              onValueChange={handleLoadVersion}
            >
              <SelectTrigger id="version-selector" className="flex-1">
                <SelectValue placeholder="Select a version" />
              </SelectTrigger>
              <SelectContent className="z-[9999]">
                <SelectItem value="current">
                  Current Version (Latest)
                </SelectItem>
                {versions.map((version) => (
                  <SelectItem key={version.id} value={version.id}>
                    Version {version.versionNumber} - {new Date(version.createdAt).toLocaleString()}
                    {version.changes && ` - ${version.changes}`}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {selectedVersionId && (
              <Button
                variant="outline"
                size="icon"
                onClick={() => handleLoadVersion('current')}
                title="Return to current version"
              >
                <RotateCcw className="w-4 h-4" />
              </Button>
            )}
          </div>
          {selectedVersionId && (
            <p className="text-xs text-amber-600 flex items-center gap-1">
              <AlertCircle className="w-3 h-3" />
              Viewing historical version. Click the reset button to return to current.
            </p>
          )}
        </div>
      )}

      {/* Summary Display */}
      <div className="space-y-2">
        <Label>Summary</Label>
        <div className="p-4 rounded-lg bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800">
          <p className="text-sm text-muted-foreground">
            {formData.generatedSummary || 'No summary available'}
          </p>
        </div>
      </div>

      {/* Story Content (Editable) */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="story-content">Story Content</Label>
          {hasUnsavedChanges && (
            <span className="text-xs text-amber-600 flex items-center gap-1">
              <AlertCircle className="w-3 h-3" />
              Unsaved changes
            </span>
          )}
        </div>
        <Textarea
          id="story-content"
          value={formData.generatedContent || ''}
          onChange={handleContentChange}
          rows={15}
          className="font-mono text-sm"
          placeholder="Story content will appear here..."
        />
        <div className="flex gap-4 text-xs text-muted-foreground">
          <span>📖 {wordCount} words</span>
          <span>🔤 {characterCount} characters</span>
        </div>
      </div>

      {/* Metadata Display */}
      <div className="space-y-2">
        <Label>Story Metadata</Label>
        <div className="p-4 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 space-y-2 text-sm">
          <div className="flex gap-2">
            <span className="font-medium">Genre:</span>
            <span className="text-muted-foreground">{formData.genre?.join(', ') || 'None'}</span>
          </div>
          <div className="flex gap-2">
            <span className="font-medium">Tone:</span>
            <span className="text-muted-foreground">{formData.tone?.join(', ') || 'None'}</span>
          </div>
          <div className="flex gap-2">
            <span className="font-medium">Length:</span>
            <span className="text-muted-foreground">{formData.length || 'medium'}</span>
          </div>
          <div className="flex gap-2">
            <span className="font-medium">Characters:</span>
            <span className="text-muted-foreground">
              {formData.selectedCharacters?.length || 0} selected
            </span>
          </div>
          <div className="flex gap-2">
            <span className="font-medium">Locations:</span>
            <span className="text-muted-foreground">
              {formData.selectedLocations?.length || 0} selected
            </span>
          </div>
        </div>
      </div>

      {/* Story Structure Info */}
      {formData.parts && formData.parts.length > 0 && (
        <div className="space-y-2">
          <Label>LLM-Optimized File Structure</Label>
          <div className="p-4 rounded-lg bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800">
            <p className="text-sm text-green-900 dark:text-green-100 mb-2">
              Story will be saved as separate .md files for optimal LLM processing:
            </p>
            <div className="font-mono text-xs space-y-1 text-green-800 dark:text-green-200">
              <div>story/</div>
              <div className="pl-4">├── story-index.md <span className="text-muted-foreground"># Index & metadata</span></div>
              <div className="pl-4">├── story-intro.md <span className="text-muted-foreground"># Introduction</span></div>
              {formData.parts.filter((p: any) => p.type === 'chapter').map((part: any, i: number) => (
                <div key={part.id} className="pl-4">├── story-chapter-{String(i + 1).padStart(2, '0')}.md <span className="text-muted-foreground"># {part.title}</span></div>
              ))}
              <div className="pl-4">├── story-ending.md <span className="text-muted-foreground"># Conclusion</span></div>
              <div className="pl-4">└── story-summary.md <span className="text-muted-foreground"># Rolling summary</span></div>
            </div>
          </div>
        </div>
      )}

      {/* Export Options */}
      <div className="space-y-4 p-4 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800">
        <h3 className="font-semibold text-sm">Export Options</h3>

        {/* Format Selection */}
        <div className="space-y-2">
          <Label>File Format</Label>
          <div className="p-3 rounded bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800">
            <div className="flex items-center gap-2">
              <span className="font-medium text-blue-900 dark:text-blue-100">Markdown (.md)</span>
              <span className="text-xs text-blue-700 dark:text-blue-300">- LLM-optimized with YAML frontmatter</span>
            </div>
            <p className="text-xs text-blue-600 dark:text-blue-400 mt-1">
              Each part includes metadata for better LLM context understanding
            </p>
          </div>
        </div>

        {/* Filename */}
        <div className="space-y-2">
          <Label htmlFor="export-filename">Filename</Label>
          <Input
            id="export-filename"
            value={exportOptions.filename}
            onChange={(e) => setExportOptions({ ...exportOptions, filename: e.target.value })}
            placeholder="story"
          />
          <p className="text-xs text-muted-foreground">
            Extension will be added automatically
          </p>
        </div>

        {/* Include Options */}
        <div className="space-y-3">
          <div className="flex items-center space-x-2">
            <Checkbox
              id="include-metadata"
              checked={exportOptions.includeMetadata}
              onCheckedChange={(checked) =>
                setExportOptions({ ...exportOptions, includeMetadata: checked as boolean })
              }
            />
            <Label htmlFor="include-metadata" className="text-sm font-normal cursor-pointer">
              Include metadata (genre, tone, characters, locations)
            </Label>
          </div>
          <div className="flex items-center space-x-2">
            <Checkbox
              id="include-summary"
              checked={exportOptions.includeSummary}
              onCheckedChange={(checked) =>
                setExportOptions({ ...exportOptions, includeSummary: checked as boolean })
              }
            />
            <Label htmlFor="include-summary" className="text-sm font-normal cursor-pointer">
              Include story summary
            </Label>
          </div>
        </div>
      </div>

      {/* Export Button */}
      <Button
        onClick={handleExport}
        disabled={isExporting || !formData.generatedContent}
        className="w-full gap-2"
        size="lg"
      >
        <Download className="w-4 h-4" />
        {isExporting ? 'Exporting...' : 'Export Story'}
      </Button>

      {/* Export Success Message */}
      {exportSuccess && (
        <div className="p-4 rounded-lg bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800">
          <div className="flex items-center gap-2 text-green-900 dark:text-green-100">
            <CheckCircle className="w-5 h-5" />
            <div>
              <p className="font-semibold">Export Successful!</p>
              {exportedFilePath && (
                <p className="text-sm mt-1">File saved: {exportedFilePath}</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Export Error Message */}
      {exportError && (
        <div className="p-4 rounded-lg bg-red-50 dark:bg-red-950/20 border border-red-200 dark:border-red-800">
          <div className="flex items-center gap-2 text-red-900 dark:text-red-100">
            <AlertCircle className="w-5 h-5" />
            <div>
              <p className="font-semibold">Export Failed</p>
              <p className="text-sm mt-1">{exportError}</p>
            </div>
          </div>
        </div>
      )}

      {/* Info Box */}
      <div className="bg-blue-50 dark:bg-blue-950/20 p-4 rounded-md">
        <p className="text-sm text-blue-900 dark:text-blue-100">
          💡 <strong>Tip:</strong> You can edit the story content before exporting.
          Changes will be saved when you complete the wizard.
        </p>
      </div>
    </WizardFormLayout>
  );
}

import React, { useCallback, useState, useEffect } from 'react';
import { WizardProvider, useWizard } from '@/contexts/WizardContext';
import { ProductionWizardContainer as WizardContainer } from '../production-wizards/ProductionWizardContainer';
import type { WizardStep } from '@/types';
import type { Story } from '@/types/story';
import { createEmptyStory } from '@/types/story';
import { useStore } from '@/store';
import { Step1StorySetup } from './Step1StorySetup';
import { Step2CharacterSelection } from './Step2CharacterSelection';
import { Step3LocationSelection } from './Step3LocationSelection';
import { Step4StoryGeneration } from './Step4StoryGeneration';
import { Step5ReviewExport } from './Step5ReviewExport';
import { saveStoryToDisk, saveScenarioToDisk } from '@/utils/storyFileIO';
import { toast } from '@/utils/toast';
import { Button } from '@/components/ui/button';
import { FileText, Plus, RefreshCw, Save, FileSpreadsheet, Book, Users, MapPin, Sparkles, ClipboardCheck } from 'lucide-react';

// ============================================================================
// Storyteller Wizard Component - Updated to use hasSavedProgress
// ============================================================================

export interface StorytellerWizardProps {
  onComplete: (story: Story) => void;
  onCancel: () => void;
  initialData?: Partial<Story>;
}

const WIZARD_STEPS: WizardStep[] = [
  { number: 1, title: 'Epic Design', description: 'Genre, tone, and length', icon: Book },
  { number: 2, title: 'Casting', description: 'Select or create', icon: Users },
  { number: 3, title: 'Environment', description: 'Select or create', icon: MapPin },
  { number: 4, title: 'Synthesis', description: 'AI story creation', icon: Sparkles },
  { number: 5, title: 'Validation', description: 'Finalize and save', icon: ClipboardCheck },
];

// ============================================================================
// Storyteller Wizard Content
// ============================================================================

interface StorytellerWizardContentProps {
  steps: WizardStep[];
  onCancel: () => void;
  renderStepContent: (step: number) => React.ReactNode;
}

function StorytellerWizardContent({ steps, onCancel, renderStepContent }: StorytellerWizardContentProps) {
  const { currentStep } = useWizard();

  return (
    <WizardContainer
      title="Narrative Synthesis Engine"
      steps={steps}
      onCancel={onCancel}
      allowJumpToStep={false}
      showAutoSaveIndicator={true}
    >
      {renderStepContent(currentStep)}
    </WizardContainer>
  );
}

// ============================================================================
// Continue Dialog Component - Shown when hasSavedProgress() returns true
// ============================================================================

interface ContinueDialogProps {
  onContinuePrevious: () => void;
  onStartFresh: () => void;
  isLoading: boolean;
}

function ContinueDialog({ onContinuePrevious, onStartFresh, isLoading }: ContinueDialogProps) {
  return (
    <div className="flex items-center justify-center h-[500px]">
      <div className="text-center p-8 max-w-md cyber-card bg-card/50 backdrop-blur-md border-primary/20">
        <FileText className="w-16 h-16 mx-auto mb-4 text-primary neon-text" />
        <h2 className="text-2xl font-bold mb-2 neon-text text-primary italic uppercase tracking-wider">Session Persistence Detected</h2>
        <p className="text-primary-foreground/70 mb-6 font-medium">
          A previous narrative blueprint was found in the buffer. Resume synthesis or initialize a fresh sequence?
        </p>
        <div className="flex gap-4 justify-center">
          <Button onClick={onContinuePrevious} className="gap-2 btn-neon bg-primary/20 text-primary hover:bg-primary/30" disabled={isLoading}>
            {isLoading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
            Resume Blueprint
          </Button>
          <Button onClick={onStartFresh} variant="outline" className="gap-2 border-primary/30 text-primary hover:bg-primary/10" disabled={isLoading}>
            <Plus className="w-4 h-4" />
            Clear & Restart
          </Button>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// Storyteller Wizard Inner - Has access to wizard context via useWizard()
// ============================================================================

interface StorytellerWizardInnerProps {
  steps: WizardStep[];
  onCancel: () => void;
  renderStepContent: (step: number) => React.ReactNode;
}

function StorytellerWizardInner({ steps, onCancel, renderStepContent }: StorytellerWizardInnerProps) {
  const { hasSavedProgress, loadProgress, clearSavedProgress } = useWizard();
  const [showContinueDialog, setShowContinueDialog] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [wizardReady, setWizardReady] = useState(false);

  // Check for saved progress on mount using hasSavedProgress()
  useEffect(() => {
    if (hasSavedProgress()) {
      setShowContinueDialog(true);
    } else {
      setWizardReady(true);
    }
  }, [hasSavedProgress]);

  // Handle continue previous - call loadProgress() manually
  const handleContinuePrevious = useCallback(() => {
    setIsLoading(true);
    try {
      loadProgress();
      setShowContinueDialog(false);
      setWizardReady(true);
      toast.success('Progress Loaded', 'Your previous progress has been restored');
    } catch (error) {
      console.error('Failed to load progress:', error);
      toast.error('Load Failed', 'Failed to load saved progress');
    } finally {
      setIsLoading(false);
    }
  }, [loadProgress]);

  // Handle start fresh - call clearSavedProgress()
  const handleStartFresh = useCallback(() => {
    try {
      clearSavedProgress();
      setShowContinueDialog(false);
      setWizardReady(true);
    } catch (error) {
      console.error('Failed to clear progress:', error);
      // Still proceed even if clear fails
      setShowContinueDialog(false);
      setWizardReady(true);
    }
  }, [clearSavedProgress]);

  // Show continue dialog if hasSavedProgress() returned true
  if (showContinueDialog) {
    return (
      <ContinueDialog
        onContinuePrevious={handleContinuePrevious}
        onStartFresh={handleStartFresh}
        isLoading={isLoading}
      />
    );
  }

  // Show loading state while initializing
  if (!wizardReady) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <RefreshCw className="w-12 h-12 mx-auto mb-4 animate-spin" />
          <p className="text-muted-foreground">Initializing wizard...</p>
        </div>
      </div>
    );
  }

  return (
    <StorytellerWizardContent
      steps={steps}
      onCancel={onCancel}
      renderStepContent={renderStepContent}
    />
  );
}

// ============================================================================
// Main Storyteller Wizard Component
// ============================================================================

export function StorytellerWizard({ onComplete, onCancel, initialData }: StorytellerWizardProps) {
  const addStory = useStore((state) => state.addStory);
  const currentProject = useStore((state) => state.project);

  const getInitialStoryData = useCallback((): Partial<Story> => {
    const baseData = initialData || createEmptyStory();

    if (currentProject?.metadata) {
      const projectMeta = currentProject.metadata;
      return {
        ...baseData,
        genre: (projectMeta.genre as string[]) || baseData.genre,
        tone: (projectMeta.tone as string[]) || baseData.tone,
        length: projectMeta.projectType === 'court-metrage' ? 'scene' :
          projectMeta.projectType === 'moyen-metrage' ? 'short_story' :
            projectMeta.projectType === 'long-metrage-standard' ? 'novella' :
              projectMeta.projectType === 'long-metrage-premium' ? 'novel' :
                projectMeta.projectType === 'tres-long-metrage' ? 'epic_novel' :
                  baseData.length,
      };
    }
    return baseData;
  }, [currentProject, initialData]);

  const validateStep = useCallback(
    async (step: number, data: Record<string, unknown>): Promise<Record<string, string[]>> => {
      const errors: Record<string, string[]> = {};

      switch (step) {
        case 1:
          // Allow empty - will use project defaults
          break;
        case 2:
        case 3:
          break;
        case 4:
          break;
        case 5:
          if (!data.generatedContent || (data.generatedContent as string).trim() === '') {
            errors.content = ['Story content is required'];
          }
          if (!data.generatedSummary || (data.generatedSummary as string).trim() === '') {
            errors.summary = ['Story summary is required'];
          }
          break;
      }
      return errors;
    },
    []
  );

  const handleSubmit = useCallback(
    async (data: Record<string, unknown>) => {
      const selectedChars = (data.selectedCharacters as Array<{ id: string }>) || [];
      const characterRefs = selectedChars.map(c => ({ id: c.id })) as Story['charactersUsed'];
      const selectedLocs = (data.selectedLocations as Array<{ id: string; name: string }>) || [];
      const locationRefs = selectedLocs.map(l => ({ id: l.id, name: l.name, significance: 'present' })) as Story['locationsUsed'];

      const now = Date.now();
      const story: Story = {
        id: crypto.randomUUID(),
        title: (data.title as string) || 'Untitled Story',
        content: (data.generatedContent as string) || '',
        summary: (data.generatedSummary as string) || '',
        genre: (data.genre as string[]) || [],
        tone: (data.tone as string[]) || [],
        length: (data.length as Story['length']) || 'medium',
        charactersUsed: characterRefs,
        locationsUsed: locationRefs,
        autoGeneratedElements: (data.autoGeneratedElements as Story['autoGeneratedElements']) || [],
        createdAt: now,
        updatedAt: now,
        version: 1,
        worldId: data.worldId as string | undefined,
        parts: data.parts as Story['parts'],
        fileFormat: 'md',
      };

      addStory(story);

      // Save story to disk if Electron API is available and project has a valid path
      const projectPath = currentProject?.path || currentProject?.project_name;
      if (window.electronAPI?.fs && projectPath) {
        try {
          console.log('[StorytellerWizard] Saving story to disk at path:', projectPath);

          // Save story files (index, parts, summary, etc.)
          await saveStoryToDisk(projectPath, story);

          // Generate and save scenario.md for video/film production
          try {
            await saveScenarioToDisk(projectPath, story);
            toast.success('Story Saved', 'Story files and scenario saved to disk');
          } catch (scenarioError) {
            console.warn('[StorytellerWizard] Scenario save failed, but story saved:', scenarioError);
            toast.success('Story Saved', 'Story files saved (scenario generation failed)');
          }
        } catch (error) {
          console.error('[StorytellerWizard] Failed to save story to disk:', error);
          toast.error('Save Failed', 'Failed to save story to disk');
        }
      } else {
        console.warn('[StorytellerWizard] Cannot save to disk - missing project path or Electron API');
        // Story is still saved to store (addStory was called above)
        toast.info('Story Created', 'Story saved to application state');
      }

      window.dispatchEvent(new CustomEvent('story-created', { detail: { story } }));
      onComplete(story);
    },
    [onComplete, addStory, currentProject]
  );

  const renderStepContent = (currentStep: number) => {
    switch (currentStep) {
      case 1: return <Step1StorySetup />;
      case 2: return <Step2CharacterSelection />;
      case 3: return <Step3LocationSelection />;
      case 4: return <Step4StoryGeneration />;
      case 5: return <Step5ReviewExport />;
      default: return null;
    }
  };

  return (
    <WizardProvider
      wizardType="storyteller"
      totalSteps={5}
      initialData={getInitialStoryData()}
      onSubmit={handleSubmit as (data: unknown) => Promise<void>}
      onValidateStep={validateStep as (step: number, data: unknown) => Promise<Record<string, string[]>>}
      autoSave={true}
      autoSaveDelay={2000}
      autoLoad={false}
    >
      <StorytellerWizardInner
        steps={WIZARD_STEPS}
        onCancel={onCancel}
        renderStepContent={renderStepContent}
      />
    </WizardProvider>
  );
}

