    onUpdate({ ...data, genre });
  };

  const handleToneChange = (tone: string[]) => {
    onUpdate({ ...data, tone });
  };

  return (
    <div className="space-y-6">
      {/* Presets Grid */}
      <div>
        <h3 className="text-lg font-semibold mb-3 flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-amber-500" />
