        </h3>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
          {/* Start Fresh Option */}
          <button
            onClick={() => {
              setSelectedPreset(null);
              onApplyPreset({
                id: 'fresh',
                name: 'Fresh Start',
                description: 'Start with a blank world',
                genre: [],
                tone: [],
                locations: [],
                rules: [],
