export function WorldBuilderWizard({
  onComplete,
  onCancel,
  initialData,
}: WorldBuilderWizardProps) {
  // State
  const [currentStep, setCurrentStep] = useState(1);
  const [data, setData] = useState<Partial<World>>(initialData || {});
  const addWorld = useStore((state) => state.addWorld);
  
  // Get saveWorld function from persistence hook
  const { saveWorld } = useWorldPersistence();

  // Steps definition
  const steps: WizardStep[] = [
    { number: 1, title: 'Quick Setup', description: 'Presets & basics' },
    { number: 2, title: 'Locations & Rules', description: 'Build your world' },
    { number: 3, title: 'Culture & Review', description: 'Finalize' },
  ];

  // Data update
  const updateData = useCallback((newData: Partial<World>) => {
    setData((prev) => ({ ...prev, ...newData }));
  }, []);

  // Location management
  const addLocation = useCallback(() => {
    const newLocation: Location = {
      id: crypto.randomUUID(),
      name: '',
      description: '',
      significance: '',
      atmosphere: '',
    };
    updateData({
      locations: [...(data.locations || []), newLocation],
    });
  }, [data.locations, updateData]);

  const removeLocation = useCallback((id: string) => {
    updateData({
      locations: data.locations?.filter((l) => l.id !== id) || [],
    });
  }, [data.locations, updateData]);

  // Rule management
  const addRule = useCallback(() => {
    const newRule: WorldRule = {
      id: crypto.randomUUID(),
      category: 'physical',
      rule: '',
      implications: '',
    };
    updateData({
      rules: [...(data.rules || []), newRule],
    });
  }, [data.rules, updateData]);

  const removeRule = useCallback((id: string) => {
    updateData({
      rules: data.rules?.filter((r) => r.id !== id) || [],
    });
  }, [data.rules, updateData]);

  // Apply preset
  const applyPreset = useCallback((preset: WorldPreset) => {
    setData({
      name: preset.name,
      genre: preset.genre,
      tone: preset.tone,
      locations: preset.locations.map((l) => ({
        id: crypto.randomUUID(),
        name: l.name || '',
        description: l.description || '',
        significance: l.significance || '',
        atmosphere: l.atmosphere || '',
      })),
      rules: preset.rules.map((r) => ({
        id: crypto.randomUUID(),
        category: r.category || 'physical',
        rule: r.rule || '',
        implications: r.implications || '',
      })),
      culturalElements: {
        languages: preset.culturalElements.languages || [],
        religions: preset.culturalElements.religions || [],
        traditions: preset.culturalElements.traditions || [],
        historicalEvents: [],
        culturalConflicts: [],
      },
    });
  }, []);

  // Navigation
  const canGoNext = useMemo(() => {
    if (currentStep === 1) {
      return data.name && data.name.trim() !== '';
    }
    return true;
  }, [currentStep, data.name]);

  const canGoBack = currentStep > 1;

  const handleNext = useCallback(() => {
    if (currentStep < 3) {
      setCurrentStep((prev) => prev + 1);
    }
  }, [currentStep]);

  const handleBack = useCallback(() => {
    if (currentStep > 1) {
      setCurrentStep((prev) => prev - 1);
    }
  }, [currentStep]);

  const handleComplete = useCallback(async () => {
    const world: World = {
      id: crypto.randomUUID(),
      name: data.name || 'Unnamed World',
      genre: data.genre || [],
      timePeriod: data.timePeriod || 'Unknown',
      tone: data.tone || [],
      locations: data.locations || [],
      rules: data.rules || [],
      atmosphere: data.atmosphere || '',
      culturalElements: data.culturalElements || {
        languages: [],
        religions: [],
        traditions: [],
        historicalEvents: [],
        culturalConflicts: [],
      },
      technology: data.technology || '',
      magic: data.magic || '',
      conflicts: data.conflicts || [],
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Add to store first
    addWorld(world);
    
    // Then save to project directory
    try {
      await saveWorld(world);
    } catch (error) {
      console.error('[WorldBuilderWizard] Failed to save world to project:', error);
      // World is already in store, so we still call onComplete
    }
    
    onComplete(world);
  }, [data, addWorld, saveWorld, onComplete]);

  // Render current step
  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <Step1QuickSetup
            data={data}
            onUpdate={updateData}
            presets={WORLD_PRESETS}
            onApplyPreset={applyPreset}
          />
        );
      case 2:
        return (
          <Step2LocationsRules
            data={data}
            onUpdate={updateData}
            onAddLocation={addLocation}
            onRemoveLocation={removeLocation}
            onAddRule={addRule}
            onRemoveRule={removeRule}
          />
        );
      case 3:
        return (
          <Step3CultureReview
            data={data}
            onUpdate={updateData}
            onComplete={handleComplete}
          />
        );
      default:
        return null;
    }
  };

  return (
    <WizardErrorBoundary
      wizardType="world"
      onReset={() => {
        setCurrentStep(1);
        setData({});
      }}
    >
      <div className="wizard-builder p-6">
        {/* Header */}
        <div className="mb-6">
          <h2 className="text-2xl font-bold mb-2">Create Your World</h2>
          <p className="text-gray-500">Choose a preset or start fresh, then build your world.</p>
        </div>

        {/* Step Indicator */}
        <div className="mb-6">
          <WizardStepIndicator
            steps={steps}
            currentStep={currentStep}
            allowJumpToStep={false}
          />
        </div>

        {/* Content */}
        <div className="mb-6">
          {renderStep()}
        </div>

        {/* Navigation */}
        <div className="flex justify-between">
          <button
            onClick={onCancel}
            className="px-4 py-2 text-gray-600 hover:text-gray-800"
          >
            Cancel
          </button>
          <div className="flex gap-2">
            {currentStep > 1 && (
              <button
                onClick={handleBack}
                className="px-4 py-2 border rounded-lg hover:bg-gray-50"
              >
                Back
              </button>
            )}
            {currentStep < 3 ? (
              <button
                onClick={handleNext}
                disabled={!canGoNext}
                className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50"
              >
                Next
              </button>
            ) : null}
          </div>
        </div>
      </div>
    </WizardErrorBoundary>
  );
}

