export const ProjectResumeSection: React.FC<ProjectResumeSectionProps> = ({ className }) => {
    const project = useAppStore((state: unknown) => state.project);
    const shots = useAppStore((state: unknown) => state.shots);
    const ollamaStatus = useAppStore((state: unknown) => state.ollamaStatus);
    const characters = useStore((state: unknown) => state.characters);
    const { showSuccess, showError, showInfo } = useNotifications();

    const [resume, setResume] = useState<string>('');
    const [isEditing, setIsEditing] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // Sync with project data
    useEffect(() => {
        if (project?.global_resume) {
            setResume(project.global_resume);
        } else if (project?.metadata?.description) {
            setResume(project.metadata.description);
        }
    }, [project]);

    const handleSave = async () => {
        if (!project) return;
        setIsSaving(true);
        try {
            // In a real app, this would call ProjectService.updateGlobalResume
            // For now, we update the store and simulate persistence
            const updatedProject = {
                ...project,
                global_resume: resume,
                metadata: {
                    ...project.metadata,
                    description: resume // Keep them in sync
                }
            };

            useAppStore.getState().setProject(updatedProject);

            // If Electron, save to disk
            if (window.electronAPI && project.metadata?.path) {
                try {
                    const projectData = JSON.stringify(updatedProject, null, 2);
                    await window.electronAPI.fs.writeFile(`${project.metadata.path}/project.json`, projectData);
                } catch (err) {
                    console.error('Failed to save project.json:', err);
                }
            }

            showSuccess('Resume Saved', 'Project summary has been updated.');
            setIsEditing(false);
        } catch (error) {
            showError('Save Failed', 'Could not save the resume.');
        } finally {
            setIsSaving(false);
        }
    };

    const handleGenerate = async () => {
        if (ollamaStatus !== 'connected') {
            showError('Ollama Offline', 'Please connect Ollama to generate a resume.');
            return;
        }

        setIsGenerating(true);
        try {
            const models = await ollamaClient.listModels();
            const model = models.find(m => m.category === 'storytelling' || m.name.includes('llama'))?.name || models[0]?.name;

            if (!model) throw new Error('No suitable LLM model found');

            const context = {
                name: project?.metadata?.name || 'Untitled',
                genre: project?.metadata?.genre || 'Not specified',
                characters: characters?.map((c: unknown) => `${c.name} (${c.role?.archetype || c.archetype || 'Unnamed Archetype'})`).join(', ') || 'None',
                sequences: shots?.length || 0,
            };

            const prompt = `You are a creative director. Summarize the following project into a compelling, high-level "Creative Resume" (3-5 sentences).
      
      Project Name: ${context.name}
      Genre: ${context.genre}
      Characters: ${context.characters}
      Current Progress: ${context.sequences} scenes planned.
      
      Output only the resume text. Make it sound professional and inspiring.`;

            const result = await ollamaClient.generate(model, prompt);
            setResume(result.trim());
            setIsEditing(true); // Open for review
            showInfo('Resume Generated', 'AI has created a summary based on your project data.');
        } catch (error) {
            showError('Generation Failed', error instanceof Error ? error.message : 'AI could not generate the resume.');
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className={`project-resume-section ${className || ''}`}>
            <div className="section-header">
                <div className="flex items-center gap-2">
                    <BookOpen className="w-5 h-5 text-primary" />
                    <h3>Project Creative Resume</h3>
                </div>
                <div className="header-actions">
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={handleGenerate}
                        disabled={isGenerating || ollamaStatus !== 'connected'}
                        className="gap-2"
                    >
                        {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        Generate with AI
                    </Button>
                    {!isEditing ? (
                        <Button variant="ghost" size="sm" onClick={() => setIsEditing(true)}>
                            <Edit3 className="w-4 h-4" />
                        </Button>
                    ) : (
                        <Button variant="ghost" size="sm" onClick={handleSave} disabled={isSaving}>
                            {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        </Button>
                    )}
                </div>
            </div>

            <div className="resume-body">
                {isEditing ? (
                    <textarea
                        className="resume-textarea"
                        value={resume}
                        onChange={(e) => setResume(e.target.value)}
                        placeholder="Describe your story and project vision here..."
                    />
                ) : (
                    <p className="resume-text">
                        {resume || "No resume yet. Use the 'Generate with AI' button to create one from your project data."}
                    </p>
                )}
            </div>
        </div>
    );
};

/**
 * Project Workspace Component
 * 
 * Main workspace view displaying project tools, status, and wizard launchers
 */

import React, { useState } from 'react';
import type { ProjectWorkspaceProps } from '../../types/configuration';
import { useActiveProject } from '../../hooks/useConfigurationHooks';
import { WizardLauncher } from '@/components/wizard/WizardLauncher';
import { GhostTrackerWizard } from '@/components/wizard/GhostTrackerWizard';
import { WIZARD_DEFINITIONS } from '../../data/wizardDefinitions';
import { useAppStore } from '../../stores/useAppStore';
import { useEditorStore } from '../../stores/editorStore';
import { useSequencePlanStore } from '../../stores/sequencePlanStore';
import { useToast } from '../../hooks/use-toast';
import { logger } from '../../utils/logging';
import './ProjectWorkspace.css';

export function ProjectWorkspace({
  projectId,
  projectName,
  onOpenSettings,
}: Readonly<ProjectWorkspaceProps>) {
  const activeProject = useActiveProject();
  const openWizard = useAppStore((state) => state.openWizard);
  const setShowWorldWizard = useAppStore((state) => state.setShowWorldWizard);
  const setShowCharacterWizard = useAppStore((state) => state.setShowCharacterWizard);
  const setShowStorytellerWizard = useAppStore((state) => state.setShowStorytellerWizard);
  const setShowProjectSetupWizard = useAppStore((state) => state.setShowProjectSetupWizard);
  const openSequencePlanWizard = useAppStore((state) => state.openSequencePlanWizard);
  const setShowDialogueWriter = useAppStore((state) => state.setShowDialogueWriter);
  const projectPath = useEditorStore((state) => state.projectPath);
  const currentProject = useEditorStore((state) => state.currentProject);

  // Sequence plan data
  const sequences = useSequencePlanStore((state) => state.plans);
  const shots = useSequencePlanStore((state) => state.currentPlanData?.shots || []);

  // Toast hook
  const { toast } = useToast();

  // Handle wizard launch
  const handleLaunchWizard = (wizardId: string) => {
    // Get the closeActiveWizard function from store
    const closeActiveWizard = useAppStore.getState().closeActiveWizard;

    // Close ALL wizards first (mutual exclusion)
    closeActiveWizard();

    // Map wizard IDs to appropriate wizard openers
    // Multi-step wizards (world, character) use separate modals
    // Simple form wizards use GenericWizardModal
    switch (wizardId) {
      case 'project-init':
        setShowProjectSetupWizard(true);
        break;
      case 'world-building':
        setShowWorldWizard(true);
        break;
      case 'character-creation':
        setShowCharacterWizard(true);
        break;
      case 'storyteller-wizard':
        setShowStorytellerWizard(true);
        break;
      case 'scene-generator':
        openWizard('scene-generator');
        break;
      case 'storyboard-creator':
        openWizard('storyboard-creator');
        break;
      case 'dialogue-writer':
      case 'dialogue-wizard':
        useEditorStore.getState().openWizard('dialogue-writer', 1);
        break;
      case 'style-transfer':
        openWizard('style-transfer');
        break;
      case 'shot-planning':
        openSequencePlanWizard();
        break;
      case 'ghost-tracker-wizard':
        // Ghost Tracker Wizard is available via the Wizards section
        toast({
          title: 'Ghost Tracker Wizard',
          description: 'Access the Ghost Tracker Wizard from the Wizards section.',
          variant: 'default',
        });
        break;
      default:
        logger.warn(`Unknown wizard type: ${wizardId}`);
        toast({
          title: 'Wizard Not Implemented',
          description: `Wizard "${wizardId}" is not yet implemented.`,
          variant: 'default',
        });
    }
  };

  // Handle opening project files in system file explorer
  const handleOpenProjectFiles = async () => {
    try {
      if (!projectPath) {
        toast({
          title: 'No Project Loaded',
          description: 'No project is currently loaded.',
          variant: 'destructive',
        });
        return;
      }

      const electronAPI = window.electronAPI as typeof window.electronAPI;
      if (!electronAPI?.app?.openFolder) {
        toast({
          title: 'File Explorer Not Available',
          description: 'File explorer integration is not available in this environment.',
          variant: 'default',
        });
        return;
      }

      await electronAPI.app.openFolder(projectPath);
    } catch (error) {
      logger.error('Failed to open project folder:', error);
      toast({
        title: 'Failed to Open Folder',
        description: 'Failed to open project folder. Please check if the project path is valid.',
        variant: 'destructive',
      });
    }
  };

  // Handle opening Grid Editor
  const handleOpenGridEditor = () => {
    // Navigate to editor page with grid view
    globalThis.location.href = '/editor?view=grid';
  };

  // Handle analytics dashboard
  const handleOpenAnalytics = () => {
    toast({
      title: 'Coming Soon',
      description: 'Analytics dashboard will be available in a future update.',
      variant: 'default',
    });
  };

  // Handle export functionality
  const handleExport = async () => {
    try {
      if (!currentProject) {
        toast({
          title: 'No Project Loaded',
          description: 'No project is currently loaded.',
          variant: 'destructive',
        });
        return;
      }

      // Check if there's content to export
      const hasShots = currentProject.storyboard && currentProject.storyboard.length > 0;
      const hasAssets = currentProject.assets && currentProject.assets.length > 0;
      const hasSequences = shots && shots.length > 0;

      if (!hasShots && !hasAssets && !hasSequences) {
        toast({
          title: 'Nothing to Export',
          description: 'Project has no content to export. Please generate some shots, add assets, or create sequences first.',
          variant: 'destructive',
        });
        return;
      }

      // Create comprehensive export data
      const exportData = {
        project: {
          id: projectId,
          name: projectName,
          exportedAt: new Date().toISOString(),
          version: '1.0.0',
          format: 'StoryCore Project Export',
        },
        metadata: {
          totalShots: currentProject.storyboard?.length || 0,
          totalAssets: currentProject.assets?.length || 0,
          totalSequences: sequences?.length || 0,
          totalSequenceShots: shots?.length || 0,
        },
        content: {
          shots: currentProject.storyboard || [],
          assets: currentProject.assets || [],
          sequences: sequences || [],
          sequenceShots: shots || [],
        },
        settings: {
          theme: 'dark', // Could be made dynamic
          neonEffects: true,
          exportTimestamp: Date.now(),
        }
      };

      // Create downloadable JSON file
      const dataStr = JSON.stringify(exportData, null, 2);
      const dataBlob = new Blob([dataStr], { type: 'application/json' });

      const link = document.createElement('a');
      link.href = URL.createObjectURL(dataBlob);
      link.download = `${projectName.replaceAll(/[^a-zA-Z0-9]/g, '_')}_export_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(link.href);

      toast({
        title: 'Project Exported Successfully',
        description: `Exported ${exportData.metadata.totalShots} shots, ${exportData.metadata.totalAssets} assets, and ${exportData.metadata.totalSequences} sequences.`,
      });

    } catch (error) {
      logger.error('Failed to export project:', error);
      toast({
        title: 'Export Failed',
        description: 'Failed to export project. Please check the console for details.',
        variant: 'destructive',
      });
    }
  };

  // Handle settings navigation
  const handleOpenProjectSettings = () => {
    onOpenSettings('api');
  };

  return (
    <div className="project-workspace">
      {/* Project Header */}
      <div className="project-header">
        <div className="project-info">
          <h1 className="project-name">{projectName}</h1>
          <div className="project-meta">
            <span className="project-id">ID: {projectId}</span>
            {activeProject && (
              <>
                <span className="separator">•</span>
                <span className={`project-status status-${activeProject.status}`}>
                  {activeProject.status}
                </span>
                <span className="separator">•</span>
                <span className="project-modified">
                  Modified: {new Date(activeProject.lastModified).toLocaleString()}
                </span>
              </>
            )}
          </div>
        </div>

        <div className="project-actions">
          <button
            className="settings-button"
            onClick={() => onOpenSettings('api')}
            title="API Settings"
          >
            🔌 API
          </button>
          <button
            className="settings-button general"
            onClick={() => onOpenSettings('llm')}
            title="LLM Settings"
          >
            ⚙️ General
          </button>
          {/*
            LLM and ComfyUI configuration removed to avoid conflicts.
            Use Settings menu (top bar) > LLM Configuration / ComfyUI Configuration
          */}
          <div className="settings-info-badge" title="Use Settings menu for LLM and ComfyUI configuration">
            💡 Use Settings menu for LLM & ComfyUI
          </div>
        </div>
      </div>

      {/* Pipeline Status */}
      <div className="pipeline-status">
        <h3>Pipeline Status</h3>
        <div className="status-grid">
          <div className="status-card">
            <div className="status-icon">📝</div>
            <div className="status-info">
              <div className="status-label">Script</div>
              <div className="status-value">Ready</div>
            </div>
          </div>

          <div className="status-card">
            <div className="status-icon">🎬</div>
            <div className="status-info">
              <div className="status-label">Scenes</div>
              <div className="status-value">0 generated</div>
            </div>
          </div>

          <div className="status-card">
            <div className="status-icon">🖼️</div>
            <div className="status-info">
              <div className="status-label">Images</div>
              <div className="status-value">0 generated</div>
            </div>
          </div>

          <div className="status-card">
            <div className="status-icon">🎵</div>
            <div className="status-info">
              <div className="status-label">Audio</div>
              <div className="status-value">Not started</div>
            </div>
          </div>
        </div>
      </div>

      {/* Wizard Launcher */}
      <WizardLauncher
        availableWizards={WIZARD_DEFINITIONS}
        onLaunchWizard={handleLaunchWizard}
      />

      {/* Quick Access */}
      <div className="quick-access">
        <h3>Quick Access</h3>
        <div className="quick-access-grid">
          <button
            className="quick-access-card"
            onClick={handleOpenProjectFiles}
            title="Open project folder in file explorer"
          >
            <div className="quick-access-icon">📁</div>
            <div className="quick-access-label">Project Files</div>
          </button>

          <button
            className="quick-access-card"
            onClick={handleOpenGridEditor}
            title="Open Master Coherence Sheet Editor (3x3 Grid)"
          >
            <div className="quick-access-icon">🎨</div>
            <div className="quick-access-label">Grid Editor</div>
          </button>

          <button
            className="quick-access-card"
            onClick={handleOpenAnalytics}
            title="View project analytics and statistics"
          >
            <div className="quick-access-icon">📊</div>
            <div className="quick-access-label">Analytics</div>
          </button>

          <button
            className="quick-access-card"
            onClick={handleExport}
            title="Export project content"
          >
            <div className="quick-access-icon">📤</div>
            <div className="quick-access-label">Export</div>
          </button>

          <button
            className="quick-access-card"
            onClick={handleOpenProjectSettings}
            title="Open project settings"
          >
            <div className="quick-access-icon">⚙️</div>
            <div className="quick-access-label">Settings</div>
          </button>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="recent-activity">
        <h3>Recent Activity</h3>
        <div className="activity-list">
          <div className="activity-item">
            <div className="activity-icon">✅</div>
            <div className="activity-content">
              <div className="activity-title">Project created</div>
              <div className="activity-time">
                {activeProject && new Date(activeProject.createdAt).toLocaleString()}
              </div>
            </div>
          </div>

          <div className="activity-item">
            <div className="activity-icon">⚙️</div>
            <div className="activity-content">
              <div className="activity-title">Configuration initialized</div>
              <div className="activity-time">Just now</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default ProjectWorkspace;

// Ghost Tracker Wizard Modal
function GhostTrackerWizardModal({
  isOpen,
  onClose,
  projectPath
}: Readonly<{
  isOpen: boolean;
  onClose: () => void;
  projectPath?: string;
}>) {
  return (
    <div className={`ghost-tracker-modal ${isOpen ? 'open' : ''}`} role="dialog" aria-modal="true">
      <div
        className="ghost-tracker-modal-overlay"
        onClick={onClose}
        onKeyDown={(e) => { if (e.key === 'Escape') onClose(); }}
        role="button"
        tabIndex={0}
        aria-label="Close modal"
      />
      <div className="ghost-tracker-modal-content">
        <button className="modal-close" onClick={onClose} aria-label="Close">×</button>
        <GhostTrackerWizard isOpen={isOpen} onClose={onClose} projectPath={projectPath} />
      </div>
    </div>
  );
}

/**
 * Sequence Edit Modal Component
 * 
 * Modal for editing sequence properties:
 * - Order number
 * - Duration
 * - Number of shots
 * - Resume/description
 */

import { useState, useEffect } from 'react';
import { X, Save } from 'lucide-react';
import './SequenceEditModal.css';

interface SequenceEditModalProps {
  sequence: {
    id: string;
    name: string;
    order: number;
    duration: number;
    shots: number;
    resume: string;
  };
  onSave: (updatedSequence: {
    id: string;
    order: number;
    duration: number;
    shots: number;
    resume: string;
  }) => void;
  onClose: () => void;
}

export function SequenceEditModal({
  sequence,
  onSave,
  onClose,
}: SequenceEditModalProps) {
  const [order, setOrder] = useState(sequence.order);
  const [duration, setDuration] = useState(sequence.duration);
  const [shots, setShots] = useState(sequence.shots);
  const [resume, setResume] = useState(sequence.resume);

  // Handle save
  const handleSave = () => {
    onSave({
      id: sequence.id,
      order,
      duration,
      shots,
      resume,
    });
    onClose();
  };

  // Handle keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      } else if (e.key === 'Enter' && e.ctrlKey) {
        handleSave();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [order, duration, shots, resume]);

  return (
    <div className="sequence-edit-modal-overlay" onClick={onClose}>
      <div className="sequence-edit-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Éditer Séquence: {sequence.name}</h2>
          <button className="btn-close" onClick={onClose} aria-label="Fermer">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="modal-body">
          <div className="form-group">
            <label htmlFor="order">Numéro d'ordre</label>
            <input
              id="order"
              type="number"
              min="1"
              value={order}
              onChange={(e) => setOrder(parseInt(e.target.value) || 1)}
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="duration">Durée (secondes)</label>
            <input
              id="duration"
              type="number"
              min="0"
              step="0.1"
              value={duration}
              onChange={(e) => setDuration(parseFloat(e.target.value) || 0)}
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="shots">Nombre de plans</label>
            <input
              id="shots"
              type="number"
              min="1"
              value={shots}
              onChange={(e) => setShots(parseInt(e.target.value) || 1)}
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="resume">Résumé</label>
            <textarea
              id="resume"
              value={resume}
              onChange={(e) => setResume(e.target.value)}
              className="form-textarea"
              rows={4}
              maxLength={500}
            />
            <span className="char-count">{resume.length}/500 caractères</span>
          </div>
        </div>

        <div className="modal-footer">
          <button className="btn-cancel" onClick={onClose}>
            Annuler
          </button>
          <button className="btn-save" onClick={handleSave}>
            <Save className="w-4 h-4" />
            <span>Enregistrer</span>
          </button>
        </div>

        <div className="modal-hint">
          <p>Astuce: Appuyez sur Ctrl+Enter pour enregistrer, Échap pour annuler</p>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { FileText, Edit3, ChevronDown, ChevronUp, Trash2, Eye, Copy, Check } from 'lucide-react';
import type { StoryPart, StoryPartType } from '@/types/story';
import { cn } from '@/lib/utils';
import './StoryPartCard.css';

interface StoryPartCardProps {
  part: StoryPart;
  storyTitle: string;
  partNumber?: number;
  totalParts?: number;
  onEdit?: (part: StoryPart) => void;
  onDelete?: (partId: string) => void;
  onPreview?: (part: StoryPart) => void;
  onQuickEdit?: (part: StoryPart, newContent: string) => void;
  isExpanded?: boolean;
  className?: string;
}

// Configuration des types de parties
const PART_TYPE_CONFIG: Record<StoryPartType, { 
  label: string; 
  icon: string; 
  color: string;
  colorBg: string;
}> = {
  intro: { 
    label: 'Introduction', 
    icon: '📖',
    color: 'var(--intro-color, #3b82f6)',
    colorBg: 'var(--intro-bg, #eff6ff)',
  },
  chapter: { 
    label: 'Chapter', 
    icon: '📑',
    color: 'var(--chapter-color, #8b5cf6)',
    colorBg: 'var(--chapter-bg, #f5f3ff)',
  },
  ending: { 
    label: 'Ending', 
    icon: '🎬',
    color: 'var(--ending-color, #10b981)',
    colorBg: 'var(--ending-bg, #ecfdf5)',
  },
};

export function StoryPartCard({
  part,
  storyTitle,
  partNumber,
  totalParts,
  onEdit,
  onDelete,
  onPreview,
  onQuickEdit,
  isExpanded: defaultExpanded = false,
  className,
}: StoryPartCardProps) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(part.content);
  const [copied, setCopied] = useState(false);
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);

  const config = PART_TYPE_CONFIG[part.type] || PART_TYPE_CONFIG.chapter;

  // Tronquer le contenu pour l'affichage
  const truncatedContent = part.content.length > 200 
    ? part.content.substring(0, 200) + '...' 
    : part.content;

  // Tronquer le résumé pour l'affichage
  const truncatedSummary = part.summary.length > 100 
    ? part.summary.substring(0, 100) + '...' 
    : part.summary;

  const handleCopy = async () => {
    await navigator.clipboard.writeText(part.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleQuickEditSave = () => {
    if (onQuickEdit) {
      onQuickEdit(part, editContent);
    }
    setIsEditing(false);
  };

  const handleQuickEditCancel = () => {
    setEditContent(part.content);
    setIsEditing(false);
  };

  return (
    <div 
      className={cn(
        'story-part-card',
        `story-part-card--${part.type}`,
        isExpanded && 'story-part-card--expanded',
        className
      )}
      style={{ '--part-color': config.color, '--part-bg': config.colorBg } as React.CSSProperties}
    >
      {/* Header */}
      <div className="story-part-card__header" onClick={() => setIsExpanded(!isExpanded)}>
        <div className="story-part-card__header-left">
          <span className="story-part-card__icon">{config.icon}</span>
          <div className="story-part-card__info">
            <h4 className="story-part-card__title">
              {part.title}
              {partNumber && totalParts && part.type === 'chapter' && (
                <span className="story-part-card__chapter-badge">
                  Chapter {partNumber}/{totalParts}
                </span>
              )}
              {part.type === 'intro' && (
                <span className="story-part-card__type-badge">Introduction</span>
              )}
              {part.type === 'ending' && (
                <span className="story-part-card__type-badge">Conclusion</span>
              )}
            </h4>
            <p className="story-part-card__story-title">{storyTitle}</p>
          </div>
        </div>
        
        <div className="story-part-card__header-right">
          {/* Actions rapides */}
          <div className="story-part-card__quick-actions" onClick={(e) => e.stopPropagation()}>
            {onPreview && (
              <button
                className="story-part-card__action-btn"
                onClick={() => onPreview(part)}
                title="Aperçu"
              >
                <Eye className="w-4 h-4" />
              </button>
            )}
            <button
              className="story-part-card__action-btn"
              onClick={handleCopy}
              title="Copier le contenu"
            >
              {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
            </button>
            {onEdit && (
              <button
                className="story-part-card__action-btn story-part-card__action-btn--primary"
                onClick={() => onEdit(part)}
                title="Éditer"
              >
                <Edit3 className="w-4 h-4" />
              </button>
            )}
            {onDelete && (
              <button
                className="story-part-card__action-btn story-part-card__action-btn--danger"
                onClick={() => setShowConfirmDelete(true)}
                title="Supprimer"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>
          
          <button className="story-part-card__expand-btn">
            {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
          </button>
        </div>
      </div>

      {/* Contenu étendu */}
      {isExpanded && (
        <div className="story-part-card__content">
          {/* Résumé pour le contexte LLM */}
          <div className="story-part-card__summary">
            <h5 className="story-part-card__summary-title">
              <FileText className="w-4 h-4" />
              Résumé pour la suite
            </h5>
            <p className="story-part-card__summary-text">{truncatedSummary}</p>
          </div>

          {/* Contenu principal */}
          <div className="story-part-card__main-content">
            {isEditing ? (
              <div className="story-part-card__editor">
                <textarea
                  id={`story-part-content-${part.id}`}
                  aria-label="Part content editor"
                  title="Enter the story part content"
                  placeholder="Write your story part content here..."
                  className="story-part-card__textarea"
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  rows={10}
                  autoFocus
                />
                <div className="story-part-card__editor-actions">
                  <button 
                    className="story-part-card__editor-btn story-part-card__editor-btn--cancel"
                    onClick={handleQuickEditCancel}
                  >
                    Annuler
                  </button>
                  <button 
                    className="story-part-card__editor-btn story-part-card__editor-btn--save"
                    onClick={handleQuickEditSave}
                  >
                    Sauvegarder
                  </button>
                </div>
              </div>
            ) : (
              <div className="story-part-card__text">
                <pre className="story-part-card__pre">{truncatedContent}</pre>
                {part.content.length > 200 && (
                  <button 
                    className="story-part-card__read-more"
                    onClick={() => onEdit && onEdit(part)}
                  >
                    Lire la suite...
                  </button>
                )}
              </div>
            )}
          </div>

          {/* Score de révision */}
          {part.reviewScore && (
            <div className="story-part-card__review-scores">
              <div className="story-part-card__score">
                <span className="story-part-card__score-label">Tension</span>
                <div className="story-part-card__score-bar">
                  <div 
                    className="story-part-card__score-fill" 
                    style={{ width: `${part.reviewScore.tension}%` }}
                  />
                </div>
                <span className="story-part-card__score-value">{part.reviewScore.tension}</span>
              </div>
              <div className="story-part-card__score">
                <span className="story-part-card__score-label">Drame</span>
                <div className="story-part-card__score-bar">
                  <div 
                    className="story-part-card__score-fill story-part-card__score-fill--drama" 
                    style={{ width: `${part.reviewScore.drama}%` }}
                  />
                </div>
                <span className="story-part-card__score-value">{part.reviewScore.drama}</span>
              </div>
              <div className="story-part-card__score">
                <span className="story-part-card__score-label">Cohérence</span>
                <div className="story-part-card__score-bar">
                  <div 
                    className="story-part-card__score-fill story-part-card__score-fill--sense" 
                    style={{ width: `${part.reviewScore.sense}%` }}
                  />
                </div>
                <span className="story-part-card__score-value">{part.reviewScore.sense}</span>
              </div>
              <div className="story-part-card__score">
                <span className="story-part-card__score-label">Émotion</span>
                <div className="story-part-card__score-bar">
                  <div 
                    className="story-part-card__score-fill story-part-card__score-fill--emotion" 
                    style={{ width: `${part.reviewScore.emotion}%` }}
                  />
                </div>
                <span className="story-part-card__score-value">{part.reviewScore.emotion}</span>
              </div>
              <div className="story-part-card__score story-part-card__score--overall">
                <span className="story-part-card__score-label">Note</span>
                <div className="story-part-card__score-bar story-part-card__score-bar--overall">
                  <div 
                    className="story-part-card__score-fill story-part-card__score-fill--overall" 
                    style={{ width: `${part.reviewScore.overall * 10}%` }}
                  />
                </div>
                <span className="story-part-card__score-value">{part.reviewScore.overall}/10</span>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Confirmation de suppression */}
      {showConfirmDelete && (
        <div className="story-part-card__confirm-delete" onClick={(e) => e.stopPropagation()}>
          <div className="story-part-card__confirm-dialog">
            <p>Supprimer « {part.title} » ?</p>
            <div className="story-part-card__confirm-actions">
              <button 
                className="story-part-card__confirm-btn story-part-card__confirm-btn--cancel"
                onClick={() => setShowConfirmDelete(false)}
              >
                Annuler
              </button>
              <button 
                className="story-part-card__confirm-btn story-part-card__confirm-btn--delete"
                onClick={() => {
                  onDelete && onDelete(part.id);
                  setShowConfirmDelete(false);
                }}
              >
                Supprimer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useCallback } from 'react';
import { BookOpen, Plus, RefreshCw, Edit3, Trash2, ChevronDown, ChevronRight, FileText, X } from 'lucide-react';
import { useStore } from '@/store';
import { useAppStore } from '@/stores/useAppStore';
import { StoryPartCard } from './StoryPartCard';
import type { Story, StoryPart } from '@/types/story';
import { saveStoryToDisk } from '@/utils/storyFileIO';
import { toast } from '@/utils/toast';
import { logger } from '@/utils/logging';
import './StoryPartsSection.css';

interface StoryPartsSectionProps {
  story?: Story | null;
  onPartsUpdated?: (parts: StoryPart[]) => void;
  onClose?: () => void;
  className?: string;
}

export function StoryPartsSection({ story, onPartsUpdated, onClose, className }: StoryPartsSectionProps) {
  const updateStory = useStore((state) => state.updateStory);
  const project = useAppStore((state) => state.project);
  
  const [isExpanded, setIsExpanded] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [editingPartId, setEditingPartId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');

  // Organiser les parties par type
  const storyParts = useMemo(() => {
    if (!story?.parts || story.parts.length === 0) return null;

    const intro = story.parts.find(p => p.type === 'intro');
    const chapters = story.parts.filter(p => p.type === 'chapter').sort((a, b) => a.order - b.order);
    const ending = story.parts.find(p => p.type === 'ending');
    const summary = story.summary;

    return { intro, chapters, ending, summary };
  }, [story]);

  // Sauvegarder les modifications rapides
  const handleQuickEdit = useCallback(async (part: StoryPart, newContent: string) => {
    if (!story) return;

    try {
      const updatedParts = story.parts?.map(p => 
        p.id === part.id ? { ...p, content: newContent, updatedAt: new Date() } : p
      ) || [];

      updateStory(story.id, { parts: updatedParts });

      // Sauvegarder sur le disque
      if (project?.metadata?.path && window.electronAPI?.fs) {
        await saveStoryToDisk(project.metadata.path, {
          ...story,
          parts: updatedParts,
        });
      }

      toast.success('Partie sauvegardée', 'Vos modifications ont été enregistrées.');
      setEditingPartId(null);
      
      if (onPartsUpdated) {
        onPartsUpdated(updatedParts);
      }
    } catch (error) {
      logger.error('Failed to save part:', error);
      toast.error('Erreur', 'Impossible de sauvegarder les modifications.');
    }
  }, [story, updateStory, project, onPartsUpdated]);

  // Supprimer une partie
  const handleDeletePart = useCallback(async (partId: string) => {
    if (!story) return;

    try {
      const updatedParts = story.parts?.filter(p => p.id !== partId) || [];
      updateStory(story.id, { parts: updatedParts });

      // Sauvegarder sur le disque
      if (project?.metadata?.path && window.electronAPI?.fs) {
        await saveStoryToDisk(project.metadata.path, {
          ...story,
          parts: updatedParts,
        });
      }

      toast.success('Partie supprimée', 'La partie a été supprimée.');
      
      if (onPartsUpdated) {
        onPartsUpdated(updatedParts);
      }
    } catch (error) {
      logger.error('Failed to delete part:', error);
      toast.error('Erreur', 'Impossible de supprimer la partie.');
    }
  }, [story, updateStory, project, onPartsUpdated]);

  // Rafraîchir depuis les fichiers
  const handleRefresh = async () => {
    setIsRefreshing(true);
    await new Promise(resolve => setTimeout(resolve, 1000));
    setIsRefreshing(false);
    toast.info('Actualisé', 'Les parties ont été actualisées.');
  };

  // Calculer les statistiques
  const stats = useMemo(() => {
    if (!storyParts) return null;

    const totalWords = story.parts?.reduce((sum, part) => 
      sum + (part.content.split(/\s+/).filter(Boolean).length), 0
    ) || 0;

    return {
      totalParts: story.parts?.length || 0,
      totalWords,
      chaptersCount: storyParts.chapters.length,
    };
  }, [story, storyParts]);

  if (!story) {
    return (
      <div className={`story-parts-section story-parts-section--empty ${className || ''}`}>
        <div className="story-parts-section__empty-state">
          <BookOpen className="story-parts-section__empty-icon" />
          <h3>Aucun story créée</h3>
          <p>Créez d'abord une histoire avec le Storyteller Wizard.</p>
        </div>
      </div>
    );
  }

  if (!storyParts) {
    return (
      <div className={`story-parts-section story-parts-section--loading ${className || ''}`}>
        <div className="story-parts-section__loading">
          <FileText className="story-parts-section__loading-icon" />
          <p>En attente des parties d'histoire...</p>
          <span className="story-parts-section__loading-hint">
            Utilisez le Storyteller Wizard pour générer votre histoire.
          </span>
        </div>
      </div>
    );
  }

  return (
    <div className={`story-parts-section ${isExpanded ? 'story-parts-section--expanded' : ''} ${className || ''}`}>
      {/* Header */}
      <div 
        className="story-parts-section__header"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="story-parts-section__header-left">
          <BookOpen className="story-parts-section__icon" />
          <div className="story-parts-section__info">
            <h3 className="story-parts-section__title">{story.title}</h3>
            <div className="story-parts-section__meta">
              {stats && (
                <>
                  <span>{stats.totalParts} parties</span>
                  <span>•</span>
                  <span>{stats.totalWords.toLocaleString()} mots</span>
                  <span>•</span>
                  <span>{stats.chaptersCount} chapitres</span>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="story-parts-section__header-right">
          <button 
            className="story-parts-section__action-btn"
            onClick={(e) => {
              e.stopPropagation();
              handleRefresh();
            }}
            title="Actualiser"
          >
            <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          </button>
          {onClose && (
            <button 
              className="story-parts-section__action-btn story-parts-section__action-btn--close"
              onClick={(e) => {
                e.stopPropagation();
                onClose();
              }}
              title="Fermer"
            >
              <X className="w-4 h-4" />
            </button>
          )}
          <button className="story-parts-section__expand-btn">
            {isExpanded ? <ChevronDown className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
          </button>
        </div>
      </div>

      {/* Contenu étendu */}
      {isExpanded && (
        <div className="story-parts-section__content">
          {/* Résumé global */}
          {storyParts.summary && (
            <div className="story-parts-section__section">
              <div className="story-parts-section__section-header">
                <FileText className="w-4 h-4" />
                <h4>Résumé Global</h4>
              </div>
              <div className="story-parts-section__summary-card">
                <p>{storyParts.summary}</p>
              </div>
            </div>
          )}

          {/* Introduction */}
          {storyParts.intro && (
            <div className="story-parts-section__section">
              <div className="story-parts-section__section-header">
                <span className="story-parts-section__section-icon">📖</span>
                <h4>Introduction</h4>
              </div>
              <StoryPartCard
                part={storyParts.intro}
                storyTitle={story.title}
                onEdit={(part) => {
                  setEditingPartId(part.id);
                  setEditContent(part.content);
                }}
                onDelete={handleDeletePart}
              />
            </div>
          )}

          {/* Chapitres */}
          {storyParts.chapters.length > 0 && (
            <div className="story-parts-section__section">
              <div className="story-parts-section__section-header">
                <span className="story-parts-section__section-icon">📑</span>
                <h4>Chapitres ({storyParts.chapters.length})</h4>
              </div>
              <div className="story-parts-section__parts-grid">
                {storyParts.chapters.map((chapter, index) => (
                  <StoryPartCard
                    key={chapter.id}
                    part={chapter}
                    storyTitle={story.title}
                    partNumber={index + 1}
                    totalParts={storyParts.chapters.length}
                    onEdit={(part) => {
                      setEditingPartId(part.id);
                      setEditContent(part.content);
                    }}
                    onDelete={handleDeletePart}
                  />
                ))}
              </div>
            </div>
          )}

          {/* Conclusion */}
          {storyParts.ending && (
            <div className="story-parts-section__section">
              <div className="story-parts-section__section-header">
                <span className="story-parts-section__section-icon">🎬</span>
                <h4>Conclusion</h4>
              </div>
              <StoryPartCard
                part={storyParts.ending}
                storyTitle={story.title}
                onEdit={(part) => {
                  setEditingPartId(part.id);
                  setEditContent(part.content);
                }}
                onDelete={handleDeletePart}
              />
            </div>
          )}

          {/* Actions additionnelles */}
          <div className="story-parts-section__actions">
            <button 
              className="story-parts-section__add-btn"
              onClick={() => {
                toast.info('Fonction à venir', 'Ajout de parties bientôt disponible.');
              }}
            >
              <Plus className="w-4 h-4" />
              <span>Ajouter un chapitre</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { videoEditorAPI } from '@/services/videoEditorAPI';
import { ShotThumbnail } from '../timeline/ShotThumbnail';
import { Loader2, Film, Image as ImageIcon, Search, RefreshCw } from 'lucide-react';

interface VaultGalleryProps {
    projectId: string;
    className?: string;
}

export function VaultGallery({ projectId, className = '' }: VaultGalleryProps) {
    const [assets, setAssets] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filter, setFilter] = useState('');

    const fetchAssets = async () => {
        setIsLoading(true);
        try {
            const response = await videoEditorAPI.listProjectAssets(projectId);
            setAssets(response.assets || []);
        } catch (err) {
            console.error('[VaultGallery] Failed to fetch assets:', err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchAssets();
    }, [projectId]);

    const filteredAssets = assets.filter(asset =>
        asset.path.toLowerCase().includes(filter.toLowerCase()) ||
        asset.type.toLowerCase().includes(filter.toLowerCase())
    ).reverse(); // Most recent first

    return (
        <div className={`flex flex-col h-full bg-card border rounded-lg overflow-hidden ${className}`}>
            {/* Header */}
            <div className="p-4 border-b border-border bg-muted/30 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Film className="w-5 h-5 text-primary" />
                    <h2 className="font-semibold text-sm">Asset Vault</h2>
                    <span className="text-xs bg-muted px-2 py-0.5 rounded-full text-muted-foreground">
                        {assets.length}
                    </span>
                </div>
                <button
                    onClick={fetchAssets}
                    className="p-1.5 hover:bg-muted rounded-md transition-colors"
                    title="Refresh assets"
                >
                    <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
                </button>
            </div>

            {/* Search Bar */}
            <div className="p-3 border-b border-border bg-background">
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <input
                        type="text"
                        placeholder="Search assets..."
                        value={filter}
                        onChange={(e) => setFilter(e.target.value)}
                        className="w-full pl-9 pr-4 py-1.5 text-xs bg-muted/50 border-none rounded-md focus:ring-1 focus:ring-primary"
                    />
                </div>
            </div>

            {/* Grid */}
            <div className="flex-1 overflow-auto p-4 custom-scrollbar">
                {isLoading ? (
                    <div className="h-full flex flex-col items-center justify-center text-muted-foreground">
                        <Loader2 className="w-8 h-8 animate-spin mb-2" />
                        <p className="text-xs">Loading vault...</p>
                    </div>
                ) : filteredAssets.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-muted-foreground/60 text-center px-4">
                        <ImageIcon className="w-12 h-12 mb-3 opacity-20" />
                        <p className="text-sm font-medium">No assets found</p>
                        <p className="text-xs mt-1 italic">Generated videos will appear here automatically.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-2 gap-3">
                        {filteredAssets.map((asset, idx) => (
                            <div
                                key={idx}
                                className="group relative aspect-video bg-muted rounded-md overflow-hidden border border-border hover:border-primary transition-all cursor-pointer shadow-sm hover:shadow-md"
                            >
                                <ShotThumbnail
                                    videoUrl={asset.type === 'generated_video' ? `/api/video-editor/projects/${projectId}/media-raw?path=${asset.path}` : undefined}
                                    imageUrl={asset.type === 'generated_image' ? `/api/video-editor/projects/${projectId}/media-raw?path=${asset.path}` : undefined}
                                    alt={asset.path}
                                    className="w-full h-full"
                                />

                                {/* Overlay Info */}
                                <div className="absolute inset-x-0 bottom-0 p-2 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                                    <p className="text-[10px] text-white truncate font-medium">
                                        {asset.path.split('/').pop()}
                                    </p>
                                    <p className="text-[8px] text-gray-400">
                                        {asset.added_at ? new Date(asset.added_at).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'Unknown date'}
                                    </p>
                                </div>

                                {/* Badge */}
                                <div className="absolute top-1.5 right-1.5 px-1.5 py-0.5 rounded text-[8px] font-bold bg-black/60 text-white backdrop-blur-sm border border-white/10 uppercase tracking-wider">
                                    {asset.type.replace('generated_', '')}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

import { describe, it, expect } from 'vitest';
import { render } from '@testing-library/react';
import { ContentRenderer, detectContentFormat } from '../ContentRenderer';

describe('detectContentFormat', () => {
  describe('markdown detection', () => {
    it('should detect markdown headers', () => {
      expect(detectContentFormat('# Title')).toBe('markdown');
      expect(detectContentFormat('## Subtitle')).toBe('markdown');
      expect(detectContentFormat('### Section')).toBe('markdown');
      expect(detectContentFormat('#### Subsection')).toBe('markdown');
    });

    it('should detect markdown emphasis (bold)', () => {
      expect(detectContentFormat('**bold text**')).toBe('markdown');
      expect(detectContentFormat('__bold text__')).toBe('markdown');
      expect(detectContentFormat('Some **bold** text')).toBe('markdown');
    });

    it('should detect markdown emphasis (italic)', () => {
      expect(detectContentFormat('*italic text*')).toBe('markdown');
      expect(detectContentFormat('_italic text_')).toBe('markdown');
      expect(detectContentFormat('Some *italic* text')).toBe('markdown');
    });

    it('should detect markdown unordered lists', () => {
      expect(detectContentFormat('- list item')).toBe('markdown');
      expect(detectContentFormat('* list item')).toBe('markdown');
      expect(detectContentFormat('+ list item')).toBe('markdown');
      expect(detectContentFormat('  - indented item')).toBe('markdown');
    });

    it('should detect markdown ordered lists', () => {
      expect(detectContentFormat('1. first item')).toBe('markdown');
      expect(detectContentFormat('2. second item')).toBe('markdown');
      expect(detectContentFormat('  1. indented item')).toBe('markdown');
    });

    it('should detect markdown links', () => {
      expect(detectContentFormat('[link text](url)')).toBe('markdown');
      expect(detectContentFormat('Check [this link](https://example.com)')).toBe('markdown');
    });
  });

  describe('plaintext detection', () => {
    it('should return plaintext for no markdown', () => {
      expect(detectContentFormat('Just plain text')).toBe('plaintext');
      expect(detectContentFormat('Multiple lines\nof plain text')).toBe('plaintext');
    });

    it('should return plaintext for empty strings', () => {
      expect(detectContentFormat('')).toBe('plaintext');
      expect(detectContentFormat('   ')).toBe('plaintext');
    });

    it('should return plaintext for text with special characters but no markdown', () => {
      expect(detectContentFormat('Text with @ symbols')).toBe('plaintext');
      expect(detectContentFormat('Text with $ and %')).toBe('plaintext');
    });
  });

  describe('edge cases', () => {
    it('should handle mixed content', () => {
      const mixed = 'Plain text\n# Header\nMore text';
      expect(detectContentFormat(mixed)).toBe('markdown');
    });

    it('should handle false positives', () => {
      // Single asterisk not surrounded by matching pair
      expect(detectContentFormat('Price: $5 * 2 = $10')).toBe('plaintext');
    });
  });
});

describe('ContentRenderer', () => {
  describe('markdown rendering', () => {
    it('should render markdown headers correctly', () => {
      const content = '# Header 1\n## Header 2';
      const { container } = render(<ContentRenderer content={content} />);
      
      expect(container.querySelector('h1')).toHaveTextContent('Header 1');
      expect(container.querySelector('h2')).toHaveTextContent('Header 2');
    });

    it('should render markdown emphasis correctly', () => {
      const content = '**bold** and *italic*';
      const { container } = render(<ContentRenderer content={content} />);
      
      expect(container.querySelector('strong')).toHaveTextContent('bold');
      expect(container.querySelector('em')).toHaveTextContent('italic');
    });

    it('should render markdown lists correctly', () => {
      const content = '- item 1\n- item 2';
