/**
 * Configuration Context
 * 
 * Provides centralized state management for all configuration data
 * throughout the application.
 */

import { createContext, useContext, useState, useCallback } from 'react';
import type { ReactNode } from 'react';
import type {
  ConfigurationContextValue,
  ProjectConfiguration,
  GlobalConfiguration,
  ProjectMetadata,
  ValidationResult,
} from '../types/configuration';
import { ConfigurationStore } from '../services/configurationStore';
import {
  validateProjectConfiguration,
} from '../services/configurationValidator';

// ============================================================================
// Context Creation
// ============================================================================

const ConfigurationContext = createContext<ConfigurationContextValue | undefined>(undefined);

// ============================================================================
// Provider Component
// ============================================================================

interface ConfigurationProviderProps {
  children: ReactNode;
}

export function ConfigurationProvider({ children }: ConfigurationProviderProps) {
  // State
  const [projectConfig, setProjectConfig] = useState<ProjectConfiguration | null>(null);
  const [globalConfig, setGlobalConfig] = useState<GlobalConfiguration | null>(null);
  const [activeProject, setActiveProject] = useState<ProjectMetadata | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // ============================================================================
  // Actions
  // ============================================================================

  /**
   * Load configuration for a project
   */
  const loadConfiguration = useCallback(async (projectId: string) => {
    setIsLoading(true);
    try {
      // Load project configuration
      const projConfig = await ConfigurationStore.loadProjectConfig(projectId);
      setProjectConfig(projConfig);

      // Load global configuration
      const globConfig = await ConfigurationStore.loadGlobalConfig();
      setGlobalConfig(globConfig);

      // Set active project metadata
      setActiveProject({
        id: projectId,
        name: projConfig.projectId,
        createdAt: new Date().toISOString(),
        lastModified: new Date().toISOString(),
        status: 'active',
      });

      ;
    } catch (error) {
      console.error('Failed to load configuration:', error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, []);

  /**
   * Save project configuration
   */
  const saveProjectConfig = useCallback(
    async (config: Partial<ProjectConfiguration>) => {
      if (!projectConfig) {
        throw new Error('No project configuration loaded');
      }

      setIsSaving(true);
      try {
        // Merge with existing configuration
        const updatedConfig: ProjectConfiguration = {
          ...projectConfig,
          ...config,
        };

        // Validate before saving
        const validationResult = validateProjectConfiguration(updatedConfig);
        if (!validationResult.isValid) {
          throw new Error(
            `Validation failed: ${validationResult.errors.map(e => e.message).join(', ')}`
          );
        }

        // Save to storage
        await ConfigurationStore.saveProjectConfig(updatedConfig.projectId, updatedConfig);

        // Update state
        setProjectConfig(updatedConfig);

        // Update last modified timestamp
        if (activeProject) {
          setActiveProject({
            ...activeProject,
            lastModified: new Date().toISOString(),
          });
        }

        ;
      } catch (error) {
        console.error('Failed to save project configuration:', error);
        throw error;
      } finally {
        setIsSaving(false);
      }
    },
    [projectConfig, activeProject]
  );

  /**
   * Save global configuration
   */
  const saveGlobalConfig = useCallback(
    async (config: Partial<GlobalConfiguration>) => {
      if (!globalConfig) {
        throw new Error('No global configuration loaded');
      }

      setIsSaving(true);
      try {
        // Merge with existing configuration
        const updatedConfig: GlobalConfiguration = {
          ...globalConfig,
          ...config,
        };

        // Save to storage
        await ConfigurationStore.saveGlobalConfig(updatedConfig);

        // Update state
        setGlobalConfig(updatedConfig);

        ;
      } catch (error) {
        console.error('Failed to save global configuration:', error);
        throw error;
      } finally {
        setIsSaving(false);
      }
    },
    [globalConfig]
  );

  /**
   * Validate configuration
   */
  const validateConfiguration = useCallback((config: unknown): ValidationResult => {
    return validateProjectConfiguration(config as ProjectConfiguration);
  }, []);

  /**
   * Reset configuration to defaults
   */
  const resetToDefaults = useCallback(
    async (scope: 'project' | 'global') => {
      setIsSaving(true);
      try {
        if (scope === 'project' && activeProject) {
          // Delete existing configuration
          await ConfigurationStore.deleteProjectConfig(activeProject.id);

          // Reload configuration (will load defaults)
          await loadConfiguration(activeProject.id);

          ;
        } else if (scope === 'global') {
          // Clear global configuration from storage
          localStorage.removeItem('storycore_global_config');

          // Reload global configuration
          const defaultGlobalConfig = await ConfigurationStore.loadGlobalConfig();
          setGlobalConfig(defaultGlobalConfig);

          ;
        }
      } catch (error) {
        console.error('Failed to reset configuration:', error);
        throw error;
      } finally {
        setIsSaving(false);
      }
    },
    [activeProject, loadConfiguration]
  );

  /**
   * Export configuration
   */
  const exportConfiguration = useCallback(async (): Promise<string> => {
    if (!activeProject) {
      throw new Error('No active project');
    }

    try {
      const exportData = await ConfigurationStore.exportConfiguration(activeProject.id);
      ;
      return exportData;
    } catch (error) {
      console.error('Failed to export configuration:', error);
      throw error;
    }
  }, [activeProject]);

  /**
   * Import configuration
   */
  const importConfiguration = useCallback(
    async (data: string) => {
      if (!activeProject) {
        throw new Error('No active project');
      }

      setIsSaving(true);
      try {
        await ConfigurationStore.importConfiguration(activeProject.id, data);

        // Reload configuration
        await loadConfiguration(activeProject.id);

        ;
      } catch (error) {
        console.error('Failed to import configuration:', error);
        throw error;
      } finally {
        setIsSaving(false);
      }
    },
    [activeProject, loadConfiguration]
  );

  // ============================================================================
  // Context Value
  // ============================================================================

  const contextValue: ConfigurationContextValue = {
    projectConfig,
    globalConfig,
    activeProject,
    isLoading,
    isSaving,
    loadConfiguration,
    saveProjectConfig,
    saveGlobalConfig,
    validateConfiguration,
    resetToDefaults,
    exportConfiguration,
    importConfiguration,
  };

  return (
    <ConfigurationContext.Provider value={contextValue}>
      {children}
    </ConfigurationContext.Provider>
  );
}

// ============================================================================
// Custom Hook
// ============================================================================

/**
 * Hook to access configuration context
 */
export function useConfiguration(): ConfigurationContextValue {
  const context = useContext(ConfigurationContext);

  if (context === undefined) {
    throw new Error('useConfiguration must be used within a ConfigurationProvider');
  }

  return context;
}

/**
 * DialogueContext - Dialogue phrase management operations
 * 
 * Responsibility: Dialogue phrase CRUD, timing, and shot linking
 * Part of ProjectContext split (see docs/PROJECTCONTEXT_ANALYSIS.md)
 * 
 * State Variables:
 * - Managed through project.audioPhrases (DialoguePhrase array)
 * 
 * Callback Functions:
 * - addDialoguePhrase(phrase): Add new phrase and return its ID
 * - updateDialoguePhrase(phraseId, updates): Update phrase properties
 * - deleteDialoguePhrase(phraseId): Remove phrase from project
 * - linkPhraseToShot(phraseId, shotId): Link phrase to a shot via shotId
 */

import React, { createContext, useContext, useCallback, useMemo, useState } from 'react';
import type { DialoguePhrase } from '../types';

// Generate unique ID for phrases
const generatePhraseId = (): string => {
  return `phrase_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
};

interface DialogueContextType {
  addDialoguePhrase: (phrase: DialoguePhrase) => string;
  updateDialoguePhrase: (phraseId: string, updates: Partial<DialoguePhrase>) => void;
  deleteDialoguePhrase: (phraseId: string) => void;
  linkPhraseToShot: (phraseId: string, shotId: string) => void;
}

export type { DialogueContextType };

const DialogueContext = createContext<DialogueContextType | undefined>(undefined);

export const DialogueProvider: React.FC<{ 
  children: React.ReactNode;
  phrases?: DialoguePhrase[];
  onPhrasesUpdate?: (phrases: DialoguePhrase[]) => void;
}> = ({ 
  children,
  phrases: externalPhrases,
  onPhrasesUpdate 
}) => {
  // Use external phrases if provided, otherwise use internal state
  const [internalPhrases, setInternalPhrases] = React.useState<DialoguePhrase[]>([]);
  
  // Use external phrases or internal state
  const phrases = externalPhrases !== undefined ? externalPhrases : internalPhrases;

  const addDialoguePhrase = useCallback((phrase: DialoguePhrase) => {
    const phraseId = phrase.id || generatePhraseId();
    const newPhrase: DialoguePhrase = {
      ...phrase,
      id: phraseId,
    };

    setInternalPhrases(prev => {
      const updatedPhrases = [...prev, newPhrase];
      onPhrasesUpdate?.(updatedPhrases);
      return updatedPhrases;
    });

    return phraseId;
  }, [onPhrasesUpdate]);

  const updateDialoguePhrase = useCallback((phraseId: string, updates: Partial<DialoguePhrase>) => {
    setInternalPhrases(prev => {
      const updatedPhrases = prev.map(phrase => 
        phrase.id === phraseId 
          ? { ...phrase, ...updates }
          : phrase
      );
      
      onPhrasesUpdate?.(updatedPhrases);
      return updatedPhrases;
    });
  }, [onPhrasesUpdate]);

  const deleteDialoguePhrase = useCallback((phraseId: string) => {
    setInternalPhrases(prev => {
      const updatedPhrases = prev.filter(phrase => phrase.id !== phraseId);
      onPhrasesUpdate?.(updatedPhrases);
      return updatedPhrases;
    });
  }, [onPhrasesUpdate]);

  const linkPhraseToShot = useCallback((phraseId: string, shotId: string) => {
    // Link phrase to shot by updating the phrase's shotId
    // The phrase maintains its own shotId for the relationship
    setInternalPhrases(prev => {
      const updatedPhrases = prev.map(phrase => 
        phrase.id === phraseId 
          ? { ...phrase, shotId }
          : phrase
      );
      
      onPhrasesUpdate?.(updatedPhrases);
      return updatedPhrases;
    });
  }, [onPhrasesUpdate]);

  const value = useMemo(() => ({
    addDialoguePhrase,
    updateDialoguePhrase,
    deleteDialoguePhrase,
    linkPhraseToShot
  }), [
    addDialoguePhrase,
    updateDialoguePhrase,
    deleteDialoguePhrase,
    linkPhraseToShot
  ]);

  return (
    <DialogueContext.Provider value={value}>
      {children}
    </DialogueContext.Provider>
  );
};

export const useDialogue = () => {
  const context = useContext(DialogueContext);
  if (!context) {
    throw new Error('useDialogue must be used within a DialogueProvider');
  }
  return context;
};

/**
 * GenerationContext
 * Manages the state and logic for media generation sequences including
 * grid generation, ComfyUI processing, QA checks, and export operations.
 */

import React, { createContext, useContext, useState, useCallback, useRef } from 'react';

export type GenerationPhase = 'idle' | 'running' | 'complete' | 'error';

export interface GenerationStatus {
  grid: GenerationPhase;
  comfyui: GenerationPhase;
  promotion: GenerationPhase;
  qa: GenerationPhase;
  export: GenerationPhase;
}

export interface GenerationContextType {
  generationStatus: GenerationStatus;
  generationProgress: number;
  isGenerating: boolean;
  generationError: string | null;
  generateSequence: () => Promise<void>;
  cancelGeneration: () => void;
  resetGeneration: () => void;
  updateStatus: (phase: keyof GenerationStatus, status: GenerationPhase) => void;
  setProgress: (progress: number) => void;
  setError: (error: string | null) => void;
}

const GenerationContext = createContext<GenerationContextType | undefined>(undefined);

const INITIAL_STATUS: GenerationStatus = {
  grid: 'idle',
  comfyui: 'idle',
  promotion: 'idle',
  qa: 'idle',
  export: 'idle'
};

export const GenerationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [generationStatus, setGenerationStatus] = useState<GenerationStatus>(INITIAL_STATUS);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationError, setGenerationError] = useState<string | null>(null);
  
  const abortControllerRef = useRef<AbortController | null>(null);

  const updateStatus = useCallback((phase: keyof GenerationStatus, status: GenerationPhase) => {
    setGenerationStatus(prev => ({
      ...prev,
      [phase]: status
    }));
  }, []);

  const setProgress = useCallback((progress: number) => {
    setGenerationProgress(Math.min(100, Math.max(0, progress)));
  }, []);

  const setError = useCallback((error: string | null) => {
    setGenerationError(error);
  }, []);

  const generateSequence = useCallback(async () => {
    if (isGenerating) {
      console.warn('Generation already in progress');
      return;
    }

    // Reset state for new generation
    setGenerationStatus(INITIAL_STATUS);
    setGenerationProgress(0);
    setGenerationError(null);
    setIsGenerating(true);
    
    // Create abort controller for cancellation support
    abortControllerRef.current = new AbortController();

    try {
      // Phase 1: Grid Generation (0-20%)
      updateStatus('grid', 'running');
      setProgress(0);
      
      // Simulate grid generation - in production, this would call the grid generation API
      await simulateGenerationStep('grid', 0, 20, abortControllerRef.current.signal);
      
      updateStatus('grid', 'complete');
      setProgress(20);

      // Phase 2: ComfyUI Processing (20-50%)
      updateStatus('comfyui', 'running');
      
      await simulateGenerationStep('comfyui', 20, 50, abortControllerRef.current.signal);
      
      updateStatus('comfyui', 'complete');
      setProgress(50);

      // Phase 3: Promotion/Enhancement (50-70%)
      updateStatus('promotion', 'running');
      
      await simulateGenerationStep('promotion', 50, 70, abortControllerRef.current.signal);
      
      updateStatus('promotion', 'complete');
      setProgress(70);

      // Phase 4: QA Checks (70-85%)
      updateStatus('qa', 'running');
      
      await simulateGenerationStep('qa', 70, 85, abortControllerRef.current.signal);
      
      updateStatus('qa', 'complete');
      setProgress(85);

      // Phase 5: Export (85-100%)
      updateStatus('export', 'running');
      
      await simulateGenerationStep('export', 85, 100, abortControllerRef.current.signal);
      
      updateStatus('export', 'complete');
      setProgress(100);

      // Generation complete
      setIsGenerating(false);
      console.log('Generation sequence completed successfully');
      
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        console.log('Generation was cancelled');
        setGenerationError(null);
      } else {
        console.error('Generation failed:', error);
        setGenerationError(error instanceof Error ? error.message : 'Unknown error occurred');
        
        // Mark the current phase as errored
        const currentPhase = getCurrentPhase(generationStatus);
        if (currentPhase) {
          updateStatus(currentPhase, 'error');
        }
      }
      setIsGenerating(false);
    } finally {
      abortControllerRef.current = null;
    }
  }, [isGenerating, generationStatus, updateStatus]);

  const cancelGeneration = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    setIsGenerating(false);
    setGenerationError(null);
    console.log('Generation cancelled');
  }, []);

  const resetGeneration = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    abortControllerRef.current = null;
    setGenerationStatus(INITIAL_STATUS);
    setGenerationProgress(0);
    setIsGenerating(false);
    setGenerationError(null);
  }, []);

  return (
    <GenerationContext.Provider value={{
      generationStatus,
      generationProgress,
      isGenerating,
      generationError,
      generateSequence,
      cancelGeneration,
      resetGeneration,
      updateStatus,
      setProgress,
      setError
    }}>
      {children}
    </GenerationContext.Provider>
  );
};

// Helper function to simulate generation steps
// In production, this would be replaced with actual API calls
async function simulateGenerationStep(
  _phase: keyof GenerationStatus,
  startProgress: number,
  endProgress: number,
  signal: AbortSignal
): Promise<void> {
  const steps = 10;
  const stepDuration = 100; // ms per step
  const progressRange = endProgress - startProgress;
  const progressPerStep = progressRange / steps;

  for (let i = 0; i < steps; i++) {
    // Check for cancellation
    if (signal.aborted) {
      throw new Error('Aborted');
    }

    // Simulate async work
    await new Promise(resolve => setTimeout(resolve, stepDuration));
    
    // Progress update would be handled by the component using setProgress
  }
}

// Helper to determine current active phase
function getCurrentPhase(status: GenerationStatus): keyof GenerationStatus | null {
  if (status.grid === 'running') return 'grid';
  if (status.comfyui === 'running') return 'comfyui';
  if (status.promotion === 'running') return 'promotion';
  if (status.qa === 'running') return 'qa';
  if (status.export === 'running') return 'export';
  return null;
}

export const useGeneration = () => {
  const context = useContext(GenerationContext);
  if (!context) {
    throw new Error('useGeneration must be used within a GenerationProvider');
  }
  return context;
};

export default GenerationContext;

/**
 * Installation Wizard Context
 * Manages state for the ComfyUI installation wizard
 */

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { WizardState } from '../types/installation';

interface InstallationWizardContextType {
  wizardState: WizardState;
  updateWizardState: (updates: Partial<WizardState>) => void;
  resetWizard: () => void;
  setCurrentStep: (step: WizardState['currentStep']) => void;
  setFileDetected: (detected: boolean, valid: boolean) => void;
  setInstallationProgress: (progress: number, status: string) => void;
  setInstallationError: (error: string | null) => void;
  setInstallationComplete: (url: string, models: string[], workflows: string[]) => void;
}

const InstallationWizardContext = createContext<InstallationWizardContextType | undefined>(undefined);

const initialWizardState: WizardState = {
  currentStep: 'download',
  downloadZonePath: '',
  fileDetected: false,
  fileValid: false,
  installationProgress: 0,
  installationStatus: '',
  installationError: null,
  installedModels: [],
  installedWorkflows: [],
  comfyUIUrl: null
};

interface InstallationWizardProviderProps {
  children: ReactNode;
}

export const InstallationWizardProvider: React.FC<InstallationWizardProviderProps> = ({ children }) => {
  const [wizardState, setWizardState] = useState<WizardState>(initialWizardState);

  const updateWizardState = useCallback((updates: Partial<WizardState>) => {
    setWizardState(prev => ({ ...prev, ...updates }));
  }, []);

  const resetWizard = useCallback(() => {
    setWizardState(initialWizardState);
  }, []);

  const setCurrentStep = useCallback((step: WizardState['currentStep']) => {
    setWizardState(prev => ({ ...prev, currentStep: step }));
  }, []);

  const setFileDetected = useCallback((detected: boolean, valid: boolean) => {
    setWizardState(prev => ({
      ...prev,
      fileDetected: detected,
      fileValid: valid
    }));
  }, []);

  const setInstallationProgress = useCallback((progress: number, status: string) => {
    setWizardState(prev => ({
      ...prev,
      installationProgress: progress,
      installationStatus: status
    }));
  }, []);

  const setInstallationError = useCallback((error: string | null) => {
    setWizardState(prev => ({
      ...prev,
      installationError: error
    }));
  }, []);

  const setInstallationComplete = useCallback((
    url: string,
    models: string[],
    workflows: string[]
  ) => {
    setWizardState(prev => ({
      ...prev,
      currentStep: 'completion',
      comfyUIUrl: url,
      installedModels: models,
      installedWorkflows: workflows,
      installationProgress: 100,
      installationStatus: 'Installation completed successfully!'
    }));
  }, []);

  const value: InstallationWizardContextType = {
    wizardState,
    updateWizardState,
    resetWizard,
    setCurrentStep,
    setFileDetected,
    setInstallationProgress,
    setInstallationError,
    setInstallationComplete
  };

  return (
    <InstallationWizardContext.Provider value={value}>
      {children}
    </InstallationWizardContext.Provider>
