/**
 * ShotManagementContext - Shot selection and management operations
 * 
 * Responsibility: Shot CRUD, selection, validation, and prompt status tracking
 * Part of ProjectContext split (see docs/PROJECTCONTEXT_ANALYSIS.md)
 * 
 * State Variables:
 * - selectedShot: Currently selected shot for editing
 * 
 * Callback Functions:
 * - updateShot(shotId, updates): Update shot properties
 * - deleteShot(shotId): Remove shot from project
 * - validateAllShots(): Validate all shots for completeness
 * - getPromptCompletionStatus(): Get prompt status per shot
 * - selectShot(shot): Set currently selected shot
 */

import React, { createContext, useContext, useState, useCallback, useMemo } from 'react';
import type { Shot } from '../types';

// Define PromptStatus type for tracking prompt completion
export type PromptStatus = 
  | 'pending'      // Prompt not yet generated
  | 'in-progress'   // Prompt generation in progress
  | 'complete'      // Prompt generated successfully
  | 'failed';       // Prompt generation failed

interface ShotManagementContextType {
  selectedShot: Shot | null;
  updateShot: (shotId: string, updates: Partial<Shot>) => void;
  deleteShot: (shotId: string) => void;
  validateAllShots: () => { valid: boolean; errors: string[] };
  getPromptCompletionStatus: () => Record<string, PromptStatus>;
  selectShot: (shot: Shot | null) => void;
}

export type { ShotManagementContextType };

const ShotManagementContext = createContext<ShotManagementContextType | undefined>(undefined);

// Validation rules for shots
const SHOT_VALIDATION_RULES = {
  minimumTitleLength: 1,
  minimumDuration: 0.5, // seconds
  maximumShotsPerProject: 1000,
};

export const ShotManagementProvider: React.FC<{ 
  children: React.ReactNode;
  shots?: Shot[];
  onShotsUpdate?: (shots: Shot[]) => void;
}> = ({ 
  children,
  shots: externalShots,
  onShotsUpdate 
}) => {
  // Use external shots if provided, otherwise use local state
  const [selectedShot, setSelectedShot] = useState<Shot | null>(null);
  
  // Internal shots state if no external source
  const [internalShots, setInternalShots] = useState<Shot[]>([]);
  
  // Use external shots or internal state
  const shots = externalShots !== undefined ? externalShots : internalShots;
  
  const updateShot = useCallback((shotId: string, updates: Partial<Shot>) => {
    setInternalShots(prev => {
      const updatedShots = prev.map(shot => 
        shot.id === shotId 
          ? { ...shot, ...updates, updatedAt: new Date().toISOString() }
          : shot
      );
      
      // Update selected shot if it's the one being modified
      setSelectedShot(current => 
        current?.id === shotId 
          ? { ...current, ...updates }
          : current
      );
      
      // Notify external handler
      onShotsUpdate?.(updatedShots);
      
      return updatedShots;
    });
  }, [onShotsUpdate]);

  const deleteShot = useCallback((shotId: string) => {
    setInternalShots(prev => {
      const filteredShots = prev.filter(shot => shot.id !== shotId);
      onShotsUpdate?.(filteredShots);
      return filteredShots;
    });
    
    // Clear selected shot if it was deleted
    setSelectedShot(current => 
      current?.id === shotId ? null : current
    );
  }, [onShotsUpdate]);

  const validateAllShots = useCallback((): { valid: boolean; errors: string[] } => {
    const errors: string[] = [];
    
    // Check for empty shots array
    if (shots.length === 0) {
      errors.push('No shots in project. Add at least one shot.');
      return { valid: false, errors };
    }
    
    // Check shot count limit
    if (shots.length > SHOT_VALIDATION_RULES.maximumShotsPerProject) {
      errors.push(`Too many shots (${shots.length}). Maximum is ${SHOT_VALIDATION_RULES.maximumShotsPerProject}.`);
    }
    
    // Validate each shot
    shots.forEach((shot, index) => {
      // Validate title
      if (!shot.title || shot.title.trim().length < SHOT_VALIDATION_RULES.minimumTitleLength) {
        errors.push(`Shot ${index + 1}: Title is required.`);
      }
      
      // Validate duration
      if (shot.duration < SHOT_VALIDATION_RULES.minimumDuration) {
        errors.push(`Shot "${shot.title}": Duration must be at least ${SHOT_VALIDATION_RULES.minimumDuration} seconds.`);
      }
      
      // Validate position uniqueness
      const positionCount = shots.filter(s => s.position === shot.position).length;
      if (positionCount > 1) {
        errors.push(`Shot "${shot.title}": Duplicate position (${shot.position}).`);
      }
    });
    
    // Check for gaps in positions
    const positions = shots.map(s => s.position).sort((a, b) => a - b);
    for (let i = 0; i < positions.length - 1; i++) {
      if (positions[i + 1] - positions[i] > 1) {
        errors.push(`Gap detected between positions ${positions[i]} and ${positions[i + 1]}.`);
      }
    }
    
    return {
      valid: errors.length === 0,
      errors
    };
  }, [shots]);

  const getPromptCompletionStatus = useCallback((): Record<string, PromptStatus> => {
    const status: Record<string, PromptStatus> = {};
    
    shots.forEach(shot => {
      // Determine prompt status based on shot properties
      // A shot has a complete prompt if it has required generation data
      const hasGenerationData = !!(
        shot.metadata?.prompt ||
        shot.metadata?.positivePrompt ||
        shot.promoted_panel_path
      );
      
      const isGenerating = shot.metadata?.generationStatus === 'in-progress';
      const hasFailed = shot.metadata?.generationStatus === 'failed';
      
      if (isGenerating) {
        status[shot.id] = 'in-progress';
      } else if (hasFailed) {
        status[shot.id] = 'failed';
      } else if (hasGenerationData) {
        status[shot.id] = 'complete';
      } else {
        status[shot.id] = 'pending';
      }
    });
    
    return status;
  }, [shots]);

  const selectShot = useCallback((shot: Shot | null) => {
    setSelectedShot(shot);
  }, []);

  const value = useMemo(() => ({
    selectedShot,
    updateShot,
    deleteShot,
    validateAllShots,
    getPromptCompletionStatus,
    selectShot
  }), [
    selectedShot,
    updateShot,
    deleteShot,
    validateAllShots,
    getPromptCompletionStatus,
    selectShot
  ]);

  return (
    <ShotManagementContext.Provider value={value}>
      {children}
    </ShotManagementContext.Provider>
  );
};

export const useShotManagement = () => {
  const context = useContext(ShotManagementContext);
  if (!context) {
    throw new Error('useShotManagement must be used within a ShotManagementProvider');
  }
  return context;
};

/**
 * Video Editor Context
 * Global state management for the video editor
 */
import React, { createContext, useContext, useCallback, useState } from 'react';
import {
  EditorProject,
  MediaFile,
  Track,
  Clip,
  ExportSettings,
  EditorMode,
  UndoRedoState,
} from '../types/video-editor';

interface VideoEditorContextType {
  // State
  project: EditorProject | null;
  mediaLibrary: MediaFile[];
  tracks: Track[];
  clips: Clip[];
  selectedClipIds: string[];
  selectedTrackId: string | null;
  activePanel: 'effects' | 'text' | 'audio' | 'media';
  editorMode: EditorMode;
  previewUrl: string | null;
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  isDirty: boolean;
  undoStack: UndoRedoState[];
  redoStack: UndoRedoState[];
  showExportDialog: boolean;
  showSettingsDialog: boolean;
  
  // Setters
  setProject: React.Dispatch<React.SetStateAction<EditorProject | null>>;
  setMediaLibrary: React.Dispatch<React.SetStateAction<MediaFile[]>>;
  setTracks: React.Dispatch<React.SetStateAction<Track[]>>;
  setClips: React.Dispatch<React.SetStateAction<Clip[]>>;
  setSelectedClipIds: React.Dispatch<React.SetStateAction<string[]>>;
  setSelectedTrackId: React.Dispatch<React.SetStateAction<string | null>>;
  setActivePanel: React.Dispatch<React.SetStateAction<'effects' | 'text' | 'audio' | 'media'>>;
  setEditorMode: React.Dispatch<React.SetStateAction<EditorMode>>;
  setPreviewUrl: React.Dispatch<React.SetStateAction<string | null>>;
  setIsPlaying: React.Dispatch<React.SetStateAction<boolean>>;
  setCurrentTime: React.Dispatch<React.SetStateAction<number>>;
  setDuration: React.Dispatch<React.SetStateAction<number>>;
  setShowExportDialog: React.Dispatch<React.SetStateAction<boolean>>;
  setShowSettingsDialog: React.Dispatch<React.SetStateAction<boolean>>;
  
  // Actions
  importMedia: (files: FileList) => Promise<void>;
  addClipToTimeline: (mediaId: string, trackId: string, startTime: number, inPoint?: number, outPoint?: number) => void;
  moveClip: (clipId: string, newTrackId: string, newStartTime: number) => void;
  trimClip: (clipId: string, inPoint?: number, outPoint?: number) => void;
  splitClip: (clipId: string, splitTime: number) => void;
  deleteClips: (clipIds: string[]) => void;
  updateClip: (clipId: string, updates: Partial<Clip>) => void;
  updateTrack: (trackId: string, updates: Partial<Track>) => void;
  deleteMedia: (mediaId: string) => void;
  selectClip: (clipId: string, addToSelection: boolean) => void;
  selectTrack: (trackId: string | null) => void;
  undo: () => void;
  redo: () => void;
  play: () => void;
  pause: () => void;
  seek: (time: number) => void;
  export: (settings: ExportSettings) => Promise<void>;
  
  // Computed
  selectedClips: Clip[];
  selectedTrack: Track | null;
  canUndo: boolean;
  canRedo: boolean;
}

const VideoEditorContext = createContext<VideoEditorContextType | null>(null);

export const useVideoEditor = () => {
  const context = useContext(VideoEditorContext);
  if (!context) {
    throw new Error('useVideoEditor must be used within a VideoEditorProvider');
  }
  return context;
};

interface VideoEditorProviderProps {
  children: React.ReactNode;
  initialProject?: EditorProject | null;
}

export const VideoEditorProvider: React.FC<VideoEditorProviderProps> = ({
  children,
  initialProject = null,
}) => {
  const [project, setProject] = useState<EditorProject | null>(initialProject);
  const [mediaLibrary, setMediaLibrary] = useState<MediaFile[]>([]);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [clips, setClips] = useState<Clip[]>([]);
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [selectedTrackId, setSelectedTrackId] = useState<string | null>(null);
  const [activePanel, setActivePanel] = useState<'effects' | 'text' | 'audio' | 'media'>('media');
  const [editorMode, setEditorMode] = useState<EditorMode>(EditorMode.VIDEO);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [isDirty, setIsDirty] = useState(false);
  const [undoStack, setUndoStack] = useState<UndoRedoState[]>([]);
  const [redoStack, setRedoStack] = useState<UndoRedoState[]>([]);
  const [showExportDialog, setShowExportDialog] = useState(false);
  const [showSettingsDialog, setShowSettingsDialog] = useState(false);
  
  // Computed values
  const selectedClips = clips.filter(clip => selectedClipIds.includes(clip.id));
  const selectedTrack = tracks.find(track => track.id === selectedTrackId) || null;
  const canUndo = undoStack.length > 0;
  const canRedo = redoStack.length > 0;
  
  // Save to undo stack
  const saveToUndoStack = useCallback((newClips: Clip[], newTracks: Track[]) => {
    setUndoStack(prev => [...prev.slice(-19), {
      clips: [...newClips],
      tracks: [...newTracks],
      timestamp: Date.now(),
    }]);
    setRedoStack([]);
    setIsDirty(true);
  }, []);
  
  // Undo action
  const undo = useCallback(() => {
    if (undoStack.length === 0) return;
    
    const previousState = undoStack[undoStack.length - 1];
    const currentState: UndoRedoState = {
      clips: [...clips],
      tracks: [...tracks],
      timestamp: Date.now(),
    };
    
    setRedoStack(prev => [...prev, currentState]);
    setClips(previousState.clips);
    setTracks(previousState.tracks);
    setUndoStack(prev => prev.slice(0, -1));
  }, [undoStack, clips, tracks]);
  
  // Redo action
  const redo = useCallback(() => {
    if (redoStack.length === 0) return;
    
    const nextState = redoStack[redoStack.length - 1];
    const currentState: UndoRedoState = {
      clips: [...clips],
      tracks: [...tracks],
      timestamp: Date.now(),
    };
    
    setUndoStack(prev => [...prev, currentState]);
    setClips(nextState.clips);
    setTracks(nextState.tracks);
    setRedoStack(prev => prev.slice(0, -1));
  }, [redoStack, clips, tracks]);
  
  // Media actions (to be implemented with API)
  const importMedia = useCallback(async (files: FileList) => {
    // Placeholder - should be connected to API
    console.log('Importing media:', files);
  }, []);
  
  // Clip actions
  const addClipToTimeline = useCallback((
    mediaId: string,
    trackId: string,
    startTime: number,
    inPoint?: number,
    outPoint?: number
  ) => {
    const newClip: Clip = {
      id: `clip-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      mediaId,
      trackId,
      startTime,
      inPoint: inPoint || 0,
      outPoint: outPoint,
      duration: (outPoint || 0) - (inPoint || 0),
      keyframes: [],
      effects: [],
    };
    
    saveToUndoStack([...clips, newClip], tracks.map(t => 
      t.id === trackId 
        ? { ...t, clips: [...t.clips, newClip.id] }
        : t
    ));
    
    setClips(prev => [...prev, newClip]);
    setTracks(prev => prev.map(t => 
      t.id === trackId 
        ? { ...t, clips: [...t.clips, newClip.id] }
        : t
    ));
  }, [clips, tracks, saveToUndoStack]);
  
  const moveClip = useCallback((clipId: string, newTrackId: string, newStartTime: number) => {
    saveToUndoStack(
      clips.map(clip => clip.id === clipId ? { ...clip, trackId: newTrackId, startTime: newStartTime } : clip),
      tracks
    );
    setClips(prev => prev.map(clip => 
      clip.id === clipId ? { ...clip, trackId: newTrackId, startTime: newStartTime } : clip
    ));
  }, [clips, tracks, saveToUndoStack]);
  
  const trimClip = useCallback((clipId: string, inPoint?: number, outPoint?: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    
    saveToUndoStack(
      clips.map(c => c.id === clipId 
        ? { ...c, inPoint: inPoint ?? c.inPoint, outPoint: outPoint ?? c.outPoint }
        : c
      ),
      tracks
    );
    setClips(prev => prev.map(c => 
      c.id === clipId 
        ? { ...c, inPoint: inPoint ?? c.inPoint, outPoint: outPoint ?? c.outPoint }
        : c
    ));
  }, [clips, tracks, saveToUndoStack]);
  
  const splitClip = useCallback((clipId: string, splitTime: number) => {
    const clip = clips.find(c => c.id === clipId);
    if (!clip) return;
    
    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + clip.duration;
    
    if (splitTime <= clipStart || splitTime >= clipEnd) return;
    
    const firstDuration = splitTime - clipStart;
    const secondClip: Clip = {
      ...clip,
      id: `clip-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      startTime: splitTime,
      inPoint: clip.inPoint + firstDuration,
      duration: clip.duration - firstDuration,
    };
    
    const updatedFirstClip: Clip = {
      ...clip,
      outPoint: clip.inPoint + firstDuration,
      duration: firstDuration,
    };
    
    const newClips = clips.map(c => c.id === clipId ? updatedFirstClip : c).concat(secondClip);
    
    saveToUndoStack(newClips, tracks);
    setClips(newClips);
  }, [clips, tracks, saveToUndoStack]);
  
  const deleteClips = useCallback((clipIds: string[]) => {
    saveToUndoStack(
      clips.filter((c: Clip) => !clipIds.includes(c.id)),
      tracks.map((t: Track) => ({ ...t, clips: t.clips.filter((id: string) => !clipIds.includes(id)) }))
    );
    setClips((prev: Clip[]) => prev.filter((c: Clip) => !clipIds.includes(c.id)));
    setTracks((prev: Track[]) => prev.map((t: Track) => ({ ...t, clips: t.clips.filter((id: string) => !clipIds.includes(id)) })));
    setSelectedClipIds((prev: string[]) => prev.filter((id: string) => !clipIds.includes(id)));
  }, [clips, tracks, saveToUndoStack]);
  
  const selectClip = useCallback((clipId: string, addToSelection: boolean) => {
    setSelectedClipIds(prev => 
      addToSelection 
        ? (prev.includes(clipId) ? prev.filter(id => id !== clipId) : [...prev, clipId])
        : [clipId]
    );
  }, []);
  
  const selectTrack = useCallback((trackId: string | null) => {
    setSelectedTrackId(trackId);
  }, []);
  
  // Update clip action
  const updateClip = useCallback((clipId: string, updates: Partial<Clip>) => {
    saveToUndoStack(
      clips.map((c: Clip) => c.id === clipId ? { ...c, ...updates } : c),
      tracks
    );
    setClips((prev: Clip[]) => prev.map((c: Clip) => c.id === clipId ? { ...c, ...updates } : c));
  }, [clips, tracks, saveToUndoStack]);
  
  // Update track action
  const updateTrack = useCallback((trackId: string, updates: Partial<Track>) => {
    saveToUndoStack(
      clips,
      tracks.map((t: Track) => t.id === trackId ? { ...t, ...updates } : t)
    );
    setTracks((prev: Track[]) => prev.map((t: Track) => t.id === trackId ? { ...t, ...updates } : t));
  }, [clips, tracks, saveToUndoStack]);
  
  // Delete media action
  const deleteMedia = useCallback((mediaId: string) => {
    setMediaLibrary((prev: MediaFile[]) => prev.filter((m: MediaFile) => m.id !== mediaId));
  }, []);
  
  // Playback actions
  const play = useCallback(() => {
    setIsPlaying(true);
  }, []);
  
  const pause = useCallback(() => {
    setIsPlaying(false);
  }, []);
  
  const seek = useCallback((time: number) => {
    setCurrentTime(time);
  }, []);
  
  // Export action (placeholder)
  const exportSettings = useCallback(async (settings: ExportSettings) => {
    console.log('Exporting with settings:', settings);
    // Should be connected to API
  }, []);
  
  const value: VideoEditorContextType = {
    // State
    project,
    mediaLibrary,
    tracks,
    clips,
    selectedClipIds,
    selectedTrackId,
    activePanel,
    editorMode,
    previewUrl,
    isPlaying,
    currentTime,
    duration,
    isDirty,
    undoStack,
    redoStack,
    showExportDialog,
    showSettingsDialog,
    
    // Setters
    setProject,
    setMediaLibrary,
    setTracks,
    setClips,
    setSelectedClipIds,
    setSelectedTrackId,
    setActivePanel,
    setEditorMode,
    setPreviewUrl,
    setIsPlaying,
    setCurrentTime,
    setDuration,
    setShowExportDialog,
    setShowSettingsDialog,
    
    // Actions
    importMedia,
    addClipToTimeline,
    moveClip,
    trimClip,
    splitClip,
    deleteClips,
    updateClip,
    updateTrack,
    deleteMedia,
    selectClip,
    selectTrack,
    undo,
    redo,
    play,
    pause,
    seek,
    export: exportSettings,
    
    // Computed
    selectedClips,
    selectedTrack,
    canUndo,
    canRedo,
  };
  
  return (
    <VideoEditorContext.Provider value={value}>
      {children}
    </VideoEditorContext.Provider>
  );
};

export default VideoEditorContext;

import { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react';

// ============================================================================
// Wizard Context Types
// ============================================================================

export type WizardType =
  | 'world'
  | 'character'
  | 'storyteller'
  | 'dialogue-writer'
  | 'scene-generator'
  | 'storyboard-creator'
  | 'style-transfer'
  | 'sequence-plan'
  | 'shot'
  | 'project-setup'
  | 'object';

/**
 * Wizard chain configuration for triggering subsequent wizards
 */
export interface WizardChainConfig {
  /** The wizard type to trigger next */
  wizardType: WizardType;
  /** Whether this chain is auto-triggered or manual */
  autoTrigger: boolean;
  /** Initial data to pass to the next wizard */
  initialData?: Record<string, unknown>;
  /** Label for the chain button */
  label?: string;
  /** Description of what the next wizard will do */
  description?: string;
}

/**
 * Wizard chain state
 */
export interface WizardChainState {
  /** Whether wizard chaining is enabled */
  isChained: boolean;
  /** Array of wizard chains to trigger after completion */
  triggeredWizards: WizardChainConfig[];
  /** Current chain index */
  currentChainIndex: number;
  /** Data accumulated from previous wizards in the chain */
  chainData: Record<string, unknown>;
}

export interface WizardContextState<T> {
  currentStep: number;
  totalSteps: number;
  formData: Partial<T>;
  validationErrors: Record<string, string[]>;
  isSubmitting: boolean;
  isDirty: boolean;
  isManualMode: boolean; // Manual entry mode (fallback from LLM)
  
  // Wizard Chain State
  chainState: WizardChainState;
  
  // Actions
  goToStep: (step: number) => void;
  nextStep: () => Promise<void>;
  previousStep: () => void;
  updateFormData: (data: Partial<T>) => void;
  setValidationErrors: (errors: Record<string, string[]>) => void;
  validateStep: (step: number) => Promise<boolean>;
  submitWizard: () => Promise<void>;
  resetWizard: () => void;
  saveProgress: () => void;
  loadProgress: () => void;
  setManualMode: (enabled: boolean) => void;
  clearSavedProgress: () => void;
  hasSavedProgress: () => boolean;
  
  // Wizard Chain Actions
  setChainEnabled: (enabled: boolean) => void;
  addTriggeredWizard: (config: WizardChainConfig) => void;
  removeTriggeredWizard: (index: number) => void;
  clearTriggeredWizards: () => void;
  triggerNextWizard: () => WizardChainConfig | null;
  addToChainData: (key: string, value: unknown) => void;
  getChainData: () => Record<string, unknown>;
}

interface WizardProviderProps<T> {
  children: ReactNode;
  wizardType: WizardType;
  totalSteps: number;
  initialData?: Partial<T>;
  onSubmit: (data: T) => Promise<void>;
  onComplete?: (data: T) => void;
  onValidateStep?: (step: number, data: Partial<T>) => Promise<Record<string, string[]>>;
  autoSave?: boolean;
  autoSaveDelay?: number; // milliseconds
  autoLoad?: boolean; // NEW: defaults to false
}

// ============================================================================
// Context Creation
// ============================================================================

const WizardContext = createContext<WizardContextState<any> | null>(null);

// ============================================================================
// Wizard Provider Component
// ============================================================================

export function WizardProvider<T>({
  children,
  wizardType,
  totalSteps,
  initialData = {},
  onSubmit,
  onComplete,
  onValidateStep,
  autoSave = true,
  autoSaveDelay = 2000,
  autoLoad = false,
}: WizardProviderProps<T>) {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState<Partial<T>>(initialData);
  const [validationErrors, setValidationErrors] = useState<Record<string, string[]>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDirty, setIsDirty] = useState(false);
  const [isManualMode, setIsManualMode] = useState(false);
  const [autoSaveTimeout, setAutoSaveTimeout] = useState<NodeJS.Timeout | null>(null);

  // ============================================================================
  // Wizard Chain State
  // ============================================================================
  const [chainState, setChainState] = useState<WizardChainState>({
    isChained: false,
    triggeredWizards: [],
    currentChainIndex: 0,
    chainData: {},
  });

  // ============================================================================
  // Wizard Chain Functions
  // ============================================================================
  
  const setChainEnabled = useCallback((enabled: boolean) => {
    setChainState(prev => ({ ...prev, isChained: enabled }));
  }, []);

  const addTriggeredWizard = useCallback((config: WizardChainConfig) => {
    setChainState(prev => ({
      ...prev,
      triggeredWizards: [...prev.triggeredWizards, config],
    }));
  }, []);

  const removeTriggeredWizard = useCallback((index: number) => {
    setChainState(prev => ({
      ...prev,
      triggeredWizards: prev.triggeredWizards.filter((_, i) => i !== index),
    }));
  }, []);

  const clearTriggeredWizards = useCallback(() => {
    setChainState(prev => ({
      ...prev,
      triggeredWizards: [],
      currentChainIndex: 0,
      chainData: {},
    }));
  }, []);

  const triggerNextWizard = useCallback((): WizardChainConfig | null => {
    const { triggeredWizards, currentChainIndex } = chainState;
    
    // Check if there are more wizards in the chain
    if (currentChainIndex >= triggeredWizards.length) {
      return null;
    }
    
    // Get the next wizard config
    const nextWizard = triggeredWizards[currentChainIndex];
    
    // Increment chain index
    setChainState(prev => ({
      ...prev,
      currentChainIndex: prev.currentChainIndex + 1,
    }));
    
    return nextWizard;
  }, [chainState]);

  const addToChainData = useCallback((key: string, value: unknown) => {
    setChainState(prev => ({
      ...prev,
      chainData: { ...prev.chainData, [key]: value },
    }));
  }, []);

  const getChainData = useCallback((): Record<string, unknown> => {
    return chainState.chainData;
  }, [chainState]);

  // ============================================================================
  // Validation - MUST be defined BEFORE nextStep
  // ============================================================================

  const validateStep = useCallback(async (step: number, data?: Partial<T>): Promise<boolean> => {
    // Use provided data or fall back to current formData from closure
    const dataToValidate = data || formData;
    if (!onValidateStep) return true;

    try {
      const errors = await onValidateStep(step, dataToValidate);
      setValidationErrors(errors);
      return Object.keys(errors).length === 0;
    } catch (error) {
      console.error('Validation error:', error);
      return false;
    }
  }, [formData, onValidateStep]);

  // ============================================================================
  // Auto-save to localStorage
  // ============================================================================

  const saveProgress = useCallback(() => {
    try {
      const state = {
        wizardType,
        timestamp: new Date().toISOString(),
        currentStep,
        formData,
        isManualMode,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days
      };

      localStorage.setItem(`wizard-${wizardType}`, JSON.stringify(state));
    } catch (error) {
      console.error('Failed to save wizard progress:', error);
    }
  }, [wizardType, currentStep, formData, isManualMode]);

  const loadProgress = useCallback(() => {
    try {
      const saved = localStorage.getItem(`wizard-${wizardType}`);
      if (!saved) return;

      const state = JSON.parse(saved);

      // Check if expired
      if (new Date(state.expiresAt) < new Date()) {
        localStorage.removeItem(`wizard-${wizardType}`);
        return;
      }

      setCurrentStep(state.currentStep);
      setFormData(state.formData);
      setIsManualMode(state.isManualMode || false);
      setIsDirty(true);
    } catch (error) {
      console.error('Failed to load wizard progress:', error);
      // Clear corrupted state
      localStorage.removeItem(`wizard-${wizardType}`);
    }
  }, [wizardType]);

  // Check if saved progress exists without loading it
  const hasSavedProgress = useCallback((): boolean => {
    const saved = localStorage.getItem(`wizard-${wizardType}`);
    if (!saved) return false;

    try {
      const state = JSON.parse(saved);
      // Check if expired
      if (new Date(state.expiresAt) < new Date()) {
        return false;
      }
      return true;
    } catch {
      return false;
    }
  }, [wizardType]);

  // Load progress on mount only if autoLoad is true
  useEffect(() => {
    if (autoLoad) {
      loadProgress();
    }
  }, [loadProgress, autoLoad]);

  // Auto-save when form data changes
  useEffect(() => {
    if (!autoSave || !isDirty) return;

    // Clear existing timeout
    if (autoSaveTimeout) {
      clearTimeout(autoSaveTimeout);
    }

    // Set new timeout
    const timeout = setTimeout(() => {
      saveProgress();
    }, autoSaveDelay);

    setAutoSaveTimeout(timeout);

    return () => {
      if (timeout) clearTimeout(timeout);
    };
  }, [formData, autoSave, autoSaveDelay, isDirty, saveProgress]);

  // Reset validation errors when wizard first loads
  useEffect(() => {
    setValidationErrors({});
  }, [wizardType]);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (autoSaveTimeout) {
        clearTimeout(autoSaveTimeout);
      }
    };
  }, [autoSaveTimeout]);

  // ============================================================================
  // Navigation Actions
  // ============================================================================

  const goToStep = useCallback((step: number) => {
    if (step < 1 || step > totalSteps) return;
    setCurrentStep(step);
  }, [totalSteps]);

  const nextStep = useCallback(async () => {
    // Validate current step before proceeding
    const isValid = await validateStep(currentStep);
    if (isValid && currentStep < totalSteps) {
      setCurrentStep(currentStep + 1);
    }
  }, [currentStep, totalSteps, validateStep]);

  const previousStep = useCallback(() => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  }, [currentStep]);

  // ============================================================================
  // Form Data Actions
  // ============================================================================

  // Auto-validate when form data changes
  useEffect(() => {
    if (!onValidateStep || isDirty) return;

    // Only auto-validate for steps 1, 4, 5 which have validation requirements
    // Skip for steps 2 and 3 which are optional
    if (currentStep === 2 || currentStep === 3) return;

    validateStep(currentStep);
  }, [formData, currentStep, onValidateStep, validateStep, isDirty]);

  const updateFormData = useCallback((data: Partial<T>) => {
    setFormData((prev) => ({ ...prev, ...data }));
    setIsDirty(true);

    // Immediately clear validation errors for updated fields (sync operation)
    const updatedFields = Object.keys(data);
    setValidationErrors((prev) => {
      const newErrors = { ...prev };
      updatedFields.forEach((field) => {
        delete newErrors[field];
      });
      return newErrors;
    });

    // For immediate feedback, validate with the merged data
    if (onValidateStep) {
      // Use setTimeout to ensure we have the latest formData
      setTimeout(() => {
        validateStep(currentStep, { ...formData, ...data });
      }, 0);
    }
  }, [currentStep, onValidateStep, validateStep, formData]);

  // ============================================================================
  // Submission
  // ============================================================================

  const submitWizard = useCallback(async () => {
    setIsSubmitting(true);

    try {
      // Validate all steps
      let isValid = true;
      for (let step = 1; step <= totalSteps; step++) {
        const stepValid = await validateStep(step);
        if (!stepValid) {
          isValid = false;
          setCurrentStep(step); // Go to first invalid step
          break;
        }
      }

      if (!isValid) {
        setIsSubmitting(false);
        return;
      }

      // Submit the form
      await onSubmit(formData as T);

      // Call onComplete callback after successful submission
      if (onComplete) {
        onComplete(formData as T);
      }

      // Clear saved progress on successful submission
      localStorage.removeItem(`wizard-${wizardType}`);

      // Reset wizard state
      setFormData(initialData);
      setCurrentStep(1);
      setIsDirty(false);
      setValidationErrors({});
    } catch (error) {
      console.error('Wizard submission error:', error);
      throw error;
    } finally {
      setIsSubmitting(false);
    }
  }, [formData, totalSteps, validateStep, onSubmit, onComplete, wizardType, initialData]);

  // ============================================================================
  // Reset
  // ============================================================================

  const resetWizard = useCallback(() => {
    setFormData(initialData);
    setCurrentStep(1);
    setValidationErrors({});
    setIsDirty(false);
    setIsManualMode(false);
    localStorage.removeItem(`wizard-${wizardType}`);
  }, [initialData, wizardType]);

  // ============================================================================
  // Clear Saved Progress (for fresh start)
  // ============================================================================

  const clearSavedProgress = useCallback(() => {
    localStorage.removeItem(`wizard-${wizardType}`);
    setIsDirty(false);
  }, [wizardType]);

  // ============================================================================
  // Manual Mode Toggle
  // ============================================================================

  const setManualMode = useCallback((enabled: boolean) => {
    setIsManualMode(enabled);
  }, []);

  // ============================================================================
  // Context Value
  // ============================================================================

  const value: WizardContextState<T> = {
    currentStep,
    totalSteps,
    formData,
    validationErrors,
    isSubmitting,
    isDirty,
    isManualMode,
    chainState,
    goToStep,
    nextStep,
    previousStep,
    updateFormData,
    setValidationErrors,
    validateStep,
    submitWizard,
    resetWizard,
    saveProgress,
    loadProgress,
    setManualMode,
    clearSavedProgress,
    hasSavedProgress,
    setChainEnabled,
    addTriggeredWizard,
    removeTriggeredWizard,
    clearTriggeredWizards,
    triggerNextWizard,
    addToChainData,
    getChainData,
  };

  return (
    <WizardContext.Provider value={value}>
      {children}
    </WizardContext.Provider>
  );
}

// ============================================================================
// Hook to use Wizard Context
// ============================================================================

export function useWizard<T>(): WizardContextState<T> {
  const context = useContext(WizardContext);

  if (!context) {
    throw new Error('useWizard must be used within a WizardProvider');
  }

  return context as WizardContextState<T>;
}

