  return [...GENERATION_PRESETS]
    .sort((a, b) => b.qualityScore - a.qualityScore)
    .slice(0, limit);
};

/**
 * AnimationOrchestrationExample Component
 * 
 * Demonstrates animation orchestration to prevent visual conflicts.
 * Shows sequential, parallel, and staggered animation patterns.
 * 
 * Validates: Requirements 11.8
 */

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import {
  useAnimationOrchestrator,
  useSequentialAnimations,
  useParallelAnimations,
  useStaggeredAnimations,
} from '../hooks/useAnimationOrchestrator';

/**
 * Example of orchestrated animations
 */
export function AnimationOrchestrationExample() {
  const [status, setStatus] = useState('');
  const { executeAnimation, getStatus } = useAnimationOrchestrator();
  const { executeSequence } = useSequentialAnimations();
  const { executeParallel } = useParallelAnimations();
  const { executeStaggered } = useStaggeredAnimations(150);

  const [box1, setBox1] = useState({ x: 0, color: 'bg-blue-500' });
  const [box2, setBox2] = useState({ x: 0, color: 'bg-green-500' });
  const [box3, setBox3] = useState({ x: 0, color: 'bg-red-500' });

  const animateBox = async (
    boxId: number,
    setter: React.Dispatch<React.SetStateAction<any>>,
    distance: number
  ) => {
    return new Promise<void>((resolve) => {
      setter((prev: unknown) => ({ ...prev, x: distance }));
      setTimeout(() => {
        setter((prev: unknown) => ({ ...prev, x: 0 }));
        resolve();
      }, 500);
    });
  };

  const handleSequential = async () => {
    setStatus('Running sequential animations...');

    await executeSequence([
      {
        id: 'box1-seq',
        execute: () => animateBox(1, setBox1, 200),
      },
      {
        id: 'box2-seq',
        execute: () => animateBox(2, setBox2, 200),
      },
      {
        id: 'box3-seq',
        execute: () => animateBox(3, setBox3, 200),
      },
    ]);

    setStatus('Sequential animations complete!');
  };

  const handleParallel = async () => {
    setStatus('Running parallel animations...');

    await executeParallel([
      {
        id: 'box1-par',
        execute: () => animateBox(1, setBox1, 200),
      },
      {
        id: 'box2-par',
        execute: () => animateBox(2, setBox2, 200),
      },
      {
        id: 'box3-par',
        execute: () => animateBox(3, setBox3, 200),
      },
    ]);

    setStatus('Parallel animations complete!');
  };

  const handleStaggered = async () => {
    setStatus('Running staggered animations...');

    await executeStaggered([
      {
        id: 'box1-stag',
        execute: () => animateBox(1, setBox1, 200),
      },
      {
        id: 'box2-stag',
        execute: () => animateBox(2, setBox2, 200),
      },
      {
        id: 'box3-stag',
        execute: () => animateBox(3, setBox3, 200),
      },
    ]);

    setStatus('Staggered animations complete!');
  };

  const handleConflicting = async () => {
    setStatus('Running conflicting animations (orchestrator will manage)...');

    // Try to animate the same box multiple times
    // Orchestrator will queue them to prevent conflicts
    await Promise.all([
      executeAnimation('box1-conflict-1', () => animateBox(1, setBox1, 100)),
      executeAnimation('box1-conflict-2', () => animateBox(1, setBox1, 200)),
      executeAnimation('box1-conflict-3', () => animateBox(1, setBox1, 150)),
    ]);

    setStatus('Conflicting animations resolved!');
  };

  const updateStatus = () => {
    const orchestratorStatus = getStatus();
    setStatus(
      `Running: ${orchestratorStatus.running}, Queued: ${orchestratorStatus.queued}`
    );
  };

  return (
    <div className="p-8 space-y-8">
      <div>
        <h2 className="text-2xl font-bold mb-2">Animation Orchestration Demo</h2>
        <p className="text-gray-600">
          Demonstrates how the orchestrator manages multiple animations to
          prevent visual conflicts.
        </p>
      </div>

      <div className="space-y-4">
        <div className="flex gap-4">
          <button
            onClick={handleSequential}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            Sequential
          </button>
          <button
            onClick={handleParallel}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
          >
            Parallel
          </button>
          <button
            onClick={handleStaggered}
            className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700"
          >
            Staggered
          </button>
          <button
            onClick={handleConflicting}
            className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
          >
            Conflicting (Managed)
          </button>
          <button
            onClick={updateStatus}
            className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
          >
            Check Status
          </button>
        </div>

        {status && (
          <div className="p-4 bg-blue-50 text-blue-800 rounded-lg">
            {status}
          </div>
        )}
      </div>

      <div className="space-y-4">
        <motion.div
          animate={{ x: box1.x }}
          transition={{ duration: 0.5 }}
          className={`w-20 h-20 ${box1.color} rounded-lg`}
        />
        <motion.div
          animate={{ x: box2.x }}
          transition={{ duration: 0.5 }}
          className={`w-20 h-20 ${box2.color} rounded-lg`}
        />
        <motion.div
          animate={{ x: box3.x }}
          transition={{ duration: 0.5 }}
          className={`w-20 h-20 ${box3.color} rounded-lg`}
        />
      </div>

      <div className="p-4 bg-gray-100 rounded-lg space-y-2">
        <h3 className="font-semibold">How It Works</h3>
        <ul className="text-sm text-gray-700 space-y-1 list-disc list-inside">
          <li>
            <strong>Sequential:</strong> Animations run one after another
          </li>
          <li>
            <strong>Parallel:</strong> All animations run simultaneously
          </li>
          <li>
            <strong>Staggered:</strong> Animations start with a delay between
            each
          </li>
          <li>
            <strong>Conflicting:</strong> Orchestrator queues conflicting
            animations to prevent visual issues
          </li>
        </ul>
      </div>
    </div>
  );
}

/**
 * Central Configuration UI - Usage Example
 * 
 * This example demonstrates how to integrate the Central Configuration UI
 * into your application.
 */

import React, { useState } from 'react';
import { CentralConfigurationUI } from '../components';

export function CentralConfigurationUIExample() {
  const [isOpen, setIsOpen] = useState(false);
  const [currentProject, setCurrentProject] = useState({
    id: 'demo-project-123',
    name: 'My Awesome Project',
  });

  return (
    <div>
      {/* Your application content */}
      <div style={{ padding: '20px' }}>
        <h1>My Application</h1>
        <button onClick={() => setIsOpen(true)}>
          Open Configuration
        </button>
      </div>

      {/* Central Configuration UI */}
      {isOpen && (
        <CentralConfigurationUI
          projectId={currentProject.id}
          projectName={currentProject.name}
          onClose={() => setIsOpen(false)}
        />
      )}
    </div>
  );
}

/**
 * Alternative: Embedded in a page (without modal overlay)
 */
export function EmbeddedConfigurationExample() {
  const projectId = 'demo-project-456';
  const projectName = 'Embedded Project';

  return (
    <div style={{ minHeight: '100vh' }}>
      <CentralConfigurationUI
        projectId={projectId}
        projectName={projectName}
        // No onClose prop = no close button
      />
    </div>
  );
}

/**
 * Alternative: Using configuration context directly
 */
import { ConfigurationProvider, useConfiguration } from '../components';

function MyCustomComponent() {
  const {
    projectConfig,
    saveProjectConfig,
    isLoading,
  } = useConfiguration();

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h2>Custom Configuration Component</h2>
      <pre>{JSON.stringify(projectConfig, null, 2)}</pre>
      <button
        onClick={() => {
          const currentApi = projectConfig?.api || {
            endpoints: {},
            defaultTimeout: 30000,
            enableLogging: false,
          };
          saveProjectConfig({
            api: {
              ...currentApi,
              enableLogging: true,
            },
          });
        }}
      >
        Enable API Logging
      </button>
    </div>
  );
}

export function CustomConfigurationExample() {
  return (
    <ConfigurationProvider>
      <MyCustomComponent />
    </ConfigurationProvider>
  );
}

/**
 * Configuration Export/Import Example
 * 
 * Demonstrates the usage of the configuration export/import system
 * for the grid editor.
 */

import React, { useState } from 'react';
import { ConfigurationExportImport } from '../components/gridEditor/ConfigurationExportImport';
import type { GridEditorConfiguration } from '../services/gridEditor/ConfigurationExportImport';
import type { GridLayoutConfig, GridPanel } from '../types/gridEditorAdvanced';

export const ConfigurationExportImportExample: React.FC = () => {
  const [showDialog, setShowDialog] = useState(false);
  const [configuration, setConfiguration] = useState<GridEditorConfiguration>({
    layout: {
      columns: 3,
      rows: 3,
      gap: 16,
      cellSize: { width: 200, height: 200 },
      snapEnabled: true,
      snapThreshold: 10,
      showGridLines: true
    },
    visualPreferences: {
      theme: 'light',
      showGridLines: true,
      showAlignmentGuides: true,
      animationsEnabled: true
    },
    snapSettings: {
      enabled: true,
      threshold: 10,
      gridSizes: [8, 16, 24, 32]
    },
    panels: []
  });

  const handleImport = (newConfig: GridEditorConfiguration) => {
    setConfiguration(newConfig);
    ;
  };

  return (
    <div style={{ padding: '40px', maxWidth: '1200px', margin: '0 auto' }}>
      <h1 style={{ marginBottom: '24px' }}>Configuration Export/Import Example</h1>
      
      <div style={{
        padding: '24px',
        background: '#f5f5f5',
        borderRadius: '12px',
        marginBottom: '24px'
      }}>
        <h2 style={{ marginTop: 0 }}>Current Configuration</h2>
        
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '16px' }}>
          <ConfigSection title="Layout">
            <ConfigItem label="Columns" value={configuration.layout.columns} />
            <ConfigItem label="Rows" value={configuration.layout.rows} />
            <ConfigItem label="Gap" value={`${configuration.layout.gap}px`} />
            <ConfigItem 
              label="Cell Size" 
              value={`${configuration.layout.cellSize.width}x${configuration.layout.cellSize.height}`} 
            />
            <ConfigItem label="Snap Enabled" value={configuration.layout.snapEnabled ? 'Yes' : 'No'} />
            <ConfigItem label="Snap Threshold" value={configuration.layout.snapThreshold} />
          </ConfigSection>

          <ConfigSection title="Visual Preferences">
            <ConfigItem label="Theme" value={configuration.visualPreferences.theme || 'default'} />
            <ConfigItem 
              label="Show Grid Lines" 
              value={configuration.visualPreferences.showGridLines ? 'Yes' : 'No'} 
            />
            <ConfigItem 
              label="Show Alignment Guides" 
              value={configuration.visualPreferences.showAlignmentGuides ? 'Yes' : 'No'} 
            />
            <ConfigItem 
              label="Animations" 
              value={configuration.visualPreferences.animationsEnabled ? 'Enabled' : 'Disabled'} 
            />
          </ConfigSection>

          <ConfigSection title="Snap Settings">
            <ConfigItem label="Enabled" value={configuration.snapSettings.enabled ? 'Yes' : 'No'} />
            <ConfigItem label="Threshold" value={configuration.snapSettings.threshold} />
            <ConfigItem 
              label="Grid Sizes" 
              value={configuration.snapSettings.gridSizes.join(', ')} 
            />
          </ConfigSection>

          <ConfigSection title="Panels">
            <ConfigItem label="Count" value={configuration.panels?.length || 0} />
          </ConfigSection>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
        <button
          onClick={() => setShowDialog(true)}
          style={{
            padding: '12px 24px',
            background: '#2196F3',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            fontSize: '16px',
            fontWeight: 600,
            cursor: 'pointer'
          }}
        >
          📤 Export / 📥 Import Configuration
        </button>

        <button
          onClick={() => {
            setConfiguration({
              ...configuration,
              layout: {
                ...configuration.layout,
                columns: Math.floor(Math.random() * 5) + 2,
                gap: Math.floor(Math.random() * 20) + 8
              }
            });
          }}
          style={{
            padding: '12px 24px',
            background: '#757575',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            fontSize: '16px',
            cursor: 'pointer'
          }}
        >
          🎲 Randomize Configuration
        </button>
      </div>

      {/* Features List */}
      <div style={{
        padding: '24px',
        background: 'white',
        border: '1px solid #e0e0e0',
        borderRadius: '12px'
      }}>
        <h2 style={{ marginTop: 0 }}>Features</h2>
        
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '16px' }}>
          <FeatureCard
            icon="📄"
            title="JSON Export"
            description="Export configuration as a JSON file for easy storage and version control"
          />
          <FeatureCard
            icon="📋"
            title="YAML Export"
            description="Export as human-readable YAML format for documentation"
          />
          <FeatureCard
            icon="🔗"
            title="URL Sharing"
            description="Generate shareable URLs with base64-encoded configuration"
          />
          <FeatureCard
            icon="📥"
            title="Import from File"
            description="Import configurations from JSON or YAML files"
          />
          <FeatureCard
            icon="🔄"
            title="Conflict Resolution"
            description="Automatically detect and resolve configuration conflicts"
          />
          <FeatureCard
            icon="📦"
            title="Template Export"
            description="Export reusable templates without panel positions"
          />
          <FeatureCard
            icon="✅"
            title="Validation"
            description="Comprehensive validation with detailed error messages"
          />
          <FeatureCard
            icon="🔍"
            title="Smart Merge"
            description="Intelligent merging of configurations with conflict detection"
          />
        </div>
      </div>

      {/* Usage Instructions */}
      <div style={{
        marginTop: '24px',
        padding: '24px',
        background: '#e3f2fd',
        borderRadius: '12px'
      }}>
        <h3 style={{ marginTop: 0 }}>How to Use</h3>
        <ol style={{ marginBottom: 0 }}>
          <li style={{ marginBottom: '8px' }}>
            Click "Export / Import Configuration" to open the dialog
          </li>
          <li style={{ marginBottom: '8px' }}>
            <strong>Export:</strong> Choose format (JSON, YAML, or URL) and export type (Full or Template)
          </li>
          <li style={{ marginBottom: '8px' }}>
            <strong>Import:</strong> Upload a file or paste a configuration URL
          </li>
          <li style={{ marginBottom: '8px' }}>
            If conflicts are detected, choose a resolution strategy
          </li>
          <li>
            The configuration will be applied to your grid editor
          </li>
        </ol>
      </div>

      {/* Dialog */}
      {showDialog && (
        <>
          {/* Backdrop */}
          <div
            onClick={() => setShowDialog(false)}
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: 'rgba(0, 0, 0, 0.5)',
              zIndex: 9999
            }}
          />
          
          {/* Dialog */}
          <ConfigurationExportImport
            currentConfiguration={configuration}
            onImport={handleImport}
            onClose={() => setShowDialog(false)}
          />
        </>
      )}

      {/* Notification Listener */}
      <NotificationListener />
    </div>
  );
};

