import { renderHook, act, waitFor } from '@testing-library/react';
import { useLandingPage } from '../useLandingPage';
import { useAppStore } from '@/stores/useAppStore';

// Mock the store
vi.mock('@/stores/useAppStore');

describe('useLandingPage - Project Validation Integration', () => {
  let mockSetProject: ReturnType<typeof vi.fn>;
  let mockSetShots: ReturnType<typeof vi.fn>;
  let mockElectronAPI: any;

  beforeEach(() => {
    // Reset mocks
    mockSetProject = vi.fn();
    mockSetShots = vi.fn();

    // Mock store - need to mock the selector function
    (useAppStore as any).mockImplementation((selector: any) => {
      const state = {
        setProject: mockSetProject,
        setShots: mockSetShots,
      };
      return selector(state);
    });

    // Mock Electron API
    mockElectronAPI = {
      project: {
        open: vi.fn(),
        selectForOpen: vi.fn(),
      },
      recentProjects: {
        get: vi.fn().mockResolvedValue([]),
      },
    };

    // Set up window.electronAPI
    (window as any).electronAPI = mockElectronAPI;
  });

  afterEach(() => {
    // Clean up
    delete (window as any).electronAPI;
    vi.clearAllMocks();
  });

  describe('Validation with valid project directories', () => {
    it('should successfully open a valid project directory', async () => {
      // Arrange
      const validProjectPath = '/path/to/valid/project';
      const mockProject = {
        id: 'test-id',
        name: 'Test Project',
        path: validProjectPath,
        version: '1.0.0',
        createdAt: new Date(),
        modifiedAt: new Date(),
        config: {
          schema_version: '1.0',
          project_name: 'Test Project',
          capabilities: {
            grid_generation: true,
            promotion_engine: true,
            qa_engine: true,
            autofix_engine: true,
          },
          generation_status: {
            grid: 'pending' as const,
            promotion: 'pending' as const,
          },
        },
      };

      mockElectronAPI.project.open.mockResolvedValue(mockProject);

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        await result.current.handleOpenProjectSubmit(validProjectPath);
      });

      // Assert
      expect(mockElectronAPI.project.open).toHaveBeenCalledWith(validProjectPath);
      expect(mockSetProject).toHaveBeenCalled();
      expect(mockSetShots).toHaveBeenCalled();
      expect(result.current.error).toBeNull();
    });

    it('should handle project with all required fields', async () => {
      // Arrange
      const projectPath = '/path/to/complete/project';
      const completeProject = {
        id: 'complete-id',
        name: 'Complete Project',
        path: projectPath,
        version: '1.0.0',
        createdAt: new Date(),
        modifiedAt: new Date(),
        config: {
          schema_version: '1.0',
          project_name: 'Complete Project',
          shots: [{ id: 'shot1', name: 'Shot 1' }],
          assets: [{ id: 'asset1', name: 'Asset 1' }],
          capabilities: {
            grid_generation: true,
            promotion_engine: true,
            qa_engine: true,
            autofix_engine: true,
          },
          generation_status: {
            grid: 'done' as const,
            promotion: 'done' as const,
          },
          metadata: {
            id: 'complete-id',
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          },
        },
      };

      mockElectronAPI.project.open.mockResolvedValue(completeProject);

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        await result.current.handleOpenProjectSubmit(projectPath);
      });

      // Assert
      expect(mockElectronAPI.project.open).toHaveBeenCalledWith(projectPath);
      expect(mockSetProject).toHaveBeenCalled();
      expect(result.current.error).toBeNull();
    });
  });

  describe('Validation with invalid directories', () => {
    it('should display error for non-existent directory', async () => {
      // Arrange
      const invalidPath = '/path/to/nonexistent/project';
      const errorMessage = 'Project directory does not exist';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(invalidPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockElectronAPI.project.open).toHaveBeenCalledWith(invalidPath);
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should display error for directory without project.json', async () => {
      // Arrange
      const invalidPath = '/path/to/empty/directory';
      const errorMessage = "Required file 'project.json' is missing";

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(invalidPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should display error for corrupted project.json', async () => {
      // Arrange
      const invalidPath = '/path/to/corrupted/project';
      const errorMessage = 'Invalid JSON syntax';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(invalidPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should display error for project with missing required fields', async () => {
      // Arrange
      const invalidPath = '/path/to/incomplete/project';
      const errorMessage = 'Missing or invalid project_name';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(invalidPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should display error for permission denied', async () => {
      // Arrange
      const restrictedPath = '/path/to/restricted/project';
      const errorMessage = 'Insufficient permissions to access project directory';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(restrictedPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockSetProject).not.toHaveBeenCalled();
    });
  });

  describe('Validation with project.json files', () => {
    it('should validate parent directory when project.json file is selected', async () => {
      // Arrange
      const parentDirectory = '/path/to/project';
      
      // Mock selectForOpen to return the parent directory (as IPC handler does path normalization)
      mockElectronAPI.project.selectForOpen.mockResolvedValue(parentDirectory);
      
      const mockProject = {
        id: 'test-id',
        name: 'Test Project',
        path: parentDirectory,
        version: '1.0.0',
        createdAt: new Date(),
        modifiedAt: new Date(),
        config: {
          schema_version: '1.0',
          project_name: 'Test Project',
          capabilities: {
            grid_generation: true,
            promotion_engine: true,
            qa_engine: true,
            autofix_engine: true,
          },
          generation_status: {
            grid: 'pending' as const,
            promotion: 'pending' as const,
          },
        },
      };

      mockElectronAPI.project.open.mockResolvedValue(mockProject);

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        await result.current.handleOpenProject();
      });

      // Assert
      expect(mockElectronAPI.project.selectForOpen).toHaveBeenCalled();
      expect(mockElectronAPI.project.open).toHaveBeenCalledWith(parentDirectory);
      expect(mockSetProject).toHaveBeenCalled();
      expect(result.current.error).toBeNull();
    });

    it('should handle validation failure when parent directory is invalid', async () => {
      // Arrange
      const parentDirectory = '/path/to/invalid';
      
      mockElectronAPI.project.selectForOpen.mockResolvedValue(parentDirectory);
      
      const errorMessage = 'Missing or invalid capabilities object';
      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        await result.current.handleOpenProject();
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockElectronAPI.project.open).toHaveBeenCalledWith(parentDirectory);
      expect(mockSetProject).not.toHaveBeenCalled();
    });
  });

  describe('Error message verification', () => {
    it('should display descriptive error for missing files', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      const errorMessage = "Required file 'project.json' is missing";

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
        expect(result.current.error).toContain('project.json');
      });
    });

    it('should display descriptive error for configuration issues', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      const errorMessage = 'Configuration errors: 3 issue(s)';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
        expect(result.current.error).toContain('Configuration');
      });
    });

    it('should display descriptive error for permission issues', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      const errorMessage = 'Permission denied';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
        expect(result.current.error).toContain('Permission');
      });
    });

    it('should clear error when clearError is called', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      const errorMessage = 'Test error';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act - trigger error
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });

      // Act - clear error
      act(() => {
        result.current.clearError();
      });

      // Assert
      expect(result.current.error).toBeNull();
    });
  });

  describe('Validation precedes loading', () => {
    it('should call project.open (which validates) before updating store', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      const callOrder: string[] = [];

      mockElectronAPI.project.open.mockImplementation(async () => {
        callOrder.push('validate');
        return {
          id: 'test-id',
          name: 'Test Project',
          path: projectPath,
          version: '1.0.0',
          createdAt: new Date(),
          modifiedAt: new Date(),
          config: {
            schema_version: '1.0',
            project_name: 'Test Project',
            capabilities: {
              grid_generation: true,
              promotion_engine: true,
              qa_engine: true,
              autofix_engine: true,
            },
            generation_status: {
              grid: 'pending' as const,
              promotion: 'pending' as const,
            },
          },
        };
      });

      mockSetProject.mockImplementation(() => {
        callOrder.push('setProject');
      });

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        await result.current.handleOpenProjectSubmit(projectPath);
      });

      // Assert
      expect(callOrder).toEqual(['validate', 'setProject']);
      expect(mockElectronAPI.project.open).toHaveBeenCalled();
      expect(mockSetProject).toHaveBeenCalled();
    });

    it('should not update store if validation fails', async () => {
      // Arrange
      const projectPath = '/path/to/invalid/project';
      const errorMessage = 'Validation failed';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.error).toBe(errorMessage);
      });
      expect(mockElectronAPI.project.open).toHaveBeenCalled();
      expect(mockSetProject).not.toHaveBeenCalled();
      expect(mockSetShots).not.toHaveBeenCalled();
    });
  });

  describe('Loading state during validation', () => {
    it('should set loading state during validation', async () => {
      // Arrange
      const projectPath = '/path/to/project';
      let resolveOpen: any;
      const openPromise = new Promise((resolve) => {
        resolveOpen = resolve;
      });

      mockElectronAPI.project.open.mockReturnValue(openPromise);

      const { result } = renderHook(() => useLandingPage());

      // Act - start opening
      act(() => {
        result.current.handleOpenProjectSubmit(projectPath);
      });

      // Assert - loading should be true
      await waitFor(() => {
        expect(result.current.isLoading).toBe(true);
      });

      // Complete the operation
      await act(async () => {
        resolveOpen({
          id: 'test-id',
          name: 'Test Project',
          path: projectPath,
          version: '1.0.0',
          createdAt: new Date(),
          modifiedAt: new Date(),
          config: {
            schema_version: '1.0',
            project_name: 'Test Project',
            capabilities: {
              grid_generation: true,
              promotion_engine: true,
              qa_engine: true,
              autofix_engine: true,
            },
            generation_status: {
              grid: 'pending' as const,
              promotion: 'pending' as const,
            },
          },
        });
        await openPromise;
      });

      // Assert - loading should be false
      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
      });
    });

    it('should clear loading state after validation failure', async () => {
      // Arrange
      const projectPath = '/path/to/invalid/project';
      const errorMessage = 'Validation failed';

      mockElectronAPI.project.open.mockRejectedValue(new Error(errorMessage));

      const { result } = renderHook(() => useLandingPage());

      // Act
      await act(async () => {
        try {
          await result.current.handleOpenProjectSubmit(projectPath);
        } catch (error) {
          // Expected to throw
        }
      });

      // Assert
      await waitFor(() => {
        expect(result.current.isLoading).toBe(false);
        expect(result.current.error).toBe(errorMessage);
      });
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useLayoutPersistence } from '../useLayoutPersistence';
import { useAppStore } from '@/stores/useAppStore';

// Mock the store
vi.mock('@/stores/useAppStore');

// Mock localStorage
const localStorageMock = (() => {
  let store: Record<string, string> = {};

  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    },
  };
})();

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
});

describe('useLayoutPersistence', () => {
  const mockSetPanelSizes = vi.fn();
  const mockSetShowChat = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    localStorageMock.clear();

    (useAppStore as any).mockReturnValue({
      panelSizes: {
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      },
      setPanelSizes: mockSetPanelSizes,
      showChat: false,
      setShowChat: mockSetShowChat,
    });
  });

  afterEach(() => {
    localStorageMock.clear();
  });

  describe('Loading Layout', () => {
    it('loads layout from localStorage on mount', () => {
      const savedLayout = {
        panelSizes: {
          assetLibrary: 25,
          canvas: 45,
          propertiesOrChat: 30,
        },
        showChat: true,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(savedLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).toHaveBeenCalledWith(savedLayout.panelSizes);
      expect(mockSetShowChat).toHaveBeenCalledWith(true);
    });

    it('does not load if no saved layout exists', () => {
      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).not.toHaveBeenCalled();
      expect(mockSetShowChat).not.toHaveBeenCalled();
    });

    it('handles invalid JSON gracefully', () => {
      localStorageMock.setItem('creative-studio-layout', 'invalid json');

      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      renderHook(() => useLayoutPersistence());

      expect(consoleErrorSpy).toHaveBeenCalled();
      expect(localStorageMock.getItem('creative-studio-layout')).toBeNull();

      consoleErrorSpy.mockRestore();
    });

    it('validates panel sizes before loading', () => {
      const invalidLayout = {
        panelSizes: {
          assetLibrary: -10, // invalid
          canvas: 50,
          propertiesOrChat: 60,
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(invalidLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).not.toHaveBeenCalled();
    });

    it('rejects panel sizes with invalid total', () => {
      const invalidLayout = {
        panelSizes: {
          assetLibrary: 20,
          canvas: 50,
          propertiesOrChat: 40, // total = 110
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(invalidLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).not.toHaveBeenCalled();
    });

    it('rejects panel sizes with values out of range', () => {
      const invalidLayout = {
        panelSizes: {
          assetLibrary: 150, // > 100
          canvas: -20, // < 0
          propertiesOrChat: 30,
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(invalidLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).not.toHaveBeenCalled();
    });
  });

  describe('Saving Layout', () => {
    it('saves layout to localStorage when panel sizes change', () => {
      const { rerender } = renderHook(() => useLayoutPersistence());

      // Change panel sizes
      (useAppStore as any).mockReturnValue({
        panelSizes: {
          assetLibrary: 25,
          canvas: 45,
          propertiesOrChat: 30,
        },
        setPanelSizes: mockSetPanelSizes,
        showChat: false,
        setShowChat: mockSetShowChat,
      });

      rerender();

      const saved = localStorageMock.getItem('creative-studio-layout');
      expect(saved).toBeTruthy();

      const parsed = JSON.parse(saved!);
      expect(parsed.panelSizes).toEqual({
        assetLibrary: 25,
        canvas: 45,
        propertiesOrChat: 30,
      });
    });

    it('saves layout to localStorage when chat visibility changes', () => {
      const { rerender } = renderHook(() => useLayoutPersistence());

      // Change chat visibility
      (useAppStore as any).mockReturnValue({
        panelSizes: {
          assetLibrary: 20,
          canvas: 50,
          propertiesOrChat: 30,
        },
        setPanelSizes: mockSetPanelSizes,
        showChat: true,
        setShowChat: mockSetShowChat,
      });

      rerender();

      const saved = localStorageMock.getItem('creative-studio-layout');
      expect(saved).toBeTruthy();

      const parsed = JSON.parse(saved!);
      expect(parsed.showChat).toBe(true);
    });

    it('includes version in saved layout', () => {
      renderHook(() => useLayoutPersistence());

      const saved = localStorageMock.getItem('creative-studio-layout');
      expect(saved).toBeTruthy();

      const parsed = JSON.parse(saved!);
      expect(parsed.version).toBe('1.0');
    });

    it('handles localStorage errors gracefully', () => {
      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      // Mock setItem to throw error
      vi.spyOn(localStorageMock, 'setItem').mockImplementation(() => {
        throw new Error('Storage full');
      });

      renderHook(() => useLayoutPersistence());

      expect(consoleErrorSpy).toHaveBeenCalled();

      consoleErrorSpy.mockRestore();
    });
  });

  describe('clearSavedLayout', () => {
    it('removes layout from localStorage', () => {
      localStorageMock.setItem('creative-studio-layout', JSON.stringify({ test: 'data' }));

      const { result } = renderHook(() => useLayoutPersistence());

      act(() => {
        result.current.clearSavedLayout();
      });

      expect(localStorageMock.getItem('creative-studio-layout')).toBeNull();
    });

    it('handles errors gracefully', () => {
      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      // Mock removeItem to throw error
      vi.spyOn(localStorageMock, 'removeItem').mockImplementation(() => {
        throw new Error('Storage error');
      });

      const { result } = renderHook(() => useLayoutPersistence());

      act(() => {
        result.current.clearSavedLayout();
      });

      expect(consoleErrorSpy).toHaveBeenCalled();

      consoleErrorSpy.mockRestore();
    });
  });

  describe('hasSavedLayout', () => {
    it('returns true when layout exists', () => {
      localStorageMock.setItem('creative-studio-layout', JSON.stringify({ test: 'data' }));

      const { result } = renderHook(() => useLayoutPersistence());

      expect(result.current.hasSavedLayout()).toBe(true);
    });

    it('returns false when layout does not exist', () => {
      const { result } = renderHook(() => useLayoutPersistence());

      expect(result.current.hasSavedLayout()).toBe(false);
    });

    it('handles errors gracefully', () => {
      // Mock getItem to throw error
      vi.spyOn(localStorageMock, 'getItem').mockImplementation(() => {
        throw new Error('Storage error');
      });

      const { result } = renderHook(() => useLayoutPersistence());

      expect(result.current.hasSavedLayout()).toBe(false);
    });
  });

  describe('Validation', () => {
    it('accepts valid panel sizes', () => {
      const validLayout = {
        panelSizes: {
          assetLibrary: 20,
          canvas: 50,
          propertiesOrChat: 30,
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(validLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).toHaveBeenCalledWith(validLayout.panelSizes);
    });

    it('rejects panel sizes with missing properties', () => {
      const invalidLayout = {
        panelSizes: {
          assetLibrary: 20,
          canvas: 50,
          // missing propertiesOrChat
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(invalidLayout));

      renderHook(() => useLayoutPersistence());

      expect(mockSetPanelSizes).not.toHaveBeenCalled();
    });

    it('rejects panel sizes with non-number values', () => {
      const invalidLayout = {
        panelSizes: {
          assetLibrary: '20', // string instead of number
          canvas: 50,
          propertiesOrChat: 30,
        },
        showChat: false,
        version: '1.0',
      };

      localStorageMock.setItem('creative-studio-layout', JSON.stringify(invalidLayout));

      renderHook(() => useLayoutPersistence());

