        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 15,
          canvas: 45,
          propertiesOrChat: 40,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.resetPanelSizes();
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      });
    });
  });

  describe('isAssetLibraryVisible', () => {
    it('returns true when asset library has size', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.isAssetLibraryVisible).toBe(true);
    });

    it('returns false when asset library has zero size', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 0,
          canvas: 70,
          propertiesOrChat: 30,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.isAssetLibraryVisible).toBe(false);
    });
  });

  describe('return values', () => {
    it('returns showChat from store', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.showChat).toBe(false);
    });

    it('returns panelSizes from store', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.panelSizes).toEqual({
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      });
    });
  });
});

/**
 * Tests for useProgressTracking Hook
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useProgressTracking } from '../useProgressTracking';
import { useAppStore } from '@/stores/useAppStore';
import type { GenerationTask } from '@/types';

// Mock the store
vi.mock('@/stores/useAppStore');

// Mock the service
vi.mock('@/services/progressTrackingService', () => ({
  createProgressTrackingService: vi.fn(() => ({
    startTracking: vi.fn(),
    stopTracking: vi.fn(),
    stopAllTracking: vi.fn(),
    isTracking: vi.fn(() => false),
    getTrackedTaskIds: vi.fn(() => []),
    fetchProgress: vi.fn(),
  })),
  ProgressTrackingService: vi.fn(),
  MockProgressTrackingService: vi.fn(),
}));

describe('useProgressTracking', () => {
  const mockTask: GenerationTask = {
    id: 'task-1',
    shotId: 'shot-1',
    type: 'grid',
    status: 'processing',
    priority: 1,
    createdAt: new Date(),
  };

  beforeEach(() => {
    vi.useFakeTimers();
    
    // Setup store mock
    (useAppStore as any).mockImplementation((selector: any) => {
      const state = {
        taskQueue: [mockTask],
        reorderTasks: vi.fn(),
      };
      return selector ? selector(state) : state;
    });

    (useAppStore as any).getState = vi.fn(() => ({
      taskQueue: [mockTask],
      reorderTasks: vi.fn(),
    }));
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  describe('initialization', () => {
    it('should initialize with default options', () => {
      const { result } = renderHook(() => useProgressTracking());

      expect(result.current.progressUpdates).toBeInstanceOf(Map);
      expect(result.current.trackedTaskIds).toEqual([]);
    });

    it('should initialize with custom options', () => {
      const onProgress = vi.fn();
      const onComplete = vi.fn();
      const onError = vi.fn();

      const { result } = renderHook(() =>
        useProgressTracking({
          pollInterval: 5000,
          autoStart: false,
          useMock: true,
          onProgress,
          onComplete,
          onError,
        })
      );

      expect(result.current).toBeDefined();
    });
  });

  describe('startTracking', () => {
    it('should start tracking a task', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      // Service should be called
      expect(result.current.isTracking).toBeDefined();
    });

    it('should call onProgress callback', async () => {
