    it('should not auto-start when disabled', () => {
      const processingTask: GenerationTask = {
        ...mockTask,
        status: 'processing',
      };

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [processingTask],
          reorderTasks: vi.fn(),
        };
        return selector ? selector(state) : state;
      });

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.trackedTaskIds).toEqual([]);
    });
  });

  describe('store integration', () => {
    it('should update store when task status changes', async () => {
      const reorderTasks = vi.fn();
      
      (useAppStore as any).getState = vi.fn(() => ({
        taskQueue: [mockTask],
        reorderTasks,
      }));

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      // Store update should be available
      await waitFor(() => {
        expect(result.current).toBeDefined();
      });
    });
  });

  describe('callbacks', () => {
    it('should call onComplete when task completes', async () => {
      const onComplete = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onComplete })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onComplete).toBeDefined();
    });

    it('should call onError when task fails', async () => {
      const onError = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onError })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onError).toBeDefined();
    });

    it('should call onProgress on updates', async () => {
      const onProgress = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onProgress })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onProgress).toBeDefined();
    });
  });

  describe('cleanup', () => {
    it('should stop all tracking on unmount', () => {
      const { result, unmount } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
        result.current.startTracking('task-2');
      });

      unmount();

      // Cleanup should have been called
      expect(result.current).toBeDefined();
    });
  });

  describe('progressUpdates', () => {
    it('should maintain progress updates map', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.progressUpdates).toBeInstanceOf(Map);
      expect(result.current.progressUpdates.size).toBe(0);
    });
  });

  describe('trackedTaskIds', () => {
    it('should maintain tracked task IDs list', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.trackedTaskIds).toEqual([]);
    });
  });
});

/**
 * Tests for useProjectExport Hook
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useProjectExport } from '../useProjectExport';
import { useAppStore } from '@/stores/useAppStore';
import type { Project, Shot, Asset } from '@/types';

// Mock the store
vi.mock('@/stores/useAppStore');

describe('useProjectExport', () => {
  let mockProject: Project;
  let mockShots: Shot[];
  let mockAssets: Asset[];
  let mockSetProject: ReturnType<typeof vi.fn>;
  let mockSetShots: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    mockShots = [
      {
        id: 'shot-1',
        title: 'Opening Scene',
        description: 'A beautiful sunrise',
        duration: 5,
        position: 0,
        audioTracks: [],
        effects: [],
        textLayers: [],
        animations: [],
      },
      {
        id: 'shot-2',
        title: 'Middle Scene',
        description: 'Action sequence',
        duration: 10,
        position: 1,
        audioTracks: [],
        effects: [],
        textLayers: [],
        animations: [],
      },
    ];

    mockAssets = [
      {
        id: 'asset-1',
        name: 'Background Music',
        type: 'audio',
        url: '/assets/music.mp3',
      },
    ];

    mockProject = {
      schema_version: '1.0',
      project_name: 'Test Project',
      shots: mockShots,
      assets: mockAssets,
      capabilities: {
        grid_generation: true,
        promotion_engine: true,
        qa_engine: true,
        autofix_engine: true,
      },
      generation_status: {
        grid: 'pending',
        promotion: 'pending',
      },
    };

    mockSetProject = vi.fn();
    mockSetShots = vi.fn();

    (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
      project: mockProject,
      shots: mockShots,
      assets: mockAssets,
      setProject: mockSetProject,
      setShots: mockSetShots,
    });
  });

  describe('exportCurrentProject', () => {
    it('should export current project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).not.toBeNull();
      expect(exported?.schema_version).toBe('1.0');
      expect(exported?.project_name).toBe('Test Project');
    });

    it('should return null when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).toBeNull();
    });

    it('should return null when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [], // Empty shots array will fail validation
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).toBeNull();
    });

    it('should include all shots in export', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported?.shots).toHaveLength(2);
      expect(exported?.shots[0].id).toBe('shot-1');
      expect(exported?.shots[1].id).toBe('shot-2');
    });

    it('should include all assets in export', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported?.assets).toHaveLength(1);
      expect(exported?.assets[0].id).toBe('asset-1');
    });
  });

  describe('exportCurrentProjectToJSON', () => {
    it('should export project as JSON string', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(typeof json).toBe('string');
      expect(() => JSON.parse(json!)).not.toThrow();
    });

    it('should export pretty-printed JSON by default', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toContain('\n');
      expect(json).toContain('  ');
    });

    it('should export minified JSON when pretty is false', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON(false);
      
      expect(json).not.toContain('\n  ');
    });

    it('should return null when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toBeNull();
    });

    it('should return null when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toBeNull();
    });
  });

  describe('downloadCurrentProject', () => {
    beforeEach(() => {
      // Mock DOM methods
      global.URL.createObjectURL = vi.fn(() => 'blob:mock-url');
      global.URL.revokeObjectURL = vi.fn();
      global.alert = vi.fn();
      
      const mockLink = {
        href: '',
        download: '',
        click: vi.fn(),
      };
      vi.spyOn(document, 'createElement').mockReturnValue(mockLink as any);
      vi.spyOn(document.body, 'appendChild').mockImplementation(() => mockLink as any);
      vi.spyOn(document.body, 'removeChild').mockImplementation(() => mockLink as any);
    });

    it('should trigger download', () => {
      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(document.createElement).toHaveBeenCalledWith('a');
    });

    it('should not download when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(document.createElement).not.toHaveBeenCalled();
    });

    it('should show alert when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(global.alert).toHaveBeenCalled();
      expect(document.createElement).not.toHaveBeenCalled();
    });
  });

  describe('validateCurrentProject', () => {
    it('should validate valid project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(true);
      expect(validation.errors).toHaveLength(0);
    });

    it('should return invalid when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('No project loaded');
    });

    it('should return errors for invalid project', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(false);
      expect(validation.errors.length).toBeGreaterThan(0);
    });
  });

  describe('importProject', () => {
    it('should import valid project JSON', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      const success = result.current.importProject(validJSON);
      
      expect(success).toBe(true);
      expect(mockSetProject).toHaveBeenCalledWith(mockProject);
      expect(mockSetShots).toHaveBeenCalledWith(mockProject.shots);
    });

    it('should return false for invalid JSON', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const success = result.current.importProject('invalid json');
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
      expect(mockSetShots).not.toHaveBeenCalled();
    });

    it('should return false for wrong schema version', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const invalidProject = { ...mockProject, schema_version: '2.0' };
      const success = result.current.importProject(JSON.stringify(invalidProject));
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should update store with imported project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      result.current.importProject(validJSON);
      
      expect(mockSetProject).toHaveBeenCalledTimes(1);
      expect(mockSetShots).toHaveBeenCalledTimes(1);
    });
  });

  describe('importProjectFromFile', () => {
    it('should import project from file', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      const file = new File([validJSON], 'project.json', { type: 'application/json' });
      
      const success = await result.current.importProjectFromFile(file);
      
      expect(success).toBe(true);
      expect(mockSetProject).toHaveBeenCalled();
    });

    it('should return false for invalid file content', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const file = new File(['invalid json'], 'project.json', { type: 'application/json' });
      
      const success = await result.current.importProjectFromFile(file);
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should handle file read errors', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const mockFile = {
        text: vi.fn().mockRejectedValue(new Error('Read error')),
      } as unknown as File;
      
      const success = await result.current.importProjectFromFile(mockFile);
      
      expect(success).toBe(false);
    });
  });

  describe('hook stability', () => {
    it('should maintain stable function references', () => {
      const { result, rerender } = renderHook(() => useProjectExport());
      
      const firstRender = {
        exportCurrentProject: result.current.exportCurrentProject,
        exportCurrentProjectToJSON: result.current.exportCurrentProjectToJSON,
        downloadCurrentProject: result.current.downloadCurrentProject,
        validateCurrentProject: result.current.validateCurrentProject,
        importProject: result.current.importProject,
        importProjectFromFile: result.current.importProjectFromFile,
      };
      
      rerender();
      
      expect(result.current.exportCurrentProject).toBe(firstRender.exportCurrentProject);
      expect(result.current.exportCurrentProjectToJSON).toBe(firstRender.exportCurrentProjectToJSON);
      expect(result.current.downloadCurrentProject).toBe(firstRender.downloadCurrentProject);
      expect(result.current.validateCurrentProject).toBe(firstRender.validateCurrentProject);
      expect(result.current.importProject).toBe(firstRender.importProject);
      expect(result.current.importProjectFromFile).toBe(firstRender.importProjectFromFile);
    });
  });
});

/**
 * useResultDisplay Hook Tests
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, waitFor, act } from '@testing-library/react';
import { useResultDisplay } from '../useResultDisplay';
import { useAppStore } from '@/stores/useAppStore';
import type { GeneratedResult, GeneratedAsset } from '@/services/resultService';

// Mock the store
vi.mock('@/stores/useAppStore');

// Mock the service
vi.mock('@/services/resultService', () => ({
  createResultService: vi.fn(() => ({
    fetchResult: vi.fn(),
    fetchMultipleResults: vi.fn(),
    fetchProjectResults: vi.fn(),
    downloadAsset: vi.fn(),
    downloadAllAssets: vi.fn(),
    deleteResult: vi.fn(),
    getPreviewUrl: vi.fn((asset: GeneratedAsset) => asset.url),
  })),
  ResultService: vi.fn(),
  MockResultService: vi.fn(),
}));

describe('useResultDisplay', () => {
  const mockResult: GeneratedResult = {
    taskId: 'task-1',
    shotId: 'shot-1',
    type: 'grid',
    status: 'success',
    assets: [
      {
        id: 'asset-1',
        type: 'image',
        name: 'test.png',
        url: 'http://localhost:3000/assets/test.png',
      },
    ],
    generatedAt: new Date(),
  };

  beforeEach(() => {
    vi.clearAllMocks();

    // Mock store state
    (useAppStore as any).mockImplementation((selector: any) => {
      const state = {
        taskQueue: [],
        project: { project_name: 'test-project' },
      };
      return selector(state);
    });
  });

  describe('initialization', () => {
    it('should initialize with empty results', () => {
      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      expect(result.current.results.size).toBe(0);
      expect(result.current.isLoading).toBe(false);
      expect(result.current.error).toBeNull();
    });

    it('should create service with useMock option', () => {
      const { createResultService } = require('@/services/resultService');
      
      renderHook(() => useResultDisplay({ useMock: true, autoFetch: false }));

      expect(createResultService).toHaveBeenCalledWith(true);
    });
  });

  describe('fetchResult', () => {
    it('should fetch result for a task', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResult: GeneratedResult | null = null;
      await act(async () => {
        fetchedResult = await result.current.fetchResult('task-1');
      });

      expect(fetchedResult).toEqual(mockResult);
      expect(result.current.results.get('task-1')).toEqual(mockResult);
    });

    it('should set loading state during fetch', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      let resolvePromise: (value: GeneratedResult) => void;
      const promise = new Promise<GeneratedResult>((resolve) => {
        resolvePromise = resolve;
      });
      mockService.fetchResult.mockReturnValueOnce(promise);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      act(() => {
        result.current.fetchResult('task-1');
      });

      await waitFor(() => {
        expect(result.current.isLoading).toBe(true);
      });

      await act(async () => {
        resolvePromise!(mockResult);
        await promise;
      });

      expect(result.current.isLoading).toBe(false);
    });

    it('should handle fetch error', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockRejectedValueOnce(new Error('Network error'));

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(result.current.error).toBe('Network error');
    });

    it('should call onResultFetched callback', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const onResultFetched = vi.fn();
      const { result } = renderHook(() =>
        useResultDisplay({ autoFetch: false, onResultFetched })
      );

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(onResultFetched).toHaveBeenCalledWith(mockResult);
    });
  });

  describe('fetchMultipleResults', () => {
    it('should fetch multiple results', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      const results = [
        { ...mockResult, taskId: 'task-1' },
        { ...mockResult, taskId: 'task-2' },
      ];
      mockService.fetchMultipleResults.mockResolvedValueOnce(results);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResults: GeneratedResult[] = [];
      await act(async () => {
        fetchedResults = await result.current.fetchMultipleResults(['task-1', 'task-2']);
      });

      expect(fetchedResults).toHaveLength(2);
      expect(result.current.results.size).toBe(2);
    });
  });

  describe('fetchProjectResults', () => {
    it('should fetch all results for project', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      const results = [mockResult];
      mockService.fetchProjectResults.mockResolvedValueOnce(results);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResults: GeneratedResult[] = [];
      await act(async () => {
        fetchedResults = await result.current.fetchProjectResults();
      });

      expect(fetchedResults).toHaveLength(1);
      expect(mockService.fetchProjectResults).toHaveBeenCalledWith(
        'test-project',
        expect.any(Object)
      );
    });
  });

  describe('downloadAsset', () => {
    it('should download an asset', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
