/**
 * Audio Visualization Hooks for StoryCore
 * React hooks for audio analysis and visualization
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { AudioContextService, createAudioContextService } from '../services/audio/AudioContextService';
import {
  AudioVisualizerConfig,
  WaveformData,
  FrequencyData,
  AudioAnalyzerState,
  VisualizationType,
  VisualizationPreset,
} from '../services/audio-visualization/AudioVisualizerTypes';

// Default visualization presets
export const DEFAULT_PRESETS: VisualizationPreset[] = [
  {
    id: 'waveform-default',
    name: 'Waveform',
    type: 'waveform',
    config: { fftSize: 2048, smoothingTimeConstant: 0.8 },
    colors: ['#00d4ff', '#0099cc'],
    gpuAccelerated: false,
  },
  {
    id: 'spectrum-default',
    name: 'Spectrum',
    type: 'spectrum',
    config: { fftSize: 2048, smoothingTimeConstant: 0.85 },
    colors: ['#ff6b6b', '#feca57', '#48dbfb'],
    gpuAccelerated: true,
  },
  {
    id: 'circular-default',
    name: 'Circular',
    type: 'circular',
    config: { fftSize: 512, smoothingTimeConstant: 0.75 },
    colors: ['#a55eea', '#ff6b6b', '#feca57'],
    gpuAccelerated: true,
  },
  {
    id: 'bars-default',
    name: 'Frequency Bars',
    type: 'bar',
    config: { fftSize: 1024, smoothingTimeConstant: 0.8 },
    colors: ['#00d4ff', '#00ff88', '#ff6b6b'],
    gpuAccelerated: true,
  },
];

/**
 * Hook to manage audio context and analyzer
 */
export function useAudioContext(config?: Partial<AudioVisualizerConfig>) {
  const [isInitialized, setIsInitialized] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const audioServiceRef = useRef<AudioContextService | null>(null);

  const initialize = useCallback(async () => {
    try {
      audioServiceRef.current = createAudioContextService(config);
      await audioServiceRef.current.initialize();
      setIsInitialized(true);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to initialize audio context');
      setIsInitialized(false);
    }
  }, [config]);

  useEffect(() => {
    initialize();

    return () => {
      if (audioServiceRef.current) {
        audioServiceRef.current.dispose();
        audioServiceRef.current = null;
      }
    };
  }, [initialize]);

  const loadAudio = useCallback(async (url: string) => {
    if (!audioServiceRef.current) {
      throw new Error('Audio context not initialized');
    }
    await audioServiceRef.current.loadAudio(url);
  }, []);

  const attachAudioElement = useCallback((audioElement: HTMLAudioElement) => {
    if (!audioServiceRef.current) {
      throw new Error('Audio context not initialized');
    }
    audioServiceRef.current.attachAudioElement(audioElement);
  }, []);

  const play = useCallback(() => {
    audioServiceRef.current?.play();
  }, []);

  const pause = useCallback(() => {
    audioServiceRef.current?.pause();
  }, []);

  const stop = useCallback(() => {
    audioServiceRef.current?.stop();
  }, []);

  const seek = useCallback((time: number) => {
    audioServiceRef.current?.seek(time);
  }, []);

  const setVolume = useCallback((volume: number) => {
    audioServiceRef.current?.setVolume(volume);
  }, []);

  const getState = useCallback(() => {
    return audioServiceRef.current?.getState() ?? null;
  }, []);

  return {
    isInitialized,
    error,
    audioService: audioServiceRef.current,
    loadAudio,
    attachAudioElement,
    play,
    pause,
    stop,
    seek,
    setVolume,
    getState,
  };
}

/**
 * Hook for spectrum analysis with real-time frequency data
 */
export function useSpectrumAnalysis(
  audioService: AudioContextService | null,
  options: {
    enabled?: boolean;
    updateInterval?: number;
  } = {}
) {
  const { enabled = true, updateInterval = 16 } = options;

  const [frequencyData, setFrequencyData] = useState<FrequencyData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const animationFrameRef = useRef<number | null>(null);
  const lastUpdateRef = useRef<number>(0);

  const startAnalysis = useCallback(() => {
    if (!audioService || !enabled) return;

    setIsAnalyzing(true);

    const analyze = (timestamp: number) => {
      if (!enabled || !audioService) return;

      if (timestamp - lastUpdateRef.current >= updateInterval) {
        const data = audioService.getFrequencyData();
        setFrequencyData(data);
        lastUpdateRef.current = timestamp;
      }

      animationFrameRef.current = requestAnimationFrame(analyze);
    };

    animationFrameRef.current = requestAnimationFrame(analyze);
  }, [audioService, enabled, updateInterval]);

  const stopAnalysis = useCallback(() => {
    if (animationFrameRef.current !== null) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    setIsAnalyzing(false);
  }, []);

  useEffect(() => {
    if (enabled) {
      startAnalysis();
    } else {
      stopAnalysis();
    }

    return () => {
      stopAnalysis();
    };
  }, [enabled, startAnalysis, stopAnalysis]);

  return {
    frequencyData,
    isAnalyzing,
    startAnalysis,
    stopAnalysis,
  };
}

/**
 * Hook for waveform data analysis
 */
export function useWaveformData(
  audioService: AudioContextService | null,
  options: {
    enabled?: boolean;
    updateInterval?: number;
  } = {}
) {
  const { enabled = true, updateInterval = 16 } = options;

  const [waveformData, setWaveformData] = useState<WaveformData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const animationFrameRef = useRef<number | null>(null);
  const lastUpdateRef = useRef<number>(0);

  const startAnalysis = useCallback(() => {
    if (!audioService || !enabled) return;

    setIsAnalyzing(true);

    const analyze = (timestamp: number) => {
      if (!enabled || !audioService) return;

      if (timestamp - lastUpdateRef.current >= updateInterval) {
        const data = audioService.getWaveformData();
        setWaveformData(data);
        lastUpdateRef.current = timestamp;
      }

      animationFrameRef.current = requestAnimationFrame(analyze);
    };

    animationFrameRef.current = requestAnimationFrame(analyze);
  }, [audioService, enabled, updateInterval]);

  const stopAnalysis = useCallback(() => {
    if (animationFrameRef.current !== null) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    setIsAnalyzing(false);
  }, []);

  useEffect(() => {
    if (enabled) {
      startAnalysis();
    } else {
      stopAnalysis();
    }

    return () => {
      stopAnalysis();
    };
  }, [enabled, startAnalysis, stopAnalysis]);

  return {
    waveformData,
    isAnalyzing,
    startAnalysis,
    stopAnalysis,
  };
}

/**
 * Hook for combined audio visualization
 */
export function useAudioVisualization(
  audioService: AudioContextService | null,
  options: {
    enabled?: boolean;
    updateInterval?: number;
    visualizationType?: VisualizationType;
  } = {}
) {
  const { enabled = true, updateInterval = 16, visualizationType = 'spectrum' } = options;

  const [frequencyData, setFrequencyData] = useState<FrequencyData | null>(null);
  const [waveformData, setWaveformData] = useState<WaveformData | null>(null);
  const [state, setState] = useState<AudioAnalyzerState | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const animationFrameRef = useRef<number | null>(null);
  const lastUpdateRef = useRef<number>(0);

  const startVisualization = useCallback(() => {
    if (!audioService || !enabled) return;

    setIsAnalyzing(true);

    const update = (timestamp: number) => {
      if (!enabled || !audioService) return;

      if (timestamp - lastUpdateRef.current >= updateInterval) {
        const freqData = audioService.getFrequencyData();
        const waveData = audioService.getWaveformData();
        const audioState = audioService.getState();

        setFrequencyData(freqData);
        setWaveformData(waveData);
        setState(audioState);

        lastUpdateRef.current = timestamp;
      }

      animationFrameRef.current = requestAnimationFrame(update);
    };

    animationFrameRef.current = requestAnimationFrame(update);
  }, [audioService, enabled, updateInterval]);

  const stopVisualization = useCallback(() => {
    if (animationFrameRef.current !== null) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    setIsAnalyzing(false);
  }, []);

  useEffect(() => {
    if (enabled) {
      startVisualization();
    } else {
      stopVisualization();
    }

    return () => {
      stopVisualization();
    };
  }, [enabled, startVisualization, stopVisualization]);

  // Sync with audio service state changes
  useEffect(() => {
    if (audioService) {
      audioService.setStateChangeCallback((newState) => {
        setState(newState);
      });
    }
  }, [audioService]);

  return {
    frequencyData,
    waveformData,
    state,
    isAnalyzing,
    visualizationType,
    startVisualization,
    stopVisualization,
  };
}

/**
 * Hook for beat detection
 */
export function useBeatDetection(
  audioService: AudioContextService | null,
  options: {
    enabled?: boolean;
    threshold?: number;
    minInterval?: number;
  } = {}
) {
  const { enabled = true, threshold = 0.7, minInterval = 200 } = options;

  const [isBeat, setIsBeat] = useState(false);
  const [beatIntensity, setBeatIntensity] = useState(0);
  const lastBeatTimeRef = useRef<number>(0);
  const animationFrameRef = useRef<number | null>(null);

  const detectBeat = useCallback(() => {
    if (!audioService || !enabled) return;

    const frequencyData = audioService.getFrequencyData();
    const now = performance.now();

    // Calculate bass energy (low frequencies)
    const bassEndIndex = Math.floor((250 / (audioService.getAudioContext()?.sampleRate || 44100)) * (frequencyData.frequencyData.length * 2));
    let bassEnergy = 0;
    for (let i = 0; i < bassEndIndex; i++) {
      bassEnergy += frequencyData.frequencyData[i];
    }
    bassEnergy /= bassEndIndex * 255;

    // Check for beat
    if (bassEnergy > threshold && now - lastBeatTimeRef.current > minInterval) {
      setIsBeat(true);
      setBeatIntensity(bassEnergy);
      lastBeatTimeRef.current = now;

      // Reset beat flag after short delay
      setTimeout(() => setIsBeat(false), 50);
    }
  }, [audioService, enabled, threshold, minInterval]);

  useEffect(() => {
    if (!enabled) return;

    const loop = () => {
      detectBeat();
      animationFrameRef.current = requestAnimationFrame(loop);
    };

    animationFrameRef.current = requestAnimationFrame(loop);

    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [enabled, detectBeat]);

  return { isBeat, beatIntensity };
}

/**
 * Hook for managing visualization presets
 */
export function useVisualizationPresets() {
  const [presets, setPresets] = useState<VisualizationPreset[]>(DEFAULT_PRESETS);
  const [activePreset, setActivePreset] = useState<VisualizationPreset | null>(null);

  const addPreset = useCallback((preset: VisualizationPreset) => {
    setPresets((prev) => [...prev, preset]);
  }, []);

  const removePreset = useCallback((presetId: string) => {
    setPresets((prev) => prev.filter((p) => p.id !== presetId));
  }, []);

  const updatePreset = useCallback((presetId: string, updates: Partial<VisualizationPreset>) => {
    setPresets((prev) =>
      prev.map((p) => (p.id === presetId ? { ...p, ...updates } : p))
    );
  }, []);

  const selectPreset = useCallback((presetId: string) => {
    const preset = presets.find((p) => p.id === presetId);
    if (preset) {
      setActivePreset(preset);
    }
  }, [presets]);

  return {
    presets,
    activePreset,
    addPreset,
    removePreset,
    updatePreset,
    selectPreset,
  };
}

import { useState, useEffect, useCallback } from 'react';

// ============================================================================
// useAutoSave Hook
// Sauvegarde automatique des données dans localStorage
// ============================================================================

interface DraftData<T> {
  data: T;
  timestamp: number;
  stepIndex: number;
}

interface UseAutoSaveOptions {
  storageKey: string;
  interval?: number;
  maxDrafts?: number;
}

/**
 * Hook pour la sauvegarde automatique des brouillons de wizard
 */
export function useAutoSave<T>(
  options: UseAutoSaveOptions
) {
  const { storageKey, interval = 30000, maxDrafts = 5 } = options;

  const [draft, setDraft] = useState<T | null>(null);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const getStorageKey = useCallback((stepIndex?: number) => {
    return stepIndex !== undefined 
      ? `${storageKey}_step_${stepIndex}`
      : storageKey;
  }, [storageKey]);

  const saveToStorage = useCallback((data: T, stepIndex: number) => {
    try {
      const storageKeyWithStep = getStorageKey(stepIndex);
      
      const draftData: DraftData<T> = {
        data,
        timestamp: Date.now(),
        stepIndex,
      };
      
      localStorage.setItem(storageKeyWithStep, JSON.stringify(draftData));
      
      // Gestion des anciens brouillons
      const allDrafts: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key?.startsWith(`${storageKey}_step_`)) {
          allDrafts.push(key);
        }
      }
      
      if (allDrafts.length > maxDrafts) {
        const sortedDrafts = allDrafts.sort((a, b) => {
          const timeA = parseInt(a.split('_').pop() || '0');
          const timeB = parseInt(b.split('_').pop() || '0');
          return timeA - timeB;
        });
        
        const toRemove = sortedDrafts.slice(0, allDrafts.length - maxDrafts);
        toRemove.forEach(key => localStorage.removeItem(key));
      }
      
      setLastSaved(new Date());
      setError(null);
    } catch (err) {
      console.error('Erreur lors de la sauvegarde:', err);
      setError('Impossible de sauvegarder le brouillon');
    }
  }, [storageKey, maxDrafts, getStorageKey]);

  const saveNow = useCallback((data: T, stepIndex: number) => {
    setIsSaving(true);
    try {
      saveToStorage(data, stepIndex);
    } finally {
      setIsSaving(false);
    }
  }, [saveToStorage]);

  const restore = useCallback((stepIndex?: number): T | null => {
    try {
      const storageKeyWithStep = getStorageKey(stepIndex);
      const saved = localStorage.getItem(storageKeyWithStep);
      
      if (saved) {
        const parsed: DraftData<T> = JSON.parse(saved);
        setDraft(parsed.data);
        return parsed.data;
      }
      
      if (stepIndex === undefined) {
        const keys = Object.keys(localStorage).filter(k => 
          k.startsWith(`${storageKey}_step_`)
        );
        
        if (keys.length > 0) {
          const mostRecentKey = keys.sort((a, b) => {
            const timeA = parseInt(a.split('_').pop() || '0');
            const timeB = parseInt(b.split('_').pop() || '0');
            return timeB - timeA;
          })[0];
          
          const savedData = localStorage.getItem(mostRecentKey);
          if (savedData) {
            const parsed: DraftData<T> = JSON.parse(savedData);
            setDraft(parsed.data);
            return parsed.data;
          }
        }
      }
      
      return null;
    } catch (err) {
      console.error('Erreur lors de la restauration:', err);
      setError('Impossible de restaurer le brouillon');
      return null;
    }
  }, [storageKey, getStorageKey]);

  const clear = useCallback(() => {
    try {
      const keys = Object.keys(localStorage).filter(k => 
        k.startsWith(`${storageKey}_step_`)
      );
      
      keys.forEach(key => localStorage.removeItem(key));
      setDraft(null);
      setLastSaved(null);
      setError(null);
    } catch (err) {
      console.error('Erreur lors de la suppression:', err);
    }
  }, [storageKey]);

  return {
    draft,
    lastSaved,
    isSaving,
    error,
    saveNow,
    restore,
    clear,
    hasDraft: draft !== null,
  };
}

export default useAutoSave;

/**
 * useBackendIntegration Hook
 * 
 * React hook for backend API integration with task submission and status tracking
 */

import { useState, useCallback, useEffect, useRef } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { backendApi, type BackendApiService } from '@/services/backendApiService';
import { exportProject } from '@/services/projectExportService';
import type { GenerationTask } from '@/types';

export interface UseBackendIntegrationReturn {
  /**
   * Submit current project for generation
   */
  submitProject: () => Promise<boolean>;
  
  /**
   * Submit a specific task
   */
  submitTask: (task: GenerationTask) => Promise<boolean>;
  
  /**
   * Submit all tasks in queue
   */
  submitAllTasks: () => Promise<void>;
  
  /**
   * Get status of a task
   */
  getTaskStatus: (taskId: string) => Promise<void>;
  
  /**
   * Cancel a running task
   */
  cancelTask: (taskId: string) => Promise<boolean>;
  
  /**
   * Invoke StoryCore-Engine CLI command
   */
  invokeCliCommand: (command: string, args: Record<string, unknown>) => Promise<any>;
  
  /**
   * Current submission state
   */
  isSubmitting: boolean;
  
  /**
   * Last error message
   */
  error: string | null;
  
  /**
   * Clear error
   */
  clearError: () => void;
}

export interface UseBackendIntegrationOptions {
  /**
   * Custom backend API service
   */
  apiService?: BackendApiService;
  
  /**
   * Auto-refresh interval for task status (ms)
   */
  refreshInterval?: number;
  
  /**
   * Enable auto-refresh
   */
  autoRefresh?: boolean;
}

export function useBackendIntegration(
  options: UseBackendIntegrationOptions = {}
): UseBackendIntegrationReturn {
  const {
    apiService = backendApi,
    refreshInterval = 5000,
    autoRefresh = false,
  } = options;

  const { project, shots, assets, taskQueue, reorderTasks } = useAppStore();
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  const refreshTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  /**
   * Submit current project for generation
   */
  const submitProject = useCallback(async (): Promise<boolean> => {
    if (!project) {
      setError('No project to submit');
      return false;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      // Export project to Data Contract v1 format
      const exportedProject = exportProject(project.project_name, shots, assets);
      
      // Submit to backend
      const response = await apiService.submitProject(exportedProject);
      
      if (!response.success) {
        setError(response.error || 'Failed to submit project');
        return false;
      }

      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      return false;
    } finally {
      setIsSubmitting(false);
    }
  }, [project, shots, assets, apiService]);

  /**
   * Submit a specific task
   */
  const submitTask = useCallback(async (task: GenerationTask): Promise<boolean> => {
    if (!project) {
      setError('No project context for task');
      return false;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      // Export project for context
      const exportedProject = exportProject(project.project_name, shots, assets);
      
      // Submit task to backend
      const response = await apiService.submitTask(task, exportedProject);
      
      if (!response.success) {
        setError(response.error || 'Failed to submit task');
        return false;
      }

      // Update task status in queue
      const updatedQueue = taskQueue.map((t) =>
        t.id === task.id
          ? { ...t, status: 'processing' as const, startedAt: new Date() }
          : t
      );
      reorderTasks(updatedQueue);

      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      return false;
    } finally {
      setIsSubmitting(false);
    }
  }, [project, shots, assets, taskQueue, apiService, reorderTasks]);

  /**
   * Submit all tasks in queue
   */
  const submitAllTasks = useCallback(async (): Promise<void> => {
    if (!project) {
      setError('No project context for tasks');
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      // Get pending tasks
      const pendingTasks = taskQueue.filter((t) => t.status === 'pending');
      
      if (pendingTasks.length === 0) {
        setError('No pending tasks to submit');
        return;
      }

      // Submit tasks sequentially
      for (const task of pendingTasks) {
        const success = await submitTask(task);
        if (!success) {
          // Stop on first failure
          break;
        }
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  }, [project, taskQueue, submitTask]);

  /**
   * Get status of a task
   */
  const getTaskStatus = useCallback(async (taskId: string): Promise<void> => {
    try {
      const response = await apiService.getTaskStatus(taskId);
      
      if (!response.success) {
        console.error('Failed to get task status:', response.error);
        return;
      }

      // Update task in queue
      const updatedQueue = taskQueue.map((t) => {
        if (t.id === taskId && response.data) {
          return {
            ...t,
            status: response.data.status,
            error: response.data.error,
            completedAt: response.data.status === 'completed' ? new Date() : t.completedAt,
          };
        }
        return t;
      });
      reorderTasks(updatedQueue);
    } catch (err) {
      console.error('Error getting task status:', err);
    }
  }, [taskQueue, apiService, reorderTasks]);

  /**
   * Cancel a running task
   */
  const cancelTask = useCallback(async (taskId: string): Promise<boolean> => {
    setError(null);

    try {
      const response = await apiService.cancelTask(taskId);
      
      if (!response.success) {
        setError(response.error || 'Failed to cancel task');
        return false;
      }

      // Update task status in queue
      const updatedQueue = taskQueue.map((t) =>
        t.id === taskId
          ? { ...t, status: 'failed' as const, error: 'Cancelled by user' }
          : t
      );
      reorderTasks(updatedQueue);

      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      return false;
    }
  }, [taskQueue, apiService, reorderTasks]);

  /**
   * Invoke StoryCore-Engine CLI command
   */
  const invokeCliCommand = useCallback(
    async (command: string, args: Record<string, unknown>): Promise<any> => {
      setIsSubmitting(true);
      setError(null);

      try {
        const response = await apiService.invokeCliCommand(command, args);
        
        if (!response.success) {
          setError(response.error || 'Failed to execute command');
          return null;
        }

        return response.data;
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(errorMessage);
        return null;
      } finally {
        setIsSubmitting(false);
      }
    },
    [apiService]
  );

  /**
   * Clear error
   */
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  /**
   * Auto-refresh task statuses
   */
  useEffect(() => {
    if (!autoRefresh) {
      return;
    }

    const refreshStatuses = async () => {
      const processingTasks = taskQueue.filter((t) => t.status === 'processing');
      
      for (const task of processingTasks) {
        await getTaskStatus(task.id);
      }
    };

    // Initial refresh
    refreshStatuses();

    // Set up interval
    refreshTimerRef.current = setInterval(refreshStatuses, refreshInterval);

    return () => {
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
      }
    };
  }, [autoRefresh, refreshInterval, taskQueue, getTaskStatus]);

  return {
    submitProject,
    submitTask,
    submitAllTasks,
    getTaskStatus,
    cancelTask,
    invokeCliCommand,
    isSubmitting,
    error,
    clearError,
  };
}

