  VideoInfo,
  ThumbnailOptions,
  AudioExtractionOptions,
  ConcatenationOptions,
  TrimOptions,
  WatermarkOptions,
  SpeedChangeOptions,
  GPUCapabilities,
  AsyncResult,
  Preset,
  PresetCategory,
  FormatOptions,
  CodecOptions,
} from '../services/ffmpeg/FFmpegTypes';

// =============================================================================
// API Service
// =============================================================================

interface FFmpegAPI {
  /** Transcode a video file */
  transcode(
    inputPath: string,
    outputPath: string,
    options: Partial<ExportSettings>,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Convert video format */
  convertFormat(
    inputPath: string,
    outputPath: string,
    targetFormat: VideoFormat,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Generate thumbnails */
  generateThumbnails(
    inputPath: string,
    options: ThumbnailOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Extract audio */
  extractAudio(
    options: AudioExtractionOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Concatenate videos */
  concatenateVideos(
    options: ConcatenationOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Trim video */
  trimVideo(
    options: TrimOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Add watermark */
  addWatermark(
    options: WatermarkOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Change video speed */
  changeSpeed(
    options: SpeedChangeOptions,
    onProgress: (progress: ProgressCallback) => void
  ): Promise<ExportResponse>;
  
  /** Get video information */
  getVideoInfo(inputPath: string): Promise<VideoInfo>;
  
  /** Get GPU capabilities */
  getGPUCapabilities(): Promise<GPUCapabilities>;
  
  /** Check FFmpeg availability */
  checkAvailability(): Promise<boolean>;
  
  /** Cancel current operation */
  cancelOperation(): Promise<void>;
}

