export interface UseFFmpegReturn {
  // State
  state: FFmpegState;
  
  // Actions
  transcode: (
    inputPath: string,
    outputPath: string,
    options?: Partial<ExportSettings>
  ) => Promise<AsyncResult<string>>;
  
  convertFormat: (
    inputPath: string,
    outputPath: string,
    targetFormat: VideoFormat
  ) => Promise<AsyncResult<string>>;
  
  generateThumbnails: (
    inputPath: string,
    options: Omit<ThumbnailOptions, 'outputPath'>,
    outputPath: string
  ) => Promise<AsyncResult<string>>;
  
  extractAudio: (
    options: Omit<AudioExtractionOptions, 'inputPath'>,
    inputPath: string
  ) => Promise<AsyncResult<string>>;
  
  concatenateVideos: (
    inputFiles: string[],
    outputPath: string,
    format?: VideoFormat
  ) => Promise<AsyncResult<string>>;
  
  trim: (
    inputPath: string,
    outputPath: string,
    startTime: number,
    endTime?: number
  ) => Promise<AsyncResult<string>>;
  
  addWatermark: (
    inputPath: string,
    watermarkPath: string,
    outputPath: string,
    options?: Partial<WatermarkOptions>
  ) => Promise<AsyncResult<string>>;
  
  changeSpeed: (
    inputPath: string,
    outputPath: string,
    speedFactor: number,
    adjustAudio?: boolean
  ) => Promise<AsyncResult<string>>;
  
  getVideoInfo: (inputPath: string) => Promise<AsyncResult<VideoInfo>>;
  
  cancel: () => Promise<void>;
  
  // Utilities
  presets: typeof EXPORT_PRESETS;
  formatOptions: typeof FORMAT_OPTIONS;
}

export function useFFmpeg(): UseFFmpegReturn {
  const [state, setState] = useState<FFmpegState>({
    status: 'idle',
    progress: 0,
    message: null,
    timeElapsed: 0,
    timeRemaining: null,
    fps: 0,
    bitrate: null,
    error: null,
    outputPath: null,
  });

  const abortControllerRef = useRef<AbortController | null>(null);
  const startTimeRef = useRef<number>(0);
  const progressIntervalRef = useRef<NodeJS.Timeout | null>(null);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
     
    // Intentionally run only on mount - cleanup should happen once on unmount
  }, []);

  const updateState = useCallback((updates: Partial<FFmpegState>) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const createProgressCallback = useCallback(
    (operationName: string): ((progress: ProgressCallback) => void) => {
      return (progress: ProgressCallback) => {
        const timeElapsed = (Date.now() - startTimeRef.current) / 1000;
        
        let timeRemaining: number | null = null;
        if (progress.progress > 0 && progress.progress < 100) {
          const estimatedTotal = timeElapsed / (progress.progress / 100);
          timeRemaining = estimatedTotal - timeElapsed;
        }

        setState(prev => ({
          ...prev,
          status: progress.status === 'completed' ? 'completed' : 'processing',
          progress: progress.progress,
          message: progress.message || `${operationName}: ${progress.status}`,
          timeElapsed,
          timeRemaining,
          fps: progress.fps,
          bitrate: progress.bitrate,
          error: progress.status === 'error' ? progress.message : null,
        }));
      };
    },
    []
  );

  const executeOperation = useCallback(
    async <T>(
      operation: (onProgress: (progress: ProgressCallback) => void) => Promise<T>,
      operationName: string
    ): Promise<AsyncResult<T>> => {
      // Cancel any existing operation
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      abortControllerRef.current = new AbortController();
      startTimeRef.current = Date.now();

      updateState({
        status: 'preparing',
        progress: 0,
        message: `Preparing ${operationName}...`,
        error: null,
        outputPath: null,
      });

      try {
        updateState({ status: 'processing', message: `Starting ${operationName}...` });

        const result = await operation(createProgressCallback(operationName));

        updateState({
          status: 'completed',
          progress: 100,
          message: `${operationName} completed successfully`,
        });

        return { success: true, data: result };
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        
        updateState({
          status: 'error',
          error: errorMessage,
          message: `${operationName} failed: ${errorMessage}`,
        });

        return { success: false, error: errorMessage };
      }
    },
    [createProgressCallback, updateState]
  );

  // ==========================================================================
  // Main Operations
  // ==========================================================================

  const transcode = useCallback(
    async (
      inputPath: string,
      outputPath: string,
      options?: Partial<ExportSettings>
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/transcode', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              outputPath,
              options: { ...DEFAULT_EXPORT_SETTINGS, ...options },
            }),
          });

          if (!response.ok) {
            throw new Error(`Transcode failed: ${response.statusText}`);
          }

          // Handle SSE progress
          const reader = response.body?.getReader();
          if (!reader) throw new Error('No response body');

          const decoder = new TextDecoder();
          let done = false;

          while (!done) {
            const { value, done: doneReading } = await reader.read();
            done = doneReading;
            if (value) {
              const chunk = decoder.decode(value);
              try {
                const progress = JSON.parse(chunk);
                onProgress(progress);
                if (progress.status === 'completed') {
                  break;
                }
              } catch {
                // Skip non-JSON chunks
              }
            }
          }

          return outputPath;
        },
        'Transcoding'
      );
    },
    [executeOperation]
  );

  const convertFormat = useCallback(
    async (
      inputPath: string,
      outputPath: string,
      targetFormat: VideoFormat
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/convert', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              outputPath,
              targetFormat,
            }),
          });

          if (!response.ok) {
            throw new Error(`Format conversion failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Converting format'
      );
    },
    [executeOperation]
  );

  const generateThumbnails = useCallback(
    async (
      inputPath: string,
      options: Omit<ThumbnailOptions, 'outputPath'>,
      outputPath: string
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/thumbnails', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              options: { ...options, outputPath },
            }),
          });

          if (!response.ok) {
            throw new Error(`Thumbnail generation failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Generating thumbnails'
      );
    },
    [executeOperation]
  );

  const extractAudio = useCallback(
    async (
      options: Omit<AudioExtractionOptions, 'inputPath'>,
      inputPath: string
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/extract-audio', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              options: { ...options, inputPath },
            }),
          });

          if (!response.ok) {
            throw new Error(`Audio extraction failed: ${response.statusText}`);
          }

          return options.outputPath;
        },
        'Extracting audio'
      );
    },
    [executeOperation]
  );

  const concatenateVideos = useCallback(
    async (
      inputFiles: string[],
      outputPath: string,
      format: VideoFormat = 'mp4'
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/concatenate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputFiles,
              outputPath,
              format,
            }),
          });

          if (!response.ok) {
            throw new Error(`Concatenation failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Concatenating videos'
      );
    },
    [executeOperation]
  );

  const trim = useCallback(
    async (
      inputPath: string,
      outputPath: string,
      startTime: number,
      endTime?: number
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/trim', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              outputPath,
              startTime,
              endTime,
            }),
          });

          if (!response.ok) {
            throw new Error(`Trim failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Trimming video'
      );
    },
    [executeOperation]
  );

  const addWatermark = useCallback(
    async (
      inputPath: string,
      watermarkPath: string,
      outputPath: string,
      options?: Partial<WatermarkOptions>
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/watermark', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              watermarkPath,
              outputPath,
              options: {
                position: 'bottomright',
                opacity: 0.5,
                scale: 0.15,
                ...options,
              },
            }),
          });

          if (!response.ok) {
            throw new Error(`Watermark failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Adding watermark'
      );
    },
    [executeOperation]
  );

  const changeSpeed = useCallback(
    async (
      inputPath: string,
      outputPath: string,
      speedFactor: number,
      adjustAudio: boolean = true
    ): Promise<AsyncResult<string>> => {
      return executeOperation(
        async (onProgress) => {
          const response = await fetch('/api/ffmpeg/speed', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              inputPath,
              outputPath,
              speedFactor,
              adjustAudio,
            }),
          });

          if (!response.ok) {
            throw new Error(`Speed change failed: ${response.statusText}`);
          }

          return outputPath;
        },
        'Changing video speed'
      );
    },
    [executeOperation]
  );

  const getVideoInfo = useCallback(
    async (inputPath: string): Promise<AsyncResult<VideoInfo>> => {
      try {
        const response = await fetch(`/api/ffmpeg/info?path=${encodeURIComponent(inputPath)}`);
        
        if (!response.ok) {
          throw new Error(`Failed to get video info: ${response.statusText}`);
        }

        const info = await response.json();
        return { success: true, data: info };
      } catch (error) {
        return {
          success: false,
          error: error instanceof Error ? error.message : String(error),
        };
      }
    },
    []
  );

  const cancel = useCallback(async () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    try {
      await fetch('/api/ffmpeg/cancel', { method: 'POST' });
    } catch {
      // Ignore cancel API errors
    }

    updateState({
      status: 'cancelled',
      message: 'Operation cancelled',
      progress: 0,
    });
  }, [updateState]);

  return {
    state,
    transcode,
    convertFormat,
    generateThumbnails,
    extractAudio,
    concatenateVideos,
    trim,
    addWatermark,
    changeSpeed,
    getVideoInfo,
    cancel,
    presets: EXPORT_PRESETS,
    formatOptions: FORMAT_OPTIONS,
  };
}

