/**
 * File Polling Hook
 * Manages polling interval for file detection with cleanup and manual refresh
 */

import { useEffect, useRef, useCallback, useState } from 'react';

interface UseFilePollingOptions {
  /**
   * Callback function to execute on each poll
   */
  onPoll: () => void | Promise<void>;
  
  /**
   * Polling interval in milliseconds (default: 2000ms)
   */
  interval?: number;
  
  /**
   * Whether polling is enabled
   */
  enabled?: boolean;
  
  /**
   * Condition to stop polling (e.g., file detected)
   */
  stopCondition?: boolean;
}

interface UseFilePollingReturn {
  /**
   * Whether polling is currently active
   */
  isPolling: boolean;
  
  /**
   * Manually trigger a poll immediately
   */
  refresh: () => void;
  
  /**
   * Start polling
   */
  start: () => void;
  
  /**
   * Stop polling
   */
  stop: () => void;
}

/**
 * Custom hook for managing file polling with interval control
 * 
 * Features:
 * - 2-second polling interval (configurable)
 * - Automatic cleanup on unmount
 * - Manual refresh trigger
 * - Stops polling when file detected or wizard closed
 * 
 * @param options - Polling configuration options
 * @returns Polling control interface
 */
export const useFilePolling = ({
  onPoll,
  interval = 2000,
  enabled = true,
  stopCondition = false
}: UseFilePollingOptions): UseFilePollingReturn => {
  const [isPolling, setIsPolling] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const isPollingRef = useRef(false);

  /**
   * Stop polling and clear interval
   */
  const stop = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setIsPolling(false);
    isPollingRef.current = false;
  }, []);

  /**
   * Start polling
   */
  const start = useCallback(() => {
    // Don't start if already polling or if stop condition is met
    if (isPollingRef.current || stopCondition) {
      return;
    }

    // Clear any existing interval
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }

    // Set polling state
    setIsPolling(true);
    isPollingRef.current = true;

    // Start interval
    intervalRef.current = setInterval(() => {
      onPoll();
    }, interval);
  }, [onPoll, interval, stopCondition]);

  /**
   * Manually trigger a poll immediately
   */
  const refresh = useCallback(() => {
    onPoll();
  }, [onPoll]);

  /**
   * Effect to manage polling lifecycle
   */
  useEffect(() => {
    // Stop polling if disabled or stop condition is met
    if (!enabled || stopCondition) {
      stop();
      return;
    }

    // Start polling if enabled and not already polling
    if (enabled && !isPollingRef.current) {
      // Initial poll
      onPoll();
      
      // Start interval polling
      start();
    }

    // Cleanup on unmount or when dependencies change
    return () => {
      stop();
    };
  }, [enabled, stopCondition, onPoll, start, stop]);

  return {
    isPolling,
    refresh,
    start,
    stop
  };
};

/**
 * useFocusManagement Hook
 * 
 * Provides focus management utilities for modals and complex UI components.
 * Handles focus trapping, restoration, and initial focus setting.
 * 
 * Requirements: All UI requirements - focus management in modals
 */

import { useEffect, useRef, useCallback } from 'react';

// ============================================================================
// Types
// ============================================================================

export interface UseFocusManagementOptions {
  /** Whether focus management is active */
  enabled?: boolean;
  /** Element to focus when enabled */
  initialFocusRef?: React.RefObject<HTMLElement>;
  /** Element to restore focus to when disabled */
  restoreFocusRef?: React.RefObject<HTMLElement>;
  /** Whether to trap focus within container */
  trapFocus?: boolean;
}

// ============================================================================
// Hook
// ============================================================================

/**
 * useFocusManagement Hook
 * 
 * Manages focus for modals and complex UI components.
 * Provides focus trapping and restoration capabilities.
 */
export const useFocusManagement = (
  containerRef: React.RefObject<HTMLElement>,
  options: UseFocusManagementOptions = {}
): void => {
  const {
    enabled = true,
    initialFocusRef,
    restoreFocusRef,
    trapFocus = true,
  } = options;

  const previousActiveElement = useRef<HTMLElement | null>(null);

  /**
   * Get all focusable elements within container
   */
  const getFocusableElements = useCallback((): HTMLElement[] => {
    if (!containerRef.current) return [];

    const focusableSelectors = [
      'a[href]',
      'button:not([disabled])',
      'textarea:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      '[tabindex]:not([tabindex="-1"])',
    ].join(', ');

    const elements = Array.from(
      containerRef.current.querySelectorAll<HTMLElement>(focusableSelectors)
    );

    return elements.filter((el) => {
      // Filter out hidden elements
      return el.offsetParent !== null;
    });
  }, [containerRef]);

  /**
   * Handle Tab key for focus trapping
   */
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!enabled || !trapFocus || event.key !== 'Tab') return;

      const focusableElements = getFocusableElements();
      if (focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey) {
        // Shift + Tab: moving backwards
        if (document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        }
      } else {
        // Tab: moving forwards
        if (document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }
    },
    [enabled, trapFocus, getFocusableElements]
  );

  /**
   * Set initial focus when enabled
   */
  useEffect(() => {
    if (!enabled) return;

    // Store current active element for restoration
    previousActiveElement.current = document.activeElement as HTMLElement;

    // Set initial focus
    if (initialFocusRef?.current) {
      initialFocusRef.current.focus();
    } else {
      // Focus first focusable element
      const focusableElements = getFocusableElements();
      if (focusableElements.length > 0) {
        focusableElements[0].focus();
      }
    }

    // Add keyboard event listener for focus trapping
    if (trapFocus) {
      document.addEventListener('keydown', handleKeyDown);
    }

    return () => {
      if (trapFocus) {
        document.removeEventListener('keydown', handleKeyDown);
      }

      // Restore focus when disabled
      if (restoreFocusRef?.current) {
        restoreFocusRef.current.focus();
      } else if (previousActiveElement.current) {
        previousActiveElement.current.focus();
      }
    };
  }, [
    enabled,
    initialFocusRef,
    restoreFocusRef,
    trapFocus,
    handleKeyDown,
    getFocusableElements,
  ]);
};

export default useFocusManagement;

/**
 * useFormValidation Hook
 * 
 * Custom hook for managing form validation state
 */

import { useState, useCallback, useMemo } from 'react';

export interface ValidationRule<T = any> {
  field: keyof T;
  validate: (value: unknown, formData: T) => string | null;
  message?: string;
}

export interface UseFormValidationResult<T> {
  errors: Partial<Record<keyof T, string>>;
  isValid: boolean;
  validationErrors: string[];
  validate: (formData: T) => boolean;
  validateField: (field: keyof T, value: unknown, formData: T) => string | null;
  clearErrors: () => void;
  clearFieldError: (field: keyof T) => void;
  setFieldError: (field: keyof T, error: string) => void;
}

export function useFormValidation<T extends Record<string, unknown>>(
  rules: ValidationRule<T>[]
): UseFormValidationResult<T> {
  const [errors, setErrors] = useState<Partial<Record<keyof T, string>>>({});

  const validateField = useCallback(
    (field: keyof T, value: unknown, formData: T): string | null => {
      const fieldRules = rules.filter(rule => rule.field === field);
      
      for (const rule of fieldRules) {
        const error = rule.validate(value, formData);
        if (error) {
          return error;
        }
      }
      
      return null;
    },
    [rules]
  );

  const validate = useCallback(
    (formData: T): boolean => {
      const newErrors: Partial<Record<keyof T, string>> = {};
      let hasErrors = false;

      for (const rule of rules) {
        const value = formData[rule.field];
        const error = rule.validate(value, formData);
        
        if (error) {
          newErrors[rule.field] = error;
          hasErrors = true;
        }
      }

      setErrors(newErrors);
      return !hasErrors;
    },
    [rules]
  );

  const clearErrors = useCallback(() => {
    setErrors({});
  }, []);

  const clearFieldError = useCallback((field: keyof T) => {
    setErrors(prev => {
      const newErrors = { ...prev };
      delete newErrors[field];
      return newErrors;
    });
  }, []);

  const setFieldError = useCallback((field: keyof T, error: string) => {
    setErrors(prev => ({
      ...prev,
      [field]: error,
    }));
  }, []);

  const isValid = useMemo(() => {
    return Object.keys(errors).length === 0;
  }, [errors]);

  const validationErrors = useMemo(() => {
    return Object.values(errors).filter((error): error is string => error !== undefined);
  }, [errors]);

  return {
    errors,
    isValid,
    validationErrors,
    validate,
    validateField,
    clearErrors,
    clearFieldError,
    setFieldError,
  };
}

/**
 * Common validation rules
 */
export const ValidationRules = {
  required: (message = 'This field is required') => (value: unknown) => {
    if (value === null || value === undefined || value === '') {
      return message;
    }
    return null;
  },

  url: (message = 'Please enter a valid URL') => (value: string) => {
    if (!value) return null;
    
    try {
      new URL(value);
      return null;
    } catch {
      return message;
    }
  },

  minLength: (min: number, message?: string) => (value: string) => {
    if (!value) return null;
    
    if (value.length < min) {
      return message || `Must be at least ${min} characters`;
    }
    return null;
  },

  maxLength: (max: number, message?: string) => (value: string) => {
    if (!value) return null;
    
    if (value.length > max) {
      return message || `Must be at most ${max} characters`;
    }
    return null;
  },

  pattern: (regex: RegExp, message = 'Invalid format') => (value: string) => {
    if (!value) return null;
    
    if (!regex.test(value)) {
      return message;
    }
    return null;
  },

  number: (message = 'Must be a valid number') => (value: unknown) => {
    if (value === null || value === undefined || value === '') return null;
    
    if (isNaN(Number(value))) {
      return message;
    }
    return null;
  },

  min: (min: number, message?: string) => (value: number) => {
    if (value === null || value === undefined) return null;
    
    if (value < min) {
      return message || `Must be at least ${min}`;
    }
    return null;
  },

  max: (max: number, message?: string) => (value: number) => {
    if (value === null || value === undefined) return null;
    
    if (value > max) {
      return message || `Must be at most ${max}`;
    }
    return null;
  },

  email: (message = 'Please enter a valid email address') => (value: string) => {
    if (!value) return null;
    
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      return message;
    }
    return null;
  },

  custom: <T = any>(validator: (value: unknown, formData: T) => boolean, message: string) => 
    (value: unknown, formData: T) => {
      if (!validator(value, formData)) {
        return message;
      }
      return null;
    },
};

/**
 * useKeyboardNavigation Hook
 * 
 * Provides keyboard navigation utilities for wizard components
 * Implements accessibility best practices for keyboard interaction
 * 
 * Requirements: 13.3
 */

import { useCallback, useEffect, useRef } from 'react';

/**
 * Options for keyboard navigation
 */
export interface KeyboardNavigationOptions {
  /**
   * Enable arrow key navigation for lists
   */
  enableArrowKeys?: boolean;
  
  /**
   * Enable Enter/Space key activation
   */
  enableActivation?: boolean;
  
  /**
   * Enable Escape key to close/cancel
   */
  enableEscape?: boolean;
  
  /**
   * Callback when Enter or Space is pressed
   */
  onActivate?: () => void;
  
  /**
   * Callback when Escape is pressed
   */
  onEscape?: () => void;
  
  /**
   * Callback when arrow keys are pressed
   */
  onArrowKey?: (direction: 'up' | 'down' | 'left' | 'right') => void;
}

/**
 * Hook for handling keyboard navigation
 */
export function useKeyboardNavigation(options: KeyboardNavigationOptions = {}) {
  const {
    enableArrowKeys = false,
    enableActivation = true,
    enableEscape = false,
    onActivate,
    onEscape,
    onArrowKey,
  } = options;

  /**
   * Handle keyboard events
   */
  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      // Handle activation keys (Enter/Space)
      if (enableActivation && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault();
        onActivate?.();
        return;
      }

      // Handle escape key
      if (enableEscape && event.key === 'Escape') {
        event.preventDefault();
        onEscape?.();
        return;
      }

      // Handle arrow keys
      if (enableArrowKeys && onArrowKey) {
        switch (event.key) {
          case 'ArrowUp':
            event.preventDefault();
            onArrowKey('up');
            break;
          case 'ArrowDown':
            event.preventDefault();
            onArrowKey('down');
            break;
          case 'ArrowLeft':
            event.preventDefault();
            onArrowKey('left');
            break;
          case 'ArrowRight':
            event.preventDefault();
            onArrowKey('right');
            break;
        }
      }
    },
    [enableActivation, enableEscape, enableArrowKeys, onActivate, onEscape, onArrowKey]
  );

  return { handleKeyDown };
}

/**
 * Hook for managing focus within a list of items
 */
export function useListKeyboardNavigation<T extends HTMLElement>(
  itemCount: number,
  options: {
    onSelect?: (index: number) => void;
    orientation?: 'vertical' | 'horizontal';
    loop?: boolean;
  } = {}
) {
  const { onSelect, orientation = 'vertical', loop = true } = options;
  const currentIndexRef = useRef<number>(0);
  const itemRefs = useRef<(T | null)[]>([]);

  /**
   * Set ref for an item at a specific index
   */
  const setItemRef = useCallback((index: number) => {
    return (element: T | null) => {
      itemRefs.current[index] = element;
    };
  }, []);

  /**
   * Focus an item at a specific index
   */
  const focusItem = useCallback((index: number) => {
    if (index >= 0 && index < itemCount) {
      currentIndexRef.current = index;
      itemRefs.current[index]?.focus();
    }
  }, [itemCount]);

  /**
   * Handle keyboard navigation
   */
  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      const isVertical = orientation === 'vertical';
      const nextKey = isVertical ? 'ArrowDown' : 'ArrowRight';
      const prevKey = isVertical ? 'ArrowUp' : 'ArrowLeft';

      let newIndex = currentIndexRef.current;

      switch (event.key) {
        case nextKey:
          event.preventDefault();
          newIndex = currentIndexRef.current + 1;
          if (newIndex >= itemCount) {
            newIndex = loop ? 0 : itemCount - 1;
          }
          focusItem(newIndex);
          break;

        case prevKey:
          event.preventDefault();
          newIndex = currentIndexRef.current - 1;
          if (newIndex < 0) {
            newIndex = loop ? itemCount - 1 : 0;
          }
          focusItem(newIndex);
          break;

        case 'Home':
          event.preventDefault();
          focusItem(0);
          break;

        case 'End':
          event.preventDefault();
          focusItem(itemCount - 1);
          break;

        case 'Enter':
        case ' ':
          event.preventDefault();
          onSelect?.(currentIndexRef.current);
          break;
      }
    },
    [itemCount, orientation, loop, focusItem, onSelect]
  );

  return {
    handleKeyDown,
    setItemRef,
    focusItem,
    currentIndex: currentIndexRef.current,
  };
}

/**
 * Hook for managing focus trap within a modal or dialog
 */
export function useFocusTrap(isActive: boolean) {
  const containerRef = useRef<HTMLElement | null>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!isActive || !containerRef.current) return;

    // Store the currently focused element
    previousFocusRef.current = document.activeElement as HTMLElement;

    // Get all focusable elements within the container
    const getFocusableElements = () => {
      if (!containerRef.current) return [];
      
      const focusableSelectors = [
        'a[href]',
        'button:not([disabled])',
        'textarea:not([disabled])',
        'input:not([disabled])',
        'select:not([disabled])',
        '[tabindex]:not([tabindex="-1"])',
      ].join(', ');

      return Array.from(
        containerRef.current.querySelectorAll<HTMLElement>(focusableSelectors)
      );
    };

    // Focus the first focusable element
    const focusableElements = getFocusableElements();
    if (focusableElements.length > 0) {
      focusableElements[0].focus();
    }

    // Handle Tab key to trap focus
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;

      const focusableElements = getFocusableElements();
      if (focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey) {
        // Shift + Tab: move focus backwards
        if (document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        }
      } else {
        // Tab: move focus forwards
        if (document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    // Cleanup: restore focus to previous element
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      if (previousFocusRef.current) {
        previousFocusRef.current.focus();
      }
    };
  }, [isActive]);

  return containerRef;
}

/**
 * Hook for announcing changes to screen readers
 */
export function useAriaLiveAnnouncement() {
  const announcementRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    // Create announcement element if it doesn't exist
    if (!announcementRef.current) {
      const element = document.createElement('div');
      element.setAttribute('role', 'status');
      element.setAttribute('aria-live', 'polite');
      element.setAttribute('aria-atomic', 'true');
      element.style.position = 'absolute';
      element.style.left = '-10000px';
      element.style.width = '1px';
      element.style.height = '1px';
      element.style.overflow = 'hidden';
      document.body.appendChild(element);
      announcementRef.current = element;
    }

    return () => {
      if (announcementRef.current) {
        document.body.removeChild(announcementRef.current);
        announcementRef.current = null;
      }
    };
  }, []);

  const announce = useCallback((message: string) => {
    if (announcementRef.current) {
      announcementRef.current.textContent = message;
    }
  }, []);

  return announce;
}

