/**
 * useKeyframes Hook
 * 
 * React hook for keyframe-based animations.
 * Provides declarative keyframe animations inspired by Remotion's animation patterns.
 * 
 * Validates: Requirements 11.8 - Animation System
 * 
 * @example
 * ```tsx
 * const { value } = useKeyframes({
 *   from: { opacity: 0, transform: { scale: 0 } },
 *   keyframes: [
 *     { time: 0, value: { opacity: 0.5, scale: 0.5 } },
 *     { time: 0.5, value: { opacity: 1, scale: 1 }, easing: Easing.easeOutBounce },
 *     { time: 1, value: { opacity: 0, scale: 1.5 } }
 *   ],
 *   duration: 1000,
 *   loop: true
 * });
 * ```
 */

import { 
  useCallback, 
  useEffect, 
  useRef, 
  useState 
} from 'react';
import { 
  Keyframe, 
  KeyframeAnimationConfig, 
  AnimationInstance,
  EasingFunction,
  Easing 
} from '../services/animation/AnimationTypes';

/**
 * Keyframe animation hook return type
 */
export interface UseKeyframesReturn<T> {
  value: T;
  progress: number;
  isAnimating: boolean;
  play: () => void;
  pause: () => void;
  stop: () => void;
  seek: (progress: number) => void;
  reset: () => void;
}

/**
 * Interpolate between two values with easing
 */
function interpolateValue(
  from: number,
  to: number,
  progress: number,
  easing?: EasingFunction
): number {
  const easedProgress = easing ? easing(progress) : progress;
  return from + (to - from) * easedProgress;
}

/**
 * Parse keyframe time values (handle both 0-1 percentages and absolute times)
 */
function parseKeyframes<T>(
  keyframes: Array<Keyframe<T>>,
  duration: number,
  fromValue: T extends number ? number : never,
  toValue: T extends number ? number : never
): Array<{ time: number; value: number; easing?: EasingFunction }> {
  return keyframes.map((kf, index) => {
    let time: number;
    
    if (kf.time >= 0 && kf.time <= 1) {
      // Percentage-based time
      time = kf.time * duration;
    } else {
      // Absolute time
      time = kf.time;
    }
    
    // Get value
    const value = typeof kf.value === 'number' ? kf.value : 
      kf.value as unknown as number;
    
    return {
      time,
      value,
      easing: kf.easing
    };
  }).sort((a, b) => a.time - b.time);
}

/**
 * Hook for single value keyframe animation
 */
export function useKeyframes(
  config: {
    from: number;
    to: number;
    keyframes: Array<Keyframe<number>>;
    duration: number;
    easing?: EasingFunction;
    delay?: number;
    loop?: boolean | number;
    direction?: 'normal' | 'reverse' | 'alternate';
    immediate?: boolean;
  }
): UseKeyframesReturn<number> {
  const [value, setValue] = useState(config.from);
  const [progress, setProgress] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationRef = useRef<{
    startTime: number;
    pausedAt: number;
    isPaused: boolean;
    loopCount: number;
    direction: 'normal' | 'reverse';
  } | null>(null);
  const rafRef = useRef<number | null>(null);

  // Parse keyframes
  const parsedKeyframes = useRef(parseKeyframes(config.keyframes, config.duration, config.from, config.to));
  const totalDuration = config.duration;

  // Calculate value at a given progress (0-1)
  const calculateValue = useCallback((prog: number): number => {
    const keyframes = parsedKeyframes.current;
    
    if (keyframes.length === 0) {
      return interpolateValue(config.from, config.to, prog, config.easing);
    }

    // Add start and end keyframes if not present
    const allKeyframes = [
      { time: 0, value: config.from, easing: undefined as EasingFunction | undefined },
      ...keyframes,
      { time: totalDuration, value: config.to, easing: undefined as EasingFunction | undefined }
    ];

    // Find the current keyframe segment
    let startKf = allKeyframes[0];
    let endKf = allKeyframes[1];

    for (let i = 1; i < allKeyframes.length; i++) {
      if (prog * totalDuration >= allKeyframes[i].time) {
        startKf = allKeyframes[i - 1];
        endKf = allKeyframes[i];
      }
    }

    // Calculate progress within this segment
    const segmentDuration = endKf.time - startKf.time;
    const segmentProgress = segmentDuration > 0 
      ? (prog * totalDuration - startKf.time) / segmentDuration 
      : 0;

    return interpolateValue(startKf.value, endKf.value, segmentProgress, endKf.easing || config.easing);
  }, [config.from, config.to, config.easing]);

  // Animation loop
  const animate = useCallback(() => {
    if (!animationRef.current) return;

    const { startTime, isPaused, loopCount, direction } = animationRef.current;

    if (isPaused) {
      rafRef.current = requestAnimationFrame(animate);
      return;
    }

    const now = performance.now();
    const elapsed = now - startTime;
    const totalElapsed = elapsed;

    // Calculate progress
    let prog: number;
    const currentLoop = Math.floor(totalElapsed / totalDuration);
    const loopProgress = (totalElapsed % totalDuration) / totalDuration;

    if (config.loop && typeof config.loop === 'number' && currentLoop >= config.loop) {
      // Animation complete
      setProgress(1);
      setValue(config.direction === 'reverse' ? config.from : config.to);
      setIsAnimating(false);
      return;
    }

    if (config.direction === 'alternate' && currentLoop % 2 === 1) {
      prog = 1 - loopProgress;
    } else if (config.direction === 'reverse') {
      prog = 1 - loopProgress;
    } else {
      prog = loopProgress;
    }

    const clampedProgress = Math.min(Math.max(prog, 0), 1);
    const newValue = calculateValue(clampedProgress);

    setProgress(clampedProgress);
    setValue(newValue);

    rafRef.current = requestAnimationFrame(animate);
  }, [config.from, config.to, config.loop, config.direction, totalDuration, calculateValue]);

  // Play animation
  const play = useCallback(() => {
    if (isAnimating) return;

    const now = performance.now();
    animationRef.current = {
      startTime: now - (progress * totalDuration),
      pausedAt: 0,
      isPaused: false,
      loopCount: 0,
      direction: config.direction === 'reverse' ? 'reverse' : 'normal'
    };

    setIsAnimating(true);
    rafRef.current = requestAnimationFrame(animate);
  }, [isAnimating, progress, totalDuration, config.direction, animate]);

  // Pause animation
  const pause = useCallback(() => {
    if (!animationRef.current) return;
    
    animationRef.current.isPaused = true;
    animationRef.current.pausedAt = progress * totalDuration;
    
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }
  }, [progress, totalDuration]);

  // Stop animation
  const stop = useCallback(() => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }

    animationRef.current = null;
    setIsAnimating(false);
    setProgress(0);
    setValue(config.from);
  }, [config.from]);

  // Seek to a specific progress
  const seek = useCallback((newProgress: number) => {
    const clampedProgress = Math.min(Math.max(newProgress, 0), 1);
    const newValue = calculateValue(clampedProgress);

    setProgress(clampedProgress);
    setValue(newValue);
  }, [calculateValue]);

  // Reset animation
  const reset = useCallback(() => {
    stop();
  }, [stop]);

  // Effect to handle immediate animations
  useEffect(() => {
    if (config.immediate) {
      setValue(config.to);
      setProgress(1);
    }
  }, [config.to, config.immediate]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  return {
    value,
    progress,
    isAnimating,
    play,
    pause,
    stop,
    seek,
    reset
  };
}

/**
 * Hook for object value keyframe animations
 */
export function useKeyframesObject<T extends object>(
  config: {
    from: T;
    to: T;
    keyframes: Array<Keyframe<T>>;
    duration: number;
    easing?: EasingFunction;
    delay?: number | { [K in keyof T]?: number };
    loop?: boolean | number;
    direction?: 'normal' | 'reverse' | 'alternate';
    immediate?: boolean;
  }
): UseKeyframesReturn<T> {
  const [values, setValues] = useState<T>(config.from);
  const [progress, setProgress] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationRef = useRef<{
    startTime: number;
    pausedAt: number;
    isPaused: boolean;
    direction: 'normal' | 'reverse';
  } | null>(null);
  const rafRef = useRef<number | null>(null);
  const totalDuration = config.duration;

  // Parse keyframes for each property
  const parsedKeyframes = useRef<Map<keyof T, Array<{ time: number; value: number; easing?: EasingFunction }>>>(
    new Map()
  );

  // Initialize keyframes for each property
  useEffect(() => {
    const keys = Object.keys(config.from) as (keyof T)[];
    
    keys.forEach(key => {
      const keyframesForKey: Array<Keyframe<number>> = [];
      
      config.keyframes.forEach(kf => {
        if (typeof kf.value === 'object' && kf.value !== null) {
          const objValue = kf.value as unknown as { [K in keyof T]: number };
          if (key in objValue) {
            keyframesForKey.push({
              time: kf.time,
              value: objValue[key],
              easing: kf.easing
            });
          }
        }
      });

      parsedKeyframes.current.set(
        key, 
        parseKeyframes(keyframesForKey, totalDuration, config.from[key] as number, config.to[key] as number)
      );
    });
  }, [config.from, config.to, config.keyframes, totalDuration]);

  // Calculate value for a single property
  const calculatePropertyValue = useCallback((
    key: keyof T,
    prog: number,
    fromVal: number,
    toVal: number,
    easing?: EasingFunction
  ): number => {
    const keyframes = parsedKeyframes.current.get(key);
    
    if (!keyframes || keyframes.length === 0) {
      return interpolateValue(fromVal, toVal, prog, easing);
    }

    const allKeyframes = [
      { time: 0, value: fromVal, easing: undefined as EasingFunction | undefined },
      ...keyframes,
      { time: totalDuration, value: toVal, easing: undefined as EasingFunction | undefined }
    ];

    let startKf = allKeyframes[0];
    let endKf = allKeyframes[1];

    for (let i = 1; i < allKeyframes.length; i++) {
      if (prog * totalDuration >= allKeyframes[i].time) {
        startKf = allKeyframes[i - 1];
        endKf = allKeyframes[i];
      }
    }

    const segmentDuration = endKf.time - startKf.time;
    const segmentProgress = segmentDuration > 0 
      ? (prog * totalDuration - startKf.time) / segmentDuration 
      : 0;

    return interpolateValue(startKf.value, endKf.value, segmentProgress, endKf.easing || easing);
  }, [totalDuration]);

  // Animation loop
  const animate = useCallback(() => {
    if (!animationRef.current) return;

    const { startTime, isPaused, direction } = animationRef.current;

    if (isPaused) {
      rafRef.current = requestAnimationFrame(animate);
      return;
    }

    const now = performance.now();
    const elapsed = now - startTime;
    const loopProgress = (elapsed % totalDuration) / totalDuration;

    let prog: number;
    if (direction === 'reverse' || (config.direction === 'reverse' && !config.loop)) {
      prog = 1 - loopProgress;
    } else {
      prog = loopProgress;
    }

    const clampedProgress = Math.min(Math.max(prog, 0), 1);
    const keys = Object.keys(config.from) as (keyof T)[];

    const newValues = {} as T;
    keys.forEach(key => {
      newValues[key] = calculatePropertyValue(
        key,
        clampedProgress,
        config.from[key] as number,
        config.to[key] as number,
        config.easing
      ) as T[keyof T];
    });

    setValues(newValues);
    setProgress(clampedProgress);

    rafRef.current = requestAnimationFrame(animate);
  }, [config.from, config.to, config.direction, config.easing, totalDuration, calculatePropertyValue]);

  // Play
  const play = useCallback(() => {
    if (isAnimating) return;

    const now = performance.now();
    animationRef.current = {
      startTime: now - (progress * totalDuration),
      pausedAt: 0,
      isPaused: false,
      direction: config.direction === 'reverse' ? 'reverse' : 'normal'
    };

    setIsAnimating(true);
    rafRef.current = requestAnimationFrame(animate);
  }, [isAnimating, progress, totalDuration, config.direction, animate]);

  // Pause
  const pause = useCallback(() => {
    if (!animationRef.current) return;
    
    animationRef.current.isPaused = true;
    
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }
  }, []);

  // Stop
  const stop = useCallback(() => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }

    animationRef.current = null;
    setIsAnimating(false);
    setProgress(0);
    setValues(config.from);
  }, [config.from]);

  // Seek
  const seek = useCallback((newProgress: number) => {
    const clampedProgress = Math.min(Math.max(newProgress, 0), 1);
    const keys = Object.keys(config.from) as (keyof T)[];

    const newValues = {} as T;
    keys.forEach(key => {
      newValues[key] = calculatePropertyValue(
        key,
        clampedProgress,
        config.from[key] as number,
        config.to[key] as number,
        config.easing
      ) as T[keyof T];
    });

    setValues(newValues);
    setProgress(clampedProgress);
  }, [config.from, config.to, config.easing, calculatePropertyValue]);

  // Reset
  const reset = useCallback(() => {
    stop();
  }, [stop]);

  // Effect to handle immediate animations
  useEffect(() => {
    if (config.immediate) {
      setValues(config.to);
      setProgress(1);
    }
  }, [config.to, config.immediate]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  return {
    value: values,
    progress,
    isAnimating,
    play,
    pause,
    stop,
    seek,
    reset
  };
}

/**
 * Staggered keyframe animation for lists
 */
export function useKeyframesStagger<T>(
  items: T[],
  config: {
    from: T extends object ? { [K in keyof T]: number } : number;
    to: T extends object ? { [K in keyof T]: number } : number;
    keyframes?: Array<Keyframe<T extends object ? { [K in keyof T]: number } : number>>;
    duration: number;
    stagger: number;
    easing?: EasingFunction;
    loop?: boolean | number;
  }
): {
  values: Array<T extends object ? { [K in keyof T]: number } : number>;
  play: () => void;
  stop: () => void;
} {
  const [values, setValues] = useState<Array<T extends object ? { [K in keyof T]: number } : number>>(
    items.map(() => config.from as any)
  );
  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Calculate value for item at index
  const calculateValue = useCallback((index: number, progress: number): unknown => {
    const fromVal = config.from as any;
    const toVal = config.to as any;

    // Apply stagger delay
    const staggerDelay = index * config.stagger;
    const adjustedDuration = config.duration - staggerDelay;
    
    if (progress < 0) {
      return fromVal;
    }

    const itemProgress = adjustedDuration > 0 
      ? Math.min(Math.max((progress - staggerDelay) / adjustedDuration, 0), 1)
      : 1;

    if (typeof fromVal === 'number') {
      return interpolateValue(fromVal, toVal, itemProgress, config.easing);
    }

    const result = {} as any;
    Object.keys(fromVal).forEach(key => {
      result[key] = interpolateValue(
        fromVal[key] as number,
        toVal[key] as number,
        itemProgress,
        config.easing
      );
    });

    return result;
  }, [config.from, config.to, config.duration, config.stagger, config.easing]);

  // Animation loop
  const animate = useCallback(() => {
    if (!startTimeRef.current) {
      startTimeRef.current = performance.now();
    }

    const now = performance.now();
    const elapsed = now - startTimeRef.current;
    const progress = elapsed / config.duration;

    if (progress <= 1) {
      const newValues = items.map((_, index) => calculateValue(index, progress * config.duration));
      setValues(newValues as any);
      rafRef.current = requestAnimationFrame(animate);
    } else if (config.loop) {
      startTimeRef.current = null;
      rafRef.current = requestAnimationFrame(animate);
    }
  }, [items.length, config.duration, config.loop, calculateValue]);

  // Play
  const play = useCallback(() => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }
    startTimeRef.current = null;
    rafRef.current = requestAnimationFrame(animate);
  }, [animate]);

  // Stop
  const stop = useCallback(() => {
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    startTimeRef.current = null;
    setValues(items.map(() => config.from as any));
  }, [items.length, config.from]);

  return {
    values,
    play,
    stop
  };
}

export { Easing };

import { useState, useCallback, useRef, useEffect } from 'react';
import { LLMService, LLMError } from '@/services/llmService';
import { llmConfigService } from '@/services/llmConfigService';
import type {
  LLMRequest,
  LLMResponse,
  ErrorRecoveryOptions,
} from '@/services/llmService';

// ============================================================================
// LLM Generation State
// ============================================================================

export interface LLMGenerationState {
  isLoading: boolean;
  isStreaming: boolean;
  error: ErrorRecoveryOptions | null;
  data: LLMResponse | null;
  streamedContent: string;
  requestId: string | null;
}

export interface UseLLMGenerationOptions {
  onSuccess?: (data: LLMResponse) => void;
  onError?: (error: ErrorRecoveryOptions) => void;
  onManualEntry?: () => void;
  autoRetry?: boolean;
  maxRetries?: number;
  llmService?: LLMService;
}

// ============================================================================
// useLLMGeneration Hook
// ============================================================================

export function useLLMGeneration(options: UseLLMGenerationOptions = {}) {
  const {
    onSuccess,
    onError,
    onManualEntry,
    autoRetry = false,
    maxRetries = 1,
  } = options;

  // Get LLM service from llmConfigService (always up-to-date)
  const [llmService, setLLMService] = useState<LLMService | null>(() => 
    options.llmService || llmConfigService.getService()
  );

  // Subscribe to configuration changes
  useEffect(() => {
    if (options.llmService) {
      // If a custom service is provided, use it
      return;
    }

    // Subscribe to config changes
    const unsubscribe = llmConfigService.subscribe(() => {
      const newService = llmConfigService.getService();
      setLLMService(newService);
    });

    return unsubscribe;
  }, [options.llmService]);

  const [state, setState] = useState<LLMGenerationState>({
    isLoading: false,
    isStreaming: false,
    error: null,
    data: null,
    streamedContent: '',
    requestId: null,
  });

  const retryCountRef = useRef(0);
  const lastRequestRef = useRef<LLMRequest | null>(null);

  // ============================================================================
  // Generate Completion
  // ============================================================================

  const generate = useCallback(
    async (request: LLMRequest) => {
      if (!llmService) {
        const error = new Error('LLM service not initialized. Please configure your LLM settings first.');
        error.name = 'LLMServiceNotInitialized';
        handleError(error);
        return;
      }

      // Store request for retry
      lastRequestRef.current = request;
      retryCountRef.current = 0;

      // Reset state
      setState({
        isLoading: true,
        isStreaming: false,
        error: null,
        data: null,
        streamedContent: '',
        requestId: `req_${Date.now()}`,
      });

      try {
        const response = await llmService.generateCompletion(request, state.requestId || undefined);

        if (response.success && response.data) {
          setState((prev) => ({
            ...prev,
            isLoading: false,
            data: response.data!,
          }));
          onSuccess?.(response.data);
        } else {
          console.error('❌ LLM GENERATION FAILED - Error:', response.error, 'Code:', response.code);
          throw new LLMError(
            response.error || 'Generation failed',
            response.code || 'unknown',
            false
          );
        }
      } catch (error) {
        handleError(error as Error);
      }
    },
    [llmService, onSuccess, state.requestId]
  );

  // ============================================================================
  // Generate Streaming Completion
  // ============================================================================

  const generateStreaming = useCallback(
    async (request: LLMRequest) => {
      if (!llmService) {
        const error = new Error('LLM service not initialized. Please configure your LLM settings first.');
        error.name = 'LLMServiceNotInitialized';
        handleError(error);
        return;
      }

      // Store request for retry
      lastRequestRef.current = request;
      retryCountRef.current = 0;

      // Reset state
      setState({
        isLoading: true,
        isStreaming: true,
        error: null,
        data: null,
        streamedContent: '',
        requestId: `req_${Date.now()}`,
      });

      try {
        const response = await llmService.generateStreamingCompletion(
          request,
          (chunk) => {
            setState((prev) => ({
              ...prev,
              streamedContent: prev.streamedContent + chunk,
            }));
          },
          state.requestId || undefined
        );

        if (response.success && response.data) {
          setState((prev) => ({
            ...prev,
            isLoading: false,
            isStreaming: false,
            data: response.data!,
          }));
          onSuccess?.(response.data);
        } else {
          throw new LLMError(
            response.error || 'Generation failed',
            response.code || 'unknown',
            false
          );
        }
      } catch (error) {
        handleError(error as Error);
      }
    },
    [llmService, onSuccess, state.requestId]
  );

  // ============================================================================
  // Error Handling
  // ============================================================================

  const handleError = useCallback(
    (error: Error) => {
      if (!llmService) {
        console.error('[useLLMGeneration] No LLM service available for error handling');
        return;
      }

      const recoveryOptions = llmService.createRecoveryOptions(
        error,
        () => retry(),
        onManualEntry,
        () => cancel()
      );

      setState((prev) => ({
        ...prev,
        isLoading: false,
        isStreaming: false,
        error: recoveryOptions,
      }));

      onError?.(recoveryOptions);

      // Auto-retry if enabled and error is retryable
      if (autoRetry && recoveryOptions.retryable && retryCountRef.current < maxRetries) {
        retryCountRef.current++;
        setTimeout(() => {
          if (lastRequestRef.current) {
            if (state.isStreaming) {
              generateStreaming(lastRequestRef.current);
            } else {
              generate(lastRequestRef.current);
            }
          }
        }, 1000 * retryCountRef.current); // Exponential backoff
      }
    },
    [llmService, onManualEntry, onError, autoRetry, maxRetries, state.isStreaming]
  );

  // ============================================================================
  // Retry
  // ============================================================================

  const retry = useCallback(() => {
    if (!lastRequestRef.current) return;

    if (state.isStreaming) {
      generateStreaming(lastRequestRef.current);
    } else {
      generate(lastRequestRef.current);
    }
  }, [generate, generateStreaming, state.isStreaming]);

  // ============================================================================
  // Cancel
  // ============================================================================

  const cancel = useCallback(() => {
    if (!llmService) return;
    
    if (state.requestId) {
      llmService.cancelRequest(state.requestId);
    }

    setState((prev) => ({
      ...prev,
      isLoading: false,
      isStreaming: false,
      error: null,
    }));
  }, [llmService, state.requestId]);

  // ============================================================================
  // Clear Error
  // ============================================================================

  const clearError = useCallback(() => {
    setState((prev) => ({
      ...prev,
      error: null,
    }));
  }, []);

  // ============================================================================
  // Reset
  // ============================================================================

  const reset = useCallback(() => {
    cancel();
    lastRequestRef.current = null;
    retryCountRef.current = 0;
    setState({
      isLoading: false,
      isStreaming: false,
      error: null,
      data: null,
      streamedContent: '',
      requestId: null,
    });
  }, [cancel]);

  // ============================================================================
  // Return
  // ============================================================================

  return {
    ...state,
    generate,
    generateStreaming,
    retry,
    cancel,
    clearError,
    reset,
  };
}

// ============================================================================
// Simplified Hook for Non-Streaming Generation
// ============================================================================

export function useSimpleLLMGeneration(options: UseLLMGenerationOptions = {}) {
  const generation = useLLMGeneration(options);

  return {
    isLoading: generation.isLoading,
    error: generation.error,
    data: generation.data,
    generate: generation.generate,
    retry: generation.retry,
    cancel: generation.cancel,
    clearError: generation.clearError,
    reset: generation.reset,
  };
}

/// <reference path="../types/electron.d.ts" />

import { useState, useCallback } from 'react';
import type { RecentProject } from '@/components/launcher/RecentProjectsList';
import { useAppStore } from '@/stores/useAppStore';
import { useEditorStore } from '@/stores/editorStore';
import { useCharacterPersistence } from '@/hooks/useCharacterPersistence';
import { useWorldPersistence } from '@/hooks/useWorldPersistence';
import type { Project as StoreProject } from '@/types';
import { generateProjectTemplate, sequencesToShots } from '@/utils/projectTemplateGenerator';
import type { SerializableProjectFormat } from '@/components/launcher/CreateProjectDialog';

// Helper function to convert Electron project to Store project format
function convertElectronProjectToStore(electronProject: unknown): StoreProject {
  // Extract config from Electron project
  const config = electronProject.config || {};
  
  return {
    schema_version: config.schema_version || '1.0',
    project_name: electronProject.name || config.project_name || 'Untitled Project',
    shots: config.shots || [],
    assets: config.assets || [],
    worlds: config.worlds,
    selectedWorldId: config.selectedWorldId,
    characters: config.characters,
    capabilities: config.capabilities || {
      grid_generation: true,
      promotion_engine: true,
      qa_engine: true,
      autofix_engine: true,
    },
    generation_status: config.generation_status || {
      grid: 'pending',
      promotion: 'pending',
    },
    casting: config.casting,
    metadata: {
      id: electronProject.id,
      path: electronProject.path,
      version: electronProject.version,
      created_at: electronProject.createdAt instanceof Date 
        ? electronProject.createdAt.toISOString() 
        : electronProject.createdAt || config.created_at || new Date().toISOString(),
      updated_at: electronProject.modifiedAt instanceof Date 
        ? electronProject.modifiedAt.toISOString() 
        : electronProject.modifiedAt || config.modified_at || new Date().toISOString(),
      ...config.metadata,
    },
  };
}

// ============================================================================
// Types
// ============================================================================

interface UseLandingPageReturn {
  // State
  isLoading: boolean;
  error: string | null;
  showCreateDialog: boolean;
  showOpenDialog: boolean;
  recentProjects: RecentProject[];

  // Actions
  handleCreateProject: () => void;
  handleOpenProject: () => void;
  handleCreateProjectSubmit: (projectName: string, projectPath: string, format: unknown) => Promise<void>;
  handleOpenProjectSubmit: (projectPath: string) => Promise<void>;
  handleRecentProjectClick: (project: RecentProject) => void;
  handleRemoveRecentProject: (projectPath: string) => Promise<void>;
  setShowCreateDialog: (show: boolean) => void;
  setShowOpenDialog: (show: boolean) => void;
  clearError: () => void;
}

// ============================================================================
// useLandingPage Hook
// ============================================================================

export function useLandingPage(): UseLandingPageReturn {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showOpenDialog, setShowOpenDialog] = useState(false);
  const [recentProjects, setRecentProjects] = useState<RecentProject[]>([]);

  // Get store actions
  const setProject = useAppStore((state) => state.setProject);
  const setShots = useAppStore((state) => state.setShots);

  // Get persistence functions at top level (hooks can only be called at top level)
  const { loadAndSyncCharacters } = useCharacterPersistence();
  const { syncWorldsFromProject } = useWorldPersistence();

  // Load recent projects on mount
  const loadRecentProjects = useCallback(async () => {
    try {
      if (window.electronAPI) {
        const projects = await window.electronAPI.recentProjects.get();
        setRecentProjects(projects);
      }
    } catch (err) {
      console.error('Failed to load recent projects:', err);
      // Don't show error to user for this - just log it
    }
  }, []);

  // Handle create project button click
  const handleCreateProject = useCallback(() => {
    setError(null);
    setShowCreateDialog(true);
  }, []);

  // Handle create project submission
  const handleCreateProjectSubmit = useCallback(
    async (projectName: string, projectPath: string, format: SerializableProjectFormat) => {
      console.log('[useLandingPage] handleCreateProjectSubmit called with:', {
        projectName,
        projectPath: projectPath || '(empty - will use default)',
        format: format.name,
      });
      
      setIsLoading(true);
      setError(null);

      try {
        // Generate project template based on format
        const template = generateProjectTemplate(format);
        const initialShots = sequencesToShots(template.sequences);

        if (window.electronAPI) {
          // Create project via Electron API with format (returns Project directly, throws on error)
          // If projectPath is empty, the backend will use the default Documents directory
          const createData: unknown = {
            name: projectName,
            format: format,
            initialShots: initialShots,
          };
          
          // Only include location if it's not empty - this ensures default path is used
          if (projectPath && projectPath.trim() !== '') {
            createData.location = projectPath;
            console.log('[useLandingPage] Using custom location:', projectPath);
          } else {
            console.log('[useLandingPage] No location specified, backend will use default path');
          }
          
          console.log('[useLandingPage] Creating project with data:', createData);
          const electronProject = await window.electronAPI.project.create(createData);

          console.log('Project created successfully:', electronProject);

          // Convert Electron project to Store project format
          const storeProject = convertElectronProjectToStore(electronProject);
          // Get the actual project path from the electron project
          const actualProjectPath = electronProject.path || `${projectPath}/${projectName}`;

          // Load the created project into the store
          setProject(storeProject);
          setShots(storeProject.shots || initialShots);

          // Set project path in editor store so persistence hooks can use it
          useEditorStore.getState().setProjectPath(actualProjectPath);

          // Reload recent projects
          await loadRecentProjects();

          // Close dialog
          setShowCreateDialog(false);

        } else {
          // Demo mode - simulate creation
          await new Promise((resolve) => setTimeout(resolve, 1000));

          // Create a demo project in Store format with format info and initial shots
          const demoProject: StoreProject = {
            schema_version: '1.0',
            project_name: projectName,
            shots: initialShots,
            assets: [],
            capabilities: {
              grid_generation: true,
              promotion_engine: true,
              qa_engine: true,
              autofix_engine: true,
            },
            generation_status: {
              grid: 'pending',
              promotion: 'pending',
            },
            metadata: {
              id: Date.now().toString(),
              path: `${projectPath}/${projectName}`,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
              format: format,
              sequences: template.sequences.length,
              totalShots: template.totalShots,
              totalDuration: template.totalDuration,
            },
          };

          // Load into store
          setProject(demoProject);
          setShots(initialShots);

          // Add to recent projects
          const newProject: RecentProject = {
            id: Date.now().toString(),
            name: projectName,
            path: `${projectPath}/${projectName}`,
            lastAccessed: new Date(),
            exists: true,
          };

          setRecentProjects((prev) => [newProject, ...prev].slice(0, 10));
          setShowCreateDialog(false);

        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to create project';
        setError(errorMessage);
        throw err; // Re-throw so dialog can handle it
      } finally {
        setIsLoading(false);
      }
    },
    [loadRecentProjects, setProject, setShots]
  );

// Handle open project submission
  const handleOpenProjectSubmit = useCallback(
    async (projectPath: string) => {
      setIsLoading(true);
      setError(null);

      try {
        if (window.electronAPI) {
          // Open project via Electron API (returns Project directly, throws on error)
          const electronProject = await window.electronAPI.project.open(projectPath);

          // Convert Electron project to Store project format
          const storeProject = convertElectronProjectToStore(electronProject);

          // Load the opened project into the store
          setProject(storeProject);
          setShots(storeProject.shots || []);

          // Set project path in editor store so persistence hooks can use it
          useEditorStore.getState().setProjectPath(projectPath);

          // Sync characters from project directory to store
          await loadAndSyncCharacters();

          // Sync worlds from project directory to store
          await syncWorldsFromProject();

          // Reload recent projects
          await loadRecentProjects();

          // Close dialog
          setShowOpenDialog(false);

        } else {
          // Demo mode - simulate opening
          await new Promise((resolve) => setTimeout(resolve, 1000));

          // Create a demo project in Store format
          const demoProject: StoreProject = {
            schema_version: '1.0',
            project_name: 'Demo Project',
            shots: [],
            assets: [],
            capabilities: {
              grid_generation: true,
              promotion_engine: true,
              qa_engine: true,
              autofix_engine: true,
            },
            generation_status: {
              grid: 'pending',
              promotion: 'pending',
            },
            metadata: {
              id: Date.now().toString(),
              path: projectPath,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
            },
          };

          // Load into store
          setProject(demoProject);
          setShots([]);

          // Set project path in editor store so persistence hooks can use it
          useEditorStore.getState().setProjectPath(projectPath);

          // Sync characters from project directory to store
          await loadAndSyncCharacters();

          // Sync worlds from project directory to store
          await syncWorldsFromProject();

          setShowOpenDialog(false);
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to open project';
        setError(errorMessage);
        throw err; // Re-throw so dialog can handle it
      } finally {
        setIsLoading(false);
      }
    },
    [loadRecentProjects, setProject, setShots, loadAndSyncCharacters, syncWorldsFromProject]
  );



  // ============================================================================
  // Handle open project button click
  // ============================================================================
  //
  // CRITICAL: This function implements two distinct code paths based on the
  // execution environment (Electron vs Browser mode). Native dialogs are
  // preferred in both environments when available.
  //
  const handleOpenProject = useCallback(async () => {
    setError(null);
    
    // ========================================================================
    // ELECTRON MODE: Use native OS file dialog
    // ========================================================================
    if (window.electronAPI) {
      try {
        setIsLoading(true);
        
        // Open native OS file dialog - returns selected path or null
        const selectedPath = await window.electronAPI.project.selectForOpen();
        
        if (selectedPath) {
          // User selected a path - proceed to open the project
          await handleOpenProjectSubmit(selectedPath);
        }
        // If selectedPath is null, user canceled the dialog - do nothing
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to select project';
        setError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    } else {
      // ======================================================================
      // BROWSER MODE: Try File System Access API, fallback to custom modal
      // ======================================================================
      
      // Check if File System Access API is available (Chrome, Edge, Opera)
      if ('showDirectoryPicker' in window) {
        try {
          setIsLoading(true);
          
          // Open native browser directory picker
          const dirHandle = await (window as any).showDirectoryPicker({
            mode: 'read',
          });
          
          // Get the full path (if available) or use the directory name
          const projectPath = dirHandle.name;
          
          if (projectPath) {
            await handleOpenProjectSubmit(projectPath);
          }
        } catch (err) {
          // User canceled or error occurred
          if (err instanceof Error && err.name !== 'AbortError') {
            const errorMessage = err.message || 'Failed to select project';
            setError(errorMessage);
          }
          // AbortError means user canceled - not an error
        } finally {
          setIsLoading(false);
        }
      } else {
        // Fallback to custom modal for browsers without File System Access API
        setShowOpenDialog(true);
      }
    }
  }, [handleOpenProjectSubmit]);

// Handle recent project click
  const handleRecentProjectClick = useCallback(
    async (project: RecentProject) => {
      if (project.exists === false) {
        setError(`Project "${project.name}" not found at ${project.path}`);
        return;
      }

      setIsLoading(true);
      setError(null);

      try {
        if (window.electronAPI) {
          // Open project via Electron API (returns Project directly, throws on error)
          const electronProject = await window.electronAPI.project.open(project.path);

          // Convert Electron project to Store project format
          const storeProject = convertElectronProjectToStore(electronProject);

          // Load the opened project into the store
          setProject(storeProject);
          setShots(storeProject.shots || []);

          // Set project path in editor store so persistence hooks can use it
          useEditorStore.getState().setProjectPath(project.path);

          // Sync characters from project directory to store
          await loadAndSyncCharacters();

          // Sync worlds from project directory to store
          await syncWorldsFromProject();

          // Reload recent projects to update last accessed time
          await loadRecentProjects();

        } else {
          // Demo mode - simulate opening
          await new Promise((resolve) => setTimeout(resolve, 500));

          // Create a demo project in Store format
          const demoProject: StoreProject = {
            schema_version: '1.0',
            project_name: project.name,
            shots: [],
            assets: [],
            capabilities: {
              grid_generation: true,
              promotion_engine: true,
              qa_engine: true,
              autofix_engine: true,
            },
            generation_status: {
              grid: 'pending',
              promotion: 'pending',
            },
            metadata: {
              id: project.id,
              path: project.path,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
            },
          };

          // Load into store
          setProject(demoProject);
          setShots([]);

          // Set project path in editor store so persistence hooks can use it
          useEditorStore.getState().setProjectPath(project.path);

          // Sync characters from project directory to store
          await loadAndSyncCharacters();

          // Sync worlds from project directory to store
          await syncWorldsFromProject();

          // Update last accessed time
          setRecentProjects((prev) =>
            prev.map((p) =>
              p.id === project.id ? { ...p, lastAccessed: new Date() } : p
            )
          );

        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to open project';
        setError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    },
    [loadRecentProjects, setProject, setShots, loadAndSyncCharacters, syncWorldsFromProject]
  );



  // Handle remove recent project
  const handleRemoveRecentProject = useCallback(
    async (projectPath: string) => {
      try {
        if (window.electronAPI) {
          // Remove via Electron API
          await window.electronAPI.recentProjects.remove(projectPath);

          // Reload recent projects
          await loadRecentProjects();
        } else {
          // Demo mode - remove from local state
          setRecentProjects((prev) => prev.filter((p) => p.path !== projectPath));
        }
      } catch (err) {
        console.error('Failed to remove recent project:', err);
        setError('Failed to remove project from recent list');
      }
    },
    [loadRecentProjects]
  );

  // Clear error
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    // State
    isLoading,
    error,
    showCreateDialog,
    showOpenDialog,
    recentProjects,

    // Actions
    handleCreateProject,
    handleOpenProject,
    handleCreateProjectSubmit,
    handleOpenProjectSubmit,
    handleRecentProjectClick,
    handleRemoveRecentProject,
    setShowCreateDialog,
    setShowOpenDialog,
    clearError,
  };
}

import { useEffect } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import type { PanelSizes } from '@/types';

const LAYOUT_STORAGE_KEY = 'creative-studio-layout';

interface LayoutState {
  panelSizes: PanelSizes;
  showChat: boolean;
  version: string; // for future migrations
}

/**
 * Hook for persisting and restoring layout state to/from localStorage
 */
export function useLayoutPersistence() {
  const { panelSizes, setPanelSizes, showChat, setShowChat } = useAppStore();

  /**
   * Load layout from localStorage on mount
   */
  useEffect(() => {
    try {
      const stored = localStorage.getItem(LAYOUT_STORAGE_KEY);
      if (stored) {
        const layoutState: LayoutState = JSON.parse(stored);

        // Validate and restore panel sizes
        if (layoutState.panelSizes && isValidPanelSizes(layoutState.panelSizes)) {
          setPanelSizes(layoutState.panelSizes);
        }

        // Restore chat visibility
        if (typeof layoutState.showChat === 'boolean') {
          setShowChat(layoutState.showChat);
        }
      }
    } catch (error) {
      console.error('Failed to load layout from localStorage:', error);
      // Clear invalid data
      localStorage.removeItem(LAYOUT_STORAGE_KEY);
    }
  }, []); // Only run on mount

  /**
   * Save layout to localStorage whenever it changes
   */
  useEffect(() => {
    try {
      const layoutState: LayoutState = {
        panelSizes,
        showChat,
        version: '1.0',
      };

      localStorage.setItem(LAYOUT_STORAGE_KEY, JSON.stringify(layoutState));
    } catch (error) {
      console.error('Failed to save layout to localStorage:', error);
    }
  }, [panelSizes, showChat]);

  /**
   * Clear saved layout
   */
  const clearSavedLayout = () => {
    try {
      localStorage.removeItem(LAYOUT_STORAGE_KEY);
    } catch (error) {
      console.error('Failed to clear layout from localStorage:', error);
    }
  };

  /**
   * Check if saved layout exists
   */
  const hasSavedLayout = (): boolean => {
    try {
      return localStorage.getItem(LAYOUT_STORAGE_KEY) !== null;
    } catch (error) {
      return false;
    }
  };

  return {
    clearSavedLayout,
    hasSavedLayout,
  };
}

/**
 * Validate panel sizes object
 */
function isValidPanelSizes(sizes: unknown): sizes is PanelSizes {
  if (!sizes || typeof sizes !== 'object') return false;

  const { assetLibrary, canvas, propertiesOrChat } = sizes;

  // Check if all properties exist and are numbers
  if (
    typeof assetLibrary !== 'number' ||
    typeof canvas !== 'number' ||
    typeof propertiesOrChat !== 'number'
  ) {
    return false;
  }

  // Check if values are within reasonable ranges
  if (
    assetLibrary < 0 ||
    assetLibrary > 100 ||
    canvas < 0 ||
    canvas > 100 ||
    propertiesOrChat < 0 ||
    propertiesOrChat > 100
  ) {
    return false;
  }

  // Check if total is approximately 100 (allow small floating point errors)
  const total = assetLibrary + canvas + propertiesOrChat;
  if (Math.abs(total - 100) > 1) {
    return false;
  }

  return true;
}

