/**
 * useModalState Hook
 *
 * Manages comprehensive modal state including form data, validation errors,
 * loading states, and connection testing status.
 */

import { useState, useCallback, useEffect } from 'react';
import type { ModalState, ModalSchema, ValidationResult } from '@/types/modal';

/**
 * Hook for managing modal state
 */
export function useModalState(schema: ModalSchema, initialData?: Record<string, unknown>) {
  // Initialize form data with defaults from schema
  const initializeFormData = useCallback(() => {
    const data: Record<string, unknown> = {};

    for (const field of schema.fields) {
      data[field.id] = initialData?.[field.id] ?? field.defaultValue ?? '';
    }

    return data;
  }, [schema.fields, initialData]);

  // Modal state
  const [isOpen, setIsOpen] = useState(false);
  const [data, setData] = useState<Record<string, unknown>>(initializeFormData);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState({ submit: false, connectionTest: false });
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  // Reset state when modal opens/closes or schema changes
  useEffect(() => {
    if (isOpen) {
      setData(initializeFormData());
      setErrors({});
      setLoading({ submit: false, connectionTest: false });
      setConnectionStatus('idle');
    }
  }, [isOpen, initializeFormData]);

  // Update field value
  const updateField = useCallback((fieldId: string, value: unknown) => {
    setData(prev => ({ ...prev, [fieldId]: value }));

    // Clear error for this field when user starts typing
    if (errors[fieldId]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[fieldId];
        return newErrors;
      });
    }
  }, [errors]);

  // Update multiple fields
  const updateFields = useCallback((updates: Record<string, unknown>) => {
    setData(prev => ({ ...prev, ...updates }));

    // Clear errors for updated fields
    setErrors(prev => {
      const newErrors = { ...prev };
      for (const fieldId of Object.keys(updates)) {
        delete newErrors[fieldId];
      }
      return newErrors;
    });
  }, []);

  // Set validation errors
  const setValidationErrors = useCallback((validationErrors: Record<string, string>) => {
    setErrors(validationErrors);
  }, []);

  // Set loading state
  const setLoadingState = useCallback((key: keyof ModalState['loading'], value: boolean) => {
    setLoading(prev => ({ ...prev, [key]: value }));
  }, []);

  // Open modal
  const open = useCallback((data?: Record<string, unknown>) => {
    if (data) {
      setData(prev => ({ ...initializeFormData(), ...data }));
    }
    setIsOpen(true);
  }, [initializeFormData]);

  // Close modal
  const close = useCallback(() => {
    setIsOpen(false);
  }, []);

  // Reset form
  const reset = useCallback(() => {
    setData(initializeFormData());
    setErrors({});
    setLoading({ submit: false, connectionTest: false });
    setConnectionStatus('idle');
  }, [initializeFormData]);

  return {
    // State
    isOpen,
    data,
    errors,
    loading,
    connectionStatus,

    // Actions
    open,
    close,
    updateField,
    updateFields,
    setValidationErrors,
    setLoadingState,
    setConnectionStatus,
    reset,
  };
}

/**
 * useModalValidation Hook
 *
 * Provides unified validation logic for modal forms based on schema configuration.
 * Supports built-in validation rules and custom validation functions.
 */

import { useCallback } from 'react';
import type { ModalSchema, ValidationRule, ValidationResult, ValidationContext } from '@/types/modal';

/**
 * Built-in validation functions
 */
const validationRules = {
  required: (value: unknown): boolean => {
    if (typeof value === 'string') return value.trim().length > 0;
    if (typeof value === 'number') return !isNaN(value);
    if (Array.isArray(value)) return value.length > 0;
    return value !== null && value !== undefined;
  },

  minLength: (value: unknown, length: number): boolean => {
    if (typeof value === 'string') return value.length >= length;
    if (Array.isArray(value)) return value.length >= length;
    return false;
  },

  maxLength: (value: unknown, length: number): boolean => {
    if (typeof value === 'string') return value.length <= length;
    if (Array.isArray(value)) return value.length <= length;
    return false;
  },

  pattern: (value: unknown, pattern: string): boolean => {
    if (typeof value !== 'string') return false;
    const regex = new RegExp(pattern);
    return regex.test(value);
  },

  email: (value: unknown): boolean => {
    if (typeof value !== 'string') return false;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(value);
  },

  url: (value: unknown): boolean => {
    if (typeof value !== 'string') return false;
    try {
      new URL(value);
      return true;
    } catch {
      return false;
    }
  },

  custom: (value: unknown, validator: (value: unknown) => boolean): boolean => {
    return validator(value);
  },
};

/**
 * Validate a single field
 */
function validateField(
  field: ModalSchema['fields'][0],
  value: unknown,
  context: ValidationContext
): string | null {
  // Check required validation first
  if (field.required && !validationRules.required(value)) {
    return 'Ce champ est requis';
  }

  // Skip other validations if field is empty and not required
  if (!validationRules.required(value) && !field.required) {
    return null;
  }

  // Apply field-specific validation rules
  if (field.validation) {
    for (const rule of field.validation) {
      const validator = validationRules[rule.type];

      if (!validator) {
        continue; // Unknown validation rule
      }

      let isValid: boolean;

      switch (rule.type) {
        case 'custom':
          isValid = validator(value, rule.value as (value: unknown) => boolean);
          break;
        case 'minLength':
        case 'maxLength':
          isValid = validator(value, rule.value as number);
          break;
        case 'pattern':
          isValid = validator(value, rule.value as string);
          break;
        default:
          isValid = validator(value);
      }

      if (!isValid) {
        return rule.message;
      }
    }
  }

  return null; // No errors
}

/**
 * Hook for form validation
 */
export function useModalValidation(schema: ModalSchema) {
  /**
   * Validate entire form
   */
  const validate = useCallback((data: Record<string, unknown>): ValidationResult => {
    const errors: Record<string, string> = {};
    let isValid = true;

    const context: ValidationContext = {
      data,
      schema,
    };

    for (const field of schema.fields) {
      const error = validateField(field, data[field.id], { ...context, field });

      if (error) {
        errors[field.id] = error;
        isValid = false;
      }
    }

    return { isValid, errors };
  }, [schema]);

  /**
   * Validate single field
   */
  const validateFieldById = useCallback((fieldId: string, value: unknown, data: Record<string, unknown>): string | null => {
    const field = schema.fields.find(f => f.id === fieldId);

    if (!field) {
      return null;
    }

    const context: ValidationContext = {
      data,
      field,
      schema,
    };

    return validateField(field, value, context);
  }, [schema]);

  /**
   * Get validation summary
   */
  const getValidationSummary = useCallback((errors: Record<string, string>): { count: number; fields: string[] } => {
    const fields = Object.keys(errors);
    return {
      count: fields.length,
      fields,
    };
  }, []);

  return {
    validate,
    validateField: validateFieldById,
    getValidationSummary,
  };
}

/**
 * React Hook for Narrative Service
 * 
 * Provides real-time synchronization with NarrativeService
 * using the Observer pattern.
 */

import { useState, useEffect, useCallback } from 'react';
import { NarrativeService } from '@/services/asset-integration/NarrativeService';
import type { NarrativeText } from '@/types/asset-integration';

// Get singleton instance
const narrativeService = NarrativeService.getInstance();

// ============================================================================
// Hook: useNarrative
// ============================================================================

export interface UseNarrativeReturn {
  narrative: NarrativeText | null;
  isLoading: boolean;
  error: Error | null;
  loadNarrative: (path: string) => Promise<void>;
  saveNarrative: (narrative: NarrativeText, path: string) => Promise<void>;
  createNewNarrative: (title: string, type?: NarrativeText['type']) => NarrativeText;
  updateContent: (narrative: NarrativeText, newContent: string) => NarrativeText;
  clearCache: () => void;
}

/**
 * Hook for managing narrative texts with real-time synchronization
 * 
 * @param initialPath - Optional path to load narrative on mount
 * 
 * @example
 * ```typescript
 * function NarrativeEditor() {
 *   const { 
 *     narrative, 
 *     isLoading, 
 *     loadNarrative, 
 *     saveNarrative,
 *     updateContent 
 *   } = useNarrative('/path/to/narrative.txt');
 *   
 *   if (isLoading) return <div>Loading...</div>;
 *   if (!narrative) return <div>No narrative loaded</div>;
 *   
 *   return (
 *     <div>
 *       <h2>{narrative.title}</h2>
 *       <textarea value={narrative.content} />
 *     </div>
 *   );
 * }
 * ```
 */
export function useNarrative(initialPath?: string): UseNarrativeReturn {
  const [narrative, setNarrative] = useState<NarrativeText | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [currentPath, setCurrentPath] = useState<string | null>(initialPath || null);

  // Load initial narrative
  useEffect(() => {
    if (initialPath) {
      loadNarrative(initialPath);
    }
     
    // Only run when initialPath changes - loadNarrative is intentionally excluded
  }, [initialPath]);

  // Subscribe to narrative updates
  useEffect(() => {
    const unsubscribe = narrativeService.subscribeToNarrativeUpdates((path, updatedNarrative) => {
      
      // Update if it's the current narrative
      if (currentPath && path === currentPath) {
        setNarrative(updatedNarrative);
      }
    });

    return unsubscribe;
  }, [currentPath]);

  // Load narrative
  const loadNarrative = useCallback(async (path: string) => {
    try {
      setIsLoading(true);
      setError(null);
      setCurrentPath(path);
      const loadedNarrative = await narrativeService.loadNarrativeText(path);
      setNarrative(loadedNarrative);
    } catch (err) {
      console.error('[useNarrative] Failed to load narrative:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Save narrative
  const saveNarrative = useCallback(async (narrativeToSave: NarrativeText, path: string) => {
    try {
      setIsLoading(true);
      setError(null);
      await narrativeService.saveNarrativeText(narrativeToSave, path);
      setNarrative(narrativeToSave);
      setCurrentPath(path);
    } catch (err) {
      console.error('[useNarrative] Failed to save narrative:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Create new narrative
  const createNewNarrative = useCallback((title: string, type?: NarrativeText['type']): NarrativeText => {
    const newNarrative = narrativeService.createNewNarrative(title, type);
    setNarrative(newNarrative);
    setCurrentPath(null); // New narrative doesn't have a path yet
    return newNarrative;
  }, []);

  // Update content
  const updateContent = useCallback((narrativeToUpdate: NarrativeText, newContent: string): NarrativeText => {
    const updatedNarrative = narrativeService.updateNarrativeContent(narrativeToUpdate, newContent);
    setNarrative(updatedNarrative);
    return updatedNarrative;
  }, []);

  // Clear cache
  const clearCache = useCallback(() => {
    narrativeService.clearCache();
  }, []);

  return {
    narrative,
    isLoading,
    error,
    loadNarrative,
    saveNarrative,
    createNewNarrative,
    updateContent,
    clearCache,
  };
}

// ============================================================================
// Hook: useNarrativeCache
// ============================================================================

export interface UseNarrativeCacheReturn {
  clearCache: () => void;
  cacheCleared: boolean;
}

/**
 * Hook for managing narrative cache
 * 
 * @example
 * ```typescript
 * function CacheManager() {
 *   const { clearCache, cacheCleared } = useNarrativeCache();
 *   
 *   return (
 *     <div>
 *       <button onClick={clearCache}>Clear Cache</button>
 *       {cacheCleared && <p>Cache cleared!</p>}
 *     </div>
 *   );
 * }
 * ```
 */
export function useNarrativeCache(): UseNarrativeCacheReturn {
  const [cacheCleared, setCacheCleared] = useState(false);

  // Subscribe to cache updates
  useEffect(() => {
    const unsubscribe = narrativeService.subscribeToCacheUpdates((cleared) => {
      setCacheCleared(cleared);
      
      // Reset flag after 3 seconds
      if (cleared) {
        setTimeout(() => setCacheCleared(false), 3000);
      }
    });

    return unsubscribe;
  }, []);

  const clearCache = useCallback(() => {
    narrativeService.clearCache();
  }, []);

  return {
    clearCache,
    cacheCleared,
  };
}

// ============================================================================
// Hook: useNarrativeList
// ============================================================================

export interface UseNarrativeListReturn {
  narratives: string[];
  isLoading: boolean;
  error: Error | null;
  refresh: () => Promise<void>;
}

/**
 * Hook for listing available narratives
 * 
 * @example
 * ```typescript
 * function NarrativeList() {
 *   const { narratives, isLoading, refresh } = useNarrativeList();
 *   
 *   if (isLoading) return <div>Loading...</div>;
 *   
 *   return (
 *     <div>
 *       <button onClick={refresh}>Refresh</button>
 *       <ul>
 *         {narratives.map(path => <li key={path}>{path}</li>)}
 *       </ul>
 *     </div>
 *   );
 * }
 * ```
 */
export function useNarrativeList(): UseNarrativeListReturn {
  const [narratives, setNarratives] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const loadNarratives = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const availableNarratives = await narrativeService.listAvailableNarratives();
      setNarratives(availableNarratives);
    } catch (err) {
      console.error('[useNarrativeList] Failed to load narratives:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Load narratives on mount
  useEffect(() => {
    loadNarratives();
  }, [loadNarratives]);

  return {
    narratives,
    isLoading,
    error,
    refresh: loadNarratives,
  };
}

