/**
 * useProgressiveImageLoading Hook
 * 
 * React hook for progressive image loading with automatic state management
 * Provides low-resolution preview first, then progressively loads higher resolutions
 * 
 * Requirements: 13.1, 13.2, 13.3
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { imageLoader, ImageData } from '../services/gridEditor/ImageLoaderService';

export interface ProgressiveImageState {
  currentImage: ImageData | null;
  isLoading: boolean;
  isFullResolution: boolean;
  error: Error | null;
  progress: number; // 0-100
}

export interface UseProgressiveImageLoadingOptions {
  enabled?: boolean;
  zoom?: number; // Current zoom level for mipmap selection
}

/**
 * Hook for loading a single image progressively
 */
export function useProgressiveImageLoading(
  url: string | null,
  options: UseProgressiveImageLoadingOptions = {}
): ProgressiveImageState {
  const { enabled = true, zoom = 1.0 } = options;

  const [state, setState] = useState<ProgressiveImageState>({
    currentImage: null,
    isLoading: false,
    isFullResolution: false,
    error: null,
    progress: 0,
  });

  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!url || !enabled) {
      setState({
        currentImage: null,
        isLoading: false,
        isFullResolution: false,
        error: null,
        progress: 0,
      });
      return;
    }

    // Create abort controller for cleanup
    abortControllerRef.current = new AbortController();
    const abortSignal = abortControllerRef.current.signal;

    setState((prev) => ({
      ...prev,
      isLoading: true,
      error: null,
    }));

    // Load image progressively
    imageLoader
      .loadImageProgressively(url, (imageData) => {
        if (abortSignal.aborted) return;

        const isFullRes = imageData.level === 0;
        const totalLevels = 5; // Approximate number of mipmap levels
        const progress = ((totalLevels - imageData.level) / totalLevels) * 100;

        setState({
          currentImage: imageData,
          isLoading: !isFullRes,
          isFullResolution: isFullRes,
          error: null,
          progress,
        });
      })
      .catch((error) => {
        if (abortSignal.aborted) return;

        setState({
          currentImage: null,
          isLoading: false,
          isFullResolution: false,
          error: error as Error,
          progress: 0,
        });
      });

    // Cleanup
    return () => {
      abortControllerRef.current?.abort();
    };
  }, [url, enabled]);

  return state;
}

/**
 * Hook for loading multiple images progressively
 */
export function useProgressiveImagesLoading(
  urls: string[],
  options: UseProgressiveImageLoadingOptions = {}
): Map<string, ProgressiveImageState> {
  const { enabled = true } = options;

  const [states, setStates] = useState<Map<string, ProgressiveImageState>>(new Map());
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (urls.length === 0 || !enabled) {
      setStates(new Map());
      return;
    }

    // Create abort controller for cleanup
    abortControllerRef.current = new AbortController();
    const abortSignal = abortControllerRef.current.signal;

    // Initialize states for all URLs
    const initialStates = new Map<string, ProgressiveImageState>();
    urls.forEach((url) => {
      initialStates.set(url, {
        currentImage: null,
        isLoading: true,
        isFullResolution: false,
        error: null,
        progress: 0,
      });
    });
    setStates(initialStates);

    // Load all images progressively
    imageLoader
      .loadImagesProgressively(urls, (url, imageData) => {
        if (abortSignal.aborted) return;

        const isFullRes = imageData.level === 0;
        const totalLevels = 5;
        const progress = ((totalLevels - imageData.level) / totalLevels) * 100;

        setStates((prev) => {
          const next = new Map(prev);
          next.set(url, {
            currentImage: imageData,
            isLoading: !isFullRes,
            isFullResolution: isFullRes,
            error: null,
            progress,
          });
          return next;
        });
      })
      .catch((error) => {
        if (abortSignal.aborted) return;

        console.error('Failed to load images progressively:', error);
      });

    // Cleanup
    return () => {
      abortControllerRef.current?.abort();
    };
  }, [urls.join(','), enabled]);

  return states;
}

/**
 * Hook for zoom-aware image loading
 * Automatically selects appropriate mipmap level based on zoom
 */
export function useZoomAwareImageLoading(
  url: string | null,
  zoom: number
): ProgressiveImageState {
  const [state, setState] = useState<ProgressiveImageState>({
    currentImage: null,
    isLoading: false,
    isFullResolution: false,
    error: null,
    progress: 100,
  });

  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!url) {
      setState({
        currentImage: null,
        isLoading: false,
        isFullResolution: false,
        error: null,
        progress: 0,
      });
      return;
    }

    // Create abort controller for cleanup
    abortControllerRef.current = new AbortController();
    const abortSignal = abortControllerRef.current.signal;

    setState((prev) => ({
      ...prev,
      isLoading: true,
      error: null,
    }));

    // Get appropriate mipmap for zoom level
    imageLoader
      .getMipmapForZoom(url, zoom)
      .then((imageData) => {
        if (abortSignal.aborted) return;

        setState({
          currentImage: imageData,
          isLoading: false,
          isFullResolution: imageData.level === 0,
          error: null,
          progress: 100,
        });
      })
      .catch((error) => {
        if (abortSignal.aborted) return;

        setState({
          currentImage: null,
          isLoading: false,
          isFullResolution: false,
          error: error as Error,
          progress: 0,
        });
      });

    // Cleanup
    return () => {
      abortControllerRef.current?.abort();
    };
  }, [url, zoom]);

  return state;
}

/**
 * Hook for preloading images in the background
 */
export function useImagePreloader(
  urls: string[],
  options: { enabled?: boolean; progressive?: boolean } = {}
): {
  isPreloading: boolean;
  preloadedCount: number;
  totalCount: number;
  error: Error | null;
} {
  const { enabled = true, progressive = true } = options;

  const [state, setState] = useState({
    isPreloading: false,
    preloadedCount: 0,
    totalCount: urls.length,
    error: null as Error | null,
  });

  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (urls.length === 0 || !enabled) {
      setState({
        isPreloading: false,
        preloadedCount: 0,
        totalCount: urls.length,
        error: null,
      });
      return;
    }

    // Create abort controller for cleanup
    abortControllerRef.current = new AbortController();
    const abortSignal = abortControllerRef.current.signal;

    setState({
      isPreloading: true,
      preloadedCount: 0,
      totalCount: urls.length,
      error: null,
    });

    const preloadFn = progressive
      ? imageLoader.preloadImagesProgressively.bind(imageLoader)
      : imageLoader.preloadImages.bind(imageLoader);

    let loadedCount = 0;

    const progressCallback = progressive
      ? (url: string, imageData: unknown) => {
          if (abortSignal.aborted) return;
          if (imageData.level === 0) {
            // Only count full-resolution images
            loadedCount++;
            setState((prev) => ({
              ...prev,
              preloadedCount: loadedCount,
            }));
          }
        }
      : undefined;

    preloadFn(urls, progressCallback)
      .then(() => {
        if (abortSignal.aborted) return;

        setState({
          isPreloading: false,
          preloadedCount: urls.length,
          totalCount: urls.length,
          error: null,
        });
      })
      .catch((error) => {
        if (abortSignal.aborted) return;

        setState((prev) => ({
          ...prev,
          isPreloading: false,
          error: error as Error,
        }));
      });

    // Cleanup
    return () => {
      abortControllerRef.current?.abort();
    };
  }, [urls.join(','), enabled, progressive]);

  return state;
}

/**
 * useProjectLoader Hook
 * 
 * Custom hook for loading and managing project data from multiple sources.
 * Orchestrates data loading from file system discovery and recent projects.
 * 
 * Implements Requirements 7.2, 7.3, 7.4
 * Tasks: 7.1, 7.2, 7.3
 */

import { useState, useCallback } from 'react';
import { MergedProject, mergeProjects } from '../utils/projectMerger';
import { RecentProjectsService } from '../services/recentProjects/RecentProjectsService';
import { DiscoveryResult } from '../types/projectDiscovery';

/**
 * Project state interface
 */
export interface ProjectState {
  projects: MergedProject[];
  isLoading: boolean;
  error: string | null;
  lastRefresh: number;
}

/**
 * Hook return type
 */
export interface UseProjectLoaderReturn extends ProjectState {
  loadProjects: () => Promise<void>;
  refreshProjects: () => Promise<void>;
}

// Cache TTL: 30 seconds
const CACHE_TTL = 30000;

/**
 * Custom hook for loading projects from multiple sources
 * 
 * Features:
 * - Loads projects from file system discovery via Electron IPC
 * - Merges with recent projects from localStorage
 * - Implements caching with 30-second TTL
 * - Handles loading states and errors
 * - Provides manual refresh functionality
 * - Gracefully handles IPC unavailability
 * 
 * @returns Project state and loading functions
 */
export function useProjectLoader(): UseProjectLoaderReturn {
  const [state, setState] = useState<ProjectState>({
    projects: [],
    isLoading: true,
    error: null,
    lastRefresh: 0,
  });

  /**
   * Load projects from all sources
   * Implements Task 7.1 (parallel data loading) and Task 7.2 (validation and merging)
   */
  const loadProjects = useCallback(async () => {
    setState(prev => ({ ...prev, isLoading: true, error: null }));
    
    try {
      // Task 7.3: Check cache freshness
      const now = Date.now();
      const cacheAge = now - state.lastRefresh;
      
      if (cacheAge < CACHE_TTL && state.projects.length > 0) {
        console.log(`[useProjectLoader] Using cached data (age: ${cacheAge}ms)`);
        setState(prev => ({ ...prev, isLoading: false }));
        return;
      }

      // Task 7.1: Check for Electron IPC availability
      const hasElectronAPI = typeof window !== 'undefined' && 
                            window.electron?.projectDiscovery?.discoverProjects;

      if (!hasElectronAPI) {
        console.warn('[useProjectLoader] Electron IPC unavailable, showing recent projects only');
        
        // Fallback: Load only recent projects from localStorage
        const recentProjectsService = new RecentProjectsService();
        const recentProjects = recentProjectsService.getRecentProjects();
        
        // Convert recent projects to MergedProject format
        const mergedProjects: MergedProject[] = recentProjects.map(rp => ({
          name: rp.name,
          path: rp.path,
          lastModified: rp.lastModified instanceof Date ? rp.lastModified.getTime() : new Date(rp.lastModified).getTime(),
          isValid: true,
          isRecent: true,
          lastAccessed: rp.lastModified instanceof Date ? rp.lastModified.getTime() : new Date(rp.lastModified).getTime(),
        }));

        setState({
          projects: mergedProjects,
          isLoading: false,
          error: 'Running in browser mode. Showing recent projects only.',
          lastRefresh: now,
        });
        return;
      }

      // Task 7.1: Parallel data loading
      console.log('[useProjectLoader] Loading projects from file system and localStorage');
      
      // Load recent projects from localStorage
      const recentProjectsService = new RecentProjectsService();
      const recentProjects = recentProjectsService.getRecentProjects();
      
      // Discover projects from file system via IPC
      const discoveryResult: DiscoveryResult = await window.electron.projectDiscovery.discoverProjects();
      
      console.log(`[useProjectLoader] Discovered ${discoveryResult.projects.length} projects with ${discoveryResult.errors.length} errors`);

      // Task 7.2: Validate and cleanup recent projects
      const validatedRecent = recentProjectsService.validateAndCleanup(discoveryResult.projects);
      
      console.log(`[useProjectLoader] Validated ${validatedRecent.length} recent projects`);

      // Task 7.2: Merge discovered and recent projects
      const mergedProjects = mergeProjects(discoveryResult.projects, validatedRecent);
      
      console.log(`[useProjectLoader] Merged ${mergedProjects.length} total projects`);

      // Update state with merged projects
      setState({
        projects: mergedProjects,
        isLoading: false,
        error: discoveryResult.errors.length > 0 
          ? `Loaded ${mergedProjects.length} projects with ${discoveryResult.errors.length} errors`
          : null,
        lastRefresh: now,
      });

    } catch (error) {
      console.error('[useProjectLoader] Failed to load projects:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to load projects';
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMessage,
      }));
    }
  }, [state.lastRefresh, state.projects.length]);

  /**
   * Force refresh projects, bypassing cache
   * Implements Task 7.3 (manual refresh)
   */
  const refreshProjects = useCallback(async () => {
    console.log('[useProjectLoader] Manual refresh triggered, bypassing cache');
    
    setState(prev => ({ 
      ...prev, 
      isLoading: true, 
      error: null,
      lastRefresh: 0, // Reset cache timestamp to force reload
    }));
    
    try {
      // Force reload by resetting lastRefresh
      await loadProjects();
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to refresh projects';
      setState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMessage,
      }));
    }
  }, [loadProjects]);

  return {
    ...state,
    loadProjects,
    refreshProjects,
  };
}

