          font-size: 0.875rem;
          font-weight: 500;
          cursor: pointer;
          transition: all 0.2s;
        }

        .wizard-recovery-button--discard {
          background: #f5f5f5;
          color: #666;
        }

        .wizard-recovery-button--discard:hover {
          background: #e5e5e5;
        }

        .wizard-recovery-button--accept {
