/**
 * Wizard Error Handler Hook
 * 
 * Provides error handling utilities for wizards with consistent error recovery.
 */

import { useState, useCallback, useRef } from 'react';
import type { WizardType } from '../../utils/wizardStorage';

export interface WizardErrorInfo {
  error: Error;
  componentStack?: string;
  timestamp: Date;
  wizardType: WizardType;
}

export interface WizardErrorHandlerResult {
  error: WizardErrorInfo | null;
  hasError: boolean;
  dataExported: boolean;
  setError: (error: Error, componentStack?: string) => void;
  clearError: () => void;
  exportOnError: () => void;
  getErrorMessage: () => string;
  getErrorDescription: () => string;
}

export function useWizardErrorHandler(wizardType: WizardType): WizardErrorHandlerResult {
  const [error, setErrorState] = useState<WizardErrorInfo | null>(null);
  const [dataExported, setDataExported] = useState(false);
  const wizardTypeRef = useRef(wizardType);
  
  // Update ref when wizardType changes
  wizardTypeRef.current = wizardType;

  const setError = useCallback((err: Error, componentStack?: string) => {
    const errorInfo: WizardErrorInfo = {
      error: err,
      componentStack,
      timestamp: new Date(),
      wizardType: wizardTypeRef.current,
    };
    setErrorState(errorInfo);
    
    // Auto-export data
    try {
      // emergencyExportWizardState(wizardTypeRef.current, err);
      setDataExported(true);
    } catch (exportError) {
      console.error('Failed to export wizard data:', exportError);
    }
  }, []);

  const clearError = useCallback(() => {
    setErrorState(null);
    setDataExported(false);
  }, []);

  const exportOnError = useCallback(() => {
    if (error) {
      try {
        // emergencyExportWizardState(error.wizardType, error.error);
        setDataExported(true);
      } catch (err) {
        console.error('Failed to export wizard data:', err);
      }
    }
  }, [error]);

  const getErrorMessage = useCallback(() => {
    if (!error) return '';
    return error.error.message || 'An unexpected error occurred';
  }, [error]);

  const getErrorDescription = useCallback(() => {
    if (!error) return '';
    
    const message = error.error.message || '';
    
    if (message.includes('network') || message.includes('fetch')) {
      return 'Unable to connect to the server. Please check your internet connection and try again.';
    }
    if (message.includes('timeout')) {
      return 'The operation timed out. Please try again.';
    }
    if (message.includes('validation')) {
      return 'There was an issue with the data you entered. Please review your input and try again.';
    }
    if (message.includes('permission') || message.includes('access')) {
      return 'You do not have permission to perform this action. Please check your access rights.';
    }
    if (message.includes('storage') || message.includes('localStorage')) {
      return 'There was an issue saving your progress.';
    }
    
    return 'Something went wrong while processing your request. Please try again.';
  }, [error]);

  return {
    error,
    hasError: error !== null,
    dataExported,
    setError,
    clearError,
    exportOnError,
    getErrorMessage,
    getErrorDescription,
  };
}

export interface ErrorRecoveryOption {
  label: string;
  action: () => void;
  variant?: 'default' | 'destructive' | 'outline';
}

export interface WizardErrorRecoveryProps {
  error: WizardErrorInfo | null;
  dataExported: boolean;
  onRetry: () => void;
  onReload: () => void;
  onExport?: () => void;
  customOptions?: ErrorRecoveryOption[];
}

export function getDefaultRecoveryOptions(
  dataExported: boolean,
  onRetry: () => void,
  onReload: () => void,
  onExport?: () => void
): ErrorRecoveryOption[] {
  const options: ErrorRecoveryOption[] = [
    {
      label: 'Try Again',
      action: onRetry,
      variant: 'default',
    },
    {
      label: 'Reload Page',
      action: onReload,
      variant: 'outline',
    },
  ];

  if (!dataExported && onExport) {
    options.push({
      label: 'Export Data',
      action: onExport,
      variant: 'outline',
    });
  }

  return options;
}

/**
 * useWizardVoiceAssistant
 * ========================
 * Hook React pour les commandes vocales/textuelles contextuelles dans les wizards.
 *
 * S'intègre avec :
 *   - WizardContext (updateFormData)
 *   - WizardFieldIntelligence (parsing sémantique)
 *   - useLLMGeneration (génération IA des sections)
 *
 * Usage dans un step de wizard :
 *
 *   // Dans CharacterWizard.tsx ou step individuel :
 *   const assistant = useWizardVoiceAssistant({
 *     entityType: 'character',
 *     onPatchApplied: (patch) => console.log('Appliqué :', patch),
 *     onTabChange: (tabId) => setActiveStep(tabId),
 *   });
 *
 *   // Depuis un transcript vocal ou texte saisi :
 *   assistant.handleCommand("Mets les yeux en vert");
 *   assistant.handleCommand("Remplis les champs manquants");
 *   assistant.handleCommand("Génère un physique cohérent");
 */

import { useState, useCallback, useRef } from 'react';
import {
  WizardFieldIntelligence,
  WizardCommandIntent,
  WizardEntityType,
  FieldPatch,
} from '@/services/WizardFieldIntelligence';
import { useVoiceInput } from './useAddonVoiceCommands';

// ============================================================================
// TYPES
// ============================================================================

export interface WizardVoiceAssistantOptions {
  /** Type d'entité éditée dans ce wizard */
  entityType: WizardEntityType;

  /** Fonction pour mettre à jour le formData du wizard */
  onFieldChange: (section: string | null, field: string, value: unknown) => void;

  /** Callback quand une navigation d'onglet est demandée */
  onTabChange?: (tabId: string) => void;

  /** Callback quand une génération IA est demandée */
  onGenerateSection?: (sectionName: string, prompt: string) => void;

  /** Callback quand l'utilisateur demande de remplir les champs vides */
  onFillMissing?: () => void;

  /** Callback quand un patch est appliqué (pour feedback) */
  onPatchApplied?: (patch: FieldPatch) => void;

  /** Callback erreur */
  onError?: (message: string) => void;
}

export interface WizardCommandFeedback {
  type: 'success' | 'warning' | 'error' | 'info';
  message: string;
  patches?: FieldPatch[];
  timestamp: number;
}

export interface UseWizardVoiceAssistantReturn {
  /** Traite une commande (texte ou vocal) */
  handleCommand: (transcript: string, confidence?: number) => WizardCommandIntent;

  /** Feedback de la dernière commande */
  lastFeedback: WizardCommandFeedback | null;

  /** Historique des commandes appliquées */
  commandHistory: WizardCommandFeedback[];

  /** Écoute vocale */
  isListening: boolean;
  isVoiceSupported: boolean;
  transcript: string;
  startListening: () => void;
  stopListening: () => void;
  toggleListening: () => void;

  /** Suggestions contextuelles */
  suggestions: string[];

  /** Reset le feedback */
  clearFeedback: () => void;
}

// ============================================================================
// HOOK
// ============================================================================

export function useWizardVoiceAssistant(
  options: WizardVoiceAssistantOptions,
): UseWizardVoiceAssistantReturn {
  const {
    entityType,
    onFieldChange,
    onTabChange,
    onGenerateSection,
    onFillMissing,
    onPatchApplied,
    onError,
  } = options;

  const [lastFeedback, setLastFeedback] = useState<WizardCommandFeedback | null>(null);
  const [commandHistory, setCommandHistory] = useState<WizardCommandFeedback[]>([]);
  const feedbackTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ── Traitement d'une commande ─────────────────────────────────────────────

  const handleCommand = useCallback(
    (transcript: string, _confidence = 1.0): WizardCommandIntent => {
      if (!transcript.trim()) {
        return { action: 'unknown', entityType, patches: [], confidence: 0, rawTranscript: '' };
      }

      const intent = WizardFieldIntelligence.parseCommand(transcript, entityType);

      let feedback: WizardCommandFeedback;

      switch (intent.action) {

        // ── Patch de champs ──────────────────────────────────────────────
        case 'set_field': {
          if (intent.patches.length === 0) {
            feedback = { type: 'warning', message: `Champ non reconnu : "${transcript}"`, timestamp: Date.now() };
            break;
          }

          const applied: FieldPatch[] = [];
          const skipped: string[] = [];

          for (const patch of intent.patches) {
            if (patch.confidence >= 0.5) {
              onFieldChange(patch.section, patch.field, patch.value);
              onPatchApplied?.(patch);
              applied.push(patch);
            } else {
              skipped.push(patch.explanation);
            }
          }

          if (applied.length > 0) {
            const lines = applied.map(p => `✓ ${p.explanation}`).join('\n');
            feedback = {
              type: 'success',
              message: applied.length === 1
                ? `✅ ${applied[0].explanation}`
                : `✅ ${applied.length} champs mis à jour :\n${lines}`,
              patches: applied,
              timestamp: Date.now(),
            };
          } else {
            feedback = {
              type: 'warning',
              message: `Confiance insuffisante pour appliquer : ${skipped.join(', ')}`,
              timestamp: Date.now(),
            };
          }
          break;
        }

        // ── Génération IA ────────────────────────────────────────────────
        case 'generate_section': {
          const section = intent.sectionToGenerate ?? 'current';
          const prompt = intent.generationPrompt ?? 'Génère une suggestion cohérente.';
          onGenerateSection?.(section, prompt);
          feedback = {
            type: 'info',
            message: `🤖 Génération IA demandée pour : ${section}`,
            timestamp: Date.now(),
          };
          break;
        }

        // ── Remplir les champs vides ─────────────────────────────────────
        case 'fill_missing': {
          onFillMissing?.();
          feedback = {
            type: 'info',
            message: `✨ Remplissage intelligent des champs vides…`,
            timestamp: Date.now(),
          };
          break;
        }

        // ── Navigation onglet ────────────────────────────────────────────
        case 'navigate_tab': {
          if (intent.targetTab) {
            onTabChange?.(intent.targetTab);
            feedback = {
              type: 'success',
              message: `📑 Navigation vers : ${intent.targetTab}`,
              timestamp: Date.now(),
            };
          } else {
            feedback = { type: 'warning', message: 'Onglet non trouvé', timestamp: Date.now() };
          }
          break;
        }

        // ── Inconnu ──────────────────────────────────────────────────────
        default: {
          const suggestions = WizardFieldIntelligence.getSuggestionsFor(entityType);
          feedback = {
            type: 'warning',
            message: `❓ Commande non reconnue : "${transcript}"\nExemples : ${suggestions.slice(0, 3).join(' • ')}`,
            timestamp: Date.now(),
          };
          onError?.(`Commande non reconnue : "${transcript}"`);
          break;
        }
      }

      setLastFeedback(feedback);
      setCommandHistory(prev => [feedback, ...prev].slice(0, 20));

      // Auto-clear feedback après 4s
      if (feedbackTimerRef.current) clearTimeout(feedbackTimerRef.current);
      feedbackTimerRef.current = setTimeout(() => setLastFeedback(null), 4000);

      return intent;
    },
    [entityType, onFieldChange, onTabChange, onGenerateSection, onFillMissing, onPatchApplied, onError],
  );

  // ── Écoute vocale ─────────────────────────────────────────────────────────

  const { isListening, isSupported, transcript, startListening, stopListening, toggleListening } = useVoiceInput({
    onCommand: (result) => {
      if (result.handled) return; // déjà géré par l'addon router
    },
    onTranscriptChange: (t) => {
      if (t && t.length > 3) {
        // Traitement interactif pendant la dictée (transcript intermédiaire)
        // On attend le final pour appliquer
      }
    },
  });

  // Intercepter le transcript final pour l'envoyer au wizard
  // (Le useVoiceInput appelle onCommand avec le résultat routé,
  //  mais on veut aussi traiter localement pour le wizard)
  // On se branche sur les events de reconnaissance vocale

  // ── Suggestions ───────────────────────────────────────────────────────────

  const suggestions = WizardFieldIntelligence.getSuggestionsFor(entityType);

  const clearFeedback = useCallback(() => setLastFeedback(null), []);

  return {
    handleCommand,
    lastFeedback,
    commandHistory,
    isListening,
    isVoiceSupported: isSupported,
    transcript,
    startListening,
    stopListening,
    toggleListening,
    suggestions,
    clearFeedback,
  };
}

/**
 * useWorkerPool - Hook React pour utiliser le WorkerPool
 * 
 * Ce hook fournit une interface simple pour exécuter des tâches
 * dans un pool de Web Workers avec gestion automatique du cycle de vie.
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import { WorkerPool } from '../utils/workers/WorkerPool';

export interface WorkerPoolStats {
  queueSize: number;
  availableWorkers: number;
  busyWorkers: number;
  totalWorkers: number;
}

export interface UseWorkerPoolOptions {
  poolSize?: number;
  workerUrl?: string;
}

export interface UseWorkerPoolReturn {
  execute: <T, R>(type: string, data: T, priority?: number) => Promise<R>;
  cancel: (taskId: string) => boolean;
  cancelAll: () => void;
  stats: WorkerPoolStats;
  isReady: boolean;
}

/**
 * Hook pour utiliser un pool de Web Workers
 * 
 * @param options - Options de configuration du pool
 * @returns Interface pour exécuter des tâches et gérer le pool
 * 
 * @example
 * ```tsx
 * const { execute, stats, cancelAll } = useWorkerPool({ poolSize: 4 });
 * 
 * const handleGenerateThumbnail = async () => {
 *   try {
 *     const blob = await execute('generateThumbnail', {
 *       videoUrl: 'video.mp4',
 *       time: 5.0
 *     });
 *     // Utiliser le blob
 *   } catch (error) {
 *     console.error('Failed to generate thumbnail:', error);
 *   }
 * };
 * ```
 */
export function useWorkerPool(options: UseWorkerPoolOptions = {}): UseWorkerPoolReturn {
  const poolRef = useRef<WorkerPool | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [stats, setStats] = useState<WorkerPoolStats>({
    queueSize: 0,
    availableWorkers: 0,
    busyWorkers: 0,
    totalWorkers: 0
  });

  // Initialiser le pool
  useEffect(() => {
    const pool = new WorkerPool(options.poolSize, options.workerUrl);
    poolRef.current = pool;
    setIsReady(true);

    // Mettre à jour les stats initiales
    updateStats();

    // Nettoyer à la destruction
    return () => {
      if (poolRef.current) {
        poolRef.current.terminate();
        poolRef.current = null;
      }
      setIsReady(false);
    };
  }, [options.poolSize, options.workerUrl]);

  // Mettre à jour les statistiques
  const updateStats = useCallback(() => {
    if (poolRef.current) {
      setStats({
        queueSize: poolRef.current.getQueueSize(),
        availableWorkers: poolRef.current.getAvailableWorkers(),
        busyWorkers: poolRef.current.getBusyWorkers(),
        totalWorkers: poolRef.current.size
      });
    }
  }, []);

  // Exécuter une tâche
  const execute = useCallback(async <T, R>(
    type: string,
    data: T,
    priority: number = 0
  ): Promise<R> => {
    if (!poolRef.current) {
      throw new Error('WorkerPool not initialized');
    }

    updateStats();

    try {
      const result = await poolRef.current.execute<T, R>(type, data, priority);
      updateStats();
      return result;
    } catch (error) {
      updateStats();
      throw error;
    }
  }, [updateStats]);

  // Annuler une tâche spécifique
  const cancel = useCallback((taskId: string): boolean => {
    if (!poolRef.current) {
      return false;
    }

    const result = poolRef.current.cancel(taskId);
    updateStats();
    return result;
  }, [updateStats]);

  // Annuler toutes les tâches
  const cancelAll = useCallback(() => {
    if (poolRef.current) {
      poolRef.current.cancelAll();
      updateStats();
    }
  }, [updateStats]);

  return {
    execute,
    cancel,
    cancelAll,
    stats,
    isReady
  };
}

/**
 * Hook pour exécuter une tâche unique dans un worker
 * 
 * @param type - Type de tâche à exécuter
 * @param data - Données à traiter
 * @param options - Options d'exécution
 * @returns État de l'exécution et résultat
 * 
 * @example
 * ```tsx
 * const { result, loading, error } = useWorkerTask('generateThumbnail', {
 *   videoUrl: 'video.mp4',
 *   time: 5.0
 * });
 * ```
 */
export function useWorkerTask<T, R>(
  type: string,
  data: T,
  options: { enabled?: boolean; priority?: number } = {}
) {
  const { enabled = true, priority = 0 } = options;
  const { execute } = useWorkerPool();
  const [result, setResult] = useState<R | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    let cancelled = false;

    const runTask = async () => {
      setLoading(true);
      setError(null);

      try {
        const taskResult = await execute<T, R>(type, data, priority);
        if (!cancelled) {
          setResult(taskResult);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err as Error);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    runTask();

    return () => {
      cancelled = true;
    };
  }, [type, JSON.stringify(data), enabled, priority, execute]);

  return { result, loading, error };
}

import { useEffect, useCallback } from 'react';
import { useStore } from '@/store';
import { useEditorStore } from '@/stores/editorStore';
import type { World } from '@/types/world';
import { toast } from '@/hooks/use-toast';

// ============================================================================
// World Persistence Hook
// ============================================================================

/**
 * Save a world to the project directory
 * Uses Electron API if available, otherwise falls back to file picker
 */
async function saveWorldToProjectDirectory(world: World, projectPath: string): Promise<void> {
  console.log('[useWorldPersistence] ============================================');
  console.log('[useWorldPersistence] Starting save to project directory...');
  console.log('[useWorldPersistence] projectPath:', projectPath);
  console.log('[useWorldPersistence] world.id:', world.id);
  console.log('[useWorldPersistence] world.name:', world.name);

  // Check if Electron API is available
  if (!window.electronAPI) {
    console.error('[useWorldPersistence] ERROR: Electron API not available');
    console.error('[useWorldPersistence] This function requires Electron to be running');
    throw new Error('Electron API not available - please run the application in Electron mode');
  }

  if (!window.electronAPI.fs) {
    console.error('[useWorldPersistence] ERROR: Electron FS API not available');
    throw new Error('Electron file system API not available');
  }

  const worldsDir = `${projectPath}/worlds`;
  const fileName = `world_${world.id}.json`;
  const filePath = `${worldsDir}/${fileName}`;

  console.log('[useWorldPersistence] Target file path:', filePath);
  console.log('[useWorldPersistence] Directory will be:', worldsDir);

  try {
    // Create worlds directory if it doesn't exist
    console.log('[useWorldPersistence] Ensuring worlds directory exists...');
    if (window.electronAPI.fs.mkdir) {
      try {
        console.log('[useWorldPersistence] Creating directory with recursive option...');
        await window.electronAPI.fs.mkdir(worldsDir, { recursive: true });
        console.log('[useWorldPersistence] ✓ Worlds directory created/verified successfully');
      } catch (mkdirError) {
        console.error('[useWorldPersistence] ERROR creating directory:', mkdirError);
        console.warn('[useWorldPersistence] Continuing despite mkdir error...');
      }
    } else {
      console.warn('[useWorldPersistence] WARN: mkdir function not available');
    }

    // Prepare world data for saving
    const worldData = {
      ...world,
      createdAt: typeof world.createdAt === 'number' ? world.createdAt : new Date(world.createdAt).getTime(),
      updatedAt: Date.now(),
      creation_timestamp: typeof world.createdAt === 'number' ? new Date(world.createdAt).toISOString() : String(world.createdAt),
    };

    console.log('[useWorldPersistence] World data prepared, size:', JSON.stringify(worldData).length, 'bytes');

    // Write world file
    console.log('[useWorldPersistence] Writing world file...');

    if (window.electronAPI.fs.writeFile) {
      try {
        const jsonContent = JSON.stringify(worldData, null, 2);
        console.log('[useWorldPersistence] JSON content length:', jsonContent.length, 'chars');

        await window.electronAPI.fs.writeFile(filePath, jsonContent);
        console.log('[useWorldPersistence] ✓ World file written successfully to:', filePath);
      } catch (writeError) {
        console.error('[useWorldPersistence] ERROR writing world file:', writeError);
        console.error('[useWorldPersistence] File path:', filePath);
        throw writeError;
      }
    } else {
      console.error('[useWorldPersistence] ERROR: writeFile function not available');
      throw new Error('writeFile function not available');
    }

    // Verify the file was created
    if (window.electronAPI.fs.exists) {
      try {
        const exists = await window.electronAPI.fs.exists(filePath);
        console.log('[useWorldPersistence] File exists check:', exists);
        if (!exists) {
          console.warn('[useWorldPersistence] WARN: File was not created despite no errors');
          console.warn('[useWorldPersistence] This might indicate a permission issue');
        } else {
          console.log('[useWorldPersistence] ✓ File verified on disk');
        }
      } catch (existsError) {
        console.warn('[useWorldPersistence] Could not verify file creation:', existsError);
      }
    }

    console.log(`[useWorldPersistence] ✓ World saved successfully to: ${filePath}`);
    console.log('[useWorldPersistence] ============================================');
  } catch (error) {
    console.error('[useWorldPersistence] ============================================');
    console.error('[useWorldPersistence] FAILED to save world to project directory');
    console.error('[useWorldPersistence] Error:', error);
    console.error('[useWorldPersistence] Project path:', projectPath);
    console.error('[useWorldPersistence] World ID:', world.id);
    console.error('[useWorldPersistence] World name:', world.name);
    console.error('[useWorldPersistence] ============================================');
    throw error;
  }
}

/**
 * Load all worlds from the project directory
 */
async function loadWorldsFromProjectDirectory(projectPath: string): Promise<World[]> {
  if (!window.electronAPI?.fs?.readdir) {
    throw new Error('Electron file system API not available');
  }

  const worldsDir = `${projectPath}/worlds`;
  const worlds: World[] = [];

  try {
    // Check if directory exists
    try {
      if (window.electronAPI.fs.exists) {
        const exists = await window.electronAPI.fs.exists(worldsDir);
        if (!exists) {
          // Directory doesn't exist, return empty array
          return worlds;
        }
      }
    } catch {
      // Directory doesn't exist, return empty array
      return worlds;
    }

    // Read directory contents
    const files = await window.electronAPI.fs.readdir(worldsDir);

    // Filter for world files
    const worldFiles = files.filter((file: string) =>
      file.startsWith('world_') && file.endsWith('.json')
    );

    console.log(`[useWorldPersistence] Found ${worldFiles.length} world files in project`);

    // Load each world file
    for (const file of worldFiles) {
      try {
        const filePath = `${worldsDir}/${file}`;
        // Read file (returns Uint8Array/Buffer via IPC)
        const rawContent = await window.electronAPI.fs.readFile(filePath);

        let contentString = '';

        // Handle Buffer/Uint8Array from Electron IPC
        if (typeof rawContent !== 'string') {
          try {
            // TextDecoder handles Uint8Array and ArrayBuffer
            contentString = new TextDecoder('utf-8').decode(rawContent as any);
          } catch (e) {
            console.warn(`[useWorldPersistence] Failed to decode content for ${file}, trying string conversion`, e);
            contentString = String(rawContent);
          }
        } else {
          contentString = rawContent;
        }

        const worldData = JSON.parse(contentString.trim());

        // Validate and convert dates to timestamps (number)
        const world: World = {
          ...worldData,
          createdAt: typeof worldData.createdAt === 'number' ? worldData.createdAt : new Date(worldData.createdAt).getTime(),
          updatedAt: typeof worldData.updatedAt === 'number' ? worldData.updatedAt : new Date(worldData.updatedAt).getTime(),
        };

        worlds.push(world);
      } catch (error) {
        console.error(`[useWorldPersistence] Failed to load world from ${file}:`, error);
      }
    }

    return worlds;
  } catch (error) {
    console.error('[useWorldPersistence] Failed to load worlds from project directory:', error);
    return worlds;
  }
}

/**
 * Delete a world from the project directory
 */
async function deleteWorldFromProjectDirectory(worldId: string, projectPath: string): Promise<void> {
  if (!window.electronAPI?.fs?.unlink) {
    throw new Error('Electron file system API not available');
  }

  const filePath = `${projectPath}/worlds/world_${worldId}.json`;

  try {
    await window.electronAPI.fs.unlink(filePath);
    console.log(`[useWorldPersistence] World deleted: ${filePath}`);
  } catch (error) {
    console.error('[useWorldPersistence] Failed to delete world file:', error);
    throw error;
  }
}

/**
 * Hook to load and persist worlds from/to localStorage and project directory
 * Automatically loads worlds when project changes and saves to project directory
 */
export function useWorldPersistence() {
  const project = useStore((state) => state.project);
  const worlds = useStore((state) => state.worlds);
  const addWorld = useStore((state) => state.addWorld);
  const updateWorld = useStore((state) => state.updateWorld);
  const removeWorld = useStore((state) => state.deleteWorld);
  const projectPath = useEditorStore((state) => state.projectPath);

  /**
   * Save a world to localStorage and project directory
   */
  const saveWorld = useCallback(async (world: World): Promise<void> => {
    console.log('[useWorldPersistence] saveWorld called for:', world.name);
    console.log('[useWorldPersistence] projectPath:', projectPath);
    console.log('[useWorldPersistence] project:', project ? project.project_name : 'null');

    let localStorageSuccess = false;
    let projectDirectorySuccess = false;
    const errorMessages: string[] = [];

    // Save to localStorage
    if (project) {
      const storageKey = `project-${project.project_name}-worlds`;
      try {
        const existingWorlds = JSON.parse(localStorage.getItem(storageKey) || '[]');
        const worldIndex = existingWorlds.findIndex((w: World) => w.id === world.id);

        const worldData = {
          ...world,
          createdAt: typeof world.createdAt === 'number' ? world.createdAt : new Date(world.createdAt).getTime(),
          updatedAt: Date.now(),
          creation_timestamp: typeof world.createdAt === 'number' ? new Date(world.createdAt).toISOString() : String(world.createdAt),
        };

        if (worldIndex >= 0) {
          existingWorlds[worldIndex] = worldData;
        } else {
          existingWorlds.push(worldData);
        }

        localStorage.setItem(storageKey, JSON.stringify(existingWorlds));
        localStorageSuccess = true;
        console.log('[useWorldPersistence] World saved to localStorage successfully');
      } catch (error) {
        const errorMsg = 'Failed to save world to localStorage';
        console.error('[useWorldPersistence]', errorMsg, error);
        errorMessages.push(errorMsg);
      }
    } else {
      console.warn('[useWorldPersistence] No project in store, localStorage save skipped');
    }

    // Save to project directory if available
    if (projectPath) {
      console.log('[useWorldPersistence] Attempting to save to project directory...');
      console.log('[useWorldPersistence] Target path:', `${projectPath}/worlds/world_${world.id}.json`);

      // Verify Electron API availability
      if (!window.electronAPI) {
        const errorMsg = 'Electron API not available - cannot save to project folder';
        console.error('[useWorldPersistence]', errorMsg);
        errorMessages.push(errorMsg + '. Please run the application in Electron mode.');

        toast({
          title: 'Save Warning',
          description: errorMsg,
          variant: 'warning',
        });
      } else {
        try {
          await saveWorldToProjectDirectory(world, projectPath);
          projectDirectorySuccess = true;
          console.log('[useWorldPersistence] World saved to project directory successfully');

          toast({
            title: 'World Saved',
            description: `World "${world.name}" saved to: ${projectPath}/worlds/`,
          });
        } catch (error) {
          const errorMsg = `Failed to save to project folder: ${error instanceof Error ? error.message : 'Unknown error'}`;
          console.warn('[useWorldPersistence] Project directory save failed:', error);
          errorMessages.push(errorMsg);

          toast({
            title: 'Save Failed',
            description: errorMsg,
            variant: 'destructive',
          });
        }
      }
    } else {
      console.warn('[useWorldPersistence] No project path available');
      console.warn('[useWorldPersistence] NOTE: To save to project folder, open or create a project first');

      // Show helpful message when no project is open
      toast({
        title: 'No Project Open',
        description: 'World saved to localStorage. Open a project to save to disk.',
        variant: 'warning',
      });
    }

    // Summary
    console.log('[useWorldPersistence] Save summary:', {
      localStorage: localStorageSuccess ? 'success' : 'failed/skipped',
      projectDirectory: projectDirectorySuccess ? 'success' : 'failed/skipped',
      errors: errorMessages,
    });

    // Throw error if nothing was saved
    if (!localStorageSuccess && !projectDirectorySuccess) {
      throw new Error('World could not be saved anywhere. Check console for details.');
    }
  }, [project, projectPath]);

  /**
   * Delete a world from localStorage and project directory
   */
  const deleteWorld = useCallback(async (worldId: string): Promise<void> => {
    // Remove from localStorage
    if (project) {
      const storageKey = `project-${project.project_name}-worlds`;
      try {
        const existingWorlds = JSON.parse(localStorage.getItem(storageKey) || '[]');
        const updatedWorlds = existingWorlds.filter((w: World) => w.id !== worldId);
        localStorage.setItem(storageKey, JSON.stringify(updatedWorlds));
      } catch (error) {
        console.error('Failed to remove world from localStorage:', error);
      }
    }

    // Remove from project directory if available
    if (projectPath) {
      try {
        await deleteWorldFromProjectDirectory(worldId, projectPath);
      } catch (error) {
        console.warn('[useWorldPersistence] Failed to delete from project directory:', error);
      }
    }

    // Remove from store
    removeWorld(worldId);
  }, [project, projectPath, removeWorld]);

  /**
   * Sync worlds from project directory to store
   */
  const syncWorldsFromProject = useCallback(async (): Promise<{ loaded: number; errors: number }> => {
    if (!projectPath) {
      console.log('[useWorldPersistence] No project path available for sync');
      return { loaded: 0, errors: 0 };
    }

    let loaded = 0;
    let errors = 0;

    try {
      const worlds = await loadWorldsFromProjectDirectory(projectPath);

      for (const world of worlds) {
        try {
          // Check if world already exists in store
          const existingWorlds = useStore.getState().worlds;
          const existingIndex = existingWorlds.findIndex((w) => w.id === world.id);

          if (existingIndex >= 0) {
            // Update existing world
            updateWorld(world.id, world);
          } else {
            // Add new world
            addWorld(world);
          }

          // Also save to localStorage
          if (project) {
            const storageKey = `project-${project.project_name}-worlds`;
            const existingWorldsStorage = JSON.parse(localStorage.getItem(storageKey) || '[]');
            const worldIndex = existingWorldsStorage.findIndex((w: World) => w.id === world.id);
            const worldData = {
              ...world,
              createdAt: typeof world.createdAt === 'number' ? world.createdAt : new Date(world.createdAt).getTime(),
              updatedAt: Date.now(),
              creation_timestamp: typeof world.createdAt === 'number' ? new Date(world.createdAt).toISOString() : String(world.createdAt),
            };

            if (worldIndex >= 0) {
              existingWorldsStorage[worldIndex] = worldData;
            } else {
              existingWorldsStorage.push(worldData);
            }
            localStorage.setItem(storageKey, JSON.stringify(existingWorldsStorage));
          }

          loaded++;
        } catch (error) {
          console.error(`[useWorldPersistence] Failed to sync world ${world.id}:`, error);
          errors++;
        }
      }

      if (loaded > 0) {
        toast({
          title: 'Worlds Synchronized',
          description: `Loaded ${loaded} world${loaded > 1 ? 's' : ''} from project directory`,
        });
      }

      return { loaded, errors };
    } catch (error) {
      console.error('[useWorldPersistence] Failed to sync worlds from project:', error);
      return { loaded, errors };
    }
  }, [projectPath, project, addWorld, updateWorld]);

  // Load worlds from localStorage when project changes
  useEffect(() => {
    if (!project) {
      return;
    }

    const storageKey = `project-${project.project_name}-worlds`;

    try {
      const storedWorlds = localStorage.getItem(storageKey);

      if (storedWorlds) {
        const parsedWorlds: World[] = JSON.parse(storedWorlds);

        // Ensure timestamps are numbers
        const worldsWithDates = parsedWorlds.map((world) => ({
          ...world,
          createdAt: typeof world.createdAt === 'number' ? world.createdAt : new Date(world.createdAt).getTime(),
          updatedAt: typeof world.updatedAt === 'number' ? world.updatedAt : new Date(world.updatedAt).getTime(),
        }));

        console.log(`[useWorldPersistence] Loaded ${worldsWithDates.length} worlds from localStorage`);

        // Only load if store doesn't already have these worlds
        if (worlds.length === 0) {
          worldsWithDates.forEach((world) => {
            addWorld(world);
          });
        }
      }
    } catch (error) {
      console.error('Failed to load worlds from localStorage:', error);
    }
     
    // Only re-run when project name changes - worlds/addWorld should not trigger reload
  }, [project?.project_name]);

  // Auto-sync from project directory when projectPath changes
  useEffect(() => {
    if (projectPath && project) {
      console.log('[useWorldPersistence] Project path changed, syncing worlds...');
      syncWorldsFromProject();
    }
     
    // syncWorldsFromProject is a callback - only run when project path/name changes
  }, [projectPath, project?.project_name]);

  return {
    worlds,
    project,
    saveWorld,
    deleteWorld,
    syncWorldsFromProject,
  };
}

/**
 * Hook to export worlds to JSON
 */
export function useWorldExport() {
  const worlds = useStore((state) => state.worlds);

  const exportWorlds = () => {
    const dataStr = JSON.stringify(worlds, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);

    const link = document.createElement('a');
    link.href = url;
    link.download = `worlds-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const exportWorld = (worldId: string) => {
    const world = worlds.find((w) => w.id === worldId);
    if (!world) {
      console.error('World not found:', worldId);
      return;
    }

    const dataStr = JSON.stringify(world, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);

    const link = document.createElement('a');
    link.href = url;
    link.download = `world-${world.name.toLowerCase().replace(/\s+/g, '-')}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return {
    exportWorlds,
    exportWorld,
  };
}

/**
 * Hook to import worlds from JSON
 */
export function useWorldImport() {
  const addWorld = useStore((state) => state.addWorld);

  const importWorlds = (file: File): Promise<void> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (e) => {
        try {
          const content = e.target?.result as string;
          const data = JSON.parse(content);

          // Handle both single world and array of worlds
          const worldsToImport: World[] = Array.isArray(data) ? data : [data];

          worldsToImport.forEach((world) => {
            // Generate new ID to avoid conflicts
            const importedWorld: World = {
              ...world,
              id: crypto.randomUUID(),
              createdAt: typeof world.createdAt === 'number' ? world.createdAt : (world.createdAt ? new Date(world.createdAt).getTime() : Date.now()),
              updatedAt: Date.now(),
            };

            addWorld(importedWorld);
          });

          resolve();
        } catch (error) {
          reject(new Error('Failed to parse world data: ' + (error as Error).message));
        }
      };

      reader.onerror = () => {
        reject(new Error('Failed to read file'));
      };

      reader.readAsText(file);
    });
  };

  return {
    importWorlds,
  };
}

/**
 * Hook to clear all worlds (with confirmation)
 */
export function useWorldClear() {
  const project = useStore((state) => state.project);
  const worlds = useStore((state) => state.worlds);
  const deleteWorld = useStore((state) => state.deleteWorld);

  const clearAllWorlds = () => {
    if (!project) {
      return;
    }

    // Delete all worlds
    worlds.forEach((world) => {
      deleteWorld(world.id);
    });

    // Clear localStorage
    const storageKey = `project-${project.project_name}-worlds`;
    try {
      localStorage.removeItem(storageKey);
    } catch (error) {
      console.error('Failed to clear worlds from localStorage:', error);
    }
  };

  return {
    clearAllWorlds,
    worldCount: worlds.length,
  };
}

/**
 * Prompt Library Service
 * Provides easy access to the prompt library for UI components
 */

export interface PromptVariable {
  type: 'string' | 'enum' | 'number';
  required: boolean;
  description?: string;
  options?: string[];
  examples?: string[];
  default?: string | number;
}

export interface PromptTemplate {
  category: string;
  subcategory: string;
  id: string;
  name: string;
  description: string;
  tags: string[];
  prompt: string;
  variables: Record<string, PromptVariable>;
  examples?: Array<Record<string, string | number>>;
}

export interface PromptCategory {
  name: string;
  description: string;
  prompts: string[];
}

export interface LibraryIndex {
  version: string;
  lastUpdated: string;
  totalPrompts: number;
  categories: Record<string, PromptCategory>;
}

export class PromptLibraryService {
  private static instance: PromptLibraryService;
  private index: LibraryIndex | null = null;
  private cache: Map<string, PromptTemplate> = new Map();
  private basePath = '/assets/library';

  private constructor() {}

  static getInstance(): PromptLibraryService {
    if (!PromptLibraryService.instance) {
      PromptLibraryService.instance = new PromptLibraryService();
    }
    return PromptLibraryService.instance;
  }

  /**
   * Load the library index
   */
  async loadIndex(): Promise<LibraryIndex> {
    if (this.index) return this.index;

    try {

      // Use fetch instead of dynamic import for JSON files
      const response = await fetch(`${this.basePath}/index.json`);

      if (!response.ok) {
        console.error(`[PromptLibraryService] Failed to load index: HTTP ${response.status} - ${response.statusText}`);
        console.error(`[PromptLibraryService] Response URL: ${response.url}`);

        // Return a minimal empty index instead of throwing
        console.warn(`[PromptLibraryService] Returning empty index due to missing library files`);
        this.index = {
          version: "1.0.0",
          lastUpdated: new Date().toISOString(),
          totalPrompts: 0,
          categories: {}
        };
        return this.index;
      }

      const responseText = await response.text();

      this.index = JSON.parse(responseText);
      return this.index;
    } catch (error) {
      console.error(`[PromptLibraryService] Error loading index: ${error instanceof Error ? error.message : String(error)}`);

      // Return empty index instead of throwing to prevent app crashes
      console.warn(`[PromptLibraryService] Returning empty index due to error`);
      this.index = {
        version: "1.0.0",
        lastUpdated: new Date().toISOString(),
        totalPrompts: 0,
        categories: {}
      };
      return this.index;
    }
  }

  /**
   * Get all categories
   */
  async getCategories(): Promise<Record<string, PromptCategory>> {
    const index = await this.loadIndex();
    return index.categories;
  }

  /**
   * Load a specific prompt template
   */
  async loadPrompt(path: string): Promise<PromptTemplate> {
    if (this.cache.has(path)) {
      return this.cache.get(path)!;
    }

    try {

      // Use fetch instead of dynamic import for JSON files
      const response = await fetch(`${this.basePath}/${path}`);

      if (!response.ok) {
        console.error(`[PromptLibraryService] Failed to load prompt ${path}: HTTP ${response.status} - ${response.statusText}`);
        console.error(`[PromptLibraryService] Response URL: ${response.url}`);

        // Return a minimal mock prompt instead of throwing
        console.warn(`[PromptLibraryService] Returning mock prompt for missing file: ${path}`);
        const mockPrompt: PromptTemplate = {
          category: 'mock',
          subcategory: 'mock',
          id: `mock-${path}`,
          name: `Mock Prompt (${path})`,
          description: 'This is a mock prompt because the library file is missing.',
          tags: ['mock'],
          prompt: 'Mock prompt text',
          variables: {}
        };
        this.cache.set(path, mockPrompt);
        return mockPrompt;
      }

      const responseText = await response.text();

      const template = JSON.parse(responseText);
      this.cache.set(path, template);
      return template;
    } catch (error) {
      console.error(`[PromptLibraryService] Error loading prompt ${path}: ${error instanceof Error ? error.message : String(error)}`);

      // Return mock prompt instead of throwing to prevent app crashes
      console.warn(`[PromptLibraryService] Returning mock prompt due to error: ${path}`);
      const mockPrompt: PromptTemplate = {
        category: 'error',
        subcategory: 'error',
        id: `error-${path}`,
        name: `Error Loading (${path})`,
        description: 'Failed to load prompt due to an error.',
        tags: ['error'],
        prompt: 'Error loading prompt template',
        variables: {}
      };
      this.cache.set(path, mockPrompt);
      return mockPrompt;
    }
  }

  /**
   * Get all prompts in a category
   */
  async getPromptsByCategory(categoryId: string): Promise<PromptTemplate[]> {
    const index = await this.loadIndex();
    const category = index.categories[categoryId];

    if (!category) {
      console.warn(`[PromptLibraryService] Category ${categoryId} not found, returning empty array`);
      return [];
    }

    const prompts = await Promise.all(
      category.prompts.map(path => this.loadPrompt(path))
    );

    return prompts;
  }

  /**
   * Search prompts by tags
   */
  async searchByTags(tags: string[]): Promise<PromptTemplate[]> {
    const index = await this.loadIndex();
    const allPromptPaths: string[] = [];
    
    Object.values(index.categories).forEach(category => {
      allPromptPaths.push(...category.prompts);
    });

    const allPrompts = await Promise.all(
      allPromptPaths.map(path => this.loadPrompt(path))
    );

    return allPrompts.filter(prompt => 
      tags.some(tag => prompt.tags.includes(tag))
    );
  }

  /**
   * Search prompts by text query
   */
  async search(query: string): Promise<PromptTemplate[]> {
    const index = await this.loadIndex();
    const allPromptPaths: string[] = [];
    
    Object.values(index.categories).forEach(category => {
      allPromptPaths.push(...category.prompts);
    });

    const allPrompts = await Promise.all(
      allPromptPaths.map(path => this.loadPrompt(path))
    );

    const lowerQuery = query.toLowerCase();
    return allPrompts.filter(prompt => 
      prompt.name.toLowerCase().includes(lowerQuery) ||
      prompt.description.toLowerCase().includes(lowerQuery) ||
      prompt.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
    );
  }

  /**
   * Fill a prompt template with variable values
   */
  fillPrompt(template: PromptTemplate, values: Record<string, string | number>): string {
    let filledPrompt = template.prompt;

    // Replace all variables
    Object.entries(values).forEach(([key, value]) => {
      const regex = new RegExp(`\\{${key}\\}`, 'g');
      filledPrompt = filledPrompt.replace(regex, String(value));
    });

    // Check for missing required variables
    const missingVars: string[] = [];
    Object.entries(template.variables).forEach(([key, variable]) => {
      if (variable.required && !values[key]) {
        missingVars.push(key);
      }
    });

    if (missingVars.length > 0) {
      console.warn(`Missing required variables: ${missingVars.join(', ')}`);
    }

    return filledPrompt;
  }

  /**
   * Get a random example for a template
   */
  getRandomExample(template: PromptTemplate): Record<string, string | number> | null {
    if (!template.examples || template.examples.length === 0) {
      return null;
    }
    const randomIndex = Math.floor(Math.random() * template.examples.length);
    return template.examples[randomIndex];
  }

  /**
   * Validate variable values against template
   */
  validateValues(
    template: PromptTemplate, 
    values: Record<string, string | number>
  ): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    Object.entries(template.variables).forEach(([key, variable]) => {
      const value = values[key];

      // Check required
      if (variable.required && (value === undefined || value === null || value === '')) {
        errors.push(`${key} is required`);
        return;
      }

      // Check enum options
      if (variable.type === 'enum' && variable.options && value) {
        if (!variable.options.includes(String(value))) {
          errors.push(`${key} must be one of: ${variable.options.join(', ')}`);
        }
      }

      // Check type
      if (value !== undefined && value !== null) {
        if (variable.type === 'number' && typeof value !== 'number') {
          errors.push(`${key} must be a number`);
        }
      }
    });

    return {
      valid: errors.length === 0,
      errors
    };
  }

  /**
   * Clear the cache
   */
  clearCache(): void {
    this.cache.clear();
    this.index = null;
  }

  // ============================================================================
  // Wizard-Specific Query Methods
  // ============================================================================

  /**
   * Get time of day prompts (6 prompts)
   */
  async getTimeOfDayPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('time-of-day');
  }

  /**
   * Get mood/atmosphere prompts (10 prompts)
   */
  async getMoodPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('mood-atmosphere');
  }

  /**
   * Get shot type prompts (7 prompts)
   */
  async getShotTypePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('shot-types');
  }

  /**
   * Get camera angle prompts (6 prompts)
   */
  async getCameraAnglePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('camera-angles');
  }

  /**
   * Get camera movement prompts (8 prompts)
   */
  async getCameraMovementPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('camera-movements');
  }

  /**
   * Get transition prompts (5 prompts)
   */
  async getTransitionPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('transitions');
  }

  /**
   * Get lighting prompts (4 prompts)
   */
  async getLightingPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('lighting');
  }

  /**
   * Get genre prompts (15 prompts)
   */
  async getGenrePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('genres');
  }

  /**
   * Get visual style prompts (11 prompts)
   */
  async getVisualStylePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('visual-styles');
  }

  /**
   * Get color palette prompts (6 prompts)
   */
  async getColorPalettePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('color-palettes');
  }

  /**
   * Get universe type prompts (5 prompts)
   */
  async getUniverseTypePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('universe-types');
  }

  /**
   * Get character archetype prompts (3 prompts)
   */
  async getCharacterArchetypePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('character-archetypes');
  }

  /**
   * Get master coherence prompts (3 prompts)
   */
  async getMasterCoherencePrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('master-coherence');
  }

  /**
   * Get scene element prompts (4 prompts)
   */
  async getSceneElementPrompts(): Promise<PromptTemplate[]> {
    return this.getPromptsByCategory('scene-elements');
  }

  /**
   * Get all prompts organized by category
   * Returns all 93 prompts grouped by their categories
   */
  async getAllPromptsByCategory(): Promise<Record<string, PromptTemplate[]>> {
    const index = await this.loadIndex();
    const result: Record<string, PromptTemplate[]> = {};

    for (const [categoryId, _category] of Object.entries(index.categories)) {
      result[categoryId] = await this.getPromptsByCategory(categoryId);
    }

    return result;
  }

  /**
   * Get total prompt count
   */
  async getTotalPromptCount(): Promise<number> {
    const index = await this.loadIndex();
    return index.totalPrompts;
  }

  /**
   * Get category information
   */
  async getCategoryInfo(categoryId: string): Promise<PromptCategory | null> {
    const index = await this.loadIndex();
    return index.categories[categoryId] || null;
  }

  /**
   * Check if library is fully loaded
   */
  async isLibraryLoaded(): Promise<boolean> {
    try {
      const index = await this.loadIndex();
      return index.totalPrompts === 93;
    } catch {
      return false;
    }
  }

  // ============================================================================
  // Filtering Methods
  // ============================================================================

  /**
   * Filter prompts by genre
   * @param prompts - Array of prompts to filter
   * @param genre - Genre to filter by (e.g., 'sci-fi', 'fantasy', 'horror')
   * @returns Filtered prompts that match the genre
   */
  filterByGenre(prompts: PromptTemplate[], genre: string): PromptTemplate[] {
    const genreLower = genre.toLowerCase();
    return prompts.filter(prompt => {
      // Check if genre is in tags
      const hasGenreTag = prompt.tags.some(tag => tag.toLowerCase().includes(genreLower));
      
      // Check if genre is mentioned in description
      const hasGenreInDescription = prompt.description.toLowerCase().includes(genreLower);
      
      // Check if genre is in the prompt category
      const hasGenreInCategory = prompt.category.toLowerCase().includes(genreLower);
      
      return hasGenreTag || hasGenreInDescription || hasGenreInCategory;
    });
  }

  /**
   * Filter prompts by visual style
   * @param prompts - Array of prompts to filter
   * @param style - Visual style to filter by (e.g., 'cinematic', 'anime', 'realistic')
   * @returns Filtered prompts that match the style
   */
  filterByStyle(prompts: PromptTemplate[], style: string): PromptTemplate[] {
    const styleLower = style.toLowerCase();
    return prompts.filter(prompt => {
      // Check if style is in tags
      const hasStyleTag = prompt.tags.some(tag => tag.toLowerCase().includes(styleLower));
      
      // Check if style is mentioned in description
      const hasStyleInDescription = prompt.description.toLowerCase().includes(styleLower);
      
      // Check if style is in the prompt text itself (handle both string and object)
      const promptText = typeof prompt.prompt === 'string' ? prompt.prompt : JSON.stringify(prompt.prompt);
      const hasStyleInPrompt = promptText.toLowerCase().includes(styleLower);
      
      return hasStyleTag || hasStyleInDescription || hasStyleInPrompt;
    });
  }

  /**
   * Filter prompts by universe type
   * @param prompts - Array of prompts to filter
   * @param universeType - Universe type to filter by (e.g., 'realistic', 'fantasy', 'sci-fi')
   * @returns Filtered prompts that match the universe type
   */
  filterByUniverseType(prompts: PromptTemplate[], universeType: string): PromptTemplate[] {
    const universeLower = universeType.toLowerCase();
    return prompts.filter(prompt => {
      // Check if universe type is in tags
      const hasUniverseTag = prompt.tags.some(tag => tag.toLowerCase().includes(universeLower));
      
      // Check if universe type is mentioned in description
      const hasUniverseInDescription = prompt.description.toLowerCase().includes(universeLower);
      
      // Check if universe type is in category
      const hasUniverseInCategory = prompt.category.toLowerCase().includes(universeLower);
      
      // Check subcategory as well (handle undefined)
      const hasUniverseInSubcategory = prompt.subcategory ? 
        prompt.subcategory.toLowerCase().includes(universeLower) : false;
      
      return hasUniverseTag || hasUniverseInDescription || hasUniverseInCategory || hasUniverseInSubcategory;
    });
  }

  /**
   * Apply multiple filters to prompts
   * @param prompts - Array of prompts to filter
   * @param filters - Object containing filter criteria
   * @returns Filtered prompts that match all criteria
   */
  applyFilters(
    prompts: PromptTemplate[],
    filters: {
      genre?: string;
      style?: string;
      universeType?: string;
      tags?: string[];
    }
  ): PromptTemplate[] {
    let filtered = prompts;

    if (filters.genre) {
      filtered = this.filterByGenre(filtered, filters.genre);
    }

    if (filters.style) {
      filtered = this.filterByStyle(filtered, filters.style);
    }

    if (filters.universeType) {
      filtered = this.filterByUniverseType(filtered, filters.universeType);
    }

    if (filters.tags && filters.tags.length > 0) {
      filtered = filtered.filter(prompt =>
        filters.tags!.some(tag => prompt.tags.includes(tag))
      );
    }

    return filtered;
  }
}

