  { id: 'instagram_story', name: 'Instagram Story', platform: 'Instagram', resolution: '1080x1920', width: 1080, height: 1920, aspectRatio: '9:16', format: 'mp4', quality: 'high', description: 'Vertical for Instagram Stories' },
