const ANIMATION_TEMPLATES = [
  {
    id: 'walk-cycle',
    name: 'Walk Cycle',
    description: '4-frame walking animation',
    frames: [
      { frame: 0, pose: 'walking' },
      { frame: 6, pose: 'idle' },
      { frame: 12, pose: 'walking' },
      { frame: 18, pose: 'idle' },
    ],
  },
  {
    id: 'wave-hello',
    name: 'Wave Hello',
