/**
 * Playhead Indicator Component
 * 
 * Enhanced draggable playhead with smooth scrubbing, snap-to-frame behavior,
 * timecode display, click-to-seek, and keyboard navigation support.
 * 
 * Features:
 * - Draggable playhead with smooth scrubbing
 * - Click-to-seek on timeline ruler
 * - Vertical line indicator across all tracks
 * - Timecode tooltip during scrubbing
 * - Keyboard navigation (arrow keys, Home/End, Page Up/Down)
 * 
 * Requirements: 1.8, 3.2, 4.5, 4.6
 */

import React, { useCallback, useRef, useEffect, useState } from 'react';

interface PlayheadIndicatorProps {
  position: number;
  height: number;
  zoomLevel: number;
  fps?: number;
  isDragging: boolean;
  isPlaying?: boolean;
  snapToGrid?: boolean;
  onMouseDown: (e: React.MouseEvent) => void;
  onPositionChange: (position: number) => void;
  onDragStart?: () => void;
  onDragEnd?: () => void;
}

export const PlayheadIndicator: React.FC<PlayheadIndicatorProps> = ({
  position,
  height,
  zoomLevel,
  fps = 24,
  isDragging,
  isPlaying = false,
  snapToGrid = true,
  onMouseDown,
  onPositionChange,
  onDragStart,
  onDragEnd,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [showTooltip, setShowTooltip] = useState(false);
  const dragStartTimeRef = useRef<number>(0);
  
  // Calculate frame from position
  const frameFromPosition = useCallback((pos: number): number => {
    const frame = pos / zoomLevel;
    if (snapToGrid) {
      return Math.round(frame);
    }
    return Math.floor(frame);
  }, [zoomLevel, snapToGrid]);
  
  // Calculate position from frame
  const positionFromFrame = useCallback((frame: number): number => {
    return frame * zoomLevel;
  }, [zoomLevel]);
  
  // Format timecode from frame
  const formatTimecode = useCallback((frame: number): string => {
    const totalSeconds = Math.floor(frame / fps);
    const seconds = totalSeconds % 60;
    const minutes = Math.floor(totalSeconds / 60);
    const frameNum = frame % fps;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frameNum).padStart(2, '0')}`;
  }, [fps]);
  
  // Format duration from frames
  const formatDuration = useCallback((frame: number): string => {
    const totalSeconds = Math.floor(frame / fps);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    if (minutes > 0) {
      return `${minutes}m ${seconds}s`;
    }
    return `${seconds}s`;
  }, [fps]);
  
  const currentFrame = frameFromPosition(position);
  const timecode = formatTimecode(currentFrame);
  const totalFrames = Math.round(height / zoomLevel);
  const duration = formatDuration(totalFrames);
  
  // Show tooltip when hovering or dragging
  useEffect(() => {
    if (isHovered || isDragging) {
      setShowTooltip(true);
    } else {
      // Delay hiding tooltip slightly for better UX
      const timer = setTimeout(() => setShowTooltip(false), 200);
      return () => clearTimeout(timer);
    }
  }, [isHovered, isDragging]);
  
  // Handle drag start
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    dragStartTimeRef.current = Date.now();
    if (onDragStart) {
      onDragStart();
    }
    onMouseDown(e);
  }, [onMouseDown, onDragStart]);
  
  // Handle drag end
  useEffect(() => {
    if (!isDragging && dragStartTimeRef.current > 0) {
      const dragDuration = Date.now() - dragStartTimeRef.current;
      dragStartTimeRef.current = 0;
      
      // Only call onDragEnd if it was actually a drag (not just a click)
      if (dragDuration > 100 && onDragEnd) {
        onDragEnd();
      }
    }
  }, [isDragging, onDragEnd]);
  
  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isDragging) return;
      
      let delta = 0;
      
      switch (e.key) {
        case 'ArrowLeft':
          e.preventDefault();
          delta = e.shiftKey ? -10 : -1; // Shift for 10 frames, normal for 1
          break;
        case 'ArrowRight':
          e.preventDefault();
          delta = e.shiftKey ? 10 : 1;
          break;
        case 'Home':
          e.preventDefault();
          onPositionChange(0);
          return;
        case 'End':
          e.preventDefault();
          onPositionChange(positionFromFrame(Math.round(height / zoomLevel)));
          return;
        case 'PageUp':
          e.preventDefault();
          delta = fps; // 1 second
          break;
        case 'PageDown':
          e.preventDefault();
          delta = -fps; // -1 second
          break;
      }
      
      if (delta !== 0) {
        const newFrame = Math.max(0, currentFrame + delta);
        onPositionChange(positionFromFrame(newFrame));
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isDragging, currentFrame, height, zoomLevel, fps, onPositionChange, positionFromFrame]);
  
  return (
    <div
      className={`playhead-indicator ${isDragging ? 'dragging' : ''} ${isPlaying ? 'playing' : ''} ${isHovered ? 'hovered' : ''}`}
      style={{
        left: position,
        height,
      }}
      onMouseDown={handleMouseDown}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      role="slider"
      aria-label="Playhead position"
      aria-valuenow={currentFrame}
      aria-valuemin={0}
      aria-valuemax={Math.round(height / zoomLevel)}
      tabIndex={0}
    >
      {/* Playhead handle with timecode */}
      <div className={`playhead-handle ${isHovered || isDragging ? 'hovered' : ''}`}>
        <div className="playhead-handle-top" />
        
        {/* Timecode tooltip - shown during hover or drag */}
        {showTooltip && (
          <div className="playhead-tooltip">
            <div className="playhead-tooltip-timecode">{timecode}</div>
            <div className="playhead-tooltip-info">
              <span>Frame: {currentFrame}</span>
              <span>Total: {duration}</span>
            </div>
            {isDragging && (
              <div className="playhead-tooltip-hint">
                {snapToGrid ? '🔒 Snapped' : '🔓 Free'}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Playhead line - vertical indicator across all tracks */}
      <div className="playhead-line" style={{ height }}>
        {/* Add subtle gradient for better visibility */}
        <div className="playhead-line-glow" />
      </div>
      
      {/* Current frame indicator on line */}
      <div 
        className="playhead-frame-marker"
        style={{ bottom: 0 }}
        title={`Frame ${currentFrame}`}
      />
      
      {/* Playing indicator */}
      {isPlaying && (
        <div className="playhead-playing-indicator">
          <span className="playing-dot" />
          <span className="playing-text">PLAY</span>
        </div>
      )}
      
      {/* Scrubbing indicator */}
      {isDragging && !isPlaying && (
        <div className="playhead-scrubbing-indicator">
          <span className="scrubbing-icon">⏩</span>
          <span className="scrubbing-text">SCRUB</span>
        </div>
      )}
    </div>
  );
};

// Export utility functions
export { formatTimecodeFromPosition };

function formatTimecodeFromPosition(pixels: number, fps: number = 24, zoomLevel: number = 1): string {
  const frame = Math.round(pixels / zoomLevel);
  const totalSeconds = Math.floor(frame / fps);
  const seconds = totalSeconds % 60;
  const minutes = Math.floor(totalSeconds / 60);
  const frames = frame % fps;

  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frames).padStart(2, '0')}`;
}

export default PlayheadIndicator;

/**
 * TimeRuler Component
 * 
 * Timeline ruler with configurable time markers and granularity.
 * Supports frames, seconds, and minutes display.
 * Includes click-to-seek functionality for quick playhead positioning.
 * 
 * Features:
 * - Click anywhere on ruler to seek to that position
 * - Configurable time format (frames/seconds/minutes)
 * - Snap-to-grid visual feedback
 * - Hover preview of timecode
 * 
 * Requirements: 1.8, 4.5, 4.6
 */

import React, { useCallback, useMemo, useState, useRef } from 'react';

interface TimeRulerProps {
  zoomLevel: number;
  duration: number;
  fps?: number;
  snapToGrid?: boolean;
  playheadPosition?: number;
  onSeek?: (frame: number) => void;
  onMarkerClick?: (frame: number) => void;
}

type TimeFormat = 'frames' | 'seconds' | 'minutes';

export const TimeRuler: React.FC<TimeRulerProps> = ({
  zoomLevel,
  duration,
  fps = 24,
  snapToGrid = true,
  playheadPosition = 0,
  onSeek,
  onMarkerClick,
}) => {
  const [timeFormat, setTimeFormat] = useState<TimeFormat>('seconds');
  const [hoverPosition, setHoverPosition] = useState<number | null>(null);
  const rulerRef = useRef<HTMLDivElement>(null);
  
  // Calculate marker interval based on zoom level
  const markerInterval = useMemo(() => {
    if (zoomLevel >= 50) {
      return 1; // Every frame
    } else if (zoomLevel >= 20) {
      return 5; // Every 5 frames
    } else if (zoomLevel >= 10) {
      return 10; // Every 10 frames (about 0.4 seconds)
    } else if (zoomLevel >= 5) {
      return 30; // Every 30 frames (about 1.25 seconds)
    } else {
      return 60; // Every 60 frames (about 2.5 seconds)
    }
  }, [zoomLevel]);
  
  // Major marker interval (every 10th marker)
  const majorInterval = useMemo(() => {
    if (zoomLevel >= 50) {
      return 10; // Every 10 frames
    } else if (zoomLevel >= 20) {
      return 30; // Every 30 frames
    } else {
      return 60; // Every 60 frames
    }
  }, [zoomLevel]);
  
  // Calculate total width
  const totalWidth = duration * zoomLevel;
  
  // Format timecode
  const formatTimecode = useCallback((frame: number): string => {
    const totalSeconds = Math.floor(frame / fps);
    const seconds = totalSeconds % 60;
    const minutes = Math.floor(totalSeconds / 60);
    const frameNum = frame % fps;
    
    if (timeFormat === 'frames') {
      return `${frameNum}`;
    } else if (timeFormat === 'minutes') {
      return `${minutes}:00`;
    } else {
      return `${minutes}:${String(seconds).padStart(2, '0')}`;
    }
  }, [fps, timeFormat]);
  
  // Generate markers
  const markers = useMemo(() => {
    const result: { frame: number; position: number; isMajor: boolean; label: string }[] = [];
    const numMarkers = Math.ceil(duration / markerInterval);
    
    for (let frame = 0; frame <= numMarkers * markerInterval; frame += markerInterval) {
      if (frame > duration) break;
      
      const isMajor = frame % majorInterval === 0;
      const label = formatTimecode(frame);
      
      result.push({
        frame,
        position: frame * zoomLevel,
        isMajor,
        label,
      });
    }
    
    return result;
  }, [duration, markerInterval, majorInterval, zoomLevel, formatTimecode]);
  
  // Handle marker click
  const handleMarkerClick = useCallback((frame: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (onMarkerClick) {
      onMarkerClick(frame);
    }
    if (onSeek) {
      onSeek(frame);
    }
  }, [onMarkerClick, onSeek]);
  
  // Handle ruler click for seek
  const handleRulerClick = useCallback((e: React.MouseEvent) => {
    if (!rulerRef.current || !onSeek) return;
    
    const rect = rulerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const frame = Math.round(x / zoomLevel);
    
    // Clamp to valid range
    const clampedFrame = Math.max(0, Math.min(frame, duration));
    onSeek(clampedFrame);
  }, [zoomLevel, duration, onSeek]);
  
  // Handle mouse move for hover preview
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!rulerRef.current) return;
    
    const rect = rulerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const frame = Math.round(x / zoomLevel);
    
    setHoverPosition(Math.max(0, Math.min(frame, duration)));
  }, [zoomLevel, duration]);
  
  // Handle mouse leave
  const handleMouseLeave = useCallback(() => {
    setHoverPosition(null);
  }, []);
  
  // Toggle time format on double-click
  const handleDoubleClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    const formats: TimeFormat[] = ['seconds', 'frames', 'minutes'];
    const currentIndex = formats.indexOf(timeFormat);
    const nextIndex = (currentIndex + 1) % formats.length;
    setTimeFormat(formats[nextIndex]);
  }, [timeFormat]);
  
  // Calculate hover timecode
  const hoverTimecode = useMemo(() => {
    if (hoverPosition === null) return null;
    return formatTimecode(hoverPosition);
  }, [hoverPosition, formatTimecode]);
  
  return (
    <div 
      ref={rulerRef}
      className={`timeline-ruler ${snapToGrid ? 'snap-grid-active' : ''}`}
      style={{ width: totalWidth }}
      onClick={handleRulerClick}
      onDoubleClick={handleDoubleClick}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      role="slider"
      aria-label="Time ruler - click to seek"
      aria-valuenow={playheadPosition}
      aria-valuemin={0}
      aria-valuemax={duration}
      tabIndex={0}
      title="Click to seek, double-click to change time format"
    >
      {/* Markers */}
      {markers.map((marker) => (
        <div
          key={`marker-${marker.frame}`}
          className={`timeline-ruler-marker ${marker.isMajor ? 'major' : 'minor'}`}
          style={{ left: marker.position }}
          onClick={(e) => handleMarkerClick(marker.frame, e)}
          role="button"
          aria-label={`Go to ${marker.label}`}
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              handleMarkerClick(marker.frame, e as any);
            }
          }}
        >
          {marker.isMajor && (
            <span className="timeline-ruler-label">
              {marker.label}
            </span>
          )}
        </div>
      ))}
      
      {/* Hover preview indicator */}
      {hoverPosition !== null && (
        <div 
          className="ruler-hover-indicator"
          style={{ left: hoverPosition * zoomLevel }}
        >
          <div className="ruler-hover-line" />
          <div className="ruler-hover-tooltip">
            {hoverTimecode}
          </div>
        </div>
      )}
      
      {/* Current playhead position indicator */}
      <div 
        className="ruler-playhead-indicator"
        style={{ left: playheadPosition * zoomLevel }}
      />
      
      {/* Format indicator tooltip */}
      <div className="ruler-format-hint" title="Double-click to change format">
        {timeFormat === 'seconds' && '⏱️ Seconds'}
        {timeFormat === 'frames' && '🎬 Frames'}
        {timeFormat === 'minutes' && '⏰ Minutes'}
      </div>
    </div>
  );
};

// Export utility functions
export { formatTimecodeFromFrames, formatDurationFromFrames };

function formatTimecodeFromFrames(frames: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frames / fps);
  const seconds = totalSeconds % 60;
  const minutes = Math.floor(totalSeconds / 60);
  const frameNum = frames % fps;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frameNum).padStart(2, '0')}`;
}

function formatDurationFromFrames(frames: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frames / fps);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  
  if (minutes > 0) {
    return `${minutes}m ${seconds}s`;
  }
  return `${seconds}s`;
}

