};

const DEFAULT_ZOOM = 10; // pixels per frame
const MIN_ZOOM = 1;
const MAX_ZOOM = 100;
const PLAYHEAD_SNAP_THRESHOLD = 5; // pixels
const TRACK_HEADERS_WIDTH = 200;

// ============================================================================
// Component
// ============================================================================

export const Timeline: React.FC = () => {
  const dispatch = useAppDispatch();
