          layers: [
            {
              id: 'layer-3',
              type: 'media',
              startTime: 0,
              duration: 150,
              locked: false,
              hidden: false,
              opacity: 1,
              blendMode: 'normal',
              data: {
                sourceUrl: '',
                trim: { start: 0, end: 150 },
                transform: {
                  position: { x: 0, y: 0 },
                  scale: { x: 1, y: 1 },
                  rotation: 0,
                  anchor: { x: 0.5, y: 0.5 },
                },
              } as MediaLayerData,
            },
            {
              id: 'layer-4',
              type: 'audio',
              startTime: 0,
              duration: 150,
              locked: false,
              hidden: false,
              opacity: 1,
              blendMode: 'normal',
              data: {
                sourceUrl: '',
                volume: 0.8,
                fadeIn: 0,
                fadeOut: 0,
              },
            }
          ],
          referenceImages: [],
          prompt: 'Epic battle scene with explosions',
          parameters: {
            seed: 11111,
            denoising: 0.7,
            steps: 30,
            guidance: 7.5,
            sampler: 'euler',
            scheduler: 'normal',
          },
          generationStatus: 'pending',
        },
      ];

      sampleShots.forEach((shot) => {
        dispatch(addShot(shot));
      });
    }
  }, [shots.length, dispatch]);

  // Render time ruler using TimeRuler component
  const renderTimeRuler = useCallback(() => {
    return (
      <TimeRuler
        zoomLevel={zoomLevel}
        duration={duration}
        fps={24}
        snapToGrid={snapToGrid}
        playheadPosition={playheadPosition}
        onSeek={handleRulerSeek}
      />
    );
  }, [zoomLevel, duration, snapToGrid, playheadPosition, handleRulerSeek]);

  // Filter visible tracks for virtual mode
  const visibleTracks: Track[] = useMemo(
    () => tracks.filter((track: Track) => !track.hidden),
    [tracks]
  );

  return (
    <div className="timeline-panel">
      {/* Timeline Controls */}
      <TimelineControls
        zoomLevel={zoomLevel}
        onZoomChange={handleZoomChange}
        onAddTrack={handleAddTrack}
        playheadPosition={playheadPosition}
        duration={duration}
        onToggleVirtualMode={() => setUseVirtualMode(!useVirtualMode)}
        useVirtualMode={useVirtualMode}
        onSplit={handleSplit}
        onAutoMix={handleAutoMix}
      />

      {/* Timeline Container */}
      <div
        ref={timelineRef}
        className="timeline-container"
        onClick={handleTimelineClick}
        onScroll={handleScroll}
      >
        {/* Track Headers */}
        <div className="timeline-track-headers">
          <div className="timeline-ruler-spacer" />
          {renderTrackHeaders()}
        </div>

        {/* Timeline Content Area */}
        <div
          ref={contentAreaRef}
          className="timeline-content-area"
        >
          {/* Time Ruler */}
          {renderTimeRuler()}

          {/* Track Content */}
          {useVirtualMode ? (
            /* Virtual Scrolling Mode */
            <VirtualTimelineCanvas
              tracks={tracks}
              shots={shots}
              zoomLevel={zoomLevel}
              playheadPosition={playheadPosition}
              selectedElements={selectedElements}
              timelineWidth={timelineWidth}
              onShotSelect={handleShotSelect}
            />
          ) : (
            /* DOM-based Rendering Mode (Legacy) */
            <div
              className="timeline-tracks-area"
              style={{ width: timelineWidth, height: totalTracksHeight }}
            >
              {visibleTracks.map((track: Track) => (
                <div
                  key={track.id}
                  className="timeline-track-row"
                  style={{ height: track.height }}
                >
                  {shots
                    .filter((shot: Shot) => shot.layers.some((layer: Layer) => layer.type === track.type))
                    .flatMap((shot: Shot) =>
                      shot.layers
                        .filter((layer: Layer) => layer.type === track.type)
                        .map((layer: Layer, layerIndex: number) => ({ shot, layer, layerIndex }))
                    )
                    .map(({ shot, layer, layerIndex }: { shot: Shot; layer: Layer; layerIndex: number }) => {
                      const isSelected = selectedElements.includes(shot.id);
                      const shotLeft = shot.startTime * zoomLevel;
                      const shotWidth = shot.duration * zoomLevel;

                      return (
                        <div
                          key={`${track.id}-${shot.id}-${layer.id || layerIndex}`}
                          className={`timeline-shot ${isSelected ? 'selected' : ''}`}
                          style={{
                            left: `${shotLeft}px`,
                            width: `${shotWidth}px`,
                            height: '28px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                          }}
                          onClick={(e) => {
                            e.stopPropagation();
                            handleShotSelect(shot.id, e.ctrlKey || e.metaKey);
                          }}
                        >
                          <div
                            className="shot-content"
                            style={{
                              backgroundColor: track.color,
                              opacity: isSelected ? 1 : 0.8,
                            }}
                          >
                            <span className="shot-name">{shot.name}</span>
                          </div>
                        </div>
                      );
                    })}
                </div>
              ))}
            </div>
          )}

          {/* Playhead Indicator */}
          <PlayheadIndicator
            position={playheadPosition * zoomLevel}
            height={totalTracksHeight}
            zoomLevel={zoomLevel}
            fps={24}
            isDragging={isDraggingPlayhead}
            isPlaying={false}
            snapToGrid={snapToGrid}
            onMouseDown={handlePlayheadMouseDown}
            onPositionChange={(frame) => dispatch(setPlayheadPosition(frame))}
            onDragStart={handlePlayheadDragStart}
            onDragEnd={handlePlayheadDragEnd}
          />
        </div>
      </div>
    </div>
  );
};

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Format frame number to timecode string (MM:SS:FF)
 */
function formatTimecode(frame: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frame / fps);
  const seconds = totalSeconds % 60;
  const minutes = Math.floor(totalSeconds / 60);
  const frames = frame % fps;

  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frames).padStart(2, '0')}`;
}

export default Timeline;

/**
 * Timeline Context Menu
 * Right-click context menu for timeline.
 */
import React, { useState, useCallback, useRef, useEffect } from 'react';
import './TimelineContextMenu.css';

interface ContextMenuProps {
  position: { x: number; y: number } | null;
  target: 'shot' | 'track' | 'timeline' | null;
  onClose: () => void;
  onAction?: (action: string) => void;
}

interface MenuItem {
  id: string;
  label: string;
  shortcut?: string;
  submenu?: MenuItem[];
}

export const TimelineContextMenu: React.FC<ContextMenuProps> = ({
  position,
  target,
  onClose,
  onAction,
}) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const [activeSubmenu, setActiveSubmenu] = useState<string | null>(null);
  
  const menuItems: MenuItem[] = [
    {
      id: 'edit',
      label: 'Edit',
      submenu: [
        { id: 'cut', label: 'Cut', shortcut: 'Ctrl+X' },
        { id: 'copy', label: 'Copy', shortcut: 'Ctrl+C' },
        { id: 'paste', label: 'Paste', shortcut: 'Ctrl+V' },
        { id: 'duplicate', label: 'Duplicate', shortcut: 'Ctrl+D' },
        { id: 'delete', label: 'Delete', shortcut: 'Del' },
      ],
    },
    {
      id: 'shot',
      label: 'Shot',
      submenu: [
        { id: 'split', label: 'Split at Playhead' },
        { id: 'trimStart', label: 'Trim Start' },
        { id: 'trimEnd', label: 'Trim End' },
        { id: 'addMarker', label: 'Add Marker' },
      ],
    },
    {
      id: 'timing',
      label: 'Timing',
      submenu: [
        { id: 'normalSpeed', label: 'Normal Speed (1x)' },
        { id: 'halfSpeed', label: 'Half Speed (0.5x)' },
        { id: 'doubleSpeed', label: 'Double Speed (2x)' },
      ],
    },
    {
      id: 'track',
      label: 'Track',
      submenu: [
        { id: 'mute', label: 'Mute' },
        { id: 'solo', label: 'Solo' },
        { id: 'lock', label: 'Lock' },
        { id: 'hide', label: 'Hide' },
      ],
    },
  ];

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    document.addEventListener('click', handleClick);
    return () => document.removeEventListener('click', handleClick);
  }, [onClose]);

  const handleAction = useCallback((action: string) => {
    onAction?.(action);
    onClose();
  }, [onAction, onClose]);

  if (!position) return null;

  return (
    <div 
      ref={menuRef}
      className="timeline-context-menu"
      style={{ top: position.y, left: position.x }}
      role="menu"
    >
      {menuItems.map((item) => (
        <div 
          key={item.id}
          className="context-menu-item"
          onMouseEnter={() => item.submenu && setActiveSubmenu(item.id)}
          onClick={() => item.submenu || handleAction(item.id)}
        >
          <span className="item-label">{item.label}</span>
          {item.submenu && <span className="item-arrow">▶</span>}
          
          {item.submenu && activeSubmenu === item.id && (
            <div className="context-submenu">
              {item.submenu.map((subItem) => (
                <div 
                  key={subItem.id}
                  className="context-menu-item"
                  onClick={(e) => { e.stopPropagation(); handleAction(subItem.id); }}
                >
                  <span className="item-label">{subItem.label}</span>
                  {subItem.shortcut && (
                    <span className="item-shortcut">{subItem.shortcut}</span>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

export default TimelineContextMenu;

/**
 * Timeline Controls Component
 * 
 * Comprehensive timeline control bar with playback controls, zoom controls,
 * track management, edit mode toggles, and playback shortcuts.
 * 
 * Requirements: 1.1, 1.2, 1.4, 3.4, 3.5, 16.1, 16.2, 16.3, 16.4, 16.5, 17.2
 */

import React, { useCallback, useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../store';
import { play, pause, stop } from '../../store/slices/previewSlice';
import { setPlayheadPosition } from '../../store/slices/timelineSlice';
import type { LayerType, PlaybackState } from '../../types';
import { GoToTimeDialog } from './GoToTimeDialog';

interface TimelineControlsProps {
  zoomLevel: number;
  onZoomChange: (zoom: number) => void;
  onAddTrack: (type: LayerType) => void;
  onDeleteTrack?: () => void;
  playheadPosition: number;
  duration: number; // Total duration in frames
  onToggleVirtualMode?: () => void;
  useVirtualMode?: boolean;
  // Edit mode toggles
  snapToGrid?: boolean;
  onToggleSnapToGrid?: () => void;
  rippleEdit?: boolean;
  onToggleRippleEdit?: () => void;
  magneticTimeline?: boolean;
  onToggleMagneticTimeline?: () => void;
  onSplit?: () => void;
  onAutoMix?: () => void;
}

export const TimelineControls: React.FC<TimelineControlsProps> = ({
  zoomLevel,
  onZoomChange,
  onAddTrack,
  onDeleteTrack,
  playheadPosition,
  duration,
  onToggleVirtualMode,
  useVirtualMode = true,
  snapToGrid = true,
  onToggleSnapToGrid,
  rippleEdit = false,
  onToggleRippleEdit,
  magneticTimeline = false,
  onToggleMagneticTimeline,
  onSplit,
  onAutoMix,
}) => {
  const dispatch = useAppDispatch();
  const [showAddTrackMenu, setShowAddTrackMenu] = useState(false);
  const [showGoToTimeDialog, setShowGoToTimeDialog] = useState(false);

  // Get playback state from Redux
  const playbackState: PlaybackState = useAppSelector((state) => state.preview.playbackState);
  const isPlaying = playbackState === 'playing';
  const isPaused = playbackState === 'paused';

  // Track type options
  const trackTypes: { type: LayerType; label: string; icon: string }[] = [
    { type: 'media', label: 'Media Track', icon: '🎬' },
    { type: 'audio', label: 'Audio Track', icon: '🔊' },
    { type: 'effects', label: 'Effects Track', icon: '✨' },
    { type: 'transitions', label: 'Transitions Track', icon: '↔️' },
    { type: 'text', label: 'Text Track', icon: '📝' },
    { type: 'keyframes', label: 'Keyframes Track', icon: '🔑' },
  ];

  // Playback control handlers
  const handlePlayPause = useCallback(() => {
    if (isPlaying) {
      dispatch(pause());
    } else {
      dispatch(play());
    }
  }, [dispatch, isPlaying]);

  const handleStop = useCallback(() => {
    dispatch(stop());
    dispatch(setPlayheadPosition(0));
  }, [dispatch]);

  const handleGoToStart = useCallback(() => {
    dispatch(setPlayheadPosition(0));
  }, [dispatch]);

  const handleGoToEnd = useCallback(() => {
    dispatch(setPlayheadPosition(duration));
  }, [dispatch, duration]);

  const handlePreviousFrame = useCallback(() => {
    dispatch(setPlayheadPosition(Math.max(0, playheadPosition - 1)));
  }, [dispatch, playheadPosition]);

  const handleNextFrame = useCallback(() => {
    dispatch(setPlayheadPosition(Math.min(duration, playheadPosition + 1)));
  }, [dispatch, playheadPosition, duration]);

  // Keyboard shortcuts for playback
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in an input field
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      // Ctrl/Cmd + G - Go to Time
      if ((e.ctrlKey || e.metaKey) && e.key === 'g') {
        e.preventDefault();
        setShowGoToTimeDialog(true);
        return;
      }

      switch (e.key) {
        case ' ': // Space - Play/Pause
          e.preventDefault();
          handlePlayPause();
          break;
        case 'k': // K - Stop
        case 'K':
          e.preventDefault();
          handleStop();
          break;
        case 'j': // J - Previous frame (backward)
        case 'J':
          e.preventDefault();
          handlePreviousFrame();
          break;
        case 'l': // L - Next frame (forward)
        case 'L':
          e.preventDefault();
          handleNextFrame();
          break;
        case 'Home': // Home - Go to start
          e.preventDefault();
          handleGoToStart();
          break;
        case 'End': // End - Go to end
          e.preventDefault();
          handleGoToEnd();
          break;
        case 'ArrowLeft': // Left arrow - Previous frame
          if (!e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            handlePreviousFrame();
          }
          break;
        case 'ArrowRight': // Right arrow - Next frame
          if (!e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            handleNextFrame();
          }
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlePlayPause, handleStop, handlePreviousFrame, handleNextFrame, handleGoToStart, handleGoToEnd]);

  // Handle zoom in
  const handleZoomIn = useCallback(() => {
    onZoomChange(Math.min(100, zoomLevel * 1.5));
  }, [zoomLevel, onZoomChange]);

  // Handle zoom out
  const handleZoomOut = useCallback(() => {
    onZoomChange(Math.max(1, zoomLevel / 1.5));
  }, [zoomLevel, onZoomChange]);

  // Handle fit to window
  const handleFitToWindow = useCallback(() => {
    onZoomChange(10);
  }, [onZoomChange]);

  // Handle add track
  const handleAddTrack = useCallback((type: LayerType) => {
    onAddTrack(type);
    setShowAddTrackMenu(false);
  }, [onAddTrack]);

  // Handle delete track
  const handleDeleteTrack = useCallback(() => {
    if (onDeleteTrack) {
      onDeleteTrack();
    }
  }, [onDeleteTrack]);

  // Handle go to time
  const handleGoToTime = useCallback((frame: number) => {
    dispatch(setPlayheadPosition(frame));
    setShowGoToTimeDialog(false);
  }, [dispatch]);

  // Format current time
  const formatTime = (frames: number) => {
    const fps = 24;
    const totalSeconds = Math.floor(frames / fps);
    const seconds = totalSeconds % 60;
    const minutes = Math.floor(totalSeconds / 60);
    const frameNum = frames % fps;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frameNum).padStart(2, '0')}`;
  };

  return (
    <div className="timeline-controls-bar">
      {/* Playback controls */}
      <div className="timeline-controls-group">
        <button
          className="timeline-control-btn"
          title="Go to start (Home)"
          onClick={handleGoToStart}
        >
          ⏮️
        </button>
        <button
          className="timeline-control-btn"
          title="Previous frame (J or Left Arrow)"
          onClick={handlePreviousFrame}
        >
          ⏪
        </button>
        <button
          className={`timeline-control-btn playback-btn ${isPlaying ? 'playing' : ''}`}
          title={isPlaying ? "Pause (Space)" : "Play (Space)"}
          onClick={handlePlayPause}
        >
          {isPlaying ? '⏸️' : '▶️'}
        </button>
        <button
          className="timeline-control-btn"
          title="Stop (K)"
          onClick={handleStop}
        >
          ⏹️
        </button>
        <button
          className="timeline-control-btn"
          title="Next frame (L or Right Arrow)"
          onClick={handleNextFrame}
        >
          ⏩
        </button>
        <button
          className="timeline-control-btn"
          title="Go to end (End)"
          onClick={handleGoToEnd}
        >
          ⏭️
        </button>
      </div>

      {/* Timecode display with duration */}
      <div className="timeline-timecode">
        <span className="current-time">{formatTime(playheadPosition)}</span>
        <span className="time-separator"> / </span>
        <span className="total-duration">{formatTime(duration)}</span>
      </div>

      {/* Go to Time button */}
      <button
        className="timeline-control-btn"
        onClick={() => setShowGoToTimeDialog(true)}
        title="Go to specific time (Ctrl/Cmd + G)"
      >
        🎯
      </button>

      {/* Zoom controls */}
      <div className="timeline-controls-group">
        <button
          className="timeline-control-btn"
          onClick={handleZoomOut}
          title="Zoom out (Ctrl/Cmd + -)"
        >
          🔍-
        </button>

        <div className="zoom-level-display">
          {Math.round(zoomLevel * 10)}%
        </div>

        <button
          className="timeline-control-btn"
          onClick={handleZoomIn}
          title="Zoom in (Ctrl/Cmd + +)"
        >
          🔍+
        </button>

        <button
          className="timeline-control-btn"
          onClick={handleFitToWindow}
          title="Fit to window"
        >
          ⊡
        </button>
      </div>

      {/* Track management */}
      <div className="timeline-controls-group timeline-track-controls">
        {/* Add Track dropdown */}
        <div className="add-track-dropdown">
          <button
            className="timeline-control-btn add-track-btn"
            onClick={() => setShowAddTrackMenu(!showAddTrackMenu)}
            title="Add new track"
          >
            + Track
          </button>

          {showAddTrackMenu && (
            <div className="add-track-menu">
              {trackTypes.map(({ type, label, icon }) => (
                <button
                  key={type}
                  className="add-track-menu-item"
                  onClick={() => handleAddTrack(type)}
                >
                  <span className="track-type-icon">{icon}</span>
                  <span>{label}</span>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Delete Track button */}
        <button
          className="timeline-control-btn add-track-btn delete-track-btn"
          onClick={handleDeleteTrack}
          title="Delete selected track (Delete)"
          disabled={!onDeleteTrack}
        >
          - Track
        </button>
      </div>

      {/* Edit mode toggles */}
      <div className="timeline-controls-group">
        <button
          className={`timeline-control-btn toggle-btn ${snapToGrid ? 'active' : ''}`}
          onClick={onToggleSnapToGrid}
          title="Snap to Grid (S) - Align edits to grid"
        >
          <span className="toggle-icon">⊡</span>
          <span className="toggle-label">Snap</span>
          <span className="toggle-shortcut">S</span>
        </button>

        <button
          className={`timeline-control-btn toggle-btn ${rippleEdit ? 'active' : ''}`}
          onClick={onToggleRippleEdit}
          title="Ripple Edit (R) - Automatically shift downstream edits"
        >
          <span className="toggle-icon">≋</span>
          <span className="toggle-label">Ripple</span>
          <span className="toggle-shortcut">R</span>
        </button>

        <button
          className={`timeline-control-btn toggle-btn ${magneticTimeline ? 'active' : ''}`}
          onClick={onToggleMagneticTimeline}
          title="Magnetic Timeline (M) - Auto-align edits to nearby content"
        >
          <span className="toggle-icon">🧲</span>
          <span className="toggle-label">Magnetic</span>
          <span className="toggle-shortcut">M</span>
        </button>
      </div>

      {/* Additional tools */}
      <div className="timeline-controls-group">
        <button
          className="timeline-control-btn toggle-btn"
          onClick={onSplit}
          title="Split clip at playhead (Ctrl/Cmd + B)"
        >
          ✂️
        </button>
        <button
          className="timeline-control-btn toggle-btn"
          onClick={onAutoMix}
          title="Apply AI Auto-Mix to all audio tracks"
        >
          ✨ Mix
        </button>

        <button
          className="timeline-control-btn toggle-btn"
          title="Delete selected (Delete)"
        >
          🗑️
        </button>
      </div>

      {/* Virtual mode toggle (for large timelines) */}
      {onToggleVirtualMode && (
        <div className="timeline-controls-group">
          <button
            className={`timeline-control-btn toggle-btn ${useVirtualMode ? 'active' : ''}`}
            onClick={onToggleVirtualMode}
            title="Toggle virtual scrolling mode"
          >
            <span className="toggle-icon">{useVirtualMode ? '⚡' : '🐌'}</span>
            <span className="toggle-label">{useVirtualMode ? 'Virtual' : 'DOM'}</span>
          </button>
        </div>
      )}

      {/* Go to Time Dialog */}
      <GoToTimeDialog
        isOpen={showGoToTimeDialog}
        onClose={() => setShowGoToTimeDialog(false)}
        onGoToTime={handleGoToTime}
        maxFrame={duration}
        fps={24}
      />
    </div>
  );
};

export default TimelineControls;

/**
 * Timeline Drop Target Component
 * 
 * Provides drop zones for timeline tracks to accept dragged assets.
 * Enhanced with multi-select support, validation, and undo/redo integration.
 * Requirements: 15.2, 15.3, 15.4, 15.7 - Drop target highlighting, asset placement, and multi-select
 */

import React, { useCallback } from 'react';
import { useDrop, DropTargetMonitor } from 'react-dnd';
import { DND_ITEM_TYPES, type DraggedAssetItem } from '../AssetLibrary/DraggableAsset';
import { useAppDispatch } from '../../store';
import { addShot, addLayer } from '../../store/slices/timelineSlice';
import type { Track, LayerType, Asset, Shot, Layer } from '../../types';
import { v4 as uuidv4 } from 'uuid';

// ============================================================================
// Types
// ============================================================================

interface TimelineDropTargetProps {
  track: Track;
  zoomLevel: number;
  onAssetDrop?: (assets: Asset[], position: number, trackType: LayerType) => void;
  children: React.ReactNode;
}

/**
 * Validates if an asset type is compatible with a track type
 */
function isAssetCompatibleWithTrack(assetType: Asset['type'] | string, trackType: LayerType): boolean {
  // Transitions track only accepts transitions
  if (trackType === 'transitions') {
    return assetType === 'template' || assetType === 'transition';
  }

  // Media track accepts most visual assets
  if (trackType === 'media') {
    return ['character', 'environment', 'prop', 'camera-preset', 'template'].includes(assetType);
  }

  // Effects track accepts visual styles and general template effects
  if (trackType === 'effects') {
    return assetType === 'visual-style' || assetType === 'template';
  }

  // Audio track accepts audio assets
  if (trackType === 'audio') {
    return assetType === 'audio' || assetType === 'camera-preset'; // Some presets might have audio
  }

  // Other tracks have specific requirements
  return false;
}

// ============================================================================
// Component
// ============================================================================

export const TimelineDropTarget: React.FC<TimelineDropTargetProps> = ({
  track,
  zoomLevel,
  onAssetDrop,
  children,
}) => {
  const dispatch = useAppDispatch();

  // Calculate drop position from mouse coordinates
  const getDropPosition = useCallback((monitor: DropTargetMonitor): number => {
    const clientOffset = monitor.getClientOffset();
    if (!clientOffset) return 0;

    // Get the timeline canvas element
    const timelineElement = document.querySelector('.timeline-canvas');
    if (!timelineElement) return 0;

    const rect = timelineElement.getBoundingClientRect();
    const relativeX = clientOffset.x - rect.left;

    // Convert pixel position to frame position
    const framePosition = Math.max(0, Math.floor(relativeX / zoomLevel));
    return framePosition;
  }, [zoomLevel]);

  // Handle asset drop
  const handleDrop = useCallback((item: DraggedAssetItem, monitor: DropTargetMonitor) => {
    const dropPosition = getDropPosition(monitor);
    const assets = [item.asset];

    // Default behavior depends on track and asset type
    assets.forEach((asset, index) => {
      const isTransition = asset.metadata?.category === 'transition' || asset.name.toLowerCase().includes('transition');
      const isEffect = asset.metadata?.category === 'effect' || asset.metadata?.category === 'lut';

      // If dropped on media/audio track, create new shot
      if (track.type === 'media' || track.type === 'audio') {
        const newShot: Shot = {
          id: `shot-${uuidv4()}`,
          name: asset.name,
          startTime: dropPosition + (index * 120),
          duration: 120,
          layers: [
            {
              id: `layer-${uuidv4()}`,
              type: track.type,
              startTime: 0,
              duration: 120,
              locked: false,
              hidden: false,
              opacity: 1,
              blendMode: 'normal',
              data: (track.type as string) === 'media' ? {
                sourceUrl: asset.thumbnailUrl || '',
                trim: { start: 0, end: 120 },
                transform: {
                  position: { x: 0, y: 0 },
                  scale: { x: 1, y: 1 },
                  rotation: 0,
                  anchor: { x: 0.5, y: 0.5 },
                },
              } : {
                sourceUrl: asset.thumbnailUrl || '',
                volume: 1.0,
                fadeIn: 0,
                fadeOut: 0,
              } as any, // TODO: Define proper type for audio layer data
            },
          ],
          referenceImages: asset.thumbnailUrl ? [{
            id: `ref-${uuidv4()}`,
            url: asset.thumbnailUrl,
            weight: 1.0,
            source: 'library',
          }] : [],
          prompt: asset.metadata?.description || `Generate ${asset.name}`,
          parameters: {
            seed: Math.floor(Math.random() * 1000000),
            denoising: 0.7,
            steps: 30,
            guidance: 7.5,
            sampler: 'euler',
            scheduler: 'normal',
          },
          generationStatus: 'pending',
        };
        dispatch(addShot(newShot));
      } else if (track.type === 'transitions' || track.type === 'effects') {
        // Find existing shot at drop position to apply transition/effect
        // This would normally be handled by a more sophisticated logic
        console.log(`Applying ${track.type} to track at position ${dropPosition}`);
        // TODO: Implement finding the shot at position and calling addLayer
      }
    });
  }, [dispatch, track, getDropPosition]);

  // Set up drop target
  const [{ isOver, canDrop }, drop] = useDrop<
    DraggedAssetItem,
    void,
    { isOver: boolean; canDrop: boolean }
  >(
    () => ({
      accept: DND_ITEM_TYPES.ASSET,
      drop: handleDrop,
      canDrop: (item) => {
        // Validate asset compatibility with track
        return isAssetCompatibleWithTrack(item.asset.type, track.type);
      },
      collect: (monitor) => ({
        isOver: monitor.isOver(),
        canDrop: monitor.canDrop(),
      }),
    }),
    [track, handleDrop]
  );

  // Determine drop target state
  const isActive = isOver && canDrop;
  const isInvalid = isOver && !canDrop;

  return (
    <div
      ref={(node) => { drop(node); }}
      className={`timeline-drop-target ${isActive ? 'drop-active' : ''} ${isInvalid ? 'drop-invalid' : ''} ${canDrop && !isOver ? 'drop-ready' : ''}`}
      style={{
        position: 'relative',
        width: '100%',
        height: '100%',
      }}
    >
      {children}

      {/* Drop indicator overlay */}
      {isActive && (
        <div className="drop-indicator">
          <div className="drop-indicator-content">
            <span className="drop-icon">📍</span>
            <span className="drop-text">Drop to add to {track.type} track</span>
          </div>
        </div>
      )}

      {/* Invalid drop indicator */}
      {isInvalid && (
        <div className="drop-indicator invalid">
          <div className="drop-indicator-content">
            <span className="drop-icon">🚫</span>
            <span className="drop-text">Cannot drop here</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default TimelineDropTarget;

/**
 * Timeline Interaction Handler
 * 
 * Handles mouse interactions on the timeline based on the active tool.
 * Integrates with toolInteractions utility to perform tool-specific operations.
 * 
 * Requirements: 2.4, 10.1-10.10
 */

import React, { useCallback, useState, useRef, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../store';
import {
  updateShot,
  deleteShot,
  addShot,
  setSelectedElements,
} from '../../store/slices/timelineSlice';
import type { Shot, Layer, ToolType } from '../../types';
import {
  handleSelectTool,
  handleShotMove,
  handleShotTrim,
  handleShotSplit,
  handleRippleEdit,
  handleRollEdit,
  handleSlipEdit,
  handleSlideEdit,
  handleAddTransition,
  handleAddText,
  handleAddKeyframe,
  findShotAtFrame,
  findAdjacentShots,
  getShotEdge,
} from '../../utils/toolInteractions';

// ============================================================================
// Types
// ============================================================================

interface TimelineInteractionHandlerProps {
  children: React.ReactNode;
  zoomLevel: number;
  onShotSelect: (shotId: string, multiSelect: boolean) => void;
}

interface DragState {
  isDragging: boolean;
  shotId: string | null;
  startX: number;
  startFrame: number;
  edge: 'start' | 'end' | 'middle' | null;
  initialDuration: number;
  initialStartTime: number;
}

// ============================================================================
// Component
// ============================================================================

export const TimelineInteractionHandler: React.FC<TimelineInteractionHandlerProps> = ({
  children,
  zoomLevel,
  onShotSelect,
}) => {
  const dispatch = useAppDispatch();
  const containerRef = useRef<HTMLDivElement>(null);
  
  const { activeTool } = useAppSelector((state) => state.tools);
  const { shots, playheadPosition, selectedElements } = useAppSelector((state) => state.timeline);
  
  const [dragState, setDragState] = useState<DragState>({
    isDragging: false,
    shotId: null,
    startX: 0,
    startFrame: 0,
    edge: null,
    initialDuration: 0,
    initialStartTime: 0,
  });
  
  const [showDurationTooltip, setShowDurationTooltip] = useState(false);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const [tooltipText, setTooltipText] = useState('');
  
  // ============================================================================
  // Tool-Specific Handlers
  // ============================================================================
  
  /**
   * Handle Select Tool interactions
   */
  const handleSelectToolInteraction = useCallback((
    shotId: string,
    multiSelect: boolean,
    isDrag: boolean,
    deltaFrames: number
  ) => {
    if (isDrag && deltaFrames !== 0) {
      // Drag to move
      const result = handleShotMove(shotId, deltaFrames, shots);
      if (result) {
        dispatch(updateShot({
          id: result.shotId,
          updates: { startTime: result.newStartTime },
        }));
      }
    } else {
      // Click to select
      const newSelection = handleSelectTool(shotId, multiSelect, selectedElements);
      dispatch(setSelectedElements(newSelection));
      onShotSelect(shotId, multiSelect);
    }
  }, [shots, selectedElements, dispatch, onShotSelect]);
  
  /**
   * Handle Trim Tool interactions
   */
  const handleTrimToolInteraction = useCallback((
    shotId: string,
    edge: 'start' | 'end',
    deltaFrames: number
  ) => {
    const result = handleShotTrim(shotId, edge, deltaFrames, shots);
    if (result) {
      const updates: Partial<Shot> = { duration: result.newDuration };
      if (result.newStartTime !== undefined) {
        updates.startTime = result.newStartTime;
      }
      dispatch(updateShot({ id: result.shotId, updates }));
      
      // Show duration tooltip
      setTooltipText(`Duration: ${result.newDuration} frames`);
      setShowDurationTooltip(true);
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Cut/Split Tool interactions
   */
  const handleCutToolInteraction = useCallback((
    shotId: string,
    splitFrame: number
  ) => {
    const result = handleShotSplit(shotId, splitFrame, shots);
    if (result) {
      // Delete original shot
      dispatch(deleteShot(result.originalShotId));
      
      // Add two new shots
      dispatch(addShot(result.newShots[0]));
      dispatch(addShot(result.newShots[1]));
      
      // Select the right shot
      dispatch(setSelectedElements([result.newShots[1].id]));
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Ripple Edit Tool interactions
   */
  const handleRippleToolInteraction = useCallback((
    shotId: string,
    edge: 'start' | 'end',
    deltaFrames: number
  ) => {
    const result = handleRippleEdit(shotId, edge, deltaFrames, shots);
    if (result) {
      // Update the trimmed shot
      dispatch(updateShot({
        id: result.shotId,
        updates: { duration: result.newDuration },
      }));
      
      // Update affected shots
      result.affectedShots.forEach((affected: { shotId: string; newStartTime: number }) => {
        dispatch(updateShot({
          id: affected.shotId,
          updates: { startTime: affected.newStartTime },
        }));
      });
      
      setTooltipText(`Ripple: ${result.affectedShots.length} shots affected`);
      setShowDurationTooltip(true);
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Roll Edit Tool interactions
   */
  const handleRollToolInteraction = useCallback((
    leftShotId: string,
    rightShotId: string,
    deltaFrames: number
  ) => {
    const result = handleRollEdit(leftShotId, rightShotId, deltaFrames, shots);
    if (result) {
      // Update left shot
      dispatch(updateShot({
        id: result.leftShotId,
        updates: { duration: result.leftNewDuration },
      }));
      
      // Update right shot
      dispatch(updateShot({
        id: result.rightShotId,
        updates: {
          startTime: result.rightNewStartTime,
          duration: result.rightNewDuration,
        },
      }));
      
      setTooltipText(`Roll: Junction adjusted`);
      setShowDurationTooltip(true);
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Slip Edit Tool interactions
   */
  const handleSlipToolInteraction = useCallback((
    shotId: string,
    deltaFrames: number
  ) => {
    const result = handleSlipEdit(shotId, deltaFrames, shots);
    if (result) {
      const shot = shots.find((s: Shot) => s.id === shotId);
      if (shot) {
        const updatedLayers = shot.layers.map((layer: Layer) => {
          if (layer.type === 'media') {
            return {
              ...layer,
              data: {
                ...layer.data,
                trim: {
                  start: result.newTrimStart,
                  end: result.newTrimEnd,
                },
              },
            };
          }
          return layer;
        });
        
        dispatch(updateShot({
          id: shotId,
          updates: { layers: updatedLayers },
        }));
        
        setTooltipText(`Slip: Content adjusted`);
        setShowDurationTooltip(true);
      }
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Slide Edit Tool interactions
   */
  const handleSlideToolInteraction = useCallback((
    shotId: string,
    deltaFrames: number
  ) => {
    const result = handleSlideEdit(shotId, deltaFrames, shots);
    if (result) {
      // Update the slid shot
      dispatch(updateShot({
        id: result.shotId,
        updates: { startTime: result.newStartTime },
      }));
      
      // Update affected shots
      result.affectedShots.forEach((affected: { shotId: string; newStartTime: number }) => {
        dispatch(updateShot({
          id: affected.shotId,
          updates: { startTime: affected.newStartTime },
        }));
      });
      
      setTooltipText(`Slide: ${result.affectedShots.length} shots adjusted`);
      setShowDurationTooltip(true);
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Transition Tool interactions
   */
  const handleTransitionToolInteraction = useCallback((
    shotId: string
  ) => {
    const shot = shots.find((s) => s.id === shotId);
    if (!shot) return;
    
    const { left, right } = findAdjacentShots(shotId, shots);
    
    if (left && shot) {
      // Add transition between left and current shot
      const result = handleAddTransition(left.id, shotId, 'fade', 30, shots);
      if (result) {
        const updatedShot = shots.find((s) => s.id === result.shotId);
        if (updatedShot) {
          dispatch(updateShot({
            id: result.shotId,
            updates: {
              layers: [...updatedShot.layers, result.layer],
            },
          }));
        }
      }
    } else if (right) {
      // Add transition between current and right shot
      const result = handleAddTransition(shotId, right.id, 'fade', 30, shots);
      if (result) {
        const updatedShot = shots.find((s) => s.id === result.shotId);
        if (updatedShot) {
          dispatch(updateShot({
            id: result.shotId,
            updates: {
              layers: [...updatedShot.layers, result.layer],
            },
          }));
        }
      }
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Text Tool interactions
   */
  const handleTextToolInteraction = useCallback((
    clickFrame: number
  ) => {
    const shot = findShotAtFrame(clickFrame, shots);
    if (!shot) return;
    
    const result = handleAddText(shot.id, clickFrame, shots);
    if (result) {
      // Add the new text layer to the shot
      dispatch(updateShot({
        id: result.shotId,
        updates: {
          layers: [...shot.layers, result.layer],
        },
      }));
      
      // Select the newly created text layer for editing
      // This will make the TextEditor panel show the new layer
      const store = require('../../store').store;
      const state = store.getState();
      
      // Log for debugging
      console.log('Text layer added:', {
        layerId: result.layer.id,
        shotId: result.shotId,
        content: (result.layer.data as any).content
      });
      
      // In a full implementation, we would:
      // 1. Set the selected text layer in the store
      // 2. Open the text editor panel
      // 3. Show a toast notification
      
      // For now, dispatch a notification action if it exists
      try {
        // Try to set the text layer as selected if the action exists
        const { setSelectedTextLayer } = require('../../store/slices/textLayersSlice');
        if (setSelectedTextLayer) {
          dispatch(setSelectedTextLayer(result.layer.id));
        }
      } catch (e) {
        // Action doesn't exist, ignore
      }
    }
  }, [shots, dispatch]);
  
  /**
   * Handle Keyframe Tool interactions
   */
  const handleKeyframeToolInteraction = useCallback((
    clickFrame: number
  ) => {
    const shot = findShotAtFrame(clickFrame, shots);
    if (!shot) return;
    
    // Default to opacity property
    const result = handleAddKeyframe(shot.id, clickFrame, 'opacity', 1.0, shots);
    if (result) {
      const existingLayerIndex = shot.layers.findIndex((l) => l.id === result.layer.id);
      
      if (existingLayerIndex !== -1) {
        // Update existing layer
        const updatedLayers = [...shot.layers];
        updatedLayers[existingLayerIndex] = result.layer;
        
        dispatch(updateShot({
          id: result.shotId,
          updates: { layers: updatedLayers },
        }));
      } else {
        // Add new layer
        dispatch(updateShot({
          id: result.shotId,
          updates: {
            layers: [...shot.layers, result.layer],
          },
        }));
      }
      
      console.log('Keyframe added at frame', clickFrame);
    }
  }, [shots, dispatch]);
  
  // ============================================================================
  // Mouse Event Handlers
  // ============================================================================
  
  const handleMouseDown = useCallback((e: React.MouseEvent, shotId: string, shotLeft: number, shotWidth: number) => {
    e.stopPropagation();
    
    const shot = shots.find((s) => s.id === shotId);
    if (!shot) return;
    
    const multiSelect = e.ctrlKey || e.metaKey;
    
    // Determine edge for trim/ripple/roll tools
    const edge = getShotEdge(shotId, e.clientX, shotLeft, shotWidth);
    
    // Handle tool-specific interactions
    switch (activeTool) {
      case 'select':
        if (edge === 'middle') {
          // Start drag to move
          setDragState({
            isDragging: true,
            shotId,
            startX: e.clientX,
            startFrame: shot.startTime,
            edge: 'middle',
            initialDuration: shot.duration,
            initialStartTime: shot.startTime,
          });
        } else {
          // Just select
          handleSelectToolInteraction(shotId, multiSelect, false, 0);
        }
        break;
      
      case 'trim':
        if (edge !== 'middle') {
          setDragState({
            isDragging: true,
            shotId,
            startX: e.clientX,
            startFrame: shot.startTime,
            edge,
            initialDuration: shot.duration,
            initialStartTime: shot.startTime,
          });
        }
        break;
      
      case 'cut':
        // Split at playhead
        handleCutToolInteraction(shotId, playheadPosition);
        break;
      
      case 'ripple':
        if (edge !== 'middle') {
          setDragState({
            isDragging: true,
            shotId,
            startX: e.clientX,
            startFrame: shot.startTime,
            edge,
            initialDuration: shot.duration,
            initialStartTime: shot.startTime,
          });
        }
        break;
      
      case 'roll':
        if (edge === 'end') {
          const { right } = findAdjacentShots(shotId, shots);
          if (right) {
            setDragState({
              isDragging: true,
              shotId: `${shotId}|${right.id}`, // Store both IDs
              startX: e.clientX,
              startFrame: shot.startTime,
              edge: 'end',
              initialDuration: shot.duration,
              initialStartTime: shot.startTime,
            });
          }
        }
        break;
      
      case 'slip':
        if (edge === 'middle') {
          setDragState({
            isDragging: true,
            shotId,
            startX: e.clientX,
            startFrame: shot.startTime,
            edge: 'middle',
            initialDuration: shot.duration,
            initialStartTime: shot.startTime,
          });
        }
        break;
      
      case 'slide':
        if (edge === 'middle') {
          setDragState({
            isDragging: true,
            shotId,
            startX: e.clientX,
            startFrame: shot.startTime,
            edge: 'middle',
            initialDuration: shot.duration,
            initialStartTime: shot.startTime,
          });
        }
        break;
      
      case 'transition':
        handleTransitionToolInteraction(shotId);
        break;
      
      default:
        // Default to select behavior
        handleSelectToolInteraction(shotId, multiSelect, false, 0);
        break;
    }
  }, [
    activeTool,
    shots,
    playheadPosition,
    handleSelectToolInteraction,
    handleCutToolInteraction,
    handleTransitionToolInteraction,
  ]);
  
  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!dragState.isDragging || !dragState.shotId) return;
    
    const deltaX = e.clientX - dragState.startX;
    const deltaFrames = Math.round(deltaX / zoomLevel);
    
    if (deltaFrames === 0) return;
    
    // Update tooltip position
    setTooltipPosition({ x: e.clientX + 10, y: e.clientY - 30 });
    
    // Handle tool-specific drag operations
    switch (activeTool) {
      case 'select':
        if (dragState.edge === 'middle') {
          handleSelectToolInteraction(dragState.shotId, false, true, deltaFrames);
        }
        break;
      
      case 'trim':
        if (dragState.edge) {
          handleTrimToolInteraction(dragState.shotId, dragState.edge, deltaFrames);
        }
        break;
      
      case 'ripple':
        if (dragState.edge) {
          handleRippleToolInteraction(dragState.shotId, dragState.edge, deltaFrames);
        }
        break;
      
      case 'roll':
        if (dragState.shotId.includes('|')) {
          const [leftId, rightId] = dragState.shotId.split('|');
          handleRollToolInteraction(leftId, rightId, deltaFrames);
        }
        break;
      
      case 'slip':
        handleSlipToolInteraction(dragState.shotId, deltaFrames);
        break;
      
      case 'slide':
        handleSlideToolInteraction(dragState.shotId, deltaFrames);
        break;
    }
  }, [
    dragState,
    zoomLevel,
    activeTool,
    handleSelectToolInteraction,
    handleTrimToolInteraction,
    handleRippleToolInteraction,
    handleRollToolInteraction,
    handleSlipToolInteraction,
    handleSlideToolInteraction,
  ]);
  
  const handleMouseUp = useCallback(() => {
    setDragState({
      isDragging: false,
      shotId: null,
      startX: 0,
      startFrame: 0,
      edge: null,
      initialDuration: 0,
      initialStartTime: 0,
    });
    
    // Hide tooltip after a delay
    setTimeout(() => {
      setShowDurationTooltip(false);
    }, 1000);
  }, []);
  
  // Handle timeline click for text and keyframe tools
  const handleTimelineClick = useCallback((e: React.MouseEvent) => {
    if (!containerRef.current) return;
    
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const clickFrame = Math.round(x / zoomLevel);
    
    switch (activeTool) {
      case 'text':
        handleTextToolInteraction(clickFrame);
        break;
      
      case 'keyframe':
        handleKeyframeToolInteraction(clickFrame);
        break;
    }
  }, [activeTool, zoomLevel, handleTextToolInteraction, handleKeyframeToolInteraction]);
  
  // Set up global mouse event listeners
  useEffect(() => {
    if (dragState.isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      
      return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
      };
    }
  }, [dragState.isDragging, handleMouseMove, handleMouseUp]);
  
  // ============================================================================
  // Render
  // ============================================================================
  
  return (
    <div
      ref={containerRef}
      className="timeline-interaction-handler"
      onClick={handleTimelineClick}
    >
      {children}
      
      {/* Duration Tooltip */}
      {showDurationTooltip && (
        <div
          className="timeline-tooltip"
          style={{
            position: 'fixed',
            left: `${tooltipPosition.x}px`,
            top: `${tooltipPosition.y}px`,
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            color: 'white',
            padding: '4px 8px',
            borderRadius: '4px',
            fontSize: '12px',
            pointerEvents: 'none',
            zIndex: 10000,
          }}
        >
          {tooltipText}
        </div>
      )}
    </div>
  );
};

export default TimelineInteractionHandler;

/**
 * TimelineRegions Component
 * 
 * Renders regions on the timeline with drag and resize support.
 * Regions can be used for work areas, selections, loops, etc.
 * 
 * Requirements: 3.6, 3.7, 3.8
 */

import React, { useState, useCallback, useRef, useEffect } from 'react';
import {
  TimelineRegion,
  RegionType,
  getRegionColor,
  isPositionInRegion,
} from './markerTypes';

interface TimelineRegionsProps {
  regions: TimelineRegion[];
  zoomLevel: number;
  height: number;
  selectedIds?: string[];
  onRegionClick?: (region: TimelineRegion) => void;
  onRegionDoubleClick?: (region: TimelineRegion) => void;
  onRegionDragStart?: (region: TimelineRegion) => void;
  onRegionDrag?: (region: TimelineRegion, newStart: number) => void;
  onRegionResizeStart?: (region: TimelineRegion, edge: 'start' | 'end') => void;
  onRegionResize?: (region: TimelineRegion, newStart: number, newEnd: number) => void;
  onRegionResizeEnd?: (region: TimelineRegion) => void;
  onRegionDragEnd?: (region: TimelineRegion) => void;
  onCreateRegion?: (start: number, end: number) => void;
}

export const TimelineRegions: React.FC<TimelineRegionsProps> = ({
  regions,
  zoomLevel,
  height,
  selectedIds = [],
  onRegionClick,
  onRegionDoubleClick,
  onRegionDragStart,
  onRegionDrag,
  onRegionResizeStart,
  onRegionResize,
  onRegionResizeEnd,
  onRegionDragEnd,
  onCreateRegion,
}) => {
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [resizingId, setResizingId] = useState<string | null>(null);
  const [resizeEdge, setResizeEdge] = useState<'start' | 'end'>('start');
  const [dragStartX, setDragStartX] = useState(0);
  const [dragStartStart, setDragStartStart] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // Handle region click
  const handleRegionClick = useCallback((region: TimelineRegion, e: React.MouseEvent) => {
    e.stopPropagation();
    if (onRegionClick) {
      onRegionClick(region);
    }
  }, [onRegionClick]);

  // Handle region double click
  const handleRegionDoubleClick = useCallback((region: TimelineRegion, e: React.MouseEvent) => {
    e.stopPropagation();
    if (onRegionDoubleClick) {
      onRegionDoubleClick(region);
    }
  }, [onRegionDoubleClick]);

  // Handle region drag start
  const handleRegionDragStart = useCallback((region: TimelineRegion, e: React.MouseEvent) => {
    e.stopPropagation();
    setDraggingId(region.id);
    setDragStartX(e.clientX);
    setDragStartStart(region.start);
    if (onRegionDragStart) {
      onRegionDragStart(region);
    }
  }, [onRegionDragStart]);

  // Handle resize handle mousedown
  const handleResizeStart = useCallback((region: TimelineRegion, edge: 'start' | 'end', e: React.MouseEvent) => {
    e.stopPropagation();
    setResizingId(region.id);
    setResizeEdge(edge);
    setDragStartX(e.clientX);
    setDragStartStart(edge === 'start' ? region.start : region.end);
    if (onRegionResizeStart) {
      onRegionResizeStart(region, edge);
    }
  }, [onRegionResizeStart]);

  // Handle mouse move for dragging and resizing
  useEffect(() => {
    if (!draggingId && !resizingId) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - dragStartX;
      const deltaFrames = Math.round(deltaX / zoomLevel);

      if (draggingId) {
        const region = regions.find(r => r.id === draggingId);
        if (region) {
          const newStart = Math.max(0, dragStartStart + deltaFrames);
          if (onRegionDrag) {
            onRegionDrag(region, newStart);
          }
        }
      } else if (resizingId) {
        const region = regions.find(r => r.id === resizingId);
        if (region) {
          const newStart = region.start;
          const newEnd = region.end;
          
          if (resizeEdge === 'start') {
            const calculatedStart = Math.max(0, Math.min(dragStartStart + deltaFrames, region.end - 1));
            if (onRegionResize) {
              onRegionResize(region, calculatedStart, newEnd);
            }
          } else {
            const calculatedEnd = Math.max(region.start + 1, dragStartStart + deltaFrames);
            if (onRegionResize) {
              onRegionResize(region, newStart, calculatedEnd);
            }
          }
        }
      }
    };

    const handleMouseUp = () => {
      if (draggingId) {
        const region = regions.find(r => r.id === draggingId);
        if (region && onRegionDragEnd) {
          onRegionDragEnd(region);
        }
        setDraggingId(null);
      }
      if (resizingId) {
        const region = regions.find(r => r.id === resizingId);
        if (region && onRegionResizeEnd) {
          onRegionResizeEnd(region);
        }
        setResizingId(null);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggingId, resizingId, resizeEdge, dragStartX, dragStartStart, regions, zoomLevel, onRegionDrag, onRegionResize, onRegionDragEnd, onRegionResizeEnd]);

  // Handle container click to create new region
  const handleContainerClick = useCallback((e: React.MouseEvent) => {
    if (!containerRef.current || !onCreateRegion) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const position = Math.round(x / zoomLevel);

    if (position >= 0 && !e.shiftKey) {
      // Simple click - don't create region
      return;
    }

    if (e.shiftKey && onCreateRegion) {
      // Shift+click to create a region of default length (e.g., 60 frames / 2.5 seconds)
      const defaultLength = 60;
      const start = Math.max(0, position - Math.round(defaultLength / 2));
      const end = start + defaultLength;
      onCreateRegion(start, end);
    }
  }, [zoomLevel, onCreateRegion]);

  // Get region label based on type
  const getRegionLabel = (type: RegionType): string => {
    const labels: Record<RegionType, string> = {
      work: 'Work Area',
      selection: 'Selection',
      gap: 'Gap',
      loop: 'Loop',
      highlight: 'Highlight',
      comment: 'Comment',
    };
    return labels[type] || 'Region';
  };

  // Sort regions by start position
  const sortedRegions = [...regions].sort((a, b) => a.start - b.start);

  return (
    <div 
      ref={containerRef}
      className="timeline-regions"
      style={{ height, position: 'relative' }}
      onClick={handleContainerClick}
      role="list"
      aria-label="Timeline regions"
    >
      {sortedRegions.map((region) => {
        const left = region.start * zoomLevel;
        const width = (region.end - region.start) * zoomLevel;
        const isSelected = selectedIds.includes(region.id);
        const isDragging = draggingId === region.id;
        const isResizing = resizingId === region.id;
        const color = getRegionColor(region.type, region.color);

        return (
          <div
            key={region.id}
            className={`timeline-region ${isSelected ? 'selected' : ''} ${isDragging ? 'dragging' : ''} ${isResizing ? 'resizing' : ''} type-${region.type}`}
            style={{
              left,
              width,
              backgroundColor: color,
              borderColor: color.replace('0.2', '0.8').replace('0.3', '0.8'),
            }}
            onClick={(e) => handleRegionClick(region, e)}
            onDoubleClick={(e) => handleRegionDoubleClick(region, e)}
            onMouseDown={(e) => handleRegionDragStart(region, e)}
            role="listitem"
            aria-label={`${region.label || getRegionLabel(region.type)} from frame ${region.start} to ${region.end}`}
            tabIndex={0}
          >
            {/* Resize handle - start */}
            <div 
              className="region-resize-handle start"
              onMouseDown={(e) => handleResizeStart(region, 'start', e)}
              title="Drag to resize start"
            />

            {/* Region content */}
            <div className="region-content">
              {(region.label || isSelected) && (
                <div className="region-label">
                  {region.label || getRegionLabel(region.type)}
                </div>
              )}
              {region.description && (
                <div className="region-description">{region.description}</div>
              )}
            </div>

            {/* Resize handle - end */}
            <div 
              className="region-resize-handle end"
              onMouseDown={(e) => handleResizeStart(region, 'end', e)}
              title="Drag to resize end"
            />

            {/* Lock indicator */}
            {region.isLocked && (
              <div className="region-locked-indicator" title="Region is locked">
                🔒
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

// Export for use in other components
export default TimelineRegions;

/**
 * Track Header Component
 * 
 * Displays track information, controls, and handles for track management.
 * Supports drag-and-drop reordering, vertical resizing, and audio track controls.
 * 
 * Requirements: 1.3, 1.4, 1.5, 1.6, 1.7
 */

import React, { useCallback, useState, useRef, useEffect } from 'react';
import type { Track, LayerType } from '../../types';

interface TrackHeaderProps {
  track: Track;
  index: number;
  isHovered: boolean;
  isDragging: boolean;
  isDropTarget: boolean;
  onHover: (id: string | null) => void;
  onLockToggle: () => void;
  onHideToggle: () => void;
  onResize: (newHeight: number) => void;
  onReorder: (fromIndex: number, toIndex: number) => void;
  onMuteToggle?: () => void;
  onSoloToggle?: () => void;
  onRecordToggle?: () => void;
  zoomLevel: number;
}

// Track type configuration
export const TRACK_CONFIG: Record<LayerType, { color: string; icon: string; name: string; minHeight: number }> = {
  media: { color: '#4A90E2', icon: 'film', name: 'Media', minHeight: 40 },
  audio: { color: '#50C878', icon: 'volume', name: 'Audio', minHeight: 30 },
  effects: { color: '#9B59B6', icon: 'magic', name: 'Effects', minHeight: 30 },
  transitions: { color: '#E67E22', icon: 'shuffle', name: 'Transitions', minHeight: 25 },
  text: { color: '#F39C12', icon: 'text', name: 'Text', minHeight: 30 },
  keyframes: { color: '#E74C3C', icon: 'key', name: 'Keyframes', minHeight: 25 },
};

export const TrackHeader: React.FC<TrackHeaderProps> = ({
  track,
  index,
  isHovered,
  isDragging,
  isDropTarget,
  onHover,
  onLockToggle,
  onHideToggle,
  onResize,
  onReorder,
  onMuteToggle,
  onSoloToggle,
  onRecordToggle,
  zoomLevel,
}) => {
  const [isResizing, setIsResizing] = useState(false);
  const [resizeStartY, setResizeStartY] = useState(0);
  const [resizeStartHeight, setResizeStartHeight] = useState(track.height);
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
  const headerRef = useRef<HTMLDivElement>(null);

  const config = TRACK_CONFIG[track.type] || { color: '#888888', icon: '📁', name: track.type, minHeight: 30 };

  // Handle resize start
  const handleResizeStart = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
    setResizeStartY(e.clientY);
    setResizeStartHeight(track.height);
  }, [track.height]);

  // Handle resize move
  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaY = e.clientY - resizeStartY;
      const newHeight = Math.max(config.minHeight, resizeStartHeight + deltaY);
      onResize(newHeight);
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isResizing, resizeStartY, resizeStartHeight, onResize, config.minHeight]);

  // Handle drag start for reordering
  const handleDragStart = useCallback((e: React.DragEvent) => {
    e.dataTransfer.setData('trackIndex', index.toString());
    e.dataTransfer.effectAllowed = 'move';
    if (headerRef.current) {
      headerRef.current.classList.add('dragging');
    }
  }, [index]);

  // Handle drag end
  const handleDragEnd = useCallback(() => {
    setDragOverIndex(null);
    if (headerRef.current) {
      headerRef.current.classList.remove('dragging');
    }
  }, []);

  // Handle drag over for reordering
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }, []);

  // Handle drag enter
  const handleDragEnter = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    // Calculate which index we're dragging over
    // This will be handled by the parent component
  }, []);

  // Handle drop for reordering
  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    const fromIndex = parseInt(e.dataTransfer.getData('trackIndex'), 10);
    if (!isNaN(fromIndex) && fromIndex !== index) {
      onReorder(fromIndex, index);
    }
    setDragOverIndex(null);
  }, [index, onReorder]);

  // Get audio-specific state
  const isAudioTrack = track.type === 'audio';
  // For demo, we'll track mute/solo state locally (would normally come from track state)
  const [isMuted, setIsMuted] = useState(false);
  const [isSolo, setIsSolo] = useState(false);

  const handleMuteClick = useCallback(() => {
    setIsMuted(!isMuted);
    onMuteToggle?.();
  }, [isMuted, onMuteToggle]);

  const handleSoloClick = useCallback(() => {
    setIsSolo(!isSolo);
    onSoloToggle?.();
  }, [isSolo, onSoloToggle]);

  return (
    <div
      ref={headerRef}
      className={`
        track-header 
        ${track.locked ? 'locked' : ''} 
        ${track.hidden ? 'hidden' : ''} 
        ${isHovered ? 'hovered' : ''}
        ${isDragging ? 'dragging' : ''}
        ${isDropTarget ? 'drop-target' : ''}
        ${isResizing ? 'resizing' : ''}
      `}
      style={{
        height: track.height,
        backgroundColor: track.locked 
          ? 'var(--bg-locked, #1a1a1a)' 
          : isDropTarget 
            ? 'var(--accent-color, #4A90E2)' 
            : 'var(--bg-secondary, #2a2a2a)',
        opacity: track.hidden ? 0.5 : 1,
      }}
      draggable={!track.locked && !isResizing}
      onMouseEnter={() => onHover(track.id)}
      onMouseLeave={() => onHover(null)}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      {/* Drag handle (visible on hover) */}
      <div className="track-drag-handle" title="Drag to reorder">
        ⋮⋮
      </div>

      {/* Track icon */}
      <div className="track-icon" title={config.name}>
        <span className="track-icon-emoji">{config.icon}</span>
      </div>

      {/* Track name */}
      <div className="track-name">
        {config.name}
        {track.hidden && ' (Hidden)'}
        {track.locked && ' (Locked)'}
      </div>

      {/* Track controls */}
      <div className="track-controls">
        {/* Lock button */}
        <button
          className={`track-control-btn ${track.locked ? 'active' : ''}`}
          onClick={onLockToggle}
          title={track.locked ? 'Unlock track' : 'Lock track'}
          disabled={track.hidden}
        >
          <span className="btn-icon">{track.locked ? '🔒' : '🔓'}</span>
        </button>

        {/* Hide button */}
        <button
          className={`track-control-btn ${track.hidden ? 'active' : ''}`}
          onClick={onHideToggle}
          title={track.hidden ? 'Show track' : 'Hide track'}
        >
          <span className="btn-icon">{track.hidden ? '👁️' : '👁️'}</span>
        </button>

        {/* Audio track controls */}
        {isAudioTrack && (
          <>
            {/* Mute button */}
            <button
              className={`track-control-btn audio-btn mute-btn ${isMuted ? 'active' : ''}`}
              onClick={handleMuteClick}
              title={isMuted ? 'Unmute track' : 'Mute track'}
            >
              <span className="btn-icon">M</span>
            </button>

            {/* Solo button */}
            <button
              className={`track-control-btn audio-btn solo-btn ${isSolo ? 'active' : ''}`}
              onClick={handleSoloClick}
              title={isSolo ? 'Unsolo track' : 'Solo track'}
            >
              <span className="btn-icon">S</span>
            </button>

            {/* Record arm button */}
            {onRecordToggle && (
              <button
                className="track-control-btn audio-btn record-btn"
                title="Record arm track"
              >
                <span className="btn-icon">⏺</span>
              </button>
            )}
          </>
        )}
      </div>

      {/* Track color indicator */}
      <div
        className="track-color-indicator"
        style={{ backgroundColor: track.color }}
      />

      {/* Resize handle */}
      <div
        className={`track-resize-handle ${isResizing ? 'active' : ''}`}
        onMouseDown={handleResizeStart}
        title="Drag to resize track height"
      >
        <div className="resize-grip" />
      </div>
    </div>
  );
};

export default TrackHeader;

/**
 * VirtualTimelineCanvas Component
 * 
 * High-performance timeline canvas using @tanstack/react-virtual for virtual scrolling
 * and canvas-based rendering for efficient handling of large timelines (1000+ shots).
 * Supports shot thumbnails, multiple layers, layer stacking, and layer selection.
 * 
 * Requirements: 1.1, 1.3, 1.8, 4.3, 9.1, 9.2, 9.3, 9.4, 9.5, 9.7
 */

import React, { useRef, useEffect, useCallback, useMemo, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { Track, Shot, Layer, LayerType } from '../../types';

// ============================================================================
// Constants
// ============================================================================

// Track type configuration with colors and icons
export const TRACK_CONFIG: Record<LayerType, { color: string; icon: string; height: number; name: string }> = {
  media: { color: '#4A90E2', icon: '🎬', height: 60, name: 'Media' },
  audio: { color: '#50C878', icon: '🔊', height: 40, name: 'Audio' },
  effects: { color: '#9B59B6', icon: '✨', height: 40, name: 'Effects' },
  transitions: { color: '#E67E22', icon: '↔️', height: 30, name: 'Transitions' },
  text: { color: '#F39C12', icon: '📝', height: 40, name: 'Text' },
  keyframes: { color: '#E74C3C', icon: '🔑', height: 30, name: 'Keyframes' },
};

// Layer type configuration
export const LAYER_ICONS: Record<LayerType, string> = {
  media: '🎬',
  audio: '🔊',
  effects: '✨',
  transitions: '↔️',
  text: '📝',
  keyframes: '🔑',
};

// Timeline rendering constants
const SHOT_CORNER_RADIUS = 4;
const SHOT_PADDING = 2;
const LAYER_STACK_HEIGHT = 26;
const MIN_SHOT_WIDTH = 20;
const PLAYHEAD_WIDTH = 2;
const THUMBNAIL_HEIGHT = 20;
const THUMBNAIL_WIDTH = 40;

// ============================================================================
// Types
// ============================================================================

interface VirtualTimelineCanvasProps {
  /** Array of tracks to render */
  tracks: Track[];
  /** Array of shots to display */
  shots: Shot[];
  /** Current zoom level (pixels per frame) */
  zoomLevel: number;
  /** Current playhead position in frames */
  playheadPosition: number;
  /** Currently selected element IDs */
  selectedElements: string[];
  /** Timeline width in pixels */
  timelineWidth: number;
  /** Function to handle shot selection */
  onShotSelect: (shotId: string, multiSelect: boolean) => void;
  /** Function to handle layer selection */
  onLayerSelect?: (shotId: string, layerId: string, multiSelect: boolean) => void;
  /** Function to handle shot move */
  onShotMove?: (shotId: string, newStartTime: number) => void;
  /** Function to handle shot resize */
  onShotResize?: (shotId: string, newDuration: number, edge: 'start' | 'end') => void;
  /** Current scroll offset */
  scrollLeft?: number;
  /** Whether playback is active */
  isPlaying?: boolean;
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Get shots that have layers matching the specified track type
 */
export function getTrackShots(shots: Shot[], trackType: LayerType): Array<{ shot: Shot; layer: Layer }> {
  const result: Array<{ shot: Shot; layer: Layer }> = [];
  
  shots.forEach((shot) => {
    shot.layers
      .filter((layer) => layer.type === trackType)
      .forEach((layer) => {
        result.push({ shot, layer });
      });
  });
  
  return result;
}

/**
 * Get layer index for stacking within a shot
 */
function getLayerIndex(shot: Shot, trackType: LayerType, targetLayer: Layer): number {
  return shot.layers
    .filter((l) => l.type === trackType)
    .indexOf(targetLayer);
}

/**
 * Format timecode from frame number
 */
function formatTimecode(frame: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frame / fps);
  const seconds = totalSeconds % 60;
  const minutes = Math.floor(totalSeconds / 60);
  const frames = frame % fps;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}:${String(frames).padStart(2, '0')}`;
}

/**
 * Draw grid lines on canvas
 */
function drawGridLines(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  zoomLevel: number,
  fps: number = 24
): void {
  // Draw vertical grid lines based on zoom level
  const gridSpacing = zoomLevel >= 50 ? zoomLevel : zoomLevel >= 20 ? zoomLevel * 5 : zoomLevel * 10;
  const majorGridSpacing = gridSpacing * 10;
  
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
  ctx.lineWidth = 1;
  
  // Minor grid lines
  for (let x = 0; x <= width; x += gridSpacing) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }
  
  // Major grid lines with time labels
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
  for (let x = 0; x <= width; x += majorGridSpacing) {
    const frame = Math.round(x / zoomLevel);
    const timecode = formatTimecode(frame, fps);
    
    // Draw line
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
    
    // Draw time label
    ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.font = '10px SF Mono, Monaco, Consolas, monospace';
    ctx.fillText(timecode, x + 4, 12);
  }
}

/**
 * Draw shot thumbnail on canvas
 */
function drawThumbnail(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  thumbnailUrl?: string
): void {
  // Draw thumbnail background
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x + 2, y + 2, THUMBNAIL_WIDTH, THUMBNAIL_HEIGHT);
  
  // Draw placeholder or actual thumbnail
  if (thumbnailUrl) {
    // In a real implementation, this would draw the actual image
    // For now, draw a placeholder pattern
    ctx.fillStyle = '#333';
    ctx.fillRect(x + 4, y + 4, THUMBNAIL_WIDTH - 8, THUMBNAIL_HEIGHT - 8);
  } else {
    // Draw placeholder icon
    ctx.fillStyle = '#333';
    ctx.fillRect(x + 4, y + 4, THUMBNAIL_WIDTH - 8, THUMBNAIL_HEIGHT - 8);
    
    // Draw play icon
    ctx.fillStyle = '#666';
    ctx.beginPath();
    ctx.moveTo(x + THUMBNAIL_WIDTH / 2 - 4, y + THUMBNAIL_HEIGHT / 2 - 6);
    ctx.lineTo(x + THUMBNAIL_WIDTH / 2 + 6, y + THUMBNAIL_HEIGHT / 2);
    ctx.lineTo(x + THUMBNAIL_WIDTH / 2 - 4, y + THUMBNAIL_HEIGHT / 2 + 6);
    ctx.closePath();
    ctx.fill();
  }
}

/**
 * Draw a layer on the canvas
 */
function drawLayer(
  ctx: CanvasRenderingContext2D,
  shot: Shot,
  layer: Layer,
  trackType: LayerType,
  trackHeight: number,
  zoomLevel: number,
  isSelected: boolean,
  trackColor: string,
  isLocked: boolean,
  isHidden: boolean
): void {
  const x = shot.startTime * zoomLevel;
  const width = Math.max(shot.duration * zoomLevel, MIN_SHOT_WIDTH);
  const layerIndex = getLayerIndex(shot, trackType, layer);
  const y = layerIndex * LAYER_STACK_HEIGHT + SHOT_PADDING;
  const height = LAYER_STACK_HEIGHT - SHOT_PADDING * 2;
  
  // Skip if hidden
  if (isHidden) return;
  
  // Calculate opacity
  let alpha = isSelected ? 1 : 0.8;
  if (isLocked) alpha = 0.5;
  
  // Draw layer background with rounded corners
  ctx.fillStyle = trackColor;
  ctx.globalAlpha = alpha;
  
  // Rounded rectangle path
  ctx.beginPath();
  ctx.roundRect(x, y, width, height, SHOT_CORNER_RADIUS);
  ctx.fill();
  
  // Draw selection outline
  if (isSelected) {
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  
  // Draw layer icon and name
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#ffffff';
  ctx.font = '11px -apple-system, BlinkMacSystemFont, sans-serif';
  ctx.textBaseline = 'middle';
  
  const textPadding = 4;
  const iconPadding = 2;
  
  // Draw layer icon
  const icon = LAYER_ICONS[layer.type] || '📁';
  ctx.font = '12px -apple-system, BlinkMacSystemFont, sans-serif';
  ctx.fillText(icon, x + iconPadding, y + height / 2);
  
  // Draw layer name
  ctx.font = '10px -apple-system, BlinkMacSystemFont, sans-serif';
  const iconWidth = 16;
  const nameX = x + iconWidth + iconPadding;
  const maxTextWidth = width - iconWidth - textPadding * 2;
  
  let text = shot.name || 'Untitled';
  if (maxTextWidth > 0) {
    while (ctx.measureText(text).width > maxTextWidth && text.length > 3) {
      text = text.slice(0, -4) + '...';
    }
  }
  
  if (width > iconWidth + textPadding * 2 + 20) {
    ctx.fillText(text, nameX, y + height / 2);
  }
  
  // Draw thumbnail if there's enough space
  if (width > THUMBNAIL_WIDTH + 60) {
    drawThumbnail(ctx, x + width - THUMBNAIL_WIDTH - 4, y + (height - THUMBNAIL_HEIGHT) / 2, THUMBNAIL_WIDTH, THUMBNAIL_HEIGHT);
  }
  
  // Draw duration indicator
  if (width > 60) {
    const durationText = `${Math.round(shot.duration / 24)}s`;
    const durationWidth = ctx.measureText(durationText).width;
    const thumbnailOffset = width > THUMBNAIL_WIDTH + 60 ? THUMBNAIL_WIDTH + 8 : 0;
    
    if (width > iconWidth + textPadding * 2 + 20 + durationWidth + thumbnailOffset) {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
      ctx.textAlign = 'right';
      ctx.fillText(durationText, x + width - textPadding - thumbnailOffset, y + height / 2);
      ctx.textAlign = 'left';
    }
  }
  
  // Draw resize handles if selected and not locked
  if (isSelected && !isLocked) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
    // Left handle
    ctx.fillRect(x, y, 6, height);
    // Right handle
    ctx.fillRect(x + width - 6, y, 6, height);
  }
  
  // Draw locked indicator
  if (isLocked) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.fillRect(x, y, width, height);
    
    // Lock icon
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.font = '10px -apple-system, BlinkMacSystemFont, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('🔒', x + width - 4, y + height / 2);
    ctx.textAlign = 'left';
  }
}

/**
 * Draw playhead on canvas
 */
function drawPlayhead(
  ctx: CanvasRenderingContext2D,
  position: number,
  height: number,
  isPlaying: boolean
): void {
  const x = position;
  
  // Draw playhead line
  ctx.strokeStyle = '#4A90E2';
  ctx.lineWidth = PLAYHEAD_WIDTH;
  ctx.shadowColor = '#4A90E2';
  ctx.shadowBlur = 4;
  ctx.beginPath();
  ctx.moveTo(x, 0);
  ctx.lineTo(x, height);
  ctx.stroke();
  ctx.shadowBlur = 0;
  
  // Draw playhead handle
  ctx.fillStyle = '#4A90E2';
  ctx.beginPath();
  ctx.moveTo(x - 8, 0);
  ctx.lineTo(x + 8, 0);
  ctx.lineTo(x, 12);
  ctx.closePath();
  ctx.fill();
  
  // Pulse animation when playing
  if (isPlaying) {
    ctx.strokeStyle = 'rgba(74, 144, 226, 0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x - 4, 0);
    ctx.lineTo(x - 4, height);
    ctx.moveTo(x + 4, 0);
    ctx.lineTo(x + 4, height);
    ctx.stroke();
  }
}

// ============================================================================
// Main VirtualTimelineCanvas Component
// ============================================================================

export const VirtualTimelineCanvas: React.FC<VirtualTimelineCanvasProps> = ({
  tracks,
  shots,
  zoomLevel,
  playheadPosition,
  selectedElements,
  timelineWidth,
  onShotSelect,
  onLayerSelect,
  onShotMove,
  onShotResize,
  isPlaying = false,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRefs = useRef<Map<string, HTMLCanvasElement>>(new Map());
  const [containerSize, setContainerSize] = useState({ width: 800, height: 400 });
  
  // Filter out hidden tracks
  const visibleTracks = useMemo(
    () => tracks.filter((track) => !track.hidden),
    [tracks]
  );
  
  // Calculate total height of all tracks
  const totalHeight = useMemo(
    () => visibleTracks.reduce((sum, track) => sum + track.height, 0),
    [visibleTracks]
  );
  
  // Setup virtualizer for vertical scrolling
  const rowVirtualizer = useVirtualizer({
    count: visibleTracks.length,
    getScrollElement: () => containerRef.current,
    estimateSize: (index) => visibleTracks[index]?.height || 40,
    overscan: 3,
    // Enable measurement for test environments
    measureElement:
      typeof window !== 'undefined' && window.document
        ? undefined
        : () => 40,
  });
  
  // Update container size on resize
  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        setContainerSize({
          width: containerRef.current.clientWidth,
          height: containerRef.current.clientHeight,
        });
      }
    };
    
    updateSize();
    const resizeObserver = new ResizeObserver(updateSize);
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }
    
    return () => resizeObserver.disconnect();
  }, []);
  
  // Draw each track canvas
  useEffect(() => {
    visibleTracks.forEach((track) => {
      const canvas = canvasRefs.current.get(track.id);
      if (!canvas) return;
      
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      
      const trackLayers = getTrackShots(shots, track.type);
      
      // Clear canvas
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      
      // Draw background
      ctx.fillStyle = track.color + '15';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      
      // Draw grid lines
      drawGridLines(ctx, canvas.width, canvas.height, zoomLevel);
      
      // Draw layers
      trackLayers.forEach(({ shot, layer }) => {
        const isSelected = selectedElements.includes(shot.id);
        drawLayer(
          ctx,
          shot,
          layer,
          track.type,
          track.height,
          zoomLevel,
          isSelected,
          track.color,
          layer.locked,
          layer.hidden
        );
      });
      
      // Draw playhead
      const playheadX = playheadPosition * zoomLevel;
      if (playheadX >= 0 && playheadX <= canvas.width) {
        drawPlayhead(ctx, playheadX, canvas.height, isPlaying);
      }
    });
  }, [visibleTracks, shots, zoomLevel, playheadPosition, selectedElements, isPlaying]);
  
  // Handle canvas click for shot/layer selection
  const handleCanvasClick = useCallback(
    (e: React.MouseEvent<HTMLCanvasElement>, track: Track) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      
      const trackLayers = getTrackShots(shots, track.type);
      
      // If onLayerSelect is provided, try to find the specific layer clicked
      if (onLayerSelect) {
        for (const { shot, layer } of trackLayers) {
          const shotStart = shot.startTime * zoomLevel;
          const shotEnd = (shot.startTime + shot.duration) * zoomLevel;
          const layerIndex = getLayerIndex(shot, track.type, layer);
          const layerTop = layerIndex * LAYER_STACK_HEIGHT + SHOT_PADDING;
          const layerBottom = layerTop + LAYER_STACK_HEIGHT - SHOT_PADDING * 2;
          
          // Check if click is within layer bounds (both X and Y)
          if (x >= shotStart && x <= shotEnd && y >= layerTop && y <= layerBottom) {
            // Layer clicked
            onLayerSelect(shot.id, layer.id, e.ctrlKey || e.metaKey);
            return;
          }
        }
      }
      
      // If no specific layer was clicked or onLayerSelect not provided,
      // check if any shot was clicked (more lenient - just check X coordinate)
      for (const { shot } of trackLayers) {
        const shotStart = shot.startTime * zoomLevel;
        const shotEnd = (shot.startTime + shot.duration) * zoomLevel;
        
        if (x >= shotStart && x <= shotEnd) {
          if (onLayerSelect) {
            // If onLayerSelect is provided but we didn't find exact layer,
            // call it with the first layer of the shot
            const firstLayer = shot.layers.find(l => l.type === track.type);
            if (firstLayer) {
              onLayerSelect(shot.id, firstLayer.id, e.ctrlKey || e.metaKey);
            }
          } else {
            onShotSelect(shot.id, e.ctrlKey || e.metaKey);
          }
          return;
        }
      }
    },
    [shots, zoomLevel, onShotSelect, onLayerSelect]
  );
  
  // Resize canvas observer
  useEffect(() => {
    visibleTracks.forEach((track) => {
      const container = document.getElementById(`track-container-${track.id}`);
      const canvas = canvasRefs.current.get(track.id);
      if (!container || !canvas) return;
      
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const { width } = entry.contentRect;
          canvas.width = width;
          canvas.height = track.height;
        }
      });
      
      resizeObserver.observe(container);
    });
  }, [visibleTracks]);
  
  return (
    <div ref={containerRef} className="virtual-timeline-canvas">
      {/* Canvas for drawing static elements (grid, playhead, etc.) */}
      <div
        className="static-overlay-canvas"
        style={{
          width: timelineWidth,
          height: totalHeight,
          position: 'absolute',
          top: 0,
          left: 0,
          pointerEvents: 'none',
          zIndex: 5,
        }}
      >
        <canvas
          width={timelineWidth}
          height={totalHeight}
          className="overlay-canvas"
        />
      </div>
      
      {/* Virtual list of tracks */}
      <div
        className="timeline-track-list"
        style={{
          height: `${rowVirtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {/* Render all visible tracks (fallback for test environment) */}
        {rowVirtualizer.getVirtualItems().length === 0 && visibleTracks.map((track, index) => {
          const trackLayers = getTrackShots(shots, track.type);
          
          return (
            <div
              key={track.id}
              className="virtual-track-row"
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${track.height}px`,
                transform: `translateY(${visibleTracks.slice(0, index).reduce((sum, t) => sum + t.height, 0)}px)`,
              }}
            >
              <div
                id={`track-container-${track.id}`}
                className="track-canvas-container"
                style={{ width: '100%', height: track.height }}
              >
                <canvas
                  ref={(el) => {
                    if (el) canvasRefs.current.set(track.id, el);
                    else canvasRefs.current.delete(track.id);
                  }}
                  className="track-canvas"
                  width={timelineWidth}
                  height={track.height}
                  onClick={(e) => handleCanvasClick(e, track)}
                  style={{
                    width: timelineWidth,
                    height: track.height,
                    cursor: 'pointer',
                  }}
                />
                
                {/* Layer count indicator */}
                {trackLayers.length > 0 && (
                  <div className="layer-count-badge" title={`${trackLayers.length} layers`}>
                    {trackLayers.length}
                  </div>
                )}
              </div>
            </div>
          );
        })}
        
        {/* Virtual items (normal rendering) */}
        {rowVirtualizer.getVirtualItems().map((virtualItem) => {
          const track = visibleTracks[virtualItem.index];
          const trackLayers = getTrackShots(shots, track.type);
          
          return (
            <div
              key={track.id}
              className="virtual-track-row"
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${track.height}px`,
                transform: `translateY(${virtualItem.start}px)`,
              }}
            >
              <div
                id={`track-container-${track.id}`}
                className="track-canvas-container"
                style={{ width: '100%', height: track.height }}
              >
                <canvas
                  ref={(el) => {
                    if (el) canvasRefs.current.set(track.id, el);
                    else canvasRefs.current.delete(track.id);
                  }}
                  className="track-canvas"
                  width={timelineWidth}
                  height={track.height}
                  onClick={(e) => handleCanvasClick(e, track)}
                  style={{
                    width: timelineWidth,
                    height: track.height,
                    cursor: 'pointer',
                  }}
                />
                
                {/* Layer count indicator */}
                {trackLayers.length > 0 && (
                  <div className="layer-count-badge" title={`${trackLayers.length} layers`}>
                    {trackLayers.length}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default VirtualTimelineCanvas;

