        top: 0,
        right: 1000,
        bottom: 30,
        width: 1000,
        height: 30,
        x: 0,
        y: 0,
        toJSON: () => {},
      });
      
      fireEvent.mouseMove(ruler!, { clientX: 240 });
      
      expect(container.querySelector('.ruler-hover-tooltip')).toBeInTheDocument();
