    it('should handle negative zoom level', () => {
      renderWithProviders(
        <TimelineDropTarget track={mockTrack} zoomLevel={-10}>
          <div>Negative Zoom</div>
        </TimelineDropTarget>
      );

      expect(screen.getByText('Negative Zoom')).toBeInTheDocument();
