// Helper function to create sample tracks
function createSampleTracks(): Track[] {
  return [
    {
      id: 'track-media',
      type: 'media',
      height: 60,
      locked: false,
      hidden: false,
      color: '#4A90E2',
      icon: 'film',
    },
    {
