      type: 'effects',
      height: 40,
      locked: false,
      hidden: false,
      color: '#9B59B6',
      icon: 'magic',
    },
  ];
}

// Helper function to create sample shot
function createSampleShot(id: string, startTime: number, duration: number, layerType: LayerType = 'media'): Shot {
  return {
    id,
    name: `Shot ${id}`,
    startTime,
    duration,
    layers: [
      {
        id: `layer-${id}`,
        type: layerType,
        startTime: 0,
        duration,
        locked: false,
        hidden: false,
        opacity: 1,
        blendMode: 'normal',
        data: {
          sourceUrl: '',
          trim: { start: 0, end: duration },
          transform: {
            position: { x: 0, y: 0 },
