/**
 * Timeline Animations Hook
 * Provides animation utilities for timeline operations.
 */
import { useCallback, useRef } from 'react';

interface AnimationOptions {
  duration?: number;
  easing?: string;
  onComplete?: () => void;
}

export const useTimelineAnimations = () => {
const animationRef = useRef<Animation | null>(null);

  const animate = useCallback((
    element: HTMLElement,
    keyframes: Keyframe[],
    options: AnimationOptions
  ) => {
    element.animate(keyframes, {
      duration: options.duration || 300,
      easing: options.easing || 'ease-out',
      fill: 'forwards',
    });
  }, []);

  const fadeIn = useCallback((element: HTMLElement) => {
    animate(element, [
      { opacity: 0 },
      { opacity: 1 },
    ], { duration: 200 });
  }, [animate]);

  const fadeOut = useCallback((element: HTMLElement) => {
    animate(element, [
      { opacity: 1 },
      { opacity: 0 },
    ], { duration: 200 });
  }, [animate]);

  const slideIn = useCallback((element: HTMLElement, direction: 'left' | 'right' | 'top' | 'bottom') => {
    const transform = direction === 'left' ? 'translateX(-20px)' 
      : direction === 'right' ? 'translateX(20px)'
      : direction === 'top' ? 'translateY(-20px)'
      : 'translateY(20px)';
    
    animate(element, [
      { opacity: 0, transform },
      { opacity: 1, transform: 'translateX(0)' },
    ], { duration: 250 });
  }, [animate]);

  const pulse = useCallback((element: HTMLElement) => {
    element.animate([
      { transform: 'scale(1)' },
      { transform: 'scale(1.02)' },
      { transform: 'scale(1)' },
    ], { duration: 300, iterations: 2 });
  }, []);

  const ripple = useCallback((element: HTMLElement, x: number, y: number) => {
    const ripple = document.createElement('div');
    ripple.style.cssText = `
      position: absolute;
      width: 20px;
      height: 20px;
      background: rgba(74, 144, 226, 0.3);
      border-radius: 50%;
      transform: scale(0);
      animation: ripple 0.6s ease-out;
      pointer-events: none;
      left: ${x}px;
      top: ${y}px;
    `;
    element.appendChild(ripple);
    setTimeout(() => ripple.remove(), 600);
  }, []);

  return {
    animate,
    fadeIn,
    fadeOut,
    slideIn,
    pulse,
    ripple,
  };
};

export default useTimelineAnimations;

/**
 * Timeline Selection Hook
 * Manages shot selection state and operations.
 */
import { useCallback, useState } from 'react';
import type { Shot } from '../../types';

interface UseTimelineSelectionOptions {
  shots?: Shot[];
  onSelectionChange?: (selectedIds: string[]) => void;
}

export const useTimelineSelection = (options: UseTimelineSelectionOptions = {}) => {
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [lastSelectedId, setLastSelectedId] = useState<string | null>(null);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
    setLastSelectedId(null);
    options.onSelectionChange?.([]);
  }, [options]);

  const selectOne = useCallback((id: string, addToSelection = false) => {
    const newSelection = addToSelection
      ? new Set(selectedIds)
      : new Set<string>();
    newSelection.add(id);
    setSelectedIds(newSelection);
    setLastSelectedId(id);
    options.onSelectionChange?.(Array.from(newSelection));
  }, [selectedIds, options]);

  const selectRange = useCallback((startId: string, endId: string) => {
    if (!options.shots) return;
    const shotsArray = options.shots;
    const startIndex = shotsArray.findIndex((s) => s.id === startId);
    const endIndex = shotsArray.findIndex((s) => s.id === endId);
    if (startIndex === -1 || endIndex === -1) return;
    const [min, max] = startIndex < endIndex ? [startIndex, endIndex] : [endIndex, startIndex];
    const newSelection = new Set<string>();
    for (let i = min; i <= max; i++) {
      newSelection.add(shotsArray[i].id);
    }
    setSelectedIds(newSelection);
    setLastSelectedId(endId);
    options.onSelectionChange?.(Array.from(newSelection));
  }, [options.shots, options]);

  const toggleSelection = useCallback((id: string) => {
    const newSelection = new Set(selectedIds);
    if (newSelection.has(id)) {
      newSelection.delete(id);
    } else {
      newSelection.add(id);
    }
    setSelectedIds(newSelection);
    setLastSelectedId(id);
    options.onSelectionChange?.(Array.from(newSelection));
  }, [selectedIds, options]);

  const handleItemClick = useCallback((id: string, event: React.MouseEvent | React.KeyboardEvent) => {
    const isMulti = event.shiftKey || event.ctrlKey || event.metaKey;
    const isRange = event.shiftKey && lastSelectedId;
    if (isRange && options.shots) {
      selectRange(lastSelectedId, id);
    } else if (isMulti) {
      toggleSelection(id);
    } else {
      selectOne(id, false);
    }
  }, [lastSelectedId, options.shots, selectRange, toggleSelection, selectOne]);

  const selectAll = useCallback(() => {
    if (!options.shots) return;
    const allIds = new Set(options.shots.map((s) => s.id));
    setSelectedIds(allIds);
    options.onSelectionChange?.(Array.from(allIds));
  }, [options.shots, options]);

  const isSelected = useCallback((id: string) => selectedIds.has(id), [selectedIds]);

  const getSelectedItems = useCallback(() => {
    if (!options.shots) return [];
    return options.shots.filter((s) => selectedIds.has(s.id));
  }, [options.shots, selectedIds]);

  return {
    selectedIds,
    selectedCount: selectedIds.size,
    lastSelectedId,
    clearSelection,
    selectOne,
    selectRange,
    toggleSelection,
    handleItemClick,
    selectAll,
    isSelected,
    getSelectedItems,
  };
};

export default useTimelineSelection;

/**
 * Timeline Snapping Hook
 * 
 * Provides snapping behavior for timeline operations.
 * Snaps to shot boundaries, playhead, and grid.
 */

import { useCallback, useMemo } from 'react';
import type { Shot } from '../../types';

interface UseTimelineSnappingOptions {
  shots: Shot[];
  zoomLevel: number;
  snapThreshold?: number;
  enabled?: boolean;
}

export const useTimelineSnapping = ({
  shots,
  zoomLevel,
  snapThreshold = 10,
  enabled = true,
}: UseTimelineSnappingOptions) => {
  // Calculate snap points from shot boundaries
  const snapPoints = useMemo(() => {
    if (!enabled) return [];
    
    const points: number[] = [0]; // Always snap to start
    
    shots.forEach((shot) => {
      const start = shot.startTime || 0;
      const end = start + (shot.duration || 0);
      
      if (!points.includes(start)) points.push(start);
      if (!points.includes(end)) points.push(end);
    });
    
    return points.sort((a, b) => a - b);
  }, [shots, enabled]);

  // Find closest snap point
  const findSnapPoint = useCallback(
    (position: number): number => {
      if (!enabled || snapPoints.length === 0) return position;
      
      let closestPoint = position;
      let minDistance = Infinity;
      
      for (const point of snapPoints) {
        const distance = Math.abs(point - position);
        if (distance < minDistance) {
          minDistance = distance;
          closestPoint = point;
        }
      }
      
      // Only snap if within threshold
      return minDistance <= snapThreshold ? closestPoint : position;
    },
    [snapPoints, snapThreshold, enabled]
  );

  // Snap a range (start, end) while maintaining duration
  const snapRange = useCallback(
    (start: number, end: number): { start: number; end: number } => {
      const snappedStart = findSnapPoint(start);
      const duration = end - start;
      
      // Try to snap end to a point while maintaining duration
      const targetEnd = snappedStart + duration;
      const snappedEnd = findSnapPoint(targetEnd);
      
      // If end snapped, adjust start to maintain duration
      if (snappedEnd !== targetEnd && snappedEnd > snappedStart) {
        const newStart = snappedEnd - duration;
        return { start: findSnapPoint(newStart), end: snappedEnd };
      }
      
      return { start: snappedStart, end: snappedEnd };
    },
    [findSnapPoint]
  );

  // Get visual snap indicator position
  const getSnapIndicator = useCallback(
    (position: number): number | null => {
      if (!enabled) return null;
      
      const snapped = findSnapPoint(position);
      return snapped !== position ? snapped : null;
    },
    [enabled, findSnapPoint]
  );

  return {
    snapPoints,
    findSnapPoint,
    snapRange,
    getSnapIndicator,
  };
};

export default useTimelineSnapping;

