/**
 * Transcription Panel Component - Text-Based Editing
 * Like Adobe Premiere Text-Based Editing feature
 */

import React, { useState, useCallback } from 'react';
import {
  transcriptionService,
  Transcript,
  MontageStyle,
  MontageRequest,
  MontageResult,
  SegmentType
} from '../../services/transcriptionService';
import styles from './TranscriptionPanel.module.css';

interface TranscriptionPanelProps {
  audioUrl?: string;
  onMontageComplete?: (result: MontageResult) => void;
}

export const TranscriptionPanel: React.FC<TranscriptionPanelProps> = ({
  audioUrl,
  onMontageComplete
}) => {
  const [audioId, setAudioId] = useState('');
  const [transcript, setTranscript] = useState<Transcript | null>(null);
  const [montageResult, setMontageResult] = useState<MontageResult | null>(null);
  const [montageStyle, setMontageStyle] = useState<MontageStyle>('chronological');
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [isGeneratingMontage, setIsGeneratingMontage] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [language, setLanguage] = useState('fr');

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleTranscribe = useCallback(async () => {
    if (!audioUrl) {
      setError('Veuillez selectionner un fichier audio');
      return;
    }

    setIsTranscribing(true);
    setError(null);

    try {
      const id = `audio_${Date.now()}`;
      setAudioId(id);
      
      const result = await transcriptionService.transcribe(
        id,
        audioUrl,
        language,
        true
      );
      
      setTranscript(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Transcription echouee');
    } finally {
      setIsTranscribing(false);
    }
  }, [audioUrl, language]);

  const handleGenerateMontage = useCallback(async () => {
    if (!transcript) {
      setError('Veuillez d\'abord transcrire l\'audio');
      return;
    }

    setIsGeneratingMontage(true);
    setError(null);

    try {
      const request: MontageRequest = {
        transcriptId: transcript.transcriptId,
        style: montageStyle,
        includeSpeakers: undefined,
        excludeSpeakers: undefined,
        maxDuration: undefined
      };

      const result = await transcriptionService.generateMontage(request);
      setMontageResult(result);
      
      if (onMontageComplete) {
        onMontageComplete(result);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Generation montage echouee');
    } finally {
      setIsGeneratingMontage(false);
    }
  }, [transcript, montageStyle, onMontageComplete]);

  const handleExportSrt = useCallback(async () => {
    if (!transcript) return;
    
    try {
      const srt = await transcriptionService.exportSrt(transcript.transcriptId);
      const blob = new Blob([srt], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${transcript.transcriptId}.srt`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      setError('Echec de l\'export SRT');
    }
  }, [transcript]);

  const handleExportVtt = useCallback(async () => {
    if (!transcript) return;
    
    try {
      const vtt = await transcriptionService.exportVtt(transcript.transcriptId);
      const blob = new Blob([vtt], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${transcript.transcriptId}.vtt`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      setError('Echec de l\'export VTT');
    }
  }, [transcript]);

  const filteredSegments = transcript && searchQuery
    ? transcriptionService.searchInTranscript(transcript, searchQuery)
    : (transcript?.segments || []);

  const segmentsBySpeaker = transcript
    ? transcriptionService.getSegmentsBySpeaker(transcript)
    : {};

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3>Transcription & Montage Texte</h3>
        <p>Transcrivez l'audio et montez par copier-coller</p>
      </div>

      <div className={styles.section}>
        <h4>Transcription</h4>
        
        <div className={styles.field}>
          <label>Langue:</label>
          <select
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            className={styles.select}
          >
            <option value="fr">Francais</option>
            <option value="en">Anglais</option>
            <option value="es">Espagnol</option>
            <option value="de">Allemand</option>
            <option value="auto">Auto-detection</option>
          </select>
        </div>

        <button
          onClick={handleTranscribe}
          disabled={isTranscribing || !audioUrl}
          className={styles.buttonPrimary}
        >
          {isTranscribing ? 'Transcription...' : 'Transcrire l\'audio'}
        </button>
      </div>

      {error && (
        <div className={styles.error}>
          {error}
        </div>
      )}

      {transcript && (
        <>
          <div className={styles.section}>
            <h4>Resultats ({transcript.wordCount} mots, {transcript.speakerCount} locuteurs)</h4>
            
            <div className={styles.exportButtons}>
              <button
                onClick={handleExportSrt}
                className={styles.buttonSecondary}
              >
                Export SRT
              </button>
              <button
                onClick={handleExportVtt}
                className={styles.buttonSecondary}
              >
                Export VTT
              </button>
            </div>
          </div>

          <div className={styles.section}>
            <h4>Generation Montage</h4>
            
            <div className={styles.field}>
              <label>Style de montage:</label>
              <select
                value={montageStyle}
                onChange={(e) => setMontageStyle(e.target.value as MontageStyle)}
                className={styles.select}
              >
                <option value="chronologique">Chronologique</option>
                <option value="highlights">Points forts</option>
                <option value="compact">Compact</option>
                <option value="conversation">Par conversation</option>
              </select>
            </div>

            <button
              onClick={handleGenerateMontage}
              disabled={isGeneratingMontage}
              className={styles.buttonPrimary}
            >
              {isGeneratingMontage ? 'Generation...' : 'Generer le montage'}
            </button>
          </div>

          {montageResult && (
            <div className={styles.section}>
              <h4>Montage Genere ({montageResult.totalDuration.toFixed(1)}s)</h4>
              
              <div className={styles.montageSummary}>
                {montageResult.summary}
              </div>

              <div className={styles.shotsList}>
                {montageResult.shots.map((shot) => (
                  <div key={shot.shotId} className={styles.shotItem}>
                    <div className={styles.shotTime}>
                      {formatTime(shot.sourceStart)} - {formatTime(shot.sourceEnd)}
                    </div>
                    <div className={styles.shotText}>
                      {shot.text}
                    </div>
                    {shot.speaker && (
                      <div className={styles.shotSpeaker}>
                        {shot.speaker}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className={styles.section}>
            <h4>Transcript</h4>
            
            <div className={styles.searchBox}>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Rechercher dans le transcript..."
                className={styles.input}
              />
            </div>

            <div className={styles.segmentsList}>
              {filteredSegments.map((segment) => (
                <div key={segment.segmentId} className={styles.segmentItem}>
                  <div className={styles.segmentHeader}>
                    <span className={styles.segmentTime}>
                      {formatTime(segment.startTime)} - {formatTime(segment.endTime)}
                    </span>
                    {segment.speaker && (
                      <span className={styles.segmentSpeaker}>
                        {segment.speaker.speakerLabel}
                      </span>
                    )}
                    <span className={styles.segmentType}>
                      {segment.segmentType}
                    </span>
                  </div>
                  <div className={styles.segmentText}>
                    {segment.text}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {Object.keys(segmentsBySpeaker).length > 0 && (
            <div className={styles.section}>
              <h4>Par Locuteur</h4>
              
              {Object.entries(segmentsBySpeaker).map(([speaker, segments]) => (
                <div key={speaker} className={styles.speakerSection}>
                  <div className={styles.speakerHeader}>
                    {speaker} ({segments.length} segments)
                  </div>
                  {segments.slice(0, 3).map((segment) => (
                    <div key={segment.segmentId} className={styles.segmentMini}>
                      <span className={styles.timeMini}>
                        {formatTime(segment.startTime)}
                      </span>
                      <span className={styles.textMini}>
                        {segment.text.substring(0, 80)}...
                      </span>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default TranscriptionPanel;

/**
 * Transitions Panel Component
 * 
 * Provides UI for selecting and applying video transitions between clips.
 * Supports 17 transition types from the backend transitions_service.py.
 * 
 * Requirements: Phase 3 - Implement missing UI controls
 * Phase 2 - Connected to Redux store
 */

import React, { useState, useCallback } from 'react';
import { useAppDispatch, useAppSelector } from '../../store';
import { addTransition, removeTransition } from '../../store/slices/timelineSlice';
import './transitionsPanel.css';

// Transition types matching backend TransitionType enum
export type TransitionType = 
  | 'cut'
  | 'dissolve'
  | 'crossfade'
  | 'fade_black'
  | 'fade_white'
  | 'wipe_left'
  | 'wipe_right'
  | 'wipe_up'
  | 'wipe_down'
  | 'slide_left'
  | 'slide_right'
  | 'slide_up'
  | 'slide_down'
  | 'zoom_in'
  | 'zoom_out'
  | 'iris'
  | 'pixelate';

interface TransitionInfo {
  type: TransitionType;
  name: string;
  description: string;
  minDuration: number;
  maxDuration: number;
  icon: string;
  category: 'basic' | 'fade' | 'wipe' | 'slide' | 'zoom' | 'special';
}

const TRANSITIONS: TransitionInfo[] = [
  { type: 'cut', name: 'Cut', description: 'Instant cut to next clip', minDuration: 0, maxDuration: 0, icon: '✂️', category: 'basic' },
  { type: 'dissolve', name: 'Dissolve', description: 'Fade through black', minDuration: .5, maxDuration: 3., icon: '💧', category: 'fade' },
  { type: 'crossfade', name: 'Crossfade', description: 'Smooth blend between clips', minDuration: .5, maxDuration: 2., icon: '🌫️', category: 'fade' },
  { type: 'fade_black', name: 'Fade to Black', description: 'Fade out to black', minDuration: .5, maxDuration: 2., icon: '⬛', category: 'fade' },
  { type: 'fade_white', name: 'Fade to White', description: 'Fade out to white', minDuration: .5, maxDuration: 2., icon: '⬜', category: 'fade' },
  { type: 'wipe_left', name: 'Wipe Left', description: 'Wipe from right to left', minDuration: 0.3, maxDuration: 1.5, icon: '⬅️', category: 'wipe' },
  { type: 'wipe_right', name: 'Wipe Right', description: 'Wipe from left to right', minDuration: 0.3, maxDuration: 1.5, icon: '➡️', category: 'wipe' },
  { type: 'wipe_up', name: 'Wipe Up', description: 'Wipe from bottom to top', minDuration: 0.3, maxDuration: 1.5, icon: '⬆️', category: 'wipe' },
  { type: 'wipe_down', name: 'Wipe Down', description: 'Wipe from top to bottom', minDuration: 0.3, maxDuration: 1.5, icon: '⬇️', category: 'wipe' },
  { type: 'slide_left', name: 'Slide Left', description: 'Push clip from right', minDuration: 0.3, maxDuration: 1.5, icon: '<<', category: 'slide' },
  { type: 'slide_right', name: 'Slide Right', description: 'Push clip from left', minDuration: 0.3, maxDuration: 1.5, icon: '>>', category: 'slide' },
  { type: 'slide_up', name: 'Slide Up', description: 'Push clip from bottom', minDuration: 0.3, maxDuration: 1.5, icon: '^^', category: 'slide' },
  { type: 'slide_down', name: 'Slide Down', description: 'Push clip from top', minDuration: 0.3, maxDuration: 1.5, icon: 'vv', category: 'slide' },
  { type: 'zoom_in', name: 'Zoom In', description: 'Zoom into next clip', minDuration: .5, maxDuration: 2., icon: '🔍+', category: 'zoom' },
  { type: 'zoom_out', name: 'Zoom Out', description: 'Zoom out to reveal next clip', minDuration: .5, maxDuration: 2., icon: '🔍-', category: 'zoom' },
  { type: 'iris', name: 'Iris', description: 'Circular wipe effect', minDuration: 0.3, maxDuration: 1.5, icon: '⭕', category: 'special' },
  { type: 'pixelate', name: 'Pixelate', description: 'Pixelation transition', minDuration: 0.3, maxDuration: 1.5, icon: '🔲', category: 'special' },
];

interface TransitionsPanelProps {
  clipId?: string;
  position?: 'in' | 'out';
}

export const TransitionsPanel: React.FC<TransitionsPanelProps> = ({ 
  clipId, 
  position = 'out' 
}) => {
  const dispatch = useAppDispatch();
  const selectedElements = useAppSelector((state) => state.timeline.selectedElements);
  
  // Get selected clip
  const selectedClipId = clipId || (selectedElements.length > 0 ? selectedElements[0] : null);
  
  // Local state
  const [selectedTransition, setSelectedTransition] = useState<TransitionType>('dissolve');
  const [duration, setDuration] = useState(1.);
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  
  // Get current transition for selected clip (from backend)
  const currentTransition = useCallback((clipId: string, pos: string) => {
    // In production, get from Redux store
    return null;
  }, []);
  
  // Filter transitions by category and search
  const filteredTransitions = TRANSITIONS.filter(t => {
    const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
    const matchesSearch = t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         t.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });
  
  // Handle apply transition
  const handleApplyTransition = useCallback(async () => {
    if (!selectedClipId) return;
    
    try {
      // Call backend API to apply transition
      const response = await fetch('/api/timeline/transitions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          clip_id: selectedClipId,
          transition_type: selectedTransition,
          position,
          duration,
        }),
      });
      
      if (response.ok) {
        // Update Redux store
        dispatch(addTransition({
          clipId: selectedClipId,
          transitionType: selectedTransition,
          position,
          duration,
        }));
      }
    } catch (error) {
      console.error('Failed to apply transition:', error);
    }
  }, [selectedClipId, selectedTransition, position, duration, dispatch]);
  
  // Handle remove transition
  const handleRemoveTransition = useCallback(async () => {
    if (!selectedClipId) return;
    
    try {
      const response = await fetch(`/api/timeline/transitions/${selectedClipId}/${position}`, {
        method: 'DELETE',
      });
      
      if (response.ok) {
        dispatch(removeTransition({
          clipId: selectedClipId,
          position,
        }));
      }
    } catch (error) {
      console.error('Failed to remove transition:', error);
    }
  }, [selectedClipId, position, dispatch]);
  
  // Get categories
  const categories = [
    { id: 'all', label: 'All' },
    { id: 'basic', label: 'Basic' },
    { id: 'fade', label: 'Fade' },
    { id: 'wipe', label: 'Wipe' },
    { id: 'slide', label: 'Slide' },
    { id: 'zoom', label: 'Zoom' },
    { id: 'special', label: 'Special' },
  ];
  
  // Get current transition info
  const currentTransitionInfo = currentTransition(selectedClipId || '', position);
  const selectedTransitionInfo = TRANSITIONS.find(t => t.type === selectedTransition);
  
  return (
    <div className="transitions-panel">
      <div className="transitions-panel-header">
        <h3>Transitions</h3>
        <span className="position-badge">{position === 'in' ? 'In' : 'Out'}</span>
      </div>
      
      {/* Search */}
      <div className="transitions-search">
        <input
          type="text"
          placeholder="Search transitions..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="transitions-search-input"
        />
      </div>
      
      {/* Category Filter */}
      <div className="transitions-categories">
        {categories.map(cat => (
          <button
            key={cat.id}
            className={`category-btn ${selectedCategory === cat.id ? 'active' : ''}`}
            onClick={() => setSelectedCategory(cat.id)}
          >
            {cat.label}
          </button>
        ))}
      </div>
      
      {/* Transitions Grid */}
      <div className="transitions-grid">
        {filteredTransitions.map(transition => (
          <button
            key={transition.type}
            className={`transition-item ${selectedTransition === transition.type ? 'selected' : ''}`}
            onClick={() => setSelectedTransition(transition.type)}
            title={transition.description}
          >
            <span className="transition-icon">{transition.icon}</span>
            <span className="transition-name">{transition.name}</span>
          </button>
        ))}
      </div>
      
      {/* Duration Slider */}
      {selectedTransitionInfo && selectedTransitionInfo.minDuration > 0 && (
        <div className="transition-duration">
          <label>
            Duration: {duration.toFixed(1)}s
          </label>
          <input
            type="range"
            min={selectedTransitionInfo.minDuration}
            max={selectedTransitionInfo.maxDuration}
            step={0.1}
            value={duration}
            onChange={(e) => setDuration(Number.parseFloat(e.target.value))}
            className="duration-slider"
            aria-label="Transition duration"
          />
          <div className="duration-range">
            <span>{selectedTransitionInfo.minDuration}s</span>
            <span>{selectedTransitionInfo.maxDuration}s</span>
          </div>
        </div>
      )}
      
      {/* Preview Description */}
      {selectedTransitionInfo && (
        <div className="transition-preview">
          <p>{selectedTransitionInfo.description}</p>
        </div>
      )}
      
      {/* Action Buttons */}
      <div className="transitions-actions">
        <button
          className="remove-transition-btn"
          onClick={handleRemoveTransition}
          disabled={!selectedClipId || !currentTransitionInfo}
        >
          Remove
        </button>
        <button
          className="apply-transition-btn"
          onClick={handleApplyTransition}
          disabled={!selectedClipId}
        >
          Apply
        </button>
      </div>
    </div>
  );
};

export default TransitionsPanel;

/**
 * VideoEffectsPanel Component
 *
 * Panel for applying advanced video effects to media layers:
 *  - Chroma Key (green screen removal)
 *  - Masking (shape masks, image masks, AI alpha masks)
 *  - Color Correction (brightness, contrast, saturation, hue)
 *  - Blur
 *  - Speed control
 *
 * Similar to CapCut's "Effects" and "Background Removal" tools.
 *
 * Requirements: Phase 2 of R&D plan
 */

import React, { useState, useCallback } from 'react';
import { useDispatch } from 'react-redux';
import { updateLayer } from '../../store/slices/timelineSlice';
import type { Layer, Shot, MediaLayerData, VideoMask, VideoEffects } from '../../types';
import './videoEffectsPanel.css';

interface VideoEffectsPanelProps {
    shot: Shot;
    selectedLayerId: string | null;
}

export const VideoEffectsPanel: React.FC<VideoEffectsPanelProps> = ({
    shot,
    selectedLayerId,
}) => {
    const dispatch = useDispatch();
    const [activeTab, setActiveTab] = useState<'mask' | 'chroma' | 'color' | 'blur'>('mask');
    const [isProcessingAI, setIsProcessingAI] = useState(false);

    const selectedLayer = selectedLayerId
        ? shot.layers.find(l => l.id === selectedLayerId)
        : null;

    if (!selectedLayer || selectedLayer.type !== 'media') {
        return (
            <div className="video-effects-panel">
                <div className="video-effects-empty">
                    <div className="video-effects-empty-icon">🎬</div>
                    <p>Select a media layer to apply effects</p>
                </div>
            </div>
        );
    }

    const mediaData = selectedLayer.data as MediaLayerData;
    const currentEffects: VideoEffects = mediaData.effects ?? {};
    const currentMask: VideoMask | undefined = mediaData.mask;

    // ---------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------

    const updateMediaData = (updates: Partial<MediaLayerData>) => {
        dispatch(
            updateLayer({
                shotId: shot.id,
                layerId: selectedLayer.id,
                updates: {
                    data: {
                        ...mediaData,
                        ...updates,
                    },
                },
            }),
        );
    };

    const updateEffects = (updates: Partial<VideoEffects>) => {
        updateMediaData({
            effects: { ...currentEffects, ...updates },
        });
    };

    const updateMask = (mask: VideoMask | undefined) => {
        updateMediaData({ mask });
    };

    // ---------------------------------------------------------------------------
    // AI Background Removal (Magic Cut)
    // ---------------------------------------------------------------------------

    const handleAIRemoveBackground = useCallback(async () => {
        setIsProcessingAI(true);
        try {
            // TODO: Call actual AI backend (rembg or ComfyUI segment-anything)
            // For now simulate a 2-second processing delay
            await new Promise(resolve => setTimeout(resolve, 2000));

            // Set the mask to alpha type (the AI would produce a mask image)
            updateMask({
                type: 'alpha',
                source: 'ai-generated', // placeholder
                invert: false,
            });
        } catch {
            console.error('AI background removal failed');
        } finally {
            setIsProcessingAI(false);
        }
    }, [selectedLayer, mediaData]);

    // ---------------------------------------------------------------------------
    // Render
    // ---------------------------------------------------------------------------

    return (
        <div className="video-effects-panel">
            <div className="video-effects-header">
                <h3>Video Effects</h3>
            </div>

            {/* Tab Bar */}
            <div className="video-effects-tabs">
                {(['mask', 'chroma', 'color', 'blur'] as const).map(tab => (
                    <button
                        key={tab}
                        className={`vfx-tab ${activeTab === tab ? 'active' : ''}`}
                        onClick={() => setActiveTab(tab)}
                    >
                        {tab === 'mask' && '🎭'}
                        {tab === 'chroma' && '🟢'}
                        {tab === 'color' && '🎨'}
                        {tab === 'blur' && '💨'}
                        <span>{tab.charAt(0).toUpperCase() + tab.slice(1)}</span>
                    </button>
                ))}
            </div>

            <div className="video-effects-content">
                {/* ================================================================ */}
                {/* MASK TAB                                                         */}
                {/* ================================================================ */}
                {activeTab === 'mask' && (
                    <div className="vfx-section">
                        <div className="vfx-section-title">Mask / Alpha</div>

                        {/* AI Remove Background */}
                        <button
                            className="vfx-action-btn vfx-action-btn-primary"
                            onClick={handleAIRemoveBackground}
                            disabled={isProcessingAI || selectedLayer.locked}
                        >
                            {isProcessingAI ? (
                                <span className="vfx-spinner" />
                            ) : (
                                '✨'
                            )}
                            <span>{isProcessingAI ? 'Processing...' : 'AI Remove Background'}</span>
                        </button>

                        {/* Shape Masks */}
                        <div className="vfx-row">
                            <label className="vfx-label">Shape Mask</label>
                            <div className="vfx-shape-buttons">
                                <button
                                    className={`vfx-shape-btn ${currentMask?.type === 'shape' && currentMask?.source === 'circle' ? 'active' : ''}`}
                                    onClick={() => updateMask({ type: 'shape', source: 'circle', invert: false })}
                                    disabled={selectedLayer.locked}
                                    title="Circle"
                                >
                                    ⭕
                                </button>
                                <button
                                    className={`vfx-shape-btn ${currentMask?.type === 'shape' && currentMask?.source === 'rectangle' ? 'active' : ''}`}
                                    onClick={() => updateMask({ type: 'shape', source: 'rectangle', invert: false })}
                                    disabled={selectedLayer.locked}
                                    title="Rectangle"
                                >
                                    ▬
                                </button>
                                <button
                                    className={`vfx-shape-btn ${currentMask?.type === 'shape' && currentMask?.source === 'star' ? 'active' : ''}`}
                                    onClick={() => updateMask({ type: 'shape', source: 'star', invert: false })}
                                    disabled={selectedLayer.locked}
                                    title="Star"
                                >
                                    ⭐
                                </button>
                                <button
                                    className="vfx-shape-btn"
                                    onClick={() => updateMask(undefined)}
                                    disabled={selectedLayer.locked}
                                    title="Remove Mask"
                                >
                                    ✖
                                </button>
                            </div>
                        </div>

                        {/* Invert Mask */}
                        {currentMask && (
                            <div className="vfx-row">
                                <label className="vfx-label">Invert Mask</label>
                                <input
                                    type="checkbox"
                                    checked={currentMask.invert ?? false}
                                    onChange={e => updateMask({ ...currentMask, invert: e.target.checked })}
                                    disabled={selectedLayer.locked}
                                />
                            </div>
                        )}
                    </div>
                )}

                {/* ================================================================ */}
                {/* CHROMA KEY TAB                                                   */}
                {/* ================================================================ */}
                {activeTab === 'chroma' && (
                    <div className="vfx-section">
                        <div className="vfx-section-title">Chroma Key (Green Screen)</div>

                        <div className="vfx-row">
                            <label className="vfx-label">Key Color</label>
                            <input
                                type="color"
                                className="vfx-color-picker"
                                value={currentEffects.chromaKey?.color ?? '#00FF00'}
                                onChange={e =>
                                    updateEffects({
                                        chromaKey: {
                                            color: e.target.value,
                                            similarity: currentEffects.chromaKey?.similarity ?? 40,
                                        },
                                    })
                                }
                                disabled={selectedLayer.locked}
                            />
                        </div>

                        <div className="vfx-row">
                            <label className="vfx-label">Similarity</label>
                            <input
                                type="range"
                                className="vfx-slider"
                                min={0}
                                max={100}
                                value={currentEffects.chromaKey?.similarity ?? 40}
                                onChange={e =>
                                    updateEffects({
                                        chromaKey: {
                                            color: currentEffects.chromaKey?.color ?? '#00FF00',
                                            similarity: Number(e.target.value),
                                        },
                                    })
                                }
                                disabled={selectedLayer.locked}
                            />
                            <span className="vfx-value">{currentEffects.chromaKey?.similarity ?? 40}%</span>
                        </div>

                        <button
                            className="vfx-action-btn vfx-action-btn-danger"
                            onClick={() => {
                                const { chromaKey, ...rest } = currentEffects;
                                updateMediaData({ effects: rest });
                            }}
                            disabled={!currentEffects.chromaKey || selectedLayer.locked}
                        >
                            Remove Chroma Key
                        </button>
                    </div>
                )}

                {/* ================================================================ */}
                {/* COLOR CORRECTION TAB                                             */}
                {/* ================================================================ */}
                {activeTab === 'color' && (
                    <div className="vfx-section">
                        <div className="vfx-section-title">Color Correction</div>

                        {[
                            { label: 'Brightness', key: 'brightness', min: -1, max: 1, step: 0.05, defaultVal: 0 },
                            { label: 'Contrast', key: 'contrast', min: 0, max: 3, step: 0.05, defaultVal: 1 },
                            { label: 'Saturation', key: 'saturation', min: 0, max: 3, step: 0.05, defaultVal: 1 },
                            { label: 'Hue', key: 'hue', min: -180, max: 180, step: 1, defaultVal: 0 },
                        ].map(({ label, key, min, max, step, defaultVal }) => (
                            <div className="vfx-row" key={key}>
                                <label className="vfx-label">{label}</label>
                                <input
                                    type="range"
                                    className="vfx-slider"
                                    min={min}
                                    max={max}
                                    step={step}
                                    value={(currentEffects.colorCorrection as any)?.[key] ?? defaultVal}
                                    onChange={e =>
                                        updateEffects({
                                            colorCorrection: {
                                                brightness: currentEffects.colorCorrection?.brightness ?? 0,
                                                contrast: currentEffects.colorCorrection?.contrast ?? 1,
                                                saturation: currentEffects.colorCorrection?.saturation ?? 1,
                                                hue: currentEffects.colorCorrection?.hue ?? 0,
                                                [key]: Number(e.target.value),
                                            },
                                        })
                                    }
                                    disabled={selectedLayer.locked}
                                />
                                <span className="vfx-value">
                                    {((currentEffects.colorCorrection as any)?.[key] ?? defaultVal).toFixed(2)}
                                </span>
                            </div>
                        ))}

                        <button
                            className="vfx-action-btn"
                            onClick={() => {
                                const { colorCorrection, ...rest } = currentEffects;
                                updateMediaData({ effects: rest });
                            }}
                            disabled={!currentEffects.colorCorrection || selectedLayer.locked}
                        >
                            Reset Colors
                        </button>
                    </div>
                )}

                {/* ================================================================ */}
                {/* BLUR TAB                                                         */}
                {/* ================================================================ */}
                {activeTab === 'blur' && (
                    <div className="vfx-section">
                        <div className="vfx-section-title">Blur</div>

                        <div className="vfx-row">
                            <label className="vfx-label">Blur Radius</label>
                            <input
                                type="range"
                                className="vfx-slider"
                                min={0}
                                max={50}
                                value={currentEffects.blur ?? 0}
                                onChange={e => updateEffects({ blur: Number(e.target.value) })}
                                disabled={selectedLayer.locked}
                            />
                            <span className="vfx-value">{currentEffects.blur ?? 0}px</span>
                        </div>

                        <button
                            className="vfx-action-btn"
                            onClick={() => updateEffects({ blur: 0 })}
                            disabled={selectedLayer.locked}
                        >
                            Remove Blur
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

