/**
 * usePerformance Hook
 * 
 * React hooks for performance monitoring and optimization.
 * 
 * Requirements: 3.6, 20.1, 22.3
 */

import { useEffect, useRef, useCallback, useMemo } from 'react';

// ============================================================================
// useWhyDidYouUpdate Hook
// ============================================================================

/**
 * Hook to debug why a component re-rendered
 */
export function useWhyDidYouUpdate(name: string, props: Record<string, unknown>): void {
  const previousProps = useRef<Record<string, unknown> | undefined>(undefined);
  
  useEffect(() => {
    if (previousProps.current) {
      const allKeys = Object.keys({ ...previousProps.current, ...props });
      const changedProps: Record<string, { from: unknown; to: unknown }> = {};
      
      allKeys.forEach((key) => {
        if (previousProps.current![key] !== props[key]) {
          changedProps[key] = {
            from: previousProps.current![key],
            to: props[key],
          };
        }
      });
      
      if (Object.keys(changedProps).length > 0) {
        console.log('[why-did-you-update]', name, changedProps);
      }
    }
    
    previousProps.current = props;
  });
}

// ============================================================================
// useRenderCount Hook
// ============================================================================

/**
 * Hook to count component renders
 */
export function useRenderCount(componentName: string): number {
  const renderCount = useRef(0);
  
  useEffect(() => {
    renderCount.current++;
    console.log(`${componentName} rendered ${renderCount.current} times`);
  });
  
  return renderCount.current;
}

// ============================================================================
// useOptimizedCallback Hook
// ============================================================================

/**
 * Hook for creating optimized callbacks with dependency tracking
 */
export function useOptimizedCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  deps: React.DependencyList
): T {
  const callbackRef = useRef<T>(callback);
  
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);
  
  return useCallback(
    ((...args: unknown[]) => callbackRef.current(...args)) as T,
    deps
  );
}

// ============================================================================
// useOptimizedMemo Hook
// ============================================================================

/**
 * Hook for optimized memoization with custom equality
 */
export function useOptimizedMemo<T>(
  factory: () => T,
  deps: React.DependencyList,
  isEqual: (a: T, b: T) => boolean = Object.is
): T {
  const valueRef = useRef<T | undefined>(undefined);
  const depsRef = useRef<React.DependencyList | undefined>(undefined);
  
  if (
    !depsRef.current ||
    depsRef.current.length !== deps.length ||
    depsRef.current.some((dep, i) => !Object.is(dep, deps[i]))
  ) {
    const newValue = factory();
    
    if (!valueRef.current || !isEqual(valueRef.current, newValue)) {
      valueRef.current = newValue;
    }
    
    depsRef.current = deps;
  }
  
  return valueRef.current!;
}

// ============================================================================
// usePrevious Hook
// ============================================================================

/**
 * Hook to get previous value
 */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  
  useEffect(() => {
    ref.current = value;
  }, [value]);
  
  return ref.current;
}

// ============================================================================
// useUpdateEffect Hook
// ============================================================================

/**
 * Hook that runs effect only on updates, not on mount
 */
export function useUpdateEffect(effect: React.EffectCallback, deps?: React.DependencyList): void {
  const isFirstMount = useRef(true);
  
  useEffect(() => {
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }
    
    return effect();
  }, deps);
}

// ============================================================================
// useEffectOnce Hook
// ============================================================================

/**
 * Hook that runs effect only once on mount
 */
export function useEffectOnce(effect: React.EffectCallback): void {
  useEffect(effect, []);
}

// ============================================================================
// useIsMounted Hook
// ============================================================================

/**
 * Hook to check if component is mounted
 */
export function useIsMounted(): () => boolean {
  const isMounted = useRef(false);
  
  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);
  
  return useCallback(() => isMounted.current, []);
}

// ============================================================================
// useConstant Hook
// ============================================================================

/**
 * Hook to create a constant value that never changes
 */
export function useConstant<T>(factory: () => T): T {
  const ref = useRef<{ value: T } | undefined>(undefined);
  
  if (!ref.current) {
    ref.current = { value: factory() };
  }
  
  return ref.current.value;
}

// ============================================================================
// useForceUpdate Hook
// ============================================================================

/**
 * Hook to force component re-render
 */
export function useForceUpdate(): () => void {
  const [, setTick] = React.useState<number>(0);
  
  return useCallback(() => {
    setTick((tick: number) => tick + 1);
  }, []);
}

// ============================================================================
// useLatest Hook
// ============================================================================

/**
 * Hook to always get the latest value without causing re-renders
 */
export function useLatest<T>(value: T): React.MutableRefObject<T> {
  const ref = useRef(value);
  
  useEffect(() => {
    ref.current = value;
  });
  
  return ref;
}

// ============================================================================
// useMountedState Hook
// ============================================================================

/**
 * Hook to get mounted state
 */
export function useMountedState(): () => boolean {
  const mountedRef = useRef<boolean>(false);
  const get = useCallback(() => mountedRef.current, []);
  
  useEffect(() => {
    mountedRef.current = true;
    
    return () => {
      mountedRef.current = false;
    };
  }, []);
  
  return get;
}

// ============================================================================
// useUnmount Hook
// ============================================================================

/**
 * Hook to run cleanup on unmount
 */
export function useUnmount(fn: () => void): void {
  const fnRef = useLatest(fn);
  
  useEffect(() => {
    return () => {
      fnRef.current();
    };
  }, []);
}

// ============================================================================
// Export React import
// ============================================================================

import * as React from 'react';

/**
 * useProjectFile Hook
 * 
 * Provides file-based project save/load operations with keyboard shortcuts.
 * Handles manual save (Ctrl/Cmd+S) and project file management.
 * 
 * Requirements: 19.4, 19.6, 19.7
 */

import { useCallback, useEffect, useState } from 'react';
import { useAppDispatch, useAppSelector } from '../store';
import { markSaved, setSaveStatus, setProject, updateSettings } from '../store/slices/projectSlice';
import { reorderShots, reorderTracks, setPlayheadPosition, setZoomLevel, setSelectedElements } from '../store/slices/timelineSlice';
import { loadAssets, setActiveCategory, setSearchQuery } from '../store/slices/assetsSlice';
import { setPanelLayout, setActivePanel, setShotConfigTarget } from '../store/slices/panelsSlice';
import { setActiveTool } from '../store/slices/toolsSlice';
import {
  saveProjectToFile,
  loadProjectFromFile,
  validateProjectCompatibility,
} from '../services/projectPersistence';
import type { Shot, Track, AssetCategory } from '../types';

export interface UseProjectFileResult {
  saveToFile: (filename?: string) => Promise<void>;
  loadFromFile: (file: File) => Promise<void>;
  isSaving: boolean;
  isLoading: boolean;
  error: string | null;
  clearError: () => void;
  // Dialog state and handlers for SequenceEditor compatibility
  showUnsavedDialog: boolean;
  handleSave: () => void | Promise<void>;
  handleDiscard: () => void;
  handleCancel: () => void;
  setShowUnsavedDialog: (show: boolean) => void;
}

/**
 * Hook for file-based project persistence
 */
export function useProjectFile(): UseProjectFileResult {
  const dispatch = useAppDispatch();
  const state = useAppSelector((state) => state);
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  /**
   * Save project to file
   * Requirement 19.4: Manual save option
   */
  const saveToFile = useCallback(async (filename?: string) => {
    setIsSaving(true);
    setError(null);
    
    try {
      // Set saving status
      dispatch(setSaveStatus({ state: 'saving' }));
      
      // Save to file
      saveProjectToFile(state, filename);
      
      // Mark as saved
      dispatch(markSaved());
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to save project';
      setError(errorMessage);
      dispatch(setSaveStatus({
        state: 'error',
        error: errorMessage,
      }));
      throw err;
    } finally {
      setIsSaving(false);
    }
  }, [state, dispatch]);
  
  /**
   * Load project from file
   * Requirement 19.4: Manual save option (load counterpart)
   */
  const loadFromFile = useCallback(async (file: File) => {
    setIsLoading(true);
    setError(null);
    
    try {
      // Load and parse file
      const projectData = await loadProjectFromFile(file);
      
      // Validate compatibility
      const validation = validateProjectCompatibility(projectData);
      if (!validation.compatible) {
        throw new Error(`Incompatible project file: ${validation.errors.join(', ')}`);
      }
      
      // Show warnings if any
      if (validation.warnings.length > 0) {
        console.warn('Project compatibility warnings:', validation.warnings);
      }
      
      // Restore project state
      if (projectData.project) {
        if (projectData.project.metadata) {
          dispatch(setProject(projectData.project.metadata));
        }
        if (projectData.project.settings) {
          dispatch(updateSettings(projectData.project.settings));
        }
      }
      
      // Restore timeline state
      if (projectData.timeline) {
        if (projectData.timeline.shots) {
          dispatch(reorderShots(projectData.timeline.shots as Shot[]));
        }
        if (projectData.timeline.tracks) {
          dispatch(reorderTracks(projectData.timeline.tracks as Track[]));
        }
        if (typeof projectData.timeline.playheadPosition === 'number') {
          dispatch(setPlayheadPosition(projectData.timeline.playheadPosition));
        }
        if (typeof projectData.timeline.zoomLevel === 'number') {
          dispatch(setZoomLevel(projectData.timeline.zoomLevel));
        }
        if (projectData.timeline.selectedElements) {
          dispatch(setSelectedElements(projectData.timeline.selectedElements));
        }
      }
      
      // Restore assets state
      if (projectData.assets) {
        if (projectData.assets.categories) {
          dispatch(loadAssets(projectData.assets.categories as AssetCategory[]));
        }
        if (projectData.assets.activeCategory) {
          dispatch(setActiveCategory(projectData.assets.activeCategory));
        }
        if (projectData.assets.searchQuery) {
          dispatch(setSearchQuery(projectData.assets.searchQuery));
        }
      }
      
      // Restore panels state
      if (projectData.panels) {
        if (projectData.panels.layout) {
          dispatch(setPanelLayout(projectData.panels.layout));
        }
        if (projectData.panels.activePanel) {
          dispatch(setActivePanel(projectData.panels.activePanel as 'assetLibrary' | 'preview' | 'shotConfig' | 'timeline' | null));
        }
        if (projectData.panels.shotConfigTarget) {
          dispatch(setShotConfigTarget(projectData.panels.shotConfigTarget));
        }
      }
      
      // Restore tools state
      if (projectData.tools) {
        if (projectData.tools.activeTool) {
          dispatch(setActiveTool(projectData.tools.activeTool as any));
        }
      }
      
      // Mark as saved
      dispatch(markSaved());
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load project';
      setError(errorMessage);
      dispatch(setSaveStatus({
        state: 'error',
        error: errorMessage,
      }));
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [dispatch]);
  
  /**
   * Clear error state
   */
  const clearError = useCallback(() => {
    setError(null);
  }, []);
  
  /**
   * Keyboard shortcut for save (Ctrl/Cmd+S)
   * Requirement 19.4: Manual save option
   */
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Check for Ctrl+S (Windows/Linux) or Cmd+S (Mac)
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        saveToFile();
      }
    };
    
    globalThis.addEventListener('keydown', handleKeyDown);
    
    return () => {
      globalThis.removeEventListener('keydown', handleKeyDown);
    };
  }, [saveToFile]);
  
  // State for unsaved changes dialog (for SequenceEditor compatibility)
  const [showUnsavedDialog, setShowUnsavedDialog] = useState(false);
  
  // Handlers for unsaved changes dialog
  const handleSave = useCallback(async () => {
    try {
      await saveToFile();
      setShowUnsavedDialog(false);
    } catch (err) {
      console.error('Failed to save:', err);
    }
  }, [saveToFile]);
  
  const handleDiscard = useCallback(() => {
    dispatch(markSaved());
    setShowUnsavedDialog(false);
  }, [dispatch]);
  
  const handleCancel = useCallback(() => {
    setShowUnsavedDialog(false);
  }, []);
  
  return {
    saveToFile,
    loadFromFile,
    isSaving,
    isLoading,
    error,
    clearError,
    // Dialog state and handlers for SequenceEditor compatibility
    showUnsavedDialog,
    handleSave,
    handleDiscard,
    handleCancel,
    setShowUnsavedDialog,
  };
}

/**
 * useProjectRecovery Hook
 * 
 * Manages automatic recovery snapshots and crash detection.
 * Provides recovery UI and snapshot management.
 * 
 * Requirements: 19.2
 */

import { useEffect, useState, useCallback, useRef } from 'react';
import { useAppDispatch, useAppSelector } from '../store';
import { setProject, updateSettings, markSaved } from '../store/slices/projectSlice';
import { reorderShots, reorderTracks, setPlayheadPosition, setZoomLevel, setSelectedElements } from '../store/slices/timelineSlice';
import { loadAssets, setActiveCategory, setSearchQuery } from '../store/slices/assetsSlice';
import { setPanelLayout, setActivePanel, setShotConfigTarget } from '../store/slices/panelsSlice';
import { setActiveTool } from '../store/slices/toolsSlice';
import {
  RecoveryManager,
  checkForCrashedSession,
  clearCrashedSessionFlag,
  getRecoverySnapshots,
  loadRecoverySnapshot,
  deleteRecoverySnapshot,
  clearAllRecoverySnapshots,
  formatSnapshotTimestamp,
  type RecoverySnapshot,
} from '../services/projectRecovery';
import type { Shot, Track, AssetCategory } from '../types';

export interface UseProjectRecoveryResult {
  hasCrashedSession: boolean;
  hasRecovery: boolean;
  recoverySnapshots: RecoverySnapshot[];
  showRecoveryDialog: boolean;
  recoverFromSnapshot: (snapshotId: string) => Promise<void>;
  handleRecover: (snapshotId: string) => Promise<void>;
  dismissCrashRecovery: () => void;
  handleDismiss: () => void;
  deleteSnapshot: (snapshotId: string) => void;
  clearAllSnapshots: () => void;
  formatTimestamp: (timestamp: string) => string;
  isRecovering: boolean;
  error: string | null;
}

/**
 * Hook for project recovery management
 */
export function useProjectRecovery(): UseProjectRecoveryResult {
  const dispatch = useAppDispatch();
  const state = useAppSelector((state) => state);
  const [hasCrashedSession, setHasCrashedSession] = useState(false);
  const [recoverySnapshots, setRecoverySnapshots] = useState<RecoverySnapshot[]>([]);
  const [isRecovering, setIsRecovering] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const recoveryManagerRef = useRef<RecoveryManager | null>(null);
  
  /**
   * Initialize recovery system
   * Requirement 19.2: Detect crashed sessions on startup
   */
  useEffect(() => {
    // Check for crashed session
    const crashed = checkForCrashedSession();
    setHasCrashedSession(crashed);
    
    // Load available snapshots
    const snapshots = getRecoverySnapshots();
    setRecoverySnapshots(snapshots);
    
    // Create recovery manager
    recoveryManagerRef.current = new RecoveryManager(() => state);
    
    // Start automatic snapshots
    recoveryManagerRef.current.start();
    
    // Cleanup on unmount
    return () => {
      if (recoveryManagerRef.current) {
        recoveryManagerRef.current.stop();
      }
    };
  }, []);
  
  /**
   * Recover project from snapshot
   * Requirement 19.2: Offer recovery option with timestamp
   */
  const recoverFromSnapshot = useCallback(async (snapshotId: string) => {
    setIsRecovering(true);
    setError(null);
    
    try {
      // Load snapshot data
      const projectData = loadRecoverySnapshot(snapshotId);
      
      if (!projectData) {
        throw new Error('Recovery snapshot not found');
      }
      
      // Restore project state
      if (projectData.project) {
        if (projectData.project.metadata) {
          dispatch(setProject(projectData.project.metadata));
        }
        if (projectData.project.settings) {
          dispatch(updateSettings(projectData.project.settings));
        }
      }
      
      // Restore timeline state
      if (projectData.timeline) {
        if (projectData.timeline.shots) {
          dispatch(reorderShots(projectData.timeline.shots as Shot[]));
        }
        if (projectData.timeline.tracks) {
          dispatch(reorderTracks(projectData.timeline.tracks as Track[]));
        }
        if (typeof projectData.timeline.playheadPosition === 'number') {
          dispatch(setPlayheadPosition(projectData.timeline.playheadPosition));
        }
        if (typeof projectData.timeline.zoomLevel === 'number') {
          dispatch(setZoomLevel(projectData.timeline.zoomLevel));
        }
        if (projectData.timeline.selectedElements) {
          dispatch(setSelectedElements(projectData.timeline.selectedElements));
        }
      }
      
      // Restore assets state
      if (projectData.assets) {
        if (projectData.assets.categories) {
          dispatch(loadAssets(projectData.assets.categories as AssetCategory[]));
        }
        if (projectData.assets.activeCategory) {
          dispatch(setActiveCategory(projectData.assets.activeCategory));
        }
        if (projectData.assets.searchQuery) {
          dispatch(setSearchQuery(projectData.assets.searchQuery));
        }
      }
      
      // Restore panels state
      if (projectData.panels) {
        if (projectData.panels.layout) {
          dispatch(setPanelLayout(projectData.panels.layout));
        }
        if (projectData.panels.activePanel) {
          dispatch(setActivePanel(projectData.panels.activePanel as 'assetLibrary' | 'preview' | 'shotConfig' | 'timeline' | null));
        }
        if (projectData.panels.shotConfigTarget) {
          dispatch(setShotConfigTarget(projectData.panels.shotConfigTarget));
        }
      }
      
      // Restore tools state
      if (projectData.tools) {
        if (projectData.tools.activeTool) {
          dispatch(setActiveTool(projectData.tools.activeTool as any));
        }
      }
      
      // Mark as saved
      dispatch(markSaved());
      
      // Clear crashed session flag
      clearCrashedSessionFlag();
      setHasCrashedSession(false);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to recover project';
      setError(errorMessage);
      throw err;
    } finally {
      setIsRecovering(false);
    }
  }, [dispatch]);
  
  /**
   * Dismiss crash recovery dialog
   */
  const dismissCrashRecovery = useCallback(() => {
    clearCrashedSessionFlag();
    setHasCrashedSession(false);
  }, []);
  
  /**
   * Delete a recovery snapshot
   */
  const deleteSnapshot = useCallback((snapshotId: string) => {
    deleteRecoverySnapshot(snapshotId);
    setRecoverySnapshots(getRecoverySnapshots());
  }, []);
  
  /**
   * Clear all recovery snapshots
   */
  const clearAllSnapshots = useCallback(() => {
    clearAllRecoverySnapshots();
    setRecoverySnapshots([]);
  }, []);
  
  /**
   * Format timestamp for display
   */
  const formatTimestamp = useCallback((timestamp: string) => {
    return formatSnapshotTimestamp(timestamp);
  }, []);
  
  // Derived state for compatibility
  const hasRecovery = hasCrashedSession || recoverySnapshots.length > 0;
  const showRecoveryDialog = hasRecovery;
  
  return {
    hasCrashedSession,
    hasRecovery,
    recoverySnapshots,
    showRecoveryDialog,
    recoverFromSnapshot,
    handleRecover: recoverFromSnapshot,
    dismissCrashRecovery,
    handleDismiss: dismissCrashRecovery,
    deleteSnapshot,
    clearAllSnapshots,
    formatTimestamp,
    isRecovering,
    error,
  };
}

