/**
 * ExportService
 * 
 * Export service for StoryCore Creative Studio.
 * Handles project export to different formats:
 * - JSON (Data Contract v1 Format)
 * - PDF (Project Report)
 * - Video (Promoted Sequence)
 * 
 * This service uses a project state-based approach (ProjectState)
 * and delegates actual operations to the existing ProjectExportService.
 * 
 * Requirements: 13.1-13.6
 */

import type { Project, Shot, Asset } from '@/types';
import { projectExportService, ExportResult } from './projectExportService';
import { logger } from '@/utils/logger';

/**
 * Project state interface for export service
 */
export interface ProjectState {
  project: Project | null;
  shots: Shot[];
  assets: Asset[];
  projectName: string;
}

/**
 * Export options for methods
 */
export interface ExportOptions {
  /** Include metadata in export */
  includeMetadata?: boolean;
  /** Export format (default: automatic based on method) */
  format?: string;
  /** Export quality (for PDF and Video) */
  quality?: 'low' | 'medium' | 'high';
}

/**
 * Progress callback for export operations
 */
export type ExportProgressCallback = (progress: number, message: string) => void;

/**
 * ExportService Class
 * 
 * Service principal pour les opérations d'export.
 * Fournit une interface simple basée sur ProjectState.
 * 
 * Example d'utilisation:
 * ```typescript
 * const state: ProjectState = { project, shots, assets, projectName };
 * const exportService = new ExportService(state);
 * const result = await exportService.exportJSON();
 * ```
 */
export class ExportService {
  private projectState: ProjectState;
  private progressCallback?: ExportProgressCallback;
  private onError?: (error: Error) => void;

  /**
   * ExportService constructor
   * 
   * @param projectState - Current project state
   */
  constructor(projectState: ProjectState) {
    this.projectState = projectState;
  }

  /**
   * Set progress callback
   */
  setProgressCallback(callback: ExportProgressCallback): void {
    this.progressCallback = callback;
  }

  /**
   * Set error callback
   */
  setOnError(callback: (error: Error) => void): void {
    this.onError = callback;
  }

  /**
   * Report progress
   */
  private reportProgress(progress: number, message: string): void {
    if (this.progressCallback) {
      this.progressCallback(progress, message);
    }
    logger.debug(`[ExportService] Progress: ${progress}% - ${message}`);
  }

  /**
   * Handle error
   */
  private handleError(error: Error, context: string): never {
    logger.error(`[ExportService] Error in ${context}:`, error);
    if (this.onError) {
      this.onError(error);
    }
    throw error;
  }

  /**
   * Get project from state
   */
  private getProject(): Project | null {
    return this.projectState.project;
  }

  /**
   * Validate project data before export
   * 
   * @returns true if data is valid
   */
  private validateProjectData(): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { projectName, shots } = this.projectState;

    // Validate project name
    if (!projectName || projectName.trim().length === 0) {
      errors.push('Le nom du projet est requis');
    }

    // Validate shots
    if (!shots || shots.length === 0) {
      errors.push('Le projet doit contenir au moins un plan');
    }

    // Validate each shot
    shots.forEach((shot, index) => {
      if (!shot.id) {
        errors.push(`Plan ${index + 1}: L'ID est requis`);
      }
      if (!shot.title || shot.title.trim().length === 0) {
        errors.push(`Plan ${index + 1}: Le titre est requis`);
      }
      if (shot.duration <= 0) {
        errors.push(`Plan ${index + 1}: La durée doit être supérieure à 0`);
      }
    });

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Export project to JSON format
   * 
   * Collects project data, validates, and generates a formatted JSON file.
   * Uses Electron API to save file if available.
   * 
   * @param options - Optional export options
   * @returns Promise<ExportResult> - Export result
   */
  async exportJSON(options?: ExportOptions): Promise<ExportResult> {
    const context = 'exportJSON';
    this.reportProgress(0, 'Starting JSON export...');

    try {
      // Valider les données
      this.reportProgress(10, 'Validation des données du projet...');
      const validation = this.validateProjectData();
      
      if (!validation.valid) {
        throw new Error(`Validation échouée: ${validation.errors.join(', ')}`);
      }

      const project = this.getProject();
      if (!project) {
        throw new Error('Aucun projet à exporter');
      }

      // Delegate to existing export service
      this.reportProgress(50, 'Generating JSON...');
      const result = await projectExportService.exportJSON(project);

      if (result.success) {
        this.reportProgress(100, 'JSON export completed');
        logger.debug(`[ExportService] JSON exported successfully: ${result.filePath}`);
      } else {
        this.reportProgress(100, 'JSON export failed');
        if (result.error) {
          this.handleError(result.error, context);
        }
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error(`[ExportService] JSON export failed: ${errorMessage}`);

      return {
        success: false,
        error: error instanceof Error ? error : new Error(errorMessage),
      };
    }
  }

  /**
   * Export project to PDF format
   * 
   * Uses jsPDF to generate a project report including:
   * - Title page with metadata
   * - Liste des plans avec descriptions
   * - Liste des assets
   * - Statut des capacités et de la génération
   * 
   * @param options - Options d'export optionnelles (quality, includeMetadata)
   * @returns Promise<ExportResult> - Résultat de l'export
   */
  async exportPDF(options?: ExportOptions): Promise<ExportResult> {
    const context = 'exportPDF';
    this.reportProgress(0, 'Starting PDF export...');

    try {
      // Validate data
      this.reportProgress(10, 'Validating project data...');
      const validation = this.validateProjectData();
      
      if (!validation.valid) {
        throw new Error(`Validation failed: ${validation.errors.join(', ')}`);
      }

      const project = this.getProject();
      if (!project) {
        throw new Error('No project to export');
      }

      // Delegate to existing export service
      this.reportProgress(30, 'Generating PDF content...');
      const result = await projectExportService.exportPDF(project);

      if (result.success) {
        this.reportProgress(100, 'PDF export completed');
        logger.debug(`[ExportService] PDF exported successfully: ${result.filePath}`);
      } else {
        this.reportProgress(100, 'PDF export failed');
        if (result.error) {
          this.handleError(result.error, context);
        }
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error(`[ExportService] PDF export failed: ${errorMessage}`);

      return {
        success: false,
        error: error instanceof Error ? error : new Error(errorMessage),
      };
    }
  }

  /**
   * Export project to Video format
   * 
   * Integration with existing video rendering service.
   * Collects promoted shots and assets to generate a video sequence.
   * 
   * Note: Full FFmpeg implementation is in development.
   * Currently returns a placeholder with integration instructions.
   * 
   * @param options - Optional export options (quality)
   * @returns Promise<ExportResult> - Export result
   */
  async exportVideo(options?: ExportOptions): Promise<ExportResult> {
    const context = 'exportVideo';
    this.reportProgress(0, 'Starting video export...');

    try {
      // Validate data
      this.reportProgress(10, 'Validating project data...');
      const validation = this.validateProjectData();
      
      if (!validation.valid) {
        throw new Error(`Validation failed: ${validation.errors.join(', ')}`);
      }

      const project = this.getProject();
      if (!project) {
        throw new Error('No project to export');
      }

      // Check for shots with promoted panels
      const shotsWithPanels = project.shots.filter(shot => (shot as any).promoted_panel_path);
      
      if (shotsWithPanels.length === 0) {
        throw new Error('No promoted shots found. Please promote shots before exporting to video.');
      }

      // Delegate to existing export service
      this.reportProgress(40, 'Generating video sequence...');
      const result = await projectExportService.exportVideo(project);

      if (result.success) {
        this.reportProgress(100, 'Video export completed');
        logger.debug(`[ExportService] Video exported successfully: ${result.filePath}`);
      } else {
        this.reportProgress(100, 'Video export failed');
        if (result.error) {
          this.handleError(result.error, context);
        }
      }

      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error(`[ExportService] Video export failed: ${errorMessage}`);

      return {
        success: false,
        error: error instanceof Error ? error : new Error(errorMessage),
      };
    }
  }

  /**
   * Export multiple formats
   *
   * Exports the project in multiple formats simultaneously.
   * 
   * @param formats - Formats à exporter
   * @param options - Options d'export
   * @returns Promise<Map<string, ExportResult>> - Résultats par format
   */
  async exportMultiple(
    formats: ('json' | 'pdf' | 'video')[],
    options?: ExportOptions
  ): Promise<Map<string, ExportResult>> {
    const results = new Map<string, ExportResult>();

    for (const format of formats) {
      let result: ExportResult;
      
      switch (format) {
        case 'json':
          result = await this.exportJSON(options);
          break;
        case 'pdf':
          result = await this.exportPDF(options);
          break;
        case 'video':
          result = await this.exportVideo(options);
          break;
        default:
          result = {
            success: false,
            error: new Error(`Format non supporté: ${format}`),
          };
      }
      
      results.set(format, result);
    }

    return results;
  }
}

/**
 * Factory function pour créer un ExportService à partir de l'état de l'application
 * 
 * @param projectState - État du projet
 * @returns Nouvelle instance de ExportService
 */
export function createExportService(projectState: ProjectState): ExportService {
  return new ExportService(projectState);
}

/**
 * Export par défaut - instance singleton du ExportService
 * Note: Préférez créer une nouvelle instance avec createExportService
 * pour une meilleure isolation des états.
 */
export const exportService = new ExportService({
  project: null,
  shots: [],
  assets: [],
  projectName: '',
});

/**
 * FileSystemService - File System Management Service for StoryCore
 *
 * Provides methods to read and write configuration files
 * with error handling and localStorage synchronization
 * 
 * Compatible with browser and Node.js environments
 */

import { AddonConfig } from './AddonManager';
import { logger } from '@/utils/logger';

/**
 * Node.js fs.promises interface
 */
interface NodeFsPromises {
  readFile(path: string, encoding: string): Promise<string>;
  writeFile(path: string, data: string, encoding: string): Promise<void>;
  access(path: string): Promise<void>;
  mkdir(path: string, options?: { recursive?: boolean }): Promise<void>;
  unlink(path: string): Promise<void>;
}

/**
 * Node.js path module interface
 */
interface NodePath {
  dirname(path: string): string;
  join(...paths: string[]): string;
  resolve(...paths: string[]): string;
}

/**
 * Error with code property (Node.js style error)
 */
interface NodeJSError extends Error {
  code?: string;
}

/**
 * Type guard to check if an error has a code property
 */
function isNodeJSError(error: unknown): error is NodeJSError {
  return error instanceof Error && 'code' in error;
}

// Type guard to check if we are in a Node.js environment
const isNodeEnvironment = typeof globalThis !== 'undefined' && 
                          typeof globalThis.window === 'undefined' && 
                          typeof process !== 'undefined';

// Lazy loading of Node.js modules to avoid errors in browser
let fs: NodeFsPromises | null = null;
let path: NodePath | null = null;

if (isNodeEnvironment) {
  try {
     
    const nodeFs = require('node:fs');
     
    const nodePath = require('node:path');
    fs = nodeFs.promises;
    path = nodePath;
  } catch (error) {
    logger.warn('[FileSystemService] Unable to load Node.js modules:', error);
  }
}

export class FileSystemService {
    private static instance: FileSystemService;
    private readonly useFileSystem: boolean;
    
    private constructor() {
        this.useFileSystem = isNodeEnvironment && fs !== null;
    }
    
    /**
     * Obtient l'instance singleton du service
     */
    static getInstance(): FileSystemService {
        if (!FileSystemService.instance) {
            FileSystemService.instance = new FileSystemService();
        }
        return FileSystemService.instance;
    }
    
    /**
     * Vérifie si le système de fichiers est disponible
     */
    private isFileSystemAvailable(): boolean {
        return this.useFileSystem;
    }
    
    /**
     * Lit le fichier de configuration des add-ons
     * @param filePath Chemin du fichier de configuration
     * @returns Configuration des add-ons
     * @throws Error Si le fichier existe mais est invalide
     */
    async readConfigFile(filePath: string): Promise<AddonConfig> {
        // Utiliser localStorage en premier dans le browser
        if (!this.isFileSystemAvailable() || !fs) {
            return this.readFromLocalStorage();
        }
        
        try {
            const data = await fs.readFile(filePath, 'utf-8');
            const parsed = JSON.parse(data);
            
            // Validation du format
            if (!parsed.addons || typeof parsed.addons !== 'object') {
                throw new Error('Format de configuration invalide: la propriété "addons" est manquante ou invalide');
            }
            
            return parsed.addons;
        } catch (error: unknown) {
            // Handle specific errors
            if (isNodeJSError(error) && error.code === 'ENOENT') {
                // File not found - try localStorage
                logger.warn(`[FileSystemService] File not found: ${filePath}, fallback to localStorage`);
                return this.readFromLocalStorage();
            }
            
            if (error instanceof SyntaxError) {
                throw new Error(`Invalid JSON format in ${filePath}: ${error.message}`);
            }
            
            // Handle permission errors
            if (isNodeJSError(error) && (error.code === 'EACCES' || error.code === 'EPERM')) {
                throw new Error(`Permission denied to read file ${filePath}`);
            }
            
            // On error, try localStorage
            logger.warn(`[FileSystemService] Error reading file, fallback to localStorage:`, error);
            return this.readFromLocalStorage();
        }
    }
    
    /**
     * Reads configuration from localStorage
     */
    private readFromLocalStorage(): Promise<AddonConfig> {
        try {
            const data = localStorage.getItem('storycore_addon_config');
            if (data) {
                return Promise.resolve(JSON.parse(data));
            }
        } catch (error) {
            logger.warn('[FileSystemService] Error reading from localStorage:', error);
        }
        return Promise.resolve({});
    }
    
    /**
     * Écrit la configuration des add-ons dans un fichier
     * @param filePath Chemin du fichier de configuration
     * @param config Configuration des add-ons à sauvegarder
     * @throws Error Si l'écriture du fichier échoue
     */
    async writeConfigFile(filePath: string, config: AddonConfig): Promise<void> {
        // Sync with localStorage in all cases
        await this.syncWithLocalStorage(config);
        
        // If no file system available, stop here
        if (!this.isFileSystemAvailable() || !fs || !path) {
            logger.debug('[FileSystemService] Configuration saved to localStorage only (browser)');
            return;
        }
        
        try {
            // Ensure directory exists
            await this.ensureDirectoryExists(path.dirname(filePath));
            
            // Create complete structure with metadata
            const fullConfig = {
                version: '1.0',
                timestamp: new Date().toISOString(),
                addons: config
            };
            
            // Write file with readable JSON formatting
            await fs.writeFile(filePath, JSON.stringify(fullConfig, null, 2), 'utf-8');
            
            logger.debug(`[FileSystemService] Configuration saved to ${filePath}`);
        } catch (error: unknown) {
            // Handle permission errors
            if (isNodeJSError(error) && (error.code === 'EACCES' || error.code === 'EPERM')) {
                throw new Error(`Permission denied to write file ${filePath}`);
            }
            
            // Handle disk space errors
            if (isNodeJSError(error) && error.code === 'ENOSPC') {
                throw new Error(`Insufficient disk space to write file ${filePath}`);
            }
            
            logger.error(`[FileSystemService] Failed to write file ${filePath}:`, error);
            // Don't throw since localStorage sync succeeded
        }
    }
    
    /**
     * Ensures the directory exists, creates it if necessary
     * @param dirPath Directory path
     */
    async ensureDirectoryExists(dirPath: string): Promise<void> {
        if (!this.isFileSystemAvailable() || !fs) {
            return;
        }
        
        try {
            // Check if directory exists
            await fs.access(dirPath);
        } catch {
            // Directory doesn't exist, create it recursively
            try {
                await fs.mkdir(dirPath, { recursive: true });
                logger.debug(`[FileSystemService] Directory created: ${dirPath}`);
            } catch (error: unknown) {
                // Handle permission errors
                if (isNodeJSError(error) && (error.code === 'EACCES' || error.code === 'EPERM')) {
                    throw new Error(`Permission denied to create directory ${dirPath}`);
                }
                
                logger.error(`[FileSystemService] Failed to create directory ${dirPath}:`, error);
                const errorMessage = error instanceof Error ? error.message : String(error);
                throw new Error(`Failed to create directory: ${errorMessage}`);
            }
        }
    }
    
    /**
     * Synchronizes configuration with localStorage
     * @param config Configuration to synchronize
     * @throws Error If localStorage synchronization fails
     */
    async syncWithLocalStorage(config: AddonConfig): Promise<void> {
        try {
            // Save to localStorage
            localStorage.setItem('storycore_addon_config', JSON.stringify(config));
            logger.debug('[FileSystemService] Configuration synchronized with localStorage');
        } catch (error: unknown) {
            // Handle quota exceeded errors
            if (error instanceof Error && error.name === 'QuotaExceededError') {
                throw new Error('Local storage quota exceeded');
            }
            
            logger.error('[FileSystemService] Failed to synchronize with localStorage:', error);
            const errorMessage = error instanceof Error ? error.message : String(error);
            throw new Error(`Failed to synchronize with localStorage: ${errorMessage}`);
        }
    }
    
    /**
     * Checks if a file exists
     * @param filePath File path
     * @returns true if file exists, false otherwise
     */
    async fileExists(filePath: string): Promise<boolean> {
        if (!this.isFileSystemAvailable() || !fs) {
            return false;
        }
        
        try {
            await fs.access(filePath);
            return true;
        } catch {
            return false;
        }
    }
    
    /**
     * Deletes a configuration file
     * @param filePath Path of the file to delete
     * @throws Error If deletion fails
     */
    async deleteConfigFile(filePath: string): Promise<void> {
        if (!this.isFileSystemAvailable() || !fs) {
            return;
        }
        
        try {
            await fs.unlink(filePath);
            logger.debug(`[FileSystemService] File deleted: ${filePath}`);
        } catch (error: unknown) {
            // Handle specific errors
            if (isNodeJSError(error) && error.code === 'ENOENT') {
                // File not found - not a critical error
                logger.warn(`[FileSystemService] File not found for deletion: ${filePath}`);
                return;
            }
            
            // Handle permission errors
            if (isNodeJSError(error) && (error.code === 'EACCES' || error.code === 'EPERM')) {
                throw new Error(`Permission denied to delete file ${filePath}`);
            }
            
            logger.error(`[FileSystemService] Failed to delete file ${filePath}:`, error);
            const errorMessage = error instanceof Error ? error.message : String(error);
            throw new Error(`Failed to delete file: ${errorMessage}`);
        }
    }
}

// Export de l'instance singleton
export const fileSystemService = FileSystemService.getInstance();

/**
 * FormAutoFill - Pré-remplissage automatique des formulaires
 *
 * Utilise l'extracteur de contexte pour pré-remplir automatiquement
 * les formulaires des wizards avec des valeurs extraites du texte utilisateur
 */

import { contextExtractor, ExtractedContext, WorldContext, CharacterContext, SceneContext, DialogueContext, StoryboardContext, StyleContext } from './ContextExtractor';
import { World } from '@/types/world';
import { Character } from '@/types/character';

export interface AutoFillResult {
  success: boolean;
  filledFields: string[];
  suggestions: string[];
  confidence: number;
  data: unknown;
}

export interface FormData {
  [key: string]: unknown;
}

/**
 * Service de pré-remplissage automatique des formulaires
 */
export class FormAutoFill {
  private static instance: FormAutoFill;

  private constructor() {}

  static getInstance(): FormAutoFill {
    if (!FormAutoFill.instance) {
      FormAutoFill.instance = new FormAutoFill();
    }
    return FormAutoFill.instance;
  }

  /**
   * Pré-remplit automatiquement un formulaire de monde
   */
  autoFillWorldForm(text: string): AutoFillResult {
    const context = contextExtractor.analyzeText(text);
    const filledFields: string[] = [];
    const suggestions = contextExtractor.getSuggestions(context);

    if (!context.worldContext) {
      return {
        success: false,
        filledFields: [],
        suggestions,
        confidence: context.confidence,
        data: {}
      };
    }

    const formData: Partial<World> = {};

    // Mapping du contexte vers les champs du formulaire
    const worldContext = context.worldContext;

    // Nom du monde
    if (worldContext.name) {
      formData.name = worldContext.name;
      filledFields.push('name');
    }

    // Genres
    if (worldContext.genre && worldContext.genre.length > 0) {
      formData.genre = worldContext.genre;
      filledFields.push('genre');
    }

    // Tons
    if (worldContext.tone && worldContext.tone.length > 0) {
      formData.tone = worldContext.tone;
      filledFields.push('tone');
    }

    // Période temporelle
    if (worldContext.timePeriod) {
      formData.timePeriod = worldContext.timePeriod;
      filledFields.push('timePeriod');
    }

    // Atmosphère
    if (worldContext.atmosphere) {
      formData.atmosphere = worldContext.atmosphere;
      filledFields.push('atmosphere');
    }

    // Règles
    if (worldContext.rules && worldContext.rules.length > 0) {
      formData.rules = worldContext.rules;
      filledFields.push('rules');
    }

    // Magie
    if (worldContext.magic) {
      formData.magic = worldContext.magic;
      filledFields.push('magic');
    }

    // Technologie
    if (worldContext.technology) {
      formData.technology = worldContext.technology;
      filledFields.push('technology');
    }

    // Conflits
    if (worldContext.conflicts && worldContext.conflicts.length > 0) {
      formData.conflicts = worldContext.conflicts;
      filledFields.push('conflicts');
    }

    // Lieux
    if (worldContext.locations && worldContext.locations.length > 0) {
      formData.locations = worldContext.locations.map(loc => ({
        id: crypto.randomUUID(),
        name: loc.name || '',
        description: loc.description || '',
        type: loc.type || 'location'
      }));
      filledFields.push('locations');
    }

    return {
      success: filledFields.length > 0,
      filledFields,
      suggestions,
      confidence: context.confidence,
      data: formData
    };
  }

  /**
   * Pré-remplit automatiquement un formulaire de personnage
   */
  autoFillCharacterForm(text: string): AutoFillResult {
    const context = contextExtractor.analyzeText(text);
    const filledFields: string[] = [];
    const suggestions = contextExtractor.getSuggestions(context);

    if (!context.characterContext) {
      return {
        success: false,
        filledFields: [],
        suggestions,
        confidence: context.confidence,
        data: {}
      };
    }

    const formData: Partial<Character> = {};
    const characterContext = context.characterContext;

    // Nom du personnage
    if (characterContext.name) {
      formData.name = characterContext.name;
      filledFields.push('name');
    }

    // Traits de personnalité
    if (characterContext.personality && characterContext.personality.length > 0) {
      formData.personality = {
        traits: characterContext.personality,
        values: [],
        fears: [],
        desires: [],
        flaws: [],
        strengths: [],
        temperament: '',
        communication_style: ''
      };
      filledFields.push('personality');
    }

    // Apparence
    if (characterContext.appearance) {
      formData.visual_identity = {
        hair_color: '',
        hair_style: '',
        hair_length: '',
        eye_color: '',
        eye_shape: '',
        skin_tone: '',
        facial_structure: '',
        distinctive_features: [],
        age_range: characterContext.age || '',
        height: '',
        build: '',
        posture: '',
        clothing_style: characterContext.appearance,
        color_palette: []
      };
      filledFields.push('visual_identity');
    }

    // Background
    if (characterContext.background || characterContext.occupation) {
      formData.background = {
        origin: '',
        occupation: characterContext.occupation || '',
        education: '',
        family: '',
        significant_events: [],
        current_situation: characterContext.background || ''
      };
      filledFields.push('background');
    }

    // Relations
    if (characterContext.relationships && characterContext.relationships.length > 0) {
      formData.relationships = characterContext.relationships;
      filledFields.push('relationships');
    }

    return {
      success: filledFields.length > 0,
      filledFields,
      suggestions,
      confidence: context.confidence,
      data: formData
    };
  }

  /**
   * Pré-remplit automatiquement un formulaire de scène
   */
  autoFillSceneForm(text: string): AutoFillResult {
    const context = contextExtractor.analyzeText(text);
    const filledFields: string[] = [];
    const suggestions = contextExtractor.getSuggestions(context);

    if (!context.sceneContext) {
      return {
        success: false,
        filledFields: [],
        suggestions,
        confidence: context.confidence,
        data: {}
      };
    }

    const formData: unknown = {};
    const sceneContext = context.sceneContext;

    // Type de scène
    if (sceneContext.type) {
      formData.sceneType = sceneContext.type;
      filledFields.push('sceneType');
    }

    // Lieu
    if (sceneContext.location) {
      formData.location = sceneContext.location;
      filledFields.push('location');
    }

    // Moment de la journée
    if (sceneContext.time) {
      formData.timeOfDay = sceneContext.time;
      filledFields.push('timeOfDay');
    }

    // Personnages présents
    if (sceneContext.characters && sceneContext.characters.length > 0) {
      formData.characters = sceneContext.characters;
      filledFields.push('characters');
    }

    // Action/Description
    if (sceneContext.action) {
      formData.description = sceneContext.action;
      filledFields.push('description');
    }

    // Ambiance
    if (sceneContext.mood) {
      formData.mood = sceneContext.mood;
      filledFields.push('mood');
    }

    return {
      success: filledFields.length > 0,
      filledFields,
      suggestions,
      confidence: context.confidence,
      data: formData
    };
  }

