        /\*\*(?:Description|Appearance|Overview)\s*[:：]?\*\*\s*(.+?)(?:\n\n|\n(?=[A-Z*#-]))/gis,
    ],
};

const GENDER_PATTERNS = {
    fr: [
        /(?:genre|sexe)\s*[:：]\s*(homme|femme|masculin|féminin|non-binaire|neutre)/gi,
        /\*\*(?:Genre|Sexe)\s*[:：]?\*\*\s*(homme|femme|masculin|féminin|non-binaire|neutre)/gi,
