        /(?:type|catégorie|genre)\s*[:：]\s*(.+?)(?:\n|$)/gi,
        /\*\*(?:Type|Catégorie)\s*[:：]?\*\*\s*(.+?)(?:\n|$)/gi,
    ],
    en: [
        /(?:type|category|kind)\s*[:：]\s*(.+?)(?:\n|$)/gi,
