const USAGE_PATTERNS = {
    fr: [
        /(?:utilisation|usage|fonction)\s*[:：]\s*(.+?)(?:\n|$)/gi,
        /\*\*(?:Utilisation|Usage|Fonction)\s*[:：]?\*\*\s*(.+?)(?:\n|$)/gi,
    ],
    en: [
        /(?:usage|use|function)\s*[:：]\s*(.+?)(?:\n|$)/gi,
