/**
 * OfflineService - Enhanced Offline Mode Service
 *
 * Manages intelligent suggestion caching, basic offline functionality,
 * and automatic synchronization on reconnection.
 */

import { promptSuggestionService, type PromptSuggestion, type Message } from './PromptSuggestionService';
import { notificationService } from './NotificationService';
import { logger } from '@/utils/logger';

export interface CachedSuggestion {
  id: string;
  suggestions: PromptSuggestion[];
  context: string;
  timestamp: Date;
  expiresAt: Date;
}

/**
 * Serialized format for cached suggestions in localStorage
 */
interface SerializedCachedSuggestion {
  id: string;
  suggestions: PromptSuggestion[];
  context: string;
  timestamp: string;
  expiresAt: string;
}

export interface OfflineCapabilities {
  canGenerateSuggestions: boolean;
  canUseCachedData: boolean;
  canSaveLocally: boolean;
  hasNetworkAccess: boolean;
  lastOnlineCheck: Date;
}

export interface SyncStatus {
  isOnline: boolean;
  lastSync: Date;
  pendingUploads: number;
  cachedItems: number;
  syncInProgress: boolean;
}

/**
 * Service de gestion du mode hors-ligne
 */
export class OfflineService {
  private static instance: OfflineService;
  private cachedSuggestions: CachedSuggestion[] = [];
  private readonly capabilities: OfflineCapabilities;
  private readonly syncStatus: SyncStatus;
  private syncListeners: Array<(status: SyncStatus) => void> = [];
  private onlineCheckInterval: NodeJS.Timeout | null = null;

  private constructor() {
    this.capabilities = this.initializeCapabilities();
    this.syncStatus = this.initializeSyncStatus();
    this.loadCachedData();
    this.startPeriodicOnlineCheck();
  }

  static getInstance(): OfflineService {
    if (!OfflineService.instance) {
      OfflineService.instance = new OfflineService();
    }
    return OfflineService.instance;
  }

  /**
   * Initialise les capacités hors-ligne
   */
  private initializeCapabilities(): OfflineCapabilities {
    return {
      canGenerateSuggestions: true, // Les suggestions sont générées localement
      canUseCachedData: true,
      canSaveLocally: true,
      hasNetworkAccess: navigator.onLine,
      lastOnlineCheck: new Date()
    };
  }

  /**
   * Initialise le statut de synchronisation
   */
  private initializeSyncStatus(): SyncStatus {
    return {
      isOnline: navigator.onLine,
      lastSync: new Date(),
      pendingUploads: 0,
      cachedItems: 0,
      syncInProgress: false
    };
  }

  /**
   * Charge les données mises en cache
   */
  private loadCachedData(): void {
    try {
      const cached = localStorage.getItem('offline-suggestions-cache');
      if (cached) {
        const parsed: SerializedCachedSuggestion[] = JSON.parse(cached);
        this.cachedSuggestions = parsed.map((item) => ({
          id: item.id,
          suggestions: item.suggestions,
          context: item.context,
          timestamp: new Date(item.timestamp),
          expiresAt: new Date(item.expiresAt)
        }));

        // Clean expired items
        this.cleanExpiredCache();
        this.syncStatus.cachedItems = this.cachedSuggestions.length;
      }
    } catch (error) {
      logger.warn('[OfflineService] Failed to load cached suggestions:', error);
      this.cachedSuggestions = [];
    }
  }

  /**
   * Save cached data
   */
  private saveCachedData(): void {
    try {
      const dataToSave = this.cachedSuggestions.map(item => ({
        ...item,
        timestamp: item.timestamp.toISOString(),
        expiresAt: item.expiresAt.toISOString()
      }));
      localStorage.setItem('offline-suggestions-cache', JSON.stringify(dataToSave));
      this.syncStatus.cachedItems = this.cachedSuggestions.length;
      this.notifySyncListeners();
    } catch (error) {
      logger.warn('[OfflineService] Failed to save cached suggestions:', error);
    }
  }

  /**
   * Clean expired cache
   */
  private cleanExpiredCache(): void {
    const now = new Date();
    const initialCount = this.cachedSuggestions.length;
    this.cachedSuggestions = this.cachedSuggestions.filter(item =>
      item.expiresAt > now
    );

    if (this.cachedSuggestions.length !== initialCount) {
      this.saveCachedData();
    }
  }

  /**
   * Démarre la vérification périodique de la connexion
   */
  private startPeriodicOnlineCheck(): void {
    // Vérifier la connexion toutes les 30 secondes
    this.onlineCheckInterval = setInterval(() => {
      this.checkOnlineStatus();
    }, 30000);

    // Écouter les événements de changement de connexion
    globalThis.addEventListener('online', () => this.handleOnline());
    globalThis.addEventListener('offline', () => this.handleOffline());
  }

  /**
   * Vérifie le statut de la connexion
   */
  private checkOnlineStatus(): void {
    const wasOnline = this.syncStatus.isOnline;
    const isOnline = navigator.onLine;

    this.capabilities.hasNetworkAccess = isOnline;
    this.capabilities.lastOnlineCheck = new Date();

    if (wasOnline !== isOnline) {
      if (isOnline) {
        this.handleOnline();
      } else {
        this.handleOffline();
      }
    }
  }

  /**
   * Gère le passage en ligne
   */
  private handleOnline(): void {
    this.syncStatus.isOnline = true;
    this.syncStatus.lastSync = new Date();

    notificationService.info(
      'Connexion rétablie',
      'Vous êtes de nouveau en ligne. Synchronisation en cours...'
    );

    // Démarrer la synchronisation automatique
    this.performSync();
  }

  /**
   * Gère le passage hors ligne
   */
  private handleOffline(): void {
    this.syncStatus.isOnline = false;

    notificationService.warning(
      'Mode hors ligne',
      'Connexion perdue. Utilisation du mode hors ligne avec données mises en cache.',
      [
        {
          label: 'Continuer',
          action: () => {},
          primary: true
        }
      ]
    );
  }

  /**
   * Effectue la synchronisation
   */
  private async performSync(): Promise<void> {
    if (this.syncStatus.syncInProgress) return;

    this.syncStatus.syncInProgress = true;
    this.notifySyncListeners();

    try {
      // Simuler une synchronisation (dans un vrai système, cela uploaderait les données locales)
      await new Promise(resolve => setTimeout(resolve, 2000));

      this.syncStatus.lastSync = new Date();
      this.syncStatus.pendingUploads = 0;

      notificationService.success(
        'Synchronisation terminée',
        'Toutes vos données ont été synchronisées avec succès.'
      );

    } catch (error) {
      logger.error('[OfflineService] Sync failed:', error);
      notificationService.error(
        'Erreur de synchronisation',
        'Impossible de synchroniser les données. Réessayer plus tard.',
        [
          {
            label: 'Réessayer',
            action: () => { this.performSync(); },
            primary: true
          }
        ]
      );
    } finally {
      this.syncStatus.syncInProgress = false;
      this.notifySyncListeners();
    }
  }

  /**
   * Génère des suggestions avec cache intelligent
   */
  async generateOfflineSuggestions(
    messages: Message[],
    language: string,
    currentInput: string = ''
  ): Promise<PromptSuggestion[]> {
    // Essayer d'abord de récupérer depuis le cache
    const cacheKey = this.generateCacheKey(messages, language, currentInput);
    const cached = this.getCachedSuggestions(cacheKey);

    if (cached) {
      return cached.suggestions;
    }

    // Générer de nouvelles suggestions
    let suggestions: PromptSuggestion[];

    if (this.capabilities.canGenerateSuggestions) {
      try {
        suggestions = promptSuggestionService.generateSuggestions(
          messages,
          language as any,
          currentInput
        );
      } catch (error) {
        logger.warn('[OfflineService] Failed to generate suggestions:', error);
        // Fallback to default suggestions
        suggestions = promptSuggestionService.getDefaultSuggestions(language as any);
      }
    } else {
      // Degraded mode: only default suggestions
      suggestions = promptSuggestionService.getDefaultSuggestions(language as any);
    }

    // Mettre en cache si en ligne
    if (this.syncStatus.isOnline) {
      this.cacheSuggestions(cacheKey, suggestions, currentInput);
    }

    return suggestions;
  }

  /**
   * Génère une clé de cache
   */
  private generateCacheKey(messages: Message[], language: string, input: string): string {
    const recentMessages = messages.slice(-3);
    const content = recentMessages.map(m => m.content).join('') + input + language;
    return btoa(content).substring(0, 32); // Hash simple
  }

  /**
   * Récupère les suggestions depuis le cache
   */
  private getCachedSuggestions(cacheKey: string): CachedSuggestion | null {
    const cached = this.cachedSuggestions.find(item =>
      item.id === cacheKey &&
      item.expiresAt > new Date()
    );
    return cached || null;
  }

  /**
   * Met en cache les suggestions
   */
  private cacheSuggestions(cacheKey: string, suggestions: PromptSuggestion[], context: string): void {
    const cachedItem: CachedSuggestion = {
      id: cacheKey,
      suggestions,
      context,
      timestamp: new Date(),
      expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000) // Expire dans 24h
    };

    // Éviter les doublons
    this.cachedSuggestions = this.cachedSuggestions.filter(item => item.id !== cacheKey);
    this.cachedSuggestions.unshift(cachedItem);

    // Limiter la taille du cache
    if (this.cachedSuggestions.length > 100) {
      this.cachedSuggestions = this.cachedSuggestions.slice(0, 100);
    }

    this.saveCachedData();
  }

  /**
   * Obtient les capacités hors-ligne actuelles
   */
  getCapabilities(): OfflineCapabilities {
    return { ...this.capabilities };
  }

  /**
   * Obtient le statut de synchronisation
   */
  getSyncStatus(): SyncStatus {
    return { ...this.syncStatus };
  }

  /**
   * S'abonne aux changements de statut de synchronisation
   */
  subscribeToSync(listener: (status: SyncStatus) => void): () => void {
    this.syncListeners.push(listener);
    return () => {
      this.syncListeners = this.syncListeners.filter(l => l !== listener);
    };
  }

  /**
   * Notifie les listeners de synchronisation
   */
  private notifySyncListeners(): void {
    this.syncListeners.forEach(listener => listener(this.syncStatus));
  }

  /**
   * Force une synchronisation
   */
  async forceSync(): Promise<void> {
    if (!this.syncStatus.isOnline) {
      notificationService.warning(
        'Impossible de synchroniser',
        'Aucune connexion internet disponible.'
      );
      return;
    }

    await this.performSync();
  }

  /**
   * Vide le cache
   */
  clearCache(): void {
    this.cachedSuggestions = [];
    this.saveCachedData();

    notificationService.info(
      'Cache vidé',
      'Le cache des suggestions a été vidé avec succès.'
    );
  }

  /**
   * Obtient des statistiques de cache
   */
  getCacheStats(): { totalItems: number; totalSize: number; oldestItem: Date | null; newestItem: Date | null } {
    const totalItems = this.cachedSuggestions.length;
    const totalSize = JSON.stringify(this.cachedSuggestions).length;
    const timestamps = this.cachedSuggestions.map(item => item.timestamp);

    return {
      totalItems,
      totalSize,
      oldestItem: timestamps.length > 0 ? new Date(Math.min(...timestamps.map(t => t.getTime()))) : null,
      newestItem: timestamps.length > 0 ? new Date(Math.max(...timestamps.map(t => t.getTime()))) : null
    };
  }

  /**
   * Nettoie les ressources
   */
  destroy(): void {
    if (this.onlineCheckInterval) {
      clearInterval(this.onlineCheckInterval);
    }
    this.syncListeners = [];
    this.cachedSuggestions = [];
  }
}

// Export de l'instance singleton
export const offlineService = OfflineService.getInstance();

/**
 * PersistenceCache - Cache intelligent pour optimiser les performances
 *
 * Cache avec TTL et stratégie d'éviction LRU pour améliorer les performances
 * des opérations de persistance fréquentes
 */

export interface CacheEntry<T = any> {
  data: T;
  timestamp: number;
  ttl: number;
  accessCount: number;
  lastAccess: number;
  size: number; // Taille approximative en octets
}

export interface CacheStats {
  totalEntries: number;
  totalSize: number;
  hitRate: number;
  missRate: number;
  averageAccessTime: number;
  evictionCount: number;
}

export enum CacheStrategy {
  LRU = 'lru', // Least Recently Used
  LFU = 'lfu', // Least Frequently Used
  SIZE = 'size', // Based on size
  TTL = 'ttl' // Time-based
}

/**
 * Cache intelligent avec stratégies d'éviction configurables
 */
export class PersistenceCache {
  private static instance: PersistenceCache;
  private cache = new Map<string, CacheEntry>();
  private maxSize = 50 * 1024 * 1024; // 50MB max
  private currentSize = 0;
  private defaultTTL = 5 * 60 * 1000; // 5 minutes
  private strategy = CacheStrategy.LRU;

  // Statistiques
  private stats = {
    hits: 0,
    misses: 0,
    totalAccessTime: 0,
    evictionCount: 0
  };

  private constructor() {
    // Démarrage du nettoyage automatique
    this.startCleanupInterval();
  }

  static getInstance(): PersistenceCache {
    if (!PersistenceCache.instance) {
      PersistenceCache.instance = new PersistenceCache();
    }
    return PersistenceCache.instance;
  }

  /**
   * Récupère une entrée du cache
   */
  get<T>(key: string): T | null {
    const entry = this.cache.get(key);

    if (!entry) {
      this.stats.misses++;
      return null;
    }

    // Vérifier TTL
    if (Date.now() - entry.timestamp > entry.ttl) {
      this.cache.delete(key);
      this.currentSize -= entry.size;
      this.stats.misses++;
      return null;
    }

    // Mettre à jour les métriques d'accès
    entry.accessCount++;
    entry.lastAccess = Date.now();

    this.stats.hits++;

    const startTime = performance.now();
    const result = entry.data;
    this.stats.totalAccessTime += performance.now() - startTime;

    return result as T;
  }

  /**
   * Stocke une entrée dans le cache
   */
  set<T>(
    key: string,
    data: T,
    options: {
      ttl?: number;
      priority?: number;
    } = {}
  ): boolean {
    const { ttl = this.defaultTTL, priority = 0 } = options;

    // Calculer la taille approximative
    const size = this.calculateSize(data);

    // Vérifier si ça rentre dans le cache
    if (size > this.maxSize * 0.8) { // Si > 80% de la taille max, ne pas cacher
      return false;
    }

    // Éviction si nécessaire
    this.evictIfNeeded(size);

    // Créer l'entrée
    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      ttl,
      accessCount: 1,
      lastAccess: Date.now(),
      size
    };

    // Stocker dans le cache
    this.cache.set(key, entry);
    this.currentSize += size;

    return true;
  }

  /**
   * Supprime une entrée du cache
   */
  delete(key: string): boolean {
    const entry = this.cache.get(key);
    if (entry) {
      this.cache.delete(key);
      this.currentSize -= entry.size;
      return true;
    }
    return false;
  }

  /**
   * Vérifie si une clé existe dans le cache
   */
  has(key: string): boolean {
    const entry = this.cache.get(key);
    if (!entry) return false;

    // Vérifier TTL
    if (Date.now() - entry.timestamp > entry.ttl) {
      this.cache.delete(key);
      this.currentSize -= entry.size;
      return false;
    }

    return true;
  }

  /**
   * Vide complètement le cache
   */
  clear(): void {
    this.cache.clear();
    this.currentSize = 0;
  }

  /**
   * Obtient les statistiques du cache
   */
  getStats(): CacheStats {
    const totalRequests = this.stats.hits + this.stats.misses;
    const hitRate = totalRequests > 0 ? (this.stats.hits / totalRequests) * 100 : 0;
    const missRate = totalRequests > 0 ? (this.stats.misses / totalRequests) * 100 : 0;
    const averageAccessTime = this.stats.hits > 0 ? this.stats.totalAccessTime / this.stats.hits : 0;

    return {
      totalEntries: this.cache.size,
      totalSize: this.currentSize,
      hitRate,
      missRate,
      averageAccessTime,
      evictionCount: this.stats.evictionCount
    };
  }

  /**
   * Configure les paramètres du cache
   */
  configure(options: {
    maxSize?: number;
    defaultTTL?: number;
    strategy?: CacheStrategy;
  }): void {
    if (options.maxSize !== undefined) {
      this.maxSize = options.maxSize;
    }
    if (options.defaultTTL !== undefined) {
      this.defaultTTL = options.defaultTTL;
    }
    if (options.strategy !== undefined) {
      this.strategy = options.strategy;
    }
  }

  /**
   * Précharge des données fréquemment utilisées
   */
  async preload(keys: string[], loader: (key: string) => Promise<any>): Promise<void> {
    const preloadPromises = keys.map(async (key) => {
      if (!this.has(key)) {
        try {
          const data = await loader(key);
          this.set(key, data, { ttl: this.defaultTTL * 2 }); // TTL plus long pour les données préchargées
        } catch (error) {
          console.warn(`[PersistenceCache] Failed to preload ${key}:`, error);
        }
      }
    });

    await Promise.allSettled(preloadPromises);
  }

  /**
   * Exporte le contenu du cache (pour debug)
   */
  export(): Array<{ key: string; entry: CacheEntry }> {
    return Array.from(this.cache.entries()).map(([key, entry]) => ({
      key,
      entry: { ...entry, data: '[DATA]' } // Ne pas exporter les données réelles
    }));
  }

  /**
   * Calcule la taille approximative d'un objet
   */
  private calculateSize(obj: unknown): number {
    const str = JSON.stringify(obj);
    return str ? str.length * 2 : 0; // Approximation: 2 octets par caractère
  }

  /**
   * Éviction selon la stratégie configurée
   */
  private evictIfNeeded(requiredSize: number): void {
    while (this.currentSize + requiredSize > this.maxSize && this.cache.size > 0) {
      let keyToEvict: string | null = null;

      switch (this.strategy) {
        case CacheStrategy.LRU:
          keyToEvict = this.findLRUKey();
          break;
        case CacheStrategy.LFU:
          keyToEvict = this.findLFUKey();
          break;
        case CacheStrategy.SIZE:
          keyToEvict = this.findLargestKey();
          break;
        case CacheStrategy.TTL:
          keyToEvict = this.findExpiredKey();
          break;
      }

      if (keyToEvict) {
        const entry = this.cache.get(keyToEvict);
        if (entry) {
          this.cache.delete(keyToEvict);
          this.currentSize -= entry.size;
          this.stats.evictionCount++;
        }
      } else {
        // Fallback: supprimer la première entrée
        const firstKey = this.cache.keys().next().value;
        if (firstKey) {
          const entry = this.cache.get(firstKey);
          if (entry) {
            this.cache.delete(firstKey);
            this.currentSize -= entry.size;
            this.stats.evictionCount++;
          }
        }
      }
    }
  }

  /**
   * Trouve la clé la moins récemment utilisée
   */
  private findLRUKey(): string | null {
    let oldestKey: string | null = null;
    let oldestTime = Date.now();

    for (const [key, entry] of this.cache.entries()) {
      if (entry.lastAccess < oldestTime) {
        oldestTime = entry.lastAccess;
        oldestKey = key;
      }
    }

    return oldestKey;
  }

  /**
   * Trouve la clé la moins fréquemment utilisée
   */
  private findLFUKey(): string | null {
    let leastUsedKey: string | null = null;
    let leastUsedCount = Infinity;

    for (const [key, entry] of this.cache.entries()) {
      if (entry.accessCount < leastUsedCount) {
        leastUsedCount = entry.accessCount;
        leastUsedKey = key;
      }
    }

    return leastUsedKey;
  }

  /**
   * Trouve la clé avec la plus grande taille
   */
  private findLargestKey(): string | null {
    let largestKey: string | null = null;
    let largestSize = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (entry.size > largestSize) {
        largestSize = entry.size;
        largestKey = key;
      }
    }

    return largestKey;
  }

  /**
   * Trouve une clé expirée
   */
  private findExpiredKey(): string | null {
    const now = Date.now();

    for (const [key, entry] of this.cache.entries()) {
      if (now - entry.timestamp > entry.ttl) {
        return key;
      }
    }

    return null;
  }

  /**
   * Démarre l'intervalle de nettoyage automatique
   */
  private startCleanupInterval(): void {
    // Nettoyer les entrées expirées toutes les 5 minutes
    setInterval(() => {
      this.cleanupExpiredEntries();
    }, 5 * 60 * 1000);
  }

  /**
   * Nettoie les entrées expirées
   */
  private cleanupExpiredEntries(): void {
    const now = Date.now();
    const expiredKeys: string[] = [];

    for (const [key, entry] of this.cache.entries()) {
      if (now - entry.timestamp > entry.ttl) {
        expiredKeys.push(key);
      }
    }

    for (const key of expiredKeys) {
      const entry = this.cache.get(key);
      if (entry) {
        this.cache.delete(key);
        this.currentSize -= entry.size;
      }
    }

    if (expiredKeys.length > 0) {
    }
  }

  /**
   * Obtient les clés les plus fréquemment utilisées (pour préchargement)
   */
  getHotKeys(limit = 10): string[] {
    return Array.from(this.cache.entries())
      .sort(([,a], [,b]) => b.accessCount - a.accessCount)
      .slice(0, limit)
      .map(([key]) => key);
  }

  /**
   * Optimise le cache basé sur les patterns d'usage
   */
  optimize(): void {
    // Analyser les patterns d'usage et ajuster les stratégies
    const stats = this.getStats();

    // Si le taux de succès est faible, augmenter TTL
    if (stats.hitRate < 50) {
      this.defaultTTL *= 1.5;
    }

    // Si la taille est proche de la limite, changer de stratégie
    if (this.currentSize > this.maxSize * 0.8) {
      if (this.strategy === CacheStrategy.LRU) {
        this.strategy = CacheStrategy.SIZE;
      }
    }
  }
}

// Export de l'instance singleton
export const persistenceCache = PersistenceCache.getInstance();

/**
 * PersistenceService - Unified multi-layer persistence service
 *
 * Provides robust persistence with fallbacks and retry logic
 * to ensure data is saved even in case of failure
 * 
 * FIXES applied:
 * - Deduplication before save to prevent redundant operations
 * - Storage cleanup when duplicates detected
 * - Compressed storage for large datasets
 */

import { World } from '@/types/world';
import { Character } from '@/types/character';
import { logger } from '@/utils/logger';

export interface PersistenceResult {
  success: boolean;
  layer: 'store' | 'localStorage' | 'file' | 'fallback';
  error?: string;
  retryCount?: number;
}

export interface ValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
}

/**
 * Service de persistance unifié avec multi-layer fallbacks
 */
export class PersistenceService {
  private static instance: PersistenceService;
  private retryQueue: Map<string, { operation: () => Promise<any>, retries: number }> = new Map();
  // FIX: Track last save time to prevent rapid duplicate saves
  private lastSaveTimes: Map<string, number> = new Map();
  private readonly MIN_SAVE_INTERVAL = 1000; // 1 second minimum between saves

  private constructor() {
    // Démarrer le processing de la queue de retry
    this.processRetryQueue();
  }

  static getInstance(): PersistenceService {
    if (!PersistenceService.instance) {
      PersistenceService.instance = new PersistenceService();
    }
    return PersistenceService.instance;
  }

  /**
   * FIX: Check if character was saved recently to prevent duplicates
   */
  private canSaveCharacter(characterId: string): boolean {
    const lastSave = this.lastSaveTimes.get(characterId) || 0;
    const now = Date.now();
    if (now - lastSave < this.MIN_SAVE_INTERVAL) {
      logger.debug(`[PersistenceService] Skipping duplicate save for character ${characterId} (${Math.round((now - lastSave)/1000)}s since last save)`);
      return false;
    }
    this.lastSaveTimes.set(characterId, now);
    return true;
  }

  /**
   * FIX: Clean up old duplicates from localStorage
   */
  private cleanupDuplicates(key: string): void {
    try {
      const existingData = localStorage.getItem(key);
      if (existingData) {
        const parsed = JSON.parse(existingData);
        // Keep only unique items by ID
        const seen = new Set();
        const unique = parsed.filter((item: { id: string }) => {
          if (seen.has(item.id)) return false;
          seen.add(item.id);
          return true;
        });
        // Only update if there were duplicates
        if (unique.length !== parsed.length) {
          localStorage.setItem(key, JSON.stringify(unique));
          logger.debug(`[PersistenceService] Cleaned up ${parsed.length - unique.length} duplicates from ${key}`);
        }
      }
    } catch (error) {
      logger.warn('[PersistenceService] Cleanup failed:', error);
    }
  }

  /**
   * Save a character with multi-layer persistence
   */
  async saveCharacter(character: Character, projectPath?: string): Promise<PersistenceResult[]> {
    const results: PersistenceResult[] = [];

    // FIX: Check for duplicate before proceeding
    if (!this.canSaveCharacter(character.character_id)) {
      return [{ success: true, layer: 'store' }]; // Skip duplicate save
    }

    // Normalize role field to ensure it's in object format
    const normalizedCharacter = this.normalizeCharacterRole(character);

    // Validation des données
    const validation = this.validateCharacter(normalizedCharacter);
    if (!validation.isValid) {
      throw new Error(`Validation failed: ${validation.errors.join(', ')}`);
    }

    // FIX: Clean up any existing duplicates before saving
    const projectName = projectPath ? projectPath.split(/[/\\]/).pop() || 'unknown' : 'default';
    this.cleanupDuplicates(`project-${projectName}-characters`);

    // Layer 1: Store Zustand (si disponible)
    try {
      results.push(await this.saveCharacterToStore(normalizedCharacter));
    } catch (error) {
      logger.warn('[PersistenceService] Store save failed:', error);
      results.push({
        success: false,
        layer: 'store',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }

    // Layer 2: localStorage
    try {
      results.push(await this.saveCharacterToLocalStorage(normalizedCharacter, projectPath));
    } catch (error) {
      logger.warn('[PersistenceService] localStorage save failed:', error);
      results.push({
        success: false,
        layer: 'localStorage',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }

    // Layer 3: Fichier JSON du projet
    if (projectPath) {
      try {
        results.push(await this.saveCharacterToFile(normalizedCharacter, projectPath));
      } catch (error) {
        logger.warn('[PersistenceService] File save failed:', error);
        results.push({
          success: false,
          layer: 'file',
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    // Si toutes les couches ont échoué, utiliser fallback
    const successfulLayers = results.filter(r => r.success);
    if (successfulLayers.length === 0) {
      try {
        results.push(await this.saveCharacterToFallback(normalizedCharacter));
      } catch (error) {
        logger.error('[PersistenceService] All persistence layers failed:', error);
      }
    }

    return results;
  }

  /**
   * Sauvegarde un monde avec multi-layer persistance
   */
  async saveWorld(world: World, projectPath?: string): Promise<PersistenceResult[]> {
    const results: PersistenceResult[] = [];

    // Validation des données
    const validation = this.validateWorld(world);
    if (!validation.isValid) {
      throw new Error(`Validation failed: ${validation.errors.join(', ')}`);
    }

    // Layer 1: Store Zustand (si disponible)
    try {
      results.push(await this.saveToStore(world));
    } catch (error) {
      logger.warn('[PersistenceService] Store save failed:', error);
      results.push({
        success: false,
        layer: 'store',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }

    // Layer 2: localStorage
    try {
      results.push(await this.saveToLocalStorage(world, projectPath));
    } catch (error) {
      logger.warn('[PersistenceService] localStorage save failed:', error);
      results.push({
        success: false,
        layer: 'localStorage',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }

    // Layer 3: Fichier JSON du projet
    if (projectPath) {
      try {
        results.push(await this.saveToFile(world, projectPath));
      } catch (error) {
        logger.warn('[PersistenceService] File save failed:', error);
        results.push({
          success: false,
          layer: 'file',
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    // Si toutes les couches ont échoué, utiliser fallback
    const successfulLayers = results.filter(r => r.success);
    if (successfulLayers.length === 0) {
      try {
        results.push(await this.saveToFallback(world));
      } catch (error) {
        logger.error('[PersistenceService] All persistence layers failed:', error);
      }
    }

    return results;
  }

  /**
   * Charge un monde depuis les différentes couches
   */
  async loadWorld(worldId: string, projectPath?: string): Promise<World | null> {
    // Essayer d'abord les fichiers du projet
    if (projectPath) {
      try {
        const world = await this.loadFromFile(worldId, projectPath);
        if (world) return world;
      } catch (error) {
        logger.warn('[PersistenceService] File load failed:', error);
      }
    }

    // Puis localStorage
    try {
      const world = await this.loadFromLocalStorage(worldId, projectPath);
      if (world) return world;
    } catch (error) {
      logger.warn('[PersistenceService] localStorage load failed:', error);
    }

    // Enfin le store
    try {
      const world = await this.loadFromStore(worldId);
      if (world) return world;
    } catch (error) {
      logger.warn('[PersistenceService] Store load failed:', error);
    }

    return null;
  }

  /**
   * Sauvegarde dans le store Zustand
   */
  private async saveToStore(world: World): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Importer dynamiquement pour éviter les dépendances circulaires
      const { useStore } = await import('@/store');
      const store = useStore.getState();
      store.addWorld(world);

      return { success: true, layer: 'store' as const };
    }, 3);
  }

  /**
   * Sauvegarde dans localStorage
   */
  private async saveToLocalStorage(world: World, projectPath?: string): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      const projectName = projectPath ?
        projectPath.split(/[/\\]/).pop() || 'unknown' :
        'default';

      const key = `project-${projectName}-worlds`;
      const existingWorlds = JSON.parse(localStorage.getItem(key) || '[]');
      const updatedWorlds = existingWorlds.filter((w: World) => w.id !== world.id);
      updatedWorlds.push(world);

      localStorage.setItem(key, JSON.stringify(updatedWorlds));

      return { success: true, layer: 'localStorage' as const };
    }, 3);
  }

  /**
   * Sauvegarde dans un fichier JSON
   */
  private async saveToFile(world: World, projectPath: string): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Utiliser l'API Electron pour sauvegarder
      if (window.electronAPI?.fs?.writeFile) {
        const worldsDir = `${projectPath}/worlds`;
        const fileName = `world_${world.id}.json`;
        const filePath = `${worldsDir}/${fileName}`;

        // S'assurer que le dossier existe (use mkdir with recursive option)
        if (window.electronAPI.fs.mkdir) {
          await window.electronAPI.fs.mkdir(worldsDir, { recursive: true });
        }

        const jsonData = JSON.stringify(world, null, 2);
        
        // Convert to string or Buffer - electron fs API accepts string or Buffer
        await window.electronAPI.fs.writeFile(filePath, jsonData);

        return { success: true, layer: 'file' as const };
      }

      // Fallback: déclencher un téléchargement
      this.downloadAsFile(world, `world_${world.id}.json`);

      return { success: true, layer: 'file' as const };
    }, 3);
  }

  /**
   * Sauvegarde de fallback (IndexedDB ou autre)
   */
  private async saveToFallback(world: World): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Utiliser IndexedDB comme fallback
      const db = await this.openIndexedDB();
      const transaction = db.transaction(['worlds'], 'readwrite');
      const store = transaction.objectStore('worlds');

      await new Promise((resolve, reject) => {
        const request = store.put(world);
        request.onsuccess = () => resolve(undefined);
        request.onerror = () => reject(request.error);
      });

      return { success: true, layer: 'fallback' as const };
    }, 3);
  }

  /**
   * Charge depuis un fichier JSON
   */
  private async loadFromFile(worldId: string, projectPath: string): Promise<World | null> {
    if (window.electronAPI?.fs?.readFile) {
      const worldsDir = `${projectPath}/worlds`;
      const fileName = `world_${worldId}.json`;
      const filePath = `${worldsDir}/${fileName}`;

      try {
        const buffer = await window.electronAPI.fs.readFile(filePath);
        const jsonString = new TextDecoder().decode(buffer);
        return JSON.parse(jsonString);
      } catch (error) {
        return null;
      }
    }
    return null;
  }

  /**
   * Charge depuis localStorage
   */
  private async loadFromLocalStorage(worldId: string, projectPath?: string): Promise<World | null> {
    const projectName = projectPath ?
      projectPath.split(/[/\\]/).pop() || 'unknown' :
      'default';

    const key = `project-${projectName}-worlds`;
    const worldsData = localStorage.getItem(key);

    if (worldsData) {
      try {
        const worlds: World[] = JSON.parse(worldsData);
        return worlds.find(w => w.id === worldId) || null;
      } catch (error) {
        return null;
      }
    }
    return null;
  }

  /**
   * Charge depuis le store
   */
  private async loadFromStore(worldId: string): Promise<World | null> {
    const { useStore } = await import('@/store');
    const store = useStore.getState();
    return store.getWorldById(worldId) || null;
  }

  /**
   * Sauvegarde un personnage dans le store Zustand
   */
  private async saveCharacterToStore(character: Character): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Importer dynamiquement pour éviter les dépendances circulaires
      const { useStore } = await import('@/store');
      const store = useStore.getState();
      store.addCharacter(character);

      return { success: true, layer: 'store' as const };
    }, 3);
  }

  /**
   * Sauvegarde un personnage dans localStorage
   */
  private async saveCharacterToLocalStorage(character: Character, projectPath?: string): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      const projectName = projectPath ?
        projectPath.split(/[/\\]/).pop() || 'unknown' :
        'default';

      const key = `project-${projectName}-characters`;
      const existingCharacters = JSON.parse(localStorage.getItem(key) || '[]');
      const updatedCharacters = existingCharacters.filter((c: Character) => c.character_id !== character.character_id);
      updatedCharacters.push(character);

      localStorage.setItem(key, JSON.stringify(updatedCharacters));

      return { success: true, layer: 'localStorage' as const };
    }, 3);
  }

  /**
   * Sauvegarde un personnage dans un fichier JSON
   */
  private async saveCharacterToFile(character: Character, projectPath: string): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Utiliser l'API Electron pour sauvegarder
      if (window.electronAPI?.fs?.writeFile) {
        const charactersDir = `${projectPath}/characters`;
        const fileName = `character_${character.character_id}.json`;
        const filePath = `${charactersDir}/${fileName}`;

        // S'assurer que le dossier existe
        if (window.electronAPI.fs.mkdir) {
          await window.electronAPI.fs.mkdir(charactersDir, { recursive: true });
        }

        const jsonData = JSON.stringify(character, null, 2);
        
        // Convert to string or Buffer - electron fs API accepts string or Buffer
        await window.electronAPI.fs.writeFile(filePath, jsonData);

        return { success: true, layer: 'file' as const };
      }

      // Fallback: déclencher un téléchargement
      this.downloadAsFile(character, `character_${character.character_id}.json`);

      return { success: true, layer: 'file' as const };
    }, 3);
  }

  /**
   * Sauvegarde de fallback pour personnage (IndexedDB ou autre)
   */
  private async saveCharacterToFallback(character: Character): Promise<PersistenceResult> {
    return this.retryOperation(async () => {
      // Utiliser IndexedDB comme fallback
      const db = await this.openIndexedDB();
      const transaction = db.transaction(['characters'], 'readwrite');
      const store = transaction.objectStore('characters');

      await new Promise((resolve, reject) => {
        const request = store.put(character);
        request.onsuccess = () => resolve(undefined);
        request.onerror = () => reject(request.error);
      });

      return { success: true, layer: 'fallback' as const };
    }, 3);
  }

  /**
   * Normalizes the character role field to ensure it's in object format
   * Handles migration from legacy string format to object format
   */
  private normalizeCharacterRole(character: Character): Character {
    // If role is null or undefined, set it to empty object
    if (!character.role) {
      return {
        ...character,
        role: {
          archetype: '',
          narrative_function: '',
          character_arc: ''
        }
      };
    }

    // If role is already an object, return as-is
    if (typeof character.role === 'object' && character.role !== null) {
      // Ensure all required properties exist
      return {
        ...character,
        role: {
          archetype: character.role.archetype || '',
          narrative_function: character.role.narrative_function || '',
          character_arc: character.role.character_arc || ''
        }
      };
    }

    // If role is a string (legacy format), convert to object
    if (typeof character.role === 'string') {
      return {
        ...character,
        role: {
          archetype: character.role,
          narrative_function: '',
          character_arc: ''
        }
      };
    }

    // If role is any other type, convert to string representation and use as archetype
    return {
      ...character,
      role: {
        archetype: String(character.role),
        narrative_function: '',
        character_arc: ''
      }
    };
  }

  /**
   * Validation des données du personnage
   */
  private validateCharacter(character: Character): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Validation de base
    if (!character.character_id || typeof character.character_id !== 'string') {
      errors.push('Character ID is required and must be a string');
    }

    if (!character.name || character.name.trim().length === 0) {
      errors.push('Character name is required');
    }

    // Validate role field - handle both object and legacy string formats
    if (!character.role) {
      warnings.push('Character role is recommended for better consistency');
    } else {
      const role = character.role as { archetype?: string; narrative_function?: string; character_arc?: string };
      // Role is an object with archetype, narrative_function, character_arc
      if (!role.archetype || typeof role.archetype !== 'string' || role.archetype.trim().length === 0) {
        warnings.push('Character archetype is recommended for better consistency');
      }
      if (role.narrative_function && typeof role.narrative_function === 'string' && role.narrative_function.trim().length === 0) {
        warnings.push('Character narrative function should not be empty if provided');
      }
      if (role.character_arc && typeof role.character_arc === 'string' && role.character_arc.trim().length === 0) {
        warnings.push('Character arc should not be empty if provided');
      }
    }

    // Validation des traits de personnalité
    if (character.personality?.traits && Array.isArray(character.personality.traits)) {
      if (character.personality.traits.length === 0) {
        warnings.push('At least one personality trait is recommended');
      }
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings
    };
  }

  /**
   * Validation des données du monde
   */
  private validateWorld(world: World): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Validation de base
    if (!world.id || typeof world.id !== 'string') {
      errors.push('World ID is required and must be a string');
    }

    if (!world.name || world.name.trim().length === 0) {
      errors.push('World name is required');
    }

    if (!world.genre || !Array.isArray(world.genre) || world.genre.length === 0) {
      errors.push('At least one genre is required');
    }

    if (!world.timePeriod || world.timePeriod.trim().length === 0) {
      warnings.push('Time period is recommended for better world consistency');
    }

    // Validation des données complexes
    if (world.locations && Array.isArray(world.locations)) {
      world.locations.forEach((location, index) => {
        if (!location.name || location.name.trim().length === 0) {
          errors.push(`Location ${index + 1} must have a name`);
        }
      });
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings
    };
  }

  /**
   * Téléchargement d'un fichier comme fallback
   */
  private downloadAsFile(data: unknown, filename: string): void {
    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }

  /**
   * Ouvre la base IndexedDB
   */
  private async openIndexedDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('StoryCore_Persistence', 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains('worlds')) {
          db.createObjectStore('worlds', { keyPath: 'id' });
        }
      };
    });
  }

  /**
   * Retry logic avec exponential backoff
   */
  private async retryOperation<T>(
    operation: () => Promise<T>,
    maxRetries: number = 3,
    baseDelay: number = 1000
  ): Promise<T> {
    let lastError: Error;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error) {
        lastError = error instanceof Error ? error : new Error('Unknown error');

        if (attempt < maxRetries) {
          const delay = baseDelay * Math.pow(2, attempt);
          logger.warn(`[PersistenceService] Operation failed, retrying in ${delay}ms...`, error);
          await new Promise(resolve => setTimeout(resolve, delay));
        }
      }
    }

    throw lastError!;
  }

  /**
   * Traite la queue de retry en arrière-plan
   */
  private async processRetryQueue(): Promise<void> {
    setInterval(async () => {
      for (const [id, { operation, retries }] of this.retryQueue.entries()) {
        if (retries < 3) {
          try {
            await operation();
            this.retryQueue.delete(id);
          } catch (error) {
            this.retryQueue.set(id, { operation, retries: retries + 1 });
            logger.warn(`[PersistenceService] Queued operation ${id} failed again (${retries + 1}/3)`);
          }
        } else {
          logger.error(`[PersistenceService] Queued operation ${id} failed permanently after 3 retries`);
          this.retryQueue.delete(id);
        }
      }
    }, 30000); // Vérifier toutes les 30 secondes
  }

  /**
   * Synchronise les données entre les couches
   */
  async syncData(projectPath?: string): Promise<{ synced: number, errors: number }> {
    let synced = 0;
    let errors = 0;

    try {
      // Synchroniser les mondes
      const { useStore } = await import('@/store');
      const store = useStore.getState();
      const worlds = store.worlds;

      for (const world of worlds) {
        try {
          await this.saveWorld(world, projectPath);
          synced++;
        } catch (error) {
          logger.error(`[PersistenceService] Sync failed for world ${world.id}:`, error);
          errors++;
        }
      }
    } catch (error) {
      logger.error('[PersistenceService] Sync process failed:', error);
      errors++;
    }

    return { synced, errors };
  }
}

