import type { Story, StoryPart, StoryGenerationParams, GenerationProgress } from '../types/story';
import type { StoryMethodologyType, MethodologyState } from '../types/storyMethodology';
import { useMemoryStore } from '../stores/memoryStore';
import { storyReviewer } from './StoryReviewer';
import { generateStoryContent, generateStorySummary, retryWithBackoff } from './storyGenerationService';
import { methodologyFactory } from './MethodologyFactory';

/**
 * StoryWeaver service
 * Orchestrates multi-part story generation with iterative refinement
 * With fallback handling for when LLM is not available
 * Supports multiple story creation methodologies
 */
export class StoryWeaver {
    private methodology: MethodologyState | null = null;

    /**
     * Generate a complete story using the specified methodology
     * @param params Generation parameters
     * @param methodologyType The methodology to use for generation
     * @param methodologyOptions Options for the methodology
     * @param onProgress Progress callback
     * @returns The complete story
     */
    async weaveStory(
        params: StoryGenerationParams,
        methodologyType?: StoryMethodologyType,
        methodologyOptions?: Record<string, unknown>,
        onProgress?: (progress: GenerationProgress) => void
    ): Promise<Partial<Story>> {
        // If no methodology specified or sequential, use legacy approach
        if (!methodologyType || methodologyType === 'sequential') {
            return this.weaveStoryLegacy(params, onProgress);
        }

        // Create methodology instance
        const methodology = methodologyFactory.createMethodology(
            methodologyType,
            methodologyOptions
        );

        // Store methodology state
        this.methodology = methodology.getState();

        // Generate content using the methodology
        const state = methodology.getState();
        const phases = state.phases;

        // Generate each approved phase
        for (const phase of phases) {
            onProgress?.({
                stage: 'generating_intro',
                progress: (phases.indexOf(phase) / phases.length) * 100,
                currentTask: `Generating ${phase.phase}...`,
            });

            try {
                const result = await methodology.generateContent(phase.phase, params);
                methodology.completePhase(phase.phase, result);

                // Auto-approve for generation flow
                methodology.approvePhase(phase.phase);
            } catch (error) {
                console.error(`[StoryWeaver] Failed to generate ${phase.phase}:`, error);
            }
        }

        // Export the final story
        const story = await methodology.exportStory();

        return {
            title: params.totalTitle || 'Untitled Story',
            content: story.content,
            summary: story.summary,
            updatedAt: Date.now(),
        };
    }

    /**
     * Legacy story generation for backward compatibility
     * @deprecated Use weaveStory with methodology instead
     */
    async weaveStoryLegacy(
        params: StoryGenerationParams,
        onProgress?: (progress: GenerationProgress) => void
    ): Promise<Partial<Story>> {
        const parts: StoryPart[] = [];
        const numChapters = params.length === 'short' ? 1 : params.length === 'medium' ? 3 : 5;
        let runningSummaryData = '';

        // 1. Generate Intro
        onProgress?.({
            stage: 'generating_intro',
            progress: 10,
            currentTask: 'Generating story introduction...',
        });

        try {
            const intro = await this.generatePart({
                type: 'intro',
                params,
                previousSummary: '',
                order: 1,
            });
            parts.push(intro);
            runningSummaryData = intro.summary;
        } catch (error) {
            console.error('[StoryWeaver] Failed to generate intro:', error);
            const fallbackIntro = this.createFallbackPart('intro', params, 1);
            parts.push(fallbackIntro);
            runningSummaryData = fallbackIntro.summary;
        }

        // 2. Generate Chapters
        for (let i = 0; i < numChapters; i++) {
            const chapterNum = i + 1;
            const progressBase = 15 + (i / numChapters) * 60;

            onProgress?.({
                stage: 'generating_chapter',
                progress: progressBase,
                currentTask: `Generating chapter ${chapterNum} of ${numChapters}...`,
                currentChapter: chapterNum,
                totalChapters: numChapters,
            });

            try {
                const chapter = await this.generatePart({
                    type: 'chapter',
                    params,
                    previousSummary: runningSummaryData,
                    order: parts.length + 1,
                    partIndex: chapterNum,
                });
                parts.push(chapter);
                runningSummaryData = chapter.summary;
            } catch (error) {
                console.error(`[StoryWeaver] Failed to generate chapter ${chapterNum}:`, error);
                const fallbackChapter = this.createFallbackPart('chapter', params, parts.length + 1, chapterNum);
                parts.push(fallbackChapter);
                runningSummaryData = fallbackChapter.summary;
            }
        }

        // 3. Generate Ending
        onProgress?.({
            stage: 'generating_ending',
            progress: 85,
            currentTask: 'Generating story conclusion...',
        });

        try {
            const ending = await this.generatePart({
                type: 'ending',
                params,
                previousSummary: runningSummaryData,
                order: parts.length + 1,
            });
            parts.push(ending);
        } catch (error) {
            console.error('[StoryWeaver] Failed to generate ending:', error);
            const fallbackEnding = this.createFallbackPart('ending', params, parts.length + 1);
            parts.push(fallbackEnding);
        }

        // 4. Generate Final Summary
        onProgress?.({
            stage: 'reviewing',
            progress: 95,
            currentTask: 'Creating story summary...',
        });

        const fullContent = parts.map(p => `### ${p.title}\n\n${p.content}`).join('\n\n');

        let finalSummary = '';
        try {
            finalSummary = await generateStorySummary(fullContent);
        } catch (error) {
            console.warn('[StoryWeaver] Summary generation failed, using basic summary');
            finalSummary = this.createBasicSummary(parts, params);
        }

        // 5. Complete
        onProgress?.({
            stage: 'complete',
            progress: 100,
            currentTask: 'Story generation complete!',
        });

        return {
            title: params.totalTitle || 'Untitled Story',
            content: fullContent,
            summary: finalSummary,
            parts,
            updatedAt: Date.now(),
        };
    }

    /**
     * Get the current methodology state
     */
    getMethodologyState(): MethodologyState | null {
        return this.methodology;
    }

    /**
     * Create a fallback part when LLM generation fails
     */
    private createFallbackPart(
        type: 'intro' | 'chapter' | 'ending',
        params: StoryGenerationParams,
        order: number,
        partIndex?: number
    ): StoryPart {
        const charNames = params.characters?.map((c: any) => c.name).join(', ') || 'the characters';
        const locationNames = params.locations?.map((l: any) => l.name).join(', ') || 'the world';

        let content = '';
        let summary = '';

        if (type === 'intro') {
            content = `The story begins in ${locationNames}, where ${charNames} find themselves at the heart of the adventure.\n\nThe world of ${params.worldContext?.name || 'this realm'} is shaped by ${params.genre?.join(' and ') || 'fantasy'} traditions, with a ${params.tone?.join(', ') || 'adventurous'} atmosphere that permeates every corner of this tale.\n\nAs the narrative unfolds, the initial conflict emerges, setting the stage for what promises to be an epic journey.`;
            summary = 'The story begins with the main characters in their initial situation, establishing the setting and world.';
        } else if (type === 'chapter') {
            content = `Chapter ${partIndex}\n\nThe adventure continues in ${locationNames}. ${charNames} face new challenges and revelations that will shape the course of their journey.\n\nTensions rise as the plot thickens, bringing unexpected twists and deeper understanding of the world they inhabit.`;
            summary = `Chapter ${partIndex} develops the plot further, introducing new challenges and character development.`;
        } else {
            content = `The Conclusion\n\nAfter many trials and tribulations, ${charNames} find themselves at a crossroads. The climax of the story approaches, bringing resolution to the central conflict.\n\nIn the end, the lessons learned and the bonds forged will determine the fate of ${locationNames} and all who dwell within.`;
            summary = 'The story reaches its climax and provides a satisfying resolution to the main conflict.';
        }

        return {
            id: crypto.randomUUID(),
            type,
            title: type === 'intro' ? 'Introduction' : type === 'ending' ? 'Conclusion' : `Chapter ${partIndex}`,
            content,
            summary,
            reviewScore: { tension: 50, drama: 50, sense: 70, emotion: 50, overall: 55 },
            order,
        };
    }

    /**
     * Create a basic summary from parts without calling LLM
     */
    private createBasicSummary(parts: StoryPart[], params: StoryGenerationParams): string {
        const chapterCount = parts.filter(p => p.type === 'chapter').length;
        return `A ${params.length} ${params.genre?.join(', ') || 'fantasy'} story with ${params.tone?.join(', ') || 'adventurous'} tone. ` +
            `The story features ${chapterCount} chapters following the introduction and ending. ` +
            `Key themes and elements from the ${params.genre?.[0] || 'fantasy'} genre are explored.`;
    }

    /**
     * Generates a single story part
     */
    private async generatePart(options: {
        type: 'intro' | 'chapter' | 'ending';
        params: StoryGenerationParams;
        previousSummary: string;
        order: number;
        partIndex?: number;
    }): Promise<StoryPart> {
        const { type, params, previousSummary, order, partIndex } = options;

        const basePrompt = this.getPartPrompt(type, params, previousSummary, partIndex);

        let content = '';
        try {
            content = await retryWithBackoff(async () => {
                const { getLLMService } = await import('./llmService');
                const llmService = getLLMService();

                const response = await llmService.generateText(basePrompt, {
                    temperature: 0.8,
                    maxTokens: 1500,
                });

                if (!response || response.trim().length === 0) throw new Error('Empty response');
                return response.trim();
            }, 2);
        } catch (error) {
            console.error('[StoryWeaver] LLM generation failed for part:', type, error);
            throw error;
        }

        // Total Recall: Analyze for memory
        const { projectMemory } = await import('./ProjectMemoryService');
        projectMemory.analyzeForMemory(content, `Story Generation: ${type} ${partIndex || ''}`);

        let scores;
        try {
            scores = await storyReviewer.reviewPart(content, { genre: params.genre, tone: params.tone });
        } catch {
            scores = { tension: 50, drama: 50, sense: 70, emotion: 50, overall: 55 };
        }

        let summary = '';
        try {
            summary = await generateStorySummary(content);
        } catch {
            summary = content.substring(0, 200) + '...';
        }

        return {
            id: crypto.randomUUID(),
            type,
            title: type === 'intro' ? 'Introduction' : type === 'ending' ? 'Conclusion' : `Chapter ${partIndex}`,
            content,
            summary,
            reviewScore: scores,
            order,
        };
    }

    private getPartPrompt(type: string, params: StoryGenerationParams, previousSummary: string, partIndex?: number): string {
        const contextStr = previousSummary ? `\n\nPreviously in the story:\n${previousSummary}` : '';
        const workingContext = useMemoryStore.getState().workingContext;

        let instructions = '';
        if (type === 'intro') {
            instructions = 'Establish the setting, introduce characters, and set the initial conflict.';
        } else if (type === 'chapter') {
            instructions = `Develop the plot further (Chapter ${partIndex}). Escalate tension and evolve character relationships.`;
        } else if (type === 'ending') {
            instructions = 'Reach the climax and provide a satisfying resolution for the main conflict.';
        }

        return `
You are writing a story in the following style:
Genre: ${params.genre?.join(', ') || 'fantasy'}
Tone: ${params.tone?.join(', ') || 'adventurous'}

[LIVING PROJECT PROTOCOL]
${workingContext}

Instructions: ${instructions}${contextStr}

World Context:
${JSON.stringify(params.worldContext)}

Character Context:
${params.characters?.map((c: any) => `- ${c.name}: ${c.description || c.role}`).join('\n') || ''}

Location Context:
${params.locations?.map((l: any) => `- ${l.name}: ${l.description || l.type}`).join('\n') || ''}

Write the next part of the story. Output only the story content, no meta-commentary.
`;
    }
}

export const storyWeaver = new StoryWeaver();

/**
 * SyncManager - Bidirectional synchronization manager
 *
 * Synchronizes data between Zustand store and JSON files
 * with automatic conflict detection and resolution
 */

import { persistenceService } from './PersistenceService';
import { logger } from '@/utils/logger';
import type { World } from '@/types/world';

export interface SyncConflict {
  entityType: string;
  entityId: string;
  storeVersion: unknown;
  fileVersion: unknown;
  conflictType: 'modified' | 'deleted' | 'created';
  resolution: 'store-wins' | 'file-wins' | 'merge' | 'manual';
  timestamp: Date;
}

export interface SyncResult {
  synced: number;
  conflicts: SyncConflict[];
  errors: string[];
  duration: number;
}

// Type guard function to check if value is a plain object
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Gestionnaire de synchronisation bidirectionnelle
 */
export class SyncManager {
  private static instance: SyncManager;
  private syncInProgress = false;
  private lastSyncTime: Date | null = null;
  private conflicts: SyncConflict[] = [];

  private constructor() {
    // Démarrer la synchronisation automatique
    this.startAutoSync();
  }

  static getInstance(): SyncManager {
    if (!SyncManager.instance) {
      SyncManager.instance = new SyncManager();
    }
    return SyncManager.instance;
  }

  /**
   * Synchronisation complète bidirectionnelle
   */
  async fullSync(projectPath?: string): Promise<SyncResult> {
    if (this.syncInProgress) {
      logger.warn('[SyncManager] Sync already in progress, skipping...');
      return { synced: 0, conflicts: [], errors: ['Sync already in progress'], duration: 0 };
    }

    const startTime = Date.now();
    this.syncInProgress = true;

    try {

      const results = await Promise.allSettled([
        this.syncWorlds(projectPath),
        this.syncCharacters(projectPath),
        this.syncSequences(projectPath),
        this.syncScenes(projectPath),
        this.syncShots(projectPath),
      ]);

      const synced = results.reduce((acc, result) => {
        if (result.status === 'fulfilled') {
          return acc + result.value.synced;
        }
        return acc;
      }, 0);

      const allConflicts = results.flatMap(result =>
        result.status === 'fulfilled' ? result.value.conflicts : []
      );

      const errors = results.flatMap(result =>
        result.status === 'rejected' ? [result.reason?.message || 'Unknown error'] : []
      );

      const duration = Date.now() - startTime;


      this.lastSyncTime = new Date();
      this.conflicts.push(...allConflicts);

      return {
        synced,
        conflicts: allConflicts,
        errors,
        duration
      };

    } finally {
      this.syncInProgress = false;
    }
  }

  /**
   * Synchronisation des mondes
   */
  private async syncWorlds(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    try {
      // Importer dynamiquement pour éviter les dépendances circulaires
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const storeWorlds = store.worlds || [];
      let synced = 0;
      const conflicts: SyncConflict[] = [];

      for (const world of storeWorlds) {
        try {
          // Essayer de charger depuis le fichier
          const fileWorld = await persistenceService.loadWorld(world.id, projectPath);

          if (!fileWorld) {
            // Monde existe dans store mais pas dans fichier - sauvegarder
            await persistenceService.saveWorld(world, projectPath);
            synced++;
          } else {
            // Les deux existent - vérifier les conflits
            const conflict = this.detectConflict(world, fileWorld, 'world');
            if (conflict) {
              conflicts.push(conflict);
              // Résoudre automatiquement : store wins (plus récent)
              await persistenceService.saveWorld(world, projectPath);
            }
          }
        } catch (error) {
          logger.error(`[SyncManager] Error syncing world ${world.id}:`, error);
        }
      }

      // Vérifier les mondes qui existent dans les fichiers mais pas dans le store
      // Cette logique serait plus complexe et nécessiterait de scanner les fichiers

      return { synced, conflicts };
    } catch (error) {
      logger.error('[SyncManager] Error syncing worlds:', error);
      return { synced: 0, conflicts: [] };
    }
  }

  /**
   * Synchronisation des personnages
   */
  private async syncCharacters(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    try {
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const storeCharacters = store.characters || [];
      let synced = 0;
      const conflicts: SyncConflict[] = [];

      // Synchroniser chaque personnage avec la méthode appropriée
      for (const character of storeCharacters) {
        try {
          // Utiliser saveCharacter au lieu de saveWorld
          await persistenceService.saveCharacter(character, projectPath);
          synced++;
        } catch (error) {
          logger.error(`[SyncManager] Error syncing character ${character.character_id}:`, error);
        }
      }

      return { synced, conflicts };
    } catch (error) {
      logger.error('[SyncManager] Error syncing characters:', error);
      return { synced: 0, conflicts: [] };
    }
  }

  /**
   * Synchronisation des séquences
   */
  private async syncSequences(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les séquences
    return { synced: 0, conflicts: [] };
  }

  /**
   * Synchronisation des scènes
   */
  private async syncScenes(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les scènes
    return { synced: 0, conflicts: [] };
  }

  /**
   * Synchronisation des plans
   */
  private async syncShots(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les plans
    return { synced: 0, conflicts: [] };
  }

  /**
   * Détection de conflits entre versions
   */
  private detectConflict(storeVersion: unknown, fileVersion: unknown, entityType: string): SyncConflict | null {
    // Type guard to check if it's a valid object with timestamps
    if (!isObject(storeVersion) || !isObject(fileVersion)) {
      return null;
    }

    // Comparer les timestamps de mise à jour
    const storeTime = (storeVersion as Record<string, unknown>).updatedAt || (storeVersion as Record<string, unknown>).createdAt;
    const fileTime = (fileVersion as Record<string, unknown>).updatedAt || (fileVersion as Record<string, unknown>).createdAt;

    if (!storeTime || !fileTime) {
      return null; // Impossible de déterminer
    }

    const storeTimestamp = new Date(storeTime as string).getTime();
    const fileTimestamp = new Date(fileTime as string).getTime();
    const diff = Math.abs(storeTimestamp - fileTimestamp);

    // Si la différence est supérieure à 5 secondes, considérer comme conflit
    if (diff > 5000) {
      return {
        entityType,
        entityId: String((storeVersion as Record<string, unknown>).id || (storeVersion as Record<string, unknown>).character_id || ''),
        storeVersion,
        fileVersion,
        conflictType: 'modified',
        resolution: 'store-wins', // Par défaut, store gagne
        timestamp: new Date()
      };
    }

    return null;
  }

  /**
   * Résoudre un conflit manuellement
   */
  async resolveConflict(conflict: SyncConflict, resolution: SyncConflict['resolution'], customData?: unknown): Promise<void> {
    try {
      let finalData: unknown;

      switch (resolution) {
        case 'store-wins':
          finalData = conflict.storeVersion;
          break;
        case 'file-wins':
          finalData = conflict.fileVersion;
          break;
        case 'merge':
          finalData = this.mergeVersions(conflict.storeVersion, conflict.fileVersion);
          break;
        case 'manual':
          finalData = customData;
          break;
      }

      // Sauvegarder la version résolue
      if (conflict.entityType === 'world' && isObject(finalData)) {
        await persistenceService.saveWorld(finalData as unknown as World);
      }
      // Ajouter d'autres types d'entités selon les besoins

      // Marquer le conflit comme résolu
      this.conflicts = this.conflicts.filter(c => c !== conflict);

    } catch (error) {
      logger.error(`[SyncManager] Error resolving conflict:`, error);
      throw error;
    }
  }

  /**
   * Fusionner deux versions automatiquement
   */
  private mergeVersions(version1: unknown, version2: unknown): unknown {
    // Stratégie de fusion simple : prendre la version la plus récente pour chaque champ
    if (!isObject(version1)) {
      return version2;
    }
    const obj1 = version1 as Record<string, unknown>;
    const merged: Record<string, unknown> = { ...obj1 };

    if (isObject(version2)) {
      const obj2 = version2 as Record<string, unknown>;
      for (const [key, value] of Object.entries(obj2)) {
        if (!(key in merged) || this.isNewer(value, merged[key])) {
          merged[key] = value;
        }
      }
    }

    // Mettre à jour le timestamp
    merged.updatedAt = new Date();

    return merged;
  }

  /**
   * Déterminer si une valeur est "plus récente"
   */
  private isNewer(value1: unknown, value2: unknown): boolean {
    // Pour les dates
    if (value1 instanceof Date && value2 instanceof Date) {
      return value1 > value2;
    }

    // Pour les chaînes de date
    if (typeof value1 === 'string' && typeof value2 === 'string') {
      try {
        const date1 = new Date(value1);
        const date2 = new Date(value2);
        if (!Number.isNaN(date1.getTime()) && !Number.isNaN(date2.getTime())) {
          return date1 > date2;
        }
      } catch {
        // Pas des dates valides
      }
    }

    // Par défaut, considérer la première valeur comme plus récente
    return true;
  }

  /**
   * Créer un backup automatique
   */
  async createBackup(projectPath?: string): Promise<string> {
    try {
      const timestamp = new Date().toISOString().replaceAll(':', '-').replaceAll('.', '-');
      const backupId = `backup-${timestamp}`;

      // Sauvegarder toutes les entités
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const backupData = {
        id: backupId,
        timestamp: new Date(),
        data: {
          worlds: store.worlds,
          characters: store.characters,
          project: store.project
        }
      };

      // Sauvegarder dans localStorage avec une clé spéciale
      const backupKey = `backup_${backupId}`;
      localStorage.setItem(backupKey, JSON.stringify(backupData));

      return backupId;
    } catch (error) {
      logger.error('[SyncManager] Error creating backup:', error);
      throw error;
    }
  }

  /**
   * Restaurer depuis un backup
   */
  async restoreFromBackup(backupId: string): Promise<void> {
    try {
      const backupKey = `backup_${backupId}`;
      const backupDataStr = localStorage.getItem(backupKey);

      if (!backupDataStr) {
        throw new Error(`Backup ${backupId} not found`);
      }

      const backupData = JSON.parse(backupDataStr);

      // Restaurer les données dans le store
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      // Restaurer mondes
      for (const world of backupData.data.worlds || []) {
        await store.addWorld(world);
      }

      // Restaurer personnages
      for (const character of backupData.data.characters || []) {
        await store.addCharacter(character);
      }

    } catch (error) {
      logger.error(`[SyncManager] Error restoring backup ${backupId}:`, error);
      throw error;
    }
  }

  /**
   * Démarrer la synchronisation automatique
   */
  private startAutoSync(): void {
    // Synchroniser toutes les 5 minutes
    setInterval(async () => {
      try {
        // Obtenir le chemin du projet actuel
        const { useAppStore } = await import('@/stores/useAppStore');
        const appStore = useAppStore.getState();
        const projectPath = appStore.project?.metadata?.path as string | undefined;

        await this.fullSync(projectPath);
      } catch (error) {
        logger.error('[SyncManager] Auto-sync failed:', error);
      }
    }, 5 * 60 * 1000); // 5 minutes

    // Écouter les changements de projet
    globalThis.addEventListener('project-changed', async () => {
      try {
        const { useAppStore } = await import('@/stores/useAppStore');
        const appStore = useAppStore.getState();
        const projectPath = appStore.project?.metadata?.path as string | undefined;

        await this.fullSync(projectPath);
      } catch (error) {
        logger.error('[SyncManager] Project change sync failed:', error);
      }
    });
  }

  /**
   * Obtenir l'état actuel de la synchronisation
   */
  getSyncStatus(): {
    inProgress: boolean;
    lastSyncTime: Date | null;
    conflictCount: number;
    recentConflicts: SyncConflict[];
  } {
    return {
      inProgress: this.syncInProgress,
      lastSyncTime: this.lastSyncTime,
      conflictCount: this.conflicts.length,
      recentConflicts: this.conflicts.slice(-5) // Derniers 5 conflits
    };
  }

  /**
   * Nettoyer les anciens conflits résolus
   */
  cleanupOldConflicts(maxAge: number = 24 * 60 * 60 * 1000): void { // 24h par défaut
    const cutoff = Date.now() - maxAge;
    this.conflicts = this.conflicts.filter(conflict => conflict.timestamp.getTime() > cutoff);
  }
}

