/**
 * Template Marketplace Service
 * MI3: Template Marketplace - User template sharing
 */

import {
  Template,
  TemplateCollection,
  TemplateReview,
  MarketplaceSearchParams,
  TemplateUploadData,
} from '../types/template-marketplace';

interface MarketplaceAPIConfig {
  baseUrl: string;
  apiKey?: string;
  timeout: number;
}

class TemplateMarketplaceService {
  private config: MarketplaceAPIConfig;
  private cache: Map<string, { data: unknown; timestamp: number }> = new Map();
  private cacheTimeout = 5 * 60 * 1000; // 5 minutes

  constructor(config?: Partial<MarketplaceAPIConfig>) {
    this.config = {
      baseUrl: 'https://api.storycore.io/marketplace',
      timeout: 30000,
      ...config,
    };
  }

  /**
   * Search templates with given parameters
   */
  async searchTemplates(params: MarketplaceSearchParams): Promise<{
    templates: Template[];
    totalCount: number;
    hasMore: boolean;
  }> {
    const cacheKey = `search_${JSON.stringify(params)}`;
    const cached = this.getFromCache(cacheKey) as any;
    if (cached) return cached;

    try {
      const queryParams = new URLSearchParams({
        page: params.page.toString(),
        limit: params.limit.toString(),
        sortBy: params.sortBy || 'popular',
      });

      if (params.query) queryParams.set('q', params.query);
      if (params.price) queryParams.set('price', params.price);
      if (params.rating) queryParams.set('rating', params.rating.toString());
      if (params.categories?.length) {
        queryParams.set('categories', params.categories.join(','));
      }
      if (params.aspectRatios?.length) {
        queryParams.set('aspectRatios', params.aspectRatios.join(','));
      }
      if (params.resolutions?.length) {
        queryParams.set('resolutions', params.resolutions.join(','));
      }
      if (params.tags?.length) {
        queryParams.set('tags', params.tags.join(','));
      }

      const response = await fetch(
        `${this.config.baseUrl}/templates?${queryParams}`,
        {
          headers: this.getHeaders(),
        }
      );

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json();
      this.addToCache(cacheKey, data);
      return data;
    } catch (error) {
      console.error('Failed to search templates:', error);
      return { templates: [], totalCount: 0, hasMore: false };
    }
  }

  /**
   * Get template details by ID
   */
  async getTemplateById(id: string): Promise<Template | null> {
    const cacheKey = `template_${id}`;
    const cached = this.getFromCache(cacheKey) as any;
    if (cached) return cached;

    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${id}`,
        { headers: this.getHeaders() }
      );

      if (!response.ok) {
        if (response.status === 404) return null;
        throw new Error(`API error: ${response.status}`);
      }

      const template = await response.json();
      this.addToCache(cacheKey, template);
      return template;
    } catch (error) {
      console.error('Failed to get template:', error);
      return null;
    }
  }

  /**
   * Get featured templates
   */
  async getFeaturedTemplates(): Promise<Template[]> {
    const cacheKey = 'featured';
    const cached = this.getFromCache(cacheKey) as any;
    if (cached) return cached;

    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/featured`,
        { headers: this.getHeaders() }
      );

      if (!response.ok) throw new Error(`API error: ${response.status}`);

      const templates = await response.json();
      this.addToCache(cacheKey, templates);
      return templates;
    } catch (error) {
      console.error('Failed to get featured templates:', error);
      return [];
    }
  }

  /**
   * Get template collections
   */
  async getCollections(): Promise<TemplateCollection[]> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/collections`,
        { headers: this.getHeaders() }
      );

      if (!response.ok) throw new Error(`API error: ${response.status}`);
      return await response.json();
    } catch (error) {
      console.error('Failed to get collections:', error);
      return [];
    }
  }

  /**
   * Get reviews for a template
   */
  async getTemplateReviews(templateId: string): Promise<TemplateReview[]> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${templateId}/reviews`,
        { headers: this.getHeaders() }
      );

      if (!response.ok) throw new Error(`API error: ${response.status}`);
      return await response.json();
    } catch (error) {
      console.error('Failed to get reviews:', error);
      return [];
    }
  }

  /**
   * Download a template
   */
  async downloadTemplate(templateId: string): Promise<Blob | null> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${templateId}/download`,
        {
          headers: this.getHeaders(),
        }
      );

      if (!response.ok) throw new Error(`API error: ${response.status}`);
      return await response.blob();
    } catch (error) {
      console.error('Failed to download template:', error);
      return null;
    }
  }

  /**
   * Purchase a template
   */
  async purchaseTemplate(templateId: string): Promise<{
    success: boolean;
    transactionId?: string;
    error?: string;
  }> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${templateId}/purchase`,
        {
          method: 'POST',
          headers: this.getHeaders(),
        }
      );

      if (!response.ok) {
        const error = await response.json();
        return { success: false, error: error.message };
      }

      return await response.json();
    } catch (error) {
      console.error('Failed to purchase template:', error);
      return { success: false, error: 'Network error' };
    }
  }

  /**
   * Upload a new template
   */
  async uploadTemplate(data: TemplateUploadData): Promise<{
    success: boolean;
    templateId?: string;
    error?: string;
  }> {
    try {
      const formData = new FormData();

      // Add template data
      formData.append('template', JSON.stringify(data.template));
      formData.append('isPublic', data.isPublic.toString());
      formData.append('license', data.license);
      formData.append('attributionRequired', data.attributionRequired.toString());

      if (data.price !== undefined) {
        formData.append('price', data.price.toString());
      }

      // Add files
      formData.append('thumbnail', data.thumbnail);
      if (data.preview) {
        formData.append('preview', data.preview);
      }
      if (data.documentation) {
        formData.append('documentation', data.documentation);
      }
      data.assets.forEach((asset, index) => {
        formData.append(`asset_${index}`, asset);
      });

      const response = await fetch(`${this.config.baseUrl}/templates`, {
        method: 'POST',
        headers: {
          ...this.getHeaders(),
          'Content-Type': 'multipart/form-data',
        },
        body: formData,
      });

      if (!response.ok) {
        const error = await response.json();
        return { success: false, error: error.message };
      }

      const result = await response.json();
      return { success: true, templateId: result.id };
    } catch (error) {
      console.error('Failed to upload template:', error);
      return { success: false, error: 'Network error' };
    }
  }

  /**
   * Submit a review
   */
  async submitReview(
    templateId: string,
    review: Omit<TemplateReview, 'id' | 'templateId' | 'createdAt' | 'updatedAt'>
  ): Promise<TemplateReview | null> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${templateId}/reviews`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify(review),
        }
      );

      if (!response.ok) throw new Error(`API error: ${response.status}`);
      return await response.json();
    } catch (error) {
      console.error('Failed to submit review:', error);
      return null;
    }
  }

  /**
   * Favorite/unfavorite a template
   */
  async toggleFavorite(templateId: string): Promise<boolean> {
    try {
      const response = await fetch(
        `${this.config.baseUrl}/templates/${templateId}/favorite`,
        {
          method: 'POST',
          headers: this.getHeaders(),
        }
      );

      return response.ok;
    } catch (error) {
      console.error('Failed to toggle favorite:', error);
      return false;
    }
  }

  /**
   * Clear cache
   */
  clearCache(): void {
    this.cache.clear();
  }

  /**
   * Get headers for API requests
   */
  private getHeaders(): HeadersInit {
    const headers: HeadersInit = {
      'Accept': 'application/json',
    };

    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    return headers;
  }

  /**
   * Cache management
   */
  private getFromCache(key: string): unknown | null {
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.data;
    }
    return null;
  }

  private addToCache(key: string, data: unknown): void {
    this.cache.set(key, { data, timestamp: Date.now() });
  }
}

export const templateMarketplaceService = new TemplateMarketplaceService();
export default TemplateMarketplaceService;

/**
 * ThumbnailCache Service
 * 
 * Implements a two-tier caching system for video thumbnails:
 * - Memory cache with LRU eviction policy
 * - Persistent disk cache using IndexedDB
 * 
 * Now with Observer pattern for real-time synchronization
 * 
 * Validates: Requirements 5.1, 5.2, 5.3, 5.8
 */

export interface ThumbnailCacheConfig {
  maxMemorySize: number; // in MB
  maxDiskSize: number; // in MB
  quality: 'low' | 'medium' | 'high';
  preloadDistance: number; // number of thumbnails to preload
}

export interface CacheEntry {
  key: string;
  blob: Blob;
  size: number;
  lastAccessed: number;
  quality: string;
}

/**
 * Callback type for cache updates
 */
export type CacheUpdateCallback = (key: string, entry: CacheEntry) => void;

/**
 * Callback type for cache clear events
 */
export type CacheClearCallback = (cleared: boolean) => void;

/**
 * Callback type for cache stats updates
 */
export type CacheStatsCallback = (stats: CacheStats) => void;

export interface CacheStats {
  memorySize: number;
  memoryUsage: number;
  memoryCount: number;
  maxMemorySize: number;
}

export class ThumbnailCache {
  private memoryCache: Map<string, CacheEntry>;
  private db: IDBDatabase | null = null;
  private config: ThumbnailCacheConfig;
  private currentMemorySize: number;
  private static instance: ThumbnailCache | null = null;
  private initPromise: Promise<void> | null = null;
  
  // Subscribers for different events
  private cacheUpdateSubscribers: Set<CacheUpdateCallback> = new Set();
  private cacheClearSubscribers: Set<CacheClearCallback> = new Set();
  private cacheStatsSubscribers: Set<CacheStatsCallback> = new Set();

  private constructor(config: ThumbnailCacheConfig) {
    this.memoryCache = new Map();
    this.config = config;
    this.currentMemorySize = 0;
  }

  /**
   * Get singleton instance of ThumbnailCache
   */
  static getInstance(config?: ThumbnailCacheConfig): ThumbnailCache {
    if (!ThumbnailCache.instance) {
      const defaultConfig: ThumbnailCacheConfig = {
        maxMemorySize: 100, // 100 MB
        maxDiskSize: 500, // 500 MB
        quality: 'medium',
        preloadDistance: 5
      };
      ThumbnailCache.instance = new ThumbnailCache(config || defaultConfig);
    }
    return ThumbnailCache.instance;
  }

  /**
   * Subscribe to cache updates
   * Returns unsubscribe function
   */
  public subscribeToCacheUpdates(callback: CacheUpdateCallback): () => void {
    this.cacheUpdateSubscribers.add(callback);
    return () => {
      this.cacheUpdateSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to cache clear events
   * Returns unsubscribe function
   */
  public subscribeToCacheClear(callback: CacheClearCallback): () => void {
    this.cacheClearSubscribers.add(callback);
    return () => {
      this.cacheClearSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to cache stats updates
   * Returns unsubscribe function
   */
  public subscribeToCacheStats(callback: CacheStatsCallback): () => void {
    this.cacheStatsSubscribers.add(callback);
    return () => {
      this.cacheStatsSubscribers.delete(callback);
    };
  }

  /**
   * Notify subscribers of cache update
   */
  private notifyCacheUpdate(key: string, entry: CacheEntry): void {
    this.cacheUpdateSubscribers.forEach(callback => {
      try {
        callback(key, entry);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache update subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of cache clear
   */
  private notifyCacheClear(cleared: boolean): void {
    this.cacheClearSubscribers.forEach(callback => {
      try {
        callback(cleared);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache clear subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of cache stats update
   */
  private notifyCacheStats(): void {
    const stats = this.getStats();
    this.cacheStatsSubscribers.forEach(callback => {
      try {
        callback(stats);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache stats subscriber:', error);
      }
    });
  }

  /**
   * Initialize IndexedDB for persistent storage
   * Validates: Requirement 5.8
   */
  async initIndexedDB(): Promise<void> {
    if (this.initPromise) {
      return this.initPromise;
    }

    this.initPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open('ThumbnailCacheDB', 1);

      request.onerror = () => {
        reject(new Error('Failed to open IndexedDB'));
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        
        if (!db.objectStoreNames.contains('thumbnails')) {
          const objectStore = db.createObjectStore('thumbnails', { keyPath: 'key' });
          objectStore.createIndex('lastAccessed', 'lastAccessed', { unique: false });
          objectStore.createIndex('size', 'size', { unique: false });
        }
      };
    });

    return this.initPromise;
  }

  /**
   * Get thumbnail from cache (memory first, then disk)
   * Validates: Requirements 5.1, 5.2
   */
  async get(videoUrl: string, time: number, quality?: string): Promise<Blob | null> {
    const key = this.generateKey(videoUrl, time, quality);

    // Check memory cache first (Requirement 5.1)
    const memoryEntry = this.memoryCache.get(key);
    if (memoryEntry) {
      memoryEntry.lastAccessed = Date.now();
      return memoryEntry.blob;
    }

    // Check IndexedDB (Requirement 5.2)
    const diskEntry = await this.getFromDisk(key);
    if (diskEntry) {
      this.addToMemory(key, diskEntry);
      return diskEntry.blob;
    }

    return null;
  }

  /**
   * Set thumbnail in cache (both memory and disk)
   * Validates: Requirements 5.1, 5.3
   */
  async set(videoUrl: string, time: number, blob: Blob, quality?: string): Promise<void> {
    const key = this.generateKey(videoUrl, time, quality);
    const entry: CacheEntry = {
      key,
      blob,
      size: blob.size,
      lastAccessed: Date.now(),
      quality: quality || this.config.quality
    };

    // Add to memory cache with LRU eviction (Requirement 5.3)
    this.addToMemory(key, entry);

    // Persist to disk
    await this.saveToDisk(key, entry);
    
    // Notify subscribers
    this.notifyCacheUpdate(key, entry);
    this.notifyCacheStats();
  }

  /**
   * Add entry to memory cache with LRU eviction
   * Validates: Requirement 5.3
   */
  private addToMemory(key: string, entry: CacheEntry): void {
    const maxMemoryBytes = this.config.maxMemorySize * 1024 * 1024;

    // Evict LRU entries if necessary (Requirement 5.3)
    while (this.currentMemorySize + entry.size > maxMemoryBytes && this.memoryCache.size > 0) {
      this.evictLRU();
    }

    // Only add if there's space
    if (this.currentMemorySize + entry.size <= maxMemoryBytes) {
      this.memoryCache.set(key, entry);
      this.currentMemorySize += entry.size;
    }
  }

  /**
   * Evict least recently used entry from memory cache
   * Validates: Requirement 5.3 (LRU eviction policy)
   */
  private evictLRU(): void {
    let oldestKey: string | null = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.memoryCache.entries()) {
      if (entry.lastAccessed < oldestTime) {
        oldestTime = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      const entry = this.memoryCache.get(oldestKey)!;
      this.currentMemorySize -= entry.size;
      this.memoryCache.delete(oldestKey);
    }
  }

  /**
   * Get entry from IndexedDB
   * Validates: Requirement 5.8
   */
  private async getFromDisk(key: string): Promise<CacheEntry | null> {
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        resolve(null);
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readonly');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.get(key);

      request.onsuccess = () => {
        resolve(request.result || null);
      };

      request.onerror = () => {
        reject(new Error(`Failed to get entry from disk: ${key}`));
      };
    });
  }

  /**
   * Save entry to IndexedDB
   * Validates: Requirement 5.8
   */
  private async saveToDisk(key: string, entry: CacheEntry): Promise<void> {
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.put(entry);

      request.onsuccess = () => {
        resolve();
      };

      request.onerror = () => {
        // Handle quota exceeded error
        if (request.error?.name === 'QuotaExceededError') {
          this.handleQuotaExceeded().then(() => {
            // Retry after cleanup
            this.saveToDisk(key, entry).then(resolve).catch(reject);
          }).catch(reject);
        } else {
          reject(new Error(`Failed to save entry to disk: ${key}`));
        }
      };
    });
  }

  /**
   * Handle quota exceeded error by removing oldest entries
   * Validates: Requirement 5.8
   */
  private async handleQuotaExceeded(): Promise<void> {
    if (!this.db) {
      return;
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const index = objectStore.index('lastAccessed');
      const request = index.openCursor();

      let deletedCount = 0;
      const maxToDelete = 10; // Delete 10 oldest entries

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result;
        if (cursor && deletedCount < maxToDelete) {
          cursor.delete();
          deletedCount++;
          cursor.continue();
        } else {
          resolve();
        }
      };

      request.onerror = () => {
        reject(new Error('Failed to handle quota exceeded'));
      };
    });
  }

  /**
   * Generate cache key from video URL, time, and quality
   */
  private generateKey(videoUrl: string, time: number, quality?: string): string {
    return `${videoUrl}:${time}:${quality || this.config.quality}`;
  }

  /**
   * Check if key exists in cache
   */
  has(key: string): boolean {
    return this.memoryCache.has(key);
  }

  /**
   * Get current memory cache size
   */
  size(): number {
    return this.memoryCache.size;
  }

  /**
   * Get current memory usage in bytes
   */
  getMemoryUsage(): number {
    return this.currentMemorySize;
  }

  /**
   * Clear all caches (memory and disk)
   */
  async clear(): Promise<void> {
    // Clear memory cache
    this.memoryCache.clear();
    this.currentMemorySize = 0;

    // Clear disk cache
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.clear();

      request.onsuccess = () => {
        // Notify subscribers
        this.notifyCacheClear(true);
        this.notifyCacheStats();
        resolve();
      };

      request.onerror = () => {
        reject(new Error('Failed to clear disk cache'));
      };
    });
  }

  /**
   * Preload thumbnails for given times
   * Validates: Requirements 5.5, 5.7
   */
  async preload(videoUrl: string, times: number[], quality?: string): Promise<void> {
    const promises = times.map(time => 
      this.generateAndCache(videoUrl, time, quality)
    );
    await Promise.all(promises);
  }

  /**
   * Preload adjacent thumbnails based on current position
   * Validates: Requirements 5.5, 5.7
   */
  async preloadAdjacent(
    videoUrl: string,
    currentTime: number,
    framerate: number,
    quality?: string
  ): Promise<void> {
    const frameTime = 1 / framerate;
    const times: number[] = [];

    // Preload thumbnails before and after current position
    for (let i = 1; i <= this.config.preloadDistance; i++) {
      times.push(currentTime + (i * frameTime));
      times.push(Math.max(0, currentTime - (i * frameTime)));
    }

    await this.preload(videoUrl, times, quality);
  }

  /**
   * Preload thumbnails for visible range with priority
   * Validates: Requirements 5.5, 5.7
   */
  async preloadVisible(
    videoUrl: string,
    visibleTimes: number[],
    adjacentTimes: number[],
    quality?: string
  ): Promise<void> {
    // Prioritize visible thumbnails
    const visiblePromises = visibleTimes.map(time =>
      this.generateAndCache(videoUrl, time, quality)
    );

    // Wait for visible thumbnails first
    await Promise.all(visiblePromises);

    // Then preload adjacent thumbnails in background
    const adjacentPromises = adjacentTimes.map(time =>
      this.generateAndCache(videoUrl, time, quality)
    );

    // Don't wait for adjacent thumbnails
    Promise.all(adjacentPromises).catch(err => {
      console.warn('Failed to preload adjacent thumbnails:', err);
    });
  }

  /**
   * Generate thumbnail and cache it
   * Validates: Requirements 5.5, 5.7
   */
  async generateAndCache(
    videoUrl: string,
    time: number,
    quality?: string
  ): Promise<Blob> {
    const key = this.generateKey(videoUrl, time, quality);

    // Check if already in cache
    const cached = await this.get(videoUrl, time, quality);
    if (cached) {
      return cached;
    }

    // Generate thumbnail (this would be implemented by the video player)
    const blob = await this.generateThumbnail(videoUrl, time, quality);
    await this.set(videoUrl, time, blob, quality);
    return blob;
  }

  /**
   * Generate thumbnail from video at specific time
   * This is a placeholder - actual implementation would use video element
   */
  private async generateThumbnail(
    videoUrl: string,
    time: number,
    quality?: string
  ): Promise<Blob> {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.crossOrigin = 'anonymous';
      video.src = videoUrl;

      video.addEventListener('loadedmetadata', () => {
        video.currentTime = time;
      });

      video.addEventListener('seeked', () => {
        const canvas = document.createElement('canvas');
        const qualitySettings = {
          low: { width: 160, height: 90 },
          medium: { width: 320, height: 180 },
          high: { width: 640, height: 360 }
        };

        const settings = qualitySettings[quality as keyof typeof qualitySettings] || qualitySettings.medium;
        canvas.width = settings.width;
        canvas.height = settings.height;

        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((blob) => {
            if (blob) {
              resolve(blob);
            } else {
              reject(new Error('Failed to generate thumbnail blob'));
            }
          }, 'image/jpeg', 0.8);
        } else {
          reject(new Error('Failed to get canvas context'));
        }
      });

      video.addEventListener('error', () => {
        reject(new Error(`Failed to load video: ${videoUrl}`));
      });
    });
  }

  /**
   * Get cache statistics
   */
  getStats(): {
    memorySize: number;
    memoryUsage: number;
    memoryCount: number;
    maxMemorySize: number;
  } {
    return {
      memorySize: this.currentMemorySize,
      memoryUsage: (this.currentMemorySize / (this.config.maxMemorySize * 1024 * 1024)) * 100,
      memoryCount: this.memoryCache.size,
      maxMemorySize: this.config.maxMemorySize * 1024 * 1024
    };
  }
}

/**
 * VoiceTextService - Service d'intégration voix/texte
 *
 * Permet la reconnaissance vocale pour la saisie, la synthèse vocale
 * pour les réponses, le contrôle vocal des fonctionnalités,
 * et améliore l'accessibilité.
 */

import { notificationService } from './NotificationService';
import { LanguageCode } from '@/utils/llmConfigStorage';

// Use any type for browser Web Speech APIs to avoid type conflicts
/* eslint-disable @typescript-eslint/no-explicit-any */

export interface VoiceHotkeyConfig {
  key: string;
  modifier: 'alt' | 'ctrl' | 'shift' | 'meta' | 'none';
  enabled: boolean;
}

export interface VoiceSettings {
  enabled: boolean;
  inputLanguage: LanguageCode;
  outputLanguage: LanguageCode;
  voiceSpeed: number; // 0.5 - 2.0
  voicePitch: number; // 0 - 2
  voiceVolume: number; // 0 - 1
  autoSpeakResponses: boolean;
  voiceActivationKeyword: string;
  continuousListening: boolean;
  activationHotkey: VoiceHotkeyConfig;
}

export interface SpeechRecognitionResult {
  transcript: string;
  confidence: number;
  isFinal: boolean;
  language: LanguageCode;
}

export interface VoiceCommand {
  command: string;
  action: () => void;
  keywords: string[];
  description: string;
}

/**
 * Service d'intégration voix/texte
 */
export class VoiceTextService {
  private static instance: VoiceTextService;

  // APIs du navigateur - using any to avoid type conflicts
  private speechRecognition: any = null;
  private speechSynthesis: any = null;

  // État du service
  private settings: VoiceSettings;
  private isListening = false;
  private isSpeaking = false;
  private recognitionCallbacks: {
    onResult: (result: SpeechRecognitionResult) => void;
    onError: (error: string) => void;
    onStart: () => void;
    onEnd: () => void;
  } | null = null;

  // Commandes vocales
  private voiceCommands: VoiceCommand[] = [];

  private constructor() {
    this.settings = this.loadSettings();
    this.initializeAPIs();
    this.setupVoiceCommands();
  }

  static getInstance(): VoiceTextService {
    if (!VoiceTextService.instance) {
      VoiceTextService.instance = new VoiceTextService();
    }
    return VoiceTextService.instance;
  }

  /**
   * Initialise les APIs du navigateur
   */
  private initializeAPIs(): void {
    // Reconnaissance vocale - use any to access browser API
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      this.speechRecognition = new SpeechRecognition();
      this.configureSpeechRecognition();
    }

    // Synthèse vocale
    if ('speechSynthesis' in window) {
      this.speechSynthesis = (window as any).speechSynthesis;
    }

    // Vérifier la compatibilité
    if (!this.speechRecognition || !this.speechSynthesis) {
      notificationService.warning(
        'Fonctionnalités vocales limitées',
        'Certaines fonctionnalités vocales ne sont pas disponibles dans votre navigateur.',
        [
          {
            label: 'En savoir plus',
            action: () => window.open('https://caniuse.com/speech-recognition', '_blank'),
            primary: true
          }
        ]
      );
    }
  }

  /**
   * Configure la reconnaissance vocale
   */
  private configureSpeechRecognition(): void {
    if (!this.speechRecognition) return;

    this.speechRecognition.continuous = this.settings.continuousListening;
    this.speechRecognition.interimResults = true;
    this.speechRecognition.lang = this.getLanguageCode(this.settings.inputLanguage);

    this.speechRecognition.onstart = () => {
      this.isListening = true;
      this.recognitionCallbacks?.onStart();
    };

    this.speechRecognition.onresult = (event: any) => {
      const result = event.results[event.results.length - 1];
      const transcript = result[0].transcript;
      const confidence = result[0].confidence;

      this.recognitionCallbacks?.onResult({
        transcript,
        confidence,
        isFinal: result.isFinal,
        language: this.settings.inputLanguage
      });

      // Vérifier les commandes vocales
      if (result.isFinal) {
        this.processVoiceCommand(transcript);
      }
    };

    this.speechRecognition.onerror = (event: any) => {
      this.isListening = false;
      let errorMessage = 'Erreur de reconnaissance vocale';

      switch (event.error) {
        case 'network':
          errorMessage = 'Erreur réseau lors de la reconnaissance vocale';
          break;
        case 'not-allowed':
          errorMessage = 'Permission micro refusée';
          break;
        case 'no-speech':
          errorMessage = 'Aucune parole détectée';
          break;
        case 'aborted':
          errorMessage = 'Reconnaissance vocale interrompue';
          break;
      }

      this.recognitionCallbacks?.onError(errorMessage);
    };

    this.speechRecognition.onend = () => {
      this.isListening = false;
      this.recognitionCallbacks?.onEnd();
    };
  }

  /**
   * Charge les paramètres
   */
  private loadSettings(): VoiceSettings {
    const defaultSettings: VoiceSettings = {
      enabled: true,
      inputLanguage: 'fr',
      outputLanguage: 'fr',
      voiceSpeed: 1.0,
      voicePitch: 1.0,
      voiceVolume: 0.8,
      autoSpeakResponses: false,
      voiceActivationKeyword: 'hé ros',
      continuousListening: false,
      activationHotkey: {
        key: 'Space',
        modifier: 'alt',
        enabled: true
      }
    };

    try {
      const stored = localStorage.getItem('voice-settings');
      const parsed = stored ? JSON.parse(stored) : {};
      return { ...defaultSettings, ...parsed };
    } catch {
      return defaultSettings;
    }
  }

  /**
   * Sauvegarde les paramètres
   */
  saveSettings(settings: Partial<VoiceSettings>): void {
    this.settings = { ...this.settings, ...settings };
    localStorage.setItem('voice-settings', JSON.stringify(this.settings));

    // Reconfigurer la reconnaissance si la langue a changé
    if (settings.inputLanguage) {
      this.configureSpeechRecognition();
    }
  }

  /**
   * Configure les commandes vocales
   */
  private setupVoiceCommands(): void {
    this.voiceCommands = [
      {
        command: 'envoyer',
        action: () => {
          // Simuler l'envoi du message
          const sendButton = document.querySelector('button[aria-label="Send message"]') as HTMLButtonElement;
          sendButton?.click();
        },
        keywords: ['envoyer', 'envoyez', 'send', 'submit'],
        description: 'Envoyer le message actuel'
      },
      {
        command: 'effacer',
        action: () => {
          // Effacer le texte
          const textarea = document.querySelector('textarea[aria-label="Message input"]') as HTMLTextAreaElement;
          if (textarea) {
            textarea.value = '';
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
          }
        },
        keywords: ['effacer', 'clear', 'delete', 'supprimer'],
        description: 'Effacer le texte saisi'
      },
      {
        command: 'suggestions',
        action: () => {
          // Basculer l'affichage des suggestions
          const suggestionsButton = document.querySelector('button[title*="suggestions"]') as HTMLButtonElement;
          suggestionsButton?.click();
        },
        keywords: ['suggestions', 'conseils', 'aide'],
        description: 'Afficher/masquer les suggestions'
      },
      {
        command: 'améliorer',
        action: () => {
          // Déclencher l'amélioration IA
          const enhanceButton = document.querySelector('button[aria-label*="améliorer"]') as HTMLButtonElement;
          enhanceButton?.click();
        },
        keywords: ['améliorer', 'enhance', 'improve'],
        description: 'Améliorer le texte avec IA'
      },
      {
        command: 'parler',
        action: () => {
          // Activer/désactiver la synthèse vocale
          this.settings.autoSpeakResponses = !this.settings.autoSpeakResponses;
          notificationService.info(
            'Synthèse vocale',
            `Synthèse vocale ${this.settings.autoSpeakResponses ? 'activée' : 'désactivée'}`
          );
        },
        keywords: ['parler', 'speak', 'voice', 'talk'],
        description: 'Activer/désactiver la synthèse vocale'
      }
    ];
  }

  /**
   * Démarre la reconnaissance vocale
   */
  startListening(callbacks: {
    onResult: (result: SpeechRecognitionResult) => void;
    onError: (error: string) => void;
    onStart: () => void;
    onEnd: () => void;
  }): boolean {
    if (!this.settings.enabled || !this.speechRecognition) {
      callbacks.onError('Reconnaissance vocale non disponible');
      return false;
    }

    if (this.isListening) {
      this.stopListening();
    }

    this.recognitionCallbacks = callbacks;

    try {
      this.speechRecognition.start();
      return true;
    } catch (error) {
      callbacks.onError('Impossible de démarrer la reconnaissance vocale');
      return false;
    }
  }

  /**
   * Arrête la reconnaissance vocale
   */
  stopListening(): void {
    if (this.speechRecognition && this.isListening) {
      this.speechRecognition.stop();
    }
  }

  /**
   * Parle un texte
   */
  speak(text: string, options?: {
    speed?: number;
    pitch?: number;
    volume?: number;
    voice?: any;
  }): boolean {
    if (!this.settings.enabled || !this.speechSynthesis) {
      return false;
    }

    // Arrêter la synthèse en cours
    if (this.isSpeaking) {
      this.speechSynthesis.cancel();
    }

    const utterance = new (window as any).SpeechSynthesisUtterance(text);

    // Configuration
    utterance.rate = options?.speed || this.settings.voiceSpeed;
    utterance.pitch = options?.pitch || this.settings.voicePitch;
    utterance.volume = options?.volume || this.settings.voiceVolume;
    utterance.lang = this.getLanguageCode(this.settings.outputLanguage);

    if (options?.voice) {
      utterance.voice = options.voice;
    } else {
      // Sélectionner une voix appropriée
      const voices = this.speechSynthesis.getVoices();
      const preferredVoice = voices.find((voice: any) =>
        voice.lang.startsWith(this.settings.outputLanguage) && voice.localService
      );
      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }
    }

    utterance.onstart = () => {
      this.isSpeaking = true;
    };

    utterance.onend = () => {
      this.isSpeaking = false;
    };

    utterance.onerror = (event: any) => {
      this.isSpeaking = false;
      console.error('Speech synthesis error:', event.error);
    };

    this.speechSynthesis.speak(utterance);
    return true;
  }

  /**
   * Arrête la synthèse vocale
   */
  stopSpeaking(): void {
    if (this.speechSynthesis) {
      this.speechSynthesis.cancel();
      this.isSpeaking = false;
    }
  }

  /**
   * Traite une commande vocale
   */
  private processVoiceCommand(transcript: string): void {
    const lowerTranscript = transcript.toLowerCase().trim();

    // Vérifier le mot-clé d'activation
    if (this.settings.voiceActivationKeyword &&
        !lowerTranscript.includes(this.settings.voiceActivationKeyword.toLowerCase())) {
      return;
    }

    // Nettoyer le transcript du mot-clé
    let cleanTranscript = lowerTranscript;
    if (this.settings.voiceActivationKeyword) {
      cleanTranscript = cleanTranscript.replace(this.settings.voiceActivationKeyword.toLowerCase(), '').trim();
    }

    // Trouver la commande correspondante
    for (const command of this.voiceCommands) {
      const hasKeyword = command.keywords.some(keyword =>
        cleanTranscript.includes(keyword.toLowerCase())
      );

      if (hasKeyword) {
        notificationService.info(
          'Commande vocale exécutée',
          `"${command.description}"`,
          [
            {
              label: 'Annuler',
              action: () => {}, // Pourrait implémenter un undo
              primary: true
            }
          ]
        );

        command.action();
        return;
      }
    }
  }

  /**
   * Obtient la liste des voix disponibles
   */
  getAvailableVoices(): any[] {
    return this.speechSynthesis ? this.speechSynthesis.getVoices() : [];
  }

  /**
   * Obtient les paramètres actuels
   */
  getSettings(): VoiceSettings {
    return { ...this.settings };
  }

  /**
   * Vérifie si la reconnaissance vocale est disponible
   */
  isSpeechRecognitionAvailable(): boolean {
    return !!this.speechRecognition;
  }

  /**
   * Vérifie si la synthèse vocale est disponible
   */
  isSpeechSynthesisAvailable(): boolean {
    return !!this.speechSynthesis;
  }

  /**
   * Obtient l'état actuel
   */
  getStatus(): {
    isListening: boolean;
    isSpeaking: boolean;
    hasRecognition: boolean;
    hasSynthesis: boolean;
  } {
    return {
      isListening: this.isListening,
      isSpeaking: this.isSpeaking,
      hasRecognition: this.isSpeechRecognitionAvailable(),
      hasSynthesis: this.isSpeechSynthesisAvailable()
    };
  }

  /**
   * Obtient les commandes vocales disponibles
   */
  getVoiceCommands(): VoiceCommand[] {
    return [...this.voiceCommands];
  }

  /**
   * Convertit un code de langue en code BCP 47
   */
  private getLanguageCode(language: LanguageCode): string {
    const languageMap: Record<LanguageCode, string> = {
      fr: 'fr-FR',
      en: 'en-US',
      es: 'es-ES',
      de: 'de-DE',
      it: 'it-IT',
      pt: 'pt-BR',
      ja: 'ja-JP',
      zh: 'zh-CN',
      ko: 'ko-KR'
    };
    return languageMap[language] || 'fr-FR';
  }

  /**
   * Teste la reconnaissance vocale
   */
  async testSpeechRecognition(): Promise<boolean> {
    return new Promise((resolve) => {
      if (!this.speechRecognition) {
        resolve(false);
        return;
      }

      const testCallbacks = {
        onResult: (result: SpeechRecognitionResult) => {
          if (result.isFinal && result.transcript.trim()) {
            notificationService.success(
              'Test réussi',
              `Reconnaissance: "${result.transcript}" (${Math.round(result.confidence * 100)}% de confiance)`
            );
            this.stopListening();
            resolve(true);
          }
        },
        onError: (error: string) => {
          notificationService.error('Test échoué', error);
          resolve(false);
        },
        onStart: () => {
          notificationService.info('Test en cours', 'Parlez maintenant...');
        },
        onEnd: () => {
          resolve(false);
        }
      };

      setTimeout(() => {
        this.stopListening();
        notificationService.warning('Test expiré', 'Aucune parole détectée');
        resolve(false);
      }, 5000);

      this.startListening(testCallbacks);
    });
  }

  /**
   * Teste la synthèse vocale
   */
  testSpeechSynthesis(): boolean {
    const testText = this.settings.outputLanguage === 'fr'
      ? 'Test de synthèse vocale réussi'
      : 'Speech synthesis test successful';

    const success = this.speak(testText);

    if (success) {
      notificationService.success('Test réussi', 'Synthèse vocale fonctionnelle');
    } else {
      notificationService.error('Test échoué', 'Synthèse vocale non disponible');
    }

    return success;
  }

  /**
   * Nettoie les ressources
   */
  destroy(): void {
    this.stopListening();
    this.stopSpeaking();

    if (this.speechRecognition) {
      this.speechRecognition.abort();
    }
  }
}

