    metadata: {
      generationParams: { prompt: 'test prompt' },
      fileSize: 1024,
      dimensions: { width: 512, height: 512 },
      format: type === 'image' ? 'png' : type === 'video' ? 'mp4' : 'wav',
    },
    relatedAssets: [],
