      expect(imageRelated[0].id).toBe(videoAsset.id);
      
      const videoRelated = assetManagementService.getRelatedAssets(videoAsset.id);
      expect(videoRelated).toHaveLength(1);
      expect(videoRelated[0].id).toBe(audioAsset.id);
