describe('Event History', () => {
  beforeEach(() => {
    eventEmitter.offAll();
    eventEmitter.clearHistory();
  });

  it('should record character events in history', () => {
    const payload = createCharacterCreatedPayload(mockCharacter, 'wizard');
    eventEmitter.emit(CharacterEventType.CHARACTER_CREATED, payload);

    const history = eventEmitter.getHistory(CharacterEventType.CHARACTER_CREATED);
    expect(history).toHaveLength(1);
    expect(history[0].type).toBe(CharacterEventType.CHARACTER_CREATED);
    expect(history[0].payload).toBe(payload);
  });

  it('should filter history by event type', () => {
    const createdPayload = createCharacterCreatedPayload(mockCharacter, 'wizard');
    const updatedPayload = createCharacterUpdatedPayload('char-123', { name: 'New Name' }, 'editor');

    eventEmitter.emit(CharacterEventType.CHARACTER_CREATED, createdPayload);
    eventEmitter.emit(CharacterEventType.CHARACTER_UPDATED, updatedPayload);

    const createdHistory = eventEmitter.getHistory(CharacterEventType.CHARACTER_CREATED);
    expect(createdHistory).toHaveLength(1);
    expect(createdHistory[0].type).toBe(CharacterEventType.CHARACTER_CREATED);

    const updatedHistory = eventEmitter.getHistory(CharacterEventType.CHARACTER_UPDATED);
    expect(updatedHistory).toHaveLength(1);
    expect(updatedHistory[0].type).toBe(CharacterEventType.CHARACTER_UPDATED);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { ChatService } from '../chatService';
import type { ChatContext, ProjectCreationRequest } from '../chatService';

describe('ChatService', () => {
  let chatService: ChatService;
  let mockContext: ChatContext;

  beforeEach(() => {
    mockContext = {
      project: {
        id: 'test-project-1',
        schema_version: '1.0',
        project_name: 'Test Project',
        shots: [],
        assets: [],
        capabilities: {
          grid_generation: true,
          promotion_engine: true,
          qa_engine: true,
          autofix_engine: true,
        },
        generation_status: {
          grid: 'pending',
          promotion: 'pending',
        },
      },
      shots: [],
      assets: [],
      selectedShotId: null,
    };

    chatService = new ChatService(mockContext);
  });

  describe('Context Management', () => {
    it('initializes with provided context', () => {
      expect(chatService).toBeDefined();
    });

    it('updates context', () => {
      const newShot = {
        id: 'shot-1',
        title: 'Test Shot',
        description: 'Test',
        duration: 5,
        position: 0,
        audioTracks: [],
        effects: [],
        textLayers: [],
        animations: [],
      };

      chatService.updateContext({ shots: [newShot] });

      // Context should be updated (verified through behavior)
      expect(chatService).toBeDefined();
    });
  });

  describe('Conversation History', () => {
    it('adds messages to history', () => {
      const message = {
        id: 'msg-1',
        role: 'user' as const,
        content: 'Test message',
        timestamp: new Date(),
      };

      chatService.addToHistory(message);

      const history = chatService.getHistory();
      expect(history).toHaveLength(1);
      expect(history[0]).toEqual(message);
    });

    it('maintains conversation history', () => {
      const message1 = {
        id: 'msg-1',
        role: 'user' as const,
        content: 'First message',
        timestamp: new Date(),
      };

      const message2 = {
        id: 'msg-2',
        role: 'assistant' as const,
        content: 'Response',
        timestamp: new Date(),
      };

      chatService.addToHistory(message1);
      chatService.addToHistory(message2);

      const history = chatService.getHistory();
      expect(history).toHaveLength(2);
    });

    it('clears conversation history', () => {
      const message = {
        id: 'msg-1',
        role: 'user' as const,
        content: 'Test',
        timestamp: new Date(),
      };

      chatService.addToHistory(message);
      chatService.clearHistory();

      const history = chatService.getHistory();
      expect(history).toHaveLength(0);
    });
  });

  describe('Intent Analysis', () => {
    it('recognizes shot creation intent', async () => {
      const response = await chatService.processMessage('Create 3 shots about sunrise');

      expect(response.message).toContain('created');
      expect(response.actions).toBeDefined();
      expect(response.actions?.length).toBe(3);
