/**
 * AI Shot Composition Service
 * 
 * Provides intelligent shot composition suggestions using the AI Shot Composition Engine.
 * Integrates with the existing service architecture and provides React hooks for UI integration.
 */

import { EventEmitter } from 'events';
import { getLLMService } from './llmService';

// Shot composition basic types (synchronized with existing codebase)
export enum ShotType {
  EXTREME_CLOSE_UP = 'extreme_close_up',
  CLOSE_UP = 'close_up',
  MEDIUM_CLOSE_UP = 'medium_close_up',
  MEDIUM_SHOT = 'medium_shot',
  WIDE_SHOT = 'wide_shot',
  ESTABLISHING = 'establishing'
}

export enum CameraMovement {
  STATIC = 'static',
  PAN = 'pan',
  TILT = 'tilt',
  DOLLY = 'dolly',
  TRACKING = 'tracking',
  STEADICAM = 'steadicam'
}

export enum LightingStyle {
  HIGH_KEY = 'high_key',
  LOW_KEY = 'low_key',
  NATURAL = 'natural',
  CHIAOSCURO = 'chiaoscuro',
  SOFT = 'soft'
}

export enum CompositionRule {
  RULE_OF_THIRDS = 'rule_of_thirds',
  GOLDEN_RATIO = 'golden_ratio',
  SYMMETRICAL_BALANCE = 'symmetrical_balance',
  LEADING_LINES = 'leading_lines',
  FRAMING = 'framing'
}

export interface VisualBalance {
  horizontalBalance: number;
  verticalBalance: number;
  depthBalance: number;
