}

// Shot composition data types
export interface ShotComposition {
  id: string;
  sceneId: string;
  shotNumber: number;
  composition: ShotCompositionResult;
  createdAt: Date;
  updatedAt: Date;
}

export interface ShotCompositionResult {
  shotType: ShotType;
  cameraMovement: CameraMovement;
