export class VoiceProfileBuilder {
  private profile: Partial<VoiceProfile>;
  private projectId: string;

  constructor(projectId: string) {
    this.projectId = projectId;
    this.profile = {
      id: `voice_profile_${projectId}`,
      projectId,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      voiceType: 'raw',
      textContent: '',
      language: 'fr',
      filters: [],
      tracks: []
    };
  }

  setVoiceType(voiceType: string): VoiceProfileBuilder {
    const validTypes: VoiceType[] = ['raw', 'sung', 'whisper', 'styled'];
    this.profile.voiceType = validTypes.includes(voiceType.toLowerCase() as VoiceType) ? voiceType.toLowerCase() as VoiceType : 'raw';
    return this;
  }

  setTextContent(text: string): VoiceProfileBuilder {
    this.profile.textContent = text;
    return this;
  }

  setLanguage(language: string): VoiceProfileBuilder {
    this.profile.language = language;
    return this;
  }

  addFilter(filterType: string, params: Record<string, number>): VoiceProfileBuilder {
    const validFilterTypes: VoiceFilterType[] = ['eq', 'compressor', 'reverb', 'distortion', 'band_pass', 'pitch_shift', 'vibrato', 'chorus', 'phaser'];
    this.profile.filters?.push({
      filterType: validFilterTypes.includes(filterType as VoiceFilterType) ? filterType as VoiceFilterType : 'eq',
      enabled: true,
      parameters: params
    });
    return this;
  }

  build(): VoiceProfile {
    return {
      ...this.profile,
      tracks: this.generateDefaultTracks()
    } as VoiceProfile;
  }

  private generateDefaultTracks() {
    const tracks: VoiceTrack[] = [];
    
    if (this.profile.voiceType === 'raw') {
      tracks.push({
        id: `voice_raw_${this.projectId}`,
        name: 'Voix Brute',
        trackType: 'raw',
        prompt: this.generateVoicePrompt(),
        parameters: {},
        enabled: true,
        volume: 0,
        pan: 0,
        muted: false,
        solo: false,
        effects: [],
        automation: [],
        voiceType: 'raw',
        filters: []
      });
    }
    
    if (this.profile.voiceType === 'styled') {
      tracks.push({
        id: `voice_styled_${this.projectId}`,
        name: 'Voix Stylisée',
        trackType: 'styled',
        prompt: this.generateStyledVoicePrompt(),
        parameters: {},
        enabled: true,
        volume: 0,
        pan: 0,
        muted: false,
        solo: false,
        effects: [],
        automation: [],
        voiceType: 'styled',
        filters: []
      });
    }
    
    return tracks;
  }

  private generateVoicePrompt(): string {
    return `Génère une piste voix BRUTE pour: "${this.profile.textContent}"
Langue: ${this.profile.language}
Style: naturel, voix humaine
Filters: EQ, compressor, reverb légère
Duration: estimation basée sur le texte`;
  }

  private generateStyledVoicePrompt(): string {
    return `Génère une piste voix STYLISÉE pour: "${this.profile.textContent}"
Langue: ${this.profile.language}
Style: effets spécial
Filters: ${this.profile.filters?.map(f => f.filterType).join(', ') || 'standard'}
Duration: estimation basée sur le texte`;
  }
}

/**
 * StoryCore-Engine Audio-Sequence Integration Service
 */

import type {
  MusicProfile,
  SFXProfile,
  VoiceProfile,
  MixConfiguration
} from '../types/audioMultitrack';
import { audioMultitrackService } from './audioMultitrack';

export type IntegrationAudioType = 'music' | 'sfx' | 'voice' | 'all';
export type IntegrationStatus = 'pending' | 'processing' | 'completed' | 'failed';

export interface SequenceAudioContext {
  projectId: string;
  projectType?: string;
  location?: string;
  themes: string[];
  visualStyle?: string;
  emotionalIntensity: string;
  shotId?: string;
  shotType: string;
  shotDescription?: string;
  shotDuration: number;
  actionType?: string;
  actionIntensity?: string;
  visualRhythm?: string;
  autoMix: boolean;
  ducking: boolean;
}

export interface IntegratedAudioResult {
  success: boolean;
  status: IntegrationStatus;
  musicPrompts: TrackPrompt[];
  sfxPrompts: TrackPrompt[];
  voicePrompts: TrackPrompt[];
  errors: string[];
  generatedAt: string;
}

export interface TrackPrompt {
  trackName: string;
  trackType: string;
  prompt: string;
  shotId?: string;
}

export interface TimelineTrack {
  id: string;
  name: string;
  type: string;
  clips: TimelineClip[];
  muted: boolean;
  volume: number;
  height: number;
}

export interface TimelineClip {
  id: string;
  name: string;
  startTime: number;
  duration: number;
  audioTrackId: string;
  prompt: string;
  regeneratable: boolean;
}

export interface TimelineSyncData {
  sequenceId: string;
  projectId: string;
  totalDuration: number;
  tracks: TimelineTrack[];
  generatedAt: string;
  audioPrompts: {
    music: TrackPrompt[];
    sfx: TrackPrompt[];
    voice: TrackPrompt[];
  };
}

export class AudioSequenceIntegrationService {
  /**
   * Extract audio contexts from a generated sequence
   */
  extractContextsFromSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>
  ): SequenceAudioContext[] {
    const contexts: SequenceAudioContext[] = [];
    const projectId = sequence.project_id || '';
    const shots = sequence.shots || [];
    const projType = projectContext?.project_type || '';
    const location = projectContext?.location || '';
    const themes = projectContext?.themes || [];
    const style = projectContext?.visual_style || '';
    const intensity = projectContext?.emotional_intensity || 'medium';

    for (const shot of shots) {
      contexts.push({
        projectId,
        projectType: projType,
        location,
        themes: [...themes],
        visualStyle: style,
        emotionalIntensity: intensity,
        shotId: shot.id,
        shotType: shot.shot_type || 'action',
        shotDescription: shot.prompt || '',
        shotDuration: shot.duration_seconds || 5.0,
        autoMix: true,
        ducking: true
      });
    }
    return contexts;
  }

  /**
   * Generate all audio for a complete sequence
   */
  async generateAudioForSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>,
    audioTypes: IntegrationAudioType[] = ['all']
  ): Promise<IntegratedAudioResult> {
    const result: IntegratedAudioResult = {
      success: true,
      status: 'completed',
      musicPrompts: [],
      sfxPrompts: [],
      voicePrompts: [],
      errors: [],
      generatedAt: new Date().toISOString()
    };

    const contexts = this.extractContextsFromSequence(sequence, projectContext);
    const shouldGenerateMusic = audioTypes.includes('all') || audioTypes.includes('music');
    const shouldGenerateSFX = audioTypes.includes('all') || audioTypes.includes('sfx');
    const shouldGenerateVoice = audioTypes.includes('all') || audioTypes.includes('voice');

    if (shouldGenerateMusic) {
      for (const context of contexts) {
        result.musicPrompts.push(
          { trackName: 'Base', trackType: 'base', prompt: `Music base for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Melody', trackType: 'melody', prompt: `Music melody for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Percussion', trackType: 'percussion', prompt: `Percussion for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Bass', trackType: 'bass', prompt: `Bass for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'FX', trackType: 'fx', prompt: `Music FX for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Drones', trackType: 'drones', prompt: `Drones for ${context.shotType}`, shotId: context.shotId }
        );
      }
    }

    if (shouldGenerateSFX) {
      for (const context of contexts) {
        result.sfxPrompts.push(
          { trackName: 'Action', trackType: 'action', prompt: `SFX for ${context.shotType} action`, shotId: context.shotId },
          { trackName: 'Environment', trackType: 'environment', prompt: `Environment sounds for ${context.location || 'scene'}`, shotId: context.shotId },
          { trackName: 'Stylized', trackType: 'stylized', prompt: `Stylized SFX for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Bullet Time', trackType: 'bullet_time', prompt: `Bullet time SFX for ${context.shotType}`, shotId: context.shotId }
        );
      }
    }

    if (shouldGenerateVoice) {
      for (const context of contexts) {
        result.voicePrompts.push({
          trackName: 'Voice',
          trackType: context.shotType === 'narration' ? 'whisper' : 'raw',
          prompt: context.shotDescription || '',
          shotId: context.shotId
        });
      }
    }

    result.status = result.success ? 'completed' : 'failed';
    return result;
  }

  /**
   * Attach generated audio to a shot
   */
  attachAudioToShot(
    shot: unknown,
    audioResult: IntegratedAudioResult,
    audioType: IntegrationAudioType = 'all'
  ): unknown {
    const shotId = shot.id;
    const musicTracks = audioResult.musicPrompts.filter(p => p.shotId === shotId);
    const sfxTracks = audioResult.sfxPrompts.filter(p => p.shotId === shotId);
    const voiceTracks = audioResult.voicePrompts.filter(p => p.shotId === shotId);
    const audioTracks: unknown[] = [];
    const duration = shot.duration_seconds || 5.0;

    if (audioType === 'all' || audioType === 'music') {
      for (const track of musicTracks) {
        audioTracks.push({
          id: `${shotId}_music_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'music',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: -6.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    if (audioType === 'all' || audioType === 'sfx') {
      for (const track of sfxTracks) {
        audioTracks.push({
          id: `${shotId}_sfx_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'sfx',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: 0.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    if (audioType === 'all' || audioType === 'voice') {
      for (const track of voiceTracks) {
        audioTracks.push({
          id: `${shotId}_voice_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'voice',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: 0.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    return { ...shot, audio_tracks: audioTracks, audio_generated: audioTracks.length > 0 };
  }

  /**
   * Generate timeline synchronization data
   */
  generateTimelineSyncData(sequence: unknown, audioResult: IntegratedAudioResult): TimelineSyncData {
    const shots = sequence.shots || [];
    const timelineTracks: TimelineTrack[] = [
      { id: 'timeline_dialogue', name: 'Dialogue', type: 'voice', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_sfx_action', name: 'SFX - Action', type: 'sfx', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_sfx_environment', name: 'SFX - Environment', type: 'sfx', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_base', name: 'Music - Base', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_melody', name: 'Music - Melody', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_percussion', name: 'Music - Percussion', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_bass', name: 'Music - Bass', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_fx', name: 'Music - FX', type: 'music', clips: [], muted: false, volume: 0, height: 40 }
    ];

    let currentTime = 0;
    for (const shot of shots) {
      const shotDuration = shot.duration_seconds || 5.0;
      const shotId = shot.id || '';
      const audioTracks = shot.audio_tracks || [];

      for (const audioTrack of audioTracks) {
        const trackType = audioTrack.type || 'music';
        const trackName = audioTrack.name || '';
        let timelineTrackId = '';

        if (trackType === 'voice') {
          timelineTrackId = 'timeline_dialogue';
        } else if (trackType === 'sfx') {
          timelineTrackId = trackName.toLowerCase().includes('action') ? 'timeline_sfx_action' : 'timeline_sfx_environment';
        } else {
          const nameLower = trackName.toLowerCase();
          if (nameLower.includes('base')) timelineTrackId = 'timeline_music_base';
          else if (nameLower.includes('melody')) timelineTrackId = 'timeline_music_melody';
          else if (nameLower.includes('percussion')) timelineTrackId = 'timeline_music_percussion';
          else if (nameLower.includes('bass')) timelineTrackId = 'timeline_music_bass';
          else if (nameLower.includes('fx')) timelineTrackId = 'timeline_music_fx';
          else timelineTrackId = 'timeline_music_base';
        }

        for (const track of timelineTracks) {
          if (track.id === timelineTrackId) {
            track.clips.push({
              id: audioTrack.id,
              name: trackName,
              startTime: currentTime,
              duration: shotDuration,
              audioTrackId: audioTrack.id,
              prompt: audioTrack.prompt || '',
              regeneratable: audioTrack.regeneratable !== false
            });
            break;
          }
        }
      }
      currentTime += shotDuration;
    }

    return {
      sequenceId: sequence.id || '',
      projectId: sequence.project_id || '',
      totalDuration: currentTime,
      tracks: timelineTracks,
      generatedAt: new Date().toISOString(),
      audioPrompts: { music: audioResult.musicPrompts, sfx: audioResult.sfxPrompts, voice: audioResult.voicePrompts }
    };
  }

  /**
   * Apply audio to entire sequence
   */
  async applyAudioToSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>,
    audioTypes: IntegrationAudioType[] = ['all']
  ): Promise<{ sequence: unknown; timeline: TimelineSyncData }> {
    const audioResult = await this.generateAudioForSequence(sequence, projectContext, audioTypes);
    const type = audioTypes.includes('all') ? 'all' : audioTypes[0];
    const updatedShots = (sequence.shots || []).map((shot: unknown) => this.attachAudioToShot(shot, audioResult, type));
    const updatedSequence = { ...sequence, shots: updatedShots, audio_generated: audioResult.success, audio_generation_result: audioResult };
    const timeline = this.generateTimelineSyncData(updatedSequence, audioResult);
    return { sequence: updatedSequence, timeline };
  }
}

export const audioSequenceIntegrationService = new AudioSequenceIntegrationService();

export function getDefaultAudioForShotType(shotType: string): { musicIntensity: string; sfxIntensity: string; enableVoice: boolean } {
  const mapping: Record<string, { musicIntensity: string; sfxIntensity: string; enableVoice: boolean }> = {
    'action': { musicIntensity: 'high', sfxIntensity: 'high', enableVoice: false },
    'dialogue': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: true },
    'ambient': { musicIntensity: 'medium', sfxIntensity: 'medium', enableVoice: false },
    'transition': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: false },
    'narration': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: true }
  };
  return mapping[shotType] || { musicIntensity: 'medium', sfxIntensity: 'medium', enableVoice: false };
}

export function estimateAudioGenerationTime(shotCount: number, audioTypes: IntegrationAudioType[]): number {
  return 30 + (shotCount * 10 * audioTypes.length);
}

/**
 * WorkerPool - Pool de Web Workers pour traitement parallèle
 * 
 * Gère un pool de workers pour exécuter des tâches en parallèle:
 * - Allocation et libération de workers
 * - File d'attente de tâches
 * - Gestion des erreurs
 * - Annulation de tâches
 * 
 * Exigences: 10.1, 10.6
 */

import type { WorkerTask, WorkerMessage } from '../../types';

/**
 * Configuration du pool de workers
 */
export interface WorkerPoolConfig {
  size?: number;
  workerUrl?: string;
}

/**
 * Pool de Web Workers
 * Exigence: 10.1 - Traitement non-bloquant
 * Exigence: 10.6 - Traitement parallèle avec file d'attente
 */
export class WorkerPool {
  private workers: Worker[] = [];
  private availableWorkers: Worker[] = [];
  private taskQueue: WorkerTask[] = [];
  public readonly size: number;
  
  constructor(config: WorkerPoolConfig = {}) {
    this.size = config.size || navigator.hardwareConcurrency || 4;
    this.initializeWorkers();
  }
  
  /**
   * Initialise les workers
   */
  private initializeWorkers(): void {
    for (let i = 0; i < this.size; i++) {
      try {
        const worker = new Worker(
          new URL('../../workers/processing.worker.ts', import.meta.url),
          { type: 'module' }
        );
        
        worker.onmessage = (event) => {
          this.handleWorkerMessage(worker, event.data);
        };
        
        worker.onerror = (error) => {
          this.handleWorkerError(worker, error);
        };
        
        this.workers.push(worker);
        this.availableWorkers.push(worker);
      } catch (error) {
        console.error(`Failed to create worker ${i}:`, error);
      }
    }
  }
  
  /**
   * Exécute une tâche
   * Exigence: 10.1 - Traitement non-bloquant
   */
  async execute<T>(type: string, data: unknown): Promise<T> {
    return new Promise((resolve, reject) => {
      const task: WorkerTask = {
        id: this.generateId(),
        type,
        data,
        resolve,
        reject
      };
      
      const worker = this.availableWorkers.pop();
      
      if (worker) {
        this.executeTask(worker, task);
      } else {
        // Aucun worker disponible, ajouter à la file d'attente
        this.taskQueue.push(task);
      }
    });
  }
  
  /**
   * Exécute une tâche sur un worker
   */
  private executeTask(worker: Worker, task: WorkerTask): void {
    const message: WorkerMessage = {
      id: task.id,
      type: task.type as WorkerMessage['type'],
      data: task.data
    };
    
    worker.postMessage(message);
    
    // Stocker la tâche pour la résolution
    (worker as any).__currentTask = task;
  }
  
  /**
   * Gère les messages des workers
   */
  private handleWorkerMessage(worker: Worker, message: unknown): void {
    const task = (worker as any).__currentTask as WorkerTask;
    
    if (task && message.id === task.id) {
      if (message.status === 'completed') {
        task.resolve(message.result);
        this.releaseWorker(worker);
      } else if (message.status === 'error') {
        task.reject(new Error(message.error));
        this.releaseWorker(worker);
      } else if (message.status === 'progress') {
        // Progression - ne pas libérer le worker
        // Peut être géré par un callback si nécessaire
      }
    }
  }
  
  /**
   * Gère les erreurs des workers
   */
  private handleWorkerError(worker: Worker, error: ErrorEvent): void {
    const task = (worker as any).__currentTask as WorkerTask;
    
    if (task) {
      task.reject(new Error(error.message));
      delete (worker as any).__currentTask;
    }
    
    // Recréer le worker
    const index = this.workers.indexOf(worker);
    if (index !== -1) {
      worker.terminate();
      this.workers.splice(index, 1);
      
      try {
        const newWorker = new Worker(
          new URL('../../workers/processing.worker.ts', import.meta.url),
          { type: 'module' }
        );
        
        newWorker.onmessage = (event) => {
          this.handleWorkerMessage(newWorker, event.data);
        };
        
        newWorker.onerror = (error) => {
          this.handleWorkerError(newWorker, error);
        };
        
        this.workers.push(newWorker);
        this.availableWorkers.push(newWorker);
      } catch (error) {
        console.error('Failed to recreate worker:', error);
      }
    }
  }
  
  /**
   * Libère un worker et traite la prochaine tâche
   * Exigence: 10.6 - File d'attente de tâches
   */
  private releaseWorker(worker: Worker): void {
    delete (worker as any).__currentTask;
    
    // Traiter la prochaine tâche en attente
    const nextTask = this.taskQueue.shift();
    if (nextTask) {
      this.executeTask(worker, nextTask);
    } else {
      // Aucune tâche en attente, rendre le worker disponible
      this.availableWorkers.push(worker);
    }
  }
  
  /**
   * Annule toutes les tâches en cours
   * Exigence: 10.5 - Annulation de tâches
   */
  cancelAll(): void {
    // Vider la file d'attente
    for (const task of this.taskQueue) {
      task.reject(new Error('Task cancelled'));
    }
    this.taskQueue = [];
    
    // Annuler les tâches en cours
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task) {
        // Envoyer un message d'annulation au worker
        worker.postMessage({ id: task.id, type: 'cancel' });
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
      }
    }
    
    // Tous les workers sont maintenant disponibles
    this.availableWorkers = [...this.workers];
  }
  
  /**
   * Termine tous les workers
   */
  terminate(): void {
    this.cancelAll();
    
    for (const worker of this.workers) {
      worker.terminate();
    }
    
    this.workers = [];
    this.availableWorkers = [];
  }
  
  /**
   * Récupère le nombre de tâches en attente
   */
  getQueueSize(): number {
    return this.taskQueue.length;
  }
  
  /**
   * Récupère le nombre de workers disponibles
   */
  getAvailableWorkers(): number {
    return this.availableWorkers.length;
  }
  
  /**
   * Récupère le nombre de workers occupés
   */
  getBusyWorkers(): number {
    return this.workers.length - this.availableWorkers.length;
  }
  
  /**
   * Génère un ID unique
   */
  private generateId(): string {
    return `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * Character Event System
 * 
 * This module extends the event emitter with character-specific event types
 * and payload definitions for the Character Integration System.
 * 
 * Requirements: 5.4, 12.1, 12.2, 12.3, 12.4, 12.5
 */

import type { Character, CharacterRelationship } from '@/types/character';
import type { BaseEventPayload } from './eventEmitter';

// ============================================================================
// Character Event Types
// ============================================================================

/**
 * Character-specific event types for the Character Integration System
 */
export const CharacterEventType = {
  // Character CRUD events
  CHARACTER_CREATED: 'character:created',
  CHARACTER_UPDATED: 'character:updated',
  CHARACTER_DELETED: 'character:deleted',
  CHARACTER_SELECTED: 'character:selected',
  
  // Relationship events
  RELATIONSHIP_ADDED: 'character:relationship:added',
  RELATIONSHIP_UPDATED: 'character:relationship:updated',
  RELATIONSHIP_REMOVED: 'character:relationship:removed',
  
  // Validation events
  CHARACTER_VALIDATION_FAILED: 'character:validation:failed',
  CHARACTER_VALIDATION_PASSED: 'character:validation:passed',
  
  // Import/Export events
  CHARACTER_EXPORTED: 'character:exported',
  CHARACTER_IMPORTED: 'character:imported',
  CHARACTER_IMPORT_FAILED: 'character:import:failed',
  
  // Dependency events
  CHARACTER_DEPENDENCIES_CHECKED: 'character:dependencies:checked',
  CHARACTER_DELETION_BLOCKED: 'character:deletion:blocked',
} as const;

// ============================================================================
// Character Event Payload Interfaces
// ============================================================================

/**
 * Character creation event payload
 * Emitted when a new character is created through any means
 * 
 * Requirements: 3.4, 12.1
 */
export interface CharacterCreatedEventPayload extends BaseEventPayload {
  character: Character;
  source: 'wizard' | 'editor' | 'import' | 'api';
  projectName?: string;
}

/**
 * Character update event payload
 * Emitted when a character is modified
 * 
 * Requirements: 5.2, 12.2
 */
export interface CharacterUpdatedEventPayload extends BaseEventPayload {
  characterId: string;
  updates: Partial<Character>;
  previousCharacter?: Character;
  source: 'editor' | 'relationship-sync' | 'import' | 'api';
  changeType?: 'field-update' | 'relationship-sync' | 'bulk-update';
}

/**
 * Character deletion event payload
 * Emitted when a character is deleted
 * 
 * Requirements: 5.3, 12.3
 */
export interface CharacterDeletedEventPayload extends BaseEventPayload {
  characterId: string;
  characterName: string;
  dependencies?: {
    stories: Array<{ id: string; name: string }>;
    relationships: Array<{ characterId: string; characterName: string }>;
  };
  forced?: boolean; // Whether deletion was forced despite dependencies
}

/**
 * Character selection event payload
 * Emitted when a character is selected in the UI
 * 
 * Requirements: 4.2, 12.4
 */
export interface CharacterSelectedEventPayload extends BaseEventPayload {
  characterId: string;
  character: Character;
  context: 'story-generator' | 'editor' | 'list' | 'dashboard';
  multiSelect?: boolean;
  selectedIds?: string[]; // All currently selected character IDs
}

/**
 * Relationship added event payload
 * Emitted when a relationship is added between characters
 * 
 * Requirements: 6.1, 12.2
 */
export interface RelationshipAddedEventPayload extends BaseEventPayload {
  fromCharacterId: string;
  toCharacterId: string;
  relationship: CharacterRelationship;
  inverseRelationship: CharacterRelationship;
  bidirectional: boolean;
}

/**
 * Relationship updated event payload
 * Emitted when a relationship is modified
 * 
 * Requirements: 6.2, 12.2
 */
export interface RelationshipUpdatedEventPayload extends BaseEventPayload {
  fromCharacterId: string;
  toCharacterId: string;
  updates: Partial<CharacterRelationship>;
  previousRelationship: CharacterRelationship;
  bidirectional: boolean;
}

/**
 * Relationship removed event payload
 * Emitted when a relationship is deleted
 * 
 * Requirements: 6.3, 12.2
 */
export interface RelationshipRemovedEventPayload extends BaseEventPayload {
  fromCharacterId: string;
  toCharacterId: string;
  relationship: CharacterRelationship;
  bidirectional: boolean;
}

/**
 * Character validation failed event payload
 * Emitted when character validation fails
 * 
 * Requirements: 2.3, 2.4, 11.5
 */
export interface CharacterValidationFailedEventPayload extends BaseEventPayload {
  characterId?: string;
  characterData: Partial<Character>;
  errors: Record<string, string[]>;
  context: 'create' | 'update' | 'import';
}

/**
 * Character validation passed event payload
 * Emitted when character validation succeeds
 * 
 * Requirements: 2.3
 */
export interface CharacterValidationPassedEventPayload extends BaseEventPayload {
  characterId?: string;
  characterData: Partial<Character>;
  context: 'create' | 'update' | 'import';
}

/**
 * Character exported event payload
 * Emitted when a character is exported to JSON
 * 
 * Requirements: 10.2
 */
export interface CharacterExportedEventPayload extends BaseEventPayload {
  characterId: string;
  characterName: string;
  format: 'json';
  destination?: string; // File path or download
}

/**
 * Character imported event payload
 * Emitted when a character is successfully imported
 * 
 * Requirements: 10.4
 */
export interface CharacterImportedEventPayload extends BaseEventPayload {
  character: Character;
  sourceFile?: string;
  conflictResolution?: 'rename' | 'replace' | 'skip';
}

/**
 * Character import failed event payload
 * Emitted when character import fails
 * 
 * Requirements: 10.4, 10.5
 */
export interface CharacterImportFailedEventPayload extends BaseEventPayload {
  sourceFile?: string;
  error: string;
  validationErrors?: Record<string, string[]>;
  reason: 'invalid-json' | 'schema-mismatch' | 'duplicate-id' | 'validation-failed';
}

/**
 * Character dependencies checked event payload
 * Emitted when dependencies are checked for a character
 * 
 * Requirements: 7.1
 */
export interface CharacterDependenciesCheckedEventPayload extends BaseEventPayload {
  characterId: string;
  characterName: string;
  dependencies: {
    stories: Array<{ id: string; name: string }>;
    relationships: Array<{ characterId: string; characterName: string }>;
  };
  hasDependencies: boolean;
}

/**
 * Character deletion blocked event payload
 * Emitted when character deletion is blocked due to dependencies
 * 
 * Requirements: 7.2
 */
export interface CharacterDeletionBlockedEventPayload extends BaseEventPayload {
  characterId: string;
  characterName: string;
  dependencies: {
    stories: Array<{ id: string; name: string }>;
    relationships: Array<{ characterId: string; characterName: string }>;
  };
  userAction?: 'cancelled' | 'pending';
}

/**
 * Union type of all character event payloads
 */
export type CharacterEventPayload =
  | CharacterCreatedEventPayload
  | CharacterUpdatedEventPayload
  | CharacterDeletedEventPayload
  | CharacterSelectedEventPayload
  | RelationshipAddedEventPayload
  | RelationshipUpdatedEventPayload
  | RelationshipRemovedEventPayload
  | CharacterValidationFailedEventPayload
  | CharacterValidationPassedEventPayload
  | CharacterExportedEventPayload
  | CharacterImportedEventPayload
  | CharacterImportFailedEventPayload
  | CharacterDependenciesCheckedEventPayload
  | CharacterDeletionBlockedEventPayload;

// ============================================================================
// Type Guards
// ============================================================================

/**
 * Type guard to check if an event is a character event
 */
export function isCharacterEvent(eventType: string): boolean {
  return Object.values(CharacterEventType).includes(eventType as any);
}

/**
 * Type guard for character created event
 */
export function isCharacterCreatedEvent(
  payload: unknown
): payload is CharacterCreatedEventPayload {
  return !!payload && 'character' in payload && 'source' in payload;
}

/**
 * Type guard for character updated event
 */
export function isCharacterUpdatedEvent(
  payload: unknown
): payload is CharacterUpdatedEventPayload {
  return !!payload && 'characterId' in payload && 'updates' in payload;
}

/**
 * Type guard for character deleted event
 */
export function isCharacterDeletedEvent(
  payload: unknown
): payload is CharacterDeletedEventPayload {
  return !!payload && 'characterId' in payload && 'characterName' in payload;
}

// ============================================================================
// Event Helper Functions
// ============================================================================

/**
 * Create a character created event payload
 * 
 * @param character - The created character
 * @param source - The source of the creation
 * @param projectName - Optional project name
 * @returns Character created event payload
 */
export function createCharacterCreatedPayload(
  character: Character,
  source: CharacterCreatedEventPayload['source'],
  projectName?: string
): CharacterCreatedEventPayload {
  return {
    character,
    source,
    projectName,
    timestamp: new Date(),
  };
}

/**
 * Create a character updated event payload
 * 
 * @param characterId - The ID of the updated character
 * @param updates - The updates applied
 * @param source - The source of the update
 * @param previousCharacter - Optional previous character state
 * @returns Character updated event payload
 */
export function createCharacterUpdatedPayload(
  characterId: string,
  updates: Partial<Character>,
  source: CharacterUpdatedEventPayload['source'],
  previousCharacter?: Character
): CharacterUpdatedEventPayload {
  return {
    characterId,
    updates,
    previousCharacter,
    source,
    timestamp: new Date(),
  };
}

/**
 * Create a character deleted event payload
 * 
 * @param characterId - The ID of the deleted character
 * @param characterName - The name of the deleted character
 * @param dependencies - Optional dependencies information
 * @param forced - Whether deletion was forced
 * @returns Character deleted event payload
 */
export function createCharacterDeletedPayload(
  characterId: string,
  characterName: string,
  dependencies?: CharacterDeletedEventPayload['dependencies'],
  forced?: boolean
): CharacterDeletedEventPayload {
  return {
    characterId,
    characterName,
    dependencies,
    forced,
    timestamp: new Date(),
    source: 'character-manager',
  };
}

/**
 * Create a character selected event payload
 * 
 * @param character - The selected character
 * @param context - The context of the selection
 * @param multiSelect - Whether this is part of multi-select
 * @param selectedIds - All currently selected character IDs
 * @returns Character selected event payload
 */
export function createCharacterSelectedPayload(
  character: Character,
  context: CharacterSelectedEventPayload['context'],
  multiSelect?: boolean,
  selectedIds?: string[]
): CharacterSelectedEventPayload {
  return {
    characterId: character.character_id,
    character,
    context,
    multiSelect,
    selectedIds,
    timestamp: new Date(),
    source: `character-${context}`,
  };
}

/**
 * Create a relationship added event payload
 * 
 * @param fromCharacterId - The source character ID
 * @param toCharacterId - The target character ID
 * @param relationship - The relationship data
 * @param inverseRelationship - The inverse relationship data
 * @returns Relationship added event payload
 */
export function createRelationshipAddedPayload(
  fromCharacterId: string,
  toCharacterId: string,
  relationship: CharacterRelationship,
  inverseRelationship: CharacterRelationship
): RelationshipAddedEventPayload {
  return {
    fromCharacterId,
    toCharacterId,
    relationship,
    inverseRelationship,
    bidirectional: true,
    timestamp: new Date(),
    source: 'relationship-manager',
  };
}

/**
 * Create a validation failed event payload
 * 
 * @param characterData - The character data that failed validation
 * @param errors - The validation errors
 * @param context - The context of the validation
 * @param characterId - Optional character ID
 * @returns Validation failed event payload
 */
export function createValidationFailedPayload(
  characterData: Partial<Character>,
  errors: Record<string, string[]>,
  context: CharacterValidationFailedEventPayload['context'],
  characterId?: string
): CharacterValidationFailedEventPayload {
  return {
    characterId,
    characterData,
    errors,
    context,
    timestamp: new Date(),
    source: 'character-validator',
  };
}

/**
 * Create a dependencies checked event payload
 * 
 * @param characterId - The character ID
 * @param characterName - The character name
 * @param dependencies - The dependencies found
 * @returns Dependencies checked event payload
 */
export function createDependenciesCheckedPayload(
  characterId: string,
  characterName: string,
  dependencies: CharacterDependenciesCheckedEventPayload['dependencies']
): CharacterDependenciesCheckedEventPayload {
  return {
    characterId,
    characterName,
    dependencies,
    hasDependencies: dependencies.stories.length > 0 || dependencies.relationships.length > 0,
    timestamp: new Date(),
    source: 'dependency-checker',
  };
}

