   */
  /**
   * Handle character creation request
   */
  private async handleCreateCharacter(input: string, llmService?: any, language: LanguageCode = 'fr'): Promise<ChatResponse> {
    const nameMatch = input.match(/(?:appelé|nommé|named|called)\s+["']?([^"',;.]+)["']?/i)
      || input.match(/["']([^"']+)["']/);
    let name = nameMatch ? nameMatch[1].trim() : undefined;

    let description = '';
    let generatedPrompts: string[] = [];
    let gender = '';
    let archetype = '';

    // Generate details using LLM if available
    if (llmService && typeof llmService.generateCompletion === 'function') {
      try {
        const workingContext = useMemoryStore.getState().workingContext;
        const prompt = `Generate a detailed character profile based on this request: "${input}". 
        
        [LIVING PROJECT PROTOCOL]
        ${workingContext}

        Provide a JSON response with the following fields:
        {
          "name": "A creative name (if not provided)",
          "archetype": "The character's role (e.g. Hero, Villain, Mentor)",
          "gender": "male/female/neutral",
          "description": "Short description (2-3 sentences)",
          "visual_prompts": ["3 descriptive prompts for image generation"]
        }`;

        const response = await llmService.generateCompletion({
          prompt,
          maxTokens: 500,
          temperature: 0.8,
        });

        if (response.success && response.data) {
          try {
            // Attempt to parse JSON from response
            const jsonMatch = response.data.content.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
              const data = JSON.parse(jsonMatch[0]);
              description = data.description || '';
              archetype = data.archetype || '';
              gender = data.gender || '';
              generatedPrompts = data.visual_prompts || [];
              if (!name) name = data.name; // Use generated name if not provided
            } else {
              // Fallback if no JSON found
              description = response.data.content;
            }
          } catch (e) {
            console.warn('Failed to parse LLM character generation response', e);
            description = response.data.content;
          }

          // Total Recall: Analyze for memory
          const { projectMemory } = await import('@/services/ProjectMemoryService');
          projectMemory.analyzeForMemory(description, 'Character Concept Analysis');
        }
      } catch (error) {
        console.error('Error generating character details:', error);
      }
    }

    return {
      message: name
        ? `I'll create the character "${name}". ${description ? `\n\n${description}` : "I'll generate their appearance, personality, and backstory automatically."}`
        : `I'll create a new character for you. ${description ? `\n\n${description}` : "What would you like to know about them? I can generate all the details automatically."}`,
      suggestions: [
        'Create a warrior character',
        'Create a female mage named Aria',
        'Create a mysterious antagonist',
      ],
      actions: [{
        type: 'createCharacter',
        payload: {
          name,
          rawInput: input,
          description,
          archetype,
          gender,
          prompts: generatedPrompts
        },
      }],
    };
  }

