   */
  validateCharacterConsistency(shotId: string): ConsistencyIssue[] {
    const timer = getPerformanceMonitoringService().createTimer('validateCharacterConsistency');
    
    const issues: ConsistencyIssue[] = [];
    
    if (!this.projectStore) {
      return issues;
