      if (inconsistency) {
        issues.push(inconsistency);
      }
    }

    const duration = timer.stop({ shotId, characterCount: shot.characterReferences.length });
    getPerformanceMonitoringService().trackConsistencyCheck(1, duration);

    return issues;
