/**
 * Media Search Service - Frontend for Media Intelligence
 * Natural language multimedia asset search
 */

import { backendApiService } from './backendApiService';
import { logger } from '@/utils/logger';

export type AssetType = 'image' | 'video' | 'audio' | 'text';
export type SearchMode = 'semantic' | 'keyword' | 'hybrid' | 'similarity';

export interface AssetMetadata {
  assetId: string;
  assetType: AssetType;
  filePath: string;
  fileName: string;
  fileSize: number;
  createdAt: string;
  updatedAt: string;
  projectId: string;
  tags: string[];
  description: string;
  duration?: number;
  resolution?: { width: number; height: number };
  thumbnailUrl?: string;
}

export interface SearchResult {
  assetId: string;
  assetType: AssetType;
  filePath: string;
  fileName: string;
  similarityScore: number;
  matchType: 'semantic' | 'keyword' | 'hybrid';
  highlightedText?: string;
  previewUrl?: string;
  metadata: Record<string, unknown>;
}

export interface SearchRequest {
  query: string;
  projectId?: string;
  assetTypes?: AssetType[];
  searchMode?: SearchMode;
  limit?: number;
  similarityThreshold?: number;
}

export interface IndexStats {
  totalAssets: number;
  indexedAssets: number;
  indexSizeMb: number;
  lastIndexed?: string;
  assetTypeCounts: Record<string, number>;
}

export interface MediaSearchService {
  search(request: SearchRequest): Promise<SearchResult[]>;
  indexProject(projectId: string): Promise<{ indexedAssets: number; durationSeconds: number }>;
  addAsset(filePath: string, projectId: string, tags?: string[], description?: string): Promise<string>;
  removeAsset(assetId: string): Promise<boolean>;
  getAssetMetadata(assetId: string): Promise<AssetMetadata | null>;
  getIndexStats(): Promise<IndexStats>;
}

class MediaSearchServiceImpl implements MediaSearchService {
  private baseUrl = '/api/v1/media';
  private cache: Map<string, { results: SearchResult[]; timestamp: number }> = new Map();
  private cacheTTL = 10 * 60 * 1000; // 10 minutes

  async search(request: SearchRequest): Promise<SearchResult[]> {
    const cacheKey = `${request.query}:${request.projectId}:${request.searchMode}`;
    const cached = this.cache.get(cacheKey);
    
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      logger.debug(`[MediaSearch] Cache hit for: ${request.query}`);
      return cached.results;
    }

    try {
      const response = await backendApiService.post<{ results: SearchResult[] }>(
        `${this.baseUrl}/search`,
        request
      );

      // Cache the results
      this.cache.set(cacheKey, {
        results: response.results,
        timestamp: Date.now()
      });

      return response.results;
    } catch (error) {
      logger.error('[MediaSearch] Search failed:', error);
      // Fallback: basic local search
      return this.localSearchFallback(request);
    }
  }

  async indexProject(projectId: string): Promise<{ indexedAssets: number; durationSeconds: number }> {
    try {
      const response = await backendApiService.post<{
        projectId: string;
        indexedAssets: number;
        durationSeconds: number;
        errors: string[];
      }>(`${this.baseUrl}/index`, { projectId });

      logger.debug(`[MediaSearch] Indexed ${response.indexedAssets} assets for project ${projectId}`);
      return {
        indexedAssets: response.indexedAssets,
        durationSeconds: response.durationSeconds
      };
    } catch (error) {
      logger.error('[MediaSearch] Indexing failed:', error);
      throw error;
    }
  }

  async addAsset(
    filePath: string,
    projectId: string,
    tags?: string[],
    description?: string
  ): Promise<string> {
    try {
      const response = await backendApiService.post<{ assetId: string }>(
        `${this.baseUrl}/add`,
        { filePath, projectId, tags, description }
      );

      // Invalidate cache
      this.cache.clear();

      return response.assetId;
    } catch (error) {
      logger.error('[MediaSearch] Add asset failed:', error);
      throw error;
    }
  }

  async removeAsset(assetId: string): Promise<boolean> {
    try {
      await backendApiService.delete(`${this.baseUrl}/${assetId}`);
      
      // Invalidate cache
      this.cache.clear();

      return true;
    } catch (error) {
      logger.error('[MediaSearch] Remove asset failed:', error);
      return false;
    }
  }

  async getAssetMetadata(assetId: string): Promise<AssetMetadata | null> {
    try {
      return await backendApiService.get<AssetMetadata>(`${this.baseUrl}/${assetId}`);
    } catch (error) {
      logger.error('[MediaSearch] Get metadata failed:', error);
      return null;
    }
  }

  async getIndexStats(): Promise<IndexStats> {
    try {
      return await backendApiService.get<IndexStats>(`${this.baseUrl}/stats`);
    } catch (error) {
      logger.error('[MediaSearch] Get stats failed:', error);
      return {
        totalAssets: 0,
        indexedAssets: 0,
        indexSizeMb: 0,
        assetTypeCounts: {}
      };
    }
  }

  /**
   * Basic local search (fallback)
   */
  private async localSearchFallback(request: SearchRequest): Promise<SearchResult[]> {
    // Simple keyword search implementation
    const queryWords = request.query.toLowerCase().split(' ');
    
    //TODO: Integrate with existing asset system
    logger.debug('[MediaSearch] Using local fallback search');
    
    return [];
  }

  /**
   * Clear the cache
   */
  clearCache(): void {
    this.cache.clear();
  }
}

export const mediaSearchService = new MediaSearchServiceImpl();

/**
 * Menu State Manager
 * 
 * Manages menu bar state including open/close logic, item focus,
 * navigation, and state change subscriptions.
 * 
 * Requirements: 8.1-8.6
 */

import {
  MenuBarState,
  StateListener,
  DEFAULT_MENU_BAR_STATE,
} from '../../types/menuBarState';

/**
 * MenuStateManager class
 * 
 * Centralized state management for menu bar UI.
 * Provides methods for menu operations and state subscriptions.
 */
export class MenuStateManager {
  private state: MenuBarState;
  private listeners: Set<StateListener<MenuBarState>>;

  constructor(initialState?: Partial<MenuBarState>) {
    this.state = {
      ...DEFAULT_MENU_BAR_STATE,
      ...initialState,
      // Ensure activeModals is a Set
      activeModals: new Set(initialState?.activeModals || []),
    };
    this.listeners = new Set();
  }

  /**
   * Get current menu bar state
   * Returns a deep copy to prevent external mutations
   */
  getState(): MenuBarState {
    return {
      ...this.state,
      activeModals: new Set(this.state.activeModals),
      recentProjects: [...this.state.recentProjects],
    };
  }

  /**
   * Update menu bar state
   * Merges partial updates and notifies listeners
   */
  setState(updates: Partial<MenuBarState>): void {
    const previousState = this.getState();
    
    this.state = {
      ...this.state,
      ...updates,
      // Handle Set properly
      activeModals: updates.activeModals
        ? new Set(updates.activeModals)
        : this.state.activeModals,
      // Handle array properly
      recentProjects: updates.recentProjects
        ? [...updates.recentProjects]
        : this.state.recentProjects,
    };

    // Notify all listeners of state change
    this.notifyListeners();
  }

  /**
   * Open a menu by ID
   * Closes any currently open menu first
   */
  openMenu(menuId: string): void {
    this.setState({
      openMenu: menuId,
      focusedItemIndex: 0, // Focus first item when opening
    });
  }

  /**
   * Close the currently open menu
   * Resets focused item index
   */
  closeMenu(): void {
    this.setState({
      openMenu: null,
      focusedItemIndex: -1,
    });
  }

  /**
   * Toggle menu open/close state
   */
  toggleMenu(menuId: string): void {
    if (this.state.openMenu === menuId) {
      this.closeMenu();
    } else {
      this.openMenu(menuId);
    }
  }

  /**
   * Check if a specific menu is open
   */
  isMenuOpen(menuId: string): boolean {
    return this.state.openMenu === menuId;
  }

  /**
   * Focus a menu item by index
   * Clamps index to valid range
   */
  focusItem(index: number): void {
    this.setState({
      focusedItemIndex: Math.max(-1, index),
    });
  }

  /**
   * Navigate to next menu item
   * Wraps around to first item if at end
   */
  navigateNext(itemCount: number): void {
    if (itemCount === 0) return;

    const currentIndex = this.state.focusedItemIndex;
    const nextIndex = currentIndex >= itemCount - 1 ? 0 : currentIndex + 1;
    
    this.focusItem(nextIndex);
  }

  /**
   * Navigate to previous menu item
   * Wraps around to last item if at beginning
   */
  navigatePrevious(itemCount: number): void {
    if (itemCount === 0) return;

    const currentIndex = this.state.focusedItemIndex;
    const previousIndex = currentIndex <= 0 ? itemCount - 1 : currentIndex - 1;
    
    this.focusItem(previousIndex);
  }

  /**
   * Navigate menu items in specified direction
   */
  navigateItems(direction: 'next' | 'previous', itemCount: number): void {
    if (direction === 'next') {
      this.navigateNext(itemCount);
    } else {
      this.navigatePrevious(itemCount);
    }
  }

  /**
   * Navigate to first menu item
   */
  navigateFirst(): void {
    this.focusItem(0);
  }

  /**
   * Navigate to last menu item
   */
  navigateLast(itemCount: number): void {
    if (itemCount > 0) {
      this.focusItem(itemCount - 1);
    }
  }

  /**
   * Open a modal by ID
   */
  openModal(modalId: string): void {
    const activeModals = new Set(this.state.activeModals);
    activeModals.add(modalId);
    
    this.setState({
      activeModals,
    });
  }

  /**
   * Close a modal by ID
   */
  closeModal(modalId: string): void {
    const activeModals = new Set(this.state.activeModals);
    activeModals.delete(modalId);
    
    this.setState({
      activeModals,
    });
  }

  /**
   * Close all modals
   */
  closeAllModals(): void {
    this.setState({
      activeModals: new Set(),
    });
  }

  /**
   * Check if a modal is open
   */
  isModalOpen(modalId: string): boolean {
    return this.state.activeModals.has(modalId);
  }

  /**
   * Check if any modal is open
   */
  hasOpenModals(): boolean {
    return this.state.activeModals.size > 0;
  }

  /**
   * Add a recent project to the list
   * Maintains max 10 entries, removes oldest if exceeded
   */
  addRecentProject(project: {
    id: string;
    name: string;
    path: string;
    lastModified: Date;
    thumbnail?: string;
  }): void {
    const recentProjects = [...this.state.recentProjects];
    
    // Remove existing entry with same ID if present
    const existingIndex = recentProjects.findIndex(p => p.id === project.id);
    if (existingIndex !== -1) {
      recentProjects.splice(existingIndex, 1);
    }
    
    // Add new entry at the beginning
    recentProjects.unshift(project);
    
    // Keep only the 10 most recent
    if (recentProjects.length > 10) {
      recentProjects.splice(10);
    }
    
    this.setState({
      recentProjects,
    });
  }

  /**
   * Remove a recent project from the list
   */
  removeRecentProject(projectId: string): void {
    const recentProjects = this.state.recentProjects.filter(
      p => p.id !== projectId
    );
    
    this.setState({
      recentProjects,
    });
  }

  /**
   * Clear all recent projects
   */
  clearRecentProjects(): void {
    this.setState({
      recentProjects: [],
    });
  }

  /**
   * Subscribe to state changes
   * Returns unsubscribe function
   */
  subscribe(listener: StateListener<MenuBarState>): () => void {
    this.listeners.add(listener);
    
    // Return unsubscribe function
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Notify all listeners of state change
   */
  private notifyListeners(): void {
    const currentState = this.getState();
    
    this.listeners.forEach(listener => {
      try {
        listener(currentState);
      } catch (error) {
        console.error('Error in state listener:', error);
      }
    });
  }

  /**
   * Reset state to default values
   */
  reset(): void {
    this.state = {
      ...DEFAULT_MENU_BAR_STATE,
      activeModals: new Set(),
    };
    this.notifyListeners();
  }

  /**
   * Get number of active listeners
   * Useful for debugging and testing
   */
  getListenerCount(): number {
    return this.listeners.size;
  }
}

/**
 * Create a new MenuStateManager instance
 */
export function createMenuStateManager(
  initialState?: Partial<MenuBarState>
): MenuStateManager {
  return new MenuStateManager(initialState);
}

/**
 * ModalManager - Centralized modal management for menu bar
 * 
 * Manages modal lifecycle including:
 * - Modal registration and component mapping
 * - Opening and closing modals
 * - Tracking active modals
 * - Passing props to modal components
 * 
 * Requirements: 1.1, 1.4, 1.5, 2.10, 6.2, 6.3
 */

import React from 'react';

export interface ModalConfig {
  id: string;
  component: React.ComponentType<any>;
  props?: Record<string, unknown>;
}

export interface ModalState {
  id: string;
  props?: Record<string, unknown>;
}

type ModalListener = (activeModals: Set<string>) => void;

/**
 * ModalManager class
 * 
 * Provides centralized modal management with:
 * - Registration of modal components
 * - Opening/closing modals with props
 * - Tracking active modals
 * - State change notifications
 */
export class ModalManager {
  private modalComponents: Map<string, React.ComponentType<any>>;
  private activeModals: Map<string, ModalState>;
  private listeners: Set<ModalListener>;

  constructor() {
    this.modalComponents = new Map();
    this.activeModals = new Map();
    this.listeners = new Set();
  }

  /**
   * Register a modal component
   * 
   * @param id - Unique identifier for the modal
   * @param component - React component to render
   */
  registerModal(id: string, component: React.ComponentType<any>): void {
    this.modalComponents.set(id, component);
  }

  /**
   * Unregister a modal component
   * 
   * @param id - Modal identifier to unregister
   */
  unregisterModal(id: string): void {
    this.modalComponents.delete(id);
    this.activeModals.delete(id);
    this.notifyListeners();
  }

  /**
   * Open a modal
   * 
   * @param id - Modal identifier
   * @param props - Props to pass to the modal component
   * @throws Error if modal is not registered
   */
  openModal(id: string, props?: Record<string, unknown>): void {
    if (!this.modalComponents.has(id)) {
      throw new Error(`Modal "${id}" is not registered`);
    }

    this.activeModals.set(id, { id, props });
    this.notifyListeners();
  }

  /**
   * Close a modal
   * 
   * @param id - Modal identifier to close
   */
  closeModal(id: string): void {
    this.activeModals.delete(id);
    this.notifyListeners();
  }

  /**
   * Close all modals
   */
  closeAll(): void {
    this.activeModals.clear();
    this.notifyListeners();
  }

  /**
   * Check if a modal is open
   * 
   * @param id - Modal identifier
   * @returns true if modal is open
   */
  isOpen(id: string): boolean {
    return this.activeModals.has(id);
  }

  /**
   * Get all active modal IDs
   * 
   * @returns Set of active modal IDs
   */
  getActiveModals(): Set<string> {
    return new Set(this.activeModals.keys());
  }

  /**
   * Get modal component by ID
   * 
   * @param id - Modal identifier
   * @returns Modal component or undefined
   */
  getModalComponent(id: string): React.ComponentType<any> | undefined {
    return this.modalComponents.get(id);
  }

  /**
   * Get modal state (props) by ID
   * 
   * @param id - Modal identifier
   * @returns Modal state or undefined
   */
  getModalState(id: string): ModalState | undefined {
    return this.activeModals.get(id);
  }

  /**
   * Subscribe to modal state changes
   * 
   * @param listener - Callback function
   * @returns Unsubscribe function
   */
  subscribe(listener: ModalListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Notify all listeners of state changes
   */
  private notifyListeners(): void {
    const activeModalIds = this.getActiveModals();
    this.listeners.forEach(listener => listener(activeModalIds));
  }

  /**
   * Get all registered modal IDs
   * 
   * @returns Array of registered modal IDs
   */
  getRegisteredModals(): string[] {
    return Array.from(this.modalComponents.keys());
  }

  /**
   * Clear all registrations and active modals
   * Useful for cleanup or testing
   */
  reset(): void {
    this.modalComponents.clear();
    this.activeModals.clear();
    this.listeners.clear();
  }
}

// Singleton instance for global use
export const modalManager = new ModalManager();

/**
 * Performance Monitoring Service
 * Tracks performance metrics for Continuous Creation feature
 * 
 * Features:
 * - Operation timing with performance.now()
 * - Memory usage tracking
 * - Custom metrics for reference inheritance, video replication, consistency checks
 * - Optional monitoring (can be disabled in production)
 */

import { v4 as uuidv4 } from 'uuid';

// ============================================================================
// Configuration
// ============================================================================

export interface PerformanceMonitoringConfig {
  enabled: boolean;
  maxHistoryEntries: number;
  sampleRate: number; // 0-1, for sampling expensive operations
  memoryTrackingInterval: number; // ms
}

const DEFAULT_CONFIG: PerformanceMonitoringConfig = {
  enabled: true,
  maxHistoryEntries: 1000,
  sampleRate: 1.0,
  memoryTrackingInterval: 5000,
};

// ============================================================================
// Types
// ============================================================================

export interface TimingEntry {
  id: string;
  operation: string;
  startTime: number;
  endTime?: number;
  duration?: number;
  metadata?: Record<string, unknown>;
}

export interface MemorySnapshot {
  timestamp: number;
  heapUsed: number;
  heapTotal: number;
  external: number;
}

export interface InheritanceMetric {
  depth: number;
  duration: number;
  timestamp: number;
}

export interface ReplicationMetric {
  progress: number; // 0-100
  duration: number;
  timestamp: number;
}

export interface ConsistencyMetric {
  shotCount: number;
  duration: number;
  timestamp: number;
}

export interface PerformanceReport {
  summary: {
    totalOperations: number;
    averageDuration: number;
    p50Duration: number;
    p95Duration: number;
    p99Duration: number;
  };
  memory: {
    currentHeapUsed: number;
    peakHeapUsed: number;
    averageHeapUsed: number;
  };
  inheritance: {
    totalInheritances: number;
    averageDepth: number;
    maxDepth: number;
    averageDuration: number;
  };
  replication: {
    totalReplications: number;
    averageProgressRate: number;
    averageDuration: number;
  };
  consistency: {
    totalChecks: number;
    averageDuration: number;
    averageShotCount: number;
  };
  recentOperations: TimingEntry[];
}

export interface PerformanceMetric {
  type: 'timer' | 'memory' | 'inheritance' | 'replication' | 'consistency' | 'cache';
  operation: string;
  value: number;
  metadata?: Record<string, unknown>;
  timestamp: number;
}

// ============================================================================
// Performance Monitoring Service
// ============================================================================

export class PerformanceMonitoringService {
  private config: PerformanceMonitoringConfig;
  private activeTimers: Map<string, TimingEntry> = new Map();
  private timingHistory: TimingEntry[] = [];
  private memorySnapshots: MemorySnapshot[] = [];
  private inheritanceMetrics: InheritanceMetric[] = [];
  private replicationMetrics: ReplicationMetric[] = [];
  private consistencyMetrics: ConsistencyMetric[] = [];
  private customMetrics: PerformanceMetric[] = [];
  private memoryTrackingInterval: ReturnType<typeof setInterval> | null = null;
  private enabled: boolean = true;

  constructor(config: Partial<PerformanceMonitoringConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.enabled = this.config.enabled;

    if (this.enabled && typeof window !== 'undefined') {
      this.startMemoryTracking();
    }
  }

  // ============================================================================
  // Timer Operations
  // ============================================================================

  /**
   * Start tracking an operation
   * @param operationId - Unique identifier for the operation
   * @param operation - Name of the operation
   * @param metadata - Optional metadata
   */
  startTimer(operationId: string, operation: string, metadata?: Record<string, unknown>): void {
    if (!this.enabled) return;

    const entry: TimingEntry = {
      id: operationId,
      operation,
      startTime: performance.now(),
      metadata,
    };

    this.activeTimers.set(operationId, entry);
  }

  /**
   * End tracking an operation and return duration
   * @param operationId - The operation identifier
   * @param additionalMetadata - Optional additional metadata
   * @returns Duration in milliseconds
   */
  endTimer(operationId: string, additionalMetadata?: Record<string, unknown>): number {
    if (!this.enabled) return 0;

    const entry = this.activeTimers.get(operationId);
    if (!entry) {
      console.warn(`[PerformanceMonitoring] No active timer found for: ${operationId}`);
      return 0;
    }

    const endTime = performance.now();
    const duration = endTime - entry.startTime;

    const completedEntry: TimingEntry = {
      ...entry,
      endTime,
      duration,
      metadata: { ...entry.metadata, ...additionalMetadata },
    };

    // Remove from active timers
    this.activeTimers.delete(operationId);

    // Add to history
    this.timingHistory.push(completedEntry);

    // Trim history if needed
    if (this.timingHistory.length > this.config.maxHistoryEntries) {
      this.timingHistory = this.timingHistory.slice(-this.config.maxHistoryEntries);
    }

    return duration;
  }

  /**
   * Create a timer context manager for TypeScript
   * @param operation - Name of the operation
   * @returns Timer object with stop method
   */
  createTimer(operation: string): { stop: (metadata?: Record<string, unknown>) => number } {
    const id = uuidv4();
    this.startTimer(id, operation);

    return {
      stop: (metadata?: Record<string, unknown>): number => {
        return this.endTimer(id, metadata);
      },
    };
  }

  /**
   * Measure execution time of a function
   * @param operation - Name of the operation
   * @param fn - Function to measure
   * @param metadata - Optional metadata
   * @returns Result of the function and duration
   */
  async measure<T>(
    operation: string,
    fn: () => T | Promise<T>,
    metadata?: Record<string, unknown>
  ): Promise<{ result: T; duration: number }> {
    const timer = this.createTimer(operation);
    const startMemory = this.getMemoryUsage();

    try {
      const result = await fn();
      const duration = timer.stop({ ...metadata, success: true });

      return { result, duration };
    } catch (error) {
      timer.stop({ ...metadata, success: false, error: String(error) });
      throw error;
    }
  }

  // ============================================================================
  // Memory Tracking
  // ============================================================================

  /**
   * Track heap memory usage
   * @returns Current memory snapshot or null if unavailable
   */
  trackMemoryUsage(): MemorySnapshot | null {
    if (typeof window === 'undefined') return null;

    const perf = window.performance as unknown as { memory?: { usedJSHeapSize: number; totalJSHeapSize: number; jsHeapSizeLimit: number } };
    if (!perf.memory) return null;

    const memory = perf.memory;

    const snapshot: MemorySnapshot = {
      timestamp: Date.now(),
      heapUsed: memory.usedJSHeapSize,
      heapTotal: memory.totalJSHeapSize,
      external: 0, // Not available in Chrome performance.memory
    };

    this.memorySnapshots.push(snapshot);

    // Trim history
    if (this.memorySnapshots.length > this.config.maxHistoryEntries) {
      this.memorySnapshots = this.memorySnapshots.slice(-this.config.maxHistoryEntries);
    }

    return snapshot;
  }

  /**
   * Get current memory usage
   * @returns Current memory snapshot or null
   */
  getMemoryUsage(): MemorySnapshot | null {
    return this.trackMemoryUsage();
  }

  /**
   * Start periodic memory tracking
   */
  private startMemoryTracking(): void {
    if (this.memoryTrackingInterval) {
      clearInterval(this.memoryTrackingInterval);
    }

    this.memoryTrackingInterval = setInterval(() => {
      this.trackMemoryUsage();
    }, this.config.memoryTrackingInterval);
  }

  /**
   * Stop periodic memory tracking
   */
  stopMemoryTracking(): void {
    if (this.memoryTrackingInterval) {
      clearInterval(this.memoryTrackingInterval);
      this.memoryTrackingInterval = null;
    }
  }

  // ============================================================================
  // Custom Metrics
  // ============================================================================

  /**
   * Track reference inheritance performance
   * @param depth - Inheritance depth (1 = direct, 2 = parent, etc.)
   * @param duration - Duration in milliseconds
   */
  trackReferenceInheritance(depth: number, duration: number): void {
    if (!this.enabled) return;

    const metric: InheritanceMetric = {
      depth,
      duration,
      timestamp: Date.now(),
    };

    this.inheritanceMetrics.push(metric);

    // Trim history
    if (this.inheritanceMetrics.length > this.config.maxHistoryEntries) {
      this.inheritanceMetrics = this.inheritanceMetrics.slice(-this.config.maxHistoryEntries);
    }

    // Also track as custom metric
    this.customMetrics.push({
      type: 'inheritance',
      operation: 'referenceInheritance',
      value: duration,
      metadata: { depth },
      timestamp: Date.now(),
    });
  }

  /**
   * Track video replication progress
   * @param progress - Progress percentage (0-100)
   * @param duration - Duration in milliseconds
   */
  trackVideoReplication(progress: number, duration: number): void {
    if (!this.enabled) return;

    const metric: ReplicationMetric = {
      progress,
      duration,
      timestamp: Date.now(),
    };

    this.replicationMetrics.push(metric);

    // Trim history
    if (this.replicationMetrics.length > this.config.maxHistoryEntries) {
      this.replicationMetrics = this.replicationMetrics.slice(-this.config.maxHistoryEntries);
    }

    // Also track as custom metric
    this.customMetrics.push({
      type: 'replication',
      operation: 'videoReplication',
      value: progress,
      metadata: { duration },
      timestamp: Date.now(),
    });
  }

  /**
   * Track visual consistency check time
   * @param shotCount - Number of shots checked
   * @param duration - Duration in milliseconds
   */
  trackConsistencyCheck(shotCount: number, duration: number): void {
    if (!this.enabled) return;

    const metric: ConsistencyMetric = {
      shotCount,
      duration,
      timestamp: Date.now(),
    };

    this.consistencyMetrics.push(metric);

    // Trim history
    if (this.consistencyMetrics.length > this.config.maxHistoryEntries) {
      this.consistencyMetrics = this.consistencyMetrics.slice(-this.config.maxHistoryEntries);
    }

    // Also track as custom metric
    this.customMetrics.push({
      type: 'consistency',
      operation: 'consistencyCheck',
      value: duration,
      metadata: { shotCount },
      timestamp: Date.now(),
    });
  }

  /**
   * Track a custom metric
   * @param type - Metric type
   * @param operation - Operation name
   * @param value - Metric value
   * @param metadata - Optional metadata
   */
  trackCustomMetric(
    type: PerformanceMetric['type'],
    operation: string,
    value: number,
    metadata?: Record<string, unknown>
  ): void {
    if (!this.enabled) return;

    this.customMetrics.push({
      type,
      operation,
      value,
      metadata,
      timestamp: Date.now(),
    });

    // Trim history
    if (this.customMetrics.length > this.config.maxHistoryEntries) {
      this.customMetrics = this.customMetrics.slice(-this.config.maxHistoryEntries);
    }
  }

  // ============================================================================
  // Report Generation
  // ============================================================================

  /**
   * Generate performance report
   * @returns Comprehensive performance report
   */
  getPerformanceReport(): PerformanceReport {
    const durations = this.timingHistory
      .filter(e => e.duration !== undefined)
      .map(e => e.duration as number);

    const sortedDurations = [...durations].sort((a, b) => a - b);

    const calculatePercentile = (p: number): number => {
      if (sortedDurations.length === 0) return 0;
      const index = Math.floor(sortedDurations.length * p);
      return sortedDurations[Math.min(index, sortedDurations.length - 1)];
    };

    // Memory stats
    const memoryUsages = this.memorySnapshots.map(m => m.heapUsed);

    // Inheritance stats
    const avgDepth = this.inheritanceMetrics.length > 0
      ? this.inheritanceMetrics.reduce((sum, m) => sum + m.depth, 0) / this.inheritanceMetrics.length
      : 0;
    const maxDepth = this.inheritanceMetrics.length > 0
      ? Math.max(...this.inheritanceMetrics.map(m => m.depth))
      : 0;
    const avgInheritanceDuration = this.inheritanceMetrics.length > 0
      ? this.inheritanceMetrics.reduce((sum, m) => sum + m.duration, 0) / this.inheritanceMetrics.length
      : 0;

    // Replication stats
    const avgReplicationDuration = this.replicationMetrics.length > 0
      ? this.replicationMetrics.reduce((sum, m) => sum + m.duration, 0) / this.replicationMetrics.length
      : 0;

    // Consistency stats
    const avgConsistencyDuration = this.consistencyMetrics.length > 0
      ? this.consistencyMetrics.reduce((sum, m) => sum + m.duration, 0) / this.consistencyMetrics.length
      : 0;
    const avgShotCount = this.consistencyMetrics.length > 0
      ? this.consistencyMetrics.reduce((sum, m) => sum + m.shotCount, 0) / this.consistencyMetrics.length
      : 0;

    return {
      summary: {
        totalOperations: this.timingHistory.length,
        averageDuration: durations.length > 0 ? durations.reduce((a, b) => a + b, 0) / durations.length : 0,
        p50Duration: calculatePercentile(0.5),
        p95Duration: calculatePercentile(0.95),
        p99Duration: calculatePercentile(0.99),
      },
      memory: {
        currentHeapUsed: memoryUsages.length > 0 ? memoryUsages[memoryUsages.length - 1] : 0,
        peakHeapUsed: memoryUsages.length > 0 ? Math.max(...memoryUsages) : 0,
        averageHeapUsed: memoryUsages.length > 0 ? memoryUsages.reduce((a, b) => a + b, 0) / memoryUsages.length : 0,
      },
      inheritance: {
        totalInheritances: this.inheritanceMetrics.length,
        averageDepth: avgDepth,
        maxDepth: maxDepth,
        averageDuration: avgInheritanceDuration,
      },
      replication: {
        totalReplications: this.replicationMetrics.length,
        averageProgressRate: this.replicationMetrics.length > 0
          ? this.replicationMetrics.reduce((sum, m) => sum + m.progress, 0) / this.replicationMetrics.length
          : 0,
        averageDuration: avgReplicationDuration,
      },
      consistency: {
        totalChecks: this.consistencyMetrics.length,
        averageDuration: avgConsistencyDuration,
        averageShotCount: avgShotCount,
      },
      recentOperations: this.timingHistory.slice(-50),
    };
  }

  /**
   * Get raw timing history
   * @returns Array of timing entries
   */
  getTimingHistory(): TimingEntry[] {
    return [...this.timingHistory];
  }

  /**
   * Get memory snapshots
   * @returns Array of memory snapshots
   */
  getMemorySnapshots(): MemorySnapshot[] {
    return [...this.memorySnapshots];
  }

  /**
   * Get inheritance metrics
   * @returns Array of inheritance metrics
   */
  getInheritanceMetrics(): InheritanceMetric[] {
    return [...this.inheritanceMetrics];
  }

  /**
   * Get replication metrics
   * @returns Array of replication metrics
   */
  getReplicationMetrics(): ReplicationMetric[] {
    return [...this.replicationMetrics];
  }

  /**
   * Get consistency metrics
   * @returns Array of consistency metrics
   */
  getConsistencyMetrics(): ConsistencyMetric[] {
    return [...this.consistencyMetrics];
  }

  /**
   * Get custom metrics
   * @returns Array of custom metrics
   */
  getCustomMetrics(): PerformanceMetric[] {
    return [...this.customMetrics];
  }

  // ============================================================================
  // Service Management
  // ============================================================================

  /**
   * Enable or disable monitoring
   * @param enabled - Whether monitoring should be enabled
   */
  setEnabled(enabled: boolean): void {
    this.enabled = enabled;

    if (enabled) {
      this.startMemoryTracking();
    } else {
      this.stopMemoryTracking();
    }
  }

  /**
   * Check if monitoring is enabled
   * @returns Whether monitoring is enabled
   */
  isEnabled(): boolean {
    return this.enabled;
  }

  /**
   * Clear all metrics and history
   */
  clear(): void {
    this.activeTimers.clear();
    this.timingHistory = [];
    this.memorySnapshots = [];
    this.inheritanceMetrics = [];
    this.replicationMetrics = [];
    this.consistencyMetrics = [];
    this.customMetrics = [];
  }

  /**
   * Shutdown the monitoring service
   */
  shutdown(): void {
    this.stopMemoryTracking();
    this.clear();
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

let monitoringServiceInstance: PerformanceMonitoringService | null = null;

/**
 * Get the singleton performance monitoring service instance
 * @param config - Optional configuration
 * @returns PerformanceMonitoringService instance
 */
export function getPerformanceMonitoringService(config?: Partial<PerformanceMonitoringConfig>): PerformanceMonitoringService {
  if (!monitoringServiceInstance) {
    monitoringServiceInstance = new PerformanceMonitoringService(config);
  }
  return monitoringServiceInstance;
}

/**
 * Reset the singleton instance (for testing)
 */
export function resetPerformanceMonitoringService(): void {
  if (monitoringServiceInstance) {
    monitoringServiceInstance.shutdown();
    monitoringServiceInstance = null;
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Format bytes to human readable string
 * @param bytes - Number of bytes
 * @returns Formatted string (e.g., "1.5 MB")
 */
export function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 Bytes';

  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

/**
 * Format duration to human readable string
 * @param ms - Duration in milliseconds
 * @returns Formatted string (e.g., "1.5s", "200ms")
 */
export function formatDuration(ms: number): string {
  if (ms < 1) return `${(ms * 1000).toFixed(2)}μs`;
  if (ms < 1000) return `${ms.toFixed(2)}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(2)}s`;

  const minutes = Math.floor(ms / 60000);
  const seconds = Math.floor((ms % 60000) / 1000);
  return `${minutes}m ${seconds}s`;
}

/**
 * ComfyUI Instance Store
 *
 * Persistence layer for ComfyUI instance configurations and state.
 * Handles loading, saving, and migrating instance data.
 */

import type {
  ComfyUIInstancesConfig,
  ComfyUIInstanceConfig,
  MigrationResult,
} from '../../types/comfyui-instance';
import { WizardError } from '../wizard/types';
import { getLogger } from '../wizard/logger';

const CONFIG_VERSION = '1.0';
const CONFIG_FILENAME = 'comfyui_instances.json';

/**
 * ComfyUI Instance Persistence Store
 */
export class ComfyUIInstanceStore {
  private configPath: string;
  private logger = getLogger();

  constructor(configPath?: string) {
    this.configPath = configPath || this.getDefaultConfigPath();
  }

  /**
   * Load instance configurations from storage
   */
  async loadInstances(): Promise<ComfyUIInstancesConfig> {
    try {
      const configText = await this.readConfigFile();
      const config: ComfyUIInstancesConfig = JSON.parse(configText);

      // Validate and migrate if necessary
      const migratedConfig = await this.migrateConfig(config);

      this.logger.info('comfyui-store', 'Loaded instance configurations', {
        version: migratedConfig.version,
        instanceCount: migratedConfig.instances.length,
        activeInstanceId: migratedConfig.activeInstanceId,
      });

      return migratedConfig;
    } catch (error) {
      if (error instanceof WizardError) {
        throw error;
      }

      // If file doesn't exist or is corrupted, return default config
      this.logger.warn('comfyui-store', 'Failed to load config, using defaults', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });

      return this.createDefaultConfig();
    }
  }

  /**
   * Save instance configurations to storage
   */
  async saveInstances(config: ComfyUIInstancesConfig): Promise<void> {
    try {
      // Update timestamp
      config.lastSaved = new Date().toISOString();

      // Validate config before saving
      this.validateConfig(config);

      const configText = JSON.stringify(config, null, 2);
      await this.writeConfigFile(configText);

      this.logger.info('comfyui-store', 'Saved instance configurations', {
        version: config.version,
        instanceCount: config.instances.length,
        activeInstanceId: config.activeInstanceId,
      });
    } catch (error) {
      this.logger.error('comfyui-store', 'Failed to save instance configurations', error as Error);
      throw new WizardError(
        'Failed to save ComfyUI instance configurations',
        'filesystem',
        false,
        false,
        { originalError: error }
      );
    }
  }

  /**
   * Export configurations to a string
   */
  async exportInstances(): Promise<string> {
    const config = await this.loadInstances();
    return JSON.stringify(config, null, 2);
  }

  /**
   * Import configurations from a string
   */
  async importInstances(data: string): Promise<void> {
    try {
      const importedConfig: ComfyUIInstancesConfig = JSON.parse(data);

      // Validate imported config
      this.validateConfig(importedConfig);

      // Check for port conflicts with existing instances
      await this.validateImportedInstances(importedConfig.instances);

      // Save imported config
      await this.saveInstances(importedConfig);

      this.logger.info('comfyui-store', 'Imported instance configurations', {
        version: importedConfig.version,
        instanceCount: importedConfig.instances.length,
      });
    } catch (error) {
      this.logger.error('comfyui-store', 'Failed to import instance configurations', error as Error);
      throw new WizardError(
        'Failed to import ComfyUI instance configurations',
        'datacontract',
        false,
        false,
        { originalError: error }
      );
    }
  }

  /**
   * Migrate legacy single-instance configuration
   */
  async migrateLegacyConfig(): Promise<MigrationResult> {
    try {
      // Try to detect and load legacy configuration
      // This would check project config or other locations for single-instance setup
      const legacyConfig = await this.detectLegacyConfig();

      if (!legacyConfig) {
        return {
          migrated: false,
          toVersion: CONFIG_VERSION,
          instancesCreated: 0,
          errors: [],
        };
      }

      // Create instance from legacy config
      const instanceConfig: ComfyUIInstanceConfig = {
        id: 'legacy_migrated',
        name: 'Migrated Instance',
        port: legacyConfig.port || 8188,
        host: legacyConfig.host || 'localhost',
        gpuDevice: legacyConfig.gpuDevice,
        envVars: legacyConfig.envVars,
        customNodesPath: legacyConfig.customNodesPath,
        maxConcurrentWorkflows: legacyConfig.maxConcurrentWorkflows,
        timeoutMs: legacyConfig.timeout,
        enableQueueMonitoring: legacyConfig.enableQueueMonitoring !== false,
        autoStart: false,
        description: 'Migrated from legacy single-instance configuration',
      };

      // Load current config and add migrated instance
      const currentConfig = await this.loadInstances();
      const existingIds = new Set(currentConfig.instances.map(i => i.id));

      // Generate unique ID if needed
      let instanceId = instanceConfig.id;
      let counter = 1;
      while (existingIds.has(instanceId)) {
        instanceId = `${instanceConfig.id}_${counter}`;
        counter++;
      }
      instanceConfig.id = instanceId;

      currentConfig.instances.push(instanceConfig);

      // Set as active if no active instance
      if (!currentConfig.activeInstanceId) {
        currentConfig.activeInstanceId = instanceConfig.id;
      }

      // Save migrated config
      await this.saveInstances(currentConfig);

      this.logger.info('comfyui-store', 'Migrated legacy configuration', {
        instanceId: instanceConfig.id,
        port: instanceConfig.port,
      });

      return {
        migrated: true,
        fromVersion: 'legacy',
        toVersion: CONFIG_VERSION,
        instancesCreated: 1,
        errors: [],
      };
    } catch (error) {
      this.logger.error('comfyui-store', 'Failed to migrate legacy config', error as Error);
      return {
        migrated: false,
        toVersion: CONFIG_VERSION,
        instancesCreated: 0,
        errors: [error instanceof Error ? error.message : 'Unknown migration error'],
      };
    }
  }

  /**
   * Get default configuration file path
   */
  private getDefaultConfigPath(): string {
    // Use localStorage key for browser environment
    // In Electron, this could be extended to use file system
    return CONFIG_FILENAME;
  }

  /**
   * Read configuration from storage
   */
  private async readConfigFile(): Promise<string> {
    // Browser environment - use localStorage
    const configText = localStorage.getItem(this.configPath);
    if (!configText) {
      throw new WizardError(
        'Configuration not found in localStorage',
        'filesystem',
        false,
        false,
        { configPath: this.configPath }
      );
    }
    return configText;
  }

  /**
   * Write configuration to storage
   */
  private async writeConfigFile(configText: string): Promise<void> {
    // Browser environment - use localStorage
    localStorage.setItem(this.configPath, configText);
  }

  /**
   * Create default configuration
   */
  private createDefaultConfig(): ComfyUIInstancesConfig {
    return {
      version: CONFIG_VERSION,
      instances: [
        {
          id: 'default_instance',
          name: 'Default Instance',
          port: 8188,
          host: 'localhost',
          maxConcurrentWorkflows: 1,
          timeoutMs: 300000,
          enableQueueMonitoring: true,
          autoStart: false,
          description: 'Default ComfyUI instance',
        },
      ],
      activeInstanceId: 'default_instance',
      lastSaved: new Date().toISOString(),
    };
  }

  /**
   * Validate configuration structure
   */
  private validateConfig(config: ComfyUIInstancesConfig): void {
    if (!config.version) {
      throw new WizardError(
        'Configuration missing version',
        'datacontract',
        false,
        false
      );
    }

    if (!Array.isArray(config.instances)) {
      throw new WizardError(
        'Configuration instances must be an array',
        'datacontract',
        false,
        false
      );
    }

    // Validate each instance
    const ids = new Set<string>();
    for (const instance of config.instances) {
      if (!instance.id || !instance.name || typeof instance.port !== 'number') {
        throw new WizardError(
          'Invalid instance configuration',
          'datacontract',
          false,
          false,
          { instanceId: instance.id }
        );
      }

      if (ids.has(instance.id)) {
        throw new WizardError(
          `Duplicate instance ID: ${instance.id}`,
          'datacontract',
          false,
          false,
          { instanceId: instance.id }
        );
      }
      ids.add(instance.id);

      if (instance.port < 1 || instance.port > 65535) {
        throw new WizardError(
          `Invalid port number: ${instance.port}`,
          'datacontract',
          false,
          false,
          { instanceId: instance.id, port: instance.port }
        );
      }
    }

    // Validate active instance ID
    if (config.activeInstanceId && !ids.has(config.activeInstanceId)) {
      throw new WizardError(
        `Active instance ID not found: ${config.activeInstanceId}`,
        'datacontract',
        false,
        false,
        { activeInstanceId: config.activeInstanceId }
      );
    }
  }

  /**
   * Validate imported instances for conflicts
   */
  private async validateImportedInstances(instances: ComfyUIInstanceConfig[]): Promise<void> {
    const currentConfig = await this.loadInstances();
    const currentPorts = new Set(currentConfig.instances.map(i => i.port));

    for (const instance of instances) {
      if (currentPorts.has(instance.port)) {
        throw new WizardError(
          `Imported instance port conflict: ${instance.port} (instance: ${instance.name})`,
          'datacontract',
          false,
          false,
          { instanceId: instance.id, port: instance.port }
        );
      }
    }
  }

  /**
   * Migrate configuration to current version
   */
  private async migrateConfig(config: ComfyUIInstancesConfig): Promise<ComfyUIInstancesConfig> {
    // For now, only version 1.0 is supported
    // Future migrations would go here
    return config;
  }

  /**
   * Detect legacy single-instance configuration
   */
  private async detectLegacyConfig(): Promise<any | null> {
    // Try to detect legacy configuration from various sources
    // This is a placeholder - actual implementation would check:
    // - Project configuration files
    // - Environment variables
    // - Other configuration stores

    // For now, return null (no legacy config detected)
    return null;
  }
}

// Singleton instance
let instanceStoreInstance: ComfyUIInstanceStore | null = null;

/**
 * Get the singleton instance store
 */
export function getComfyUIInstanceStore(): ComfyUIInstanceStore {
  if (!instanceStoreInstance) {
    instanceStoreInstance = new ComfyUIInstanceStore();
  }
  return instanceStoreInstance;
}

/**
 * Create a new instance store instance
 */
export function createComfyUIInstanceStore(configPath?: string): ComfyUIInstanceStore {
  return new ComfyUIInstanceStore(configPath);
}

import type { StorageBackend } from './projectPersistence';
import type { Project } from '../../types';

/**
 * RoverBackend implementation of StorageBackend
 * Bridges the UI persistence to the Electron Rover Service
 */
export class RoverBackend implements StorageBackend {
    private projectPath: string;

    constructor(projectPath: string) {
        this.projectPath = projectPath;
    }

    /**
     * Save project data and create a Rover checkpoint
     */
    async save(key: string, data: string): Promise<void> {
        try {
            const parsedData = JSON.parse(data) as Project;
            const projectId = parsedData.id || (parsedData as any).project_id;

            // Use Rover API if available
            if (window.electronAPI?.rover?.sync) {
                await window.electronAPI.rover.sync(
                    this.projectPath,
                    projectId,
                    'Auto-save checkpoint',
                    parsedData as unknown as Record<string, unknown>
                );
            } else {
                console.warn('[RoverBackend] Rover API sync not available, using basic FS');
            }

            // Always write the main project.json for compatibility with the rest of the app
            if (window.electronAPI?.fs?.writeFile) {
                await window.electronAPI.fs.writeFile(pathJoin(this.projectPath, 'project.json'), data);
            } else {
                console.error('[RoverBackend] FS API not available for save');
                throw new Error('No persistence available');
            }
        } catch (error) {
            console.error('[RoverBackend] Save failed:', error);
            throw error;
        }
    }

    /**
     * Load project data
     */
    async load(key: string): Promise<string | null> {
        if (!window.electronAPI?.fs?.readFile) {
            console.error('[RoverBackend] FS API not available for load');
            return null;
        }

        try {
            const filePath = pathJoin(this.projectPath, 'project.json');
            const exists = await window.electronAPI.fs.exists(filePath);

            if (!exists) return null;

            const buffer = await window.electronAPI.fs.readFile(filePath);
            return buffer.toString('utf-8');
        } catch (error) {
            console.error('[RoverBackend] Load failed:', error);
            return null;
        }
    }

    /**
     * Check if project exists
     */
    async exists(key: string): Promise<boolean> {
        if (!window.electronAPI?.fs?.exists) return false;
        try {
            return await window.electronAPI.fs.exists(pathJoin(this.projectPath, 'project.json'));
        } catch (error) {
            return false;
        }
    }

    /**
     * Delete project file
     */
    async delete(key: string): Promise<void> {
        if (!window.electronAPI?.fs?.unlink) {
            throw new Error('FS API not available for delete operation');
        }

        try {
            const filePath = pathJoin(this.projectPath, 'project.json');
            const exists = await window.electronAPI.fs.exists(filePath);

            if (exists) {
                await window.electronAPI.fs.unlink(filePath);
                console.log('[RoverBackend] Project deleted:', filePath);
            }
        } catch (error) {
            console.error('[RoverBackend] Delete failed:', error);
            throw error;
        }
    }

    /**
     * List projects (not supported via RoverBackend for now)
     */
    async list(): Promise<string[]> {
        return [];
    }
}

/**
 * Helper to join paths safely in the renderer
 */
function pathJoin(base: string, part: string): string {
    // Simple path joining for renderer (assumes forward or backward slashes depending on OS)
    const separator = base.includes('\\') ? '\\' : '/';
    return base.endsWith(separator) ? base + part : base + separator + part;
}

/**
 * Phrase Synchronization Manager
 * 
 * Manages synchronization between voice recordings and phrase data
 * Coordinates with VoiceHttpClient for backend communication
 */

import { VoiceHttpClient, VoiceApiResponse } from './voiceHttpClient';
import type { VoiceRecording, PhraseData, SyncStatus } from '@/types';

/**
 * Phrase Synchronization Manager Configuration
 */
export interface PhraseSyncConfig {
  autoSync: boolean;
  syncInterval: number;
  maxRetries: number;
}

/**
 * Default configuration for Phrase Synchronization Manager
 */
const DEFAULT_SYNC_CONFIG: PhraseSyncConfig = {
  autoSync: true,
  syncInterval: 5000, // 5 seconds
  maxRetries: 3,
};

/**
 * Synchronization result
 */
export interface SyncResult {
  success: boolean;
  phraseId?: string;
  recordingId?: string;
  error?: string;
  timestamp: string;
}

/**
 * Phrase Synchronization Manager Class
 */
export class PhraseSyncManager {
  private voiceClient: VoiceHttpClient;
  private config: PhraseSyncConfig;
  private syncQueue: Array<{ phrase: PhraseData; recording: VoiceRecording }>;
  private isProcessing: boolean;
  private intervalId?: NodeJS.Timeout;

  constructor(
    voiceClient?: VoiceHttpClient,
    config?: Partial<PhraseSyncConfig>
  ) {
    this.voiceClient = voiceClient || new VoiceHttpClient();
    this.config = { ...DEFAULT_SYNC_CONFIG, ...config };
    this.syncQueue = [];
    this.isProcessing = false;

    if (this.config.autoSync) {
      this.startAutoSync();
    }
  }

  /**
   * Start automatic synchronization
   */
  startAutoSync(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }

    this.intervalId = setInterval(() => {
      if (this.syncQueue.length > 0 && !this.isProcessing) {
        this.processQueue();
      }
    }, this.config.syncInterval);
  }

  /**
   * Stop automatic synchronization
   */
  stopAutoSync(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = undefined;
    }
  }

  /**
   * Add phrase and recording to synchronization queue
   * 
   * @param phrase - Phrase data to synchronize
   * @param recording - Voice recording to associate
   */
  addToSyncQueue(phrase: PhraseData, recording: VoiceRecording): void {
    this.syncQueue.push({ phrase, recording });
  }

  /**
   * Process synchronization queue
   */
  private async processQueue(): Promise<void> {
    if (this.isProcessing || this.syncQueue.length === 0) {
      return;
    }

    this.isProcessing = true;

    try {
      // Process items in queue
      while (this.syncQueue.length > 0) {
        const item = this.syncQueue.shift();
        if (item) {
          await this.syncPhraseWithRecording(item.phrase, item.recording);
        }
      }
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * Synchronize phrase with voice recording
   * 
   * @param phrase - Phrase data
   * @param recording - Voice recording
   * @returns Synchronization result
   */
  async syncPhraseWithRecording(
    phrase: PhraseData,
    recording: VoiceRecording
  ): Promise<SyncResult> {
    try {
      // First upload the voice recording
      const uploadResponse = await this.voiceClient.uploadVoiceRecording(
        recording
      );

      if (!uploadResponse.success) {
        throw new Error(
          uploadResponse.error || 'Failed to upload voice recording'
        );
      }

      // Associate recording ID with phrase
      const phraseWithRecording: PhraseData = {
        ...phrase,
        recordingId: uploadResponse.data?.recordingId,
      };

      // Synchronize phrase data with backend
      const syncResponse = await this.voiceClient.syncPhraseData(
        phraseWithRecording
      );

      if (!syncResponse.success) {
        throw new Error(
          syncResponse.error || 'Failed to synchronize phrase data'
        );
      }

      return {
        success: true,
        phraseId: phrase.id,
        recordingId: uploadResponse.data?.recordingId,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      return {
        success: false,
        phraseId: phrase.id,
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: new Date().toISOString(),
      };
    }
  }

  /**
   * Get synchronization status for a phrase
   * 
   * @param phraseId - ID of the phrase to check
   * @returns Current synchronization status
   */
  async getSyncStatus(phraseId: string): Promise<SyncStatus> {
    // In a real implementation, this would check backend status
    // For now, return a default status
    return {
      phraseId,
      status: 'synced',
      lastUpdated: new Date().toISOString(),
      retries: 0,
    };
  }

  /**
   * Get all pending synchronizations
   * 
   * @returns Array of pending synchronization items
   */
  getPendingSyncs(): Array<{ phrase: PhraseData; recording: VoiceRecording }> {
    return [...this.syncQueue];
  }

  /**
   * Clear synchronization queue
   */
  clearQueue(): void {
    this.syncQueue = [];
  }

  /**
   * Update synchronization configuration
   * 
   * @param config - New configuration
   */
  updateConfig(config: Partial<PhraseSyncConfig>): void {
    this.config = { ...this.config, ...config };

    if (this.config.autoSync && !this.intervalId) {
      this.startAutoSync();
    } else if (!this.config.autoSync && this.intervalId) {
      this.stopAutoSync();
    }
  }

  /**
   * Get current configuration
   * 
   * @returns Current synchronization configuration
   */
  getConfig(): PhraseSyncConfig {
    return { ...this.config };
  }

  /**
   * Cleanup resources
   */
  destroy(): void {
    this.stopAutoSync();
    this.clearQueue();
  }
}

/**
 * Default Phrase Synchronization Manager instance
 */
export const phraseSyncManager = new PhraseSyncManager();

/**
 * Mock Phrase Synchronization Manager for development/testing
