/**
 * LayoutPreferences Service
 * 
 * Manages persistence of layout preferences per screen size.
 * Saves and restores user preferences for different breakpoints.
 * 
 * Exigence: 12.8
 */

import type { ResponsiveBreakpoint } from '../../hooks/useResponsiveGrid';

export interface LayoutPreference {
  breakpointName: string;
  columns?: number;
  useListMode?: boolean;
  gridSize?: number;
  showGridLines?: boolean;
  snapEnabled?: boolean;
  customSettings?: Record<string, unknown>;
  lastUpdated: number;
}

export interface LayoutPreferencesState {
  preferences: Record<string, LayoutPreference>;
  version: string;
}

const STORAGE_KEY = 'storycore_layout_preferences';
const STORAGE_VERSION = '1.0';

/**
 * Layout Preferences Manager
 */
export class LayoutPreferencesManager {
  private preferences: Map<string, LayoutPreference> = new Map();
  private storageAvailable: boolean;

  constructor() {
    this.storageAvailable = this.checkStorageAvailable();
    this.loadPreferences();
  }

  /**
   * Check if localStorage is available
   */
  private checkStorageAvailable(): boolean {
    try {
      const test = '__storage_test__';
      localStorage.setItem(test, test);
      localStorage.removeItem(test);
      return true;
    } catch (e) {
      return false;
    }
  }

  /**
   * Load preferences from localStorage
   * Exigence: 12.8
   */
  private loadPreferences(): void {
    if (!this.storageAvailable) return;

    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return;

      const state: LayoutPreferencesState = JSON.parse(stored);
      
      // Check version compatibility
      if (state.version !== STORAGE_VERSION) {
        console.warn('Layout preferences version mismatch, resetting preferences');
        this.clearPreferences();
        return;
      }

      // Load preferences into map
      Object.entries(state.preferences).forEach(([key, pref]) => {
        this.preferences.set(key, pref);
      });
    } catch (error) {
      console.error('Failed to load layout preferences:', error);
      this.clearPreferences();
    }
  }

  /**
   * Save preferences to localStorage
   * Exigence: 12.8
   */
  private savePreferences(): void {
    if (!this.storageAvailable) return;

    try {
      const state: LayoutPreferencesState = {
        version: STORAGE_VERSION,
        preferences: Object.fromEntries(this.preferences)
      };

      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (error) {
      console.error('Failed to save layout preferences:', error);
    }
  }

  /**
   * Get preference for a breakpoint
   * Exigence: 12.8
   */
  getPreference(breakpoint: ResponsiveBreakpoint): LayoutPreference | null {
    return this.preferences.get(breakpoint.name) || null;
  }

  /**
   * Set preference for a breakpoint
   * Exigence: 12.8
   */
  setPreference(breakpoint: ResponsiveBreakpoint, preference: Partial<LayoutPreference>): void {
    const existing = this.preferences.get(breakpoint.name);
    
    const updated: LayoutPreference = {
      breakpointName: breakpoint.name,
      ...existing,
      ...preference,
      lastUpdated: Date.now()
    };

    this.preferences.set(breakpoint.name, updated);
    this.savePreferences();
  }

  /**
   * Update specific preference field
   */
  updatePreference(
    breakpoint: ResponsiveBreakpoint,
    field: keyof LayoutPreference,
    value: unknown
  ): void {
    const existing = this.preferences.get(breakpoint.name) || {
      breakpointName: breakpoint.name,
      lastUpdated: Date.now()
    };

    const updated = {
      ...existing,
      [field]: value,
      lastUpdated: Date.now()
    };

    this.preferences.set(breakpoint.name, updated);
    this.savePreferences();
  }

  /**
   * Clear all preferences
   */
  clearPreferences(): void {
    this.preferences.clear();
    if (this.storageAvailable) {
      localStorage.removeItem(STORAGE_KEY);
    }
  }

  /**
   * Clear preference for specific breakpoint
   */
  clearPreference(breakpoint: ResponsiveBreakpoint): void {
    this.preferences.delete(breakpoint.name);
    this.savePreferences();
  }

  /**
   * Get all preferences
   */
  getAllPreferences(): Map<string, LayoutPreference> {
    return new Map(this.preferences);
  }

  /**
   * Export preferences as JSON
   */
  exportPreferences(): string {
    const state: LayoutPreferencesState = {
      version: STORAGE_VERSION,
      preferences: Object.fromEntries(this.preferences)
    };
    return JSON.stringify(state, null, 2);
  }

  /**
   * Import preferences from JSON
   */
  importPreferences(json: string): boolean {
    try {
      const state: LayoutPreferencesState = JSON.parse(json);
      
      if (state.version !== STORAGE_VERSION) {
        console.error('Version mismatch in imported preferences');
        return false;
      }

      this.preferences.clear();
      Object.entries(state.preferences).forEach(([key, pref]) => {
        this.preferences.set(key, pref);
      });

      this.savePreferences();
      return true;
    } catch (error) {
      console.error('Failed to import preferences:', error);
      return false;
    }
  }
}

// Singleton instance
let instance: LayoutPreferencesManager | null = null;

/**
 * Get singleton instance of LayoutPreferencesManager
 */
export const getLayoutPreferencesManager = (): LayoutPreferencesManager => {
  if (!instance) {
    instance = new LayoutPreferencesManager();
  }
  return instance;
};

/**
 * Result Service
 * 
 * Manages fetching and displaying generated results from the backend.
 * Supports result retrieval, preview, and download functionality.
 */

import type { GenerationTask } from '../types';
import { getCachedPlaceholder } from '../utils/placeholderImage';

export interface GeneratedResult {
  taskId: string;
  shotId: string;
  type: GenerationTask['type'];
  status: 'success' | 'failed';

  // Generated assets
  assets: GeneratedAsset[];

  // Metadata
  generatedAt: Date;
  processingTime?: number; // seconds

  // Quality metrics (if available)
  qualityScore?: number; // 0-100
  metrics?: Record<string, number>;

  // Error information (if failed)
  error?: string;
}

export interface GeneratedAsset {
  id: string;
  type: 'image' | 'video' | 'audio' | 'data';
  name: string;
  url: string;
  thumbnail?: string;
  size?: number; // bytes
  format?: string; // e.g., 'png', 'mp4', 'wav', 'json'
  dimensions?: { width: number; height: number };
  duration?: number; // seconds (for video/audio)
  metadata?: Record<string, unknown>;
}

export interface ResultFetchOptions {
  includeAssets?: boolean; // Include asset URLs (default: true)
  includeThumbnails?: boolean; // Include thumbnails (default: true)
  includeMetrics?: boolean; // Include quality metrics (default: false)
}

export class ResultService {
  private baseUrl: string;

  constructor(baseUrl: string = import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') {
    this.baseUrl = baseUrl;
  }

  /**
   * Generate a placeholder image as data URI to avoid CSP violations
   */
  protected generatePlaceholderImage(width: number, height: number, text: string): string {
    return getCachedPlaceholder(width, height, text);
  }

  /**
   * Fetch result for a completed task
   */
  async fetchResult(taskId: string, options: ResultFetchOptions = {}): Promise<GeneratedResult> {
    const {
      includeAssets = true,
      includeThumbnails = true,
      includeMetrics = false,
    } = options;

    const params = new URLSearchParams({
      includeAssets: String(includeAssets),
      includeThumbnails: String(includeThumbnails),
      includeMetrics: String(includeMetrics),
    });

    const response = await fetch(`${this.baseUrl}/api/tasks/${taskId}/result?${params}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch result: ${response.statusText}`);
    }

    const data = await response.json();

    return {
      taskId: data.taskId,
      shotId: data.shotId,
      type: data.type,
      status: data.status,
      assets: data.assets || [],
      generatedAt: new Date(data.generatedAt),
      processingTime: data.processingTime,
      qualityScore: data.qualityScore,
      metrics: data.metrics,
      error: data.error,
    };
  }

  /**
   * Fetch results for multiple tasks
   */
  async fetchMultipleResults(taskIds: string[], options: ResultFetchOptions = {}): Promise<GeneratedResult[]> {
    const promises = taskIds.map((taskId) => this.fetchResult(taskId, options));
    return Promise.all(promises);
  }

  /**
   * Fetch all results for a project
   */
  async fetchProjectResults(projectName: string, options: ResultFetchOptions = {}): Promise<GeneratedResult[]> {
    const {
      includeAssets = true,
      includeThumbnails = true,
      includeMetrics = false,
    } = options;

    const params = new URLSearchParams({
      includeAssets: String(includeAssets),
      includeThumbnails: String(includeThumbnails),
      includeMetrics: String(includeMetrics),
    });

    const response = await fetch(`${this.baseUrl}/api/projects/${projectName}/results?${params}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch project results: ${response.statusText}`);
    }

    const data = await response.json();

    return data.results.map((result: any) => ({
      taskId: result.taskId,
      shotId: result.shotId,
      type: result.type,
      status: result.status,
      assets: result.assets || [],
      generatedAt: new Date(result.generatedAt),
      processingTime: result.processingTime,
      qualityScore: result.qualityScore,
      metrics: result.metrics,
      error: result.error,
    }));
  }

  /**
   * Download an asset
   */
  async downloadAsset(asset: GeneratedAsset, filename?: string): Promise<void> {
    const response = await fetch(asset.url);

    if (!response.ok) {
      throw new Error(`Failed to download asset: ${response.statusText}`);
    }

    const blob = await response.blob();
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = filename || asset.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }

  /**
   * Download all assets from a result
   */
  async downloadAllAssets(result: GeneratedResult): Promise<void> {
    for (const asset of result.assets) {
      await this.downloadAsset(asset);
    }
  }

  /**
   * Get preview URL for an asset
   */
  getPreviewUrl(asset: GeneratedAsset): string {
    if (asset.thumbnail) {
      return asset.thumbnail;
    }

    // For images, use the asset URL directly
    if (asset.type === 'image') {
      return asset.url;
    }

    // For other types, return a placeholder or generate thumbnail URL
    return `${this.baseUrl}/api/assets/${asset.id}/thumbnail`;
  }

  /**
   * Delete a result
   */
  async deleteResult(taskId: string): Promise<void> {
    const response = await fetch(`${this.baseUrl}/api/tasks/${taskId}/result`, {
      method: 'DELETE',
    });

    if (!response.ok) {
      throw new Error(`Failed to delete result: ${response.statusText}`);
    }
  }
}

