import type { Shot } from '../../types';
import type { SearchCriteria, SearchOperator, SearchFilter } from '../../types/gridEditorAdvanced';

/**
 * SearchService - Advanced search and filtering for shots
 * 
 * Supports:
 * - Real-time search (<200ms)
 * - Multiple search fields (name, tags, duration, type, status)
 * - Logical operators (AND, OR, NOT)
 * - Saved filters
 * - Predefined filters
 */
export class SearchService {
  private shots: Shot[];
  private savedFilters: Map<string, SearchFilter>;

  constructor(shots: Shot[] = []) {
    this.shots = shots;
    this.savedFilters = new Map();
  }

  /**
   * Update the shots collection
   */
  updateShots(shots: Shot[]): void {
    this.shots = shots;
  }

  /**
   * Perform a simple search across all fields
   */
  search(query: string): Shot[] {
    if (!query.trim()) {
      return this.shots;
    }

    const lowerQuery = query.toLowerCase().trim();
    
    return this.shots.filter(shot => {
      return (
        shot.title.toLowerCase().includes(lowerQuery) ||
        shot.description?.toLowerCase().includes(lowerQuery) ||
        this.matchTags(shot, lowerQuery) ||
        this.matchType(shot, lowerQuery) ||
        this.matchStatus(shot, lowerQuery)
      );
    });
  }

  /**
   * Perform an advanced search with criteria and logical operators
   */
  advancedSearch(criteria: SearchCriteria[]): Shot[] {
    if (criteria.length === 0) {
      return this.shots;
    }

    return this.shots.filter(shot => {
      return this.evaluateCriteria(shot, criteria);
    });
  }

  /**
   * Evaluate search criteria with logical operators
   */
  private evaluateCriteria(shot: Shot, criteria: SearchCriteria[]): boolean {
    if (criteria.length === 0) return true;
    if (criteria.length === 1) return this.matchCriterion(shot, criteria[0]);

    // Group criteria by operator
    const andGroups: SearchCriteria[][] = [];
    const orGroups: SearchCriteria[][] = [];
    const notGroups: SearchCriteria[] = [];

    let currentAndGroup: SearchCriteria[] = [];
    const currentOrGroup: SearchCriteria[] = [];

    for (let i = 0; i < criteria.length; i++) {
      const criterion = criteria[i];
      const nextOperator = i < criteria.length - 1 ? criteria[i + 1].operator : undefined;

      if (criterion.operator === 'NOT') {
        notGroups.push(criterion);
      } else if (nextOperator === 'AND' || nextOperator === undefined) {
        currentAndGroup.push(criterion);
        if (nextOperator === undefined || i === criteria.length - 1) {
          andGroups.push([...currentAndGroup]);
          currentAndGroup = [];
        }
      } else if (nextOperator === 'OR') {
        currentOrGroup.push(criterion);
        if (i === criteria.length - 1) {
          orGroups.push([...currentOrGroup]);
        }
      }
    }

    // Evaluate NOT criteria (must all be false)
    for (const criterion of notGroups) {
      if (this.matchCriterion(shot, criterion)) {
        return false;
      }
    }

    // Evaluate AND groups (at least one group must have all criteria match)
    let andResult = andGroups.length === 0;
    for (const group of andGroups) {
      const groupResult = group.every(c => this.matchCriterion(shot, c));
      if (groupResult) {
        andResult = true;
        break;
      }
    }

    // Evaluate OR groups (at least one criterion must match)
    let orResult = orGroups.length === 0;
    for (const group of orGroups) {
      const groupResult = group.some(c => this.matchCriterion(shot, c));
      if (groupResult) {
        orResult = true;
        break;
      }
    }

    return andResult && orResult;
  }

  /**
   * Match a single criterion against a shot
   */
  private matchCriterion(shot: Shot, criterion: SearchCriteria): boolean {
    const { field, value } = criterion;
    const lowerValue = value.toLowerCase().trim();

    switch (field) {
      case 'title':
        return shot.title.toLowerCase().includes(lowerValue);
      
      case 'description':
        return shot.description?.toLowerCase().includes(lowerValue) ?? false;
      
      case 'tags':
        return this.matchTags(shot, lowerValue);
      
      case 'duration':
        return this.matchDuration(shot.duration, value);
      
      case 'type':
        return this.matchType(shot, lowerValue);
      
      case 'status':
        return this.matchStatus(shot, lowerValue);
      
      default:
        return false;
    }
  }

  /**
   * Match tags
   */
  private matchTags(shot: Shot, query: string): boolean {
    const tags = shot.metadata?.tags as string[] | undefined;
    return tags?.some(tag => tag.toLowerCase().includes(query)) ?? false;
  }

  /**
   * Match type
   */
  private matchType(shot: Shot, query: string): boolean {
    const type = shot.metadata?.type as string | undefined;
    return type?.toLowerCase().includes(query) ?? false;
  }

  /**
   * Match status
   */
  private matchStatus(shot: Shot, query: string): boolean {
    const status = shot.metadata?.status as string | undefined;
    return status?.toLowerCase().includes(query) ?? false;
  }

  /**
   * Match duration with comparison operators
   */
  private matchDuration(duration: number, query: string): boolean {
    // Handle range queries (e.g., "5-10")
    if (query.includes('-')) {
      const [min, max] = query.split('-').map(s => parseFloat(s.trim()));
      if (!isNaN(min) && !isNaN(max)) {
        return duration >= min && duration <= max;
      }
    }
    
    // Handle comparison queries (e.g., ">5", "<10", ">=5", "<=10")
    const comparisonMatch = query.match(/^([<>]=?)\s*(\d+(?:\.\d+)?)$/);
    if (comparisonMatch) {
      const operator = comparisonMatch[1];
      const value = parseFloat(comparisonMatch[2]);
      
      if (!isNaN(value)) {
        switch (operator) {
          case '>': return duration > value;
          case '>=': return duration >= value;
          case '<': return duration < value;
          case '<=': return duration <= value;
        }
      }
    }
    
    // Handle exact match
    const exactValue = parseFloat(query);
    if (!isNaN(exactValue)) {
      return Math.abs(duration - exactValue) < 0.1;
    }
    
    return false;
  }

  /**
   * Save a filter for later use
   */
  saveFilter(filter: SearchFilter): void {
    this.savedFilters.set(filter.id, filter);
  }

  /**
   * Get a saved filter by ID
   */
  getSavedFilter(id: string): SearchFilter | undefined {
    return this.savedFilters.get(id);
  }

  /**
   * Get all saved filters
   */
  getAllSavedFilters(): SearchFilter[] {
    return Array.from(this.savedFilters.values());
  }

  /**
   * Delete a saved filter
   */
  deleteSavedFilter(id: string): boolean {
    return this.savedFilters.delete(id);
  }

  /**
   * Apply a saved filter
   */
  applySavedFilter(id: string): Shot[] {
    const filter = this.savedFilters.get(id);
    if (!filter) {
      return this.shots;
    }

    return this.advancedSearch(filter.criteria);
  }

  /**
   * Apply a predefined filter
   */
  applyPredefinedFilter(filterType: 'favorites' | 'recent' | 'unused' | 'errors'): Shot[] {
    switch (filterType) {
      case 'favorites':
        return this.shots.filter(shot => shot.metadata?.favorite === true);
      
      case 'recent':
        // Sort by creation/update time and return recent ones
        const sortedByTime = [...this.shots].sort((a, b) => {
          const timeA = (a.metadata?.updatedAt as number) || (a.metadata?.createdAt as number) || 0;
          const timeB = (b.metadata?.updatedAt as number) || (b.metadata?.createdAt as number) || 0;
          return timeB - timeA;
        });
        return sortedByTime.slice(0, 10); // Return 10 most recent
      
      case 'unused':
        return this.shots.filter(shot => shot.metadata?.used === false);
      
      case 'errors':
        return this.shots.filter(shot => shot.metadata?.hasErrors === true || shot.metadata?.status === 'error');
      
      default:
        return this.shots;
    }
  }

  /**
   * Get search suggestions based on query
   */
  getSuggestions(query: string): string[] {
    if (!query.trim()) {
      return [];
    }

    const lowerQuery = query.toLowerCase().trim();
    const suggestions = new Set<string>();

    // Suggest titles
    this.shots.forEach(shot => {
      if (shot.title.toLowerCase().includes(lowerQuery)) {
        suggestions.add(shot.title);
      }
    });

    // Suggest tags
    this.shots.forEach(shot => {
      const tags = shot.metadata?.tags as string[] | undefined;
      tags?.forEach(tag => {
        if (tag.toLowerCase().includes(lowerQuery)) {
          suggestions.add(tag);
        }
      });
    });

    // Suggest types
    this.shots.forEach(shot => {
      const type = shot.metadata?.type as string | undefined;
      if (type && type.toLowerCase().includes(lowerQuery)) {
        suggestions.add(type);
      }
    });

    return Array.from(suggestions).slice(0, 5); // Limit to 5 suggestions
  }

  /**
   * Get alternative search suggestions when no results found
   */
  getAlternativeSuggestions(query: string): string[] {
    const suggestions: string[] = [];

    // Suggest removing special characters
    if (/[^a-zA-Z0-9\s]/.test(query)) {
      suggestions.push(`Try searching without special characters: "${query.replace(/[^a-zA-Z0-9\s]/g, '')}"`);
    }

    // Suggest shorter query
    if (query.length > 20) {
      suggestions.push(`Try a shorter search term`);
    }

    // Suggest common fields
    suggestions.push(`Try searching in specific fields (title, tags, type, status)`);

    // Suggest checking spelling
    suggestions.push(`Check your spelling`);

    // Suggest using filters
    suggestions.push(`Try using advanced filters`);

    return suggestions.slice(0, 3);
  }
}

// Singleton instance
let searchServiceInstance: SearchService | null = null;

export function getSearchService(shots?: Shot[]): SearchService {
  if (!searchServiceInstance) {
    searchServiceInstance = new SearchService(shots);
  } else if (shots) {
    searchServiceInstance.updateShots(shots);
  }
  return searchServiceInstance;
}

/**
 * Sequence Generation Service
 * 
 * Orchestrates the complete StoryCore pipeline for sequence generation:
 * Stage 1: Generate Master Coherence Sheet (3x3 grid)
 * Stage 2: Trigger ComfyUI integration
 * Stage 3: Process through StoryCore pipeline (promotion, QA, autofix)
 * Stage 4: Export results
 * 
 * Requirements: 3.2, 3.3, 3.4, 3.5, 3.6, 3.7, 8.1, 8.2, 8.3, 8.4, 9.5
 */

import type {
  Project,
  Shot,
  GenerationStatus,
  GenerationResults,
  GeneratedShot,
  QAReport,
  GenerationError,
} from '../types/projectDashboard';
import { BackendApiService } from './backendApiService';
import {
  GenerationErrorHandler,
  createGenerationError,
  getUserFriendlyErrorMessage,
  logError,
} from '../utils/generationErrorHandling';

// ============================================================================
// Types
// ============================================================================

/**
 * Pipeline stage identifiers
 */
export type PipelineStage = 'grid' | 'comfyui' | 'promotion' | 'qa' | 'export';

/**
 * Stage progress callback
 */
export type StageProgressCallback = (status: GenerationStatus) => void;

/**
 * Stage completion callback
 */
export type StageCompleteCallback = (stage: PipelineStage, result: unknown) => void;

/**
 * Error callback
 */
export type ErrorCallback = (error: GenerationError) => void;

/**
 * Generation options
 */
export interface GenerationOptions {
  onProgress?: StageProgressCallback;
  onStageComplete?: StageCompleteCallback;
  onError?: ErrorCallback;
  retryAttempts?: number;
  retryDelayMs?: number;
}

/**
 * Stage result types
 */
export interface GridGenerationResult {
  masterCoherenceSheetUrl: string;
  gridImages: string[];
  generatedAt: number;
}

export interface ComfyUIResult {
  promptId: string;
  outputs: Array<{
    shotId: string;
    imageUrl: string;
  }>;
}

export interface PromotionResult {
  promotedShots: Array<{
    shotId: string;
    imageUrl: string;
    processingTime: number;
  }>;
}

export interface QAResult {
  report: QAReport;
  autofixApplied: boolean;
}

export interface ExportResult {
  exportPackageUrl: string;
  timestamp: number;
}

// ============================================================================
// Sequence Generation Service
// ============================================================================

/**
 * Service for orchestrating sequence generation through the StoryCore pipeline
 * Requirements: 3.2, 3.3, 3.4, 3.5
 */
export class SequenceGenerationService {
  private backendApi: BackendApiService;
  private errorHandler: GenerationErrorHandler;
  private abortController: AbortController | null = null;
  private currentStage: PipelineStage | null = null;
  private startTime: number = 0;

  constructor(backendApi?: BackendApiService, errorHandler?: GenerationErrorHandler) {
    this.backendApi = backendApi || new BackendApiService();
    this.errorHandler = errorHandler || new GenerationErrorHandler();
  }

  /**
   * Generate sequence through complete pipeline
   * Requirements: 3.2, 3.3, 3.4, 3.5
   * 
   * @param project - Project with shots and prompts
   * @param options - Generation options with callbacks
   * @returns Generation results or null if cancelled/failed
   */
  async generateSequence(
    project: Project,
    options: GenerationOptions = {}
  ): Promise<GenerationResults | null> {
    const {
      onProgress,
      onStageComplete,
      onError,
      retryAttempts = 3,
      retryDelayMs = 2000,
    } = options;

    // Initialize abort controller for cancellation
    this.abortController = new AbortController();
    this.startTime = Date.now();

    try {
      // Validate project has shots with valid prompts
      if (!project.shots || project.shots.length === 0) {
        throw new Error('Project has no shots to generate');
      }

      const totalShots = project.shots.length;
      let currentShot = 0;

      // Reset error handler for new generation
      this.errorHandler.reset();

      // Stage 1: Generate Master Coherence Sheet (3x3 grid)
      this.currentStage = 'grid';
      onProgress?.({
        stage: 'grid',
        progress: 0,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
      });

      const gridResult = await this.executeWithRetry(
        () => this.generateMasterCoherenceSheet(project),
        retryAttempts,
        retryDelayMs,
        'grid',
        onError
      );

      if (!gridResult) {
        return null; // Cancelled or failed
      }

      // Save partial results after grid generation
      this.errorHandler.savePartialResults(
        project.id,
        ['grid'],
        [],
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('grid', gridResult);
      onProgress?.({
        stage: 'grid',
        progress: 20,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(20, totalShots),
      });

      // Stage 2: Trigger ComfyUI integration
      this.currentStage = 'comfyui';
      onProgress?.({
        stage: 'comfyui',
        progress: 20,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(20, totalShots),
      });

      const comfyuiResult = await this.executeWithRetry(
        () => this.generateWithComfyUI(project, gridResult, (shotIndex) => {
          currentShot = shotIndex + 1;
          const progress = 20 + Math.floor((shotIndex / totalShots) * 40);
          onProgress?.({
            stage: 'comfyui',
            progress,
            currentShot,
            totalShots,
            startTime: this.startTime,
            estimatedCompletion: this.estimateCompletion(progress, totalShots),
          });
        }),
        retryAttempts,
        retryDelayMs,
        'comfyui',
        onError
      );

      if (!comfyuiResult) {
        return null;
      }

      // Save partial results after ComfyUI generation
      this.errorHandler.savePartialResults(
        project.id,
        ['grid', 'comfyui'],
        comfyuiResult.outputs.map(output => ({
          shotId: output.shotId,
          imageUrl: output.imageUrl,
          qaScore: 0,
          processingTime: 0,
        })),
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('comfyui', comfyuiResult);
      onProgress?.({
        stage: 'comfyui',
        progress: 60,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(60, totalShots),
      });

      // Stage 3: Process through StoryCore pipeline (promotion, QA, autofix)
      this.currentStage = 'promotion';
      onProgress?.({
        stage: 'promotion',
        progress: 60,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(60, totalShots),
      });

      const promotionResult = await this.executeWithRetry(
        () => this.promoteShots(comfyuiResult, (shotIndex) => {
          const progress = 60 + Math.floor((shotIndex / totalShots) * 15);
          onProgress?.({
            stage: 'promotion',
            progress,
            currentShot: shotIndex + 1,
            totalShots,
            startTime: this.startTime,
            estimatedCompletion: this.estimateCompletion(progress, totalShots),
          });
        }),
        retryAttempts,
        retryDelayMs,
        'promotion',
        onError
      );

      if (!promotionResult) {
        return null;
      }

      // Save partial results after promotion
      this.errorHandler.savePartialResults(
        project.id,
        ['grid', 'comfyui', 'promotion'],
        promotionResult.promotedShots.map(shot => ({
          shotId: shot.shotId,
          imageUrl: shot.imageUrl,
          qaScore: 0,
          processingTime: shot.processingTime,
        })),
        gridResult.masterCoherenceSheetUrl
      );

      onStageComplete?.('promotion', promotionResult);

      // QA Stage
      this.currentStage = 'qa';
      onProgress?.({
        stage: 'qa',
        progress: 75,
        currentShot: 0,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(75, totalShots),
      });

      const qaResult = await this.executeWithRetry(
        () => this.runQAAnalysis(promotionResult),
        retryAttempts,
        retryDelayMs,
        'qa',
        onError
      );

      if (!qaResult) {
        return null;
      }

      onStageComplete?.('qa', qaResult);
      onProgress?.({
        stage: 'qa',
        progress: 90,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(90, totalShots),
      });

      // Stage 4: Export results
      this.currentStage = 'export';
      onProgress?.({
        stage: 'export',
        progress: 90,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
        estimatedCompletion: this.estimateCompletion(90, totalShots),
      });

      const exportResult = await this.executeWithRetry(
        () => this.exportResults(project, gridResult, promotionResult, qaResult),
        retryAttempts,
        retryDelayMs,
        'export',
        onError
      );

      if (!exportResult) {
        return null;
      }

      onStageComplete?.('export', exportResult);
      onProgress?.({
        stage: 'complete',
        progress: 100,
        currentShot: totalShots,
        totalShots,
        startTime: this.startTime,
      });

      // Compile final results
      const generatedShots: GeneratedShot[] = promotionResult.promotedShots.map(shot => ({
        shotId: shot.shotId,
        imageUrl: shot.imageUrl,
        qaScore: qaResult.report.shotScores.find(s => s.shotId === shot.shotId)?.score || 0,
        processingTime: shot.processingTime,
      }));

      const results: GenerationResults = {
        success: true,
        masterCoherenceSheetUrl: gridResult.masterCoherenceSheetUrl,
        generatedShots,
        qaReport: qaResult.report,
        exportPackageUrl: exportResult.exportPackageUrl,
      };

      // Clear partial results after successful completion
      this.errorHandler.clearPartialResults(project.id);

      return results;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      
      // Save partial results on failure
      if (this.currentStage) {
        const generationError = createGenerationError(
          this.currentStage,
          errorMessage,
          undefined,
          true
        );

        this.errorHandler.savePartialResults(
          project.id,
          [],
          [],
          undefined,
          generationError
        );
      }

      onProgress?.({
        stage: 'error',
        progress: 0,
        error: errorMessage,
        startTime: this.startTime,
      });

      onError?.({
        stage: this.currentStage || 'grid',
        message: getUserFriendlyErrorMessage(error as Error),
        retryable: true,
      });

      return null;
    } finally {
      this.abortController = null;
      this.currentStage = null;
    }
  }

  /**
   * Cancel ongoing generation
   * Requirements: 8.5
   */
  cancel(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
  }

  /**
   * Check if generation is in progress
   */
  isGenerating(): boolean {
    return this.abortController !== null;
  }

  // ============================================================================
  // Pipeline Stage Implementations
  // ============================================================================

  /**
   * Stage 1: Generate Master Coherence Sheet (3x3 grid)
   * Requirements: 3.3
   */
  private async generateMasterCoherenceSheet(
    project: Project
  ): Promise<GridGenerationResult> {
    this.checkAborted();

    // Call backend to generate grid
    const response = await this.backendApi.invokeCliCommand('grid', {
      project: project.name,
    });

    if (!response.success) {
      throw new Error(response.error || 'Failed to generate Master Coherence Sheet');
    }

    // Extract grid result from response
    const gridUrl = response.data?.gridUrl || `/projects/${project.name}/grid.png`;
    const gridImages = response.data?.gridImages || [];

    return {
      masterCoherenceSheetUrl: gridUrl,
      gridImages,
      generatedAt: Date.now(),
    };
  }

  /**
   * Stage 2: Generate shots with ComfyUI
   * Requirements: 3.4
   */
  private async generateWithComfyUI(
    project: Project,
    gridResult: GridGenerationResult,
    onShotProgress: (shotIndex: number) => void
  ): Promise<ComfyUIResult> {
    this.checkAborted();

    const outputs: Array<{ shotId: string; imageUrl: string }> = [];

    // Process each shot through ComfyUI
    for (let i = 0; i < project.shots.length; i++) {
      this.checkAborted();

      const shot = project.shots[i];
      onShotProgress(i);

      // Submit ComfyUI workflow for this shot
      const workflowResponse = await this.backendApi.submitComfyUIWorkflow({
        workflowId: 'image-generation',
        inputs: {
          prompt: shot.prompt,
          width: 512,
          height: 512,
          seed: -1,
          masterCoherenceSheet: gridResult.masterCoherenceSheetUrl,
        },
      });

      if (!workflowResponse.success || !workflowResponse.data) {
        throw new Error(`Failed to generate shot ${shot.id}: ${workflowResponse.error}`);
      }

      // Poll for completion
      const result = await this.pollComfyUICompletion(workflowResponse.data.promptId);
      
      if (result.outputs && result.outputs.length > 0) {
        outputs.push({
          shotId: shot.id,
          imageUrl: result.outputs[0].url,
        });
      }
    }

    return {
      promptId: `batch-${Date.now()}`,
      outputs,
    };
  }

  /**
   * Poll ComfyUI for workflow completion
   */
  private async pollComfyUICompletion(promptId: string): Promise<any> {
    const maxAttempts = 60; // 5 minutes with 5 second intervals
    const pollInterval = 5000;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      this.checkAborted();

      const statusResponse = await this.backendApi.getComfyUIStatus(promptId);
      
      if (!statusResponse.success || !statusResponse.data) {
        throw new Error('Failed to get ComfyUI status');
      }

      const status = statusResponse.data;

      if (status.status === 'completed') {
        return status;
      }

      if (status.status === 'failed') {
        throw new Error(status.error || 'ComfyUI workflow failed');
      }

      // Wait before next poll
      await this.delay(pollInterval);
    }

    throw new Error('ComfyUI workflow timeout');
  }

  /**
   * Stage 3a: Promote shots through StoryCore pipeline
   * Requirements: 3.5
   */
  private async promoteShots(
    comfyuiResult: ComfyUIResult,
    onShotProgress: (shotIndex: number) => void
  ): Promise<PromotionResult> {
    this.checkAborted();

    const promotedShots: Array<{
      shotId: string;
      imageUrl: string;
      processingTime: number;
    }> = [];

    for (let i = 0; i < comfyuiResult.outputs.length; i++) {
      this.checkAborted();

      const output = comfyuiResult.outputs[i];
      onShotProgress(i);

      const startTime = Date.now();

      // Call promotion engine
      const response = await this.backendApi.invokeCliCommand('promote', {
        shotId: output.shotId,
        imageUrl: output.imageUrl,
      });

      if (!response.success) {
        throw new Error(`Failed to promote shot ${output.shotId}: ${response.error}`);
      }

      const processingTime = Date.now() - startTime;

      promotedShots.push({
        shotId: output.shotId,
        imageUrl: response.data?.promotedUrl || output.imageUrl,
        processingTime,
      });
    }

    return { promotedShots };
  }

  /**
   * Stage 3b: Run QA analysis and autofix
   * Requirements: 3.5
   */
  private async runQAAnalysis(promotionResult: PromotionResult): Promise<QAResult> {
    this.checkAborted();

    // Call QA engine
    const response = await this.backendApi.invokeCliCommand('qa', {
      shots: promotionResult.promotedShots,
    });

    if (!response.success) {
      throw new Error(`QA analysis failed: ${response.error}`);
    }

    const qaData = response.data || {};

    const report: QAReport = {
      overallScore: qaData.overallScore || 0,
      shotScores: qaData.shotScores || [],
      autofixApplied: qaData.autofixApplied || false,
    };

    return {
      report,
      autofixApplied: report.autofixApplied,
    };
  }

  /**
   * Stage 4: Export results
   * Requirements: 3.5
   */
  private async exportResults(
    project: Project,
    gridResult: GridGenerationResult,
    promotionResult: PromotionResult,
    qaResult: QAResult
  ): Promise<ExportResult> {
    this.checkAborted();

    // Call export engine
    const response = await this.backendApi.invokeCliCommand('export', {
      project: project.name,
      gridUrl: gridResult.masterCoherenceSheetUrl,
      shots: promotionResult.promotedShots,
      qaReport: qaResult.report,
    });

    if (!response.success) {
      throw new Error(`Export failed: ${response.error}`);
    }

    return {
      exportPackageUrl: response.data?.exportUrl || `/exports/${project.name}-${Date.now()}.zip`,
      timestamp: Date.now(),
    };
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Execute function with retry logic and exponential backoff
   * Requirements: 3.7, 9.5
   */
  private async executeWithRetry<T>(
    fn: () => Promise<T>,
    maxAttempts: number,
    delayMs: number,
    stage: PipelineStage,
    onError?: ErrorCallback
  ): Promise<T | null> {
    let attemptNumber = 1;

    while (attemptNumber <= maxAttempts) {
      try {
        this.checkAborted();
        return await fn();
      } catch (error) {
        const err = error instanceof Error ? error : new Error('Unknown error');

        // Don't retry if aborted
        if (this.abortController?.signal.aborted) {
          return null;
        }

        // Handle error with error handler
        const errorContext = {
          stage,
          timestamp: Date.now(),
          attemptNumber,
        };

        const handlerResult = this.errorHandler.handleError(err, errorContext);

        // Log error for debugging
        logError(err, errorContext);

        // Create generation error for callback
        const generationError = createGenerationError(
          stage,
          getUserFriendlyErrorMessage(err),
          undefined,
          handlerResult.canRetry
        );

        // Report error to callback
        onError?.(generationError);

        // Check if we should retry
        if (handlerResult.action === 'retry' && attemptNumber < maxAttempts) {
          // Wait before retry with exponential backoff
          const backoffDelay = handlerResult.suggestedDelay || delayMs * Math.pow(2, attemptNumber - 1);
          await this.delay(backoffDelay);
          attemptNumber++;
        } else {
          // No more retries, throw error
          throw err;
        }
      }
    }

    // Should not reach here, but throw error if we do
    throw new Error(`Stage ${stage} failed after ${maxAttempts} attempts`);
  }

  /**
   * Check if generation was aborted
   */
  private checkAborted(): void {
    if (this.abortController?.signal.aborted) {
      throw new Error('Generation cancelled');
    }
  }

  /**
   * Delay helper
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Estimate completion time based on current progress
   * Requirements: 8.3, 8.4
   */
  private estimateCompletion(currentProgress: number, totalShots: number): number {
    if (currentProgress === 0) {
      return 0;
    }

    const elapsed = Date.now() - this.startTime;
    const estimatedTotal = (elapsed / currentProgress) * 100;
    const remaining = estimatedTotal - elapsed;

    return Date.now() + remaining;
  }

  /**
   * Update backend API service
   */
  updateBackendApi(backendApi: BackendApiService): void {
    this.backendApi = backendApi;
  }

  /**
   * Get partial results for recovery
   * Requirements: 9.5
   */
  getPartialResults(projectId: string) {
    return this.errorHandler.loadPartialResults(projectId);
  }

  /**
   * Get error handler for advanced error management
   */
  getErrorHandler(): GenerationErrorHandler {
    return this.errorHandler;
  }
}

/**
 * Default sequence generation service instance
 */
export const sequenceGenerationService = new SequenceGenerationService();

/**
 * Sequence Plan Service
 * 
 * Provides services for managing sequence plans:
 * - CRUD operations (Create, Read, Update, Delete)
 * - Import/Export with validation
 * - Auto-save functionality
 * - Version history (future)
 * 
 * Task 7.7: Sequence Plan Services
 */

import type { SequencePlan } from '@/types/sequencePlan';
import type { Shot } from '@/types';

export interface SequencePlanData {
  id: string;
  name: string;
  description?: string;
  shots: Shot[];
  totalDuration: number;
  frameRate: number;
  resolution: { width: number; height: number };
  createdAt: number;
  modifiedAt: number;
  metadata?: Record<string, unknown>;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export interface ExportOptions {
  includeMetadata?: boolean;
  includeThumbnails?: boolean;
  format?: 'json' | 'csv';
}

/**
 * Callback type for sequence plan updates
 */
export type SequencePlanUpdateCallback = (planId: string, plan: SequencePlanData) => void;

/**
 * Callback type for sequence plan list updates
 */
export type SequencePlanListUpdateCallback = (plans: SequencePlan[]) => void;

/**
 * Callback type for auto-save status updates
 */
export type AutoSaveStatusCallback = (enabled: boolean, lastSaveTime: number | null) => void;

/**
 * Sequence Plan Service Class
 * 
 * Now with Observer pattern for real-time synchronization
 */
export class SequencePlanService {
  private static instance: SequencePlanService;
  private autoSaveInterval: NodeJS.Timeout | null = null;
  private lastSaveTime: number | null = null;
  private isDirty: boolean = false;
  
  // Subscribers for different events
  private planUpdateSubscribers: Set<SequencePlanUpdateCallback> = new Set();
  private planListSubscribers: Set<SequencePlanListUpdateCallback> = new Set();
  private autoSaveStatusSubscribers: Set<AutoSaveStatusCallback> = new Set();

  private constructor() {
  }

  /**
   * Get singleton instance
   */
  public static getInstance(): SequencePlanService {
    if (!SequencePlanService.instance) {
      SequencePlanService.instance = new SequencePlanService();
    }
    return SequencePlanService.instance;
  }

  /**
   * Subscribe to plan updates
   * Returns unsubscribe function
   */
  public subscribeToPlanUpdates(callback: SequencePlanUpdateCallback): () => void {
    this.planUpdateSubscribers.add(callback);
    return () => {
      this.planUpdateSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to plan list updates
   * Returns unsubscribe function
   */
  public subscribeToPlanList(callback: SequencePlanListUpdateCallback): () => void {
    this.planListSubscribers.add(callback);
    return () => {
      this.planListSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to auto-save status updates
   * Returns unsubscribe function
   */
  public subscribeToAutoSaveStatus(callback: AutoSaveStatusCallback): () => void {
    this.autoSaveStatusSubscribers.add(callback);
    return () => {
      this.autoSaveStatusSubscribers.delete(callback);
    };
  }

  /**
   * Notify subscribers of plan update
   */
  private notifyPlanUpdate(planId: string, plan: SequencePlanData): void {
    this.planUpdateSubscribers.forEach(callback => {
      try {
        callback(planId, plan);
      } catch (error) {
        console.error('[DEBUG] Error in plan update subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of plan list update
   */
  private async notifyPlanListUpdate(): Promise<void> {
    const plans = await this.listSequencePlans();
    this.planListSubscribers.forEach(callback => {
      try {
        callback(plans);
      } catch (error) {
        console.error('[DEBUG] Error in plan list subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of auto-save status change
   */
  private notifyAutoSaveStatus(): void {
    const enabled = this.autoSaveInterval !== null;
    this.autoSaveStatusSubscribers.forEach(callback => {
      try {
        callback(enabled, this.lastSaveTime);
      } catch (error) {
        console.error('[SequencePlanService] Error in auto-save status subscriber:', error);
      }
    });
  }

  /**
   * Create a new sequence plan
   */
  public async createSequencePlan(
    name: string,
    description?: string
  ): Promise<SequencePlanData> {
    const now = Date.now();
    const plan: SequencePlanData = {
      id: this.generateId(),
      name,
      description,
      shots: [],
      totalDuration: 0,
      frameRate: 30,
      resolution: { width: 1920, height: 1080 },
      createdAt: now,
      modifiedAt: now,
      metadata: {},
    };

    // Save to storage
    await this.savePlan(plan);

    return plan;
  }

  /**
   * Load a sequence plan by ID
   */
  public async loadSequencePlan(planId: string): Promise<SequencePlanData | null> {
    try {
      // In a real implementation, this would load from file system or database
      // For now, we'll use localStorage as a mock
      const stored = localStorage.getItem(`sequence-plan-${planId}`);
      if (!stored) return null;

      const plan = JSON.parse(stored) as SequencePlanData;
      return plan;
    } catch (error) {
      console.error('Failed to load sequence plan:', error);
      return null;
    }
  }

  /**
   * Update a sequence plan
   */
  public async updateSequencePlan(
    planId: string,
    updates: Partial<SequencePlanData>
  ): Promise<SequencePlanData> {
    const plan = await this.loadSequencePlan(planId);
    if (!plan) {
      throw new Error(`Sequence plan not found: ${planId}`);
    }

    const updatedPlan: SequencePlanData = {
      ...plan,
      ...updates,
      modifiedAt: Date.now(),
    };

    await this.savePlan(updatedPlan);
    this.markDirty();

    // Notify subscribers
    this.notifyPlanUpdate(planId, updatedPlan);
    await this.notifyPlanListUpdate();

    return updatedPlan;
  }

  /**
   * Delete a sequence plan
   */
  public async deleteSequencePlan(planId: string): Promise<void> {
    try {
      localStorage.removeItem(`sequence-plan-${planId}`);
      
      // Remove from plan list
      const planList = await this.listSequencePlans();
      const updatedList = planList.filter((p) => p.id !== planId);
      localStorage.setItem('sequence-plan-list', JSON.stringify(updatedList));

      // Notify subscribers
      await this.notifyPlanListUpdate();
    } catch (error) {
      console.error('Failed to delete sequence plan:', error);
      throw new Error('Failed to delete sequence plan');
    }
  }

  /**
   * Duplicate a sequence plan
   */
  public async duplicateSequencePlan(planId: string): Promise<SequencePlanData> {
    const plan = await this.loadSequencePlan(planId);
    if (!plan) {
      throw new Error(`Sequence plan not found: ${planId}`);
    }

    // Generate unique name
    const copyName = this.generateUniqueName(plan.name);

    const now = Date.now();
    const duplicatedPlan: SequencePlanData = {
      ...plan,
      id: this.generateId(),
      name: copyName,
      createdAt: now,
      modifiedAt: now,
      // Deep copy shots
      shots: plan.shots.map((shot) => ({
        ...shot,
        id: this.generateId(),
      })),
    };

    await this.savePlan(duplicatedPlan);

    // Notify subscribers
    this.notifyPlanUpdate(duplicatedPlan.id, duplicatedPlan);
    await this.notifyPlanListUpdate();

    return duplicatedPlan;
  }

  /**
   * List all sequence plans
   */
  public async listSequencePlans(): Promise<SequencePlan[]> {
    try {
      const stored = localStorage.getItem('sequence-plan-list');
      if (!stored) return [];

      const planList = JSON.parse(stored) as SequencePlan[];
      return planList;
    } catch (error) {
      console.error('Failed to list sequence plans:', error);
      return [];
    }
  }

  /**
   * Export a sequence plan to JSON
   */
  public async exportSequencePlan(
    planId: string,
    options: ExportOptions = {}
  ): Promise<string> {
    const plan = await this.loadSequencePlan(planId);
    if (!plan) {
      throw new Error(`Sequence plan not found: ${planId}`);
    }

    const {
      includeMetadata = true,
      includeThumbnails = true,
      format = 'json',
    } = options;

    // Prepare export data
    const exportData: unknown = {
      ...plan,
    };

    // Remove metadata if not included
    if (!includeMetadata) {
      delete exportData.metadata;
    }

    // Remove thumbnails if not included
    if (!includeThumbnails) {
      exportData.shots = exportData.shots.map((shot: Shot) => {
        const { image, ...shotWithoutImage } = shot;
        return shotWithoutImage;
      });
    }

    if (format === 'json') {
      return JSON.stringify(exportData, null, 2);
    } else {
      // CSV format (simplified)
      throw new Error('CSV export not yet implemented');
    }
  }

  /**
   * Import a sequence plan from JSON
   */
  public async importSequencePlan(jsonData: string): Promise<SequencePlanData> {
    // Validate JSON
    const validation = this.validateSequencePlan(jsonData);
    if (!validation.valid) {
      throw new Error(`Invalid sequence plan: ${validation.errors.join(', ')}`);
    }

    const plan = JSON.parse(jsonData) as SequencePlanData;

    // Generate new ID to avoid conflicts
    plan.id = this.generateId();
    plan.createdAt = Date.now();
    plan.modifiedAt = Date.now();

    // Generate new IDs for shots
    plan.shots = plan.shots.map((shot) => ({
      ...shot,
      id: this.generateId(),
    }));

    await this.savePlan(plan);

    // Notify subscribers
    this.notifyPlanUpdate(plan.id, plan);
    await this.notifyPlanListUpdate();

    return plan;
  }

  /**
   * Validate a sequence plan JSON
   */
  public validateSequencePlan(jsonData: string): ValidationResult {
    const errors: string[] = [];

    try {
      const plan = JSON.parse(jsonData);

      // Required fields
      if (!plan.id) errors.push('Missing required field: id');
      if (!plan.name) errors.push('Missing required field: name');
      if (!Array.isArray(plan.shots)) errors.push('Missing or invalid field: shots');
      if (typeof plan.totalDuration !== 'number') {
        errors.push('Missing or invalid field: totalDuration');
      }
      if (typeof plan.frameRate !== 'number') {
        errors.push('Missing or invalid field: frameRate');
      }
      if (!plan.resolution || typeof plan.resolution.width !== 'number' || typeof plan.resolution.height !== 'number') {
        errors.push('Missing or invalid field: resolution');
      }

      // Validate shots
      if (Array.isArray(plan.shots)) {
        plan.shots.forEach((shot: unknown, index: number) => {
          if (!shot.id) errors.push(`Shot ${index}: Missing required field: id`);
          if (!shot.title) errors.push(`Shot ${index}: Missing required field: title`);
          if (typeof shot.duration !== 'number') {
            errors.push(`Shot ${index}: Missing or invalid field: duration`);
          }
        });
      }
    } catch (error) {
      errors.push('Invalid JSON format');
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Enable auto-save
   */
  public enableAutoSave(intervalMs: number = 30000): void {
    if (this.autoSaveInterval) {
      clearInterval(this.autoSaveInterval);
    }

    this.autoSaveInterval = setInterval(() => {
      if (this.isDirty) {
        this.saveCurrentPlan();
      }
    }, intervalMs);

    // Notify subscribers
    this.notifyAutoSaveStatus();
  }

  /**
   * Disable auto-save
   */
  public disableAutoSave(): void {
    if (this.autoSaveInterval) {
      clearInterval(this.autoSaveInterval);
      this.autoSaveInterval = null;
    }

    // Notify subscribers
    this.notifyAutoSaveStatus();
  }

  /**
   * Get last save time
   */
  public getLastSaveTime(): number | null {
    return this.lastSaveTime;
  }

  /**
   * Mark plan as dirty (needs saving)
   */
  public markDirty(): void {
    this.isDirty = true;
  }

  /**
   * Save current plan (called by auto-save)
   */
  private async saveCurrentPlan(): Promise<void> {
    // This would be implemented to save the current active plan
    // For now, we'll just mark as clean
    this.isDirty = false;
    this.lastSaveTime = Date.now();
  }

  /**
   * Save a plan to storage
   */
  private async savePlan(plan: SequencePlanData): Promise<void> {
    try {
      // Save plan data
      localStorage.setItem(`sequence-plan-${plan.id}`, JSON.stringify(plan));

      // Update plan list
      const planList = await this.listSequencePlans();
      const existingIndex = planList.findIndex((p) => p.id === plan.id);

      const planSummary: SequencePlan = {
        id: plan.id,
        name: plan.name,
        description: plan.description || '',
        worldId: plan.metadata?.worldId || '',
        templateId: plan.metadata?.templateId,
        targetDuration: plan.totalDuration,
        frameRate: plan.frameRate,
        resolution: plan.resolution,
        acts: [],
        scenes: [],
        shots: [], // Empty array since we're just creating a summary
        createdAt: plan.createdAt,
        modifiedAt: plan.modifiedAt,
        status: 'draft',
        tags: [],
      };

      if (existingIndex >= 0) {
        planList[existingIndex] = planSummary;
      } else {
        planList.push(planSummary);
      }

      localStorage.setItem('sequence-plan-list', JSON.stringify(planList));

      this.lastSaveTime = Date.now();
      this.isDirty = false;

      // Notify subscribers
      this.notifyPlanUpdate(plan.id, plan);
      await this.notifyPlanListUpdate();
    } catch (error) {
      console.error('Failed to save sequence plan:', error);
      throw new Error('Failed to save sequence plan');
    }
  }

  /**
   * Generate unique ID
   */
  private generateId(): string {
    return `plan-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
  }

  /**
   * Generate unique name for duplicated plan
   */
  private generateUniqueName(baseName: string): string {
    const copyMatch = baseName.match(/^(.+?)\s*\(Copy(?:\s+(\d+))?\)$/);
    
    if (copyMatch) {
      const [, name, num] = copyMatch;
      const nextNum = num ? parseInt(num, 10) + 1 : 2;
      return `${name} (Copy ${nextNum})`;
    }
    
    return `${baseName} (Copy)`;
  }
}

