}

/**
 * Get queue statistics
 */
export async function getQueueStats(projectId?: string): Promise<QueueStatsResponse> {
  const params = projectId ? `?project_id=${projectId}` : '';
  const response = await fetchWithAuth(`/api/tasks/stats${params}`);
  
  if (!response.ok) {
