/**
 * Get status badge color based on status
 */
export function getStatusColor(status: string): string {
  switch (status) {
    case 'pending':
      return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50';
    case 'processing':
      return 'bg-blue-500/20 text-blue-400 border-blue-500/50 animate-pulse';
    case 'completed':
      return 'bg-green-500/20 text-green-400 border-green-500/50';
    case 'failed':
      return 'bg-red-500/20 text-red-400 border-red-500/50';
    case 'cancelled':
      return 'bg-gray-500/20 text-gray-400 border-gray-500/50';
    default:
      return 'bg-gray-500/20 text-gray-400 border-gray-500/50';
  }
}

/**
 * Get priority badge color
 */
export function getPriorityColor(priority: number): string {
  if (priority <= 2) {
    return 'bg-red-500/20 text-red-400 border-red-500/50'; // High priority
  } else if (priority <= 4) {
    return 'bg-orange-500/20 text-orange-400 border-orange-500/50'; // Medium-high
  } else if (priority <= 6) {
    return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50'; // Medium
  } else if (priority <= 8) {
    return 'bg-blue-500/20 text-blue-400 border-blue-500/50'; // Medium-low
  } else {
    return 'bg-gray-500/20 text-gray-400 border-gray-500/50'; // Low priority
  }
}

/**
 * Format estimated time
 */
export function formatEstimatedTime(seconds?: number | null): string {
  if (!seconds) return '-';
  
  if (seconds < 60) {
    return `${seconds}s`;
  } else if (seconds < 3600) {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}m ${remainingSeconds}s`;
  } else {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  }
}

/**
 * Get status icon
 */
export function getStatusIcon(status: string): string {
  switch (status) {
    case 'pending':
      return '⏳';
    case 'processing':
      return '⚙️';
    case 'completed':
      return '✅';
    case 'failed':
      return '❌';
    case 'cancelled':
      return '🚫';
    default:
      return '📋';
  }
}

/**
 * Get priority icon
 */
export function getPriorityIcon(priority: number): string {
  if (priority <= 2) return '🔴';
  if (priority <= 4) return '🟠';
  if (priority <= 6) return '🟡';
  if (priority <= 8) return '🔵';
  return '⚪';
}

export default {
  getTaskQueue,
  updateJobPriority,
  moveJobUp,
  moveJobDown,
  retryJob,
  getQueueStats,
  deleteJob,
  getStatusColor,
  getPriorityColor,
  formatEstimatedTime,
  getStatusIcon,
  getPriorityIcon,
};

