/**
 * Transcription Service - Frontend for Transcription Engine
 * Audio transcription and text-based montage
 */

import { backendApiService } from './backendApiService';
import { logger } from '@/utils/logger';

export type SegmentType = 'dialogue' | 'narration' | 'music' | 'sound-effect' | 'silence';
export type MontageStyle = 'chronological' | 'highlights' | 'compact' | 'conversation';

export interface SpeakerInfo {
  speakerId: string;
  speakerLabel: string;
  confidence: number;
}

export interface WordTimestamp {
  word: string;
  start: number;
  end: number;
  confidence: number;
}

export interface TranscriptSegment {
  segmentId: string;
  startTime: number;
  endTime: number;
  text: string;
  speaker: SpeakerInfo | null;
  confidence: number;
  words: WordTimestamp[];
  segmentType: SegmentType;
}

export interface Transcript {
  transcriptId: string;
  audioId: string;
  language: string;
  duration: number;
  segments: TranscriptSegment[];
  createdAt: string;
  speakerCount: number;
  wordCount: number;
  languageConfidence: number;
}

export interface MontageRequest {
  transcriptId: string;
  style: MontageStyle;
  includeSpeakers?: string[];
  excludeSpeakers?: string[];
  maxDuration?: number;
  preserveTiming?: boolean;
  addTransitions?: boolean;
}

export interface MontageShot {
  shotId: string;
  sourceStart: number;
  sourceEnd: number;
  text: string;
  speaker: string | null;
  shotType: string;
  duration: number;
  order: number;
}

export interface MontageResult {
  resultId: string;
  transcriptId: string;
  style: MontageStyle;
  shots: MontageShot[];
  totalDuration: number;
  wordCount: number;
  createdAt: string;
  summary: string;
}

export interface TranscriptionService {
  transcribe(
    audioId: string,
    audioUrl: string,
    language?: string,
    enableSpeakerDiarization?: boolean
  ): Promise<Transcript>;
  generateMontage(request: MontageRequest): Promise<MontageResult>;
  exportSrt(transcriptId: string): Promise<string>;
  exportVtt(transcriptId: string): Promise<string>;
  exportAss(transcriptId: string): Promise<string>;
  getTranscript(transcriptId: string): Promise<Transcript | null>;
  getMontage(resultId: string): Promise<MontageResult | null>;
}

class TranscriptionServiceImpl implements TranscriptionService {
  private baseUrl = '/api/v1/transcription';
  private transcriptCache: Map<string, { transcript: Transcript; timestamp: number }> = new Map();
  private montageCache: Map<string, { result: MontageResult; timestamp: number }> = new Map();
  private cacheTTL = 10 * 60 * 1000; // 10 minutes

  async transcribe(
    audioId: string,
    audioUrl: string,
    language?: string,
    enableSpeakerDiarization: boolean = true
  ): Promise<Transcript> {
    // Check cache with TTL
    const cacheKey = `transcript:${audioId}`;
    const cached = this.transcriptCache.get(cacheKey);
    
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      logger.debug(`[Transcription] Cache hit for: ${audioId}`);
      return cached.transcript;
    }

    try {
      logger.debug(`[Transcription] Starting transcription: ${audioUrl}`);

      const response = await backendApiService.post<Transcript>(
        `${this.baseUrl}/transcribe`,
        {
          audioId,
          audioUrl,
          language,
          enableSpeakerDiarization
        }
      );

      // Cache with timestamp
      this.transcriptCache.set(cacheKey, {
        transcript: response,
        timestamp: Date.now()
      });

      logger.debug(`[Transcription] Complete: ${response.wordCount} words, ${response.speakerCount} speakers`);
      return response;
    } catch (error) {
      logger.error('[Transcription] Failed:', error);
      throw error;
    }
  }

  async generateMontage(request: MontageRequest): Promise<MontageResult> {
    try {
      logger.debug(`[Transcription] Generating ${request.style} montage`);

      const response = await backendApiService.post<MontageResult>(
        `${this.baseUrl}/generate-montage`,
        request
      );

      // Cache with timestamp
      this.montageCache.set(response.resultId, {
        result: response,
        timestamp: Date.now()
      });

      logger.debug(`[Transcription] Montage complete: ${response.shots.length} shots, ${response.totalDuration.toFixed(1)}s`);
      return response;
    } catch (error) {
      logger.error('[Transcription] Montage generation failed:', error);
      throw error;
    }
  }

  async exportSrt(transcriptId: string): Promise<string> {
    try {
      return await backendApiService.get<string>(
        `${this.baseUrl}/${transcriptId}/export/srt`
      );
    } catch (error) {
      logger.error('[Transcription] SRT export failed:', error);
      throw error;
    }
  }

  async exportVtt(transcriptId: string): Promise<string> {
    try {
      return await backendApiService.get<string>(
        `${this.baseUrl}/${transcriptId}/export/vtt`
      );
    } catch (error) {
      logger.error('[Transcription] VTT export failed:', error);
      throw error;
    }
  }

  async exportAss(transcriptId: string): Promise<string> {
    try {
      return await backendApiService.get<string>(
        `${this.baseUrl}/${transcriptId}/export/ass`
      );
    } catch (error) {
      logger.error('[Transcription] ASS export failed:', error);
      throw error;
    }
  }

  async getTranscript(transcriptId: string): Promise<Transcript | null> {
    // Check cache with TTL
    for (const [key, cached] of this.transcriptCache.entries()) {
      if (cached.transcript.transcriptId === transcriptId || cached.transcript.audioId === transcriptId) {
        if (Date.now() - cached.timestamp < this.cacheTTL) {
          return cached.transcript;
        }
      }
    }

    try {
      const response = await backendApiService.get<Transcript>(
        `${this.baseUrl}/${transcriptId}`
      );

      this.transcriptCache.set(response.audioId, {
        transcript: response,
        timestamp: Date.now()
      });
      return response;
    } catch (error) {
      logger.error('[Transcription] Get transcript failed:', error);
      return null;
    }
  }

  async getMontage(resultId: string): Promise<MontageResult | null> {
    // Check cache with TTL
    const cached = this.montageCache.get(resultId);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.result;
    }

    try {
      const response = await backendApiService.get<MontageResult>(
        `${this.baseUrl}/montage/${resultId}`
      );

      this.montageCache.set(resultId, {
        result: response,
        timestamp: Date.now()
      });
      return response;
    } catch (error) {
      logger.error('[Transcription] Get montage failed:', error);
      return null;
    }
  }

  /**
   * Parse an imported SRT file
   */
  parseSrt(content: string): Array<{ start: number; end: number; text: string }> {
    const segments: Array<{ start: number; end: number; text: string }> = [];
    const blocks = content.trim().split(/\n\n+/);

    for (const block of blocks) {
      const lines = block.split('\n');
      if (lines.length < 3) continue;

      // Parser le temps
      const timeLine = lines[1];
      const [startStr, endStr] = timeLine.split(' --> ');
      
      const start = this.parseTimeCode(startStr.trim());
      const end = this.parseTimeCode(endStr.trim());

      // Parser le texte
      const text = lines.slice(2).join('\n');

      segments.push({ start, end, text });
    }

    return segments;
  }

  /**
   * Parser un code temps SRT
   */
  private parseTimeCode(timeStr: string): number {
    // Format: HH:MM:SS,mmm ou HH:MM:SS.mmm
    const parts = timeStr.replace(',', '.').split(':');
    
    const hours = parseInt(parts[0], 10) || 0;
    const minutes = parseInt(parts[1], 10) || 0;
    const seconds = parseFloat(parts[2]) || 0;

    return hours * 3600 + minutes * 60 + seconds;
  }

  /**
   * Formater en mm:ss
   */
  formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  }

  /**
   * Rechercher dans la transcription
   */
  searchInTranscript(transcript: Transcript, query: string): TranscriptSegment[] {
    const queryLower = query.toLowerCase();
    
    return transcript.segments.filter(segment =>
      segment.text.toLowerCase().includes(queryLower)
    );
  }

  /**
   * Obtenir les segments par locuteur
   */
  getSegmentsBySpeaker(transcript: Transcript): Record<string, TranscriptSegment[]> {
    const bySpeaker: Record<string, TranscriptSegment[]> = {};

    for (const segment of transcript.segments) {
      const speakerId = segment.speaker?.speakerLabel || 'Unknown';
      
      if (!bySpeaker[speakerId]) {
        bySpeaker[speakerId] = [];
      }
      bySpeaker[speakerId].push(segment);
    }

    return bySpeaker;
  }

  /**
   * Effacer les caches
   */
  clearCaches(): void {
    this.transcriptCache.clear();
    this.montageCache.clear();
  }
}

export const transcriptionService = new TranscriptionServiceImpl();

/**
 * WebGL Transition Engine for StoryCore
 * GPU-accelerated shader-based transitions with performance optimization
 */

import {
  TransitionConfig,
  TransitionState,
  TransitionMetrics,
  ShaderProgram,
  ShaderUniforms,
  TransitionFrameData,
  TransitionCanvasOptions,
  GPUMode,
  PerformanceTier,
  TransitionPreset,
  TransitionCategory,
  FadeTransitionConfig,
  SlideTransitionConfig,
  ZoomTransitionConfig,
  WipeTransitionConfig,
  GlitchTransitionConfig,
  CustomTransitionConfig,
} from './TransitionTypes';

// ============================================
// WebGL Context Management
// ============================================

export class WebGLRenderer {
  private gl: WebGLRenderingContext | null = null;
  private canvas: HTMLCanvasElement | null = null;
  private programs: Map<string, WebGLProgram> = new Map();
  private textures: Map<string, WebGLTexture> = new Map();
  private framebuffers: Map<string, WebGLFramebuffer> = new Map();
  private buffers: Map<string, WebGLBuffer> = new Map();
  private extentions: Map<string, any> = new Map();
  private width: number = 0;
  private height: number = 0;
  private gpuMode: GPUMode = 'auto';
  private performanceTier: PerformanceTier = 'high';
  private isInitialized: boolean = false;

  constructor(canvas: HTMLCanvasElement, options?: Partial<TransitionCanvasOptions>) {
    this.canvas = canvas;
    this.width = options?.width || canvas.width;
    this.height = options?.height || canvas.height;
    this.initializeContext(options?.glAttributes);
  }

  private initializeContext(attributes?: WebGLContextAttributes): void {
    if (!this.canvas) return;

    const defaultAttributes: WebGLContextAttributes = {
      antialias: attributes?.antialias ?? true,
      alpha: attributes?.alpha ?? false,
      depth: attributes?.depth ?? true,
      stencil: attributes?.stencil ?? false,
      preserveDrawingBuffer: attributes?.preserveDrawingBuffer ?? false,
      premultipliedAlpha: attributes?.premultipliedAlpha ?? false,
    };

    // Try WebGL2 first, fallback to WebGL1
    this.gl = (this.canvas.getContext('webgl2', defaultAttributes) ||
              this.canvas.getContext('webgl', defaultAttributes) ||
              this.canvas.getContext('experimental-webgl', defaultAttributes)) as WebGLRenderingContext | null;

    if (!this.gl) {
      console.warn('WebGL not supported, falling back to CSS transitions');
      this.gpuMode = 'disabled';
      return;
    }

    this.setupExtensions();
    this.setupBuffers();
    this.isInitialized = true;
  }

  private setupExtensions(): void {
    if (!this.gl) return;

    // Get commonly used extensions
    const ext = this.gl.getExtension('OES_texture_float');
    if (ext) this.extentions.set('OES_texture_float', ext);

    const extLinear = this.gl.getExtension('OES_texture_float_linear');
    if (extLinear) this.extentions.set('OES_texture_float_linear', extLinear);

    const extAnisotropic = this.gl.getExtension('EXT_texture_filter_anisotropic');
    if (extAnisotropic) this.extentions.set('EXT_texture_filter_anisotropic', extAnisotropic);
  }

  private setupBuffers(): void {
    if (!this.gl) return;

    // Create fullscreen quad buffer
    const positions = new Float32Array([
      -1, -1,
       1, -1,
      -1,  1,
       1,  1,
    ]);

    const buffer = this.gl.createBuffer();
    if (buffer) {
      this.gl.bindBuffer(this.gl.ARRAY_BUFFER, buffer);
      this.gl.bufferData(this.gl.ARRAY_BUFFER, positions, this.gl.STATIC_DRAW);
      this.buffers.set('quad', buffer);
    }

    // Create index buffer for triangle strip
    const indices = new Uint16Array([0, 1, 2, 3]);
    const indexBuffer = this.gl.createBuffer();
    if (indexBuffer) {
      this.gl.bindBuffer(this.gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
      this.gl.bufferData(this.gl.ELEMENT_ARRAY_BUFFER, indices, this.gl.STATIC_DRAW);
      this.buffers.set('indices', indexBuffer);
    }
  }

  // ============================================
  // Shader Management
  // ============================================

  compileShader(type: number, source: string): WebGLShader | null {
    if (!this.gl) return null;

    const shader = this.gl.createShader(type);
    if (!shader) return null;

    this.gl.shaderSource(shader, source);
    this.gl.compileShader(shader);

    if (!this.gl.getShaderParameter(shader, this.gl.COMPILE_STATUS)) {
      console.error('Shader compile error:', this.gl.getShaderInfoLog(shader));
      this.gl.deleteShader(shader);
      return null;
    }

    return shader;
  }

  createProgram(vertexShader: string, fragmentShader: string): WebGLProgram | null {
    if (!this.gl) return null;

    const vs = this.compileShader(this.gl.VERTEX_SHADER, vertexShader);
    const fs = this.compileShader(this.gl.FRAGMENT_SHADER, fragmentShader);

    if (!vs || !fs) return null;

    const program = this.gl.createProgram();
    if (!program) return null;

    this.gl.attachShader(program, vs);
    this.gl.attachShader(program, fs);
    this.gl.linkProgram(program);

    if (!this.gl.getProgramParameter(program, this.gl.LINK_STATUS)) {
      console.error('Program link error:', this.gl.getProgramInfoLog(program));
      this.gl.deleteProgram(program);
      return null;
    }

    return program;
  }

  useProgram(program: WebGLProgram | null): void {
    if (!this.gl) return;
    this.gl.useProgram(program);
  }

  getUniformLocation(program: WebGLProgram, name: string): WebGLUniformLocation | null {
    if (!this.gl) return null;
    return this.gl.getUniformLocation(program, name);
  }

  getAttribLocation(program: WebGLProgram, name: string): number {
    if (!this.gl) return -1;
    return this.gl.getAttribLocation(program, name);
  }

  // ============================================
  // Texture Management
  // ============================================

  createTexture(
    source: HTMLCanvasElement | HTMLVideoElement | ImageBitmap,
    id: string
  ): WebGLTexture | null {
    if (!this.gl) return null;

    const texture = this.gl.createTexture();
    if (!texture) return null;

    this.gl.bindTexture(this.gl.TEXTURE_2D, texture);
    this.gl.texImage2D(
      this.gl.TEXTURE_2D,
      0,
      this.gl.RGBA,
      this.gl.RGBA,
      this.gl.UNSIGNED_BYTE,
      source
    );

    // Set texture parameters for smooth scaling
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_WRAP_S, this.gl.CLAMP_TO_EDGE);
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_WRAP_T, this.gl.CLAMP_TO_EDGE);
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_MIN_FILTER, this.gl.LINEAR);
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_MAG_FILTER, this.gl.LINEAR);

    this.textures.set(id, texture);
    return texture;
  }

  updateTexture(
    source: HTMLCanvasElement | HTMLVideoElement | ImageBitmap,
    id: string
  ): void {
    if (!this.gl) return;

    const texture = this.textures.get(id);
    if (!texture) {
      this.createTexture(source, id);
      return;
    }

    this.gl.bindTexture(this.gl.TEXTURE_2D, texture);
    this.gl.texImage2D(
      this.gl.TEXTURE_2D,
      0,
      this.gl.RGBA,
      this.gl.RGBA,
      this.gl.UNSIGNED_BYTE,
      source
    );
  }

  bindTexture(texture: WebGLTexture, unit: number, id: string): void {
    if (!this.gl) return;

    this.gl.activeTexture(this.gl.TEXTURE0 + unit);
    this.gl.bindTexture(this.gl.TEXTURE_2D, texture);
    this.textures.set(id, texture);
  }

  deleteTexture(id: string): void {
    if (!this.gl) return;

    const texture = this.textures.get(id);
    if (texture) {
      this.gl.deleteTexture(texture);
      this.textures.delete(id);
    }
  }

  // ============================================
  // Framebuffer Management
  // ============================================

  createFramebuffer(id: string, width: number, height: number): WebGLFramebuffer | null {
    if (!this.gl) return null;

    const framebuffer = this.gl.createFramebuffer();
    if (!framebuffer) return null;

    this.gl.bindFramebuffer(this.gl.FRAMEBUFFER, framebuffer);

    // Create texture attachment
    const texture = this.gl.createTexture();
    this.gl.bindTexture(this.gl.TEXTURE_2D, texture);
    this.gl.texImage2D(
      this.gl.TEXTURE_2D,
      0,
      this.gl.RGBA,
      width,
      height,
      0,
      this.gl.RGBA,
      this.gl.UNSIGNED_BYTE,
      null
    );
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_MIN_FILTER, this.gl.LINEAR);
    this.gl.texParameteri(this.gl.TEXTURE_2D, this.gl.TEXTURE_MAG_FILTER, this.gl.LINEAR);
    this.gl.framebufferTexture2D(
      this.gl.FRAMEBUFFER,
      this.gl.COLOR_ATTACHMENT0,
      this.gl.TEXTURE_2D,
      texture,
      0
    );

    this.gl.bindFramebuffer(this.gl.FRAMEBUFFER, null);
    this.framebuffers.set(id, framebuffer);

    return framebuffer;
  }

  bindFramebuffer(framebuffer: WebGLFramebuffer | null): void {
    if (!this.gl) return;
    this.gl.bindFramebuffer(this.gl.FRAMEBUFFER, framebuffer);
  }

  // ============================================
  // Rendering
  // ============================================

  setViewport(width: number, height: number): void {
    if (!this.gl) return;
    this.gl.viewport(0, 0, width, height);
  }

  clear(color?: [number, number, number, number]): void {
    if (!this.gl) return;

    this.gl.clearColor(
      color ? color[0] : 0,
      color ? color[1] : 0,
      color ? color[2] : 0,
      color ? color[3] : 1
    );
    this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
  }

  drawQuad(): void {
    if (!this.gl) return;

    const buffer = this.buffers.get('quad');
    const indices = this.buffers.get('indices');

    if (!buffer || !indices) return;

    this.gl.bindBuffer(this.gl.ARRAY_BUFFER, buffer);
    this.gl.bindBuffer(this.gl.ELEMENT_ARRAY_BUFFER, indices);

    const positionLoc = 0; // Layout location in shader
    this.gl.enableVertexAttribArray(positionLoc);
    this.gl.vertexAttribPointer(positionLoc, 2, this.gl.FLOAT, false, 0, 0);

    this.gl.drawElements(this.gl.TRIANGLE_STRIP, 4, this.gl.UNSIGNED_SHORT, 0);
  }

  // ============================================
  // Performance & Optimization
  // ============================================

  setGPUMode(mode: GPUMode): void {
    this.gpuMode = mode;
  }

  setPerformanceTier(tier: PerformanceTier): void {
    this.performanceTier = tier;

    // Adjust based on tier
    switch (tier) {
      case 'low':
        this.gl?.disable(this.gl.DITHER);
        break;
      case 'medium':
      case 'high':
      case 'ultra':
        this.gl?.enable(this.gl.DITHER);
        break;
    }
  }

  getGPUMemoryUsage(): number {
    // This is a simplified estimation
    // Real GPU memory tracking requires browser-specific APIs
    let totalMemory = 0;

    this.textures.forEach((texture) => {
      // Rough estimation: 4 bytes per pixel * texture size
      // This is an approximation
      totalMemory += 4 * 1024 * 1024; // Assume 1MB per texture
    });

    return totalMemory;
  }

  // ============================================
  // Cleanup
  // ============================================

  destroy(): void {
    if (!this.gl) return;

    // Delete all programs
    this.programs.forEach((program) => this.gl?.deleteProgram(program));
    this.programs.clear();

    // Delete all textures
    this.textures.forEach((texture) => this.gl?.deleteTexture(texture));
    this.textures.clear();

    // Delete all framebuffers
    this.framebuffers.forEach((fb) => this.gl?.deleteFramebuffer(fb));
    this.framebuffers.clear();

    // Delete all buffers
    this.buffers.forEach((buffer) => this.gl?.deleteBuffer(buffer));
    this.buffers.clear();

    this.isInitialized = false;
  }

  // ============================================
  // Getters
  // ============================================

  getContext(): WebGLRenderingContext | null {
    return this.gl;
  }

  getWidth(): number {
    return this.width;
  }

  getHeight(): number {
    return this.height;
  }

  isReady(): boolean {
    return this.isInitialized && this.gl !== null;
  }

  getGPUMode(): GPUMode {
    return this.gpuMode;
  }

  getPerformanceTier(): PerformanceTier {
    return this.performanceTier;
  }
}

