/**
 * UndoRedoManager - Advanced Undo/Redo System
 * 
 * This class implements a comprehensive undo/redo system with:
 * - Undo/Redo stacks with configurable capacity
 * - FIFO eviction when capacity is reached
 * - Save point marking for tracking unsaved changes
 * - State cloning for immutability
 * - Action descriptions for UI display
 * 
 * Requirements: 7.1, 7.2, 7.3, 7.4, 7.7
 */

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * History entry containing state snapshot and metadata
 */
export interface HistoryEntry<T = any> {
  id: string;
  timestamp: number;
  description: string;
  state: T;
  inverseAction?: () => void;
}

/**
 * Configuration options for UndoRedoManager
 */
export interface UndoRedoConfig {
  maxStackSize?: number;
  enablePersistence?: boolean;
  storageKey?: string;
}

// ============================================================================
// UndoRedoManager Class
// ============================================================================

/**
 * Generic Undo/Redo Manager
 * 
 * @template T - The type of state being managed
 * 
 * @example
 * const manager = new UndoRedoManager(initialState, { maxStackSize: 50 });
 * manager.execute('Move shot', newState);
 * manager.undo();
 * manager.redo();
 */
export class UndoRedoManager<T = any> {
  private undoStack: HistoryEntry<T>[] = [];
  private redoStack: HistoryEntry<T>[] = [];
  private currentState: T;
  private maxStackSize: number;
  private savedStateId: string | null = null;
  private enablePersistence: boolean;
  private storageKey: string;

  /**
   * Create a new UndoRedoManager
   * 
   * @param initialState - The initial state to manage
   * @param config - Configuration options
   */
  constructor(initialState: T, config: UndoRedoConfig = {}) {
    this.currentState = this.cloneState(initialState);
    this.maxStackSize = config.maxStackSize || 50;
    this.enablePersistence = config.enablePersistence || false;
    this.storageKey = config.storageKey || 'undoRedoHistory';

    // Load persisted history if enabled
    if (this.enablePersistence) {
      this.loadHistory();
    }
  }

  // ============================================================================
  // Core Operations
  // ============================================================================

  /**
   * Execute a new action and save the previous state
   * 
   * Requirements: 7.1
   * 
   * @param description - Human-readable description of the action
   * @param newState - The new state after the action
   * @param inverseAction - Optional function to reverse the action
   */
  execute(description: string, newState: T, inverseAction?: () => void): void {
    // Create history entry with current state (before the change)
    const entry: HistoryEntry<T> = {
      id: this.generateId(),
      timestamp: Date.now(),
      description,
      state: this.cloneState(this.currentState),
      inverseAction
    };

    // Add to undo stack
    this.undoStack.push(entry);

    // Enforce max stack size with FIFO eviction (Requirement 7.4)
    if (this.undoStack.length > this.maxStackSize) {
      this.undoStack.shift();
    }

    // Clear redo stack when new action is executed (Requirement 7.5)
    this.redoStack = [];

    // Update current state
    this.currentState = this.cloneState(newState);

    // Persist if enabled
    if (this.enablePersistence) {
      this.saveHistory();
    }
  }

  /**
   * Undo the last action
   * 
   * Requirements: 7.2
   * 
   * @returns The restored state, or null if nothing to undo
   */
  undo(): T | null {
    if (this.undoStack.length === 0) {
      return null;
    }

    // Save current state to redo stack
    const redoEntry: HistoryEntry<T> = {
      id: this.generateId(),
      timestamp: Date.now(),
      description: `Redo: ${this.undoStack[this.undoStack.length - 1].description}`,
      state: this.cloneState(this.currentState)
    };
    this.redoStack.push(redoEntry);

    // Pop from undo stack
    const entry = this.undoStack.pop()!;

    // Execute inverse action if provided
    if (entry.inverseAction) {
      entry.inverseAction();
    }

    // Restore state
    this.currentState = this.cloneState(entry.state);

    // Persist if enabled
    if (this.enablePersistence) {
      this.saveHistory();
    }

    return this.currentState;
  }

  /**
   * Redo the last undone action
   * 
   * Requirements: 7.3
   * 
   * @returns The restored state, or null if nothing to redo
   */
  redo(): T | null {
    if (this.redoStack.length === 0) {
      return null;
    }

    // Save current state to undo stack
    const undoEntry: HistoryEntry<T> = {
      id: this.generateId(),
      timestamp: Date.now(),
      description: `Undo: ${this.redoStack[this.redoStack.length - 1].description}`,
      state: this.cloneState(this.currentState)
    };
    this.undoStack.push(undoEntry);

    // Enforce max stack size
    if (this.undoStack.length > this.maxStackSize) {
      this.undoStack.shift();
    }

    // Pop from redo stack
    const entry = this.redoStack.pop()!;

    // Restore state
    this.currentState = this.cloneState(entry.state);

    // Persist if enabled
    if (this.enablePersistence) {
      this.saveHistory();
    }

    return this.currentState;
  }

  // ============================================================================
  // Query Methods
  // ============================================================================

  /**
   * Check if undo is available
   * 
   * @returns True if there are actions to undo
   */
  canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  /**
   * Check if redo is available
   * 
   * @returns True if there are actions to redo
   */
  canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  /**
   * Get the description of the next undo action
   * 
   * @returns Description string or null if nothing to undo
   */
  getUndoDescription(): string | null {
    if (this.undoStack.length === 0) return null;
    return this.undoStack[this.undoStack.length - 1].description;
  }

  /**
   * Get the description of the next redo action
   * 
   * @returns Description string or null if nothing to redo
   */
  getRedoDescription(): string | null {
    if (this.redoStack.length === 0) return null;
    return this.redoStack[this.redoStack.length - 1].description;
  }

  /**
   * Get the current state
   * 
   * @returns A clone of the current state
   */
  getCurrentState(): T {
    return this.cloneState(this.currentState);
  }

  /**
   * Get the size of the undo stack
   * 
   * @returns Number of undo operations available
   */
  getUndoStackSize(): number {
    return this.undoStack.length;
  }

  /**
   * Get the size of the redo stack
   * 
   * @returns Number of redo operations available
   */
  getRedoStackSize(): number {
    return this.redoStack.length;
  }

  // ============================================================================
  // Save Point Management
  // ============================================================================

  /**
   * Mark the current state as saved
   * 
   * Requirements: 7.7
   * 
   * This allows tracking whether there are unsaved changes
   */
  markAsSaved(): void {
    this.savedStateId = this.undoStack.length > 0
      ? this.undoStack[this.undoStack.length - 1].id
      : null;

    if (this.enablePersistence) {
      this.saveHistory();
    }
  }

  /**
   * Check if there are unsaved changes
   * 
   * Requirements: 7.7
   * 
   * @returns True if the current state differs from the last saved state
   */
  hasUnsavedChanges(): boolean {
    if (this.undoStack.length === 0) {
      return this.savedStateId !== null;
    }
    return this.undoStack[this.undoStack.length - 1].id !== this.savedStateId;
  }

  // ============================================================================
  // History Management
  // ============================================================================

  /**
   * Clear all history
   */
  clearHistory(): void {
    this.undoStack = [];
    this.redoStack = [];
    this.savedStateId = null;

    if (this.enablePersistence) {
      this.saveHistory();
    }
  }

  /**
   * Get the complete undo stack (for debugging/display)
   * 
   * @returns Array of history entries
   */
  getUndoStack(): HistoryEntry<T>[] {
    return [...this.undoStack];
  }

  /**
   * Get the complete redo stack (for debugging/display)
   * 
   * @returns Array of history entries
   */
  getRedoStack(): HistoryEntry<T>[] {
    return [...this.redoStack];
  }

  // ============================================================================
  // Private Helper Methods
  // ============================================================================

  /**
   * Clone state to ensure immutability
   * 
   * @param state - State to clone
   * @returns Deep clone of the state
   */
  private cloneState(state: T): T {
    return JSON.parse(JSON.stringify(state));
  }

  /**
   * Generate a unique ID for history entries
   * 
   * @returns Unique identifier string
   */
  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Save history to localStorage
   * 
   * Requirements: 7.8 (persistence support)
   */
  private saveHistory(): void {
    try {
      const historyData = {
        undoStack: this.undoStack.map(entry => ({
          ...entry,
          inverseAction: undefined // Don't persist functions
        })),
        redoStack: this.redoStack.map(entry => ({
          ...entry,
          inverseAction: undefined
        })),
        savedStateId: this.savedStateId
      };

      localStorage.setItem(this.storageKey, JSON.stringify(historyData));
    } catch (error) {
      console.error('Failed to save undo/redo history:', error);
    }
  }

  /**
   * Load history from localStorage
   * 
   * Requirements: 7.8 (persistence support)
   */
  private loadHistory(): void {
    try {
      const stored = localStorage.getItem(this.storageKey);
      if (stored) {
        const historyData = JSON.parse(stored);
        this.undoStack = historyData.undoStack || [];
        this.redoStack = historyData.redoStack || [];
        this.savedStateId = historyData.savedStateId || null;
      }
    } catch (error) {
      console.error('Failed to load undo/redo history:', error);
    }
  }
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Create a new UndoRedoManager instance
 * 
 * @param initialState - The initial state
 * @param config - Configuration options
 * @returns New UndoRedoManager instance
 */
export function createUndoRedoManager<T>(
  initialState: T,
  config?: UndoRedoConfig
): UndoRedoManager<T> {
  return new UndoRedoManager(initialState, config);
}

/**
 * UndoRedoPersistence - IndexedDB-based persistence for undo/redo history
 * 
 * This service provides:
 * - Persistent storage of undo/redo history in IndexedDB
 * - Automatic restoration on page load
 * - Cleanup of old history entries
 * - Support for multiple projects/contexts
 * 
 * Requirements: 7.8
 */

import { HistoryEntry } from './UndoRedoManager';

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * Persisted history data structure
 */
export interface PersistedHistory<T = any> {
  id: string;
  projectId: string;
  undoStack: HistoryEntry<T>[];
  redoStack: HistoryEntry<T>[];
  savedStateId: string | null;
  lastModified: number;
}

/**
 * Configuration for persistence service
 */
export interface PersistenceConfig {
  /** Database name (default: 'undoRedoHistory') */
  dbName?: string;
  
  /** Store name (default: 'history') */
  storeName?: string;
  
  /** Database version (default: 1) */
  version?: number;
  
  /** Maximum age of history entries in days (default: 30) */
  maxAgeDays?: number;
}

// ============================================================================
// UndoRedoPersistence Class
// ============================================================================

/**
 * Service for persisting undo/redo history to IndexedDB
 * 
 * Requirements: 7.8
 * 
 * @example
 * const persistence = new UndoRedoPersistence();
 * await persistence.initialize();
 * 
 * // Save history
 * await persistence.saveHistory('project-1', undoStack, redoStack, savedStateId);
 * 
 * // Load history
 * const history = await persistence.loadHistory('project-1');
 */
export class UndoRedoPersistence {
  private db: IDBDatabase | null = null;
  private config: Required<PersistenceConfig>;

  constructor(config: PersistenceConfig = {}) {
    this.config = {
      dbName: config.dbName || 'undoRedoHistory',
      storeName: config.storeName || 'history',
      version: config.version || 1,
      maxAgeDays: config.maxAgeDays || 30
    };
  }

  // ============================================================================
  // Initialization
  // ============================================================================

  /**
   * Initialize the IndexedDB database
   * 
   * @returns Promise that resolves when database is ready
   */
  async initialize(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.config.dbName, this.config.version);

      request.onerror = () => {
        reject(new Error('Failed to open IndexedDB'));
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Create object store if it doesn't exist
        if (!db.objectStoreNames.contains(this.config.storeName)) {
          const store = db.createObjectStore(this.config.storeName, {
            keyPath: 'id'
          });

          // Create indexes
          store.createIndex('projectId', 'projectId', { unique: false });
          store.createIndex('lastModified', 'lastModified', { unique: false });
        }
      };
    });
  }

  // ============================================================================
  // Save Operations
  // ============================================================================

  /**
   * Save undo/redo history to IndexedDB
   * 
   * Requirements: 7.8
   * 
   * @param projectId - Unique identifier for the project/context
   * @param undoStack - Array of undo history entries
   * @param redoStack - Array of redo history entries
   * @param savedStateId - ID of the last saved state
   * @returns Promise that resolves when save is complete
   */
  async saveHistory<T>(
    projectId: string,
    undoStack: HistoryEntry<T>[],
    redoStack: HistoryEntry<T>[],
    savedStateId: string | null
  ): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    const history: PersistedHistory<T> = {
      id: `history-${projectId}`,
      projectId,
      undoStack: undoStack.map(entry => ({
        ...entry,
        inverseAction: undefined // Don't persist functions
      })),
      redoStack: redoStack.map(entry => ({
        ...entry,
        inverseAction: undefined
      })),
      savedStateId,
      lastModified: Date.now()
    };

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.put(history);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to save history'));
    });
  }

  // ============================================================================
  // Load Operations
  // ============================================================================

  /**
   * Load undo/redo history from IndexedDB
   * 
   * Requirements: 7.8
   * 
   * @param projectId - Unique identifier for the project/context
   * @returns Promise that resolves with the persisted history, or null if not found
   */
  async loadHistory<T>(projectId: string): Promise<PersistedHistory<T> | null> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.get(`history-${projectId}`);

      request.onsuccess = () => {
        const result = request.result as PersistedHistory<T> | undefined;
        resolve(result || null);
      };

      request.onerror = () => reject(new Error('Failed to load history'));
    });
  }

  /**
   * Load all history entries for a project
   * 
   * @param projectId - Unique identifier for the project
   * @returns Promise that resolves with array of history entries
   */
  async loadAllHistoryForProject<T>(projectId: string): Promise<PersistedHistory<T>[]> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const index = store.index('projectId');
      const request = index.getAll(projectId);

      request.onsuccess = () => {
        resolve(request.result as PersistedHistory<T>[]);
      };

      request.onerror = () => reject(new Error('Failed to load project history'));
    });
  }

  // ============================================================================
  // Delete Operations
  // ============================================================================

  /**
   * Delete history for a specific project
   * 
   * @param projectId - Unique identifier for the project
   * @returns Promise that resolves when deletion is complete
   */
  async deleteHistory(projectId: string): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.delete(`history-${projectId}`);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to delete history'));
    });
  }

  /**
   * Delete all history entries
   * 
   * @returns Promise that resolves when deletion is complete
   */
  async deleteAllHistory(): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to clear history'));
    });
  }

  // ============================================================================
  // Cleanup Operations
  // ============================================================================

  /**
   * Clean up old history entries
   * 
   * Removes entries older than maxAgeDays
   * 
   * @returns Promise that resolves with the number of deleted entries
   */
  async cleanupOldHistory(): Promise<number> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    const maxAge = this.config.maxAgeDays * 24 * 60 * 60 * 1000; // Convert to milliseconds
    const cutoffTime = Date.now() - maxAge;

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const index = store.index('lastModified');
      const request = index.openCursor(IDBKeyRange.upperBound(cutoffTime));

      let deletedCount = 0;

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result as IDBCursorWithValue;

        if (cursor) {
          cursor.delete();
          deletedCount++;
          cursor.continue();
        } else {
          resolve(deletedCount);
        }
      };

      request.onerror = () => reject(new Error('Failed to cleanup old history'));
    });
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Check if database is initialized
   * 
   * @returns True if database is ready
   */
  isInitialized(): boolean {
    return this.db !== null;
  }

  /**
   * Close the database connection
   */
  close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  /**
   * Get database statistics
   * 
   * @returns Promise that resolves with statistics
   */
  async getStatistics(): Promise<{
    totalEntries: number;
    totalSize: number;
    oldestEntry: number | null;
    newestEntry: number | null;
  }> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.getAll();

      request.onsuccess = () => {
        const entries = request.result as PersistedHistory[];
        
        const stats = {
          totalEntries: entries.length,
          totalSize: JSON.stringify(entries).length,
          oldestEntry: entries.length > 0
            ? Math.min(...entries.map(e => e.lastModified))
            : null,
          newestEntry: entries.length > 0
            ? Math.max(...entries.map(e => e.lastModified))
            : null
        };

        resolve(stats);
      };

      request.onerror = () => reject(new Error('Failed to get statistics'));
    });
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

let persistenceInstance: UndoRedoPersistence | null = null;

/**
 * Get the singleton persistence instance
 * 
 * @param config - Configuration options (only used on first call)
 * @returns Persistence instance
 */
export function getPersistenceInstance(config?: PersistenceConfig): UndoRedoPersistence {
  if (!persistenceInstance) {
    persistenceInstance = new UndoRedoPersistence(config);
  }
  return persistenceInstance;
}

/**
 * Initialize the persistence service
 * 
 * @param config - Configuration options
 * @returns Promise that resolves when initialized
 */
export async function initializePersistence(config?: PersistenceConfig): Promise<UndoRedoPersistence> {
  const instance = getPersistenceInstance(config);
  await instance.initialize();
  return instance;
}

/**
 * User Edit Tracking Service
 * 
 * Tracks which fields have been manually edited by the user
 * Preserves user edits during LLM regeneration
 * 
 * Validates Requirements: 1.8
 */

// ============================================================================
// Types
// ============================================================================

export interface EditTrackingState {
  /**
   * Map of field paths to edit status
   * Example: { "name": true, "visual_identity.hair_color": true }
   */
  editedFields: Record<string, boolean>;

  /**
   * Timestamp of last edit
   */
  lastEditTime: Date;
}

// ============================================================================
// Edit Tracking Manager
// ============================================================================

export class EditTrackingManager {
  private editedFields: Set<string> = new Set();
  private lastEditTime: Date = new Date();

  /**
   * Mark a field as edited by the user
   */
  markFieldAsEdited(fieldPath: string): void {
    this.editedFields.add(fieldPath);
    this.lastEditTime = new Date();
  }

  /**
   * Mark multiple fields as edited
   */
  markFieldsAsEdited(fieldPaths: string[]): void {
    fieldPaths.forEach((path) => this.editedFields.add(path));
    this.lastEditTime = new Date();
  }

  /**
   * Check if a field has been edited
   */
  isFieldEdited(fieldPath: string): boolean {
    return this.editedFields.has(fieldPath);
  }

  /**
   * Get all edited field paths
   */
  getEditedFields(): string[] {
    return Array.from(this.editedFields);
  }

  /**
   * Clear edit tracking for a specific field
   */
  clearFieldEdit(fieldPath: string): void {
    this.editedFields.delete(fieldPath);
  }

  /**
   * Clear all edit tracking
   */
  clearAllEdits(): void {
    this.editedFields.clear();
    this.lastEditTime = new Date();
  }

  /**
   * Reset a field to generated state (allow regeneration)
   */
  resetFieldToGenerated(fieldPath: string): void {
    this.editedFields.delete(fieldPath);
  }

  /**
   * Get edit tracking state for persistence
   */
  getState(): EditTrackingState {
    return {
      editedFields: Object.fromEntries(
        Array.from(this.editedFields).map((field) => [field, true])
      ),
      lastEditTime: this.lastEditTime,
    };
  }

  /**
   * Restore edit tracking state from persistence
   */
  restoreState(state: EditTrackingState): void {
    this.editedFields = new Set(Object.keys(state.editedFields));
    this.lastEditTime = new Date(state.lastEditTime);
  }

  /**
   * Get count of edited fields
   */
  getEditedFieldCount(): number {
    return this.editedFields.size;
  }
}

// ============================================================================
// Merge Strategy for Regeneration
// ============================================================================

/**
 * Merges generated data with user-edited data
 * Preserves user edits while updating non-edited fields
 */
export function mergeWithUserEdits<T extends Record<string, unknown>>(
  generatedData: T,
  currentData: T,
  editTracker: EditTrackingManager
): T {
  // Recursively preserve edited fields
  // Using 'any' for recursive merge to handle nested objects of varying structures
  function preserveEdits(
    generated: unknown,
    current: unknown,
    path: string = ''
  ): unknown {
    if (typeof generated !== 'object' || generated === null) {
      // Check if this field was edited
      if (editTracker.isFieldEdited(path)) {
        return current;
      }
      return generated;
    }

    if (Array.isArray(generated)) {
      // For arrays, check if the entire array was edited
      if (editTracker.isFieldEdited(path)) {
        return current;
      }
      return generated;
    }

    // For objects, recursively check each property
    // Using 'any' for result object to build merged structure dynamically
    const result: unknown = {};
    const allKeys = new Set([
      ...Object.keys(generated),
      ...Object.keys(current || {}),
    ]);

    allKeys.forEach((key) => {
      const fieldPath = path ? `${path}.${key}` : key;
      const generatedValue = generated[key];
      const currentValue = current?.[key];

      if (editTracker.isFieldEdited(fieldPath)) {
        // Preserve user edit
        result[key] = currentValue;
      } else if (
        typeof generatedValue === 'object' &&
        generatedValue !== null &&
        !Array.isArray(generatedValue)
      ) {
        // Recursively merge nested objects
        result[key] = preserveEdits(generatedValue, currentValue, fieldPath);
      } else {
        // Use generated value
        result[key] = generatedValue;
      }
    });

    return result;
  }

  return preserveEdits(generatedData, currentData) as T;
}

// ============================================================================
// Field Path Utilities
// ============================================================================

/**
 * Converts a nested object path to a field path string
 * Example: ["visual_identity", "hair_color"] => "visual_identity.hair_color"
 */
export function createFieldPath(pathSegments: string[]): string {
  return pathSegments.join('.');
}

/**
 * Extracts field path from an input name
 * Example: "visual_identity.hair_color" => ["visual_identity", "hair_color"]
 */
export function parseFieldPath(fieldPath: string): string[] {
  return fieldPath.split('.');
}

/**
 * Gets the value at a field path in an object
 */
// Using 'any' for obj parameter and return type to support accessing any object structure
export function getValueAtPath(obj: unknown, fieldPath: string): unknown {
  const segments = parseFieldPath(fieldPath);
  let current = obj;

  for (const segment of segments) {
    if (current === null || current === undefined) {
      return undefined;
    }
    current = current[segment];
  }

  return current;
}

/**
 * Sets the value at a field path in an object
 */
// Using 'any' for obj and value parameters to support setting values in any object structure
export function setValueAtPath(
  obj: unknown,
  fieldPath: string,
  value: unknown
): void {
  const segments = parseFieldPath(fieldPath);
  let current = obj;

  for (let i = 0; i < segments.length - 1; i++) {
    const segment = segments[i];
    if (!(segment in current)) {
      current[segment] = {};
    }
    current = current[segment];
  }

  current[segments[segments.length - 1]] = value;
}

// ============================================================================
// React Hook for Edit Tracking
// ============================================================================

import { useState, useCallback, useRef } from 'react';

export function useEditTracking() {
  const trackerRef = useRef(new EditTrackingManager());
  const [editCount, setEditCount] = useState(0);

  const markFieldAsEdited = useCallback((fieldPath: string) => {
    trackerRef.current.markFieldAsEdited(fieldPath);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const markFieldsAsEdited = useCallback((fieldPaths: string[]) => {
    trackerRef.current.markFieldsAsEdited(fieldPaths);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const isFieldEdited = useCallback((fieldPath: string) => {
    return trackerRef.current.isFieldEdited(fieldPath);
  }, []);

  const resetFieldToGenerated = useCallback((fieldPath: string) => {
    trackerRef.current.resetFieldToGenerated(fieldPath);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const clearAllEdits = useCallback(() => {
    trackerRef.current.clearAllEdits();
    setEditCount(0);
  }, []);

  const getEditedFields = useCallback(() => {
    return trackerRef.current.getEditedFields();
  }, []);

  const mergeWithEdits = useCallback(
    <T extends Record<string, unknown>>(generatedData: T, currentData: T): T => {
      return mergeWithUserEdits(generatedData, currentData, trackerRef.current);
    },
    []
  );

  return {
    markFieldAsEdited,
    markFieldsAsEdited,
    isFieldEdited,
    resetFieldToGenerated,
    clearAllEdits,
    getEditedFields,
    mergeWithEdits,
    editCount,
    tracker: trackerRef.current,
  };
}

// Video Editor API Service
// Backend API communication for the video editor

import {
  EditorProject,
  MediaFile,
  ExportSettings,
  ExportJob,
  Track,
  Clip,
} from '../types/video-editor';

const API_BASE = '/api/video-editor';

interface CreateProjectParams {
  name: string;
  resolution: { width: number; height: number };
  frameRate: number;
}

interface UpdateProjectParams {
  tracks?: Track[];
  clips?: Clip[];
  media?: MediaFile[];
}

class VideoEditorAPI {
  private baseUrl: string;

  constructor(baseUrl: string = API_BASE) {
    this.baseUrl = baseUrl;
  }

  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 600000); // 10 minutes

    try {
      const response = await fetch(`${this.baseUrl}${endpoint}`, {
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
        ...options,
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      if (!response.ok) {
        const error = await response.json().catch(() => ({ message: 'Request failed' }));
        throw new Error(error.message || `HTTP ${response.status}`);
      }

      return response.json();
    } catch (error) {
      clearTimeout(timeoutId);
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error('Video editor request timed out after 10 minutes');
      }
      throw error;
    }
  }

  // Project Operations
  async createProject(params: CreateProjectParams): Promise<EditorProject> {
    return this.request<EditorProject>('/projects', {
      method: 'POST',
      body: JSON.stringify(params),
    });
  }

  async getProject(projectId: string): Promise<EditorProject> {
    return this.request<EditorProject>(`/projects/${projectId}`);
  }

  async updateProject(projectId: string, params: UpdateProjectParams): Promise<EditorProject> {
    return this.request<EditorProject>(`/projects/${projectId}`, {
      method: 'PUT',
      body: JSON.stringify(params),
    });
  }

  async deleteProject(projectId: string): Promise<void> {
    await this.request(`/projects/${projectId}`, { method: 'DELETE' });
  }

  async listProjects(): Promise<EditorProject[]> {
    return this.request<EditorProject[]>('/projects');
  }

  // Media Operations
  async importMedia(projectId: string, file: File): Promise<MediaFile> {
    const formData = new FormData();
    formData.append('file', file);

    const response = await fetch(`${this.baseUrl}/projects/${projectId}/media`, {
      method: 'POST',
      body: formData,
    });

    if (!response.ok) {
      throw new Error('Failed to import media');
    }

    return response.json();
  }

  async deleteMedia(projectId: string, mediaId: string): Promise<void> {
    await this.request(`/projects/${projectId}/media/${mediaId}`, {
      method: 'DELETE',
    });
  }

  async getMedia(projectId: string, mediaId: string): Promise<MediaFile> {
    return this.request<MediaFile>(`/projects/${projectId}/media/${mediaId}`);
  }

  // Clip Operations
  async addClip(
    projectId: string,
    trackId: string,
    mediaId: string,
    startTime: number,
    inPoint?: number,
    outPoint?: number
  ): Promise<Clip> {
    return this.request<Clip>(`/projects/${projectId}/tracks/${trackId}/clips`, {
      method: 'POST',
      body: JSON.stringify({
        mediaId,
        startTime,
        inPoint,
        outPoint,
      }),
    });
  }

  async updateClip(
    projectId: string,
    clipId: string,
    updates: Partial<Clip>
  ): Promise<Clip> {
    return this.request<Clip>(`/projects/${projectId}/clips/${clipId}`, {
      method: 'PUT',
      body: JSON.stringify(updates),
    });
  }

  async deleteClip(projectId: string, clipId: string): Promise<void> {
    await this.request(`/projects/${projectId}/clips/${clipId}`, {
      method: 'DELETE',
    });
  }

  async moveClip(
    projectId: string,
    clipId: string,
    newTrackId: string,
    newStartTime: number
  ): Promise<Clip> {
    return this.request<Clip>(`/projects/${projectId}/clips/${clipId}/move`, {
      method: 'POST',
      body: JSON.stringify({
        trackId: newTrackId,
        startTime: newStartTime,
      }),
    });
  }

  async splitClip(projectId: string, clipId: string, splitTime: number): Promise<Clip[]> {
    return this.request<Clip[]>(`/projects/${projectId}/clips/${clipId}/split`, {
      method: 'POST',
      body: JSON.stringify({ splitTime }),
    });
  }

  // Export Operations
  async exportProject(
    projectId: string,
    settings: ExportSettings
  ): Promise<ExportJob> {
    return this.request<ExportJob>(`/projects/${projectId}/export`, {
      method: 'POST',
      body: JSON.stringify(settings),
    });
  }

  async getExportProgress(jobId: string): Promise<ExportJob> {
    return this.request<ExportJob>(`/export/${jobId}/progress`);
  }

  async cancelExport(jobId: string): Promise<void> {
    await this.request(`/export/${jobId}/cancel`, { method: 'POST' });
  }

  getExportDownload(jobId: string): string {
    return `${this.baseUrl}/export/${jobId}/download`;
  }

  // AI Features
  async generateCaptions(
    projectId: string,
    language: string = 'en'
  ): Promise<{ taskId: string }> {
    return this.request<{ taskId: string }>(`/projects/${projectId}/ai/captions`, {
      method: 'POST',
      body: JSON.stringify({ language }),
    });
  }

  async getCaptionsStatus(projectId: string): Promise<{
    status: 'pending' | 'processing' | 'completed' | 'failed';
    captions?: unknown[];
  }> {
    return this.request(`/projects/${projectId}/ai/captions/status`);
  }

  async generateSpeech(
    projectId: string,
    text: string,
    voice: string,
    options?: {
      rate?: number;
      pitch?: number;
      volume?: number;
    }
  ): Promise<{ audioUrl: string }> {
    return this.request<{ audioUrl: string }>(`/projects/${projectId}/ai/tts`, {
      method: 'POST',
      body: JSON.stringify({ text, voice, ...options }),
    });
  }


  async generateVideoFromReference(
    projectId: string,
    shotId: string,
    referenceImage: string,
    parameters: unknown // Decoupled from ComfyUIParameters to avoid circular deps
  ): Promise<{ taskId: string }> {
    return this.request<{ taskId: string }>(`/projects/${projectId}/ai/generate-video`, {
      method: 'POST',
      body: JSON.stringify({ shotId, referenceImage, parameters }),
    });
  }

  async extendVideo(
    projectId: string,
    shotId: string,
    sourceVideoUrl: string,
    parameters: unknown // Decoupled from ComfyUIParameters to avoid circular deps
  ): Promise<{ taskId: string }> {
    return this.request<{ taskId: string }>(`/projects/${projectId}/ai/extend-video`, {
      method: 'POST',
      body: JSON.stringify({ shotId, sourceVideoUrl, parameters }),
    });
  }

  async getVideoGenerationStatus(
    projectId: string,
    taskId: string
  ): Promise<{
    status: 'processing' | 'completed' | 'failed';
    progress: number;
