// ============================================================================
// Video Scenario Generation Service
// ============================================================================
// This service handles generation of video scenarios from stories
// including dialogues, sequences, shots, and production elements
// ============================================================================

import type { Story, StoryPart } from '../types/story';
import type { VideoScenario, Sequence, Shot, Dialogue, ProductionElement } from '../types/videoScenario';

// ============================================================================
// Type Definitions
// ============================================================================

export interface VideoScenarioGenerationParams {
    story: Story;
    includeDialogues: boolean;
    includeSequences: boolean;
    includeShots: boolean;
    includeLyrics: boolean;
    shotStyle: 'cinematic' | 'documentary' | 'animation' | 'mixed';
    dialogueStyle: 'natural' | 'dramatic' | 'minimal';
}

// ============================================================================
// Video Scenario Generation Service
// ============================================================================

export class VideoScenarioService {
    /**
     * Generate complete video scenario from story
     */
    async generateVideoScenario(
        params: VideoScenarioGenerationParams,
        onProgress?: (progress: { stage: string; progress: number; currentTask: string }) => void
    ): Promise<VideoScenario> {
        const { story } = params;
        const sequences: Sequence[] = [];
        const dialogues: Dialogue[] = [];
        const productionElements: ProductionElement[] = [];

        // 1. Generate sequences from story parts
        onProgress?.({
            stage: 'generating_sequences',
            progress: 20,
            currentTask: 'Analyzing story structure...'
        });

        const storySequences = await this.generateSequencesFromStory(story, params);
        sequences.push(...storySequences);

        // 2. Generate dialogues if requested
        if (params.includeDialogues) {
            onProgress?.({
                stage: 'generating_dialogues',
                progress: 40,
                currentTask: 'Creating character dialogues...'
            });

            const storyDialogues = await this.generateDialoguesFromStory(story, params);
            dialogues.push(...storyDialogues);
        }

        // 3. Generate shots for each sequence
        if (params.includeShots) {
            onProgress?.({
                stage: 'generating_shots',
                progress: 60,
                currentTask: 'Planning camera shots...'
            });

            for (let i = 0; i < sequences.length; i++) {
                const sequence = sequences[i];
                const sequenceShots = await this.generateShotsForSequence(sequence, params);
                sequence.shots = sequenceShots;
            }
        }

        // 4. Generate production elements
        onProgress?.({
            stage: 'generating_elements',
            progress: 80,
            currentTask: 'Planning production elements...'
        });

        const elements = await this.generateProductionElements(story, params);
        productionElements.push(...elements);

        // 5. Complete
        onProgress?.({
            stage: 'complete',
            progress: 100,
            currentTask: 'Video scenario generation complete!'
        });

        return {
            id: crypto.randomUUID(),
            title: `${story.title} - Video Scenario`,
            storyId: story.id,
            sequences,
            dialogues,
            productionElements,
            metadata: {
                includeDialogues: params.includeDialogues,
                includeSequences: params.includeSequences,
                includeShots: params.includeShots,
                includeLyrics: params.includeLyrics,
                shotStyle: params.shotStyle,
                dialogueStyle: params.dialogueStyle,
                generatedAt: Date.now(),
            }
        };
    }

    /**
     * Generate sequences from story parts
     */
    private async generateSequencesFromStory(
        story: Story,
        params: VideoScenarioGenerationParams
    ): Promise<Sequence[]> {
        const sequences: Sequence[] = [];

        if (story.parts && story.parts.length > 0) {
            // Convert each story part to a sequence
            for (let i = 0; i < story.parts.length; i++) {
                const part = story.parts[i];
                const sequence = await this.createSequenceFromPart(part, i + 1, params);
                sequences.push(sequence);
            }
        } else {
            // Create a single sequence from the main content
            const sequence = await this.createSequenceFromContent(story, 1, params);
            sequences.push(sequence);
        }

        return sequences;
    }

    /**
     * Create sequence from story part
     */
    private async createSequenceFromPart(
        part: StoryPart,
        order: number,
        params: VideoScenarioGenerationParams
    ): Promise<Sequence> {
        const prompt = this.buildSequencePrompt(part, params);

        try {
            const { getLLMService } = await import('./llmService');
            const llmService = getLLMService();

            const response = await llmService.generateText(prompt, {
                temperature: 0.7,
                maxTokens: 1000,
            });

            return this.parseSequenceResponse(response, part, order);
        } catch (error) {
            console.error('[VideoScenarioService] Failed to generate sequence:', error);
            return this.createFallbackSequence(part, order);
        }
    }

    /**
     * Create sequence from story content
     */
    private async createSequenceFromContent(
        story: Story,
        order: number,
        params: VideoScenarioGenerationParams
    ): Promise<Sequence> {
        const prompt = this.buildContentSequencePrompt(story, params);

        try {
            const { getLLMService } = await import('./llmService');
            const llmService = getLLMService();

            const response = await llmService.generateText(prompt, {
                temperature: 0.7,
                maxTokens: 1500,
            });

            return this.parseContentSequenceResponse(response, story, order);
        } catch (error) {
            console.error('[VideoScenarioService] Failed to generate content sequence:', error);
            return this.createFallbackContentSequence(story, order);
        }
    }

    /**
     * Generate dialogues from story
     */
    private async generateDialoguesFromStory(
        story: Story,
        params: VideoScenarioGenerationParams
    ): Promise<Dialogue[]> {
        const dialogues: Dialogue[] = [];

        const prompt = this.buildDialoguePrompt(story, params);

        try {
            const { getLLMService } = await import('./llmService');
            const llmService = getLLMService();

            const response = await llmService.generateText(prompt, {
                temperature: 0.8,
                maxTokens: 2000,
            });

            return this.parseDialogueResponse(response, story);
        } catch (error) {
            console.error('[VideoScenarioService] Failed to generate dialogues:', error);
            return [];
        }
    }

    /**
     * Generate shots for a sequence
     */
    private async generateShotsForSequence(
        sequence: Sequence,
        params: VideoScenarioGenerationParams
    ): Promise<Shot[]> {
        const prompt = this.buildShotPrompt(sequence, params);

        try {
            const { getLLMService } = await import('./llmService');
            const llmService = getLLMService();

            const response = await llmService.generateText(prompt, {
                temperature: 0.7,
                maxTokens: 1500,
            });

            return this.parseShotResponse(response, sequence);
        } catch (error) {
            console.error('[VideoScenarioService] Failed to generate shots:', error);
            return [];
        }
    }

    /**
     * Generate production elements
     */
    private async generateProductionElements(
        story: Story,
        params: VideoScenarioGenerationParams
    ): Promise<ProductionElement[]> {
        const prompt = this.buildProductionElementPrompt(story, params);

        try {
            const { getLLMService } = await import('./llmService');
            const llmService = getLLMService();

            const response = await llmService.generateText(prompt, {
                temperature: 0.7,
                maxTokens: 1000,
            });

            return this.parseProductionElementResponse(response, story);
        } catch (error) {
            console.error('[VideoScenarioService] Failed to generate production elements:', error);
            return [];
        }
    }

    // ============================================================================
    // Prompt Builders
    // ============================================================================

    private buildSequencePrompt(part: StoryPart, params: VideoScenarioGenerationParams): string {
        return `
Convert this story part into a video sequence plan:

Story Part: ${part.title}
Content: ${part.content.substring(0, 1000)}

Characters: ${part.type === 'intro' ? 'Introduction characters' : 'Main characters'}
Location: ${part.type === 'intro' ? 'Starting location' : 'Current location'}

Generate a sequence with:
- Sequence number and title
- Location description
- Time of day
- Main action/scene description
- Key visual elements
- Mood/atmosphere

Format as JSON with fields: sequenceNumber, title, location, timeOfDay, description, visualElements, mood
`;
    }

    private buildContentSequencePrompt(story: Story, params: VideoScenarioGenerationParams): string {
        return `
Convert this story into a video sequence plan:

Story: ${story.title}
Content: ${story.content.substring(0, 1500)}

Characters: ${story.charactersUsed.map(c => c.name).join(', ')}
Locations: ${story.locationsUsed.map(l => l.name).join(', ')}

Generate a sequence with:
- Sequence number and title
- Location description
- Time of day
- Main action/scene description
- Key visual elements
- Mood/atmosphere

Format as JSON with fields: sequenceNumber, title, location, timeOfDay, description, visualElements, mood
`;
    }

    private buildDialoguePrompt(story: Story, params: VideoScenarioGenerationParams): string {
        const style = params.dialogueStyle === 'natural' ? 'natural, realistic dialogue' :
            params.dialogueStyle === 'dramatic' ? 'dramatic, theatrical dialogue' :
                'minimal, essential dialogue';

        return `
Generate ${style} dialogues for this story:

Story: ${story.title}
Characters: ${story.charactersUsed.map(c => `${c.name} (${c.role})`).join(', ')}
Content: ${story.content.substring(0, 1500)}

Generate dialogues with:
- Character name
- Dialogue text
- Context/emotion
- Scene reference

Format as JSON array with fields: character, text, emotion, sceneReference

${params.includeLyrics ? 'Include song lyrics if appropriate for the story.' : ''}
`;
    }

    private buildShotPrompt(sequence: Sequence, params: VideoScenarioGenerationParams): string {
        const style = params.shotStyle === 'cinematic' ? 'cinematic, film-like shots' :
            params.shotStyle === 'documentary' ? 'documentary-style shots' :
                params.shotStyle === 'animation' ? 'animated shots' :
                    'mixed style shots';

        return `
Plan ${style} shots for this sequence:

Sequence: ${sequence.title}
Location: ${sequence.location}
Description: ${sequence.description}

Generate shots with:
- Shot number
- Shot type (wide, medium, close-up, etc.)
- Camera movement
- Framing
- Focus point
- Duration
- Purpose/meaning

Format as JSON array with fields: shotNumber, type, cameraMovement, framing, focusPoint, duration, purpose
`;
    }

    private buildProductionElementPrompt(story: Story, params: VideoScenarioGenerationParams): string {
        return `
Generate production elements for this video story:

Story: ${story.title}
Genre: ${story.genre.join(', ')}
Tone: ${story.tone.join(', ')}
Characters: ${story.charactersUsed.map(c => c.name).join(', ')}

Generate production elements with:
- Element type (music, sound effect, visual effect, etc.)
- Description
- Timing/scene reference
- Purpose/impact

Format as JSON array with fields: type, description, timing, purpose
`;
    }

    // ============================================================================
    // Response Parsers
    // ============================================================================

    private parseSequenceResponse(response: string, part: StoryPart, order: number): Sequence {
        try {
            const jsonMatch = response.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return {
                    id: crypto.randomUUID(),
                    sequenceNumber: parsed.sequenceNumber || order,
                    title: parsed.title || part.title,
                    location: parsed.location || 'Unknown Location',
                    timeOfDay: parsed.timeOfDay || 'Day',
                    description: parsed.description || part.summary || '',
                    visualElements: parsed.visualElements || [],
                    mood: parsed.mood || '',
                    shots: [],
                    duration: 0,
                    order,
                };
            }
        } catch (error) {
            console.error('[VideoScenarioService] Failed to parse sequence response:', error);
        }

        return this.createFallbackSequence(part, order);
    }

    private parseContentSequenceResponse(response: string, story: Story, order: number): Sequence {
        try {
            const jsonMatch = response.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return {
                    id: crypto.randomUUID(),
                    sequenceNumber: parsed.sequenceNumber || order,
                    title: parsed.title || story.title,
                    location: parsed.location || 'Unknown Location',
                    timeOfDay: parsed.timeOfDay || 'Day',
                    description: parsed.description || story.summary || '',
                    visualElements: parsed.visualElements || [],
                    mood: parsed.mood || '',
                    shots: [],
                    duration: 0,
                    order,
                };
            }
        } catch (error) {
            console.error('[VideoScenarioService] Failed to parse content sequence response:', error);
        }

        return this.createFallbackContentSequence(story, order);
    }

    private parseDialogueResponse(response: string, story: Story): Dialogue[] {
        try {
            const jsonMatch = response.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return parsed.map((d: any) => ({
                    id: crypto.randomUUID(),
                    character: d.character || 'Unknown',
                    text: d.text || '',
                    emotion: d.emotion || '',
                    sceneReference: d.sceneReference || '',
                    timestamp: '',
                }));
            }
        } catch (error) {
            console.error('[VideoScenarioService] Failed to parse dialogue response:', error);
        }

        return [];
    }

    private parseShotResponse(response: string, sequence: Sequence): Shot[] {
        try {
            const jsonMatch = response.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return parsed.map((s: any, index: number) => ({
                    id: crypto.randomUUID(),
                    shotNumber: s.shotNumber || index + 1,
                    type: s.type || 'medium',
                    cameraMovement: s.cameraMovement || '',
                    framing: s.framing || '',
                    focusPoint: s.focusPoint || '',
                    duration: s.duration || 5,
                    purpose: s.purpose || '',
                    sequenceId: sequence.id,
                }));
            }
        } catch (error) {
            console.error('[VideoScenarioService] Failed to parse shot response:', error);
        }

        return [];
    }

    private parseProductionElementResponse(response: string, story: Story): ProductionElement[] {
        try {
            const jsonMatch = response.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return parsed.map((e: any) => ({
                    id: crypto.randomUUID(),
                    type: e.type || 'visual',
                    description: e.description || '',
                    timing: e.timing || '',
                    purpose: e.purpose || '',
                    storyId: story.id,
                }));
            }
        } catch (error) {
            console.error('[VideoScenarioService] Failed to parse production element response:', error);
        }

        return [];
    }

    // ============================================================================
    // Fallback Generators
    // ============================================================================

    private createFallbackSequence(part: StoryPart, order: number): Sequence {
        return {
            id: crypto.randomUUID(),
            sequenceNumber: order,
            title: part.title,
            location: 'Unknown Location',
            timeOfDay: 'Day',
            description: part.summary || '',
            visualElements: [],
            mood: '',
            shots: [],
            duration: 0,
            order,
        };
    }

    private createFallbackContentSequence(story: Story, order: number): Sequence {
        return {
            id: crypto.randomUUID(),
            sequenceNumber: order,
            title: story.title,
            location: 'Unknown Location',
            timeOfDay: 'Day',
            description: story.summary || '',
            visualElements: [],
            mood: '',
            shots: [],
            duration: 0,
            order,
        };
    }
}

export const videoScenarioService = new VideoScenarioService();

/**
 * VideoPlayerService - Core video playback service for StoryCore Engine
 * 
 * Handles all video playback operations including:
 * - Play/pause/stop controls
 * - Frame-accurate seeking
 * - Frame-by-frame navigation
 * - Playback rate control
 * - Loop and mute toggles
 * - Event emission for state changes
 * 
 * @module services/video/VideoPlayerService
 */

import {
  PlaybackState,
  PlaybackStatus,
  PlaybackControls,
  PlaybackRate,
  PLAYBACK_RATES,
  FrameInfo,
  formatTime,
  formatTimecode,
  secondsToFrame,
  frameToSeconds,
} from '../../types/video';

// ============================================
// Configuration
// ============================================

type VideoPlayerConfig = {
  defaultPlaybackRate: PlaybackRate;
  defaultVolume: number;
  defaultMuted: boolean;
  defaultLooping: boolean;
  frameRate: number;
  useHighPrecisionTime: boolean;
  bufferThresholdSeconds: number;
  maxBufferedSeconds: number;
};

const DEFAULT_CONFIG: VideoPlayerConfig = {
  defaultPlaybackRate: 1,
  defaultVolume: 1.0,
  defaultMuted: false,
  defaultLooping: false,
  frameRate: 30,
  useHighPrecisionTime: true,
  bufferThresholdSeconds: 0.5,
  maxBufferedSeconds: 30,
};

// ============================================
// Error Classes
// ============================================

export class VideoPlayerError extends Error {
  code: string;
  originalError?: Error;
  
  constructor(message: string, code: string, originalError?: Error) {
    super(message);
    this.name = 'VideoPlayerError';
    this.code = code;
    this.originalError = originalError;
  }
}

export class VideoNotLoadedError extends VideoPlayerError {
  constructor() {
    super('Video source not loaded', 'VIDEO_NOT_LOADED');
  }
}

export class InvalidSeekError extends VideoPlayerError {
  constructor(time: number, min: number, max: number) {
    super(
      `Invalid seek time: ${time}. Must be between ${min} and ${max}`,
      'INVALID_SEEK_TIME'
    );
  }
}

export class InvalidFrameError extends VideoPlayerError {
  constructor(frame: number, min: number, max: number) {
    super(
      `Invalid frame: ${frame}. Must be between ${min} and ${max}`,
      'INVALID_FRAME'
    );
  }
}

// ============================================
// Event Types
// ============================================

export type VideoPlayerEventType = 
  | 'state:change'
  | 'time:update'
  | 'frame:update'
  | 'rate:change'
  | 'volume:change'
  | 'muted:change'
  | 'loop:change'
  | 'play'
  | 'pause'
  | 'ended'
  | 'seeking'
  | 'seeked'
  | 'waiting'
  | 'canplay'
  | 'fps:update'
  | 'dropped:frame'
  | 'buffer:update'
  | 'error';

export type VideoPlayerEventCallback = (data?: unknown) => void;

// ============================================
// Service Class
// ============================================

export class VideoPlayerService {
  private videoEl: HTMLVideoElement | null = null;
  private configData: VideoPlayerConfig;
  private statusData: PlaybackStatus;
  private animationId: number | null = null;
  private lastFrameTime: number = 0;
  private frameCount: number = 0;
  private currentFps: number = 30;
  private frameTimes: number[] = [];
  private droppedFramesData: number = 0;
  private lastPerfCheck: number = 0;
  
  // Event listeners storage
  private listeners: Map<VideoPlayerEventType, Set<VideoPlayerEventCallback>> = new Map();
  
  // Event handlers - bound once for performance
  private handleTimeUpdateBound: () => void;
  private handlePlayBound: () => void;
  private handlePauseBound: () => void;
  private handleEndedBound: () => void;
  private handleWaitingBound: () => void;
  private handleCanPlayBound: () => void;
  private handleErrorBound: () => void;
  
  constructor(config: Partial<VideoPlayerConfig> = {}) {
    this.configData = { ...DEFAULT_CONFIG, ...config };
    this.statusData = {
      state: 'idle',
      currentTime: 0,
      currentFrame: 0,
      duration: 0,
      totalFrames: 0,
      playbackRate: this.configData.defaultPlaybackRate,
      isMuted: this.configData.defaultMuted,
      isLooping: this.configData.defaultLooping,
      volume: this.configData.defaultVolume,
      bufferProgress: 0,
      isBuffering: false,
    };
    
    // Bind event handlers once
    this.handleTimeUpdateBound = this.onTimeUpdate.bind(this);
    this.handlePlayBound = this.onPlay.bind(this);
    this.handlePauseBound = this.onPause.bind(this);
    this.handleEndedBound = this.onEnded.bind(this);
    this.handleWaitingBound = this.onWaiting.bind(this);
    this.handleCanPlayBound = this.onCanPlay.bind(this);
    this.handleErrorBound = this.onError.bind(this);
  }
  
  // ============================================
  // Event System
  // ============================================
  
  on(event: VideoPlayerEventType, callback: VideoPlayerEventCallback): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(callback);
  }
  
  off(event: VideoPlayerEventType, callback: VideoPlayerEventCallback): void {
    const handlers = this.listeners.get(event);
    if (handlers) {
      handlers.delete(callback);
    }
  }
  
  once(event: VideoPlayerEventType, callback: VideoPlayerEventCallback): void {
    const self = this;
    const wrapper: VideoPlayerEventCallback = function(data) {
      self.off(event, wrapper);
      callback(data);
    };
    this.on(event, wrapper);
  }
  
  private emitStateChange(state: PlaybackState): void {
    const handlers = this.listeners.get('state:change');
    if (handlers) {
      handlers.forEach(cb => cb(state));
    }
  }
  
  private emitTimeUpdate(time: number): void {
    const handlers = this.listeners.get('time:update');
    if (handlers) {
      handlers.forEach(cb => cb(time));
    }
  }
  
  private emitFrameUpdate(frame: number): void {
    const handlers = this.listeners.get('frame:update');
    if (handlers) {
      handlers.forEach(cb => cb(frame));
    }
  }
  
  private emitRateChange(rate: PlaybackRate): void {
    const handlers = this.listeners.get('rate:change');
    if (handlers) {
      handlers.forEach(cb => cb(rate));
    }
  }
  
  private emitVolumeChange(volume: number): void {
    const handlers = this.listeners.get('volume:change');
    if (handlers) {
      handlers.forEach(cb => cb(volume));
    }
  }
  
  private emitMutedChange(muted: boolean): void {
    const handlers = this.listeners.get('muted:change');
    if (handlers) {
      handlers.forEach(cb => cb(muted));
    }
  }
  
  private emitLoopChange(looping: boolean): void {
    const handlers = this.listeners.get('loop:change');
    if (handlers) {
      handlers.forEach(cb => cb(looping));
    }
  }
  
  private emitPlay(): void {
    const handlers = this.listeners.get('play');
    if (handlers) {
      handlers.forEach(cb => cb());
    }
  }
  
  private emitPause(): void {
    const handlers = this.listeners.get('pause');
    if (handlers) {
      handlers.forEach(cb => cb());
    }
  }
  
  private emitEnded(): void {
    const handlers = this.listeners.get('ended');
    if (handlers) {
      handlers.forEach(cb => cb());
    }
  }
  
  private emitSeeking(time: number): void {
    const handlers = this.listeners.get('seeking');
    if (handlers) {
      handlers.forEach(cb => cb(time));
    }
  }
  
  private emitSeeked(time: number): void {
    const handlers = this.listeners.get('seeked');
    if (handlers) {
      handlers.forEach(cb => cb(time));
    }
  }
  
  private emitWaiting(): void {
    const handlers = this.listeners.get('waiting');
    if (handlers) {
      handlers.forEach(cb => cb());
    }
  }
  
  private emitCanPlay(): void {
    const handlers = this.listeners.get('canplay');
    if (handlers) {
      handlers.forEach(cb => cb());
    }
  }
  
  private emitFpsUpdate(fps: number): void {
    const handlers = this.listeners.get('fps:update');
    if (handlers) {
      handlers.forEach(cb => cb(fps));
    }
  }
  
  private emitDroppedFrame(count: number): void {
    const handlers = this.listeners.get('dropped:frame');
    if (handlers) {
      handlers.forEach(cb => cb(count));
    }
  }
  
  private emitBufferUpdate(progress: number): void {
    const handlers = this.listeners.get('buffer:update');
    if (handlers) {
      handlers.forEach(cb => cb(progress));
    }
  }
  
  private emitError(error: VideoPlayerError): void {
    const handlers = this.listeners.get('error');
    if (handlers) {
      handlers.forEach(cb => cb(error));
    }
  }
  
  // ============================================
  // Initialization
  // ============================================
  
  initialize(videoElement: HTMLVideoElement): void {
    if (this.videoEl) {
      this.detach();
    }
    
    this.videoEl = videoElement;
    this.attachEventListeners();
    
    this.videoEl.volume = this.statusData.volume;
    this.videoEl.muted = this.statusData.isMuted;
    this.videoEl.loop = this.statusData.isLooping;
    this.videoEl.playbackRate = this.configData.frameRate;
    
    this.statusData.state = 'ready';
    this.statusData.duration = this.videoEl.duration || 0;
    this.statusData.totalFrames = this.calcTotalFrames();
    
    this.emitStateChange(this.statusData.state);
    this.emitCanPlay();
  }
  
  private attachEventListeners(): void {
    if (!this.videoEl) return;
    
    this.videoEl.addEventListener('timeupdate', this.handleTimeUpdateBound);
    this.videoEl.addEventListener('play', this.handlePlayBound);
    this.videoEl.addEventListener('pause', this.handlePauseBound);
    this.videoEl.addEventListener('ended', this.handleEndedBound);
    this.videoEl.addEventListener('waiting', this.handleWaitingBound);
    this.videoEl.addEventListener('canplay', this.handleCanPlayBound);
    this.videoEl.addEventListener('error', this.handleErrorBound);
  }
  
  detach(): void {
    if (!this.videoEl) return;
    
    this.pause();
    this.stopAnimationLoop();
    
    this.videoEl.removeEventListener('timeupdate', this.handleTimeUpdateBound);
    this.videoEl.removeEventListener('play', this.handlePlayBound);
    this.videoEl.removeEventListener('pause', this.handlePauseBound);
    this.videoEl.removeEventListener('ended', this.handleEndedBound);
    this.videoEl.removeEventListener('waiting', this.handleWaitingBound);
    this.videoEl.removeEventListener('canplay', this.handleCanPlayBound);
    this.videoEl.removeEventListener('error', this.handleErrorBound);
    
    this.videoEl = null;
    this.statusData.state = 'idle';
  }
  
  // ============================================
  // Playback Controls
  // ============================================
  
  async play(): Promise<void> {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    if (this.statusData.state === 'playing') {
      return;
    }
    
    if (this.statusData.state === 'error') {
      throw new VideoPlayerError('Cannot play in error state', 'ERROR_STATE');
    }
    
    try {
      this.statusData.state = 'loading';
      this.emitStateChange(this.statusData.state);
      
      await this.videoEl.play();
    } catch (error) {
      this.statusData.state = 'error';
      this.statusData.error = error instanceof Error ? error.message : 'Unknown play error';
      this.emitStateChange(this.statusData.state);
      const err = new VideoPlayerError(
        `Failed to play: ${this.statusData.error}`,
        'PLAY_FAILED',
        error instanceof Error ? error : undefined
      );
      this.emitError(err);
      throw err;
    }
  }
  
  pause(): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    if (this.statusData.state !== 'playing' && this.statusData.state !== 'loading') {
      return;
    }
    
    this.videoEl.pause();
    this.stopAnimationLoop();
  }
  
  stop(): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    this.videoEl.pause();
    this.videoEl.currentTime = 0;
    this.stopAnimationLoop();
    
    this.statusData.state = 'ready';
    this.statusData.currentTime = 0;
    this.statusData.currentFrame = 0;
    this.statusData.isBuffering = false;
    
    this.emitStateChange(this.statusData.state);
    this.emitTimeUpdate(this.statusData.currentTime);
    this.emitFrameUpdate(this.statusData.currentFrame);
  }
  
  async togglePlay(): Promise<void> {
    if (this.statusData.state === 'playing') {
      this.pause();
    } else {
      await this.play();
    }
  }
  
  seek(time: number): Promise<void> {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    const minTime = 0;
    const maxTime = this.statusData.duration;
    
    if (time < minTime || time > maxTime) {
      throw new InvalidSeekError(time, minTime, maxTime);
    }
    
    this.statusData.state = 'seeking';
    this.statusData.isBuffering = true;
    this.emitStateChange(this.statusData.state);
    this.emitSeeking(time);
    
    const videoEl = this.videoEl;
    
    return new Promise((resolve, reject) => {
      const onSeeked = () => {
        videoEl.removeEventListener('seeked', onSeeked);
        videoEl.removeEventListener('error', onError);
        
        this.statusData.currentTime = videoEl.currentTime;
        this.statusData.currentFrame = this.calcCurrentFrame();
        this.statusData.isBuffering = false;
        this.statusData.state = videoEl.paused ? 'ready' : 'playing';
        
        this.emitStateChange(this.statusData.state);
        this.emitTimeUpdate(this.statusData.currentTime);
        this.emitFrameUpdate(this.statusData.currentFrame);
        this.emitSeeked(this.statusData.currentTime);
        
        resolve();
      };
      
      const onError = () => {
        videoEl.removeEventListener('seeked', onSeeked);
        videoEl.removeEventListener('error', onError);
        
        this.statusData.state = 'error';
        this.statusData.isBuffering = false;
        this.statusData.error = 'Seek failed';
        
        this.emitStateChange(this.statusData.state);
        reject(new VideoPlayerError('Seek operation failed', 'SEEK_FAILED'));
      };
      
      videoEl.addEventListener('seeked', onSeeked, { once: true });
      videoEl.addEventListener('error', onError, { once: true });
      
      videoEl.currentTime = time;
    });
  }
  
  async seekToFrame(frame: number): Promise<void> {
    const minFrame = 0;
    const maxFrame = this.statusData.totalFrames - 1;
    
    if (frame < minFrame || frame > maxFrame) {
      throw new InvalidFrameError(frame, minFrame, maxFrame);
    }
    
    const time = frameToSeconds(frame, this.configData.frameRate);
    await this.seek(time);
  }
  
  async stepForward(frames: number = 1): Promise<void> {
    const targetFrame = Math.min(this.statusData.currentFrame + frames, this.statusData.totalFrames - 1);
    await this.seekToFrame(targetFrame);
  }
  
  async stepBackward(frames: number = 1): Promise<void> {
    const targetFrame = Math.max(this.statusData.currentFrame - frames, 0);
    await this.seekToFrame(targetFrame);
  }
  
  setPlaybackRate(rate: PlaybackRate): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    if (!PLAYBACK_RATES.includes(rate)) {
      throw new VideoPlayerError(
        `Invalid playback rate: ${rate}. Valid rates: ${PLAYBACK_RATES.join(', ')}`,
        'INVALID_PLAYBACK_RATE'
      );
    }
    
    this.statusData.playbackRate = rate;
    this.videoEl.playbackRate = rate;
    this.emitRateChange(rate);
  }
  
  setVolume(volume: number): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    const clampedVolume = Math.max(0, Math.min(1, volume));
    this.statusData.volume = clampedVolume;
    this.videoEl.volume = clampedVolume;
    this.emitVolumeChange(clampedVolume);
  }
  
  toggleMute(): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    this.statusData.isMuted = !this.statusData.isMuted;
    this.videoEl.muted = this.statusData.isMuted;
    this.emitMutedChange(this.statusData.isMuted);
  }
  
  toggleLoop(): void {
    if (!this.videoEl) {
      throw new VideoNotLoadedError();
    }
    
    this.statusData.isLooping = !this.statusData.isLooping;
    this.videoEl.loop = this.statusData.isLooping;
    this.emitLoopChange(this.statusData.isLooping);
  }
  
  // ============================================
  // Status & Information
  // ============================================
  
  getStatus(): PlaybackStatus {
    return { ...this.statusData };
  }
  
  getState(): PlaybackState {
    return this.statusData.state;
  }
  
  getCurrentTime(): number {
    return this.statusData.currentTime;
  }
  
  getCurrentFrame(): number {
    return this.statusData.currentFrame;
  }
  
  getFormattedTime(): string {
    return formatTime(this.statusData.currentTime, this.statusData.duration > 3600);
  }
  
  getFormattedTimecode(): string {
    return formatTimecode(
      this.statusData.currentFrame,
      this.configData.frameRate,
      this.statusData.duration > 3600
    );
  }
  
  getDuration(): number {
    return this.statusData.duration;
  }
  
  getTotalFrames(): number {
    return this.statusData.totalFrames;
  }
  
  getCurrentFps(): number {
    return this.currentFps;
  }
  
  getDroppedFrames(): number {
    return this.droppedFramesData;
  }
  
  getCurrentFrameInfo(): FrameInfo {
    return {
      frameNumber: this.statusData.currentFrame,
      timestamp: this.statusData.currentTime,
      width: this.videoEl?.videoWidth || 0,
      height: this.videoEl?.videoHeight || 0,
    };
  }
  
  isPlaying(): boolean {
    return this.statusData.state === 'playing';
  }
  
  isMuted(): boolean {
    return this.statusData.isMuted;
  }
  
  isLooping(): boolean {
    return this.statusData.isLooping;
  }
  
  isReady(): boolean {
    return this.statusData.state === 'ready' || this.statusData.state === 'playing';
  }
  
  isLoaded(): boolean {
    return this.videoEl !== null;
  }
  
  // ============================================
  // Event Handlers
  // ============================================
  
  private onTimeUpdate(): void {
    if (!this.videoEl) return;
    
    this.statusData.currentTime = this.videoEl.currentTime;
    this.statusData.currentFrame = this.calcCurrentFrame();
    this.updatePerfMetrics();
    this.updateBufferProgress();
    
    this.emitTimeUpdate(this.statusData.currentTime);
    this.emitFrameUpdate(this.statusData.currentFrame);
  }
  
  private onPlay(): void {
    this.statusData.state = 'playing';
    this.statusData.isBuffering = false;
    this.startAnimationLoop();
    this.emitStateChange(this.statusData.state);
    this.emitPlay();
  }
  
  private onPause(): void {
    this.statusData.state = 'ready';
    this.stopAnimationLoop();
    this.emitStateChange(this.statusData.state);
    this.emitPause();
  }
  
  private onEnded(): void {
    this.stopAnimationLoop();
    
    if (this.statusData.isLooping) {
      this.seek(0).then(() => this.play());
    } else {
      this.statusData.state = 'ready';
      this.emitStateChange(this.statusData.state);
    }
    
    this.emitEnded();
  }
  
  private onWaiting(): void {
    this.statusData.state = 'loading';
    this.statusData.isBuffering = true;
    this.emitStateChange(this.statusData.state);
    this.emitWaiting();
  }
  
  private onCanPlay(): void {
    if (this.statusData.state === 'loading' && this.videoEl) {
      this.statusData.state = 'ready';
      this.statusData.isBuffering = false;
      this.statusData.duration = this.videoEl.duration || 0;
      this.statusData.totalFrames = this.calcTotalFrames();
      this.emitStateChange(this.statusData.state);
      this.emitCanPlay();
    }
  }
  
  private onError(): void {
    if (!this.videoEl) return;
    
    const error = this.videoEl.error;
    this.statusData.state = 'error';
    this.statusData.error = error?.message || 'Unknown video error';
    this.statusData.isBuffering = false;
    
    this.emitStateChange(this.statusData.state);
    
    const errorObj = error ? new Error(error.message) : new Error('Unknown video error');
    errorObj.name = 'VideoPlayerError';
    
    const err = new VideoPlayerError(
      `Video error: ${this.statusData.error}`,
      error?.code ? `VIDEO_ERROR_${error.code}` : 'VIDEO_ERROR',
      errorObj
    );
    this.emitError(err);
  }
  
  // ============================================
  // Animation & Performance
  // ============================================
  
  private startAnimationLoop(): void {
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
    }
    
    this.lastFrameTime = performance.now();
    this.frameCount = 0;
    this.frameTimes = [];
    
    const animate = (timestamp: number) => {
      if (this.statusData.state !== 'playing') {
        return;
      }
      
      const deltaTime = timestamp - this.lastFrameTime;
      this.frameTimes.push(deltaTime);
      
      if (this.frameTimes.length > 60) {
        this.frameTimes.shift();
      }
      
      this.frameCount++;
      if (this.frameCount >= 30) {
        const avgFrameTime = this.frameTimes.reduce((a, b) => a + b, 0) / this.frameTimes.length;
        this.currentFps = 1000 / avgFrameTime;
        this.emitFpsUpdate(this.currentFps);
        this.frameCount = 0;
      }
      
      this.lastFrameTime = timestamp;
      
      if (deltaTime > 33) {
        this.droppedFramesData++;
        this.emitDroppedFrame(this.droppedFramesData);
      }
      
      this.animationId = requestAnimationFrame(animate);
    };
    
    this.animationId = requestAnimationFrame(animate);
  }
  
  private stopAnimationLoop(): void {
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
  }
  
  private updatePerfMetrics(): void {
    const now = performance.now();
    if (now - this.lastPerfCheck > 1000) {
      this.lastPerfCheck = now;
      this.emitFpsUpdate(this.currentFps);
    }
  }
  
  private updateBufferProgress(): void {
    if (!this.videoEl || this.statusData.duration === Infinity) {
      return;
    }
    
    const buffered = this.videoEl.buffered;
    if (buffered.length > 0) {
      const bufferedEnd = buffered.end(buffered.length - 1);
      this.statusData.bufferProgress = bufferedEnd / this.statusData.duration;
      this.emitBufferUpdate(this.statusData.bufferProgress);
    }
  }
  
  // ============================================
  // Helper Methods
  // ============================================
  
  private calcCurrentFrame(): number {
    if (!this.videoEl) return 0;
    return secondsToFrame(this.videoEl.currentTime, this.configData.frameRate);
  }
  
  private calcTotalFrames(): number {
    if (!this.videoEl || !this.videoEl.duration) return 0;
    return Math.floor(this.videoEl.duration * this.configData.frameRate);
  }
  
  getVideoElement(): HTMLVideoElement | null {
    return this.videoEl;
  }
  
  getControls(): PlaybackControls {
    return {
      play: () => this.play(),
      pause: () => this.pause(),
      stop: () => this.stop(),
      togglePlay: () => this.togglePlay(),
      seek: (time: number) => this.seek(time),
      seekToFrame: (frame: number) => this.seekToFrame(frame),
      stepForward: (frames?: number) => this.stepForward(frames),
      stepBackward: (frames?: number) => this.stepBackward(frames),
      setPlaybackRate: (rate: PlaybackRate) => this.setPlaybackRate(rate),
      setVolume: (volume: number) => this.setVolume(volume),
      toggleMute: () => this.toggleMute(),
      toggleLoop: () => this.toggleLoop(),
    };
  }
  
  // ============================================
  // Cleanup
  // ============================================
  
  destroy(): void {
    this.detach();
    this.listeners.clear();
    this.statusData = {
      state: 'idle',
      currentTime: 0,
      currentFrame: 0,
      duration: 0,
      totalFrames: 0,
      playbackRate: 1,
      isMuted: false,
      isLooping: false,
      volume: 1,
      bufferProgress: 0,
      isBuffering: false,
    };
  }
}

// ============================================
// Singleton Instance
// ============================================

let defaultInstance: VideoPlayerService | null = null;

export function getDefaultVideoPlayerService(): VideoPlayerService {
  if (!defaultInstance) {
    defaultInstance = new VideoPlayerService();
  }
  return defaultInstance;
}

export function resetDefaultVideoPlayerService(): void {
  if (defaultInstance) {
    defaultInstance.destroy();
    defaultInstance = null;
  }
}

/**
 * Video Thumbnail Cache Unit Tests
 */

import { VideoThumbnailCache, ThumbnailEntry } from '../VideoThumbnailCache';

const createMockVideoElement = () => {
  return {
    currentTime: 0,
    videoWidth: 1920,
    videoHeight: 1080,
  } as HTMLVideoElement;
};

describe('VideoThumbnailCache', () => {
  let cache: VideoThumbnailCache;

  beforeEach(() => {
    cache = new VideoThumbnailCache({
      maxCacheSize: 10,
      thumbnailWidth: 160,
      thumbnailHeight: 90,
    });
  });

  afterEach(() => {
    cache.destroy();
  });

  describe('Initialization', () => {
    it('initializes with custom configuration', () => {
      expect(cache.maxSize).toBe(10);
    });

    it('initializes with default configuration', () => {
      const defaultCache = new VideoThumbnailCache();
      expect(defaultCache.maxSize).toBe(1000);
      defaultCache.destroy();
    });
  });

  describe('Cache Operations', () => {
    it('stores and retrieves thumbnails', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      
      const retrieved = cache.get('video-1', 0);
      expect(retrieved).toBeDefined();
      expect(retrieved?.frameNumber).toBe(0);
    });

    it('tracks cache statistics', () => {
      const stats = cache.getStats();
      expect(stats).toHaveProperty('size');
      expect(stats).toHaveProperty('maxSize');
      expect(stats).toHaveProperty('hits');
      expect(stats).toHaveProperty('misses');
      expect(stats).toHaveProperty('memoryUsage');
    });

    it('evicts old entries when cache is full', () => {
      for (let i = 0; i < 15; i++) {
        const entry: ThumbnailEntry = {
          key: `test-video:${i}`,
          videoId: 'test-video',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      const stats = cache.getStats();
      expect(stats.size).toBeLessThanOrEqual(10);
    });

    it('returns undefined for cache miss', () => {
      const result = cache.get('video-1', 999);
      expect(result).toBeUndefined();
    });
  });

  describe('Cache Invalidation', () => {
    it('deletes specific thumbnail', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      expect(cache.has('video-1', 0)).toBe(true);
      
      cache.delete('video-1', 0);
      expect(cache.has('video-1', 0)).toBe(false);
    });

    it('deletes all thumbnails for a video', () => {
      for (let i = 0; i < 5; i++) {
        const entry: ThumbnailEntry = {
          key: `video-1:${i}`,
          videoId: 'video-1',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      const deleted = cache.deleteVideo('video-1');
      expect(deleted).toBe(5);
      expect(cache.has('video-1', 0)).toBe(false);
    });

    it('clears entire cache', () => {
      for (let i = 0; i < 5; i++) {
        const entry: ThumbnailEntry = {
          key: `video-1:${i}`,
          videoId: 'video-1',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      cache.clear();
      expect(cache.size).toBe(0);
    });
  });

  describe('Hit Rate Tracking', () => {
    it('tracks hits correctly', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      
      // Access the entry
      cache.get('video-1', 0);
      
      const stats = cache.getStats();
      expect(stats.hits).toBeGreaterThan(0);
    });

    it('tracks misses correctly', () => {
      cache.get('video-1', 999);
      
      const stats = cache.getStats();
      expect(stats.misses).toBeGreaterThan(0);
    });

    it('calculates hit rate correctly', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      
      // Hit
      cache.get('video-1', 0);
      // Miss
      cache.get('video-1', 1);
      
      const stats = cache.getStats();
      expect(stats.hitRate).toBe(0.5);
    });
  });

  describe('Preloading', () => {
    it('cancels pending preloads for a video', () => {
      cache.requestPreload('video-1', 0, 100, 1);
      cache.requestPreload('video-2', 0, 100, 1);
      
      cache.cancelPreloads('video-1');
      
      // Queue should still have video-2 request
      expect((cache as unknown as { preloadQueue: unknown[] }).preloadQueue.length).toBeGreaterThanOrEqual(1);
    });
  });

  describe('Cleanup', () => {
    it('destroys cache and clears all data', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      cache.destroy();
      expect(cache.size).toBe(0);
    });

    it('resets statistics', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      cache.get('video-1', 0);
      
      cache.resetStats();
      
      const stats = cache.getStats();
      expect(stats.hits).toBe(0);
      expect(stats.misses).toBe(0);
    });
  });

  describe('Get Multiple', () => {
    it('retrieves multiple thumbnails at once', () => {
      for (let i = 0; i < 5; i++) {
        const entry: ThumbnailEntry = {
          key: `video-1:${i}`,
          videoId: 'video-1',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      const result = cache.getMultiple('video-1', [0, 2, 4]);
      expect(result.size).toBe(3);
      expect(result.has(0)).toBe(true);
      expect(result.has(2)).toBe(true);
      expect(result.has(4)).toBe(true);
    });
  });
});

/**
 * Voice HTTP Client
 * 
 * Handles HTTP communication with the backend for voice recording synchronization
 * Uses the fetch API for making HTTP requests
 */

import type { VoiceRecording, PhraseData } from '@/types';

/**
 * Voice HTTP Client Configuration
 */
export interface VoiceHttpConfig {
  baseUrl: string;
  timeout: number;
  retryAttempts: number;
}

/**
 * Default configuration for Voice HTTP Client
 */
const DEFAULT_VOICE_CONFIG: VoiceHttpConfig = {
  baseUrl: import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000',
  timeout: 120000, // 2 minutes for TTS generation
  retryAttempts: 3,
};

/**
 * API response types for voice operations
 */
export interface VoiceApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

/**
 * Voice recording upload response
 */
export interface VoiceUploadResponse {
  recordingId: string;
  status: 'uploaded' | 'processing' | 'completed' | 'failed';
  message: string;
  timestamp: string;
}

/**
 * Phrase synchronization response
 */
export interface PhraseSyncResponse {
  phraseId: string;
  recordingId: string;
  syncStatus: 'synced' | 'pending' | 'failed';
  timestamp: string;
}

/**
 * Voice HTTP Client Class
 */
export class VoiceHttpClient {
  private config: VoiceHttpConfig;

  constructor(config?: Partial<VoiceHttpConfig>) {
    this.config = { ...DEFAULT_VOICE_CONFIG, ...config };
  }

  /**
   * Upload voice recording to backend
   * 
   * @param recording - Voice recording data
   * @returns Upload response with recording ID
   */
  async uploadVoiceRecording(
    recording: VoiceRecording
  ): Promise<VoiceApiResponse<VoiceUploadResponse>> {
    try {
      const formData = new FormData();
      formData.append('audio', recording.audioBlob, recording.filename);
      formData.append('metadata', JSON.stringify({
        userId: recording.userId,
        sessionId: recording.sessionId,
        timestamp: recording.timestamp,
        duration: recording.duration,
        sampleRate: recording.sampleRate,
      }));

      const response = await this.fetchWithRetry('/api/voice/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to upload voice recording',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Synchronize phrase data with backend
   * 
   * @param phrase - Phrase data to synchronize
   * @returns Synchronization response
   */
  async syncPhraseData(
    phrase: PhraseData
  ): Promise<VoiceApiResponse<PhraseSyncResponse>> {
    try {
      const response = await this.fetchWithRetry('/api/voice/phrase/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(phrase),
      });

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to synchronize phrase data',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get voice recording status
   * 
   * @param recordingId - ID of the recording to check
   * @returns Status response
   */
  async getRecordingStatus(
    recordingId: string
  ): Promise<VoiceApiResponse<VoiceUploadResponse>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/status/${recordingId}`
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to get recording status',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get all recordings for a session
   * 
   * @param sessionId - Session ID to get recordings for
   * @returns List of voice recordings
   */
  async getSessionRecordings(
    sessionId: string
  ): Promise<VoiceApiResponse<VoiceRecording[]>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/session/${sessionId}`
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to get session recordings',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Delete a voice recording
   * 
   * @param recordingId - ID of the recording to delete
   * @returns Deletion response
   */
  async deleteRecording(
    recordingId: string
  ): Promise<VoiceApiResponse<void>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/delete/${recordingId}`,
        {
          method: 'DELETE',
        }
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to delete recording',
        };
      }

      return {
        success: true,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Fetch with retry logic for voice operations
   * 
   * @param url - URL to fetch
   * @param options - Fetch options
   * @returns Fetch response
   */
  private async fetchWithRetry(
    url: string,
    options?: RequestInit
  ): Promise<Response> {
    const fullUrl = `${this.config.baseUrl}${url}`;
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < this.config.retryAttempts; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(
          () => controller.abort(),
          this.config.timeout
        );

        const response = await fetch(fullUrl, {
          ...options,
          signal: controller.signal,
        });

        clearTimeout(timeoutId);
        return response;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error('Unknown error');

        // Don't retry on abort (timeout)
        if (error instanceof Error && error.name === 'AbortError') {
          throw new Error('Request timeout');
        }

        // Wait before retry (exponential backoff)
        if (attempt < this.config.retryAttempts - 1) {
          await this.delay(Math.pow(2, attempt) * 1000);
        }
      }
    }

    throw lastError || new Error('Failed after retries');
  }

  /**
   * Delay helper
   * 
   * @param ms - Milliseconds to delay
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Update voice HTTP configuration
   * 
   * @param config - New configuration
   */
  updateConfig(config: Partial<VoiceHttpConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current configuration
   * 
   * @returns Current voice HTTP configuration
   */
  getConfig(): VoiceHttpConfig {
    return { ...this.config };
  }
}

/**
 * Default Voice HTTP Client instance
 */
export const voiceHttpClient = new VoiceHttpClient();

/**
 * Mock Voice HTTP Client for development/testing
