  });

  describe('generateUniqueId', () => {
    it('should generate unique IDs with prefix', () => {
      const id1 = generateUniqueId('shot');
      const id2 = generateUniqueId('shot');
      
      expect(id1).toMatch(/^shot_\d+$/);
      expect(id2).toMatch(/^shot_\d+$/);
