 */
export function getRecoveryActions(error: WizardError): string[] {
  const template = generateErrorMessage(error);
  return template.recoveryInstructions;
}

/**
 * Check if an error is actionable by the user
 * 
 * @param error - WizardError instance
 * @returns True if user can take action to resolve the error
 */
export function isErrorActionable(error: WizardError): boolean {
  const template = generateErrorMessage(error);
  return template.actionable;
}

/**
 * Error Logging System
 * 
 * Enhanced error logging with file rotation, project-specific logs,
 * and comprehensive error tracking for wizard operations.
 * 
 * Requirements: 13.7
 */

import { WizardError } from './types';
import { getLogger, type WizardLogger } from './logger';
import { joinPath } from './pathUtils';

/**
 * Error log entry with enhanced metadata
 */
export interface ErrorLogEntry {
  timestamp: string;
  errorId: string;
  category: string;
  message: string;
  stack?: string;
  details?: Record<string, unknown>;
  recoverable: boolean;
  retryable: boolean;
  userMessage: string;
  context?: {
    projectPath?: string;
    wizardType?: string;
    operation?: string;
    userId?: string;
  };
}

/**
 * Log rotation configuration
 */
export interface LogRotationConfig {
  maxLogSizeBytes: number;
  maxLogFiles: number;
  rotateOnStartup: boolean;
}

/**
 * Error logger configuration
 */
export interface ErrorLoggerConfig {
  projectPath?: string;
  logDirectory: string;
  logFilePrefix: string;
  rotation: LogRotationConfig;
  includeStackTrace: boolean;
  includeSensitiveData: boolean;
}

/**
 * Default error logger configuration
 */
const DEFAULT_CONFIG: ErrorLoggerConfig = {
  logDirectory: 'logs',
  logFilePrefix: 'editor',
  rotation: {
    maxLogSizeBytes: 10 * 1024 * 1024, // 10 MB
    maxLogFiles: 5,
    rotateOnStartup: false,
  },
  includeStackTrace: true,
  includeSensitiveData: false,
};

/**
 * Error Logger Class
 * Manages error logging with file rotation and project-specific organization
 * 
 * Requirements: 13.7
 */
export class ErrorLogger {
  private config: ErrorLoggerConfig;
  private logger: WizardLogger;
  private errorLogs: ErrorLogEntry[] = [];
  private currentLogFile: string;

  constructor(config?: Partial<ErrorLoggerConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.logger = getLogger();
    this.currentLogFile = this.generateLogFilename();

    if (this.config.rotation.rotateOnStartup) {
      this.rotateLogsIfNeeded();
    }
  }

  /**
   * Log a wizard error with full context
   * 
   * @param error - WizardError instance
   * @param context - Additional context information
   * 
   * Requirements: 13.7
   */
  logError(
    error: WizardError,
    context?: {
      projectPath?: string;
      wizardType?: string;
      operation?: string;
      userId?: string;
    }
  ): void {
    const errorId = this.generateErrorId();
    const timestamp = new Date().toISOString();

    const entry: ErrorLogEntry = {
      timestamp,
      errorId,
      category: error.category,
      message: error.message,
      stack: this.config.includeStackTrace ? error.stack : undefined,
      details: this.sanitizeDetails(error.details),
      recoverable: error.recoverable,
      retryable: error.retryable,
      userMessage: error.getUserMessage(),
      context: context || {},
    };

    // Add to in-memory log
    this.errorLogs.unshift(entry);

    // Log to wizard logger
    this.logger.logWizardError(error, context);

    // Persist to file
    this.persistErrorLog(entry);

    // Check if rotation is needed
    this.rotateLogsIfNeeded();
  }

  /**
   * Log error to project-specific log file
   * Format: projects/{project_name}/logs/editor_{date}.log
   * 
   * @param entry - Error log entry
   * 
   * Requirements: 13.7
   */
  private persistErrorLog(entry: ErrorLogEntry): void {
    try {
      const logPath = this.getLogFilePath();
      const logLine = this.formatLogEntry(entry);

      // In browser environment, use localStorage with project-specific key
      const storageKey = this.getStorageKey();
      const existingLogs = this.getStoredErrorLogs(storageKey);

      existingLogs.unshift(entry);

      // Keep only recent errors (last 100 per project)
      const trimmedLogs = existingLogs.slice(0, 100);

      localStorage.setItem(storageKey, JSON.stringify(trimmedLogs));

      this.logger.debug('error-logger', 'Error logged to storage', {
        errorId: entry.errorId,
        logPath,
        storageKey,
      });
    } catch (error) {
      this.logger.warn('error-logger', 'Failed to persist error log', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  /**
   * Get log file path for current project
   * 
   * @returns Log file path
   */
  private getLogFilePath(): string {
    const date = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
    const filename = `${this.config.logFilePrefix}_${date}.log`;

    if (this.config.projectPath) {
      return joinPath(this.config.projectPath, this.config.logDirectory, filename);
    }

    return joinPath(this.config.logDirectory, filename);
  }

  /**
   * Get storage key for current project
   * 
   * @returns Storage key
   */
  private getStorageKey(): string {
    const date = new Date().toISOString().split('T')[0];
    const projectKey = this.config.projectPath
      ? this.config.projectPath.replace(/[^a-zA-Z0-9]/g, '_')
      : 'default';

    return `error_logs_${projectKey}_${date}`;
  }

  /**
   * Get stored error logs from localStorage
   * 
   * @param storageKey - Storage key
   * @returns Array of error log entries
   */
  private getStoredErrorLogs(storageKey: string): ErrorLogEntry[] {
    try {
      const stored = localStorage.getItem(storageKey);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  }

  /**
   * Format error log entry for file output
   * 
   * @param entry - Error log entry
   * @returns Formatted log line
   */
  private formatLogEntry(entry: ErrorLogEntry): string {
    const parts = [
      `[${entry.timestamp}]`,
      `[${entry.errorId}]`,
      `[${entry.category.toUpperCase()}]`,
      entry.message,
    ];

    if (entry.context?.operation) {
      parts.push(`Operation: ${entry.context.operation}`);
    }

    if (entry.context?.wizardType) {
      parts.push(`Wizard: ${entry.context.wizardType}`);
    }

    if (entry.details) {
      parts.push(`Details: ${JSON.stringify(entry.details)}`);
    }

    if (entry.stack) {
      parts.push(`\nStack: ${entry.stack}`);
    }

    return parts.join(' ') + '\n';
  }

  /**
   * Generate unique error ID
   * 
   * @returns Error ID
   */
  private generateErrorId(): string {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8);
    return `ERR_${timestamp}_${random}`;
  }

  /**
   * Generate log filename with date
   * 
   * @returns Log filename
   */
  private generateLogFilename(): string {
    const date = new Date().toISOString().split('T')[0];
    return `${this.config.logFilePrefix}_${date}.log`;
  }

  /**
   * Sanitize error details to remove sensitive data
   * 
   * @param details - Raw error details
   * @returns Sanitized details
   */
  private sanitizeDetails(details?: Record<string, unknown>): Record<string, unknown> | undefined {
    if (!details) {
      return undefined;
    }

    if (this.config.includeSensitiveData) {
      return details;
    }

    const sanitized: Record<string, unknown> = {};
    const sensitiveKeys = ['password', 'token', 'apiKey', 'secret', 'credential'];

    for (const [key, value] of Object.entries(details)) {
      const lowerKey = key.toLowerCase();
      const isSensitive = sensitiveKeys.some((sk) => lowerKey.includes(sk));

      if (isSensitive) {
        sanitized[key] = '[REDACTED]';
      } else if (typeof value === 'object' && value !== null) {
        sanitized[key] = this.sanitizeDetails(value);
      } else {
        sanitized[key] = value;
      }
    }

    return sanitized;
  }

  /**
   * Rotate logs if size limit is exceeded
   * 
   * Requirements: 13.7
   */
  private rotateLogsIfNeeded(): void {
    try {
      const storageKey = this.getStorageKey();
      const logs = this.getStoredErrorLogs(storageKey);

      // Calculate approximate size (rough estimate)
      const approximateSize = JSON.stringify(logs).length;

      if (approximateSize > this.config.rotation.maxLogSizeBytes) {
        this.logger.info('error-logger', 'Rotating logs due to size limit', {
          approximateSize,
          maxSize: this.config.rotation.maxLogSizeBytes,
        });

        // Keep only the most recent logs (half of max)
        const trimmedLogs = logs.slice(0, Math.floor(logs.length / 2));
        localStorage.setItem(storageKey, JSON.stringify(trimmedLogs));

        // Archive old logs
        this.archiveOldLogs(logs.slice(Math.floor(logs.length / 2)));
      }
    } catch (error) {
      this.logger.warn('error-logger', 'Failed to rotate logs', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  /**
   * Archive old logs to separate storage
   * 
   * @param logs - Logs to archive
   */
  private archiveOldLogs(logs: ErrorLogEntry[]): void {
    try {
      const archiveKey = `${this.getStorageKey()}_archive_${Date.now()}`;
      localStorage.setItem(archiveKey, JSON.stringify(logs));

      this.logger.info('error-logger', 'Logs archived', {
        archiveKey,
        logCount: logs.length,
      });

      // Clean up old archives (keep only last N)
      this.cleanupOldArchives();
    } catch (error) {
      this.logger.warn('error-logger', 'Failed to archive logs', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  /**
   * Clean up old archived logs
   */
  private cleanupOldArchives(): void {
    try {
      const archiveKeys: string[] = [];

      // Find all archive keys
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.includes('_archive_')) {
          archiveKeys.push(key);
        }
      }

      // Sort by timestamp (newest first)
      archiveKeys.sort((a, b) => {
        const timestampA = parseInt(a.split('_archive_')[1] || '0');
        const timestampB = parseInt(b.split('_archive_')[1] || '0');
        return timestampB - timestampA;
      });

      // Remove old archives beyond max count
      const toRemove = archiveKeys.slice(this.config.rotation.maxLogFiles);
      toRemove.forEach((key) => {
        localStorage.removeItem(key);
        this.logger.debug('error-logger', 'Removed old archive', { key });
      });

      if (toRemove.length > 0) {
        this.logger.info('error-logger', 'Cleaned up old archives', {
          removedCount: toRemove.length,
        });
      }
    } catch (error) {
      this.logger.warn('error-logger', 'Failed to cleanup old archives', {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  /**
   * Get all error logs with optional filtering
   * 
   * @param filter - Optional filter criteria
   * @returns Array of error log entries
   */
  getErrorLogs(filter?: {
    category?: string;
    startTime?: Date;
    endTime?: Date;
    recoverable?: boolean;
    retryable?: boolean;
  }): ErrorLogEntry[] {
    let filtered = [...this.errorLogs];

    if (filter) {
      if (filter.category) {
        filtered = filtered.filter((log) => log.category === filter.category);
      }

      if (filter.startTime) {
        filtered = filtered.filter(
          (log) => new Date(log.timestamp) >= filter.startTime!
        );
      }

      if (filter.endTime) {
        filtered = filtered.filter(
          (log) => new Date(log.timestamp) <= filter.endTime!
        );
      }

      if (filter.recoverable !== undefined) {
        filtered = filtered.filter((log) => log.recoverable === filter.recoverable);
      }

      if (filter.retryable !== undefined) {
        filtered = filtered.filter((log) => log.retryable === filter.retryable);
      }
    }

    return filtered;
  }

  /**
   * Get error log by ID
   * 
   * @param errorId - Error ID
   * @returns Error log entry or undefined
   */
  getErrorById(errorId: string): ErrorLogEntry | undefined {
    return this.errorLogs.find((log) => log.errorId === errorId);
  }

  /**
   * Get error statistics
   * 
   * @returns Error statistics
   */
  getStatistics(): {
    total: number;
    byCategory: Record<string, number>;
    recoverable: number;
    retryable: number;
  } {
    const stats = {
      total: this.errorLogs.length,
      byCategory: {} as Record<string, number>,
      recoverable: 0,
      retryable: 0,
    };

    this.errorLogs.forEach((log) => {
      stats.byCategory[log.category] = (stats.byCategory[log.category] || 0) + 1;
      if (log.recoverable) stats.recoverable++;
      if (log.retryable) stats.retryable++;
    });

    return stats;
  }

  /**
   * Export error logs as JSON
   * 
   * @param filter - Optional filter criteria
   * @returns JSON string of error logs
   */
  exportLogs(filter?: Parameters<typeof this.getErrorLogs>[0]): string {
    const logs = this.getErrorLogs(filter);
    return JSON.stringify(logs, null, 2);
  }

  /**
   * Download error logs as file
   * 
   * @param filter - Optional filter criteria
   */
  downloadLogs(filter?: Parameters<typeof this.getErrorLogs>[0]): void {
    const logs = this.exportLogs(filter);
    const blob = new Blob([logs], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const filename = this.generateLogFilename().replace('.log', '_errors.json');
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();

    URL.revokeObjectURL(url);
  }

  /**
   * Clear error logs from memory
   */
  clearLogs(): void {
    this.errorLogs = [];
  }

  /**
   * Update configuration
   * 
   * @param config - Partial configuration update
   */
  updateConfig(config: Partial<ErrorLoggerConfig>): void {
    this.config = { ...this.config, ...config };
    this.logger.info('error-logger', 'Configuration updated', this.config);
  }

  /**
   * Get current configuration
   * 
   * @returns Current configuration
   */
  getConfig(): ErrorLoggerConfig {
    return { ...this.config };
  }
}

/**
 * Singleton error logger instance
 */
let errorLoggerInstance: ErrorLogger | null = null;

/**
 * Get the singleton error logger instance
 */
export function getErrorLogger(): ErrorLogger {
  if (!errorLoggerInstance) {
    errorLoggerInstance = new ErrorLogger();
  }
  return errorLoggerInstance;
}

/**
 * Create a new error logger instance
 */
export function createErrorLogger(config?: Partial<ErrorLoggerConfig>): ErrorLogger {
  return new ErrorLogger(config);
}

/**
 * Set the singleton error logger instance
 */
export function setErrorLogger(logger: ErrorLogger): void {
  errorLoggerInstance = logger;
}

/**
 * Log a wizard error using singleton logger
 * 
 * @param error - WizardError instance
 * @param context - Additional context
 * 
 * Requirements: 13.7
 */
export function logWizardError(
  error: WizardError,
  context?: Parameters<ErrorLogger['logError']>[1]
): void {
  const logger = getErrorLogger();
  logger.logError(error, context);
}

/**
 * Wizard Logging Service
 * 
 * Provides structured logging for wizard operations with file persistence
 * and filtering capabilities.
 * 
 * Requirements: 13.7
 */

import type { LogEntry, LogFilter } from './types';
import { WizardError } from './types';
import { generateUniqueFilename } from './pathUtils';

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

/**
 * Logger configuration
 */
export interface LoggerConfig {
  level: LogLevel;
  enableConsole: boolean;
  enableFile: boolean;
  maxLogSize: number; // Maximum number of log entries in memory
  logDirectory?: string;
}

const DEFAULT_CONFIG: LoggerConfig = {
  level: 'info',
  enableConsole: true,
  enableFile: true,
  maxLogSize: 1000,
};

/**
 * Wizard Logger Service
 */
export class WizardLogger {
  private config: LoggerConfig;
  private logs: LogEntry[] = [];
  private logLevels: Record<LogLevel, number> = {
    debug: 0,
    info: 1,
    warn: 2,
    error: 3,
  };

  constructor(config: Partial<LoggerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Log a debug message
   */
  debug(category: string, message: string, details?: Record<string, unknown>): void {
    this.log('debug', category, message, details);
  }

  /**
   * Log an info message
   */
  info(category: string, message: string, details?: Record<string, unknown>): void {
    this.log('info', category, message, details);
  }

  /**
   * Log a warning message
   */
  warn(category: string, message: string, details?: Record<string, unknown>): void {
    this.log('warn', category, message, details);
  }

  /**
   * Log an error message
   */
  error(
    category: string,
    message: string,
    error?: Error | WizardError,
    details?: Record<string, unknown>
  ): void {
    this.log('error', category, message, { ...details, error });
  }

  /**
   * Log a wizard error
   */
  logWizardError(error: WizardError, context?: Record<string, unknown>): void {
    this.error(
      error.category,
      error.message,
      error,
      {
        ...context,
        recoverable: error.recoverable,
        retryable: error.retryable,
        details: error.details,
      }
    );
  }

  /**
   * Core logging method
   */
  private log(
    level: LogLevel,
    category: string,
    message: string,
    details?: Record<string, unknown>
  ): void {
    // Check if this log level should be recorded
    if (this.logLevels[level] < this.logLevels[this.config.level]) {
      return;
    }

    const entry: any = {
      timestamp: new Date().toISOString(),
      level,
      category,
      message,
      details,
      error: details?.error,
    };

    // Add to in-memory log
    this.logs.unshift(entry);

    // Trim log if too large
    if (this.logs.length > this.config.maxLogSize) {
      this.logs = this.logs.slice(0, this.config.maxLogSize);
    }

    // Console output
    if (this.config.enableConsole) {
      this.logToConsole(entry);
    }

    // File output (in browser, we'll use localStorage as a fallback)
    if (this.config.enableFile) {
      this.persistLog(entry);
    }
  }

  /**
   * Log to console with appropriate formatting
   */
  private logToConsole(entry: LogEntry): void {
    // Suppress connection errors for optional services (Ollama/ComfyUI)
    // These are expected when services aren't installed/running
    if (entry.level === 'error' && entry.category === 'connection') {
      // Only show connection errors in debug mode
      if (this.config.level !== 'debug') {
        return;
      }
    }

    const prefix = `[${entry.timestamp}] [${entry.level.toUpperCase()}] [${entry.category}]`;
    const message = `${prefix} ${entry.message}`;

    switch (entry.level) {
      case 'debug':
        console.debug(message, entry.details);
        break;
      case 'info':
        console.info(message, entry.details);
        break;
      case 'warn':
        console.warn(message, entry.details);
        break;
      case 'error':
        console.error(message, entry.details, entry.error);
        break;
    }
  }

  /**
   * Persist log entry to storage
   * In browser environment, uses localStorage
   * In Node environment, would write to file
   */
  private persistLog(entry: LogEntry): void {
    try {
      // Get existing logs from storage
      const storageKey = 'wizard_logs';
      const existingLogs = this.getStoredLogs();

      // Add new entry
      existingLogs.unshift(entry);

      // Keep only recent logs (last 500)
      const trimmedLogs = existingLogs.slice(0, 500);

      // Save back to storage
      localStorage.setItem(storageKey, JSON.stringify(trimmedLogs));
    } catch (error) {
      // Silently fail if storage is not available
      console.warn('Failed to persist log entry:', error);
    }
  }

  /**
   * Get logs from storage
   */
  private getStoredLogs(): LogEntry[] {
    try {
      const storageKey = 'wizard_logs';
      const stored = localStorage.getItem(storageKey);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  }

  /**
   * Get all logs with optional filtering
   */
  getLogs(filter?: LogFilter): LogEntry[] {
    let filtered = [...this.logs];

    if (filter) {
      if (filter.level) {
        const minLevel = this.logLevels[filter.level];
        filtered = filtered.filter(
          (log) => this.logLevels[log.level] >= minLevel
        );
      }

      if (filter.category) {
        filtered = filtered.filter((log) => log.category === filter.category);
      }

      if (filter.startTime) {
        filtered = filtered.filter(
          (log) => new Date(log.timestamp) >= filter.startTime!
        );
      }

      if (filter.endTime) {
        filtered = filtered.filter(
          (log) => new Date(log.timestamp) <= filter.endTime!
        );
      }
    }

    return filtered;
  }

  /**
   * Get logs by category
   */
  getLogsByCategory(category: string): LogEntry[] {
    return this.logs.filter((log) => log.category === category);
  }

  /**
   * Get error logs only
   */
  getErrorLogs(): LogEntry[] {
    return this.logs.filter((log) => log.level === 'error');
  }

  /**
   * Clear all logs from memory
   */
  clearLogs(): void {
    this.logs = [];
  }

  /**
   * Clear logs from storage
   */
  clearStoredLogs(): void {
    try {
      localStorage.removeItem('wizard_logs');
    } catch (error) {
      console.warn('Failed to clear stored logs:', error);
    }
  }

  /**
   * Export logs as JSON string
   */
  exportLogs(filter?: LogFilter): string {
    const logs = this.getLogs(filter);
    return JSON.stringify(logs, null, 2);
  }

  /**
   * Export logs to file (browser download)
   */
  downloadLogs(filter?: LogFilter): void {
    const logs = this.exportLogs(filter);
    const blob = new Blob([logs], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const filename = generateUniqueFilename('wizard_logs', 'json');
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();

    URL.revokeObjectURL(url);
  }

  /**
   * Get log statistics
   */
  getStatistics(): {
    total: number;
    byLevel: Record<LogLevel, number>;
    byCategory: Record<string, number>;
  } {
    const stats = {
      total: this.logs.length,
      byLevel: {
        debug: 0,
        info: 0,
        warn: 0,
        error: 0,
      } as Record<LogLevel, number>,
      byCategory: {} as Record<string, number>,
    };

    this.logs.forEach((log) => {
      stats.byLevel[log.level]++;
      stats.byCategory[log.category] = (stats.byCategory[log.category] || 0) + 1;
    });

    return stats;
  }

  /**
   * Set log level
   */
  setLevel(level: LogLevel): void {
    this.config.level = level;
  }

  /**
   * Get current log level
   */
  getLevel(): LogLevel {
    return this.config.level;
  }

  /**
   * Enable/disable console logging
   */
  setConsoleLogging(enabled: boolean): void {
    this.config.enableConsole = enabled;
  }

  /**
   * Enable/disable file logging
   */
  setFileLogging(enabled: boolean): void {
    this.config.enableFile = enabled;
  }
}

/**
 * Singleton logger instance
 */
let loggerInstance: WizardLogger | null = null;

/**
 * Get the singleton logger instance
 */
export function getLogger(): WizardLogger {
  if (!loggerInstance) {
    loggerInstance = new WizardLogger();
  }
  return loggerInstance;
}

/**
 * Create a new logger instance with custom configuration
 */
export function createLogger(config?: Partial<LoggerConfig>): WizardLogger {
  return new WizardLogger(config);
}

/**
 * Helper function to log wizard operations
 */
export function logWizardOperation(
  operation: string,
  status: 'started' | 'completed' | 'failed',
  details?: Record<string, unknown>
): void {
  const logger = getLogger();
  const message = `Wizard operation ${operation} ${status}`;

  if (status === 'failed') {
    logger.error('wizard', message, undefined, details);
  } else {
    logger.info('wizard', message, details);
  }
}

/**
 * Cross-Platform Path Utilities
 * 
 * Provides cross-platform file path handling utilities.
 * Ensures compatibility across Windows, Linux, and macOS.
 * 
 * Note: This is a browser-compatible implementation that mimics Node.js path module behavior.
 * 
 * Requirements: 15.1, 15.2, 15.3, 15.4, 15.5, 15.6
 */

// Detect platform separator (for display purposes)
const isWindowsPath = (path: string): boolean => /^[a-zA-Z]:\\/.test(path) || path.includes('\\');
const POSIX_SEP = '/';
const WIN_SEP = '\\';

/**
 * Join path segments using forward slashes (standard for web/storage)
 * 
 * @param segments - Path segments to join
 * @returns Joined path with forward slashes
 */
export function joinPath(...segments: string[]): string {
  // Filter out empty segments
  const filtered = segments.filter(seg => seg && seg.length > 0);
  
  if (filtered.length === 0) {
    return '.';
  }
  
  // Join with forward slash and normalize
  let joined = filtered.join(POSIX_SEP);
  
  // Normalize multiple slashes
  joined = joined.replace(/\/+/g, POSIX_SEP);
  
  // Remove trailing slash unless it's the root
  if (joined.length > 1 && joined.endsWith(POSIX_SEP)) {
    joined = joined.slice(0, -1);
  }
  
  return joined;
}

/**
 * Normalize a path to use forward slashes (for storage in JSON)
 * 
 * @param filePath - Path to normalize
 * @returns Path with forward slashes
 */
export function normalizePath(filePath: string): string {
  return filePath.replace(/\\/g, POSIX_SEP).replace(/\/+/g, POSIX_SEP);
}

/**
 * Convert a stored path (with forward slashes) to platform-specific format
 * For browser environment, this returns the path as-is with forward slashes
 * 
 * @param storedPath - Path with forward slashes from JSON
 * @returns Path (forward slashes for web compatibility)
 */
export function toPlatformPath(storedPath: string): string {
  // In browser environment, always use forward slashes
  return normalizePath(storedPath);
}

/**
 * Get the directory name from a path
 * 
 * @param filePath - Full file path
 * @returns Directory path
 */
export function getDirName(filePath: string): string {
  const normalized = normalizePath(filePath);
  const lastSlash = normalized.lastIndexOf(POSIX_SEP);
  
  if (lastSlash === -1) {
    return '.';
  }
  
  if (lastSlash === 0) {
    return POSIX_SEP;
  }
  
  return normalized.slice(0, lastSlash);
}

/**
 * Get the base name (filename with extension) from a path
 * 
 * @param filePath - Full file path
 * @returns Filename with extension
 */
export function getBaseName(filePath: string): string {
  const normalized = normalizePath(filePath);
  const lastSlash = normalized.lastIndexOf(POSIX_SEP);
  return lastSlash === -1 ? normalized : normalized.slice(lastSlash + 1);
}

/**
 * Get the file extension from a path
 * 
 * @param filePath - Full file path
 * @returns File extension (including the dot)
 */
export function getExtension(filePath: string): string {
  const base = getBaseName(filePath);
  const lastDot = base.lastIndexOf('.');
  
  if (lastDot === -1 || lastDot === 0) {
    return '';
  }
  
  return base.slice(lastDot);
}

/**
 * Get the filename without extension
 * 
 * @param filePath - Full file path
 * @returns Filename without extension
 */
export function getFileNameWithoutExt(filePath: string): string {
  const base = getBaseName(filePath);
  const ext = getExtension(filePath);
  return ext ? base.slice(0, -ext.length) : base;
}

/**
 * Check if a path is absolute
 * 
 * @param filePath - Path to check
 * @returns True if path is absolute
 */
export function isAbsolute(filePath: string): boolean {
  // Check for Windows absolute path (C:\, D:\, etc.)
  if (/^[a-zA-Z]:[\\\/]/.test(filePath)) {
    return true;
  }
  
  // Check for Unix absolute path (starts with /)
  if (filePath.startsWith(POSIX_SEP)) {
    return true;
  }
  
  return false;
}

/**
 * Resolve a relative path to an absolute path
 * Note: In browser environment, this is limited - mainly for path manipulation
 * 
 * @param basePath - Base directory path
 * @param relativePath - Relative path to resolve
 * @returns Resolved path
 */
export function resolvePath(basePath: string, relativePath: string): string {
  if (isAbsolute(relativePath)) {
    return normalizePath(relativePath);
  }
  
  return joinPath(basePath, relativePath);
}

/**
 * Get the relative path from one path to another
 * 
 * @param from - Starting path
 * @param to - Target path
 * @returns Relative path from 'from' to 'to'
 */
export function getRelativePath(from: string, to: string): string {
  const fromParts = normalizePath(from).split(POSIX_SEP).filter(p => p);
  const toParts = normalizePath(to).split(POSIX_SEP).filter(p => p);
  
  // Find common base
  let commonLength = 0;
  const minLength = Math.min(fromParts.length, toParts.length);
  
  for (let i = 0; i < minLength; i++) {
    if (fromParts[i] === toParts[i]) {
      commonLength++;
    } else {
      break;
    }
  }
  
  // Build relative path
  const upCount = fromParts.length - commonLength;
  const relativeParts = Array(upCount).fill('..');
  const remainingParts = toParts.slice(commonLength);
  
  return joinPath(...relativeParts, ...remainingParts);
}

/**
 * Ensure a path uses forward slashes (standard for web)
 * Handles both forward slashes and backslashes in input
 * 
 * @param filePath - Path to normalize
 * @returns Path with forward slashes
 */
export function ensurePlatformSeparator(filePath: string): string {
  return normalizePath(filePath);
}

/**
 * Build a project file path following the documented pattern
 * 
 * @param projectPath - Base project directory path
 * @param category - File category (e.g., 'characters', 'scenes', 'shots')
 * @param filename - Filename
 * @returns Full file path
 */
export function buildProjectFilePath(
  projectPath: string,
  category: string,
  filename: string
): string {
  return joinPath(projectPath, category, filename);
}

/**
 * Build an asset file path following the documented pattern
 * 
 * @param projectPath - Base project directory path
 * @param assetType - Asset type ('images', 'audio', 'video')
 * @param filename - Filename
 * @returns Full file path
 */
export function buildAssetFilePath(
  projectPath: string,
  assetType: 'images' | 'audio' | 'video',
  filename: string
): string {
  return joinPath(projectPath, 'assets', assetType, filename);
}

/**
 * Generate a unique filename with timestamp
 * 
 * @param prefix - Filename prefix
 * @param extension - File extension (without dot)
 * @returns Unique filename
 */
export function generateUniqueFilename(prefix: string, extension: string): string {
  const timestamp = Date.now();
  return `${prefix}_${timestamp}.${extension}`;
}

/**
 * Generate a unique ID following the documented pattern
 * 
 * @param prefix - ID prefix (e.g., 'shot', 'char', 'scene')
 * @param index - Optional index for sequential IDs
 * @returns Unique ID
 */
export function generateUniqueId(prefix: string, index?: number): string {
  const timestamp = Date.now();
  if (index !== undefined) {
    return `${prefix}_${timestamp}_${index}`;
  }
  return `${prefix}_${timestamp}`;
}

/**
 * Sanitize a filename to remove invalid characters
 * 
 * @param filename - Original filename
 * @returns Sanitized filename safe for all platforms
 */
export function sanitizeFilename(filename: string): string {
  // Remove or replace characters that are invalid on Windows, macOS, or Linux
  return filename
    .replace(/[<>:"|?*]/g, '') // Windows invalid chars
    .replace(/\//g, '-') // Forward slash
    .replace(/\\/g, '-') // Backslash
    .replace(/\s+/g, '_') // Replace spaces with underscores
    .replace(/\.+/g, '.') // Collapse multiple dots
    .replace(/^\./, '') // Remove leading dot
    .trim();
}

/**
 * Validate that a path is safe (no directory traversal)
 * 
 * @param basePath - Base directory that should contain the path
 * @param targetPath - Path to validate
 * @returns True if path is safe
 */
export function isSafePath(basePath: string, targetPath: string): boolean {
  const normalizedBase = normalizePath(basePath);
  const normalizedTarget = normalizePath(targetPath);
  
  // Resolve the target path relative to base
  const resolved = resolvePath(normalizedBase, normalizedTarget);
  
  // Check if resolved path starts with base path
  return resolved.startsWith(normalizedBase);
}

/**
 * Get the path separator (always forward slash for web)
 * 
 * @returns Path separator
 */
export function getPathSeparator(): string {
  return POSIX_SEP;
}

/**
 * Check if the current platform is Windows
 * In browser environment, this checks the user agent
 * 
 * @returns True if running on Windows
 */
export function isWindows(): boolean {
  if (typeof navigator !== 'undefined') {
    return navigator.platform.toLowerCase().includes('win');
  }
  return false;
}

/**
 * Format a path for display in the UI (always use forward slashes)
 * 
 * @param filePath - Path to format
 * @returns Path formatted for display
 */
export function formatPathForDisplay(filePath: string): string {
  return normalizePath(filePath);
}

/**
 * Parse a file path into its components
 * 
 * @param filePath - Path to parse
 * @returns Object with path components
 */
export function parseFilePath(filePath: string): {
  dir: string;
  base: string;
  ext: string;
  name: string;
} {
  const normalized = normalizePath(filePath);
  const dir = getDirName(normalized);
  const base = getBaseName(normalized);
  const ext = getExtension(normalized);
  const name = getFileNameWithoutExt(normalized);
  
  return { dir, base, ext, name };
}

/**
 * Retry Logic Module
 * 
 * Provides retry functionality for failed operations with exponential backoff,
 * request parameter preservation, and retry state management.
 * 
 * Requirements: 13.2, 13.4
 */

import { WizardError } from './types';
import { getLogger } from './logger';

/**
 * Retry configuration
 */
export interface RetryConfig {
  maxAttempts: number;
  initialDelayMs: number;
  maxDelayMs: number;
  backoffMultiplier: number;
  retryableErrors?: string[];
}

/**
 * Retry state for tracking retry attempts
 */
export interface RetryState<T = any> {
  operationId: string;
  operation: string;
  parameters: T;
  attemptCount: number;
  lastError?: WizardError;
  lastAttemptTime?: Date;
  nextRetryTime?: Date;
  canRetry: boolean;
}

/**
 * Retry result
 */
export interface RetryResult<T> {
  success: boolean;
  result?: T;
  error?: WizardError;
  attemptCount: number;
  totalDuration: number;
}

/**
 * Default retry configuration
 */
const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  initialDelayMs: 1000,
  maxDelayMs: 10000,
  backoffMultiplier: 2,
};

/**
 * Retry manager class
 * Manages retry state and execution for failed operations
 * 
 * Requirements: 13.2, 13.4
 */
export class RetryManager {
  private logger = getLogger();
  private retryStates: Map<string, RetryState> = new Map();
  private config: RetryConfig;

  constructor(config?: Partial<RetryConfig>) {
    this.config = { ...DEFAULT_RETRY_CONFIG, ...config };
  }

  /**
   * Execute operation with retry logic
   * 
   * @param operationId - Unique identifier for the operation
   * @param operation - Function to execute
   * @param parameters - Parameters to pass to the operation
   * @param config - Optional retry configuration override
   * @returns Retry result with success status and result/error
   * 
   * Requirements: 13.2, 13.4
   */
  async executeWithRetry<T, P = any>(
    operationId: string,
    operation: (params: P) => Promise<T>,
    parameters: P,
    config?: Partial<RetryConfig>
  ): Promise<RetryResult<T>> {
    const retryConfig = { ...this.config, ...config };
    const startTime = Date.now();

    this.logger.info('retry', 'Starting operation with retry', {
      operationId,
      maxAttempts: retryConfig.maxAttempts,
    });

    // Initialize or get existing retry state
    let retryState = this.retryStates.get(operationId);
    if (!retryState) {
      retryState = {
        operationId,
        operation: operationId,
        parameters,
        attemptCount: 0,
        canRetry: true,
      };
      this.retryStates.set(operationId, retryState);
    } else {
      // Update parameters for retry
      retryState.parameters = parameters;
    }

    let lastError: WizardError | undefined;
    let delayMs = retryConfig.initialDelayMs;

    for (let attempt = 1; attempt <= retryConfig.maxAttempts; attempt++) {
      retryState.attemptCount = attempt;
      retryState.lastAttemptTime = new Date();

      this.logger.debug('retry', `Attempt ${attempt}/${retryConfig.maxAttempts}`, {
        operationId,
        attempt,
      });

      try {
        const result = await operation(parameters);

        const totalDuration = Date.now() - startTime;

        this.logger.info('retry', 'Operation succeeded', {
          operationId,
          attempt,
          totalDuration,
        });

        // Clear retry state on success
        this.retryStates.delete(operationId);

        return {
          success: true,
          result,
          attemptCount: attempt,
          totalDuration,
        };
      } catch (error) {
        const wizardError = error instanceof WizardError
          ? error
          : new WizardError(
            error instanceof Error ? error.message : 'Unknown error',
            'unknown',
            true,
            true,
            { originalError: error }
          );

        lastError = wizardError;
        retryState.lastError = wizardError;

        this.logger.warn('retry', `Attempt ${attempt} failed`, {
          operationId,
          attempt,
          error: wizardError.message,
          category: wizardError.category,
          retryable: wizardError.retryable,
        });

        // Check if error is retryable
        if (!wizardError.retryable) {
          this.logger.info('retry', 'Error is not retryable, stopping', {
            operationId,
            category: wizardError.category,
          });

          retryState.canRetry = false;
          break;
        }

        // Don't delay after last attempt
        if (attempt < retryConfig.maxAttempts) {
          const nextRetryTime = new Date(Date.now() + delayMs);
          retryState.nextRetryTime = nextRetryTime;

          this.logger.debug('retry', `Waiting ${delayMs}ms before retry`, {
            operationId,
            attempt,
            delayMs,
            nextRetryTime,
          });

          await this.delay(delayMs);

          // Exponential backoff with max delay cap
          delayMs = Math.min(
            delayMs * retryConfig.backoffMultiplier,
            retryConfig.maxDelayMs
          );
        }
      }
    }

    const totalDuration = Date.now() - startTime;

    this.logger.error('retry', 'Operation failed after all retry attempts', lastError!, {
      operationId,
      attempts: retryConfig.maxAttempts,
      totalDuration,
    });

    retryState.canRetry = false;

    return {
      success: false,
      error: lastError,
      attemptCount: retryConfig.maxAttempts,
      totalDuration,
    };
  }

  /**
   * Get retry state for an operation
   * 
   * @param operationId - Operation identifier
   * @returns Retry state or undefined if not found
   */
  getRetryState(operationId: string): RetryState | undefined {
    return this.retryStates.get(operationId);
  }

  /**
   * Check if an operation can be retried
   * 
   * @param operationId - Operation identifier
   * @returns True if operation can be retried
   */
  canRetry(operationId: string): boolean {
    const state = this.retryStates.get(operationId);
    return state?.canRetry ?? false;
  }

  /**
   * Get preserved parameters for retry
   * 
   * @param operationId - Operation identifier
   * @returns Preserved parameters or undefined
   * 
   * Requirements: 13.4
   */
  getPreservedParameters<T = any>(operationId: string): T | undefined {
    const state = this.retryStates.get(operationId);
    return state?.parameters as T | undefined;
  }

  /**
   * Clear retry state for an operation
   * 
   * @param operationId - Operation identifier
   */
  clearRetryState(operationId: string): void {
    this.retryStates.delete(operationId);
    this.logger.debug('retry', 'Retry state cleared', { operationId });
  }

  /**
   * Clear all retry states
   */
  clearAllRetryStates(): void {
    this.retryStates.clear();
    this.logger.debug('retry', 'All retry states cleared');
  }

  /**
   * Get all retry states
   * 
   * @returns Array of all retry states
   */
  getAllRetryStates(): RetryState[] {
    return Array.from(this.retryStates.values());
  }

  /**
   * Update retry configuration
   * 
   * @param config - Partial retry configuration
   */
  updateConfig(config: Partial<RetryConfig>): void {
    this.config = { ...this.config, ...config };
    this.logger.info('retry', 'Retry configuration updated', this.config as any);
  }

  /**
   * Get current retry configuration
   * 
   * @returns Current retry configuration
   */
  getConfig(): RetryConfig {
    return { ...this.config };
  }

  /**
   * Delay helper for retry logic
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * Singleton retry manager instance
 */
let retryManagerInstance: RetryManager | null = null;

/**
 * Get the singleton retry manager instance
 */
export function getRetryManager(): RetryManager {
  if (!retryManagerInstance) {
    retryManagerInstance = new RetryManager();
  }
  return retryManagerInstance;
}

/**
 * Create a new retry manager instance
 */
export function createRetryManager(config?: Partial<RetryConfig>): RetryManager {
  return new RetryManager(config);
}

/**
 * Set the singleton retry manager instance
 */
export function setRetryManager(manager: RetryManager): void {
  retryManagerInstance = manager;
}

/**
 * Execute operation with retry using singleton manager
 * 
 * @param operationId - Unique identifier for the operation
 * @param operation - Function to execute
 * @param parameters - Parameters to pass to the operation
 * @param config - Optional retry configuration override
 * @returns Retry result
 * 
 * Requirements: 13.2, 13.4
 */
export async function executeWithRetry<T, P = any>(
  operationId: string,
  operation: (params: P) => Promise<T>,
  parameters: P,
  config?: Partial<RetryConfig>
): Promise<RetryResult<T>> {
  const manager = getRetryManager();
  return manager.executeWithRetry(operationId, operation, parameters, config);
}

/**
 * Get preserved parameters for retry using singleton manager
 * 
 * @param operationId - Operation identifier
 * @returns Preserved parameters or undefined
 * 
 * Requirements: 13.4
 */
export function getPreservedParameters<T = any>(operationId: string): T | undefined {
  const manager = getRetryManager();
  return manager.getPreservedParameters<T>(operationId);
}

/**
 * Check if operation can be retried using singleton manager
 * 
 * @param operationId - Operation identifier
 * @returns True if operation can be retried
 */
export function canRetry(operationId: string): boolean {
  const manager = getRetryManager();
  return manager.canRetry(operationId);
}

/**
 * Clear retry state using singleton manager
 * 
 * @param operationId - Operation identifier
 */
export function clearRetryState(operationId: string): void {
  const manager = getRetryManager();
  manager.clearRetryState(operationId);
}

/**
 * Wizard Session Preservation Module
 * 
 * Provides session preservation functionality for wizard workflows,
 * allowing users to resume interrupted sessions with preserved form data.
 * 
 * Requirements: 13.5, 13.6
 */

import { getLogger } from './logger';
import type { WizardType } from './types';

/**
 * Preserved session data
 */
export interface PreservedSession {
  wizardId: string;
  wizardType: WizardType;
  currentStep: number;
  totalSteps: number;
  formData: Record<string, unknown>;
  timestamp: string;
  expiresAt: string;
}

/**
 * Session preservation configuration
 */
export interface SessionPreservationConfig {
  expirationHours: number;
  storageKey: string;
  autoSave: boolean;
  autoSaveIntervalMs: number;
}

/**
 * Default session preservation configuration
 */
const DEFAULT_CONFIG: SessionPreservationConfig = {
  expirationHours: 24,
  storageKey: 'wizard_sessions',
  autoSave: true,
  autoSaveIntervalMs: 30000, // 30 seconds
};

/**
 * Session preservation manager
 * Manages wizard session state persistence and restoration
 * 
 * Requirements: 13.5, 13.6
 */
export class SessionPreservationManager {
  private logger = getLogger();
  private config: SessionPreservationConfig;
  private autoSaveTimers: Map<string, NodeJS.Timeout> = new Map();

  constructor(config?: Partial<SessionPreservationConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Save wizard session to localStorage
   * 
   * @param wizardId - Unique wizard identifier
   * @param wizardType - Type of wizard
   * @param currentStep - Current step number
   * @param totalSteps - Total number of steps
   * @param formData - Form data to preserve
   * 
   * Requirements: 13.5
   */
  saveSession(
    wizardId: string,
    wizardType: WizardType,
    currentStep: number,
    totalSteps: number,
    formData: Record<string, unknown>
  ): void {
    try {
      const timestamp = new Date().toISOString();
      const expiresAt = new Date(
        Date.now() + this.config.expirationHours * 60 * 60 * 1000
      ).toISOString();

      const session: PreservedSession = {
        wizardId,
        wizardType,
        currentStep,
        totalSteps,
        formData: this.sanitizeFormData(formData),
        timestamp,
        expiresAt,
      };

      // Get existing sessions
      const sessions = this.getAllSessions();

      // Update or add session
      const existingIndex = sessions.findIndex((s) => s.wizardId === wizardId);
      if (existingIndex >= 0) {
        sessions[existingIndex] = session;
      } else {
        sessions.push(session);
      }

      // Save to localStorage
      localStorage.setItem(this.config.storageKey, JSON.stringify(sessions));

      this.logger.info('session', 'Wizard session saved', {
        wizardId,
        wizardType,
        currentStep,
        expiresAt,
      });
    } catch (error) {
      this.logger.error('session', 'Failed to save wizard session', error as Error, {
        wizardId,
        wizardType,
      });
    }
  }

  /**
   * Load wizard session from localStorage
   * 
   * @param wizardId - Wizard identifier
   * @returns Preserved session or undefined if not found or expired
   * 
   * Requirements: 13.5, 13.6
   */
  loadSession(wizardId: string): PreservedSession | undefined {
    try {
      const sessions = this.getAllSessions();
      const session = sessions.find((s) => s.wizardId === wizardId);

      if (!session) {
        this.logger.debug('session', 'No preserved session found', { wizardId });
        return undefined;
      }

      // Check if session has expired
      const expiresAt = new Date(session.expiresAt);
      const now = new Date();

      if (now > expiresAt) {
        this.logger.info('session', 'Preserved session has expired', {
          wizardId,
          expiresAt: session.expiresAt,
        });

        // Remove expired session
        this.deleteSession(wizardId);
        return undefined;
      }

      this.logger.info('session', 'Wizard session loaded', {
        wizardId,
        wizardType: session.wizardType,
        currentStep: session.currentStep,
        age: now.getTime() - new Date(session.timestamp).getTime(),
      });

      return session;
    } catch (error) {
      this.logger.error('session', 'Failed to load wizard session', error as Error, {
        wizardId,
      });
      return undefined;
    }
  }

  /**
   * Delete wizard session
   * 
   * @param wizardId - Wizard identifier
   */
  deleteSession(wizardId: string): void {
    try {
      const sessions = this.getAllSessions();
      const filtered = sessions.filter((s) => s.wizardId !== wizardId);

      localStorage.setItem(this.config.storageKey, JSON.stringify(filtered));

      // Clear auto-save timer if exists
      this.stopAutoSave(wizardId);

      this.logger.info('session', 'Wizard session deleted', { wizardId });
    } catch (error) {
      this.logger.error('session', 'Failed to delete wizard session', error as Error, {
        wizardId,
      });
    }
  }

  /**
   * Get all preserved sessions
   * 
   * @returns Array of preserved sessions
   */
  getAllSessions(): PreservedSession[] {
    try {
      const stored = localStorage.getItem(this.config.storageKey);
      if (!stored) {
        return [];
      }

      const sessions: PreservedSession[] = JSON.parse(stored);
      return sessions;
    } catch (error) {
      this.logger.error('session', 'Failed to get all sessions', error as Error);
      return [];
    }
  }

  /**
   * Get sessions by wizard type
   * 
   * @param wizardType - Type of wizard
   * @returns Array of preserved sessions for the wizard type
   */
  getSessionsByType(wizardType: WizardType): PreservedSession[] {
    const sessions = this.getAllSessions();
    return sessions.filter((s) => s.wizardType === wizardType);
  }

  /**
   * Check if a session exists and is valid
   * 
   * @param wizardId - Wizard identifier
   * @returns True if session exists and is not expired
   */
  hasValidSession(wizardId: string): boolean {
    const session = this.loadSession(wizardId);
    return session !== undefined;
  }

  /**
   * Clean up expired sessions
   * Removes all sessions that have passed their expiration time
   * 
   * @returns Number of sessions removed
   */
  cleanupExpiredSessions(): number {
    try {
      const sessions = this.getAllSessions();
      const now = new Date();

      const validSessions = sessions.filter((session) => {
        const expiresAt = new Date(session.expiresAt);
        return now <= expiresAt;
      });

      const removedCount = sessions.length - validSessions.length;

      if (removedCount > 0) {
        localStorage.setItem(this.config.storageKey, JSON.stringify(validSessions));

        this.logger.info('session', 'Expired sessions cleaned up', {
          removedCount,
          remainingCount: validSessions.length,
        });
      }

      return removedCount;
    } catch (error) {
      this.logger.error('session', 'Failed to cleanup expired sessions', error as Error);
      return 0;
    }
  }

  /**
   * Start auto-save for a wizard session
   * 
   * @param wizardId - Wizard identifier
   * @param wizardType - Type of wizard
   * @param getSessionData - Function to get current session data
   * 
   * Requirements: 13.5
   */
  startAutoSave(
    wizardId: string,
    wizardType: WizardType,
    getSessionData: () => {
      currentStep: number;
      totalSteps: number;
      formData: Record<string, unknown>;
    }
  ): void {
    if (!this.config.autoSave) {
      return;
    }

    // Clear existing timer if any
    this.stopAutoSave(wizardId);

    const timer = setInterval(() => {
      try {
        const data = getSessionData();
        this.saveSession(
          wizardId,
          wizardType,
          data.currentStep,
          data.totalSteps,
          data.formData
        );

        this.logger.debug('session', 'Auto-save completed', { wizardId });
      } catch (error) {
        this.logger.error('session', 'Auto-save failed', error as Error, { wizardId });
      }
    }, this.config.autoSaveIntervalMs);

    this.autoSaveTimers.set(wizardId, timer);

    this.logger.info('session', 'Auto-save started', {
      wizardId,
      intervalMs: this.config.autoSaveIntervalMs,
    });
  }

  /**
   * Stop auto-save for a wizard session
   * 
   * @param wizardId - Wizard identifier
   */
  stopAutoSave(wizardId: string): void {
    const timer = this.autoSaveTimers.get(wizardId);
    if (timer) {
      clearInterval(timer);
      this.autoSaveTimers.delete(wizardId);

      this.logger.info('session', 'Auto-save stopped', { wizardId });
    }
  }

  /**
   * Stop all auto-save timers
   */
  stopAllAutoSave(): void {
    this.autoSaveTimers.forEach((timer, wizardId) => {
      clearInterval(timer);
      this.logger.debug('session', 'Auto-save stopped', { wizardId });
    });

    this.autoSaveTimers.clear();
    this.logger.info('session', 'All auto-save timers stopped');
  }

  /**
   * Sanitize form data before saving
   * Removes sensitive data and non-serializable values
   * 
   * @param formData - Raw form data
   * @returns Sanitized form data
   */
  private sanitizeFormData(formData: Record<string, unknown>): Record<string, unknown> {
    const sanitized: Record<string, unknown> = {};

    for (const [key, value] of Object.entries(formData)) {
      // Skip functions and undefined values
      if (typeof value === 'function' || value === undefined) {
        continue;
      }

      // Skip File objects (can't be serialized)
      if (value instanceof File) {
        sanitized[key] = {
          _type: 'File',
          name: value.name,
          size: value.size,
          type: value.type,
        };
        continue;
      }

      // Handle arrays
      if (Array.isArray(value)) {
        sanitized[key] = value.map((item) => {
          if (item instanceof File) {
            return {
              _type: 'File',
              name: item.name,
              size: item.size,
              type: item.type,
            };
          }
          return item;
        });
        continue;
      }

      // Handle objects
      if (typeof value === 'object' && value !== null) {
        sanitized[key] = this.sanitizeFormData(value as Record<string, unknown>);
        continue;
      }

      // Primitive values
      sanitized[key] = value;
    }

    return sanitized;
  }

  /**
   * Update configuration
   * 
   * @param config - Partial configuration update
   */
  updateConfig(config: Partial<SessionPreservationConfig>): void {
    this.config = { ...this.config, ...config };
    this.logger.info('session', 'Configuration updated', this.config as any);
  }

  /**
   * Get current configuration
   * 
   * @returns Current configuration
   */
  getConfig(): SessionPreservationConfig {
    return { ...this.config };
  }
}

/**
 * Singleton session preservation manager instance
 */
let sessionManagerInstance: SessionPreservationManager | null = null;

/**
 * Get the singleton session preservation manager instance
 */
export function getSessionManager(): SessionPreservationManager {
  if (!sessionManagerInstance) {
    sessionManagerInstance = new SessionPreservationManager();
  }
  return sessionManagerInstance;
}

/**
 * Create a new session preservation manager instance
 */
export function createSessionManager(
  config?: Partial<SessionPreservationConfig>
): SessionPreservationManager {
  return new SessionPreservationManager(config);
}

/**
 * Set the singleton session preservation manager instance
 */
export function setSessionManager(manager: SessionPreservationManager): void {
  sessionManagerInstance = manager;
}

/**
 * Save wizard session using singleton manager
 * 
 * @param wizardId - Wizard identifier
 * @param wizardType - Type of wizard
 * @param currentStep - Current step number
 * @param totalSteps - Total number of steps
 * @param formData - Form data to preserve
 * 
 * Requirements: 13.5
 */
export function saveWizardSession(
  wizardId: string,
  wizardType: WizardType,
  currentStep: number,
  totalSteps: number,
  formData: Record<string, unknown>
): void {
  const manager = getSessionManager();
  manager.saveSession(wizardId, wizardType, currentStep, totalSteps, formData);
}

/**
 * Load wizard session using singleton manager
 * 
 * @param wizardId - Wizard identifier
 * @returns Preserved session or undefined
 * 
 * Requirements: 13.5, 13.6
 */
export function loadWizardSession(wizardId: string): PreservedSession | undefined {
  const manager = getSessionManager();
  return manager.loadSession(wizardId);
}

/**
 * Delete wizard session using singleton manager
 * 
 * @param wizardId - Wizard identifier
 */
export function deleteWizardSession(wizardId: string): void {
  const manager = getSessionManager();
  manager.deleteSession(wizardId);
}

/**
 * Check if wizard has valid preserved session
 * 
 * @param wizardId - Wizard identifier
 * @returns True if valid session exists
 */
export function hasValidWizardSession(wizardId: string): boolean {
