      expect(useStore.getState().isPlaying).toBe(false);
      expect(useStore.getState().currentTime).toBe(0);
    });

    it('should set playback speed', () => {
      useStore.getState().setPlaybackSpeed(2);
      expect(useStore.getState().playbackSpeed).toBe(2);
    });
  });

  describe('Undo/Redo', () => {
