      pushOperation(op2);
      undo();
      
      const undoStack = getUndoStack();
      const redoStack = getRedoStack();
      
      expect(undoStack).toHaveLength(1);
      expect(undoStack[0]).toEqual(op1);
      expect(redoStack).toHaveLength(1);
      expect(redoStack[0]).toEqual(op2);
