      setCharacterSearchQuery('h');
      setCharacterSearchQuery('he');
      setCharacterSearchQuery('her');
      setCharacterSearchQuery('hero');

      const { characterSearchQuery } = useAppStore.getState();
      expect(characterSearchQuery).toBe('hero');
    });
  });
});

/**
 * Property-Based Tests for ViewportStore Transformations
 * 
 * Task 2.6: Write property tests for viewport transformations
 * 
 * These tests verify:
 * - Property 17: Zoom Center Preservation
 * - Property 18: Viewport Pan Delta
 * 
 * Validates: Requirements 7.1, 7.2
 */

import { describe, it, expect, beforeEach } from 'vitest';
import * as fc from 'fast-check';
import { useViewportStore, type Point } from '../viewportStore';

describe('ViewportStore Transformations - Property-Based Tests', () => {
  beforeEach(() => {
    // Reset viewport to default state
    useViewportStore.getState().resetViewport();
  });

  describe('Property 17: Zoom Center Preservation', () => {
    it('should keep the point under cursor at same screen position when zooming', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Initial viewport state
          fc.record({
            zoom: fc.double({ min: 0.5, max: 5.0, noNaN: true }),
            pan: fc.record({
              x: fc.integer({ min: -1000, max: 1000 }),
              y: fc.integer({ min: -1000, max: 1000 }),
            }),
          }),
          // Cursor position (point to preserve)
          fc.record({
            x: fc.integer({ min: 0, max: 1920 }),
            y: fc.integer({ min: 0, max: 1080 }),
          }),
          // New zoom level
          fc.double({ min: 0.1, max: 10.0, noNaN: true }),
          async (initialState, cursorPoint, newZoom) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setZoom(initialState.zoom);
            useViewportStore.getState().setPan(initialState.pan);
            
            // Convert cursor point to canvas coordinates before zoom
            const canvasPointBefore = useViewportStore.getState().screenToCanvas(cursorPoint);
            
            // Zoom to point (this should preserve the cursor position)
            useViewportStore.getState().zoomToPoint(newZoom, cursorPoint);
            
            // Convert the same canvas point back to screen coordinates after zoom
            const screenPointAfter = useViewportStore.getState().canvasToScreen(canvasPointBefore);
            
            // Property: The screen position should be preserved (within floating point tolerance)
            const tolerance = 0.1; // Allow small floating point errors
            expect(Math.abs(screenPointAfter.x - cursorPoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(screenPointAfter.y - cursorPoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should preserve center point when zooming from any initial state', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Initial zoom and pan
          fc.record({
            zoom: fc.double({ min: 0.5, max: 5.0, noNaN: true }),
            pan: fc.record({
              x: fc.integer({ min: -500, max: 500 }),
              y: fc.integer({ min: -500, max: 500 }),
            }),
          }),
          // Center point to preserve
          fc.record({
            x: fc.integer({ min: 500, max: 1420 }), // Center region of 1920px viewport
            y: fc.integer({ min: 300, max: 780 }), // Center region of 1080px viewport
          }),
          // Zoom factor
          fc.double({ min: 0.5, max: 2.0, noNaN: true }),
          async (initialState, centerPoint, zoomFactor) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setZoom(initialState.zoom);
            useViewportStore.getState().setPan(initialState.pan);
            
            const oldZoom = useViewportStore.getState().zoom;
            const newZoom = Math.max(0.1, Math.min(10.0, oldZoom * zoomFactor));
            
            // Get canvas coordinates before zoom
            const canvasPointBefore = useViewportStore.getState().screenToCanvas(centerPoint);
            
            // Zoom to point
            useViewportStore.getState().zoomToPoint(newZoom, centerPoint);
            
            // Get screen coordinates after zoom
            const screenPointAfter = useViewportStore.getState().canvasToScreen(canvasPointBefore);
            
            // Property: Center point should remain at same screen position
            const tolerance = 0.5;
            expect(Math.abs(screenPointAfter.x - centerPoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(screenPointAfter.y - centerPoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should maintain zoom center across multiple zoom operations', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Fixed point to preserve
          fc.record({
            x: fc.integer({ min: 400, max: 1520 }),
            y: fc.integer({ min: 200, max: 880 }),
          }),
          // Sequence of zoom operations
          fc.array(
            fc.double({ min: 0.5, max: 3.0, noNaN: true }),
            { minLength: 2, maxLength: 5 }
          ),
          async (fixedPoint, zoomSequence) => {
            // Reset viewport
            useViewportStore.getState().resetViewport();
            
            // Get initial canvas coordinates
            const initialCanvasPoint = useViewportStore.getState().screenToCanvas(fixedPoint);
            
            // Apply sequence of zooms
            for (const zoomFactor of zoomSequence) {
              const currentZoom = useViewportStore.getState().zoom;
              const newZoom = Math.max(0.1, Math.min(10.0, currentZoom * zoomFactor));
              useViewportStore.getState().zoomToPoint(newZoom, fixedPoint);
            }
            
            // Get final screen coordinates
            const finalScreenPoint = useViewportStore.getState().canvasToScreen(initialCanvasPoint);
            
            // Property: After multiple zooms, the point should still be at same screen position
            const tolerance = 1.0; // Slightly larger tolerance for accumulated errors
            expect(Math.abs(finalScreenPoint.x - fixedPoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(finalScreenPoint.y - fixedPoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should handle zoom center preservation at viewport edges', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Edge points (corners and edges of viewport)
          fc.constantFrom(
            { x: 0, y: 0 },       // Top-left corner
            { x: 1920, y: 0 },    // Top-right corner
            { x: 0, y: 1080 },    // Bottom-left corner
            { x: 1920, y: 1080 }, // Bottom-right corner
            { x: 960, y: 0 },     // Top edge center
            { x: 960, y: 1080 },  // Bottom edge center
            { x: 0, y: 540 },     // Left edge center
            { x: 1920, y: 540 }   // Right edge center
          ),
          // Zoom level
          fc.double({ min: 0.5, max: 5.0, noNaN: true }),
          async (edgePoint, newZoom) => {
            // Reset viewport
            useViewportStore.getState().resetViewport();
            
            // Get canvas coordinates before zoom
            const canvasPointBefore = useViewportStore.getState().screenToCanvas(edgePoint);
            
            // Zoom to edge point
            useViewportStore.getState().zoomToPoint(newZoom, edgePoint);
            
            // Get screen coordinates after zoom
            const screenPointAfter = useViewportStore.getState().canvasToScreen(canvasPointBefore);
            
            // Property: Edge point should be preserved
            const tolerance = 0.5;
            expect(Math.abs(screenPointAfter.x - edgePoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(screenPointAfter.y - edgePoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('Property 18: Viewport Pan Delta', () => {
    it('should change pan offset by exactly the delta amount', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Initial pan state
          fc.record({
            x: fc.integer({ min: -1000, max: 1000 }),
            y: fc.integer({ min: -1000, max: 1000 }),
          }),
          // Pan delta
          fc.record({
            x: fc.integer({ min: -500, max: 500 }),
            y: fc.integer({ min: -500, max: 500 }),
          }),
          async (initialPan, delta) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setPan(initialPan);
            
            // Apply pan delta
            useViewportStore.getState().panBy(delta);
            
            // Property: New pan should equal initial pan plus delta
            const newPan = useViewportStore.getState().pan;
            expect(newPan.x).toBe(initialPan.x + delta.x);
            expect(newPan.y).toBe(initialPan.y + delta.y);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should accumulate multiple pan deltas correctly', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Initial pan state
          fc.record({
            x: fc.integer({ min: -500, max: 500 }),
            y: fc.integer({ min: -500, max: 500 }),
          }),
          // Sequence of pan deltas
          fc.array(
            fc.record({
              x: fc.integer({ min: -100, max: 100 }),
              y: fc.integer({ min: -100, max: 100 }),
            }),
            { minLength: 1, maxLength: 10 }
          ),
          async (initialPan, deltas) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setPan(initialPan);
            
            // Calculate expected final pan
            const expectedPan = deltas.reduce(
              (acc, delta) => ({
                x: acc.x + delta.x,
                y: acc.y + delta.y,
              }),
              initialPan
            );
            
            // Apply all deltas
            for (const delta of deltas) {
              useViewportStore.getState().panBy(delta);
            }
            
            // Property: Final pan should equal sum of all deltas
            const finalPan = useViewportStore.getState().pan;
            expect(finalPan.x).toBe(expectedPan.x);
            expect(finalPan.y).toBe(expectedPan.y);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should handle zero delta (no-op)', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.record({
            x: fc.integer({ min: -1000, max: 1000 }),
            y: fc.integer({ min: -1000, max: 1000 }),
          }),
          async (initialPan) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setPan(initialPan);
            
            // Apply zero delta
            useViewportStore.getState().panBy({ x: 0, y: 0 });
            
            // Property: Pan should remain unchanged
            const newPan = useViewportStore.getState().pan;
            expect(newPan.x).toBe(initialPan.x);
            expect(newPan.y).toBe(initialPan.y);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should handle negative deltas (panning in opposite direction)', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.record({
            x: fc.integer({ min: -500, max: 500 }),
            y: fc.integer({ min: -500, max: 500 }),
          }),
          fc.record({
            x: fc.integer({ min: -500, max: 500 }),
            y: fc.integer({ min: -500, max: 500 }),
          }),
          async (initialPan, delta) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setPan(initialPan);
            
            // Pan forward
            useViewportStore.getState().panBy(delta);
            const panAfterForward = useViewportStore.getState().pan;
            
            // Pan backward (negative delta)
            useViewportStore.getState().panBy({ x: -delta.x, y: -delta.y });
            
            // Property: Should return to initial pan
            const finalPan = useViewportStore.getState().pan;
            expect(finalPan.x).toBe(initialPan.x);
            expect(finalPan.y).toBe(initialPan.y);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should maintain pan delta independence from zoom level', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Zoom level
          fc.double({ min: 0.5, max: 5.0, noNaN: true }),
          // Initial pan
          fc.record({
            x: fc.integer({ min: -500, max: 500 }),
            y: fc.integer({ min: -500, max: 500 }),
          }),
          // Pan delta
          fc.record({
            x: fc.integer({ min: -200, max: 200 }),
            y: fc.integer({ min: -200, max: 200 }),
          }),
          async (zoom, initialPan, delta) => {
            // Reset and set initial state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setZoom(zoom);
            useViewportStore.getState().setPan(initialPan);
            
            // Apply pan delta
            useViewportStore.getState().panBy(delta);
            
            // Property: Pan delta should be independent of zoom level
            const newPan = useViewportStore.getState().pan;
            expect(newPan.x).toBe(initialPan.x + delta.x);
            expect(newPan.y).toBe(initialPan.y + delta.y);
            
            // Zoom level should remain unchanged
            expect(useViewportStore.getState().zoom).toBe(zoom);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('Coordinate Transformation Properties', () => {
    it('should maintain round-trip consistency (screen -> canvas -> screen)', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Viewport state
          fc.record({
            zoom: fc.double({ min: 0.5, max: 5.0, noNaN: true }),
            pan: fc.record({
              x: fc.integer({ min: -500, max: 500 }),
              y: fc.integer({ min: -500, max: 500 }),
            }),
          }),
          // Screen point
          fc.record({
            x: fc.integer({ min: 0, max: 1920 }),
            y: fc.integer({ min: 0, max: 1080 }),
          }),
          async (viewportState, screenPoint) => {
            // Reset and set viewport state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setZoom(viewportState.zoom);
            useViewportStore.getState().setPan(viewportState.pan);
            
            // Transform screen -> canvas -> screen
            const canvasPoint = useViewportStore.getState().screenToCanvas(screenPoint);
            const backToScreen = useViewportStore.getState().canvasToScreen(canvasPoint);
            
            // Property: Round trip should preserve coordinates
            const tolerance = 0.01; // Very small tolerance for floating point
            expect(Math.abs(backToScreen.x - screenPoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(backToScreen.y - screenPoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should maintain round-trip consistency (canvas -> screen -> canvas)', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Viewport state
          fc.record({
            zoom: fc.double({ min: 0.5, max: 5.0, noNaN: true }),
            pan: fc.record({
              x: fc.integer({ min: -500, max: 500 }),
              y: fc.integer({ min: -500, max: 500 }),
            }),
          }),
          // Canvas point
          fc.record({
            x: fc.integer({ min: -1000, max: 3000 }),
            y: fc.integer({ min: -1000, max: 3000 }),
          }),
          async (viewportState, canvasPoint) => {
            // Reset and set viewport state
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setZoom(viewportState.zoom);
            useViewportStore.getState().setPan(viewportState.pan);
            
            // Transform canvas -> screen -> canvas
            const screenPoint = useViewportStore.getState().canvasToScreen(canvasPoint);
            const backToCanvas = useViewportStore.getState().screenToCanvas(screenPoint);
            
            // Property: Round trip should preserve coordinates
            const tolerance = 0.01;
            expect(Math.abs(backToCanvas.x - canvasPoint.x)).toBeLessThan(tolerance);
            expect(Math.abs(backToCanvas.y - canvasPoint.y)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should scale coordinates correctly with zoom', async () => {
      await fc.assert(
        fc.asyncProperty(
          // Two different zoom levels
          fc.double({ min: 0.5, max: 2.0, noNaN: true }),
          fc.double({ min: 0.5, max: 2.0, noNaN: true }),
          // Canvas point (exclude origin to avoid division by zero)
          fc.record({
            x: fc.integer({ min: 10, max: 1000 }),
            y: fc.integer({ min: 10, max: 1000 }),
          }),
          async (zoom1, zoom2, canvasPoint) => {
            // Skip if zooms are too similar
            if (Math.abs(zoom1 - zoom2) < 0.1) return;
            
            // Reset viewport with no pan for simplicity
            useViewportStore.getState().resetViewport();
            useViewportStore.getState().setPan({ x: 0, y: 0 });
            
            // Transform at zoom1
            useViewportStore.getState().setZoom(zoom1);
            const screen1 = useViewportStore.getState().canvasToScreen(canvasPoint);
            
            // Transform at zoom2
            useViewportStore.getState().setZoom(zoom2);
            const screen2 = useViewportStore.getState().canvasToScreen(canvasPoint);
            
            // Property: Screen coordinates should scale proportionally with zoom
            const expectedRatio = zoom2 / zoom1;
            const actualRatioX = screen2.x / screen1.x;
            const actualRatioY = screen2.y / screen1.y;
            
            const tolerance = 0.01;
            expect(Math.abs(actualRatioX - expectedRatio)).toBeLessThan(tolerance);
            expect(Math.abs(actualRatioY - expectedRatio)).toBeLessThan(tolerance);
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('Viewport State Consistency', () => {
    it('should maintain consistent state across zoom and pan operations', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.array(
            fc.oneof(
              fc.record({
                type: fc.constant('zoom' as const),
                value: fc.double({ min: 0.5, max: 5.0, noNaN: true }),
              }),
              fc.record({
                type: fc.constant('pan' as const),
                value: fc.record({
                  x: fc.integer({ min: -100, max: 100 }),
                  y: fc.integer({ min: -100, max: 100 }),
                }),
              })
            ),
            { minLength: 1, maxLength: 10 }
          ),
          async (operations) => {
            // Reset viewport
            useViewportStore.getState().resetViewport();
            
            // Apply operations
            for (const op of operations) {
              if (op.type === 'zoom') {
                useViewportStore.getState().setZoom(op.value);
              } else {
                useViewportStore.getState().panBy(op.value);
              }
            }
            
            // Property: Viewport state should always be valid
            const state = useViewportStore.getState().getViewportState();
            expect(state.zoom).toBeGreaterThanOrEqual(0.1);
            expect(state.zoom).toBeLessThanOrEqual(10.0);
            expect(Number.isFinite(state.pan.x)).toBe(true);
            expect(Number.isFinite(state.pan.y)).toBe(true);
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { useWorldBuilderStore } from '../worldBuilderStore';
import { act } from '@testing-library/react';

// Mock localStorage
const localStorageMock = {
  getItem: jest.fn(),
  setItem: jest.fn(),
  removeItem: jest.fn(),
  clear: jest.fn(),
};
Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
});

describe('worldBuilderStore Integration', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    useWorldBuilderStore.getState().resetWorld();
    // Clear localStorage mock
    localStorageMock.clear();
  });

  afterEach(() => {
    // Clean up after each test
    localStorageMock.clear();
  });

  describe('State Initialization and Persistence', () => {
    it('should initialize with default state', () => {
      const state = useWorldBuilderStore.getState();
      expect(state.worldData).toBeNull();
      expect(state.currentStep).toBe('foundations');
      expect(state.completedSteps.size).toBe(0);
      expect(state.isLoading).toBe(false);
      expect(state.error).toBeNull();
      expect(state.lastSaved).toBeNull();
    });

    it('should persist state to localStorage', () => {
      const { initializeWorld, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({ foundations: { name: 'Persistent World' } });
        updateStep('foundations', { genre: 'fantasy' });
      });

      expect(localStorageMock.setItem).toHaveBeenCalled();
      const [key, value] = localStorageMock.setItem.mock.calls[0];
      expect(key).toBe('world-builder-storage');
      expect(JSON.parse(value)).toHaveProperty('state.worldData.foundations.name', 'Persistent World');
    });

    it('should restore state from localStorage on initialization', () => {
      const persistedState = {
        worldData: {
          id: 'restored-world',
          foundations: { name: 'Restored World', genre: 'fantasy', setting: 'Test', scale: 'medium' },
        },
        currentStep: 'rules',
        completedSteps: ['foundations'],
        lastSaved: new Date().toISOString(),
      };

      localStorageMock.getItem.mockReturnValue(JSON.stringify({ state: persistedState }));

      // Re-initialize store to trigger hydration
      const store = useWorldBuilderStore.getState();
      expect(store.worldData?.foundations.name).toBe('Restored World');
      expect(store.currentStep).toBe('rules');
      expect(store.completedSteps.has('foundations')).toBe(true);
    });
  });

  describe('World Data Management', () => {
    it('should initialize world data with provided values', () => {
      const { initializeWorld } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({
          foundations: {
            name: 'Test World',
            genre: 'fantasy',
            setting: 'A magical world',
            scale: 'large',
          },
        });
      });

      const state = useWorldBuilderStore.getState();
      expect(state.worldData).not.toBeNull();
      expect(state.worldData?.foundations.name).toBe('Test World');
      expect(state.worldData?.foundations.genre).toBe('fantasy');
      expect(state.worldData?.foundations.scale).toBe('large');
      expect(state.worldData?.id).toMatch(/^[a-f0-9-]+$/); // UUID format
    });

    it('should merge provided data with defaults', () => {
      const { initializeWorld } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({
          foundations: { name: 'Partial World' },
        });
      });

      const state = useWorldBuilderStore.getState();
      expect(state.worldData?.foundations.name).toBe('Partial World');
      expect(state.worldData?.foundations.genre).toBe(''); // Default empty
      expect(state.worldData?.foundations.scale).toBe('medium'); // Default value
    });

    it('should update step data and increment version', () => {
      const { initializeWorld, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      const initialState = useWorldBuilderStore.getState();
      const initialVersion = initialState.worldData?.version;

      act(() => {
        updateStep('foundations', { name: 'Updated World' });
      });

      const updatedState = useWorldBuilderStore.getState();
      expect(updatedState.worldData?.foundations.name).toBe('Updated World');
      expect(updatedState.worldData?.version).toBe(initialVersion! + 1);
      expect(updatedState.lastSaved).toBeInstanceOf(Date);
    });

    it('should handle complex nested updates', () => {
      const { initializeWorld, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
        updateStep('culture', {
          societies: [{
            id: 'society1',
            name: 'Test Society',
            values: ['honor', 'courage'],
            customs: ['ritual combat'],
          }],
          conflicts: ['resource wars'],
        });
      });

      const state = useWorldBuilderStore.getState();
      expect(state.worldData?.culture.societies).toHaveLength(1);
      expect(state.worldData?.culture.societies[0].name).toBe('Test Society');
      expect(state.worldData?.culture.conflicts).toEqual(['resource wars']);
    });
  });

  describe('Step Navigation and Validation', () => {
    it('should navigate between steps', () => {
      const { navigateToStep } = useWorldBuilderStore.getState();

      act(() => {
        navigateToStep('rules');
      });

      const state = useWorldBuilderStore.getState();
      expect(state.currentStep).toBe('rules');

      act(() => {
        navigateToStep('culture');
      });

      expect(useWorldBuilderStore.getState().currentStep).toBe('culture');
    });

    it('should reject navigation to invalid steps', () => {
      const { navigateToStep } = useWorldBuilderStore.getState();
      const initialStep = useWorldBuilderStore.getState().currentStep;

      act(() => {
        navigateToStep('invalid_step' as any);
      });

      expect(useWorldBuilderStore.getState().currentStep).toBe(initialStep);
    });

    it('should mark steps as complete', () => {
      const { markStepComplete } = useWorldBuilderStore.getState();

      act(() => {
        markStepComplete('foundations');
      });

      const state = useWorldBuilderStore.getState();
      expect(state.completedSteps.has('foundations')).toBe(true);
      expect(state.completedSteps.size).toBe(1);
    });

    it('should validate foundations step correctly', () => {
      const { initializeWorld, validateStep, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      expect(validateStep('foundations')).toBe(false);

      act(() => {
        updateStep('foundations', {
          name: 'Valid World',
          genre: 'fantasy',
          setting: 'Valid setting description',
        });
      });

      expect(validateStep('foundations')).toBe(true);
    });

    it('should validate rules step based on physics array', () => {
      const { initializeWorld, validateStep, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      expect(validateStep('rules')).toBe(false);

      act(() => {
        updateStep('rules', {
          physics: ['magic follows will', 'gravity is mutable'],
        });
      });

      expect(validateStep('rules')).toBe(true);
    });

    it('should validate culture step based on societies', () => {
      const { initializeWorld, validateStep, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      expect(validateStep('culture')).toBe(false);

      act(() => {
        updateStep('culture', {
          societies: [{
            id: 'society1',
            name: 'Test Society',
            values: [],
            customs: [],
          }],
        });
      });

      expect(validateStep('culture')).toBe(true);
    });

    it('should validate locations step based on locations array', () => {
      const { initializeWorld, validateStep, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      expect(validateStep('locations')).toBe(false);

      act(() => {
        updateStep('locations', [{
          id: 'location1',
          name: 'Test Location',
          type: 'city',
          description: 'A test city',
          coordinates: { x: 100, y: 200 },
        }]);
      });

      expect(validateStep('locations')).toBe(true);
    });

    it('should validate synthesis step based on summary and themes', () => {
      const { initializeWorld, validateStep, updateStep } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      expect(validateStep('synthesis')).toBe(false);

      act(() => {
        updateStep('synthesis', {
          summary: 'World summary',
          themes: ['redemption', 'power'],
          plotHooks: [],
          keyEvents: [],
        });
      });

      expect(validateStep('synthesis')).toBe(true);
    });

    it('should return false for invalid step validation', () => {
      const { validateStep } = useWorldBuilderStore.getState();

      expect(validateStep('invalid_step' as any)).toBe(false);
    });
  });

  describe('Error Handling and Loading States', () => {
    it('should handle save operation with loading states', async () => {
      const { saveWorld } = useWorldBuilderStore.getState();

      // Mock successful save
      const savePromise = act(async () => {
        await saveWorld();
      });

      expect(useWorldBuilderStore.getState().isLoading).toBe(false);
      expect(useWorldBuilderStore.getState().lastSaved).toBeInstanceOf(Date);
    });

    it('should handle save errors', async () => {
      const { saveWorld } = useWorldBuilderStore.getState();

      // Mock save function to throw
      useWorldBuilderStore.setState({
        saveWorld: async () => {
          throw new Error('Save failed');
        },
      });

      await act(async () => {
        await saveWorld();
      });

      expect(useWorldBuilderStore.getState().error).toBe('Failed to save world');
      expect(useWorldBuilderStore.getState().isLoading).toBe(false);
    });

    it('should set and clear errors', () => {
      const { setError } = useWorldBuilderStore.getState();

      act(() => {
        setError('Test error');
      });

      expect(useWorldBuilderStore.getState().error).toBe('Test error');

      act(() => {
        setError(null);
      });

      expect(useWorldBuilderStore.getState().error).toBeNull();
    });
  });

  describe('World Reset and Cleanup', () => {
    it('should reset world to initial state', () => {
      const { initializeWorld, updateStep, markStepComplete, setError, resetWorld } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({ foundations: { name: 'Test World' } });
        updateStep('foundations', { genre: 'fantasy' });
        markStepComplete('foundations');
        setError('Test error');
      });

      // Verify state is modified
      expect(useWorldBuilderStore.getState().worldData).not.toBeNull();
      expect(useWorldBuilderStore.getState().completedSteps.size).toBe(1);
      expect(useWorldBuilderStore.getState().error).toBe('Test error');

      act(() => {
        resetWorld();
      });

      // Verify reset
      const resetState = useWorldBuilderStore.getState();
      expect(resetState.worldData).toBeNull();
      expect(resetState.currentStep).toBe('foundations');
      expect(resetState.completedSteps.size).toBe(0);
      expect(resetState.error).toBeNull();
      expect(resetState.lastSaved).toBeNull();
    });
  });

  describe('Selectors and Computed Values', () => {
    it('should provide correct step completion status', () => {
      const { markStepComplete } = useWorldBuilderStore.getState();
      const selectors = useWorldBuilderStore.getState();

      expect(selectors.completedSteps.has('foundations')).toBe(false);

      act(() => {
        markStepComplete('foundations');
      });

      expect(useWorldBuilderStore.getState().completedSteps.has('foundations')).toBe(true);
    });

    it('should determine navigation permissions correctly', () => {
      const { initializeWorld, markStepComplete } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      // Can navigate to current step
      expect(useWorldBuilderStore.getState().currentStep).toBe('foundations');

      act(() => {
        markStepComplete('foundations');
      });

      // Now can navigate to completed steps
      expect(useWorldBuilderStore.getState().completedSteps.has('foundations')).toBe(true);
    });
  });

  describe('Concurrent Operations', () => {
    it('should handle rapid state updates', () => {
      const { updateStep } = useWorldBuilderStore.getState();

      act(() => {
        // Simulate rapid updates (like typing)
        for (let i = 0; i < 10; i++) {
          updateStep('foundations', { name: `Update ${i}` });
        }
      });

      // Should have the last update
      expect(useWorldBuilderStore.getState().worldData?.foundations.name).toBe('Update 9');
      expect(useWorldBuilderStore.getState().worldData?.version).toBe(10); // Initial + 9 updates
    });

    it('should maintain state consistency during complex operations', () => {
      const { initializeWorld, updateStep, navigateToStep, markStepComplete } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
        updateStep('foundations', { name: 'Complex World', genre: 'fantasy' });
        navigateToStep('rules');
        markStepComplete('foundations');
        updateStep('rules', { physics: ['magic'] });
      });

      const state = useWorldBuilderStore.getState();
      expect(state.worldData?.foundations.name).toBe('Complex World');
      expect(state.worldData?.foundations.genre).toBe('fantasy');
      expect(state.worldData?.rules.physics).toEqual(['magic']);
      expect(state.currentStep).toBe('rules');
      expect(state.completedSteps.has('foundations')).toBe(true);
    });
  });

  describe('Memory and Performance', () => {
    it('should not create unnecessary re-renders', () => {
      const { initializeWorld } = useWorldBuilderStore.getState();

      act(() => {
        initializeWorld({});
      });

      const state1 = useWorldBuilderStore.getState();
      const state2 = useWorldBuilderStore.getState();

      // Same reference should be returned for same state
      expect(state1).toBe(state2);
    });

    it('should handle large world data efficiently', () => {
      const { initializeWorld, updateStep } = useWorldBuilderStore.getState();

      const largeCultureData = {
        societies: Array.from({ length: 100 }, (_, i) => ({
          id: `society${i}`,
          name: `Society ${i}`,
          values: Array.from({ length: 10 }, (_, j) => `Value ${j}`),
          customs: Array.from({ length: 5 }, (_, j) => `Custom ${j}`),
        })),
        conflicts: Array.from({ length: 50 }, (_, i) => `Conflict ${i}`),
        alliances: Array.from({ length: 25 }, (_, i) => `Alliance ${i}`),
      };

      act(() => {
        initializeWorld({});
        updateStep('culture', largeCultureData);
      });

      const state = useWorldBuilderStore.getState();
      expect(state.worldData?.culture.societies).toHaveLength(100);
      expect(state.worldData?.culture.conflicts).toHaveLength(50);
      // Should handle large data without issues
    });
  });

  describe('Edge Cases and Error Conditions', () => {
    it('should handle invalid step updates gracefully', () => {
      const { updateStep } = useWorldBuilderStore.getState();

      act(() => {
        updateStep('invalid_step' as any, { data: 'test' });
      });

      // Should not crash, just ignore
      expect(useWorldBuilderStore.getState().worldData).toBeNull();
    });

    it('should handle null/undefined data in validation', () => {
      const { validateStep } = useWorldBuilderStore.getState();

      // No world data
      expect(validateStep('foundations')).toBe(false);
      expect(validateStep('rules')).toBe(false);
      expect(validateStep('culture')).toBe(false);
      expect(validateStep('locations')).toBe(false);
      expect(validateStep('synthesis')).toBe(false);
    });

    it('should handle malformed persisted data', () => {
      localStorageMock.getItem.mockReturnValue('invalid json');

      // Store should handle corrupted localStorage gracefully
      expect(() => useWorldBuilderStore.getState()).not.toThrow();
    });

    it('should handle localStorage errors', () => {
      localStorageMock.setItem.mockImplementation(() => {
        throw new Error('Storage quota exceeded');
      });

      const { initializeWorld } = useWorldBuilderStore.getState();

      // Should not crash even if localStorage fails
      expect(() => {
        act(() => {
          initializeWorld({});
        });
      }).not.toThrow();
    });
  });
});

