  RemixPreview,
  BeatMarker,
  SectionMarker,
  RemixCut
} from '../services/musicRemixService';

export interface AudioRemixState {
  // Track state
  currentTrackUrl: string | null;
  currentTrackId: string | null;
  trackName: string;
  
  // Structure analysis
  musicStructure: MusicStructure | null;
  isAnalyzing: boolean;
  analysisError: string | null;
  
  // Remix state
  remixResult: RemixResult | null;
  remixPreview: RemixPreview | null;
  isRemixing: boolean;
  remixError: string | null;
  
  // Target duration
  targetDuration: number;
  
  // Style selection
  selectedStyle: RemixStyle;
  
  // Cuts preview
  suggestedCuts: Array<{
    section: string;
    originalStart: number;
    originalEnd: number;
    suggestedStart: number;
    suggestedEnd: number;
    removed: number;
  }>;
  selectedCuts: string[]; // IDs of selected cuts
  
  // Effects/modifications
  fadeInDuration: number;
  fadeOutDuration: number;
  crossfadeDuration: number;
  preserveIntro: boolean;
  preserveOutro: boolean;
  
  // Export state
  isExporting: boolean;
  exportError: string | null;
  exportedUrl: string | null;
  
  // Actions
  loadTrack: (audioId: string, audioUrl: string) => Promise<void>;
  analyzeStructure: () => Promise<void>;
  setTargetDuration: (duration: number) => void;
  setRemixStyle: (style: RemixStyle) => void;
  calculateSuggestedCuts: () => void;
  toggleCut: (cutId: string) => void;
  applyEffect: (effect: string, value: number | boolean) => void;
  previewRemix: () => Promise<void>;
  executeRemix: () => Promise<void>;
  export: (outputFormat?: string) => Promise<string>;
  reset: () => void;
  clearResult: () => void;
}

export const useAudioRemixStore = create<AudioRemixState>((set, get) => ({
  currentTrackUrl: null,
  currentTrackId: null,
  trackName: '',
  musicStructure: null,
  isAnalyzing: false,
  analysisError: null,
  remixResult: null,
  remixPreview: null,
  isRemixing: false,
  remixError: null,
  targetDuration: 60,
  selectedStyle: 'smooth',
  suggestedCuts: [],
  selectedCuts: [],
  fadeInDuration: 0.5,
  fadeOutDuration: 1.0,
  crossfadeDuration: 2.0,
  preserveIntro: true,
  preserveOutro: true,
  isExporting: false,
  exportError: null,
  exportedUrl: null,

  loadTrack: async (audioId: string, audioUrl: string) => {
    set({
      currentTrackId: audioId,
      currentTrackUrl: audioUrl,
      trackName: audioUrl.split('/').pop() || audioUrl,
      remixResult: null,
      remixPreview: null,
      suggestedCuts: [],
      selectedCuts: [],
      analysisError: null
    });

    // Auto-analyze structure
    await get().analyzeStructure();
  },

  analyzeStructure: async () => {
    const { currentTrackUrl } = get();
    if (!currentTrackUrl) return;

    set({ isAnalyzing: true, analysisError: null });

    try {
      const structure = await musicRemixService.analyzeStructure(currentTrackUrl);
      set({ 
        musicStructure: structure, 
        isAnalyzing: false,
        targetDuration: Math.round(structure.duration * 0.8) // Default to 80% of original
      });
      
      // Calculate initial suggested cuts
      get().calculateSuggestedCuts();
    } catch (error) {
      set({ 
        analysisError: error instanceof Error ? error.message : 'Analyse échouée',
        isAnalyzing: false 
      });
    }
  },

  setTargetDuration: (duration: number) => {
    set({ targetDuration: duration });
    get().calculateSuggestedCuts();
  },

  setRemixStyle: (style: RemixStyle) => {
    set({ selectedStyle: style });
  },

  calculateSuggestedCuts: () => {
    const { musicStructure, targetDuration } = get();
    if (!musicStructure) return;

    const cuts = musicRemixService.calculateSuggestedCuts(musicStructure, targetDuration);
    set({ suggestedCuts: cuts });
  },

  toggleCut: (cutId: string) => {
    const { selectedCuts } = get();
    const newSelected = selectedCuts.includes(cutId)
      ? selectedCuts.filter(id => id !== cutId)
      : [...selectedCuts, cutId];
    set({ selectedCuts: newSelected });
  },

  applyEffect: (effect: string, value: number | boolean) => {
    const state = get();
    switch (effect) {
      case 'fadeIn':
        set({ fadeInDuration: value as number });
        break;
      case 'fadeOut':
        set({ fadeOutDuration: value as number });
        break;
      case 'crossfade':
        set({ crossfadeDuration: value as number });
        break;
      case 'preserveIntro':
        set({ preserveIntro: value as boolean });
        break;
      case 'preserveOutro':
        set({ preserveOutro: value as boolean });
        break;
    }
  },

  previewRemix: async () => {
    const { 
      currentTrackId, 
      currentTrackUrl, 
      targetDuration, 
      selectedStyle,
      fadeInDuration,
      fadeOutDuration,
      crossfadeDuration,
      preserveIntro,
      preserveOutro
    } = get();

    if (!currentTrackId || !currentTrackUrl) return;

    const request: RemixRequest = {
      audioId: currentTrackId,
      audioUrl: currentTrackUrl,
      targetDuration,
      style: selectedStyle,
      fadeInDuration,
      fadeOutDuration,
      crossfadeDuration,
      preserveIntro,
      preserveOutro
    };

    try {
      const preview = await musicRemixService.previewRemix(request);
      set({ remixPreview: preview });
    } catch (error) {
      console.error('Preview failed:', error);
    }
  },

  executeRemix: async () => {
    const { 
      currentTrackId, 
      currentTrackUrl, 
      targetDuration, 
      selectedStyle,
      fadeInDuration,
      fadeOutDuration,
      crossfadeDuration,
      preserveIntro,
      preserveOutro
    } = get();

    if (!currentTrackId || !currentTrackUrl) return;

    set({ isRemixing: true, remixError: null });

    const request: RemixRequest = {
      audioId: currentTrackId,
      audioUrl: currentTrackUrl,
      targetDuration,
      style: selectedStyle,
      fadeInDuration,
      fadeOutDuration,
      crossfadeDuration,
      preserveIntro,
      preserveOutro
    };

    try {
      const result = await musicRemixService.remix(request);
      set({ 
        remixResult: result, 
        isRemixing: false,
        exportedUrl: result.outputUrl
      });
    } catch (error) {
      set({ 
        remixError: error instanceof Error ? error.message : 'Remix échoué',
        isRemixing: false 
      });
    }
  },

  export: async (outputFormat?: string) => {
    const { remixResult } = get();
    if (!remixResult) {
      throw new Error('Aucun remix à exporter');
    }

    set({ isExporting: true, exportError: null });

    try {
      // For now, just return the already-generated output URL
      // In a full implementation, this would handle format conversion
      set({ 
        isExporting: false, 
        exportedUrl: remixResult.outputUrl 
      });
      return remixResult.outputUrl;
    } catch (error) {
      set({ 
        exportError: error instanceof Error ? error.message : 'Export échoué',
        isExporting: false 
      });
      throw error;
    }
  },

  reset: () => {
    set({
      currentTrackUrl: null,
      currentTrackId: null,
      trackName: '',
      musicStructure: null,
      isAnalyzing: false,
      analysisError: null,
      remixResult: null,
      remixPreview: null,
      isRemixing: false,
      remixError: null,
      targetDuration: 60,
      selectedStyle: 'smooth',
      suggestedCuts: [],
      selectedCuts: [],
      fadeInDuration: 0.5,
      fadeOutDuration: 1.0,
      crossfadeDuration: 2.0,
      preserveIntro: true,
      preserveOutro: true,
      exportedUrl: null
    });
  },

  clearResult: () => {
    set({ 
      remixResult: null, 
      remixPreview: null,
      exportedUrl: null 
    });
  }
}));

// Export helper types for consumers
export type { 
  MusicStructure, 
  RemixRequest, 
  RemixResult, 
  RemixPreview,
  BeatMarker,
  SectionMarker,
  RemixCut,
  RemixStyle 
};

/**
 * Camera Angle Store - Zustand store for camera angle editor feature
 * 
 * This store manages:
 * - Current generation job state
 * - Available presets
 * - Selected angles for generation
 * - Source image
 * - Generation options
 * - Error handling
 */

import { create } from 'zustand';
import { cameraAngleService } from '@/services/cameraAngleService';
import type {
  CameraAnglePreset,
  CameraAngleJobStatus,
  CameraAnglePresetMetadata,
  CameraAngleRequest,
  CameraAngleJobResponse,
  CameraAngleResult,
  CameraAngleQuality,
  CameraAngleResultResponse,
  CameraAngleApiError,
} from '@/types/cameraAngle';

// ============================================================================
// Store State Interface
// ============================================================================

interface CameraAngleStoreState {
  // Current job state
  currentJob: {
    jobId: string | null;
    status: CameraAngleJobStatus;
    progress: number;
    currentStep: string | null;
    completedAngles: CameraAnglePreset[];
    remainingAngles: CameraAnglePreset[];
    error: string | null;
    results: CameraAngleResult[];
    isLoading: boolean;
  };

  // Available presets
  presets: CameraAnglePresetMetadata[];
  presetsLoaded: boolean;

  // Selected angles for generation
  selectedAngles: CameraAnglePreset[];

  // Source image (base64)
  sourceImage: string | null;

  // Generation options
  options: {
    preserveStyle: boolean;
    quality: CameraAngleQuality;
    seed: number | null;
    customPrompt: string | null;
  };

  // Error state
  error: string | null;

  // Polling cleanup function
  _pollingCleanup: (() => void) | null;
}

// ============================================================================
// Store Actions Interface
// ============================================================================

interface CameraAngleStoreActions {
  // Job actions
  startGeneration: () => Promise<string>;
  fetchJobStatus: (jobId: string) => Promise<void>;
  fetchJobResult: (jobId: string) => Promise<CameraAngleResultResponse>;
  cancelJob: () => Promise<void>;
  resetJob: () => void;

  // Preset actions
  fetchPresets: () => Promise<void>;

  // Selection actions
  setSelectedAngles: (angles: CameraAnglePreset[]) => void;
  toggleAngle: (angle: CameraAnglePreset) => void;
  selectAllAngles: () => void;
  clearAngleSelection: () => void;

  // Source image actions
  setSourceImage: (imageBase64: string | null) => void;

  // Options actions
  setOptions: (options: Partial<CameraAngleStoreState['options']>) => void;
  setPreserveStyle: (preserveStyle: boolean) => void;
  setQuality: (quality: CameraAngleQuality) => void;
  setSeed: (seed: number | null) => void;
  setCustomPrompt: (prompt: string | null) => void;

  // Error actions
  setError: (error: string | null) => void;
  clearError: () => void;

  // Internal actions
  _setPollingCleanup: (cleanup: (() => void) | null) => void;
  _updateJobStatus: (status: CameraAngleJobResponse) => void;
  _setJobLoading: (isLoading: boolean) => void;
  _setJobResults: (results: CameraAngleResult[]) => void;
}

// ============================================================================
// Initial State
// ============================================================================

const initialJobState: CameraAngleStoreState['currentJob'] = {
  jobId: null,
  status: 'pending',
  progress: 0,
  currentStep: null,
  completedAngles: [],
  remainingAngles: [],
  error: null,
  results: [],
  isLoading: false,
};

const initialOptions: CameraAngleStoreState['options'] = {
  preserveStyle: true,
  quality: 'standard',
  seed: null,
  customPrompt: null,
};

// ============================================================================
// Store Creation
// ============================================================================

export const useCameraAngleStore = create<
  CameraAngleStoreState & CameraAngleStoreActions
>((set, get) => ({
  // Initial state
  currentJob: { ...initialJobState },
  presets: [],
  presetsLoaded: false,
  selectedAngles: [],
  sourceImage: null,
  options: { ...initialOptions },
  error: null,
  _pollingCleanup: null,

  // ==========================================================================
  // Job Actions
  // ==========================================================================

  startGeneration: async () => {
    const state = get();

    // Validate state
    if (!state.sourceImage) {
      throw new Error('No source image provided');
    }

    if (state.selectedAngles.length === 0) {
      throw new Error('No angles selected');
    }

    // Set loading state
    set({
      currentJob: {
        ...initialJobState,
        isLoading: true,
        status: 'pending',
        remainingAngles: state.selectedAngles,
      },
      error: null,
    });

    try {
      // Build request
      const request: CameraAngleRequest = {
        imageBase64: state.sourceImage,
        angleIds: state.selectedAngles,
        preserveStyle: state.options.preserveStyle,
        quality: state.options.quality,
        seed: state.options.seed,
        customPrompt: state.options.customPrompt,
      };

      // Start generation
      const response = await cameraAngleService.generate(request);

      // Update job state
      set({
        currentJob: {
          ...get().currentJob,
          jobId: response.jobId,
          status: response.status,
          progress: response.progress,
          currentStep: response.currentStep,
          completedAngles: response.completedAngles as CameraAnglePreset[],
          remainingAngles: response.remainingAngles as CameraAnglePreset[],
          isLoading: false,
        },
      });

      // Start polling for status updates
      const cleanup = cameraAngleService.pollJobStatus(
        response.jobId,
        // onProgress
        (status) => {
          get()._updateJobStatus(status);
        },
        // onComplete
        (result) => {
          set({
            currentJob: {
              ...get().currentJob,
              status: 'completed',
              progress: 100,
              results: result.results,
              isLoading: false,
            },
          });
        },
        // onError
        (error) => {
          set({
            currentJob: {
              ...get().currentJob,
              status: 'failed',
              error: error.message,
              isLoading: false,
            },
            error: error.message,
          });
        }
      );

      get()._setPollingCleanup(cleanup);

      return response.jobId;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to start generation';

      set({
        currentJob: {
          ...get().currentJob,
          status: 'failed',
          error: errorMessage,
          isLoading: false,
        },
        error: errorMessage,
      });

      throw error;
    }
  },

  fetchJobStatus: async (jobId: string) => {
    try {
      const status = await cameraAngleService.getStatus(jobId);
      get()._updateJobStatus(status);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to fetch job status';
      set({
        error: errorMessage,
      });
      throw error;
    }
  },

  fetchJobResult: async (jobId: string) => {
    try {
      const result = await cameraAngleService.getResult(jobId);
      get()._setJobResults(result.results);
      return result;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to fetch job result';
      set({
        error: errorMessage,
      });
      throw error;
    }
  },

  cancelJob: async () => {
    const state = get();
    const jobId = state.currentJob.jobId;

    if (!jobId) {
      return;
    }

    // Stop polling
    if (state._pollingCleanup) {
      state._pollingCleanup();
      get()._setPollingCleanup(null);
    }

    try {
      await cameraAngleService.cancelJob(jobId);

      set({
        currentJob: {
          ...get().currentJob,
          status: 'cancelled',
          isLoading: false,
        },
      });
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to cancel job';
      set({
        error: errorMessage,
      });
      throw error;
    }
  },

  resetJob: () => {
    // Stop polling if active
    const state = get();
    if (state._pollingCleanup) {
      state._pollingCleanup();
    }

    set({
      currentJob: { ...initialJobState },
      error: null,
      _pollingCleanup: null,
    });
  },

  // ==========================================================================
  // Preset Actions
  // ==========================================================================

  fetchPresets: async () => {
    // Skip if already loaded
    if (get().presetsLoaded) {
      return;
    }

    try {
      const response = await cameraAngleService.getPresets();

      set({
        presets: response.presets,
        presetsLoaded: true,
      });
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to fetch presets';
      set({
        error: errorMessage,
      });
      throw error;
    }
  },

  // ==========================================================================
  // Selection Actions
  // ==========================================================================

  setSelectedAngles: (angles: CameraAnglePreset[]) => {
    set({ selectedAngles: angles });
  },

  toggleAngle: (angle: CameraAnglePreset) => {
    const state = get();
    const isSelected = state.selectedAngles.includes(angle);

    if (isSelected) {
      set({
        selectedAngles: state.selectedAngles.filter((a) => a !== angle),
      });
    } else {
      set({
        selectedAngles: [...state.selectedAngles, angle],
      });
    }
  },

  selectAllAngles: () => {
    const state = get();
    set({
      selectedAngles: state.presets.map((p) => p.id),
    });
  },

  clearAngleSelection: () => {
    set({ selectedAngles: [] });
  },

  // ==========================================================================
  // Source Image Actions
  // ==========================================================================

  setSourceImage: (imageBase64: string | null) => {
    set({ sourceImage: imageBase64 });
  },

  // ==========================================================================
  // Options Actions
  // ==========================================================================

  setOptions: (options: Partial<CameraAngleStoreState['options']>) => {
    set({
      options: {
        ...get().options,
        ...options,
      },
    });
  },

  setPreserveStyle: (preserveStyle: boolean) => {
    set({
      options: {
        ...get().options,
        preserveStyle,
      },
    });
  },

  setQuality: (quality: CameraAngleQuality) => {
    set({
      options: {
        ...get().options,
        quality,
      },
    });
  },

  setSeed: (seed: number | null) => {
    set({
      options: {
        ...get().options,
        seed,
      },
    });
  },

  setCustomPrompt: (prompt: string | null) => {
    set({
      options: {
        ...get().options,
        customPrompt: prompt,
      },
    });
  },

  // ==========================================================================
  // Error Actions
  // ==========================================================================

  setError: (error: string | null) => {
    set({ error });
  },

  clearError: () => {
    set({ error: null });
  },

  // ==========================================================================
  // Internal Actions
  // ==========================================================================

  _setPollingCleanup: (cleanup: (() => void) | null) => {
    set({ _pollingCleanup: cleanup });
  },

  _updateJobStatus: (status: CameraAngleJobResponse) => {
    set({
      currentJob: {
        ...get().currentJob,
        jobId: status.jobId,
        status: status.status,
        progress: status.progress,
        currentStep: status.currentStep,
        completedAngles: status.completedAngles as CameraAnglePreset[],
        remainingAngles: status.remainingAngles as CameraAnglePreset[],
        error: status.error,
      },
    });
  },

  _setJobLoading: (isLoading: boolean) => {
    set({
      currentJob: {
        ...get().currentJob,
        isLoading,
      },
    });
  },

  _setJobResults: (results: CameraAngleResult[]) => {
    set({
      currentJob: {
        ...get().currentJob,
        results,
      },
    });
  },
}));

// ============================================================================
// Selector Hooks
// ============================================================================

/**
 * Select current job state
 */
export const useCurrentJob = () =>
  useCameraAngleStore((state) => state.currentJob);

/**
 * Select available presets
 */
export const usePresets = () =>
  useCameraAngleStore((state) => state.presets);

/**
 * Select selected angles
 */
export const useSelectedAngles = () =>
  useCameraAngleStore((state) => state.selectedAngles);

/**
 * Select source image
 */
export const useSourceImage = () =>
  useCameraAngleStore((state) => state.sourceImage);

/**
 * Select generation options
 */
export const useGenerationOptions = () =>
  useCameraAngleStore((state) => state.options);

/**
 * Select error state
 */
export const useCameraAngleError = () =>
  useCameraAngleStore((state) => state.error);

/**
 * Check if generation is in progress
 */
export const useIsGenerating = () =>
  useCameraAngleStore(
    (state) =>
      state.currentJob.isLoading ||
      state.currentJob.status === 'pending' ||
      state.currentJob.status === 'processing'
  );

/**
 * Check if job has completed with results
 */
export const useHasResults = () =>
  useCameraAngleStore(
    (state) =>
      state.currentJob.status === 'completed' &&
      state.currentJob.results.length > 0
  );

/**
 * Caption Style Store
 * MI2: Caption Styles - Modern, Classic, Dynamic
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import {
  CaptionStyle,
  CaptionStylePreset,
  CaptionTrack,
  CaptionLayer,
  CaptionStyleLibrary,
} from '../types/caption-style';

interface CaptionStyleStore {
  // Built-in styles
  builtInStyles: CaptionStyle[];

  // User presets
  userPresets: CaptionStylePreset[];
  recentStyles: string[];
  favoriteStyleIds: string[];

  // Active caption track
  activeTrack: CaptionTrack | null;
  tracks: CaptionTrack[];

  // Selected layer
  selectedLayerId: string | null;
  selectedStyleId: string | null;

  // UI state
  isPanelOpen: boolean;
  isStyleEditorOpen: boolean;
  previewMode: boolean;

  // Actions
  // Style management
  registerBuiltInStyle: (style: CaptionStyle) => void;
  createPreset: (preset: CaptionStylePreset) => void;
  updatePreset: (id: string, updates: Partial<CaptionStylePreset>) => void;
  deletePreset: (id: string) => void;
  addToFavorites: (id: string) => void;
  removeFromFavorites: (id: string) => void;
  addToRecent: (id: string) => void;

  // Track management
  createTrack: (track: CaptionTrack) => void;
  updateTrack: (id: string, updates: Partial<CaptionTrack>) => void;
  deleteTrack: (id: string) => void;
  selectTrack: (id: string | null) => void;

  // Layer management
  createLayer: (layer: CaptionLayer) => void;
  updateLayer: (id: string, updates: Partial<CaptionLayer>) => void;
  deleteLayer: (id: string) => void;
  selectLayer: (id: string | null) => void;

  // Style application
  applyStyleToLayer: (styleId: string, layerId: string) => void;
  applyStyleToTrack: (styleId: string, trackId: string) => void;
  selectStyle: (id: string | null) => void;

  // UI
  togglePanel: () => void;
  toggleStyleEditor: () => void;
  setPreviewMode: (enabled: boolean) => void;

  // Bulk operations
  importStyles: (styles: CaptionStyle[]) => void;
  exportStyles: (styleIds: string[]) => (CaptionStyle | CaptionStylePreset)[];
  resetToDefaults: () => void;
}

export const useCaptionStyleStore = create<CaptionStyleStore>()(
  subscribeWithSelector((set, get) => ({
    // Initial state
    builtInStyles: [],
    userPresets: [],
    recentStyles: [],
    favoriteStyleIds: [],
    activeTrack: null,
    tracks: [],
    selectedLayerId: null,
    selectedStyleId: null,
    isPanelOpen: false,
    isStyleEditorOpen: false,
    previewMode: false,

    // Style management
    registerBuiltInStyle: (style) => set((state) => ({
      builtInStyles: state.builtInStyles.some((s) => s.id === style.id)
        ? state.builtInStyles
        : [...state.builtInStyles, style],
    })),

    createPreset: (preset) => set((state) => ({
      userPresets: [...state.userPresets, preset],
    })),

    updatePreset: (id, updates) => set((state) => ({
      userPresets: state.userPresets.map((p) =>
        p.id === id ? { ...p, ...updates, updatedAt: Date.now() } : p
      ),
    })),

    deletePreset: (id) => set((state) => ({
      userPresets: state.userPresets.filter((p) => p.id !== id),
      favoriteStyleIds: state.favoriteStyleIds.filter((fId) => fId !== id),
    })),

    addToFavorites: (id) => set((state) => ({
      favoriteStyleIds: state.favoriteStyleIds.includes(id)
        ? state.favoriteStyleIds
        : [...state.favoriteStyleIds, id],
    })),

    removeFromFavorites: (id) => set((state) => ({
      favoriteStyleIds: state.favoriteStyleIds.filter((fId) => fId !== id),
    })),

    addToRecent: (id) => set((state) => {
      const recent = [id, ...state.recentStyles.filter((rId) => rId !== id)].slice(0, 10);
      return { recentStyles: recent };
    }),

    // Track management
    createTrack: (track) => set((state) => ({
      tracks: [...state.tracks, track],
      activeTrack: state.activeTrack || track,
    })),

    updateTrack: (id, updates) => set((state) => ({
      tracks: state.tracks.map((t) =>
        t.id === id ? { ...t, ...updates } : t
      ),
      activeTrack: state.activeTrack?.id === id
        ? { ...state.activeTrack, ...updates }
        : state.activeTrack,
    })),

    deleteTrack: (id) => set((state) => ({
      tracks: state.tracks.filter((t) => t.id !== id),
      activeTrack: state.activeTrack?.id === id
        ? (state.tracks[0] || null)
        : state.activeTrack,
    })),

    selectTrack: (id) => {
      const track = id ? get().tracks.find((t) => t.id === id) : null;
      set({ activeTrack: track });
    },

    // Layer management
    createLayer: (layer) => set((state) => {
      const tracks = state.tracks.map((t) =>
        t.id === layer.trackId
          ? { ...t, layers: [...t.layers, layer] }
          : t
      );
      return {
        tracks,
        activeTrack: state.activeTrack?.id === layer.trackId
          ? { ...state.activeTrack, layers: [...state.activeTrack.layers, layer] }
          : state.activeTrack,
      };
    }),

    updateLayer: (id, updates) => set((state) => {
      const tracks = state.tracks.map((t) => ({
        ...t,
        layers: t.layers.map((l) =>
          l.id === id ? { ...l, ...updates } : l
        ),
      }));
      return {
        tracks,
        activeTrack: state.activeTrack
          ? {
            ...state.activeTrack,
            layers: state.activeTrack.layers.map((l) =>
              l.id === id ? { ...l, ...updates } : l
            ),
          }
          : state.activeTrack,
      };
    }),

    deleteLayer: (id) => set((state) => {
      const tracks = state.tracks.map((t) => ({
        ...t,
        layers: t.layers.filter((l) => l.id !== id),
      }));
      return {
        tracks,
        activeTrack: state.activeTrack
          ? {
            ...state.activeTrack,
            layers: state.activeTrack.layers.filter((l) => l.id !== id),
          }
          : state.activeTrack,
        selectedLayerId: state.selectedLayerId === id ? null : state.selectedLayerId,
      };
    }),

    selectLayer: (id) => set({ selectedLayerId: id }),

    // Style application
    applyStyleToLayer: (styleId, layerId) => {
      const { builtInStyles, userPresets, updateLayer, addToRecent } = get();
      const style = builtInStyles.find((s) => s.id === styleId) ||
        userPresets.find((p) => p.id === styleId);

      if (style) {
        updateLayer(layerId, {
          styleId,
          customStyle: (style && 'customizations' in style)
            ? (style as CaptionStylePreset).customizations
            : undefined,
        });
        addToRecent(styleId);
      }
    },

    applyStyleToTrack: (styleId, trackId) => {
      const { builtInStyles, userPresets, updateTrack, addToRecent } = get();
      const style = builtInStyles.find((s) => s.id === styleId) ||
        userPresets.find((p) => p.id === styleId);

      if (style) {
        updateTrack(trackId, {
          styleId,
        });
        addToRecent(styleId);
      }
    },

    selectStyle: (id) => set({ selectedStyleId: id }),

    // UI
    togglePanel: () => set((state) => ({ isPanelOpen: !state.isPanelOpen })),

    toggleStyleEditor: () => set((state) => ({ isStyleEditorOpen: !state.isStyleEditorOpen })),

    setPreviewMode: (enabled) => set({ previewMode: enabled }),

    // Bulk operations
    importStyles: (styles) => set((state) => ({
      builtInStyles: [...state.builtInStyles, ...styles],
    })),

    exportStyles: (styleIds) => {
      const { builtInStyles, userPresets } = get();
      return [...builtInStyles, ...userPresets].filter((s) =>
        styleIds.includes(s.id)
      );
    },

    resetToDefaults: () => set({
      userPresets: [],
      recentStyles: [],
      favoriteStyleIds: [],
      tracks: [],
      activeTrack: null,
    }),
  }))
);

/**
 * Color Correction Store
 * MI1: Color Correction Presets - Vintage, Noir, Vibrant, Cinematic
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import {
  ColorCorrectionPreset,
  ColorCorrectionLayer,
  ColorGradingState,
  ColorCorrectionSettings,
  ColorCorrectionPresetLibrary,
} from '../types/color-correction';

interface ColorCorrectionStore {
  // Presets
  presets: ColorCorrectionPreset[];
  customPresets: ColorCorrectionPreset[];
  recentlyUsed: string[];
  favorites: string[];
  
  // Active correction
  activeLayer: ColorCorrectionLayer | null;
  layers: ColorCorrectionLayer[];
  globalAdjustment: ColorCorrectionLayer | null;
  
  // State
  state: ColorGradingState;
  
  // Settings
  settings: ColorCorrectionSettings;
  
  // UI
  isPanelOpen: boolean;
  selectedLayerId: string | null;
  selectedPresetId: string | null;
  compareMode: boolean;
  beforeAfterView: boolean;
  
  // Actions
  // Preset management
  loadPreset: (preset: ColorCorrectionPreset) => void;
  saveCustomPreset: (preset: ColorCorrectionPreset) => void;
  deleteCustomPreset: (id: string) => void;
  addToFavorites: (id: string) => void;
  removeFromFavorites: (id: string) => void;
  addToRecent: (id: string) => void;
  
  // Layer management
  addLayer: (layer: ColorCorrectionLayer) => void;
  removeLayer: (id: string) => void;
  updateLayer: (id: string, updates: Partial<ColorCorrectionLayer>) => void;
  reorderLayers: (fromIndex: number, toIndex: number) => void;
  selectLayer: (id: string | null) => void;
  
  // Active preset
  applyPreset: (presetId: string) => void;
  applyPresetToLayer: (presetId: string, layerId: string) => void;
  selectPreset: (id: string | null) => void;
  
  // Global adjustment
  updateGlobalAdjustment: (adjustments: Partial<ColorCorrectionLayer['adjustments']>) => void;
  
  // State management
  toggleEnabled: () => void;
  setCompareMode: (enabled: boolean) => void;
  setBeforeAfterView: (enabled: boolean) => void;
  
  // Settings
  updateSettings: (settings: Partial<ColorCorrectionSettings>) => void;
  
  // UI
  togglePanel: () => void;
  
  // Reset
  resetAll: () => void;
  resetLayer: (id: string) => void;
}

const defaultSettings: ColorCorrectionSettings = {
  enableHDR: false,
  bitDepth: 8,
  colorSpace: 'Rec.709',
  gamma: 2.4,
  gamutMapping: 'perceptual',
};

export const useColorCorrectionStore = create<ColorCorrectionStore>()(
  subscribeWithSelector((set, get) => ({
    // Initial state
    presets: [],
    customPresets: [],
    recentlyUsed: [],
    favorites: [],
    activeLayer: null,
    layers: [],
    globalAdjustment: null,
    state: {
      activePresets: [],
      globalAdjustment: {
        exposure: 0,
        contrast: 0,
        highlights: 0,
        shadows: 0,
        whites: 0,
        blacks: 0,
        temperature: 0,
        tint: 0,
        saturation: 0,
        vibrance: 0,
        clarity: 0,
        fade: 0,
        grain: 0,
        vignette: {
          intensity: 0,
          midpoint: 50,
          roundness: 100,
          feather: 50,
          color: '#000000',
        },
        colorBalance: {
          shadows: [0, 0, 0],
          midtones: [0, 0, 0],
          highlights: [0, 0, 0],
        },
        hsl: [],
      },
      beforeCorrection: false,
      afterCorrection: true,
      isEnabled: true,
    },
    settings: { ...defaultSettings },
    isPanelOpen: false,
    selectedLayerId: null,
    selectedPresetId: null,
    compareMode: false,
    beforeAfterView: false,
    
    // Preset management
    loadPreset: (preset) => set((state) => ({
      presets: state.presets.some((p) => p.id === preset.id)
        ? state.presets
        : [...state.presets, preset],
    })),
    
    saveCustomPreset: (preset) => set((state) => ({
      customPresets: [...state.customPresets, preset],
    })),
    
    deleteCustomPreset: (id) => set((state) => ({
      customPresets: state.customPresets.filter((p) => p.id !== id),
      favorites: state.favorites.filter((fId) => fId !== id),
    })),
    
    addToFavorites: (id) => set((state) => ({
      favorites: state.favorites.includes(id) 
        ? state.favorites 
        : [...state.favorites, id],
    })),
    
    removeFromFavorites: (id) => set((state) => ({
      favorites: state.favorites.filter((fId) => fId !== id),
    })),
    
    addToRecent: (id) => set((state) => {
      const recent = [id, ...state.recentlyUsed.filter((rId) => rId !== id)].slice(0, 10);
      return { recentlyUsed: recent };
    }),
    
    // Layer management
    addLayer: (layer) => set((state) => ({
      layers: [...state.layers, layer],
    })),
    
    removeLayer: (id) => set((state) => ({
      layers: state.layers.filter((l) => l.id !== id),
      selectedLayerId: state.selectedLayerId === id ? null : state.selectedLayerId,
    })),
    
    updateLayer: (id, updates) => set((state) => ({
      layers: state.layers.map((l) => 
        l.id === id ? { ...l, ...updates } : l
      ),
    })),
    
    reorderLayers: (fromIndex, toIndex) => set((state) => {
      const newLayers = [...state.layers];
      const [removed] = newLayers.splice(fromIndex, 1);
      newLayers.splice(toIndex, 0, removed);
      return {
        layers: newLayers.map((l, index) => ({ ...l, order: index })),
      };
    }),
    
    selectLayer: (id) => set({ selectedLayerId: id }),
    
    // Active preset
    applyPreset: (presetId) => {
      const { presets, addLayer } = get();
      const preset = presets.find((p) => p.id === presetId);
      if (preset) {
        addLayer({
          id: `layer-${Date.now()}`,
          name: preset.name,
          isEnabled: true,
          blendMode: 'normal',
          opacity: 100,
          presetId,
          adjustments: preset.adjustments,
          order: get().layers.length,
        });
        get().addToRecent(presetId);
      }
    },
    
    applyPresetToLayer: (presetId, layerId) => {
      const { presets, updateLayer, addToRecent } = get();
      const preset = presets.find((p) => p.id === presetId);
      if (preset) {
        updateLayer(layerId, {
          presetId,
          adjustments: preset.adjustments,
        });
        addToRecent(presetId);
      }
    },
    
    selectPreset: (id) => set({ selectedPresetId: id }),
    
    // Global adjustment
    updateGlobalAdjustment: (adjustments) => set((state) => ({
      globalAdjustment: {
        ...state.globalAdjustment!,
        ...adjustments,
      },
    })),
    
    // State management
    toggleEnabled: () => set((state) => ({
      state: { ...state.state, isEnabled: !state.state.isEnabled },
    })),
    
    setCompareMode: (enabled) => set({ compareMode: enabled }),
    
    setBeforeAfterView: (enabled) => set({ beforeAfterView: enabled }),
    
    // Settings
    updateSettings: (settings) => set((state) => ({
      settings: { ...state.settings, ...settings },
    })),
    
    // UI
    togglePanel: () => set((state) => ({ isPanelOpen: !state.isPanelOpen })),
    
    // Reset
    resetAll: () => set({
      layers: [],
      globalAdjustment: defaultSettings as any,
    }),
    
    resetLayer: (id) => {
      const { presets, updateLayer } = get();
      const layer = get().layers.find((l) => l.id === id);
      if (layer?.presetId) {
        const preset = presets.find((p) => p.id === layer.presetId);
        if (preset) {
          updateLayer(id, { adjustments: preset.adjustments });
        }
      }
    },
  }))
);

/**
 * Composition Store for StoryCore
 * 
 * Manages compositions, tracks, clips with support for:
 * - Unlimited nested compositions
 * - Full CRUD operations
 * - Clipboard (copy/paste)
 * - Undo/redo stack
 * - Parent-child composition relationships
 */

import { v4 as uuidv4 } from 'uuid';
import {
  Composition,
  Track,
  Clip,
  CompositionId,
  TrackId,
  ClipId,
  TimelineState,
  ClipboardState,
  ClipboardItem,
  UndoRedoAction,
  UndoActionType,
  SelectionState,
  NestedComposition,
  Duration,
  TimeStamp,
  TrackType,
  ClipType,
  VisualProperties,
  AudioProperties,
  Keyframe,
  HistoryEntry,
} from '../services/animation/CompositionTypes';

// ============================================================================
// State Interface
// ============================================================================

interface CompositionStoreState {
  /** All compositions indexed by ID */
  compositions: Map<CompositionId, Composition>;
  
  /** All tracks indexed by ID */
  tracks: Map<TrackId, Track>;
  
  /** All clips indexed by ID */
  clips: Map<ClipId, Clip>;
  
  /** Root composition ID (top-level) */
  rootCompositionId: CompositionId | null;
  
  /** Currently active composition ID */
  activeCompositionId: CompositionId | null;
  
  /** Timeline state */
  timeline: TimelineState;
  
  /** Clipboard state */
  clipboard: ClipboardState;
  
  /** Selection state */
  selection: SelectionState;
  
  /** Undo stack */
  undoStack: HistoryEntry[];
  
  /** Redo stack */
  redoStack: HistoryEntry[];
  
  /** Maximum undo history size */
  maxUndoHistory: number;
  
  /** Whether to skip next history entry (for batch operations) */
  skipNextHistory: boolean;
}

// ============================================================================
// Initial State
// ============================================================================

const initialState: CompositionStoreState = {
  compositions: new Map(),
  tracks: new Map(),
  clips: new Map(),
  rootCompositionId: null,
  activeCompositionId: null,
  timeline: {
    currentCompositionId: '',
    playhead: 0,
    zoom: 50,
    scrollOffset: 0,
    isPlaying: false,
    playbackRate: 1,
    visibleTimeStart: 0,
    visibleTimeEnd: 60000,
    selectedClipIds: [],
    selectedTrackIds: [],
  },
  clipboard: {
    items: [],
    hasContent: false,
  },
  selection: {
    selectedCompositionIds: [],
    selectedTrackIds: [],
    selectedClipIds: [],
    isMultiSelecting: false,
  },
  undoStack: [],
  redoStack: [],
  maxUndoHistory: 100,
  skipNextHistory: false,
};

// ============================================================================
// Store Class
// ============================================================================

class CompositionStore {
  private state: CompositionStoreState;
  private listeners: Set<(state: CompositionStoreState) => void> = new Set();
  private historyListeners: Set<(canUndo: boolean, canRedo: boolean) => void> = new Set();

  constructor() {
    this.state = { ...initialState };
  }

  // ==========================================================================
  // Subscription
  // ==========================================================================

  subscribe(listener: (state: CompositionStoreState) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  subscribeToHistory(listener: (canUndo: boolean, canRedo: boolean) => void): () => void {
    this.historyListeners.add(listener);
    return () => this.historyListeners.delete(listener);
  }

  private notify(): void {
    const canUndo = this.state.undoStack.length > 0;
    const canRedo = this.state.redoStack.length > 0;
    this.listeners.forEach(listener => listener(this.state));
    this.historyListeners.forEach(listener => listener(canUndo, canRedo));
  }

  private getState(): CompositionStoreState {
    return { ...this.state };
  }

  // ==========================================================================
  // UUID Generator
  // ==========================================================================

  private generateId<T extends string>(): T {
    return uuidv4() as T;
  }

  // ==========================================================================
  // Composition CRUD Operations
  // ==========================================================================

  /**
   * Create a new composition
   */
  createComposition(
    name: string,
    width: number = 1920,
    height: number = 1080,
    duration: Duration = 60000,
    fps: number = 30,
    parentId: CompositionId | null = null
  ): Composition {
    const id = this.generateId<CompositionId>();
    const now = new Date();

    const composition: Composition = {
      id,
      name,
      width,
      height,
      duration,
      fps,
      trackIds: [],
      parentCompositionId: parentId,
      nestedCompositionIds: [],
      currentTime: 0,
      isActive: true,
      metadata: {},
      createdAt: now,
      updatedAt: now,
    };

    // Create default tracks
    const videoTrack = this.createTrackInternal(id, 'Video', 'video', 0);
    const audioTrack = this.createTrackInternal(id, 'Audio', 'audio', 1);

    composition.trackIds = [videoTrack.id, audioTrack.id];

    // Add to parent composition if nested
    if (parentId) {
      const parent = this.state.compositions.get(parentId);
      if (parent) {
        parent.nestedCompositionIds.push(id);
        parent.updatedAt = now;
      }
    }

    // Set as root if no parent
    if (!parentId && !this.state.rootCompositionId) {
      this.state.rootCompositionId = id;
    }

    this.state.compositions.set(id, composition);
    this.state.tracks.set(videoTrack.id, videoTrack);
    this.state.tracks.set(audioTrack.id, audioTrack);

    this.recordHistory('create_composition', 'composition', id, null, composition);
    this.notify();

    return composition;
  }

  /**
   * Create track internally (used by composition creation)
   */
  private createTrackInternal(
    compositionId: CompositionId,
    name: string,
    type: TrackType,
    sortOrder: number
  ): Track {
    const id = this.generateId<TrackId>();
    const track: Track = {
      id,
      name,
      compositionId,
      clipIds: [],
      type,
      isVisible: true,
      isLocked: false,
      height: 60,
      sortOrder,
      volume: 1,
      isMuted: false,
    };
    return track;
  }

  /**
   * Add a track to a composition
   */
  addTrack(
    compositionId: CompositionId,
    name: string,
    type: TrackType = 'video'
  ): Track {
    const composition = this.state.compositions.get(compositionId);
    if (!composition) {
      throw new Error(`Composition ${compositionId} not found`);
    }

    const id = this.generateId<TrackId>();
    const sortOrder = composition.trackIds.length;

    const track: Track = {
      id,
      name,
      compositionId,
      clipIds: [],
      type,
      isVisible: true,
      isLocked: false,
      height: 60,
      sortOrder,
      volume: 1,
      isMuted: false,
    };

    composition.trackIds.push(track.id);
    composition.updatedAt = new Date();
    this.state.tracks.set(id, track);

    this.recordHistory('create_track', 'track', id, null, track);
    this.notify();

    return track;
  }

  /**
   * Delete a track
   */
  deleteTrack(trackId: TrackId): boolean {
    const track = this.state.tracks.get(trackId);
    if (!track) return false;

    // Delete all clips on the track
    track.clipIds.forEach(clipId => this.deleteClipInternal(clipId));

    // Remove from composition
    const composition = this.state.compositions.get(track.compositionId);
    if (composition) {
      composition.trackIds = composition.trackIds.filter(id => id !== trackId);
      composition.updatedAt = new Date();
    }

    this.state.tracks.delete(trackId);
    this.recordHistory('delete_track', 'track', trackId, track, null);
    this.notify();

    return true;
  }

  /**
   * Get composition by ID
   */
  getComposition(id: CompositionId): Composition | undefined {
    return this.state.compositions.get(id);
  }

  /**
   * Get all compositions
   */
  getAllCompositions(): Composition[] {
    return Array.from(this.state.compositions.values());
  }

  /**
   * Update composition
   */
  updateComposition(
    id: CompositionId,
    updates: Partial<Omit<Composition, 'id' | 'createdAt'>>
  ): Composition | null {
    const composition = this.state.compositions.get(id);
    if (!composition) return null;

    const previousState = { ...composition };
    Object.assign(composition, updates, { updatedAt: new Date() });

    this.recordHistory('update_composition', 'composition', id, previousState, composition);
    this.notify();

    return composition;
  }

  /**
   * Delete a composition
   */
  deleteComposition(id: CompositionId): boolean {
    const composition = this.state.compositions.get(id);
    if (!composition) return false;

    // Recursively delete nested compositions
    composition.nestedCompositionIds.forEach(nestedId => {
      this.deleteComposition(nestedId);
    });

    // Delete all tracks and clips
    composition.trackIds.forEach(trackId => {
      this.deleteTrack(trackId);
    });

    // Remove from parent
    if (composition.parentCompositionId) {
      const parent = this.state.compositions.get(composition.parentCompositionId);
      if (parent) {
        parent.nestedCompositionIds = parent.nestedCompositionIds.filter(
          nestedId => nestedId !== id
        );
        parent.updatedAt = new Date();
      }
    }

    // Update root if needed
    if (this.state.rootCompositionId === id) {
      this.state.rootCompositionId = null;
    }

    this.state.compositions.delete(id);
    this.recordHistory('delete_composition', 'composition', id, composition, null);
    this.notify();

    return true;
  }

  // ==========================================================================
  // Clip CRUD Operations
  // ==========================================================================

  /**
   * Add a clip to a track
   */
  addClip(
    trackId: TrackId,
    name: string,
    startTime: TimeStamp,
    duration: Duration,
    type: ClipType,
    assetId?: string
  ): Clip {
    const track = this.state.tracks.get(trackId);
    if (!track) {
      throw new Error(`Track ${trackId} not found`);
    }

    const id = this.generateId<ClipId>();
    const endTime = startTime + duration;

    const clip: Clip = {
      id,
      name,
      trackId,
      compositionId: track.compositionId,
      startTime,
      endTime,
      sourceStartTime: 0,
      sourceEndTime: duration,
      type,
      assetId,
      visualProperties: this.getDefaultVisualProperties(),
      audioProperties: this.getDefaultAudioProperties(),
      effectIds: [],
      keyframes: [],
      isSelected: false,
      isLocked: false,
    };

    track.clipIds.push(clip.id);
    this.state.clips.set(id, clip);

    this.recordHistory('create_clip', 'clip', id, null, clip);
    this.notify();

    return clip;
  }

  /**
   * Get default visual properties
   */
  private getDefaultVisualProperties(): VisualProperties {
    return {
      opacity: 1,
      scale: 1,
      rotation: 0,
      x: 0,
      y: 0,
    };
  }

  /**
   * Get default audio properties
   */
  private getDefaultAudioProperties(): AudioProperties {
    return {
      volume: 1,
      pan: 0,
      fadeIn: 0,
      fadeOut: 0,
    };
  }

  /**
   * Get clip by ID
   */
  getClip(id: ClipId): Clip | undefined {
    return this.state.clips.get(id);
  }

  /**
   * Get all clips for a track
   */
  getClipsForTrack(trackId: TrackId): Clip[] {
    const track = this.state.tracks.get(trackId);
    if (!track) return [];

    return track.clipIds
      .map(id => this.state.clips.get(id))
      .filter((clip): clip is Clip => clip !== undefined);
  }

  /**
   * Move a clip to a new track and/or time
   */
  moveClip(
    clipId: ClipId,
    newTrackId: TrackId,
    newStartTime: TimeStamp
  ): Clip | null {
    const clip = this.state.clips.get(clipId);
    if (!clip) return null;

    const oldTrackId = clip.trackId;
    const oldStartTime = clip.startTime;

    // Remove from old track
    const oldTrack = this.state.tracks.get(oldTrackId);
    if (oldTrack) {
      oldTrack.clipIds = oldTrack.clipIds.filter(id => id !== clipId);
    }

    // Add to new track
    const newTrack = this.state.tracks.get(newTrackId);
    if (!newTrack) {
      // Revert
      if (oldTrack) oldTrack.clipIds.push(clipId);
      return null;
    }

    // Calculate new end time
    const duration = clip.endTime - clip.startTime;
    
    // Update clip
    clip.trackId = newTrackId;
    clip.compositionId = newTrack.compositionId;
    clip.startTime = newStartTime;
    clip.endTime = newStartTime + duration;

    newTrack.clipIds.push(clipId);

    this.recordHistory('move_clip', 'clip', clipId, 
      { trackId: oldTrackId, startTime: oldStartTime },
      { trackId: newTrackId, startTime: newStartTime }
    );
    this.notify();

    return clip;
  }

  /**
   * Resize a clip
   */
  resizeClip(
    clipId: ClipId,
    newStartTime: TimeStamp,
    newEndTime: TimeStamp
  ): Clip | null {
    const clip = this.state.clips.get(clipId);
    if (!clip) return null;

    const previousState = {
      startTime: clip.startTime,
      endTime: clip.endTime,
    };

    clip.startTime = newStartTime;
    clip.endTime = newEndTime;
    clip.sourceEndTime = newEndTime - newStartTime;

    this.recordHistory('resize_clip', 'clip', clipId, previousState, {
      startTime: newStartTime,
      endTime: newEndTime,
    });
    this.notify();

    return clip;
  }

  /**
   * Update a clip
   */
  updateClip(clipId: ClipId, updates: Partial<Clip>): Clip | null {
    const clip = this.state.clips.get(clipId);
    if (!clip) return null;

    const previousState = { ...clip };
    Object.assign(clip, updates);

    this.recordHistory('update_clip', 'clip', clipId, previousState, clip);
    this.notify();

    return clip;
  }

  /**
   * Delete a clip internally (used by track deletion)
   */
  private deleteClipInternal(clipId: ClipId): boolean {
    const clip = this.state.clips.get(clipId);
    if (!clip) return false;

    // Remove from track
    const track = this.state.tracks.get(clip.trackId);
    if (track) {
      track.clipIds = track.clipIds.filter(id => id !== clipId);
    }

    this.state.clips.delete(clipId);
    return true;
  }

  /**
   * Delete a clip
   */
  deleteClip(clipId: ClipId): boolean {
    const clip = this.state.clips.get(clipId);
    if (!clip) return false;

    const result = this.deleteClipInternal(clipId);
    if (result) {
      this.recordHistory('delete_clip', 'clip', clipId, clip, null);
      this.notify();
    }

    return result;
  }

  // ==========================================================================
  // Nested Composition Operations
  // ==========================================================================

  /**
   * Add a nested composition to a parent composition
   */
  addNestedComposition(
    parentCompositionId: CompositionId,
    nestedCompositionId: CompositionId
  ): boolean {
    const parent = this.state.compositions.get(parentCompositionId);
    const nested = this.state.compositions.get(nestedCompositionId);
    
    if (!parent || !nested) return false;

    if (parent.nestedCompositionIds.includes(nestedCompositionId)) return false;

    parent.nestedCompositionIds.push(nestedCompositionId);
    nested.parentCompositionId = parentCompositionId;
    parent.updatedAt = new Date();
    nested.updatedAt = new Date();

    this.recordHistory('add_nested_composition', 'composition', nestedCompositionId, null, {
      parentCompositionId,
    });
    this.notify();

    return true;
  }

  /**
   * Remove a nested composition from its parent
   */
  removeNestedComposition(nestedCompositionId: CompositionId): boolean {
    const nested = this.state.compositions.get(nestedCompositionId);
    if (!nested || !nested.parentCompositionId) return false;

    const parent = this.state.compositions.get(nested.parentCompositionId);
    if (parent) {
      parent.nestedCompositionIds = parent.nestedCompositionIds.filter(
        id => id !== nestedCompositionId
      );
      parent.updatedAt = new Date();
    }

    nested.parentCompositionId = null;
    nested.updatedAt = new Date();

    this.recordHistory('remove_nested_composition', 'composition', nestedCompositionId, {
      parentCompositionId: parent?.id ?? null,
    }, null);
    this.notify();

    return true;
  }

  /**
   * Get the full nesting path from root to a composition
   */
  getNestingPath(compositionId: CompositionId): CompositionId[] {
    const path: CompositionId[] = [];
    let currentId: CompositionId | null = compositionId;

    while (currentId) {
      path.unshift(currentId);
      const composition = this.state.compositions.get(currentId);
      currentId = composition?.parentCompositionId ?? null;
    }

    return path;
  }

  /**
   * Get all nested compositions recursively
   */
  getNestedCompositions(compositionId: CompositionId): Composition[] {
    const composition = this.state.compositions.get(compositionId);
    if (!composition) return [];

    const nested: Composition[] = [];
    
    composition.nestedCompositionIds.forEach(id => {
      const nestedComp = this.state.compositions.get(id);
      if (nestedComp) {
        nested.push(nestedComp);
        nested.push(...this.getNestedCompositions(id));
      }
    });

    return nested;
  }

  /**
   * Get nesting depth of a composition
   */
  getNestingDepth(compositionId: CompositionId): number {
    let depth = 0;
    let currentId: CompositionId | null = compositionId;

    while (currentId) {
      const composition = this.state.compositions.get(currentId);
      currentId = composition?.parentCompositionId ?? null;
      depth++;
    }

    return depth - 1; // Subtract 1 because we start from the composition itself
  }

  // ==========================================================================
  // Clipboard Operations
  // ==========================================================================

  /**
   * Copy a clip to clipboard
   */
  copyClip(clipId: ClipId): boolean {
    const clip = this.state.clips.get(clipId);
    if (!clip) return false;

    const item: ClipboardItem = {
      type: 'clip',
      data: { ...clip },
      sourceId: clipId,
      copiedAt: new Date(),
    };

    this.state.clipboard.items = [item];
    this.state.clipboard.hasContent = true;
    this.notify();

    return true;
  }

  /**
   * Copy multiple clips to clipboard
   */
  copyClips(clipIds: ClipId[]): boolean {
    const items: ClipboardItem[] = [];

    clipIds.forEach(clipId => {
      const clip = this.state.clips.get(clipId);
      if (clip) {
        items.push({
          type: 'clip',
          data: { ...clip },
          sourceId: clipId,
          copiedAt: new Date(),
        });
      }
    });

    this.state.clipboard.items = items;
    this.state.clipboard.hasContent = items.length > 0;
    this.notify();

    return items.length > 0;
  }

  /**
   * Paste clipboard content to a track
   */
  pasteClips(trackId: TrackId, insertTime: TimeStamp): Clip[] {
    if (!this.state.clipboard.hasContent) return [];

    const pasted: Clip[] = [];

    this.state.clipboard.items.forEach(item => {
      if (item.type === 'clip') {
        const sourceClip = item.data as Clip;
        const newClip = this.addClip(
          trackId,
          `${sourceClip.name} (Copy)`,
          insertTime,
          sourceClip.endTime - sourceClip.startTime,
          sourceClip.type,
          sourceClip.assetId
        );

        // Copy properties
        newClip.visualProperties = { ...sourceClip.visualProperties };
        newClip.audioProperties = { ...sourceClip.audioProperties };
        newClip.keyframes = [...sourceClip.keyframes];
        newClip.effectIds = [...sourceClip.effectIds];

        pasted.push(newClip);
      }
    });

    this.recordHistory('paste_clip', 'clip', pasted.map(c => c.id)[0] ?? '', null, pasted);
    this.notify();

    return pasted;
  }

  /**
   * Get clipboard state
   */
  getClipboardState(): ClipboardState {
    return { ...this.state.clipboard };
  }

  /**
   * Clear clipboard
   */
  clearClipboard(): void {
    this.state.clipboard.items = [];
    this.state.clipboard.hasContent = false;
    this.notify();
  }

  // ==========================================================================
  // Timeline Operations
  // ==========================================================================

  /**
   * Set the active composition
   */
  setActiveComposition(compositionId: CompositionId): void {
    const composition = this.state.compositions.get(compositionId);
    if (composition) {
      this.state.activeCompositionId = compositionId;
      this.state.timeline.currentCompositionId = compositionId;
      this.state.timeline.playhead = composition.currentTime;
      this.notify();
    }
  }

  /**
   * Set playhead position
   */
  setPlayhead(time: TimeStamp): void {
    this.state.timeline.playhead = time;
    
    const composition = this.state.compositions.get(this.state.timeline.currentCompositionId);
    if (composition) {
      composition.currentTime = time;
    }

    this.notify();
  }

  /**
   * Set zoom level
   */
  setZoom(zoom: number): void {
    this.state.timeline.zoom = Math.max(1, Math.min(200, zoom));
    this.notify();
  }

  /**
   * Play/pause
   */
  setPlaying(isPlaying: boolean): void {
    this.state.timeline.isPlaying = isPlaying;
    this.notify();
  }

  /**
   * Get timeline state
   */
  getTimelineState(): TimelineState {
    return { ...this.state.timeline };
  }

  // ==========================================================================
  // Selection Operations
  // ==========================================================================

  /**
   * Select a clip
   */
  selectClip(clipId: ClipId, multiSelect: boolean = false): void {
    if (multiSelect) {
      this.state.selection.selectedClipIds.push(clipId);
    } else {
      this.state.selection.selectedClipIds = [clipId];
    }
    this.notify();
  }

  /**
   * Deselect a clip
   */
  deselectClip(clipId: ClipId): void {
    this.state.selection.selectedClipIds = this.state.selection.selectedClipIds.filter(
      id => id !== clipId
    );
    this.notify();
  }

  /**
   * Clear all selections
   */
  clearSelection(): void {
    this.state.selection.selectedClipIds = [];
    this.state.selection.selectedTrackIds = [];
    this.state.selection.selectedCompositionIds = [];
    this.notify();
  }

  /**
   * Get selection state
   */
  getSelectionState(): SelectionState {
    return { ...this.state.selection };
  }

  // ==========================================================================
  // Undo/Redo Operations
  // ==========================================================================

  /**
   * Record a history entry
   */
  private recordHistory(
    operation: UndoActionType,
    entityType: 'composition' | 'track' | 'clip',
    entityId: string,
    previousValue: unknown,
    newValue: unknown,
    parentId?: string
  ): void {
    if (this.state.skipNextHistory) return;

    const entry: HistoryEntry = {
      id: this.generateId<string>(),
      operation,
      entityType,
      entityId,
      previousValue,
      newValue,
      parentId,
      timestamp: new Date(),
    };

    this.state.undoStack.push(entry);

    // Limit history size
    if (this.state.undoStack.length > this.state.maxUndoHistory) {
      this.state.undoStack.shift();
    }

    // Clear redo stack on new action
    this.state.redoStack = [];
  }

  /**
   * Undo the last action
   */
  undo(): boolean {
    const entry = this.state.undoStack.pop();
    if (!entry) return false;

    this.state.redoStack.push(entry);
    this.applyHistoryEntry(entry, false);
    this.notify();

    return true;
  }

  /**
   * Redo the last undone action
   */
  redo(): boolean {
    const entry = this.state.redoStack.pop();
    if (!entry) return false;

    this.state.undoStack.push(entry);
    this.applyHistoryEntry(entry, true);
    this.notify();

    return true;
  }

  /**
   * Apply a history entry
   */
  private applyHistoryEntry(entry: HistoryEntry, isRedo: boolean): void {
    const { entityType, entityId, previousValue, newValue } = entry;
    const value = isRedo ? newValue : previousValue;

    switch (entityType) {
      case 'composition':
        if (value === null) {
          this.state.compositions.delete(entityId as CompositionId);
        } else {
          this.state.compositions.set(entityId as CompositionId, value as Composition);
        }
        break;

      case 'track':
        if (value === null) {
          this.state.tracks.delete(entityId as TrackId);
        } else {
          this.state.tracks.set(entityId as TrackId, value as Track);
        }
        break;

      case 'clip':
        if (value === null) {
          this.state.clips.delete(entityId as ClipId);
        } else {
          this.state.clips.set(entityId as ClipId, value as Clip);
        }
        break;
    }
  }

  /**
   * Check if undo is available
   */
  canUndo(): boolean {
    return this.state.undoStack.length > 0;
  }

  /**
   * Check if redo is available
   */
  canRedo(): boolean {
    return this.state.redoStack.length > 0;
  }

  /**
   * Begin batch operation (skips history until endBatch is called)
   */
  beginBatch(): void {
    this.state.skipNextHistory = true;
  }

  /**
   * End batch operation
   */
  endBatch(): void {
    this.state.skipNextHistory = false;
  }

  /**
   * Clear all history
   */
  clearHistory(): void {
    this.state.undoStack = [];
    this.state.redoStack = [];
    this.notify();
  }

  // ==========================================================================
  // Track Operations
  // ==========================================================================

  /**
   * Get track by ID
   */
  getTrack(id: TrackId): Track | undefined {
    return this.state.tracks.get(id);
  }

  /**
   * Get all tracks for a composition
   */
  getTracksForComposition(compositionId: CompositionId): Track[] {
    const composition = this.state.compositions.get(compositionId);
    if (!composition) return [];

    return composition.trackIds
      .map(id => this.state.tracks.get(id))
      .filter((track): track is Track => track !== undefined)
      .sort((a, b) => a.sortOrder - b.sortOrder);
  }

  /**
   * Update a track
   */
  updateTrack(trackId: TrackId, updates: Partial<Track>): Track | null {
    const track = this.state.tracks.get(trackId);
    if (!track) return null;

    const previousState = { ...track };
    Object.assign(track, updates);

    this.recordHistory('update_track', 'track', trackId, previousState, track);
    this.notify();

    return track;
  }

  // ==========================================================================
  // Serialization
  // ==========================================================================

  /**
   * Export composition with all nested content
   */
  exportComposition(compositionId: CompositionId): object | null {
    const composition = this.state.compositions.get(compositionId);
    if (!composition) return null;

    const tracks = this.getTracksForComposition(compositionId);
    const nested = this.getNestedCompositions(compositionId);

    return {
      composition: { ...composition },
      tracks: tracks.map(t => ({ ...t })),
      clips: Array.from(this.state.clips.values())
        .filter(c => c.compositionId === compositionId)
        .map(c => ({ ...c })),
      nested: nested.map(c => this.exportComposition(c.id)),
    };
  }

  /**
   * Import composition
   */
  importComposition(data: object, parentId: CompositionId | null = null): Composition | null {
    try {
      const { composition, tracks, clips, nested } = data as {
        composition: Composition;
        tracks: Track[];
        clips: Clip[];
        nested: unknown[];
      };

      // Generate new IDs
      const newId = this.generateId<CompositionId>();
      const idMap = new Map<string, string>();

      // Create new composition
      const newComposition: Composition = {
        ...composition,
        id: newId,
        parentCompositionId: parentId,
        trackIds: [],
        nestedCompositionIds: [],
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      this.state.compositions.set(newId, newComposition);

      // Import tracks
      tracks.forEach((track, index) => {
        const newTrackId = this.generateId<TrackId>();
        idMap.set(track.id, newTrackId);

        const newTrack: Track = {
          ...track,
          id: newTrackId,
          compositionId: newId,
          clipIds: [],
        };

        this.state.tracks.set(newTrackId, newTrack);
        newComposition.trackIds.push(newTrackId);
      });

      // Import clips
      clips.forEach(clip => {
        const newClipId = this.generateId<ClipId>();
        idMap.set(clip.id, newClipId);

        const newClip: Clip = {
          ...clip,
          id: newClipId,
          trackId: idMap.get(clip.trackId) ?? clip.trackId,
          compositionId: newId,
        };

        this.state.clips.set(newClipId, newClip);

        const track = this.state.tracks.get(newClip.trackId);
        if (track) {
          track.clipIds.push(newClipId);
        }
      });

      // Update track references in clips
      this.state.clips.forEach(clip => {
        if (idMap.has(clip.trackId)) {
          clip.trackId = idMap.get(clip.trackId) as TrackId;
        }
      });

      // Import nested
      if (nested && nested.length > 0) {
        nested.forEach(childData => {
          const child = this.importComposition(childData as object, newId);
          if (child) {
            newComposition.nestedCompositionIds.push(child.id);
          }
        });
      }

      // Add to parent
      if (parentId) {
        const parent = this.state.compositions.get(parentId);
        if (parent) {
          parent.nestedCompositionIds.push(newId);
        }
      }

      // Set as root if no parent
      if (!parentId && !this.state.rootCompositionId) {
        this.state.rootCompositionId = newId;
      }

      this.notify();
      return newComposition;
    } catch (error) {
      console.error('Failed to import composition:', error);
      return null;
    }
  }
}

