      if (!projectPath) {
        return;
      }

      const assets = await assetService.getAllAssets(projectPath);
      set({ assets });
    } catch (error) {
      console.error('Failed to refresh assets:', error);
    }
  },

  // ============================================================================
  // Shot Actions
  // ============================================================================

  createShot: async (shotData: ShotInput) => {
    try {
      const { projectService, projectPath, currentProject } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        const shot = await projectService.createShot(projectPath, shotData);

        // Refresh shots
        await get().refreshShots();

        // Auto-select new shot
        set({ selectedShotId: shot.id });

        return shot;
      } else {
        // For in-memory projects (JSON-loaded), create shot directly
        const shot: Shot = {
          id: crypto.randomUUID(),
          title: shotData.title || `Shot ${(currentProject.storyboard?.length || 0) + 1}`,
          position: shotData.number || (currentProject.storyboard?.length || 0) + 1,
          description: shotData.description || '',
          duration: shotData.duration || 3,
          effects: [],
          audioTracks: [],
          textLayers: [],
          animations: [],

        };

        // Update current project
        const updatedProject = {
          ...currentProject,
          storyboard: [...(currentProject.storyboard || []), shot],
        };

        set({
          currentProject: updatedProject,
          shots: updatedProject.storyboard || [],
          selectedShotId: shot.id,
        });

        return shot;
      }
    } catch (error) {
      console.error('Failed to create shot:', error);
      throw error;
    }
  },

  updateShot: async (shotId: string, updates: Partial<Shot>) => {
    try {
      const { projectService, projectPath, currentProject, shots } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        // Find the shot to get its sequence ID
        const shot = shots.find(s => s.id === shotId);

        if (shot && (shot as any).sequencePlanId) {
          // This is a ProductionShot with sequence information
          const sequenceId = (shot as any).sequencePlanId;

          // Use the new sequence IPC method to update the shot in its sequence file
          if (window.electronAPI?.sequence) {
            try {
              await window.electronAPI.sequence.updateShot(projectPath, sequenceId, shotId, updates);
            } catch (error) {
              console.warn('Failed to update shot in sequence file, falling back to project service:', error);
              await projectService.updateShot(projectPath, shotId, updates);
            }
          } else {
            // Fallback to old method if sequence API not available
            await projectService.updateShot(projectPath, shotId, updates);
          }
        } else {
          // Regular shot without sequence information, use old method
          await projectService.updateShot(projectPath, shotId, updates);
        }

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, update shot directly
        const updatedStoryboard = (currentProject.storyboard || []).map(shot =>
          shot.id === shotId ? { ...shot, ...updates } : shot
        );

        const updatedProject = {
          ...currentProject,
          storyboard: updatedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: updatedStoryboard,
        });

      }
    } catch (error) {
      console.error('Failed to update shot:', error);
      throw error;
    }
  },

  deleteShot: async (shotId: string) => {
    try {
      const { projectService, projectPath, currentProject, selectedShotId } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        await projectService.deleteShot(projectPath, shotId);

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, delete shot directly
        const updatedStoryboard = (currentProject.storyboard || []).filter(
          shot => shot.id !== shotId
        );

        const updatedProject = {
          ...currentProject,
          storyboard: updatedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: updatedStoryboard,
          selectedShotId: selectedShotId === shotId ? null : selectedShotId,
        });

      }
    } catch (error) {
      console.error('Failed to delete shot:', error);
      throw error;
    }
  },

  selectShot: (shotId: string | null) => {
    set({ selectedShotId: shotId });
  },

  reorderShots: async (shotIds: string[]) => {
    try {
      const { projectService, projectPath, currentProject } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        await projectService.reorderShots(projectPath, shotIds);

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, reorder shots directly
        const shotMap = new Map((currentProject.storyboard || []).map(shot => [shot.id, shot]));
        const reorderedStoryboard = shotIds
          .map(id => shotMap.get(id))
          .filter((shot): shot is Shot => shot !== undefined);

        const updatedProject = {
          ...currentProject,
          storyboard: reorderedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: reorderedStoryboard,
        });

      }
    } catch (error) {
      console.error('Failed to reorder shots:', error);
      throw error;
    }
  },

  refreshShots: async () => {
    try {
      const { projectPath } = get();

      if (!projectPath) {
        return;
      }

      // Reload project to get updated shots
      await get().loadProject(projectPath);
    } catch (error) {
      console.error('Failed to refresh shots:', error);
    }
  },

  // ============================================================================
  // Connection Check Actions
  // ============================================================================

  checkOllamaConnection: async () => {
    const { wizardService } = get();
    return await wizardService.checkOllamaConnection();
  },

  checkComfyUIConnection: async () => {
    const { wizardService } = get();
    return await wizardService.checkComfyUIConnection();
  },

  checkAllConnections: async () => {
    const { wizardService } = get();
    return await wizardService.checkAllConnections();
  },
}));

/**
 * Generation Store - Zustand store for generation-buttons-ui feature
 * 
 * This store manages:
 * - Pipeline state (currentPipeline, stages)
 * - Queue management (tasks, activeTask)
 * - History tracking (delegated to GenerationHistoryService)
 * - Asset associations (relatedAssets graph)
 * 
 * Requirements: 6.1, 6.2, 6.3, 6.4
 */

import { create } from 'zustand';
import { generationHistoryService } from '../services/GenerationHistoryService';
import { PipelineStateMachine } from '../services/PipelineStateMachine';
import type { PipelineStage } from '../services/PipelineStateMachine';
import type {
  GenerationPipelineState,
  GenerationQueue,
  GenerationTask,
  GeneratedAsset,
  GeneratedPrompt,
  GenerationHistory,
  HistoryEntry,
  StageState,
  GenerationProgress,
  BatchGenerationConfig,
  BatchGenerationTask,
  BatchGenerationState,
} from '../types/generation';

/**
 * Asset graph for tracking relationships
 */
interface AssetGraph {
  nodes: Map<string, GeneratedAsset>;
  edges: Map<string, string[]>; // assetId -> [relatedAssetIds]
}

/**
 * Generation store state interface
 */
interface GenerationStore {
  // Pipeline state
  currentPipeline: GenerationPipelineState | null;
  
  // Queue management
  queue: GenerationQueue;
  
  // Batch generation state
  batchConfig: BatchGenerationConfig;
  activeBatch: BatchGenerationState | null;
  batchHistory: BatchGenerationState[];
  
  // History (delegated to GenerationHistoryService)
  // Use generationHistoryService for history operations
  
  // Asset graph
  assetGraph: AssetGraph;
  
  // Actions - Pipeline Management
  startPipeline: () => string;
  completeStage: (stage: 'prompt' | 'image' | 'video' | 'audio', result: GeneratedPrompt | GeneratedAsset) => void;
  failStage: (stage: 'prompt' | 'image' | 'video' | 'audio', error: string) => void;
  skipStage: (stage: 'prompt' | 'image' | 'video' | 'audio') => void;
  updateStageProgress: (stage: 'prompt' | 'image' | 'video' | 'audio', progress: GenerationProgress) => void;
  resetPipeline: () => void;
  
  // Actions - Pipeline State Machine
  progressToNextStage: () => void;
  restartFromStage: (stage: PipelineStage) => void;
  getAvailableActions: () => ReturnType<typeof PipelineStateMachine.getAvailableActions>;
  getPipelineProgress: () => number;
  getAllPipelineAssets: () => ReturnType<typeof PipelineStateMachine.getAllAssets>;
  
  // Actions - Queue Management
  addToQueue: (task: Omit<GenerationTask, 'id' | 'createdAt' | 'status' | 'progress'>) => string;
  removeFromQueue: (taskId: string) => void;
  updateTaskStatus: (taskId: string, status: GenerationTask['status']) => void;
  updateTaskProgress: (taskId: string, progress: GenerationProgress) => void;
  completeTask: (taskId: string, result: GeneratedAsset) => void;
  failTask: (taskId: string, error: string) => void;
  cancelTask: (taskId: string) => void;
  clearQueue: () => void;
  reorderQueue: (taskId: string, newIndex: number) => void;
  
  // Actions - Batch Generation Management
  setBatchConfig: (config: Partial<BatchGenerationConfig>) => void;
  startBatch: (type: 'image' | 'video' | 'audio', baseParams: Record<string, unknown>) => string;
  cancelBatch: (batchId: string) => void;
  updateBatchTaskStatus: (batchId: string, taskId: string, status: BatchGenerationTask['status']) => void;
  completeBatchTask: (batchId: string, taskId: string, result: GeneratedAsset) => void;
  failBatchTask: (batchId: string, taskId: string, error: string) => void;
  markAsFavorite: (batchId: string, assetId: string) => void;
  markAsDiscarded: (batchId: string, assetId: string) => void;
  clearBatchSelections: (batchId: string) => void;
  
  // Actions - History Management (delegated to service)
  // Use generationHistoryService.logGeneration() instead of addToHistory()
  // Use generationHistoryService.queryHistory() instead of getHistoryByType()
  // Use generationHistoryService.getEntriesByPipelineId() instead of getHistoryByPipeline()
  
  // Actions - Asset Graph Management
  linkAssets: (sourceId: string, targetId: string) => void;
  getRelatedAssets: (assetId: string) => GeneratedAsset[];
  addAssetToGraph: (asset: GeneratedAsset) => void;
  removeAssetFromGraph: (assetId: string) => void;
}

/**
 * Create initial stage state
 */
const createInitialStageState = <T>(): StageState<T> => ({
  status: 'pending',
  attempts: 0,
});

/**
 * Create initial pipeline state
 */
const createInitialPipeline = (): GenerationPipelineState => {
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    currentStage: 'prompt',
    stages: {
      prompt: createInitialStageState<GeneratedPrompt>(),
      image: createInitialStageState<GeneratedAsset>(),
      video: createInitialStageState<GeneratedAsset>(),
      audio: createInitialStageState<GeneratedAsset>(),
    },
    createdAt: now,
    updatedAt: now,
  };
};

/**
 * Create generation store with Zustand
 */
export const useGenerationStore = create<GenerationStore>((set, get) => ({
  // Initial state
  currentPipeline: null,
  queue: {
    tasks: [],
    activeTask: null,
    maxConcurrent: 1,
  },
  batchConfig: {
    enabled: false,
    batchSize: 4,
    variationParams: {
      varySeeds: true,
      varyPrompts: false,
      varyParameters: false,
    },
  },
  activeBatch: null,
  batchHistory: [],
  assetGraph: {
    nodes: new Map(),
    edges: new Map(),
  },

  // ============================================================================
  // Pipeline Management Actions
  // ============================================================================

  startPipeline: () => {
    const pipeline = createInitialPipeline();
    set({ currentPipeline: pipeline });
    return pipeline.id;
  },

  completeStage: (stage, result) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    // Use type assertion to handle the union type assignment
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      status: 'completed',
      result: result,
      attempts: updatedPipeline.stages[stage].attempts + 1,
    };

    // Determine next stage
    const stageOrder: Array<'prompt' | 'image' | 'video' | 'audio'> = ['prompt', 'image', 'video', 'audio'];
    const currentIndex = stageOrder.indexOf(stage);
    const nextStage = currentIndex < stageOrder.length - 1 ? stageOrder[currentIndex + 1] : 'complete';

    updatedPipeline.currentStage = nextStage as GenerationPipelineState['currentStage'];
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });

    // Add to history if result is an asset (using GenerationHistoryService)
    if ('url' in result) {
      generationHistoryService.logGeneration(
        updatedPipeline.id,
        stage as 'image' | 'video' | 'audio',
        result.metadata.generationParams,
        result as GeneratedAsset
      );

      // Add to asset graph
      get().addAssetToGraph(result as GeneratedAsset);
    }
  },

  failStage: (stage, error) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'failed',
      error,
      attempts: updatedPipeline.stages[stage].attempts + 1,
    };
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  skipStage: (stage) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'skipped',
    };

    // Determine next stage
    const stageOrder: Array<'prompt' | 'image' | 'video' | 'audio'> = ['prompt', 'image', 'video', 'audio'];
    const currentIndex = stageOrder.indexOf(stage);
    const nextStage = currentIndex < stageOrder.length - 1 ? stageOrder[currentIndex + 1] : 'complete';

    updatedPipeline.currentStage = nextStage as GenerationPipelineState['currentStage'];
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  updateStageProgress: (stage, progress) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'in_progress',
      progress,
    };
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  resetPipeline: () => {
    set({ currentPipeline: null });
  },

  // ============================================================================
  // Pipeline State Machine Actions
  // ============================================================================

  progressToNextStage: () => {
    const state = get();
    if (!state.currentPipeline) return;

    const nextStage = PipelineStateMachine.getNextStage(state.currentPipeline.currentStage);
    if (!nextStage) return;

    const updatedPipeline = { ...state.currentPipeline };
    updatedPipeline.currentStage = nextStage;
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  restartFromStage: (stage) => {
    const state = get();
    if (!state.currentPipeline) return;

    if (!PipelineStateMachine.canRestartFromStage(state.currentPipeline, stage)) {
      throw new Error(`Cannot restart from stage: ${stage}`);
    }

    const { clearSubsequent } = PipelineStateMachine.getRestartStage(state.currentPipeline, stage);
    const updatedPipeline = { ...state.currentPipeline };

    // Reset the target stage
    updatedPipeline.currentStage = stage;
    updatedPipeline.stages[stage as keyof typeof updatedPipeline.stages] = {
      status: 'pending',
      attempts: 0,
    };

    // Clear subsequent stages if needed
    if (clearSubsequent) {
      const allStages = PipelineStateMachine.getAllStages();
      const stageIndex = allStages.indexOf(stage);
      
      for (let i = stageIndex + 1; i < allStages.length; i++) {
        const stageToReset = allStages[i];
        if (stageToReset !== 'complete') {
          updatedPipeline.stages[stageToReset as keyof typeof updatedPipeline.stages] = {
            status: 'pending',
            attempts: 0,
          };
        }
      }
    }

    updatedPipeline.updatedAt = Date.now();
    set({ currentPipeline: updatedPipeline });
  },

  getAvailableActions: () => {
    const state = get();
    if (!state.currentPipeline) {
      return {
        canProgress: false,
        canSkip: false,
        canRestart: false,
        restartableStages: [],
      };
    }

    return PipelineStateMachine.getAvailableActions(state.currentPipeline);
  },

  getPipelineProgress: () => {
    const state = get();
    if (!state.currentPipeline) return 0;
    return PipelineStateMachine.calculateProgress(state.currentPipeline);
  },

  getAllPipelineAssets: () => {
    const state = get();
    if (!state.currentPipeline) {
      return {
        prompt: undefined,
        image: undefined,
        video: undefined,
        audio: undefined,
      };
    }

    return PipelineStateMachine.getAllAssets(state.currentPipeline);
  },

  // ============================================================================
  // Queue Management Actions
  // ============================================================================

  addToQueue: (taskData) => {
    const task: GenerationTask = {
      ...taskData,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      status: 'queued',
      progress: {
        stage: '',
        stageProgress: 0,
        overallProgress: 0,
        estimatedTimeRemaining: 0,
        message: 'Queued',
        cancellable: true,
      },
    };

    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: [...state.queue.tasks, task],
      },
    });

    return task.id;
  },

  removeFromQueue: (taskId) => {
    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: state.queue.tasks.filter(t => t.id !== taskId),
        activeTask: state.queue.activeTask === taskId ? null : state.queue.activeTask,
      },
    });
  },

  updateTaskStatus: (taskId, status) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId ? { ...t, status } : t
    );
    const activeTask = status === 'running' ? taskId : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  updateTaskProgress: (taskId, progress) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId ? { ...t, progress } : t
    );

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
      },
    });
  },

  completeTask: (taskId, result) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'completed' as const, result, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  failTask: (taskId, error) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'failed' as const, error, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  cancelTask: (taskId) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'cancelled' as const, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  clearQueue: () => {
    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: [],
        activeTask: null,
      },
    });
  },

  reorderQueue: (taskId, newIndex) => {
    const state = get();
    const tasks = [...state.queue.tasks];
    const currentIndex = tasks.findIndex(t => t.id === taskId);
    
    if (currentIndex === -1 || newIndex < 0 || newIndex >= tasks.length) {
      return;
    }

    const [task] = tasks.splice(currentIndex, 1);
    tasks.splice(newIndex, 0, task);

    set({
      queue: {
        ...state.queue,
        tasks,
      },
    });
  },

  // ============================================================================
  // Batch Generation Management Actions
  // ============================================================================

  setBatchConfig: (config) => {
    const state = get();
    set({
      batchConfig: {
        ...state.batchConfig,
        ...config,
      },
    });
  },

  startBatch: (type, baseParams) => {
    const state = get();
    const { batchConfig } = state;
    
    if (!batchConfig.enabled) {
      throw new Error('Batch generation is not enabled');
    }

    const batchId = crypto.randomUUID();
    const tasks: BatchGenerationTask[] = [];

    // Generate tasks based on batch configuration
    for (let i = 0; i < batchConfig.batchSize; i++) {
      const params = { ...baseParams };

      // Apply variations
      if (batchConfig.variationParams.varySeeds) {
        const seedRange = batchConfig.variationParams.seedRange || [0, 999999];
        params.seed = Math.floor(Math.random() * (seedRange[1] - seedRange[0] + 1)) + seedRange[0];
      }

      if (batchConfig.variationParams.varyPrompts && batchConfig.variationParams.promptVariations) {
        const variations = batchConfig.variationParams.promptVariations;
        params.prompt = variations[i % variations.length];
      }

      if (batchConfig.variationParams.varyParameters && batchConfig.variationParams.parameterRanges) {
        Object.entries(batchConfig.variationParams.parameterRanges).forEach(([key, [min, max]]) => {
          params[key] = Math.random() * (max - min) + min;
        });
      }

      tasks.push({
        id: crypto.randomUUID(),
        batchId,
        type,
        params,
        priority: 1,
        status: 'queued',
        progress: {
          stage: '',
          stageProgress: 0,
          overallProgress: 0,
          estimatedTimeRemaining: 0,
          message: 'Queued',
          cancellable: true,
        },
        createdAt: Date.now(),
        batchIndex: i,
      });
    }

    const batch: BatchGenerationState = {
      id: batchId,
      config: batchConfig,
      tasks,
      status: 'pending',
      completedCount: 0,
      failedCount: 0,
      results: [],
      favorites: new Set(),
      discarded: new Set(),
      createdAt: Date.now(),
    };

    set({ activeBatch: batch });
    return batchId;
  },

  cancelBatch: (batchId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const cancelledBatch: BatchGenerationState = {
        ...state.activeBatch,
        status: 'cancelled',
        completedAt: Date.now(),
        tasks: state.activeBatch.tasks.map(t => 
          t.status === 'queued' || t.status === 'running'
            ? { ...t, status: 'cancelled' as const }
            : t
        ),
      };

      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, cancelledBatch],
      });
    }
  },

  updateBatchTaskStatus: (batchId, taskId, status) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId ? { ...t, status, startedAt: status === 'running' ? Date.now() : t.startedAt } : t
    );

    set({
      activeBatch: {
        ...state.activeBatch,
        tasks: updatedTasks,
        status: updatedTasks.some(t => t.status === 'running') ? 'running' : state.activeBatch.status,
      },
    });
  },

  completeBatchTask: (batchId, taskId, result) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'completed' as const, result, completedAt: Date.now() }
        : t
    );

    const completedCount = updatedTasks.filter(t => t.status === 'completed').length;
    const failedCount = updatedTasks.filter(t => t.status === 'failed').length;
    const allDone = updatedTasks.every(t => 
      t.status === 'completed' || t.status === 'failed' || t.status === 'cancelled'
    );

    const updatedBatch: BatchGenerationState = {
      ...state.activeBatch,
      tasks: updatedTasks,
      completedCount,
      failedCount,
      results: [...state.activeBatch.results, result],
      status: allDone ? 'completed' : 'running',
      completedAt: allDone ? Date.now() : undefined,
    };

    // Add result to asset graph
    get().addAssetToGraph(result);

    // If batch is complete, move to history
    if (allDone) {
      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, updatedBatch],
      });
    } else {
      set({ activeBatch: updatedBatch });
    }
  },

  failBatchTask: (batchId, taskId, error) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'failed' as const, error, completedAt: Date.now() }
        : t
    );

    const completedCount = updatedTasks.filter(t => t.status === 'completed').length;
    const failedCount = updatedTasks.filter(t => t.status === 'failed').length;
    const allDone = updatedTasks.every(t => 
      t.status === 'completed' || t.status === 'failed' || t.status === 'cancelled'
    );

    const updatedBatch: BatchGenerationState = {
      ...state.activeBatch,
      tasks: updatedTasks,
      completedCount,
      failedCount,
      status: allDone ? (completedCount > 0 ? 'completed' : 'failed') : 'running',
      completedAt: allDone ? Date.now() : undefined,
    };

    // If batch is complete, move to history
    if (allDone) {
      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, updatedBatch],
      });
    } else {
      set({ activeBatch: updatedBatch });
    }
  },

  markAsFavorite: (batchId, assetId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const favorites = new Set(state.activeBatch.favorites);
      const discarded = new Set(state.activeBatch.discarded);
      
      favorites.add(assetId);
      discarded.delete(assetId); // Remove from discarded if present

      set({
        activeBatch: {
          ...state.activeBatch,
          favorites,
          discarded,
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        const batch = updatedHistory[batchIndex];
        const favorites = new Set(batch.favorites);
        const discarded = new Set(batch.discarded);
        
        favorites.add(assetId);
        discarded.delete(assetId);

        updatedHistory[batchIndex] = {
          ...batch,
          favorites,
          discarded,
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  markAsDiscarded: (batchId, assetId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const favorites = new Set(state.activeBatch.favorites);
      const discarded = new Set(state.activeBatch.discarded);
      
      discarded.add(assetId);
      favorites.delete(assetId); // Remove from favorites if present

      set({
        activeBatch: {
          ...state.activeBatch,
          favorites,
          discarded,
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        const batch = updatedHistory[batchIndex];
        const favorites = new Set(batch.favorites);
        const discarded = new Set(batch.discarded);
        
        discarded.add(assetId);
        favorites.delete(assetId);

        updatedHistory[batchIndex] = {
          ...batch,
          favorites,
          discarded,
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  clearBatchSelections: (batchId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      set({
        activeBatch: {
          ...state.activeBatch,
          favorites: new Set(),
          discarded: new Set(),
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        updatedHistory[batchIndex] = {
          ...updatedHistory[batchIndex],
          favorites: new Set(),
          discarded: new Set(),
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  // ============================================================================
  // Asset Graph Management Actions
  // ============================================================================

  linkAssets: (sourceId, targetId) => {
    const state = get();
    const edges = new Map(state.assetGraph.edges);
    const existing = edges.get(sourceId) || [];
    
    if (!existing.includes(targetId)) {
      edges.set(sourceId, [...existing, targetId]);
    }

    set({
      assetGraph: {
        ...state.assetGraph,
        edges,
      },
    });
  },

  getRelatedAssets: (assetId) => {
    const { assetGraph } = get();
    const relatedIds = assetGraph.edges.get(assetId) || [];
    return relatedIds
      .map(id => assetGraph.nodes.get(id))
      .filter((asset): asset is GeneratedAsset => asset !== undefined);
  },

  addAssetToGraph: (asset) => {
    const state = get();
    const nodes = new Map(state.assetGraph.nodes);
    nodes.set(asset.id, asset);

    set({
      assetGraph: {
        ...state.assetGraph,
        nodes,
      },
    });
  },

  removeAssetFromGraph: (assetId) => {
    const state = get();
    const nodes = new Map(state.assetGraph.nodes);
    const edges = new Map(state.assetGraph.edges);
    
    nodes.delete(assetId);
    edges.delete(assetId);
    
    // Remove from other assets' edges
    edges.forEach((targets, sourceId) => {
      const filtered = targets.filter(id => id !== assetId);
      if (filtered.length !== targets.length) {
        edges.set(sourceId, filtered);
      }
    });

    set({
      assetGraph: {
        nodes,
        edges,
      },
    });
  },
}));

/**
 * Grid Editor Store - Zustand store for Advanced Grid Editor feature
 * 
 * This store manages the complete state for the 3x3 Master Coherence Sheet editor:
 * - Grid configuration (panels, layers, transforms, crops)
 * - Panel selection and active tool state
 * - Clipboard operations
 * - Integration with backend services
 * 
 * Requirements: 1.5, 2.1, 2.2, 2.3, 3.2, 4.6, 5.1, 5.2, 5.5, 10.1, 10.2
 */

import { create } from 'zustand';

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * Geometry primitives
 */
export interface Point {
  x: number;
  y: number;
}

export interface Rectangle {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Transform (Position, scale, rotation)
 */
export interface Transform {
  position: Point; // pixels from panel origin
  scale: Point; // 1.0 = 100%
  rotation: number; // degrees
  pivot: Point; // 0-1 normalized
}

/**
 * Crop Region (Normalized coordinates)
 */
export interface CropRegion {
  x: number; // 0-1
  y: number; // 0-1
  width: number; // 0-1
  height: number; // 0-1
}

/**
 * Blend modes for layer composition
 */
export type BlendMode = 'normal' | 'multiply' | 'screen' | 'overlay' | 'darken' | 'lighten';

/**
 * Layer content types
 */
export interface ImageContent {
  type: 'image';
  url: string;
  naturalWidth: number;
  naturalHeight: number;
}

export interface AnnotationContent {
  type: 'annotation';
  drawings: DrawingElement[];
  textAnnotations: TextAnnotation[];
}

export interface EffectContent {
  type: 'effect';
  effectType: string;
  parameters: Record<string, unknown>;
}

export type LayerContent = ImageContent | AnnotationContent | EffectContent;

/**
 * Drawing elements for annotations
 */
export interface DrawingElement {
  id: string;
  type: 'path' | 'rectangle' | 'ellipse' | 'line';
  points: Point[];
  style: {
    strokeColor: string;
    strokeWidth: number;
    fillColor?: string;
    opacity: number;
  };
}

export interface TextAnnotation {
  id: string;
  text: string;
  position: Point;
  style: {
    fontSize: number;
    fontFamily: string;
    color: string;
    backgroundColor?: string;
  };
}

/**
 * Layer (Composable visual element)
 */
export interface Layer {
  id: string;
  name: string;
  type: 'image' | 'annotation' | 'effect';
  visible: boolean;
  locked: boolean;
  opacity: number; // 0-1
  blendMode: BlendMode;
  content: LayerContent;
}

/**
 * Panel (Individual grid cell)
 */
export interface Panel {
  id: string;
  position: { row: number; col: number }; // 0-2 for 3x3
  layers: Layer[];
  transform: Transform;
  crop: CropRegion | null;
  annotations: Annotation[];
  metadata: {
    generatedAt?: number; // timestamp in ms
    seed?: number;
    qualityScore?: number;
    modified?: boolean;
  };
}

/**
 * Annotation (visual markers and feedback)
 */
export interface Annotation {
  id: string;
  type: 'drawing' | 'text';
  content: string;
  visible: boolean;
}

/**
 * Grid Configuration (Top-level)
 */
export interface GridConfiguration {
  version: string; // "1.0"
  projectId: string;
  panels: Panel[];
  presets: Preset[];
  metadata: {
    createdAt: number; // timestamp in ms
    modifiedAt: number; // timestamp in ms
    author?: string;
    description?: string;
  };
}

/**
 * Preset (Predefined configuration)
 */
export interface Preset {
  id: string;
  name: string;
  description: string;
  thumbnail?: string;
  panelTransforms: Transform[];
  panelCrops: (CropRegion | null)[];
}

/**
 * Tool types
 */
export type Tool = 'select' | 'crop' | 'rotate' | 'scale' | 'pan' | 'annotate';

// ============================================================================
// Store Interface
// ============================================================================

export interface GridStore {
  // ============================================================================
  // State
  // ============================================================================

  config: GridConfiguration;
  selectedPanelIds: string[];
  activeTool: Tool;
  clipboard: Panel | null;

  // ============================================================================
  // Selection Actions
  // ============================================================================

  /**
   * Select a panel, optionally adding to existing selection
   * Requirements: 2.1, 2.2, 2.3
   */
  selectPanel: (panelId: string, addToSelection: boolean) => void;

  /**
   * Deselect all panels
   * Requirements: 2.4
   */
  deselectAll: () => void;

  /**
   * Get currently selected panels
   */
  getSelectedPanels: () => Panel[];

  // ============================================================================
  // Transform Actions
  // ============================================================================

  /**
   * Update transform for a specific panel
   * Requirements: 3.2, 3.3, 3.4, 3.5, 3.6, 3.8
   */
  updatePanelTransform: (panelId: string, transform: Transform) => void;

  /**
   * Apply transform to multiple panels simultaneously
   * Requirements: 6.2
   */
  updateMultiplePanelTransforms: (panelIds: string[], transform: Transform) => void;

  // ============================================================================
  // Crop Actions
  // ============================================================================

  /**
   * Update crop region for a specific panel
   * Requirements: 4.2, 4.3, 4.4, 4.6, 4.7
   */
  updatePanelCrop: (panelId: string, crop: CropRegion | null) => void;

  // ============================================================================
  // Layer Management Actions
  // ============================================================================

  /**
   * Add a new layer to a panel
   * Requirements: 5.1
   */
  addLayer: (panelId: string, layer: Layer) => void;

  /**
   * Remove a layer from a panel
   * Requirements: 5.5
   */
  removeLayer: (panelId: string, layerId: string) => void;

  /**
   * Reorder layers within a panel
   * Requirements: 5.2
   */
  reorderLayers: (panelId: string, layerId: string, newIndex: number) => void;

  /**
   * Update layer properties
   * Requirements: 5.3, 5.4, 5.8
   */
  updateLayer: (panelId: string, layerId: string, updates: Partial<Layer>) => void;

  /**
   * Toggle layer visibility
   * Requirements: 5.3
   */
  toggleLayerVisibility: (panelId: string, layerId: string) => void;

  /**
   * Toggle layer lock status
   * Requirements: 5.4
   */
  toggleLayerLock: (panelId: string, layerId: string) => void;

  // ============================================================================
  // Generation Actions
  // ============================================================================

  /**
   * Update panel image after generation
   * Requirements: 11.2
   */
  updatePanelImage: (
    panelId: string,
    imageUrl: string,
    metadata: {
      seed: number;
      generationTime: number;
      qualityScore: number;
      width: number;
      height: number;
    }
  ) => void;

  /**
   * Mark panel as modified
   * Requirements: 11.5
   */
  markPanelAsModified: (panelId: string) => void;

  /**
   * Push operation to undo stack
   * Requirements: 11.7
   */
  // Using 'any' for operation parameter to support flexible operation types from undo/redo system
  pushOperation: (operation: unknown) => void;

  // ============================================================================
  // Tool Actions
  // ============================================================================

  /**
   * Set the active editing tool
   * Requirements: 8.1, 8.2, 8.3, 8.4
   */
  setActiveTool: (tool: Tool) => void;

  // ============================================================================
  // Clipboard Actions
  // ============================================================================

  /**
   * Copy a panel to clipboard
   * Requirements: 8.8
   */
  copyPanel: (panelId: string) => void;

  /**
   * Paste clipboard content to target panel
   * Requirements: 8.8
   */
  pastePanel: (targetPanelId: string) => void;

  /**
   * Duplicate a panel
   * Requirements: 8.8
   */
  duplicatePanel: (panelId: string, targetPanelId: string) => void;

  // ============================================================================
  // Configuration Persistence Actions
  // ============================================================================

  /**
   * Load a grid configuration
   * Requirements: 10.2
   */
  loadConfiguration: (config: GridConfiguration) => void;

  /**
   * Export current grid configuration
   * Requirements: 10.1, 10.3
   */
  exportConfiguration: () => GridConfiguration;

  /**
   * Reset to default configuration
   */
  resetConfiguration: (projectId: string) => void;

  // ============================================================================
  // Panel Query Helpers
  // ============================================================================

  /**
   * Get panel by ID
   */
  getPanelById: (panelId: string) => Panel | undefined;

  /**
   * Get panel by grid position
   */
  getPanelByPosition: (row: number, col: number) => Panel | undefined;

  /**
   * Get all panels
   */
  getAllPanels: () => Panel[];

  // ============================================================================
  // Preset Actions
  // ============================================================================

  /**
   * Apply a preset to the grid
   * Requirements: 14.1, 14.2, 14.5
   */
  applyPreset: (preset: Preset) => void;
}

// ============================================================================
// Default Values and Helpers
// ============================================================================

/**
 * Create default transform
 */
export const createDefaultTransform = (): Transform => ({
  position: { x: 0, y: 0 },
  scale: { x: 1.0, y: 1.0 },
  rotation: 0,
  pivot: { x: 0.5, y: 0.5 },
});

/**
 * Create default panel
 */
export const createDefaultPanel = (row: number, col: number): Panel => ({
  id: `panel-${row}-${col}`,
  position: { row, col },
  layers: [],
  transform: createDefaultTransform(),
  crop: null,
  annotations: [],
  metadata: {},
});

/**
 * Create default grid configuration
 */
export const createDefaultGridConfiguration = (projectId: string): GridConfiguration => {
  const panels: Panel[] = [];

  // Create 3x3 grid of panels
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      panels.push(createDefaultPanel(row, col));
    }
  }

  return {
    version: '1.0',
    projectId,
    panels,
    presets: [],
    metadata: {
      createdAt: Date.now(),
      modifiedAt: Date.now(),
    },
  };
};

// ============================================================================
// Store Implementation
// ============================================================================

/**
 * Create Grid Editor Store with Zustand
 */
export const useGridStore = create<GridStore>((set, get) => ({
  // ============================================================================
  // Initial State
  // ============================================================================

  config: createDefaultGridConfiguration('default'),
  selectedPanelIds: [],
  activeTool: 'select',
  clipboard: null,

  // ============================================================================
  // Selection Actions
  // ============================================================================

  selectPanel: (panelId: string, addToSelection: boolean = false) => {
    set((state) => {
      if (addToSelection) {
        // Add to selection if not already selected
        if (!state.selectedPanelIds.includes(panelId)) {
          return {
            selectedPanelIds: [...state.selectedPanelIds, panelId],
          };
        }
        return state;
      } else {
        // Replace selection with single panel
        return {
          selectedPanelIds: [panelId],
        };
      }
    });
  },

  deselectAll: () => {
    set({ selectedPanelIds: [] });
  },

  getSelectedPanels: () => {
    const { config, selectedPanelIds } = get();
    return config.panels.filter((panel) => selectedPanelIds.includes(panel.id));
  },

  // ============================================================================
  // Transform Actions
  // ============================================================================

  updatePanelTransform: (panelId: string, transform: Transform) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? { ...panel, transform }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  updateMultiplePanelTransforms: (panelIds: string[], transform: Transform) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panelIds.includes(panel.id)
            ? { ...panel, transform }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  // ============================================================================
  // Crop Actions
  // ============================================================================

  updatePanelCrop: (panelId: string, crop: CropRegion | null) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? { ...panel, crop }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  // ============================================================================
  // Layer Management Actions
  // ============================================================================

  addLayer: (panelId: string, layer: Layer) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? { ...panel, layers: [...panel.layers, layer] }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  removeLayer: (panelId: string, layerId: string) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? {
              ...panel,
              layers: panel.layers.filter((layer) => layer.id !== layerId),
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  reorderLayers: (panelId: string, layerId: string, newIndex: number) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) => {
          if (panel.id !== panelId) return panel;

          const layers = [...panel.layers];
          const currentIndex = layers.findIndex((layer) => layer.id === layerId);

          if (currentIndex === -1) return panel;

          // Remove layer from current position
          const [layer] = layers.splice(currentIndex, 1);

          // Insert at new position
          layers.splice(newIndex, 0, layer);

          return { ...panel, layers };
        }),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  updateLayer: (panelId: string, layerId: string, updates: Partial<Layer>) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? {
              ...panel,
              layers: panel.layers.map((layer) =>
                layer.id === layerId
                  ? { ...layer, ...updates }
                  : layer
              ),
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  toggleLayerVisibility: (panelId: string, layerId: string) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? {
              ...panel,
              layers: panel.layers.map((layer) =>
                layer.id === layerId
                  ? { ...layer, visible: !layer.visible }
                  : layer
              ),
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  toggleLayerLock: (panelId: string, layerId: string) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? {
              ...panel,
              layers: panel.layers.map((layer) =>
                layer.id === layerId
                  ? { ...layer, locked: !layer.locked }
                  : layer
              ),
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  // ============================================================================
  // Tool Actions
  // ============================================================================

  setActiveTool: (tool: Tool) => {
    set({ activeTool: tool });
  },

  // ============================================================================
  // Clipboard Actions
  // ============================================================================

  copyPanel: (panelId: string) => {
    const panel = get().getPanelById(panelId);
    if (panel) {
      set({ clipboard: { ...panel } });
    }
  },

  pastePanel: (targetPanelId: string) => {
    const { clipboard } = get();
    if (!clipboard) return;

    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === targetPanelId
            ? {
              ...panel,
              layers: clipboard.layers.map((layer) => ({
                ...layer,
                id: `${layer.id}-copy-${Date.now()}`,
              })),
              transform: clipboard.transform,
              crop: clipboard.crop,
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  duplicatePanel: (panelId: string, targetPanelId: string) => {
    get().copyPanel(panelId);
    get().pastePanel(targetPanelId);
  },

  // ============================================================================
  // Configuration Persistence Actions
  // ============================================================================

  loadConfiguration: (config: GridConfiguration) => {
    set({
      config,
      selectedPanelIds: [],
      activeTool: 'select',
    });
  },

  exportConfiguration: () => {
    return get().config;
  },

  resetConfiguration: (projectId: string) => {
    set({
      config: createDefaultGridConfiguration(projectId),
      selectedPanelIds: [],
      activeTool: 'select',
      clipboard: null,
    });
  },

  // ============================================================================
  // Panel Query Helpers
  // ============================================================================

  getPanelById: (panelId: string) => {
    return get().config.panels.find((panel) => panel.id === panelId);
  },

  getPanelByPosition: (row: number, col: number) => {
    return get().config.panels.find(
      (panel) => panel.position.row === row && panel.position.col === col
    );
  },

  getAllPanels: () => {
    return get().config.panels;
  },

  // ============================================================================
  // Generation Actions
  // ============================================================================

  updatePanelImage: (
    panelId: string,
    imageUrl: string,
    metadata: {
      seed: number;
      generationTime: number;
      qualityScore: number;
      width: number;
      height: number;
    }
  ) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) => {
          if (panel.id !== panelId) return panel;

          // Create or update the image layer
          const imageLayer: Layer = {
            id: `layer-image-${Date.now()}`,
            name: 'Generated Image',
            type: 'image',
            visible: true,
            locked: false,
            opacity: 1.0,
            blendMode: 'normal',
            content: {
              type: 'image',
              url: imageUrl,
              naturalWidth: metadata.width,
              naturalHeight: metadata.height,
            },
          };

          // Replace first layer or add new layer
          const layers = panel.layers.length > 0
            ? [imageLayer, ...panel.layers.slice(1)]
            : [imageLayer];

          return {
            ...panel,
            layers,
            metadata: {
              ...panel.metadata,
              generatedAt: Date.now(),
              seed: metadata.seed,
              qualityScore: metadata.qualityScore,
              modified: false, // Reset modified flag after generation
            },
          };
        }),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  markPanelAsModified: (panelId: string) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel) =>
          panel.id === panelId
            ? {
              ...panel,
              metadata: {
                ...panel.metadata,
                modified: true,
              },
            }
            : panel
        ),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },

  // Using 'any' for _operation parameter to match interface signature
  pushOperation: (_operation: unknown) => {
    // This is a placeholder - the actual undo/redo is handled by useUndoRedoStore
    // This method is here for convenience so components can call it directly
    // In practice, components should import and use useUndoRedoStore directly
    console.warn('pushOperation called on GridStore - use useUndoRedoStore instead');
  },

  // ============================================================================
  // Preset Actions
  // ============================================================================

  applyPreset: (preset: Preset) => {
    set((state) => ({
      config: {
        ...state.config,
        panels: state.config.panels.map((panel, index) => ({
          ...panel,
          // Apply preset transform (preserve existing images)
          transform: preset.panelTransforms[index] || panel.transform,
          // Apply preset crop
          crop: preset.panelCrops[index] !== undefined ? preset.panelCrops[index] : panel.crop,
        })),
        metadata: {
          ...state.config.metadata,
          modifiedAt: Date.now(),
        },
      },
    }));
  },
}));

