// ============================================================================
// Preset Store Interface
// ============================================================================

interface PresetStore {
  // State
  presets: Preset[];
  customPresets: Preset[];
  selectedPresetId: string | null;
  
  // Actions
  loadDefaultPresets: () => void;
  addCustomPreset: (preset: Omit<Preset, 'id'>) => string;
  deleteCustomPreset: (presetId: string) => boolean;
  getPresetById: (presetId: string) => Preset | undefined;
  getAllPresets: () => Preset[];
  selectPreset: (presetId: string | null) => void;
  updatePresetThumbnail: (presetId: string, thumbnail: string) => void;
}

// ============================================================================
// Preset Store Implementation
// ============================================================================

export const usePresetStore = create<PresetStore>()(
  persist(
    (set, get) => ({
      // Initial state
      presets: DEFAULT_PRESETS,
      customPresets: [],
      selectedPresetId: null,

      // Load default presets (useful for reset)
      loadDefaultPresets: () => {
        set({ presets: DEFAULT_PRESETS });
      },

      // Add a custom preset
      addCustomPreset: (preset) => {
        const newPreset: Preset = {
          ...preset,
          id: `preset-custom-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        };
        
        set((state) => ({
          customPresets: [...state.customPresets, newPreset],
        }));
        
        return newPreset.id;
      },

      // Delete a custom preset
      deleteCustomPreset: (presetId) => {
        const state = get();
        
        // Prevent deletion of default presets
        if (state.presets.some(p => p.id === presetId)) {
          console.warn('Cannot delete default preset:', presetId);
          return false;
        }
        
        set((state) => ({
          customPresets: state.customPresets.filter(p => p.id !== presetId),
          selectedPresetId: state.selectedPresetId === presetId ? null : state.selectedPresetId,
        }));
        
        return true;
      },

      // Get preset by ID
      getPresetById: (presetId) => {
        const state = get();
        return [...state.presets, ...state.customPresets].find(p => p.id === presetId);
      },

      // Get all presets (default + custom)
      getAllPresets: () => {
        const state = get();
        return [...state.presets, ...state.customPresets];
      },

      // Select a preset
      selectPreset: (presetId) => {
        set({ selectedPresetId: presetId });
      },

      // Update preset thumbnail
      updatePresetThumbnail: (presetId, thumbnail) => {
        set((state) => {
          // Update in default presets
          const updatedPresets = state.presets.map(p =>
            p.id === presetId ? { ...p, thumbnail } : p
          );
          
          // Update in custom presets
          const updatedCustomPresets = state.customPresets.map(p =>
            p.id === presetId ? { ...p, thumbnail } : p
          );
          
          return {
            presets: updatedPresets,
            customPresets: updatedCustomPresets,
          };
        });
      },
    }),
    {
      name: 'grid-editor-presets', // localStorage key
      partialize: (state) => ({
        // Only persist custom presets, not default ones
        customPresets: state.customPresets,
        selectedPresetId: state.selectedPresetId,
      }),
    }
  )
);

// ============================================================================
// Preset Utilities
// ============================================================================

/**
 * Create a preset from current grid configuration
 */
export function createPresetFromPanels(
  name: string,
  description: string,
  panels: Array<{ transform: Transform; crop: CropRegion | null }>
): Omit<Preset, 'id'> {
  return {
    name,
    description,
    thumbnail: undefined,
    panelTransforms: panels.map(p => p.transform),
    panelCrops: panels.map(p => p.crop),
  };
}

/**
 * Validate preset structure
 */
export function validatePreset(preset: Preset): boolean {
  if (!preset.id || !preset.name) {
    return false;
  }
  
  if (preset.panelTransforms.length !== 9) {
    return false;
  }
  
  if (preset.panelCrops.length !== 9) {
    return false;
  }
  
  return true;
}

/**
 * Generate thumbnail data URL from canvas
 */
export function generatePresetThumbnail(
  canvas: HTMLCanvasElement,
  width: number = 200,
  height: number = 200
): string {
  const thumbnailCanvas = document.createElement('canvas');
  thumbnailCanvas.width = width;
  thumbnailCanvas.height = height;
  
  const ctx = thumbnailCanvas.getContext('2d');
  if (!ctx) {
    return '';
  }
  
  // Draw scaled version of main canvas
  ctx.drawImage(canvas, 0, 0, width, height);
  
  return thumbnailCanvas.toDataURL('image/png');
}

/**
 * Lip Sync Store
 * 
 * Zustand store for managing Lip Sync state.
 */

import { create } from 'zustand';
import {
  LipSyncModel,
  LipSyncStatus,
  LipSyncRequest,
  LipSyncStatusResponse,
  LipSyncOptions,
  DEFAULT_LIP_SYNC_OPTIONS
} from '../types/lipSync';
import { lipSyncService } from '../services/lipSyncService';

// Use actual string values for comparison
const LIP_SYNC_STATUS_COMPLETED = 'completed';
const LIP_SYNC_STATUS_FAILED = 'failed';

interface LipSyncState {
  // Current job
  currentJob: LipSyncStatusResponse | null;

  // Selected assets
  characterFaceImage: string | null;
  audioFile: string | null;

  // Options
  options: LipSyncOptions;

  // Status
  isGenerating: boolean;
  progress: number;
  error: string | null;

  // Jobs list
  jobs: LipSyncStatusResponse[];

  // Actions
  setCharacterFaceImage: (image: string | null) => void;
  setAudioFile: (audio: string | null) => void;
  setOptions: (options: Partial<LipSyncOptions>) => void;
  generateLipSync: (projectId: string) => Promise<void>;
  checkStatus: (jobId: string) => Promise<void>;
  loadJobs: (projectId?: string) => Promise<void>;
  clearError: () => void;
  reset: () => void;
}

const initialState = {
  currentJob: null,
  characterFaceImage: null,
  audioFile: null,
  options: DEFAULT_LIP_SYNC_OPTIONS,
  isGenerating: false,
  progress: 0,
  error: null,
  jobs: [],
};

export const useLipSyncStore = create<LipSyncState>((set, get) => ({
  ...initialState,

  setCharacterFaceImage: (image) => {
    set({ characterFaceImage: image });
  },

  setAudioFile: (audio) => {
    set({ audioFile: audio });
  },

  setOptions: (newOptions) => {
    set((state) => ({
      options: { ...state.options, ...newOptions }
    }));
  },

  generateLipSync: async (projectId) => {
    const { characterFaceImage, audioFile, options } = get();

    if (!characterFaceImage) {
      set({ error: 'Please select a character face image' });
      return;
    }

    if (!audioFile) {
      set({ error: 'Please select an audio file' });
      return;
    }

    set({ isGenerating: true, progress: 0, error: null });

    try {
      const request: LipSyncRequest = {
        projectId,
        characterFaceImage,
        audioFile,
        model: options.model,
        enhancer: options.enhancer,
        pads: options.pads,
        nosmooth: options.nosmooth,
        style: options.style,
      };

      const response = await lipSyncService.generateLipSync(request);

      set({
        currentJob: {
          job_id: response.job_id,
          status: response.status as LipSyncStatus,
          progress: response.progress,
          created_at: Date.now(),
        },
        isGenerating: true,
        progress: 0,
      });

      // Poll for completion
      await lipSyncService.waitForCompletion(
        response.job_id,
        (status) => {
          set({
            currentJob: status,
            progress: status.progress,
            isGenerating: status.status !== LIP_SYNC_STATUS_COMPLETED && status.status !== LIP_SYNC_STATUS_FAILED,
          });
        },
        120,
        2000
      );

      // Refresh jobs list
      get().loadJobs(projectId);

    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Lip sync generation failed',
        isGenerating: false,
      });
    }
  },

  checkStatus: async (jobId) => {
    try {
      const status = await lipSyncService.checkStatus(jobId);
      set({ currentJob: status, progress: status.progress });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : 'Failed to check status'
      });
    }
  },

  loadJobs: async (projectId) => {
    try {
      const jobs = await lipSyncService.listJobs(projectId);
      set({ jobs });
    } catch (error) {
      console.error('Failed to load jobs:', error);
    }
  },

  clearError: () => {
    set({ error: null });
  },

  reset: () => {
    set(initialState);
  },
}));

/**
 * Location Store
 * 
 * Zustand store for managing location state with CRUD operations,
 * cube texture management, and scene placement functions.
 * Now connects to backend API for persistent storage.
 * 
 * File: creative-studio-ui/src/stores/locationStore.ts
 */

import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';
import type {
  Location,
  CubeFace,
  LocationType,
  CubeTextureMapping,
  CubeFaceTexture,
  PlacedAsset,
  Transform3D,
  SceneLocation
} from '@/types/location';
import { listLocationsInProject, loadLocationFromProject } from '@/utils/locationStorage';
import { API_BASE_URL } from '../config/apiConfig';

// ============================================================================
// API Configuration
// ============================================================================

// API_BASE_URL is now imported from central config

/**
 * Fetch wrapper with error handling
 */
async function fetchApi<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const url = `${API_BASE_URL}${endpoint}`;

  try {
    const response = await fetch(url, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options?.headers,
      },
    });

    if (!response.ok) {
      throw new Error(`API error: ${response.status} ${response.statusText}`);
    }

    return response.json();
  } catch (error) {
    // Don't log error in offline mode (Electron without backend)
    // This is expected behavior
    throw error;
  }
}

// ============================================================================
// Types
// ============================================================================

/**
 * Location store state interface
 */
interface LocationState {
  // Data
  locations: Location[];
  sceneLocations: SceneLocation[];
  projectLocationIds: string[];

  // UI State
  selectedLocationId: string | null;
  editingLocationId: string | null;
  selectedSceneLocationId: string | null;

  // Editor state
  cubeViewRotation: { x: number; y: number };
  selectedCubeFace: CubeFace | null;
  textureDirection: 'inward' | 'outward';

  // Filters
  filterType: LocationType | 'all';
  filterWorld: string | 'all';
  searchQuery: string;

  // Loading states
  isLoading: boolean;
  isSaving: boolean;
  generationProgress: Map<string, number>;

  // Error state
  error: string | null;

  // Actions - Locations CRUD
  setLocations: (locations: Location[]) => void;
  fetchLocations: () => Promise<void>;
  fetchProjectLocations: (projectId: string) => Promise<void>;
  mergeProjectLocations: (projectId: string) => Promise<void>;
  addLocation: (location: Location) => Promise<void>;
  updateLocation: (id: string, updates: Partial<Location>) => Promise<void>;
  deleteLocation: (id: string) => Promise<void>;

  // Selection
  selectLocation: (id: string | null) => void;
  openEditor: (id: string) => void;
  closeEditor: () => void;

  // Cube editing
  setCubeViewRotation: (rotation: { x: number; y: number }) => void;
  selectCubeFace: (face: CubeFace | null) => void;
  setTextureDirection: (direction: 'inward' | 'outward') => void;
  updateCubeTexture: (locationId: string, face: CubeFace, texture: CubeFaceTexture) => Promise<void>;
  removeCubeTexture: (locationId: string, face: CubeFace) => Promise<void>;

  // Filters
  setFilterType: (type: LocationType | 'all') => void;
  setFilterWorld: (worldId: string | 'all') => void;
  setSearchQuery: (query: string) => void;

  // Progress
  setGenerationProgress: (faceId: string, progress: number) => void;
  setLoading: (loading: boolean) => void;
  setSaving: (saving: boolean) => void;
  setError: (error: string | null) => void;

  // Scene placement
  addSceneLocation: (sceneLocation: SceneLocation) => void;
  updateSceneLocation: (instanceId: string, updates: Partial<SceneLocation>) => void;
  removeSceneLocation: (instanceId: string) => void;
  selectSceneLocation: (instanceId: string | null) => void;
  updateSceneLocationTransform: (instanceId: string, transform: Partial<Transform3D>) => void;

  // Assets
  addPlacedAsset: (locationId: string, asset: PlacedAsset) => void;
  updatePlacedAsset: (locationId: string, assetId: string, updates: Partial<PlacedAsset>) => void;
  removePlacedAsset: (locationId: string, assetId: string) => void;
}

// ============================================================================
// Store Implementation
// ============================================================================

export const useLocationStore = create<LocationState>()(
  devtools(
    persist(
      (set, get) => ({
        // Initial state
        locations: [],
        sceneLocations: [],
        projectLocationIds: [],
        selectedLocationId: null,
        editingLocationId: null,
        selectedSceneLocationId: null,
        cubeViewRotation: { x: 0, y: 0 },
        selectedCubeFace: null,
        textureDirection: 'outward',
        filterType: 'all',
        filterWorld: 'all',
        searchQuery: '',
        isLoading: false,
        isSaving: false,
        generationProgress: new Map(),
        error: null,

        // Actions - Locations CRUD
        setLocations: (locations) => set({ locations }),

        fetchLocations: async () => {
          set({ isLoading: true, error: null });
          try {
            // Try to fetch from API, but don't fail if offline (Electron mode)
            const response = await fetchApi<{ locations: Location[] }>('/api/locations');
            set({ locations: response.locations });
          } catch (error) {
            // Handle 404 Not Found gracefully - it just means no locations exist yet
            if (error instanceof Error && error.message.includes('404')) {
              console.warn('No locations found on server, using local locations');
              set({ locations: [] });
            } else {
              // In Electron mode without backend, just use existing locations from store
              console.warn('API not available, using local locations:', error);
              // Don't set error in offline mode - just silently use local data
            }
            set({ error: null });
          } finally {
            set({ isLoading: false });
          }
        },

        fetchProjectLocations: async (projectId: string) => {
          set({ isLoading: true, error: null });
          try {
            // List all location files in the project's locations folder
            const locationIds = await listLocationsInProject(projectId);
            set({ projectLocationIds: locationIds });

            // Load each location
            const projectLocations: Location[] = [];
            for (const locationId of locationIds) {
              const location = await loadLocationFromProject(projectId, locationId);
              if (location) {
                projectLocations.push(location);
              }
            }

            // Merge with existing locations, avoiding duplicates by location_id
            set((state) => {
              const existingIds = new Set(state.locations.map(l => l.location_id));
              const newLocations = [...state.locations];

              for (const location of projectLocations) {
                if (!existingIds.has(location.location_id)) {
                  newLocations.push(location);
                }
              }

              return { locations: newLocations };
            });
          } catch (error) {
            console.warn('Failed to fetch project locations:', error);
            set({ error: null });
          } finally {
            set({ isLoading: false });
          }
        },

        mergeProjectLocations: async (projectId: string) => {
          await get().fetchProjectLocations(projectId);
        },

        addLocation: async (location) => {
          set({ isSaving: true, error: null });
          try {
            // Try API first, fallback to local storage in offline mode
            try {
              const response = await fetchApi<{ location: Location }>('/api/locations', {
                method: 'POST',
                body: JSON.stringify({
                  name: location.name,
                  location_type: location.location_type,
                  description: location.metadata?.description,
                  atmosphere: location.metadata?.atmosphere,
                  genre_tags: location.metadata?.genre_tags,
                  world_id: location.world_id,
                  world_location_id: location.world_location_id,
                  prompts: location.prompts,
                }),
              });
              set((state) => ({
                locations: [...state.locations, response.location],
              }));
            } catch (apiError) {
              // Offline mode - add locally
              console.warn('API not available, adding location locally');
              set((state) => ({
                locations: [...state.locations, location],
              }));
            }
          } catch (error) {
            set({ error: 'Failed to create location' });
            console.error('Failed to create location:', error);
            throw error;
          } finally {
            set({ isSaving: false });
          }
        },

        updateLocation: async (id, updates) => {
          set({ isSaving: true, error: null });
          try {
            // Try API first, fallback to local update in offline mode
            try {
              const response = await fetchApi<{ location: Location }>(`/api/locations/${id}`, {
                method: 'PUT',
                body: JSON.stringify(updates),
              });
              set((state) => ({
                locations: state.locations.map((loc) =>
                  loc.location_id === id ? response.location : loc
                ),
              }));
            } catch (apiError) {
              // Offline mode - update locally
              console.warn('API not available, updating location locally');
              set((state) => ({
                locations: state.locations.map((loc) =>
                  loc.location_id === id ? { ...loc, ...updates } : loc
                ),
              }));
            }
          } catch (error) {
            set({ error: 'Failed to update location' });
            console.error('Failed to update location:', error);
            throw error;
          } finally {
            set({ isSaving: false });
          }
        },

        deleteLocation: async (id) => {
          set({ isSaving: true, error: null });
          try {
            // Try API first, fallback to local delete in offline mode
            try {
              await fetchApi(`/api/locations/${id}`, {
                method: 'DELETE',
              });
            } catch (apiError) {
              // Offline mode - delete locally
              console.warn('API not available, deleting location locally');
            }
            // Always update local state
            set((state) => ({
              locations: state.locations.filter((loc) => loc.location_id !== id),
              selectedLocationId: state.selectedLocationId === id ? null : state.selectedLocationId,
              editingLocationId: state.editingLocationId === id ? null : state.editingLocationId,
            }));
          } catch (error) {
            set({ error: 'Failed to delete location' });
            console.error('Failed to delete location:', error);
            throw error;
          } finally {
            set({ isSaving: false });
          }
        },

        // Selection
        selectLocation: (id) => set({ selectedLocationId: id }),
        openEditor: (id) => set({ editingLocationId: id }),
        closeEditor: () => set({ editingLocationId: null, selectedCubeFace: null }),

        // Cube editing
        setCubeViewRotation: (rotation) => set({ cubeViewRotation: rotation }),
        selectCubeFace: (face) => set({ selectedCubeFace: face }),
        setTextureDirection: (direction) => set({ textureDirection: direction }),

        updateCubeTexture: async (locationId, face, texture) => {
          set({ isSaving: true, error: null });
          try {
            const response = await fetchApi<{ location: Location }>(`/api/locations/${locationId}/cube-textures`, {
              method: 'POST',
              body: JSON.stringify({
                face,
                prompt: texture.generation_params?.prompt,
                negative_prompt: texture.generation_params?.negative_prompt,
                width: texture.generation_params?.width || 512,
                height: texture.generation_params?.height || 512,
                steps: texture.generation_params?.steps || 20,
                cfg_scale: texture.generation_params?.cfg_scale || 7,
                seed: texture.generation_params?.seed,
              }),
            });
            set((state) => ({
              locations: state.locations.map((loc) =>
                loc.location_id === locationId ? response.location : loc
              ),
            }));
          } catch (error) {
            set({ error: 'Failed to update cube texture' });
            console.error('Failed to update cube texture:', error);
            throw error;
          } finally {
            set({ isSaving: false });
          }
        },

        removeCubeTexture: async (locationId, face) => {
          set({ isSaving: true, error: null });
          try {
            const location = get().locations.find((loc) => loc.location_id === locationId);
            if (location) {
              const { [face]: _, ...remainingTextures } = location.cube_textures;
              await get().updateLocation(locationId, { cube_textures: remainingTextures });
            }
          } catch (error) {
            set({ error: 'Failed to remove cube texture' });
            console.error('Failed to remove cube texture:', error);
            throw error;
          } finally {
            set({ isSaving: false });
          }
        },

        // Filters
        setFilterType: (type) => set({ filterType: type }),
        setFilterWorld: (worldId) => set({ filterWorld: worldId }),
        setSearchQuery: (query) => set({ searchQuery: query }),

        // Progress
        setGenerationProgress: (faceId, progress) => set((state) => {
          const newProgress = new Map(state.generationProgress);
          newProgress.set(faceId, progress);
          return { generationProgress: newProgress };
        }),

        setLoading: (loading) => set({ isLoading: loading }),
        setSaving: (saving) => set({ isSaving: saving }),
        setError: (error) => set({ error }),

        // Scene placement
        addSceneLocation: (sceneLocation) => set((state) => ({
          sceneLocations: [...state.sceneLocations, sceneLocation],
        })),

        updateSceneLocation: (instanceId, updates) => set((state) => ({
          sceneLocations: state.sceneLocations.map((sl) =>
            sl.instance_id === instanceId ? { ...sl, ...updates } : sl
          ),
        })),

        removeSceneLocation: (instanceId) => set((state) => ({
          sceneLocations: state.sceneLocations.filter((sl) => sl.instance_id !== instanceId),
          selectedSceneLocationId: state.selectedSceneLocationId === instanceId ? null : state.selectedSceneLocationId,
        })),

        selectSceneLocation: (instanceId) => set({ selectedSceneLocationId: instanceId }),

        updateSceneLocationTransform: (instanceId, transform) => set((state) => ({
          sceneLocations: state.sceneLocations.map((sl) =>
            sl.instance_id === instanceId
              ? { ...sl, transform: { ...sl.transform, ...transform } }
              : sl
          ),
        })),

        // Assets
        addPlacedAsset: (locationId, asset) => set((state) => ({
          locations: state.locations.map((loc) => {
            if (loc.location_id !== locationId) return loc;
            return {
              ...loc,
              placed_assets: [...loc.placed_assets, asset],
            };
          }),
        })),

        updatePlacedAsset: (locationId, assetId, updates) => set((state) => ({
          locations: state.locations.map((loc) => {
            if (loc.location_id !== locationId) return loc;
            return {
              ...loc,
              placed_assets: loc.placed_assets.map((asset) =>
                asset.id === assetId ? { ...asset, ...updates } : asset
              ),
            };
          }),
        })),

        removePlacedAsset: (locationId, assetId) => set((state) => ({
          locations: state.locations.map((loc) => {
            if (loc.location_id !== locationId) return loc;
            return {
              ...loc,
              placed_assets: loc.placed_assets.filter((asset) => asset.id !== assetId),
            };
          }),
        })),
      }),
      {
        name: 'location-store',
        partialize: (state) => ({
          filterType: state.filterType,
          filterWorld: state.filterWorld,
          searchQuery: state.searchQuery,
        }),
      }
    ),
    { name: 'LocationStore' }
  )
);

// ============================================================================
// Selector Functions
// ============================================================================

/**
 * Get filtered locations based on current filters
 */
export function getFilteredLocations(state: LocationState): Location[] {
  let filtered = [...state.locations];

  // Filter by type
  if (state.filterType !== 'all') {
    filtered = filtered.filter((loc) => loc.location_type === state.filterType);
  }

  // Filter by world
  if (state.filterWorld !== 'all') {
    filtered = filtered.filter((loc) => loc.world_id === state.filterWorld);
  }

  // Filter by search query
  if (state.searchQuery) {
    const query = state.searchQuery.toLowerCase();
    filtered = filtered.filter((loc) =>
      loc.name.toLowerCase().includes(query) ||
      loc.metadata?.description?.toLowerCase().includes(query) ||
      loc.metadata?.genre_tags?.some((tag) => tag.toLowerCase().includes(query))
    );
  }

  return filtered;
}

/**
 * Get selected location
 */
export function getSelectedLocation(state: LocationState): Location | undefined {
  return state.locations.find((loc) => loc.location_id === state.selectedLocationId);
}

/**
 * Get editing location
 */
export function getEditingLocation(state: LocationState): Location | undefined {
  return state.locations.find((loc) => loc.location_id === state.editingLocationId);
}

/**
 * Get scene location by instance ID
 */
export function getSceneLocationById(state: LocationState, instanceId: string): SceneLocation | undefined {
  return state.sceneLocations.find((sl) => sl.instance_id === instanceId);
}

/**
 * Get locations by world ID
 */
export function getLocationsByWorldId(state: LocationState, worldId: string): Location[] {
  return state.locations.filter((loc) => loc.world_id === worldId);
}

/**
 * Get scene locations for a specific shot
 */
export function getSceneLocationsByShotId(state: LocationState, shotId: string): SceneLocation[] {
  return state.sceneLocations.filter((sl) => sl.parent_shot_id === shotId);
}

/**
 * Check if a location has all cube faces generated
 */
export function isLocationFullyTextured(location: Location): boolean {
  const requiredFaces: CubeFace[] = ['front', 'back', 'left', 'right', 'top', 'bottom'];
  return requiredFaces.every((face) => location.cube_textures[face]?.image_path);
}

/**
 * Get completion percentage for a location's cube textures
 */
export function getLocationCompletionPercentage(location: Location): number {
  const requiredFaces: CubeFace[] = ['front', 'back', 'left', 'right', 'top', 'bottom'];
  const completedFaces = requiredFaces.filter((face) => location.cube_textures[face]?.image_path);
  return Math.round((completedFaces.length / requiredFaces.length) * 100);
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

export type MemoryCategory =
    | 'CREATIVE_STYLE'
    | 'CHARACTER_INSIGHT'
    | 'PRODUCTION_RULE'
    | 'PROJECT_LORE'
    | 'TECHNICAL_CONSTRAINT'
    | 'USER_PREFERENCE';

export interface MemoryInsight {
    id: string;
    text: string;
    category: MemoryCategory;
    timestamp: number;
    confidence: number; // 0-1
    isPermanent: boolean;
    source?: string; // e.g., 'directorial_advice', 'user_chat'
}

interface MemoryState {
    insights: MemoryInsight[];
    workingContext: string; // The "Counter" - condensed persistent personality/rules

    // Actions
    addInsight: (insight: Omit<MemoryInsight, 'id' | 'timestamp'>) => void;
    promoteInsight: (id: string) => void;
    removeInsight: (id: string) => void;
    updateWorkingContext: (text: string) => void;
    summarizeLogs: () => Promise<void>;
    clearMemory: () => void;
}

/**
 * Project Memory Store
 * 
 * Implements a "Total Recall" inspired tiered memory system:
 * 1. Log: All new insights land here (addInsight).
 * 2. Registers: Promoted insights become permanent anchors.
 * 3. Working Context: A distilled summary of active rules.
 */
export const useMemoryStore = create<MemoryState>()(
    persist(
        (set, get) => ({
            insights: [],
            workingContext: "Standard StoryCore production protocols active.",

            addInsight: (insight) => {
                const newInsight: MemoryInsight = {
                    ...insight,
                    id: crypto.randomUUID(),
                    timestamp: Date.now(),
                };
                set((state) => ({
                    insights: [newInsight, ...state.insights]
                }));
            },

            promoteInsight: (id) => {
                set((state) => ({
                    insights: state.insights.map(i =>
                        i.id === id ? { ...i, isPermanent: true, confidence: 1.0 } : i
                    )
                }));
            },

            removeInsight: (id) => {
                set((state) => ({
                    insights: state.insights.filter(i => i.id !== id)
                }));
            },

            updateWorkingContext: (text) => set({ workingContext: text }),

            summarizeLogs: async () => {
                // Logic to be implemented in a service: taking permanent insights
                // and recent high-confidence logs to rebuild workingContext.
            },

            clearMemory: () => set({ insights: [], workingContext: '' })
        }),
        {
            name: 'storycore-project-memory',
            storage: createJSONStorage(() => localStorage),
        }
    )
);

import { create } from 'zustand';
import { devtools } from 'zustand/middleware';
import { StoryObject } from '@/types/object';
import { listObjectsInProject, loadObjectFromProject, saveObjectToProject, deleteObjectFromProject } from '@/utils/objectStorage';

interface ObjectState {
    objects: StoryObject[];
    isLoading: boolean;
    error: string | null;

    // Actions
    fetchProjectObjects: (projectId: string) => Promise<void>;
    addObject: (projectId: string, object: StoryObject) => Promise<void>;
    updateObject: (projectId: string, object: StoryObject) => Promise<void>;
    removeObject: (projectId: string, objectId: string) => Promise<void>;
}

export const useObjectStore = create<ObjectState>()(
    devtools(
        (set, get) => ({
            objects: [],
            isLoading: false,
            error: null,

            fetchProjectObjects: async (projectId) => {
                set({ isLoading: true, error: null });
                try {
                    const objectIds = await listObjectsInProject(projectId);
                    const loadedObjects: StoryObject[] = [];

                    for (const id of objectIds) {
                        const obj = await loadObjectFromProject(projectId, id);
                        if (obj) loadedObjects.push(obj);
                    }

                    set({ objects: loadedObjects, isLoading: false });
                } catch (error) {
                    console.error('Failed to fetch project objects:', error);
                    set({ error: 'Failed to load objects', isLoading: false });
                }
            },

            addObject: async (projectId, object) => {
                try {
                    await saveObjectToProject(projectId, object.id, object);
                    set((state) => ({
                        objects: [...state.objects, object]
                    }));
                } catch (error) {
                    console.error('Failed to add object:', error);
                    throw error;
                }
            },

            updateObject: async (projectId, object) => {
                try {
                    await saveObjectToProject(projectId, object.id, object);
                    set((state) => ({
                        objects: state.objects.map(obj => obj.id === object.id ? object : obj)
                    }));
                } catch (error) {
                    console.error('Failed to update object:', error);
                    throw error;
                }
            },

            removeObject: async (projectId, objectId) => {
                try {
                    await deleteObjectFromProject(projectId, objectId);
                    set((state) => ({
                        objects: state.objects.filter(obj => obj.id !== objectId)
                    }));
                } catch (error) {
                    console.error('Failed to remove object:', error);
                    throw error;
                }
            },
        }),
        { name: 'ObjectStore' }
    )
);

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

export interface ManifestedAsset {
    id: string;
    characterId?: string;
    locationId?: string;
    objectId?: string;
    characterName?: string;
    generatedAt: string;
    type: 'CHARACTER_REFERENCE_SHEET' | 'LOCATION_REFERENCE_SHEET' | 'OBJECT_REFERENCE_SHEET' | 'GLOBAL_STYLE_GUIDE';
    url: string;
    metadata?: Record<string, any>;
}

export interface DirectorialAdvice {
    id: string;
    text: string;
    timestamp: string;
    context: string;
}

interface ProductionState {
    manifestedAssets: ManifestedAsset[];
    adviceHistory: DirectorialAdvice[];
    lastTrajectory: any[]; // RLM Trajectory
    lastSyncTimestamp: number | null;

    // Actions
    addManifestedAsset: (asset: ManifestedAsset) => void;
    removeManifestedAsset: (id: string) => void;
    addAdvice: (text: string, context: string) => void;
    setLastTrajectory: (trajectory: any[]) => void;
    clearSession: () => void;
}

/**
 * Production Store
 * 
 * Manages the "Neural Production Ledger" and directorial intelligence history.
 * Persists manifested assets across sessions via localStorage.
 */
export const useProductionStore = create<ProductionState>()(
    persist(
        (set) => ({
            manifestedAssets: [],
            adviceHistory: [],
            lastTrajectory: [],
            lastSyncTimestamp: null,

            addManifestedAsset: (asset) =>
                set((state) => ({
                    manifestedAssets: [asset, ...state.manifestedAssets],
                    lastSyncTimestamp: Date.now()
                })),

            removeManifestedAsset: (id) =>
                set((state) => ({
                    manifestedAssets: state.manifestedAssets.filter(a => a.id !== id),
                    lastSyncTimestamp: Date.now()
                })),

            addAdvice: (text, context) =>
                set((state) => ({
                    adviceHistory: [
                        {
                            id: crypto.randomUUID(),
                            text,
                            context,
                            timestamp: new Date().toISOString()
                        },
                        ...state.adviceHistory
                    ].slice(0, 50) // Keep last 50 advice items
                })),

            setLastTrajectory: (trajectory) =>
                set({ lastTrajectory: trajectory }),

            clearSession: () =>
                set({
                    manifestedAssets: [],
                    adviceHistory: [],
                    lastTrajectory: [],
                    lastSyncTimestamp: null
                }),
        }),
        {
            name: 'storycore-production-ledger',
            storage: createJSONStorage(() => localStorage),
        }
    )
);

/**
