  isDetailViewOpen: boolean;
  isUploadModalOpen: boolean;
  
  // Actions
  // Search and browse
  searchTemplates: (params: Partial<MarketplaceSearchParams>) => void;
  loadMoreTemplates: () => void;
  refreshMarketplace: () => void;
  
  // Templates
