  loadTemplateDetails: (id: string) => void;
  downloadTemplate: (id: string) => void;
  purchaseTemplate: (id: string) => void;
  favoriteTemplate: (id: string) => void;
  unfavoriteTemplate: (id: string) => void;
  
  // Collections
