const defaultSearchParams: MarketplaceSearchParams = {
  query: '',
  categories: [],
  platforms: [],
  aspectRatios: [],
  resolutions: [],
  price: 'all',
  sortBy: 'popular',
  page: 1,
  limit: 24,
};

export const useTemplateMarketplaceStore = create<TemplateMarketplaceStore>()(
  subscribeWithSelector((set, get) => ({
    // Initial state
    marketplace: {
      templates: [],
      collections: [],
      featuredTemplates: [],
      searchParams: { ...defaultSearchParams },
      isLoading: false,
      error: null,
      hasMore: true,
      totalCount: 0,
    },
    
    userLibrary: {
      purchasedTemplates: [],
      downloadedTemplates: [],
      favorites: [],
      collections: [],
      uploadHistory: [],
    },
    
    selectedTemplateId: null,
    selectedCollectionId: null,
    isPanelOpen: false,
    isDetailViewOpen: false,
    isUploadModalOpen: false,
    
    // Search and browse
    searchTemplates: (params) => set((state) => ({
      marketplace: {
        ...state.marketplace,
        searchParams: { ...state.marketplace.searchParams, ...params, page: 1 },
        isLoading: true,
      },
    })),
    
    loadMoreTemplates: () => set((state) => ({
      marketplace: {
        ...state.marketplace,
        searchParams: {
          ...state.marketplace.searchParams,
