    purchaseTemplate: (id) => {
      const { userLibrary } = get();
      if (!userLibrary.purchasedTemplates.includes(id)) {
        set({
          userLibrary: {
            ...userLibrary,
            purchasedTemplates: [...userLibrary.purchasedTemplates, id],
          },
        });
      }
