    favoriteTemplate: (id) => {
      const { userLibrary } = get();
      if (!userLibrary.favorites.includes(id)) {
        set({
          userLibrary: {
            ...userLibrary,
            favorites: [...userLibrary.favorites, id],
          },
        });
      }
