  setProject: (project) => set({ project }),
  setShots: (shots) => set({ shots }),
  addShot: (shot) => set((state) => ({ shots: [...state.shots, shot] })),
  updateShot: (id, updates) =>
    set((state) => ({
      shots: state.shots.map((shot) => (shot.id === id ? { ...shot, ...updates } : shot)),
    })),
  deleteShot: (id) =>
    set((state) => ({
      shots: state.shots.filter((shot) => shot.id !== id),
      selectedShotId: state.selectedShotId === id ? null : state.selectedShotId,
    })),
  setSelectedShotId: (id) => set({ selectedShotId: id }),
  setCurrentTime: (time) => set({ currentTime: time }),
  setShowChat: (show) => set({ showChat: show }),
  setShowTaskQueue: (show) => set({ showTaskQueue: show }),
  setPanelSizes: (sizes) => set({ panelSizes: sizes }),
  setChatPanelPosition: (position) => set({ chatPanelPosition: position }),
  setChatPanelSize: (size) => set({ chatPanelSize: size }),
  setChatPanelMinimized: (minimized) => set({ chatPanelMinimized: minimized }),
  setIsPlaying: (playing) => set({ isPlaying: playing }),
  setPlaybackSpeed: (speed) => set({ playbackSpeed: speed }),
  addAsset: (asset) => set((state) => ({ assets: [...state.assets, asset] })),
  addTask: (task) => set((state) => ({ taskQueue: [...state.taskQueue, task] })),
  removeTask: (taskId) =>
    set((state) => ({
      taskQueue: state.taskQueue.filter((task) => task.id !== taskId),
    })),
  reorderTasks: (tasks) => set({ taskQueue: tasks }),
  addChatMessage: (message) =>
    set((state) => ({ chatMessages: [...state.chatMessages, message] })),
  clearChatMessages: () => set({ chatMessages: [] }),
  setShowInstallationWizard: (show) => set({ showInstallationWizard: show }),
  setInstallationComplete: (complete) => set({ installationComplete: complete }),
  setShowWorldWizard: (show) => set({ showWorldWizard: show }),
  setShowCharacterWizard: (show) => {
    logger.debug('[useAppStore] setShowCharacterWizard called with:', show);
    set({ showCharacterWizard: show });
  },
  setShowProjectSetupWizard: (show) => set({ showProjectSetupWizard: show }),
  setShowCreateProjectDialog: (show) => set({ showCreateProjectDialog: show }),
  setShowStorytellerWizard: (show) => {
    logger.debug('[useAppStore] setShowStorytellerWizard called with:', show);
    set({ showStorytellerWizard: show });
  },
  setShowLLMSettings: (show) => set({ showLLMSettings: show }),
  setShowComfyUISettings: (show) => set({ showComfyUISettings: show }),
  setShowGeneralSettings: (show) => set({ showGeneralSettings: show }),
  setShowAddonsModal: (show) => set({ showAddonsModal: show }),
  setShowCharactersModal: (show) => set({ showCharactersModal: show }),
  setShowWorldModal: (show) => set({ showWorldModal: show }),
  setShowLocationsModal: (show) => set({ showLocationsModal: show }),
  setShowObjectsModal: (show) => set({ showObjectsModal: show }),
  setShowObjectWizard: (show) => {
    logger.debug('[useAppStore] setShowObjectWizard called with:', show);
    set({ showObjectWizard: show });
  },
  setShowImageGalleryModal: (show) => set({ showImageGalleryModal: show }),
  setShowFactCheckModal: (show) => set({ showFactCheckModal: show }),
  setShowAboutModal: (show) => set({ showAboutModal: show }),
  setShowDialogueEditor: (show) => set({ showDialogueEditor: show }),
  setShowFeedbackPanel: (show) => set({ showFeedbackPanel: show }),
  setShowPendingReportsList: (show) => set({ showPendingReportsList: show }),
  openSequencePlanWizard: (context) => {
    set({
      showSequencePlanWizard: true,
      sequencePlanWizardContext: context || { mode: 'create' },
    });
  },
  closeSequencePlanWizard: () =>
    set({
      showSequencePlanWizard: false,
      sequencePlanWizardContext: null,
    }),
  openShotWizard: (context) =>
    set({
      showShotWizard: true,
      shotWizardContext: context || { mode: 'create' },
    }),
  closeShotWizard: () =>
    set({
      showShotWizard: false,
      shotWizardContext: null,
    }),

  // Generic wizard form actions (simple forms in GenericWizardModal)
  setShowDialogueWriter: (show) => set({ showDialogueWriter: show }),
  setShowSceneGenerator: (show) => set({ showSceneGenerator: show }),
  setShowStoryboardCreator: (show) => set({ showStoryboardCreator: show }),
  setShowStyleTransfer: (show) => set({ showStyleTransfer: show }),

  // Open wizard with mutual exclusion (Requirement 3.4)
  openWizard: (wizardType) =>
    set({
      // Close ALL wizards first (mutual exclusion) - including multi-step wizards
      showWorldWizard: false,
      showCharacterWizard: false,
      showProjectSetupWizard: false,
      showStorytellerWizard: false,
      showDialogueWriter: false,
      showSceneGenerator: false,
      showStoryboardCreator: false,
      showStyleTransfer: false,
      showAboutModal: false,
      // Set active wizard type
      activeWizardType: wizardType,
      // Open the requested wizard
      ...(wizardType === 'dialogue-writer' && { showDialogueWriter: true }),
      ...(wizardType === 'scene-generator' && { showSceneGenerator: true }),
      ...(wizardType === 'storyboard-creator' && { showStoryboardCreator: true }),
      ...(wizardType === 'style-transfer' && { showStyleTransfer: true }),
    }),

  // Close active wizard (Requirement 3.3)
  closeActiveWizard: () =>
    set({
      showWorldWizard: false,
      showCharacterWizard: false,
      showProjectSetupWizard: false,
      showStorytellerWizard: false,
      showDialogueWriter: false,
      showSceneGenerator: false,
      showStoryboardCreator: false,
      showStyleTransfer: false,
      activeWizardType: null,
    }),

  // Character integration system actions
  // Requirements: 4.2, 9.2, 9.4
  setSelectedCharacterIds: (ids) => set({ selectedCharacterIds: ids }),
  setCharacterSearchQuery: (query) => set({ characterSearchQuery: query }),
  setCharacterFilters: (filters) => set({ characterFilters: filters }),
  openCharacterEditor: (characterId) =>
    set({
      isCharacterEditorOpen: true,
      editingCharacterId: characterId,
    }),
  closeCharacterEditor: () =>
    set({
      isCharacterEditorOpen: false,
      editingCharacterId: null,
    }),
  setOllamaStatus: (status) => set({ ollamaStatus: status }),
  setComfyUIStatus: (status) => set({ comfyuiStatus: status }),

  // Reference sheet actions (Continuous Creation feature)
  setMasterReferenceSheet: (sheet) => set({ masterReferenceSheet: sheet }),
  addSequenceReferenceSheet: (sheet) =>
    set((state) => ({
      sequenceReferenceSheets: [...state.sequenceReferenceSheets, sheet],
    })),
  updateSequenceReferenceSheet: (id, updates) =>
    set((state) => ({
      sequenceReferenceSheets: state.sequenceReferenceSheets.map((s) =>
        s.id === id ? { ...s, ...updates } : s
      ),
    })),
  removeSequenceReferenceSheet: (id) =>
    set((state) => ({
      sequenceReferenceSheets: state.sequenceReferenceSheets.filter((s) => s.id !== id),
      activeSequenceSheetId: state.activeSequenceSheetId === id ? null : state.activeSequenceSheetId,
    })),
  setActiveSequenceSheetId: (id) => set({ activeSequenceSheetId: id }),
  addShotReference: (reference) =>
    set((state) => ({
      shotReferences: { ...state.shotReferences, [reference.id]: reference },
    })),
  updateShotReference: (id, updates) =>
    set((state) => {
      const existing = state.shotReferences[id];
      if (!existing) return state;
      return {
        shotReferences: { ...state.shotReferences, [id]: { ...existing, ...updates } },
      };
    }),
  removeShotReference: (id) =>
    set((state) => {
      const { [id]: _, ...rest } = state.shotReferences;
      return { shotReferences: rest };
    }),

  // Continuous Creation dialog actions
  setShowReferenceSheetManager: (show) => set({ showReferenceSheetManager: show }),
  setShowVideoReplicationDialog: (show) => set({ showVideoReplicationDialog: show }),
  setShowCrossShotReferencePicker: (show) => set({ showCrossShotReferencePicker: show }),
  setShowProjectBranchingDialog: (show) => set({ showProjectBranchingDialog: show }),
  setShowEpisodeReferenceDialog: (show) => set({ showEpisodeReferenceDialog: show }),

  // Addon Settings
  openAddonSettings: (addonId) => set({ settingsAddonId: addonId }),
  closeAddonSettings: () => set({ settingsAddonId: null }),
}));

/**
 * @fileoverview Main application state store using Zustand
 * 
 * This file defines the global application state and actions for the Creative Studio UI.
 * It uses Zustand for state management with middleware for persistence and devtools.
 * 
 * @module stores/useStore
 * @requires zustand
 * @requires zustand/middleware
 */

import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';
import type {
  Shot,
  Asset,
  Project,
  GenerationTask,
  PanelSizes,
  AudioTrack,
  Effect,
  TextLayer,
  Animation,
  Transition
} from '@/types';

type ProjectSettings = Record<string, any>;

/**
 * Application state interface
 * 
 * Defines the complete state structure for the Creative Studio application.
 * Includes project data, UI state, playback state, and undo/redo history.
 */
interface AppState {
  // ============================================================================
  // Project Data
  // ============================================================================

  /**
   * Current project data
   * Null when no project is loaded
   */
  project: Project | null;

  /**
   * Array of all shots in the current project
   * Ordered by position property
   */
  shots: Shot[];

  /**
   * Array of all assets available in the project
   * Includes images, audio files, and templates
   */
  assets: Asset[];

  // ============================================================================
  // UI State
  // ============================================================================

  /**
   * ID of the currently selected shot
   * Null when no shot is selected
   */
  selectedShotId: string | null;

  /**
   * Current playhead position in seconds
   * Used for timeline scrubbing and preview
   */
  currentTime: number;

  /**
   * Whether the chat assistant panel is visible
   */
  showChat: boolean;

  /**
   * Whether the task queue modal is open
   */
  showTaskQueue: boolean;

  /**
   * Panel size configuration as percentages
   * Must sum to 100
   */
  panelSizes: PanelSizes;

  // ============================================================================
  // Task Queue
  // ============================================================================

  /**
   * Array of generation tasks to be processed by backend
   * Ordered by priority (lower number = higher priority)
   */
  taskQueue: GenerationTask[];

  // ============================================================================
  // Playback State
  // ============================================================================

  /**
   * Whether the timeline is currently playing
   */
  isPlaying: boolean;

  /**
   * Playback speed multiplier
   * 1.0 = normal speed, 0.5 = half speed, 2.0 = double speed
   */
  playbackSpeed: number;

  // ============================================================================
  // Undo/Redo State
  // ============================================================================

  /**
   * Array of historical states for undo functionality
   * Limited to 50 entries to prevent memory issues
   */
  history: AppState[];

  /**
   * Current position in history array
   * Used to track undo/redo position
   */
  historyIndex: number;

  // ============================================================================
  // Project Actions
  // ============================================================================

  /**
   * Creates a new project with default settings
   * 
   * @param name - Project name
   * @param settings - Optional project settings
   * @returns void
   * 
   * @example
   * ```typescript
   * createProject('My Video', { resolution: '1920x1080', frameRate: 30 });
   * ```
   */
  createProject: (name: string, settings?: ProjectSettings) => void;

  /**
   * Loads an existing project from JSON data
   * 
   * @param projectData - Project data conforming to Data Contract v1
   * @returns void
   * 
   * @example
   * ```typescript
   * const projectData = JSON.parse(jsonString);
   * loadProject(projectData);
   * ```
   */
  loadProject: (projectData: Project) => void;

  /**
   * Saves the current project
   * 
   * @returns Promise that resolves when save is complete
   * 
   * @example
   * ```typescript
   * await saveProject();
   * ```
   */
  saveProject: () => Promise<void>;

  /**
   * Exports the project in specified format
   * 
   * @param format - Export format ('json', 'pdf', or 'video')
   * @returns Promise resolving to Blob of exported data
   * 
   * @example
   * ```typescript
   * const blob = await exportProject('json');
   * const url = URL.createObjectURL(blob);
   * ```
   */
  exportProject: (format: 'json' | 'pdf' | 'video') => Promise<Blob>;

  // ============================================================================
  // Shot Actions
  // ============================================================================

  /**
   * Adds a new shot to the project
   * 
   * @param shot - Partial shot data (id and position will be auto-generated)
   * @returns ID of the newly created shot
   * 
   * @example
   * ```typescript
   * const shotId = addShot({
   *   title: 'Opening Scene',
   *   description: 'Sunrise over the city',
   *   duration: 5
   * });
   * ```
   */
  addShot: (shot: Partial<Shot>) => string;

  /**
   * Updates an existing shot with new data
   * 
   * @param shotId - ID of the shot to update
   * @param updates - Partial shot data to merge with existing
   * @returns void
   * 
   * @example
   * ```typescript
   * updateShot('shot-123', { title: 'New Title', duration: 8 });
   * ```
   */
  updateShot: (shotId: string, updates: Partial<Shot>) => void;

  /**
   * Deletes a shot from the project
   * 
   * Also removes the shot from timeline and updates positions of remaining shots
   * 
   * @param shotId - ID of the shot to delete
   * @returns void
   * 
   * @example
   * ```typescript
   * deleteShot('shot-123');
   * ```
   */
  deleteShot: (shotId: string) => void;

  /**
   * Reorders shots based on new array of IDs
   * 
   * @param shotIds - Array of shot IDs in desired order
   * @returns void
   * 
   * @example
   * ```typescript
   * reorderShots(['shot-2', 'shot-1', 'shot-3']);
   * ```
   */
  reorderShots: (shotIds: string[]) => void;

  /**
   * Selects a shot for editing
   * 
   * @param shotId - ID of shot to select, or null to deselect
   * @returns void
   * 
   * @example
   * ```typescript
   * selectShot('shot-123'); // Select shot
   * selectShot(null);       // Deselect all
   * ```
   */
  selectShot: (shotId: string | null) => void;

  // ============================================================================
  // Asset Actions
  // ============================================================================

  /**
   * Adds a new asset to the library
   * 
   * @param asset - Partial asset data (id will be auto-generated)
   * @returns ID of the newly created asset
   * 
   * @example
   * ```typescript
   * const assetId = addAsset({
   *   name: 'Background Music',
   *   type: 'audio',
   *   url: '/assets/music.mp3'
   * });
   * ```
   */
  addAsset: (asset: Partial<Asset>) => string;

  /**
   * Uploads an asset file and adds it to the library
   * 
   * @param file - File object to upload
   * @returns Promise resolving to asset ID
   * 
   * @example
   * ```typescript
   * const assetId = await uploadAsset(file);
   * ```
   */
  uploadAsset: (file: File) => Promise<string>;

  /**
   * Deletes an asset from the library
   * 
   * Warning: This does not remove the asset from shots that use it
   * 
   * @param assetId - ID of the asset to delete
   * @returns void
   * 
   * @example
   * ```typescript
   * deleteAsset('asset-456');
   * ```
   */
  deleteAsset: (assetId: string) => void;

  /**
   * Searches assets by name or metadata
   * 
   * @param query - Search query string
   * @returns Array of matching assets
   * 
   * @example
   * ```typescript
   * const results = searchAssets('music');
   * ```
   */
  searchAssets: (query: string) => Asset[];

  // ============================================================================
  // Audio Actions
  // ============================================================================

  /**
   * Adds an audio track to a shot
   * 
   * @param shotId - ID of the shot
   * @param track - Partial audio track data
   * @returns ID of the newly created audio track
   * 
   * @example
   * ```typescript
   * const trackId = addAudioTrack('shot-123', {
   *   name: 'Background Music',
   *   type: 'music',
   *   url: '/assets/music.mp3',
   *   volume: 80
   * });
   * ```
   */
  addAudioTrack: (shotId: string, track: Partial<AudioTrack>) => string;

  /**
   * Updates an audio track
   * 
   * @param shotId - ID of the shot containing the track
   * @param trackId - ID of the track to update
   * @param updates - Partial audio track data to merge
   * @returns void
   * 
   * @example
   * ```typescript
   * updateAudioTrack('shot-123', 'track-456', { volume: 90, pan: -20 });
   * ```
   */
  updateAudioTrack: (shotId: string, trackId: string, updates: Partial<AudioTrack>) => void;

  /**
   * Deletes an audio track from a shot
   * 
   * @param shotId - ID of the shot containing the track
   * @param trackId - ID of the track to delete
   * @returns void
   * 
   * @example
   * ```typescript
   * deleteAudioTrack('shot-123', 'track-456');
   * ```
   */
  deleteAudioTrack: (shotId: string, trackId: string) => void;

  // ============================================================================
  // UI Actions
  // ============================================================================

  /**
   * Toggles the chat assistant panel visibility
   * 
   * @returns void
   * 
   * @example
   * ```typescript
   * toggleChat(); // Opens chat if closed, closes if open
   * ```
   */
  toggleChat: () => void;

  /**
   * Toggles the task queue modal visibility
   * 
   * @returns void
   * 
   * @example
   * ```typescript
   * toggleTaskQueue();
   * ```
   */
  toggleTaskQueue: () => void;

  /**
   * Updates panel sizes
   * 
   * @param sizes - Partial panel sizes (percentages)
   * @returns void
   * 
   * @example
   * ```typescript
   * updatePanelSizes({ assetLibrary: 20, canvas: 60, propertiesOrChat: 20 });
   * ```
   */
  updatePanelSizes: (sizes: Partial<PanelSizes>) => void;

  /**
   * Sets the playback state
   * 
   * @param isPlaying - Whether timeline should be playing
   * @returns void
   * 
   * @example
   * ```typescript
   * setPlaying(true);  // Start playback
   * setPlaying(false); // Pause playback
   * ```
   */
  setPlaying: (isPlaying: boolean) => void;

  /**
   * Sets the current playhead time
   * 
   * @param time - Time in seconds
   * @returns void
   * 
   * @example
   * ```typescript
   * setCurrentTime(10.5); // Jump to 10.5 seconds
   * ```
   */
  setCurrentTime: (time: number) => void;

  // ============================================================================
  // Undo/Redo Actions
  // ============================================================================

  /**
   * Undoes the last action
   * 
   * Reverts state to previous history entry
   * 
   * @returns void
   * 
   * @example
   * ```typescript
   * undo(); // Revert last change
   * ```
   */
  undo: () => void;

  /**
   * Redoes the last undone action
   * 
   * Moves forward in history
   * 
   * @returns void
   * 
   * @example
   * ```typescript
   * redo(); // Reapply undone change
   * ```
   */
  redo: () => void;

  /**
   * Checks if undo is available
   * 
   * @returns true if there are actions to undo
   * 
   * @example
   * ```typescript
   * if (canUndo()) {
   *   undo();
   * }
   * ```
   */
  canUndo: () => boolean;

  /**
   * Checks if redo is available
   * 
   * @returns true if there are actions to redo
   * 
   * @example
   * ```typescript
   * if (canRedo()) {
   *   redo();
   * }
   * ```
   */
  canRedo: () => boolean;
}

/**
 * Main application store
 * 
 * Uses Zustand with devtools and persistence middleware.
 * State is persisted to localStorage under 'creative-studio-state' key.
 * 
 * @example
 * ```typescript
 * // In a component
 * import { useStore } from '@/stores/useStore';
 * 
 * function MyComponent() {
 *   const shots = useStore((state) => state.shots);
 *   const addShot = useStore((state) => state.addShot);
 *   
 *   return <button onClick={() => addShot({ title: 'New Shot' })}>Add</button>;
 * }
 * ```
 */
export const useStore = create<AppState>()(
  devtools(
    persist(
      (set, get) => ({
        // Initial state
        project: null,
        shots: [],
        assets: [],
        selectedShotId: null,
        currentTime: 0,
        showChat: false,
        showTaskQueue: false,
        panelSizes: {
          assetLibrary: 20,
          canvas: 60,
          propertiesOrChat: 20
        },
        taskQueue: [],
        isPlaying: false,
        playbackSpeed: 1.0,
        history: [],
        historyIndex: -1,

        // Project actions
        createProject: (name, settings) => {
          set({
            project: {
              id: crypto.randomUUID(),
              schema_version: '1.0',
              project_name: name,
              shots: [],
              assets: [],
              capabilities: {
                grid_generation: true,
                promotion_engine: true,
                qa_engine: true,
                autofix_engine: true
              },
              generation_status: {
                grid: 'pending',
                promotion: 'pending'
              },
              metadata: settings
            },
            shots: [],
            assets: [],
            selectedShotId: null
          });
        },

        loadProject: (projectData) => {
          set({
            project: projectData,
            shots: projectData.shots,
            assets: projectData.assets,
            selectedShotId: null
          });
        },

        saveProject: async () => {
          const state = get();
          // Implementation would save to backend or localStorage
        },

        exportProject: async (format) => {
          const state = get();
          const json = JSON.stringify(state.project, null, 2);
          return new Blob([json], { type: 'application/json' });
        },

        // Shot actions
        addShot: (shot) => {
          const id = crypto.randomUUID();
          const newShot: Shot = {
            id,
            title: shot.title || 'New Shot',
            description: shot.description || '',
            duration: shot.duration || 5,
            image: shot.image,
            audioTracks: shot.audioTracks || [],
            effects: shot.effects || [],
            textLayers: shot.textLayers || [],
            animations: shot.animations || [],
            transitionOut: shot.transitionOut,
            position: get().shots.length,
            metadata: shot.metadata
          };

          set((state) => ({
            shots: [...state.shots, newShot]
          }));

          return id;
        },

        updateShot: (shotId, updates) => {
          set((state) => ({
            shots: state.shots.map((shot) =>
              shot.id === shotId ? { ...shot, ...updates } : shot
            )
          }));
        },

        deleteShot: (shotId) => {
          set((state) => ({
            shots: state.shots.filter((shot) => shot.id !== shotId),
            selectedShotId: state.selectedShotId === shotId ? null : state.selectedShotId
          }));
        },

        reorderShots: (shotIds) => {
          const state = get();
          const shotsMap = new Map(state.shots.map((shot) => [shot.id, shot]));
          const reorderedShots = shotIds
            .map((id) => shotsMap.get(id))
            .filter((shot): shot is Shot => shot !== undefined)
            .map((shot, index) => ({ ...shot, position: index }));

          set({ shots: reorderedShots });
        },

        selectShot: (shotId) => {
          set({ selectedShotId: shotId });
        },

        // Asset actions
        addAsset: (asset) => {
          const id = crypto.randomUUID();
          const newAsset: Asset = {
            id,
            name: asset.name || 'New Asset',
            type: asset.type || 'image',
            url: asset.url || '',
            thumbnail: asset.thumbnail,
            metadata: asset.metadata
          };

          set((state) => ({
            assets: [...state.assets, newAsset]
          }));

          return id;
        },

        uploadAsset: async (file) => {
          // Implementation would upload to backend
          const url = URL.createObjectURL(file);
          return get().addAsset({
            name: file.name,
            type: file.type.startsWith('image/') ? 'image' : 'audio',
            url
          });
        },

        deleteAsset: (assetId) => {
          set((state) => ({
            assets: state.assets.filter((asset) => asset.id !== assetId)
          }));
        },

        searchAssets: (query) => {
          const state = get();
          const lowerQuery = query.toLowerCase();
          return state.assets.filter((asset) =>
            asset.name.toLowerCase().includes(lowerQuery)
          );
        },

        // Audio actions
        addAudioTrack: (shotId, track) => {
          const trackId = crypto.randomUUID();
          const newTrack: AudioTrack = {
            id: trackId,
            name: track.name || 'Audio Track',
            type: track.type || 'music',
            url: track.url || '',
            startTime: track.startTime || 0,
            duration: track.duration || 10,
            offset: track.offset || 0,
            volume: track.volume || 80,
            fadeIn: track.fadeIn || 0,
            fadeOut: track.fadeOut || 0,
            pan: track.pan || 0,
            muted: track.muted || false,
            solo: track.solo || false,
            effects: track.effects || [],
            waveformData: track.waveformData
          };

          set((state) => ({
            shots: state.shots.map((shot) =>
              shot.id === shotId
                ? { ...shot, audioTracks: [...shot.audioTracks, newTrack] }
                : shot
            )
          }));

          return trackId;
        },

        updateAudioTrack: (shotId, trackId, updates) => {
          set((state) => ({
            shots: state.shots.map((shot) =>
              shot.id === shotId
                ? {
                  ...shot,
                  audioTracks: shot.audioTracks.map((track) =>
                    track.id === trackId ? { ...track, ...updates } : track
                  )
                }
                : shot
            )
          }));
        },

        deleteAudioTrack: (shotId, trackId) => {
          set((state) => ({
            shots: state.shots.map((shot) =>
              shot.id === shotId
                ? {
                  ...shot,
                  audioTracks: shot.audioTracks.filter((track) => track.id !== trackId)
                }
                : shot
            )
          }));
        },

        // UI actions
        toggleChat: () => {
          set((state) => ({ showChat: !state.showChat }));
        },

        toggleTaskQueue: () => {
          set((state) => ({ showTaskQueue: !state.showTaskQueue }));
        },

        updatePanelSizes: (sizes) => {
          set((state) => ({
            panelSizes: { ...state.panelSizes, ...sizes }
          }));
        },

        setPlaying: (isPlaying) => {
          set({ isPlaying });
        },

        setCurrentTime: (time) => {
          set({ currentTime: time });
        },

        // Undo/Redo actions
        undo: () => {
          const state = get();
          if (state.historyIndex > 0) {
            const previousState = state.history[state.historyIndex - 1];
            set({
              ...previousState,
              historyIndex: state.historyIndex - 1
            });
          }
        },

        redo: () => {
          const state = get();
          if (state.historyIndex < state.history.length - 1) {
            const nextState = state.history[state.historyIndex + 1];
            set({
              ...nextState,
              historyIndex: state.historyIndex + 1
            });
          }
        },

        canUndo: () => {
          return get().historyIndex > 0;
        },

        canRedo: () => {
          const state = get();
          return state.historyIndex < state.history.length - 1;
        }
      }),
      {
        name: 'creative-studio-state',
        partialize: (state) => ({
          // Only persist these fields
          project: state.project,
          shots: state.shots,
          assets: state.assets,
          panelSizes: state.panelSizes
        })
      }
    ),
    {
      name: 'Creative Studio Store'
    }
  )
);

/**
 * Wizard State Store using Zustand
 * Manages the complete state for the Project Setup Wizard
 */

import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';
import type {
  WizardState,
  WizardStepData,
  ValidationResult,
  ValidationError,
  ProjectTypeData,
  GenreStyleData,
  WorldBuildingData,
  CharacterProfile,
  StoryStructureData,
  ScriptData,
  SceneBreakdown,
  ShotPlan,
  WizardType,
} from '../../types/wizard';

// Initial state factory
const createInitialState = () => ({
  // Wizard metadata
  wizardType: null as WizardType | null,

  // Navigation state
  currentStep: 1,
  completedSteps: new Set<number>(),
  isReviewMode: false,

  // Project data
  projectType: null,
  genreStyle: null,
  worldBuilding: null,
  characters: [],
  storyStructure: null,
  script: null,
  scenes: [],
  shots: [],

  // Metadata
  draftId: null,
  lastSaved: null,
  validationErrors: new Map<number, ValidationError[]>(),
});

/**
 * Wizard Store
 * Provides centralized state management for the wizard workflow
 */
export const useWizardStore = create<WizardState>()(
  devtools(
    persist(
      (set, get) => ({
        ...createInitialState(),

        /**
         * Set the wizard type
         * @param type - Wizard type identifier
         */
        setWizardType: (type: WizardType) => {
          set({ wizardType: type }, false, 'setWizardType');
        },

        /**
         * Set the current step
         * @param step - Step number to navigate to (1-8)
         */
        setCurrentStep: (step: number) => {
          set({ currentStep: step }, false, 'setCurrentStep');
        },

        /**
         * Update data for a specific step
         * @param step - Step number (1-8)
         * @param data - Partial data to update for that step
         */
        updateStepData: (step: number, data: Partial<WizardStepData>) => {
          set(
            (state) => {
              const updates: Partial<WizardState> = {};

              switch (step) {
                case 1:
                  updates.projectType = {
                    ...state.projectType,
                    ...data,
                  } as ProjectTypeData;
                  break;
                case 2:
                  updates.genreStyle = {
                    ...state.genreStyle,
                    ...data,
                  } as GenreStyleData;
                  break;
                case 3:
                  updates.worldBuilding = {
                    ...state.worldBuilding,
                    ...data,
                  } as WorldBuildingData;
                  break;
                case 4:
                  updates.characters = data as CharacterProfile[];
                  break;
                case 5:
                  updates.storyStructure = {
                    ...state.storyStructure,
                    ...data,
                  } as StoryStructureData;
                  break;
                case 6:
                  updates.script = {
                    ...state.script,
                    ...data,
                  } as ScriptData;
                  break;
                case 7:
                  updates.scenes = data as SceneBreakdown[];
                  break;
                case 8:
                  updates.shots = data as ShotPlan[];
                  break;
              }

              return updates;
            },
            false,
            'updateStepData'
          );
        },

        /**
         * Mark a step as complete
         * @param step - Step number to mark complete
         */
        markStepComplete: (step: number) => {
          set(
            (state) => {
              const newCompletedSteps = new Set(state.completedSteps);
              newCompletedSteps.add(step);
              return { completedSteps: newCompletedSteps };
            },
            false,
            'markStepComplete'
          );
        },

        /**
         * Validate a specific step
         * This is a placeholder that will call ValidationEngine when implemented
         * @param step - Step number to validate
         * @returns Validation result
         */
        validateStep: async (step: number): Promise<ValidationResult> => {
          const state = get();

          // Placeholder validation logic
          // This will be replaced with actual ValidationEngine calls in task 3
          const errors: ValidationError[] = [];
          const warnings: ValidationError[] = [];

          // Basic validation for each step
          switch (step) {
            case 1:
              if (!state.projectType) {
                errors.push({
                  field: 'projectType',
                  message: 'Project type is required',
                  severity: 'error',
                });
              } else if (state.projectType.durationMinutes <= 0) {
                errors.push({
                  field: 'durationMinutes',
                  message: 'Duration must be greater than 0',
                  severity: 'error',
                });
              }
              break;

            case 2:
              if (!state.genreStyle) {
                errors.push({
                  field: 'genreStyle',
                  message: 'Genre and style are required',
                  severity: 'error',
                });
              } else {
                if (state.genreStyle.genres.length === 0) {
                  errors.push({
                    field: 'genres',
                    message: 'At least one genre must be selected',
                    severity: 'error',
                  });
                }
              }
              break;

            case 3:
              if (!state.worldBuilding) {
                errors.push({
                  field: 'worldBuilding',
                  message: 'World building data is required',
                  severity: 'error',
                });
              } else if (state.worldBuilding.locations.length === 0) {
                errors.push({
                  field: 'locations',
                  message: 'At least one location is required',
                  severity: 'error',
                });
              }
              break;

            case 4:
              if (state.characters.length === 0) {
                errors.push({
                  field: 'characters',
                  message: 'At least one character is required',
                  severity: 'error',
                });
              }
              break;

            case 5:
              if (!state.storyStructure) {
                errors.push({
                  field: 'storyStructure',
                  message: 'Story structure is required',
                  severity: 'error',
                });
              } else {
                if (!state.storyStructure.premise) {
                  errors.push({
                    field: 'premise',
                    message: 'Premise is required',
                    severity: 'error',
                  });
                }
                if (!state.storyStructure.logline) {
                  errors.push({
                    field: 'logline',
                    message: 'Logline is required',
                    severity: 'error',
                  });
                }
              }
              break;

            case 6:
              if (!state.script) {
                errors.push({
                  field: 'script',
                  message: 'Script data is required',
                  severity: 'error',
                });
              }
              break;

            case 7:
              if (state.scenes.length === 0) {
                errors.push({
                  field: 'scenes',
                  message: 'At least one scene is required',
                  severity: 'error',
                });
              } else {
                // Validate each scene has location and characters
                state.scenes.forEach((scene, index) => {
                  if (!scene.locationId) {
                    errors.push({
                      field: `scenes[${index}].locationId`,
                      message: `Scene ${scene.sceneNumber} must have a location`,
                      severity: 'error',
                    });
                  }
                  if (scene.characterIds.length === 0) {
                    errors.push({
                      field: `scenes[${index}].characterIds`,
                      message: `Scene ${scene.sceneNumber} must have at least one character`,
                      severity: 'error',
                    });
                  }
                });
              }
              break;

            case 8:
              if (state.shots.length === 0) {
                errors.push({
                  field: 'shots',
                  message: 'At least one shot is required',
                  severity: 'error',
                });
              } else {
                // Validate each scene has at least one shot
                const scenesWithShots = new Set(state.shots.map((shot) => shot.sceneId));
                state.scenes.forEach((scene) => {
                  if (!scenesWithShots.has(scene.id)) {
                    warnings.push({
                      field: 'shots',
                      message: `Scene ${scene.sceneNumber} has no shots`,
                      severity: 'warning',
                    });
                  }
                });
              }
              break;
          }

          const result: ValidationResult = {
            isValid: errors.length === 0,
            errors,
            warnings,
          };

          // Update validation errors in state
          set(
            (state) => {
              const newValidationErrors = new Map(state.validationErrors);
              if (errors.length > 0) {
                newValidationErrors.set(step, errors);
              } else {
                newValidationErrors.delete(step);
              }
              return { validationErrors: newValidationErrors };
            },
            false,
            'validateStep'
          );

          return result;
        },

        /**
         * Check if the user can proceed from the current step
         * @returns true if validation passes for current step
         */
        canProceed: (): boolean => {
          const state = get();
          const currentStepErrors = state.validationErrors.get(state.currentStep);
          return !currentStepErrors || currentStepErrors.length === 0;
        },

        /**
         * Reset the wizard to initial state
         */
        reset: () => {
          set(createInitialState(), false, 'reset');
        },
      }),
      {
        name: 'wizard-storage',
        // Custom serialization for Set and Map
        partialize: (state) => ({
          ...state,
          completedSteps: Array.from(state.completedSteps),
          validationErrors: Array.from(state.validationErrors.entries()),
        }),
        // Custom deserialization for Set and Map with proper type handling
        merge: (persistedState: any, currentState) => {
          // Safely convert completedSteps to Set
          const completedSteps = Array.isArray(persistedState.completedSteps)
            ? new Set(persistedState.completedSteps)
            : new Set<number>();

          // Safely convert validationErrors to Map
          const validationErrors = Array.isArray(persistedState.validationErrors)
            ? new Map(persistedState.validationErrors)
            : new Map<number, ValidationError[]>();

          return {
            ...currentState,
            ...persistedState,
            completedSteps,
            validationErrors,
          };
        },
      }
    ),
    { name: 'WizardStore' }
  )
);

/**
 * Selector hooks for common state access patterns
 */

export const useCurrentStep = () => useWizardStore((state) => state.currentStep);
export const useCompletedSteps = () => useWizardStore((state) => state.completedSteps);
export const useIsReviewMode = () => useWizardStore((state) => state.isReviewMode);
export const useProjectType = () => useWizardStore((state) => state.projectType);
export const useGenreStyle = () => useWizardStore((state) => state.genreStyle);
export const useWorldBuilding = () => useWizardStore((state) => state.worldBuilding);
export const useCharacters = () => useWizardStore((state) => state.characters);
export const useStoryStructure = () => useWizardStore((state) => state.storyStructure);
export const useScript = () => useWizardStore((state) => state.script);
export const useScenes = () => useWizardStore((state) => state.scenes);
export const useShots = () => useWizardStore((state) => state.shots);
export const useValidationErrors = () => useWizardStore((state) => state.validationErrors);
export const useCanProceed = () => useWizardStore((state) => state.canProceed());

/**
 * Workflow Store - Zustand store for high-level creative journey orchestration
 * 
 * Tracks the user's progress through the end-to-end filmmaking workflow:
 * 1. Pre-production (Wizards: World, Characters)
 * 2. Storytelling (Script, Sequences, Shots)
 * 3. Generation (AI Assets: Images, Videos, Audio)
 * 4. Post-production (Review, Adjustments, Regeneration)
 * 5. Export (Final Film)
 */

import { create } from 'zustand';

export type WorkflowStage =
    | 'preparation'   // World building, character creation
    | 'storytelling'  // Plot, sequence planning, shot listing
    | 'generation'    // AI asset generation
    | 'post_prod'     // Review, edit, regenerate
    | 'delivery';     // Final export

export interface StageProgress {
    percentage: number;
    status: 'todo' | 'in_progress' | 'completed';
    requiredTasks: string[];
    completedTasks: string[];
}

interface WorkflowState {
    currentStage: WorkflowStage;
    stageProgress: Record<WorkflowStage, StageProgress>;
    lastCheckpoint: number; // Timestamp
    globalProgress: number; // 0-100

    // Actions
    setStage: (stage: WorkflowStage) => void;
    updateStageProgress: (stage: WorkflowStage, updates: Partial<StageProgress>) => void;
    completeTask: (stage: WorkflowStage, taskId: string) => void;
    uncompleteTask: (stage: WorkflowStage, taskId: string) => void;
    resetWorkflow: () => void;
    calculateGlobalProgress: () => void;
}

const INITIAL_STAGES: Record<WorkflowStage, StageProgress> = {
    preparation: {
        percentage: 0,
        status: 'todo',
        requiredTasks: ['create_world', 'create_main_character'],
        completedTasks: [],
    },
    storytelling: {
        percentage: 0,
        status: 'todo',
        requiredTasks: ['generate_story', 'plan_sequences', 'list_shots'],
        completedTasks: [],
    },
    generation: {
        percentage: 0,
        status: 'todo',
        requiredTasks: ['generate_images', 'generate_videos', 'generate_audio'],
        completedTasks: [],
    },
    post_prod: {
        percentage: 0,
        status: 'todo',
        requiredTasks: ['review_shots', 'adjust_timing'],
        completedTasks: [],
    },
    delivery: {
        percentage: 0,
        status: 'todo',
        requiredTasks: ['render_final', 'export_file'],
        completedTasks: [],
    },
};

export const useWorkflowStore = create<WorkflowState>((set, get) => ({
    currentStage: 'preparation',
    stageProgress: INITIAL_STAGES,
    lastCheckpoint: Date.now(),
    globalProgress: 0,

    setStage: (stage) => set({ currentStage: stage, lastCheckpoint: Date.now() }),

    updateStageProgress: (stage, updates) =>
        set((state) => {
            const newStageProgress = {
                ...state.stageProgress,
                [stage]: { ...state.stageProgress[stage], ...updates }
            };

            // Auto-update status based on percentage
            if (newStageProgress[stage].percentage >= 100) {
                newStageProgress[stage].status = 'completed';
            } else if (newStageProgress[stage].percentage > 0) {
                newStageProgress[stage].status = 'in_progress';
            }

            return { stageProgress: newStageProgress };
        }),

    completeTask: (stage, taskId) =>
        set((state) => {
            const stageData = state.stageProgress[stage];
            if (stageData.completedTasks.includes(taskId)) return state;

            const completedTasks = [...stageData.completedTasks, taskId];
            const percentage = Math.round((completedTasks.length / stageData.requiredTasks.length) * 100);

            const newStageProgress = {
                ...state.stageProgress,
                [stage]: {
                    ...stageData,
                    completedTasks,
                    percentage,
                    status: percentage >= 100 ? 'completed' : 'in_progress',
                }
            };

            return { stageProgress: newStageProgress };
        }),

    uncompleteTask: (stage, taskId) =>
        set((state) => {
            const stageData = state.stageProgress[stage];
            const completedTasks = stageData.completedTasks.filter(id => id !== taskId);
            const percentage = Math.round((completedTasks.length / stageData.requiredTasks.length) * 100);

            const newStageProgress = {
                ...state.stageProgress,
                [stage]: {
                    ...stageData,
                    completedTasks,
                    percentage,
                    status: percentage === 0 ? 'todo' : 'in_progress',
                }
            };

            return { stageProgress: newStageProgress };
        }),

    calculateGlobalProgress: () =>
        set((state) => {
            const stages = Object.values(state.stageProgress);
            const totalProgress = stages.reduce((acc, stage) => acc + stage.percentage, 0);
            const globalProgress = Math.round(totalProgress / stages.length);
            return { globalProgress };
        }),

    resetWorkflow: () => set({
        currentStage: 'preparation',
        stageProgress: INITIAL_STAGES,
        globalProgress: 0,
        lastCheckpoint: Date.now()
    }),
}));

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

export interface WorldData {
  id: string;
  version: number;
  foundations: {
    name: string;
    genre: string;
    tone: string;
    setting: string;
    scale: 'small' | 'medium' | 'large';
  };
  rules: {
    physics: string[];
    magic: string[];
    technology: string[];
    restrictions: string[];
  };
  culture: {
    societies: Array<{
      id: string;
      name: string;
      values: string[];
      customs: string[];
    }>;
    conflicts: string[];
    alliances: string[];
  };
  locations: Array<{
    id: string;
    name: string;
    type: 'city' | 'wilderness' | 'dungeon' | 'other';
    description: string;
    coordinates: { x: number; y: number };
  }>;
  synthesis: {
    plotHooks: string[];
    keyEvents: string[];
    themes: string[];
    summary: string;
  };
}

export interface WorldBuilderState {
  worldData: WorldData | null;
  currentStep: string;
  completedSteps: Set<string>;
  isLoading: boolean;
  error: string | null;
  lastSaved: Date | null;

  // Actions
  initializeWorld: (data: Partial<WorldData>) => void;
  updateStep: (step: string, data: unknown) => void;
  navigateToStep: (step: string) => void;
  markStepComplete: (step: string) => void;
  validateStep: (step: string) => boolean;
  saveWorld: () => Promise<void>;
  loadWorld: (id: string) => Promise<void>;
  resetWorld: () => void;
  setError: (error: string | null) => void;
}

const initialWorldData: Omit<WorldData, 'id'> = {
  version: 1,
  foundations: {
    name: '',
    genre: '',
    tone: '',
    setting: '',
    scale: 'medium',
  },
  rules: {
    physics: [],
    magic: [],
    technology: [],
    restrictions: [],
  },
  culture: {
    societies: [],
    conflicts: [],
    alliances: [],
  },
  locations: [],
  synthesis: {
    plotHooks: [],
    keyEvents: [],
    themes: [],
    summary: '',
  },
};

const STEPS = ['foundations', 'rules', 'culture', 'locations', 'synthesis'];

export const useWorldBuilderStore = create<WorldBuilderState>()(
  persist(
    (set, get) => ({
      worldData: null,
      currentStep: 'foundations',
      completedSteps: new Set(),
      isLoading: false,
      error: null,
      lastSaved: null,

      initializeWorld: (data: Partial<WorldData>) => {
        const newWorld: WorldData = {
          id: crypto.randomUUID(),
          ...initialWorldData,
          ...data,
        };
        set({
          worldData: newWorld,
          currentStep: 'foundations',
          completedSteps: new Set(),
          lastSaved: new Date(),
        });
      },

      updateStep: (step: string, data: unknown) => {
        const { worldData } = get();
        if (!worldData) return;

        const updatedWorld = {
          ...worldData,
          [step]: { ...(worldData[step as keyof WorldData] as any), ...(data as any) },
          version: worldData.version + 1,
        };

        set({
          worldData: updatedWorld,
          lastSaved: new Date(),
        });
      },

      navigateToStep: (step: string) => {
        if (!STEPS.includes(step)) return;
        set({ currentStep: step });
      },

      markStepComplete: (step: string) => {
        if (!STEPS.includes(step)) return;
        const { completedSteps } = get();
        const newCompleted = new Set(completedSteps);
        newCompleted.add(step);
        set({ completedSteps: newCompleted });
      },

      validateStep: (step: string): boolean => {
        const { worldData } = get();
        if (!worldData) return false;

        switch (step) {
          case 'foundations':
            return !!(
              worldData.foundations.name &&
              worldData.foundations.genre &&
              worldData.foundations.setting
            );
          case 'rules':
            return worldData.rules.physics.length > 0;
          case 'culture':
            return worldData.culture.societies.length > 0;
          case 'locations':
            return worldData.locations.length > 0;
          case 'synthesis':
            return !!(worldData.synthesis.summary && worldData.synthesis.themes.length > 0);
          default:
            return false;
        }
      },

      saveWorld: async () => {
        set({ isLoading: true, error: null });
        try {
          // TODO: Integrate with WorldBuilderService
          await new Promise(resolve => setTimeout(resolve, 100)); // Mock
          set({ lastSaved: new Date(), isLoading: false });
        } catch (error) {
          set({ error: 'Failed to save world', isLoading: false });
        }
      },

      loadWorld: async (id: string) => {
        set({ isLoading: true, error: null });
        try {
          // TODO: Integrate with WorldBuilderService
          await new Promise(resolve => setTimeout(resolve, 100)); // Mock
          set({ isLoading: false });
        } catch (error) {
          set({ error: 'Failed to load world', isLoading: false });
        }
      },

      resetWorld: () => {
        set({
          worldData: null,
          currentStep: 'foundations',
          completedSteps: new Set(),
          error: null,
          lastSaved: null,
        });
      },

      setError: (error: string | null) => {
        set({ error });
      },
    }),
    {
      name: 'world-builder-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        worldData: state.worldData,
        currentStep: state.currentStep,
        completedSteps: Array.from(state.completedSteps),
        lastSaved: state.lastSaved,
      }),
    }
  )
);

// Helper hooks
export const useWorldBuilderActions = () => {
  const {
    initializeWorld,
    updateStep,
    navigateToStep,
    markStepComplete,
    validateStep,
    saveWorld,
    loadWorld,
    resetWorld,
    setError,
  } = useWorldBuilderStore();

  return {
    initializeWorld,
    updateStep,
    navigateToStep,
    markStepComplete,
    validateStep,
    saveWorld,
    loadWorld,
    resetWorld,
    setError,
  };
};

export const useWorldBuilderSelectors = () => {
  const { worldData, currentStep, completedSteps, isLoading, error, lastSaved } =
    useWorldBuilderStore();

  return {
    worldData,
    currentStep,
    completedSteps,
    isLoading,
    error,
    lastSaved,
    isStepCompleted: (step: string) => completedSteps.has(step),
    canNavigateToStep: (step: string) => completedSteps.has(step) || step === currentStep,
  };
};

/**
 * Accessibility Testing Helpers
 * 
 * Utilities for testing accessibility compliance using axe-core.
 * Provides helpers for running accessibility audits and asserting WCAG compliance.
 * 
 * Requirements: 10.1-10.7
 */

import axe from 'axe-core';
import type { RenderResult } from '@testing-library/react';
import { expect } from 'vitest';

declare module 'vitest' {
  interface Assertion<T = any> {
    toHaveNoViolations(): void;
  }
}

/**
 * Custom matcher for axe violations
 */
function toHaveNoViolations(results: any) {
  const violations = results.violations || [];
  const pass = violations.length === 0;

  if (pass) {
    return {
      message: () => 'Expected to have accessibility violations, but found none',
      pass: true,
    };
  }

  const violationMessages = violations.map((violation: any) => {
    return `${violation.id}: ${violation.description}\n  ${violation.helpUrl}`;
  }).join('\n\n');

  return {
    message: () => `Expected no accessibility violations, but found ${violations.length}:\n\n${violationMessages}`,
    pass: false,
  };
}

// Extend expect with custom matcher
expect.extend({ toHaveNoViolations });

/**
 * Run accessibility audit on a rendered component
 * 
 * @param container - The rendered component container
 * @param options - Axe configuration options
 * @returns Axe results
 */
export async function runAccessibilityAudit(
  container: HTMLElement | RenderResult,
  options?: {
    rules?: Record<string, { enabled: boolean }>;
    tags?: string[];
  }
) {
  const element = 'container' in container ? container.container : container;

  const results = await axe.run(element, {
    rules: options?.rules || {},
    runOnly: {
      type: 'tag',
      values: options?.tags || ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'],
    },
  });

  return results;
}

/**
 * Assert that a component has no accessibility violations
 * 
 * @param container - The rendered component container
 * @param options - Axe configuration options
 */
export async function assertNoAccessibilityViolations(
  container: HTMLElement | RenderResult,
  options?: {
    rules?: Record<string, { enabled: boolean }>;
    tags?: string[];
  }
): Promise<void> {
  const results = await runAccessibilityAudit(container, options);
  expect(results).toHaveNoViolations();
}

/**
 * Assert that a component meets WCAG AA standards
 * 
 * @param container - The rendered component container
 */
export async function assertWCAGAACompliance(
  container: HTMLElement | RenderResult
): Promise<void> {
  await assertNoAccessibilityViolations(container, {
    tags: ['wcag2a', 'wcag2aa'],
  });
}

/**
 * Assert that a component meets WCAG AAA standards
 * 
 * @param container - The rendered component container
 */
export async function assertWCAGAAACompliance(
  container: HTMLElement | RenderResult
): Promise<void> {
  await assertNoAccessibilityViolations(container, {
    tags: ['wcag2a', 'wcag2aa', 'wcag2aaa'],
  });
}

/**
 * Check for specific accessibility violations
 * 
 * @param container - The rendered component container
 * @param ruleIds - Array of rule IDs to check
 * @returns Array of violations found
 */
export async function checkAccessibilityRules(
  container: HTMLElement | RenderResult,
  ruleIds: string[]
): Promise<any[]> {
  const element = 'container' in container ? container.container : container;

  const results = await axe.run(element, {
    rules: ruleIds.reduce((acc, id) => ({ ...acc, [id]: { enabled: true } }), {}),
  });

  return results.violations;
}

/**
 * Assert that keyboard navigation is properly implemented
 * 
 * @param container - The rendered component container
 */
export async function assertKeyboardNavigable(
  container: HTMLElement | RenderResult
): Promise<void> {
  const violations = await checkAccessibilityRules(container, [
    'tabindex',
    'focus-order-semantics',
    'focusable-content',
    'focusable-element',
  ]);

  expect(violations).toHaveLength(0);
}

/**
 * Assert that ARIA attributes are properly implemented
 * 
 * @param container - The rendered component container
 */
export async function assertProperARIA(
  container: HTMLElement | RenderResult
): Promise<void> {
  const violations = await checkAccessibilityRules(container, [
    'aria-allowed-attr',
    'aria-required-attr',
    'aria-required-children',
    'aria-required-parent',
    'aria-valid-attr',
    'aria-valid-attr-value',
    'aria-roles',
  ]);

  expect(violations).toHaveLength(0);
}

/**
 * Assert that color contrast meets standards
 * 
 * @param container - The rendered component container
 * @param level - WCAG level ('AA' or 'AAA')
 */
export async function assertColorContrast(
  container: HTMLElement | RenderResult,
  level: 'AA' | 'AAA' = 'AA'
): Promise<void> {
  const violations = await checkAccessibilityRules(container, [
    'color-contrast',
    'color-contrast-enhanced',
  ]);

  // Filter violations based on level
  const relevantViolations = level === 'AAA'
    ? violations
    : violations.filter(v => v.id === 'color-contrast');

  expect(relevantViolations).toHaveLength(0);
}

/**
 * Assert that interactive elements have accessible names
 * 
 * @param container - The rendered component container
 */
export async function assertAccessibleNames(
  container: HTMLElement | RenderResult
): Promise<void> {
  const violations = await checkAccessibilityRules(container, [
    'button-name',
    'link-name',
    'input-button-name',
    'label',
    'aria-label',
  ]);

  expect(violations).toHaveLength(0);
}

/**
 * Get a summary of accessibility violations
 * 
 * @param container - The rendered component container
 * @returns Summary object with violation counts by severity
 */
export async function getAccessibilitySummary(
  container: HTMLElement | RenderResult
): Promise<{
  critical: number;
  serious: number;
  moderate: number;
  minor: number;
  total: number;
  violations: any[];
}> {
  const results = await runAccessibilityAudit(container);

  const summary = {
    critical: 0,
    serious: 0,
    moderate: 0,
    minor: 0,
    total: results.violations.length,
    violations: results.violations,
  };

  (results.violations as any[]).forEach((violation: any) => {
    switch (violation.impact) {
      case 'critical':
        summary.critical++;
        break;
      case 'serious':
        summary.serious++;
        break;
      case 'moderate':
        summary.moderate++;
        break;
      case 'minor':
        summary.minor++;
        break;
    }
  });

  return summary;
}

/**
 * Log accessibility violations to console
 * 
 * @param container - The rendered component container
 */
export async function logAccessibilityViolations(
  container: HTMLElement | RenderResult
): Promise<void> {
  const summary = await getAccessibilitySummary(container);

  if (summary.total === 0) {
    console.log('✓ No accessibility violations found');
    return;
  }

  console.log(`\n⚠ Found ${summary.total} accessibility violations:`);
  console.log(`  Critical: ${summary.critical}`);
  console.log(`  Serious: ${summary.serious}`);
  console.log(`  Moderate: ${summary.moderate}`);
  console.log(`  Minor: ${summary.minor}\n`);

  summary.violations.forEach((violation, index) => {
    console.log(`${index + 1}. ${violation.id} (${violation.impact})`);
    console.log(`   ${violation.description}`);
    console.log(`   Help: ${violation.helpUrl}\n`);
  });
}

