export type Mood =
  | 'happy' | 'sad' | 'tense' | 'romantic' | 'mysterious' | 'epic'
  | 'intimate' | 'dark' | 'whimsical' | 'melancholic' | 'anxious' | 'triumphant'
  | 'nostalgic' | 'peaceful' | 'chaotic' | 'mystical' | 'ironic'
  | 'surprise' | 'relief' | 'neutral'; // Added neutral

export type Tone =
  | 'serious' | 'comedic' | 'dramatic' | 'light' | 'heavy' | 'playful'
  | 'grave' | 'hopeful' | 'cynical' | 'sentimental' | 'irreverent' | 'reverent' | 'neutral'; // Ensure neutral matches usage

export type Pacing = 'slow' | 'medium' | 'fast' | 'variable';
export type PacingEnergy = 'low' | 'medium' | 'high';
export type NoteType =
  | 'camera' | 'lighting' | 'acting' | 'sound' | 'pace' | 'emotion'
  | 'visual' | 'technical' | 'creative';
export type NotePriority = 'low' | 'medium' | 'high' | 'urgent';
export type NoteStatus = 'pending' | 'in_progress' | 'completed' | 'archived';

// ============================================================================
// CINEMATIC INTERFACES
// ============================================================================

export interface CameraMovementConfig {
  type: CameraMovement;
  name: string;
  description: string;
  category: CameraCategory;
  speed: CameraSpeed;
  smoothness: number; // 1-10
  complexity: CameraComplexity;
  promptExample: string;
  requiresSubjectMotion?: boolean;
  typicalDuration?: string;
  bestFor?: string[];
  icon?: any; // Added for UI compatibility
}

export interface BeatConfig {
  type: BeatType;
  name: string;
  description: string;
  duration?: string;
  emotionalTone?: Mood[];
  purpose?: string;
}

export interface PacingConfig {
  type: Pacing;
  name: string;
  description: string;
  shotDuration?: string;
  rhythm?: string;
  energy?: PacingEnergy;
  color?: string; // Added for UI compatibility
}

export interface MoodArc {
  id: string;
  beats: {
    beatType: BeatType;
    mood: Mood;
    intensity: number; // 0-1
  }[];
  overallTrend: 'rising' | 'falling' | 'flat' | 'complex';
  dominantMood: Mood;
  startMood: Mood;
  endMood: Mood;
  progression?: { time: number; mood: Mood }[]; // Updated type
}

export interface PacingAnalysis {
  overallPace: Pacing;
  averageShotDuration: number; // seconds
  pacingCurve: {
    time: number;
    pace: Pacing;
  }[];
  energyLevel: PacingEnergy;
  variationCount: number;
}

export interface DirectorNote {
  id: string;
  note: string;
  type: NoteType;
  priority: NotePriority;
  status: NoteStatus;
  timestamp: string;
  author?: string;
  resolvedAt?: string;
  metadata?: Metadata;
  content?: string; // Added alias for compatibility
}

export interface CharacterPresence {
  characterId: string;
  focus: CharacterFocus;
  timeStart: number; // seconds
  timeEnd: number; // seconds
  prominence: number; // 0-1
}

export interface CharacterFocusTrack {
  characterId: string;
  timeline: {
    characterId: string;
    timeStart: number;
    timeEnd: number;
    focus: CharacterFocus;
    cameraMovement?: CameraMovement;
  }[];
  totalScreenTime: number;
  dominantFocus: CharacterFocus;
}

export interface VersionEntry {
  version: string;
  timestamp: string;
  author: string;
  changes: string[];
  snapshot?: string;
}

// ============================================================================
// SHOT & SEQUENCE TYPES
// ============================================================================

export interface Shot {
  id: string;
  name: string;
  title?: string;
  description: string;
  order: number;
  position?: number;
  duration: number;
  cameraAngle?: string;
  cameraMovement?: CameraMovement;
  characters: string[];
  locationId?: string;
  sequence_id?: string;
  audio?: string;
  dialogue?: string;
  visualEffects?: string[];
  generatedImage?: string;
  seed?: number;
  prompt?: string;
  negativePrompt?: string;
  cfgScale?: number;
  denoisingStrength?: number;
  width?: number;
  height?: number;
  metadata?: Metadata;
  directorNotes?: DirectorNote[];
  status?: string;
  progress?: number;
  // Compatibility
  trim?: { start: number; end: number };
}

export interface SequenceBase {
  id: string;
  name: string;
  description?: string;
  order: number;
  duration?: number;
  createdAt?: string;
  updatedAt?: string;
  metadata?: Metadata;
}

export interface Beat extends SequenceBase {
  type: BeatType;
  importance: BeatImportance;
  suggestedDuration?: number;
  pacing: Pacing;
  mood: Mood;
  tone: Tone;
  characters: CharacterPresence[];
  locationId?: string;
  directorNotes: DirectorNote[];
  metadata?: Metadata;
}

export interface EnhancedShot {
  id: string;
  name: string;
  title?: string;
  description: string;
  order: number;
  position?: number;
  duration: number;
  beatId?: string;
  cameraMovement?: CameraMovement | null;
  pacing: Pacing;
  mood: Mood;
  tone: Tone;
  characters: CharacterPresence[];
  locationId?: string;
  directorNotes: DirectorNote[];
  metadata?: Metadata;
  sequence_id?: string;
  directorNote?: string; // backwards compatibility
  generatedImage?: string;
  prompt?: string;
  negativePrompt?: string;
  audioMood?: string;
  ttsPrompt?: string;
  version?: number;
  beatType?: BeatType;
  content?: string;
  transition?: TransitionType; // Added
}

export type CinematicShotData = EnhancedShot;

export interface CompleteSequence {
  id: string;
  name: string;
  description: string;
  order: number;
  beats: Beat[];
  shots: EnhancedShot[];
  moodArc?: MoodArc;
  pacingAnalysis?: PacingAnalysis;
  characterFocusTracks: CharacterFocusTrack[];
  directorNotes: DirectorNote[];
  versionHistory: VersionEntry[];
  createdAt: string;
  updatedAt: string;
  locationIds?: string[];
}

export interface ChapterWithBeats {
  id: string;
  title: string;
  description: string;
  beats: Beat[];
  sequences: CompleteSequence[];
  order: number;
}

