  type ChatboxLLMConfig,
  type LanguageCode,
} from '../llmConfigStorage';

// ============================================================================
// Test Setup
// ============================================================================

// Mock crypto.subtle for testing
const mockCrypto = {
  subtle: {
    generateKey: vi.fn(),
    importKey: vi.fn(),
    exportKey: vi.fn(),
    encrypt: vi.fn(),
    decrypt: vi.fn(),
