/**
 * React hook for ThumbnailCache - provides async loading and preloading of thumbnails
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { ThumbnailCache, ThumbnailData } from './ThumbnailCache';

interface ThumbnailState {
  data: ThumbnailData | null;
  loading: boolean;
  error: string | null;
}

interface UseThumbnailCacheOptions {
  preloadAdjacent?: boolean;
  adjacentCount?: number;
}

const globalCache = new ThumbnailCache();

export function useThumbnailCache(videoUrl: string, timestamp: number, options: UseThumbnailCacheOptions = {}) {
  const { preloadAdjacent = true, adjacentCount = 5 } = options;
  const [state, setState] = useState<ThumbnailState>({
    data: null,
    loading: true,
    error: null
  });

  const cacheRef = useRef(globalCache);
  const preloadTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const loadThumbnail = useCallback(async () => {
    if (!videoUrl) return;

    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      await cacheRef.current.initialize();

      const cached = await cacheRef.current.get(videoUrl, timestamp);

      if (cached) {
        setState({
          data: cached,
          loading: false,
          error: null
        });

        // Preload adjacent thumbnails
        if (preloadAdjacent) {
          preloadAdjacentThumbnails(videoUrl, timestamp, adjacentCount);
        }
      } else {
        // Thumbnail not cached, will be generated by worker
        setState({
          data: null,
          loading: false,
          error: 'Thumbnail not available'
        });
      }
    } catch (error) {
      setState({
        data: null,
        loading: false,
        error: error instanceof Error ? error.message : 'Failed to load thumbnail'
      });
    }
  }, [videoUrl, timestamp, preloadAdjacent, adjacentCount]);

  const preloadAdjacentThumbnails = useCallback(async (url: string, time: number, count: number) => {
    if (preloadTimeoutRef.current) {
      clearTimeout(preloadTimeoutRef.current);
    }

    preloadTimeoutRef.current = setTimeout(async () => {
      try {
        const frameRate = 30; // Assume 30fps, could be made configurable
        const frameDuration = 1 / frameRate;

        // Preload thumbnails before and after current position
        const promises = [];

        for (let i = 1; i <= count; i++) {
          // Before
          const beforeTime = Math.max(0, time - i * frameDuration);
          promises.push(cacheRef.current.get(url, beforeTime));

          // After
          const afterTime = time + i * frameDuration;
          promises.push(cacheRef.current.get(url, afterTime));
        }

        await Promise.allSettled(promises);
      } catch (error) {
        console.warn('Failed to preload adjacent thumbnails:', error);
      }
    }, 100); // Small delay to avoid blocking
  }, []);

  const generateThumbnail = useCallback(async (blob: Blob, width: number, height: number) => {
    if (!videoUrl) return;

    try {
      await cacheRef.current.initialize();
      await cacheRef.current.set(videoUrl, timestamp, blob, width, height);

      setState({
        data: await cacheRef.current.get(videoUrl, timestamp),
        loading: false,
        error: null
      });
    } catch (error) {
      setState(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Failed to generate thumbnail'
      }));
    }
  }, [videoUrl, timestamp]);

  useEffect(() => {
    loadThumbnail();
  }, [loadThumbnail]);

  useEffect(() => {
    return () => {
      if (preloadTimeoutRef.current) {
        clearTimeout(preloadTimeoutRef.current);
      }
    };
  }, []);

  return {
    ...state,
    generateThumbnail,
    reload: loadThumbnail
  };
}

export function useThumbnailCacheStats() {
  const [stats, setStats] = useState<{
    memoryItems: number;
    diskItems: number;
    memorySizeMB: number;
    diskSizeMB: number;
  } | null>(null);

  const loadStats = useCallback(async () => {
    try {
      await globalCache.initialize();
      const currentStats = await globalCache.getStats();
      setStats(currentStats);
    } catch (error) {
      console.warn('Failed to load cache stats:', error);
    }
  }, []);

  const clearCache = useCallback(async () => {
    try {
      await globalCache.clear();
      await loadStats();
    } catch (error) {
      console.warn('Failed to clear cache:', error);
    }
  }, [loadStats]);

  useEffect(() => {
    loadStats();
  }, [loadStats]);

  return {
    stats,
    clearCache,
    reloadStats: loadStats
  };
}

/**
 * Language Detection and Initialization Utilities
 * 
 * This module provides functions for detecting the system language,
 * initializing the language preference on first launch, and persisting
 * user language preferences to localStorage.
 * 
 * @module utils/languageDetection
 */

import {
  SUPPORTED_LANGUAGES,
  LANGUAGE_STORAGE_KEY,
  StoredLanguagePreference
} from '../types/language';

/**
 * Detects the system language from the browser's navigator.language property.
 * 
 * Algorithm:
 * 1. Extract the primary language code from navigator.language (e.g., 'en-US' -> 'en')
 * 2. Check if the language code is in SUPPORTED_LANGUAGES
 * 3. Return the supported language code or fallback to 'en' if unsupported
 * 
 * @returns {string} The detected language code or 'en' as fallback
 * 
 * @example
 * // Browser language is 'es-ES'
 * const lang = detectSystemLanguage(); // Returns 'es'
 * 
 * @example
 * // Browser language is 'xx-XX' (unsupported)
 * const lang = detectSystemLanguage(); // Returns 'en'
 */
export function detectSystemLanguage(): string {
  // Force English as default language instead of auto-detecting browser language
  // This prevents the app from defaulting to French on French systems
  return 'en';
  
  // Original auto-detection code (disabled):
  // const browserLang = navigator.language || (navigator as any).userLanguage || 'en';
  // const primaryLang = browserLang.split('-')[0].toLowerCase();
  // const isSupported = SUPPORTED_LANGUAGES.some(lang => lang.code === primaryLang);
  // return isSupported ? primaryLang : 'en';
}

/**
 * Initializes the language preference on application startup.
 * 
 * Algorithm:
 * 1. Check localStorage for an existing language preference
 * 2. If found and user-selected, return the saved language
 * 3. Otherwise, detect the system language
 * 4. Save the detected language (marked as not user-selected)
 * 5. Return the detected language
 * 
 * This function distinguishes between:
 * - User-selected languages (explicitly chosen by the user)
 * - System-detected languages (automatically detected on first launch)
 * 
 * @returns {string} The initialized language code
 * 
 * @example
 * // First launch, no saved preference
 * const lang = initializeLanguage(); // Detects system language and saves it
 * 
 * @example
 * // User has previously selected a language
 * const lang = initializeLanguage(); // Returns the user's saved preference
 */
export function initializeLanguage(): string {
  try {
    // 1. Check localStorage for existing preference
    const stored = localStorage.getItem(LANGUAGE_STORAGE_KEY);
    
    if (stored) {
      try {
        const parsed: StoredLanguagePreference = JSON.parse(stored);
        
        // 2. If user has explicitly selected a language, use it
        if (parsed.userLanguage) {
          return parsed.userLanguage;
        }
      } catch (parseError) {
        // Corrupted data - clear it and continue with detection
        console.warn('Corrupted language preference data, re-initializing:', parseError);
        localStorage.removeItem(LANGUAGE_STORAGE_KEY);
      }
    }
    
    // 3. No saved preference or not user-selected - detect system language
    const systemLang = detectSystemLanguage();
    
    // 4. Save detected language (marked as not user-selected)
    saveLanguagePreference(systemLang, false);
    
    // 5. Return the detected language
    return systemLang;
  } catch (error) {
    // localStorage unavailable - fall back to system detection without saving
    console.warn('localStorage unavailable, using in-memory language preference:', error);
    return detectSystemLanguage();
  }
}

/**
 * Alias for initializeLanguage - gets the initial language preference.
 * This function initializes or retrieves the language preference on application startup.
 * 
 * @returns {string} The initialized language code
 * 
 * @example
 * const lang = getInitialLanguagePreference(); // Returns the saved or detected language
 */
export function getInitialLanguagePreference(): string {
  return initializeLanguage();
}

/**
 * Saves the language preference to localStorage.
 * 
 * This function creates a StoredLanguagePreference object with:
 * - Schema version for future migration support
 * - User language (null if system-detected, language code if user-selected)
 * - Timestamp of when the preference was saved
 * 
 * @param {string} language - The language code to save
 * @param {boolean} userSelected - Whether the language was explicitly selected by the user
 * 
 * @example
 * // Save user-selected language
 * saveLanguagePreference('es', true);
 * 
 * @example
 * // Save system-detected language (not user-selected)
 * saveLanguagePreference('en', false);
 */
export function saveLanguagePreference(language: string, userSelected: boolean): void {
  try {
    // Create the preference object
    const preference: StoredLanguagePreference = {
      version: '1.0',
      userLanguage: userSelected ? language : null,
      lastUpdated: new Date().toISOString()
    };
    
    // Save to localStorage
    localStorage.setItem(LANGUAGE_STORAGE_KEY, JSON.stringify(preference));
  } catch (error) {
    // localStorage unavailable or quota exceeded
    console.error('Failed to save language preference to localStorage:', error);
    // Continue execution - the app will work with in-memory state
  }
}

/**
 * LLM Configuration Storage Utilities
 * 
 * Provides localStorage wrapper functions for LLM configuration with encryption support.
 * Implements requirements 6.1, 6.2, 6.3, 6.4, 6.5, 6.6, 6.7 from the LLM Chatbox Enhancement spec.
 */

import type { LLMProvider } from '@/services/llmService';

// ============================================================================
// Types
// ============================================================================

/**
 * Language codes supported by the chatbox
 */
export type LanguageCode = 'fr' | 'en' | 'es' | 'de' | 'it' | 'pt' | 'ja' | 'zh' | 'ko';

/**
 * LLM configuration for chatbox (simplified from full LLMConfig)
 */
export interface ChatboxLLMConfig {
  provider: LLMProvider;
  model: string;
  temperature: number; // 0-2
  maxTokens: number; // 100-4000
  apiKey: string;
  streamingEnabled: boolean;
}

/**
 * Stored LLM configuration (without plain API key)
 */
export interface StoredLLMConfig {
  provider: LLMProvider;
  model: string;
  temperature: number;
  maxTokens: number;
  streamingEnabled: boolean;
  lastValidated?: string; // ISO timestamp
}

/**
 * Language preference storage
 */
export interface StoredLanguagePreference {
  code: LanguageCode;
  setAt: string; // ISO timestamp
  autoDetected: boolean;
}



// ============================================================================
// Constants
// ============================================================================

/**
 * LocalStorage keys for chatbox configuration
 */
export const STORAGE_KEYS = {
  LLM_CONFIG: 'storycore_llm_config',
  LANGUAGE_PREF: 'storycore_language_preference',
  API_KEY_ENCRYPTED: 'storycore_api_key_enc',
} as const;

/**
 * Default LLM configuration
 */
export const DEFAULT_LLM_CONFIG: ChatboxLLMConfig = {
  provider: 'local',
  model: 'llama3.2:1b', // Lightweight Ollama model by default
  temperature: 0.7,
  maxTokens: 2000,
  apiKey: '',
  streamingEnabled: true,
};

/**
 * Default language (English)
 */
export const DEFAULT_LANGUAGE: LanguageCode = 'en';

/**
 * Encryption algorithm and parameters
 */
const ENCRYPTION_ALGORITHM = 'AES-GCM';
const KEY_LENGTH = 256;
const ENCRYPTION_KEY_STORAGE = 'storycore_encryption_key';

// ============================================================================
// Encryption Key Management
// ============================================================================

/**
 * Generate or retrieve encryption key from session storage
 * Key is session-specific for security
 */
async function getEncryptionKey(): Promise<CryptoKey> {
  // Check if key exists in session storage
  const storedKey = sessionStorage.getItem(ENCRYPTION_KEY_STORAGE);
  
  if (storedKey) {
    try {
      const keyData = JSON.parse(storedKey);
      return await crypto.subtle.importKey(
        'jwk',
        keyData,
        { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
        true,
        ['encrypt', 'decrypt']
      );
    } catch (error) {
      console.warn('Failed to import stored encryption key, generating new one');
    }
  }

  // Generate new key
  const key = await crypto.subtle.generateKey(
    { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
    true,
    ['encrypt', 'decrypt']
  );

  // Store key in session storage
  const exportedKey = await crypto.subtle.exportKey('jwk', key);
  sessionStorage.setItem(ENCRYPTION_KEY_STORAGE, JSON.stringify(exportedKey));

  return key;
}

// ============================================================================
// Encryption Functions
// ============================================================================

/**
 * Encrypt API key using Web Crypto API
 * Implements requirements 6.6, 6.7
 */
export async function encryptAPIKey(apiKey: string): Promise<string> {
  if (!apiKey) {
    return '';
  }

  try {
    const key = await getEncryptionKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const encoder = new TextEncoder();
    const data = encoder.encode(apiKey);

    const encrypted = await crypto.subtle.encrypt(
      { name: ENCRYPTION_ALGORITHM, iv },
      key,
      data
    );

    // Convert to base64 for storage
    const encryptedArray = new Uint8Array(encrypted);
    const encryptedBase64 = btoa(String.fromCharCode(...encryptedArray));
    const ivBase64 = btoa(String.fromCharCode(...iv));

    // Combine encrypted data and IV with separator
    return `${encryptedBase64}:${ivBase64}`;
  } catch (error) {
    console.error('API key encryption failed:', error);
    throw new Error('Failed to encrypt API key');
  }
}

/**
 * Decrypt API key using Web Crypto API
 * Implements requirements 6.6, 6.7
 */
export async function decryptAPIKey(encryptedData: string): Promise<string> {
  if (!encryptedData) {
    return '';
  }

  try {
    const key = await getEncryptionKey();
    
    // Split encrypted data and IV
    const [encryptedBase64, ivBase64] = encryptedData.split(':');
    if (!encryptedBase64 || !ivBase64) {
      throw new Error('Invalid encrypted data format');
    }

    // Convert from base64
    const encryptedArray = Uint8Array.from(atob(encryptedBase64), c => c.charCodeAt(0));
    const ivArray = Uint8Array.from(atob(ivBase64), c => c.charCodeAt(0));

    const decrypted = await crypto.subtle.decrypt(
      { name: ENCRYPTION_ALGORITHM, iv: ivArray },
      key,
      encryptedArray
    );

    const decoder = new TextDecoder();
    return decoder.decode(decrypted);
  } catch (error) {
    console.error('API key decryption failed:', error);
    throw new Error('Failed to decrypt API key');
  }
}

// ============================================================================
// Configuration Storage Functions
// ============================================================================

/**
 * Save LLM configuration to localStorage
 * Implements requirements 1.7, 6.4
 */
export async function saveConfiguration(config: ChatboxLLMConfig): Promise<void> {
  try {
    // Encrypt API key
    const encryptedApiKey = await encryptAPIKey(config.apiKey);

    // Store configuration without API key
    const storedConfig: StoredLLMConfig = {
      provider: config.provider,
      model: config.model,
      temperature: config.temperature,
      maxTokens: config.maxTokens,
      streamingEnabled: config.streamingEnabled,
      lastValidated: new Date().toISOString(),
    };

    localStorage.setItem(STORAGE_KEYS.LLM_CONFIG, JSON.stringify(storedConfig));
    localStorage.setItem(STORAGE_KEYS.API_KEY_ENCRYPTED, encryptedApiKey);
  } catch (error) {
    console.error('Failed to save LLM configuration:', error);
    throw new Error('Failed to save configuration. Please try again.');
  }
}

/**
 * Load LLM configuration from localStorage
 * Implements requirements 6.1, 6.2
 */
export async function loadConfiguration(): Promise<ChatboxLLMConfig | null> {
  try {
    const configJson = localStorage.getItem(STORAGE_KEYS.LLM_CONFIG);
    const encryptedApiKey = localStorage.getItem(STORAGE_KEYS.API_KEY_ENCRYPTED);

    if (!configJson) {
      return null;
    }

    const storedConfig: StoredLLMConfig = JSON.parse(configJson);

    // Decrypt API key
    const apiKey = encryptedApiKey ? await decryptAPIKey(encryptedApiKey) : '';

    // Reconstruct full configuration
    return {
      provider: storedConfig.provider,
      model: storedConfig.model,
      temperature: storedConfig.temperature,
      maxTokens: storedConfig.maxTokens,
      apiKey,
      streamingEnabled: storedConfig.streamingEnabled,
    };
  } catch (error) {
    console.error('Failed to load LLM configuration:', error);
    return null;
  }
}

/**
 * Get default configuration
 * Implements requirement 6.3
 */
export function getDefaultConfiguration(): ChatboxLLMConfig {
  return { ...DEFAULT_LLM_CONFIG };
}

/**
 * Delete LLM configuration from localStorage
 */
export function deleteConfiguration(): void {
  try {
    localStorage.removeItem(STORAGE_KEYS.LLM_CONFIG);
    localStorage.removeItem(STORAGE_KEYS.API_KEY_ENCRYPTED);
  } catch (error) {
    console.error('Failed to delete LLM configuration:', error);
    throw new Error('Failed to delete configuration');
  }
}

// ============================================================================
// Language Preference Functions
// ============================================================================

/**
 * Save language preference to localStorage
 * Implements requirements 2.4, 6.5
 */
export function saveLanguagePreference(language: LanguageCode, autoDetected: boolean = false): void {
  try {
    const preference: StoredLanguagePreference = {
      code: language,
      setAt: new Date().toISOString(),
      autoDetected,
    };

    localStorage.setItem(STORAGE_KEYS.LANGUAGE_PREF, JSON.stringify(preference));
  } catch (error) {
    console.error('Failed to save language preference:', error);
    throw new Error('Failed to save language preference');
  }
}

/**
 * Load language preference from localStorage
 * Implements requirements 6.1, 6.2
 */
export function loadLanguagePreference(): LanguageCode | null {
  try {
    const prefJson = localStorage.getItem(STORAGE_KEYS.LANGUAGE_PREF);

    if (!prefJson) {
      return null;
    }

    const preference: StoredLanguagePreference = JSON.parse(prefJson);
    return preference.code;
  } catch (error) {
    console.error('Failed to load language preference:', error);
    return null;
  }
}

/**
 * Detect browser language and map to supported language code
 * Implements requirement 2.3
 */
export function detectBrowserLanguage(): LanguageCode {
  try {
    const browserLang = navigator.language.toLowerCase();

    // Map browser language codes to supported languages
    if (browserLang.startsWith('fr')) return 'fr';
    if (browserLang.startsWith('es')) return 'es';
    if (browserLang.startsWith('de')) return 'de';
    if (browserLang.startsWith('it')) return 'it';
    if (browserLang.startsWith('pt')) return 'pt';
    if (browserLang.startsWith('ja')) return 'ja';
    if (browserLang.startsWith('zh')) return 'zh';
    if (browserLang.startsWith('ko')) return 'ko';
    if (browserLang.startsWith('en')) return 'en';

    // Default to English for unsupported languages
    return DEFAULT_LANGUAGE;
  } catch (error) {
    console.error('Failed to detect browser language:', error);
    return DEFAULT_LANGUAGE;
  }
}

/**
 * Get language preference with auto-detection fallback
 * Implements requirements 2.3, 6.1, 6.2
 */
export function getLanguagePreference(): LanguageCode {
  const stored = loadLanguagePreference();
  if (stored) {
    return stored;
  }

  // Auto-detect and save
  const detected = detectBrowserLanguage();
  saveLanguagePreference(detected, true);
  return detected;
}

// ============================================================================
// Configuration Validation Functions
// ============================================================================

/**
 * Validate LLM configuration
 * Implements requirement 6.3
 */
export function validateConfiguration(config: Partial<ChatboxLLMConfig>): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Validate provider
  if (config.provider) {
    const validProviders: LLMProvider[] = ['openai', 'anthropic', 'local', 'custom'];
    if (!validProviders.includes(config.provider)) {
      errors.push(`Invalid provider: ${config.provider}`);
    }
  }

  // Validate model
  if (config.model !== undefined && typeof config.model !== 'string') {
    errors.push('Model must be a string');
  }

  // Validate temperature (0-2)
  if (config.temperature !== undefined) {
    if (typeof config.temperature !== 'number' || config.temperature < 0 || config.temperature > 2) {
      errors.push('Temperature must be a number between 0 and 2');
    }
  }

  // Validate maxTokens (100-4000)
  if (config.maxTokens !== undefined) {
    if (typeof config.maxTokens !== 'number' || config.maxTokens < 100 || config.maxTokens > 4000) {
      errors.push('Max tokens must be a number between 100 and 4000');
    }
  }

  // Validate API key (if provided)
  if (config.apiKey !== undefined && typeof config.apiKey !== 'string') {
    errors.push('API key must be a string');
  }

  // Validate streaming enabled
  if (config.streamingEnabled !== undefined && typeof config.streamingEnabled !== 'boolean') {
    errors.push('Streaming enabled must be a boolean');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Validate language code
 */
export function validateLanguageCode(code: string): code is LanguageCode {
  const validCodes: LanguageCode[] = ['fr', 'en', 'es', 'de', 'it', 'pt', 'ja', 'zh', 'ko'];
  return validCodes.includes(code as LanguageCode);
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Check if Web Crypto API is available
 */
export function isCryptoAvailable(): boolean {
  return (
    typeof crypto !== 'undefined' &&
    typeof crypto.subtle !== 'undefined' &&
    typeof crypto.subtle.encrypt === 'function'
  );
}

/**
 * Check if configuration exists in localStorage
 */
export function hasStoredConfiguration(): boolean {
  return localStorage.getItem(STORAGE_KEYS.LLM_CONFIG) !== null;
}

/**
 * Check if language preference exists in localStorage
 */
export function hasStoredLanguagePreference(): boolean {
  return localStorage.getItem(STORAGE_KEYS.LANGUAGE_PREF) !== null;
}

/**
 * Get last validation timestamp
 */
export function getLastValidationTime(): Date | null {
  try {
    const configJson = localStorage.getItem(STORAGE_KEYS.LLM_CONFIG);
    if (!configJson) {
      return null;
    }

    const config: StoredLLMConfig = JSON.parse(configJson);
    return config.lastValidated ? new Date(config.lastValidated) : null;
  } catch (error) {
    console.error('Failed to get last validation time:', error);
    return null;
  }
}

/**
 * Clear all chatbox storage (configuration and language preference)
 */
export function clearAllStorage(): void {
  try {
    deleteConfiguration();
    localStorage.removeItem(STORAGE_KEYS.LANGUAGE_PREF);
    sessionStorage.removeItem(ENCRYPTION_KEY_STORAGE);
  } catch (error) {
    console.error('Failed to clear storage:', error);
    throw new Error('Failed to clear storage');
  }
}

/**
 * LLM Diagnostic Utility
 * 
 * Provides comprehensive diagnostic information about LLM configuration and connectivity.
 * Helps troubleshoot issues with LLM service initialization and usage.
 */

import { loadConfiguration, hasStoredConfiguration, isCryptoAvailable } from './llmConfigStorage';
import { LLMService, type LLMConfig } from '@/services/llmService';
import { checkOllamaStatus } from '@/services/ollamaConfig';

// ============================================================================
// Types
// ============================================================================

export interface DiagnosticResult {
  timestamp: string;
  overall: 'healthy' | 'warning' | 'error';
  checks: {
    storage: DiagnosticCheck;
    configuration: DiagnosticCheck;
    encryption: DiagnosticCheck;
    connectivity: DiagnosticCheck;
    ollama: DiagnosticCheck;
  };
  recommendations: string[];
  config?: {
    provider: string;
    model: string;
    hasApiKey: boolean;
    streamingEnabled: boolean;
  };
}

export interface DiagnosticCheck {
  status: 'pass' | 'warning' | 'fail';
  message: string;
  details?: unknown;
}

// ============================================================================
// Diagnostic Functions
// ============================================================================

/**
 * Check localStorage availability and stored configuration
 */
function checkStorage(): DiagnosticCheck {
  try {
    // Test localStorage write
    const testKey = '__storycore_test__';
    localStorage.setItem(testKey, 'test');
    localStorage.removeItem(testKey);

    // Check if configuration exists
    const hasConfig = hasStoredConfiguration();

    if (!hasConfig) {
      return {
        status: 'warning',
        message: 'No LLM configuration found in storage',
        details: {
          hasConfig: false,
          storageAvailable: true,
        },
      };
    }

    return {
      status: 'pass',
      message: 'Storage is available and configuration exists',
      details: {
        hasConfig: true,
        storageAvailable: true,
      },
    };
  } catch (error) {
    return {
      status: 'fail',
      message: 'localStorage is not available',
      details: {
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Check configuration validity
 */
async function checkConfiguration(): Promise<DiagnosticCheck> {
  try {
    const config = await loadConfiguration();

    if (!config) {
      return {
        status: 'warning',
        message: 'No configuration loaded',
        details: null,
      };
    }

    // Validate configuration fields
    const issues: string[] = [];

    if (!config.provider) {
      issues.push('Missing provider');
    }

    if (!config.model) {
      issues.push('Missing model');
    }

    // Check API key for providers that require it
    const requiresApiKey = config.provider === 'openai' || config.provider === 'anthropic';
    if (requiresApiKey && !config.apiKey) {
      issues.push('Missing API key (required for this provider)');
    }

    if (config.provider === 'local' && !(config as any).apiEndpoint) {
      issues.push('Missing API endpoint for local provider');
    }

    if (issues.length > 0) {
      return {
        status: 'warning',
        message: 'Configuration has issues',
        details: {
          issues,
          config: {
            provider: config.provider,
            model: config.model,
            hasApiKey: !!config.apiKey,
            hasEndpoint: !!(config as any).apiEndpoint,
          },
        },
      };
    }

    return {
      status: 'pass',
      message: 'Configuration is valid',
      details: {
        provider: config.provider,
        model: config.model,
        hasApiKey: !!config.apiKey,
        streamingEnabled: config.streamingEnabled,
      },
    };
  } catch (error) {
    return {
      status: 'fail',
      message: 'Failed to load configuration',
      details: {
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Check encryption availability
 */
function checkEncryption(): DiagnosticCheck {
  try {
    const available = isCryptoAvailable();

    if (!available) {
      return {
        status: 'fail',
        message: 'Web Crypto API is not available',
        details: {
          cryptoAvailable: false,
          reason: 'Browser does not support Web Crypto API or running in insecure context',
        },
      };
    }

    // Check if encryption key exists in session storage
    const hasEncryptionKey = !!sessionStorage.getItem('storycore_encryption_key');

    if (!hasEncryptionKey) {
      return {
        status: 'warning',
        message: 'Encryption key not found in session',
        details: {
          cryptoAvailable: true,
          hasEncryptionKey: false,
          note: 'Key will be generated on first use',
        },
      };
    }

    return {
      status: 'pass',
      message: 'Encryption is available and configured',
      details: {
        cryptoAvailable: true,
        hasEncryptionKey: true,
      },
    };
  } catch (error) {
    return {
      status: 'fail',
      message: 'Encryption check failed',
      details: {
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Check LLM service connectivity
 */
async function checkConnectivity(): Promise<DiagnosticCheck> {
  try {
    const config = await loadConfiguration();

    if (!config) {
      return {
        status: 'warning',
        message: 'Cannot test connectivity without configuration',
        details: null,
      };
    }

    // Create temporary service instance
    const service = new LLMService(config);

    // Validate connection
    const result = await service.validateConnection();

    if (result.success && result.data) {
      return {
        status: 'pass',
        message: 'Successfully connected to LLM provider',
        details: {
          provider: config.provider,
          model: config.model,
          connected: true,
        },
      };
    } else {
      return {
        status: 'fail',
        message: 'Failed to connect to LLM provider',
        details: {
          provider: config.provider,
          model: config.model,
          error: result.error,
          connected: false,
        },
      };
    }
  } catch (error) {
    return {
      status: 'fail',
      message: 'Connectivity test failed',
      details: {
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Check Ollama availability
 */
async function checkOllama(): Promise<DiagnosticCheck> {
  try {
    const available = await checkOllamaStatus();

    if (available) {
      return {
        status: 'pass',
        message: 'Ollama is available',
        details: {
          available: true,
          endpoint: 'http://localhost:11434',
        },
      };
    } else {
      return {
        status: 'warning',
        message: 'Ollama is not available',
        details: {
          available: false,
          endpoint: 'http://localhost:11434',
          note: 'Install Ollama for local LLM support',
        },
      };
    }
  } catch (error) {
    return {
      status: 'warning',
      message: 'Could not check Ollama status',
      details: {
        error: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Generate recommendations based on diagnostic results
 */
function generateRecommendations(checks: DiagnosticResult['checks']): string[] {
  const recommendations: string[] = [];

  // Storage recommendations
  if (checks.storage.status === 'fail') {
    recommendations.push('Enable localStorage in your browser settings');
  } else if (checks.storage.status === 'warning') {
    recommendations.push('Configure LLM settings to enable AI features');
  }

  // Configuration recommendations
  if (checks.configuration.status === 'fail') {
    recommendations.push('Reconfigure LLM settings - current configuration is invalid');
  } else if (checks.configuration.status === 'warning') {
    const details = checks.configuration.details as any;
    if (details?.issues) {
      recommendations.push(...details.issues.map((issue: string) => `Fix: ${issue}`));
    }
  }

  // Encryption recommendations
  if (checks.encryption.status === 'fail') {
    recommendations.push('Use a modern browser with Web Crypto API support');
    recommendations.push('Ensure the application is served over HTTPS');
  }

  // Connectivity recommendations
  if (checks.connectivity.status === 'fail') {
    const details = checks.connectivity.details as any;
    if (details?.provider === 'local') {
      recommendations.push('Start Ollama service: ollama serve');
    } else if (details?.provider === 'openai' || details?.provider === 'anthropic') {
      recommendations.push('Verify your API key is valid and has sufficient credits');
      recommendations.push('Check your internet connection');
    }
  }

  // Ollama recommendations
  if (checks.ollama.status === 'warning') {
    recommendations.push('Install Ollama for free local LLM support: https://ollama.ai');
  }

  // General recommendations
  if (recommendations.length === 0) {
    recommendations.push('LLM service is healthy and ready to use');
  }

  return recommendations;
}

/**
 * Determine overall health status
 */
function determineOverallStatus(checks: DiagnosticResult['checks']): 'healthy' | 'warning' | 'error' {
  const statuses = Object.values(checks).map(check => check.status);

  if (statuses.includes('fail')) {
    return 'error';
  }

  if (statuses.includes('warning')) {
    return 'warning';
  }

  return 'healthy';
}

