/**
 * LLM Response Parser Utility
 * 
 * Provides robust parsing for LLM responses with development-only logging
 * and fallback strategies for handling various response formats.
 */

import { logger } from './logger';
import { devLog, devWarn } from './devOnly';

/**
 * Parse JSON from LLM response with detailed logging
 * Handles empty responses, malformed JSON, and various edge cases
 */
export function parseLLMJSON<T = any>(
  response: string,
  context: string = 'LLM Response'
): T | null {
  devLog(`🔍 [${context}] Raw response:`, response);
  devLog(`🔍 [${context}] Response length:`, response?.length || 0);

  if (!response || response.trim().length === 0) {
    devWarn(`⚠️ [${context}] Empty response received`);
    return null;
  }

  try {
    const trimmed = response.trim();
    devLog(`🔍 [${context}] Trimmed response (first 100 chars):`, trimmed.substring(0, 100));

    // Try to find JSON array or object
    const jsonMatch = trimmed.match(/(\[[\s\S]*\]|\{[\s\S]*\})/);
    if (jsonMatch) {
      devLog(`📦 [${context}] Found JSON match`);
      try {
        const parsed = JSON.parse(jsonMatch[0]);
        devLog(`✅ [${context}] Successfully parsed JSON:`, parsed);
        return parsed as T;
      } catch (jsonError) {
        logger.error(`❌ [${context}] JSON parsing failed:`, jsonError);
        logger.error(`❌ [${context}] Failed JSON string:`, jsonMatch[0].substring(0, 200));
      }
    } else {
      devWarn(`⚠️ [${context}] No JSON object found in response`);
      devLog(`🔍 [${context}] Response starts with:`, trimmed.substring(0, 100));
    }
  } catch (error) {
    logger.error(`❌ [${context}] Unexpected error:`, error);
  }

  return null;
}

/**
 * Parse array of items from LLM response
 */
export function parseLLMArray<T = any>(
  response: string,
  context: string = 'LLM Array Response'
): T[] {
  const parsed = parseLLMJSON<T[] | T>(response, context);

  if (!parsed) {
    return [];
  }

  // If it's already an array, return it
  if (Array.isArray(parsed)) {
    devLog(`✨ [${context}] Extracted array with ${parsed.length} items`);
    return parsed;
  }

  // If it's a single object, wrap it in an array
  devLog(`✨ [${context}] Wrapped single object in array`);
  return [parsed];
}

/**
 * Parse object from LLM response
 */
export function parseLLMObject<T = any>(
  response: string,
  context: string = 'LLM Object Response'
): T | null {
  const parsed = parseLLMJSON<T | T[]>(response, context);

  if (!parsed) {
    return null;
  }

  // If it's an array, take the first element
  if (Array.isArray(parsed)) {
    devLog(`✨ [${context}] Extracted first object from array`);
    return parsed[0] || null;
  }

  // If it's already an object, return it
  devLog(`✨ [${context}] Extracted object`);
  return parsed as T;
}

/**
 * Validate that response is not empty (for debugging)
 */
export function validateLLMResponse(response: string, context: string = 'LLM Response'): boolean {
  if (!response || response.trim().length === 0) {
    logger.error(`❌ [${context}] Response is empty!`);
    logger.error(`❌ [${context}] This usually means the LLM model has extended thinking enabled`);
    logger.error(`❌ [${context}] and is consuming all tokens without producing output.`);
    logger.error(`❌ [${context}] Try using a different model like llama3.1:8b instead of qwen3-vl`);
    return false;
  }

  devLog(`✅ [${context}] Response is valid (${response.length} chars)`);
  return true;
}

/**
 * Extract text content from LLM response (for non-JSON responses)
 */
export function extractLLMText(response: string, context: string = 'LLM Text Response'): string {
  devLog(`🔍 [${context}] Extracting text from response`);

  if (!response || response.trim().length === 0) {
    devWarn(`⚠️ [${context}] Empty response`);
    return '';
  }

  const trimmed = response.trim();
  devLog(`✨ [${context}] Extracted text (${trimmed.length} chars)`);
  return trimmed;
}

/**
 * Parse comma-separated values from LLM response
 */
export function parseLLMCSV(response: string, context: string = 'LLM CSV Response'): string[] {
  devLog(`🔍 [${context}] Parsing CSV from response`);

  if (!response || response.trim().length === 0) {
    devWarn(`⚠️ [${context}] Empty response`);
    return [];
  }

  const items = response
    .split(/[,\n]/)
    .map(item => item.trim())
    .filter(item => item.length > 0);

  devLog(`✨ [${context}] Extracted ${items.length} items`);
  return items;
}

/**
 * Parse numbered list from LLM response
 */
export function parseLLMNumberedList(response: string, context: string = 'LLM List Response'): string[] {
  devLog(`🔍 [${context}] Parsing numbered list from response`);

  if (!response || response.trim().length === 0) {
    devWarn(`⚠️ [${context}] Empty response`);
    return [];
  }

  const items: string[] = [];
  const lines = response.split('\n');

  for (const line of lines) {
    const match = line.match(/^\d+\.\s*(.+)$/);
    if (match) {
      items.push(match[1].trim());
    }
  }

  devLog(`✨ [${context}] Extracted ${items.length} items from numbered list`);
  return items;
}

/**
 * Memoization utilities for expensive computations
 */

import { debounce, throttle } from './debounceAndThrottle';

// Re-export debounce and throttle from unified module
export { debounce, throttle };

// Using 'any' in generic constraint to allow memoizing functions with any parameter types and return values
type MemoizedFunction<T extends (...args: any[]) => any> = T & {
  cache: Map<string, ReturnType<T>>;
  clearCache: () => void;
};

/**
 * Memoize a function with custom key generation
 */
// Using 'any' in generic constraint to allow memoizing functions with any parameter types
export function memoize<T extends (...args: any[]) => any>(
  fn: T,
  keyGenerator?: (...args: Parameters<T>) => string
): MemoizedFunction<T> {
  const cache = new Map<string, ReturnType<T>>();

  const memoized = ((...args: Parameters<T>) => {
    const key = keyGenerator ? keyGenerator(...args) : JSON.stringify(args);

    if (cache.has(key)) {
      return cache.get(key)!;
    }

    const result = fn(...args);
    cache.set(key, result);
    return result;
  }) as MemoizedFunction<T>;

  memoized.cache = cache;
  memoized.clearCache = () => cache.clear();

  return memoized;
}

/**
 * Memoize async functions
 */
// Using 'any' in generic constraint to allow memoizing async functions with any parameter and return types
export function memoizeAsync<T extends (...args: any[]) => Promise<any>>(
  fn: T,
  keyGenerator?: (...args: Parameters<T>) => string
): MemoizedFunction<T> {
  const cache = new Map<string, ReturnType<T>>();
  const pending = new Map<string, ReturnType<T>>();

  const memoized = (async (...args: Parameters<T>) => {
    const key = keyGenerator ? keyGenerator(...args) : JSON.stringify(args);

    // Return cached result
    if (cache.has(key)) {
      return cache.get(key)!;
    }

    // Return pending promise if already in progress
    if (pending.has(key)) {
      return pending.get(key)!;
    }

    // Execute and cache
    const promise = fn(...args);
    pending.set(key, promise as ReturnType<T>);

    try {
      const result = await promise;
      cache.set(key, Promise.resolve(result) as ReturnType<T>);
      return result;
    } finally {
      pending.delete(key);
    }
  }) as MemoizedFunction<T>;

  memoized.cache = cache;
  memoized.clearCache = () => {
    cache.clear();
    pending.clear();
  };

  return memoized;
}

/**
 * LRU (Least Recently Used) cache implementation
 */
export class LRUCache<K, V> {
  private cache: Map<K, V>;
  private maxSize: number;

  constructor(maxSize: number = 100) {
    this.cache = new Map();
    this.maxSize = maxSize;
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move to end (most recently used)
    const value = this.cache.get(key)!;
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  set(key: K, value: V): void {
    // Remove if exists
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }

    // Add to end
    this.cache.set(key, value);

    // Remove oldest if over capacity
    if (this.cache.size > this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) {
        this.cache.delete(firstKey);
      }
    }
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  clear(): void {
    this.cache.clear();
  }

  get size(): number {
    return this.cache.size;
  }
}

/**
 * Menu Navigation Utilities
 * 
 * Shared utilities for menu keyboard navigation and item management.
 * This module provides reusable functions for:
 * - Finding next/previous enabled menu items
 * - Getting first/last enabled item indices
 * - Filtering menu items (skipping separators and disabled items)
 * 
 * Used by MenuDropdown and other menu components.
 */

import type { MenuItemConfig } from '../types/menuConfig';
import type { MenuItemProps } from '../components/menuBar/MenuItem';

/**
 * Check if a menu item is a regular item (not a separator)
 */
export function isRegularMenuItem(
  item: MenuItemConfig | (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true })
): item is Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> {
  return !('separator' in item);
}

/**
 * Check if a menu item is enabled (not a separator and not disabled)
 */
export function isMenuItemEnabled(
  item: MenuItemConfig | (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true })
): boolean {
  return isRegularMenuItem(item) && item.enabled !== false;
}

/**
 * Find the index of the next enabled menu item
 */
export function getNextEnabledItemIndex(
  items: (MenuItemConfig | (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true }))[],
  currentIndex: number,
  direction: 'next' | 'previous'
): number {
  const enabledItems = items
    .map((item, index) => ({ ...item, index }))
    .filter((item) => isMenuItemEnabled(item));

  if (enabledItems.length === 0) return currentIndex;

  const currentEnabledIndex = enabledItems.findIndex(
    (item) => item.index === currentIndex
  );

  if (direction === 'next') {
    const nextIndex =
      currentEnabledIndex === -1 || currentEnabledIndex === enabledItems.length - 1
        ? 0
        : currentEnabledIndex + 1;
    return enabledItems[nextIndex].index;
  } else {
    const prevIndex =
      currentEnabledIndex === -1 || currentEnabledIndex === 0
        ? enabledItems.length - 1
        : currentEnabledIndex - 1;
    return enabledItems[prevIndex].index;
  }
}

/**
 * Find the index of the first enabled menu item
 */
export function getFirstEnabledItemIndex(
  items: (MenuItemConfig | (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true }))[]
): number {
  const firstEnabled = items.findIndex((item) => isMenuItemEnabled(item));
  return firstEnabled === -1 ? 0 : firstEnabled;
}

/**
 * Find the index of the last enabled menu item
 */
export function getLastEnabledItemIndex(
  items: (MenuItemConfig | (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true }))[]
): number {
  for (let i = items.length - 1; i >= 0; i--) {
    if (isMenuItemEnabled(items[i])) {
      return i;
    }
  }
  return items.length - 1;
}

/**
 * Get all enabled menu items with their indices
 */
export function getEnabledItems<T>(
  items: T[]
): Array<{ item: T; index: number }> {
  return items
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => isMenuItemEnabled(item as any));
}

/**
 * Navigate to the next enabled item (wraps around)
 */
export function navigateToNextItem<T>(
  items: T[],
  currentIndex: number
): number {
  return getNextEnabledItemIndex(items as any, currentIndex, 'next');
}

/**
 * Navigate to the previous enabled item (wraps around)
 */
export function navigateToPreviousItem<T>(
  items: T[],
  currentIndex: number
): number {
  return getNextEnabledItemIndex(items as any, currentIndex, 'previous');
}

/**
 * Navigate to the first enabled item
 */
export function navigateToFirstItem<T>(items: T[]): number {
  return getFirstEnabledItemIndex(items as any);
}

/**
 * Navigate to the last enabled item
 */
export function navigateToLastItem<T>(items: T[]): number {
  return getLastEnabledItemIndex(items as any);
}

/**
 * Find item index by first letter (for quick navigation)
 * Handles items with separators
 */
export function findMenuItemByFirstLetter(
  items: (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true })[],
  letter: string,
  startIndex: number = 0
): number {
  const lowerLetter = letter.toLowerCase();
  
  // Search from startIndex to end
  for (let i = startIndex; i < items.length; i++) {
    const item = items[i];
    if (isRegularMenuItem(item) && item.label?.toLowerCase().startsWith(lowerLetter)) {
      return i;
    }
  }
  
  // Wrap around to beginning
  for (let i = 0; i < startIndex; i++) {
    const item = items[i];
    if (isRegularMenuItem(item) && item.label?.toLowerCase().startsWith(lowerLetter)) {
      return i;
    }
  }
  
  return -1;
}

/**
 * LLM Configuration Migration Utility
 * 
 * Migrates LLM configuration from old storage systems to the new unified system.
 * Handles three legacy storage formats:
 * 1. llmConfigStorage (storycore_llm_config)
 * 2. settingsPropagation (llm-config)
 * 3. Partial secureStorage (storycore-settings without LLM)
 */

import { loadLLMSettings, saveLLMSettings } from './secureStorage';
import type { LLMConfig } from '@/services/llmService';

// ============================================================================
// Migration Functions
// ============================================================================

/**
 * Migrate LLM configuration from legacy storage systems
 * Returns true if migration was performed
 */
export async function migrateLLMConfig(): Promise<boolean> {
  try {

    // Check if new system already has configuration
    const newConfig = await loadLLMSettings();
    if (newConfig) {
      return false;
    }

    // Try to find configuration in legacy systems
    const migratedConfig = await findLegacyConfig();
    
    if (!migratedConfig) {
      return false;
    }

    // Save to new system
    await saveLLMSettings(migratedConfig);

    // Clean up legacy storage
    cleanupLegacyStorage();

    return true;
  } catch (error) {
    console.error('[Migration] Failed to migrate LLM config:', error);
    return false;
  }
}

/**
 * Find configuration in legacy storage systems
 * Priority: llmConfigStorage > settingsPropagation > default
 */
async function findLegacyConfig(): Promise<LLMConfig | null> {
  // Try llmConfigStorage (System 1)
  const config1 = await loadFromLLMConfigStorage();
  if (config1) {
    return config1;
  }

  // Try settingsPropagation (System 3)
  const config3 = loadFromSettingsPropagation();
  if (config3) {
    return config3;
  }

  return null;
}

/**
 * Load configuration from llmConfigStorage (System 1)
 */
async function loadFromLLMConfigStorage(): Promise<LLMConfig | null> {
  try {
    const configJson = localStorage.getItem('storycore_llm_config');
    const encryptedApiKey = localStorage.getItem('storycore_api_key_enc');

    if (!configJson) {
      return null;
    }

    const stored = JSON.parse(configJson);
    
    // Decrypt API key if present
    let apiKey = '';
    if (encryptedApiKey) {
      try {
        // Try to decrypt using the old system
        apiKey = await decryptLegacyAPIKey(encryptedApiKey);
      } catch (error) {
        console.warn('[Migration] Failed to decrypt API key:', error);
        // Continue without API key - user will need to re-enter
      }
    }

    // Convert to full LLMConfig
    return {
      provider: stored.provider || 'local',
      model: stored.model || 'gemma2:2b',
      apiKey,
      apiEndpoint: stored.provider === 'local' ? 'http://localhost:11434' : undefined,
      parameters: {
        temperature: stored.temperature || 0.7,
        maxTokens: stored.maxTokens || 2000,
        topP: 1,
        frequencyPenalty: 0,
        presencePenalty: 0,
      },
      systemPrompts: {
        worldGeneration: '',
        characterGeneration: '',
        dialogueGeneration: '',
      },
      timeout: 30000,
      retryAttempts: 3,
      streamingEnabled: stored.streamingEnabled !== false,
    };
  } catch (error) {
    console.error('[Migration] Error loading from llmConfigStorage:', error);
    return null;
  }
