const SETTINGS_STORAGE_KEY = 'storycore-settings';
const SETTINGS_VERSION = '1.0';
const ENCRYPTION_ALGORITHM = 'AES-GCM';
const KEY_LENGTH = 256;

// ============================================================================
// Encryption Key Management
// ============================================================================

/**
 * Generate or retrieve encryption key from session storage
 * Key is session-specific for security
 */
async function getEncryptionKey(): Promise<CryptoKey> {
  // Check if key exists in session storage
  const storedKey = sessionStorage.getItem('encryption-key');

  if (storedKey) {
    try {
      const keyData = JSON.parse(storedKey);
      return await crypto.subtle.importKey(
        'jwk',
        keyData,
        { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
        true,
        ['encrypt', 'decrypt']
      );
    } catch (error) {
      console.warn('Failed to import stored key, generating new one');
    }
  }

  // Generate new key
  const key = await crypto.subtle.generateKey(
    { name: ENCRYPTION_ALGORITHM, length: KEY_LENGTH },
    true,
    ['encrypt', 'decrypt']
  );

  // Store key in session storage
  const exportedKey = await crypto.subtle.exportKey('jwk', key);
  sessionStorage.setItem('encryption-key', JSON.stringify(exportedKey));

  return key;
}

// ============================================================================
// Encryption Functions
// ============================================================================

/**
 * Encrypt a string value using Web Crypto API
 */
export async function encryptValue(value: string): Promise<EncryptionResult> {
  try {
    const key = await getEncryptionKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const encoder = new TextEncoder();
    const data = encoder.encode(value);

    const encrypted = await crypto.subtle.encrypt(
      { name: ENCRYPTION_ALGORITHM, iv },
      key,
      data
    );

    // Convert to base64 for storage
    const encryptedArray = new Uint8Array(encrypted);
    const encryptedBase64 = btoa(String.fromCharCode(...encryptedArray));
    const ivBase64 = btoa(String.fromCharCode(...iv));

    return {
      encrypted: encryptedBase64,
      iv: ivBase64,
    };
  } catch (error) {
    console.error('Encryption failed:', error);
    throw new Error('Failed to encrypt value');
  }
}

/**
 * Decrypt a string value using Web Crypto API
 */
export async function decryptValue(encrypted: string, iv: string): Promise<string> {
  try {
    const key = await getEncryptionKey();

    // Validate inputs
    if (!encrypted || !iv) {
      throw new Error('Missing encrypted data or IV');
    }

    // Validate base64 format
    try {
      atob(encrypted);
      atob(iv);
    } catch {
      throw new Error('Invalid base64 format');
    }

    // Convert from base64
    const encryptedArray = Uint8Array.from(atob(encrypted), c => c.charCodeAt(0));
    const ivArray = Uint8Array.from(atob(iv), c => c.charCodeAt(0));

    const decrypted = await crypto.subtle.decrypt(
      { name: ENCRYPTION_ALGORITHM, iv: ivArray },
      key,
      encryptedArray
    );

    const decoder = new TextDecoder();
    return decoder.decode(decrypted);
  } catch (error) {
    // Silently handle decryption failures - this is expected when session expires
    // The calling code will handle clearing corrupted settings
    if (error instanceof DOMException && error.name === 'OperationError') {
      // This is a normal case when encryption key doesn't match (session expired)
      throw new Error('DECRYPTION_KEY_MISMATCH');
    }

    if (error instanceof Error) {
      if (error.message.includes('operation-specific reason')) {
        throw new Error('DECRYPTION_KEY_MISMATCH');
      }
      throw new Error(`Failed to decrypt value: ${error.message}`);
    }
    throw new Error('Failed to decrypt value');
  }
}

/**
 * Check if a value is encrypted (has the expected format)
 */
export function isEncrypted(value: string): boolean {
  try {
    // Encrypted values should be valid base64
    atob(value);
    return true;
  } catch {
    return false;
  }
}

// ============================================================================
// Settings Storage Functions
// ============================================================================

/**
 * Save LLM settings with encrypted API key
 */
export async function saveLLMSettings(config: LLMConfig): Promise<void> {
  try {
    // Load existing settings
    const settings = loadSettings();

    // Encrypt API key
    const { encrypted, iv } = await encryptValue(config.apiKey);

    // Store config without API key, plus encrypted API key
    const { apiKey, ...configWithoutKey } = config;

    settings.llm = {
      config: configWithoutKey,
      encryptedApiKey: `${encrypted}:${iv}`,
      lastValidated: new Date().toISOString(),
    };

    // Save to localStorage
    localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
  } catch (error) {
    console.error('Failed to save LLM settings:', error);
    throw new Error('Failed to save settings. Please try again.');
  }
}

/**
 * Load LLM settings and decrypt API key
 */
export async function loadLLMSettings(): Promise<LLMConfig | null> {
  try {
    const settings = loadSettings();

    if (!settings.llm) {
      return null;
    }

    // Decrypt API key
    let apiKey = '';
    if (settings.llm.encryptedApiKey) {
      try {
        const [encrypted, iv] = settings.llm.encryptedApiKey.split(':');
        if (!encrypted || !iv) {
          console.warn('Invalid encrypted data format, clearing settings');
          deleteLLMSettings();
          return null;
        }
        apiKey = await decryptValue(encrypted, iv);
      } catch (decryptError) {
        // Check if it's a key mismatch (expected when session expires)
        if (decryptError instanceof Error && decryptError.message === 'DECRYPTION_KEY_MISMATCH') {
          console.info('Session expired - settings need to be re-entered');
        } else {
          console.warn('Failed to decrypt API key:', decryptError);
        }
        // Clear corrupted settings and reset encryption key
        deleteLLMSettings();
        resetEncryptionKey();
        return null;
      }
    }

    // Reconstruct full config with defaults for missing fields
    const config = {
      ...settings.llm.config,
      apiKey,
    } as LLMConfig;

    // Ensure systemPrompts exists with defaults if missing
    if (!config.systemPrompts) {
      const { getDefaultSystemPrompts } = await import('@/services/llmService');
      config.systemPrompts = getDefaultSystemPrompts();
    }

    return config;
  } catch (error) {
    console.error('Failed to load LLM settings:', error);
    return null;
  }
}

/**
 * Delete LLM settings securely
 */
export function deleteLLMSettings(): void {
  try {
    const settings = loadSettings();
    delete settings.llm;
    localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
  } catch (error) {
    console.error('Failed to delete LLM settings:', error);
    throw new Error('Failed to delete settings');
  }
}

/**
 * Export settings without credentials
 */
export function exportSettings(): string {
  try {
    const settings = loadSettings();

    // Create export object without encrypted credentials
    // Using 'any' to allow dynamic property assignment based on available settings
    const exportData: any = {
      version: settings.version,
    };

    if (settings.llm) {
      exportData.llm = {
        config: settings.llm.config,
        // Exclude encryptedApiKey
      };
    }

    if (settings.comfyui) {
      exportData.comfyui = {
        config: settings.comfyui.config,
        // Exclude encryptedCredentials
      };
    }

    return JSON.stringify(exportData, null, 2);
  } catch (error) {
    console.error('Failed to export settings:', error);
    throw new Error('Failed to export settings');
  }
}

/**
 * Import settings (without credentials)
 */
export function importSettings(jsonData: string): boolean {
  try {
    const importedData = JSON.parse(jsonData);

    // Validate structure
    if (!importedData.version) {
      throw new Error('Invalid settings format: missing version');
    }

    const settings = loadSettings();

    // Merge imported settings (preserving encrypted credentials)
    if (importedData.llm) {
      settings.llm = {
        ...settings.llm,
        config: importedData.llm.config,
      };
    }

    if (importedData.comfyui) {
      settings.comfyui = {
        ...settings.comfyui,
        config: importedData.comfyui.config,
      };
    }

    localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
    return true;
  } catch (error) {
    console.error('Failed to import settings:', error);
    return false;
  }
}

/**
 * Clear all settings securely
 */
export function clearAllSettings(): void {
  try {
    localStorage.removeItem(SETTINGS_STORAGE_KEY);
    sessionStorage.removeItem('encryption-key');
  } catch (error) {
    console.error('Failed to clear settings:', error);
    throw new Error('Failed to clear settings');
  }
}

/**
 * Reset encryption key (useful when decryption fails due to corrupted key)
 */
export function resetEncryptionKey(): void {
  try {
    sessionStorage.removeItem('encryption-key');
  } catch (error) {
    console.error('Failed to reset encryption key:', error);
  }
}

// ============================================================================
// Internal Helper Functions
// ============================================================================

/**
 * Load settings from localStorage
 */
function loadSettings(): StoredSettings {
  try {
    const stored = localStorage.getItem(SETTINGS_STORAGE_KEY);

    if (!stored) {
      return {
        version: SETTINGS_VERSION,
      };
    }

    const settings = JSON.parse(stored) as StoredSettings;

    // Validate version
    if (settings.version !== SETTINGS_VERSION) {
      console.warn('Settings version mismatch, migrating...');
      // In the future, add migration logic here
    }

    return settings;
  } catch (error) {
    console.error('Failed to load settings:', error);
    return {
      version: SETTINGS_VERSION,
    };
  }
}

/**
 * Check if Web Crypto API is available
 */
export function isCryptoAvailable(): boolean {
  return typeof crypto !== 'undefined' &&
    typeof crypto.subtle !== 'undefined' &&
    typeof crypto.subtle.encrypt === 'function';
}

/**
 * Check if settings exist
 */
export function hasStoredSettings(): boolean {
  const settings = loadSettings();
  return !!(settings.llm || settings.comfyui);
}

/**
 * Get last validation timestamp for LLM settings
 */
export function getLastValidationTime(): Date | null {
  const settings = loadSettings();
  if (settings.llm?.lastValidated) {
    return new Date(settings.llm.lastValidated);
  }
  return null;
}

/**
 * Shot Deletion Utilities
 * 
 * Provides helper functions for shot deletion operations, including
 * validation, phrase handling, and orphan detection.
 * 
 * Requirements: 7.3
 */

import type { Shot, DialoguePhrase, Project } from '../types/projectDashboard';

/**
 * Result of shot deletion validation
 */
export interface ShotDeletionValidation {
  canDelete: boolean;
  errors: string[];
  warnings: string[];
  associatedPhrases: DialoguePhrase[];
  affectedSequences: string[];
}

/**
 * Options for shot deletion
 */
export interface ShotDeletionOptions {
  /** Whether to delete associated phrases (true) or unlink them (false) */
  deletePhrases: boolean;
  /** Whether to skip confirmation dialog */
  skipConfirmation?: boolean;
}

/**
 * Validates that a shot can be deleted
 * Checks for associated phrases and sequences
 * 
 * Requirement 7.3: WHEN a user deletes a shot, THE Project_Dashboard SHALL 
 * prompt for confirmation and optionally remove associated dialogue phrases
 * 
 * @param shotId - ID of the shot to delete
 * @param project - Current project state
 * @returns Validation result with associated data
 */
export function validateShotDeletion(
  shotId: string,
  project: Project
): ShotDeletionValidation {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Check if shot exists
  const shot = project.shots.find(s => s.id === shotId);
  if (!shot) {
    errors.push(`Shot with id ${shotId} not found`);
    return {
      canDelete: false,
      errors,
      warnings,
      associatedPhrases: [],
      affectedSequences: [],
    };
  }

  // Find associated dialogue phrases
  const associatedPhrases = project.audioPhrases.filter(
    phrase => phrase.shotId === shotId
  );

  // Find sequences containing this shot
  const affectedSequences = project.sequences
    .filter(seq => seq.shotIds.includes(shotId))
    .map(seq => seq.id);

  // Add warnings
  if (associatedPhrases.length > 0) {
    warnings.push(
      `This shot has ${associatedPhrases.length} associated dialogue ${
        associatedPhrases.length === 1 ? 'phrase' : 'phrases'
      }`
    );
  }

  if (affectedSequences.length > 0) {
    warnings.push(
      `This shot is part of ${affectedSequences.length} ${
        affectedSequences.length === 1 ? 'sequence' : 'sequences'
      }`
    );
  }

  return {
    canDelete: errors.length === 0,
    errors,
    warnings,
    associatedPhrases,
    affectedSequences,
  };
}

/**
 * Gets all dialogue phrases associated with a shot
 * 
 * @param shotId - ID of the shot
 * @param phrases - All dialogue phrases in the project
 * @returns Array of associated phrases
 */
export function getAssociatedPhrases(
  shotId: string,
  phrases: DialoguePhrase[]
): DialoguePhrase[] {
  return phrases.filter(phrase => phrase.shotId === shotId);
}

/**
 * Checks for orphaned phrase references in the project
 * An orphaned phrase is one that references a non-existent shot
 * 
 * Requirement 7.3: Ensure no orphaned phrase references remain
 * 
 * @param project - Current project state
 * @returns Array of orphaned phrases
 */
export function detectOrphanedPhrases(project: Project): DialoguePhrase[] {
  const shotIds = new Set(project.shots.map(shot => shot.id));
  
  return project.audioPhrases.filter(phrase => {
    // Empty shotId is allowed (unlinked phrase)
    if (phrase.shotId === '') return false;
    
    // Check if referenced shot exists
    return !shotIds.has(phrase.shotId);
  });
}

/**
 * Validates that no orphaned phrases exist after a deletion operation
 * 
 * @param project - Project state after deletion
 * @returns True if no orphaned phrases exist
 */
export function validateNoOrphanedPhrases(project: Project): boolean {
  const orphanedPhrases = detectOrphanedPhrases(project);
  return orphanedPhrases.length === 0;
}

/**
 * Simulates shot deletion and returns the resulting project state
 * Useful for preview or validation before actual deletion
 * 
 * @param shotId - ID of the shot to delete
 * @param project - Current project state
 * @param options - Deletion options
 * @returns Simulated project state after deletion
 */
export function simulateShotDeletion(
  shotId: string,
  project: Project,
  options: ShotDeletionOptions
): Project {
  // Remove the shot
  const updatedShots = project.shots.filter(shot => shot.id !== shotId);

  // Handle associated phrases
  let updatedPhrases: DialoguePhrase[];
  
  if (options.deletePhrases) {
    // Delete all phrases linked to this shot
    updatedPhrases = project.audioPhrases.filter(
      phrase => phrase.shotId !== shotId
    );
  } else {
    // Unlink phrases by setting shotId to empty string
    updatedPhrases = project.audioPhrases.map(phrase =>
      phrase.shotId === shotId
        ? { ...phrase, shotId: '' }
        : phrase
    );
  }

  // Remove shot from sequences
  const updatedSequences = project.sequences.map(sequence => ({
    ...sequence,
    shotIds: sequence.shotIds.filter(id => id !== shotId),
  }));

  return {
    ...project,
    shots: updatedShots,
    audioPhrases: updatedPhrases,
    sequences: updatedSequences,
  };
}

/**
 * Gets a summary of what will be affected by shot deletion
 * Useful for displaying in confirmation dialogs
 * 
 * @param shotId - ID of the shot to delete
 * @param project - Current project state
 * @param options - Deletion options
 * @returns Summary object with counts and details
 */
export function getShotDeletionSummary(
  shotId: string,
  project: Project,
  options: ShotDeletionOptions
): {
  shotId: string;
  phraseCount: number;
  phrasesWillBeDeleted: boolean;
  sequenceCount: number;
  sequenceNames: string[];
} {
  const validation = validateShotDeletion(shotId, project);

  return {
    shotId,
    phraseCount: validation.associatedPhrases.length,
    phrasesWillBeDeleted: options.deletePhrases,
    sequenceCount: validation.affectedSequences.length,
    sequenceNames: project.sequences
      .filter(seq => validation.affectedSequences.includes(seq.id))
      .map(seq => seq.name),
  };
}

/**
 * Validates the integrity of shot-phrase relationships in a project
 * Ensures all phrase references are valid
 * 
 * @param project - Project to validate
 * @returns Validation result with any issues found
 */
export function validateShotPhraseIntegrity(project: Project): {
  isValid: boolean;
  orphanedPhrases: DialoguePhrase[];
  errors: string[];
} {
  const orphanedPhrases = detectOrphanedPhrases(project);
  const errors: string[] = [];

  if (orphanedPhrases.length > 0) {
    errors.push(
      `Found ${orphanedPhrases.length} orphaned phrase(s) referencing non-existent shots`
    );
    orphanedPhrases.forEach(phrase => {
      errors.push(
        `Phrase ${phrase.id} references non-existent shot ${phrase.shotId}`
      );
    });
  }

  return {
    isValid: orphanedPhrases.length === 0,
    orphanedPhrases,
    errors,
  };
}

/**
 * StorageBatchingManager - Optimizes storage operations by batching writes
 * Reduces storage warnings and improves performance during bulk operations
 */

interface BatchEntry {
  key: string;
  value: unknown;
  timestamp: number;
}

class StorageBatchingManager {
  private static pendingWrites = new Map<string, BatchEntry>();
  private static flushTimer: ReturnType<typeof setTimeout> | null = null;
  private static readonly FLUSH_DELAY_MS = 100;
  private static readonly MAX_BATCH_SIZE = 50;

  /**
   * Queue a write operation to be batched
   */
  static queueWrite(key: string, value: unknown): void {
    // Don't batch critical writes
    if (this.isCriticalKey(key)) {
      this.writeImmediate(key, value);
      return;
    }

    this.pendingWrites.set(key, {
      key,
      value,
      timestamp: Date.now(),
    });

    // Start flush timer if not already running
    if (!this.flushTimer) {
      this.flushTimer = setTimeout(() => this.flush(), this.FLUSH_DELAY_MS);
    }

    // Log storage usage warning if approaching limit
    this.logStorageUsage();
  }

  /**
   * Flush all pending writes to storage
   */
  private static async flush(): Promise<void> {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }

    const entries = Array.from(this.pendingWrites.values());
    
    if (entries.length === 0) return;

    // Process in batches to avoid blocking
    const batchSize = Math.min(this.MAX_BATCH_SIZE, entries.length);
    const batch = entries.slice(0, batchSize);

    for (const entry of batch) {
      try {
        await this.writeToStorage(entry.key, entry.value);
        this.pendingWrites.delete(entry.key);
      } catch (error) {
        console.error(`[StorageBatching] Failed to write ${entry.key}:`, error);
      }
    }

    // If more entries remain, schedule another flush
    if (this.pendingWrites.size > 0) {
      this.flushTimer = setTimeout(() => this.flush(), this.FLUSH_DELAY_MS);
    }
  }

  /**
   * Write directly to storage (critical operations)
   */
  private static writeImmediate(key: string, value: unknown): void {
    try {
      this.writeToStorage(key, value);
    } catch (error) {
      console.error(`[StorageBatching] Immediate write failed for ${key}:`, error);
    }
  }

  /**
   * Actual storage write with encoding
   */
  private static async writeToStorage(key: string, value: unknown): Promise<void> {
    const serialized = JSON.stringify(value);
    
    if (window.electronAPI?.fs) {
      // Use Electron API if available
      const encoder = new TextEncoder();
      const uint8Array = encoder.encode(serialized);
      await window.electronAPI.fs.writeFile(key, uint8Array as any);
    } else {
      // Fallback to localStorage
      localStorage.setItem(key, serialized);
    }
  }

  /**
   * Check if key is critical and should not be batched
   */
  private static isCriticalKey(key: string): boolean {
    const criticalPatterns = [
      'current-project',
      'last-opened',
      'user-preferences',
      'temp-',
    ];

    return criticalPatterns.some(pattern => key.includes(pattern));
  }

  /**
   * Log current storage usage
   */
  private static logStorageUsage(): void {
    try {
      let totalUsed = 0;
      
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key) {
          totalUsed += new Blob([localStorage.getItem(key) || '']).size;
        }
      }

      const limit = 5 * 1024 * 1024; // 5MB default limit
      const percentage = (totalUsed / limit) * 100;

      if (percentage > 10) {
        console.warn(
          `[StorageBatching] Storage usage at ${percentage.toFixed(1)}% ` +
          `{used: ${totalUsed}, limit: ${limit}}`
        );
      }
    } catch (error) {
      // Ignore errors during usage logging
    }
  }

  /**
   * Get count of pending writes
   */
  static getPendingCount(): number {
    return this.pendingWrites.size;
  }

  /**
   * Clear all pending writes (for cleanup)
   */
  static clear(): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    this.pendingWrites.clear();
  }
}

export { StorageBatchingManager };

/**
 * Storage Manager - Gère localStorage avec limite de taille
 * Bascule vers IndexedDB si localStorage est plein
 */

const STORAGE_LIMIT = 5 * 1024 * 1024; // 5MB
const STORAGE_WARNING_THRESHOLD = 0.8; // 80%

export interface StorageStats {
  used: number;
  limit: number;
  percentage: number;
  available: number;
}

export class StorageManager {
  private static getStorageSize(): number {
    let size = 0;
    try {
      for (const key in localStorage) {
        if (localStorage.hasOwnProperty(key)) {
          size += localStorage[key].length + key.length;
        }
      }
    } catch (error) {
      console.error('Failed to calculate storage size:', error);
    }
    return size;
  }

  static getStats(): StorageStats {
    const used = this.getStorageSize();
    const limit = STORAGE_LIMIT;
    const percentage = (used / limit) * 100;
    const available = limit - used;

    return { used, limit, percentage, available };
  }

  static canStore(data: string): boolean {
    const stats = this.getStats();
    const dataSize = data.length;
    return stats.available > dataSize;
  }

  static setItem(key: string, value: string): boolean {
    try {
      const stats = this.getStats();
      
      // Avertissement si proche de la limite
      if (stats.percentage > STORAGE_WARNING_THRESHOLD) {
        console.warn(
          `⚠️ Storage usage at ${stats.percentage.toFixed(1)}%`,
          stats
        );
      }

      // Check if we can store
      if (!this.canStore(value)) {
        console.error(
          `❌ Storage limit exceeded. Need ${value.length} bytes, ` +
          `available ${stats.available} bytes`
        );
        
        // Try to clean up old data
        this.cleanup();
        
        // Retry
        if (this.canStore(value)) {
          localStorage.setItem(key, value);
          return true;
        }
        
        // Switch to IndexedDB
        return this.setItemIndexedDB(key, value);
      }

      localStorage.setItem(key, value);
      return true;
    } catch (error) {
      console.error('Failed to set item in localStorage:', error);
      
      // Switch to IndexedDB
      return this.setItemIndexedDB(key, value);
    }
  }

  static getItem(key: string): string | null {
    try {
      return localStorage.getItem(key);
    } catch (error) {
      console.error('Failed to get item from localStorage:', error);
      return null;
    }
  }

  static removeItem(key: string): void {
    try {
      localStorage.removeItem(key);
    } catch (error) {
      console.error('Failed to remove item from localStorage:', error);
    }
  }

  private static cleanup(): void {
    try {
      // Delete oldest data
      const keys = Object.keys(localStorage);
      const timestampKeys = keys.filter(key => key.includes('timestamp'));
      
      if (timestampKeys.length === 0) {
        // If no timestamp, delete the oldest 10% by key
        const toDelete = Math.ceil(keys.length * 0.1);
        for (let i = 0; i < toDelete && i < keys.length; i++) {
          localStorage.removeItem(keys[i]);
        }
      } else {
        // Delete the oldest 10% by timestamp
        const sorted = timestampKeys.sort((a, b) => {
          const timeA = parseInt(localStorage.getItem(a) || '0');
          const timeB = parseInt(localStorage.getItem(b) || '0');
          return timeA - timeB;
        });

        const toDelete = Math.ceil(sorted.length * 0.1);
        for (let i = 0; i < toDelete; i++) {
          localStorage.removeItem(sorted[i]);
        }
      }
      
      console.log('✅ Storage cleanup completed');
    } catch (error) {
      console.error('Failed to cleanup storage:', error);
    }
  }

  private static setItemIndexedDB(key: string, value: string): boolean {
    try {
      const request = indexedDB.open('StoryCore', 1);
      
      request.onerror = () => {
        console.error('Failed to open IndexedDB');
      };
      
      request.onsuccess = () => {
        const db = request.result;
        
        // Create object store if necessary
        if (!db.objectStoreNames.contains('data')) {
          const version = db.version + 1;
          db.close();
          const upgradeRequest = indexedDB.open('StoryCore', version);
          upgradeRequest.onupgradeneeded = (event) => {
            const upgradeDb = (event.target as IDBOpenDBRequest).result;
            if (!upgradeDb.objectStoreNames.contains('data')) {
              upgradeDb.createObjectStore('data', { keyPath: 'key' });
            }
          };
          return;
        }
        
        const transaction = db.transaction(['data'], 'readwrite');
        const store = transaction.objectStore('data');
        store.put({ key, value, timestamp: Date.now() });
        
        console.log(`✅ Stored in IndexedDB: ${key}`);
      };
      
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains('data')) {
          db.createObjectStore('data', { keyPath: 'key' });
        }
      };
      
      return true;
    } catch (error) {
      console.error('Failed to store in IndexedDB:', error);
      return false;
    }
  }
}

// ============================================================================
// Story File I/O Utilities - LLM-Optimized Version
// ============================================================================
// This module provides functions for reading and writing story files
// optimized for LLM consumption with clear structure and metadata.
// 
// File Structure (all .md format):
//   story/
//   ├── story-index.md       # Index with metadata and links to parts
//   ├── story-intro.md       # Introduction with context
//   ├── story-chapter-01.md  # Numbered chapters
//   ├── story-chapter-02.md
//   ├── ...
//   ├── story-ending.md      # Conclusion
//   └── story-summary.md     # Rolling summary for LLM context
//
// Each file includes YAML frontmatter for LLM parsing
// ============================================================================

import type { Story, StoryPart } from '@/types/story';

// ============================================================================
// Constants
// ============================================================================

const STORY_DIR_NAME = 'story';
const FILE_NAMES = {
  index: 'story-index.md',
  intro: 'story-intro.md',
  chapter: (n: number) => `story-chapter-${String(n).padStart(2, '0')}.md`,
  ending: 'story-ending.md',
  summary: 'story-summary.md',
};

// ============================================================================
// YAML Frontmatter Helpers
// ============================================================================

interface FileMetadata {
  title: string;
  type: 'index' | 'intro' | 'chapter' | 'ending' | 'summary';
  order?: number;
  part_number?: number;
  total_parts?: number;
  genre?: string[];
  tone?: string[];
  characters?: string[];
  locations?: string[];
  previous_summary?: string;
  next_part?: string;
  prev_part?: string;
  generated_at?: string;
  review_score?: {
    tension: number;
    drama: number;
    sense: number;
    emotion: number;
    overall: number;
  };
}

function generateYAMLFrontmatter(metadata: FileMetadata): string {
  const lines = ['---'];

  for (const [key, value] of Object.entries(metadata)) {
    if (value === undefined) continue;

    if (Array.isArray(value)) {
      lines.push(`${key}:`);
      value.forEach(item => lines.push(`  - ${item}`));
    } else if (typeof value === 'object' && value !== null) {
      lines.push(`${key}:`);
      for (const [subKey, subValue] of Object.entries(value)) {
        lines.push(`  ${subKey}: ${subValue}`);
      }
    } else {
      lines.push(`${key}: ${value}`);
    }
  }

  lines.push('---');
  return lines.join('\n');
}

function parseYAMLFrontmatter(content: string): { metadata: Partial<FileMetadata>; body: string } {
  const lines = content.split('\n');

  if (lines[0] !== '---') {
    return { metadata: {}, body: content };
  }

  const endIndex = lines.findIndex((line, i) => i > 0 && line === '---');
  if (endIndex === -1) {
    return { metadata: {}, body: content };
  }

  const yamlLines = lines.slice(1, endIndex);
  const body = lines.slice(endIndex + 1).join('\n').trim();

  const metadata: Partial<FileMetadata> = {};
  let currentKey = '';
  let currentArray: string[] = [];
  let isArray = false;

  for (const line of yamlLines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    // Check if it's an array item
    if (trimmed.startsWith('- ')) {
      currentArray.push(trimmed.substring(2));
      isArray = true;
      continue;
    }

    // Save previous array if exists
    if (isArray && currentKey) {
      (metadata as any)[currentKey] = currentArray;
      currentArray = [];
      isArray = false;
    }

    // Parse key-value
    const colonIndex = trimmed.indexOf(':');
    if (colonIndex > 0) {
      currentKey = trimmed.substring(0, colonIndex).trim();
      const value = trimmed.substring(colonIndex + 1).trim();

      if (value) {
        // Try to parse as number
        const numValue = Number(value);
        (metadata as any)[currentKey] = isNaN(numValue) ? value : numValue;
      }
    }
  }

  // Save final array if exists
  if (isArray && currentKey) {
    (metadata as any)[currentKey] = currentArray;
  }

  return { metadata, body };
}

// ============================================================================
// Story Part File Generation
// ============================================================================

export function generateStoryPartFile(part: StoryPart, context: {
  totalParts: number;
  genre: string[];
  tone: string[];
  characters: string[];
  locations: string[];
  prevPart?: string;
  nextPart?: string;
}): string {
  const metadata: FileMetadata = {
    title: part.title,
    type: part.type,
    order: part.order,
    part_number: part.type === 'chapter' ? part.order : undefined,
    total_parts: context.totalParts,
    genre: context.genre,
    tone: context.tone,
    characters: context.characters,
    locations: context.locations,
    generated_at: new Date().toISOString(),
    prev_part: context.prevPart,
    next_part: context.nextPart,
  };

  if (part.reviewScore) {
    metadata.review_score = part.reviewScore;
  }

  const lines: string[] = [
    generateYAMLFrontmatter(metadata),
    '',
    `# ${part.title}`,
    '',
    '## Content',
    '',
    part.content,
    '',
    '---',
    '',
    '## Summary for Next Part',
    '',
    part.summary,
    '',
    '---',
    '',
    '> **Note for LLM**: This file is part of a multi-part story. Use the "Summary for Next Part" section as context when generating subsequent parts.',
  ];

  return lines.join('\n');
}

export function generateStoryIndexFile(story: Story): string {
  const metadata: FileMetadata = {
    title: story.title,
    type: 'index',
    genre: story.genre,
    tone: story.tone,
    characters: story.charactersUsed.map(c => c.name),
    locations: story.locationsUsed.map(l => l.name),
    generated_at: new Date().toISOString(),
  };

  const partsList = story.parts?.map((part, index) => {
    const fileName = part.type === 'intro'
      ? FILE_NAMES.intro
      : part.type === 'ending'
        ? FILE_NAMES.ending
        : FILE_NAMES.chapter(part.order - 1);

    return `- [${part.title}](./${fileName}) - Order: ${part.order}`;
  }).join('\n') || '';

  const lines: string[] = [
    generateYAMLFrontmatter(metadata),
    '',
    `# ${story.title}`,
    '',
    '## Story Information',
    '',
    `- **Genre**: ${story.genre.join(', ')}`,
    `- **Tone**: ${story.tone.join(', ')}`,
    `- **Length**: ${story.length}`,
    `- **Created**: ${new Date(story.createdAt).toLocaleDateString()}`,
    `- **Updated**: ${new Date(story.updatedAt).toLocaleDateString()}`,
    '',
    '## Summary',
    '',
    story.summary,
    '',
    '## Parts',
    '',
    partsList,
    '',
    '## Characters',
    '',
    ...story.charactersUsed.map(c => `- **${c.name}**: ${c.role}`),
    '',
    '## Locations',
    '',
    ...story.locationsUsed.map(l => `- **${l.name}**: ${l.significance}`),
    '',
    '---',
    '',
    '*This index file is automatically maintained by StoryCore-Engine.*',
  ];

  return lines.join('\n');
}

export function generateRollingSummaryFile(parts: StoryPart[]): string {
  const lastPart = parts[parts.length - 1];

  const metadata: FileMetadata = {
    title: 'Rolling Summary',
    type: 'summary',
    order: parts.length,
    total_parts: parts.length,
    generated_at: new Date().toISOString(),
  };

  const cumulativeSummary = parts.map(p =>
    `### ${p.title}\n${p.summary}`
  ).join('\n\n');

  const lines: string[] = [
    generateYAMLFrontmatter(metadata),
    '',
    '# Rolling Summary',
    '',
    '> This file contains the cumulative summary of all story parts for LLM context.',
    '',
    '## Current Context (Last Part)',
    '',
    lastPart?.summary || '',
    '',
    '## Full Story Arc',
    '',
    cumulativeSummary,
    '',
    '---',
    '',
    '> **LLM Instruction**: Use "Current Context" for generating the next part. Use "Full Story Arc" for understanding the complete narrative.',
  ];

  return lines.join('\n');
}

// ============================================================================
// Legacy Markdown Conversion (for backward compatibility)
// ============================================================================

/**
 * Converts a Story object to markdown format (legacy combined format)
 */
export function storyToMarkdown(story: Story): string {
  const lines: string[] = [];

  // Title
  lines.push(`# ${story.title || 'Untitled Story'}`);
  lines.push('');

  // Story Information
  lines.push('## Story Information');
  lines.push('');
  lines.push(`**Genre**: ${story.genre.join(', ') || '[Not specified]'}`);
  lines.push(`**Tone**: ${story.tone.join(', ') || '[Not specified]'}`);
  lines.push(`**Length**: ${story.length || 'medium'}`);
  lines.push('');

  // Summary
  lines.push('## Summary');
  lines.push('');
  lines.push(story.summary || '[Write a brief summary of your story here - 2-3 sentences describing the main plot and characters]');
  lines.push('');

  // Parts (if available)
  if (story.parts && story.parts.length > 0) {
    lines.push('## Parts');
    lines.push('');

    for (const part of story.parts) {
      lines.push(`### ${part.title}`);
      lines.push('');
      lines.push(part.content);
      lines.push('');
      lines.push(`*Summary: ${part.summary}*`);
      lines.push('');
    }
  } else {
    // Main Content (legacy)
    lines.push('## Main Content');
    lines.push('');
    lines.push(story.content || '[Your story content begins here. The storyteller wizard will help you generate and refine this content.]');
    lines.push('');
  }

  // Characters Used
  if (story.charactersUsed && story.charactersUsed.length > 0) {
    lines.push('## Characters');
    lines.push('');
    story.charactersUsed.forEach((char) => {
      lines.push(`- **${char.name}**: ${char.role}`);
    });
    lines.push('');
  }

  // Locations Used
  if (story.locationsUsed && story.locationsUsed.length > 0) {
    lines.push('## Locations');
    lines.push('');
    story.locationsUsed.forEach((loc) => {
      lines.push(`- **${loc.name}**: ${loc.significance}`);
    });
    lines.push('');
  }

  // Footer
  lines.push('---');
  lines.push('');
  lines.push('*This file is automatically read and updated by the StoryCore-Engine Storyteller Wizard.*');
  lines.push('*You can also edit it manually using any text editor.*');

  return lines.join('\n');
}

/**
 * Parses markdown content into a Story object
 */
export function markdownToStory(markdown: string, existingStory?: Partial<Story>): Story {
  const { metadata, body } = parseYAMLFrontmatter(markdown);
  const lines = body.split('\n');

  // Initialize story with defaults or existing values
  const story: Story = {
    id: existingStory?.id || crypto.randomUUID(),
    title: metadata.title || '',
    content: '',
    summary: '',
    genre: metadata.genre || existingStory?.genre || [],
    tone: metadata.tone || existingStory?.tone || [],
    length: existingStory?.length || 'medium',
    charactersUsed: existingStory?.charactersUsed || [],
    locationsUsed: existingStory?.locationsUsed || [],
    autoGeneratedElements: existingStory?.autoGeneratedElements || [],
    createdAt: existingStory?.createdAt || Date.now(),
    updatedAt: Date.now(),
    version: (existingStory?.version || 0) + 1,
    worldId: existingStory?.worldId,
  };

  let currentSection = '';
  let contentBuffer: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Parse title (# Title)
    if (line.startsWith('# ') && !story.title) {
      story.title = line.substring(2).trim();
      continue;
    }

    // Parse section headers (## Section)
    if (line.startsWith('## ')) {
      // Save previous section content
      if (currentSection === 'Main Content' || currentSection === 'Content') {
        story.content = contentBuffer.join('\n').trim();
        contentBuffer = [];
      } else if (currentSection === 'Summary') {
        story.summary = contentBuffer.join('\n').trim();
        contentBuffer = [];
      }

      currentSection = line.substring(3).trim();
      continue;
    }

    // Parse metadata fields
    if (line.startsWith('**Genre**:')) {
      const genreText = line.substring(10).trim();
      story.genre = genreText
        .split(',')
        .map((g) => g.trim())
        .filter((g) => g && g !== '[Not specified]');
      continue;
    }

    if (line.startsWith('**Tone**:')) {
      const toneText = line.substring(9).trim();
      story.tone = toneText
        .split(',')
        .map((t) => t.trim())
        .filter((t) => t && t !== '[Not specified]');
      continue;
    }

    if (line.startsWith('**Length**:')) {
      const lengthText = line.substring(11).trim().toLowerCase();
      if (['short', 'medium', 'long', 'scene', 'short_story', 'novella', 'novel', 'epic_novel'].includes(lengthText)) {
        story.length = lengthText as any;
      }
      continue;
    }

    // Collect content for current section
    if (currentSection === 'Main Content' || currentSection === 'Content' || currentSection === 'Summary') {
      contentBuffer.push(line);
    }
  }

  // Save any remaining content
  if (currentSection === 'Main Content' || currentSection === 'Content') {
    story.content = contentBuffer.join('\n').trim();
  } else if (currentSection === 'Summary') {
    story.summary = contentBuffer.join('\n').trim();
  }

  return story;
}

// ============================================================================
// File I/O Functions
// ============================================================================

/**
 * Saves a complete story with all parts as separate .md files
 * Optimized for LLM consumption with YAML frontmatter
 */
export async function saveStoryToDisk(projectPath: string, story: Story): Promise<void> {
  if (!window.electronAPI?.fs) {
    throw new Error('Electron API not available');
  }

  const storyDir = `${projectPath}/${STORY_DIR_NAME}`;

  try {
    // Ensure directory exists with recursive option
    await window.electronAPI.fs.mkdir(storyDir, { recursive: true });

    // Save index file
    const indexContent = generateStoryIndexFile(story);
    await window.electronAPI.fs.writeFile(`${storyDir}/${FILE_NAMES.index}`, indexContent);

    // Save individual parts
    if (story.parts && story.parts.length > 0) {
      const characterNames = story.charactersUsed.map(c => c.name);
      const locationNames = story.locationsUsed.map(l => l.name);

      for (let i = 0; i < story.parts.length; i++) {
        const part = story.parts[i];
        const prevPart = i > 0 ? story.parts[i - 1] : undefined;
        const nextPart = i < story.parts.length - 1 ? story.parts[i + 1] : undefined;

        const fileName = part.type === 'intro'
          ? FILE_NAMES.intro
          : part.type === 'ending'
            ? FILE_NAMES.ending
            : FILE_NAMES.chapter(part.order - 1);

        const content = generateStoryPartFile(part, {
          totalParts: story.parts.length,
          genre: story.genre,
          tone: story.tone,
          characters: characterNames,
          locations: locationNames,
          prevPart: prevPart?.title,
          nextPart: nextPart?.title,
        });

        await window.electronAPI.fs.writeFile(`${storyDir}/${fileName}`, content);
      }

      // Save rolling summary
      const summaryContent = generateRollingSummaryFile(story.parts);
      await window.electronAPI.fs.writeFile(`${storyDir}/${FILE_NAMES.summary}`, summaryContent);
    }

    // Also save legacy combined markdown for compatibility
    const legacyMarkdown = storyToMarkdown(story);
    await window.electronAPI.fs.writeFile(`${projectPath}/story.md`, legacyMarkdown);

  } catch (error) {
    console.error('[StoryFileIO] Failed to save story:', error);
    throw error;
  }
}

/**
 * Loads story parts from the story directory
 */
export async function loadStoryPartsFromDisk(projectPath: string): Promise<StoryPart[] | null> {
  if (!window.electronAPI?.fs) {
    return null;
  }

  const storyDir = `${projectPath}/${STORY_DIR_NAME}`;

  try {
    // Check if directory exists
    const exists = await window.electronAPI.fs.exists(storyDir);
    if (!exists) {
      return null;
    }

    // List files in directory
    const files = await window.electronAPI.fs.readdir(storyDir);
    const partFiles = files.filter((f: string) =>
      f.startsWith('story-') && f.endsWith('.md') && f !== 'story-index.md' && f !== 'story-summary.md'
    );

    const parts: StoryPart[] = [];

    for (const fileName of partFiles.sort()) {
      const filePath = `${storyDir}/${fileName}`;
      const content = await window.electronAPI.fs.readFile(filePath);
      const { metadata, body } = parseYAMLFrontmatter(content.toString());

      // Parse body to extract content and summary
      const contentMatch = body.match(/## Content\n\n([\s\S]*?)(?=\n\n---|$)/);
      const summaryMatch = body.match(/## Summary for Next Part\n\n([\s\S]*?)(?=\n\n---|$)/);

      parts.push({
        id: crypto.randomUUID(),
        type: metadata.type as any,
        title: metadata.title || fileName,
        content: contentMatch ? contentMatch[1].trim() : body,
        summary: summaryMatch ? summaryMatch[1].trim() : '',
        order: metadata.order || 0,
        reviewScore: metadata.review_score,
      });
    }

    // Sort by order
    return parts.sort((a, b) => a.order - b.order);

  } catch (error) {
    console.warn('[StoryFileIO] Failed to load story parts:', error);
    return null;
  }
}

/**
 * Loads story content from a story.md file (legacy)
 */
export async function loadStoryFromFile(projectPath: string | File): Promise<Story | null> {
  try {
    let file: File;

    if (projectPath instanceof File) {
      file = projectPath;
    } else {
      throw new Error(
        'Browser file system access requires user interaction. ' +
        'Please use the file picker to select the story.md file.'
      );
    }

    const content = await file.text();
    return markdownToStory(content);
  } catch (error) {
    if (error instanceof Error && error.message.includes('not found')) {
      return null;
    }
    throw error;
  }
}

/**
 * Saves story content using browser APIs (download or file picker)
 */
export async function saveStoryToFile(projectPath: string, story: Story): Promise<void> {
  try {
    const markdown = storyToMarkdown(story);

    if ('showSaveFilePicker' in window) {
      const options = {
        suggestedName: 'story.md',
        types: [
          {
            description: 'Markdown Files',
            accept: {
              'text/markdown': ['.md'],
            },
          },
        ],
      };

      const handle = await (window as any).showSaveFilePicker(options);
      const writable = await handle.createWritable();
      await writable.write(markdown);
      await writable.close();
    } else {
      const blob = new Blob([markdown], { type: 'text/markdown;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'story.md';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    }
  } catch (error) {
    if (error instanceof Error) {
      throw new Error(`Failed to save story file: ${error.message}`);
    }
    throw new Error('Failed to save story file: Unknown error');
  }
}

/**
 * Creates a new story.md file with default template content
 */
export function createDefaultStory(projectName: string): Story {
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    title: projectName,
    content: '[Your story content begins here. The storyteller wizard will help you generate and refine this content.]',
    summary: '[Write a brief summary of your story here - 2-3 sentences describing the main plot and characters]',
    genre: [],
    tone: [],
    length: 'medium',
    charactersUsed: [],
    locationsUsed: [],
    autoGeneratedElements: [],
    createdAt: now,
    updatedAt: now,
    version: 1,
  };
}

/**
 * Loads story from file with fallback to default story
 */
export async function loadStoryOrDefault(
  projectPath: string | File,
  projectName: string
): Promise<Story> {
  try {
    const story = await loadStoryFromFile(projectPath);
    if (story) {
      return story;
    }
  } catch (error) {
    console.warn('Failed to load story file, using default:', error);
  }

  return createDefaultStory(projectName);
}

// ============================================================================
// File Picker Helpers
// ============================================================================

export async function pickStoryFile(): Promise<File | null> {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.md,text/markdown';

    input.onchange = (event) => {
      const target = event.target as HTMLInputElement;
      const file = target.files?.[0];
      resolve(file || null);
    };

    input.oncancel = () => {
      resolve(null);
    };

    input.click();
  });
}

export async function loadStoryWithPicker(): Promise<Story | null> {
  try {
    const file = await pickStoryFile();
    if (!file) {
      return null;
    }

    return await loadStoryFromFile(file);
  } catch (error) {
    console.error('Failed to load story with picker:', error);
    return null;
  }
}

