// ============================================================================
// Validation Utilities
// ============================================================================

/**
 * Validates data against a schema and returns the result
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns Object with success flag and either validated data or errors
 */
export function validateData<T>(
  schema: z.ZodSchema<T>,
  data: unknown
): { success: boolean; data?: T; errors?: Record<string, string> } {
  try {
    const validated = schema.parse(data);
    return { success: true, data: validated };
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors: Record<string, string> = {};
      (error as any).errors.forEach((err: z.ZodIssue) => {
        const path = err.path.join('.');
        errors[path] = err.message;
      });
      return { success: false, errors };
    }
    return { success: false, errors: { _general: 'Validation failed' } };
  }
}

/**
 * Validates data and throws an error if validation fails
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns The validated data
 * @throws ZodError if validation fails
 */
export function validateDataOrThrow<T>(schema: z.ZodSchema<T>, data: unknown): T {
  return schema.parse(data);
}

/**
 * Safely validates data without throwing
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns The validated data or null if validation fails
 */
export function validateDataSafe<T>(schema: z.ZodSchema<T>, data: unknown): T | null {
  const result = schema.safeParse(data);
  return result.success ? result.data : null;
}

// ============================================================================
// Wizard Storage Utilities
// ============================================================================

export type WizardType =
  | 'world'
  | 'character'
  | 'storyteller'
  | 'dialogue-writer'
  | 'scene-generator'
  | 'storyboard-creator'
  | 'style-transfer'
  | 'sequence-plan'
  | 'shot'
  | 'music-generation'
  | 'lyrics-generation';

export interface WizardAutoSaveState<T> {
  wizardType: WizardType;
  timestamp: string;
  currentStep: number;
  formData: Partial<T>;
  expiresAt: string;
}

// ============================================================================
// Storage Key Generation
// ============================================================================

function getStorageKey(wizardType: WizardType): string {
  return `wizard-${wizardType}`;
}

// ============================================================================
// Save Wizard State
// ============================================================================

export function saveWizardState<T>(
  wizardType: WizardType,
  currentStep: number,
  formData: Partial<T>,
  expirationDays: number = 7
): boolean {
  try {
    const state: WizardAutoSaveState<T> = {
      wizardType,
      timestamp: new Date().toISOString(),
      currentStep,
      formData,
      expiresAt: new Date(Date.now() + expirationDays * 24 * 60 * 60 * 1000).toISOString(),
    };

    const key = getStorageKey(wizardType);
    localStorage.setItem(key, JSON.stringify(state));

    return true;
  } catch (error) {
    // Failed to save wizard state - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to save wizard state:', error);
    }

    // Check if storage is full
    if (error instanceof DOMException && error.name === 'QuotaExceededError') {
      if (process.env.NODE_ENV === 'development') {
        console.warn('LocalStorage quota exceeded. Cannot save wizard progress.');
      }
    }

    return false;
  }
}

// ============================================================================
// Load Wizard State
// ============================================================================

export function loadWizardState<T>(
  wizardType: WizardType
): WizardAutoSaveState<T> | null {
  try {
    const key = getStorageKey(wizardType);
    const saved = localStorage.getItem(key);

    if (!saved) {
      return null;
    }

    const state: WizardAutoSaveState<T> = JSON.parse(saved);

    // Validate state structure
    if (!isValidWizardState(state)) {
      if (process.env.NODE_ENV === 'development') {
        console.warn('Invalid wizard state structure, clearing corrupted data');
      }
      clearWizardState(wizardType);
      return null;
    }

    // Check if expired
    if (new Date(state.expiresAt) < new Date()) {
      console.info('Wizard state expired, clearing old data');
      clearWizardState(wizardType);
      return null;
    }

    return state;
  } catch (error) {
    // Failed to load wizard state - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to load wizard state:', error);
    }

    // Clear corrupted state
    clearWizardState(wizardType);

    return null;
  }
}

// ============================================================================
// Load Wizard State with Validation
// ============================================================================

export interface LoadStateResult<T> {
  state: WizardAutoSaveState<T> | null;
  isValid: boolean;
  isCorrupted: boolean;
  errors: string[];
  warnings: string[];
  canRecover: boolean;
}

export function loadWizardStateWithValidation<T>(
  wizardType: WizardType
): LoadStateResult<T> {
  try {
    const key = getStorageKey(wizardType);
    const saved = localStorage.getItem(key);

    if (!saved) {
      return {
        state: null,
        isValid: true,
        isCorrupted: false,
        errors: [],
        warnings: [],
        canRecover: false,
      };
    }

    const state: WizardAutoSaveState<T> = JSON.parse(saved);

    // Basic validation
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!isValidWizardState(state)) {
      errors.push('Invalid state structure');
    }

    if (state.expiresAt && new Date(state.expiresAt) < new Date()) {
      warnings.push('State has expired');
    }

    const isValid = errors.length === 0;
    const isCorrupted = errors.length > 0;
    const canRecover = isCorrupted && state.formData !== undefined;

    return {
      state: isValid ? state : null,
      isValid,
      isCorrupted,
      errors,
      warnings,
      canRecover,
    };
  } catch (error) {
    return {
      state: null,
      isValid: false,
      isCorrupted: true,
      errors: ['Failed to parse state: ' + (error instanceof Error ? error.message : String(error))],
      warnings: [],
      canRecover: false,
    };
  }
}

// ============================================================================
// Clear Wizard State
// ============================================================================

export function clearWizardState(wizardType: WizardType): void {
  try {
    const key = getStorageKey(wizardType);
    localStorage.removeItem(key);
  } catch (error) {
    // Failed to clear wizard state - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to clear wizard state:', error);
    }
  }
}

// ============================================================================
// Check if Wizard State Exists
// ============================================================================

export function hasWizardState(wizardType: WizardType): boolean {
  const state = loadWizardState(wizardType);
  return state !== null;
}

// ============================================================================
// Export Wizard State as JSON
// ============================================================================

export function exportWizardState<T>(
  wizardType: WizardType
): string | null {
  const state = loadWizardState<T>(wizardType);

  if (!state) {
    return null;
  }

  try {
    return JSON.stringify(state.formData, null, 2);
  } catch (error) {
    // Failed to export wizard state - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to export wizard state:', error);
    }
    return null;
  }
}

// ============================================================================
// Import Wizard State from JSON
// ============================================================================

export function importWizardState<T>(
  wizardType: WizardType,
  jsonData: string
): boolean {
  try {
    const formData = JSON.parse(jsonData) as Partial<T>;

    return saveWizardState(wizardType, 1, formData);
  } catch (error) {
    // Failed to import wizard state - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to import wizard state:', error);
    }
    return false;
  }
}

// ============================================================================
// Validate Wizard State Structure
// ============================================================================

// Using 'any' for state parameter to validate arbitrary wizard state structures
// before type narrowing with the type guard
function isValidWizardState(state: unknown): state is WizardAutoSaveState<any> {
  const validWizardTypes: WizardType[] = [
    'world',
    'character',
    'storyteller',
    'dialogue-writer',
    'scene-generator',
    'storyboard-creator',
    'style-transfer',
    'sequence-plan',
    'shot',
    'music-generation',
    'lyrics-generation',
  ];

  const s = state as any;

  return (
    s &&
    typeof s === 'object' &&
    typeof s.wizardType === 'string' &&
    validWizardTypes.includes(s.wizardType as WizardType) &&
    typeof s.timestamp === 'string' &&
    typeof s.currentStep === 'number' &&
    typeof s.formData === 'object' &&
    typeof s.expiresAt === 'string'
  );
}

// ============================================================================
// Check LocalStorage Availability
// ============================================================================

export function isLocalStorageAvailable(): boolean {
  try {
    const test = '__storage_test__';
    localStorage.setItem(test, test);
    localStorage.removeItem(test);
    return true;
  } catch (error) {
    return false;
  }
}

// ============================================================================
// Get LocalStorage Usage
// ============================================================================

export function getLocalStorageUsage(): {
  used: number;
  available: number;
  percentage: number;
} {
  try {
    let used = 0;

    for (const key in localStorage) {
      if (localStorage.hasOwnProperty(key)) {
        used += localStorage[key].length + key.length;
      }
    }

    // Most browsers have 5-10MB limit, we'll use 5MB as conservative estimate
    const available = 5 * 1024 * 1024; // 5MB in bytes
    const percentage = (used / available) * 100;

    return {
      used,
      available,
      percentage,
    };
  } catch (error) {
    // Failed to calculate storage usage - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Failed to calculate storage usage:', error);
    }
    return {
      used: 0,
      available: 0,
      percentage: 0,
    };
  }
}

// ============================================================================
// Clear All Wizard States
// ============================================================================

export function clearAllWizardStates(): void {
  const wizardTypes: WizardType[] = [
    'world',
    'character',
    'storyteller',
    'dialogue-writer',
    'scene-generator',
    'storyboard-creator',
    'style-transfer',
    'sequence-plan',
    'shot',
    'music-generation',
    'lyrics-generation',
  ];

  wizardTypes.forEach(type => clearWizardState(type));
}

// ============================================================================
// Emergency Export on Critical Error
// ============================================================================

export function emergencyExportWizardState<T>(
  wizardType: WizardType,
  error?: Error
): void {
  try {
    const state = loadWizardState<T>(wizardType);

    if (!state) {
      if (process.env.NODE_ENV === 'development') {
        console.warn('No wizard state to export');
      }
      return;
    }

    const exportData = {
      wizardType,
      timestamp: new Date().toISOString(),
      formData: state.formData,
      error: error ? {
        message: error.message,
        stack: error.stack,
      } : undefined,
    };

    // Create download link
    const blob = new Blob([JSON.stringify(exportData, null, 2)], {
      type: 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${wizardType}-wizard-emergency-${Date.now()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    if (process.env.NODE_ENV === 'development') {
      console.info('Emergency export completed successfully');
    }
  } catch (exportError) {
    // Failed emergency export - log for debugging in development only
    if (process.env.NODE_ENV === 'development') {
      console.error('Emergency export failed:', exportError);
    }
  }
}

// ============================================================================
// Auto-Export on Window Unload (for critical errors)
// ============================================================================

let autoExportEnabled = false;

export function enableAutoExportOnError(): void {
  if (autoExportEnabled) {
    return;
  }

  autoExportEnabled = true;

const wizardTypes: WizardType[] = [
    'world',
    'character',
    'storyteller',
    'dialogue-writer',
    'scene-generator',
    'storyboard-creator',
    'style-transfer',
    'sequence-plan',
    'shot',
    'music-generation',
    'lyrics-generation',
  ];

  // Listen for unhandled errors
  window.addEventListener('error', (event) => {
    if (process.env.NODE_ENV === 'development') {
      console.warn('Unhandled error detected, attempting emergency export');
    }
    wizardTypes.forEach(type => emergencyExportWizardState(type, event.error));
  });

  // Listen for unhandled promise rejections
  window.addEventListener('unhandledrejection', (event) => {
    if (process.env.NODE_ENV === 'development') {
      console.warn('Unhandled rejection detected, attempting emergency export');
    }
    const error = event.reason instanceof Error ? event.reason : new Error(String(event.reason));
    wizardTypes.forEach(type => emergencyExportWizardState(type, error));
  });
}

export function disableAutoExportOnError(): void {
  autoExportEnabled = false;
  // Note: Cannot remove event listeners without references
  // This is a limitation of the current implementation
}

/**
 * WorkerPool - Gestion d'un pool de Web Workers pour traitement asynchrone
 * 
 * Cette classe gère un pool de workers pour exécuter des tâches en arrière-plan
 * sans bloquer l'interface utilisateur. Elle implémente une file d'attente de tâches
 * et alloue automatiquement les workers disponibles.
 * 
 * Exigences: 10.1, 10.6
 */

export interface WorkerTask<T = any, R = any> {
  id: string;
  type: string;
  data: T;
  resolve: (result: R) => void;
  reject: (error: Error) => void;
  priority?: number;
}

export interface WorkerMessage<T = any> {
  id: string;
  type: string;
  data: T;
}

export interface WorkerResponse<R = any> {
  id: string;
  status: 'completed' | 'error' | 'progress';
  result?: R;
  error?: string;
  progress?: number;
}

export class WorkerPool {
  private workers: Worker[] = [];
  private availableWorkers: Worker[] = [];
  private taskQueue: WorkerTask[] = [];
  public readonly size: number;
  private workerUrl: string;

  /**
   * Crée un nouveau pool de workers
   * @param size - Nombre de workers dans le pool (par défaut: nombre de cœurs CPU)
   * @param workerUrl - URL du script worker à charger
   */
  constructor(
    size: number = navigator.hardwareConcurrency || 4,
    workerUrl: string = new URL('../../workers/processing.worker.ts', import.meta.url).href
  ) {
    this.size = size;
    this.workerUrl = workerUrl;
    this.initializeWorkers();
  }

  /**
   * Initialise tous les workers du pool
   * Exigence: 10.1 - Traitement non-bloquant
   */
  private initializeWorkers(): void {
    for (let i = 0; i < this.size; i++) {
      const worker = this.createWorker();
      this.workers.push(worker);
      this.availableWorkers.push(worker);
    }
  }

  /**
   * Crée un nouveau worker avec les gestionnaires d'événements
   */
  private createWorker(): Worker {
    const worker = new Worker(this.workerUrl, { type: 'module' });

    worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
      this.handleWorkerMessage(worker, event.data);
    };

    worker.onerror = (error: ErrorEvent) => {
      this.handleWorkerError(worker, error);
    };

    return worker;
  }

  /**
   * Exécute une tâche dans le pool de workers
   * @param type - Type de tâche à exécuter
   * @param data - Données à traiter
   * @param priority - Priorité de la tâche (optionnel)
   * @returns Promise qui se résout avec le résultat
   * 
   * Exigence: 10.6 - File d'attente avec priorités
   */
  async execute<T, R>(type: string, data: T, priority: number = 0): Promise<R> {
    return new Promise((resolve, reject) => {
      const task: WorkerTask<T, R> = {
        id: this.generateTaskId(),
        type,
        data,
        resolve,
        reject,
        priority
      };

      const worker = this.availableWorkers.pop();

      if (worker) {
        // Worker available, execute immediately
        this.executeTask(worker, task);
      } else {
        // No worker available, add to queue
        this.enqueueTask(task);
      }
    });
  }

  /**
   * Adds a task to the queue respecting priorities
   * Requirement: 10.6 - Priority management
   */
  private enqueueTask(task: WorkerTask): void {
    // Insert task based on its priority (higher priority = earlier in queue)
    const insertIndex = this.taskQueue.findIndex(t => (t.priority || 0) < (task.priority || 0));
    
    if (insertIndex === -1) {
      this.taskQueue.push(task);
    } else {
      this.taskQueue.splice(insertIndex, 0, task);
    }
  }

  /**
   * Executes a task on a specific worker
   */
  private executeTask(worker: Worker, task: WorkerTask): void {
    const message: WorkerMessage = {
      id: task.id,
      type: task.type,
      data: task.data
    };

    worker.postMessage(message);

    // Store task for later resolution
    (worker as any).__currentTask = task;
  }

  /**
   * Handles messages received from a worker
   * Requirement: 10.2 - Progress updates
   */
  private handleWorkerMessage(worker: Worker, response: WorkerResponse): void {
    const task = (worker as any).__currentTask as WorkerTask;

    if (!task || response.id !== task.id) {
      console.warn('Received message for unknown task:', response.id);
      return;
    }

    if (response.status === 'progress') {
      // Progress message - do not release worker
      // Progress callbacks can be added in a future version
      return;
    }

    if (response.status === 'error') {
      task.reject(new Error(response.error || 'Worker task failed'));
    } else if (response.status === 'completed') {
      task.resolve(response.result);
    }

    // Release worker
    delete (worker as any).__currentTask;
    this.availableWorkers.push(worker);

    // Process next pending task
    this.processNextTask(worker);
  }

  /**
   * Processes the next task in the queue
   */
  private processNextTask(worker: Worker): void {
    const nextTask = this.taskQueue.shift();
    if (nextTask) {
      // Remove worker from available list
      const index = this.availableWorkers.indexOf(worker);
      if (index !== -1) {
        this.availableWorkers.splice(index, 1);
      }
      this.executeTask(worker, nextTask);
    }
  }

  /**
   * Handles worker errors
   * Requirement: 10.7 - Error handling with context
   */
  private handleWorkerError(worker: Worker, error: ErrorEvent): void {
    const task = (worker as any).__currentTask as WorkerTask;

    if (task) {
      task.reject(new Error(`Worker error: ${error.message}`));
      delete (worker as any).__currentTask;
    }

    // Recreate failed worker
    const index = this.workers.indexOf(worker);
    if (index !== -1) {
      worker.terminate();
      this.workers.splice(index, 1);

      const newWorker = this.createWorker();
      this.workers.push(newWorker);
      this.availableWorkers.push(newWorker);
    }
  }

  /**
   * Cancels a specific task by its ID
   * Requirement: 10.5 - Task cancellation
   */
  cancel(taskId: string): boolean {
    // Search in queue
    const queueIndex = this.taskQueue.findIndex(t => t.id === taskId);
    if (queueIndex !== -1) {
      const task = this.taskQueue.splice(queueIndex, 1)[0];
      task.reject(new Error('Task cancelled'));
      return true;
    }

    // Search in running tasks
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task && task.id === taskId) {
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
        
        // Send cancellation message to worker
        worker.postMessage({ id: taskId, type: 'cancel' });
        
        // Make worker available
        if (!this.availableWorkers.includes(worker)) {
          this.availableWorkers.push(worker);
        }
        
        // Process next task
        this.processNextTask(worker);
        return true;
      }
    }

    return false;
  }

  /**
   * Cancels all running and pending tasks
   * Requirement: 10.5 - Task cancellation
   */
  cancelAll(): void {
    // Reject all pending tasks
    while (this.taskQueue.length > 0) {
      const task = this.taskQueue.shift();
      if (task) {
        task.reject(new Error('Task cancelled'));
      }
    }

    // Reject all running tasks
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task) {
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
        
        // Send cancellation message to worker
        worker.postMessage({ id: task.id, type: 'cancel' });
      }
    }

    // Reset available workers list
    this.availableWorkers = [...this.workers];
  }

  /**
   * Properly terminates all workers in the pool
   * Requirement: 10.5 - Clean termination
   */
  terminate(): void {
    this.cancelAll();

    for (const worker of this.workers) {
      worker.terminate();
    }

    this.workers = [];
    this.availableWorkers = [];
  }

  /**
   * Returns the number of pending tasks
   */
  getQueueSize(): number {
    return this.taskQueue.length;
  }

  /**
   * Retourne le nombre de workers disponibles
   */
  getAvailableWorkers(): number {
    return this.availableWorkers.length;
  }

  /**
   * Retourne le nombre de workers occupés
   */
  getBusyWorkers(): number {
    return this.size - this.availableWorkers.length;
  }

  /**
   * Génère un ID unique pour une tâche
   */
  private generateTaskId(): string {
    return `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * Processing Worker - handles CPU-intensive tasks off the main thread
 * Supports thumbnail generation, video processing, and batch operations
 */

interface WorkerMessage {
  type: string;
  taskId?: string;
  taskType?: string;
  data?: unknown;
  workerId?: number;
}

interface TaskResult {
  success: boolean;
  result?: unknown;
  error?: string;
}

// Worker state
let workerId: number;

// Task handlers
const taskHandlers = {
  async thumbnail_generation(taskData: unknown): Promise<TaskResult> {
    try {
      // Simulate thumbnail generation
      // In real implementation, this would extract frames from video
      await delay(100); // Simulate processing time

      const { videoUrl, timestamp, width = 160, height = 90 } = taskData as any;

      // Mock thumbnail generation
      const thumbnail = {
        url: `thumbnail-${Date.now()}.png`,
        timestamp,
        width,
        height,
        data: new ArrayBuffer(width * height * 4) // Mock RGBA data
      };

      return { success: true, result: thumbnail };
    } catch (error) {
      return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
    }
  },

  async video_encoding(taskData: unknown): Promise<TaskResult> {
    try {
      const { videoBlob, format, quality = 0.8 } = taskData as any;

      // Simulate video encoding
      await delay(500);

      const encodedVideo = {
        blob: videoBlob, // In real impl, this would be the encoded result
        format,
        quality,
        size: videoBlob.size * quality // Mock size reduction
      };

      return { success: true, result: encodedVideo };
    } catch (error) {
      return { success: false, error: error instanceof Error ? error.message : 'Encoding failed' };
    }
  },

  async batch_processing(taskData: unknown): Promise<TaskResult> {
    try {
      const { items, operation } = taskData as any;
      const results = [];

      for (let i = 0; i < items.length; i++) {
        const item = items[i];

        // Simulate processing each item
        await delay(50);

        // Report progress
        const progress = ((i + 1) / items.length) * 100;
        self.postMessage({
          type: 'TASK_PROGRESS',
          taskId: (taskData as any).taskId,
          progress,
          message: `Processing item ${i + 1}/${items.length}`
        });

        // Apply operation (mock)
        const result = { ...item, processed: true, operation };
        results.push(result);
      }

      return { success: true, result: results };
    } catch (error) {
      return { success: false, error: error instanceof Error ? error.message : 'Batch processing failed' };
    }
  }
};

// Utility functions
function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function executeTask(taskId: string, taskType: string, data: unknown) {
  const handler = taskHandlers[taskType as keyof typeof taskHandlers];

  if (!handler) {
    self.postMessage({
      type: 'TASK_COMPLETE',
      taskId,
      success: false,
      error: `Unknown task type: ${taskType}`
    });
    return;
  }

  try {
    const result = await handler(data);

    self.postMessage({
      type: 'TASK_COMPLETE',
      taskId,
      success: result.success,
      result: result.result,
      error: result.error
    });
  } catch (error) {
    self.postMessage({
      type: 'TASK_COMPLETE',
      taskId,
      success: false,
      error: error instanceof Error ? error.message : 'Task execution failed'
    });
  }
}

// Message handler
self.onmessage = async (event: MessageEvent<WorkerMessage>) => {
  const { type, taskId, taskType, data, workerId: msgWorkerId } = event.data;

  switch (type) {
    case 'INIT':
      workerId = msgWorkerId!;
      self.postMessage({ type: 'WORKER_READY' });
      break;

    case 'EXECUTE_TASK':
      if (taskId && taskType) {
        await executeTask(taskId, taskType, data);
      }
      break;

    default:
      console.warn('Unknown message type:', type);
  }
};

// Handle unhandled errors
self.onerror = (error) => {
  console.error('Worker unhandled error:', error);
};

self.onunhandledrejection = (event) => {
  console.error('Worker unhandled rejection:', event.reason);
  event.preventDefault();
};

/**
 * Processing Worker - Worker for async processing
 * 
 * This worker handles heavy background operations:
 * - Video thumbnail generation
 * - Video encoding
 * - Batch processing
 * 
 * Requirements: 10.2, 10.3, 10.4, 10.7
 */

interface WorkerMessage<T = any> {
  id: string;
  type: string;
  data: T;
}

interface WorkerResponse<R = any> {
  id: string;
  status: 'completed' | 'error' | 'progress';
  result?: R;
  error?: string;
  progress?: number;
}

/**
 * Sends a response to the main thread
 */
function sendResponse<R>(response: WorkerResponse<R>): void {
  self.postMessage(response);
}

/**
 * Sends a progress update
 * Requirement: 10.2 - Progress messages
 */
function sendProgress(id: string, progress: number): void {
  sendResponse({
    id,
    status: 'progress',
    progress
  });
}

/**
 * Sends a success result
 */
function sendSuccess<R>(id: string, result: R): void {
  sendResponse({
    id,
    status: 'completed',
    result
  });
}

/**
 * Sends an error with context
 * Requirement: 10.7 - Error handling with context
 */
function sendError(id: string, error: Error, context?: unknown): void {
  const errorMessage = error.message;
  const errorContext = context ? ` (Context: ${JSON.stringify(context)})` : '';

  sendResponse({
    id,
    status: 'error',
    error: `${errorMessage}${errorContext}`
  });
}

/**
 * Generates a thumbnail from a video
 * Requirement: 10.3 - Thumbnail generation
 */
async function generateThumbnail(
  id: string,
  data: { videoUrl: string; time: number; width?: number; height?: number }
): Promise<void> {
  try {
    const { videoUrl, time, width = 160, height = 90 } = data;

    sendProgress(id, 10);

    // Create video element (safe access for worker)
    const doc = (self as any).document;
    if (!doc) {
      throw new Error('DOM API not available in worker: Cannot creating video element');
    }

    const video = doc.createElement('video');
    video.crossOrigin = 'anonymous';
    video.preload = 'metadata';

    sendProgress(id, 30);

    // Load the video
    await new Promise<void>((resolve, reject) => {
      video.onloadedmetadata = () => resolve();
      video.onerror = () => reject(new Error('Failed to load video'));
      video.src = videoUrl;
    });

    sendProgress(id, 50);

    // Seek to specified time
    video.currentTime = time;
    await new Promise<void>((resolve) => {
      video.onseeked = () => resolve();
    });

    sendProgress(id, 70);

    // Create canvas and draw frame
    const canvas = new OffscreenCanvas(width, height);
    const ctx = canvas.getContext('2d');

    if (!ctx) {
      throw new Error('Failed to get canvas context');
    }

    ctx.drawImage(video as any, 0, 0, width, height);

    sendProgress(id, 90);

    // Convert to blob
    const blob = await canvas.convertToBlob({ type: 'image/jpeg', quality: 0.8 });

    sendProgress(id, 100);
    sendSuccess(id, blob);

  } catch (error) {
    sendError(id, error as Error, { videoUrl: data.videoUrl, time: data.time });
  }
}

/**
 * Encodes a video (simulation for now)
 * Requirement: 10.3 - Video encoding
 */
async function encodeVideo(
  id: string,
  data: { videoUrl: string; format: string; quality: string }
): Promise<void> {
  try {
    const { videoUrl, format, quality } = data;

    // Encoding simulation with progress
    for (let progress = 0; progress <= 100; progress += 10) {
      sendProgress(id, progress);
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    const result = {
      encodedUrl: videoUrl,
      format,
      quality,
      size: Math.floor(Math.random() * 10000000), // Simulated size
      duration: Math.floor(Math.random() * 300) // Simulated duration
    };

    sendSuccess(id, result);

  } catch (error) {
    sendError(id, error as Error, { videoUrl: data.videoUrl, format: data.format });
  }
}

/**
 * Processes a batch of items
 * Requirement: 10.4 - Batch processing
 */
async function processBatch(
  id: string,
  data: { items: unknown[]; operation: string; options?: unknown }
): Promise<void> {
  try {
    const { items, operation, options } = data;
    const results: unknown[] = [];
    const errors: Array<{ index: number; error: string }> = [];

    for (let i = 0; i < items.length; i++) {
      try {
        // Simulate processing of each item
        const result = await processItem(items[i], operation, options);
        results.push(result);

        // Send progress
        const progress = ((i + 1) / items.length) * 100;
        sendProgress(id, progress);

      } catch (error) {
        errors.push({
          index: i,
          error: (error as Error).message
        });
      }
    }

    sendSuccess(id, { results, errors });

  } catch (error) {
    sendError(id, error as Error, { itemCount: data.items.length, operation: data.operation });
  }
}

/**
 * Processes a single item in a batch
 */
async function processItem(item: unknown, operation: string, options?: unknown): Promise<any> {
  // Processing simulation
  await new Promise(resolve => setTimeout(resolve, 50));

  switch (operation) {
    case 'duplicate':
      return { ...(item as any), id: `${(item as any).id}_copy` };
    case 'transform':
      return { ...(item as any), ...(options as any) };
    case 'export':
      return { ...(item as any), exported: true };
    default:
      return item;
  }
}

/**
 * Optimizes an image
 * Requirement: 10.3 - Image processing
 */
async function optimizeImage(
  id: string,
  data: { imageUrl: string; maxWidth?: number; maxHeight?: number; quality?: number }
): Promise<void> {
  try {
    const { imageUrl, maxWidth = 1920, maxHeight = 1080, quality = 0.85 } = data;

    sendProgress(id, 20);

    // Load image
    const response = await fetch(imageUrl);
    const blob = await response.blob();

    sendProgress(id, 40);

    // Create bitmap
    const bitmap = await createImageBitmap(blob);

    sendProgress(id, 60);

    // Calculate new dimensions
    let width = bitmap.width;
    let height = bitmap.height;

    if (width > maxWidth || height > maxHeight) {
      const ratio = Math.min(maxWidth / width, maxHeight / height);
      width = Math.floor(width * ratio);
      height = Math.floor(height * ratio);
    }

    sendProgress(id, 80);

    // Resize
    const canvas = new OffscreenCanvas(width, height);
    const ctx = canvas.getContext('2d');

    if (!ctx) {
      throw new Error('Failed to get canvas context');
    }

    ctx.drawImage(bitmap, 0, 0, width, height);

    // Convert to blob
    const optimizedBlob = await canvas.convertToBlob({
      type: 'image/jpeg',
      quality
    });

    sendProgress(id, 100);
    sendSuccess(id, optimizedBlob);

  } catch (error) {
    sendError(id, error as Error, { imageUrl: data.imageUrl });
  }
}

/**
 * Analyzes video quality
 */
async function analyzeVideoQuality(
  id: string,
  data: { videoUrl: string }
): Promise<void> {
  try {
    const { videoUrl } = data;

    sendProgress(id, 25);

    // Load video (safe access)
    const doc = (self as any).document;
    if (!doc) {
      throw new Error('DOM API not available in worker');
    }

    const video = doc.createElement('video');
    video.crossOrigin = 'anonymous';
    video.preload = 'metadata';

    await new Promise<void>((resolve, reject) => {
      video.onloadedmetadata = () => resolve();
      video.onerror = () => reject(new Error('Failed to load video'));
      video.src = videoUrl;
    });

    sendProgress(id, 50);

    // Extract metadata
    const metadata = {
      duration: video.duration,
      width: video.videoWidth,
      height: video.videoHeight,
      aspectRatio: video.videoWidth / video.videoHeight,
      hasAudio: (video as any).mozHasAudio || Boolean((video as any).webkitAudioDecodedByteCount)
    };

    sendProgress(id, 75);

    // Analyze frames for quality
    const samples = 5;
    const qualityScores: number[] = [];

    for (let i = 0; i < samples; i++) {
      const time = (video.duration / samples) * i;
      video.currentTime = time;
      await new Promise<void>((resolve) => {
        video.onseeked = () => resolve();
      });

      // Simulate quality analysis
      qualityScores.push(Math.random() * 100);
    }

    const averageQuality = qualityScores.reduce((a, b) => a + b, 0) / qualityScores.length;

    sendProgress(id, 100);

    sendSuccess(id, {
      ...metadata,
      qualityScore: averageQuality,
      qualityScores
    });

  } catch (error) {
    sendError(id, error as Error, { videoUrl: data.videoUrl });
  }
}

/**
 * Main message handler
 * Requirement: 10.4 - Multiple operations handling
 * Requirement: 10.5 - Task cancellation
 */

// Map to track ongoing tasks and enable cancellation
const activeTasks = new Map<string, AbortController>();

self.onmessage = async (event: MessageEvent<WorkerMessage>) => {
  const { id, type, data } = event.data;

  // Handle cancellation
  if (type === 'cancel') {
    const controller = activeTasks.get(id);
    if (controller) {
      controller.abort();
      activeTasks.delete(id);
    }
    return;
  }

  // Create AbortController for this task
  const abortController = new AbortController();
  activeTasks.set(id, abortController);

  try {
    switch (type) {
      case 'generateThumbnail':
        await generateThumbnail(id, data);
        break;

      case 'encodeVideo':
        await encodeVideo(id, data);
        break;

      case 'processBatch':
        await processBatch(id, data);
        break;

      case 'optimizeImage':
        await optimizeImage(id, data);
        break;

      case 'analyzeVideoQuality':
        await analyzeVideoQuality(id, data);
        break;

      default:
        throw new Error(`Unknown operation type: ${type}`);
    }
  } catch (error) {
    // Do not send error if task was cancelled
    if (error instanceof Error && error.name === 'AbortError') {
      return;
    }
    sendError(id, error as Error, { type, data });
  } finally {
    // Cleanup controller
    activeTasks.delete(id);
  }
};

